window.__PHY_SEED__ = {"物理":{"color":"#185FA5","display":"物理","items":[{"id":"phy0001","t":"玻尔氢原子能级理论·轨道与能量量子化","s":"看到【比较氢原子能级高低或判断哪一能级更稳定】","c":"想到【能级越低越稳定（n=1 最稳定），能级为负值、比较大小必须带符号（-3.4eV > -13.6eV）】；警惕【按正数习惯比较负能级而出错，以及 eV 与 J 的单位换算】","src":"物一轮001.轻松拿下【原子模型】选择题_笔记","note":"视频|00:42","orig":"（知识）电子只能在特定轨道上运动，轨道半径不连续；每个轨道对应特定能级，能级均为负值，1eV=1.6×10⁻¹⁹J。","link":""},{"id":"phy0002","t":"玻尔氢原子能级理论·高能级向低能级跃迁","s":"看到【原子从高能级向低能级跃迁，求释放光子的能量/频率或光子种类数】","c":"想到【hν=Em−En，光子能量由能级差决定；从第 n 能级向下跃迁最多产生 C(n,2)=n(n−1)/2 种频率光子】；警惕【任意两能级差各不相同（频率唯一性），且实际辐射路径数受初始能级限制】","src":"物一轮001.轻松拿下【原子模型】选择题_笔记","note":"视频|06:11","orig":"（例）n=3→n=2 释放 ΔE=(-1.51)-(-3.4)=1.89eV；n=2→n=1 释放 10.2eV。","link":""},{"id":"phy0003","t":"玻尔氢原子能级理论·光子吸收跃迁","s":"看到【用光子照射使原子向高能级跃迁，问某能量光子能否被吸收】","c":"想到【光子吸收必须严格满足 hν=Em−En，能量恰好匹配才能被吸收】；警惕【能量大于能级差的光子（非能级差）不会被吸收】","src":"物一轮001.轻松拿下【原子模型】选择题_笔记","note":"视频|11:39","orig":"（例）n=1→n=2 需吸收 10.2eV 光子，11eV 光子不会被吸收。","link":""},{"id":"phy0004","t":"玻尔氢原子能级理论·电子碰撞激发","s":"看到【用电子碰撞（而非光子）使原子跃迁，问电子至少需要多大能量】","c":"想到【电子碰撞只需 Em−En $\\leq$ $\\Delta$E < E(m+1)−En，无需恰好等于能级差】；警惕【把光子吸收的“恰好匹配”条件误套到电子碰撞上】","src":"物一轮001.轻松拿下【原子模型】选择题_笔记","note":"视频|11:39","orig":"（例）n=1→n=2 需电子能量满足 ≥10.2eV 且 <12.09eV。","link":""},{"id":"phy0005","t":"玻尔氢原子能级理论·谱线与能级差匹配","s":"看到【给出光谱线波长/光子能量，问对应哪一能级跃迁】","c":"想到【把波长换算成光子能量，逐项计算各能级差并排除匹配，用排除法确定唯一选项】；警惕【跃迁方向写反或负能级相减时漏掉负号】","src":"物一轮001.轻松拿下【原子模型】选择题_笔记","note":"视频|11:39","orig":"（例）121.6nm 谱线对应 10.2eV，逐项算能级差：2→1 为 10.2eV（匹配），3→1 为 12.09eV，3→2 为 1.89eV，4→2 为 2.55eV。","link":""},{"id":"phy0006","t":"玻尔氢原子能级理论·跃迁后轨道与动能变化","s":"看到【原子跃迁到更低能级（轨道半径减小）后判断动能、电势能变化】","c":"想到【库仑力提供向心力，半径减小时库仑力做正功、动能增大，电势能减小（总量减小以辐射光子）】；警惕【凭“能量释放”误判动能也减小】","src":"物一轮001.轻松拿下【原子模型】选择题_笔记","note":"视频|11:39","orig":"（例）跃迁后轨道半径减小，库仑力做正功使电子动能增大。","link":""},{"id":"phy0007","t":"玻尔氢原子能级理论·电离所需能量","s":"看到【求使某能级原子电离所需的最小能量】","c":"想到【电离即跃迁到 E=0，所需最小能量 $\\Delta$E=0−En=|En|】；警惕【忘记电离后的能量为零，误用相邻能级差】","src":"物一轮001.轻松拿下【原子模型】选择题_笔记","note":"视频|11:39","orig":"（例）n=3 电离至少需要 1.51eV 能量（0-(-1.51)）。","link":""},{"id":"phy0008","t":"连接体问题·连接体的类型识别","s":"看到【多个物体通过绳、摩擦、滑轮一起运动】","c":"想到【先确认各部分加速度是否相同（大小、方向），相同才可用整体法 F外=(M+m)a】；警惕【滑轮连接的加速度方向不同，只能按大小相同处理】","src":"物一轮002.速通【连接体问题】完整视频_笔记","note":"视频|00:43","orig":"（知识）绳连接外力拉动、叠放物块摩擦力带动、滑轮连接（加速度大小相同方向不同）三类典型情形。","link":""},{"id":"phy0009","t":"连接体问题·整体法与隔离法选择","s":"看到【连接体求内力（绳拉力、弹簧弹力、摩擦力）】","c":"想到【整体法求共同加速度 a=F/(M+m)，再隔离受力少的物体求内力；内力与所带动质量成正比】；警惕【力不具有传递性，不能主观认为内力等于外力】","src":"物一轮002.速通【连接体问题】完整视频_笔记","note":"视频|02:08","orig":"（知识）整体法忽略内力仅分析外力，隔离法单独分析单个物体；优先选择受力更清晰的研究对象。","link":""},{"id":"phy0010","t":"连接体问题·外力拉动型求绳拉力","s":"看到【外力 F 通过绳/接触带动整个连接体，求某段内力】","c":"想到【内力 T=被带动质量/总质量$\\times$F，必满足 F>T（F 带动全部、T 只带动部分）】；警惕【拉力作用在不同物体上（作用在 m 还是 M）会导致内力表达式不同】","src":"物一轮002.速通【连接体问题】完整视频_笔记","note":"视频|06:50","orig":"（例）外力 F 拉绳连接的 M、m：整体 F=(M+m)a，隔离 m 得 T=m/(M+m)·F。","link":""},{"id":"phy0011","t":"连接体问题·叠放连接体与弹簧弹力","s":"看到【叠放连接体中问弹簧弹力/伸长量如何变化】","c":"想到【内力 FT=mB/(mA+mB)·F，增大被带动质量 mB（或让弹力作用在更小质量侧）可使内力增大，且与动摩擦因数 $\\mu$ 无关】；警惕【凭直觉认为摩擦力变化会改变内力比例】","src":"物一轮002.速通【连接体问题】完整视频_笔记","note":"视频|09:27","orig":"（例）A、B 叠放在粗糙地面，F 拉 A：FT−μmBg=mBa，F−μ(mA+mB)g=(mA+mB)a，解得 FT=mB/(mA+mB)·F，与 μ 无关。","link":""},{"id":"phy0012","t":"连接体问题·多段绳拉力比值","s":"看到【多个物体由绳依次串联，比较各段绳拉力大小】","c":"想到【逐段隔离：每段绳的拉力等于其后面所有物体所需合力（匀速时为摩擦力之和，加速时再加上惯性项），比例由被带动质量决定，匀速与加速比值规律一致】；警惕【误认为加速时比值会改变】","src":"物一轮002.速通【连接体问题】完整视频_笔记","note":"视频|17:47","orig":"（例）三物体串联：匀速时 T1=3μG、T2=2μG、T3=μG，比值 3:2:1；加速时按牛顿第二定律列方程组后比值仍为 3:2:1。","link":""},{"id":"phy0013","t":"连接体问题·弹簧秤示数与撤力突变","s":"看到【撤去某个外力后求物体瞬间的加速度】","c":"想到【弹簧弹力不能突变：先由原状态求出 T，撤力瞬间 T 仍不变，再对相关物体单独列牛顿第二定律】；警惕【绳弹力可突变而弹簧弹力不能，二者区分开】","src":"物一轮002.速通【连接体问题】完整视频_笔记","note":"视频|18:27","orig":"（例）弹簧秤连 m1、m2，a=(F1−F2)/(m1+m2)=2m/s²，T=F1−m1a=28N；撤去 F2 时 m2 加速度 a2=T/m2=7m/s²。","link":""},{"id":"phy0014","t":"万有引力·卫星受力特点","s":"看到【判断某物体（飞机、鸟类、卫星）是否靠万有引力做圆周运动】","c":"想到【卫星的万有引力全部提供向心力（F万=F向），不需要动力；飞机、鸟类需持续动力，不满足此模型】；警惕【“卫星无重力/不受引力”的错误表述】","src":"物一轮003.轻松拿下【环绕中心天体模型】_笔记","note":"视频|00:35","orig":"（知识）卫星能稳定绕中心天体运动而不依赖持续动力，万有引力全部提供向心力：GMm/r²=mv²/r。","link":""},{"id":"phy0015","t":"万有引力·环绕天体参量与轨道规律","s":"看到【比较不同轨道卫星的 v、$\\omega$、a、T 大小】","c":"想到【“高轨低速大周期”：轨道越高，v、$\\omega$、a 越小，T 越大；r=R+h】；警惕【题目隐藏 r/R/h 的转换，误把高度 h 当轨道半径 r】","src":"物一轮003.轻松拿下【环绕中心天体模型】_笔记","note":"视频|00:35","orig":"（知识）a=GM/r²，v=√(GM/r)，ω=√(GM/r³)，T=2π√(r³/GM)；口诀“高轨低速大周期”。","link":""},{"id":"phy0016","t":"万有引力·含高度的卫星计算","s":"看到【给出卫星距地面高度 h 求各运动参量】","c":"想到【先统一成 r=R+h 再代入 v=√(GM/r) 等公式】；警惕【混淆轨道半径与中心天体半径，以及开方处理（如 8=2^{3} 提出公因数）】","src":"物一轮003.轻松拿下【环绕中心天体模型】_笔记","note":"视频|09:13","orig":"（例）h=R 时 r=2R：v=√(GM/2R)（A错），T=4π√(2R³/GM)（B对），a=GM/4R²（C对），ω=√(GM/8R³)（D对）。","link":""},{"id":"phy0017","t":"万有引力·开普勒第三定律求比值","s":"看到【已知两环绕天体的周期（比），求轨道半径（比）或反之】","c":"想到【开普勒第三定律 T^{2}∝r^{3}（或 GMm/r^{2}=mr·4$\\pi$^{2}/T^{2}）建立比例式求解】；警惕【周期比与半径比不是线性关系，需开三次方】","src":"物一轮003.轻松拿下【环绕中心天体模型】_笔记","note":"视频|13:03","orig":"（例）周期比 1:2:4，由 T₁²/T₂²=r₁³/r₂³ 得轨道半径比 1:∛4:∛16。","link":""},{"id":"phy0018","t":"万有引力·由观测周期求行星参量","s":"看到【由观测现象（亮度变化、遮挡等）确定周期，进而求轨道半径或角速度】","c":"想到【先从题干信息求出周期 T，再用 $\\omega$=2$\\pi$/T 和 T^{2}=4$\\pi$^{2}r^{3}/(GM) 逐级求解】；警惕【角速度漏乘 2$\\pi$，或周期取了半个视周期】","src":"物一轮003.轻松拿下【环绕中心天体模型】_笔记","note":"视频|13:41","orig":"（例）由亮度变化得周期 T=t₁−t₀，r=∛[GM(t₁−t₀)²/4π²]，ω=2π/T（C 项漏乘 2π）。","link":""},{"id":"phy0019","t":"万有引力·近地与同步卫星比较","s":"看到【比较近地航天器与同步卫星（或不同高度航天器）的角速度、加速度、线速度、周期】","c":"想到【轨道低者 v、$\\omega$、a 均更大、周期更短，直接用口诀判断无需计算】；警惕【高度差很大时凭直觉排序出错】","src":"物一轮003.轻松拿下【环绕中心天体模型】_笔记","note":"视频|13:41","orig":"（例）轨道高度 400km 的核心舱与 36000km 同步卫星比较，用“高轨低速大周期”直接判断。","link":""},{"id":"phy0020","t":"弹性碰撞·定义与基本列式","s":"看到【题目明确“弹性碰撞”并求碰后速度】","c":"想到【动量守恒+动能守恒两方程联立求解 v_{1}'、v_{2}'】；警惕【与非弹性碰撞混淆——非弹性碰撞动能有损失，不能列动能守恒】","src":"物一轮004.秒解【弹性碰撞碰后速度】_笔记","note":"视频|00:38","orig":"（知识）碰撞前后系统动能不变：½m₁v₁²+½m₂v₂²=½m₁v₁'²+½m₂v₂'²，联立动量守恒 m₁v₁+m₂v₂=m₁v₁'+m₂v₂'。","link":""},{"id":"phy0021","t":"弹性碰撞·降次法消元","s":"看到【弹性碰撞联立的动量、动能两个二次方程解不动】","c":"想到【降次：两式变形后相除，化为“接近速度=远离速度”v_{1}−v_{2}=v_{2}'−v_{1}'，把二元二次降为二元一次方程组】；警惕【忘记验证碰撞前速度大小关系，出现不合理解】","src":"物一轮004.秒解【弹性碰撞碰后速度】_笔记","note":"视频|00:38","orig":"（知识）动量式变形 m₁(v₁−v₁')=m₂(v₂'−v₂)，动能式变形 m₁(v₁−v₁')(v₁+v₁')=m₂(v₂'−v₂)(v₂'+v₂)，两式相除得 v₁−v₂=v₂'−v₁'。","link":""},{"id":"phy0022","t":"弹性碰撞·碰后速度速记公式","s":"看到【需要快速写出弹性碰撞碰后速度（选择/填空）】","c":"想到【先算完全非弹性碰撞的共同速度 v共，碰后速度 v_{1}'=2v共−v_{1}、v_{2}'=2v共−v_{2}】；警惕【v共 中分子各项的正负号（速度方向相反时取负）】","src":"物一轮004.秒解【弹性碰撞碰后速度】_笔记","note":"视频|00:38","orig":"（知识）先求共同速度 v共=(m₁v₁+m₂v₂)/(m₁+m₂)，则 v₁'=2v共−v₁，v₂'=2v共−v₂。","link":""},{"id":"phy0023","t":"弹性碰撞·等质量与质量悬殊两种特例","s":"看到【弹性碰撞中两物体质量相等或质量悬殊】","c":"想到【等质量弹性碰撞交换速度；撞击质量远大于自身的物体时被原速反弹、重物只获得很小速度】；警惕【动量大不代表动能大，两者要分别用 p=mv、Ek=½mv^{2} 比较】","src":"物一轮004.秒解【弹性碰撞碰后速度】_笔记","note":"视频|16:30","orig":"（例）中子（质量 m）撞氢核（质量 m）：v₁'=v₀ 完全交换速度；撞氮核（质量 14m）：v₂'=2v₀/15，动量 pN>pH 而动能 EкH>EkN。","link":""},{"id":"phy0024","t":"弹性碰撞·碰撞与竖直上抛结合求高度","s":"看到【弹性碰撞后物体竖直反弹，问上升高度】","c":"想到【碰撞求反弹速度（用 v_{1}'=2v共−v_{1}），再用机械能守恒 h=v^{2}/2g 把速度关系转化为高度关系】；警惕【碰撞前瞬间速度需先由自由下落高度求出，两阶段不能混】","src":"物一轮004.秒解【弹性碰撞碰后速度】_笔记","note":"视频|17:07","orig":"（例）2mA=mB 的弹力球碰撞，A 反弹最大高度 H：由 vA'=2v共−vA 求反弹速度，得 h=25H/16。","link":""},{"id":"phy0025","t":"电容器动态分析·电容的两条公式","s":"看到【判断平行板电容器电容 C 如何变化】","c":"想到【用决定式 C=$\\varepsilon$S/(4$\\pi$kd) 判断：d 增大、$\\varepsilon$ 或 S 减小则 C 减小】；警惕【用定义式 C=Q/U 误认为 C 由 Q 或 U 决定】","src":"物一轮005.速通【电容器动态分析】_笔记","note":"视频|01:19","orig":"（知识）决定式 C=εS/(4πkd)，定义式 C=Q/U。","link":""},{"id":"phy0026","t":"电容器动态分析·开关闭合（U 不变）流程","s":"看到【电容器始终与电源相连（开关闭合），改变 d/S/$\\varepsilon$ 后判断 Q、E 变化】","c":"想到【U 不变是不变量：由决定式判 C，再由 C=Q/U 判 Q，由 E=U/d 判 E（d 减小则 E 增大）】；警惕【U<C 对应的瞬时过程判断——稳定后电压始终等于电源电压】","src":"物一轮005.速通【电容器动态分析】_笔记","note":"视频|01:19","orig":"（例）上极板下移（d 减小）：C 增大→瞬间 U=Q/C 减小→电源充电→稳定后 U 恢复原值、Q 增大；E=U/d 增大。","link":""},{"id":"phy0027","t":"电容器动态分析·板间带电油滴运动","s":"看到【板间带电油滴/微粒初始静止，问改变电容参数后如何运动】","c":"想到【初始平衡 qE=mg 定出电荷极性，E 增大则沿电场力方向加速、E 减小则反向加速、E 不变则保持静止】；警惕【先由电场方向和受力方向确定电荷正负，再判断运动】","src":"物一轮005.速通【电容器动态分析】_笔记","note":"视频|01:19","orig":"（例）油滴初始静止 F电=mg（带负电），E 增大后 F电 增大，油滴向上加速。","link":""},{"id":"phy0028","t":"电容器动态分析·板间某点电势变化","s":"看到【求板间固定点 p 的电势如何变化】","c":"想到【以电势恒定的极板（接地极板）为参考，用 Up=E$\\times$dP（沿电场方向的距离）推 $\\varphi$p】；警惕【所选参考极板自身电势必须不变——Q 不变时移动的板不能作参考点】","src":"物一轮005.速通【电容器动态分析】_笔记","note":"视频|01:19","orig":"（例）下极板 b 接地（φb=0），Upb=E×dpb，E 增大时 φp 增大；b 板下移时改选 a 板为参考（Uab 恒定）。","link":""},{"id":"phy0029","t":"电容器动态分析·开关断开（Q 不变）流程","s":"看到【电容器与电源断开（开关断开）后移动极板或改变 $\\varepsilon$/S】","c":"想到【Q 不变是不变量：E=4$\\pi$kQ/($\\varepsilon$S) 与 d 无关、保持不变，U=Q/C 随 C 变化】；警惕【直接用 E=U/d 判断会因 U、d 同时变化而出错，必须用含 Q 的推导式】","src":"物一轮005.速通【电容器动态分析】_笔记","note":"视频|14:56","orig":"（例）S 断开后 A 板下移：C 增大，q 恒定；E=U/d=q/(Cd)=4πkq/(εS) 保持不变，油滴仍静止，φP 不变。","link":""},{"id":"phy0030","t":"电容器动态分析·两类问题对比与通用流程","s":"看到【电容器动态分析综合选择题】","c":"想到【先看开关状态定不变量：闭合则 U 不变用 E=U/d，断开则 Q 不变用 E=4$\\pi$kQ/($\\varepsilon$S)；再按 C$\\to$Q/U$\\to$E$\\to$电势 顺序层层推进】；警惕【U 不变时两极板电势均固定可任选参考点，Q 不变时只有接地极板电势固定】","src":"物一轮005.速通【电容器动态分析】_笔记","note":"视频|21:08","orig":"（知识）U 不变（连电源）vs Q 不变（断开关）；流程：决定式判 C→依电路条件定不变量→推 Q/U→判 E→判电势差。","link":""},{"id":"phy0031","t":"电容器动态分析·传感器类问题（U 不变反推结构）","s":"看到【由电荷量（或电流计偏转）反向推断极板间距/介质变化】","c":"想到【U 不变时 Q 与 C 同向变化：Q 减小$\\to$C 减小$\\to$d 增大（或 S、$\\varepsilon$ 减小）】；警惕【把“Q 变化”与“U 变化”的条件弄反】","src":"物一轮005.速通【电容器动态分析】_笔记","note":"视频|22:55","orig":"（例）电压不变，材料温度降低时极板电荷量减少→C 减小→d 增大→E=U/d 减小，材料竖直方向尺度减小。","link":""},{"id":"phy0032","t":"电容器动态分析·电容式传感器与触摸屏","s":"看到【电容式传感器（液位计、触摸屏等）判断哪个量变化】","c":"想到【把实际装置抽象为平行板电容器，识别哪个结构量（S、d、$\\varepsilon$）在变，电流方向反映充放电（Q 增减）方向】；警惕【不会把生活情境翻译成 C=$\\varepsilon$S/(4$\\pi$kd) 中的变量】","src":"物一轮005.速通【电容器动态分析】_笔记","note":"视频|23:26","orig":"（例）电流计指针左偏（流入）→导体芯 A 带电量增加→液面高度 h 增大（相当于增大极板面积）使 C 增大；触摸屏：接触面积增大或压力增大（d 减小）均使 C 增大。","link":""},{"id":"phy0033","t":"电场强度·定义式与比值定义法","s":"看到【判断电场强度是否随试探电荷量/有无而变化】","c":"想到【E=F/q 是比值定义法，E 由场源本身决定，与试探电荷无关（如同密度与质量、体积的关系）】；警惕【误认为放入的试探电荷量越大 E 越大】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|00:42","orig":"（知识）E=F/q 为比值定义法；同一点放不同试探电荷 F/q 恒定，撤去试探电荷后 E 不变。","link":""},{"id":"phy0034","t":"电场强度·方向规定","s":"看到【给出负电荷在某点的受力方向，求该点场强方向】","c":"想到【E 方向=正电荷受力方向；负电荷受力方向与 E 相反】；警惕【直接按负电荷受力方向画场强方向】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|03:43","orig":"（知识）E 方向与正电荷在该点受力方向相同；负试探电荷受力方向与 E 相反。","link":""},{"id":"phy0035","t":"电场强度·点电荷决定式与适用范围","s":"看到【计算或比较点电荷周围各点的场强大小】","c":"想到【E=kQ/r^{2}：Q 越大 E 越大，r 按平方反比增大时 E 减小；仅适用于点电荷】；警惕【对带电平板等非点电荷源套用该式】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|06:04","orig":"（知识）由 F=kQq/r² 与 E=F/q 得 E=kQ/r²，仅适用点电荷激发的电场。","link":""},{"id":"phy0036","t":"电场强度·球面分布与正负电荷方向","s":"看到【问以点电荷为中心的球面上各点场强的大小与方向关系】","c":"想到【球面上 r 相同故 E 大小相等，但方向沿径向辐射、各点不同；正电荷向外、负电荷向内】；警惕【“大小相等”误推广为“场强相同”（方向不同则矢量不同）】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|08:33","orig":"（知识）以 Q 为中心的球面上各点 E 大小相等、方向沿径向各不相同；正电荷 E 向外，负电荷 E 向内。","link":""},{"id":"phy0037","t":"电场强度·均匀带电球体/球壳的等效","s":"看到【求均匀带电球体/球壳外某点的场强】","c":"想到【等效为电荷集中在球心的点电荷，r 取研究点到球心的距离】；警惕【把 r 误取为到球面的距离】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|10:14","orig":"（知识）均匀带电球体/球壳外部电场等效为球心处等量点电荷，E=kQ/r²，r 为到球心的距离。","link":""},{"id":"phy0038","t":"电场叠加·矢量叠加原理","s":"看到【多个点电荷（或带电体）在某点产生的合场强】","c":"想到【先分别算各场源的 E（含方向），再按平行四边形定则矢量合成；对称分布先找抵消分量】；警惕【把场强大小直接代数相加而忽略方向】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|11:57","orig":"（知识）某点总场强为各场源电荷单独产生场强的矢量和，遵循平行四边形定则；各场源电场相互独立。","link":""},{"id":"phy0039","t":"电场叠加·微元法求带电圆环轴线场强","s":"看到【均匀带电圆环/弧上一类连续带电体求轴线上的场强】","c":"想到【微元法：把带电体分割为点电荷微元，利用对称性让垂直分量抵消，只合成剩余方向分量；掌握推导方法即可，不必死记公式】；警惕【漏掉对称性抵消而试图对全部微元代数相加】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|15:27","orig":"（例）将圆环分割为点电荷微元，E=kq/(x²+r²)，对称位置垂直分量抵消，总场强沿轴线：E=kQx/(x²+r²)^(3/2)。","link":""},{"id":"phy0040","t":"电场叠加·均匀带电球壳内部场强","s":"看到【均匀带电球壳内部（空腔中）某点的场强】","c":"想到【均匀带电球壳内部场强处处为零（微元+对称性抵消），外部等效为球心点电荷】；警惕【把结论推广到不均匀或非球对称带电体】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|21:12","orig":"（例）均匀带电球壳内部场强处处为零（各方向场强分量完全抵消）。","link":""},{"id":"phy0041","t":"电场叠加·零场强点与电荷量关系","s":"看到【空间某点场强为零，反推电荷的电性或电荷量关系】","c":"想到【零场强=各电荷场强的矢量和为零：正交分解后每个分量分别为零，结合 E=kQ/r^{2} 建立电荷量与距离比的关系】；警惕【忽略场强矢量性、电荷正负号判断错误】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|22:47","orig":"（例）三点电荷共线，P 点场强为零：建系正交分解，算各电荷在 P 点的分量，利用几何关系定距离比；同号组合被排除，答案 D。","link":""},{"id":"phy0042","t":"电场叠加·对称结构场强简化","s":"看到【多个等量电荷呈对称分布（十字/正多边形），求某点合场强】","c":"想到【先分析对称性：对称位置电荷的场强分量成对抵消或叠加，把四电荷问题化为两电荷问题再矢量合成】；警惕【不对称先抵消就逐个硬算，距离漏用勾股定理 √(R^{2}+R^{2})】","src":"物一轮006.速通【电场强度叠加】选择题_笔记","note":"视频|23:30","orig":"（例）四个 +q 在 M、N、P、Q 十字对称分布，各电荷到 a 点距离均为 √2R，用对称性简化矢量叠加。","link":""},{"id":"phy0043","t":"力与物体平衡·一轮复习顺序方法论","s":"看到【规划力学复习顺序或反思复习方法】","c":"想到【力学问题的根基是受力分析：先夯实受力（力是研究运动的基础），再进入运动学研究】；警惕【按教材“先运动后力”的顺序理解，导致受力分析基础不牢】","src":"物一轮007.【课前必看】本讲听课建议_笔记","note":"视频|00:12","orig":"（知识）一轮复习先复习力后复习运动，与高一学习顺序相反，因力是研究运动的基础。","link":""},{"id":"phy0044","t":"力与物体平衡·弹力考情与命题方向","s":"看到【力学综合题中出现弹簧/杆/接触面的空间立体情境】","c":"想到【立体情境下的弹力方向判断是近年考查趋势，需具备空间思维与模型建构能力】；警惕【弹力方向画错会导致整个受力分析出错、后续全盘失效】","src":"物一轮007.【课前必看】本讲听课建议_笔记","note":"视频|07:48","orig":"（知识）弹力单独命题概率极低（近10年仅5省考过），但作为受力分析基础环节贯穿所有力学问题；单独考查常结合空间立体图形（如23年山东卷）或生活情境。","link":""},{"id":"phy0045","t":"力与物体平衡·弹力模块学习策略","s":"看到【判断自己应从哪一难度层级切入弹力复习】","c":"想到【先自测基础（画弹力方向），再攻核心（绳结、二力可转杆、$\\Delta$F=k$\\Delta$x），最后拓展（轻质物体、等效思想求弹簧串并联）；通过例题正确率动态调整】；警惕【跳过弹力方向这一基础环节直接刷难题】","src":"物一轮007.【课前必看】本讲听课建议_笔记","note":"视频|11:37","orig":"（知识）弹力分三大模块：微小/明显形变的弹力方向（基础）、弹簧结论与 ΔF=kΔx（核心）、轻质物体与弹簧串并联等效（拓展）；按基础分层学习并用讲义例题自测。","link":""},{"id":"phy0046","t":"微小形变弹力·接触面弹力方向通法","s":"看到【画两物体平面或曲面接触处的弹力方向】","c":"想到【三步：确定接触面性质$\\to$分清施力/受力物体$\\to$沿接触面垂线指向受力物体】；警惕【混淆施力与受力物体，方向画反】","src":"物一轮008.画出微小形变的弹力方向_笔记","note":"视频|02:37","orig":"（知识）方向判定原则：垂直接触面指向受力物体；平面直接作垂线，曲面找切面作垂线。","link":""},{"id":"phy0047","t":"微小形变弹力·平面接触（杆与墙/地）","s":"看到【一根杆同时与多个平面（墙、地面）接触】","c":"想到【在每个接触点分别垂直接触面指向杆，各接触点弹力方向互不影响、逐一独立判断】；警惕【把两个接触点弹力画成同一方向】","src":"物一轮008.画出微小形变的弹力方向_笔记","note":"视频|07:21","orig":"（例）杆与竖直墙接触点弹力水平向右，与水平地面接触点弹力竖直向上（答案 D）。","link":""},{"id":"phy0048","t":"微小形变弹力·曲面接触必过曲率中心","s":"看到【杆/球与圆弧面（碗、球壳）接触画弹力】","c":"想到【曲面接触弹力垂直于切面、沿半径方向且必过曲率中心】；警惕【因重心位置偏移而误判弹力方向——几何关系优先于受力直觉】","src":"物一轮008.画出微小形变的弹力方向_笔记","note":"视频|10:23","orig":"（例）杆与碗口接触点 A：弹力沿半径方向（垂直切面）从碗指向杆，延长线过圆心；曲面弹力方向必过曲率中心，与重心位置无关。","link":""},{"id":"phy0049","t":"轻绳弹力·轻绳模型与两端等力","s":"看到【轻绳两端或跨过滑轮两侧的拉力大小比较】","c":"想到【轻绳弹力处处相等，两端拉力一定相等（不能叠加计算）】；警惕【对有质量的实际绳套用“两端力相等”】","src":"物一轮008.画出微小形变的弹力方向_笔记","note":"视频|15:36","orig":"（知识）轻绳是 m=0 的理想化模型，绳上各处弹力大小相等；绳一端受拉力 f，则绳上所有点及另一端拉力均为 f。","link":""},{"id":"phy0050","t":"轻绳弹力·区分“绳给的力”与“绳受的力”","s":"看到【题目问“绳的弹力”却给出绳所受的外力（或反之）】","c":"想到【绳的弹力大小等于绳任一端所受外力大小，方向与绳给绳外的力相反（相互作用力）】；警惕【把绳受的力直接当成绳的弹力画在同一物体上】","src":"物一轮008.画出微小形变的弹力方向_笔记","note":"视频|18:33","orig":"（知识）绳的弹力指绳给接触物体的力；绳所受的力是另一概念，二者互为作用力与反作用力，大小相等方向相反。","link":""},{"id":"phy0051","t":"轻绳弹力·方向沿绳指向收缩","s":"看到【画轻绳对小球/物体的拉力方向】","c":"想到【绳弹力沿绳指向绳子收缩（固定端）方向】；警惕【给绳画出压力方向的弹力】","src":"物一轮008.画出微小形变的弹力方向_笔记","note":"视频|22:58","orig":"（知识）绳只能被拉伸不能压缩，弹力沿绳方向指向收缩方向；习惯用 T 表示绳/弹簧弹力，N 表示接触面弹力。","link":""},{"id":"phy0052","t":"轻杆弹力·方向无固定规律","s":"看到【判断轻杆对物体的弹力方向】","c":"想到【轻杆弹力方向不确定（可沿杆、垂直杆或任意方向），必须由物体的运动状态（通常平衡）和其余力反推】；警惕【默认杆弹力一定沿杆方向】","src":"物一轮008.画出微小形变的弹力方向_笔记","note":"视频|25:57","orig":"（例）水平插墙杆弹力竖直向上（与重力平衡）；斜杆弹力可沿杆向外；压弯杆弹力既不沿杆也不垂直杆——轻杆弹力方向无固定规律。","link":""},{"id":"phy0053","t":"轻杆弹力·受力分析顺序策略","s":"看到【物体同时受重力、绳、接触面、杆等多力平衡】","c":"想到【先画方向明确的力（重力、绳拉力、接触面弹力），最后由合力为零（正交分解）反推杆弹力】；警惕【一上来就猜杆弹力方向导致后续方程全错】","src":"物一轮008.画出微小形变的弹力方向_笔记","note":"视频|28:47","orig":"（知识）先分析物体运动状态，确定重力等方向明确的力，再由合力为零反推杆弹力；应最后分析杆弹力。","link":""},{"id":"phy0054","t":"力学·弹力·轻质弹簧模型","s":"看到【题目未特殊说明的弹簧】","c":"想到【按轻弹簧处理：m=0，各处弹力相等，两端拉力等大】；警惕【题干若说明弹簧有质量则不能套用轻质模型】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|00:05-00:43","orig":"（知识）高中阶段默认弹簧质量为零，除非题目特殊说明；轻弹簧各处弹力大小相等，两端所受拉力一定相等（与轻绳类似）","link":""},{"id":"phy0055","t":"力学·弹力·弹簧弹力本质","s":"看到【区分”弹簧弹力”与”弹簧所受外力”】","c":"想到【弹簧弹力是弹簧施加给接触物体的力，与外力互为作用力与反作用力】；警惕【把弹给物体的力与弹受的力混为一谈】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|02:24-03:33","orig":"（知识）弹簧弹力是弹簧给接触物体的力，不是弹簧所受的力；弹簧弹力与外力构成作用力与反作用力对","link":""},{"id":"phy0056","t":"力学·弹力·弹簧弹力与外力关系","s":"看到【求弹簧弹力大小或比较不同装置中弹簧弹力】","c":"想到【F弹=F外力，只需看任一端点受力即可确定弹力】；警惕【固定端同样存在弹力，”不动”不等于”无力”】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|03:33-04:20","orig":"（知识）F弹=F外力：弹簧弹力大小等于其一端所受外力大小；无论单端固定还是双端受力，只要外力F相同弹力就相同","link":""},{"id":"phy0057","t":"力学·弹力·弹簧弹力大小比较例题","s":"看到【固定端与双端受力装置的弹簧弹力对比】","c":"想到【比较任一端点受力大小即可判断弹力关系，与装置形式无关】；警惕【认为固定端无力而选错】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|04:20-06:44","orig":"（例）比较不同装置（固定端/双端受力）中弹簧弹力大小，依据”弹簧弹力与其一端所受外力大小相等”判断","link":""},{"id":"phy0058","t":"力学·弹力·弹簧弹力方向判定","s":"看到【画弹簧弹力的方向】","c":"想到【沿轴线指向原长：拉伸向内指、压缩向外推，一端定另一端】；警惕【高中只考虑拉伸和压缩，无弯曲/扭转形变】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|07:07-07:44","orig":"（知识）弹簧弹力沿弹簧轴线方向、指向原长位置；口诀”拉伸向内指，压缩向外推”；已知一端方向即可确定另一端","link":""},{"id":"phy0059","t":"力学·弹力·拉伸弹簧方向例题","s":"看到【弹簧处于拉伸状态画两端弹力】","c":"想到【拉伸时两端弹力均指向弹簧内部（向内拉回恢复原长）】；警惕【认为固定端”不动就没有力”】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|07:44-09:39","orig":"（例）弹簧拉伸时分析两端弹力方向：两端弹力均指向弹簧内部","link":""},{"id":"phy0060","t":"力学·弹力·压缩弹簧方向例题","s":"看到【弹簧处于压缩状态画两端弹力】","c":"想到【压缩时两端弹力均指向弹簧外部（向外推恢复原长）】；警惕【与拉伸情形方向记反】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|09:39-11:21","orig":"（例）弹簧压缩时分析两端弹力方向：两端弹力均指向弹簧外部，两端同时外推恢复原长","link":""},{"id":"phy0061","t":"力学·弹力·胡克定律","s":"看到【计算弹簧弹力大小】","c":"想到【F=kx，x取相对原长的形变量绝对值（拉伸2cm和压缩2cm都是x=0.02m）】；警惕【把当前长度当形变量x】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|11:44-12:41","orig":"（知识）F=kx：F为弹力大小（N），x为形变量绝对值（相对原长的变化量），k为劲度系数（N/m）；公式只算大小，方向单独判断","link":""},{"id":"phy0062","t":"力学·弹力·劲度系数特性","s":"看到【判断劲度系数k是否随外力/形变改变】","c":"想到【k是弹簧自身属性，与外力、形变量均无关】；警惕【”形变越大k越大”是错误认知】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|12:41-15:26","orig":"（知识）k由弹簧自身决定（材料、匝数、直径等），与外力大小和形变量无关","link":""},{"id":"phy0063","t":"力学·弹力·弹簧秤示数例题","s":"看到【求弹簧秤（轻弹簧）示数】","c":"想到【示数=弹簧弹力=其一端受力，优先分析受力明确的端点】；警惕【误认为示数是两物体重力差（9N）】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|15:26-18:42","orig":"（例）A重GA=15N、B重GB=6N，弹簧秤轻质，右端B悬空：右端绳拉力T=GB=6N，故示数为6N；A受重力15N、拉力6N、支持力9N三力平衡","link":""},{"id":"phy0064","t":"力学·弹力·弹簧伸长量比较例题","s":"看到【比较固定端、双端拉力、带物块等不同装置中弹簧的伸长量】","c":"想到【x=F/k仅由弹力和k决定，装置形式不影响伸长量】；警惕【双拉力使伸长量加倍；摩擦力影响物块运动但不改变弹簧弹力】","src":"物一轮009.画出轻弹簧弹力的方向并计算大小_笔记","note":"视频|18:42","orig":"（例）四个k相同的弹簧右端均受拉力F，比较伸长量：固定端/双拉力/带物块装置中伸长量均相同（l1=l2=l3=l4）","link":""},{"id":"phy0065","t":"力学·弹力·活结与死结","s":"看到【绳绕过滑轮或圆滑弯折（晾衣钩）】","c":"想到【活结：两侧绳拉力等大，可沿一条绳分析】；警惕【误把活结当死结而设两端力不等】","src":"物一轮010.掌握绳结、二力可转杆的弹力特点完整视频_笔记","note":"","orig":"（知识）活结：绳经滑轮、晾衣钩等圆滑弯折，两端拉力等大；死结：绳打结或杆顶硬性弯折，两端拉力不等大","link":""},{"id":"phy0066","t":"力学·弹力·活结与死结","s":"看到【绳打结或绳在杆顶硬性弯折】","c":"想到【死结：两侧拉力大小、方向独立，需分别受力分析】；警惕【默认两侧绳力等大】","src":"物一轮010.掌握绳结、二力可转杆的弹力特点完整视频_笔记","note":"","orig":"（知识）死结：绳打结或杆顶硬性弯折处，两侧绳拉力不等大","link":""},{"id":"phy0067","t":"力学·弹力·二力可转杆","s":"看到【轻杆两端各受一个力且可绕铰链转动】","c":"想到【二力可转杆弹力沿杆方向，按拉/压杆处理】；警惕【铰链$\\neq$固定端，注意题干描述】","src":"物一轮010.掌握绳结、二力可转杆的弹力特点完整视频_笔记","note":"","orig":"（知识）杆仅受两个力且可转动（如铰链连接）时，弹力方向必沿杆方向","link":""},{"id":"phy0068","t":"力学·弹力·非二力可转杆","s":"看到【杆插墙固定或杆受三个及以上力】","c":"想到【非二力可转杆弹力不沿杆，需由平衡/运动条件确定方向】；警惕【凭直觉认为杆弹力总沿杆】","src":"物一轮010.掌握绳结、二力可转杆的弹力特点完整视频_笔记","note":"","orig":"（知识）杆不可转（如插墙固定）或受多个力时，弹力方向不沿杆，需通过运动状态和其他力判断","link":""},{"id":"phy0069","t":"力学·弹力·弹簧弹力推论","s":"看到【动态平衡中求弹簧弹力的变化量】","c":"想到【直接用$\\Delta$F=k·$\\Delta$x，跳过原长和初态形变】；警惕【$\\Delta$x是长度变化量，不是相对原长的形变量】","src":"物一轮010.掌握绳结、二力可转杆的弹力特点完整视频_笔记","note":"","orig":"（知识）ΔF=k·Δx：弹簧弹力变化量与长度变化量成正比，用于简化动态平衡问题","link":""},{"id":"phy0070","t":"力学·弹力·绳结与杆综合例题","s":"看到【同一题中同时出现绳结与不同类型的杆】","c":"想到【先分类再画力：活结绳等大/死结不等大，二力可转杆沿杆/固定或多力杆不沿杆】；警惕【甲乙两图装置相似但结与杆类型不同，结论完全不同】","src":"物一轮010.掌握绳结、二力可转杆的弹力特点完整视频_笔记","note":"","orig":"（例）甲图：活结（滑轮）→绳力等大，非二力杆弹力方向需合成受力；乙图：死结（杆顶弯折）→绳力不等大，二力可转杆弹力沿杆方向","link":""},{"id":"phy0071","t":"力学·弹力·弹簧弹力推论ΔF=kΔx","s":"看到【题目求弹力/长度的”变化量”而非最终值】","c":"想到【直接用$\\Delta$F=k·$\\Delta$x一步求解】；警惕【”再拉伸”是在原有基础上叠加，需先理清总形变量；求的是$\\Delta$F不是F2】","src":"物一轮011.掌握弹簧弹力推论ΔF=kΔx完整视频_笔记","note":"视频|00:21-04:30","orig":"（例）k=100N/m的轻弹簧拉伸2cm后再拉伸4cm，求需增加的力：ΔF=kΔx=100×0.04=4N（基础法：F1=2N、F2=6N，ΔF=4N）","link":""},{"id":"phy0072","t":"力学·弹力·推论适用条件","s":"看到【题目只给长度变化量、不给原长】","c":"想到【优先用推论$\\Delta$F=k$\\Delta$x；涉及原长信息才回到基本公式F=kx】；警惕【硬设原长列方程组，多走弯路】","src":"物一轮011.掌握弹簧弹力推论ΔF=kΔx完整视频_笔记","note":"视频|04:30-04:58","orig":"（知识）题目涉及力的变化量而非力本身、或给出长度变化量而非形变量时，优先使用ΔF=kΔx","link":""},{"id":"phy0073","t":"力学·弹力·推论的图像推导","s":"看到【解释或推导$\\Delta$F=k$\\Delta$x的来源】","c":"想到【过原点直线上原点斜率与两点斜率相等】；警惕【该推论仅适用于过原点的线性关系（如定值电阻R=$\\Delta$U/$\\Delta$I），小灯泡等非线性不适用】","src":"物一轮011.掌握弹簧弹力推论ΔF=kΔx完整视频_笔记","note":"视频|04:58-07:30","orig":"（知识）F-x图像过原点直线：原点斜率k=F/x，任意两点斜率k=ΔF/Δx，二者相等推出ΔF=kΔx（线性关系差分形式保持比例）","link":""},{"id":"phy0074","t":"力学·弹力·ΔF与Δx的物理含义","s":"看到【弹簧弹力方向发生反转（压变拉）求变化量】","c":"想到【$\\Delta$F按矢量变化求大小，方向相反时做加法】；警惕【当成标量差F2-F1；混淆$\\Delta$x与形变量x】","src":"物一轮011.掌握弹簧弹力推论ΔF=kΔx完整视频_笔记","note":"视频|07:30-09:28","orig":"（知识）ΔF是弹力变化量的大小（矢量运算结果）：从向右5N变为向左3N，ΔF=8N而非2N；Δx是弹簧长度变化量，与形变量x不同（x相对原长，Δx是长度绝对变化）","link":""},{"id":"phy0075","t":"力学·弹力·压拉转换求k例题","s":"看到【弹簧由压变拉，已知两状态的力和长度差求k】","c":"想到【用$\\Delta$F=k·$\\Delta$x，$\\Delta$F取两弹力的矢量和、$\\Delta$x取长度差，避免设原长】；警惕【方向相反时$\\Delta$F做加法而非相减】","src":"物一轮011.掌握弹簧弹力推论ΔF=kΔx完整视频_笔记","note":"视频|14:27-19:35","orig":"（例）弹簧先受压F1后受拉F2，长度从l1变为l2求k：传统法设原长l0列方程组；推论法ΔF=F1+F2=k(l2-l1)，得k=(F1+F2)/(l2-l1)","link":""},{"id":"phy0076","t":"力学·弹力·多弹簧分担例题","s":"看到【n根相同弹簧共同承担总力变化】","c":"想到【总力变化均分到每根弹簧（每根$\\Delta$F=$\\Delta$F总/n），再对单根用k=$\\Delta$F/$\\Delta$x】；警惕【忘记除以弹簧根数】","src":"物一轮011.掌握弹簧弹力推论ΔF=kΔx完整视频_笔记","note":"视频|19:35-22:50","orig":"（例）取走300g盘子→减少3N压力（g=10m/s²），弹簧升高1cm对应Δx=0.01m，3根弹簧共同承担：3=k×3×0.01，k=100N/m","link":""},{"id":"phy0077","t":"力学·弹力·两公式选择总结","s":"看到【在F=kx与$\\Delta$F=k$\\Delta$x之间选择】","c":"想到【按已知量选公式：有原长信息用F=kx，只有长度变化用$\\Delta$F=k$\\Delta$x】；警惕【$\\Delta$F是矢量变化大小，方向反转时做加法】","src":"物一轮011.掌握弹簧弹力推论ΔF=kΔx完整视频_笔记","note":"视频|22:50","orig":"（知识）F=kx（x为相对原长的形变量）与ΔF=kΔx（Δx为长度绝对变化量）；涉及原长用基本公式，仅给长度变化优先推论；ΔF需考虑方向，可能做加法","link":""},{"id":"phy0078","t":"力学·弹力·轻质物体的本质","s":"看到【问轻绳/轻弹簧两端受力为何一定等大反向】","c":"想到【m=0$\\to$合力必为零$\\to$微元递推两端力等大反向】；警惕【该性质与运动状态无关，加速运动时依然成立】","src":"物一轮012.理解轻质物体的含义完整视频_笔记","note":"视频|00:58-01:10","orig":"（知识）由F=ma推导：m=0时无论a为何值合力F必为零；轻绳/弹簧任意微元两端受力相等，递推得整体两端力等大反向","link":""},{"id":"phy0079","t":"力学·弹力·轻质物体受力表现","s":"看到【轻绳/轻弹簧水平放置或竖直悬挂求内部张力】","c":"想到【轻质物体任意状态两端力等大反向；竖直悬挂时各点拉力等于下方悬挂物重力】；警惕【给轻绳算自重】","src":"物一轮012.理解轻质物体的含义完整视频_笔记","note":"视频|01:10-01:52","orig":"（知识）水平放置：静止或匀速时两端力等大反向；竖直悬挂：各点拉力=悬挂物重力（因自身无质量）","link":""},{"id":"phy0080","t":"力学·弹力·轻质物体定义","s":"看到【题目出现”轻绳/轻杆/轻弹簧/质量不计”字样】","c":"想到【按m=0理想模型处理：内部受力处处相等、合力恒为零，可少列方程】；警惕【”轻”不是”重量小”，是严格质量为零】","src":"物一轮012.理解轻质物体的含义完整视频_笔记","note":"视频|01:52-07:44","orig":"（知识）轻质物体是质量为零的理想化模型（轻绳、轻杆、轻弹簧），现实中不存在但可简化问题分析；”轻”特指质量为零","link":""},{"id":"phy0081","t":"力学·弹力·轻质与非轻质对比","s":"看到【对比有质量绳与轻绳两端拉力】","c":"想到【非轻质绳加速/悬挂时两端力不等，需把绳自身质量计入动力学】；警惕【把真实绳也当轻绳处理】","src":"物一轮012.理解轻质物体的含义完整视频_笔记","note":"视频|07:44-12:26","orig":"（知识）轻质物体任意状态两端力等大；非轻质物体：水平加速时F右>F左（a>0），竖直悬挂时上端拉力=下端拉力+自重","link":""},{"id":"phy0082","t":"力学·弹力·轻质秤盘等效例题","s":"看到【秤盘/托盘”质量不计”】","c":"想到【等效为物块直接压弹簧，Np=T，减少一个研究对象和一条方程】；警惕【忽视轻质条件，多分析秤盘动力学方程】","src":"物一轮012.理解轻质物体的含义完整视频_笔记","note":"视频|12:26-14:04","orig":"（例）弹簧台秤秤盘质量不计：可等效为物块直接接触弹簧，盘受压力Np与弹簧弹力T时刻相等（Np=T），简化方程T-mg=ma","link":""},{"id":"phy0083","t":"力学·弹力·非轻质秤盘例题","s":"看到【秤盘质量不可忽略】","c":"想到【对物块和秤盘分别列牛顿第二定律方程并联立求解】；警惕【仍按轻质等效处理导致漏方程】","src":"物一轮012.理解轻质物体的含义完整视频_笔记","note":"视频|14:04","orig":"（例）秤盘质量m1=1.5kg时必须单独分析：T-m1g-Np=m1a，需建立物块和秤盘联立方程","link":""},{"id":"phy0084","t":"力学·弹力·弹簧串联等效","s":"看到【多根弹簧首尾串联悬挂重物】","c":"想到【各弹簧受力相同、形变量相加，1/k等效=1/k1+1/k2】；警惕【串联等效k误记为直接相加】","src":"物一轮013.利用等效思想求解弹簧串并联_笔记","note":"视频|00:05-01:18","orig":"（知识）串联时各弹簧受力相等均为mg，总形变量Δx总=Δx1+Δx2=mg/k1+mg/k2，等效公式1/k等效=1/k1+1/k2（与电阻并联公式相似）","link":""},{"id":"phy0085","t":"力学·弹力·串联等效实验例题","s":"看到【用实验数据（原长、悬挂物、总伸长量）推导串联等效劲度系数】","c":"想到【对每根弹簧列F=kx、共享同一个F，消去重力即得倒数关系】；警惕【忘记串联中各弹簧受力相同这一前提】","src":"物一轮013.利用等效思想求解弹簧串并联_笔记","note":"视频|01:18-06:47","orig":"（例）实验：测原长→悬挂重物→测总伸长量，由mg/k等效=mg/ka+mg/kb消去mg得倒数关系，k等效=kakb/(ka+kb)","link":""},{"id":"phy0086","t":"力学·弹力·弹簧并联等效","s":"看到【多根弹簧并排共同承重】","c":"想到【各弹簧形变量相同、弹力相加，k等效=k1+k2】；警惕【与串联公式记反——口诀”弹簧串并电阻反”】","src":"物一轮013.利用等效思想求解弹簧串并联_笔记","note":"视频|06:47-10:03","orig":"（知识）并联时各弹簧形变量相同，总弹力F总=F1+F2=k1x+k2x，等效公式k等效=k1+k2（与电阻串联公式相似）；相同弹簧并联k等效=nk单","link":""},{"id":"phy0087","t":"力学·弹力·并联反求单根k例题","s":"看到【已知并联总劲度系数反求单根弹簧k】","c":"想到【n根相同弹簧并联：k单=k总/n】；警惕【审题——问的是单根弹簧k值而非总数】","src":"物一轮013.利用等效思想求解弹簧串并联_笔记","note":"视频|06:47-10:03","orig":"（例）两根相同弹簧并联后k总=k：k=k单+k单=2k单，故k单=0.5k","link":""},{"id":"phy0088","t":"力学·弹力·F-x图像识别弹簧组合","s":"看到【F-x图像出现转折（斜率变化）】","c":"想到【斜率=该阶段等效劲度系数，转折点前后对应不同弹簧组合介入/退出，分段求斜率再拆分】；警惕【不识别转折点的物理意义就整段拟合】","src":"物一轮013.利用等效思想求解弹簧串并联_笔记","note":"视频|10:03-13:23","orig":"（例）F-x图像0-0.2m段斜率对应大弹簧单独作用：k大=20/0.2=100N/m；之后两弹簧并联k总=300N/m，得k小=200N/m","link":""},{"id":"phy0089","t":"力学·弹力·先串后并嵌套例题","s":"看到【弹簧先串联成组、再若干组并联的嵌套结构】","c":"想到【分步等效：先算每串的k串，再用并联关系求组数，最后乘每组根数得总数】；警惕【漏算单位换算与”每组弹簧数”】","src":"物一轮013.利用等效思想求解弹簧串并联_笔记","note":"视频|13:23-17:28","orig":"（例）弹簧座垫：每组两弹簧串联k串=5N/m（1/k串=1/10+1/10），n组并联n×5=1000得n=200组，总数200×2=400个","link":""},{"id":"phy0090","t":"力学·弹力·等效思想总结","s":"看到【复杂弹簧组合系统求整体效果】","c":"想到【类比电阻串并联规律分步等效替代】；警惕【考试可能要求解释等效思想而非直接套结论】","src":"物一轮013.利用等效思想求解弹簧串并联_笔记","note":"视频|17:28","orig":"（知识）等效替代：用一根弹簧替代弹簧组合达到相同形变/弹力效果；串联1/k等效=1/k1+1/k2、并联k等效=k1+k2；口诀”弹簧串并电阻反，串联倒数并联和”","link":""},{"id":"phy0091","t":"力学·摩擦力·模块主线","s":"看到【复习/梳理摩擦力章节】","c":"想到【按”产生条件$\\to$大小方向判断$\\to$突变问题”三条主线组织知识】；警惕【跳过产生条件直接背f=$\\mu$N】","src":"物一轮014.【课前必看】本讲听课建议_笔记","note":"视频|00:09-00:30","orig":"（知识）摩擦力模块包括：摩擦力的产生条件、大小和方向判断，以及摩擦力突变问题（静→静、静→滑动、滑动→滑动）","link":""},{"id":"phy0092","t":"力学·摩擦力·高考地位","s":"看到【评估摩擦力的备考优先级】","c":"想到【把摩擦力方向判断当作受力分析基本功训练，服务于综合题】；警惕【因很少单独出题而忽视基础训练】","src":"物一轮014.【课前必看】本讲听课建议_笔记","note":"视频|02:28-03:05","orig":"（知识）摩擦力很少单独命题但非常重要，是受力分析的基础环节，必须准确判断大小和方向","link":""},{"id":"phy0093","t":"力学·摩擦力·生活情境命题","s":"看到【生活情境包装的摩擦力题（如研墨、毛笔）】","c":"想到【剥离生活外壳还原为物理模型，实质仍是摩擦力方向/条件的基础判断】；警惕【被复杂情境吓住而放弃简单题】","src":"物一轮014.【课前必看】本讲听课建议_笔记","note":"视频|03:05-04:01","orig":"（例）2014广东题：研墨过程中摩擦力方向的判断——题目情境复杂但实质考查基础，难度较低","link":""},{"id":"phy0094","t":"力学·摩擦力·综合题环节","s":"看到【综合大题中含摩擦力接触面】","c":"想到【先把摩擦力方向和大小判断准确，再进行后续受力分析与列方程】；警惕【摩擦力方向画错导致整题崩溃】","src":"物一轮014.【课前必看】本讲听课建议_笔记","note":"视频|04:01-04:17","orig":"（知识）综合考查时摩擦力作为受力分析的一个环节出现，需准确画出摩擦力方向才能正确解题","link":""},{"id":"phy0095","t":"力学·摩擦力·产生条件","s":"看到【判断某接触面有无摩擦力】","c":"想到【逐一检查三条件：有弹力、粗糙、有相对运动/趋势，缺一则f必为零】；警惕【N$\\neq$0且粗糙也未必有摩擦，还差条件③】","src":"物一轮015.知道摩擦力的产生条件_笔记","note":"视频|00:24","orig":"（知识）三个必要条件：①有弹力（N=0则f=0必然成立，但N≠0不一定有摩擦）②接触面粗糙（明确”光滑”则无摩擦）③有相对运动或相对运动趋势；三者必须同时满足","link":""},{"id":"phy0096","t":"力学·摩擦力·受力分析顺序","s":"看到【给物体画完整受力图】","c":"想到【按”先弹力后摩擦力”的顺序分析每个接触面】；警惕【跳过弹力直接假设摩擦力存在，或画了摩擦力漏了弹力】","src":"物一轮015.知道摩擦力的产生条件_笔记","note":"视频|00:24","orig":"（知识）同一接触面必须先分析弹力再分析摩擦力；若接触面无弹力则摩擦力必为零。典型错误：物体受斜向上拉力F竖直分量已平衡重力，却画地面摩擦力而不画弹力","link":""},{"id":"phy0097","t":"力学·摩擦力·相对运动与对地运动","s":"看到【板块模型中判断物块相对木板的运动方向】","c":"想到【以接触物体为参考系判断相对运动，与对地运动分开分析】；警惕【用对地运动方向替代相对运动方向】","src":"物一轮015.知道摩擦力的产生条件_笔记","note":"视频|00:24","orig":"（知识）”相对”特指相对于接触物体的运动，而非对地运动：二者方向可能相同、相反或无关（如物块右移但滑至木板左侧，则相对左移而对地右移）","link":""},{"id":"phy0098","t":"力学·摩擦力·相对运动趋势判断","s":"看到【静摩擦问题中判断有无相对运动趋势】","c":"想到【假想接触面光滑看物体是否滑动，从而判断趋势方向】；警惕【凭直觉断定”静止就无趋势”】","src":"物一轮015.知道摩擦力的产生条件_笔记","note":"视频|00:24","orig":"（知识）假想光滑法：假设接触面光滑，若物体会滑动则存在相对运动趋势，否则无趋势","link":""},{"id":"phy0099","t":"力学·摩擦力·板块模型例题","s":"看到【叠放体匀速共同运动，判断各接触面有无摩擦】","c":"想到【对每个物体单独用平衡条件反推摩擦力有无】；警惕【无摩擦$\\neq$接触面光滑——可能只是无相对运动趋势】","src":"物一轮015.知道摩擦力的产生条件_笔记","note":"视频|00:24","orig":"（例）A、B以相同速度匀速运动，B受外力F：A若受AB间摩擦力则水平方向无法平衡→fAB=0；B需地面摩擦fBC平衡F→fBC≠0；BC面有摩擦必粗糙μ2≠0，AB面无摩擦可能光滑也可能无趋势（B、D正确）","link":""},{"id":"phy0100","t":"力学·摩擦力·无摩擦≠光滑","s":"看到【选项问”接触面可能光滑/可能粗糙”类判断】","c":"想到【用三条件逐一排除：无摩擦时$\\mu$=0与μ$\\neq$0都可能成立，无法唯一确定粗糙程度】；警惕【把”无摩擦”等价于”$\\mu$=0”】","src":"物一轮015.知道摩擦力的产生条件_笔记","note":"视频|00:24","orig":"（知识）某接触面无摩擦的可能原因：①无弹力②光滑③无相对运动趋势，需具体分析，不能直接断定光滑","link":""},{"id":"phy0101","t":"力学·摩擦力·滑动摩擦力方向","s":"看到【画滑动摩擦力的方向】","c":"想到【先确定相对接触物的运动方向，摩擦力与其反向】；警惕【误按对地运动方向画摩擦力】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|00:21-01:33","orig":"（知识）滑动摩擦力方向与相对运动方向相反；判断难点在于确定”相对运动方向”（非对地运动方向）","link":""},{"id":"phy0102","t":"力学·摩擦力·标点法","s":"看到【需要严格确定两物体间相对运动方向】","c":"想到【用标点法：标记重合点、追踪各自位移、比较先后位置】；警惕【直接凭速度大小目测相对方向】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|01:33-01:45","orig":"（知识）标点法步骤：在接触物体上标记初始重合点→按各自速度计算Δt后新位置→比较位置变化定相对运动方向→摩擦力与相对运动反向","link":""},{"id":"phy0103","t":"力学·摩擦力·标点法例题","s":"看到【物块与木板速度大小方向各异的组合求摩擦力方向】","c":"想到【比较两者速度定相对运动方向，摩擦力必与其反向，与各自对地速度无直接关系】；警惕【同向运动时物块速度小也可能相对木板向后滑】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|01:45-06:07","orig":"（例）物块与木板多种速度组合（同向3m/s与2m/s、3m/s与5m/s、反向3m/s与2m/s）：分别判断物块相对木板向右/向左，摩擦力取反向","link":""},{"id":"phy0104","t":"力学·摩擦力·趋于共速法","s":"看到【一维板块问题判断摩擦力方向】","c":"想到【用趋于共速法：摩擦力方向应使快者减速、慢者加速】；警惕【该法仅限一维直线运动，二维不适用】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|06:07-09:24","orig":"（知识）仅适用一维直线运动：滑动摩擦力使两物体速度趋于相同——快的物体摩擦力使其减速，慢的物体使其加速，最终速度差减小","link":""},{"id":"phy0105","t":"力学·摩擦力·滑动摩擦因数特性","s":"看到【解出$\\mu$>1】","c":"想到【用$\\mu$<1反推检验计算过程是否出错】；警惕【不检查数量级，带着错误继续算】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|09:36-11:21","orig":"（知识）μ由接触面材质和粗糙程度决定；考试中μ值始终小于1，若计算得μ>1必定错误（实际生活中可能存在μ>1）","link":""},{"id":"phy0106","t":"力学·摩擦力·正压力N与重力","s":"看到【写滑动摩擦力公式】","c":"想到【N由受力分析确定，f=$\\mu$N】；警惕【不加分析地把N换成mg】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|11:21-11:41","orig":"（知识）f=μN中N是接触面间的正压力，非物体重力；常见误区是误将f=μN写成f=μmg","link":""},{"id":"phy0107","t":"力学·摩擦力·N的取值例题","s":"看到【不同情境（水平面/叠放/墙面压物）求滑动摩擦力】","c":"想到【先按具体受力确定正压力N，再代入f=$\\mu$N】；警惕【叠放时漏掉上层物体重量；墙面压物时N与重力无关】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|11:41-14:06","orig":"（例）三种情境求N：水平面单独物体N=mg→f=μmg；叠放物体N=(m1+m2)g→f=μ(m1+m2)g；墙面压物N=F（外力）→f=μF","link":""},{"id":"phy0108","t":"力学·摩擦力·静止物体受滑动摩擦","s":"看到【对地静止的物体问有无滑动摩擦力】","c":"想到【以接触面为参考系看相对运动，静止物体也可能受滑动摩擦】；警惕【把”对地静止”与”相对接触面静止”混同】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|14:09-16:16","orig":"（知识）”静止的物体一定不受滑动摩擦力”是错的：静止是相对地面，滑动摩擦看接触面间相对运动。反例：绳子拴住的物块对地静止，木板向右抽出时物块受向右的滑动摩擦力","link":""},{"id":"phy0109","t":"力学·摩擦力·摩擦力与运动方向关系","s":"看到【判断”滑动摩擦力一定与运动方向相反”】","c":"想到【摩擦力可以是阻力也可以是动力，只由相对运动方向决定】；警惕【默认摩擦力总是阻碍物体对地运动】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|16:16-17:23","orig":"（知识）滑动摩擦力与相对运动方向相反，与对地运动方向无必然联系：板块模型中木板受摩擦力可与运动方向相同（作为动力），物块受摩擦力与运动方向相反","link":""},{"id":"phy0110","t":"力学·摩擦力·非共线情形","s":"看到【两物体运动方向成夹角（二维相对滑动）】","c":"想到【在平面内合成相对速度方向，摩擦力沿其反向，可与物体运动方向不共线】；警惕【只在一维方向上找摩擦力】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|17:23-19:59","orig":"（例）俯视图中木板向下运动、物块向右运动：相对运动方向斜向右上方，物块受摩擦力斜向左下方，与物块向右的运动方向不共线","link":""},{"id":"phy0111","t":"力学·摩擦力·平衡误判例题","s":"看到【物体受拉力且题目未说明”匀速”求摩擦力】","c":"想到【若为滑动摩擦则f=$\\mu$N与拉力大小无关，再由合力分析运动状态】；警惕【未说明匀速/静止时不能默认受力平衡】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|19:59-23:43","orig":"（例）拉力10N、f=μN=0.1×200N=20N：误认为拉力与摩擦力平衡（10N）是错的，物体受向左合力做减速运动，摩擦力向左","link":""},{"id":"phy0112","t":"力学·摩擦力·多接触面例题","s":"看到【”缓慢拉出”且存在多个接触面】","c":"想到【”缓慢”=平衡态，各接触面摩擦力累加后与拉力平衡】；警惕【漏数摩擦面个数（如四个侧面只算两个）】","src":"物一轮016.画滑动摩擦力的方向并计算大小_笔记","note":"视频|23:43","orig":"（例）榫卯结构”缓慢拉出”：四个接触面产生摩擦力，拉力平衡F=4μF_N，得μ=F/(4F_N)","link":""},{"id":"phy0113","t":"相互作用·静摩擦力方向判断","s":"看到【判断静摩擦力方向（区别于滑动摩擦的趋势方向）】","c":"想到【静摩擦方向与相对运动趋势相反；趋势用假想光滑法或运动状态法判断】；警惕【静摩擦方向与物体实际运动方向无必然联系】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|00:14-01:26","orig":"（知识）静摩擦力方向始终与物体间相对运动趋势方向相反；趋势是「想要运动但实际静止」，比滑动摩擦更难判断","link":""},{"id":"phy0114","t":"相互作用·假想光滑法","s":"看到【直线运动+接触面受力复杂，判断静摩擦方向】","c":"想到【假想光滑法：假设接触面光滑$\\to$分析相对滑动方向$\\to$即为趋势方向$\\to$静摩擦与之相反】；警惕【非直线运动（如圆周）中此法易失效】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|01:26-06:02","orig":"（例）斜面AB整体静止（mA=m，mB=2m）：假设AB间光滑，B质量大向下滑→B相对A有向下趋势→A对B静摩擦沿斜面向上","link":""},{"id":"phy0115","t":"相互作用·运动状态法","s":"看到【圆周运动中物体随盘/带相对静止，判断静摩擦方向】","c":"想到【运动状态法：由向心加速度反推合力方向，静摩擦提供向心力指向圆心】；警惕【圆周运动必须用运动状态法，假想光滑法会误判为沿切线】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|06:02-10:36","orig":"（例）旋转圆盘上物块随盘匀速转动：假想光滑法会误判摩擦沿切线；实际物块需向心力→静摩擦指向圆心→趋势背离圆心","link":""},{"id":"phy0116","t":"相互作用·静摩擦力大小","s":"看到【求静摩擦力大小（物体平衡或相对静止）】","c":"想到【静摩擦无公式，按平衡条件或牛顿第二定律反推大小】；警惕【压力增大只是最大静摩擦增大，实际静摩擦不一定变】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|10:36-10:56","orig":"（知识）静摩擦无固定公式，是「被动力」（类似杆的弹力），由其他力和运动状态共同决定，随外力即时调整；最大静摩擦fmax∝N","link":""},{"id":"phy0117","t":"相互作用·最大静摩擦","s":"看到【推力/外力与摩擦力的关系图像，有峰值和水平段】","c":"想到【峰值即最大静摩擦，水平段为滑动摩擦f=$\\mu$N；最大静摩擦略大于滑动摩擦】；警惕【题目未特别说明时不能默认fmax=$\\mu$N】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|10:56-16:07","orig":"（例）推力-摩擦力图像：斜线上升（静摩擦）→突变下降→水平段（滑动摩擦）；峰值fmax=21N，滑动摩擦20N=μmg→μ=0.2","link":""},{"id":"phy0118","t":"相互作用·静摩擦判断误区","s":"看到【选项断言「运动的物体不受静摩擦」或「静摩擦必与运动方向相反/共线」】","c":"想到【静摩擦方向取决于相对运动趋势，与实际运动方向无必然联系（参考系不同）】；警惕【凭「物体在动」排除静摩擦是典型错误】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|16:07-18:38","orig":"（知识）误区辨析：运动的物体可受静摩擦（手握杯移动）；静摩擦可与运动方向相同（向上举杯）；静摩擦可与运动方向不共线","link":""},{"id":"phy0119","t":"相互作用·静摩擦应用例题","s":"看到【多物体叠放/接触场景逐个判断有无摩擦力】","c":"想到【逐接触点分析：无相对运动趋势则摩擦为零；用平衡条件和牛顿第三定律传递方向】；警惕【握力只影响最大静摩擦，不影响实际静摩擦】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|18:38","orig":"（例）书写「福」字：提笔静止时f=mg与握力无关；镇纸与红纸无相对运动趋势故摩擦为零；红纸受毛笔向右滑动摩擦→桌面给红纸向左静摩擦→红纸对桌面静摩擦向右","link":""},{"id":"phy0120","t":"相互作用·最大静摩擦变化","s":"看到【比较两种情况下静摩擦力与最大静摩擦谁变谁不变】","c":"想到【实际静摩擦由平衡条件定，正压力变化只改变最大静摩擦上限】；警惕【混淆「静摩擦不变」与「fmax减小」两层结论】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|18:38","orig":"（例）磁铁压纸片：两种情况静摩擦均F=mg不变；纸片折叠变厚→磁铁吸引力减小→N减小→fmax=μN减小","link":""},{"id":"phy0121","t":"相互作用·摩擦力方向方法总结","s":"看到【摩擦力方向判断方法的选择】","c":"想到【直线运动优先假想光滑法，圆周/曲线运动必须用运动状态法】；警惕【趋于共速法只适用于一维直线运动】","src":"物一轮017.画静摩擦力的方向并计算大小_笔记","note":"视频|18:38","orig":"（知识）滑动摩擦方向：标点法、趋于共速法（仅限一维直线）；静摩擦方向：假想光滑法（复杂受力更有效）、运动状态法（曲线运动更具优势）","link":""},{"id":"phy0122","t":"相互作用·摩擦力突变总览","s":"看到【题目涉及摩擦力大小或方向发生「突变」的分析】","c":"想到【先判断接触面是相对静止还是相对滑动，再按三类突变对应分析；突变根源是外力变化】；警惕【静摩擦与滑动摩擦的区分条件混淆】","src":"物一轮018.靜摩擦力-靜摩擦力突变完整视频_笔记","note":"","orig":"（知识）摩擦力突变分三类：静摩擦→静摩擦、静摩擦→滑动摩擦、滑动摩擦→滑动摩擦；突变原因是外力变化导致相对运动状态改变","link":""},{"id":"phy0123","t":"相互作用·静→静摩擦突变","s":"看到【物体保持静止，但外力F逐渐变化，问静摩擦如何变化】","c":"想到【用平衡条件正交分解跟踪摩擦力：先减至零（临界点）再反向增大】；警惕【忽略摩擦力为零的临界时刻】","src":"物一轮018.靜摩擦力-靜摩擦力突变完整视频_笔记","note":"","orig":"（例）斜面物体受外力F：F从零增大时，静摩擦先沿斜面向上减小至零，再反向（沿斜面向下）增大，物体始终保持静止","link":""},{"id":"phy0124","t":"相互作用·弹簧系统静摩擦突变","s":"看到【静止系统施加新外力后，某物体静摩擦数值突变但仍静止】","c":"想到【重新列平衡方程求新静摩擦；弹簧弹力具有瞬时保持特性】；警惕【误认为静止系统中摩擦力不会突变】","src":"物一轮018.靜摩擦力-靜摩擦力突变完整视频_笔记","note":"","orig":"（例）弹簧系统：施加推力后，木块B静摩擦从8N突变为2N（方向改变），系统仍保持静止","link":""},{"id":"phy0125","t":"相互作用·静摩擦突变命题特征","s":"看到【「相对静止」+外力变化的动态平衡情境】","c":"想到【以平衡条件为主线，逐状态重列方程，关注摩擦力方向反转的临界点】；警惕【凭直觉沿旧方向续算摩擦力】","src":"物一轮018.靜摩擦力-靜摩擦力突变完整视频_笔记","note":"","orig":"（知识）命题模型：物体在静摩擦和其他力作用下保持静止，其他力变化导致静摩擦力突变，考查相对静止的维持条件与外力-摩擦力的动态平衡","link":""},{"id":"phy0126","t":"相互作用·静摩擦到滑动摩擦突变","s":"看到【外力随时间线性变化（F=kt），物体从静止被逐渐拉动的全过程分析】","c":"想到【分段处理：静摩擦先减至零（F'=mgsin$\\theta$临界）再反向增，达fmax突变为f=$\\mu$N恒定；图像为折线+水平段】；警惕【弹簧弹力与外力等大反向同步变化，勿混淆弹力与外力的作用关系】","src":"物一轮019.静摩擦力-滑动摩擦力突变_笔记","note":"视频|00:06-06:30","orig":"（例）弹簧沿斜面拉物块，拉力F=kt：弹簧弹力F'与外力等大反向线性增长；静摩擦先沿斜面向上减小，F'=mgsinθ时为零，再反向向下增大；达fmax时突变为滑动摩擦μN恒定","link":""},{"id":"phy0127","t":"相互作用·滑动摩擦到静摩擦突变","s":"看到【变力作用下物体先加速后减速，问摩擦力随时间图像】","c":"想到【分段列F合：f=mg是速度最大转折点；v=0瞬间滑动摩擦突变为静摩擦（等于重力）】；警惕【减速阶段a增大但v仍减小，速度为零后摩擦性质立刻改变】","src":"物一轮019.静摩擦力-滑动摩擦力突变_笔记","note":"视频|06:30","orig":"（例）f=μkt竖直作用在下落物块上：f<mg时a减小v增大；f=mg时v最大；f>mg时a增大v减小；v=0瞬间突变为静摩擦f=mg保持静止","link":""},{"id":"phy0128","t":"相互作用·摩擦力突变原理总结","s":"看到【分析摩擦力为何、何时发生突变】","c":"想到【抓住逻辑链：外力$\\to$弹力$\\to$摩擦力$\\to$相对状态，临界点在f达fmax或v=0处】；警惕【突变前后摩擦性质不同，公式不可延续使用】","src":"物一轮019.静摩擦力-滑动摩擦力突变_笔记","note":"视频|06:30","orig":"（知识）突变的根本原因是相对运动状态改变（静止↔滑动）；逻辑链：外力变化→弹力变化→摩擦力调整→状态突变","link":""},{"id":"phy0129","t":"相互作用·滑动摩擦方向突变","s":"看到【物体先后在两个不同接触面上滑动（如桌布$\\to$桌面、传送带换面）】","c":"想到【逐阶段找参考系判相对运动方向，摩擦方向随相对运动反向而突变；大小看f=$\\mu$N中$\\mu$、N是否变化】；警惕【滑动摩擦方向与拉力无关，勿误判初始阶段摩擦方向】","src":"物一轮020.滑动摩擦力-滑动摩擦力突变_笔记","note":"视频|00:15-05:30","orig":"（例）猫拉桌布鱼缸：桌布比鱼缸快时，鱼缸相对桌布向左→滑动摩擦向右（带动鱼缸）；分离后鱼缸相对桌面向右→桌面对其摩擦向左；f=μN中μ、N均不变故大小不变，与拉力无关","link":""},{"id":"phy0130","t":"相互作用·传送带共速后的两种可能","s":"看到【物块与传送带共速瞬间，判断后续摩擦力性质与方向】","c":"想到【共速后比较重力分量与最大静摩擦：能平衡则转静摩擦匀速，不能则保持滑动摩擦继续加速】；警惕【共速后不一定转为静摩擦，多选题易漏掉加速下滑的可能】","src":"物一轮020.滑动摩擦力-滑动摩擦力突变_笔记","note":"视频|05:30","orig":"（例）物块无初速放上传送带：v=0时相对带向下滑→摩擦沿带向下使物块加速；共速后若匀速下滑则静摩擦向上平衡重力分量，若继续加速下滑则滑动摩擦向上小于重力分量","link":""},{"id":"phy0131","t":"相互作用·摩擦力方向判定通法","s":"看到【判断滑动摩擦力方向的任何场景】","c":"想到【以接触面为参考系标出相对运动方向，摩擦与之相反】；警惕【混淆相对运动方向与对地运动方向】","src":"物一轮020.滑动摩擦力-滑动摩擦力突变_笔记","note":"视频|00:15-05:30","orig":"（知识）滑动摩擦方向始终与相对运动方向相反；静摩擦方向需结合外力与运动趋势分析；可用标点法判断接触点相对运动方向","link":""},{"id":"phy0132","t":"相互作用·三类摩擦力突变总结","s":"看到【综合题中判断摩擦力发生哪种类型的突变】","c":"想到【按三类对号入座：先看是否仍相对静止，再看相对方向或$\\mu$、N是否变化】；警惕【高频考点为斜面、传送带场景下的突变条件】","src":"物一轮020.滑动摩擦力-滑动摩擦力突变_笔记","note":"视频|05:30","orig":"（知识）静→静：外力变化、物体始终静止；静↔动：相对运动状态改变；动→动：方向突变因相对运动方向改变，大小突变因μ或N变化（如斜向上拉力撤除致N增大）","link":""},{"id":"phy0133","t":"力学方法论·受力分析方法体系","s":"看到【拿到受力分析题不知从何下手】","c":"想到【三种方法按需选用：先按性质画力，再用运动状态定不确定的力，多物体用整体隔离】；警惕【受力分析是所有力学、电磁学解题的基础环节】","src":"物一轮021.【课前必看】本讲听课建议_笔记","note":"视频|00:24-01:46","orig":"（知识）受力分析三大方法：①按力的性质分析（需掌握弹力、摩擦力性质）；②按运动状态分析（牛顿第二定律F=ma）；③整体隔离法","link":""},{"id":"phy0134","t":"力学方法论·受力分析考情","s":"看到【纠结受力分析是否值得专项训练】","c":"想到【它是隐性高频考点：错一步力，后面计算与运动判断全错，必须扎实】；警惕【只刷综合题而忽略受力分析基本功】","src":"物一轮021.【课前必看】本讲听课建议_笔记","note":"视频|02:54-04:26","orig":"（知识）受力分析几乎不会单独命题（浙江卷可能结合力学运算单独考），但贯穿全卷作为解题基础；受力分析错误将导致整题连锁失分","link":""},{"id":"phy0135","t":"力学方法论·前置知识自检","s":"看到【复习受力分析前安排学习顺序】","c":"想到【先确认弹力/摩擦力性质已掌握，再学三大方法；用例题正确率决定是否跳级】；警惕【跳过前置直接学方法会导致似懂非懂】","src":"物一轮021.【课前必看】本讲听课建议_笔记","note":"视频|01:46-02:54","orig":"（知识）受力分析前置知识为弹力和摩擦力的大小、方向判断；可用讲义例题正确率自测掌握程度；整体隔离法是常见薄弱环节","link":""},{"id":"phy0136","t":"受力分析·性质力与效果力","s":"看到【选项说「物体受到向心力「或把效果力画进受力图】","c":"想到【受力图只画性质力，向心力/回复力由性质力（或其分力、合力）提供】；警惕【弹力双重命名：性质上是弹力，效果上叫支持力/压力】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|01:38-03:36","orig":"（知识）高中受力分析只画性质力：重力、弹力、摩擦力、库仑力、电场力、安培力、洛伦兹力（弹力/摩擦力本质是电磁相互作用）；效果力（支持力、压力、向心力、回复力）不能说「受到「","link":""},{"id":"phy0137","t":"受力分析·研究对象选择","s":"看到【多个物体叠放/接触的系统受力分析】","c":"想到【先隔离未知接触面最少的物体，再用牛顿第三定律传递到其他物体】；警惕【比较的是未知接触面数量而非接触面总数】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|10:33-13:00","orig":"（知识）优先分析未知接触面少的物体（而非总接触面少）；通过简单物体的受力可反推复杂物体的受力（如滑块Q仅2个接触点，先分析Q再推P）","link":""},{"id":"phy0138","t":"受力分析·画已知力与场力","s":"看到【开始对一个物体做受力分析】","c":"想到【第一步固定动作：先画已知力和场力（重力必画，带电体补电场/磁场力），再找接触力】；警惕【遗漏非典型场力（磁力、大气压力）】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|13:00-14:46","orig":"（知识）先画题干明确给出的已知力和场力：重力mg、库仑力F=kq₁q₂/r²、电场力F=Eq、安培力F=BIL、洛伦兹力F=qvB，其方向有明确判定方法","link":""},{"id":"phy0139","t":"受力分析·接触点排查","s":"看到【受力分析时直接「补一个摩擦力「来平衡其他力】","c":"想到【按「先弹力后摩擦力「顺序逐接触点排查】；警惕【无弹力处不可能有摩擦力，斜面问题漏画支持力是典型错误】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|14:46-16:50","orig":"（知识）环绕物体一周检查所有接触部位，每个接触点先判断弹力存在性、再判断摩擦力；摩擦力的存在必须以弹力存在为前提","link":""},{"id":"phy0140","t":"受力分析·运动状态检验","s":"看到【受力图画完需要自检】","c":"想到【用运动状态反查：各力矢量和必须匹配静止/匀速/加速状态】；警惕【静止物体合力为零而非等于重力】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|16:50-21:46","orig":"（知识）画完力后验证合力是否与实际运动状态一致：静止/匀速→合力为零；加速→合力沿加速度方向；避免凭感觉画力","link":""},{"id":"phy0141","t":"受力分析·叠放+弹簧例题","s":"看到【题目明确「某表面光滑「而另一表面未说明】","c":"想到【明确光滑处无摩擦，未说明处须考虑摩擦；弹簧弹力方向由压缩/拉伸状态定】；警惕【隔离法逐个分析时漏掉反作用力（N与N'）】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|21:46-27:26","orig":"（例）斜面上木板P压滑块Q（上表面光滑）接弹簧：先分析接触点少的Q（重力、P的斜向左上支持力、弹簧向右弹力，弹簧压缩）；再推P共受5个力","link":""},{"id":"phy0142","t":"受力分析·方向约束例题","s":"看到【力的方向有物理约束（阻力反v、升力垂直v、绳沿绳、杆沿杆或按平衡定）】","c":"想到【先用方向约束排除选项，再用四力平衡定剩余未知力方向】；警惕【升力垂直于速度而非竖直方向】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|27:26-29:53","orig":"（例）飞行物受力示意图：空气阻力f必与速度v方向相反（斜向右下），升力F₂必垂直v；排除方向错误的选项后，唯一能平衡的推力方向即正确答案","link":""},{"id":"phy0143","t":"受力分析·白板擦（含场力）例题","s":"看到【物体吸附在斜面/竖直面上保持静止（磁吸、吸盘）】","c":"想到【磁力/大气压力是场力先画；摩擦力存在性由平衡条件反推；斜面上接触体三力（场力+弹力+摩擦）合力竖直向上】；警惕【静止物体合力为零，不是「合力等于重力「】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|29:53-34:00","orig":"（例）磁吸白板擦静止：磁力（场力，垂直接触面斜向左上）+弹力+摩擦力，三力合力必与重力等大反向（竖直向上）；必须有摩擦力平衡重力沿斜面分量","link":""},{"id":"phy0144","t":"受力分析·静电平衡例题","s":"看到【带电体+绳/接触面的平衡问题】","c":"想到【口诀「场力优先，接触靠后「；按库仑力方向检验能否平衡，接触力可能为零（虚接触）】；警惕【90%错误源于受力分析顺序混乱】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|34:00-38:48","orig":"（例）带电小球平衡：先画重力、库仑力（同性斥/异性吸），再画接触力；存在虚接触——绳子存在但不影响运动状态时拉力可为零","link":""},{"id":"phy0145","t":"受力分析·大气压力例题","s":"看到【吸盘/大气压吸附类模型求物体受力个数】","c":"想到【大气压力是外界施加的场力，与玻璃弹力是两个不同的力；明确每个力的施力物体】；警惕【把「玻璃的作用力「当成竖直方向或漏算大气压力】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|38:48-43:07","orig":"（例）吸盘支架上的手机：受重力mg、大气压力F（垂直玻璃面）、玻璃弹力N、静摩擦f共4个力；玻璃对手机的作用力是弹力与摩擦力的合力（不竖直）","link":""},{"id":"phy0146","t":"受力分析·力的非传递性例题","s":"看到【力通过中间物体「传递「的情境（A推B、B推C）】","c":"想到【力无传递性：只分析直接作用于研究对象的力，按接触点逐个判断】；警惕【误认为A的推力会经B叠加传给车（车受2F）】","src":"物一轮022.根据力的性质受力分析_笔记","note":"视频|43:07","orig":"（例）两人推车未推动：A推B、B推车（推力均F）时，车只受B的推力F和地面摩擦力F，不受A的力；A自身受推力F与车反作用力平衡，地面对B摩擦为零","link":""},{"id":"phy0147","t":"受力分析·平衡状态判定","s":"看到【「缓慢移动「「逐渐拉动「等描述】","c":"想到【缓慢运动属于动态平衡，合力为零，按平衡条件处理】；警惕【把缓慢运动误当成有加速度的非平衡态】","src":"物一轮023.根据运动状态受力分析_笔记","note":"视频|03:53-05:15","orig":"（知识）平衡状态三种情形：静止、匀速直线运动、缓慢运动（「慢慢运动「「逐渐运动「）；力学特征F合=0","link":""},{"id":"phy0148","t":"受力分析·非平衡状态判定","s":"看到【物体做加速/减速直线运动，需确定合力方向】","c":"想到【先由运动特征定a的方向，合力必沿a方向，再反推某个力的方向或大小】；警惕【减速时合力与速度反向但与a同向】","src":"物一轮023.根据运动状态受力分析_笔记","note":"视频|05:15-07:07","orig":"（知识）直线加速：a与v同向；直线减速：a与v反向；力学特征F合=ma，合力方向与加速度方向一致","link":""},{"id":"phy0149","t":"受力分析·杆的弹力方向","s":"看到【杆/斜撑一端连球，系统处于静止或加速状态，求杆弹力】","c":"想到【杆弹力不一定沿杆方向：按平衡或a方向分解弹力，先定竖直分量=mg、水平分量=ma】；警惕【默认杆弹力沿杆是常见错误】","src":"物一轮023.根据运动状态受力分析_笔记","note":"视频|07:07-12:46","orig":"（例）杆上小球：静止时杆弹力竖直向上T=mg；向右加速时弹力竖直分量T₁=mg平衡重力、水平分量T₂=ma提供加速度，T=√((mg)²+(ma)²)，方向斜向右上；向左加速同理斜向左上","link":""},{"id":"phy0150","t":"受力分析·分类讨论题型","s":"看到【运动状态未明确（可能匀速/加速/减速），问某接触力的情况】","c":"想到【按运动状态分类讨论，逐状态列平衡或F=ma方程，注意某些状态不可能实现】；警惕【默认弹簧必有力或绳必有拉力，漏掉弹力为零的可能】","src":"物一轮023.根据运动状态受力分析_笔记","note":"视频|12:46-19:22","orig":"（例）球挂弹簧+细绳系统：匀速时绳无拉力、弹簧压缩；向右加速时必须绳有拉力提供水平分力，弹簧弹力可能为零/压缩/拉伸；向左加速无施力物体不可能","link":""},{"id":"phy0151","t":"受力分析·静摩擦与最大静摩擦","s":"看到【系统加速但题目给的是摩擦系数$\\mu$，求可能的最大合力】","c":"想到【静摩擦是被动可变的，仅在即将滑动时才等于$\\mu$mg；加速时f$\\leq$μmg，用勾股合成求合力上限】；警惕【把静摩擦直接取为$\\mu$mg】","src":"物一轮023.根据运动状态受力分析_笔记","note":"视频|19:22-24:54","orig":"（例）手指顶圆盘加速：竖直N=mg；水平静摩擦f≤μN=μmg提供加速度，合力上限mg√(1+μ²)；匀速时水平无净力，静摩擦为零","link":""},{"id":"phy0152","t":"受力分析·内切球几何约束","s":"看到【「内壁光滑「「内切/刚好接触「的球在运动容器中】","c":"想到【内切+光滑意味着无摩擦，接触力只沿法向；由a方向反推球挤压哪一侧壁】；警惕【减速时误判挤压侧（a与v反向）】","src":"物一轮023.根据运动状态受力分析_笔记","note":"视频|24:54","orig":"（例）光滑三棱柱内放内切球随柱匀速/加减速运动：匀速时球仅受重力和底面支持力，不挤压侧壁；向右加速挤压左侧壁获得向右分力，向左减速也挤压左侧壁，向右减速挤压右侧壁","link":""},{"id":"phy0153","t":"受力分析·内力与外力概念","s":"看到【多物体系统选「整体「的范围】","c":"想到【先定系统边界再分内外力；组合整体时确保物体间有相互作用，可按需自由组合（AB、BC、ABC）】；警惕【同一力在不同系统划分下内外属性会变】","src":"物一轮024.利用整体隔离法受力分析_笔记","note":"视频|01:51-03:54","orig":"（知识）外力=系统外物体对系统内物体的力；内力=系统内物体间的相互作用力；同一力随整体选择不同而性质改变（C对B的力在AB整体中为外力，在ABC整体中为内力）","link":""},{"id":"phy0154","t":"受力分析·整体法本质","s":"看到【求解系统与外界的相互作用力（地面摩擦、墙面弹力、绳拉力等）】","c":"想到【用整体法消除内力，只需分析重力和外部施的力，大幅减少未知量】；警惕【整体法不能求内力，且要求系统各部分运动状态相同】","src":"物一轮024.利用整体隔离法受力分析_笔记","note":"视频|04:33-08:55","orig":"（知识）整体法理论基础：系统内力（F_A→B与F_B→A）因牛顿第三定律矢量和为零，相加平衡方程后内力抵消，只剩外力；消除≠力消失，仅分析时无需考虑","link":""},{"id":"phy0155","t":"受力分析·求内力必须隔离","s":"看到【题目求系统内部物体间的摩擦力/弹力】","c":"想到【求内力必须隔离法；求外力优先整体法——「外力整体内力隔「】；警惕【系统选得太大把待求力变成内力】","src":"物一轮024.利用整体隔离法受力分析_笔记","note":"视频|08:55-14:53","orig":"（例）A叠在B上、B在C上受拉力F：求BC间摩擦力时若把ABC视为整体则该摩擦力变内力无法求解；正确做法隔离B（重力mBg、拉力F、A的压力N₁、C的支持力N₂、摩擦力f）","link":""},{"id":"phy0156","t":"受力分析·先整体后隔离","s":"看到【多物体问题，先判断某接触面有无作用力】","c":"想到【先整体排除外界作用（如墙壁无力），再隔离求内部力；某物体对另一物体的作用力=弹力与摩擦力的合力】；警惕【直接隔离导致受力不确定、漏力或把合力方向当成垂直接触面】","src":"物一轮024.利用整体隔离法受力分析_笔记","note":"视频|14:53-22:23","orig":"（例）A抱B靠竖直墙面匀速下滑：AB整体只受重力(M+m)g和拉力F→墙对A无作用力；再隔离B（重力mg、A的弹力N和摩擦力f）三力平衡；A实际受4个力，A对B的作用力是N与f的合力（竖直向上）","link":""},{"id":"phy0157","t":"受力分析·整体法求地面摩擦","s":"看到【斜面上的物体运动但整体静止，问地面摩擦力】","c":"想到【整体法一步到位：看整体水平方向有无外力，无则地面摩擦为零，无需分析内部复杂相互作用】；警惕【用隔离法逐个分析m_{1}、m_{2}的N、f再合成，又慢又易错】","src":"物一轮024.利用整体隔离法受力分析_笔记","note":"视频|22:23-25:07","orig":"（例）三角形木块M上两小木块m₁、m₂沿其下滑，系统静止：整体只受总重力(M+m₁+m₂)g和地面支持力N，水平方向无外力→地面摩擦力为零","link":""},{"id":"phy0158","t":"受力分析·整体法定绳方向","s":"看到【系统受成对等大反向外力，判断某绳的方向】","c":"想到【先整体：抵消对称外力，由重力定主绳方向；再隔离：由剩余不平衡定次绳方向】；警惕【同时处理多个未知绳力而陷入僵局】","src":"物一轮024.利用整体隔离法受力分析_笔记","note":"视频|25:07-28:22","orig":"（例）两球系统两端受等大反向外力F：整体看，F相互抵消，只剩总重力与上端绳拉力→上绳必竖直；再隔离下球：重力+斜向右上的F→下绳拉力须左偏平衡","link":""},{"id":"phy0159","t":"受力分析·整体法定支持力变化","s":"看到【系统内部结构变化（移动、换位置）后问外界支持力变化】","c":"想到【整体法看某方向：总重力不变则该方向支持力不变，与内部位置无关】；警惕【并非所有外力都能由整体法定出，定量求摩擦需隔离】","src":"物一轮024.利用整体隔离法受力分析_笔记","note":"视频|28:22-33:58","orig":"（例）直角支架AO（粗糙水平杆套P环）与OB（光滑竖直杆套Q环）用细绳连接平衡：P左移后整体竖直方向仍平衡，N=2mg不变；OB杆弹力与摩擦力需隔离Q分析","link":""},{"id":"phy0160","t":"受力分析·三种方法总结","s":"看到【任何受力分析综合题的总体策略选择】","c":"想到【流程：先按性质画力，再按运动状态定不确定的力，多物体先整体后隔离】；警惕【接触点排查不全导致漏力，是受力分析第一大错因】","src":"物一轮024.利用整体隔离法受力分析_笔记","note":"视频|33:58","orig":"（知识）方法体系：①力的性质法——选研究对象（接触面少者优先）→画已知力/场力→环绕找接触点→先弹力后摩擦→按运动状态检验；②运动状态法——平衡F合=0，非平衡F=ma且合力沿a方向；③整体隔离法——求外力用整体，求内力用隔离","link":""},{"id":"phy0161","t":"共点力平衡·知识体系定位","s":"看到【共点力平衡类力学题】","c":"想到【知识链为：弹力$\\to$摩擦力$\\to$受力分析$\\to$力的运算，先按力个数选方法再动手】；警惕【运算不熟练会拖慢所有力学大题，需练到快速准确完成三角函数运算】","src":"物一轮025.【课前必看】本讲听课建议_笔记","note":"视频|00:08-00:27","orig":"（知识）共点力平衡分三大模块：基础（矢量运算法则、正交分解法）、中等（静态平衡、基础动态平衡）、高阶（辅助圆/拉密定理法、晾衣杆模型），是力学四讲的收官运算环节","link":""},{"id":"phy0162","t":"共点力平衡·考情与命题趋势","s":"看到【静态平衡与电场力/磁场力结合的选择题】","c":"想到【先把电磁力当作普通力纳入受力分析，再按共点力平衡方法处理】；警惕【动态平衡高考占比更高，不能只练静态】","src":"物一轮025.【课前必看】本讲听课建议_笔记","note":"视频|02:45-04:35","orig":"（知识）单独考查时静态平衡多与电磁学综合（电场力/磁场力），动态平衡局限在力学章节（重力/弹力/摩擦力）","link":""},{"id":"phy0163","t":"共点力平衡·考查形式","s":"看到【平衡问题出现在选择题或解答题中】","c":"想到【共点力平衡是矢量运算基本功，单题提速可为压轴题争取时间】；警惕【重理解更要重运算熟练度，需反复练习提速】","src":"物一轮025.【课前必看】本讲听课建议_笔记","note":"视频|04:35-06:07","orig":"（知识）选择题在贵州/河北/山东等多省份近年均有考查，解答题在新疆（代表全国卷省份）、福建等地出现，年均1-2题","link":""},{"id":"phy0164","t":"力的合成·平行四边形定则","s":"看到【求两个力的合力、用平行四边形定则作图】","c":"想到【严格保证两力箭尾重合后作平行四边形，取所夹对角线为合力】；警惕【仅箭头相交不符合条件，需先把力平移至箭尾重合再作图】","src":"物一轮026.矢量运算法则_笔记","note":"视频|01:46-04:44","orig":"（知识）将两力平移至箭尾重合，以两力为邻边作平行四边形，合力为两力所夹对角线（从公共箭尾指向对角顶点）","link":""},{"id":"phy0165","t":"力的合成·平行四边形定则判断","s":"看到【判断图中合力作法是否正确】","c":"想到【先检查是否满足箭尾重合，不满足则平移后重新作平行四边形取对角线】；警惕【原图箭头相交的合力方向必然错误】","src":"物一轮026.矢量运算法则_笔记","note":"视频|04:44-06:49","orig":"（例）图中F1与F2仅箭头相交，判断所画合力是否正确","link":""},{"id":"phy0166","t":"力的合成·多力合成","s":"看到【n个力求合力】","c":"想到【n个力需n-1次平行四边形运算逐次合成，或用三角形定则一次首尾连接完成】；警惕【机械逐个合成，应先观察对称性与特殊角度】","src":"物一轮026.矢量运算法则_笔记","note":"视频|06:49-10:30","orig":"（例）求三个力的合力，先对F1、F2用平行四边形定则得F12，再将F12与F3合成","link":""},{"id":"phy0167","t":"力的合成·等大分力推论","s":"看到【两个等大分力、已知夹角$\\theta$】","c":"想到【直接用F合=2Fcos($\\theta$/2)，合力沿角平分线（菱形对角线性质）】；警惕【120$^{\\circ}$夹角时合力大小等于分力（等边三角形），口诀\"等大分力120$^{\\circ}$，合力不变沿角分\"】","src":"物一轮026.矢量运算法则_笔记","note":"视频|10:30-16:46","orig":"（知识）F1=F2=F且夹角θ时，F合=2Fcos(θ/2)，方向沿两力夹角的角平分线；θ=120°时F合=F","link":""},{"id":"phy0168","t":"力的合成·三角形定则","s":"看到【多个力求合力、要求一次作图完成】","c":"想到【所有力首尾连接，合力由首力尾端指向末力首端】；警惕【三角形定则要求首尾连接，与平行四边形定则的尾部重合操作不同】","src":"物一轮026.矢量运算法则_笔记","note":"视频|16:46-21:44","orig":"（知识）将两力平移至首尾连接，合力由第一个力的尾部指向第二个力的首部；多力依次首尾连接，合力从第一个力尾指向最后一个力首","link":""},{"id":"phy0169","t":"力的合成·封闭图形推论","s":"看到【几个力首尾连接构成封闭图形/闭合三角形】","c":"想到【合力为0，特殊三角形（直角用勾股、等腰用对称、等边三力相等）可简化计算】；警惕【题目只说\"封闭\"但未首尾连接时合力不为零，需先检验首尾连接条件】","src":"物一轮026.矢量运算法则_笔记","note":"视频|21:48-23:18","orig":"（知识）n个力首尾依次连接构成封闭图形时，合力为0；三力合力为零构成闭合三角形，可用三角函数求解","link":""},{"id":"phy0170","t":"力的合成·封闭图形应用","s":"看到【选项给出多种力的连接方式比较合力】","c":"想到【对非首尾连接的图形用三角形定则算出实际合力再比较，边长决定合力大小】；警惕【误认为所有封闭图形合力都为零】","src":"物一轮026.矢量运算法则_笔记","note":"视频|23:18-25:22","orig":"（例）封闭图形中各力未首尾连接，需逐项计算实际合力比较大小，斜边f2最长对应合力最大，答案D","link":""},{"id":"phy0171","t":"力的合成·圆的几何性质","s":"看到【力的端点分布在圆上、含直径或弦】","c":"想到【善用圆的几何性质简化计算：直径所对圆周角为90$^{\\circ}$，垂直关系使平行四边形退化为矩形】；警惕【忽略几何条件直接硬算】","src":"物一轮026.矢量运算法则_笔记","note":"视频|29:34-31:58","orig":"（例）三力尾部重合于半圆上，AB为直径则∠APB=90°，f1⊥f3，利用直径与圆周角关系逐步合成，答案C","link":""},{"id":"phy0172","t":"力的合成·六力合成策略","s":"看到【多力合成且存在反向共线或对称特殊角】","c":"想到【观察优先：先合成反向共线力对，再利用特殊角（60$^{\\circ}$、90$^{\\circ}$、120$^{\\circ}$）与对称性简化】；警惕【物理更重逻辑而非计算，多力问题必有简化技巧，硬算易错】","src":"物一轮026.矢量运算法则_笔记","note":"视频|31:58-38:05","orig":"（例）六个共点力求合力：先合成反向共线力对（f与4f、2f与5f、3f与6f），再利用120°夹角特性，答案D","link":""},{"id":"phy0173","t":"力的分解·分解原则","s":"看到【要求把一个力按效果分解】","c":"想到【先受力分析、由平衡或运动需求反推分解方向（如斜面上重力分解为沿斜面与垂直斜面）】；警惕【分解方向由平衡需求决定而非固定模式，不能机械记忆】","src":"物一轮026.矢量运算法则_笔记","note":"视频|38:05-45:35","orig":"（知识）一力分解为两个不共线的力有无穷多种方法；实际按作用效果分解，先画完整受力，再根据解题需要（如平衡条件）确定分解方向","link":""},{"id":"phy0174","t":"力的分解·重力分解应用","s":"看到【问重力应沿哪两个方向分解】","c":"想到【通过受力分析看重力要抵消哪些力，沿对应反方向分解】；警惕【不审受力直接套\"沿斜面/垂直斜面\"的分解】","src":"物一轮026.矢量运算法则_笔记","note":"视频|45:35-46:46","orig":"（例）小球受重力mg、绳拉力T、斜面弹力N三力平衡，重力需抵消T和N，故分解为沿绳方向和垂直斜面方向，答案C","link":""},{"id":"phy0175","t":"力的分解·对称受力求侧压","s":"看到【对称结构求侧壁压力、已知竖直外力】","c":"想到【利用对称性列几何关系分解，角度难判时用极限法夸张作图辅助】；警惕【忽略对称受力特征或错误判断角度关系】","src":"物一轮026.矢量运算法则_笔记","note":"视频|46:46","orig":"（例）锥形筒内四颗铁珠顶角120°，弹簧施加竖直力F，由30°-60°三角形关系得侧向压力为√3F/3，答案A","link":""},{"id":"phy0176","t":"正交分解法·适用与步骤","s":"看到【多个力夹角为一般角、求合力】","c":"想到【正交分解四步：建系让更多力落在轴上$\\to$三角函数分解$\\to$求两轴代数和$\\to$勾股合成】；警惕【正交分解的最终目的是算合力，而非单纯分解】","src":"物一轮027.正交分解法_笔记","note":"视频|01:28-02:10","orig":"（知识）通过分解方式求合力，适用于一般角度（非30°、45°、60°等特殊角）；步骤：建系→分解不在轴上的力→分别求Fx、Fy→勾股定理F合=√(Fx²+Fy²)","link":""},{"id":"phy0177","t":"正交分解法·一般角拆分","s":"看到【夹角是一般角但可拆成特殊角之和（如105°）】","c":"想到【把一般角拆为特殊角组合建系，分别投影后求和】；警惕【混淆sin/cos对应关系：邻边=Fcos$\\theta$、对边=Fsin$\\theta$】","src":"物一轮027.正交分解法_笔记","note":"视频|02:10-14:09","orig":"（例）F1=F2=10N夹角105°，将105°拆为60°+45°建系，分别算出各分量后代数求和再合成","link":""},{"id":"phy0178","t":"正交分解法·坐标系选择","s":"看到【多数力已沿水平竖直方向、仅一两个斜力】","c":"想到【优先选水平-竖直坐标系，让尽量多的力直接落在轴上，只分解斜力】；警惕【随意建系导致分解复杂化】","src":"物一轮027.正交分解法_笔记","note":"视频|14:09-17:26","orig":"（例）F1=15N竖直向下、F2=10N水平向右、F3=10N斜向上45°，选水平-竖直坐标系只需分解F3，F合=5√17N","link":""},{"id":"phy0179","t":"正交分解法·对称性简化","s":"看到【两斜力对称分布】","c":"想到【利用对称性使水平分量自动抵消，合力即y方向分力，省去一半计算】；警惕【对称关系判断错误导致漏算或重复计算】","src":"物一轮027.正交分解法_笔记","note":"视频|17:26-23:50","orig":"（例）F1向下，两个对称的10N斜力夹角120°，水平分量自动抵消，只需算y方向合力Fy=5N","link":""},{"id":"phy0180","t":"正交分解法·熟练度要求","s":"看到【考试中频繁用到力的投影】","c":"想到【练到\"看图即写分量\"的程度，避免考场推导浪费时间】；警惕【基本功不扎实导致整体解题卡顿】","src":"物一轮027.正交分解法_笔记","note":"视频|17:26-23:50","orig":"（知识）三角函数关系邻边=Fcosθ、对边=Fsinθ需熟练，特殊角三角函数值记忆准确","link":""},{"id":"phy0181","t":"静态平衡·平衡状态判断","s":"看到【物体静止或匀速直线运动】","c":"想到【按平衡处理：ΣF=0，任意方向分量代数和为零（ΣFx=0、ΣFy=0）】；警惕【匀速圆周运动有向心加速度，不是平衡状态】","src":"物一轮028.静态平衡问题_笔记","note":"视频|00:03-03:16","orig":"（知识）平衡状态=静止或匀速直线运动，本质是加速度为零；匀速圆周运动存在向心加速度，不属于平衡","link":""},{"id":"phy0182","t":"静态平衡·方法选择","s":"看到【平衡问题要选解题方法】","c":"想到【按力个数选法：三力优先合成法（闭合三角形），四力及以上必用正交分解列ΣFx=0、ΣFy=0】；警惕【有明显直角/等腰几何特征时合成法更快，不要一律硬列方程】","src":"物一轮028.静态平衡问题_笔记","note":"视频|03:16-12:26","orig":"（知识）正交分解法适用四力及以上平衡；合成法适用三力平衡，将三力首尾相连构成闭合三角形，几个力的合力必与剩余力的合力等大反向","link":""},{"id":"phy0183","t":"静态平衡·三力平衡合成法（斜面）","s":"看到【斜面上物体三力平衡求力的大小关系】","c":"想到【重力与垂直斜面方向的夹角等于斜面倾角，平移力构造直角三角形用三角函数求解】；警惕【想当然认为F>G，实际F=Gtan$\\theta$通常小于G】","src":"物一轮028.静态平衡问题_笔记","note":"视频|15:56-28:19","orig":"（例）物体受重力G、推力F、支持力N三力平衡，构造直角三角形得N=G/cos30°=2√3G/3>G、F=Gtan30°=√3G/3，答案C（N>G）","link":""},{"id":"phy0184","t":"静态平衡·死结与活结","s":"看到【绳有固定结点（死结）、两侧绳拉力关系】","c":"想到【死结两侧张力可不等，需由平衡条件求解；两力等大且夹角已知时用等腰三角形几何关系】；警惕【误认为死结两侧拉力相等——那是活结/滑轮的特性】","src":"物一轮028.静态平衡问题_笔记","note":"视频|28:19-33:08","orig":"（例）甲乙质量相等（右侧绳拉力=mg），死结处左侧绳张力T≠mg，两力等大构成等腰三角形，顶角70°则底角β=(180°-70°)/2=55°，答案B","link":""},{"id":"phy0185","t":"静态平衡·接触力合成思想","s":"看到【接触点多、接触力方向复杂难逐一分析】","c":"想到【把接触力整体归类为一个合力，由平衡条件知其与重力等大反向，避免冗余分析】；警惕【接触力过多时不合并分析，正交分解计算复杂易错】","src":"物一轮028.静态平衡问题_笔记","note":"视频|33:08-36:35","orig":"（例）物体接触点多导致受力分析困难，把所有接触力合成为一个合力F，匀速时F与重力mg等大反向（竖直向上），答案B","link":""},{"id":"phy0186","t":"静态平衡·对称双绳悬挂","s":"看到【两绳对称悬挂重物、夹角变化分析拉力】","c":"想到【用菱形合成法：两等大拉力的合力沿角平分线，2Tcos($\\theta$/2)=mg，夹角增大拉力增大】；警惕【夹角定义混淆：是两绳间夹角还是绳与竖直方向夹角，公式形式随之不同】","src":"物一轮028.静态平衡问题_笔记","note":"视频|36:35-44:08","orig":"（例）体操悬吊：两绳对称拉力T满足2Tcos(θ/2)=mg，θ增大T增大；θ=60°时T=mg（等边三角形），θ>60°时T>mg","link":""},{"id":"phy0187","t":"静态平衡·整体法","s":"看到【系统内某绳内力不要求求解（大小方向均未知）】","c":"想到【整体法把多物体视为一个整体，跳过未知内力直接列外力平衡，结合特殊三角形比例快速求解】；警惕【题目要求内力时不能用整体法】","src":"物一轮028.静态平衡问题_笔记","note":"视频|44:08","orig":"（例）三球系统只求a、c绳拉力，用整体法：整体重2G，Ta、Tc与2G构成直角三角形，按3-4-5比例得Ta=2.5G、Tc=1.5G，答案A","link":""},{"id":"phy0188","t":"动态平衡·问题识别","s":"看到【题干出现\"缓慢\"\"渐渐\"或物体匀速运动但受力持续变化】","c":"想到【每个瞬时都按平衡处理（ΣF=0），分析力随参数（角度、位置）的变化规律】；警惕【匀速$\\neq$静态平衡，受力可以一直在变】","src":"物一轮029.动态平衡问题_笔记","note":"视频|00:26-01:54","orig":"（知识）\"缓慢/慢慢/渐渐\"或匀速运动中力的大小方向持续变化，均属动态平衡；本质是每个瞬时ΣF=0","link":""},{"id":"phy0189","t":"动态平衡·方法选择","s":"看到【动态平衡题要选方法】","c":"想到【按力的个数分流：n$\\geq$4正交分解，n=3用三角形合成法看几何图形变化】；警惕【合成法是动态平衡的重点难点，需按力的变化特征（方向固定/大小固定）细分策略】","src":"物一轮029.动态平衡问题_笔记","note":"视频|01:54-03:10","orig":"（知识）四力及以上用正交分解（建系统列ΣFx=0、ΣFy=0推导力的变化）；三力平衡专用合成法（闭合三角形），按变力特征选策略","link":""},{"id":"phy0190","t":"动态平衡·正交分解（船靠岸）","s":"看到【四力平衡且某角度随运动逐渐变化】","c":"想到【正交分解列两个平衡方程，把角度增减代入cos/sin的增减逐力推变化】；警惕【某个力恒定时（如阻力f），其余力必须联动补偿，不能孤立判断】","src":"物一轮029.动态平衡问题_笔记","note":"视频|03:10-07:54","orig":"（例）船匀速靠岸受mg、拉力F、阻力f、浮力F浮：f-Fcosθ=0、F浮+Fsinθ-mg=0，θ增大→F增大、F浮减小","link":""},{"id":"phy0191","t":"动态平衡·射线法（方向不变力）","s":"看到【三力平衡：一个恒力+一个方向不变的力+一个全变的力】","c":"想到【射线法：恒力为基准边，方向不变的力画射线，闭合三角形边长即力的大小；全变的力与射线垂直（垂线段最短）时取最小值】；警惕【不保证首尾相连导致三角形画错，力的大小对应线段长度】","src":"物一轮029.动态平衡问题_笔记","note":"视频|07:54-16:50","orig":"（例）三力平衡（mg、TOA、TOB），A点上移：TOB方向不变画射线，闭合三角形中TOB线段变短即力减小；TOA先减后增，垂直射线（垂线段）时最小","link":""},{"id":"phy0192","t":"动态平衡·先减后增判断","s":"看到【旋转挡板/斜面类动态平衡问某力先减后增】","c":"想到【找变力的最小值位置：当变力与方向不变的力垂直时最小，之前减之后增】；警惕【误判旋转方向导致角度变化分析错误】","src":"物一轮029.动态平衡问题_笔记","note":"视频|16:50-20:45","orig":"（例）小球受mg、斜面支持力F2'、挡板压力F1'，挡板旋转：F1'存在最小值（垂直F2'时），故F1先减小后增大；F2'长度持续缩短，F2一直减小，答案B","link":""},{"id":"phy0193","t":"动态平衡·辅助圆（大小不变力）","s":"看到【一个力大小恒定、方向变化，求另一力或角度的极值】","c":"想到【画圆表示大小不变力的矢量末端轨迹，极值出现在圆的切线处（直角三角形解出sin$\\theta$max=F/mg）】；警惕【钝角区间sin$\\theta$先增后减的单调性、相切才对应极值】","src":"物一轮029.动态平衡问题_笔记","note":"视频|20:45-26:54","orig":"（例）恒定重力mg、大小恒定的拉力F（F<mg）、方向可变的细线T：F矢量末端轨迹为圆，T与圆相切时偏角最大，sinθmax=F/mg","link":""},{"id":"phy0194","t":"动态平衡·弹簧秤变式（圆法）","s":"看到【三力中\"恒力+定值力+全变力\"组合求极值】","c":"想到【大小不变的力用圆轨迹表示，通过有向线段（弦）判断全变力的大小方向变化】；警惕【混淆\"方向不变\"（画射线）与\"大小不变\"（画圆）两种几何处理】","src":"物一轮029.动态平衡问题_笔记","note":"视频|26:54-34:59","orig":"（例）F1大小方向都不变、F2大小不变、F3全变：以F1端点为圆心画圆表示F2，连接圆上点与F1另一端点表示F3，最大偏角sinθmax=F/mg","link":""},{"id":"phy0195","t":"动态平衡·相似三角形法","s":"看到【变力沿物体连线方向（绳拉力、杆弹力、圆弧弹力等）】","c":"想到【相似三角形法：力三角形与几何三角形相似，列比例式由几何边长变化判断力变化】；警惕【几何边与力边未正确对应，比例式写错】","src":"物一轮029.动态平衡问题_笔记","note":"视频|34:59-42:45","orig":"（例）支持力N沿半径、拉力F沿绳，力学三角形与几何三角形相似，列比例mg/h=F/l=N/R=k，得N不变、F逐渐减小","link":""},{"id":"phy0196","t":"动态平衡·滑轮活结与二力杆","s":"看到【滑轮（活结）+二力可转杆的动态系统】","c":"想到【活结保证两端绳拉力相等（本例恒等于mg），杆弹力沿杆方向，再用相似三角形分析变化】；警惕【误认为活结拉力会变化、忽略二力杆弹力沿杆的特性】","src":"物一轮029.动态平衡问题_笔记","note":"视频|42:45-48:31","orig":"（例）轻杆为二力可转杆（弹力沿杆），滑轮为活结（两端绳拉力相等），列相似三角形比例mg/AB=T/AC=F/B，AB增大则k减小、F减小、T=mg不变","link":""},{"id":"phy0197","t":"动态平衡·三角法总结","s":"看到【三力动态平衡题归类】","c":"想到【先识别每个力的特征（恒力/方向不变/大小不变/沿连线），特征对应唯一几何方法】；警惕【特征识别错误则整套方法失效】","src":"物一轮029.动态平衡问题_笔记","note":"视频|49:04","orig":"（知识）三角形法按力特征选几何处理：方向不变的力画射线、大小不变的力画圆、沿连线方向的力（绳/杆/圆弧弹力、万有引力、库仑力等）用相似三角形","link":""},{"id":"phy0198","t":"复杂动态平衡·辅助圆法适用条件","s":"看到【三力平衡+一个恒力+两个变力夹角保持不变】","c":"想到【辅助圆法：三力首尾连成闭合三角形后画外接圆，在圆上移动定角顶点，弦长变化即力的变化】；警惕【先核对适用条件，定角特征不满足时不能用外接圆】","src":"物一轮030.辅助圆-拉密定理法_笔记","note":"视频|10:08-11:25","orig":"（知识）适用条件：三力平衡、存在一个大小方向都不变的恒力（如mg）、两个变力之间夹角α恒定（α>π/2）","link":""},{"id":"phy0199","t":"复杂动态平衡·辅助圆几何原理","s":"看到【变力对应弦变为直径】","c":"想到【定边对定角保证外接圆不变，弦长最大=直径即该力最大；弦长单调增/减对应力单调变化】；警惕【两变力变化趋势可以不同：一个单调、一个先增后减】","src":"物一轮030.辅助圆-拉密定理法_笔记","note":"视频|01:17-10:05","orig":"（例）OM与MN绳夹角α恒定：定边对定角（恒力mg对应圆周角π-α不变），TMN从零逐渐增大至直径（一直增大），TOM先增大（至直径）后减小（单峰变化）","link":""},{"id":"phy0200","t":"复杂动态平衡·拉密定理法","s":"看到【定角动态平衡问题、不想精确作图】","c":"想到【拉密定理（正弦定理）：力之比等于对角正弦之比，追踪角度从锐角$\\to$90$^{\\circ}$$\\to$钝角时sin的变化趋势】；警惕【sin$\\theta$在钝角区间先增后减，不是单调的；各角的几何对应关系不能写错】","src":"物一轮030.辅助圆-拉密定理法_笔记","note":"视频|11:25-21:03","orig":"（知识）基于正弦定理：mg/sinα=TMN/sinβ=TOM/sinγ，其中α为两变力间定角；追踪各角变化趋势判断力变化","link":""},{"id":"phy0201","t":"复杂动态平衡·两种方法对比","s":"看到【动态平衡题在辅助圆与拉密定理间选择】","c":"想到【几何思维强用辅助圆，代数能力好用拉密定理；结果不一致时说明角度判断有误，用另一法验证】；警惕【终态用极端位置检验结论合理性】","src":"物一轮030.辅助圆-拉密定理法_笔记","note":"视频|21:03-21:59","orig":"（知识）辅助圆法几何直观（需准确作图），拉密定时代数分析（需正确判断角度趋势），两者结论一致可相互验证","link":""},{"id":"phy0202","t":"复杂动态平衡·应用案例（双绳旋转）","s":"看到【一绳方向固定、另一绳缓慢旋转到特定位置】","c":"想到【识别定角（两变绳夹角不变），辅助圆或拉密定理追踪角变化得力的单调性】；警惕【初始状态各力方向要明确（谁水平谁倾斜），误判旋转方向全盘皆错】","src":"物一轮030.辅助圆-拉密定理法_笔记","note":"视频|21:59","orig":"（例）小球受mg、Ta、Tb，a绳由水平转至b绳水平的过程中：β从90°增大sinβ减小→Tb减小；γ从钝角减至90°sinγ增大→Ta增大，答案D","link":""},{"id":"phy0203","t":"全反力法·全反力与摩擦角","s":"看到【物体同时受弹力N和滑动摩擦力f（f=$\\mu$N）】","c":"想到【把N与f合成为一个方向固定的全反力，tan$\\alpha$=$\\mu$，将四力平衡降为三力平衡】；警惕【摩擦角是全反力与弹力（法线方向）的夹角，方向与运动趋势相关】","src":"物一轮031.全反力法_笔记","note":"视频|00:21-14:50","orig":"（知识）弹力N与摩擦力f的合力F'称为全反力，方向固定，与竖直方向夹角α满足tanα=μ；α为摩擦角（全反力与弹力夹角）","link":""},{"id":"phy0204","t":"全反力法·拉力最小值（代数法）","s":"看到【匀速运动、拉力方向可变、求最小拉力】","c":"想到【正交分解消元后用辅助角公式a·sin$\\theta$+b·cos$\\theta$=√($a^2$+$b^2$)sin($\\theta$+$\\varphi$)求分母最大值，其中tan$\\varphi$=$\\mu$】；警惕【极值条件是sin($\\theta$+$\\varphi$)=1，不是$\\theta$=某特殊角】","src":"物一轮031.全反力法_笔记","note":"视频|00:21-14:50","orig":"（例）物体在水平面匀速运动，拉力F与水平方向成θ角：Fcosθ=μN、N+Fsinθ=mg，消元得F=μmg/(cosθ+μsinθ)，辅助角公式cosθ+μsinθ=√(1+μ²)sin(θ+φ)，θ+φ=90°时分母最大","link":""},{"id":"phy0205","t":"全反力法·拉力最小值（几何法）","s":"看到【恒力+方向不变力+全变力的三力组合求最小值】","c":"想到【垂线段最短：全变力垂直于方向不变力时最小，Fmin=mgsin$\\alpha$=$\\mu$mg/√(1+$\\mu$^{2})，与代数法结果一致】；警惕【几何法更直观，但需先正确合成全反力并定准其方向】","src":"物一轮031.全反力法_笔记","note":"视频|00:21-14:50","orig":"（例）同题用全反力法：三力平衡（mg不变、全反力F'方向不变、F全变），F垂直于F'时取得最小值，Fmin=mgsinα=μmg/√(1+μ²)","link":""},{"id":"phy0206","t":"全反力法·四力转三力合成原则","s":"看到【四力动态平衡难以直接分析】","c":"想到【合成两力转三力，优先合成方向不变的力或大小方向均不变的恒力，再用矢量三角形+垂线段最短求极值】；警惕【合成对象选择不当会让变化分析更复杂】","src":"物一轮031.全反力法_笔记","note":"视频|14:50","orig":"（例）绳牵引小船：受mg、浮力F浮、阻力f、拉力T，可将mg与F浮合成F'1（或mg与f合成F'2）转成三力动态平衡，分析得T逐渐增大、F浮减小","link":""},{"id":"phy0207","t":"全反力法·方法对比","s":"看到【求极值的平衡问题选择代数还是几何】","c":"想到【复杂函数关系用代数（辅助角公式），方向特征明确用几何（全反力/矢量三角形）】；警惕【两种方法都要求摩擦角tan$\\alpha$=$\\mu$这一桥梁结论扎实】","src":"物一轮031.全反力法_笔记","note":"视频|14:50","orig":"（知识）代数法依赖辅助角公式、计算较复杂；几何法直观形象，适用于四力平衡转三力平衡问题","link":""},{"id":"phy0208","t":"晾衣杆模型·模型识别与公式","s":"看到【一根绳跨过光滑挂钩/滑轮挂重物、绳两端固定】","c":"想到【晾衣杆模型：2Tcos$\\theta$=mg与sin$\\theta$=d/L联立，L是不变量，由d变化推$\\theta$变化再推T】；警惕【活结两侧绳拉力相等，延长绳构造等腰三角形是推导关键】","src":"物一轮032.晾衣杆模型_笔记","note":"视频|00:28-11:09","orig":"（知识）轻质不可伸长绳两端固定、悬挂光滑衣架钩（单滑轮/光滑挂钩），悬挂点三力平衡满足2Tcosθ=mg（θ为绳与竖直方向夹角），且sinθ=d/L（d为两杆间距，L为绳长）","link":""},{"id":"phy0209","t":"晾衣杆模型·张力变化规律","s":"看到【悬挂点或杆移动，问绳拉力如何变化】","c":"想到【控制变量：T只由水平间距d决定——d增大T增大，d减小T减小，d不变（仅竖直上移）T不变】；警惕【混淆活结与死结的受力差异、忽略绳长L不变这一约束】","src":"物一轮032.晾衣杆模型_笔记","note":"视频|00:28-11:09","orig":"（例）b点上移：d不变→θ不变→T不变；N杆右移：d增大→θ增大→cosθ减小→T增大（绳子需\"翘起\"保持绳长不变）","link":""},{"id":"phy0210","t":"晾衣杆模型·穹形门窗变式","s":"看到【绳经滑轮/光滑悬挂点沿曲面或斜线移动、绳长固定】","c":"想到【本质仍是晾衣杆模型：追踪d的变化趋势即得T的变化趋势，可分段分析】；警惕【分段区间划分错误导致趋势判断错误】","src":"物一轮032.晾衣杆模型_笔记","note":"视频|11:09-14:34","orig":"（例）绳长固定经滑轮悬挂重物沿弧线从B移到C：水平间距d先增大后不变→θ先增大后不变→T先变大后不变，答案C","link":""},{"id":"phy0211","t":"晾衣杆模型·双滑轮系统对比","s":"看到【系统中出现第二个滑轮/活结】","c":"想到【活结使绳上拉力处处相等且恒定，角度由重力平衡直接确定（2Tsin$\\alpha$=mBg），移动只改变绳长分配与物体高度，$\\theta$不变】；警惕【直接套用晾衣杆\"d增T增\"的结论而忽略活结使T恒定的特性】","src":"物一轮032.晾衣杆模型_笔记","note":"视频|14:34","orig":"（例）双滑轮系统存在第二个滑轮（活结）：绳拉力T=mAg恒定，θ与α互余且2Tsinα=mBg，T不变→α不变→θ不变，绳长重新分配使A升高，答案C","link":""},{"id":"phy0212","t":"晾衣杆模型·核心判别方法","s":"看到【悬挂绳动态平衡题归类辨析】","c":"想到【第一步检查有无活结：无活结按晾衣杆（T随d变），有活结按双滑轮（T恒定、$\\theta$由平衡定）】；警惕【反向延长绳构造等腰三角形、活结两端拉力必相等是两大分析技巧】","src":"物一轮032.晾衣杆模型_笔记","note":"视频|14:34","orig":"（知识）晾衣杆模型（单滑轮/光滑挂钩）：T可变，由d变化判断；双滑轮模型（有活结）：T恒定，角度由重力平衡确定；核心是检查系统中是否存在使绳拉力保持不变的活结结构","link":""},{"id":"phy0213","t":"运动的描述·章节考情","s":"看到【匀变速直线运动章节的考情分析】","c":"想到【概念题按选择题规范训练（辨析式选项），图像题既练读图选择也练在解答题中用图像给条件/辅助分析】；警惕【只刷计算而忽视概念辨析和图像信息的提取】","src":"物一轮033.【课前必看】本讲听课建议_笔记","note":"视频|00:46-06:27","orig":"（知识）运动学概念主要以选择题考查（浙江卷、福建卷高频）；运动学图像考查形式包括选择题、解答题给条件、辅助分析方法，2024年河北、辽宁、广东等多省均有涉及","link":""},{"id":"phy0214","t":"运动的描述·预备知识","s":"看到【一轮复习运动学部分的分层学习路径】","c":"想到【按自身基础选择切入点：概念不清先补位移/路程、时刻/时间间隔等基本概念；有基础直接练图像读图；扎实基础练陌生图像的函数分析】；警惕【基础概念不过关就强行刷难题】","src":"物一轮033.【课前必看】本讲听课建议_笔记","note":"视频|00:46-06:27","orig":"（知识）零基础必学预备知识：质点概念、参考系、时刻与时间间隔；零基础从“区分位移和路程”开始，有基础从“读x-t图像并还原运动过程”开始，基础扎实从“利用函数知识分析陌生图像”开始","link":""},{"id":"phy0215","t":"运动的描述·章节学习方法","s":"看到【运动学图像被标为本章核心考点】","c":"想到【图像复习的主线是“读图—还原运动过程—辅助解题”，并注意区分不同图像（x-t、v-t、a-t）的物理意义】；警惕【把图像形状直接当成运动轨迹】","src":"物一轮033.【课前必看】本讲听课建议_笔记","note":"视频|06:27","orig":"（知识）本章两节课：第一节运动的描述和图像，第二节匀变速直线运动的规律和应用；运动学图像是重要考点，需掌握读图和图像分析方法","link":""},{"id":"phy0216","t":"运动的描述·位移的定义","s":"看到【判断位移大小或方向的题目】","c":"想到【位移只看初末位置的有向线段，与路径无关；绕闭合一圈位移为零】；警惕【用轨迹长度代替位移，或忘记交代方向】","src":"物一轮034.区分位移和路程_笔记","note":"视频|00:22-06:46","orig":"（知识）位移是从初位置指向末位置的有向线段，用l表示；大小和方向仅由初末位置决定，与运动轨迹无关。例：北京→太原位移350km指向太原；绕操场跑步初末位置重合时位移为0","link":""},{"id":"phy0217","t":"运动的描述·直线运动的位移","s":"看到【直线运动中用正负号表示位移/位置】","c":"想到【先建立坐标系定正方向，再用“末位置减初位置”求$\\Delta$x，正负号即代表方向】；警惕【位置坐标与位移混为一谈——位移是变化量，坐标是状态量】","src":"物一轮034.区分位移和路程_笔记","note":"视频|06:46-11:28","orig":"（知识）直线运动位移代数表示Δx = x₂ - x₁（末减初）；正号表示与坐标系正方向相同，负号表示相反。例：Δx₁=7m-4m=3m（向右），Δx₂=-3m-2m=-5m（向左）","link":""},{"id":"phy0218","t":"运动的描述·位移与路程的区别","s":"看到【比较位移与路程，或判断“位移就是路程”类说法】","c":"想到【矢量与标量本质不同，即使大小相等也不能说“就是”；比较矢量必须同时考虑大小和方向】；警惕【“单向直线运动的位移就是路程”是错误说法——只是大小可能相等】","src":"物一轮034.区分位移和路程_笔记","note":"视频|11:28","orig":"（知识）位移是矢量（有方向），路程是标量（无方向）；大小关系：路程≥位移大小，仅单向直线运动取等号；位移遵循矢量运算法则，路程用代数加减","link":""},{"id":"phy0219","t":"运动的描述·速度的定义","s":"看到【求速度或判断速度方向的题目】","c":"想到【用v=$\\Delta$x/$\\Delta$t计算，速度方向与位移变化量方向一致】；警惕【速度是矢量，“速度不变”需大小和方向均不变，匀速直线运动是唯一速度不变的运动】","src":"物一轮035.理解速度的概念_笔记","note":"视频|00:31-03:15","orig":"（知识）速度是单位时间内物体的位移，v=Δx/Δt，是矢量，方向与Δx方向相同，描述位置变化的快慢","link":""},{"id":"phy0220","t":"运动的描述·平均速度","s":"看到【给一段过程的总位移和总时间求速度】","c":"想到【这是平均速度的定义式，用总位移除以总时间】；警惕【平均速度不反映任意时刻的瞬时快慢，不能由平均速度推断某时刻速度】","src":"物一轮035.理解速度的概念_笔记","note":"视频|03:22-04:55","orig":"（知识）平均速度=总位移/总时间（v_avg=Δx/Δt），只能粗略描述一段运动的快慢，无法反映运动细节；高中阶段凡可计算时间间隔得到的速度都是平均速度","link":""},{"id":"phy0221","t":"运动的描述·瞬时速度","s":"看到【问某一时刻的速度，或“瞬时速度如何理解”】","c":"想到【瞬时速度=$\\Delta$t$\\to$0时平均速度的极限值，此时平均速度与瞬时速度严格相等】；警惕【把一段时间内的平均速度当成某一时刻的瞬时速度】","src":"物一轮035.理解速度的概念_笔记","note":"视频|04:55-07:55","orig":"（知识）瞬时速度是Δt→0时平均速度的极限（v=lim Δx/Δt），描述某时刻的快慢；高中阶段主要通过极限概念理解，不做具体计算","link":""},{"id":"phy0222","t":"运动的描述·速率与速度的关系","s":"看到【辨析速率与速度大小关系的选项】","c":"想到【瞬时速率恒等于瞬时速度大小；但平均速率（路程/时间）通常大于平均速度大小，单向直线运动才相等】；警惕【混淆“平均速率”与“平均速度的大小”——两者不是一回事】","src":"物一轮035.理解速度的概念_笔记","note":"视频|07:55-12:34","orig":"（知识）速率=路程/时间，是标量；瞬时速率=瞬时速度大小（Δt→0时路程=位移大小）；平均速率≥平均速度大小，仅单向直线运动时相等","link":""},{"id":"phy0223","t":"运动的描述·速度概念辨析选择题","s":"看到【“位移大速度就大”“速度大位移就大”类判断】","c":"想到【比较速度必须控制时间变量（v=$\\Delta$x/$\\Delta$t是比值定义），位移大小与速度大小无直接对应】；警惕【脱离$\\Delta$t谈$\\Delta$x大小、把速度当标量处理】","src":"物一轮035.理解速度的概念_笔记","note":"视频|12:34-15:49","orig":"（例）概念辨析：A速度不变需大小方向均不变（对）；B混淆矢量标量（错）；C未控制时间变量比较位移（错）；D平均速度不反映瞬时值（错）。答案A","link":""},{"id":"phy0224","t":"运动的描述·平均速度计算","s":"看到【题目中时间以分钟、位移以km等混合单位给出求平均速度】","c":"想到【先统一单位再代入v=$\\Delta$x/$\\Delta$t（分钟$\\to$小时$\\div$60）】；警惕【直接用分钟代入计算导致数值错误】","src":"物一轮035.理解速度的概念_笔记","note":"视频|15:49","orig":"（例）位移20km、时间40分钟，v=20÷(2/3)=30km/h，答案B；易错点为分钟→小时的单位换算","link":""},{"id":"phy0225","t":"运动的描述·速度变化量的矢量运算法","s":"看到【求速度变化量$\\Delta$v，且初末速度方向不同（反弹、圆周运动转弯）】","c":"想到【$\\Delta$v是矢量：画初末速度箭头$\\to$尾端重合$\\to$从v_{0}箭头指向v箭头即为$\\Delta$v；两速度等大反向时$\\Delta$v大小为两者之和】；警惕【直接代数相减得5-5=0，忽略方向】","src":"物一轮036.理解加速度的概念_笔记","note":"视频|01:22-08:56","orig":"（例）弹性小球撞墙：v₀=5m/s向左，v=5m/s向右，矢量作图得Δv=10m/s向右；匀速圆周运动3m/s转过60°，矢量三角形构成等边三角形，Δv=3m/s","link":""},{"id":"phy0226","t":"运动的描述·速度变化量的代数运算法","s":"看到【直线运动中求$\\Delta$v】","c":"想到【三步：规定正方向$\\to$用正负号表示速度方向$\\to$代入$\\Delta$v=v-v_{0}计算，结果正负即方向】；警惕【忘记先规定正方向，或速度代入时丢掉负号】","src":"物一轮036.理解加速度的概念_笔记","note":"视频|08:56-12:23","orig":"（例）撞墙问题设向左为正：v₀=+5m/s，v=-5m/s，Δv=v-v₀=-5-(+5)=-10m/s，负号表示方向与正方向相反（向右），与矢量法结果一致","link":""},{"id":"phy0227","t":"运动的描述·加速度的定义与物理意义","s":"看到【加速度方向、正负含义或“变化快/变化多”的辨析】","c":"想到【a的方向永远与$\\Delta$v一致；a大=速度变化快，不等于$\\Delta$v大】；警惕【把“a大”等同于“速度变化量大”或“a方向=速度方向”；单位书写m/s^{2}不能漏】","src":"物一轮036.理解加速度的概念_笔记","note":"视频|12:23-15:07","orig":"（知识）a=Δv/Δt，单位m/s²，描述速度变化的快慢；“变化多”指Δv大，“变化快”指Δv/Δt大；a是矢量，方向与Δv相同，与瞬时速度v方向无必然联系","link":""},{"id":"phy0228","t":"运动的描述·加速度计算","s":"看到【给初末速度（可能反向）和作用时间求加速度】","c":"想到【先定正方向，代数求$\\Delta$v，再除以$\\Delta$t；答案需同时交代大小和方向】；警惕【方向相反的速度未带符号代入，或只给数值不说明方向】","src":"物一轮036.理解加速度的概念_笔记","note":"视频|15:07-17:27","orig":"（例）碰撞问题：向左为正，v₀=+5m/s，v=-5m/s，用时0.1s，Δv=-10m/s，a=-10/0.1=-100m/s²（大小100m/s²，方向向右）","link":""},{"id":"phy0229","t":"运动的描述·加减速判定黄金法则","s":"看到【判断物体加速还是减速，或“a为负一定是减速”类选项】","c":"想到【加减速只看v与a的方向关系：同向加速、反向减速，与a的正负无关】；警惕【用a的正负直接判断加减速——正方向是人为选定的】","src":"物一轮036.理解加速度的概念_笔记","note":"视频|17:32-23:55","orig":"（知识）v与a同向→加速，v与a反向→减速；加速度正负仅表示与设定正方向的关系，不能单独由a的正负判断加减速。四种状态：向右加速(v右,a右)、向右减速(v右,a左)、向左加速(v左,a左)、向左减速(v左,a右)","link":""},{"id":"phy0230","t":"运动的描述·a与v的辨析","s":"看到【“速度大则加速度大”“速度为零则加速度为零”类判断】","c":"想到【a与v大小、方向均无必然联系，判断要依据定义而非直觉】；警惕【用生活经验（速度快≈加速快）替代物理定义】","src":"物一轮036.理解加速度的概念_笔记","note":"视频|24:24-27:30","orig":"（知识）a与v无直接对应关系：v=0时a可非零（自由落体初始时刻a=g）；v≠0时a可为零（匀速直线运动）；速度与加速度方向可同向、反向、垂直等各种组合","link":""},{"id":"phy0231","t":"运动的描述·a与Δv的辨析","s":"看到【“$\\Delta$v大则a大”类选项】","c":"想到【必须看单位时间内的变化量：$\\Delta$v/$\\Delta$t大才是a大，仅“单位时间$\\Delta$v大$\\to$a大”正确】；警惕【混淆$\\Delta$v与$\\Delta$v/$\\Delta$t，忽略时间因素】","src":"物一轮036.理解加速度的概念_笔记","note":"视频|27:30-29:29","orig":"（知识）a=Δv/Δt，方向与Δv一致；控制Δt相同时a与Δv成正比，未控制Δt时Δv大但a可小（如高铁Δv=80m/s用200s vs 青蛙Δv=8m/s用0.2s）","link":""},{"id":"phy0232","t":"运动的描述·加速度概念综合判断","s":"看到【加速度概念的多选项综合判断题】","c":"想到【逐项用定义检验：a对应“变化快慢”，方向由$\\Delta$v决定，加减速由a与v方向关系决定】；警惕【“变化越来越快”与“变化越来越快地加速”混淆——前者指a增大，后者v与a同向即可】","src":"物一轮036.理解加速度的概念_笔记","note":"视频|29:29-37:43","orig":"（例）辨析题要点：速度大≠加速度大（匀速反例）；Δv大≠a大（需考虑Δt）；a为负不一定减速；速率不变可能有加速度（匀速圆周运动）；“变化越来越快”必然对应a增大；加速运动中a减小仍可加速（a与v同向）","link":""},{"id":"phy0233","t":"运动的描述·图像方法的三类应用","s":"看到【题目要求分析物理图像或用图像处理实验数据】","c":"想到【先分清考查类型：实验题中图像用于探究规律/求参量，选择题中用于读信息还原运动，解题时画图可辅助分析】；警惕【混淆三类用途对应的解题策略】","src":"物一轮037.读x-t图像并还原运动过程_笔记","note":"视频|00:51-02:39","orig":"（知识）图像方法三类用途：①实验规律探究（如a-1/m图像、单摆测g由斜率求值，实验题考查）；②图像信息读取与过程还原（选择题为主）；③绘制图像辅助分析（如动力学问题借助v-t图）","link":""},{"id":"phy0234","t":"运动的描述·x-t图像读图通法","s":"看到【给x-t图像还原运动过程或判断速度/位移】","c":"想到【按“截距$\\to$斜率$\\to$交点”三步读图：截距定初始位置，斜率定速度，交点定相遇】；警惕【把曲线形状当成运动轨迹——x-t图像只描述直线运动，曲线$\\neq$曲线运动】","src":"物一轮037.读x-t图像并还原运动过程_笔记","note":"视频|02:39-21:32","orig":"（知识）x-t图像：纵轴截距=初始位置，横轴截距=回到原点时刻，两线交点=同一时刻同一位置（相遇）；直线段=匀速运动，曲线段=变速运动；切线斜率绝对值=速度大小，正负=速度方向；割线斜率=平均速度","link":""},{"id":"phy0235","t":"运动的描述·x-t图像过程还原例题","s":"看到【x-t图像分段（直线+曲线混合）还原运动并算平均速度】","c":"想到【直线段斜率求速度，整段平均速度用首尾连线斜率（总位移/总时间），位移看纵坐标变化而非路程】；警惕【把匀速段误判为加速段；位移大小忘记取绝对值】","src":"物一轮037.读x-t图像并还原运动过程_笔记","note":"视频|21:32-26:56","orig":"（例）医用机器人：0-10s匀速正向（v=0.5m/s），10-20s匀速反向回原点，20-30s曲线减速至零；0-20s平均速度v=0/20=0；0-30s总位移Δx=-2m，大小2m","link":""},{"id":"phy0236","t":"运动的描述·双物体x-t图像比较","s":"看到【x-t图像中两物体同时同地（或不同地）出发比较运动】","c":"想到【速度相等看平行切线，相遇看图线交点，位移看纵坐标差】；警惕【把两图线交点误当成速度相等——交点是位置相同，速度相等要看斜率】","src":"物一轮037.读x-t图像并还原运动过程_笔记","note":"视频|26:56-33:06","orig":"（例）甲先正向减速至零再反向加速，乙匀速：判断速度相等时刻找平行切线；甲速度在t1-t2确实增大；甲有往返（方向改变）。另一题两车t1、t2位置相同即相遇，t2时刻切线斜率不同则速度不等","link":""},{"id":"phy0237","t":"运动的描述·x-t图像易错点","s":"看到【问x-t图像中某段的加速度或由曲线判断加速】","c":"想到【x-t图斜率是速度，先由斜率变化得速度变化，再推加速度；图像弯曲只说明速度在变】；警惕【把x-t曲线的弯曲直接说成“加速”或从图上直接读加速度】","src":"物一轮037.读x-t图像并还原运动过程_笔记","note":"视频|33:06","orig":"（知识）x-t图像的曲线不能直接等同于加速运动；加速度不能从x-t图直接读取，需通过速度变化间接判断","link":""},{"id":"phy0238","t":"运动的描述·v-t图像坐标意义","s":"看到【v-t图像判断运动方向】","c":"想到【方向只看v的正负：图线在t轴上方始终正向运动，跨轴则往返】；警惕【“速度减小”$\\neq$反向运动——反向与否看正负，不看增大减小】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|00:18-02:46","orig":"（知识）v-t图像横轴为时间t（标量，s），纵轴为速度v（矢量，m/s）；v>0表示与正方向同向，v<0表示反向；v-t图像只能描述直线运动","link":""},{"id":"phy0239","t":"运动的描述·v-t图像运动类型判断","s":"看到【v-t图像问“是否往返/何时改变方向”】","c":"想到【加速减速看|v|增减，往返看图线是否穿过t轴】；警惕【把“速度减小”当成“向负方向运动”】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|02:46-04:53","orig":"（知识）速度大小看绝对值变化，方向看正负；全正图像始终同向运动（可先加速后减速）；跨轴图像为往返运动；全负图像始终反向运动","link":""},{"id":"phy0240","t":"运动的描述·v-t图像斜率=加速度","s":"看到【由v-t图像比较加速度大小或判断加减速】","c":"想到【斜率=加速度：比较陡峭程度定大小，斜率正负定a方向，再按“v、a同向加速、反向减速”判断加减速】；警惕【斜率正负直接当速度方向——斜率是与正方向比，加减速要v、a联合判断】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|06:07-13:51","orig":"（知识）直线斜率=瞬时加速度；曲线割线斜率=平均加速度，切线斜率=瞬时加速度；|a|=|k|，图线越陡a越大；k的正负表示a的方向（与正方向比），与速度方向无直接关系。（例）v>0且a>0正向加速；v>0但a<0正向减速；v<0且a<0负向加速；v<0但a>0负向减速","link":""},{"id":"phy0241","t":"运动的描述·v-t图线下面积=位移","s":"看到【由v-t图像求位移或判断最终位置】","c":"想到【“面积”法求位移：上方减下方，代数和为总位移】；警惕【把上下方面积直接相加——下方面积是负位移】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|13:51-19:23","orig":"（知识）图线与t轴围成面积表示位移大小（微元思想）；t轴上方为正位移、下方为负位移，总位移=各段代数和。（例）全正图像x=+S单向运动；全负图像x=-S；跨轴图像x=S₁-S₂往返运动","link":""},{"id":"phy0242","t":"运动的描述·v-t图像分段还原","s":"看到【给一段连续v-t图像要求完整还原运动过程】","c":"想到【按“初速度方向$\\to$转折点（穿轴）$\\to$各段斜率$\\to$面积累积位置”四步分段还原】；警惕【加速度方向改变$\\neq$运动方向改变，速度方向改变只看穿轴点】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|23:12-26:26","orig":"（例）t=0速度为负（初始向左运动），0.4s后转正；0-2.0s斜率恒为正但1.2-2.0s斜率绝对值减小；分段：0-0.4s向左减速，0.4-1.2s向右加速，1.2-2.0s向右减速；负向面积小于正向面积，最终在出发点正方向","link":""},{"id":"phy0243","t":"运动的描述·v-t图像面积计算例题","s":"看到【v-t图像中用三角形/梯形面积求位移、比较加速度】","c":"想到【匀变速段位移用面积公式（如½$\\times$t$\\times$v_max），加速度比较看斜率绝对值】；警惕【把6s末速度方向改变误当成加速度方向改变——斜率在4s末已变号】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|26:26-29:32","orig":"（例）0-4s向右匀加速，4-6s向右匀减速，6-8s向左匀加速；|a₁|=1m/s²（0-4s）与|a₂|=2m/s²（6-8s）比较斜率；前6秒位移=½×6×4=12m（三角形面积）；6s末速度由正转负改变方向","link":""},{"id":"phy0244","t":"运动的描述·面积差比较位移","s":"看到【两物体v-t图线间夹“阴影面积”，比较位移或位置先后】","c":"想到【面积差=位移差：判断谁在前看面积累积；加速度相等找平行切线】；警惕【把t1时刻（共速）当成位置相同——共速时位移差最大/前方领先，未必相遇】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|29:32-36:35","orig":"（例）甲0-t1加速度减小的加速、t1-t2匀速；乙0-t1加速度先增后减、t1-t2继续加速；阴影Ⅰ面积>阴影Ⅱ面积说明甲总位移大，t2时刻乙未达50m处；可能存在平行切线（加速度相等）时刻","link":""},{"id":"phy0245","t":"运动的描述·对称性多次相遇问题","s":"看到【v-t图像有对称结构且给出某次相遇时刻，问其他时刻位置关系】","c":"想到【利用面积对称性找另一次并排时刻，用位移差反推初始位置；速度反超时刻（共速）是位置关系极值点】；警惕【以为共速就相遇——共速时两物体位置差最大或最小】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|36:35-41:54","orig":"（例）t=1s与t=3s关于t=2s对称、位移面积相等：t=3s并排则t=1s必然并排；t=0时甲在乙前方（由位移差反推）；1-3s位移差=(10+30)×2/2=40m；t=2s时甲在乙后方（速度刚反超）","link":""},{"id":"phy0246","t":"运动的描述·x-t与v-t图像对比总结","s":"看到【同一题同时涉及x-t与v-t图像的辨析】","c":"想到【抓两类图像的对应关系：x-t斜率↔v-t纵坐标（都是速度），v-t斜率=加速度；方向判断依据不同】；警惕【在v-t图上用“斜率正负”判断运动方向，或把速度为零的点都当成折返点】","src":"物一轮038.读v-t图像并还原运动过程_笔记","note":"视频|41:54","orig":"（知识）x-t：纵截距=初始位置，斜率=速度，方向由斜率正负定；v-t：纵截距=初速度，横截距=速度为零时刻，斜率=加速度，面积=位移，方向由v正负定；v-t穿轴点是方向变化临界点（仅接触不算）","link":""},{"id":"phy0247","t":"运动的描述·已知函数类型分析图像","s":"看到【给出非常规图像（如x/t-t、v^{2}-x）且已知函数类型求加速度/初速度】","c":"想到【从运动学公式出发自主推导纵坐标关于横坐标的表达式，再对照“kx+b”形式读出斜率、截距对应的物理量】；警惕【死记斜率截距结论而不推导——不同坐标组合下k、b意义完全不同】","src":"物一轮039.利用函数知识分析陌生图像_笔记","note":"视频|01:17-05:02","orig":"（知识）题目明确告知函数类型（一次、二次、幂函数等）时：①确认运动类型（通常匀变速直线运动）②结合运动学公式推导关系式③解析斜率、截距的物理意义。示例：x/t-t图像由x=v₀t+½at²推得x/t=v₀+½at，斜率k=½a，截距b=v₀；v²-x图像由v²-v₀²=2ax得v²=2ax+v₀²，斜率k=2a","link":""},{"id":"phy0248","t":"运动的描述·一次函数图像辨析例题","s":"看到【多选项各给一个图像/公式组合，要求选出推导正确的】","c":"想到【逐项独立推导函数式再核对斜率、截距和系数（如v^{2}-x中k=2a，a=k/2不能直接取k）】；警惕【跳过推导直接“看斜率猜参量”，特别是系数带2、½的场合】","src":"物一轮039.利用函数知识分析陌生图像_笔记","note":"视频|05:02-11:37","orig":"（例）由图像信息推得函数式v=-(y₀/x₀)t+y₀：A错在vt图像斜率应为负（a=-y₀/x₀）；C错在v²-x图像斜率是2a却直接取斜率值；D正确推得a=-2y₀/x₀。答案D","link":""},{"id":"phy0249","t":"运动的描述·判断图像大致形态","s":"看到【陌生的v-x（或其他组合）图像题，问大致形态】","c":"想到【先建坐标系定正方向$\\to$分段列物理量间的函数关系$\\to$按函数式匹配图像特征（正负值、线性/非线性、对称性）】；警惕【横轴物理量是“位置/距离”还是“位移”没分清，导致函数式写错】","src":"物一轮039.利用函数知识分析陌生图像_笔记","note":"视频|11:37","orig":"（例）小球自由落体+竖直上抛周期运动（加速度恒为g），落地点为原点、向上为正：下落v=-√(2g(h-x))，上升v=+√(2g(h-x))；图像须含正负速度（排除C、D）、非线性（排除B），呈抛物线特征选A；易错点：x是相对地面的距离而非位移","link":""},{"id":"phy0250","t":"运动的描述·切线斜率的物理意义","s":"看到【问某图像切线斜率代表什么物理量】","c":"想到【查该物理量定义是否为“变化量之比”形式：是则切线斜率即该量，否则斜率无此意义】；警惕【把UI图像的切线斜率当电阻——R是U/I（坐标比）而非$\\Delta$U/$\\Delta$I】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|00:16-06:02","orig":"（知识）切线斜率=Δy/Δx的极限；某物理量定义形式为Δy/Δx时，图像切线斜率即该物理量：v-t斜率=a=Δv/Δt，x-t斜率=v=Δx/Δt；非匀变速时微元下Δ(v²)/Δx=2a仍成立；φ-t斜率对应e=Δφ/Δt；易错：UI图像切线斜率ΔU/ΔI不代表电阻（电阻定义为R=U/I）","link":""},{"id":"phy0251","t":"运动的描述·与原点连线斜率的物理意义","s":"看到【图像问“某点与原点连线的斜率”或物理量定义为两坐标之比】","c":"想到【定义是“坐标比”（如R=U/I）用连线斜率；定义是“变化量比”（如a=$\\Delta$v/$\\Delta$t）用切线斜率】；警惕【两种斜率混用——比值定义与变化率定义对应不同几何量】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|06:02-07:22","orig":"（知识）点与原点连线斜率=纵坐标/横坐标（y/x）；物理量定义形式为y/x时，连线斜率即该物理量，如UI图像中连线斜率表示电阻R=U/I","link":""},{"id":"phy0252","t":"运动的描述·线下面积的判定通法","s":"看到【判断任意图像线下面积的物理意义】","c":"想到【把“纵坐标$\\times$横坐标变化量”的量纲/物理含义写出来，乘积有意义则面积有意义】；警惕【用“纵坐标$\\times$横坐标”（y·x）代替y·$\\Delta$x——两者本质不同】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|07:28-09:42","orig":"（知识）曲线下面积视为无数微元矩形之和，面积意义=纵坐标×横坐标变化量（y·Δx，注意是Δx而非x）；微元Δx→0时视纵坐标不变","link":""},{"id":"phy0253","t":"运动的描述·a-t图像面积","s":"看到【a-t图像求“面积代表什么”】","c":"想到【a-t线下面积=速度变化量$\\Delta$v，不是速度v】；警惕【把面积直接当成速度——还需知道初速度才能得末速度】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|09:42-10:25","orig":"（例）a-t图像面积单元a·Δt对应Δv，累积面积表示总速度变化量（非速度本身）","link":""},{"id":"phy0254","t":"运动的描述·1/v-x图像面积","s":"看到【纵坐标为某物理量倒数（如1/v）的图像求面积意义】","c":"想到【同样用“纵坐标$\\times$$\\Delta$横坐标”判定：$\\Delta$x/v即时间微元，累积面积=总时间】；警惕【面积单位要用“纵单位$\\times$横单位”验证（如s/m $\\times$ m = s）】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|10:25-11:38","orig":"（例）(1/v)-x图像面积单元(1/v)·Δx=Δx/v，微元下视为匀速运动，故面积表示时间Δt（理论依据∫dx/v=t）","link":""},{"id":"phy0255","t":"电学·UI图像面积的辨析","s":"看到【问UI（或类似）图像线下面积是否等于功率】","c":"想到【功率对应“纵$\\times$横”的矩形面积，不是“纵$\\times$$\\Delta$横”的曲线下面积；先判定y·$\\Delta$x有无物理意义再下结论】；警惕【见到“面积”就当成两坐标乘积——线下面积永远是y·$\\Delta$x】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|11:38-12:36","orig":"（例）UI图像线下面积U·ΔI无明确物理意义；功率P=U·I需用矩形面积（纵坐标×横坐标）而非曲线下面积","link":""},{"id":"phy0256","t":"运动的描述·非常规图像求参综合题","s":"看到【一题给四个非常规图像（x-t^{2}、v^{2}-x、x/t-t、a-t）分别求参】","c":"想到【通法：先由匀变速公式变形出“纵坐标=f(横坐标)”的一次函数式，再按斜率/截距/面积物理意义求参】；警惕【x/t-t截距是v_{0}、斜率是½a；v^{2}-x斜率是2a——系数必须从推导中来】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|12:36-19:36","orig":"（例）甲图x-t²：由x=½at²得a=2m/s²；乙图v²-x：斜率k=2a=10得a=5m/s²；丙图x/t-t：截距v₀=4m/s、斜率½a=-2；丁图a-t：面积=速度变化量，前2s为3m/s。答案B","link":""},{"id":"phy0257","t":"运动的描述·a-t图还原运动","s":"看到【给a-t图像（尤其对称/正弦形）判断速度与位置】","c":"想到【用面积累加$\\Delta$v把a-t图转成v-t图分析：上方面积增速、下方面积减物速；对称面积$\\to$对称时刻速度相同】；警惕【混淆“速度最小点（$\\Delta$v=0）”与“位移最远点”——最远要看v是否穿轴反向】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|19:36-24:32","orig":"（例）a-t图（正弦式）转化为v-t理解：0-t₀面积在上方正向加速，t₀-2t₀面积在下方正向减速，2t₀时刻速度减至0；始终单向运动不回原点；3t₀/2与t₀/2速度相同（面积对称）","link":""},{"id":"phy0258","t":"运动的描述·图像分析通用流程总结","s":"看到【任何陌生物理图像的分析题】","c":"想到【按“切线斜率查$\\Delta$比、连线斜率查坐标比、面积查y·$\\Delta$x”三类模板对号入座，最后用单位量纲检验】；警惕【不推导函数式直接凭图像形状下结论；忽略特殊图像（x-t^{2}、x/t-t）需单独推导】","src":"物一轮040.确定斜率与线下面积意义的通用方法_笔记","note":"视频|26:19","orig":"（知识）函数法四步：明确运动类型→回忆物理规律（如v=v₀+at）→推导函数关系式→由斜率/截距定参量。三类关键参数：切线斜率=Δy/Δx，原点连线斜率=y/x，线下面积=y·Δx；面积正负由纵坐标符号决定；可用物理量单位验证计算正确性","link":""},{"id":"phy0259","t":"匀变速直线运动·规律总览","s":"看到【求匀变速运动中位移、速度、时间、加速度的定量关系】","c":"想到【用匀变速直线运动规律建立方程求解；多物体相互作用需分别分析再联立】","src":"物一轮041.【课前必看】本讲听课建议_笔记","note":"视频|00:09-00:54","orig":"（知识）匀变速直线运动规律讨论位移、速度、时间、加速度等物理量之间的定量关系，应用于单物体运动和多物体相互作用问题","link":""},{"id":"phy0260","t":"匀变速直线运动·知识体系分层","s":"看到【匀变速问题按难度分层（基本公式/推论/多过程综合）】","c":"想到【先掌握四个基本公式与选公式技巧，再学中时速、逐差、比例推论，最后攻克多过程与追及综合】；警惕【比例推论仅适用于初速为零的情形】","src":"物一轮041.【课前必看】本讲听课建议_笔记","note":"视频|00:54-03:44","orig":"（知识）基础：记忆并使用四个基本公式、选择合适公式；进阶：两个重要推论、零初速比例推论、自由落体与竖直上抛；高阶：多过程运动、单向追及、复杂往返问题","link":""},{"id":"phy0261","t":"多物体/多过程问题","s":"看到【多过程运动（如匀变速+匀速组合）】","c":"想到【抓住各段衔接点的速度、位移、时间关系联立方程】","src":"物一轮041.【课前必看】本讲听课建议_笔记","note":"视频|03:44","orig":"（知识）分析多个物体或运动阶段（如匀变速+匀速组合）的交互问题，考试重点为过程衔接点的速度/位移关系","link":""},{"id":"phy0262","t":"匀变速直线运动·定义与分类","s":"看到【先减速到零再反向加速的运动（如斜面小球）】","c":"想到【速度方向改变但a恒定，仍属匀变速直线运动，可直接用基本公式全程求解】；警惕【误以为速度反向后就不再是匀变速】","src":"物一轮042.记忆并使用四个基本公式_笔记","note":"视频|01:00-05:33","orig":"（知识）匀变速直线运动：a大小方向均不变且轨迹为直线；分为匀加速（a与v₀同向）、匀减速（a与v₀反向）、往返匀变速（先减速至零再反向加速，全程a恒定）","link":""},{"id":"phy0263","t":"匀变速直线运动·四个基本公式","s":"看到【匀变速运动已知部分物理量求其余量】","c":"想到【从四个基本公式中选含已知量与待求量的那一个】；警惕【公式均为矢量式，需规定正方向】","src":"物一轮042.记忆并使用四个基本公式_笔记","note":"视频|05:33-07:25","orig":"（知识）速度时间关系v=v₀+at；位移时间关系x=v₀t+½at²；速度位移关系v²−v₀²=2ax；平均速度公式v̄=x/t=(v₀+v)/2，围绕v₀、v、t、x、a五个量建立","link":""},{"id":"phy0264","t":"运动学公式·矢量代入规范","s":"看到【匀减速问题代入运动学公式计算】","c":"想到【三步规范：设正方向、标矢量正负、带符号代入，保持原始公式形式】；警惕【a与v_{0}反向时a漏取负号、擅改公式结构导致符号混乱】","src":"物一轮042.记忆并使用四个基本公式_笔记","note":"视频|05:33-07:25","orig":"（知识）代入步骤：设正方向→确定各矢量正负（v₀、v、x、a）→带符号代入；建议保持公式原始形式，代入时处理符号","link":""},{"id":"phy0265","t":"匀变速直线运动·刹车应用","s":"看到【刹车类匀减速问题求初速度、位移或平均速度】","c":"想到【设初速度方向为正，a取负值代入公式，平均速度用(v_{0}+v)/2】；警惕【数字计算后统一标注单位】","src":"物一轮042.记忆并使用四个基本公式_笔记","note":"视频|07:25-17:54","orig":"（例）汽车刹车a=−2m/s²：代入v=v₀+at得v₀=10m/s；x=v₀t+½at²=16m；v̄=(v₀+v)/2=5m/s","link":""},{"id":"phy0266","t":"匀变速直线运动·往返多解","s":"看到【往返匀变速对全程列式解出时间双解】","c":"想到【多解对应运动不同阶段（单向与往返），两者均为实际过程的解，需结合物理意义判断不必急着舍解】；警惕【位移是位置矢量变化量，与运动路径无关】","src":"物一轮042.记忆并使用四个基本公式_笔记","note":"视频|17:54","orig":"（例）斜面小球用v²−v₀²=2ax得最高点x=25m；对16m处由t²−10t+16=0解得t₁=2s（上升阶段）、t₂=8s（往返全程）","link":""},{"id":"phy0267","t":"运动学公式·选择原则","s":"看到【不知该选哪个运动学公式】","c":"想到【数一数已知量与待求量，选恰好包含它们的公式（知三求一）】；警惕【平均速度公式使用频率低但特定场景高效】","src":"物一轮043.选择合适的公式_笔记","note":"视频|00:25-04:14","orig":"（知识）四个基本公式各含四个物理量，每个公式是一个方程，需知道其中三个量才能求解第四个量；按已知量与待求量匹配公式","link":""},{"id":"phy0268","t":"运动学公式·匹配示例","s":"看到【已知量组合中缺某个量（如缺a或缺t）】","c":"想到【避开缺失量选公式：缺a优先用v̄=(v_{0}+v)/2，缺t优先用v^{2}−v_{0}^{2}=2ax】","src":"物一轮043.选择合适的公式_笔记","note":"视频|04:14-06:42","orig":"（例）已知v₀、a、t求x→选位移时间公式；已知v₀、t、x求v→选平均速度公式；已知v₀、a、x求v→选速度位移公式","link":""},{"id":"phy0269","t":"刹车滑行·逆向思维","s":"看到【匀减速到停止（v=0）求滑行位移或某段时间内的位移】","c":"想到【逆向思维：把末速度为零的匀减速看成反向的初速度为零的匀加速，一步求解更简洁】；警惕【分段法计算时易漏全程时间关系】","src":"物一轮043.选择合适的公式_笔记","note":"视频|06:50-17:09","orig":"（例）汽车刹车，已知末速度为0、时间t、加速度a求位移：正向需分段联立，逆向视为初速为零的匀加速直接x=½at²求解","link":""},{"id":"phy0270","t":"运动学解题·基本步骤","s":"看到【列运动学方程代入数据】","c":"想到【先设正方向再带符号代入各矢量】；警惕【刹车问题中加速度符号易错】","src":"物一轮043.选择合适的公式_笔记","note":"视频|17:09-17:32","orig":"（知识）步骤：规定正方向（通常取初速度方向）→用正负号表示各矢量方向（v₀、v、x、a）→带正负号代入公式计算","link":""},{"id":"phy0271","t":"运动学公式·适用范围","s":"看到【往返运动（如竖直上抛）求总位移或总时间】","c":"想到【统一正方向后对全过程直接列式，无需分段】","src":"物一轮043.选择合适的公式_笔记","note":"视频|17:32","orig":"（知识）公式适用于一切匀变速直线运动（匀加速、匀减速、往返运动），往返运动可对全过程列式（如竖直上抛）","link":""},{"id":"phy0272","t":"匀变速推论·中时速推论","s":"看到【匀变速运动求中间时刻瞬时速度，或需把平均速度转化为瞬时速度】","c":"想到【用v̄=v(t/2)把平均速度变成某时刻的瞬时速度再代入运动学公式】；警惕【中间时刻$\\neq$位移中点，加速运动中两者位置不同】","src":"物一轮044.学习两个重要推论_笔记","note":"视频|00:47-10:47","orig":"（知识）一段匀变速直线运动的平均速度等于中间时刻的瞬时速度：v̄=v(t/2)=(v₀+v)/2，仅适用匀变速；v-t图像中对应梯形中位线高度","link":""},{"id":"phy0273","t":"中时速推论·两段位移求加速度","s":"看到【给出两段位移和各自时间求加速度】","c":"想到【各段平均速度即各段中间时刻的瞬时速度，再用v=v_{0}+at联立求解】；警惕【时刻计算需包含前段运动时长（时间轴对齐）】","src":"物一轮044.学习两个重要推论_笔记","note":"视频|05:34-10:47","orig":"（例）列车AB段132m/3s、BC段196m/4s：v̄_AB=44m/s对应1.5s时刻，v̄_BC=49m/s对应5s时刻，44+a×3.5=49得a≈1.4m/s²","link":""},{"id":"phy0274","t":"匀变速推论·逐差推论","s":"看到【相邻相等时间间隔的位移差】","c":"想到【$\\Delta$x=aT^{2}可直接求加速度或验证匀变速】；警惕【前提是匀变速且时间间隔相等】","src":"物一轮044.学习两个重要推论_笔记","note":"视频|10:47-16:59","orig":"（知识）匀变速中任意相邻相等时间T内的位移差Δx=aT²，无论x₂−x₁还是xₙ−xₙ₋₁都成立","link":""},{"id":"phy0275","t":"逐差推论·运动性质判断","s":"看到【连续相等时间的位移差不成等差数列】","c":"想到【可反推运动并非全程匀变速（如中途已停止）】；警惕【匀变速$\\to$等差成立，但等差$\\to$匀变速不成立（等差是必要不充分条件）】","src":"物一轮044.学习两个重要推论_笔记","note":"视频|13:10-15:00","orig":"（例）汽车刹车前三秒位移9m、7m、1m：位移差2m与6m不成等差，因最后一秒内车辆已停止（运动含匀变速段+静止段）","link":""},{"id":"phy0276","t":"逐差法·求加速度","s":"看到【由$\\Delta$x和T求加速度（计算或实验题）】","c":"想到【a=$\\Delta$x/T^{2}，比中时速法更简洁直接】；警惕【使用前需验证匀变速前提，为实验逐差法奠基】","src":"物一轮044.学习两个重要推论_笔记","note":"视频|15:00-16:59","orig":"（例）AB=132m、BC=196m，时间均4s：中时速法33m/s→49m/s得a=4m/s²；逐差法Δx=64m=aT²=a×4²得a=4m/s²，两法结果一致","link":""},{"id":"phy0277","t":"零初速匀变速·公式简化","s":"看到【初速度为零的匀变速运动】","c":"想到【直接用简化公式或比例推论求解，无需死记比例结论，会推导即可】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|00:32-01:16","orig":"（知识）v₀=0时公式简化为：v=at、x=½at²、v²=2ax，所有比例推论均基于这三个简化公式推导","link":""},{"id":"phy0278","t":"等时分割·速度比","s":"看到【初速为零匀加速求第1、2、3…秒末（或n秒末）的速度比】","c":"想到【速度比为1:2:3:…:n】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|02:24-03:55","orig":"（知识）v₁:v₂:v₃:…:vₙ=1:2:3:…:n，由v=at、速度与时间成正比推得","link":""},{"id":"phy0279","t":"等时分割·前n秒位移比","s":"看到【初速为零匀加速求前1、2、3…秒的总位移比】","c":"想到【前n秒位移比为1:4:9:…:n^{2}】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|03:55-04:56","orig":"（知识）X₁:X₂:X₃:…:Xₙ=1:4:9:…:n²，由x=½at²、位移与时间平方成正比推得","link":""},{"id":"phy0280","t":"等时分割·第n秒内位移比","s":"看到【初速为零匀加速求第1、2、3…秒内的位移比】","c":"想到【第n秒内位移比为奇数等差1:3:5:…:(2n−1)，由前n秒比例做差】；警惕【区分“前n秒位移”与“第n秒内位移”】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|04:56-07:26","orig":"（知识）x₁:x₂:x₃:…:xₙ=1:3:5:…:(2n−1)，由前n秒位移比做差得到（如x₂=X₂−X₁=4−1=3）","link":""},{"id":"phy0281","t":"比例推论·判断初速度","s":"看到【给出连续相等时间的位移比要求判断运动性质或初速度】","c":"想到【1:3:5对应v_{0}=0的匀变速；等差但非1:3:5则v_{0}$\\neq$0；非等差则非匀变速】；警惕【位移比等差不能反推匀变速，需题目明确匀变速前提】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|07:26-10:08","orig":"（知识）位移比1:3:5→可能是v₀=0的匀变速；3:4:5、6:8:10等非1:3:5的等差→初速必不为零；非等差→非匀变速","link":""},{"id":"phy0282","t":"等位移分割·速度比","s":"看到【初速为零匀加速按相等位移分段求各段末速度比】","c":"想到【v∝√x，n米末速度比为1:√2:√3】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|10:16-11:18","orig":"（知识）由v²=2ax，a恒定时v²与x成正比：位移比1:2:3对应速度平方比1:2:3，速度比为1:√2:√3","link":""},{"id":"phy0283","t":"等位移分割·时间比","s":"看到【初速为零匀加速按相等位移分段求时间比】","c":"想到【前n米时间比1:√2:√3，第n米内时间比1:(√2−1):(√3−√2)】；警惕【第n米内时间需由前n米时间做差，非直接比例】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|11:18-13:35","orig":"（知识）由x=½at²：前n米时间比1:√2:√3；第n米内时间比1:(√2−1):(√3−√2)，由前n米时间做差得到","link":""},{"id":"phy0284","t":"比例推论·推广到末速为零匀减速","s":"看到【末速度为零的匀减速运动求位移/速度/时间比例】","c":"想到【逆向思考为初速为零的匀加速，全部比例推论可直接套用】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|13:35-15:46","orig":"（知识）末速度为零的匀减速可视为反向的初速为零匀加速，时间轴反转后位移比例关系保持不变（如竖直上抛最高点后的下落与自由落体相同）","link":""},{"id":"phy0285","t":"比例推论·自由落体分段例","s":"看到【自由落体/初速为零匀加速按不等长时间分段求位移比】","c":"想到【分割为等时间段套用比例推论，比逐段算x=½gt^{2}更高效】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|15:46-18:43","orig":"（例）自由落体5s分为5个1s等时段：位移比1:3:5:7:9，前两秒:第二个两秒:第五秒=(1+3):(5+7):9=4:12:9","link":""},{"id":"phy0286","t":"比例推论·子弹穿砖例","s":"看到【相等位移分段+末速度为零的匀减速（如穿砖、滑块问题）】","c":"想到【逆向视为初速为零匀加速：速度比v∝√x，第n段时间比1:(√2−1):(√3−√2):(2−√3)】；警惕【混淆总时间与分段时间的比例关系】","src":"物一轮045.了解零初速匀变速直线运动的比例推论_笔记","note":"视频|18:43","orig":"（例）子弹匀减速恰好穿过四块相同砖：四段相等位移，速度比1:√2:√3:2（v∝√x），时间比1:(√2−1):(√3−√2):(2−√3)","link":""},{"id":"phy0287","t":"自由落体·运动条件","s":"看到【判断物体是否做自由落体运动】","c":"想到【只受重力+由静止释放两条件同时满足】；警惕【需关注题目是否说明“忽略空气阻力”】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|00:38-01:51","orig":"（知识）力学条件：只受重力（a=g）；运动条件：由静止释放（v₀=0），题目常出现“由静止脱手”等描述","link":""},{"id":"phy0288","t":"自由落体·基本规律","s":"看到【自由落体求速度、下落高度或时间】","c":"想到【已知h求v用v^{2}=2gh，已知h求t用h=½gt^{2}，缺h求v用v=gt】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|01:51-03:05","orig":"（知识）由匀变速公式代入v₀=0、a=g：v=gt、h=½gt²、v²=2gh","link":""},{"id":"phy0289","t":"自由落体·杆类长度问题","s":"看到【杆/绳等自身长度不可忽略的落体问题】","c":"想到【优先从v_{0}=0初始状态列式，用时间差建立方程，注意杆长等几何约束】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|03:05-10:07","orig":"（例）铁杆脱手下落h=45m：用v²=2gh得v=30m/s；杆过某点5m历时0.2s，由½g(t₂²−t₁²)=5m与t₂−t₁=0.2s联立得t₁=2.4s、h₁=28.8m；最大反应时间5=½gt²得t=1s","link":""},{"id":"phy0290","t":"竖直上抛·条件与全程列式","s":"看到【竖直上抛运动】","c":"想到【全程为匀变速，可对全程直接列式】；警惕【通常以竖直向上为正方向，g取负值】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|10:07-12:50","orig":"（知识）只受重力、有竖直向上的初速度v₀，全程a=g属匀变速；v=v₀+gt、h=v₀t+½gt²、v²−v₀²=2gh（取向上为正时g为负）","link":""},{"id":"phy0291","t":"竖直上抛·矢量正负判断","s":"看到【竖直上抛中判断速度、位移的正负号】","c":"想到【统一正方向后各矢量带符号代入；速度正负可判断上升或下降】；警惕【物体落到抛出点下方时位移须取负】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|12:50-16:12","orig":"（知识）正方向常取初速度方向（向上）：g恒为负；抛出点上方位移为正、下方位移为负；速度与正方向同向为正、反向为负","link":""},{"id":"phy0292","t":"竖直上抛·脱离运动物体例","s":"看到【物体从气球/升降机等运动物体上脱离或被竖直抛出】","c":"想到【脱离瞬间具有原物体的速度，以地面为参考系对抛体全程列式】；警惕【参考系选择错误、抛出点下方位移为负、距离（标量）与位移（矢量）混淆】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|16:12-26:40","orig":"（例）物体以v₀=20m/s脱离匀速上升的热气球，落至抛出点下方105m处：v²−20²=2×(−10)×(−105)得v=50m/s；−105=20t−5t²得t=7s；5s后与气球相距100+25=125m","link":""},{"id":"phy0293","t":"匀变速往返·对称性","s":"看到【竖直上抛或斜面等匀变速往返运动求时间、速度】","c":"想到【用速度对称、时间对称简化计算，可从最高点起逆向按初速为零下落分析】；警惕【最高点速度为零但加速度仍为g】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|26:40-30:50","orig":"（知识）速度对称：同一位置上升与下落速度等大反向（v_up=−v_down）；时间对称：同一段高度上升与下落用时相同；适用于任意匀变速往返（如斜面a=gsinθ）","link":""},{"id":"phy0294","t":"对称性·对称自由下落法测g","s":"看到【竖直抛体两次经过同两点求g（对称自由下落法）】","c":"想到【利用时间对称：最高点到该点的时间为经过间隔的一半，再由位移差列式】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|30:50-37:35","orig":"（例）物体竖直上抛两次经过a、b点间隔Tₐ、T_b，ab间距h：最高点到a、b用时各为Tₐ/2、T_b/2，h=½g(Tₐ/2)²−½g(T_b/2)²，得g=8h/(Tₐ²−T_b²)","link":""},{"id":"phy0295","t":"对称性·斜面往返多解","s":"看到【斜面上滑经过同一点对应两个不同时间（多解）】","c":"想到【多解源于直接上滑经该点与往返再次经该点两种情形，按位移比例与对称性分段求解】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|30:50-37:35","orig":"（例）物体沿4m光滑斜面上滑，B距底端3m、到B用时t：直接上滑情形AB:BC=3:1时间比1:1得总时间2t；往返情形3t₀=t得t₀=t/3，AC段用时2t/3","link":""},{"id":"phy0296","t":"匀变速推论·适用条件小结","s":"看到【解题前选择推论】","c":"想到【中时速、逐差不限初速度；比例推论必须v_{0}=0，大题需现场推导不可直接引用】","src":"物一轮046.了解自由落体和竖直上抛的规律_笔记","note":"视频|37:35","orig":"（知识）中时速推论v̄=v(t/2)与逐差推论Δx=aT²适用于任何匀变速直线运动（不要求v₀=0）；比例推论仅限初速为零，未要求记忆的比例关系需掌握推导","link":""},{"id":"phy0297","t":"多过程运动·拆分思想","s":"看到【运动含多个过程（匀加速+匀速、匀减速+静止等）】","c":"想到【拆段后每段独立列式，再用段间关系联立】","src":"物一轮047.求解多过程运动_笔记","note":"视频|01:19-02:07","orig":"（知识）将整段运动拆分为两段不同运动（人为拆分或实际不同运动，加速度可同可不同），每段有独立位移、时间和速度变化，需关注过程间衔接点","link":""},{"id":"phy0298","t":"多过程运动·时间关系","s":"看到【多过程问题方程数不够】","c":"想到【补充总时间等于各段时间之和的关系式】","src":"物一轮047.求解多过程运动_笔记","note":"视频|02:07-02:31","orig":"（知识）t=t₁+t₂，建立时间方程可多解一个未知数，是解题的重要关系式","link":""},{"id":"phy0299","t":"多过程运动·位移关系","s":"看到【多过程问题求总位移】","c":"想到【总位移=各段位移之和（同一直线上）】","src":"物一轮047.求解多过程运动_笔记","note":"视频|02:31-02:43","orig":"（知识）直线运动x=x₁+x₂，总位移为各段位移的数值相加","link":""},{"id":"phy0300","t":"多过程运动·速度关系","s":"看到【两段运动的衔接点】","c":"想到【衔接点速度相等是联立两段方程的桥梁】；警惕【存在碰撞等速度突变时该关系失效，需具体分析】","src":"物一轮047.求解多过程运动_笔记","note":"视频|02:43-03:21","orig":"（知识）衔接点：前段末速度v₁=后段初速度v₂（无碰撞时）；若存在碰撞等速度突变则该关系不成立","link":""},{"id":"phy0301","t":"多过程运动·解题流程","s":"看到【多过程运动不知从何下手】","c":"想到【先画简图/v-t图使运动可视化，再分段列式联立】","src":"物一轮047.求解多过程运动_笔记","note":"视频|03:21-04:48","orig":"（知识）流程：画运动过程简图和v-t图→确定每段运动性质并标注（匀速/匀加速/匀减速）→对单段列匀变速公式→用三关系建立联系联立方程","link":""},{"id":"phy0302","t":"多过程运动·声波传播例","s":"看到【物体运动与声/光信号传播结合的问题】","c":"想到【分别列出物体与信号波的位移方程，抓住最后信号发出到接收的时间差作辅助关系】；警惕【时间轴上运动时间与信号传播时间要分开理清】","src":"物一轮047.求解多过程运动_笔记","note":"视频|04:48-11:51","orig":"（例）救护车匀加速10s（a=2m/s²）后匀速鸣笛：车位移l=½at₁²+v(t₀−10)，声波位移l=v₀(41−t₀)，联立解得t₀=39s、l=680m","link":""},{"id":"phy0303","t":"多过程运动·刹车静止段","s":"看到【刹车问题给定时间超过停止时间】","c":"想到【先算刹车停止时间，位移只算到停止时刻；平均速度=总位移/总时间（含静止段）】；警惕【km/h未换算m/s、静止段无位移但计入总时间】","src":"物一轮047.求解多过程运动_笔记","note":"视频|11:51-15:49","orig":"（例）汽车108km/h=30m/s刹车：t=v₀/a=6s（给定9s含3s静止）；前4s位移80m，第4s内12.5m，9s总位移90m，平均速度90/9=10m/s","link":""},{"id":"phy0304","t":"多过程运动·人为分段匀变速","s":"看到【同一匀变速被人为拆成两段，给出两段位移与相同速度变化量】","c":"想到【设关键点速度，对两段用v^{2}−v_{0}^{2}=2ax列式，相除消去共同量a】；警惕【优先选含共同物理量（如a）的公式】","src":"物一轮047.求解多过程运动_笔记","note":"视频|16:14","orig":"（例）马拉松迎风直跑：AB=6m、BC=9m，两段Δv均为2m/s；设v_B，列v_B²−(v_B−2)²=2a×6与(v_B+2)²−v_B²=2a×9，两式相除消a得v_B=5m/s、v_C=7m/s","link":""},{"id":"phy0305","t":"追及问题·慢追快特征","s":"看到【慢追快追及问题（后车初速小但最终速度超过前车）】","c":"想到【最终后方速度更大则必定能追上，只需讨论追上时间与最大间距】","src":"物一轮048.求解单向慢追快的问题_笔记","note":"视频|00:20-01:43","orig":"（知识）后方物体初始速度较小，通过变速最终速度大于前方物体：后加速前匀速、两者都加速但后加速度更大、后静止前减速；初始间距x₀影响追及难度和时间","link":""},{"id":"phy0306","t":"追及问题·典型设问","s":"看到【追及问题问何时追上或最大间距】","c":"想到【间距变化由两物体速度大小关系决定，先分析共速前后的趋势再列式】","src":"物一轮048.求解单向慢追快的问题_笔记","note":"视频|01:43-02:28","orig":"（知识）典型问题：何时追上（只讨论时间）；最大间距（需分析过程中两物体间距的变化规律）","link":""},{"id":"phy0307","t":"追及问题·共速临界","s":"看到【慢追快中两物体速度相等的时刻】","c":"想到【共速是间距最大的临界点，x_m=x_{0}+$\\Delta$x（共速前相对位移）】","src":"物一轮048.求解单向慢追快的问题_笔记","note":"视频|02:28-09:43","orig":"（知识）共速前（前车更快）间距逐渐增大；共速时间距达最大值；共速后（后车更快）间距逐渐减小；x_m=x₀+共速前的相对位移","link":""},{"id":"phy0308","t":"追及问题·求解方法","s":"看到【求追上时间或最大间距】","c":"想到【追上：后车位移−前车位移=x_{0}列方程；最大间距：先求共速时刻再算相对位移】；警惕【公式法通常比图像法（需处理梯形面积）更高效】","src":"物一轮048.求解单向慢追快的问题_笔记","note":"视频|02:28-09:43","orig":"（知识）公式法：利用匀变速公式建立位移关系；图像法：通过v-t图面积差计算相对位移","link":""},{"id":"phy0309","t":"追及问题·反应时间陷阱","s":"看到【追及中存在反应时间/启动延迟】","c":"想到【延迟时间内前车继续行驶，须将延迟计入初始间距，再列位移差方程½at^{2}−v_{1}t=x_{0}】；警惕【二次方程舍去负解；初始间距包含全部延迟阶段】","src":"物一轮048.求解单向慢追快的问题_笔记","note":"视频|09:43","orig":"（例）罪犯车v₁=10m/s匀速，警车反应0.4s+启动2s后以a=2m/s²匀加速：x₀=10×2.4=24m；½at²−v₁t=x₀得t=12s追上；共速t=5s时相对位移25m，x_m=24+25=49m","link":""},{"id":"phy0310","t":"追及问题·变速情景分类","s":"看到【不同变速方式的追及场景】","c":"想到【无论哪种变速组合，共速时刻都是间距极值的分析核心】","src":"物一轮048.求解单向慢追快的问题_笔记","note":"视频|00:20-01:43","orig":"（知识）变速情景：后车加速前车匀速、后车加速度更大、前车减速后车静止；共速逻辑通用","link":""},{"id":"phy0311","t":"直线运动·快追慢问题的特征","s":"看到【后方物体速度先大于前方物体、变速后速度小于前方物体的追及场景】","c":"想到【追赶只在共速前有效，核心是比较共速前相对位移$\\Delta$x与初始间距x_{0}】；警惕【共速时刻是临界点，共速后间距只会拉大】","src":"物一轮049.求解单向快追慢的问题_笔记","note":"视频|00:01-00:08","orig":"（知识）后方物体初速v₁大于前方物体v₂，通过变速（加速/减速）后最终速度小于前方物体；追赶过程仅在共速前有效。","link":""},{"id":"phy0312","t":"直线运动·能否追上的判断","s":"看到【问能否追上/恰好追上/追上前最小距离】","c":"想到【用v-t图面积求共速前$\\Delta$x，与x_{0}比较三分讨论：$\\Delta$x<x_{0}追不上、$\\Delta$x=x_{0}恰相遇、$\\Delta$x>x_{0}已相遇】；警惕【必须算共速前的相对位移，不能拿全程位移比较】","src":"物一轮049.求解单向快追慢的问题_笔记","note":"视频|00:08-02:20","orig":"（知识）Δx<x₀无法追上；Δx=x₀恰在共速时刻相遇（仅1次）；Δx>x₀共速前已相遇（可能相遇2次）。","link":""},{"id":"phy0313","t":"直线运动·运动过程阶段划分","s":"看到【快追慢过程要求分析间距变化】","c":"想到【以共速时刻为界分段：前段速度差使间距减小、后段反向增大，共速时间距取极值】；警惕【间距最小的时刻是共速时刻而非速度为零时刻】","src":"物一轮049.求解单向快追慢的问题_笔记","note":"视频|02:20-08:50","orig":"（知识）阶段一（共速前）v₁>v₂间距逐渐减小；阶段二（共速后）v₁<v₂间距逐渐增大；共速时刻间距最短。","link":""},{"id":"phy0314","t":"直线运动·最小间距计算","s":"看到【求追赶过程中的最小距离】","c":"想到【x_min=x_{0}-$\\Delta$x，$\\Delta$x取共速前相对位移】；警惕【此式仅适用于未追上场景，追上时最小间距为0】","src":"物一轮049.求解单向快追慢的问题_笔记","note":"视频|02:20-08:50","orig":"（知识）未追上时，最小间距x_min=x₀-Δx（共速时刻距离最短）；追上时最小间距为0。","link":""},{"id":"phy0315","t":"直线运动·相遇次数分析","s":"看到【问相遇/碰撞发生几次】","c":"想到【$\\Delta$x=x_{0}恰1次、$\\Delta$x>x_{0}可能2次：共速前相遇后超越，共速后前车再反超】；警惕【二次相遇需分析速度反转后的相对运动】","src":"物一轮049.求解单向快追慢的问题_笔记","note":"视频|02:20-08:50","orig":"（知识）Δx=x₀相遇1次（共速时刻）；Δx>x₀相遇2次（共速前超越+共速后被反超）。","link":""},{"id":"phy0316","t":"直线运动·图像法解追及","s":"看到【两物体v-t图线间围成的面积】","c":"想到【v-t图线间面积即相对位移$\\Delta$x，分段按梯形/三角形累加后与x_{0}比较】；警惕【多段变速过程要分段算面积，漏段会算错$\\Delta$x】","src":"物一轮049.求解单向快追慢的问题_笔记","note":"视频|08:50-","orig":"（知识）通过v-t图面积计算相对位移Δx，结合x₀判断相遇情况；梯形/三角形面积需分段计算。","link":""},{"id":"phy0317","t":"直线运动·追尾事故判断（例）","s":"看到【刹车失灵/多段减速车辆的追尾判断】","c":"想到【分段求各段位移累加成$\\Delta$x，再与x_{0}比较判追尾、定相遇时刻】；警惕【未正确识别共速时刻位置、最小距离条件理解错误】","src":"物一轮049.求解单向快追慢的问题_笔记","note":"视频|08:50-","orig":"（例）初始间距x₀=30m，共速时刻t=5s，共速前Δx=35m（梯形15+三角形20），Δx>x₀判追尾；x₀=45m时x_min=45-35=10m。答案BD。","link":""},{"id":"phy0318","t":"直线运动·多过程追及的总体策略","s":"看到【追及相遇中物体经历多段运动（刹车+静止、加速+匀速、往返），相遇阶段未指明】","c":"想到【先分情况讨论可能的相遇阶段（减速段/静止段、去程/回程），逐一列式验证】；警惕【直接套单一过程公式可能得出物理解上不合理的解】","src":"物一轮050.求解复杂的往返、多过程追及问题_笔记","note":"视频|00:00-01:36","orig":"（知识）典型场景：前方刹车（匀减速+静止）、后方加速+匀速、往返运动——相遇发生阶段不确定。解题方法：先讨论可能的相遇阶段，再具体求解。","link":""},{"id":"phy0319","t":"直线运动·刹车追及问题","s":"看到【前方物体刹车减速且可能中途停止，问何时相遇】","c":"想到【先求刹车总时间和总位移，验证减速阶段位移差是否已达x_{0}；不够则物体停在停止位置，按静止障碍物再算】；警惕【直接按全程匀减速列方程会解出超出刹车时间的假解】","src":"物一轮050.求解复杂的往返、多过程追及问题_笔记","note":"视频|01:36-08:54","orig":"（例）B初速10m/s刹车a=2m/s²，A以4m/s匀速，相距7m。先算刹车时间t=v_B/a=5s、x_B=v_B²/2a=25m、x_A=20m；位移差25-20=5m<7m，说明静止阶段相遇，再列4t'+20-25=7解得t'=3s，总时间8s。","link":""},{"id":"phy0320","t":"直线运动·二次相遇时间解的意义","s":"看到【追及方程解出两个正的时间根】","c":"想到【两根分别对应首次相遇和反超后的二次相遇，较短时间为首次相遇】；警惕【不检验两解的物理意义会答错问的次数】","src":"物一轮050.求解复杂的往返、多过程追及问题_笔记","note":"视频|01:36-08:54","orig":"（知识）共速前相遇时方程存在两个解（如t₁=3+√2、t₂=3-√2），分别对应首次和二次相遇。","link":""},{"id":"phy0321","t":"直线运动·竖直上抛相遇时间范围","s":"看到【两物体先后竖直上抛，问抛出时间间隔的取值范围】","c":"想到【抓两个临界：一物体刚抛出另一物体恰落地定$\\Delta$t_max，低速者在最高点相遇定$\\Delta$t_min；利用竖直上抛上升/下降时间对称、h∝t^{2}简化计算】；警惕【往返问题要区分相遇在去程还是回程】","src":"物一轮050.求解复杂的往返、多过程追及问题_笔记","note":"视频|08:54-","orig":"（例）A以2v₀、B以v₀先后竖直上抛，间隔Δt：最晚Δt_max=4v₀/g（B刚抛出时A恰落地）；最早Δt_min=(3+1)v₀/g（B达最高点时相遇），答案(3+1)v₀/g<Δt<4v₀/g。","link":""},{"id":"phy0322","t":"直线运动·多过程问题解题要点","s":"看到【多过程/往返运动的综合追及大题】","c":"想到【流程：划分过程$\\to$算临界时间和位移$\\to$比较位移差定相遇阶段$\\to$分情况列式】；警惕【忽略运动状态改变的时刻（如速度减为零、方向反转）】","src":"物一轮050.求解复杂的往返、多过程追及问题_笔记","note":"视频|08:54-","orig":"（知识）明确各物体运动过程划分→计算各过程临界时间点和位移→比较位移差判断实际相遇阶段；常用v²=2as、竖直上抛对称性、位移-时间图像辅助分析。","link":""},{"id":"phy0323","t":"牛顿运动定律·三大定律定位","s":"看到【考查力与运动关系的题目，需定位用哪条牛顿定律】","c":"想到【牛一定性判断运动状态是否改变、牛二定量列F=ma、牛三处理物体间相互作用，三者是受力分析与运动学的桥梁】；警惕【牛一不是“不受力才匀速”的特例表述，它是定义惯性系的定律】","src":"物一轮051.【课前必看】本讲听课建议_笔记","note":"视频|04:23","orig":"（知识）牛一：判断运动形式的重要依据，单独命题少（浙江卷除外）；牛三：中频考点，多在选择题；牛二：超高频考点，选择与综合大题均出现。","link":""},{"id":"phy0324","t":"牛顿运动定律·连接体问题","s":"看到【多个物体通过绳、弹簧、接触面连接一起运动】","c":"想到【先整体求共同加速度，再隔离单个物体求内力；研究对象的选取是解题核心】；警惕【整体法中内力抵消不出现，隔离时必须补上相互作用力】","src":"物一轮051.【课前必看】本讲听课建议_笔记","note":"视频|04:23","orig":"（知识）多物体系统分析，研究对象选择为核心；系统内力与外力处理，整体法与隔离法应用。","link":""},{"id":"phy0325","t":"牛顿运动定律·变力作用下的运动","s":"看到【力随位置/时间/速度变化（弹簧、阻力）的动力学过程】","c":"想到【抓住瞬时对应关系分析每一位置的加速度，必要时用微元思想处理】；警惕【变力过程不能整段套匀变速公式】","src":"物一轮051.【课前必看】本讲听课建议_笔记","note":"视频|04:23","orig":"（知识）变力（如弹簧力、空气阻力）对运动的影响；瞬时加速度分析，微元思想应用。","link":""},{"id":"phy0326","t":"牛顿运动定律·动力学临界条件","s":"看到【“恰好分离”“刚好不滑动”“恰好相对静止”等临界字眼】","c":"想到【识别临界状态（如弹力为零、摩擦力达最大静摩擦），把极值条件转化为方程】；警惕【临界条件漏判或判错会导致整题方向错误】","src":"物一轮051.【课前必看】本讲听课建议_笔记","note":"视频|04:23","orig":"（知识）常见临界问题（如滑动摩擦、分离条件）；临界状态识别，极值条件转化。","link":""},{"id":"phy0327","t":"牛顿运动定律·传送带与板块模型","s":"看到【物体在传送带上/叠放板块问题上运动】","c":"想到【以“共速”为转折点判断摩擦力方向和突变，分阶段分析相对运动；板块问题注意两物体加速度的关联】；警惕【摩擦力方向由相对运动（趋势）方向决定，不是由对地速度决定】","src":"物一轮051.【课前必看】本讲听课建议_笔记","note":"视频|04:23","orig":"（知识）传送带：相对运动与摩擦力突变、速度匹配、能量转化；板块：多物体叠加运动，摩擦力方向判断与加速度关联性。","link":""},{"id":"phy0328","t":"牛顿第一定律·内容与力、运动关系","s":"看到【判断物体运动状态是否改变/是否受合力】","c":"想到【运动状态改变（v大小或方向变）$\\Leftrightarrow$存在外力（合力不为零），双向充要】；警惕【匀速直线运动和静止本质都是速度不变的状态】","src":"物一轮052.回顾牛顿第一定律_笔记","note":"视频|00:20-05:42","orig":"（知识）一切物体总保持匀速直线运动状态或静止状态，除非外力迫使它改变；运动状态用速度矢量v（大小+方向）表征；速度变化⇔合力不为零，二者互为充要条件。","link":""},{"id":"phy0329","t":"牛顿第一定律·惯性","s":"看到【比较不同物体惯性大小/问惯性与速度的关系】","c":"想到【惯性大小只看质量，质量相同惯性相同，与速度、受力无关】；警惕【惯性不是力，不能说“受到惯性作用”；惯性$\\neq$动能或冲击力】","src":"物一轮052.回顾牛顿第一定律_笔记","note":"视频|00:20-05:42","orig":"（知识）惯性是保持原有运动状态不变的性质，反映物体抵抗运动状态变化的能力；量化标准仅由质量决定，质量越大惯性越大；与速度无关（静止卡车与高速卡车惯性相同）。","link":""},{"id":"phy0330","t":"牛顿第一定律·热气球释放物体（例）","s":"看到【从运动的载体上释放/掉落物体，问其后续运动】","c":"想到【速度不会突变，释放瞬间物体保留释放前速度，再按只受的力判断运动模型】；警惕【误认为释放后立即自由下落（初速度为零）】","src":"物一轮052.回顾牛顿第一定律_笔记","note":"视频|05:56-07:28","orig":"（例）物体随热气球以速度v上升，释放瞬间因惯性保持原有向上速度，仅受重力，做竖直上抛运动（先减速上升后加速下落）。","link":""},{"id":"phy0331","t":"牛顿第一定律·绳断后小球运动（例）","s":"看到【做圆周运动的物体突然失去约束（绳断、线脱）】","c":"想到【不受力时保持瞬时速度（大小+方向）做匀速直线运动，方向沿断开瞬间的切线】；警惕【惯性维持的是速度矢量而非运动轨迹，不会沿圆弧继续】","src":"物一轮052.回顾牛顿第一定律_笔记","note":"视频|07:28-","orig":"（例）小球做匀速圆周运动，绳断后外力消失，沿断开瞬间切线方向做匀速直线运动；易错：不是继续做曲线运动。","link":""},{"id":"phy0332","t":"牛顿第三定律·内容与特征","s":"看到【问两物体间相互作用力的大小/方向关系】","c":"想到【作用力与反作用力恒等大反向共线，且同质、异体、同生同灭】；警惕【该定律恒成立，与物体静止、平衡或加速无关，不能认为加速时反作用力变小】","src":"物一轮053.回顾牛顿第三定律_笔记","note":"视频|00:29-01:27","orig":"（知识）作用力与反作用力总是大小相等、方向相反、作用在同一直线上；口诀：等大、反向、共线；还具有同质（相同性质）、异体（作用在不同物体）、同时出现同时消失的特征。","link":""},{"id":"phy0333","t":"牛顿第三定律·力的同质性","s":"看到【问某个力的反作用力是什么力/作用在谁身上】","c":"想到【反作用力与原力性质必相同：弹力对弹力、摩擦力对摩擦力、重力对“物体吸引地球”的引力】；警惕【重力的反作用力作用在地球上，不是支持力或摩擦力】","src":"物一轮053.回顾牛顿第三定律_笔记","note":"视频|01:27-05:58","orig":"（知识）弹力的反作用力必为弹力（桌面支持力N的反作用是球对桌面的压力N'）；摩擦力的反作用力是摩擦力（斜面对物块静摩擦f向上的反作用是物块对斜面f'向下）；重力的反作用力是物体对地球的吸引力G'（源于万有引力）。","link":""},{"id":"phy0334","t":"牛顿第三定律·受力分析中的应用策略","s":"看到【某物体受力复杂难直接分析，但有受力简单的关联物体】","c":"想到【“由简入繁”：先分析简单物体，用牛三把相互作用力反推到复杂物体，再结合整体法验证】；警惕【反作用力作用在另一物体上，不能与原力画在同一受力图中抵消】","src":"物一轮053.回顾牛顿第三定律_笔记","note":"视频|06:46-11:26","orig":"（知识）物体A受力复杂时，先分析关联物体B的受力，再通过牛三反推A的受力；系统中有多个相互作用物体时先分析受力简单的物体。","link":""},{"id":"phy0335","t":"牛顿第三定律·平衡力与相互作用力区分","s":"看到【判断一对力是平衡力还是作用力与反作用力】","c":"想到【看作用对象：同体等大反向是平衡力，异体等大反向是相互作用力】；警惕【相互作用力不同体，永远不能“抵消”，也不能写进同一个物体的平衡方程】","src":"物一轮053.回顾牛顿第三定律_笔记","note":"视频|06:46-11:26","orig":"（知识）易错提醒：注意区分相互作用力与平衡力，避免将反作用力误计入同一物体平衡条件。","link":""},{"id":"phy0336","t":"牛顿第三定律·匀速运动中相互作用判断（例）","s":"看到【叠加/并排物体匀速运动，问接触面间有无摩擦力】","c":"想到【先由运动状态定合力：匀速（或静止）则合力为零，逐个物体用平衡条件判断接触力有无，再用牛三互推】；警惕【无需额外假设不存在的摩擦力，“无加速度$\\to$无接触摩擦”可直接推出】","src":"物一轮053.回顾牛顿第三定律_笔记","note":"视频|11:26-","orig":"（例）AB整体匀速运动时地面摩擦力f_d与拉力F平衡；B无加速度→水平合力为零→A对B无摩擦力，由牛三B对A也无摩擦力；A仅受F和f_d即可平衡。","link":""},{"id":"phy0337","t":"牛顿第二定律·公式与决定式、定义式","s":"看到【区分加速度的决定式与定义式/问力与加速度谁是因谁是果】","c":"想到【a=F/m是决定式揭示本质，a=$\\Delta$v/$\\Delta$t是定义式仅作量度；力是因、加速度是果】；警惕【不能说“a与$\\Delta$v成正比、与$\\Delta$t成反比”作为因果表述】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|02:20-04:07","orig":"（知识）F=ma，F为合外力（N）、m质量（kg）、a加速度；力是因、加速度是果。决定式a=F/m揭示a的产生原因；定义式a=Δv/Δt仅反映数量关系，不揭示成因。","link":""},{"id":"phy0338","t":"牛顿第二定律·矢量性","s":"看到【已知加速度方向求合力方向/由运动情况判断受力】","c":"想到【a的方向≡F合的方向；加速还是减速看F与v是同向还是反向】；警惕【速度方向与合力方向无必然联系，物体向右运动可能受向左的力】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|04:07-06:51","orig":"（知识）加速度方向始终与合外力方向一致；v方向与F方向可任意夹角，无必然联系；F与v同向→加速，反向→减速；不能通过运动方向直接判断受力方向。","link":""},{"id":"phy0339","t":"牛顿第二定律·独立性","s":"看到【物体受多个力，求合加速度】","c":"想到【先合成力求F合再由a=F合/m计算，只做一次矢量合成更简便；各方向分力独立产生分加速度（F_x=ma_x）】；警惕【每个方向的力只负责该方向的加速度，不要混轴列式】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|06:51-09:26","orig":"（知识）每个分力Fᵢ独立产生加速度aᵢ=Fᵢ/m，互不干扰；可先矢量合成各分力求F合再算a（先合成法），也可先求各aᵢ再合成；优先先合成法，只需一次矢量合成。","link":""},{"id":"phy0340","t":"牛顿第二定律·瞬时性","s":"看到【求某一时刻/某一位置的加速度，或力发生突变的瞬间】","c":"想到【F=ma逐时刻成立，对特定时刻单独受力分析列式】；警惕【不能对整个过程笼统用F=ma，力变则a随时刻变】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|09:26-11:06","orig":"（知识）定律对应物体的瞬时状态（某一时刻或某一位置）；典型错误：对运动过程整体列式，应分解为瞬时状态分析。","link":""},{"id":"phy0341","t":"牛顿第二定律·同一性","s":"看到【多物体/多状态混合的动力学列式】","c":"想到【列F=ma前先锁定“同一物体、同一时刻”，再核对F、m、a三者的归属】；警惕【张冠李戴：拿甲的力算乙的加速度、拿M+m当小物块质量】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|11:06-12:21","orig":"（知识）F、m、a必须对应同一物体的同一状态；典型错误：用物体A的F与物体B的m列式，或用t₁时刻的F求t₂时刻的a。","link":""},{"id":"phy0342","t":"牛顿第二定律·板块模型受力计算（例）","s":"看到【物块叠放在木板上、拉木板求两物体加速度】","c":"想到【隔离两物体分别受力分析：滑动摩擦f=$\\mu$N成对出现方向相反；上方物体对下方的压力使地面支持力N_{2}=(M+m)g】；警惕【摩擦力方向由相对运动方向决定，两物体摩擦力方向通常相反】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|12:21-18:54","orig":"（例）m=1kg物块在M=4kg木板上：物块f₁=μmg向右，aₘ=μg；木板受地面摩擦f₂=μ(M+m)g向左，F-μmg-μ(M+m)g=Ma_M；μ=0.2时aₘ=2m/s²、a_M=6.5m/s²。","link":""},{"id":"phy0343","t":"牛顿第二定律·求加速度：所有分力已知、a方向未知","s":"看到【所有外力大小方向都已知，只求加速度】","c":"想到【矢量合成求F合，直接a=F合/m，方向沿合力方向；一维受力取合力方向为正】；警惕【二维受力需建平面直角坐标系再分解，不能代数直加】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|19:14-23:22","orig":"（知识）受力分析后所有分力大小方向均已知（如mg=20N与f=10N同向），一维受力以合力方向为正方向建系，F合=f+mg=30N，a=F合/m=15m/s²，方向与合力相同。","link":""},{"id":"phy0344","t":"牛顿第二定律·求加速度：部分分力未知、a方向已知","s":"看到【有些力未知但加速度方向可由约束确定】","c":"想到【令一坐标轴与a方向重合做正交分解：垂直a的轴合力为零解未知力，沿a的轴列ma方程】；警惕【先用约束条件锁定a的方向，再分解，否则方程建错】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|23:22-29:50","orig":"（知识）由运动约束（竖直墙限制、相对静止）确定加速度方向；沿加速度方向和垂直方向正交分解：x轴F_x-N=0，y轴F_y-f-mg=ma（f=μN）。","link":""},{"id":"phy0345","t":"牛顿第二定律·相对静止求加速度（例）","s":"看到【“相对静止”的小球/物体随车加速，绳偏离竖直方向$\\theta$角】","c":"想到【相对静止$\\Rightarrow$两物体加速度相同；由约束定a方向，重力与拉力合成满足tan$\\theta$=a/g，得a=g·tan$\\theta$】；警惕【a方向由合力方向定，不要默认与速度同向（可能是减速）】","src":"物一轮054.回顾牛顿第二定律_笔记","note":"视频|29:50-","orig":"（例）小球与小车相对静止：相对静止⇒加速度相同，小车水平运动⇒小球a必水平；小球仅受mg和T，合力水平构成直角三角形，tanθ=F合/mg，a=g·tanθ，合力向左则减速。","link":""},{"id":"phy0346","t":"牛顿第二定律应用·微小形变弹力的突变性","s":"看到【绳、杆、接触面约束状态发生突变（剪断、脱离、换面）】","c":"想到【微小形变弹力可瞬间改变，按突变后的新状态重新受力分析、列平衡或F=ma方程求新弹力】；警惕【不能沿用突变前的弹力值】","src":"物一轮055.应用瞬时性解决问题_笔记","note":"视频|00:36-04:52","orig":"（知识）绳、杆、接触面等微小形变可瞬间完成，弹力大小可突变（如雪橇从水平面滑上斜面，支持力瞬间从mg变为mgcos15°）；形变量趋于零时无法用f=kx算，需结合运动状态用牛顿第二定律或平衡方程求新值。","link":""},{"id":"phy0347","t":"牛顿第二定律应用·剪断细绳瞬时加速度（例）","s":"看到【双绳吊球剪断一根绳，求另一绳拉力或小球瞬时加速度】","c":"想到【区分运动趋势：仍被约束的绳按“径向平衡+切向ma”重新算拉力（原拉力已突变）；失去约束的绳拉力可突变为零，小球只受重力a=g】；警惕【速度为零时向心力需求为零，初速为零的圆周运动绳拉力可为零】","src":"物一轮055.应用瞬时性解决问题_笔记","note":"视频|04:52-11:44","orig":"（例）小球受mg、T_A、T_B三力平衡（T_A=mg/cosθ，T_B=mg·tanθ）。剪断OB瞬间做单摆运动：径向平衡T_A'=mgcosθ（已突变），切向mgsinθ=ma，a=gsinθ。剪断OA瞬间：OB拉力突变为零（否则径向合力不为零），仅受重力a=g。答案BD。","link":""},{"id":"phy0348","t":"牛顿第二定律应用·弹簧弹力的非突变性","s":"看到【系统中有弹簧，剪断旁边的绳/撤去外力，求瞬时加速度】","c":"想到【剪断其他约束的瞬间弹簧形变来不及变，弹力保持原值代入剪断后受力分析；只有剪断弹簧自身弹力才突变为0】；警惕【误认为瞬间所有力都突变】","src":"物一轮055.应用瞬时性解决问题_笔记","note":"视频|11:44-16:47","orig":"（知识）弹簧形变明显，可用f=kx计算；长度变化需要时间（明显形变需位移→位移需时间），故瞬时前后弹力不变（x不突变→f不突变）；特殊情形：剪断弹簧本身，弹力突变为0。","link":""},{"id":"phy0349","t":"牛顿第二定律应用·剪断轻绳含弹簧系统（例）","s":"看到【绳-弹簧-物体串联系统剪断绳，问各物体瞬时加速度】","c":"想到【流程：剪断前受力分析定弹簧弹力$\\to$剪断瞬间弹簧弹力不变$\\to$对每个物体重新求合力得瞬时加速度】；警惕【与弹簧相连的物体加速度一般不为g，未受扰动物体加速度仍为0】","src":"物一轮055.应用瞬时性解决问题_笔记","note":"视频|16:47-","orig":"（例）b球由弹簧吊：kx=mg；a球上端绳吊住且受弹簧弹力kx。剪断绳瞬间弹簧弹力保持kx=mg，a球合力变为mg+kx=2mg向下，a=2g；b受力不变加速度为0。","link":""},{"id":"phy0350","t":"牛顿第二定律应用·双弹簧系统平衡与突变（例）","s":"看到【多弹簧连接体先问平衡参量、再问剪断后瞬时加速度】","c":"想到【优先分析受力简单的物体，用“重力↔弹簧力替换”简化方程，几何关系建比例式求劲度系数比；剪断瞬间弹簧力不变重算合力】；警惕【平衡时的绳拉力剪断即消失，但弹簧力保留】","src":"物一轮055.应用瞬时性解决问题_笔记","note":"视频|16:47-","orig":"（例）双弹簧系统平衡：对b有k₂x=mg，对a把mg替换为k₂x等效受2k₂x向下，水平k₁x与绳拉力平衡，tan60°=k₁x/2k₂x得k₁/k₂=2√3；剪断绳瞬间a受2mg向下与2√3mg水平，合力4mg，a=4g；b受力不变a=0。","link":""},{"id":"phy0351","t":"牛顿第二定律·示重与实重","s":"看到【秤的读数/测力计示数与重力G比较】","c":"想到【示重=N或T，实重=mg，二者只有平衡时相等；比较读数实质是比较支持力与重力】；警惕【把仪器读数当成实际重力】","src":"物一轮056.应用矢量性解决问题_笔记","note":"视频|00:33-03:05","orig":"（知识）示重是测量仪器（体重秤、弹簧测力计）显示的读数，反映支持力或拉力（N或T）的大小；实重是实际重力G=mg。物体不平衡（如电梯加速）时示重与实重不相等。","link":""},{"id":"phy0352","t":"牛顿第二定律·超重、失重与完全失重","s":"看到【判断物体超重还是失重/问完全失重的条件】","c":"想到【只看加速度方向：a向上超重、a向下失重、a=g向下完全失重，与速度方向无关】；警惕【向上减速也是a向下，同样是失重】","src":"物一轮056.应用矢量性解决问题_笔记","note":"视频|05:30-08:09","orig":"（知识）超重：示重>实重（N>G）；失重：示重<实重（N<G）；完全失重：示重为零（N=0）仅受重力。由牛二矢量性：a有向上分量→超重，a有向下分量→失重，a=g向下（自由落体、抛体）→完全失重。","link":""},{"id":"phy0353","t":"牛顿第二定律·蹲起过程的超失重","s":"看到【人在体重秤上下蹲/起立，问示数变化】","c":"想到【按“先加速后减速”分段，每段只看a的方向定超失重，共四次交替】；警惕【只盯速度方向会判反：减速下降时a向上是超重不是失重】","src":"物一轮056.应用矢量性解决问题_笔记","note":"视频|09:25-14:06","orig":"（知识）下蹲：先加速下降（a向下→失重），后减速下降（a向上→超重）；起立：先加速上升（超重），后减速上升（失重）。蹲起过程含四次状态变化。","link":""},{"id":"phy0354","t":"牛顿第二定律·电梯升降的超失重","s":"看到【电梯/v-t图像分段升降，问各阶段超失重】","c":"想到【逐段读加速度方向：加速上升超重、减速上升失重、加速下降失重、减速下降超重】；警惕【匀速段a=0，N=G，既不超重也不失重】","src":"物一轮056.应用矢量性解决问题_笔记","note":"视频|14:06-15:25","orig":"（知识）上升：加速→超重，减速→失重；下降：加速→失重，减速→超重；电梯始终沿单一方向运动，而蹲起含方向反转。","link":""},{"id":"phy0355","t":"牛顿第二定律·示重图像分析（例）","s":"看到【示重（支持力）随时间变化的图像】","c":"想到【以G为基准线：低于G是失重段、高于G是超重段、示数为零是完全失重（离地/自由下落）】；警惕【示数为零未必是“没称重”，可能是物体与支撑面分离】","src":"物一轮056.应用矢量性解决问题_笔记","note":"视频|15:25-26:27","orig":"（例）某过程支持力图像：平衡段示数900N即实重G=900N；a→b段支持力降至300N对应下蹲失重；b→c段先小于G后大于G（先失重后超重）；d点后示数为零说明起跳离地完全失重。答案C。","link":""},{"id":"phy0356","t":"牛顿第二定律·已知a方向反推未知力","s":"看到【物体非平衡、加速度方向已知，问某个“接触力合力”/未知力】","c":"想到【把所有接触力打包成一个合力F，由F合=ma定合力方向，用矢量三角形/勾股定理求F，避免逐个分解接触力】；警惕【“作用力”指所有接触力的合力，不要漏掉或只算弹力】","src":"物一轮056.应用矢量性解决问题_笔记","note":"视频|27:32-31:57","orig":"（知识）适用条件：某些力大小方向不确定且a≠0；已知加速度方向即已知合力方向（F合=ma），画合力→补全力矢量三角形反推未知力。货车石块例：接触力合力F=√((mg)²+(ma)²)。","link":""},{"id":"phy0357","t":"牛顿第二定律·扶梯上的受力分析（例）","s":"看到【人站在加速/匀速的斜面式扶梯上，判断支持力与摩擦力】","c":"想到【沿水平竖直建系：a的竖直分量由N-mg提供（故N>mg），水平分量由f提供（故必有摩擦力）；匀速时f=0】；警惕【匀速阶段误认为仍有摩擦力；“作用力”是N与f的合力，方向随阶段变化】","src":"物一轮056.应用矢量性解决问题_笔记","note":"视频|31:57-36:41","orig":"（例）人站在加速上升的扶梯：合力斜右上（与a同向），必须有N>mg和向右的f；匀速阶段N=mg、f=0；作用力（N与f的合力）先斜右上后竖直向上。选项ABD对C错。","link":""},{"id":"phy0358","t":"牛顿第二定律·连接体由偏角定加速度（例）","s":"看到【连接体中某物体悬绳/悬线偏离竖直方向$\\theta$角】","c":"想到【先分析运动状态明确的偏角物体求系统共同加速度a=g·tan$\\theta$，再推广到其他物体求合力与形变】；警惕【误把m_{2}质量代入m_{1}的方程；加速度方向决定弹力方向，别凭直觉设】","src":"物一轮056.应用矢量性解决问题_笔记","note":"视频|36:41-","orig":"（例）m₂绳偏离竖直方向θ：m₂受m₂g和T，合力F合=m₂g·tanθ水平向左，a=F合/m₂=g·tanθ；m₁仅弹簧提供合力F=m₁a=m₁g·tanθ，形变量x=m₁g·tanθ/k。","link":""},{"id":"phy0359","t":"牛顿第二定律·两类基本问题","s":"看到【题目条件是「力不足」还是「运动学量不足」，需判断牛二解题方向】","c":"想到【两类问题互逆：缺力就先求a反推力，缺运动量就受力分析求a补足】；警惕【先确认运动学已知量是否足够（至少3个量）再选路径】","src":"物一轮057.应用牛顿第二定律解两类基本问题_笔记","note":"视频|00:03","orig":"（知识）已知力求运动：受力分析求合力，由F=ma求加速度再解运动学；已知运动求力：由运动学公式求加速度，再由F=ma反推合力或分力","link":""},{"id":"phy0360","t":"牛顿第二定律·解题流程","s":"看到【运动学公式已知量不足（如仅知v_{0}和位移），无法直接求目标量】","c":"想到【标准流程：受力分析$\\to$F=ma求a$\\to$代入运动学公式】；警惕【坐标系优先沿加速度方向建立，正交分解列x方向动力学方程和y方向平衡方程】","src":"物一轮057.应用牛顿第二定律解两类基本问题_笔记","note":"视频|00:30","orig":"（知识）确认运动过程已知量是否足够→不足时受力分析用F=ma补充加速度→返回运动学公式求解目标量","link":""},{"id":"phy0361","t":"牛顿第二定律·斜面滑块求加速度","s":"看到【斜面上滑块（或斜推力作用）求加速度，需受力分析】","c":"想到【沿斜面建系：x向 mgsin$\\theta$−$\\mu$mgcos$\\theta$=ma，y向 N=mgcos$\\theta$，通式a=gsin$\\theta$−$\\mu$gcos$\\theta$】；警惕【f=$\\mu$N中的N不总等于mg，有额外压力（如斜向推力）时N要重新算】","src":"物一轮057.应用牛顿第二定律解两类基本问题_笔记","note":"视频|03:41","orig":"（例）物块从斜面下滑求加速度：重力分解为mgsinθ=12N沿斜面和mgcosθ=16N垂直斜面，f=μN=8N，a=gsinθ−μgcosθ=2m/s²","link":""},{"id":"phy0362","t":"牛顿第二定律·多过程衔接","s":"看到【物体经平滑（圆弧/圆滑）连接从斜面进入水平面继续运动】","c":"想到【衔接点速度大小不变，前一段末速度=后一段初速度，分段受力分段用运动学】；警惕【每段加速度不同（斜面a=gsin$\\theta$−$\\mu$gcos$\\theta$，水平面a=$\\mu$g），不能全程套一个a】","src":"物一轮057.应用牛顿第二定律解两类基本问题_笔记","note":"视频|03:41","orig":"（例）物块从斜面滑到水平面：平滑连接速度大小不变无能量损失，v²=v₀²+2aL求得到底端速度","link":""},{"id":"phy0363","t":"牛顿第二定律·水平减速","s":"看到【物体在水平面上滑行减速，求滑行时间或距离】","c":"想到【滑动摩擦力提供减速加速度a=$\\mu$g，再用v=v_{0}+at或v^{2}−v_{0}^{2}=2ax】；警惕【摩擦力方向始终与运动方向相反，减速时a取负号】","src":"物一轮057.应用牛顿第二定律解两类基本问题_笔记","note":"视频|03:41","orig":"（例）水平面滑行：f'=μmg=10N，a'=5m/s²与运动方向相反，由v=v₀+a't得t=0.4s","link":""},{"id":"phy0364","t":"牛顿第二定律·已知运动求力","s":"看到【已知位移、时间等运动学量，反推某个力（升力/推力/拉力）】","c":"想到【先由运动学公式求a，再对物体完整受力分析列F=ma反推目标力】；警惕【阻力方向与运动方向相反：上升时阻力向下，升力F=ma+mg+f阻三项都不能漏】","src":"物一轮057.应用牛顿第二定律解两类基本问题_笔记","note":"视频|17:09","orig":"（例）无人机：由h=½at²得a=6m/s²，再由F−mg−f阻=ma得F=360N","link":""},{"id":"phy0365","t":"牛顿第二定律·撤力后运动","s":"看到【撤去某个外力（升力/推力）后物体继续运动，求新阶段的位移或时间】","c":"想到【撤力即进入新阶段，重新受力分析求新加速度a'，再用x=½a't^{2}】；警惕【阻力方向随运动方向反转（下落时阻力向上），且前段位移要纳入总高度计算】","src":"物一轮057.应用牛顿第二定律解两类基本问题_笔记","note":"视频|17:09","orig":"（例）无人机悬停下落：撤去升力后仅受重力和向上阻力，a'=(mg−f阻)/m=8m/s²，3s内下落x=½a't²=36m，离地12m","link":""},{"id":"phy0366","t":"牛二定律与图像·F-t图分析","s":"看到【F-t（力-时间）图像，力随时间分段变化】","c":"想到【逐段受力分析求合力，各段分别用F=ma求a再分析运动】；警惕【F突变时刻（如突然减小或消失）需重新计算a，加速度随之瞬时改变】","src":"物一轮058.结合牛顿第二定律分析图像_笔记","note":"视频|00:00","orig":"（知识）F-t图：分段读取各阶段力的大小和变化→求合力→由F=ma定加速度→分析运动状态","link":""},{"id":"phy0367","t":"牛二定律与图像·斜面+F-t图","s":"看到【F-t图像中推力（含斜向分量）变化，物体在斜面上运动】","c":"想到【正交分解：x向Fcos$\\theta$−mgsin$\\theta$−f=ma，y向n=mgcos$\\theta$+Fsin$\\theta$，f=$\\mu$n联立】；警惕【F变化时支持力n和摩擦力f都跟着变，不能沿用上一段的f值】","src":"物一轮058.结合牛顿第二定律分析图像_笔记","note":"视频|01:05","orig":"（例）斜面物体受斜向推力F随时间变化：0-1s F=30N加速，1-2s F=20N匀速，2-2.5s F=0减速；n=mgcosθ+Fsinθ随F变化，f=μn，a=(Fcosθ−mgsinθ−f)/m","link":""},{"id":"phy0368","t":"牛二定律与图像·多段位移求解","s":"看到【多阶段运动求总位移，各段加速度不同】","c":"想到【分段计算位移求和，或画v-t图用面积法（梯形/三角形面积）】；警惕【v-t图面积表示位移，曲线段需分段近似或积分思想】","src":"物一轮058.结合牛顿第二定律分析图像_笔记","note":"视频|01:05","orig":"（例）三阶段位移求和，或绘v-t图用梯形面积S=½×(1+2.5)×5=8.75m求总位移","link":""},{"id":"phy0369","t":"牛二定律与图像·v-t图反推受力","s":"看到【v-t图像含上滑减速和下滑加速两段（斜面往返）】","c":"想到【斜率求各段a$\\to$列上滑mgsin$\\theta$+$\\mu$mgcos$\\theta$=ma_{1}、下滑mgsin$\\theta$−$\\mu$mgcos$\\theta$=ma_{2}两方程联立解$\\theta$和$\\mu$】；警惕【摩擦力方向随运动方向改变而反向，两式符号一加一减】","src":"物一轮058.结合牛顿第二定律分析图像_笔记","note":"视频|15:08","orig":"（例）v-t图上滑减速a₁=−8m/s²、下滑加速a₂=−2m/s²，联立mgsinθ+μmgcosθ=ma₁与mgsinθ−μmgcosθ=ma₂解得θ=30°、μ=3/5","link":""},{"id":"phy0370","t":"牛二定律与图像·矢量性与返回速度","s":"看到【求斜面往返后的净位移或返回底端速度】","c":"想到【位移按正负号（矢量）相加；返回速度用v^{2}=2as对全程重新计算】；警惕【返回速度小于出发初速度（摩擦损耗），不能想当然认为对称】","src":"物一轮058.结合牛顿第二定律分析图像_笔记","note":"视频|15:08","orig":"（例）上滑位移+4m、下滑−1m，净位移3m（矢量性）；返回底端速度由v²=2as（a=2m/s²，s=4m）得v=4m/s≠初速度8m/s","link":""},{"id":"phy0371","t":"牛二定律·解题步骤总结","s":"看到【牛二定律动力学综合题，不知从何下手】","c":"想到【固定走五步流程，坐标正方向与加速度方向一致】；警惕【加速度方向与合力方向必须一致，减速阶段a为负但大小仍为正值参与计算】","src":"物一轮058.结合牛顿第二定律分析图像_笔记","note":"视频|26:14","orig":"（知识）五步：明确研究对象→受力分析画示意图→建立坐标系分解力→列动力学方程→解方程；注意矢量性（a与合力同向）、瞬时性（力变a即变）、独立性（各方向互不影响）","link":""},{"id":"phy0372","t":"牛二定律·临界与锁定问题","s":"看到【物体减速到速度为零，问之后静止还是反向滑动】","c":"想到【比较mgsin$\\theta$与最大静摩擦力：若下滑力$\\leq$最大静摩擦力则锁定静止，受静摩擦力平衡】；警惕【不能默认速度为零就反向下滑，也不能默认一定静止】","src":"物一轮058.结合牛顿第二定律分析图像_笔记","note":"视频|26:14","orig":"（知识）物体速度减为零时是否锁定，需判断是否满足静摩擦力条件（最大静摩擦力与下滑力比较，题目常假设最大静摩擦力等于滑动摩擦力）","link":""},{"id":"phy0373","t":"连接体·方法论总纲","s":"看到【多个物体连接（绳、杆、摩擦、挤压）的动力学问题】","c":"想到【第一反应是选研究对象：加速度相同可整体+隔离，加速度不同必须隔离】；警惕【研究对象选错会大幅增加运算量，先判断各部分加速度关系再动手】","src":"物一轮059.【课前必看】本讲听课建议_笔记","note":"视频|00:33","orig":"（知识）连接体指多个相互连接的物体，分析的关键是通过合理选择研究对象（整体或隔离）来简化问题、减小运算压力","link":""},{"id":"phy0374","t":"连接体·考情定位","s":"看到【复习时间紧张，需取舍连接体模块优先级】","c":"想到【优先精学a相同的连接体（整体法+隔离法），a不等的连接体了解思路即可】；警惕【实验题中常以环节形式出现，与牛二定律实验（如小车钩码）结合考查】","src":"物一轮059.【课前必看】本讲听课建议_笔记","note":"视频|02:34","orig":"（知识）加速度相等的连接体是中频考点，可出现在选择题或综合题/实验题（牛二定律实验）一环；加速度不等的连接体几乎不考，仅作保险性补充","link":""},{"id":"phy0375","t":"连接体·内力与外力","s":"看到【需判断某个力是内力还是外力，或整体法列方程不知画哪些力】","c":"想到【看施力物体是否在选定系统内：在内为内力（不画），在外为外力（必画）】；警惕【同一个力对不同系统性质不同：绳拉力对「两物体+绳」系统是内力，对单个物体是外力】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|03:16","orig":"（知识）内力：系统内部各部分间相互作用力，成对出现，整体受力分析中相互抵消，不画；外力：系统外物体施加的力，判断标准是施力物体是否在系统内","link":""},{"id":"phy0376","t":"连接体·力的作用点无传递性","s":"看到【外力F推/拉系统中的某一个物体，误以为F自动作用到整体或每部分】","c":"想到【明确每个力的实际作用对象，只有包含受力物体的系统列式时才计入F】；警惕【作用点没有传递性，隔离不含受力物体的部分时方程中不能出现F】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|08:40","orig":"（知识）力有明确作用点，只作用于直接受力的物体；力F作用在物体1上，只有包含物体1的系统才受F作用","link":""},{"id":"phy0377","t":"连接体·力的大小无传递性","s":"看到【力通过一串物体传递（推一摞物体），问物体间作用力大小】","c":"想到【力的大小必须用牛顿定律计算，不可臆测「平均分配」或原样传递；先用整体求a，再隔离目标侧子系统求内力】；警惕【物体间作用力一般小于外力F，其分布与质量和加速度有关】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|11:10","orig":"（例）光滑面上F推五个物体：整体a=F/(m₁+m₂+m₃+m₄+m₅)，物体间作用力需分段计算如F₁₂=F−(m₁+m₂+m₃+m₄)a，物体间作用力通常小于外力F","link":""},{"id":"phy0378","t":"连接体·a相同的特征与桥梁","s":"看到【两个（多个）物体一起加速、无相对滑动，加速度大小方向相同】","c":"想到【a是连接体问题的核心桥梁：整体法求a$\\to$隔离法求内力】；警惕【必须保证力与质量对应同一研究对象，且只分析外力不分析内力】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|15:18","orig":"（知识）无论研究整体还是某部分，加速度都是相同的a；可以a为桥梁，先研究一个对象求出a，再代入另一个对象作已知量","link":""},{"id":"phy0379","t":"连接体·整体法与隔离法选择","s":"看到【已知外力求加速度，或已知外力求内力（绳拉力/弹力）】","c":"想到【求外力优先整体法（受力简单），求内力必须隔离；「先整体求a、再隔离求T」是标准两步】；警惕【隔离体要选受力最简单且含目标力的对象】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|16:29","orig":"（知识）已知F求a优先整体法a=F/(M+m)；已知T求a用隔离a=T/m；已知F求T两步走：整体求a再代入T=ma得T=mF/(M+m)","link":""},{"id":"phy0380","t":"连接体·研究对象选择原则","s":"看到【连接体多物体多力，纠结选整体还是隔离哪个】","c":"想到【口诀：看已知力作用对象、选未知力少受力简单的系统；复杂问题可换不同研究对象组合验证】；警惕【切勿混淆研究对象对应的力和质量，加速度方向要统一】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|24:15","orig":"（知识）优先求加速度a；已知力作用在谁上就优先研究谁；选受力更简单的对象（整体通常更简单）；出现矛盾结果说明初始假设错误","link":""},{"id":"phy0381","t":"连接体·斜面体整体+隔离","s":"看到【斜面上的物块与斜面体相对静止一起加速，求推力F】","c":"想到【隔离物块：重力和支持力的合力指向加速度方向，F合=mgtan$\\theta$、a=gtan$\\theta$，再用整体F=(M+m)a】；警惕【斜面支持力与重力夹角等于斜面倾角$\\theta$，所有力的合成应指向加速度方向】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|26:36","orig":"（例）推力F作用于斜面体A上的物块B系统：对B，仅受重力和支持力，合力水平向右F合=mgtanθ，a=gtanθ；代入整体F=(M+m)a得F=(M+m)gtanθ","link":""},{"id":"phy0382","t":"连接体·绳拉力与摩擦无关","s":"看到【两物体材料相同（$\\mu$相同）、共同加速，问绳拉力与接触面粗糙程度的关系】","c":"想到【当各物体$\\mu$相同时，绳拉力T=m_{1}F/(m_{1}+m_{2})与$\\mu$无关，只由质量分配决定】；警惕【错误选项常含$\\mu$项；m_{2}增大时T减小】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|35:08","orig":"（例）两木块m₁、m₂由轻绳连接共同加速：光滑时T=m₁F/(m₁+m₂)；粗糙（μ相同）时整体a=F/(m₁+m₂)−μg，仍解得T=m₁F/(m₁+m₂)，与μ无关","link":""},{"id":"phy0383","t":"连接体·多物体选子系统","s":"看到【求中间某两个物体间的作用力（如第2对第3）】","c":"想到【把目标力「切开」：隔离包含目标力一侧受外力更少的子系统列方程】；警惕【滑动摩擦力f=$\\mu$N，水平面上N=mg才能直接$\\mu$mg；别把$\\mu$乘错质量】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|42:55","orig":"（例）五物体求第2、3物体间作用力F₂₃：选3、4、5子系统（受力最简单），整体a=2m/s²，F₂₃−3μmg=3ma，得F₂₃=12N","link":""},{"id":"phy0384","t":"连接体·弹簧剪断瞬时问题","s":"看到【剪断细线/绳的瞬间，系统中含弹簧】","c":"想到【弹簧弹力瞬间不突变（保持原值），绳/线拉力可突变；先整体求a再隔离求弹力】；警惕【剪断后若两物体仍接触则加速度相同，否则出现矛盾运动；求支持力N时勿漏掉ma项】","src":"物一轮060.分析a相同的连接体_笔记","note":"视频|49:01","orig":"（例）A（8kg）与B（2kg）由弹簧连接，剪断细线瞬间弹簧弹力保持80N不突变；整体(8+2)g−80=10a得a=2m/s²；隔离B：m_Bg−N=m_Ba得N=16N","link":""},{"id":"phy0385","t":"连接体·定滑轮绳约束模型","s":"看到【绳/定滑轮连接水平物块与竖直悬挂物，一水平动一竖直动】","c":"想到【两物体加速度大小相等方向不同，分别隔离列水平方向T=m_{2}a和竖直方向m_{1}g−T=m_{1}a，联立求解】；警惕【各段加速度方向与所设坐标轴正方向一致，注意正方向设定】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|00:34","orig":"（知识）光滑水平面上m₂经定滑轮连竖直悬挂的m₁：同一根绳位移相同→瞬时速度相同→加速度大小相同方向不同；T=m₂a，m₁g−T=m₁a，解得a=m₁g/(m₁+m₂)，T=m₁m₂g/(m₁+m₂)","link":""},{"id":"phy0386","t":"连接体·加速度方向不同不能用整体法","s":"看到【想把系统中不同方向的两个加速度矢量合成求「整体加速度」】","c":"想到【整体法只适用于各部分加速度相同的情形；方向不同时放弃整体法，逐个隔离列方程】；警惕【运动合成与分解只对同一物体成立，跨物体合成无物理意义】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|03:29","orig":"（知识）m₂向右的a与m₁向下的a不能矢量合成（运动合成具有同体性，不同物体的加速度不能直接合成）；各部分加速度方向不同时不存在统一的「整体加速度」，速度同理","link":""},{"id":"phy0387","t":"连接体·方向不同时的解法策略","s":"看到【绳连接的水平+竖直连接体求a和T】","c":"想到【隔离两个物体分别列牛二方程联立，是此类题唯一稳妥路径】；警惕【不要尝试整体法或花哨的等效技巧，考场上确保正确率】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|06:09","orig":"（知识）常规解法优先采用隔离法列方程，避免整体法带来的概念混淆；等效参考系等特殊方法考试中不建议使用","link":""},{"id":"phy0388","t":"连接体·挂重物驱动 vs 直接施力","s":"看到【对比「挂重物拖动」与「用等重的力直接拉」两种情形的加速度或绳拉力】","c":"想到【挂重物时重物自身也要被加速（被加速质量为m_{1}+m_{2}），直接施力只需加速m_{2}，故前者a和T都更小】；警惕【惯性思维：以为F=m_{1}g时拉力也等于m_{1}g，其实只有直接施力才成立】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|09:10","orig":"（例）左图m₁重物驱动系统：a=m₁g/(m₁+m₂)，T=m₁m₂g/(m₁+m₂)；右图直接施加F=m₁g：a'=m₁g/m₂，T'=m₁g；两者加速度与弹力均不相等","link":""},{"id":"phy0389","t":"连接体·弹力与重力不等大的本质","s":"看到【不平衡系统中问绳拉力是否等于悬挂物重力，或实验条件「小车质量远大于钩码质量」的由来】","c":"想到【非平衡时T$\\neq$m_{1}g，部分重力用于产生m_{1}的加速度；仅当m_{1}≪m_{2}时才近似T≈m_{1}g】；警惕【实验题中该条件不满足会造成系统误差，选择题可直接用此结论判断】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|11:39","orig":"（知识）m₁有向下加速度a说明m₁g>T；数学上T=m₁m₂g/(m₁+m₂)<m₁g恒成立；当m₁≪m₂时m₂/(m₁+m₂)≈1，T≈m₁g——这是牛二实验「小车质量远大于钩码质量」的理论依据","link":""},{"id":"phy0390","t":"连接体·轻绳定滑轮选项判断","s":"看到【定滑轮系统问绳拉力与悬挂物重力的关系、或滑轮受力】","c":"想到【有加速度的一方必有T<mg（竖直下落侧）或T>mg（竖直上升侧）；滑轮受力是两段绳拉力的矢量合成】；警惕【加速度方向不同则「a相同」指大小相同，矢量不等；别忽略滑轮处两力有夹角】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|14:20","orig":"（例）A（竖直，质量M）B（水平，质量m）经轻质定滑轮连接：T<Mg（否则A无加速度）；滑轮受两段绳拉力矢量合成F=2T<2Mg","link":""},{"id":"phy0391","t":"连接体·阿特伍德机模型","s":"看到【滑轮两侧多物体（一侧轻一侧重/多物叠加），求系统加速度或绳拉力】","c":"想到【把同侧共加速的物体捆绑成整体列式，另一侧单独列式，联立解a=mg/(2M+m)（两侧均M时）】；警惕【求物体间相互作用力（如C受的力）优先选受力最简单的单个物体分析】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|17:51","orig":"（例）A、B质量均为M，C质量m，绳连接：对BC整体(M+m)g−T=(M+m)a，对A单独T−Mg=Ma，解得a=mg/(2M+m)；对C分析F=mg−ma","link":""},{"id":"phy0392","t":"连接体·斜面+悬挂组合","s":"看到【斜面上物体经定滑轮连竖直悬挂物，含摩擦，求a和T】","c":"想到【分别隔离列竖直侧和斜面侧（沿斜面T−$\\mu$mgcos$\\theta$−mgsin$\\theta$=ma）方程，联立消T求a，再回代求T】；警惕【摩擦力方向与相对运动（趋势）方向相反，sin37$^{\\circ}$=0.6、cos37$^{\\circ}$=0.8代入勿错，联立时系数处理易错】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|24:25","orig":"（例）A（m，斜面θ=37°，μ=0.5）与B（2m竖直悬挂）绳连：2mg−T=2ma，T−μmgcosθ−mgsinθ=ma，解得a=g/3，回代T=4mg/3","link":""},{"id":"phy0393","t":"连接体·方法总结","s":"看到【绳杆连接的多体系统，不知先分析谁】","c":"想到【口诀：先定加速再选物，已知未知看清楚，受力简单优先算，联立方程破迷雾】；警惕【明确各加速度方向（相同/不同）决定能否用整体法；力无作用点与大小传递性】","src":"物一轮061.分析a相等，方向不同的连接体_笔记","note":"视频|31:17","orig":"（知识）先建立系统运动关系联立牛二方程；研究对象：已知力作用对象优先，未知力作用对象次之，选受力最简单的物体；m₁≪m₂时可近似T≈m₁g","link":""},{"id":"phy0394","t":"连接体·加速度不等的模型特征","s":"看到【连接体内部有相对滑动/相对运动，各部分加速度不同】","c":"想到【放弃整体法，改用隔离法逐个分析物体受力】；警惕【系统整体不平衡（各部分a不全为零且不同）时，整体法F=(M+m)a失效】","src":"物一轮062.应用隔离法分析加速度不等的连接体_笔记","note":"视频|00:53","orig":"（知识）系统内各部分加速度大小不相等、方向也可能不同，典型场景是内部存在相对运动（如演员沿竹竿加速下滑）；不能直接使用整体法分析","link":""},{"id":"phy0395","t":"连接体·隔离法标准步骤","s":"看到【需分析a不等连接体中各物体的受力与运动】","c":"想到【四步流程：定各物体a$\\to$逐个画受力图$\\to$列F=ma$\\to$用牛三（f与f'等大反向）联立】；警惕【相互作用力方向易画反，联立时正方向要一致】","src":"物一轮062.应用隔离法分析加速度不等的连接体_笔记","note":"视频|01:12","orig":"（知识）明确各物体加速度大小和方向→对每个物体单独受力分析→由F=ma建方程→通过作用力-反作用力关系联立；关键：摩擦力方向判断准确，相互作用力成对分析","link":""},{"id":"phy0396","t":"连接体·杂技顶竿模型","s":"看到【一个物体沿杆/绳加速下滑（或上升），另一部分静止，求地面支持力/压力】","c":"想到【先隔离加速下滑者求摩擦力f=m(g−a)，再把静止部分视为整体列平衡方程，计入反作用摩擦力f'】；警惕【压力不等于总重力(M+2m)g——非平衡部分的动力学影响使支持力减小；下滑时f'向下压在竿上】","src":"物一轮062.应用隔离法分析加速度不等的连接体_笔记","note":"视频|01:30","orig":"（例）演员乙（m）沿竿加速下滑：mg−f=ma得f=m(g−a)；竹竿（M）+演员甲（m）整体平衡：N=(M+m)g+f'=(M+2m)g−ma，地面压力F=(M+2m)g−ma","link":""},{"id":"phy0397","t":"连接体·混合系统策略","s":"看到【系统中一部分加速、一部分静止（或加速度不同），混合动力学问题】","c":"想到【拆分原则：加速部分隔离、平衡部分捆绑成整体，两侧用相互作用力衔接】；警惕【选哪个物体做「系统」会改变内力外力属性，需按目标量灵活切换】","src":"物一轮062.应用隔离法分析加速度不等的连接体_笔记","note":"视频|05:10","orig":"（知识）优先隔离有加速度的物体列动力学方程，平衡部分（a=0）可视为整体列平衡方程；注意内力与外力的转换（如摩擦力对子系统是外力）","link":""},{"id":"phy0398","t":"连接体·系统牛顿第二定律","s":"看到【系统各部分加速度不同，但只求系统受到的外力（如地面支持力、摩擦力），不需要内部相互作用力】","c":"想到【跳过隔离内部受力，直接用系统牛二律：合外力=Σmaᵢ（矢量），注意各项方向由aᵢ方向决定】；警惕【必须按矢量处理：先定各a方向再合成，超纲但低频考点，理解即可】","src":"物一轮063.应用系统牛二律分析加速度不等的连接体_笔记","note":"视频|00:46","orig":"（知识）核心公式F合外=m₁a₁+m₂a₂+…+mₙaₙ（矢量式）：系统合外力等于各部分质量与加速度乘积的矢量和；适用于各部分加速度不同且求系统外力的情形","link":""},{"id":"phy0399","t":"连接体·斜面上物体下滑求地面力","s":"看到【斜面静止在地面、其上物体加速下滑，求地面对斜面的摩擦力和支持力】","c":"想到【系统合外力=小m的ma（方向沿a方向），将其分解：水平分量$\\to$地面对斜面有静摩擦力（方向与a的水平分量同向），竖直分量$\\to$N<(M+m)g】；警惕【易错认为N=总重力——物体有向下加速度分量时N必然小于总重力】","src":"物一轮063.应用系统牛二律分析加速度不等的连接体_笔记","note":"视频|01:22","orig":"（例）斜面（M）静止、物体（m）沿斜面加速下滑：F合外=ma_m（因a_M=0）；水平分量需向左的静摩擦力提供，竖直分量使支持力N<(M+m)g","link":""},{"id":"phy0400","t":"连接体·系统牛二律解题步骤","s":"看到【用系统牛二律分析「动+静」混合系统的外部约束力】","c":"想到【三步：定F合方向$\\to$正交分解$\\to$由分量反推各外部约束力大小与方向】；警惕【矢量合成时方向的影响，内力（物体与斜面间作用力）在系统法中自动消去，无需展开】","src":"物一轮063.应用系统牛二律分析加速度不等的连接体_笔记","note":"视频|01:22","orig":"（知识）①确定系统合外力方向（与内部加速度不为零部分的a同向）②分解合外力（水平+竖直分量）③反推地面摩擦力（向左）和支持力（小于总重力）","link":""},{"id":"phy0401","t":"变力问题·模块与考情总览","s":"看到【复习变力（弹簧/空气阻力/F随t变化）专题，需安排优先级】","c":"想到【优先精学弹簧模型（中高频、24年安徽/广东/23浙江卷均考），空阻模型掌握通用分析逻辑即可】；警惕【弹簧模型分析过程较复杂，需专门训练动态过程分段】","src":"物一轮064.【课前必看】本讲听课建议_笔记","note":"视频|00:46","orig":"（知识）本讲三模块：常见变力影响因素与简单过程分析（1星）、弹簧模型分析（4星）、空阻模型分析（4星）；弹簧模型是中高频考点，空阻模型中低频但方法通用","link":""},{"id":"phy0402","t":"变力问题·F随t变化","s":"看到【力F随时间变化，问质点各时刻的运动状态】","c":"想到【每一时刻由F=ma瞬时对应加速度，力变则a立即变，分段分析运动】；警惕【不要用平均力代替瞬时力做整段计算】","src":"物一轮064.【课前必看】本讲听课建议_笔记","note":"视频|02:06","orig":"（知识）力随时间变化的质点运动分析：中低频考点、难度较低但必须掌握（24年甲卷选择题、24年广东解答题）；核心是动态受力与加速度的瞬时关系","link":""},{"id":"phy0403","t":"变力问题·弹簧与空阻模型的方法定位","s":"看到【弹力或空气阻力作为变力参与运动过程分析】","c":"想到【抓住变力与形变（弹簧）或速度（空阻）的依赖关系，逐阶段判断合力与加速度变化趋势】；警惕【空阻方向随速度方向反转，弹簧弹力在压缩/拉伸转换时过零点，均为运动转折点】","src":"物一轮064.【课前必看】本讲听课建议_笔记","note":"视频|02:06","orig":"（知识）弹簧弹力是随形变变化的变力，需分析弹力动态变化与运动状态的关系；空气阻力是与速度相关的变力，分析方法具有通用性","link":""},{"id":"phy0404","t":"变力分析·常见变力类型识别","s":"看到【系统含弹簧或弹性绳，需判断弹力是否恒定】","c":"想到【弹簧弹力 F=kx 是随形变量变化的变力，分析时先追踪 x 的变化】；警惕【默认弹力恒定不变】","src":"物一轮065.认识常见的变力影响因素_笔记","note":"视频|00:05-01:04","orig":"（知识）弹簧弹力符合胡克定律 F=kx，力的大小随形变量 x 变化；含弹簧或弹性绳的系统需注意弹力可能是变力","link":""},{"id":"phy0405","t":"变力分析·滑动摩擦力变力判断","s":"看到【物体在圆弧面/斜面等支持力变化的轨道上滑动】","c":"想到【先判断支持力 N 是否变化：N 变则 $\\mu$N 为变力，N 不变则滑动摩擦力为恒力】；警惕【见摩擦力就当恒力处理】","src":"物一轮065.认识常见的变力影响因素_笔记","note":"视频|01:04-04:32","orig":"（知识）滑动摩擦力 Ff=μN，当支持力 N 变化时（如物体沿圆弧轨道下滑）摩擦力成为变力","link":""},{"id":"phy0406","t":"变力分析·空气阻力模型","s":"看到【题目给出 F=kv 或 F=kv^{2} 型空气阻力】","c":"想到【阻力大小与速度相关、方向始终与速度相反，按 f(v) 型变力闭环分析】；警惕【自选阻力表达式，应以题目给定的关系式为准】","src":"物一轮065.认识常见的变力影响因素_笔记","note":"视频|01:04-04:32","orig":"（知识）空气阻力高中常见简化模型 F=kv 或 F=kv²，具体表达式由题目给定，阻力始终与速度相关","link":""},{"id":"phy0407","t":"变力分析·随时间变化的力","s":"看到【力随时间变化，给出 F=kt 型表达式或 F-t 图像】","c":"想到【结合牛顿第二定律分段求加速度，再按运动学方程分析，是最简单的变力类型】；警惕【忽略力的突变时间点即分段点】","src":"物一轮065.认识常见的变力影响因素_笔记","note":"视频|01:04-04:32","orig":"（知识）随时间变化的力可能直接给出表达式（如 F=kt）或 F-t 图像，显式依赖时间变量","link":""},{"id":"phy0408","t":"变力分析·电磁学中的变力","s":"看到【库仑力/安培力参与作用且间距或速度在变化】","c":"想到【库仑力随位置 r 变、安培力随速度 v 变，力学变力的分析方法可完全复用到电场磁场场景】；警惕【混淆变力随位置、速度还是时间变化】","src":"物一轮065.认识常见的变力影响因素_笔记","note":"视频|04:32-","orig":"（知识）库仑力 F=kq₁q₂/r²，电荷间距 r 变化时力随之改变，分析方法与弹簧弹力类似，均属空间参量相关变力","link":""},{"id":"phy0409","t":"变力分析·通用分析逻辑","s":"看到【含任意变力的动力学过程分析题】","c":"想到【先识别力的影响因素（位置/速度/时间），再沿「变量变化$\\to$力变化$\\to$合力$\\to$加速度$\\to$速度」链条分析】；警惕【不分类直接套匀变速公式】","src":"物一轮065.认识常见的变力影响因素_笔记","note":"视频|04:32-","orig":"（知识）变力种类虽多但分析方法通用：区分力是随位置、速度还是时间变化，再追踪该变量→力→合力→加速度→运动","link":""},{"id":"phy0410","t":"F-t图像·图像信息读取","s":"看到【F-t 图像中力出现负值】","c":"想到【负号只代表方向与正方向相反，不代表力减小】；警惕【把负值当作力的大小变小处理】","src":"物一轮066.分析F随t变化时质点的运动特点_笔记","note":"视频|00:00-00:35","orig":"（知识）F-t 图像横轴为时间 t、纵轴为力 F，负值表示力方向与选定正方向相反（如 -6N 表示向左的力）","link":""},{"id":"phy0411","t":"F-t图像·分段分析通法","s":"看到【F-t 图像中力在某时刻发生突变】","c":"想到【以突变时刻为分段点，每段用 a=F/m 求加速度、按初速度定运动，可画 v-t 图辅助（斜率对应加速度）】；警惕【跨段混用同一加速度】","src":"物一轮066.分析F随t变化时质点的运动特点_笔记","note":"视频|00:35-01:23","orig":"（知识）根据力的变化情况分段，F-t 图像中力发生突变的时间点即为分段点；每段用 F=ma 求 a，再结合初速度确定运动情况","link":""},{"id":"phy0412","t":"F-t图像·交替力作用运动判断","s":"看到【力方向周期性反向，物体从静止开始受力】","c":"想到【加速度方向变化不代表速度方向立即改变，速度减到零前方向保持不变】；警惕【误认为加速度反向则速度立即反向】","src":"物一轮066.分析F随t变化时质点的运动特点_笔记","note":"视频|01:23-04:54","orig":"（例）v₀=0 的物体 0-1s 受 F=-6N、1-2s 受 F=6N，全程速度方向不变，先向左加速后向左减速；v-t 图两段斜率一负一正且对称","link":""},{"id":"phy0413","t":"F-t图像·分段求加速度与位移","s":"看到【物体分阶段受不同大小的力做直线运动，求速度/位移】","c":"想到【分段算加速度$\\to$画 v-t 图$\\to$用图像面积求位移、顶点求最大速度；加速度向下为失重、向上为超重】；警惕【忘记分段间速度连续衔接】","src":"物一轮066.分析F随t变化时质点的运动特点_笔记","note":"视频|04:54-11:38","orig":"（例）救生缓降器：人重 600N，0-3s 拉力 360N（a₁=4m/s² 向下失重），3-5s 拉力 960N（a₂=-6m/s² 向上超重）；v-t 图面积得 h=30m，最大速度 12m/s","link":""},{"id":"phy0414","t":"摩擦力动态·N随时间变化","s":"看到【外力随时间增大压紧接触面，问摩擦力随时间的变化图像】","c":"想到【滑动阶段 f=$\\mu$N 线性增大，物体停后转静摩擦、f 与外力平衡（此处等于 $\\mu$G 不再增大），图像为「斜线+平台」】；警惕【混淆滑动摩擦与静摩擦的计算方法，误认为静摩擦继续随外力增大】","src":"物一轮066.分析F随t变化时质点的运动特点_笔记","note":"视频|11:38-","orig":"（例）物块匀速运动（F=μG），施加 Fn=kt 后滑动摩擦阶段 f=μ(G+kt) 线性增大；速度减为零后转静摩擦，f=F=μG 保持水平线不变","link":""},{"id":"phy0415","t":"摩擦力动态·静摩擦力取值","s":"看到【物体由滑动转为静止，问最终静摩擦力大小】","c":"想到【静摩擦力按二力平衡由外力反求，不套 $\\mu$N 公式】；警惕【用 $\\mu$N 计算静摩擦力】","src":"物一轮066.分析F随t变化时质点的运动特点_笔记","note":"视频|11:38-","orig":"（知识）静摩擦力大小由外力决定（与外力平衡），与滑动摩擦力无必然关联；停止瞬间静摩擦力等于初始滑动摩擦力 μG","link":""},{"id":"phy0416","t":"F-t图像·图像斜率物理意义","s":"看到【要求由 F-t 图推断 v-t 图形状】","c":"想到【逐段把 F 换成 a，v-t 斜率即 a，注意两段曲线的凹凸与对称关系】；警惕【忽略速度方向与加速度方向独立判断】","src":"物一轮066.分析F随t变化时质点的运动特点_笔记","note":"视频|00:35-01:23","orig":"（知识）F-t 图像分段对应受力变化；v-t 图像斜率对应加速度，斜率正负与大小反映加速度的方向与变化","link":""},{"id":"phy0417","t":"弹簧模型·水平弹簧变加速分析","s":"看到【光滑水平面上物块压缩/拉伸弹簧后运动】","c":"想到【追踪形变量 x$\\to$弹力 F=kx$\\to$加速度 a$\\to$结合 a 与 v 同向/反向判断加减速；压缩阶段是加速度增大的减速，不是匀减速】；警惕【认为速度减小时加速度也减小】","src":"物一轮067.弹簧基本模型分析_笔记","note":"视频|00:33-07:48","orig":"（例）光滑地面、弹簧原长，物块获初速度 v₀ 后向右压缩弹簧：x 增大→F=kx 增大→a 增大且与 v 反向，做加速度增大的减速运动至 v=0；返回时做加速度减小的加速运动","link":""},{"id":"phy0418","t":"弹簧模型·竖直弹簧下落分析","s":"看到【物块由静止落到竖直弹簧上并压缩】","c":"想到【以 F=mg 的平衡位置为界分三段：加速度减小加速$\\to$速度最大$\\to$加速度增大减速】；警惕【认为刚接触弹簧时速度最大】","src":"物一轮067.弹簧基本模型分析_笔记","note":"视频|07:48-17:00","orig":"（例）弹簧原长竖直放置，物块由静止释放：F<mg 阶段做加速度减小的加速；F=mg（平衡位置）速度最大；F>mg 阶段做加速度增大的减速到最低点","link":""},{"id":"phy0419","t":"弹簧模型·速度极值点结论","s":"看到【问物体何时速度最大/最小，或求最大速度对应位置】","c":"想到【速度极值点即受力平衡点，直接列 F合=0 求形变量或速度】；警惕【把速度最大点当作刚接触弹簧或最低点】","src":"物一轮067.弹簧基本模型分析_笔记","note":"视频|17:00-21:51","orig":"（知识）变加速过程中速度极值点必有 a=0、F合=0，可列平衡方程；竖直模型中该点弹簧弹力等于重力（mg=kΔx）","link":""},{"id":"phy0420","t":"弹簧模型·最低点后往复运动","s":"看到【弹簧振动物体从最低点反弹回程】","c":"想到【回程与下落对称：加速度减小加速$\\to$平衡位置速度最大$\\to$加速度增大减速】；警惕【忽略平衡位置前后加速度方向相反】","src":"物一轮067.弹簧基本模型分析_笔记","note":"视频|17:00-21:51","orig":"（知识）物块到最低点后上升：先做加速度减小的加速，过平衡位置后做加速度增大的减速；v-t 图呈对称「双峰」形态，两个极值点均对应 F=mg 的平衡位置","link":""},{"id":"phy0421","t":"弹簧模型·接触弹簧全过程分段","s":"看到【物体自由下落后压缩竖直弹簧，问全过程的运动/超重失重】","c":"想到【分三段：自由落体$\\to$加速度减小加速$\\to$加速度增大减速；减速段 a 向上为超重，并非全程失重】；警惕【认为刚接触弹簧瞬间弹力就等于重力】","src":"物一轮067.弹簧基本模型分析_笔记","note":"视频|23:46-27:13","orig":"（例）物块自由下落接触弹簧：接触前匀加速；接触后到平衡位置做加速度减小的加速；过平衡位置后做加速度增大的减速。速度最大时合力为零（mg=kΔx），减速阶段处于超重","link":""},{"id":"phy0422","t":"弹簧模型·v-Δx图像信息提取","s":"看到【给出 v-$\\Delta$x（速度-形变量）图像问劲度系数或状态】","c":"想到【图像最高点即平衡位置，用 k=mg/$\\Delta$x 求 k；任意形变量处比较 k$\\Delta$x 与 mg 判断超失重】；警惕【把横轴交点当作平衡位置】","src":"物一轮067.弹簧基本模型分析_笔记","note":"视频|27:13-","orig":"（例）v-Δx 图中最高点 A 为速度最大点（对应 Δx=0.10m），由 mg=kΔx 求 k=mg/Δx；曲线与横轴交点为最大压缩量位置","link":""},{"id":"phy0423","t":"弹簧模型·v-t图像特征对应","s":"看到【给出弹簧运动的 v-t 曲线要求对应运动阶段】","c":"想到【由斜率变化读出加速度增减，斜率为零处即平衡位置（速度极值）】；警惕【混淆斜率正负与速度正负的含义】","src":"物一轮067.弹簧基本模型分析_笔记","note":"视频|21:51-23:46","orig":"（知识）v-t 曲线斜率反映加速度变化，拐点对应受力平衡位置；弹簧模型运动阶段依次为加速度减小加速→加速度增大减速→反向加速→反向减速","link":""},{"id":"phy0424","t":"弹簧变式·大小方向同时变化的弹力","s":"看到【弹簧一端固定、另一端沿杆/曲面运动，弹力大小方向同时变】","c":"想到【仍沿「形变量$\\to$弹力$\\to$加速度$\\to$速度」链条分析，方向沿弹簧轴线；复杂处先定几何关系找形变量】；警惕【把二维变力问题当一维恒方向弹力处理】","src":"物一轮068.弹簧变式分析_笔记","note":"视频|00:00-01:40","orig":"（例）小球 P 沿竖直杆上下运动，弹簧一端固定于 O 点，弹簧长度和方向均改变，属于二维平面内的变力问题","link":""},{"id":"phy0425","t":"弹簧变式·由初末状态反推过程","s":"看到【初速度为零、末速度也为零的变力运动过程推断】","c":"想到【先由 v_{0}=0$\\to$vₜ=0 断定必有加速段和减速段，再定位速度极值点（合力为零处）定性分析】；警惕【试图对全过程做定量计算而陷入死角】","src":"物一轮068.弹簧变式分析_笔记","note":"视频|01:40-01:55","orig":"（知识）v₀=0 且 vₜ=0 的运动必然包含至少一次加速和一次减速；复杂运动可能含多次速度极值点，高中阶段可定性判断关键状态","link":""},{"id":"phy0426","t":"弹簧变式·速度最大点隐含条件","s":"看到【题目给出某点速度最大，且弹簧长度在该段不变】","c":"想到【速度最大$\\to$合力为零，列瞬时平衡方程；弹簧长度不变段弹力不做功、弹性势能不变，用动能定理只算重力做功】；警惕【忘记利用几何关系确定形变量与角度】","src":"物一轮068.弹簧变式分析_笔记","note":"视频|05:44-14:25","orig":"（例）小球运动到 N 点速度最大→N 点合力为零；由几何关系（OP=原长 l，ON=2l）得弹簧与竖直方向夹角 30°，k=F/Δx 可求；M 到 N 弹簧长度不变弹性势能不变，动能定理 mgh=½mv² 求速度","link":""},{"id":"phy0427","t":"弹簧变式·平衡态撤力瞬时分析","s":"看到【平衡状态突然撤去某个力，问撤力瞬间及之后的运动】","c":"想到【撤力瞬间弹力不突变，剩余力的合力与被撤的力等大反向；判断 a 与 v 同向则持续加速】；警惕【认为弹力随撤力同步消失，或最大加速度出现在速度最大处】","src":"物一轮068.弹簧变式分析_笔记","note":"视频|14:25-","orig":"（例）P 点平衡时拉力 F=2mg；撤去拉力瞬间合力立即变为 2mg 向下，a_max=2g；此后弹簧形变量减小、弹力减小，加速度方向始终向下与速度同向，速度一直增大","link":""},{"id":"phy0428","t":"弹簧变式·对称双弹簧简化","s":"看到【两根对称弹簧共同拉/压同一物体】","c":"想到【利用对称性只算一根弹簧的竖直分量再乘 2；求速度优先动能定理/能量守恒】；警惕【逐根弹簧重复计算浪费时间或漏掉角度变化】","src":"物一轮068.弹簧变式分析_笔记","note":"视频|14:25-","orig":"（知识）对称双弹簧问题只需分析一个方向的弹力分量（F合=mg+2Fcosθ 型）；变加速过程优先考虑能量法求速度","link":""},{"id":"phy0429","t":"弹簧变式·弹簧模型基本特性","s":"看到【只受重力和弹簧弹力的竖直弹簧系统】","c":"想到【识别简谐振动特征，能量在动能与弹性势能间守恒转化】；警惕【把弹簧现长当原长计算形变量 x】","src":"物一轮068.弹簧变式分析_笔记","note":"视频|01:40-01:55","orig":"（知识）弹力大小与形变量成正比、方向指向平衡位置；无其他外力时系统做简谐振动，动能与弹性势能相互转化、总机械能守恒；注意区分弹簧实际长度与原长","link":""},{"id":"phy0430","t":"空阻模型·f(v)型变力分析流程","s":"看到【物体受与速度相关的空气阻力，分析运动过程】","c":"想到【按「速度$\\to$阻力$\\to$合力$\\to$加速度$\\to$速度」闭环链逐环节分析，与弹簧模型同构（弹簧追形变量、空阻追速度）】；警惕【忽略阻力方向始终与速度相反】","src":"物一轮069.空阻基本模型分析_笔记","note":"视频|00:30-07:06","orig":"（知识）空气阻力 F=kv 或 F=kv²（题目给定），方向始终与速度相反；分析流程：v 变化→f 变化→合力变化→a 变化→反推 v 变化，闭环分析","link":""},{"id":"phy0431","t":"空阻模型·静止释放收尾速度","s":"看到【物体由静止释放，受 kv 或 kv^{2} 型阻力下落】","c":"想到【先加速度减小加速，最终合力为零达到最大速度（收尾速度）匀速；由 mg=f(vm) 解出 vm】；警惕【认为最终匀速是瞬间达到的平衡】","src":"物一轮069.空阻基本模型分析_笔记","note":"视频|00:30-07:06","orig":"（例）小球静止释放受 F=kv² 阻力：初态 v=0 时 f=0、a=g；随 v 增大阻力增大、a=（mg-kv²）/m 减小，做加速度减小的加速运动；当 kv²m=mg 时达匀速 vm","link":""},{"id":"phy0432","t":"空阻模型·v-t图像绘制","s":"看到【要求画/选空阻下落运动的 v-t 图像】","c":"想到【斜率对应加速度：从 a=g 开始递减至 0，曲线向上凸并渐近趋于 vm】；警惕【画成匀加速直线或让速度超过收尾速度】","src":"物一轮069.空阻基本模型分析_笔记","note":"视频|00:30-07:06","orig":"（知识）加速度减小的加速运动：v-t 图斜率（=a）绝对值逐渐减小，曲线趋于水平线（vm），初态斜率为 g","link":""},{"id":"phy0433","t":"空阻模型·开伞减速过程","s":"看到【下落中打开降落伞/阻力突然增大的减速过程】","c":"想到【开伞瞬间速度不突变，合力向上$\\to$加速度减小的减速$\\to$最终匀速；加速度向上为超重】；警惕【认为速度或加速度会瞬间突变反向】","src":"物一轮069.空阻基本模型分析_笔记","note":"视频|07:06-11:20","orig":"（例）跳伞员开伞瞬间仍有向下速度，f>mg 合力向上，随 v 减小 f 减小、a 减小，做加速度减小的减速运动，v-t 图为向下凸的递减曲线渐近趋于匀速；a 向上对应超重","link":""},{"id":"phy0434","t":"空阻模型·竖直上抛含阻力分段","s":"看到【竖直上抛且空气阻力不可忽略，选择 v-t 图像】","c":"想到【分上升/下降两段分别列 a 与 v 的关系：上升段 a=（mg+kv）/m 减小，下降段 a=（mg-kv）/m 减小；上升时间短、返回同一高度速度更小】；警惕【混淆 f∝v 与 f∝v^{2} 对曲线形状的影响，或让下降段末速度突变】","src":"物一轮069.空阻基本模型分析_笔记","note":"视频|11:20-","orig":"（例）排球运动：上升段受 mg+kv，a=（mg+kv）/m 随 v 减小而减小；下降段从 v=0、f=0 起先大后小；正确图像为上升减速曲线下凹、下降加速曲线上凸，末速度无突变","link":""},{"id":"phy0435","t":"空阻变式·阻力为恒力","s":"看到【题目直接说空气阻力为恒力（如重力的若干倍）】","c":"想到【此时阻力与速度无关，直接按匀变速直线运动公式 v^{2}=2ah 分段处理】；警惕【默认空气阻力必与速度相关而套变力模型】","src":"物一轮070.空阻变式分析_笔记","note":"视频|00:07-05:30","orig":"（例）空气阻力为重力的 λ 倍（恒力）：下落 a₁=(1-λ)g，上升 a₂=(1+λ)g，由 v²=2ah 得 v₂/v₁=√[(1+λ)h/((1-λ)H)]","link":""},{"id":"phy0436","t":"空阻变式·阻力含迎风面积多因素","s":"看到【阻力公式含面积 S 等多因素，配合 v^{2}-a 图像求解】","c":"想到【先由牛顿第二定律整理出 v^{2} 与 a 的函数式，再用斜率、截距对应物理量求解；加速度方向决定函数式符号】；警惕【忽略 a 方向变化使表达式斜率符号改变】","src":"物一轮070.空阻变式分析_笔记","note":"视频|05:40-15:30","orig":"（例）F=½CρSv² 含迎风面积 S 与速度 v 双变量；开伞前后 a 方向不同导致 v²-a 关系式斜率一负一正，利用图像交点/截距反求 S₁、S₂","link":""},{"id":"phy0437","t":"空阻变式·多变量消元求终态速度","s":"看到【阻力与半径、速度都相关，问末速度与半径的关系】","c":"想到【终态用合力为零列式，多变量问题把其他变量（如 m 用 r 表示）代入消元】；警惕【忽略质量随 r^{3} 变化，误判 v_{0} 与 r 的比例关系】","src":"物一轮070.空阻变式分析_笔记","note":"视频|15:30-22:34","orig":"（例）雨滴受 f=kr²v²，终态 mg=kr²v₀²；代入 m=(4/3)πr³ρ 消去 m，得 v₀²=4πρgr/(3k)，即 v₀²∝r 而非 v₀∝1/r","link":""},{"id":"phy0438","t":"变力模型·三类变力分类","s":"看到【任意含变力的动力学综合题】","c":"想到【先分类（力随 t/x/v 变化），再建立对应函数关系式，最后代入边界条件；口诀「先分类，再建式，边界条件最后代」】；警惕【未审清阻力性质直接套模型】","src":"物一轮070.空阻变式分析_笔记","note":"视频|22:34-","orig":"（知识）变力三类基本模型：f(t) 随时间变化、f(x) 随位移变化、f(v) 随速度变化；绝大多数变力场景可分解为这三类，区分关键是识别力随哪个变量变化","link":""},{"id":"phy0439","t":"空阻变式·通用解题步骤","s":"看到【含空气阻力的图像或比例关系问题】","c":"想到【按「定阻力性质$\\to$列牛顿第二定律$\\to$图像与函数式对应$\\to$消元」四步走】；警惕【跳过第一步直接套 f=kv^{2} 模型】","src":"物一轮070.空阻变式分析_笔记","note":"视频|22:34-","orig":"（知识）空阻类问题通用方法：①明确阻力影响因素（恒力/速度/其他）；②列牛顿第二定律方程；③图像题结合函数表达式（斜率/截距）；④多变量问题消元","link":""},{"id":"phy0440","t":"临界问题·临界条件概念","s":"看到【题目出现「恰好」「刚好」类临界描述】","c":"想到【先给临界态下物理判据（如恰好相遇$\\to$速度相等），把文字条件转化为等式】；警惕【直接用位置相等当相遇条件而不讨论速度】","src":"物一轮071.【课前必看】本讲听课建议_笔记","note":"视频|00:00-01:09","orig":"（知识）动力学临界条件：物体从一种状态变为另一种状态的转折点，如追及问题中两车「恰好相遇」的临界状态是速度相等","link":""},{"id":"phy0441","t":"临界问题·两大类型与考查地位","s":"看到【板块模型或连接体问题中出现临界环节】","c":"想到【摩擦临界是板块模型的核心环节、优先掌握；弹力临界考频较低可后续补充】；警惕【复习时平均用力，忽略摩擦临界的高考地位】","src":"物一轮071.【课前必看】本讲听课建议_笔记","note":"视频|03:14-04:16","orig":"（知识）动力学临界问题分摩擦临界（中频考点，选择题单独命题或作为板块模型分析环节）与弹力临界（中低频考点，过程复杂）两大类","link":""},{"id":"phy0442","t":"临界问题·学习模块分层","s":"看到【需要系统复习动力学临界问题时规划路径】","c":"想到【先掌握常见临界条件的归纳（弹力/摩擦），再进阶到外力临界值与 a-F 规律】；警惕【跳过基础临界条件直接做高阶难题】","src":"物一轮071.【课前必看】本讲听课建议_笔记","note":"视频|01:09-03:14","orig":"（知识）临界问题学习分三层：基础层归纳常见弹力和摩擦临界条件；进阶层讨论外力临界值、a-F 变化规律；高阶层分析恒力/恒定加速度下的弹力临界","link":""},{"id":"phy0443","t":"弹力临界·绳子刚好无弹力","s":"看到【题目描述绳子刚好伸直/绳弹力恰好为零】","c":"想到【临界态该绳不受力，受力分析中直接去掉该绳，只保留其余力和重力】；警惕【仍给临界绳计入弹力，或忽略「伸直」的几何约束】","src":"物一轮072.归纳常见的弹力临界条件_笔记","note":"视频|00:31-03:42","orig":"（知识）绳三种状态：伸直绷紧（有弹力）、伸直未绷紧（临界，无形变 F_N=0）、松弛（无弹力）；「绳子刚好伸直」「绳弹力刚好为零」均指临界态","link":""},{"id":"phy0444","t":"弹力临界·绳临界态求加速度","s":"看到【某绳弹力恰好为零，求系统加速度】","c":"想到【去掉零弹力绳后按剩余力做矢量分解，合力方向沿加速度方向，用三角函数列 mg 与拉力的关系】；警惕【弄错加速度方向或角度对应的边比（37$^{\\circ}$/53$^{\\circ}$ 对应 3:4:5）】","src":"物一轮072.归纳常见的弹力临界条件_笔记","note":"视频|03:42-08:53","orig":"（例）绳弹力恰好为零时，物体仅受另一绳拉力与重力，合力方向水平，由 tan53°=F合/mg 列牛顿第二定律得 a₁=(4/3)g；同理另一状态 a₂=g·tan37°=(3/4)g","link":""},{"id":"phy0445","t":"弹力临界·接触面恰好分离","s":"看到【两物体恰好分离/恰好不分离】","c":"想到【临界条件三件套：F_N=0、v 相同、a 相同，缺一不可】；警惕【误判为分离时速度不同，或只写弹力为零漏掉加速度相等条件】","src":"物一轮072.归纳常见的弹力临界条件_笔记","note":"视频|08:53-11:25","orig":"（知识）接触面临界态：接触无挤压，F_N=0 且两物体速度相同（v_A=v_B）、加速度相同（a_A=a_B）；「恰好分离」「恰好不分离」本质都是接触面弹力为零","link":""},{"id":"phy0446","t":"弹力临界·连接体分离时刻计算","s":"看到【变力（随 t 变化）推动两物体，求分离时刻】","c":"想到【分离瞬间两物体加速度仍相同且弹力为零，对两物体分别列牛顿第二定律联立求解】；警惕【遗漏 a_A=a_B 的隐含条件，或忽略力随时间减小的正负号处理】","src":"物一轮072.归纳常见的弹力临界条件_笔记","note":"视频|11:25-","orig":"（例）变力作用下 A、B 并排运动：整体法求 a，隔离法求内力 F；分离时刻 F_N=0 且 a_A=a_B，分别列 F_A=m_Aa（F_A=8-2t）、F_B=m_Ba（F_B=2+2t），联立解得 t=2s","link":""},{"id":"phy0447","t":"弹力临界·恰好拉断与恰好伸直区分","s":"看到【题目出现恰好拉断/恰好不断/绳最大承受力】","c":"想到【拉断类临界取弹力等于极限值列方程，与「弹力为零」型临界区分开】；警惕【把恰好拉断也当成弹力为零处理】","src":"物一轮072.归纳常见的弹力临界条件_笔记","note":"视频|00:31-03:42","orig":"（知识）「恰好伸直」对应弹力为零；「刚好拉断/未拉断」对应弹力达到极限值（如 10N），两者是不同方向的临界，需区分趋近方向","link":""},{"id":"phy0448","t":"弹力临界·通用解题步骤","s":"看到【含「恰好/刚好」的弹力临界综合题】","c":"想到【先翻译临界条件为受力简化依据，再列矢量方程；合力方向必沿加速度方向】；警惕【加速度方向判断错误（需结合运动方向）】","src":"物一轮072.归纳常见的弹力临界条件_笔记","note":"视频|03:42-08:53","orig":"（知识）弹力临界问题通法：①识别临界描述（恰好为零/恰好分离）；②按临界条件简化受力分析；③利用牛顿第二定律列式，合力方向与加速度一致","link":""},{"id":"phy0449","t":"相互作用·动静摩擦临界","s":"看到【”恰好保持相对静止””恰好不滑动””刚好推动”描述】","c":"想到【临界态仍相对静止，静摩擦力已达最大值 fmax=$\\mu$N，据此列平衡或动力学方程】；警惕【临界态摩擦力已最大但物体尚未滑动，外力再增大才发生滑动】","src":"物一轮073.归纳常见的摩擦临界条件_笔记","note":"视频|00:09-02:01","orig":"（知识）从静摩擦到滑动摩擦的临界点是物体”刚要推动”的状态：仍保持相对静止但静摩擦力达最大值 fmax=μN；静摩擦力范围 0<f≤fmax，滑动摩擦力为定值 f=μN","link":""},{"id":"phy0450","t":"相互作用·摩擦为零临界","s":"看到【”摩擦力恰好为零””无相对运动趋势”】","c":"想到【接触面既无相对运动也无运动趋势，摩擦为零是特殊平衡条件，常用于斜面平衡分析】；警惕【与滑动摩擦为零（$\\mu$=0）区分，此处是趋势为零而非粗糙度为零】","src":"物一轮073.归纳常见的摩擦临界条件_笔记","note":"视频|02:01-02:35","orig":"（知识）题目出现”摩擦力恰好为零””无相对运动趋势”时，接触面间不存在摩擦作用，常见于斜面上物体处于平衡状态的特殊条件分析","link":""},{"id":"phy0451","t":"相互作用·斜面摩擦临界","s":"看到【斜面上物体”恰好不下滑”，再施加外力F求F或判断状态】","c":"想到【先由初始临界态 f=$\\mu$N 列平衡求 $\\mu$，再对新状态沿斜面/垂直斜面正交分解重新列方程】；警惕【外力F会改变支持力N从而改变最大静摩擦力，不能直接套用初始状态的摩擦力值】","src":"物一轮073.归纳常见的摩擦临界条件_笔记","note":"视频|02:35-13:01","orig":"（例）物块”恰好不下滑”得 mgsin37°=μmgcos37°，μ=tan37°=3/4；加拉力F后最大静摩擦方向变为向下，N₂=mgcos37°−Fsin37°，联立 y：N₂+Fsin37°=mgcos37°、x：Fcos37°=mgsin37°+μN₂，解得 F=9.6N","link":""},{"id":"phy0452","t":"相互作用·连接体摩擦临界","s":"看到【连接体中某物体”恰好不下滑”（靠摩擦支撑悬住）】","c":"想到【隔离该物体沿竖直方向列平衡（最大静摩擦与重力平衡）建立补充方程，再整体法求外力】；警惕【未知量过多时，靠临界条件补充方程突破，隔离法求N、整体法求F】","src":"物一轮073.归纳常见的摩擦临界条件_笔记","note":"视频|13:01-20:51","orig":"（例）”B恰好不下滑”：AB间静摩擦力向上且达最大值 f₂=μ₁N₂=m_b·g，隔离B得 N₂=m_b·g/μ₁，B的加速度 a=N₂/m_b，整体法 F−μ₂(m_a+m_b)g=(m_a+m_b)a，解得 F=150N","link":""},{"id":"phy0453","t":"相互作用·临界条件归纳","s":"看到【题目出现”刚好””恰好”类关键词】","c":"想到【先翻译成对应临界状态（fmax、f=0、绳绷直、脱离、极值），再列方程求解】；警惕【不同临界态对应不同方程，斜面上”不上滑”与”不下滑”摩擦力方向相反】","src":"物一轮073.归纳常见的摩擦临界条件_笔记","note":"视频|20:51","orig":"（知识）高中常见临界条件：绳/接触面恰好绷直或脱离；摩擦 f 达 fmax 或 f=0；运动的速度/距离极值点；”恰好不上滑”时静摩擦力向下且 f=μN","link":""},{"id":"phy0454","t":"牛顿运动定律·摩擦临界与外力判断","s":"看到【判断水平拉力F能否拉动物体/是否发生相对运动】","c":"想到【本质是比较实际静摩擦力 f 与 fm；仅在平衡状态（F=f）下才可通过比较 F 与 fm 判断】；警惕【物体有加速度时 F$\\neq$f，不能惯性套用 F>$\\mu$mg 即滑动】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|01:29-04:53","orig":"（知识）平衡状态下 F=f；F<fm 保持静止，F=fm ”恰好”静止，F>fm 被拉动；但发生相对运动的本质条件是静摩擦力 f 达到最大静摩擦力 fm，而非外力 F 与 fm 的关系","link":""},{"id":"phy0455","t":"牛顿运动定律·光滑地面叠放临界","s":"看到【光滑地面叠放物体、拉力作用于下层，求恰好发生相对滑动的临界F】","c":"想到【临界条件为接触面摩擦达最大值 f=fm=$\\mu$N 且两物体加速度相同，整体法+隔离法联立解 Fm】；警惕【比较对象是 F 与临界值 Fm，而非直接比较 F 与 $\\mu$mg】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|04:56-10:14","orig":"（例）光滑地面、F 拉 m₁：对 m₁ 列 F−f=m₁a、整体 F=(m₁+m₂)a，得 f=m₂F/(m₁+m₂)；临界 f=fm=μm₁g，解得 Fm=μm₁g(m₁+m₂)/m₂","link":""},{"id":"phy0456","t":"牛顿运动定律·叠放模型变式（拉力作用于上层）","s":"看到【同样叠放模型但拉力改作用在另一物体上求临界F】","c":"想到【临界条件不变（f 达最大值+加速度相同），重新整体隔离联立推导】；警惕【拉力作用对象改变后临界值表达式随之改变，不能沿用原结论】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|11:24-13:43","orig":"（例）光滑地面、F 作用于 m₂：临界 f=μm₁g，整体 F=(m₁+m₂)a，对 m₁ 列 f=m₁a，联立解得 Fm=(m₁+m₂)μg","link":""},{"id":"phy0457","t":"牛顿运动定律·粗糙地面叠放临界","s":"看到【粗糙地面上的叠放物体，判断哪个接触面先滑动/能否拉动】","c":"想到【比较各接触面的最大静摩擦力，先达到最大值的接触面先发生相对滑动】；警惕【忽略地面摩擦对整体运动的影响会导致误判】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|13:48-20:08","orig":"（知识）静止时 F=f₁=f₂，F 增大时两个接触面摩擦力同时增大，先达到最大静摩擦的接触面先滑动；若 μ₁m₁g<μ₂(m₁+m₂)g，则无论 F 多大 m₂ 都不会被拉动","link":""},{"id":"phy0458","t":"牛顿运动定律·叠放相对滑动临界值","s":"看到【求粗糙地面叠放物体恰好发生相对运动的临界F】","c":"想到【抓住两个临界关键：摩擦力达最大值+两物体加速度相同，整体与隔离联立求解】；警惕【先划分运动阶段：F<$\\mu$_{2}(m_{1}+m_{2})g 均静止、中间段共同加速、超过Fm才相对滑动】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|20:08-23:42","orig":"（例）粗糙地面叠放求 Fm：临界 f₁=μ₁m₁g 且加速度相同，对 m₁ 列 Fm−μ₁m₁g=m₁a、整体 Fm−μ₂(m₁+m₂)g=(m₁+m₂)a，联立解得 Fm（公式不需记忆，掌握推导方法）","link":""},{"id":"phy0459","t":"牛顿运动定律·粗糙叠放变式（拉力作用于上层）","s":"看到【粗糙地面叠放、拉力作用于上层物体，分析运动顺序】","c":"想到【下层必须随整体先被拉动后才可能相对滑动，临界时仍用”摩擦达最大+加速度相同”联立】；警惕【不会出现 m_{1} 动而 m_{2} 不动的情形】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|23:42-28:15","orig":"（知识）F 作用在 m₂ 上时不会出现 m₁ 动而 m₂ 不动；必须 m₂ 先被拉动，之后两物体才可能相对滑动；临界时对 m₁ 列 μ₁m₁g=m₁a，整体 Fm−μ₂(m₁+m₂)g=(m₁+m₂)a，解得 Fm","link":""},{"id":"phy0460","t":"牛顿运动定律·多接触面临界","s":"看到【多物体叠放系统求不发生相对滑动的最大拉力】","c":"想到【整体法列系统方程+隔离受摩擦力最大的物体列式，联立求 Fm】；警惕【先确认研究对象（整体+单个物体）再建力与加速度关系】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|28:15-32:33","orig":"（例）光滑地面AB叠放求最大拉力：fmax=μN=2μmg，整体 Fm=3ma、隔离 2μmg=ma，解得 Fm=6μmg","link":""},{"id":"phy0461","t":"牛顿运动定律·多接触面临界（地面粗糙）","s":"看到【叠放问题中地面也粗糙，求临界拉力或滑动后的加速度】","c":"想到【各接触面分别计算临界条件，实际临界值取各接触面计算结果的最小值】；警惕【隔离方程中要扣除地面摩擦的贡献】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|32:33-36:08","orig":"（例）地面动摩擦因数 0.5μ：整体 Fm−1.5μmg=3ma、隔离 2μmg−1.5μmg=ma，解得 a=0.5μg、Fm=3μmg；F=4μmg>Fm 时发生相对滑动，单独分析 A 得 a=μg","link":""},{"id":"phy0462","t":"牛顿运动定律·复杂系统双临界","s":"看到【复杂多物块系统含多个可能滑动的接触面】","c":"想到【逐个分析可能滑动的接触面，分别求临界F后取最小值，保证所有接触面同时满足相对静止】；警惕【漏算某个接触面、研究对象（整体/局部）选择不当】","src":"物一轮074.讨论摩擦临界问题中的外力临界值_笔记","note":"视频|36:08","orig":"（例）四物块（m、2m，物块间μ、地面0.5μ，上部轻绳连接）：左侧接触面临界 Fm₁=6μmg，右侧接触面临界 Fm₂=3.6μmg，取较小值 3.6μmg 作为系统临界值","link":""},{"id":"phy0463","t":"牛顿运动定律·单物体a-F图像","s":"看到【粗糙地面上物体受渐增拉力F，画或分析 a-F 图像】","c":"想到【F$\\leq$fm 时 a=0（水平段），之后为斜率 1/m、截距 −$\\mu$g 的直线】；警惕【纵轴截距 −$\\mu$g 的物理意义是摩擦阻力，勿漏地面摩擦】","src":"物一轮075.讨论摩擦临界问题中a随F的变化规律_笔记","note":"视频|01:04-04:17","orig":"（知识）粗糙地面上静止物体：F<fm=μmg 时 a=0；F=fm 为恰好静止临界点；F>fm 后 F−μmg=ma，得 a=F/m−μg，图像为斜率 1/m、纵截距 −μg 的一次函数","link":""},{"id":"phy0464","t":"牛顿运动定律·光滑叠放a-F图像","s":"看到【光滑地面叠放物体，分析 a 随 F 的变化规律】","c":"想到【共速段整体法 a=F/(m_{1}+m_{2})；滑动后被动物体加速度恒定、主动物体斜率变大】；警惕【斜率变化反映质量倒数关系 1/m_{1}>1/(m_{1}+m_{2})，滑动段图像更陡】","src":"物一轮075.讨论摩擦临界问题中a随F的变化规律_笔记","note":"视频|04:17-10:15","orig":"（知识）共速阶段（F≤Fm）：整体 a=F/(m₁+m₂)，过原点直线；相对滑动后 a₁=F/m₁−μg 斜率增大为 1/m₁；a₂=μm₁g/m₂ 为定值，图像水平","link":""},{"id":"phy0465","t":"牛顿运动定律·粗糙叠放a-F图像","s":"看到【粗糙地面叠放物体，划分 a-F 图像的阶段】","c":"想到【先验证摩擦条件成立，再按静止段、整体段、滑动段分别用牛顿第二定律建 a-F 函数】；警惕【被动体滑动后加速度与 F 无关，为水平线】","src":"物一轮075.讨论摩擦临界问题中a随F的变化规律_笔记","note":"视频|10:22-15:02","orig":"（知识）需满足 μ₁m₁g>μ₂(m₁+m₂)g 才能先整体运动后相对滑动；静止段 a=0；整体段 a=F/(m₁+m₂)−μ₂g；滑动段 a₁=F/m₁−μ₁g，a₂=[μ₁m₁g−μ₂(m₁+m₂)g]/m₂ 与 F 无关","link":""},{"id":"phy0466","t":"牛顿运动定律·a-F图像真题（长木板）","s":"看到【a-F 图像中出现两个转折力 F_{1}、F_{2} 的问题】","c":"想到【F_{1} 对应整体开始运动（含总质量的最大静摩擦），F_{2} 对应相对滑动临界，分别由整体法+隔离法求得】；警惕【F_{1} 计算时包含两物体总质量，区分地面 $\\mu$ 与接触面 $\\mu$】","src":"物一轮075.讨论摩擦临界问题中a随F的变化规律_笔记","note":"视频|15:02-25:35","orig":"（例）F₁ 为系统开始运动的临界力 F₁=μ₁(m₁+m₂)g；F₂ 为发生相对运动的临界力（整体隔离联立）；能拉动需 μ₂m₂g>μ₁(m₁+m₂)g；0~t₂ 内物块与木板相对静止加速度相等","link":""},{"id":"phy0467","t":"牛顿运动定律·图像反求μ与质量","s":"看到【F-t 图像与摩擦力突变点，反求动摩擦因数和质量】","c":"想到【图像转折点对应最大静摩擦力，此时刻两物体加速度仍相同，用整体法+隔离法联立方程组】；警惕【先由图像斜率确定 F 随时间的变化关系，再代入动力学方程】","src":"物一轮075.讨论摩擦临界问题中a随F的变化规律_笔记","note":"视频|25:35-29:55","orig":"（例）3s 时摩擦力达最大 30N，由 fmax=μmg 得 μ=30/(5×10)=0.6；3s 时 F=60N 即将相对运动，整体 60=(M+m)a、木板 30=Ma，联立得 M=m=5kg，a=6m/s²","link":""},{"id":"phy0468","t":"牛顿运动定律·临界问题解题流程","s":"看到【摩擦临界问题要求外力临界值或分段 a-F 关系】","c":"想到【先判定临界条件，整体+隔离联立求 Fcrit，再按临界值划分静止段/共速加速段/相对滑动段分段列式】；警惕【共速段用整体法，滑动后必须隔离分析】","src":"物一轮075.讨论摩擦临界问题中a随F的变化规律_笔记","note":"视频|29:55","orig":"（知识）解题步骤：①确定临界两条件（fmax=μN 与加速度相同）；②整体法建加速度表达式、隔离法分析受力；③联立求临界外力 Fcrit；④按临界值划分阶段，分别建立各段 a-F 关系曲线","link":""},{"id":"phy0469","t":"牛顿运动定律·弹簧连接体分离条件","s":"看到【外力+弹簧作用下的连接体，讨论两物体何时分离】","c":"想到【分离临界=接触弹力为零+分离瞬间速度、加速度相同，两条件同时满足】；警惕【分离时弹簧弹力一般不为零，弹簧不必恢复原长】","src":"物一轮076.分析恒力与弹簧作用下连接体的弹力临界_笔记","note":"视频|01:07-02:51","orig":"（知识）连接体 AB 在外力 F 和弹簧作用下运动：分离的力学条件为 AB 间弹力 N=0，运动学条件为分离瞬间速度相同、加速度相同","link":""},{"id":"phy0470","t":"牛顿运动定律·初始不分离的最大力","s":"看到【求弹簧连接体保持不分离的最大恒力F】","c":"想到【初态弹簧弹力与总重力抵消，合力即 F，整体加速度 a=F/(mA+mB)；再隔离研究对象令 N=0 求 F 临界值】；警惕【临界条件是 N=0 而非弹簧恢复原长】","src":"物一轮076.分析恒力与弹簧作用下连接体的弹力临界_笔记","note":"视频|03:51-06:44","orig":"（例）初态平衡时弹簧弹力 F弹=(mA+mB)g，加 F 后整体 a=F/(mA+mB)；对 A 隔离，N=0 时 F 最大，得 Fmax=mA(mA+mB)g/mB","link":""},{"id":"phy0471","t":"牛顿运动定律·分离瞬间状态分析","s":"看到【判断分离瞬间弹簧状态与加速度方向】","c":"想到【分离时弹簧仍压缩并提供弹力，加速度方向取决于恒力 F 与重力 mAg 的相对大小】；警惕【分离瞬间加速度可能向上也可能向下，不能默认方向】","src":"物一轮076.分析恒力与弹簧作用下连接体的弹力临界_笔记","note":"视频|06:44-09:14","orig":"（知识）AB 分离瞬间弹簧必处于压缩状态（弹力向上），F弹=mB F/mA；加速度方向由 F 与 mAg 大小决定：F>mAg 时向上，F<mAg 时向下","link":""},{"id":"phy0472","t":"牛顿运动定律·分离前后运动过程","s":"看到【分析弹簧连接体从启动到分离的全过程运动性质】","c":"想到【分离前是”加速度减小的加速$\\to$加速度反向增大的减速”，实际分离可能发生在加速或减速阶段；分离后两者运动性质由各自受力决定】；警惕【分离不一定发生在 a=0 时刻】","src":"物一轮076.分析恒力与弹簧作用下连接体的弹力临界_笔记","note":"视频|09:14-14:21","orig":"（知识）分离前：AB 上移→压缩量减小→弹力减小→合力减小→加速度减小的加速；加速度为零后合力反向增大→加速度增大的减速；分离后 A 仅受恒力和重力做匀变速运动，B 受变力弹簧弹力做加速度变化的变速运动","link":""},{"id":"phy0473","t":"牛顿运动定律·分离选择题判断","s":"看到【选择题判断分离时刻的加速度、弹力或劲度系数】","c":"想到【分离瞬间两物体加速度相同，再对单个物体隔离分析；由 $\\Delta$F=k$\\Delta$x 求 k】；警惕【勿认为分离时接触力仍存在或弹簧已恢复原长】","src":"物一轮076.分析恒力与弹簧作用下连接体的弹力临界_笔记","note":"视频|14:21-17:50","orig":"（例）分离时加速度相同，b 加速度为 0（F=mg 平衡）；由 ΔF=mg 对应 Δx=h 得 k=mg/h；分离前为加速度减小的加速运动，答案 C","link":""},{"id":"phy0474","t":"牛顿运动定律·分离瞬间定量计算","s":"看到【求分离瞬间的加速度与弹簧弹力数值】","c":"想到【由分离条件（N=0、加速度相同）确定状态后，隔离两物体分别列牛顿第二定律联立求解】；警惕【弹簧仍处于压缩状态提供弹力】","src":"物一轮076.分析恒力与弹簧作用下连接体的弹力临界_笔记","note":"视频|17:50","orig":"（例）B 与 A 分离时：对 B 列 0.8mg−mg=ma 得 a=0.2g；对 A 列 2mg−F弹=2m×0.2g 得 F弹=1.6mg；弹簧处于压缩状态","link":""},{"id":"phy0475","t":"牛顿运动定律·恒定加速度连接体分离","s":"看到【恒定加速度下拉动弹簧连接体，求分离时刻的弹力或拉力极值】","c":"想到【分离时刻 AB 间弹力为零但弹簧弹力不为零，隔离被动物体列 F弹−mg=ma；拉力随时间变化，最小值在初始时刻】；警惕【分离时弹簧弹力不为零，不能用弹簧原长条件】","src":"物一轮077.分析加速度恒定的弹簧作用下连接体的弹力临界_笔记","note":"视频|00:08-06:58","orig":"（例）A、B 质量均为 m，系统静止时弹簧弹力 F弹=2mg；施加拉力 F 使 A 匀加速（a<g），t₁ 时刻分离；分离时 AB 间弹力为零但弹簧弹力不为零，隔离 B：F弹−mg=ma 得 F弹=m(g+a)；拉力最小值 Fmin=2ma（初始时刻）","link":""},{"id":"phy0476","t":"牛顿运动定律·最大速度位置判断","s":"看到【判断弹簧恢复原长时物体速度是否最大】","c":"想到【速度最大的位置是合力为零（a=0）的平衡位置，而非弹簧原长处】；警惕【原长处弹力为零但重力仍在，物体仍在加速或减速】","src":"物一轮077.分析加速度恒定的弹簧作用下连接体的弹力临界_笔记","note":"视频|00:08-06:58","orig":"（例）分离时 A 上升距离 Δx=m(g−a)/k；弹簧原长时 B 速度未达最大，平衡位置（a=0）速度最大","link":""},{"id":"phy0477","t":"牛顿运动定律·轻质物体分离问题","s":"看到【轻质托盘/轻弹簧参与的分离与变力-恒力阶段划分问题】","c":"想到【轻质物体合力必为零（F合=0），分离时其上弹力为零；分离临界=接触力为零+加速度相同】；警惕【先划分变力阶段与恒力阶段，再分段求拉力极值】","src":"物一轮077.分析加速度恒定的弹簧作用下连接体的弹力临界_笔记","note":"视频|06:58","orig":"（例）m=12kg、k=800N/m，初始压缩量 x₀=mg/k=0.15m；0~0.2s 为变力阶段，0.2s 后物体与托盘分离进入恒力阶段；轻质托盘质量为零⇒分离时 F弹=0；由 x=½at² 得 a=7.5m/s²；Fmin=ma=90N（初始），Fmax=m(g+a)=210N（分离时刻）","link":""},{"id":"phy0478","t":"牛顿运动定律·斜面弹簧连接体分离","s":"看到【斜面上弹簧连接体做匀加速运动，判断分离时的状态】","c":"想到【分离条件仍是 N=0+加速度相同；分离时弹簧仍需压缩以提供加速度分量，用胡克定律联立初始条件求形变量】；警惕【误认为分离时弹簧恢复原长】","src":"物一轮077.分析加速度恒定的弹簧作用下连接体的弹力临界_笔记","note":"视频|06:58","orig":"（例）初始 kx₀=3mgsinθ；分离时 AB 间弹力恰好为零（B 选项正确），弹簧仍处于压缩状态（A 错误），分离后 A 仍继续加速（C 错误）；分离时弹力 F弹=2mgsinθ+2ma，形变量 x=(2mgsinθ+2ma)/k","link":""},{"id":"phy0479","t":"牛顿运动定律·分离时间计算","s":"看到【求弹簧连接体从启动到分离的运动时间】","c":"想到【分离时刻形变量由胡克定律求得，位移差 $\\Delta$x=初始形变量−分离时形变量，再用 $\\Delta$x=½at^{2} 求时间】；警惕【时间计算中的代数变换错误、单位一致性】","src":"物一轮077.分析加速度恒定的弹簧作用下连接体的弹力临界_笔记","note":"视频|06:58","orig":"（例）位移关系 Δx=x₀−(2mgsinθ+2ma)/k，由 Δx=½at² 求分离时间 t；核心考点为连接体分离临界条件与变力作用下的匀加速运动","link":""},{"id":"phy0480","t":"传送带模型·知识框架","s":"看到【规划传送带专题的复习路线】","c":"想到【先掌握水平传送带的受力与运动分析通法，再进阶倾斜传送带（叠加 gsin$\\theta$、$\\mu$gcos$\\theta$ 分量）】；警惕【两模块分析方法同源，区别在沿斜面方向的重力分量】","src":"物一轮078.【课前必看】本讲听课建议_笔记","note":"视频|00:33-00:59","orig":"（知识）传送带模型是高中物理重要考点，分为水平传送带与倾斜传送带两大分析模块：基础模块为水平传送带基本模型及变式，进阶模块为倾斜传送带基本模型及变式","link":""},{"id":"phy0481","t":"传送带模型·分层备考策略","s":"看到【按自身基础分配传送带专题的备考精力】","c":"想到【水平传送带是基础必学模块，倾斜传送带属于进阶内容，可依据基础与时间分层取舍】；警惕【时间紧张时倾斜传送带可选择性跳过】","src":"物一轮078.【课前必看】本讲听课建议_笔记","note":"视频|00:59-02:04","orig":"（知识）零基础学生掌握水平传送带基础内容即可；中等基础学生完整学习水平+倾斜传送带查漏补缺；基础扎实学生重点攻克倾斜传送带（4星）难题","link":""},{"id":"phy0482","t":"传送带模型·考情分布","s":"看到【评估传送带考点的考查形式与频率】","c":"想到【水平传送带以选择题单独考或嵌入解答题复合模型，倾斜传送带选考、解考均有】；警惕【复习时不能只练选择题形式，需兼顾解答题中的分阶段计算】","src":"物一轮078.【课前必看】本讲听课建议_笔记","note":"视频|02:51","orig":"（知识）水平传送带为中频考点（如 2024 北京卷选择、2024 贵州卷解答、2022/2023 浙江卷），既可单独考选择题也作为解答题复合模型组成部分；倾斜传送带为中低频考点（如 2021 辽宁卷、2024 安徽卷）","link":""},{"id":"phy0483","t":"传送带模型·轻放基本模型","s":"看到【物块轻放（初速为零）到水平传送带上】","c":"想到【相对运动方向定摩擦力方向，a=$\\mu$g 匀加速至共速后摩擦力消失改匀速】；警惕【共速后摩擦力立即为零，可用假设法验证：若有静摩擦力速度会超过传送带，与相对运动方向矛盾】","src":"物一轮079.水平传送带基本模型分析_笔记","note":"视频|00:56-13:28","orig":"（知识）轻放（v₀=0）：竖直方向 N=mg 平衡，水平方向滑动摩擦力 f=μmg 向前（相对传送带向后滑），a=μg，先匀加速至共速后摩擦力为零改匀速；加速时间 t=v/(μg)，加速位移 x=v²/(2μg)，相对位移 Δx=x带−x块=v²/(2μg)","link":""},{"id":"phy0484","t":"传送带模型·带长对运动的影响","s":"看到【传送带长度 L 与加速位移 x 的比较问题】","c":"想到【先算变速位移再与 L 比较，决定是”变速+匀速”还是”全程变速”两阶段】；警惕【短传送带末速度 v^{'}=√(2$\\mu$gL)<v，勿直接代入共速速度】","src":"物一轮079.水平传送带基本模型分析_笔记","note":"视频|13:28-16:42","orig":"（知识）比较加速位移 x=v²/(2μg) 与带长 L：L>x 完整经历加速+匀速；L<x 仅加速未达共速即离开，用 x=½μgt² 得 t=√(2L/μg)；L=x 恰好在末端共速","link":""},{"id":"phy0485","t":"传送带模型·初速度不为零的变式","s":"看到【物块以初速度 v_{0} 沿传送带转动方向冲上水平传送带】","c":"想到【先比较 v_{0} 与 v 判断相对运动方向，进而定摩擦力方向和运动阶段】；警惕【无论加速还是减速，共速后摩擦力立即消失、转为匀速】","src":"物一轮079.水平传送带基本模型分析_笔记","note":"视频|16:44-19:53","orig":"（知识）同向冲上传送带三种情况：v₀<v 相对向后→摩擦力向前→先加速后匀速；v₀=v 直接共速匀速；v₀>v 相对向前→摩擦力向后→先减速后匀速","link":""},{"id":"phy0486","t":"传送带模型·离开速度与划痕计算","s":"看到【求物块离开传送带的速度、总时间或划痕长度】","c":"想到【先算加速位移并与 L 比较分段求时间；划痕长度=变速阶段的相对位移（传送带位移−物块位移）】；警惕【匀速阶段无相对滑动、不产生新划痕】","src":"物一轮079.水平传送带基本模型分析_笔记","note":"视频|19:53-27:35","orig":"（例）v=2m/s、μ=0.2、L=10m：a=μg=2m/s²，加速位移 x=v²/2a=1m<L，存在匀速段；离开速度 2m/s，加速时间 t₁=1s，总时间 t₁+(L−x)/v=5.5s；划痕=传送带位移 2m−物块位移 1m=1m","link":""},{"id":"phy0487","t":"传送带模型·斜面+传送带组合","s":"看到【斜面下滑后冲上传送带的组合模型，求底端速度或运动时间】","c":"想到【分段分析：斜面段 a=gsin$\\theta$−$\\mu$gcos$\\theta$；传送带段比较底端速度与 v 带定减速或加速，再验证变速位移是否小于带长】；警惕【连接处速率变化可忽略是前提；必须验证减速位移小于传送带长度】","src":"物一轮079.水平传送带基本模型分析_笔记","note":"视频|27:35","orig":"（例）斜面 a₁=gsin37°−μgcos37°=2m/s²，底端速度 2m/s>传送带速度 1m/s，先减速 a₂=μg=5m/s²，减速位移 0.3m<6m；t=0.2+5.7=5.9s","link":""},{"id":"phy0488","t":"传送带模型·反向运动基本变式","s":"看到【物块与传送带速度方向相反（反向运动）】","c":"想到【先向右匀减速到零再反向匀加速，全程为加速度 a=$\\mu$g 的匀变速运动】；警惕【速度为零时摩擦力方向是否突变取决于相对速度方向，此处不变】","src":"物一轮080.水平传送带变式分析_笔记","note":"视频|01:10-04:04","orig":"（知识）物块初速 v₀ 向右、传送带以 v 向左运动：摩擦力向左 f=μmg，物块向右匀减速至零；速度为零时相对传送带仍向右，摩擦力方向不变，继续向左匀加速，全程 a=μg 保持不变","link":""},{"id":"phy0489","t":"传送带模型·能否共速的判断","s":"看到【判断反向传送带上物块能否与带共速、最终以何速度离开】","c":"想到【比较 v_{0} 与 v：v_{0}$\\leq$v 对称往返后以 v_{0} 离开；v_{0}>v 共速后匀速离开】；警惕【两类情况的运动对称性与离开速度不同】","src":"物一轮080.水平传送带变式分析_笔记","note":"视频|04:50-08:55","orig":"（知识）v₀<v 时反向加速至 v₀ 即掉落、无法共速（完整经历减速+加速，末速 −v₀）；v₀>v 时反向加速至 v 后与传送带共速改匀速，不会达到 −v₀","link":""},{"id":"phy0490","t":"传送带模型·运动学参量求解","s":"看到【求反向传送带问题的减速/加速时间与相对位移】","c":"想到【加速度恒为 $\\mu$g，分段用运动学公式求时间与位移；相对位移可分段算位移差】；警惕【v_{0}>v 时往返不对称，加速段只到共速】","src":"物一轮080.水平传送带变式分析_笔记","note":"视频|08:57-15:24","orig":"（知识）a=μg 恒定：减速时间 t₁=v₀/(μg)；v₀<v 时加速时间 t₂=v₀/(μg)（对称），v₀>v 时 t₂=v/(μg)（不对称）；单程位移 x=v₀²/(2μg)，相对位移 Δx 用传送带位移减物块位移分段计算","link":""},{"id":"phy0491","t":"传送带模型·带长的临界影响","s":"看到【传送带长度是否足够让物块完成减速/返回】","c":"想到【带长与减速位移比较决定是否发生反向运动，临界时末端速度恰为零】；警惕【”能返回”类条件隐含带长不小于临界值】","src":"物一轮080.水平传送带变式分析_笔记","note":"视频|15:24-16:49","orig":"（知识）比较带长 l 与减速位移 x₁=v₀²/(2μg)：l>x₁ 能完成减速并反向加速；l<x₁ 未减速到零即掉落；l=x₁ 恰好在最右端减速到零","link":""},{"id":"phy0492","t":"传送带模型·v-t图像分析","s":"看到【给 v-t 图像分析传送带问题（最远距离/最大相对位移/摩擦力方向）】","c":"想到【相对位移=物块 v-t 曲线与传送带速度水平线围成的面积，共速时刻相对位移最大】；警惕【共速阶段摩擦力为零，图像转折点对应速度为零或共速时刻】","src":"物一轮080.水平传送带变式分析_笔记","note":"视频|16:49-22:18","orig":"（例）0~t₁ 向左减速至零（最左侧），t₁~t₂ 反向加速至共速 v₁，t₂~t₃ 匀速；t₁ 时刻离起点最远，t₂ 时刻相对位移最大；0~t₂ 摩擦力始终同向，共速后摩擦力为零","link":""},{"id":"phy0493","t":"传送带模型·斜面+传送带往返","s":"看到【求传送带最短长度或物块能否返回斜面（往返模型）】","c":"想到【最短长度=恰好减速至零的位移 v_{0}^{2}/2a；上滑加速度 gsin$\\theta$+$\\mu$gcos$\\theta$ 与下滑 gsin$\\theta$−$\\mu$gcos$\\theta$ 不同，需分段计算】；警惕【每次往返返回速度递减，上升高度递减】","src":"物一轮080.水平传送带变式分析_笔记","note":"视频|22:18-33:37","orig":"（例）斜面滑至 P 点 v₀=8m/s，带上减速 a₂=μ₂g=5m/s²，最短长度 d=v₀²/2a₂=6.4m；返回与带共速 6m/s 后上滑 a₃=gsin30°+μ₁gcos30°=8m/s²，l′=v²/2a₃=2.25m，第三次速度 3m/s","link":""},{"id":"phy0494","t":"传送带模型·弹性挡板往返","s":"看到【传送带+弹性挡板碰撞往返运动模型】","c":"想到【往返两段加速度同为 $\\mu$g，用速度-位移公式对两段分别列式联立求速度比例】；警惕【碰撞使速度方向突变、大小不变；碰撞后返回过程与 v_{0} 变化无关】","src":"物一轮080.水平传送带变式分析_笔记","note":"视频|33:37-48:19","orig":"（例）与弹性挡板碰撞时速度恰减至 v，碰撞后速度大小不变方向反向；由 v₀²−v²=2aL 与 v²=2aL 联立得 v₀=√2·v；v₀=v 时形成 v→0→v 的无限循环往复运动","link":""},{"id":"phy0495","t":"传送带模型·转向不明的分类讨论","s":"看到【传送带转动方向（顺/逆时针）未明确，判断末端速度】","c":"想到【先算减速所需距离并与带长比较：同向且带足够长才可能共速匀速，反向则全程减速 v^{'}=√(v_{0}^{2}−2aL)】；警惕【必须对同向、反向两种情形分类讨论再比对选项】","src":"物一轮080.水平传送带变式分析_笔记","note":"视频|48:19","orig":"（例）μ=0.1、v₀=4m/s：减速至 2m/s 需距离 (4²−2²)/(2×1)=6m>3.5m 带长，无法完成”减速+匀速”；逆时针时全程减速，末端速度 v′=√(4²−2×1×3.5)=3m/s","link":""},{"id":"phy0496","t":"传送带模型·倾斜传送带基本模型","s":"看到【物块初速为零轻放在向下运转的倾斜传送带上】","c":"想到【物块相对带向上滑，摩擦力沿斜面向下，a_{1}=g(sin$\\theta$+$\\mu$cos$\\theta$)，匀加速至共速】；警惕【摩擦力方向由相对运动判断，勿默认沿斜面向上】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|00:54-03:49","orig":"（例）物块初速0轻放在逆时针转动（带速v向下）的倾斜传送带上，倾角θ、动摩擦因数μ","link":""},{"id":"phy0497","t":"传送带模型·共速时刻受力分析","s":"看到【倾斜传送带上物块与传送带达到共速】","c":"想到【共速是受力突变点，必须重新判断摩擦力性质与方向】；警惕【不能沿用共速前的受力结论继续算加速度】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|03:49-04:48","orig":"（知识）共速时重力和支持力不变，摩擦力需重新判断：相对静止取静摩擦，相对运动取滑动摩擦f=μN","link":""},{"id":"phy0498","t":"传送带模型·共速后运动判断","s":"看到【倾斜传送带共速后比较$\\mu$与tan$\\theta$，μ$\\geq$tan$\\theta$】","c":"想到【静摩擦力恰好平衡重力沿斜面分量，物块随带匀速下滑】；警惕【判断条件是$\\mu$与tan$\\theta$的大小关系，不是$\\mu$与1比较】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|04:59-06:25","orig":"（知识）mgsinθ≤μmgcosθ（μ≥tanθ）时静摩擦f=mgsinθ沿斜面向上，三力平衡保持匀速","link":""},{"id":"phy0499","t":"传送带模型·共速后运动判断","s":"看到【倾斜传送带$\\mu$<tan$\\theta$，共速后物块继续下滑】","c":"想到【共速后改用滑动摩擦，a_{2}=g(sin$\\theta$-$\\mu$cos$\\theta$)继续匀加速，且a_{1}>a_{2}（两式中摩擦力与重力分量由同向变反向）】；警惕【第二段加速度变小，勿沿用a_{1}】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|06:25-07:42","orig":"（知识）mgsinθ>μmgcosθ（μ<tanθ）时滑动摩擦向上，合力向下，a₂=g(sinθ-μcosθ)继续加速","link":""},{"id":"phy0500","t":"传送带模型·共速后运动判断","s":"看到【问倾斜传送带（物块向下加速类）共速后能否减速】","c":"想到【用反证法：减速需要向上的合力，而重力分量与摩擦力均不可能提供，故不可能减速】；警惕【结论仅对本类初速为零向下加速模型成立，初速不同的变式需重新分析】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|07:42-09:05","orig":"（知识）假设共速后减速需要向上加速度，但合力方向向下，矛盾，故不可能减速","link":""},{"id":"phy0501","t":"传送带模型·v-t图像分析","s":"看到【画或读倾斜传送带问题的v-t图像】","c":"想到【图像分两段：斜率a_{1}=g(sin$\\theta$+$\\mu$cos$\\theta$)，转折点速度即传送带速度v，第二段斜率a_{2}=g(sin$\\theta$-$\\mu$cos$\\theta$)或转水平】；警惕【转折点对应的纵坐标就是带速，可用于反推】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|09:05-10:44","orig":"（知识）情况一（μ≥tanθ）：先斜率a₁=g(sinθ+μcosθ)加速至v后水平；情况二（μ<tanθ）：两段加速，斜率a₁>a₂","link":""},{"id":"phy0502","t":"传送带模型·运动参量计算","s":"看到【给定传送带长度L，求物块到达底端的末速度或时间】","c":"想到【先算共速所需位移s_{1}=v^{2}/2a_{1}并与L比较：L<s_{1}则一直以a_{1}加速；L>s_{1}再按$\\mu$与tan$\\theta$关系分共速后匀速或继续加速讨论】；警惕【是否达到共速是分段讨论的前提，勿直接假设能共速】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|10:44-15:51","orig":"（例）求物块在长L传送带上的末速度与总时间：共速前位移s₁=v²/2a₁，与L比较分情况讨论","link":""},{"id":"phy0503","t":"传送带模型·图像反求参数","s":"看到【v-t图给出两段斜率，反求倾角$\\theta$和动摩擦因数$\\mu$】","c":"想到【联立方程组：g sin$\\theta$+$\\mu$g cos$\\theta$=a_{1}，g sin$\\theta$-$\\mu$g cos$\\theta$=a_{2}，两式相加除2得g sin$\\theta$，相减除2得$\\mu$g cos$\\theta$】；警惕【共速前摩擦力方向不同，两段方程一加一减不能混】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|15:51-24:41","orig":"（例）由v-t图得a₁=10m/s²、a₂=2m/s²，联立gsinθ+μgcosθ=10与gsinθ-μgcosθ=2，解得θ=37°、μ=0.5","link":""},{"id":"phy0504","t":"传送带模型·摩擦痕迹计算","s":"看到【求传送带上留下的摩擦痕迹（划痕）长度】","c":"想到【取各段相对位移中的较大值：短划痕会被长划痕覆盖】；警惕【划痕长度不等于各段相对位移之和】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|15:51-24:41","orig":"（例）第一段相对位移x₁=5m，第二段x₂=1m，摩擦痕迹长度s=5m","link":""},{"id":"phy0505","t":"传送带模型·变式（物块初速大于带速）","s":"看到【物块以大于带速的初速度冲上倾斜传送带（同向运动）】","c":"想到【相对带向下$\\to$摩擦力向上，可能以a=g(sin$\\theta$-$\\mu$cos$\\theta$)减速至共速后随带匀速；先验证减速位移是否小于剩余带长】；警惕【a的正负号取决于gsin$\\theta$与$\\mu$gcos$\\theta$的大小，共速后受力需重判】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|24:41-34:38","orig":"（例）包裹初速1.6m/s大于带速0.6m/s，相对带向下，摩擦力向上，a=gsinθ-μgcosθ=-0.4m/s²减速至共速后匀速，总时间4.5s","link":""},{"id":"phy0506","t":"传送带模型·多过程组合","s":"看到【倾斜传送带与水平传送带组合的多过程问题】","c":"想到【分段分析：倾斜段末速度即水平段初速度，水平段按a=$\\mu$g减速（或加速），每段验证位移是否够共速】；警惕【每进入新的一段都要重新做受力分析和共速判断】","src":"物一轮081.倾斜传送带基本模型分析_笔记","note":"视频|34:38","orig":"（例）倾斜段两段加速后滑上水平传送带，a₃=μg=5m/s²减速，验证减速位移1.2m<6m后存在匀速段，总时间2.8s","link":""},{"id":"phy0507","t":"传送带模型·倾斜传送带上滑变式","s":"看到【物块以初速度沿倾斜传送带上滑】","c":"想到【按相对运动分三类讨论：v带<v_{0}（或静止）摩擦向下，a=g sin$\\theta$+$\\mu$g cos$\\theta$；v带>v_{0}摩擦向上，a=g sin$\\theta$-$\\mu$g cos$\\theta$；v带=v_{0}无滑动摩擦】；警惕【传送带转动方向（顺/逆时针）决定接触面速度方向，必须先换算成相对运动再判摩擦力】","src":"物一轮082.倾斜传送带变式分析_笔记","note":"视频|00:16","orig":"（例）物体从传送带下方以v₀=5.0m/s上滑，θ=37°，L=4.45m，μ=0.5，需分传送带静止、v带<v₀、v带>v₀三种情况讨论","link":""},{"id":"phy0508","t":"传送带模型·上滑最大距离","s":"看到【求物块沿倾斜传送带上滑的最大距离】","c":"想到【x=v_{0}^{2}/2a，其中a由摩擦力方向定：摩擦向下取g sin$\\theta$+$\\mu$g cos$\\theta$，摩擦向上取g sin$\\theta$-$\\mu$g cos$\\theta$】；警惕【先确认v带与v_{0}的大小关系再定a，勿默认取大加速度】","src":"物一轮082.倾斜传送带变式分析_笔记","note":"视频|00:16","orig":"（例）传送带静止时摩擦力向下，a=10m/s²，最大距离x=v₀²/2a=1.25m","link":""},{"id":"phy0509","t":"传送带模型·逆时针变式等价性","s":"看到【逆时针转动的倾斜传送带＋物块上滑】","c":"想到【带面向下运动与静止情形的相对运动方向一致，摩擦力与加速度结论相同】；警惕【勿凭直觉认为带一动结果就变，先做相对运动判断】","src":"物一轮082.倾斜传送带变式分析_笔记","note":"视频|00:16","orig":"（例）传送带逆时针转动时接触面向下运动，物块上滑相对带向上，结论与传送带静止时相同（1.25m）","link":""},{"id":"phy0510","t":"传送带模型·最短时间问题","s":"看到【求物块通过传送带的最短时间，需解二次方程】","c":"想到【时间最短对应全程用最小加速度的方案，列位移方程解二次方程后取符合物理情景的较小根】；警惕【二次方程两根都有数学意义，需按运动过程筛选合理解】","src":"物一轮082.倾斜传送带变式分析_笔记","note":"视频|00:16","orig":"（例）全程以最小加速度2m/s²减速：4.45=5t-½·2t²，解得t=1.16s（取较小根）","link":""},{"id":"phy0511","t":"传送带模型·对比分析（两物块）","s":"看到【两个物块在倾角、$\\mu$相同但传送带运转方向不同的倾斜带上运动】","c":"想到【摩擦力方向不同导致运动形式不同：一个先大加速度后共速再小加速度（两段），另一个全程同一加速度（一段）】；警惕【共速后加速度变小，末速度与总时间要分段算】","src":"物一轮082.倾斜传送带变式分析_笔记","note":"视频|00:16","orig":"（例）A、B两滑块重力分量均为6N、摩擦力均4N：A先a₁=g sinθ+μg cosθ=10m/s²共速后a₂=2m/s²，B全程a=2m/s²","link":""},{"id":"phy0512","t":"传送带模型·时间与末速度对比","s":"看到【比较两物块到达底端的时间或末速度】","c":"想到【各自分段列运动学方程求解后对比，共速点是A类运动的分段边界】；警惕【位移相同不代表末速度相同，加速度过程不同则结果不同】","src":"物一轮082.倾斜传送带变式分析_笔记","note":"视频|00:16","orig":"（例）滑块A总时间2s、末速度12m/s；滑块B总时间4s、末速度8m/s，两者不相等","link":""},{"id":"phy0513","t":"传送带模型·划痕与选项技巧","s":"看到【多阶段相对位移求划痕，或由选项反推传送带状态】","c":"想到【划痕取单向最大相对位移（覆盖效应）；可由选项给出的加速度反推对应的传送带速度条件】；警惕【划痕勿把往返相对位移相加；逆向推理时注意隐含条件】","src":"物一轮082.倾斜传送带变式分析_笔记","note":"视频|00:16","orig":"（例）滑块A先向上相对位移5m、后向下1m，划痕取最大值5m；选项反推：a=2m/s²对应v带>v₀","link":""},{"id":"phy0514","t":"板块模型·考情与方法框架","s":"看到【板块模型类的大题】","c":"想到【解题框架分两层：共速前做受力分析$\\to$定加速度$\\to$判运动性质$\\to$求参量；共速后重新判断摩擦力性质再分析】；警惕【共速点是前后两个阶段的分析分界，跳过共速判断直接算易错】","src":"物一轮083.【课前必看】本讲听课建议-板块模型_笔记","note":"视频|00:12-00:30","orig":"（知识）板块模型为动力学经典模型：基础模块为共速前运动过程分析（选择题或大题前两问），进阶模块为共速后运动过程分析（难题选择题或大题后两问）","link":""},{"id":"phy0515","t":"板块模型·复杂变形分类","s":"看到【斜面上的板块、多物块或多木板叠加等复杂板块变式】","c":"想到【变形题仍以基本分析流程为骨架，先逐个对象受力分析、再按共速节点分段，复杂度升级不改变方法本质】；警惕【对象多时先明确每个接触面的摩擦力方向与研究对象】","src":"物一轮083.【课前必看】本讲听课建议-板块模型_笔记","note":"视频|00:30-02:43","orig":"（知识）拓展模块的复杂变形分三类：受力复杂情况（如斜面放置）、多物块系统、多木板系统","link":""},{"id":"phy0516","t":"板块模型·考查形式","s":"看到【板块模型与其他模型综合的考题】","c":"想到【板块部分只需完成其环节任务：判断相对运动、求共速参量或相对位移，把结论作为下一模型的输入】；警惕【综合题中板块段的输出量（末速度、位移）往往是后续过程的初始条件】","src":"物一轮083.【课前必看】本讲听课建议-板块模型_笔记","note":"视频|02:43-03:44","orig":"（知识）考查形式：选择题单独考查（模型题为主）、解答题单独考查（占比最大）、多模型综合题中的环节（如结合单摆/圆周）","link":""},{"id":"phy0517","t":"板块模型·共速前受力分析（地面光滑）","s":"看到【物块在木板上相对滑动，做受力分析】","c":"想到【分别隔离两对象：物块受向左f=$\\mu$mg，板受等大反向摩擦力；注意板对地压力是(M+m)g、物块对板压力N'=mg，别漏掉】；警惕【一对摩擦力等大反向但作用在不同物体上，分别产生各自加速度】","src":"物一轮084.受力分析时的注意事项与参量求解-板块模型_笔记","note":"视频|02:44-06:07","orig":"（例）地面光滑木板上物块以v₀向右运动：物块受f=μmg向左；木板受f'=μmg向右（牛顿第三定律），竖直方向板还受物块压力N'=mg，地面支持力N地=(M+m)g","link":""},{"id":"phy0518","t":"板块模型·运动性质判断","s":"看到【板块模型共速前的运动性质判断】","c":"想到【物块匀减速、板匀加速（或反之），两者加速度方向相反，v-t图画在同一坐标系中交点即共速】；警惕【正方向要统一设定，斜率正负与加速度方向对应】","src":"物一轮084.受力分析时的注意事项与参量求解-板块模型_笔记","note":"视频|06:07-08:48","orig":"（知识）物块a₁=μg向左做向右匀减速，木板a₂=μmg/M向右匀加速；v-t图上两曲线交点即共速点","link":""},{"id":"phy0519","t":"板块模型·共速参量求解","s":"看到【求板块模型共速时间、共同速度或相对位移】","c":"想到【用速度相等联立两物体运动学方程解t和v共，再分别求对地位移，相对位移$\\Delta$x=大位移减小位移】；警惕【相对位移是对地位移之差，不是速度差直接积分后乱套公式】","src":"物一轮084.受力分析时的注意事项与参量求解-板块模型_笔记","note":"视频|08:48-11:57","orig":"（知识）联立v₀-a₁t=v共与a₂t=v共，得t=v₀/(a₁+a₂)、v共=a₂v₀/(a₁+a₂)；对地位移x₁=(v₀²-v共²)/2a₁、x₂=v共²/2a₂，相对位移Δx=x₁-x₂","link":""},{"id":"phy0520","t":"板块模型·地面粗糙变形","s":"看到【地面粗糙的板块模型，板在地面上滑动】","c":"想到【地面摩擦力按f_{2}=$\\mu$_{2}(M+m)g计算（压力为两者总重），板可能同时受物块摩擦力与地面摩擦力，逐个标方向再求合力】；警惕【地面摩擦力的正压力含物块重力，漏加m是高频错误】","src":"物一轮084.受力分析时的注意事项与参量求解-板块模型_笔记","note":"视频|11:57-15:31","orig":"（例）变形：地面粗糙（μ₂），物块初速为零、木板初速v₀向左：板水平方向受物块摩擦力f₁'=μ₁mg向右和地面摩擦力f₂=μ₂(M+m)g向右","link":""},{"id":"phy0521","t":"板块模型·变形场景运动判断","s":"看到【板有初速度而物块初速为零（或初速度与加速度反向的减速判断）】","c":"想到【初速度与加速度反向即减速，与谁静谁动无关；运动形式由初速度和合力方向共同决定】；警惕【勿默认\"物块被带动就是加速\"，先算合力方向】","src":"物一轮084.受力分析时的注意事项与参量求解-板块模型_笔记","note":"视频|15:31","orig":"（知识）物块a₁=μ₁g向左匀加速，木板a₂=[μ₁mg+μ₂(M+m)g]/M向右做向左匀减速；v-t图物块从0递增、板从v₀递减，交点即共速","link":""},{"id":"phy0522","t":"板块模型·质点模型与板长","s":"看到【物块可视为质点、恰好滑到木板一端】","c":"想到【相对位移$\\Delta$x等于木板长度（或恰好滑离的临界条件$\\Delta$x=L）】；警惕【\"恰好滑到某端\"是位移约束条件，可直接列$\\Delta$x=L方程】","src":"物一轮085.例题讲解与练习(1)-板块模型_笔记","note":"视频|00:03-10:47","orig":"（知识）物块可视为质点时宽度不计入相对位移，物块从板左端滑至右端的位移差即为板长L₀","link":""},{"id":"phy0523","t":"板块模型·初始加速度计算","s":"看到【物块滑上木板，求两者的初始加速度】","c":"想到【物块a_{1}=$\\mu$_{1}g；木板受物块摩擦力（动力）与地面摩擦$\\mu$_{2}(M+m)g（阻力），合力除以M得a_{2}】；警惕【先比较$\\mu$_{1}mg与$\\mu$_{2}(M+m)g判断板是否真的动起来，板不动则加速度为零】","src":"物一轮085.例题讲解与练习(1)-板块模型_笔记","note":"视频|00:03-10:47","orig":"（例）物块f₁=μ₁N=5N向左，a₁=5m/s²；木板受物块反作用力5N向右、地面摩擦f₂=μ₂(M+m)g=3N向左，合力2N，a₂=1m/s²","link":""},{"id":"phy0524","t":"板块模型·共速求解","s":"看到【求板块共速时间与共同速度】","c":"想到【速度相等列方程：一方v_{0}-a_{1}t、另一方a_{2}t，联立求解】；警惕【共速后速度方向要明确标注，且需重新判断相对运动】","src":"物一轮085.例题讲解与练习(1)-板块模型_笔记","note":"视频|00:03-10:47","orig":"（例）物块v₀=6m/s匀减速、木板从0匀加速，v₀-a₁t=a₂t解得t=1s、v共=1m/s（向右）","link":""},{"id":"phy0525","t":"板块模型·板长与相对位移","s":"看到【求木板最小长度或物块在板上的相对滑行距离】","c":"想到【同向运动时$\\Delta$x=x_{1}-x_{2}（位移差），相对位移与几何约束（板长）直接挂钩】；警惕【两物体同向运动取差值、反向运动取和值，先确认方向关系】","src":"物一轮085.例题讲解与练习(1)-板块模型_笔记","note":"视频|00:03-10:47","orig":"（例）物块位移x₁=(v₀²-v共²)/2a₁=3.5m，木板位移x₂=v共²/2a₂=0.5m，Δx=3m即板长L₀=3m","link":""},{"id":"phy0526","t":"板块模型·逆向思维求参量","s":"看到【木板质量未知，只给运动学结果（共速时间、位移等）】","c":"想到【逆向思维：先由运动学求加速度，再用牛顿第二定律$\\mu$_{1}mg-$\\mu$_{2}(M+m)g=Ma_{2}反求质量】；警惕【由运动反推力时，先验证v共$\\neq$0以确认板确实运动】","src":"物一轮085.例题讲解与练习(1)-板块模型_笔记","note":"视频|10:47","orig":"（例）由共速时间t=2s和a₁=2m/s²反推v共=2m/s≠0证明板必运动，得a₂=1m/s²；再由μ₁mg-μ₂(M+m)g=Ma₂解得M=4kg","link":""},{"id":"phy0527","t":"板块模型·最小长度临界","s":"看到【求物块不滑出木板的最小板长】","c":"想到【临界情形是共速时物块恰滑到板末端，最小长度=共速前相对位移】；警惕【\"最小\"对应恰好共速到达端点的临界条件，不是随便一段位移】","src":"物一轮085.例题讲解与练习(1)-板块模型_笔记","note":"视频|10:47","orig":"（例）物块位移x₁=8m、木板位移x₂=2m，最小长度d=6m","link":""},{"id":"phy0528","t":"板块模型·共速后分析的意义","s":"看到【板块（或物块与传送带）达到共速后要求继续分析】","c":"想到【共速是摩擦力性质的分界点：先用假设法判断相对静止还是相对滑动，再定后续运动】；警惕【跳过共速判断直接套用之前的摩擦力是最常见失分点】","src":"物一轮086.假设法判断共速后的相对运动情况-板块模型_笔记","note":"视频|01:57-02:31","orig":"（知识）共速后相对静止则受静摩擦（大小有范围），相对运动则受滑动摩擦f=μN；该判断决定后续受力分析与运动图像绘制","link":""},{"id":"phy0529","t":"板块模型·假设法标准步骤","s":"看到【需要判断共速后两物体是否保持相对静止】","c":"想到【三步假设法：假设相对静止$\\to$整体法求a、隔离法求所需静摩擦f需$\\to$与f_max=$\\mu$N比较：f需$\\leq$f_max相对静止，否则相对滑动】；警惕【最大静摩擦默认等于滑动摩擦力$\\mu$N】","src":"物一轮086.假设法判断共速后的相对运动情况-板块模型_笔记","note":"视频|02:31-06:00","orig":"（知识）步骤：1假设相对静止→2计算静摩擦力（整体法求a整体，隔离法求f需）→3验证f需是否≤最大静摩擦f_max=μmg，成立则假设成立","link":""},{"id":"phy0530","t":"板块模型·光滑地面共速后","s":"看到【地面光滑的板块模型共速之后】","c":"想到【系统不受外力，共速后所需静摩擦为零必然成立，两者以v共一起匀速直线运动】；警惕【v-t图上共速点处加速度突变为零，出现转折】","src":"物一轮086.假设法判断共速后的相对运动情况-板块模型_笔记","note":"视频|02:31-06:00","orig":"（例）光滑地面：假设相对静止→整体a=0→隔离物块f=ma=0<μmg，假设成立，共速后一起匀速","link":""},{"id":"phy0531","t":"板块模型·粗糙地面且μ₂<μ₁","s":"看到【粗糙地面上板块共速后，且$\\mu$_{2}（地面）<$\\mu$_{1}（板间）】","c":"想到【共速后相对静止，一起以a=$\\mu$_{2}g减速；v-t图斜率变缓，a_{3}<a_{1}且a_{3}<a_{2}】；警惕【用隔离法验证：物块所需静摩擦$\\mu$_{2}mg小于最大静摩擦$\\mu$_{1}mg才能保持相对静止】","src":"物一轮086.假设法判断共速后的相对运动情况-板块模型_笔记","note":"视频|10:53-15:01","orig":"（知识）整体a=μ₂g，物块所需静摩擦f=μ₂mg<μ₁mg，假设成立：共速后相对静止，整体以a=μ₂g共同减速","link":""},{"id":"phy0532","t":"板块模型·粗糙地面且μ₂>μ₁","s":"看到【共速后假设相对静止却得到所需静摩擦大于$\\mu$_{1}mg（如$\\mu$_{2}>$\\mu$_{1}）】","c":"想到【假设出现矛盾时取反方向二次假设：发生相对滑动，物块加速度大小突变为$\\mu$_{1}g、方向反向，板按新受力重新算a】；警惕【相对运动方向与加速度方向是两回事，勿混淆；图像斜率随$\\mu$_{1}、$\\mu$_{2}关系分段变化】","src":"物一轮086.假设法判断共速后的相对运动情况-板块模型_笔记","note":"视频|15:01","orig":"（知识）首次假设相对静止推出矛盾（需f=μ₂mg>μ₁mg），二次假设板相对物块向右运动：物块a₁'=μ₁g（方向反向），板a₂'=μ₂g+(μ₂-μ₁)mg/M","link":""},{"id":"phy0533","t":"板块模型·图像与易错警示","s":"看到【板块问题v-t图上斜率在共速点发生改变】","c":"想到【每个斜率对应一个受力阶段，共速点即受力突变点；先比较$\\mu$_{1}与$\\mu$_{2}再确定斜率变化】；警惕【斜率变化方向（变缓或变陡）由共速后受力分析决定，不能凭感觉画】","src":"物一轮086.假设法判断共速后的相对运动情况-板块模型_笔记","note":"视频|15:01","orig":"（知识）vt图像斜率与受力突变对应：相对静止时共速后斜率同时小于共速前两者；易错点：忽略μ₂与μ₁大小关系对结论的影响","link":""},{"id":"phy0534","t":"板块模型·图像法求摩擦因数","s":"看到【v-t图给出各段斜率，反求上下表面动摩擦因数】","c":"想到【共速前物块斜率对应$\\mu$_{1}=a_{1}/g；共速后若整体减速，斜率对应$\\mu$_{2}=a_{3}/g】；警惕【共速前后对应不同摩擦面，先分清斜率属于哪个阶段】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|00:03-11:19","orig":"（例）由v-t图斜率得a₁=2m/s²，则μ₁=a₁/g=0.2；共速后整体加速度a₃=μ₂g=1m/s²，得μ₂=0.1","link":""},{"id":"phy0535","t":"板块模型·速度为零时摩擦力方向","s":"看到【板块问题中物块速度减为零的时刻】","c":"想到【摩擦力方向取决于相对运动方向而非速度是否为零：物块相对板的方向未变，摩擦力就不反向】；警惕【勿默认速度为零时摩擦力方向改变或物体停止】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|00:03-11:19","orig":"（知识）物块先减速至零再反向加速，速度为零时摩擦力方向不变（相对运动方向未变），加速度不变","link":""},{"id":"phy0536","t":"板块模型·图像法求相对位移","s":"看到【共速后求板长或相对位移，两物体速度图线已知】","c":"想到【用v-t图两线围成的面积直接求相对位移，避免繁琐的位移公式计算】；警惕【质量比计算可用牛顿第二定律联立方程后约分，不必求出各自质量】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|00:03-11:19","orig":"（例）相对位移L等于v-t图中两线围成的三角形面积，L=6×1.5/2=4.5m；对板列牛顿第二定律μ₂(M+m)g+μ₁mg=Ma₂得M=3m","link":""},{"id":"phy0537","t":"板块模型·匀速板隐含条件","s":"看到【板块问题中某物体初始做匀速运动且有拉力】","c":"想到【匀速即合力为零，可列F=f摩擦的平衡方程求出摩擦因数等隐含参数】；警惕【\"匀速\"常是隐藏的平衡条件，是解题突破口】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|11:19-31:54","orig":"（例）木板初始匀速运动，拉力F=8N与地面滑动摩擦力平衡：F=μ₂Mg，解得μ₂=0.4","link":""},{"id":"phy0538","t":"板块模型·共速后假设检验","s":"看到【共速后需判断是否相对滑动】","c":"想到【算整体加速度$\\to$隔离算所需静摩擦$\\to$与f_max=$\\mu$_{1}mg比较：超出则相对滑动，两物体按新摩擦力方向分别重算加速度】；警惕【滑动后两物体加速度不同，地面摩擦力压力要用(M+m)g】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|11:19-31:54","orig":"（例）假设共速后相对静止，所需静摩擦f静=4N>最大静摩擦f_max=μ₁mg=2N，假设不成立发生相对滑动：铁块a₁'=μ₁g向左、木板a₂'=(f₂-f₁)/M=5m/s²向左","link":""},{"id":"phy0539","t":"板块模型·相对位移分段计算","s":"看到【相对运动方向发生改变的相对位移计算】","c":"想到【分段算各阶段相对位移后按方向做矢量差（后段往回抵消前段）】；警惕【相对运动反向时不能把两段相对位移直接相加，要用矢量差】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|11:19-31:54","orig":"（例）共速前Δx₁=3.5-1=2.5m，共速后（相对运动反向）Δx₂=1-0.4=0.6m，最终Δx=Δx₁-Δx₂=1.9m","link":""},{"id":"phy0540","t":"板块模型·初始均静止场景","s":"看到【板块初速均为零、施加拉力后问是否一起运动】","c":"想到【仍用假设法：假设相对静止求整体a，隔离受力较小者算f需并与f_max比较；不成立则各自按滑动摩擦力算加速度】；警惕【共速判断不只在\"达到共速\"时需要，初始状态同样需要】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|31:54","orig":"（例）板A和物块B初始均静止（v=0），受拉力F=15N：先假设相对静止整体a=9/4m/s²，隔离B得f需=2.25N>最大静摩擦1.5N，推翻假设，实际a_A=2.5m/s²、a_B=1.5m/s²","link":""},{"id":"phy0541","t":"板块模型·撤力后多阶段分析","s":"看到【运动中途撤去外力的板块问题】","c":"想到【撤力是新的受力突变点：撤力后板只受摩擦力重新算加速度，重新解共速方程，共速后再次假设法验证】；警惕【跨阶段的时间、速度参数要衔接（前段末速=后段初速）；f需恰等于f_max是相对静止的临界情形】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|31:54","orig":"（例）t=2s撤去F：板A只受摩擦力a_A'=2.5m/s²向左，设Δt后共速5-2.5Δt=3+1.5Δt，解得Δt=0.5s、v共=3.75m/s；之后f需=mμg=1.5N=f_max恰好相对静止一起以μ g减速","link":""},{"id":"phy0542","t":"板块模型·图像法多阶段应用","s":"看到【多阶段板块问题求总相对滑动距离】","c":"想到【各阶段v-t图围成面积分别求相对位移，方向相同则相加】；警惕【先确认各阶段相对运动方向是否一致，再决定相加还是相减】","src":"物一轮087.例题讲解与练习(2)-板块模型_笔记","note":"视频|31:54","orig":"（例）0-2s相对位移=½×2×(5-3)=2m，2-2.5s=½×0.5×2=0.5m，总相对位移2+0.5=2.5m","link":""},{"id":"phy0543","t":"板块模型·斜面板块受力分析","s":"看到【板块叠放在斜面上（受力复杂的板块变形）】","c":"想到【沿斜面正交分解：物块a=g sin$\\theta$±$\\mu$g cos$\\theta$（符号由相对运动定摩擦力方向）；板受斜面摩擦$\\mu$_{2}(M+m)g cos$\\theta$，压力含两物体重力分量】；警惕【每个接触面的摩擦力方向都要按相对运动单独判断】","src":"物一轮088.复杂受力情况-板块模型_笔记","note":"视频|00:59","orig":"（例）斜面倾角37°，板块系统：木块a₁=g sinθ+μ₁g cosθ=8m/s²沿斜面向下；木板受拉力F、木块摩擦力μ₁mg cosθ向上、斜面摩擦μ₂(M+m)g cosθ向下，a₂=6m/s²沿斜面向上","link":""},{"id":"phy0544","t":"板块模型·撤力与共速重合","s":"看到【外力在中途撤去，撤力时刻与共速时刻重合】","c":"想到【用v_{0}-a_{1}t=a_{2}t验证共速时刻与撤力时刻的关系，重合则两个突变叠加，共速后必须整体重新做受力分析】；警惕【撤力前后板的受力完全不同，加速度要重新计算】","src":"物一轮088.复杂受力情况-板块模型_笔记","note":"视频|00:59","orig":"（例）v₀=14m/s、F=18N，t=1s撤力；验证14-8t=6t得t=1s，撤力时刻恰为共速时刻，v共=6m/s","link":""},{"id":"phy0545","t":"板块模型·共速后假设法（斜面）","s":"看到【斜面板块共速后判断相对运动】","c":"想到【标准假设法流程照用：整体求a$\\to$隔离算f需$\\to$与f_max=$\\mu$_{1}N比较；超出则相对滑动，按新摩擦力分别重算加速度】；警惕【斜面上最大静摩擦也要按cos$\\theta$分量算，勿漏投影】","src":"物一轮088.复杂受力情况-板块模型_笔记","note":"视频|00:59","orig":"（知识）共速后假设相对静止，整体法与隔离法发现所需静摩擦f=μ₂mg cosθ=4N大于最大静摩擦μ₁mg cosθ=2N，故发生相对滑动：板a₂'=12m/s²、木块a₁'=8m/s²（均向下），板减速更快","link":""},{"id":"phy0546","t":"板块模型·板停后的静止验证","s":"看到【木板减速到速度为零之后】","c":"想到【第二次用假设法验证：比较斜面可提供的最大静摩擦与维持静止所需的摩擦力，够大则板停后不再运动】；警惕【板停后勿直接让它保持静止或下滑，必须做静摩擦验证】","src":"物一轮088.复杂受力情况-板块模型_笔记","note":"视频|00:59","orig":"（知识）木板减速至零后，斜面能提供的最大静摩擦8N>所需静摩擦4N，木板保持静止；减速时间t₂=6/12=0.5s，总时间1.5s","link":""},{"id":"phy0547","t":"板块模型·板长与相对位移（斜面）","s":"看到【斜面板块求木板最小长度（多阶段板位移）】","c":"想到【L_min=物块位移-板的各段位移之和；板的位移需分段（加速段+减速段）累加，也可用vt图面积差】；警惕【板经历多阶段时位移要逐段算再求和，勿只算一段】","src":"物一轮088.复杂受力情况-板块模型_笔记","note":"视频|00:59","orig":"（例）木块位移x₁=v₀²/2a₁=12.25m；木板位移=加速段3m+减速段1.5m共4.5m；最小长度L_min=x₁-x₂=7.75m","link":""},{"id":"phy0548","t":"板块模型·复杂问题解题总纲","s":"看到【受力复杂或多阶段的板块综合题】","c":"想到【分析总纲：定位每个突变节点（撤力、共速、停止）$\\to$节点处重新受力分析$\\to$假设法判相对运动$\\to$vt图辅助算位移】；警惕【每一个突变节点都要重启受力分析，不能沿用上一阶段结论】","src":"物一轮088.复杂受力情况-板块模型_笔记","note":"视频|00:59","orig":"（知识）解题要点：特别注意共速时刻的受力变化分析；两次使用假设法判断相对运动状态；通过vt图像辅助理解相对位移；板停止后需验证能否保持静止","link":""},{"id":"phy0549","t":"板块模型·多物块动力学","s":"看到【板块模型中某物块做匀加速且已知一段时间内的速度变化】","c":"想到【先由 a=$\\Delta$v/$\\Delta$t 求加速度，再隔离该物块用牛顿第二定律 F-$\\mu$mg=ma 解出 $\\mu$】；警惕【滑动摩擦力方向与相对运动方向相反，不是与运动方向相反】","src":"物一轮089.多物块情况-板块模型_笔记","note":"视频|00:04","orig":"（例）长木板上物块A受水平拉力F=6N，t₁=2s内速度由0增至v₁=4m/s，求A与板间动摩擦因数","link":""},{"id":"phy0550","t":"板块模型·相对位移计算","s":"看到【求两物体间距/相对位移，一个匀速一个匀加速】","c":"想到【分别用运动学公式求各自位移，再按初始位置关系叠加：x=L_{0}+x_B-x_A】；警惕【初始距离的加减关系与位移方向混淆】","src":"物一轮089.多物块情况-板块模型_笔记","note":"视频|00:04","orig":"（例）B匀速运动 x_B=v₀t，A匀加速运动 x_A=½at²，初始间距L₀=5m，求两物块最终间距","link":""},{"id":"phy0551","t":"板块模型·追及相遇","s":"看到【两物体位移差等于给定距离，需求运动时间】","c":"想到【对两物体分别写位移表达式，令位移差等于给定距离得二次方程，舍去不合理的根】；警惕【二次方程两根的物理意义取舍】","src":"物一轮089.多物块情况-板块模型_笔记","note":"视频|00:04","orig":"（例）列方程 ½at²-v₀t=L，即 t²-2t-5=0，解得 t=1+√6 s（舍负根）","link":""},{"id":"phy0552","t":"板块模型·木板加速度","s":"看到【物块在木板上滑动，求木板自身的加速度】","c":"想到【隔离木板：物块给的滑动摩擦力是动力，地面摩擦力是阻力，a=(f物-f地)/M】；警惕【表面光滑意味着无摩擦力】","src":"物一轮089.多物块情况-板块模型_笔记","note":"视频|00:04","orig":"（例）木板受物块给的摩擦力4N向右、地面摩擦力2N向左，a板=(4-2)/2=1 m/s²","link":""},{"id":"phy0553","t":"板块模型·求板最小长度","s":"看到【求木板最小长度/物块不滑出的条件】","c":"想到【最小长度=两者相对位移大小，分别求同一时间内的位移再作差】；警惕【共速时刻是位移计算的截止点】","src":"物一轮089.多物块情况-板块模型_笔记","note":"视频|00:04","orig":"（例）板长 L=x_A'-x板'，A与板均做匀加速运动至共速后求位移差","link":""},{"id":"phy0554","t":"板块模型·解题通法","s":"看到【多物块板块模型综合题】","c":"想到【流程：逐个隔离受力分析$\\to$判定匀速/匀变速$\\to$求各加速度$\\to$建位移关联方程】；警惕【最大静摩擦力通常近似等于滑动摩擦力，相对滑动时用滑动摩擦力】","src":"物一轮089.多物块情况-板块模型_笔记","note":"视频|00:04","orig":"（知识）分析顺序：先隔离后整体逐个受力分析；确定各物体运动性质；算各自加速度；建位移-时间方程","link":""},{"id":"phy0555","t":"板块模型·多木板临界判断","s":"看到【物块依次滑过多块木板，判断哪些板动哪些板不动】","c":"想到【对每块板（或板组）比较：物块给的摩擦力能否克服其最大静摩擦——$\\mu$_{1}mg 与 $\\mu$_{2}(ΣM)g 比大小，列不等式定 $\\mu$ 范围】；警惕【区分被带动的质量是双板还是单板，m与M不能混】","src":"物一轮090.多木板情况-板块模型_笔记","note":"视频|00:08","orig":"（例）物块在A板上时AB整体不动，在B板上时B板滑动：μ₁mg≥μ₂(2M+m)g 且 μ₁mg>μ₂(M+m)g，解得0.3<μ₁≤0.5","link":""},{"id":"phy0556","t":"板块模型·板静止时的减速","s":"看到【板不动，物块在板上减速滑行求某处速度】","c":"想到【此时只有物块一个研究对象，a=$\\mu$g，直接用 v^{2}-v_{0}^{2}=-2aL】；警惕【误给板列加速度方程，板实际加速度为零】","src":"物一轮090.多木板情况-板块模型_笔记","note":"视频|00:08","orig":"（例）μ₁=0.4时AB板始终静止，物块C以 a_c=μ₁g=4 m/s² 减速，v²=v₀²-2a_cL 得 v=1 m/s","link":""},{"id":"phy0557","t":"板块模型·共速时间","s":"看到【物块滑上能动的木板，求共速时间或共速时位移】","c":"想到【分别求物块减速加速度与板加速加速度，联立 v_{0}-a_{1}t=a_{2}t 求共速时刻，位移用 v^{2} 公式】；警惕【板的动力来自物块的滑动摩擦力，还要减去地面摩擦】","src":"物一轮090.多木板情况-板块模型_笔记","note":"视频|00:08","orig":"（例）物块继续以4 m/s²减速，B板加速 a_B=[μ₁mg-μ₂(M+m)g]/M=0.5 m/s²，解 1-4t=0.5t 得 t=2/9 s","link":""},{"id":"phy0558","t":"板块模型·共速后状态判断","s":"看到【两物体共速后判断一起运动还是再相对滑动】","c":"想到【假设相对静止一起减速，算出所需静摩擦力并与最大静摩擦比较：不超则成立，超出则再滑动】；警惕【共速后运动状态往往改变，不能沿用之前加速度】","src":"物一轮090.多木板情况-板块模型_笔记","note":"视频|00:08","orig":"（例）共速后整体减速 a共=μ₂g=1 m/s²，验证所需静摩擦1N<μ₁mg=4N，相对静止成立","link":""},{"id":"phy0559","t":"板块模型·全过程位移","s":"看到【求物块相对板滑行的总距离/最远距离】","c":"想到【分段计算再求和：板静止段+互滑段+共速共同运动段，逐段用运动学公式】；警惕【漏掉其中某一段位移】","src":"物一轮090.多木板情况-板块模型_笔记","note":"视频|00:08","orig":"（例）最远距离=A板位移1m+相对滑动位移10/81m+共同减速位移1/162m≈1.13m","link":""},{"id":"phy0560","t":"板块模型·解题通法","s":"看到【多木板板块综合大题】","c":"想到【流程：明确各阶段研究对象$\\to$临界摩擦条件$\\to$分段列方程$\\to$共速假设验证】；警惕【忽略共速后的运动状态变化】","src":"物一轮090.多木板情况-板块模型_笔记","note":"视频|00:08","orig":"（知识）分段确定研究对象（单板/双板系统）→算临界摩擦条件→分段列运动方程→验证共速后相对运动状态","link":""},{"id":"phy0561","t":"曲线运动·模块框架","s":"看到【复习曲线运动模块需搭建知识框架】","c":"想到【按”运动合成与分解（思想方法）$\\to$抛体运动$\\to$圆周运动”三层递进组织复习，运动合成与分解是处理匀变速曲线运动的核心思想】；警惕【跳过思想方法直接刷抛体、圆周题型】","src":"物一轮091.【课前必看】本讲听课建议_笔记","note":"视频|00:23-02:04","orig":"（知识）曲线运动模块包含三节课：运动的合成与分解、抛体运动的性质与规律、圆周运动","link":""},{"id":"phy0562","t":"曲线运动·考情与命题方向","s":"看到【判断运动的合成与分解怎么考】","c":"想到【低频单独考（小船过河选择题），重点在综合应用：与能量结合、判断运动形式；配速法是高阶延伸考点】；警惕【因直接考得少而轻视，它是基础思想方法】","src":"物一轮091.【课前必看】本讲听课建议_笔记","note":"视频|02:04-04:03","orig":"（知识）单独考查以小船过河为主（近年频率降低）；综合考查涉及能量综合及运动形式判断；电磁学配速法也用此思想","link":""},{"id":"phy0563","t":"曲线运动·关联速度分解","s":"看到【绳拉物体、斜拉船类问题需要分解速度】","c":"想到【认准物体实际（对地）运动为合运动，再按沿绳/垂直绳等方向分解分运动】；警惕【分速度方向确定错误导致合成规则用错】","src":"物一轮091.【课前必看】本讲听课建议_笔记","note":"视频|04:48","orig":"（知识）关联速度分解：将实际运动分解为分运动（如斜拉船模型），重点在分速度方向的确定与合成规则","link":""},{"id":"phy0564","t":"曲线运动·位移与路程","s":"看到【比较曲线运动的位移与路程大小】","c":"想到【位移是割线矢量、路程是弧长标量，路程总是大于位移的大小】；警惕【不能说”路程大于位移”——位移是矢量路程是标量，必须说”位移的大小”】","src":"物一轮092.了解曲线运动的特点_笔记","note":"视频|01:32-03:30","orig":"（知识）位移为初位置指向末位置的有向线段（割线方向），路程为轨迹实际长度，路程总大于位移的大小","link":""},{"id":"phy0565","t":"曲线运动·速度方向","s":"看到【确定曲线运动中某点的速度方向】","c":"想到【瞬时速度沿轨迹切线方向，平均速度沿两点连线的割线方向】；警惕【把平均速度方向当成切线方向】","src":"物一轮092.了解曲线运动的特点_笔记","note":"视频|03:30-09:44","orig":"（知识）平均速度 v̅=Δx/Δt 沿割线方向；瞬时速度为 Δt→0 的极限，沿轨迹该点切线方向","link":""},{"id":"phy0566","t":"曲线运动·变速性辨析","s":"看到【判断”曲线运动一定是变速/变加速运动”类说法】","c":"想到【速度方向时刻变$\\to$必是变速运动；但加速度可以恒定（平抛a=g），变加速不必然】；警惕【匀速圆周运动的”匀速”指速率不变，实为变速运动】","src":"物一轮092.了解曲线运动的特点_笔记","note":"视频|03:30-09:44","orig":"（知识）曲线运动一定是变速运动（速度方向必然改变）；但加速度不一定变化（如平抛运动加速度恒为g）","link":""},{"id":"phy0567","t":"曲线运动·加速度与合力方向","s":"看到【判断曲线运动轨迹弯曲方向或合力/加速度方向】","c":"想到【合力（加速度）必指向轨迹内侧；要转向，力必须指向凹侧，也可由速度变化量$\\Delta$v方向判断】；警惕【误以为合力沿轨迹方向】","src":"物一轮092.了解曲线运动的特点_笔记","note":"视频|09:44-14:20","orig":"（知识）加速度方向总指向轨迹内侧（凹侧）；可用 Δv=v末-v初 的方向确定；由 F合=ma，合力也必指向内侧","link":""},{"id":"phy0568","t":"曲线运动·恒力下的轨迹判断","s":"看到【恒力作用下判断物体可能的曲线轨迹】","c":"想到【判据：力必须指向轨迹内侧且不与速度共线，并且要在轨迹所有位置逐点验证】；警惕【只根据初始点判断，忽略”所有位置”的全程验证】","src":"物一轮092.了解曲线运动的特点_笔记","note":"视频|16:24-20:13","orig":"（例）恒力F作用下多个方向候选中选可能轨迹：排除指向外侧的F₂、与速度共线的F₁、仅在初始点指向内侧的F₃/F₅，唯一全程指向内侧的是F₄","link":""},{"id":"phy0569","t":"曲线运动·合力示意图选择","s":"看到【给轨迹图选正确的合力/受力示意图】","c":"想到【先排除指向外侧的、再排除与速度共线的；抛体运动合力恒为重力竖直向下且指向轨迹内侧】；警惕【混淆合力与某个分力的方向】","src":"物一轮092.了解曲线运动的特点_笔记","note":"视频|20:13-21:25","orig":"（例）抛体轨迹上选正确合力方向：排除指向外侧的B/C、与速度共线的D，选始终指向抛物线内侧的A（抛体合力即重力，恒竖直向下）","link":""},{"id":"phy0570","t":"曲线运动·圆周运动受力综合","s":"看到【圆周运动中同时判断摩擦力与合力方向】","c":"想到【滑动摩擦力沿轨迹切向与运动方向相反，合力须指向圆心；两条件分别独立检验】；警惕【合力虽指向内侧但不通过圆心的选项】","src":"物一轮092.了解曲线运动的特点_笔记","note":"视频|21:25-25:11","orig":"（例）雪橇做圆周运动：摩擦力与运动方向相反（沿轨迹切向水平），合力必须指向圆心，选C","link":""},{"id":"phy0571","t":"曲线运动·运动条件总结","s":"看到【判断物体做直线还是曲线运动】","c":"想到【核心条件：合力与速度是否共线——共线做直线运动，不共线做曲线运动】；警惕【合力为零时既非曲线也非变速】","src":"物一轮092.了解曲线运动的特点_笔记","note":"视频|25:11","orig":"（知识）运动学特征：一定是变速运动；动力学特征：合力指向轨迹内侧、力与速度方向不共线（F与v有夹角）","link":""},{"id":"phy0572","t":"运动合成与分解·蜡块实验","s":"看到【两分运动均为匀速，或一个匀速一个匀加速的合运动判断】","c":"想到【两匀速分运动合成仍是匀速直线运动；分运动有加速度则合运动为曲线，合力（加速度）指向轨迹内侧】；警惕【想当然认为合运动一定是曲线】","src":"物一轮093.知道运动合成与分解的性质_笔记","note":"视频|00:21-15:52","orig":"（例）蜡块竖直匀速上浮+玻璃管水平匀速右移→合运动为匀速直线运动；蜡块加速上浮+匀速右移→曲线轨迹（切线越来越陡，合力竖直向上）","link":""},{"id":"phy0573","t":"运动合成与分解·力与速度夹角","s":"看到【合力方向与速度方向成锐角/钝角/垂直】","c":"想到【锐角加速曲线、钝角减速曲线、垂直则速率不变只变方向】；警惕【只判断了加减速而漏了曲直，或反之】","src":"物一轮093.知道运动合成与分解的性质_笔记","note":"视频|00:21-15:52","orig":"（知识）合力与速度成锐角→加速曲线运动；成钝角→减速曲线运动；垂直→匀速率曲线运动（如匀速圆周）","link":""},{"id":"phy0574","t":"运动合成与分解·分运动求合运动","s":"看到【已知两个分运动规律，求合速度或合加速度】","c":"想到【先在各自方向独立解出 t、a、v 分量，再用平行四边形（勾股）矢量合成】；警惕【等时性——各分运动时间相同，用哪个方向求t都一样】","src":"物一轮093.知道运动合成与分解的性质_笔记","note":"视频|00:21-15:52","orig":"（例）小圆柱竖直匀速 v_y=3cm/s、水平初速零匀加速：由 y=6cm 得 t=2s，由 x=4cm 得 a=2cm/s²，v_x=at=4cm/s，合速度 v=√(v_x²+v_y²)=5cm/s","link":""},{"id":"phy0575","t":"运动合成与分解·合运动识别","s":"看到【拉船等关联问题中分不清哪个是合运动】","c":"想到【物体实际移动方向即合运动方向，先识别合运动再分解，这是速度分解的前提】；警惕【把分运动当成实际运动来分解】","src":"物一轮093.知道运动合成与分解的性质_笔记","note":"视频|15:52-18:46","orig":"（知识）合运动是物体实际发生的对地运动（肉眼可见）；分运动是合运动的分效果（类比合力与分力）","link":""},{"id":"phy0576","t":"运动合成与分解·四大性质","s":"看到【运动的合成与分解的适用依据/性质考查】","c":"想到【四大性质：等效、等时、独立、同一；定量计算核心靠等时性，由任一分运动求出时间即合运动时间】；警惕【把不同物体或不同时刻的运动合成到一起】","src":"物一轮093.知道运动合成与分解的性质_笔记","note":"视频|18:46-21:44","orig":"（知识）等效性（叠加效果相同）、等时性（分运动与合运动时间相同，定量计算关键）、独立性（各分运动互不影响）、同一性（同一物体同一时刻合成）","link":""},{"id":"phy0577","t":"运动合成与分解·独立性应用","s":"看到【平抛/水平射出与竖直下落物体比较，判断能否击中】","c":"想到【独立性：水平运动不影响竖直自由落体，两者竖直方向始终同步；等时性：t=L/v】；警惕【忽视子弹自身也在下坠而误判击中位置】","src":"物一轮093.知道运动合成与分解的性质_笔记","note":"视频|21:44-27:02","orig":"（例）子弹水平射出，积木同时下落：竖直方向两者同步自由落体，子弹始终与P点等高，击中P点，t=L/v","link":""},{"id":"phy0578","t":"运动合成与分解·复杂轨迹分解","s":"看到【螺旋线等复杂组合轨迹求时间或速度】","c":"想到【把复杂运动分解为简单直线+圆周等分运动，用等时性联系各分运动，矢量合成求合速度】；警惕【试图对复杂轨迹直接套轨迹方程】","src":"物一轮093.知道运动合成与分解的性质_笔记","note":"视频|27:02","orig":"（例）滑块做螺旋运动：竖直分运动为自由落体 h=½gt²，水平分运动匀速圆周，t=√(2h/g)，合速度 v合=√(v₀²+2gh)","link":""},{"id":"phy0579","t":"小船过河·三个速度的定义","s":"看到【小船过河题中区分水速、船速、合速度】","c":"想到【v合=v水+v船 矢量合成；船速方向可控、水速方向固定，实际轨迹由合速度决定】；警惕【把船速当成船对地速度】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|00:27-03:01","orig":"（知识）v水：水流速度恒沿下游；v船：船在静水中的速度，大小不变方向可变；v合：v水与v船的矢量和，决定实际轨迹","link":""},{"id":"phy0580","t":"小船过河·最短时间原理","s":"看到【求过河的最短时间】","c":"想到【用等时性与分解：时间仅取决于垂直河岸分量，水速无垂直分量，只需最大化船速的垂直分量】；警惕【误以为水流会影响过河时间】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|03:01-09:07","orig":"（知识）将运动分解为平行/垂直河岸分量，过河时间仅由垂直分量决定，t=d/v⊥，需最大化垂直河岸速度","link":""},{"id":"phy0581","t":"小船过河·最短时间结论","s":"看到【最短时间过河的船头指向与实际路径】","c":"想到【船头垂直河岸，t_min=d/v船，与水速无关；实际轨迹由合速度决定，斜向下游】；警惕【混淆船头方向与实际运动（合速度）方向】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|09:07-13:38","orig":"（知识）船头垂直河岸时 t_min=d/v船；实际轨迹斜向下游，合速度与河岸夹角 tanθ=v船/v水","link":""},{"id":"phy0582","t":"小船过河·最短路径（v船>v水）","s":"看到【船速大于水速，求垂直过河/最短位移】","c":"想到【让合速度垂直河岸，船头向上游偏转使船速水平分量抵消水流：v船sin$\\theta$=v水，cos$\\theta$=v水/v船】；警惕【前提是 v船>v水，否则无解】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|13:38-16:42","orig":"（知识）v合垂直河岸时路径最短 x_min=d；船头偏上游，cosθ=v水/v船，t=d/(v船cosθ)=d/√(v船²-v水²)","link":""},{"id":"phy0583","t":"小船过河·最短路径（v船<v水）","s":"看到【船速小于水速，求被冲向下游的最小距离】","c":"想到【不能垂直过河；令合速度方向尽可能接近垂直，几何极值条件 v合$\\perp$v船，用相似三角形求 x_min=(v水/v船)d】；警惕【误套 cos$\\theta$=v水/v船 的公式】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|17:45-25:17","orig":"（知识）船必被冲向下游无法垂直过河；使合速度与圆相切时最优，此时 v合⊥v船，相似三角形得 x_min=(v水/v船)d","link":""},{"id":"phy0584","t":"小船过河·矢量圆法","s":"看到【过河类极值问题（任意速度比）】","c":"想到【画速度矢量圆：以恒矢量为基础，可变矢量为半径作圆，相切即极值，形成直角三角形求解】；警惕【凭感觉调角度而不画矢量图找极值】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|18:18-25:17","orig":"（知识）以v水为基准矢量、v船为半径画圆（大小不变方向可变），合速度为v水末端指向圆周的矢量，v合与圆相切时路径最短","link":""},{"id":"phy0585","t":"小船过河·往返时间比","s":"看到【往返分别取最短时间与最短路径，给时间关系反求速度】","c":"想到【两类过河公式联立消 t：区分 t_min=d/v船 与 t=d/√(v船^{2}-v水^{2})，再按比值解出船速】；警惕【两种模型的时间公式互相混淆】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|25:17-30:38","orig":"（例）去程最短时间与回程最短路径时间比为k，由 t=d/v船 与 t=d/√(v船²-v水²) 联立得 v船=v水/√(1-k²)","link":""},{"id":"phy0586","t":"小船过河·骑马射箭类比","s":"看到【骑马射箭等平动载体+发射类问题】","c":"想到【识别为小船过河同构模型：载体速度类比水速、射出速度类比船速；最短时间对应射出方向垂直靶面】；警惕【按瞄准靶心方向计算最短时间】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|30:38-35:04","orig":"（例）马速v₁类比水速、箭速v₂类比船速、靶距d类比河宽；最短时间 t_min=d/v₂，瞄准点提前 L=(v₁/v₂)d","link":""},{"id":"phy0587","t":"小船过河·危险区规避","s":"看到【求避开下游危险区的最小船速】","c":"想到【临界条件：轨迹与危险区边界相切，列几何关系求临界角，v船_min=v水·sin$\\alpha$；速度矢量三角形中船速垂直合速度时取最小】；警惕【忽略几何约束直接套公式】","src":"物一轮094.处理小船过河问题_笔记","note":"视频|35:04","orig":"（例）危险区边界与轨迹相切：tanθ=100/(100√3)得θ=30°，v船=v水sinθ=4×½=2m/s，方向与河岸成60°","link":""},{"id":"phy0588","t":"关联速度·绳杆核心原理","s":"看到【绳或杆连接的两物体，求速度关系】","c":"想到【沿绳（杆）方向速度分量相等；把各端点实际速度分解为沿绳与垂直绳两个分量，沿绳分量传长度变化、垂直分量改变角度】；警惕【弹簧可形变，不满足沿绳等速】","src":"物一轮095.处理关联速度分解问题_笔记","note":"视频|01:11-08:21","orig":"（知识）沿绳/杆方向速度大小相等，原因是绳杆不可伸长（区别于可形变的弹簧）；端点速度分解为沿绳分量 v∥（改变绳长）与垂直绳分量 v⊥（改变角度）","link":""},{"id":"phy0589","t":"关联速度·绳拉船/滑轮模型","s":"看到【绳一端收放速度已知，求另一端物体（如船）的速度】","c":"想到【将物体实际（对地）速度沿绳、垂直绳分解，令沿绳分量等于绳端速度列方程】；警惕【cos$\\theta$与sin$\\theta$的位置关系弄反】","src":"物一轮095.处理关联速度分解问题_笔记","note":"视频|01:11-08:21","orig":"（例）绳左端点速度v₀，船速水平：分解得 v∥=v船cosθ，由 v₀=v船cosθ 得 v船=v₀/cosθ","link":""},{"id":"phy0590","t":"关联速度·车拉重物模型","s":"看到【车通过跨绳/滑轮拉重物，求重物速度】","c":"想到【重物速度等于车速度沿绳方向的分量，分解对象是车的实际运动】；警惕【把垂直绳分量当成重物速度】","src":"物一轮095.处理关联速度分解问题_笔记","note":"视频|08:21-10:52","orig":"（例）车以v_B水平向左运动，分解得 v∥=v_Bsinθ，重物速度即沿绳速度分量 v_Bsinθ","link":""},{"id":"phy0591","t":"关联速度·曲柄连杆特殊位形","s":"看到【杆连接系统处于垂直或共线特殊位形】","c":"想到【特殊位形下先看端点速度的沿杆分量：端点速度与杆垂直时其沿杆分量为0，另一端速度必为0；逐位形分析不套通式】；警惕【对特殊位置仍盲目套一般公式】","src":"物一轮095.处理关联速度分解问题_笔记","note":"视频|10:52-15:32","orig":"（例）曲柄连杆活塞：OP⊥OQ时沿杆分量相等，活塞速度 v=v₀；O、P、Q共线时P点沿杆分量为0，活塞速度 v=0","link":""},{"id":"phy0592","t":"关联速度·接触面关联","s":"看到【两物体通过接触面关联（如杆靠球/物块沿斜面滑）】","c":"想到【垂直接触面（法向）方向速度相等才能保持接触；把两物体速度各分解出法向分量令其相等】；警惕【该用”垂直接触面”却错用”沿绳”原则】","src":"物一轮095.处理关联速度分解问题_笔记","note":"视频|15:51-20:06","orig":"（例）物体沿半圆球滑动，球速v₀恒定：v₀cosθ=v杆sinθ，得 v杆=v₀cotθ","link":""},{"id":"phy0593","t":"关联速度·结合圆周运动","s":"看到【关联速度与杆的转动/铰链结合的题目】","c":"想到【先用关联速度求接触点线速度，再用同轴转动角速度相同 v=$\\omega$L 传递到目标点】；警惕【忽略同轴转动各点角速度相等】","src":"物一轮095.处理关联速度分解问题_笔记","note":"视频|20:06","orig":"（例）铰链杆与滑槽圆柱：圆柱速度v分解得 v⊥=vsinθ 传给杆上B点，同轴转动 ω=v·sinθtanθ/R，A点速度 v_A=ωL，结果 v_Lsin²θ/(Rcosθ)","link":""},{"id":"phy0594","t":"力与运动·加速度的分解","s":"看到【判断速度大小/方向各自如何变化】","c":"想到【分解加速度：a∥决定加速减速（同向加速、反向减速），a$\\perp$决定是否转弯做曲线】；警惕【以为加速度只能改变速度大小】","src":"物一轮096.学会运动运动与相互作用观念判断运动_笔记","note":"视频|01:32-05:20","orig":"（知识）a可分解为a∥（与v共线，改变速度大小）和a⊥（垂直v，改变速度方向）；直线运动 a⊥=0，曲线运动 a⊥≠0，匀速率曲线运动 a∥=0且a⊥≠0","link":""},{"id":"phy0595","t":"力与运动·合力为零","s":"看到【物体合力为零的运动状态判断】","c":"想到【平衡状态：静止或匀速直线运动】；警惕【匀速圆周运动速度方向在变，合力不为零，不属于此类】","src":"物一轮096.学会运动运动与相互作用观念判断运动_笔记","note":"视频|05:31-06:04","orig":"（知识）合力为零：保持静止或匀速直线运动（平衡状态），速度大小方向均不变","link":""},{"id":"phy0596","t":"力与运动·三维度判断口诀","s":"看到【由受力情况全面判断运动形式（匀变速？直线？加减速？）】","c":"想到【三问依次判断：合力恒定否$\\to$定匀变；F$\\perp$是否为零$\\to$定曲直；F∥与v的夹角$\\to$定加减速（锐角加速、钝角减速、垂直匀速率）】；警惕【三个维度混淆着看】","src":"物一轮096.学会运动运动与相互作用观念判断运动_笔记","note":"视频|06:04-09:05","orig":"（知识）合力不为零时：匀变/非匀变看合力是否恒定；直线/曲线看F⊥是否为零；加速/减速看F∥与速度方向关系。口诀：匀变看F恒，曲直看F⊥，加减看F∥方向；锐角加速，钝角减速，垂直只变向","link":""},{"id":"phy0597","t":"力与运动·恒力最小值问题","s":"看到【恒力F加重力实现某种运动形式，求F的最小值】","c":"想到【画力矢量三角形：当F与合力方向垂直时F最小；按目标运动的合力方向要求列几何关系求极值】；警惕【F的方向任意取导致漏掉最小值条件】","src":"物一轮096.学会运动运动与相互作用观念判断运动_笔记","note":"视频|09:05-24:53","orig":"（例）恒力F与重力实现指定运动求F最小值：匀减速直线 F_min=mg·sinθ（a=g·cosθ）；类平抛 F_min=mg·cosθ（a=g·sinθ）","link":""},{"id":"phy0598","t":"力与运动·含变力（f=kv）的运动判断","s":"看到【受力中含有随速度变化的力（如f=kv）求可能运动】","c":"想到【变力导致合力变化$\\to$不可能是匀变速；再按约束逐项排除，唯一可行解常为变力恰好平衡的匀速状态，用矢量三角形求参数】；警惕【默认物体仍做匀变速运动】","src":"物一轮096.学会运动运动与相互作用观念判断运动_笔记","note":"视频|09:05-24:53","orig":"（例）新增与速度垂直的变力f=kv，约束沿v方向直线运动：变力使合力变化排除匀变速，又使F⊥变化排除非匀变速直线，唯一可行是三力平衡匀速，矢量三角形垂线段最短得 k=mg·sinθ/v","link":""},{"id":"phy0599","t":"力与运动·直线运动受力反推","s":"看到【物体做加速直线运动，反推某个未知力（如空气作用力）的方向】","c":"想到【直线运动要求合力沿轨迹方向：F∥与v同向产生加速、F$\\perp$=0不转弯；用矢量合成逐一验证候选力】；警惕【把空气作用力当成单一方向的力；忽略”加速直线”对合力方向的限制】","src":"物一轮096.学会运动运动与相互作用观念判断运动_笔记","note":"视频|24:53-27:36","orig":"（例）鸟沿虚线斜向上加速飞行：合力须沿轨迹方向（与v同向）且无垂直分力，只有F₂与重力的合力满足，选B","link":""},{"id":"phy0600","t":"力与运动·曲线运动受力反推","s":"看到【给曲线轨迹图选正确的速度/合力方向】","c":"想到【速度沿轨迹切线方向；合力分解为切向分量（改变速率）与法向分量（指向内侧改变方向）逐点验证】；警惕【合力与速度反向（减速）或未沿切线的选项】","src":"物一轮096.学会运动运动与相互作用观念判断运动_笔记","note":"视频|27:36-30:13","orig":"（例）导弹沿曲线飞行：速度始终沿轨迹切线，合力分解为F∥（与v同向产生加速）+F⊥（指向轨迹内侧改变方向），为加速曲线运动，选D","link":""},{"id":"phy0601","t":"力与运动·判断总框架","s":"看到【”由受力判断运动”或”由运动反推受力”的综合题】","c":"想到【框架：F=0平衡；共线看F恒否定匀变性；不共线必曲线、夹角定加减速。口诀：直看共线曲看垂直，加速同向减速反向，恒力匀变变力非匀】；警惕【不先定轨迹就分析速率变化】","src":"物一轮096.学会运动运动与相互作用观念判断运动_笔记","note":"视频|30:13","orig":"（知识）F=0→静止或匀速直线；F≠0共线：F恒定→匀变速直线、F变化→非匀变速直线；F≠0不共线→必然曲线，F与v夹角定加减速。应用：先定轨迹→再定速率变化→最后反推受力","link":""},{"id":"phy0602","t":"曲线运动·抛体运动概述","s":"看到【平抛/斜抛运动的运动学选择题】","c":"想到【属匀变速曲线运动，用运动的合成与分解处理，优先分解为水平与竖直两个分运动】；警惕【综合解答题常与非重力场结合】","src":"物一轮097.【课前必看】本讲听课建议_笔记","note":"视频|05:03-06:40","orig":"（知识）抛体运动（平抛、斜抛等）是高中五大典型运动之一（匀变速曲线运动的代表），高考考频极高，几乎每套卷至少1题，分值3-5分","link":""},{"id":"phy0603","t":"曲线运动·考向分析","s":"看到【带电粒子在电场中偏转的解答题】","c":"想到【按类平抛模型处理：沿初速度方向匀速直线、沿合力方向初速为零的匀加速直线】","src":"物一轮097.【课前必看】本讲听课建议_笔记","note":"视频|06:40-07:43","orig":"（知识）抛体运动单独考查主要形式为选择题（基本规律）；综合考查为解答题，常见组合是与电场中带电粒子运动结合（类平抛）","link":""},{"id":"phy0604","t":"曲线运动·平抛运动基本规律","s":"看到【求平抛运动的时间或水平射程】","c":"想到【时间由下落高度唯一决定 t=√(2y/g)，与初速度v_{0}无关；水平位移x=v_{0}t】；警惕【水平位移大$\\neq$时间长】","src":"物一轮097.【课前必看】本讲听课建议_笔记","note":"视频|09:10","orig":"（知识）平抛处理核心：位移、速度分解（水平匀速+竖直自由落体），关键是时间与高度关系、水平射程公式","link":""},{"id":"phy0605","t":"曲线运动·斜面模型下的平抛","s":"看到【从斜面水平抛出又落回斜面】","c":"想到【斜面倾角=位移偏角，tan$\\theta$=gt/(2v_{0})，可解出时间与各位移】；警惕【区分位移角与速度角两种模型】","src":"物一轮097.【课前必看】本讲听课建议_笔记","note":"视频|09:10","orig":"（知识）斜面上平抛的分解与落点分析，斜面倾角对运动轨迹的影响是核心","link":""},{"id":"phy0606","t":"曲线运动·类平抛与斜抛","s":"看到【斜抛运动求最高点速度、射程或飞行时间】","c":"想到【水平竖直分解：水平匀速、竖直上抛；用时间对称性与速度对称性，最高点速度=水平分速度$\\neq$0】；警惕【误认为最高点速度为零】","src":"物一轮097.【课前必看】本讲听课建议_笔记","note":"视频|09:10","orig":"（知识）非重力场（如电场）中的类平抛；斜抛初速度分解，利用斜抛对称性（最高点速度、射程）","link":""},{"id":"phy0607","t":"曲线运动·平抛临界问题","s":"看到【平抛中”恰好不触网/不越界/恰好落在某点”类临界条件】","c":"想到【先找边界状态列方程确定临界值，再写取值范围】；警惕【多物体相遇需同时满足各自的位置与时间关系】","src":"物一轮097.【课前必看】本讲听课建议_笔记","note":"视频|09:10","orig":"（知识）边界条件分析（如最小初速度、最大高度）；多物体平抛相遇问题","link":""},{"id":"phy0608","t":"平抛运动·定义与性质","s":"看到【物体以水平初速度抛出且只受重力】","c":"想到【平抛=匀变速曲线运动，加速度恒为g、方向竖直向下】；警惕【加速度恒定但速度方向时刻变化】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|00:27-01:44","orig":"（知识）定义：具有水平初速度v₀且仅受重力的运动；a=g恒定竖直向下，属匀变速曲线运动，轨迹为抛物线，速度沿切线方向","link":""},{"id":"phy0609","t":"平抛运动·速度变化量","s":"看到【比较平抛运动在相同时间间隔内的速度变化量】","c":"想到【$\\Delta$v=g$\\Delta$t，由加速度定义a=$\\Delta$v/$\\Delta$t决定，与v_{0}无关】；警惕【$\\Delta$v是矢量差，方向竖直向下】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|02:18-05:57","orig":"（知识）Δv=gt，方向竖直向下与加速度相同；相等时间间隔内Δv大小相等，与初速度v₀无关","link":""},{"id":"phy0610","t":"平抛运动·分解规律","s":"看到【求平抛某时刻的速度或位移】","c":"想到【先由竖直方向求时间t，再代入水平方向求位移；合速度v=√(v_{0}^{2}+v_$y^2$)用勾股合成】；警惕【矢量合成不能直接相加】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|05:57-07:44","orig":"（知识）正交分解：水平匀速（vₓ=v₀，x=v₀t）、竖直自由落体（v_y=gt，y=½gt²，v_y²=2gy）；时间t是联系两分运动的桥梁","link":""},{"id":"phy0611","t":"平抛运动·基本规律应用","s":"看到【平抛与动能结合比较两次抛出】","c":"想到【E∝v^{2}，只需分别解出两过程的速度v^{2}之比即可得动能比】；警惕【时间由各自下落高度独立确定】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|07:44-25:27","orig":"（例）v₀=25m/s水平飞出，x=25m：x=v₀t得t=1s，h=½gt²=5m；另一题坑宽3h、高差0.5h，两次平抛由v²之比得E₂/E₁=18","link":""},{"id":"phy0612","t":"平抛运动·多轨迹比较","s":"看到【比较多个平抛运动的时间、初速度或末速度】","c":"想到【先由高度定时间，再由x=v_{0}t定初速度；末速度合成v=√(v_{0}^{2}+(gt)^{2})】；警惕【不能仅凭水平位移判断初速度大小】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|25:27-42:59","orig":"（例）三条轨迹比较：由h=½gt²知高度越大时间越长，t₁>t₂>t₃；再由x=v₀t结合水平位移定初速度；A(2l高、位移l)与B(l高、位移2l)对比中末速度需合成竖直分速度判断","link":""},{"id":"phy0613","t":"平抛运动·角度求时间与推论1","s":"看到【平抛中已知速度方向或位移方向】","c":"想到【角度与时间一一对应，用tan$\\alpha$=gt/v_{0}或tan$\\beta$=gt/(2v_{0})直接求t】；警惕【是正切值2倍关系，不是角度本身2倍】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|42:59-48:43","orig":"（知识）tanα=gt/v₀（速度偏角），tanβ=y/x=gt/(2v₀)（位移偏角），故tanα=2tanβ；已知角度可唯一确定时间t","link":""},{"id":"phy0614","t":"平抛运动·推论2（反向延长线）","s":"看到【判断平抛能否垂直撞击某曲面】","c":"想到【用推论”速度反向延长线必过水平位移中点”做几何判定，垂直撞击时反向延长线应过圆心/接触面特殊点】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|53:58-01:01:55","orig":"（例）半圆环平抛：竖直分速度由2gh=v²定（C点下落最高故v_y最大）；假设垂直撞击则速度反向延长线过圆心（AB中点），几何上无此位置，故不可能垂直撞击","link":""},{"id":"phy0615","t":"平抛运动·双物体几何法","s":"看到【两个平抛物体速度方向已知，求抛出点或几何量】","c":"想到【用”速度反向延长线过水平位移中点”建几何关系，避免多方程联立】；警惕【与竖直墙的夹角和速度与水平方向夹角互补，正切值勿取反】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|01:01:55-01:10:16","orig":"（例）双飞镖：两飞镖速度反向延长线交点即各自水平位移中点，由y_A=(x/2)/tan53°、y_B=(x/2)/tan37°、y_B−y_A=d解得x","link":""},{"id":"phy0616","t":"平抛运动·方法选择","s":"看到【平抛问题选择解法】","c":"想到【有高度优先t=√(2h/g)；有角度用角度法；无特殊条件用水平竖直联立】；警惕【混淆位移偏角tan$\\beta$=y/x与速度偏角tan$\\alpha$=v_y/v_{0}】","src":"物一轮098.掌握平抛运动的基本规律_笔记","note":"视频|01:10:16","orig":"（知识）基础法：水平竖直联立方程，普适性强；技巧法：由角度求时间，简便但需熟记公式；优先用高度求时间","link":""},{"id":"phy0617","t":"平抛斜面模型·落回斜面","s":"看到【从斜面水平抛出又落回斜面】","c":"想到【位移偏角正切=斜面倾角：tan$\\theta$=gt/(2v_{0})，先求时间再求位移与速度】；警惕【速度偏角是位移偏角正切的2倍，不是角度的2倍】","src":"物一轮099.掌握斜面模型下平抛运动的处理方法_笔记","note":"视频|00:54-07:47","orig":"（知识）从斜面水平抛出又落回斜面：斜面倾角θ=位移偏角，tanθ=gt/(2v₀)，t=2v₀tanθ/g；x=2v₀²tanθ/g，y=2v₀²tan²θ/g；速度偏角满足tanα=2tanθ","link":""},{"id":"phy0618","t":"平抛斜面模型·速度垂直斜面","s":"看到【平抛小球速度垂直射向斜面】","c":"想到【速度偏角$\\alpha$与斜面倾角互余，tan$\\alpha$=gt/v_{0}求t】；警惕【区分”速度垂直斜面”（用速度角gt/v_{0}）与”位移垂直斜面”（用位移角gt/2v_{0}）】","src":"物一轮099.掌握斜面模型下平抛运动的处理方法_笔记","note":"视频|07:47-10:10","orig":"（知识）速度垂直斜面时，速度与水平方向夹角α=90°−θ，tanα=gt/v₀，得t=v₀cotθ/g；此处用速度角而非位移角","link":""},{"id":"phy0619","t":"平抛斜面模型·位移最短","s":"看到【平抛小球与斜面碰撞且位移最短】","c":"想到【位移垂直斜面$\\to$位移偏角与倾角互余，用tan$\\varphi$=gt/(2v_{0})求t】；警惕【与速度垂直模型的公式易混】","src":"物一轮099.掌握斜面模型下平抛运动的处理方法_笔记","note":"视频|10:10-12:20","orig":"（知识）位移方向与斜面垂直时位移最小（垂线段最短）：位移偏角φ=90°−θ，tanφ=gt/(2v₀)，t=2v₀cotθ/g","link":""},{"id":"phy0620","t":"平抛斜面模型·落点验证","s":"看到【平抛初速度变化后判断落点位置】","c":"想到【先按斜面模型算新水平位移，验证是否超出斜面长度；超出则脱离斜面落到地面，按实际下落高度重新求时间】；警惕【不能默认速度变化后仍落在斜面上】","src":"物一轮099.掌握斜面模型下平抛运动的处理方法_笔记","note":"视频|12:20-18:37","orig":"（例）钢球以v₀抛出落在斜挡板中点，tanθ=gt/(2v₀)；速度变为2v₀时按斜面算水平位移为4倍但挡板有限，实际落到地面，由下落高度翻倍得t′=√2·t","link":""},{"id":"phy0621","t":"平抛斜面模型·垂直撞击","s":"看到【求垂直撞击斜面的时间或撞击速度】","c":"想到【构建速度矢量三角形（水平v_{0}、竖直gt），用特殊角三角函数快速求解】；警惕【合速度方向夹角与斜面倾角互余】","src":"物一轮099.掌握斜面模型下平抛运动的处理方法_笔记","note":"视频|18:37-20:47","orig":"（例）速度垂直斜面、夹角60°：tan60°=gt/v₀得t=√3v₀/g；撞击速度v=v₀/cos60°=2v₀；可构建速度矢量三角形用30°-60°-90°特性求解","link":""},{"id":"phy0622","t":"平抛斜面模型·离斜面最大距离","s":"看到【求平抛物体离斜面的最大距离】","c":"想到【沿斜面+垂直斜面建坐标系分解：垂直方向是初速v_{0}sin$\\theta$、加速度gcos$\\theta$的匀减速，速度减为零时距离最大】；警惕【坐标系按问题需求选择，不必拘泥水平竖直】","src":"物一轮099.掌握斜面模型下平抛运动的处理方法_笔记","note":"视频|20:47","orig":"（例）沿斜面和垂直斜面建系：垂直斜面方向初速v₀sinθ、加速度gcosθ做匀减速，0=v₀sinθ−(gcosθ)t得t=v₀tanθ/g，此时刻离斜面最远","link":""},{"id":"phy0623","t":"类平抛与斜抛·类平抛定义","s":"看到【合力恒定且与初速度方向垂直的运动】","c":"想到【按类平抛处理：沿初速度方向匀速直线、垂直初速度方向初速为零的匀加速直线】；警惕【垂直方向不是自由落体，加速度由合力决定】","src":"物一轮100.学会处理类平抛运动_笔记","note":"视频|00:44-00:56","orig":"（知识）类平抛：合力恒定且与初速度方向垂直的运动；”类”指运动特征与平抛相似但受力可含重力外的其他力","link":""},{"id":"phy0624","t":"类平抛与斜抛·斜面类平抛","s":"看到【小球在光滑斜面上有水平初速度（立体装置）】","c":"想到【降维成平面（侧视图）受力分析，合力mgsin$\\theta$提供加速度a=gsin$\\theta$，再沿初速度与垂直方向分解运动】；警惕【4m/s这类改变后的初速度会改变落点，需重新验证】","src":"物一轮100.学会处理类平抛运动_笔记","note":"视频|00:56-10:20","orig":"（例）光滑斜面上小球以v₀水平运动：降维作侧视图，受mg与支持力N，合力mgsinθ沿斜面向下，a=gsinθ（θ=30°时a=5m/s²）；b=v₀t与a′=½at²联立解出t与v₀","link":""},{"id":"phy0625","t":"类平抛与斜抛·含额外恒力的斜抛","s":"看到【斜抛/抛体受风力、电场力等额外恒力】","c":"想到【先合成重力与恒力，若合力与初速度垂直则按类平抛解，计算大幅简化】；警惕【漏掉非重力恒力或误判合力方向】","src":"物一轮100.学会处理类平抛运动_笔记","note":"视频|10:20","orig":"（例）物体受重力mg与风力合成，合力(2√3/3)mg与初速度垂直：沿初速方向匀速vₓ=v，垂直方向v_y=at，由末速度2v=√(v²+v_y²)解出t，避免常规分解需解二次方程","link":""},{"id":"phy0626","t":"类平抛与斜抛·降维思想","s":"看到【立体装置中的曲线运动问题】","c":"想到【降维：选侧视图/俯视图把空间问题化为平面问题，再做受力分析与运动分解】","src":"物一轮100.学会处理类平抛运动_笔记","note":"视频|10:20","orig":"（知识）将立体受力问题转化为平面视图（侧视图、俯视图）简化分析，优先选能直观展示受力与运动关系的视角","link":""},{"id":"phy0627","t":"类平抛与斜抛·斜抛运动分解","s":"看到【初速度斜向上且仅受重力的抛体】","c":"想到【水平竖直分解：水平匀速+竖直上抛，利用对称性求最高点、射程、飞行时间】；警惕【最高点速度$\\neq$0（保留水平分速度）】","src":"物一轮101.学会处理斜抛运动_笔记","note":"视频|00:44-08:53","orig":"（知识）斜抛属匀变速曲线运动（a=g恒定竖直向下）：水平方向匀速（vₓ不变）、竖直方向竖直上抛（初速度v_y、加速度g），可用时间对称性与速度对称性","link":""},{"id":"phy0628","t":"类平抛与斜抛·最大高度与落点比较","s":"看到【两个斜抛（或平抛与斜抛）最大高度相同比较其他量】","c":"想到【高度相同$\\to$竖直初速度相同$\\to$飞行时间相同；再由水平位移比较vₓ，最高点速度即vₓ】；警惕【误认为最高点速度为零】","src":"物一轮101.学会处理斜抛运动_笔记","note":"视频|00:44-08:53","orig":"（知识）最大高度相同⇒竖直初速度v_y相同；水平位移大⇒水平分速度vₓ大；落地速度v=√(vₓ²+v_y²)","link":""},{"id":"phy0629","t":"类平抛与斜抛·轨迹交点辨析","s":"看到【两条抛体轨迹相交，判断是否相遇】","c":"想到【轨迹交点只是位置相同，到达时间由各自运动独立决定】；警惕【混淆轨迹交点与相遇点】","src":"物一轮101.学会处理斜抛运动_笔记","note":"视频|08:53-14:29","orig":"（例）谷粒1平抛、谷粒2斜抛，加速度均为g：轨迹相交≠同时到达（可先后通过同一点）；水平位移相同时斜抛总时间更长，故斜抛最高点速度v₂ₓ<v₁","link":""},{"id":"phy0630","t":"类平抛与斜抛·斜向坐标系分解","s":"看到【求抛体离某条斜线（位移连线）的最远距离】","c":"想到【沿目标方向建坐标系，分别分解初速度与重力加速度，垂直方向速度减为零时距离最大】；警惕【竖直方向规定正方向后v_y与g的正负号处理】","src":"物一轮101.学会处理斜抛运动_笔记","note":"视频|14:29-25:18","orig":"（例）山东真题：v₀=20m/s与水平成30°，落点连线PQ与水平成30°（x=√3y），解得t=4s；求离PQ最远距离时沿PQ建系，g分解为沿PQ的5m/s²与垂直的5√3m/s²，垂直方向速度为零时最远","link":""},{"id":"phy0631","t":"类平抛与斜抛·抛体运动总结","s":"看到【任一抛体类运动问题】","c":"想到【先判定类型：平抛水平竖直分解、类平抛沿初速度方向分解、斜抛水平竖直分解并注意正方向】；警惕【类平抛的判定条件是合力与初速度垂直，不限于重力】","src":"物一轮101.学会处理斜抛运动_笔记","note":"视频|25:18","orig":"（知识）平抛（初速水平仅受重力）、类平抛（合力恒定且垂直初速）、斜上抛（初速斜向上仅受重力）均为匀变速曲线运动，均用运动合成与分解处理","link":""},{"id":"phy0632","t":"平抛临界·速度范围（双临界）","s":"看到【球类平抛”既不触网也不越界”求速度范围】","c":"想到【双临界法：最小速度对应恰好触网、最大速度对应恰好压底线，各列水平竖直方程解出临界v_{0}，范围夹在两值之间】；警惕【水平位移要分段相加（离网距离+半场）】","src":"物一轮102.学会处理平抛运动中的临界问题_笔记","note":"视频|00:59-08:37","orig":"（例）排球：网高2.25m、击球点高2.5m、离网3m、半场9m——最小速度恰好触网（d=v₁t₁，H−h=½gt₁²，v₁=6√5m/s）；最大速度恰好压底线（d+L=v₂t₂，H=½gt₂²，v₂=12√2m/s）","link":""},{"id":"phy0633","t":"平抛临界·临界高度","s":"看到【求”无论v_{0}多大都不可能正常过网且不出界”的临界高度】","c":"想到【临界高度=触网条件与压线条件同时成立，用同一v_{0}联立两组方程消去v_{0}和t解H】；警惕【这是”无解区间”的边界，不是最佳击球点】","src":"物一轮102.学会处理平抛运动中的临界问题_笔记","note":"视频|08:37-15:39","orig":"（例）击球高度H未知：令同一v₀同时满足触网方程（d=v₀t₁，H−h=½gt₁²）与压线方程（d+L=v₀t₂，H=½gt₂²），消元解得H=2.4m；H低于此值则无v₀能正常过网落界内","link":""},{"id":"phy0634","t":"平抛临界·台阶平抛","s":"看到【平抛物体落在台阶/楼梯上求落在第几级】","c":"想到【把离散台阶转化为连续斜面：tan$\\theta$=台阶高/宽=gt/(2v_{0})求时间t，再x=v_{0}t定落点级数】；警惕【用x除以台阶宽度判断级数时注意边界】","src":"物一轮102.学会处理平抛运动中的临界问题_笔记","note":"视频|15:39-24:52","orig":"（例）台阶高0.15m、宽0.2m，v₀=3m/s：tanθ=h/d=3/4=gt/(2v₀)得t=0.45s，x=1.35m，位于第6、7级台阶之间，落在第7级","link":""},{"id":"phy0635","t":"平抛临界·相切型最小速度","s":"看到【平抛轨迹与斜线/圆弧”恰好相切”求最小初速度】","c":"想到【相切处速度方向沿切线（与该线平行），由速度角得vy与v_{0}关系，再配几何关系（位移差）联立求解】；警惕【易漏掉额外高度差、cm与m单位换算】","src":"物一轮102.学会处理平抛运动中的临界问题_笔记","note":"视频|24:52","orig":"（例）蛛网45°斜线：轨迹与蛛丝相切时速度最小，切点处速度方向与蛛丝平行（45°），vy=v₀=gt，x=v₀²/g，y=v₀²/(2g)，结合几何关系y+0.4=x解得v₀=2√2m/s","link":""},{"id":"phy0636","t":"平抛临界·方程消元策略","s":"看到【平抛临界多个方程联立】","c":"想到【优先消时间t，把几何约束（相切、压线）翻译成位移关系方程】；警惕【临界条件判断不准导致取值范围反向】","src":"物一轮102.学会处理平抛运动中的临界问题_笔记","note":"视频|24:52","orig":"（知识）临界问题常需多方程联立（触网+压线共四个方程），优先消去时间t；空间临界通常需找相切条件；台阶问题转化为斜面简化计算","link":""},{"id":"phy0637","t":"圆周运动·物理量换算","s":"看到【圆周运动的v、$\\omega$、T、n之间互求】","c":"想到【用v=$\\omega$r=2$\\pi$r/T=2$\\pi$rn和$a_n$=v^{2}/r=$\\omega$^{2}r一条链换算】；警惕【n（r/s）与$\\omega$（rad/s）概念不同】","src":"物一轮103.【课前必看】本讲听课建议_笔记","note":"视频|01:01-01:20","orig":"（知识）核心换算：v=ωr=2πr/T=2πrn；向心加速度aₙ=v²/r=ω²r，方向始终指向圆心","link":""},{"id":"phy0638","t":"圆周运动·传动装置","s":"看到【皮带传动或齿轮传动比较各点v、$\\omega$】","c":"想到【先抓”线速度相等”的接触点，再用v=$\\omega$r换算各轮角速度】；警惕【同一轮上各点$\\omega$相同、v∝r】","src":"物一轮103.【课前必看】本讲听课建议_笔记","note":"视频|01:20-01:35","orig":"（知识）皮带传动：边缘线速度相等，ω与半径成反比；齿轮传动：接触点线速度相等，ω与齿数成反比","link":""},{"id":"phy0639","t":"圆周运动·多解性问题","s":"看到【圆周运动与平抛等其他运动结合求相遇/穿孔时刻】","c":"想到【转动具有周期性，列通式$\\theta$=$\\omega$t+2k$\\pi$（k$\\in$Z），再结合另一运动的等时条件】；警惕【只取一组解漏掉多解】","src":"物一轮103.【课前必看】本讲听课建议_笔记","note":"视频|01:35-01:53","orig":"（知识）周期性特点θ=ωt+2kπ（k∈Z）导致多解；解题需明确物理量的周期关系，建立通解表达式","link":""},{"id":"phy0640","t":"圆周运动·向心力来源","s":"看到【求圆周运动的向心力或某力大小】","c":"想到【受力分析后把各力沿指向圆心方向投影，合力=Fₙ=mv^{2}/r=$\\omega$^{2}r】；警惕【向心力是效果力，不作为单独的力画在受力图上】","src":"物一轮103.【课前必看】本讲听课建议_笔记","note":"视频|02:18-02:34","orig":"（知识）合外力提供向心力Fₙ=mv²/r，可能由弹力、摩擦力、重力分量等提供；步骤：受力分析→正交分解→指向圆心的合力即向心力","link":""},{"id":"phy0641","t":"圆周运动·竖直圆周模型","s":"看到【竖直平面内绳/杆模型圆周运动的最高点】","c":"想到【绳（内轨道）模型最高点最小速度√(gr)（重力全部提供向心力），杆（管道）模型可为零；结合最低点用机械能守恒联系】；警惕【区分绳模型与杆模型的临界条件】","src":"物一轮103.【课前必看】本讲听课建议_笔记","note":"视频|02:34-03:15","orig":"（知识）最高点临界：绳模型v≥√(gr)，杆模型v≥0；常与机械能守恒结合，注意重力势能变化","link":""},{"id":"phy0642","t":"圆周运动·临界问题","s":"看到【绳/杆恰好断裂、物体恰好分离、摩擦力恰好突变】","c":"想到【写临界状态方程：提供的力=所需的向心力（如恰好分离时弹力N=0）】；警惕【「恰好」对应的是约束力为零的状态】","src":"物一轮103.【课前必看】本讲听课建议_笔记","note":"视频|03:15-03:44","orig":"（知识）典型情境：绳/杆断裂、接触面分离、滑动摩擦力突变；分析方法：建立临界状态方程F供=F需","link":""},{"id":"phy0643","t":"圆周运动·微元思想","s":"看到【变速率圆周运动或非完整圆弧过程分析】","c":"想到【微元：把曲线切成无数小段，每小段按匀速圆周/匀变速处理再累积】","src":"物一轮103.【课前必看】本讲听课建议_笔记","note":"视频|03:44-04:26","orig":"（知识）应用场景：变速率圆周运动、非完整圆周过程；思想本质：将曲线运动微分处理为无数小段匀速圆周运动","link":""},{"id":"phy0644","t":"圆周运动·线量（线速度）","s":"看到【求圆周运动某点的瞬时线速度】","c":"想到【v=$\\Delta$l/$\\Delta$t（微元下弦长≈弧长），方向沿该点切线】","src":"物一轮104.描述圆周运动的物理量_笔记","note":"视频|02:11-02:29","orig":"（知识）微元思想：Δt足够小时弦长Δx≈弧长Δl，瞬时线速度v=Δl/Δt；方向始终沿切线方向","link":""},{"id":"phy0645","t":"圆周运动·角量与线量转换","s":"看到【弧度、角速度、角加速度与弧长、线速度互求】","c":"想到【所有角量转线量都乘半径r（v=$\\omega$r，a=$\\alpha$r），l=$\\theta$r】；警惕【弧度无量纲，rad/s可写为s^{-1}】","src":"物一轮104.描述圆周运动的物理量_笔记","note":"视频|02:29-09:44","orig":"（知识）弧长l=θr（弧度制）；角速度ω=Δθ/Δt（单位rad/s或s⁻¹）；角加速度α=Δω/Δt（rad/s²）；角量转线量一律乘半径r：v=ωr，a=αr","link":""},{"id":"phy0646","t":"圆周运动·周期与转速","s":"看到【已知周期T或转速n求v、$\\omega$】","c":"想到【n=1/T，$\\omega$=2$\\pi$/T=2$\\pi$n；掌握v=$\\omega$r与$\\omega$=2$\\pi$/T即可推导其余】；警惕【比较对象是n还是$\\omega$需明确区分，勿把r/s当rad/s】","src":"物一轮104.描述圆周运动的物理量_笔记","note":"视频|11:47-15:14","orig":"（知识）周期T：转一圈的时间，v=2πr/T，ω=2π/T；转速n=1/T，ω=2πn；n单位r/s中r（圈）不可省略，与rad不同","link":""},{"id":"phy0647","t":"圆周运动·向心加速度公式","s":"看到【求匀速圆周运动的向心加速度】","c":"想到【按已知量选公式$a_n$=v^{2}/r=$\\omega$^{2}r=4$\\pi$^{2}r/T^{2}，方向恒指圆心】；警惕【向心加速度只改变速度方向，不改变大小】","src":"物一轮104.描述圆周运动的物理量_笔记","note":"视频|18:01-19:42","orig":"（知识）aₙ=v²/r=ω²r=4π²r/T²=ωv；方向始终沿半径指向圆心（径向）","link":""},{"id":"phy0648","t":"圆周运动·加速度与向心加速度辨析","s":"看到【问圆周运动的「加速度」而非「向心加速度」】","c":"想到【先分解a∥与$a_n$再合成：a=√(a∥^{2}+$a_n$^{2})】；警惕【匀速圆周运动加速度不为零；$a_n$只是a的分量】","src":"物一轮104.描述圆周运动的物理量_笔记","note":"视频|20:09-24:53","orig":"（知识）总加速度a分解为切向a∥（改变速度大小）与径向a⊥=aₙ（改变速度方向）；匀速圆周a∥=0，a=aₙ；变速圆周两者矢量合成","link":""},{"id":"phy0649","t":"圆周运动·螺旋线运动判断","s":"看到【弧长（路程）与时间成正比的圆周运动】","c":"想到【s=kt$\\Rightarrow$速率恒定；再由v=$\\omega$r和$a_n$=v^{2}/r分析r变化引起的$\\omega$、$a_n$变化】；警惕【匀速率圆周仍有加速度（方向变化）】","src":"物一轮104.描述圆周运动的物理量_笔记","note":"视频|24:53-28:19","orig":"（例）质点沿半径减小的螺旋线运动，弧长s=kt（与时间成正比）：v恒定属匀速率圆周运动；v=ωr，r减小则ω增大；aₙ=v²/r随r减小而增大","link":""},{"id":"phy0650","t":"圆周运动·由转速求向心加速度","s":"看到【已知转速n和半径r求向心加速度】","c":"想到【$\\omega$=2$\\pi$n，$a_n$=$\\omega$^{2}r=4$\\pi$^{2}n^{2}r；可用$\\pi$^{2}≈10简化计算】；警惕【半径单位cm要换算成m】","src":"物一轮104.描述圆周运动的物理量_笔记","note":"视频|28:19-31:17","orig":"（例）转速n=50r/s、r=1cm=0.01m：ω=2πn=100πrad/s，aₙ=ω²r，用π²≈10简化得1000m/s²","link":""},{"id":"phy0651","t":"圆周运动·加速圆周运动合成","s":"看到【速率均匀增大的圆周运动求合加速度】","c":"想到【先求切向a∥=$\\Delta$v/$\\Delta$t，再求当时法向$a_n$=v^{2}/r，按勾股合成】；警惕【$a_n$必须用该时刻的瞬时速度计算，不能用初速度】","src":"物一轮104.描述圆周运动的物理量_笔记","note":"视频|31:17","orig":"（例）火车沿圆弧速率均匀增大：a∥=Δv/Δt=1/9m/s²，2分钟后v=a∥t=40/3m/s，aₙ=v²/r=2/9m/s²，合成a=5/9m/s²，方向tanθ=2","link":""},{"id":"phy0652","t":"圆周运动·同轴传动","s":"看到【两物体绕同一固定轴转动且相对位置不变】","c":"想到【同轴传动：$\\omega$相同，v=$\\omega$r∝r，$a_n$=$\\omega$^{2}r∝r】；警惕【共轴$\\neq$同轴，还须相对静止，时针与分针共轴但$\\omega$不同】","src":"物一轮105.两种传动装置_笔记","note":"视频|00:14-06:28","orig":"（知识）同轴传动：两物体绕同一固定轴旋转且保持相对静止，如转动杆上两点、圆盘上两点、地球自转的地表各点。","link":""},{"id":"phy0653","t":"圆周运动·同轴传动判断","s":"看到【判断某两点是否属于同轴传动】","c":"想到【口诀「共轴静止才同传」——公共轴与相对静止两条件缺一不可】；警惕【圆锥筒内自由滚动的球相对位置会改变，不属于同轴传动】","src":"物一轮105.两种传动装置_笔记","note":"视频|04:30-06:28","orig":"（知识）判断标准：同时满足存在公共旋转轴＋物体间相对静止；口诀「共轴静止才同传」。","link":""},{"id":"phy0654","t":"圆周运动·同源传动","s":"看到【皮带、摩擦轮、齿轮啮合等边缘接触传动（不打滑）】","c":"想到【同源传动：接触点线速度 v 相同，$\\omega$=v/r∝1/r，$a_n$=v^{2}/r∝1/r；齿轮半径与齿数成正比 r∝N】；警惕【$\\omega$_{1}/$\\omega$_{2}=N_{2}/N_{1} 是与齿数成反比，勿写成齿数正比】","src":"物一轮105.两种传动装置_笔记","note":"视频|06:38-11:15","orig":"（知识）同源传动：通过共同边缘接触传递运动，接触点线速度相同，如皮带、摩擦轮、齿轮啮合；齿轮周长 C=2πr=N·d，r∝N。","link":""},{"id":"phy0655","t":"圆周运动·两类传动对比","s":"看到【辨析同轴传动与同源（同缘）传动】","c":"想到【轴心相同看角速度，边缘接触看线速度；先识别连接方式再选比例关系】；警惕【同一装置常同时含两类关系，须逐段识别】","src":"物一轮105.两种传动装置_笔记","note":"视频|11:15-11:35","orig":"（知识）同轴：ω相同、v∝r；同源：v相同、ω∝1/r。口诀「同轴同角不同线，同源同线不同角」。","link":""},{"id":"phy0656","t":"圆周运动·自行车传动","s":"看到【自行车链条传动（大齿轮-链条-小齿轮-后轮）求转速或线速度】","c":"想到【沿传动链逐段标注：共轴段$\\omega$相同、链条段v相同，齿数比即半径比，再用 $\\omega$=2$\\pi$n、v=$\\omega$r 逐级换算】；警惕【混淆传动链中同轴/同源关系，漏掉半径比例换算】","src":"物一轮105.两种传动装置_笔记","note":"视频|11:35-18:43","orig":"（例）脚踏板与大齿轮共轴（ω相同），大齿轮经链条带小齿轮（v相同），齿数比45:15=3:1，后轮半径为小齿轮10倍；脚踏板2圈/秒时小齿轮6圈/秒，后轮与大齿轮线速度比10:1。","link":""},{"id":"phy0657","t":"圆周运动·刚体两点转动","s":"看到【同一刚体上不同半径的两点转动问题】","c":"想到【同轴转动：$\\omega$相同，v=$\\omega$r、a=$\\omega$^{2}r 均与半径成正比】；警惕【半径不等则线速度、向心加速度必不等，勿默认各量都相同】","src":"物一轮105.两种传动装置_笔记","note":"视频|18:43-19:44","orig":"（例）指尖转球：P、Q两点绕同一转轴旋转，Q点旋转半径大于P点，故ω相同而vP≠vQ、aP≠aQ。","link":""},{"id":"phy0658","t":"圆周运动·多轮皮带传动","s":"看到【多轮皮带传动装置求各轮 v、$\\omega$、T、a 之比】","c":"想到【先按同轴/同源列出两两关系，设半径比逐级传递，再由 T=2$\\pi$/$\\omega$、a=$\\omega$^{2}r 收尾】；警惕【周期与$\\omega$成反比要取倒数；a=$\\omega$^{2}r 须代入各自的$\\omega$与r】","src":"物一轮105.两种传动装置_笔记","note":"视频|19:44-","orig":"（例）皮带装置 R_A=R_C=2R_B，A与B同轴、B与C同源：v比2:1:1，ω比2:2:1，T比1:1:2，a比4:2:1。","link":""},{"id":"phy0659","t":"圆周运动·多解性本质","s":"看到【旋转圆筒/圆盘与子弹、平抛小球的相遇类问题】","c":"想到【圆周运动转过角度＝$\\theta$+2$\\pi$n（n=0,1,2…），利用等时性列方程求出一系列解】；警惕【漏掉+2$\\pi$n 项只取第一次解】","src":"物一轮106.圆周运动中的多解性问题_笔记","note":"视频|00:12","orig":"（知识）圆周运动的周期性导致同一位置可通过不同转圈数到达，时间解不唯一。","link":""},{"id":"phy0660","t":"圆周运动·子弹穿筒多解","s":"看到【子弹穿过旋转圆筒留下两孔求速度】","c":"想到【时间相等列方程 t=d/v=t_筒，速度解分母呈公差 2$\\pi$ 的等差数列，逐个 n 代入检验选项】；警惕【n=0 对应最小速度解，勿只算一次】","src":"物一轮106.圆周运动中的多解性问题_笔记","note":"视频|00:12","orig":"（例）子弹以 v 穿过直径 d 的旋转圆筒，筒壁留下相隔 θ=π/3 的两孔：t=d/v=(π/3+2πn)/ω，得 v=ωd/(π/3+2πn)，分母构成等差数列 π、7π、13π…。","link":""},{"id":"phy0661","t":"圆周运动·平抛与转盘相遇","s":"看到【平抛小球落到旋转圆盘（或转盘上某点）】","c":"想到【平抛时间与圆盘整数圈时间相等：h 由 t 决定、v_{0}=R$\\omega$/(2$\\pi$n)，n 取不同值得多解】；警惕【h 与 n^{2} 成正比、v_{0} 与 n 成反比，逐一代入验证】","src":"物一轮106.圆周运动中的多解性问题_笔记","note":"视频|00:12","orig":"（例）小球平抛 h=½gt²、R=v₀t，圆盘同期转过 t=2πn/ω，得 h=2π²gn²/ω²、v₀=Rω/(2πn)；n=2、n=4 分别对应不同选项。","link":""},{"id":"phy0662","t":"圆周运动·钟表指针重合","s":"看到【钟表分针与时针重合/成角的时刻问题】","c":"想到【圆周追及模型：$\\Delta$$\\omega$=$\\omega$_{1}−$\\omega$_{2}，再次重合需快针多转整数圈 2$\\pi$n】；警惕【圆心同侧圈数差为整数 n，圆心两侧为半整数 0.5（一般不考多次）】","src":"物一轮106.圆周运动中的多解性问题_笔记","note":"视频|00:12","orig":"（例）分针 ω=2π/h，时针 ω=π/6/h，相对角速度 Δω=11π/6 per h，重合条件 t=2πn/Δω=12n/11 小时。","link":""},{"id":"phy0663","t":"圆周运动·基本公式","s":"看到【圆周运动 v、$\\omega$、T、n 之间的换算】","c":"想到【一套公式走天下：v=$\\omega$r、$a_n$=v^{2}/r=$\\omega$^{2}r=4$\\pi$^{2}r/T^{2}，按已知量选用】；警惕【周期与转速是倒数关系，勿混用】","src":"物一轮106.圆周运动中的多解性问题_笔记","note":"视频|00:12","orig":"（知识）v=ωr，ω=2π/T，n=1/T；aₙ=v²/r=ω²r=4π²r/T²。","link":""},{"id":"phy0664","t":"圆周运动·追及相遇要点","s":"看到【两个转动物体的追及相遇（同侧或两侧）】","c":"想到【同侧相遇圈数差为整数 n，两侧相遇圈数差为 n+0.5，由圈数差$\\times$周期求时间】；警惕【只考虑第一次重合而漏解】","src":"物一轮106.圆周运动中的多解性问题_笔记","note":"视频|00:12","orig":"（知识）同侧相遇：圈数差为整数 n；两侧相遇：圈数差为(n+0.5)。","link":""},{"id":"phy0665","t":"圆周运动·综合方法","s":"看到【圆周运动与直线/平抛结合的综合多解题】","c":"想到【三步法：等时性列方程$\\to$周期性补 +2$\\pi$n 项$\\to$圈数差分析】；警惕【未考虑多解可能导致漏选】","src":"物一轮106.圆周运动中的多解性问题_笔记","note":"视频|00:12","orig":"（知识）综合题型方法：构建等时性关系、周期性叠加（+2πn）、圈数差分析三步。","link":""},{"id":"phy0666","t":"圆周运动·向心力概念","s":"看到【向心力的定义与公式选择】","c":"想到【向心力是效果力，按已知量在 mv^{2}/r、m$\\omega$^{2}r、m·4$\\pi$^{2}r/T^{2} 中选用】；警惕【受力分析图上不能单独画向心力，应说「由$\\times$$\\times$力提供」】","src":"物一轮107.寻找向心力_笔记","note":"视频|01:03-02:39","orig":"（知识）向心力 Fₙ=mv²/r=mω²r=m·4π²r/T²，方向始终沿半径指向圆心；它是效果力，由其他力共同作用产生。","link":""},{"id":"phy0667","t":"圆周运动·找向心力步骤","s":"看到【求某做圆周运动物体的向心力来源】","c":"想到【先受力分析、再找圆心、沿半径方向合成——只有径向的力（或分量）才是向心力来源】；警惕【区分实际受力与效果力，向心力总由张力、摩擦力、重力分量等性质力提供】","src":"物一轮107.寻找向心力_笔记","note":"视频|02:39-03:07","orig":"（知识）三步：确定研究对象并完整受力分析→确定圆周轨迹和圆心位置→沿半径方向的合力（或分力矢量和）提供向心力。","link":""},{"id":"phy0668","t":"圆周运动·圆柱筒内壁模型","s":"看到【物体贴在旋转圆筒（滚筒）内壁随之转动】","c":"想到【正交分解：竖直方向 f=mg 二力平衡，水平方向 N=m$\\omega$^{2}r 提供向心力】；警惕【弹力 N 是向心力唯一来源，静摩擦力只平衡重力，两者不可混淆】","src":"物一轮107.寻找向心力_笔记","note":"视频|03:07-05:22","orig":"（例）质量 m 的物体在角速度 ω 旋转的圆柱筒内保持相对静止：竖直方向静摩擦力 f 平衡重力 mg，水平方向筒壁弹力 N=mω²r 提供向心力。","link":""},{"id":"phy0669","t":"圆周运动·圆锥摆模型","s":"看到【细绳悬小球在水平面内做匀速圆周运动（圆锥摆）】","c":"想到【重力与拉力正交分解：Tcos$\\theta$=mg、Tsin$\\theta$=m$\\omega$^{2}r，联立得 $\\omega$=√(g/(Lcos$\\theta$))】；警惕【转动半径是 r=Lsin$\\theta$ 而非绳长 L】","src":"物一轮107.寻找向心力_笔记","note":"视频|05:22-08:01","orig":"（例）绳长 L、摆角 θ 的圆锥摆：竖直方向 Tcosθ=mg，水平方向 Tsinθ=mω²r，几何关系 r=Lsinθ，aₙ=gtanθ。","link":""},{"id":"phy0670","t":"圆周运动·单摆变速圆周","s":"看到【单摆或绳模型在竖直平面内的一般位置受力】","c":"想到【变速圆周运动要分径向与切向：径向合力=mv^{2}/L 提供向心力，切向合力改变速率】；警惕【最低点拉力最大（T=mg+mv^{2}/L），端点向心力为零】","src":"物一轮107.寻找向心力_笔记","note":"视频|08:01-11:33","orig":"（例）单摆一般位置：径向 T−mgcosθ=mv²/L（向心力方程），切向 mgsinθ 产生切向加速度；端点 v=0、T=mgcosθ；最低点 θ=0°，T−mg=mv²/L，速度最大。","link":""},{"id":"phy0671","t":"圆周运动·圆锥摆动态分析","s":"看到【圆锥摆改变摆角 $\\theta$ 比较拉力、周期、线速度】","c":"想到【写出各量关于 $\\theta$ 的函数再由单调性判断：T=mg/cos$\\theta$，周期 T∝√cos$\\theta$，v∝√(tan$\\theta$sin$\\theta$)】；警惕【混淆向心加速度 gtan$\\theta$ 与切向加速度表达式】","src":"物一轮107.寻找向心力_笔记","note":"视频|11:33-16:41","orig":"（例）圆锥摆各量随摆角 θ 变化：T=mg/cosθ（θ越小拉力越小）、T周=2π√(Lcosθ/g)（θ越大周期越小）、v∝√(gtanθsinθ)（θ越大速度越大）。","link":""},{"id":"phy0672","t":"圆周运动·圆锥筒内两球","s":"看到【圆锥筒内壁上两球各自做匀速圆周运动】","c":"想到【先判断是否同轴：独立运动须逐个动力学分析，N=mg/cos$\\theta$ 相同，$\\omega$=√(Nsin$\\theta$/(mr)) 随 r 增大而减小】；警惕【误判为同轴传动而默认角速度相同】","src":"物一轮107.寻找向心力_笔记","note":"视频|16:41-22:13","orig":"（例）圆锥筒内两球独立匀速圆周运动：Ncosθ=mg 使两球支持力相同，Nsinθ=mω²r，半径大的A球ω更小、周期更大、线速度更大。","link":""},{"id":"phy0673","t":"圆周运动·弹簧提供向心力","s":"看到【弹簧弹力提供向心力求临界角速度或最大线速度】","c":"想到【列 kx=m$\\omega$^{2}r，先定临界形变量 x，再由 v=$\\omega$r 换算（同轴传动各点$\\omega$相同）】；警惕【v=$\\omega$r 中 r 是旋转半径，勿误用细管全长 l】","src":"物一轮107.寻找向心力_笔记","note":"视频|22:13-26:48","orig":"（例）弹簧-插销系统：弹簧原长 l/2、劲度系数 k，伸长至 l 时插销卡住；kl/2=mω²l 得 ω=√(k/(2m))，卷轴线速度 vmax=ωr=r√(k/(2m))。","link":""},{"id":"phy0674","t":"圆周运动·斜面内圆周分力","s":"看到【水平板托着物体在竖直面内做匀速圆周运动】","c":"想到【向心加速度沿半径方向，需分解到水平/竖直：f=m$a_n$sin$\\theta$、mg−N=m$a_n$cos$\\theta$】；警惕【研究对象选受情况明确的物体（选木块而非木板）；摩擦力随位置角变化非单调】","src":"物一轮107.寻找向心力_笔记","note":"视频|26:48-30:58","orig":"（例）木板托木块在竖直面内做匀速圆周运动：水平方向 f=mv²sinθ/r，竖直方向 mg−N=mv²cosθ/r；从 a 到 b 过程 θ 减小，f 减小、N 增大。","link":""},{"id":"phy0675","t":"圆周运动·弹簧杆组合同轴","s":"看到【弹簧+轻杆连接的小球随装置同轴转动，$\\omega$ 变化】","c":"想到【杆的弹力方向可双向变化，随$\\omega$增大会经历「减小$\\to$为零$\\to$反向增大」】；警惕【弹簧弹力由形变量决定，位置不变则弹力不变；合力 F=m$\\omega$^{2}r 随$\\omega$增大】","src":"物一轮107.寻找向心力_笔记","note":"视频|30:58-38:14","orig":"（例）小球随框架同轴转动：小球高度不变、弹簧形变量不变故弹力大小不变；杆的弹力方向不确定，低速向右随ω增大而减小，高速反向向左增大，存在弹力为零的临界状态。","link":""},{"id":"phy0676","t":"圆周运动·同轴双球摩擦临界","s":"看到【竖直转轴上随$\\omega$变化的小球摩擦力方向讨论】","c":"想到【静摩擦被动调节：$\\omega$ 增大过程中摩擦力先减小至零再反向增大，存在弹力水平分量恰好提供向心力的临界状态】；警惕【同轴同半径则合力 F=m$\\omega$^{2}r 相同；摩擦力不存在单调增大的选项说法】","src":"物一轮107.寻找向心力_笔记","note":"视频|38:14-","orig":"（例）A、B两球同轴转动且半径相同：A球必须有摩擦力；B球可能无摩擦（弹力水平分量恰好提供向心力）；ω增大过程中摩擦力先减小至零再反向增大。","link":""},{"id":"phy0677","t":"竖直圆周·外轨模型（绳模型）","s":"看到【小球在竖直圆形轨道内侧（或绳系小球）运动】","c":"想到【按绳模型处理：弹力只能指向圆心，最高点不能提供支撑】；警惕【滑动摩擦力只影响切向运动，不影响径向向心力分析】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|00:38-00:58","orig":"（知识）小球在竖直圆弧轨道内侧运动，轨道弹力始终指向圆心，与绳模型拉力方向特性一致，可类比分析。","link":""},{"id":"phy0678","t":"竖直圆周·下半圆受力","s":"看到【外轨（绳）模型中下半圆任意位置的受力或挤压判断】","c":"想到【N=mgcos$\\theta$+mv^{2}/r 恒大于零，下半圆必挤压轨道不脱离】；警惕【$\\theta$ 为与竖直方向夹角，别搞错重力分量方向】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|03:37-06:02","orig":"（知识）下半圆动力学方程 N−mgcosθ=mv²/r，N=mgcosθ+mv²/r>0 恒成立，下半圆始终挤压轨道贴合运动。","link":""},{"id":"phy0679","t":"竖直圆周·上半圆与最高点临界","s":"看到【外轨（绳）模型求「恰好通过最高点」的条件】","c":"想到【最高点 N=0 时仅重力提供向心力：mg=mv^{2}/r，得 vmin=√(gr)；最高点满足则全程均可完成】；警惕【高度越高所需最小速度越大而实际速度越小，矛盾集中在上半圆】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|06:02-13:02","orig":"（知识）上半圆 N+mgcosθ=mv²/r，需 v≥√(gr·cosθ)，位置越高要求越高；最高点 θ=0° 时 vmin=√(gr)，临界时 N=0 仅重力提供向心力。","link":""},{"id":"phy0680","t":"竖直圆周·双轨模型（杆模型）","s":"看到【圆管、双轨或轻杆约束的竖直圆周运动】","c":"想到【弹力可指向或背离圆心，最高点最小速度为 0】；警惕【与绳模型本质区别在于有无内轨/杆的支撑，勿混用 vmin=√(gr)】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|13:02-14:24","orig":"（知识）内外双层轨道（或杆）可提供双向弹力，类似杆模型；最高点速度可为 0 仍能完成圆周运动。","link":""},{"id":"phy0681","t":"竖直圆周·双轨弹力随速度变化","s":"看到【双轨/杆模型最高点弹力随速度大小的变化】","c":"想到【以 v=√(gr) 为分界：大速度挤压外侧（弹力向下），小速度挤压内侧（弹力向上），临界时弹力为零】；警惕【速度递减时弹力先向下减小至零再反向增大】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|14:24-18:07","orig":"（知识）最高点：v>√(gr) 时外轨弹力向下补充向心力；v=√(gr) 时仅重力提供向心力、弹力为零；v<√(gr) 时内轨弹力向上抵消部分重力；v→0 时 FN→mg。","link":""},{"id":"phy0682","t":"竖直圆周·内轨模型（拱桥）","s":"看到【物体在拱形轨道（桥面）外侧运动】","c":"想到【支持力向上、重力向下，mg−FN=mv^{2}/r，速度越大压力越小，vmax=√(gr) 时脱离】；警惕【内轨限最大速度 √(gr)，外轨限最小速度 √(gr)，方向勿记反】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|18:07-20:27","orig":"（知识）拱桥模型：最高点 mg−FN=mv²/r，FN=0 时 vmax=√(gr)，超过则脱离轨道；车辆高速过拱桥可能腾空。","link":""},{"id":"phy0683","t":"竖直圆周·外轨模型例题","s":"看到【外轨模型最高点「恰好无挤压」与最低点支持力比较】","c":"想到【最高点无挤压即 N=0：v=√(gR)；最低点 N−mg=mv^{2}/R，N 必大于 mg】；警惕【最低点受力必须计入向心力需求】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|20:27-22:13","orig":"（例）小球在半径 R 的圆形轨道内侧运动：最高点无相互作用时 mg=mv²/R 得 v=√(gR)，R 越大 v 越大；最低点 N=mg+mv²/R 必大于重力。","link":""},{"id":"phy0684","t":"竖直圆周·双轨模型例题","s":"看到【双轨模型已知某速度下的弹力求另一速度下的弹力】","c":"想到【先由初始条件定 v，速度变化后重算 mv^{2}/r 与 mg 比较，差值即弹力，方向由大小关系定】；警惕【速度小于 √(gR) 时小球压的是内壁而非外壁】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|22:13-25:18","orig":"（例）小球过圆管最高点对壁压力为 mg 时 mg+N=mv²/R 得 v=√(2gR)；速度减半后所需向心力为 mg/2，重力过多，内壁提供向上支持力 N′=mg/2。","link":""},{"id":"phy0685","t":"竖直圆周·三模型对比总结","s":"看到【竖直圆周运动绳/杆/拱桥三类模型混选】","c":"想到【一句话记忆：绳限最低 √(gr)，杆可为 0，桥限最高 √(gr)】；警惕【题目常设陷阱是混淆绳与杆的临界条件】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|25:18-","orig":"（知识）外轨（绳）：最高点 vmin=√(gr)；双轨（杆）：vmin=0；内轨（拱桥）：vmax=√(gr)。","link":""},{"id":"phy0686","t":"竖直圆周·能量综合","s":"看到【水平运动衔接竖直圆周、题干出现「恰好通过最高点」】","c":"想到【把临界条件 v=√(gr) 与机械能守恒（或动能定理）联立求释放高度等】；警惕【「恰好」二字即弹力为零的信号，勿忽略】","src":"物一轮108.竖直圆周运动模型_笔记","note":"视频|25:18-","orig":"（知识）水平轨道连接竖直圆轨道综合题：「恰好通过最高点」隐含 v=√(gr)，需与机械能守恒联立分析。","link":""},{"id":"phy0687","t":"圆周运动·供需关系","s":"看到【圆周运动中物体运动状态突变（飞出/内滑）的判断】","c":"想到【比较 F供 与 F需=m$\\omega$^{2}r：相等做圆周运动，不足做离心运动，过剩做向心运动】；警惕【离心运动不是受「离心力」，而是合力不足以提供向心力】","src":"物一轮109.圆周运动中的临界问题_笔记","note":"视频|00:24-01:11","orig":"（知识）沿半径方向的合力（提供的力）与维持圆周运动所需的向心力（需要的力）之间的供需关系决定运动状态。","link":""},{"id":"phy0688","t":"圆周运动·离心与向心运动","s":"看到【绳突然断裂或转速加快后物体的运动去向】","c":"想到【F供<F需 离心、F供>F需 向心；绳断瞬间物体沿切线方向飞出（惯性）】；警惕【物体在半径改变前速度沿切线，不会沿径向飞出】","src":"物一轮109.圆周运动中的临界问题_笔记","note":"视频|01:30-03:05","orig":"（知识）F供<F需 时物体远离圆心做离心运动（绳断沿切线飞出、转盘转速过快物块被甩飞）；F供>F需 时物体向圆心靠近做向心运动。","link":""},{"id":"phy0689","t":"圆周运动·两类临界条件","s":"看到【圆周运动中「恰好分离/恰好不滑动」类临界问题】","c":"想到【临界即令 N=0 或 f=fmax，与直线运动临界方法一致列动力学方程】；警惕【静摩擦大小方向均可变，可突变，需分段讨论】","src":"物一轮109.圆周运动中的临界问题_笔记","note":"视频|03:33-04:37","orig":"（知识）弹力临界：接触面弹力恰好为零（N=0）；摩擦临界：摩擦力达到最大静摩擦（f=fmax）。","link":""},{"id":"phy0690","t":"圆周运动·绳系球随ω变化的图像","s":"看到【绳拉力 FT 与 $\\omega$^{2} 的关系图像（折线/截距）】","c":"想到【按弹力是否为零分段：未飞起时含重力分量截距 mgcos$\\theta$，飞起后 FT=mL$\\omega$^{2} 为过原点直线】；警惕【坐标系选择不当导致计算复杂；忽略临界状态（弹力为零）的折点】","src":"物一轮109.圆周运动中的临界问题_笔记","note":"视频|04:37-12:42","orig":"（例）斜面上细绳拴小球随ω转动：低速段沿斜面/垂直斜面分解，FT=mr·sinθ·ω²+mgcosθ；高速段球飞起，FT=mLω²，图像为斜率不同的两段折线。","link":""},{"id":"phy0691","t":"圆周运动·圆盘双物体临界","s":"看到【圆盘上两物体由细线相连、转速逐渐增大】","c":"想到【半径大的先达最大静摩擦，之后绳出现张力；再滑动时两物体同时达最大静摩擦联立方程】；警惕【烧断线后要逐个判断：静摩擦可突变继续提供向心力的物体仍做圆周运动】","src":"物一轮109.圆周运动中的临界问题_笔记","note":"视频|12:42-20:47","orig":"（例）圆盘上 a、b由细线相连：b（半径大）先达最大静摩擦 0.4mg=mω₀²r_b 出现绳张力；a 开始滑动时对 a、b 分别列 0.4mg∓T=mω²r 联立得 ω=4 rad/s；烧断细线后 b 做离心运动、a 仍随盘转动。","link":""},{"id":"phy0692","t":"圆周运动·摩擦临界半径","s":"看到【转台上物体能否被甩出（或分布范围）问题】","c":"想到【$\\mu$mg=m$\\omega$^{2}r 得临界半径 r=$\\mu$g/$\\omega$^{2}，r 内可稳定、r 外被甩出】；警惕【临界半径与质量无关（m 约去），勿选「与质量有关」的选项】","src":"物一轮109.圆周运动中的临界问题_笔记","note":"视频|20:47-24:18","orig":"（例）旋转工作台上陶屑分布：最大静摩擦提供向心力 μmg=mω²r，临界半径 r=μg/ω²，与质量无关；陶屑只能分布在临界半径内的圆内区域。","link":""},{"id":"phy0693","t":"圆周运动·供需总结","s":"看到【圆周运动临界问题综合复习】","c":"想到【先写 F需=m$\\omega$^{2}r，再判断供力来源（弹力/摩擦/绳张力），令临界条件列方程】；警惕【多物体系统须逐个分析，注意静摩擦的可突变特性】","src":"物一轮109.圆周运动中的临界问题_笔记","note":"视频|24:18-","orig":"（知识）三状态：F供=F需 圆周运动、F供<F需 离心、F供>F需 向心；两类临界：N=0、f=fmax。","link":""},{"id":"phy0694","t":"微元法·向心加速度推导思路","s":"看到【用加速度定义式推导向心加速度表达式】","c":"想到【先选匀速圆周运动排除切向分量，使 a=$\\Delta$v/$\\Delta$t 直接指向心加速度】；警惕【一般圆周运动中 a 含向心与切向两个分量，不能直接套定义式】","src":"物一轮110.圆周运动中的微元思想_笔记","note":"视频|00:17-00:52","orig":"（知识）基于 a=Δv/Δt 推导向心加速度时，须消除切向加速度干扰：选匀速圆周运动（切向分量为零），此时 a=aₙ 可直接用定义式推导。","link":""},{"id":"phy0695","t":"微元法·Δv 方向的确定","s":"看到【速度变化量 $\\Delta$v 的方向判断】","c":"想到【矢量减法 $\\Delta$v=vB−vA 指向被减数；极限下 $\\Delta$v 垂直于 v 指向圆心】；警惕【$\\Delta$v 方向不是速度方向，是两速度矢量的差矢量方向】","src":"物一轮110.圆周运动中的微元思想_笔记","note":"视频|00:52-04:11","orig":"（知识）速度由 vA 变为 vB，平移 vA 使矢量尾重合，Δv 指向被减数 vB；构建等腰三角形，顶角 θ→0 时底角→90°，故 Δv⊥v，方向指向圆心。","link":""},{"id":"phy0696","t":"微元法·aₙ=v²/r 的推导","s":"看到【推导向心加速度大小（弦弧近似）】","c":"想到【弦弧近似 $\\Delta$v≈$\\theta$v 与 $\\theta$=$\\omega$$\\Delta$t 联立得 $a_n$=$\\omega$v=v^{2}/r；微元在方向（$\\Delta$v$\\perp$v）与大小（弦≈弧）双重应用】；警惕【区分瞬时加速度与平均加速度的微元处理逻辑】","src":"物一轮110.圆周运动中的微元思想_笔记","note":"视频|04:11-10:57","orig":"（知识）微元条件下弧长≈弦长，Δv≈θ·v，转角 θ=ωΔt，代入 aₙ=Δv/Δt=ωv，结合 ω=v/r 得 aₙ=v²/r。","link":""},{"id":"phy0697","t":"微元法·三种典型应用","s":"看到【处理变速位移、曲线运动瞬时量或一般曲线动力学】","c":"想到【「无限分割$\\to$局部近似$\\to$整体累加」，按问题选化变为恒/化曲为直/化曲为圆】；警惕【斜抛最高点曲率半径 $\\rho$=v_{0}^{2}cos^{2}$\\theta$/g 勿丢 cos^{2}$\\theta$ 因子】","src":"物一轮110.圆周运动中的微元思想_笔记","note":"视频|10:57-20:37","orig":"（知识）化变为恒（v-t 图无限分割累加矩形面积求位移）、化曲为直（极短弧长近似直线段）、化曲为圆（一般曲线分段视为曲率半径 ρ 的圆弧，如斜抛最高点 ρ=v₀²cos²θ/g）。","link":""},{"id":"phy0698","t":"微元法·化圆为抛物线","s":"看到【用「切向匀速+法向匀变速」分解推导向心加速度】","c":"想到【极短时间内抛物线与圆弧起始段重合，几何关系舍去高阶无穷小（$a^2$t^{4} 类）即得 a=v^{2}/r】；警惕【高阶项的忽略仅在 t$\\to$0 极限下成立，近似是关键】","src":"物一轮110.圆周运动中的微元思想_笔记","note":"视频|10:57-20:37","orig":"（知识）极短时间 Δt 内将圆周运动分解为切向匀速（位移 vt）与法向匀变速（位移 ½at²），由相似三角形 vt²=½at²·(2r−½at²)，t→0 时高阶项消失，导出 a=v²/r。","link":""},{"id":"phy0699","t":"微元法·思想总结","s":"看到【需要处理连续变化的物理量（位移、方向、轨迹）】","c":"想到【微元三步走：无限分割、局部近似（化恒/直/圆/抛物线）、整体累加】；警惕【微元必须足够小；不同问题选合适的转化方式并注意高阶无穷小取舍】","src":"物一轮110.圆周运动中的微元思想_笔记","note":"视频|20:37-","orig":"（知识）微元法本质：无限分割→局部近似→整体累加；应用场景包括变速位移计算、曲线瞬时速度分析、一般曲线动力学研究。","link":""},{"id":"phy0700","t":"万有引力与航天·模块难度分级","s":"看到【规划天体运动模块的复习优先级】","c":"想到【按难度分层复习：先掌握两定律基本内容，再攻克万有引力与重力关系（赤道/极点/忽略自转），推论部分视余力补充】；警惕【两个推论考频低但难度大，勿在基础不牢时死磕】","src":"物一轮111.【课前必看】本讲听课建议_笔记","note":"视频|00:38-03:50","orig":"（知识）难度分级：一星——开普勒定律与万有引力定律基本内容；二星——万有引力与重力的关系（赤道/极点/忽略自转的受力特征）；四星——万有引力定律的两个推论（考频较低但难度较大）。","link":""},{"id":"phy0701","t":"万有引力与航天·考情分析","s":"看到【天体运动选择题（含黑洞、拉格朗日点等新情境）】","c":"想到【天体问题为必拿分题：常规模型化程度高靠练习掌握，新情境题回归物理概念理解而非套公式】；警惕【新情境只是包装，内核仍是环绕动力学基本关系】","src":"物一轮111.【课前必看】本讲听课建议_笔记","note":"视频|03:50-09:15","orig":"（知识）高考地位：必考高频考点，每年至少一道选择题，难度中等属必拿分；近年出现新情境命题趋势（如黑洞、拉格朗日点等）。","link":""},{"id":"phy0702","t":"万有引力与航天·考查方向与策略","s":"看到【备考天体模块需要区分选择与解答题侧重】","c":"想到【选择题主攻卫星环绕规律，解答题需额外掌握地面物体受力分析（赤道与极点对比）与两个推论】；警惕【公转周期与自转周期易混淆，是万有引力与重力关系分析的基本功】","src":"物一轮111.【课前必看】本讲听课建议_笔记","note":"视频|09:15-","orig":"（知识）选择题各省普遍考查、侧重卫星相关知识；解答题少数省份（如北京）考查，侧重万有引力与重力关系、推论等内容。","link":""},{"id":"phy0703","t":"开普勒定律·第一定律（轨道定律）","s":"看到【行星（或卫星）绕中心天体的轨道形状问题】","c":"想到【轨道定律：椭圆轨道＋中心天体位于焦点上】；警惕【太阳在焦点而非椭圆中心；只需掌握「是什么」，不必探究「为什么」】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|00:55-01:38","orig":"（知识）所有行星绕太阳运动的轨道都是椭圆，太阳处在椭圆的一个焦点上；由大量观测数据总结而来，属现象层面规律。","link":""},{"id":"phy0704","t":"开普勒定律·椭圆参数与圆轨道近似","s":"看到【椭圆轨道近似处理为圆轨道】","c":"想到【近似条件是偏心率较小：轨道变圆、a$\\to$r、焦点$\\to$圆心，为环绕中心天体模型打基础】；警惕【半长轴 a 与半径 r 在近似前不可混用】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|01:38-04:57","orig":"（知识）长轴一半为半长轴 a；偏心率较小时椭圆可近似为圆：半长轴变为半径 r，太阳位置变为圆心。","link":""},{"id":"phy0705","t":"开普勒定律·第二定律（面积定律）","s":"看到【行星在椭圆轨道上不同位置的速率比较】","c":"想到【面积定律：相等时间扫过相等面积$\\Rightarrow$近日点快、远日点慢（近快远慢）】；警惕【扇形面积公式 S=½lr 由微元近似得出，推导可用】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|04:59-06:20","orig":"（知识）行星与太阳连线在相等时间内扫过的面积相等；Δt→0 时扫过区域近似扇形，S=½lr（l 为弧长）。","link":""},{"id":"phy0706","t":"开普勒定律·近快远慢定量关系","s":"看到【椭圆轨道上两点速度与到中心天体距离的关系】","c":"想到【v∝1/r、v_{1}r_{1}=v_{2}r_{2}（对近日/远日点适用）；口诀「近快远慢」】；警惕【该反比关系适用于沿连线扫面积的两个对称点，不是任意位置普适公式】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|06:20-11:00","orig":"（知识）近日点 r 小 v 大，远日点 r 大 v 小；定量关系 v∝1/r，即 vₐ×rₐ=v_b×r_b（近日点与远日点速度与距离乘积相等）。","link":""},{"id":"phy0707","t":"开普勒定律·圆轨道特例","s":"看到【圆轨道行星（卫星）速率是否变化】","c":"想到【圆轨道是椭圆特例：r 处处相等$\\Rightarrow$匀速圆周运动】；警惕【匀速圆周运动的「匀速」指速率不变，方向时刻改变】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|11:00-12:08","orig":"（知识）轨道近似为正圆时：各点 r 相同，各点 v 相同，行星做匀速圆周运动，面积定律表现为相等时间扫过相同面积扇形。","link":""},{"id":"phy0708","t":"开普勒定律·第三定律（周期定律）","s":"看到【比较两行星（或卫星）轨道与周期的比例问题】","c":"想到【a^{3}/T^{2}=k：同一中心天体的天体可用 a^{3}∝T^{2} 建立比例求解】；警惕【区分公转周期与自转周期；k 只由中心天体决定】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|12:08-13:26","orig":"（知识）a³/T²=k，半长轴三次方与公转周期平方之比相等；圆轨道时 r³/T²=k；k 仅与中心天体质量有关。","link":""},{"id":"phy0709","t":"开普勒定律·k值与联立条件","s":"看到【跨系统比较行星周期或轨道】","c":"想到【先判断中心天体是否相同：同中心天体才可联立 a^{3}/T^{2}=k；k=GM/4$\\pi$^{2}】；警惕【日-地与地-月 k 不同，不可直接联立】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|13:26-14:11","orig":"（知识）相同中心天体的行星可联立方程（如日-地系统与日-火系统）；不同中心天体的行星不可联立（如日-地系统与地-月系统）。","link":""},{"id":"phy0710","t":"开普勒定律·解题步骤与命题方向","s":"看到【开普勒第三定律的比例计算题】","c":"想到【三步流程：判中心天体$\\to$选椭圆/圆公式$\\to$列比例式】；警惕【椭圆轨道用半长轴 a，圆轨道才可换成半径 r】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|14:11-19:13","orig":"（知识）解题三步：判断中心天体是否相同→确认用精确（椭圆）还是近似（圆）公式→建立比例关系求解；常见题型：已知参数推其他行星参数、比较不同系统 k 值、三定律综合。","link":""},{"id":"phy0711","t":"开普勒定律·飞船椭圆轨道时间","s":"看到【椭圆轨道上运动一段弧求时间】","c":"想到【先求半长轴 a=(r_min+r_max)/2，用第三定律与圆轨道周期联立求 T_椭圆，再按对称性取 ½T】；警惕【只有沿长轴对称的运动时间才是周期一半】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|19:13-25:54","orig":"（例）飞船由圆轨道变轨为椭圆轨道（近地点 R、远地点 R₀）：a=(R₀+R)/2，由 R³/T²=a³/T_椭圆² 得 T_椭圆=T√((R₀+R)³/(8R³))，从 A 到 B 的时间 t=½T_椭圆。","link":""},{"id":"phy0712","t":"开普勒定律·小行星内外切椭圆","s":"看到【椭圆与圆轨道相切的组合轨道比较周期/速度/加速度】","c":"想到【半长轴＝（远日距＋近日距）/2 切勿漏掉地球轨道半径 R；同距离处 a=GM/r^{2} 与轨道形状无关】；警惕【远日点速度小于近日点（面积定律）；切点处两轨道速度不同（变轨）】","src":"物一轮112.开普勒定律的基本內容_笔记","note":"视频|25:54-","orig":"（例）甲为外切椭圆（远日点 R₁）、乙为内切椭圆（近日点 R₂）、地球圆轨道半径 R：a甲=(R₁+R)/2、a乙=(R₂+R)/2，周期比 T₁/T₂=((R₁+R)/(R₂+R))^1.5；同距离处加速度 a=GM/r² 相同。","link":""},{"id":"phy0713","t":"万有引力·定律推导","s":"看到【推导万有引力定律表达式】","c":"想到【链路：F=mv^{2}/r$\\to$v=2$\\pi$r/T 代入$\\to$用开普勒第三定律 r^{3}/T^{2}=k 消去 T^{2} 得 F∝m/r^{2}$\\to$再由牛顿第三定律对称性引入中心天体质量 M$\\to$F=GMm/r^{2}】；警惕【椭圆近似为圆的前提是轨道偏心率较小，推导中消元对象是 T^{2}】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|01:06-09:33","orig":"（知识）行星绕太阳的变速椭圆运动近似为匀速圆周运动（偏心率较小），太阳引力提供向心力，结合开普勒第三定律推导出 F=GMm/r²。","link":""},{"id":"phy0714","t":"万有引力·月地检验","s":"看到【月地检验／验证天体引力与地表重力是否同源】","c":"想到【动力学假设两种力都满足平方反比$\\to$推加速度比 a月/g=R^{2}/r^{2}=1/3600$\\to$用运动学数据（a月=4$\\pi$^{2}r/T^{2} 与 g）验证】；警惕【距离比是60倍，加速度比是3600倍（60^{2}），勿混淆；检验方法的核心是避开质量参数的测量，无需月球质量】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|09:33-15:48","orig":"（知识）假设地球对苹果的引力与对月球的引力是同种力且都遵循平方反比，则 a苹/a月=r²/R²≈3600（地月距离约为地球半径60倍），牛顿用月球向心加速度与地表重力加速度之比 1/3600 验证成立。","link":""},{"id":"phy0715","t":"万有引力·月地检验","s":"看到【月地检验类选择题选项判断】","c":"想到【抓住两条：圆周运动基本公式 a=4$\\pi$^{2}r/T^{2} 必对；核心比例是加速度比 1/3600=1/60^{2}】；警惕【把距离比60倍直接当加速度比】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|15:48-17:34","orig":"（例）月地检验选择题：A 月球向心加速度 an=4π²r/T² 正确；B 比例应为 1/3600 而非 1/60 错误；C 验证平方反比关系正确；D 无需月球质量，错误。答案 AC。","link":""},{"id":"phy0716","t":"万有引力·黄金代换求周期","s":"看到【已知轨道半径与地球半径的倍数关系求环绕周期】","c":"想到【T=2$\\pi$√(r^{3}/GM)，用黄金代换 GM=gR^{2} 消去未知量 GM，注意 r=60R 的三次方运算】；警惕【区分半径 R 与地月距离 r；先用单位（量纲）排除选项再验算】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|17:34-24:00","orig":"（例）根据牛顿的猜想求月球绕地球公转周期：r=60R，由 F=GMm/r²=4π²mr/T² 得 T=2π√(r³/GM)，代入 GM=gR² 得 T=2π√(60³R/g)，用量纲分析排除单位不符选项。答案 C。","link":""},{"id":"phy0717","t":"万有引力·引力常量G","s":"看到【万有引力常量 G 的数值、单位或估算题】","c":"想到【G≈6.67$\\times$10^{-11} N·m^{2}/kg^{2}，主要适用于估算数量级而非精确计算；单位用量纲分析法从公式反推】；警惕【数值不便整除时只要求估算；单位是 N·m^{2}/kg^{2} 不是 N·kg^{2}/m^{2}】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|24:17-26:58","orig":"（知识）G 由卡文迪许（卡文迪什）实验测得，G=6.67×10⁻¹¹ N·m²/kg²，数量级固定 10⁻¹¹；单位由量纲分析从 F=Gm₁m₂/r² 推出为 N·m²/kg²。","link":""},{"id":"phy0718","t":"万有引力·卡文迪许扭秤实验","s":"看到【卡文迪许扭秤实验／测量微小量的实验思想】","c":"想到【实验原理是光杠杆放大法——把微小扭转量光学放大为光斑位移】；警惕【高中不要求扭矩平衡的详细计算，记住『放大法』思想即可】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|26:58-30:33","orig":"（知识）扭秤由固定大球与可转动小球组成，引力使横杆发生微小扭转，利用光杠杆放大法：平面镜反射光线在远处屏幕形成明显光斑位移。核心物理思想是放大法。","link":""},{"id":"phy0719","t":"万有引力·适用条件与r的取值","s":"看到【问 r$\\to$0 时万有引力是否趋于无穷／公式适用条件】","c":"想到【公式仅适用质点或质量均匀的球体（r 取球心距）；r$\\to$0 时不再满足质点条件，F 不会$\\to$$\\infty$；非均匀物体用割补法处理】；警惕【物体位于均匀球壳内部时不能直接套用公式（此时引力为零）】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|30:33-37:11","orig":"（知识）F=GMm/r² 严格适用于质点间作用；质量分布均匀的实心球或球壳可视为质点，r 取球心距；r→0 时物体不能视为质点，力不会趋于无穷；非均匀物体用微元法（理论）或割补法（考试常用）。","link":""},{"id":"phy0720","t":"万有引力·割补法","s":"看到【均匀球体挖去小球且挖去位置在球心（剩余为均匀球壳）】","c":"想到【先按体积比定挖去质量（同直径比三次方），剩余部分若仍是均匀球体/球壳可直接套公式】；警惕【体积比是线度比的立方】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|37:11-42:42","orig":"（例）从均匀实心球中心挖去直径为 R 的小球：挖去部分质量 m=M/8（体积比1:8），剩余为均匀球壳，直接用万有引力公式得 F=7GM²/64d²。","link":""},{"id":"phy0721","t":"万有引力·割补法","s":"看到【均匀球体偏心挖去小球求剩余部分引力】","c":"想到【割补法：F=F完整−F挖去，分别对完整球和挖去小球套公式作差】；警惕【补全后重新计算两球心距——偏心挖球时是 d−R/2 而非 d】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|42:42-46:01","orig":"（例）挖球位置偏离中心：F=完整大球引力 F₁−挖去小球引力 F₂，其中挖去小球与被研究对象间距为 d−R/2。","link":""},{"id":"phy0722","t":"开普勒定律·三定律要点","s":"看到【行星近日点／远日点速度比较或开普勒定律定性判断】","c":"想到【近快远慢，同一轨道上 v∝1/r；不同轨道比较用 a^{3}/T^{2}=k；中心天体在椭圆焦点上】；警惕【面积定律的 v∝1/r 只对同一椭圆轨道上的两点成立，与不同圆轨道的『高轨低速』推导途径不同】","src":"物一轮113.万有引力定律的推导及性质_笔记","note":"视频|46:01","orig":"（知识）第一定律（轨道）：行星轨道是椭圆，太阳位于焦点；第二定律（面积）：近日点速度最快、远日点最慢，v∝1/r；第三定律（周期）：a³/T²=k，a 为半长轴。","link":""},{"id":"phy0723","t":"万有引力·重力与万有引力关系","s":"看到【地表物体的重力与万有引力关系】","c":"想到【万有引力=重力+向心力两个分效果，重力只是其中一个分力】；警惕【除赤道与极点外重力方向近似但不严格指向地心】","src":"物一轮114.赤道上物体的受力特点_笔记","note":"","orig":"（知识）重力是万有引力的分力：万有引力分解为重力（使物体落回地面）和向心力（提供随地球自转的圆周运动）。","link":""},{"id":"phy0724","t":"万有引力·赤道与极点受力差异","s":"看到【比较赤道与极点处重力（或重力加速度）大小】","c":"想到【极点处圆周运动半径 r=0，万有引力全部成为重力；赤道处需扣除向心力，故赤道重力最小、纬度越高重力越大】；警惕【赤道受力分析必须同时列重力和向心力，不能直接令万有引力=重力】","src":"物一轮114.赤道上物体的受力特点_笔记","note":"","orig":"（知识）赤道：万有引力=重力+向心力；极点：万有引力=重力（无向心力）。赤道重力比极点小，因部分万有引力提供了向心力。","link":""},{"id":"phy0725","t":"万有引力·重力加速度变化规律","s":"看到【问重力加速度随纬度／高度如何变化】","c":"想到【纬度越高 g 越大（极点最大），海拔越高 g 越小（g∝1/r^{2}）】；警惕【该规律是由两极特殊位置推出的定性结论，不是对每一纬度的严格证明】","src":"物一轮114.赤道上物体的受力特点_笔记","note":"","orig":"（知识）纬度增加→重力增大；高度增加→重力减小（由赤道与极点重力差异推导的规律，非严格证明）。","link":""},{"id":"phy0726","t":"万有引力·纬度处三分力计算","s":"看到【给纬度求万有引力、向心力、重力三者数值关系】","c":"想到【用平行四边形定则把万有引力分解为重力与向心力，验证 F引^{2}≈F重^{2}+F向^{2}（夹角很小）】；警惕【向心力 m$\\omega$^{2}R 极小，重力方向近似指向地心但并不严格】","src":"物一轮114.赤道上物体的受力特点_笔记","note":"","orig":"（例）北纬37度处物体：算得万有引力591.88N、向心力1.6N、重力588.0N，验证重力为万有引力的分力；向心力极小。","link":""},{"id":"phy0727","t":"万有引力·赤道物体飘起临界","s":"看到【地球自转加快，赤道物体恰好飘起／对地面压力为零】","c":"想到【临界条件：万有引力全部提供向心力 GMm/R^{2}=m$\\omega$^{2}R，此时重力（支持力）为零，解出临界角速度】；警惕【飘起后物体仍随地球做圆周运动，不是不受任何力】","src":"物一轮114.赤道上物体的受力特点_笔记","note":"","orig":"（知识）自转角速度加快→所需向心力增大，当万有引力全部用于提供向心力时重力为零，物体飘起；临界条件是万有引力=向心力。","link":""},{"id":"phy0728","t":"万有引力·弹簧测力计示数比较","s":"看到【同一物体在极点与赤道用弹簧测力计称量比较示数】","c":"想到【极点：F=GMm/R^{2}；赤道：F=GMm/R^{2}−m(4$\\pi$^{2}/T^{2})R，两式相减即得向心力，可进一步求中心天体质量或密度】；警惕【示数差对应向心力 m$\\omega$^{2}R，其中 T 取地球自转周期 24h】","src":"物一轮114.赤道上物体的受力特点_笔记","note":"","orig":"（例）高考题：弹簧测力计分别于极点和赤道称同一物体，极点 F₀=GMm/R²；赤道 F₂=GMm/R²−m(4π²/T²)R，赤道示数必小于极点，差值反映向心力大小。","link":""},{"id":"phy0729","t":"万有引力·极点与忽略自转","s":"看到【极点位置／忽略自转条件下的受力分析】","c":"想到【两种情形等效：向心力为零，万有引力=重力，可直接写 GMm/r^{2}=mg】；警惕【纬度越高圆周运动半径越小，极点处 r=0；『忽略自转』是人为设定的 $\\omega$=0 物理模型】","src":"物一轮115.极点、忽略自转下物体的受力特点_笔记","note":"视频|00:19-01:17","orig":"（知识）物体处于南北极点或题目明确忽略中心天体自转时，万有引力等于重力（F引=mg）。极点处圆周运动半径 r=0 使 F向=mω²r=0；忽略自转即 ω=0，同样 F向=0。","link":""},{"id":"phy0730","t":"万有引力·黄金代换","s":"看到【表达式含未知量 G 或中心天体质量 M 且给了重力加速度 g】","c":"想到【用黄金代换 GM=gr^{2} 把 GM 整体替换掉，简化含 G、M 的计算】；警惕【该式仅在极点或忽略自转条件下严格成立】","src":"物一轮115.极点、忽略自转下物体的受力特点_笔记","note":"视频|01:17-03:21","orig":"（知识）由 GMm/r²=mg 推出黄金代换式 GM=gr²，规避难以测量的 G 和中心天体质量 M，转换为易测的 g 和 r。","link":""},{"id":"phy0731","t":"万有引力·黄金代换的g与r对应","s":"看到【高空（距表面 h 处）的重力加速度 g' 相关计算】","c":"想到【同一位置的 g 与 r 配套使用：地表配 R，高空配 R+h，两位置可联立 g/g'=(R+h)^{2}/R^{2}】；警惕【把地表 g 与高空 r 混搭是高频错误】","src":"物一轮115.极点、忽略自转下物体的受力特点_笔记","note":"视频|05:00-06:51","orig":"（知识）公式中的 g 和 r 必须取自同一测量位置：地表测量取 r=R、g 为地表重力加速度；高空测量取 r=R+h、g 为该高度处的 g'。混用不同位置参数会算错。","link":""},{"id":"phy0732","t":"万有引力·近似处理与禁用场景","s":"看到【自由落体、抛体、单摆或非赤道称重等涉及 g 的运动学问题】","c":"想到【默认忽略自转，万有引力≈重力，黄金代换可直接用】；警惕【赤道位置不可套用万有引力=重力，必须保留向心力项】","src":"物一轮115.极点、忽略自转下物体的受力特点_笔记","note":"视频|06:51-09:36","orig":"（知识）高考题会明确给出『极点』或『忽略自转』条件，模拟题可能隐含。可近似处理：与 g 相关的运动（自由落体、抛体、单摆 T=2π√(l/g)）、非赤道区域的称重问题。禁用：赤道位置的受力分析必须同时考虑重力和向心力。","link":""},{"id":"phy0733","t":"万有引力·不同天体参数比较","s":"看到【同一竖直上抛运动在两星球上时间不同，比较重力加速度或星球质量】","c":"想到【抛体时间差反推 g 之比（t∝1/g，v=gt），再用黄金代换 M=gr^{2}/G 结合半径比求质量比】；警惕【上抛到最高点时间为总时间一半，先理清题给时间是单程还是往返】","src":"物一轮115.极点、忽略自转下物体的受力特点_笔记","note":"视频|09:36-14:59","orig":"（例）竖直上抛：同一初速度下地球落地时间 t/2、外星球 5t/2，由 t∝1/g 得 g':g=1:5；再由 M=gr²/G 与半径比 R':R=1:4 得质量比 M':M=1:80。","link":""},{"id":"phy0734","t":"万有引力·超重表象下的g变化","s":"看到【高空中的称重／超重示数与地表 mg 不符】","c":"想到【本质仍是重力加速度随高度变化：先由牛顿第二定律求该处 g'，再用 g/g'=(R+h)^{2}/R^{2} 求高度】；警惕【出现『超重』表述不代表 g 变大，先算出实际 g' 再判断】","src":"物一轮115.极点、忽略自转下物体的受力特点_笔记","note":"视频|14:59","orig":"（例）10kg 物体在某高度超重示数 75N（<mg=100N），说明该处 g' 减小：由 T−mg'=ma 得 g'=2.5m/s²，联立 g/g'=(R+h)²/R² 解得 h=R=6400km。","link":""},{"id":"phy0735","t":"万有引力·推论一（均匀球壳）","s":"看到【均匀球壳内部物体受万有引力】","c":"想到【直接用结论：均匀球壳对内部任意点引力为零，球壳部分贡献可整体忽略】；警惕【前提是『均匀球壳』+『内部』两个条件缺一不可】","src":"物一轮116.万有引力定律推论_笔记","note":"视频|00:15-02:19","orig":"（知识）质量分布均匀的球壳对其内部任意一点的万有引力为零。球心处各方向引力分量对称抵消；非中心点用微元法取对称两片，由几何相似性证 m₁/r₁²=m₂/r₂²，合力为零。","link":""},{"id":"phy0736","t":"万有引力·推论一的适用范围","s":"看到【问该推论对其他力（如库仑力、立方反比力）是否成立】","c":"想到【推论的本质是距离平方反比（F∝1/r^{2}），万有引力与库仑力都适用，可推广到所有平方反比力场；若改为立方反比则不成立】；警惕【静电感应可能改变电荷分布，使用前需确认『均匀分布』前提】","src":"物一轮116.万有引力定律推论_笔记","note":"视频|02:19-11:08","orig":"（例）例题：将球壳视为微小圆柱薄片，微元质量 m=ρ·πR²·d，建立 R₁²/r₁²=R₂²/r₂² 的比例关系证明合力为零；并类比电量均匀分布球壳内部库仑力也为零。","link":""},{"id":"phy0737","t":"万有引力·推论二（均匀实心球）","s":"看到【均匀实心球内部（如井下、星球内部）物体受引力】","c":"想到【内部引力仅由半径 x 以内的『内侧球体』贡献：F=GMmx/R^{3}，F∝x（类比弹簧弹力）】；警惕【x 以外的球壳层对内部引力为零但不能忽略其存在——它决定了质量分布】","src":"物一轮116.万有引力定律推论_笔记","note":"视频|11:13-12:29","orig":"（知识）质量分布均匀的实心球对内部距球心 x 处物体的引力 F=GMmx/R³，与 x 成正比。推导：把球分为内侧小球（半径 x）与外侧球壳，球壳部分引力为零，内侧质量 M'=M·x³/R³。","link":""},{"id":"phy0738","t":"万有引力·内外物体公式选择","s":"看到【物体在球体外部还是内部（挖井、深入地心类问题）】","c":"想到【先判断位置：外部用质点公式 F=GMm/r^{2}，内部用 F=GMmx/R^{3}；推论二建议掌握推导以便考场现场推出】；警惕【内部问题误用外部公式 GMm/$x^2$ 是典型陷阱】","src":"物一轮116.万有引力定律推论_笔记","note":"视频|12:29-16:14","orig":"（知识）外部物体：实心球可等效为球心处质点，用 F=GMm/r²；内部物体：必须用推论二 F=GMmx/R³。推论一通常作为已知条件给出，推论二需主动应用。","link":""},{"id":"phy0739","t":"万有引力·螺旋星系与暗物质","s":"看到【星系模型中恒星环绕速度随距离 r 的分布（内外两段讨论）】","c":"想到【分 r>R 与 r$\\leq$R 两段：外部看总质量、内部只算 r 内质量（推论二），分别解出 v(r) 关系；实测与理论偏离时用『补质量』（暗物质）修正，利用边界 r=R 处速度连续列方程】；警惕【内外两段公式不能混用，内部恒星有效质量按 r^{3}/R^{3} 缩放】","src":"物一轮116.万有引力定律推论_笔记","note":"视频|16:14-34:01","orig":"（例）质量 M 均匀分布在半径 R 的球体内，恒星绕中心匀速圆周运动：r>R 时 F=GMm/r²，v=√(GM/r) 与 r 成反比；r≤R 时有效质量 M_eff=r³M/R³，v=√(GM/R³)·r 与 r 成正比。实测 r>R 处 v 几乎不变，引入暗物质球壳后由边界条件解得 M'=(n−1)M。","link":""},{"id":"phy0740","t":"万有引力·地心挖掘问题","s":"看到【挖井深度 d／深入星球内部求引力或重力加速度】","c":"想到【直接套推论二：F=GMm(R−d)/R^{3}，与深度线性相关，井底越深引力越小，地心处为零】；警惕【陷阱选项是误用外部公式 GMm/(R−d)^{2}】","src":"物一轮116.万有引力定律推论_笔记","note":"视频|34:01-36:58","orig":"（例）地球视为质量 M 均匀分布、半径 R 的球体，挖井深度 d 处物体仅受半径 (R−d) 内球体的引力：M_eff=(R−d)³M/R³，F=GMm(R−d)/R³。","link":""},{"id":"phy0741","t":"万有引力·两推论对比总结","s":"看到【对比球壳与实心球内部引力的选择题】","c":"想到【空壳内部恒为零（与位置无关），实心球内部 F∝x 线性增大（到表面达最大 GMm/R^{2}）】；警惕【两推论结构前提不同，先分清研究对象是壳还是实心体】","src":"物一轮116.万有引力定律推论_笔记","note":"视频|36:58","orig":"（知识）推论一针对空心球壳：内部引力恒为零；推论二针对实心球体：内部引力随到球心距离 x 线性变化。推论二在考试中出现频率更高。","link":""},{"id":"phy0742","t":"万有引力与航天·知识模块结构","s":"看到【万有引力与航天章节复习规划】","c":"想到【按『环绕模型与变轨$\\to$双星$\\to$新信息题』的顺序分层推进：先保证必考基础分，再攻信息提取与建模能力】；警惕【双星模型近年考评降低但仍需关注，不可完全放弃】","src":"物一轮117.【课前必看】本讲听课建议_笔记","note":"视频|00:11-03:02","orig":"（知识）本章四大模块按难度分层：环绕中心天体模型（2星）、卫星发射与变轨（2星）、双星模型（3星）、天体新信息问题（5星）；前两部分为高考必考基础内容，后两部分为能力提升内容。","link":""},{"id":"phy0743","t":"万有引力与航天·考情与命题规律","s":"看到【万有引力与航天的高频考点／命题趋势判断】","c":"想到【备考优先级：环绕模型和卫星变轨是拿全基础分的核心；黑洞、拉格朗日点等新概念多以题干信息形式考查，重点在临场信息提取】；警惕【北京卷可能出现在解答题中，题型不限于选择题】","src":"物一轮117.【课前必看】本讲听课建议_笔记","note":"视频|03:44","orig":"（知识）每年必考1道选择题，难度中等（分值占比约6-8%）；近年新增黑洞、拉格朗日点等新概念考查；环绕模型近2年出现在贵州、海南等5省考题中，卫星变轨被浙江、安徽等4省重点考查。","link":""},{"id":"phy0744","t":"万有引力与航天·核心考点框架","s":"看到【双星系统／天体新信息类题目特征】","c":"想到【双星抓住『同轴』特征：周期与角速度相同，引力大小相等；新信息题本质是用万有引力=向心力处理新包装的老模型】；警惕【新信息题失分点在隐含物理条件的挖掘而非计算】","src":"物一轮117.【课前必看】本讲听课建议_笔记","note":"视频|03:44","orig":"（知识）环绕中心天体模型：运动学量比较及中心天体质量密度测算；变轨问题：宇宙速度计算、离心/向心运动；双星系统：周期、角速度相同，质量比与轨道半径关系；新信息问题：暗物质、引力波等新概念的隐含条件挖掘。","link":""},{"id":"phy0745","t":"卫星·定义与受力特征","s":"看到【判断某物体是否算卫星／卫星的受力特点】","c":"想到【卫星的核心特征：无动力稳定运行，万有引力全部用于提供向心力】；警惕【发射阶段需消耗能量，稳定运行阶段不需要动力】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|00:53-04:15","orig":"（知识）卫星是能稳定在天上运动而不掉下来的物体，无需持续动力（区别于飞机、鸟类）；其重力为零，万有引力全部提供向心力（F万=F向），等式含方向相同与大小相等两层含义。","link":""},{"id":"phy0746","t":"卫星·轨道可行性判断","s":"看到【判断卫星轨道（尤其非赤道平面或偏心轨道）是否可行】","c":"想到【圆轨道圆心必须与中心天体球心重合，保证万有引力方向始终指向轨道圆心即提供向心力】；警惕【只看轨道形状不看圆心位置是常见失分点】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|04:43-06:04","orig":"（例）判断不同颜色轨道是否可行：圆心与地心重合的轨道（蓝、黄）可行；圆心偏离地心的轨道（红）不可行，因其万有引力与向心力方向不一致。","link":""},{"id":"phy0747","t":"卫星·字母含义与r=R+h","s":"看到【题目给的是距表面高度 h 还是轨道半径 r】","c":"想到【所有公式中的 r 都是轨道半径（球心距），代入前先换算 r=R+h】；警惕【把高度 h 直接当轨道半径 r 用是高频错误】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|08:34-11:46","orig":"（知识）中心天体质量用 M、环绕天体质量用 m；轨道半径 r 是球心到卫星的距离，中心天体半径为 R，高度 h 是距表面距离，r=R+h。","link":""},{"id":"phy0748","t":"卫星·运动学公式与高轨低速大周期","s":"看到【比较同一中心天体下不同轨道卫星的 v、$\\omega$、a、T】","c":"想到【直接套『高轨低速大周期』：轨道越高线速度、角速度、加速度越小，周期越大】；警惕【四个公式必须熟到直接应用；r 是轨道半径不是高度；线速度与 r 成反比、周期与 r 的 3/2 次方成正比，指数别记错】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|11:47-16:55","orig":"（知识）由 GMm/r²=m v²/r 推得：v=√(GM/r)、ω=√(GM/r³)、T=2π√(r³/GM)、a=GM/r²。各量仅由 M 和 r 决定：r 增大时 v、ω、a 减小，T 增大。口诀『高轨低速大周期』。","link":""},{"id":"phy0749","t":"卫星·动能与周期比例计算","s":"看到【求两卫星动能之比、周期之比等比例运算】","c":"想到【先写出 Ek=GMm/2r、T∝√(r^{3}) 的标度关系，再按比值代入】；警惕【动能还与环绕天体质量 m 有关，比较不同质量卫星时不能只看 r】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|16:55-19:47","orig":"（例）由 Ek=½mv² 与 v=√(GM/r) 推出动能与 r 成反比、周期与 r³ 成正比，建立比例关系求解，答案 A。","link":""},{"id":"phy0750","t":"卫星·亮度周期反推轨道","s":"看到【以亮度（或掩星）变化周期为载体考查环绕规律】","c":"想到【识别亮度变化周期就是公转周期，之后回到 T=2$\\pi$√(r^{3}/GM) 与 a=GM/r^{2} 基本公式】；警惕【加速度公式 a=GM/r^{2} 的指数是 2，选项常故意写成其他指数】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|19:47-25:58","orig":"（例）行星公转引起亮度变化：亮度变化周期=公转周期=t₁−t₀，再由 T=2π√(r³/GM) 反推轨道半径；注意 D 选项加速度表达式指数错误，答案 B。","link":""},{"id":"phy0751","t":"卫星·最大视角几何问题","s":"看到【从地球看行星的最大视角／张角问题】","c":"想到【最大视角对应视线与行星轨道相切，连地球与该行星的连线构成直角三角形，用 sin$\\theta$=r行星/l 求轨道半径比，再套高轨低速大周期比较】；警惕【切点处视线垂直于轨道半径，几何关系别画错】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|25:58-31:27","orig":"（例）水星和金星公转：最大视角时地球-行星连线与行星轨道相切，建立直角三角形得 r=l·sinθm；金星轨道高→周期大，水星轨道低→加速度大，半径比=sinαm:sinβm，答案 BC。","link":""},{"id":"phy0752","t":"卫星·同步卫星五定","s":"看到【同步卫星的特征或轨道参数】","c":"想到【同步卫星五定：T=24h、r≈7R、h≈6R、v 与 $\\omega$ 固定；所有同步卫星这些量完全相同】；警惕【r≈7R 是轨道半径，h≈6R 是离地高度，两者勿混】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|31:37-33:50","orig":"（知识）同步卫星周期与地球自转相同（T=24h），五定：周期、轨道半径（r≈7R）、高度（h≈6R，约36000km）、线速度、角速度均固定，与卫星质量和形状无关。","link":""},{"id":"phy0753","t":"卫星·近地卫星五最","s":"看到【近地卫星的最大／最小物理量或 7.9km/s、84min 等特征值】","c":"想到【近地卫星五最：r 最小、v/$\\omega$/a 最大、T 最小（约84min），v=√(GM/R)=√(gR)≈7.9km/s】；警惕【向心加速度 a 使卫星做圆周运动，g 使物体自由落体，数值相同但物理意义不同；忽略500km 高度误差在1%以内】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|33:50-38:24","orig":"（知识）近地卫星轨道半径≈地球半径（高度约500km 可忽略），五最：轨道半径最小、v 最大（√(GM/R)≈7.9km/s）、ω 最大、T 最小（≈84min）、向心加速度最大（≈9.8m/s²）。a 与 g 数值相同但意义不同。","link":""},{"id":"phy0754","t":"卫星·三体比较","s":"看到【赤道物体、近地卫星、同步卫星三者物理量比较】","c":"想到【先分类后比较：卫星间动力学规律相同（F万=F向）用高轨低速大周期；赤道物体与同步卫星运动学规律相同（同轴，$\\omega$、T 相同）用 v=$\\omega$r、a=$\\omega$^{2}r 比较】；警惕【赤道物体 F万≈F向+F重（引力并未全部提供向心力），不能对它套用卫星公式；比较顺序是借助同步卫星作桥梁】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|43:40-45:33","orig":"（例）赤道物体 a、近地卫星 b、同步卫星 c 比较：先分类再比较得 ωb>ωa=ωc，vb>vc>va，ab>ac>aa，Tb<Ta=Tc（Ta=Tc=24h，Tb≈84min）。","link":""},{"id":"phy0755","t":"卫星·光带成分判断","s":"看到【给 v-r 或 v^{2}-1/r 图象判断一群天体是环绕卫星还是同轴转动部分】","c":"想到【动力学一致的卫星群 v^{2}∝1/r；同轴转动的组成部分 v∝r；把图象转化为正比例关系（如 v^{2}-1/r）验证】；警惕【仅曲线下降不能确定反比关系，必须看是否为过原点直线】","src":"物一轮118.卫星的运动学物理量比较_笔记","note":"视频|48:33","orig":"（例）判断光带是卫星群还是天体组成部分：卫星群满足 v²∝1/r（过原点的 v²-1/r 直线，答案 D）；组成部分同轴转动满足 v∝r（对应 v-r 正比图象）。","link":""},{"id":"phy0756","t":"天体测量·忽略自转测质量","s":"看到【已知重力加速度 g 和天体半径求中心天体质量】","c":"想到【用 M=gr^{2}/G（黄金代换的逆用），前提是忽略天体自转】；警惕【r 与 g 必须取自同一位置，r 是到中心天体球心的距离】","src":"物一轮119.测量中心天体的质量密度_笔记","note":"视频|01:12-01:44","orig":"（知识）基于万有引力等于重力 GMm/r²=mg，得 M=gr²/G。必须同时知道测量点的重力加速度 g 和该点到中心的距离 r；典型场景为地球表面物体（r 即地球半径）。","link":""},{"id":"phy0757","t":"天体测量·卫星法测质量（四选二）","s":"看到【已知卫星的轨道参数组合，判断能否算出中心天体质量】","c":"想到【四选二原则：r 必须已知，再配 a/v/$\\omega$/T 中任意一个独立量；若缺 r 则需先用运动学关系（v=2$\\pi$r/T 等）把 r 解出来】；警惕【$\\omega$ 与 T 等价不能同时作为两个已知量；确认被测天体处于中心天体位置】","src":"物一轮119.测量中心天体的质量密度_笔记","note":"视频|01:44-06:04","orig":"（知识）基于 GMm/r²=ma向，需轨道半径 r 搭配任意一个运动学量（a、v、ω、T 四选一）。例外：ω 和 T 不能同时用（因 ω=2π/T 不含 r，二者不独立）。组合示例：a 与 v 由 a=v²/r 解 r；v 与 T 由 v=2πr/T 解 r。","link":""},{"id":"phy0758","t":"天体测量·密度常规法","s":"看到【求中心天体密度且给了天体半径 R】","c":"想到【先测质量（两个量），再除以体积 V=4$\\pi$R^{3}/3，共需三个量】；警惕【体积公式中的 R 是天体自身半径，不是轨道半径 r】","src":"物一轮119.测量中心天体的质量密度_笔记","note":"视频|06:04-07:23","orig":"（知识）ρ=M/V，V=4πR³/3。常规方法需三个物理量：质量公式中的两个量（g+r 或卫星四选二）加中心天体半径 R。","link":""},{"id":"phy0759","t":"天体测量·一个物理量测密度","s":"看到【仅给近地卫星的周期（或角速度）求中心天体密度】","c":"想到【近地条件 r=R 下一个量即可测密度：$\\rho$=3$\\pi$/(GT^{2}) 或 $\\rho$=3$\\omega$^{2}/(4$\\pi$G)】；警惕【只有 $\\omega$、T 有效，v、a、g+r 的组合都无法消去 r^{3}；前提必须是近地】","src":"物一轮119.测量中心天体的质量密度_笔记","note":"视频|07:23-11:49","orig":"（知识）当 r=R（近地卫星或地表物体）时，质量公式中 r³ 与体积公式 R³ 约去，仅需角速度 ω 或周期 T：ρ=3ω²/(4πG) 或 ρ=3π/(GT²)。忽略自转法（含 r²）与线速度法（含 r¹）无法完全约简。","link":""},{"id":"phy0760","t":"天体测量·能否测质量的判断","s":"看到【组合选项判断能否测某天体质量】","c":"想到【逐项核对：测量公式围绕的是中心天体——用环绕天体的数据测出的是被环绕天体的质量】；警惕【D 类陷阱：研究对象错位，地球绕太阳的数据只能测太阳质量】","src":"物一轮119.测量中心天体的质量密度_笔记","note":"视频|11:49-13:54","orig":"（例）判断哪些选项能测地球质量：A 已知 R 和 g（M=gR²/G）可；B 已知卫星 v 和 T（先求 r 再求 M）可；C 已知月球 T 及地月距离（开普勒第三定律）可；D 用地球绕太阳的数据算出的是太阳质量，不可。答案 ABC。","link":""},{"id":"phy0761","t":"天体测量·含高度比的密度计算","s":"看到【轨道高度用天体半径的倍数 k 表示，求天体密度】","c":"想到【先把高度换算成轨道半径 r=(k+1)R，代入四选二公式求 M，再除以 V=4$\\pi$R^{3}/3，R^{3} 自动约去】；警惕【(k+1) 的立方与轨道半径三次方配套，别漏掉 +1】","src":"物一轮119.测量中心天体的质量密度_笔记","note":"视频|13:54-17:22","orig":"（例）月球卫星轨道高度为 R 的 k 倍：轨道半径 r=(k+1)R，由 GMm/r²=m(4π²/T²)r 解得 M=4π²(k+1)³R³/(GT²)，密度 ρ=3π(k+1)³/(GT²)。答案 D。","link":""},{"id":"phy0762","t":"天体测量·比例估算","s":"看到【两套轨道数据成小数倍数关系，求中心天体质量比】","c":"想到【用 r^{3}/T^{2} 的比例式（开普勒第三定律形式）列比值，数量级估算时相近因子可约简】；警惕【估算后考虑修正方向（分子略大则结果略大），选最接近的选项】","src":"物一轮119.测量中心天体的质量密度_笔记","note":"视频|17:22-21:37","orig":"（例）红矮星：其行星轨道 r'=0.07r、周期 T'=0.06T，质量比 M红/M太=(r'³/T'²)/(r³/T²)=0.07³/0.06²，近似约简后略大于0.07，最接近0.1。答案 B。","link":""},{"id":"phy0763","t":"天体测量·密度定周期","s":"看到【近地卫星周期与中心天体密度的关系（或已知密度求周期）】","c":"想到【结论『密度定周期，与半径无关』：T=√(3$\\pi$/(G$\\rho$))，可正向求密度也可逆向由密度求周期】；警惕【该式只对近地卫星（r=R）成立】","src":"物一轮119.测量中心天体的质量密度_笔记","note":"视频|21:37-24:49","orig":"（例）由密度定义 ρ=M/(4πR³/3) 与近地卫星向心方程 GMm/R²=m(4π²/T²)R 联立得 T=√(3π/(Gρ))：近地卫星周期仅取决于中心天体密度，与半径无关。答案 A。","link":""},{"id":"phy0764","t":"宇宙速度·三个宇宙速度数值与含义","s":"看到【三个宇宙速度的数值大小或发射／逃逸判断】","c":"想到【7.9、11.2、16.7 km/s 依次对应：入轨环绕（最小发射=最大环绕）、脱离地球、脱离太阳】；警惕【单位是 km/s；第一宇宙速度的双重含义（最小发射速度 vs 最大环绕速度）是必考点】","src":"物一轮120.三个宇宙速度_笔记","note":"视频|00:17-10:26","orig":"（知识）第一宇宙速度 7.9km/s：最小发射速度、最大环绕速度；第二宇宙速度 11.2km/s：摆脱地球引力；第三宇宙速度 16.7km/s：摆脱太阳引力。单位是 km/s 而非 m/s。","link":""},{"id":"phy0765","t":"宇宙速度·第一宇宙速度推导","s":"看到【推导或计算第一宇宙速度】","c":"想到【两条等价路径：v=√(GM/R) 与 v=√(gR)，核心是近地卫星 r≈R 这一近似】；警惕【地表公式用于卫星依赖黄金代换这一纯数学代换，使用时确认 g、R 取自同一中心天体】","src":"物一轮120.三个宇宙速度_笔记","note":"视频|00:17-10:26","orig":"（知识）推导逻辑：近地卫星轨道半径≈地球半径。公式1：v=√(GM/R)（万有引力=向心力）；公式2：v=√(gR)（黄金代换代换 GM=gR²）。","link":""},{"id":"phy0766","t":"宇宙速度·三体运动比例链比较","s":"看到【赤道物体、近地卫星、同步卫星三者 v 或 a 的比例计算】","c":"想到【以同步卫星为桥梁分段列比例：同轴 pair 用 v=$\\omega$r、a=$\\omega$^{2}r；卫星 pair 用 v=√(GM/r)、a=GM/r^{2}，再把两段比例相乘衔接】；警惕【比例相乘时中间量（同步卫星）必须约干净；近地卫星半径取 R、同步卫星取 7R】","src":"物一轮120.三个宇宙速度_笔记","note":"视频|10:26-16:57","orig":"（例）赤道物体 v₁、近地卫星 v₂（第一宇宙速度）、同步卫星 v₃：赤道与同步卫星 ω 相同得 v₁:v₃=1:7（半径 1:7）；近地与同步卫星用 v=√(GM/r) 得 v₂:v₃=√7:1；加速度 a₁:a₃=1:7、a₂:a₃=49:1，故 a₁:a₂=1:343。","link":""},{"id":"phy0767","t":"宇宙速度·其他天体的环绕速度","s":"看到【比较另一天体的环绕速度／近地周期与地球第一宇宙速度】","c":"想到【用 v=√(gR) 与 T=2$\\pi$√(R/g) 代入重力加速度比和半径比即可，黄金代换对任意天体普遍适用】；警惕【v 的比是 (g比$\\times$R比) 的平方根，周期比是 (R比/g比) 的平方根，勿把平方根漏掉或开错对象】","src":"物一轮120.三个宇宙速度_笔记","note":"视频|16:57","orig":"（例）月球探测器：g月=g地/6、R月=R地/4，返回舱轨道半径≈R月。v月=√(g月R月)=(1/√6)(1/2)v地=v地/√24，月球环绕速度小于地球第一宇宙速度；周期比 T月/T地=√(6/2)，黄金代换 GM=gR² 在卫星问题中普遍适用。","link":""},{"id":"phy0768","t":"万有引力·卫星变轨规律","s":"看到【卫星从低轨道变轨到高轨道】","c":"想到【两次加速（近地点P、远地点Q各一次），加速瞬间v↑使所需向心力突破引力平衡而做离心运动进入椭圆转移轨道】；警惕【变轨不能直接跳轨，必须经椭圆转移轨道过渡】","src":"物一轮121.卫星的变轨_笔记","note":"视频|00:17-06:40","orig":"（知识）低轨到高轨需两次瞬时加速：近地点P加速进入椭圆转移轨道（离心运动），远地点Q再加速进入高轨圆轨道。圆轨道满足供需平衡F引=F向，P点F引<F向做离心运动，Q点F引>F向做向心运动。","link":""},{"id":"phy0769","t":"万有引力·卫星变轨速度悖论","s":"看到【卫星两次加速后最终速度反而减小】","c":"想到【升轨两次加速但椭圆段动能持续转化为势能，最终高轨环绕速度更小，即「高轨低速大周期」】；警惕【加速是瞬时操作，轨道上飞行时速度连续变化而非突变】","src":"物一轮121.卫星的变轨_笔记","note":"视频|06:40-09:38","orig":"（知识）两次加速最终高轨速度反而更小：转移轨道上速度持续减小（v∝1/r的趋近关系）；由开普勒第二定律，椭圆轨道近点速度大远点速度小，v_P>v_Q；对比结论：低轨圆轨道速度v₃>v₁（高轨）。","link":""},{"id":"phy0770","t":"万有引力·卫星降轨规律","s":"看到【卫星从高轨道变轨到低轨道】","c":"想到【两次减速（切点各一次），最终低轨环绕速度更大】；警惕【降轨中间过程速度是增加的，与升轨相反，勿凭直觉误判】","src":"物一轮121.卫星的变轨_笔记","note":"视频|09:38-09:54","orig":"（知识）高轨到低轨为逆向操作：P点减速进入椭圆轨道，Q点减速进入低轨；初始高轨速度小，最终低轨速度大，中间过程速度增加。","link":""},{"id":"phy0771","t":"万有引力·变轨中速度比较","s":"看到【比较多个轨道上不同位置的速度大小】","c":"想到【先判断比较类型再选规律：圆轨道之间用「高轨低速」，同一椭圆近快远慢（开二），切点用变轨点速度突变规律】；警惕【混淆三类比较对应的规律是主要失分点】","src":"物一轮121.卫星的变轨_笔记","note":"视频|10:04-12:38","orig":"（知识）三类比较各有对应规律：不同圆轨道用「高轨低速」（v₃>v₁）；同一椭圆轨道不同点用开普勒第二定律（v_P>v_Q）；不同轨道切点用变轨规律（v₂P>v₃P，v₁Q>v₂Q）。","link":""},{"id":"phy0772","t":"万有引力·变轨中周期比较","s":"看到【比较不同轨道（含椭圆转移轨道）的周期】","c":"想到【周期由轨道尺寸决定：圆轨道比半径，椭圆轨道比半长轴，用开三r^{3}/T^{2}=k，轨道越高周期越长】；警惕【椭圆轨道必须用半长轴而非某点距离代入开三】","src":"物一轮121.卫星的变轨_笔记","note":"视频|12:38-14:14","orig":"（知识）圆轨道直接比半径（r↑则T↑）；椭圆轨道用开普勒第三定律r³/T²=k。半长轴关系r₃<a₂<r₁对应T₃<T₂<T₁。","link":""},{"id":"phy0773","t":"万有引力·变轨中加速度比较","s":"看到【比较卫星在不同轨道上同一点（切点）的加速度】","c":"想到【同一点万有引力相同，加速度必相同，与所在轨道无关；不同位置用a=GM/r^{2}比距离】；警惕【误认为高轨上加速度更小而否认切点加速度相等】","src":"物一轮121.卫星的变轨_笔记","note":"视频|14:14-15:03","orig":"（知识）同一点加速度相同（a=GM/r²仅与到中心天体距离有关）：轨道三P点与轨道二P点加速度相同；不同点距离越近加速度越大，Q点加速度小于P点。","link":""},{"id":"phy0774","t":"万有引力·变轨例题","s":"看到【航天器在圆轨道与椭圆轨道间切换的选择题】","c":"想到【逐项套用四规律：椭圆近快远慢、半长轴定周期、变轨点减速/加速、同点加速度相同】；警惕【混淆不同比较类型对应的规律】","src":"物一轮121.卫星的变轨_笔记","note":"视频|15:03-17:45","orig":"（例）航天飞机从圆轨道I变到椭圆轨道II（高轨到低轨）：A远地点速度<近地点（开二）；B轨道II半长轴<I半径故周期更小；C高轨到低轨需减速（对）；D同一点加速度相同。答案C。","link":""},{"id":"phy0775","t":"万有引力·近月点物理量比较例题","s":"看到【两个椭圆轨道（如捕获轨道与工作轨道）的物理量比较】","c":"想到【先明确两椭圆轨道的相对高低（比半长轴），再分别用开三比周期、开二比近远点速度、变轨规律比切点速度】；警惕【两个都是椭圆轨道时不能直接用圆轨道「高轨低速」口诀比速度】","src":"物一轮121.卫星的变轨_笔记","note":"视频|17:45-20:20","orig":"（例）嫦娥卫星捕获轨道a₁=51900km与冻结轨道a₂=9900km（T₂=24h）：A捕获轨道半长轴大周期大（开三）；B近月点速度>远月点（开二）；C高轨近月点需加速进入（对）；D同高度加速度相同。答案C。","link":""},{"id":"phy0776","t":"万有引力·宇宙速度","s":"看到【考查三大宇宙速度的含义或大小】","c":"想到【7.9km/s双重身份：最小发射速度=近地卫星最大环绕速度；11.2脱离地球、16.7脱离太阳】；警惕【第一宇宙速度是环绕速度的最大值而非最小值】","src":"物一轮121.卫星的变轨_笔记","note":"视频|20:20","orig":"（知识）第一宇宙速度v₁=7.9km/s：最小发射速度，也是近地卫星的最大环绕速度；第二宇宙速度v₂=11.2km/s：摆脱地球引力的最小发射速度；第三宇宙速度v₃=16.7km/s：摆脱太阳引力的最小发射速度。","link":""},{"id":"phy0777","t":"万有引力·双星模型特点","s":"看到【两个天体相互环绕、绕连线上某点转动的双星系统】","c":"想到【向心力来源是彼此间的万有引力，两星受到的引力等大；圆心O必须在两星连线上且无实体】；警惕【引力公式中的r是两星间距L，向心力公式中的r是各自轨道半径，两者不同】","src":"物一轮122.双星模型_笔记","note":"视频|00:21-04:16","orig":"（知识）两星绕连线上固定点O做圆周运动，O仅为几何中心非实体天体；两星间万有引力互为作用力与反作用力，等大（F_A=F_B），各自提供向心力。","link":""},{"id":"phy0778","t":"万有引力·双星运动特点","s":"看到【双星系统比较角速度、线速度或周期】","c":"想到【双星同轴转动：$\\omega$和T相同；线速度v=$\\omega$r与轨道半径成正比】；警惕【角速度相同但线速度不同，勿混为一谈】","src":"物一轮122.双星模型_笔记","note":"视频|00:21-04:16","orig":"（知识）角速度相同ω_A=ω_B（必须保持O点始终在连线上）；轨道半径关系r_A+r_B=L；同ω下v=ωr，半径大者线速度大。","link":""},{"id":"phy0779","t":"万有引力·双星基本方程","s":"看到【求双星的轨道半径或质量关系】","c":"想到【列「万有引力=向心力」方程加间距关系L=r_A+r_B联立求解，核心结论：半径与质量成反比（m_Ar_A=m_Br_B）】；警惕【向心力公式里的r是各自轨道半径，不能直接代入两星间距】","src":"物一轮122.双星模型_笔记","note":"视频|04:16-11:51","orig":"（知识）对A：Gm_Am_B/L²=m_Aω²r_A，对B：Gm_Am_B/L²=m_Bω²r_B，且L=r_A+r_B；联立得m_Ar_A=m_Br_B，即r_A/r_B=m_B/m_A。","link":""},{"id":"phy0780","t":"万有引力·双星半径与周期公式","s":"看到【直接求双星的轨道半径分配、角速度或周期】","c":"想到【半径按质量反比分配总间距；周期公式与环绕模型类比：质量项换为两星质量和，距离项换为两星间距L】；警惕【公式中用的是总质量(m_A+m_B)和间距L，不是单个质量或单个半径】","src":"物一轮122.双星模型_笔记","note":"视频|04:16-11:51","orig":"（知识）r_A=m_B/(m_A+m_B)·L，r_B=m_A/(m_A+m_B)·L；ω=√[G(m_A+m_B)/L³]，T=2π√[L³/(G(m_A+m_B))]。记忆：L按质量反比分配，A星占m_B份、B星占m_A份。","link":""},{"id":"phy0781","t":"万有引力·双星求质量例题","s":"看到【已知双星周期与间距（或轨道半径）反推星体质量】","c":"想到【套用双星结论公式联立消元（如m=4$\\pi$^{2}r^{2}r^{'}/(GT^{2})型结果），优先用结论避免复杂推导】；警惕【代入时区分两星间距与各自轨道半径的符号】","src":"物一轮122.双星模型_笔记","note":"视频|11:51-15:27","orig":"（例）已知周期T、两星间距r和某星轨道半径r₁，联立周期公式与半径质量关系消去m₁，得m₂=4π²r²r₁/(GT²)，答案D。技巧：直接用双星结论比重新推导高效。","link":""},{"id":"phy0782","t":"万有引力·双星定性比较例题","s":"看到【双星定性比较质量、线速度、周期或讨论总质量/间距变化】","c":"想到【半径大$\\to$质量小、线速度大；T∝L^{3}/(m_A+m_B)，间距减小周期减小、总质量减小周期增大】；警惕【区分总质量M与单个质量；参数间用比例关系判断而非背数值】","src":"物一轮122.双星模型_笔记","note":"视频|15:27","orig":"（例）r_A>r_B：由半径质量反比得m_A<m_B（A错）；同ω下v=ωr，r_A大则v_A大（B对）；M减小则T增大（C错）；L减小则T减小（D对）。答案BD。","link":""},{"id":"phy0783","t":"万有引力·黑洞","s":"看到【题目给出「光无法逃逸」或「不可见」的天体】","c":"想到【译成条件：逃逸速度$\\geq$c，即√(2GM/r)$\\geq$c，解出临界半径或密度】；警惕【第二宇宙速度是第一宇宙速度的√2倍，不要漏掉根号】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|00:32-04:29","orig":"（知识）黑洞：引力极强使光无法逃逸而不可见的天体；关键条件是第二宇宙速度≥光速c=3×10⁸ m/s；第二宇宙速度=√2×第一宇宙速度，v₁=√(GM/r)。","link":""},{"id":"phy0784","t":"万有引力·黑洞临界计算","s":"看到【恒星收缩为黑洞求半径/密度临界值】","c":"想到【用「质量不变」分别列原天体与黑洞的逃逸速度方程，联立消GM；不等式取等号算临界值】；警惕【忽略题干隐含条件如「质量不变」；临界问题先把不等式当等式解】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|04:29-09:09","orig":"（例）太阳逃逸速度为c/500，收缩为黑洞后质量不变、半径变为r：建立√(2GM/R)=c/500与√(2GM/r)≥c，联立取等号求临界值得R/r≥2.5×10⁵，答案C。","link":""},{"id":"phy0785","t":"万有引力·拉格朗日点","s":"看到【卫星位于拉格朗日点（L1—L5）】","c":"想到【相对静止$\\Rightarrow$$\\omega$、T与环绕天体相同；向心力由两引力的合力提供（L1/L2处引力同向叠加）】；警惕【合力不是单一引力；L4/L5需按双星/复合转动中心处理，向心力指向转动中心而非太阳】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|04:29-09:09","orig":"（知识）小物体在两大物体引力作用下保持相对静止的空间点；L1/L2位于两物体连线之间及外侧且关于小天体对称，L3与大天体对称，L4/L5与小大天体构成等边三角形。动力学：小物体受两个万有引力合力提供向心力；运动学：ω和T与两大物体相同。","link":""},{"id":"phy0786","t":"万有引力·拉格朗日点例题","s":"看到【比较拉格朗日点卫星与月球（或行星）的v、a、T】","c":"想到【抓住$\\omega$相同这一核心，用v=$\\omega$r、a=$\\omega$^{2}r比较线速度与向心加速度：半径大者v、a均大】；警惕【周期与月球相同，不是更快或更慢】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|09:09-26:42","orig":"（例）地月系L2点卫星：A向心力来自地球和月球引力合力（B对C错：ω与月球相同）；因r卫星>r月球且ω相同，v=ωr得v卫星>v月球（B对），a=ω²r得a卫星>a月球（D对）。答案BD。","link":""},{"id":"phy0787","t":"万有引力·Halo轨道卫星","s":"看到【Halo轨道或「仅极少量燃料长期维持轨道」的卫星】","c":"想到【相对静止$\\Rightarrow$$\\omega$与被同步天体相同；无动力运行时只有引力做功$\\Rightarrow$机械能守恒】；警惕【发射速度判断看参照的引力体系，不能乱套第一宇宙速度】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|09:09-26:42","orig":"（例）卫星实际运行在L2附近的Halo轨道：A作为地球卫星只需大于第一宇宙速度（错）；B角速度与月球相同（对，错选）；C无动力运行机械能守恒（对）；D合力需提供绕地球和L2点的复合运动（错）。答案C。","link":""},{"id":"phy0788","t":"万有引力·日月系拉格朗日点例题","s":"看到【航天器与两大天体构成等边三角形（L4/L5点）】","c":"想到【三者同$\\omega$同T；轨道半径大小用几何关系（两边之和大于第三边）比较，再由v=$\\omega$r、a=$\\omega$^{2}r排序】；警惕【向心力指向系统转动中心，不一定指向太阳】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|26:42-31:10","orig":"（例）太阳-地球-航天器构成等边三角形（L4/L5型）：三者周期相同（A错）；a=ω²r且用三角形两边之和大于第三边证r_c>r_b，得a_c>a_b（B错）、v_c>v_b（D对）；向心力指向转动中心而非太阳（C错）。答案CD。","link":""},{"id":"phy0789","t":"万有引力·潮汐成因","s":"看到【潮汐现象、近月点与远月点海水同时鼓包】","c":"想到【用「引力与所需向心力之差」分析：引大于向则向月鼓包，引小于向则背月鼓包，两面都涨潮】；警惕【远月点鼓包不是被「甩开」那么简单，是引力小于所需向心力形成离心趋势】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|31:17-36:30","orig":"（知识）潮汐主要由月球引力引起（太阳影响约为月球1/2）；地心处F引=F向平衡，近月点F引>F向海水向月鼓包，远月点F引<F向海水离心鼓包，故正对和背对月球各涨潮一次，地球自转使每天两次涨潮。","link":""},{"id":"phy0790","t":"万有引力·洛希极限","s":"看到【天体靠近后解体、物质被吸离，或「洛希极限」一词】","c":"想到【临界条件：中心天体在该处的引力=卫星（天体）表面物体的自身引力，列平衡方程求解临界距离】；警惕【所求距离常是两表面间距离而非质心距，注意几何换算】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|36:30-37:30","orig":"（知识）洛希极限：天体自身引力与邻近天体潮汐力相等时的临界距离；两天体距离小于洛希极限时潮汐力导致天体解体（如海水、岩石被吸离）。","link":""},{"id":"phy0791","t":"万有引力·潮汐锁定","s":"看到【天体始终以同一面朝向中心天体】","c":"想到【潮汐锁定$\\Rightarrow$T自=T公，自转角速度等于公转角速度，可据此列式计算周期或角速度】；警惕【环绕模型只能求中心天体质量，求不出被锁定天体自身质量】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|37:30-39:53","orig":"（知识）被锁定天体始终以同一面朝向中心天体；原理是自转周期=公转周期，公转角度与自转角度始终抵消（月球公转1周同时自转1周，背面永远背对地球）。","link":""},{"id":"phy0792","t":"万有引力·潮汐力方向例题","s":"看到【判断近月点/远月点潮汐力方向或组成】","c":"想到【潮汐力是引力与参考系离心效应的合力，两侧极值点方向都背离地心；复杂公式可代$\\theta$=0$^{\\circ}$、180$^{\\circ}$特值验证】；警惕【把「主要作用力」等同「唯一作用力」，忽视另一天体引力的贡献】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|39:53-45:57","orig":"（例）月潮力=月球引力与惯性离心力（地球引力部分）的合力而非单一力：近月点与远月点月潮力方向均背离地心；代入θ=0°和180°验证极值点，答案D。","link":""},{"id":"phy0793","t":"万有引力·洛希极限计算例题","s":"看到【求天体瓦解临界距离（洛希极限数值）】","c":"想到【列「中心天体引力=卫星自身引力」平衡方程，用黄金代换GM=gR^{2}把未知质量换成g和半径】；警惕【区分地球半径R与月球半径r月的不同符号；「不考虑自转」提示必须用黄金代换】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|45:57-49:42","orig":"（例）月球表面物体满足GM地m/(R+h)²=GM月m/r月²时开始瓦解；用黄金代换GM地=g地R²、GM月=g月r月²（g地=6g月），化简得6R=R+h，h=(√6−1)R。","link":""},{"id":"phy0794","t":"万有引力·潮汐锁定综合计算例题","s":"看到【潮汐锁定结合光照/遮挡求可照时间或周期】","c":"想到【先由万有引力+黄金代换求$\\omega$、T，再把三维遮挡问题降为二维几何：cos$\\theta$=R/r定张角，按角度占比t=($\\theta$/$\\pi$)T求时间】；警惕【注意题干简化假设如「太阳光平行照射」；同时考虑地球阴影锥与自身背面两种遮挡】","src":"物一轮123.天体问题中的新信息_笔记","note":"视频|49:42","orig":"（例）由ω²=gR²/r³求角速度（黄金代换）；用cosθ=R/r确定月球可被照亮的张角，可照时间t=(2θ/2π)T=θT/π；潮汐锁定⇒T自=T公=2π/ω（C对）。","link":""},{"id":"phy0795","t":"机械能·两种分析视角","s":"看到【力学问题需要选择牛顿定律还是能量方法】","c":"想到【涉及时间累积或求加速度用牛顿定律，涉及位移/空间累积或求速度、能量转化用功能关系，功能视角贯穿力学与电磁学】；警惕【两类视角作用机制不同，勿混用公式】","src":"物一轮124.【课前必看】本讲听课建议_笔记","note":"视频|00:53-03:38","orig":"（知识）牛顿定律视角：力→加速度（F=ma）→速度改变Δv=a·Δt，瞬时效应、时间累积；功能关系视角：力→功（W=Fl）→动能改变，空间累积效应。","link":""},{"id":"phy0796","t":"机械能·功的计算要点","s":"看到【求某个力做功或判断做功正负】","c":"想到【恒力用W=Flcos$\\theta$，由力与位移夹角定正负】；警惕【位移必须取对地位移；正负功误判是高频易错点】","src":"物一轮124.【课前必看】本讲听课建议_笔记","note":"视频|03:38-04:18","orig":"（知识）功是力在空间上的累积效应，定义法W=Flcosθ；正负根据力与位移夹角判断。","link":""},{"id":"phy0797","t":"机械能·功率公式","s":"看到【考查做功快慢或功率计算】","c":"想到【平均功率用P=W/t，瞬时功率用P=Fv（含夹角时P=Fvcos$\\theta$）】；警惕【区分平均与瞬时；功率常与动量等模型综合命题】","src":"物一轮124.【课前必看】本讲听课建议_笔记","note":"视频|03:38-04:18","orig":"（知识）功率是做功快慢的度量：平均功率P=W/t，瞬时功率P=Fv。","link":""},{"id":"phy0798","t":"机械能·本章知识框架","s":"看到【功能关系的整体考查或章节综合题】","c":"想到【分析路径：先算各力功（注意正负与变力功）$\\to$用动能定理联系动能变化$\\to$判断是否满足机械能守恒条件（只有重力/弹力做功）】；警惕【合外力做功对应动能变化而非机械能变化】","src":"物一轮124.【课前必看】本讲听课建议_笔记","note":"视频|04:18","orig":"（知识）三块内容递进：功和功率（力的做功机制）→动能定理（W=ΔEk，功与动能的定量关系）→机械能守恒（仅重力/弹力做功时动能与势能转化，非保守力做功影响守恒判定）。","link":""},{"id":"phy0799","t":"功·功的物理意义","s":"看到【问某力做功对应什么能量转化】","c":"想到【做功必伴随能量转化，功的数值=转化量值，正功对应能向动能方向转化、负功对应消耗动能】；警惕【重力做功对应重力势能与动能的转化，弹力做功对应弹性势能与动能的转化，对应关系要写对】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|01:09-04:50","orig":"（知识）功是能量转化的量度：W=ΔE；只要有力对物体做功，必然存在不同形式能量间的转化，功的数值等于能量转化的量值（如重力做功10J对应10J重力势能与动能的转化）。","link":""},{"id":"phy0800","t":"功·恒力做功公式","s":"看到【求恒力做功或讨论W=Flcos$\\theta$的适用条件】","c":"想到【三个要素：恒力、对地位移、共点夹角；可用分力$\\times$位移或力$\\times$分位移两种投影法简化计算（如平抛中重力功=mgh）】；警惕【位移是作用点的对地位移，与路径无关】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|04:50-05:22","orig":"（知识）W=Flcosθ适用于恒力做功：F为恒力（大小方向不变），l为作用点的对地位移，θ为力F与位移l共点时的夹角；W是标量，单位J。两种投影理解：位移方向分力×位移，或力方向分位移×力。","link":""},{"id":"phy0801","t":"功·多力做功计算例题","s":"看到【斜向上拉力作用下滑动，求各力做功】","c":"想到【先受力分析再逐力用W=Flcos$\\theta$：垂直力不做功；斜拉力使N=mg−Fsin$\\theta$，摩擦力f=$\\mu$N要代入修正后的N】；警惕【误认为N=mg（漏掉拉力竖直分量）；漏掉摩擦力做负功的负号】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|05:22-17:55","orig":"（例）雪橇受重力mg、拉力F、支持力N、摩擦力f：支持力N与s垂直做功为零（错误选项）；重力与s垂直做功为零（B对）；拉力功为Fscosθ而非Fs；摩擦力f=μ(mg−Fsinθ)，功为−μ(mg−Fsinθ)s。答案B。","link":""},{"id":"phy0802","t":"功·对地位移原则","s":"看到【板块模型或传送带中求摩擦力做功】","c":"想到【摩擦力做功用各自物体的对地位移，相对位移只用于算摩擦生热Q=f·$\\Delta$x相对】；警惕【力的来源是相对运动不影响功的计算公式中的位移选择】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|18:27-20:30","orig":"（知识）计算功必须代入受力物体的对地位移而非相对位移；板块模型中物块功W=−f·x₁、木板功W=f·x₂，不能用相对位移Δx。","link":""},{"id":"phy0803","t":"功·作用点位移原则","s":"看到【人蹲起、行走或物体 rolling 类问题中问支持力是否做功】","c":"想到【找该力作用点的对地位移：作用点不动则该力不做功；重心是重力的作用点，其他力作用点需单独分析】；警惕【误用重心位移代替支持力作用点位移】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|20:30-21:14","orig":"（知识）功应用力的作用点的对地位移计算，而非重心位移：人站起过程中支持力N作用点在脚底、位移为零，做功为零；重心上升h只影响重力做功。","link":""},{"id":"phy0804","t":"功·力做功的独立性","s":"看到【同一恒力在不同摩擦条件下做功是否相同】","c":"想到【各力做功相互独立，只看该力与对地位移，不受其他力或运动状态影响】；警惕【误以为粗糙面上因有摩擦恒力F做功会变化】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|21:14-23:51","orig":"（知识）某个力做功仅由该力的大小、位移及夹角决定，与其他力无关：恒力F在光滑面和粗糙面拉动相同距离，W₁=W₂=FL，尽管运动状态（加速/减速）不同。","link":""},{"id":"phy0805","t":"功·总功的计算","s":"看到【求多个力做的总功】","c":"想到【先分别求各力功再代数求和（含正负号），或用合外力$\\times$位移计算】；警惕【功是标量，禁止用矢量合成（勾股定理）求总功】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|23:51-25:29","orig":"（知识）功是标量，求总功时各力做功直接代数相加：F₁做功3J、F₂做功4J（两力垂直），总功=3J+4J=7J，不能误用勾股定理算成5J。","link":""},{"id":"phy0806","t":"功·圆周运动做功例题","s":"看到【绳拉力沿圆弧拉动物体求各力做功】","c":"想到【始终与速度垂直的变力（绳拉力、向心力）做功恒为零；恒力功可用位移投影简化；重力功只看竖直高度差mgh】；警惕【绳拉力方向时刻变化，不能用W=Flcos$\\theta$直接套某一段】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|25:29-32:31","orig":"（例）摆动过程：重力功W_G=−mgh，h=l(1−cos37°)=0.4m，得−4J；恒力F功用水平位移lsin37°计算得6J；绳拉力始终与速度垂直做功为零；总功=−4+6+0=2J。","link":""},{"id":"phy0807","t":"功·匀速运动做功判断例题","s":"看到【匀速运动中判断各力做功正负】","c":"想到【匀速$\\Rightarrow$合力为零$\\Rightarrow$可反推未知力（如摩擦力必存在平衡推力），再按力与位移夹角定正负】；警惕【不能因相对静止误判位移为零；需先由平衡条件确认摩擦力存在】","src":"物一轮125.理解功的物理意义_笔记","note":"视频|32:31","orig":"（例）物体匀速运动：重力与支持力方向与速度垂直均不做功；推力作用点有对地位移且推力向左做负功；摩擦力必存在以平衡推力，方向与位移反向做负功。","link":""},{"id":"phy0808","t":"功·正负功的三种情况","s":"看到【判断某个力做正功、负功还是不做功】","c":"想到【只看力与对地位移（或瞬时速度）的夹角：锐角正功、直角零功、钝角负功】；警惕【功的正负完全由cos$\\theta$决定，F与l均为正值】","src":"物一轮126.定义法判断功的正负_笔记","note":"视频|01:31-04:04","orig":"（知识）W=Flcosθ，θ∈[0°,180°]：0°≤θ<90°锐角做正功；θ=90°直角不做功；90°<θ≤180°钝角做负功。θ=0°力与位移同向做最大正功，θ=180°反向做最大负功。","link":""},{"id":"phy0809","t":"功·正负功的物理意义","s":"看到【问功的正负代表什么物理意义】","c":"想到【正负只标志能量转化方向与力的促进/阻碍作用，−10J的功在数值上小于+5J的说法要按绝对值比较】；警惕【正负号不代表大小，比较做功多少应比绝对值】","src":"物一轮126.定义法判断功的正负_笔记","note":"视频|04:04-05:42","orig":"（知识）正功W>0：其他形式能转化为动能，该力起「动力」作用；负功W<0：动能转化为其他形式能，该力起「阻力」作用。功的正负仅表示能量转化方向，不表示功的大小关系。","link":""},{"id":"phy0810","t":"功·「克服」表述转换","s":"看到【题干出现「克服某力做功」的表述】","c":"想到【「克服X做功W」即X做了−W的功，数值取绝对值】；警惕【填空答「克服做功」时结果必须为正值，与「做功」的代数值表述区分】","src":"物一轮126.定义法判断功的正负_笔记","note":"视频|05:42-07:16","orig":"（知识）「物体克服阻力做功」等价于「阻力对物体做负功」；克服做功的数值取绝对值，如「克服摩擦力做300J功」对应摩擦力做功−300J。","link":""},{"id":"phy0811","t":"功·变力做功正负判断","s":"看到【力方向不断变化（绳拉力、转动支持面、摩擦力）判断其做功】","c":"想到【变力看力与瞬时速度的夹角：始终垂直速度的力不做功，如圆周运动中的绳拉力/向心力】；警惕【不能用某一时刻的位移代替全程，夹角要逐位置分析】","src":"物一轮126.定义法判断功的正负_笔记","note":"视频|07:16-16:56","orig":"（知识）标准流程：受力分析确定各力方向→确定对地位移方向→按夹角判断正负；方向变化的力考察力与瞬时速度方向的夹角。典型：扶梯下降重力正功支持力负功；斜面移动小球支持力正功绳拉力不做功；转动木板上物块摩擦力始终垂直速度不做功。","link":""},{"id":"phy0812","t":"功·斜面做功判断例题","s":"看到【多个力作用下滑斜面，逐项判断做功正负】","c":"想到【逐力画力与位移夹角再定正负：垂直位移的支持力不做功，摩擦力不一定做负功（看夹角）】；警惕【先由运动状态反推未知力（如静摩擦力方向）再判断，勿默认摩擦力做负功】","src":"物一轮126.定义法判断功的正负_笔记","note":"视频|16:56-21:33","orig":"（例）物体沿斜面下滑（受斜向力）：支持力N与斜向位移成钝角做负功（对）；摩擦力f水平向左与位移成锐角做正功；斜面支持力N₁垂直斜面与沿斜面位移垂直不做功；重力做正功。答案AD。","link":""},{"id":"phy0813","t":"功·电梯运货做功例题","s":"看到【自动扶梯/履带电梯上货物匀速运动的做功判断】","c":"想到【先按运动状态与接触面确定受力和有无摩擦力，再判断各力与位移夹角】；警惕【误认为水平扶梯存在摩擦力（匀速无需）；两种电梯支持力方向不同（竖直向上vs垂直斜面）】","src":"物一轮126.定义法判断功的正负_笔记","note":"视频|21:33-24:49","orig":"（例）台式扶梯匀速：仅受重力与支持力（水平面匀速无摩擦），支持力N向上与斜向上位移成锐角做正功（A对）；履带式电梯：支持力N₁垂直斜面不做功，静摩擦力f沿斜面向上与位移同向做正功。答案A。","link":""},{"id":"phy0814","t":"功·平衡状态做功例题","s":"看到【物体匀速运动（三力平衡）判断各力与合力做功】","c":"想到【合力为零则合力做功必为零；静摩擦力方向可与位移成任意角，正负按夹角定】；警惕【静摩擦力不一定做负功；重力做功只与竖直位移有关，水平运动时不做功】","src":"物一轮126.定义法判断功的正负_笔记","note":"视频|24:49","orig":"（例）乒乓球随球拍倾斜匀速：三力平衡（重力G、支持力N垂直拍面、静摩擦f沿拍面向上）；合力为零⇒合力功必为零；重力与水平位移垂直不做功；静摩擦力与位移成钝角做负功；支持力与位移成锐角做正功。答案D。","link":""},{"id":"phy0815","t":"功·正负判断与「克服」","s":"看到【判断功的正负或「克服做功」的符号处理】","c":"想到【按夹角三分法判断正负；「克服X做功」取绝对值报正值】；警惕【克服做功与做负功是同一件事的两种说法，数值要自洽】","src":"物一轮127.定义法计算变力功_笔记","note":"视频|00:04-00:23","orig":"（知识）由W=FLcosθ：0°≤θ<90°功为正，θ=90°功为零，90°<θ≤180°功为负；「克服某力做功」计算结果取绝对值，表示该力做负功。","link":""},{"id":"phy0816","t":"功·F-x图像法求变力功","s":"看到【F-x图像求变力做功】","c":"想到【面积=功：上方正功、下方负功，规则图形直接算面积】；警惕【非规则图像（如反比例曲线）面积不可求时此法失效，需换其他方法】","src":"物一轮127.定义法计算变力功_笔记","note":"视频|00:29-05:05","orig":"（知识）适用条件：一维直线运动、力方向不变但大小可变、图像面积可求；图像与x轴围成的面积表示功：x轴上方为正功、下方为负功。原理：把位移分割为微元Δx，每个微元内视为恒力做功后累积。","link":""},{"id":"phy0817","t":"功·弹簧弹力做功例题","s":"看到【求弹簧弹力做功或「克服弹力做功」】","c":"想到【F=kx是线性变力，用F-x图像三角形面积W=½k$x^2$（x为形变量）】；警惕【问「克服」时结果取正值；明确形变量x与位移h的关系是否相同】","src":"物一轮127.定义法计算变力功_笔记","note":"视频|05:05-09:07","orig":"（例）弹力F=kx随位移线性变化，图像为过原点直线，功的绝对值=三角形面积½kh²；弹力方向与位移相反实际做负功，「克服弹力做功」取绝对值，答案½kh²。","link":""},{"id":"phy0818","t":"功·微元累积法求变力功","s":"看到【力大小不变且始终与速度成恒定夹角（如空气阻力、滑动摩擦力）的做功】","c":"想到【用W=F·s·cos$\\theta$代入总路程s计算，阻力通常$\\theta$=180$^{\\circ}$即W=−Fs】；警惕【此处s是路程不是位移大小；该方法只适用于「大小恒定、方向随速度变化」的力】","src":"物一轮127.定义法计算变力功_笔记","note":"视频|09:07-12:56","orig":"（知识）适用条件：曲线运动、力大小不变、力与速度方向夹角θ恒定；微元段内路程≈位移，累积得W=Fscosθ，s为总路程。典型场景：空气阻力（θ=180°，cosθ=−1）、摩擦力在往复运动中的总功。","link":""},{"id":"phy0819","t":"功·摆球阻力做功例题","s":"看到【圆周/曲线运动中大小恒定的阻力（或摩擦力）做功】","c":"想到【W=−F阻$\\times$路程，先算弧长（如四分之一圆周s=½$\\pi$L）再乘阻力】；警惕【路程用弧长公式计算；阻力方向时刻变化但仍可用微元法，因为它始终与速度反向】","src":"物一轮127.定义法计算变力功_笔记","note":"视频|12:56","orig":"（例）摆球四分之一圆周运动，空气阻力大小不变、始终与速度相反：路程s=½πL，W=−F阻×½πL=−½πF阻L。","link":""},{"id":"phy0820","t":"功率·定义与做功快慢","s":"看到【变力做功但功率恒定（如机车以恒定功率行驶）】","c":"想到【恒功率下用W=Pt直接求功，绕开变力积分】；警惕【W=Pt的前提是功率恒定，功率变化时需分段计算】","src":"物一轮128.对功率的理解和计算_笔记","note":"视频|00:41-02:15","orig":"（知识）功率描述做功快慢：P=W/t，单位时间内完成的功；当力F为变力但功率恒定时，可用W=Pt求功（机车启动问题的典型应用）。","link":""},{"id":"phy0821","t":"功率·平均功率与瞬时功率","s":"看到【区分平均功率与瞬时功率】","c":"想到【平均功率是过程量（总功/总时间），瞬时功率是状态量（某时刻F与v的乘积）】；警惕【先看清题目问的是哪一段时间、哪一时刻、哪个力的功率】","src":"物一轮128.对功率的理解和计算_笔记","note":"视频|02:15-03:10","orig":"（知识）平均功率：一段时间内功率的平均值，P=W/t；瞬时功率：某时刻的功率值，P=lim(t→0)W/t；高中阶段通过推导式求解瞬时功率。","link":""},{"id":"phy0822","t":"功率·推导式P=Fvcosθ","s":"看到【求某时刻的瞬时功率】","c":"想到【用P=Fvcos$\\theta$，取力沿速度方向的分量（或速度沿力方向的分量）乘积；重力功率只看竖直分速度P=mgv_y】；警惕【cos$\\theta$是力与速度的夹角，混淆投影对象会算错】","src":"物一轮128.对功率的理解和计算_笔记","note":"视频|03:10-05:47","orig":"（知识）P=Fvcosθ，F、v均为瞬时值，θ为力与速度夹角；两种投影理解：P=(Fcosθ)v=力在速度方向的投影×速度，或P=F(vcosθ)=力×速度在力方向的投影。应用示例：平抛中重力功率P=mgv_y。","link":""},{"id":"phy0823","t":"功率·平均功率计算","s":"看到【求一段过程的平均功率】","c":"想到【总功/总时间：多阶段分别求功后代数求和再除以总时间】；警惕【第二段有初速度（非零起始），位移计算勿漏；明确所求的是哪个力的功率】","src":"物一轮128.对功率的理解和计算_笔记","note":"视频|05:47-06:35","orig":"（知识）基本方法：先算全程总功W再除以总时间t；多阶段受力不同时需分阶段求功再求和；明确计算的是哪个力的功率。","link":""},{"id":"phy0824","t":"功率·瞬时功率计算","s":"看到【求某一具体时刻的功率】","c":"想到【先定该时刻的F和v，再代P=Fvcos$\\theta$】；警惕【力分段变化时该时刻的力取对应段的值，不能用别的段的力】","src":"物一轮128.对功率的理解和计算_笔记","note":"视频|06:35-07:42","orig":"（知识）关键要素：明确所求时刻（不同时刻功率可能不同）、明确所求力的功率；优先用P=Fvcosθ，需确定该时刻的力和速度。","link":""},{"id":"phy0825","t":"功率·分段运动求功率例题","s":"看到【力分段变化的运动求某时刻瞬时功率和全程平均功率】","c":"想到【瞬时功率用该时刻的F与分段算出的末速度；平均功率=各段功之和/总时间，第二段位移要计入初速度】；警惕【第二段位移按匀变速（非零初速）计算，漏初速度必错】","src":"物一轮128.对功率的理解和计算_笔记","note":"视频|07:42-15:12","orig":"（例）0-2t₀受F₀、2t₀-3t₀受2F₀：3t₀时刻瞬时功率先分段求加速度得末速度v=4F₀t₀/m，代P=Fv得P=8F₀²t₀/m；0-3t₀平均功率分段求位移和功W=8F₀²t₀²/m，除以总时间3t₀得P=8F₀²t₀/3m。答案AC。","link":""},{"id":"phy0826","t":"功率·落地功率比较例题","s":"看到【同一高度经不同路径（自由落体/斜面）下落比较功率】","c":"想到【重力功相同W=mgh；瞬时功率比竖直分速度P=mgv_y；平均功率比时间；仅重力做功时落地速率相同但方向不同】；警惕【落地速度大小相同不等于瞬时功率相同，方向（v_y）才决定重力的瞬时功率】","src":"物一轮128.对功率的理解和计算_笔记","note":"视频|15:12","orig":"（例）四种方式下落同一高度：重力做功均为mgh相同；时间t₁=t₂<t₄<t₃（斜面角度越小时间越长）；落地瞬时功率P=mgv_y，甲乙竖直下落v_y最大，丙丁速度倾斜v_y较小，P₃=P₄<P₁=P₂；平均功率与时间成反比。答案D。","link":""},{"id":"phy0827","t":"机械能·功的概念","s":"看到【判断某力是否做功或计算做功多少】","c":"想到【功是能量转化的量度，用 W=Fscos$\\theta$ 计算，$\\theta$ 为力与位移方向夹角】；警惕【力与位移不垂直才做功，功的正负表示能量输入或输出】","src":"物一轮129.【课前必看】本讲听课建议_笔记","note":"视频|00:08-00:43","orig":"（知识）功是描述能量转化的物理量，计算公式 W=F·s·cosθ；功是能量转化的量度，表示能量转化的多少","link":""},{"id":"phy0828","t":"机械能·动能定理地位","s":"看到【求速度、位移而不求时间、加速度的功能问题】","c":"想到【动能定理是最重要的功能关系，优先考虑用合力功等于动能变化量求解】；警惕【动能定理不涉及时间与加速度信息】","src":"物一轮129.【课前必看】本讲听课建议_笔记","note":"视频|00:43-00:51","orig":"（知识）功与能量转化的关系是核心，动能定理是高中阶段最重要的功能关系之一，包括基本内容与实际应用方法","link":""},{"id":"phy0829","t":"动能定理·难度分层与学习路径","s":"看到【动能定理与图像或机车启动类变力模型结合的综合题】","c":"想到【属最高难度层级，需先掌握基本列式步骤再学图像法与机车启动模型】；警惕【基础题考审题与操作熟练度，综合题考模型迁移能力】","src":"物一轮129.【课前必看】本讲听课建议_笔记","note":"视频|00:51-02:28","orig":"（知识）动能定理按难度分层：基础（理解表达式与应用步骤）→常规应用（变力功、曲线运动、多过程）→综合应用（与图像综合、变力模型如机车启动）","link":""},{"id":"phy0830","t":"动能定理·前置知识","s":"看到【动能定理相关题目前需要推导其表达式】","c":"想到【动能定理可由牛顿第二定律结合运动学公式推导，掌握推导有助理解适用范围】；警惕【零基础应先补齐动能表达式与推导，再进入应用】","src":"物一轮129.【课前必看】本讲听课建议_笔记","note":"视频|03:44","orig":"（知识）必修前置内容：动能的表达式、动能定理的推导过程","link":""},{"id":"phy0831","t":"动能定理基础·动能的定义与标量性","s":"看到【判断动能大小或问匀速圆周运动中动能是否变化】","c":"想到【Ek=½mv^{2} 是标量，只由速率大小决定】；警惕【匀速圆周运动速度（矢量）方向改变但动能（标量）不变，勿混淆速度与速率】","src":"物一轮130.理解动能定理_笔记","note":"视频|00:26-03:01","orig":"（知识）动能是物体由于运动而具有的能量，Ek=½mv²；相同速度下质量越大动能越大，速度以平方关系影响动能；动能是标量，遵循代数运算法则","link":""},{"id":"phy0832","t":"动能定理基础·表达式","s":"看到【列动能定理方程时确定 W 的含义】","c":"想到【W 是合外力功＝各个力做功的代数和，直接相加即可】；警惕【区分合力功与单个力做功，勿漏掉某个力的功】","src":"物一轮130.理解动能定理_笔记","note":"视频|03:08-05:22","orig":"（知识）动能定理基本形式 W=Ek2−Ek1：W 为全过程合力功（所有力做功的代数和），Ek1、Ek2 分别为过程初、末动能","link":""},{"id":"phy0833","t":"动能定理基础·物理意义","s":"看到【用功的代数和表示总功】","c":"想到【动能定理体现功能关系：合力做的功量度动能的变化】；警惕【过程完整性：选定过程内所有受力（含新增力、变力）的功都要计入】","src":"物一轮130.理解动能定理_笔记","note":"视频|05:22-05:44","orig":"（知识）合力功等于动能变化量，是功能关系的体现；功具有标量性，不同力做功可直接代数相加；列式必须包含选定过程的全部受力做功","link":""},{"id":"phy0834","t":"动能定理基础·适用范围","s":"看到【曲线运动或变力作用下的功能问题】","c":"想到【动能定理不限轨迹、不限恒力变力，只要功可计算即可列式】；警惕【对系统（非质点）或内力做功复杂的情况要慎用】","src":"物一轮130.理解动能定理_笔记","note":"视频|05:44-07:40","orig":"（知识）研究对象为单一质点或可视为质点的物体（如速度相同的连接体）；直线、曲线运动均适用；受力恒力或变力均可，需满足功可计算","link":""},{"id":"phy0835","t":"动能定理基础·解题步骤","s":"看到【用动能定理求解一道完整的计算题】","c":"想到【按定对象定过程$\\to$算各力功$\\to$列 W=$\\Delta$Ek 三步走】；警惕【变力做功不能直接用 W=Fscos$\\theta$，需结合图像法、微元法等间接求解】","src":"物一轮130.理解动能定理_笔记","note":"视频|05:44-07:40","orig":"（知识）动能定理解题步骤：①确定研究对象和过程；②计算合力功 W；③列式 W=Ek2−Ek1 求解","link":""},{"id":"phy0836","t":"动能定理基础·足球例题","s":"看到【踢球瞬间位移未知，只有初末速度】","c":"想到【通过初末状态列动能定理间接求功，绕开未知位移】；警惕【易忽略摩擦力等其他力做功；注意功的正负号判定，勿把滚动位移当作踢球过程的位移】","src":"物一轮130.理解动能定理_笔记","note":"视频|07:40","orig":"（例）足球 m=0.4kg，被踢出后初速 v=10m/s，作用力 F=100N，滚动位移 l=50m 后停止；确定研究过程（踢出到停止），分析受力（踢力、摩擦力等），初动能 ½mv²、末动能 0，列动能定理求解","link":""},{"id":"phy0837","t":"动能定理·基本解题步骤","s":"看到【拿到一道动能定理解答题需要规范流程】","c":"想到【定对象定过程$\\to$受力分析$\\to$定初末动能$\\to$算各力功$\\to$列 W=$\\Delta$Ek】；警惕【过程选择错误（如混淆踢球瞬间与滚动过程）；忽略变力做功或方向变化的力】","src":"物一轮131.应用动能定理的基本步骤_笔记","note":"视频|00:02-10:49","orig":"（知识）五步流程：①确定研究对象与研究过程；②受力分析（含变力与新增力）；③确定初末状态动能；④计算各力做功（重力做功与路径无关）；⑤列动能定理方程求解","link":""},{"id":"phy0838","t":"动能定理·适用场景判断","s":"看到【题目涉及曲线运动、多过程且不涉及时间和加速度】","c":"想到【优先选用动能定理，选包含已知状态量和待求量的完整过程列式】；警惕【题目若求时间或加速度，动能定理无法直接给出，需结合运动学或牛顿定律】","src":"物一轮131.应用动能定理的基本步骤_笔记","note":"视频|00:02-10:49","orig":"（知识）动能定理适于求力、位移、速度、质量，不适用加速度、时间问题；与牛顿定律对比：优势是适用变力与曲线运动，局限是无法直接求加速度与时间","link":""},{"id":"phy0839","t":"圆弧轨道·动能定理求速度","s":"看到【物体沿光滑圆弧面下滑求某点速度】","c":"想到【光滑面上仅重力做功，支持力始终与速度垂直不做功，mgR=½mv^{2}】；警惕【圆弧面上支持力方向不断变化，虽是变力但功为零，勿误算其功】","src":"物一轮131.应用动能定理的基本步骤_笔记","note":"视频|10:49-24:25","orig":"（例）小球静止从光滑圆弧 A 释放到 B：W_G=mgR=0.2×10×0.8=1.6J，支持力始终垂直速度不做功，W_G+W_N=EkB−0，解得 v_B=4m/s","link":""},{"id":"phy0840","t":"竖直往返·分段列动能定理","s":"看到【物体往返运动且阻力大小恒定、方向始终与运动方向相反】","c":"想到【分下降、上升两段分别列动能定理，两段中重力与阻力同向或反向导致合功不同】；警惕【阻力方向始终与速度相反，往返两段符号相反；碰撞按比例损失动能后要重新定初动能】","src":"物一轮131.应用动能定理的基本步骤_笔记","note":"视频|24:25-36:03","orig":"（例）排球 m=280g 下落 h=1.2m，空气阻力恒定 f=1.2N：下降 (mg−f)h=Ek2−14，得 Ek2=15.92J；碰撞后动能保留 40%；上升 (mg+f)h′=Ek2′=6.368，得 h′=1.592m","link":""},{"id":"phy0841","t":"动能定理·变力做功求解","s":"看到【求某个大小或方向变化的力做的功】","c":"想到【先确定初末动能，再区分恒力功与变力功，用动能定理解出未知变力功】；警惕【区分恒力与变力分别计算，变力功不能套用 W=Fscos$\\theta$】","src":"物一轮131.应用动能定理的基本步骤_笔记","note":"视频|36:03","orig":"（知识）当力的大小或方向随位移变化，W=Fscosθ 难以直接应用时，通过动能变化量 ΔEk 反推合外力做功：W恒+W变=½mv₂²−½mv₁²，避免复杂积分","link":""},{"id":"phy0842","t":"动能定理·多过程问题","s":"看到【多过程组合问题（如斜面+平抛、含摩擦往返）】","c":"想到【不涉时间加速度时优先对全过程列动能定理；过程衔接处速度连续，是分段与整体的连接条件】；警惕【重力做功与路径无关；相邻过程碰撞类环节动能会按比例损失，不能直接延续动能】","src":"物一轮131.应用动能定理的基本步骤_笔记","note":"视频|36:03","orig":"（知识）分段策略：将复杂运动划分为若干典型过程（加速、减速、圆周等）；整体法可直接建立初末状态能量关系；注意相邻过程速度的连续性（如碰撞前后动能损失）；典型组合：斜面+平抛、弹簧振子多阶段、含摩擦往返运动","link":""},{"id":"phy0843","t":"变力做功·四大方法总览","s":"看到【求变力做功，需选择求解方法】","c":"想到【按条件选法：有 F-x 图用面积、力方向变大小不变用微元法、功率恒定用 W=Pt、其余用动能定理反推】；警惕【微元法的适用条件是方向变但大小不变，勿滥用】","src":"物一轮132.用动能定理求解变力做功_笔记","note":"视频|00:53-02:56","orig":"（知识）求变力功的常规方法：①图像法——利用 F-x 图像求面积；②微元累积法——适用于力方向变化但大小不变的情况（如摩擦力）；③功率法——W=Pt 适用于功率恒定的情况；④功能关系法——用动能定理 W=Ek2−Ek1 求解","link":""},{"id":"phy0844","t":"变力做功·功能关系法原理","s":"看到【除一个变力外其余各力做功与动能变化均可求】","c":"想到【把未知变力功设为 W 代入动能定理总功表达式，代数解出】；警惕【列式时所有功都先写正号形式，结果符号自然体现，不预先加负号】","src":"物一轮132.用动能定理求解变力做功_笔记","note":"视频|00:53-02:56","orig":"（知识）功能关系法展开式 W1+W2+…+Wn=Ek2−Ek1：当其他力做功和动能变化已知时，可解出未知变力功；适用于恒力或变力，不区分力的性质","link":""},{"id":"phy0845","t":"圆弧下滑·求摩擦力变力功","s":"看到【粗糙圆弧面下滑，求摩擦力做的功】","c":"想到【重力功 mgh 与动能变化已知，摩擦力功由动能定理反推，结果必为负】；警惕【勿将摩擦力负功提前写负号导致物理意义错误；支持力始终垂直位移方向不做功】","src":"物一轮132.用动能定理求解变力做功_笔记","note":"视频|02:56-07:38","orig":"（例）物块从粗糙圆弧下滑，摩擦力为变力：正确列式 mgh+Wf=½mv²−0，解得 Wf=½mv²−mgh（必为负值）","link":""},{"id":"phy0846","t":"竖直运动·求空气阻力做功","s":"看到【题目问「克服某力做功」是多少】","c":"想到【「克服做功」取正值：把该力功记为 −Wf 列式，解出的 Wf 即克服功】；警惕【「阻力做功」（负值）与「克服阻力做功」（正值）互为相反数，列式前先看清问法】","src":"物一轮132.用动能定理求解变力做功_笔记","note":"视频|07:38-10:22","orig":"（例）物体克服空气阻力做功：列式改为 Wg−Wf=Ek2−Ek1，直接解得 Wf 即为克服阻力的功（正值）；其中重力功 Wg=−mg(h2−h1)，最终 Wf=½mv₁²−½mv₂²−mg(h2−h1)","link":""},{"id":"phy0847","t":"弹簧压缩·全程列式求克服弹力功","s":"看到【物体先在平面上滑行再压缩弹簧至最短，求克服弹力做的功】","c":"想到【选「初态到最短压缩」全过程列动能定理，摩擦力功覆盖全程位移 (s+x)】；警惕【漏算接触弹簧前移动的距离 s；选不完整过程会导致缺条件；正确理解「克服做功」的列式要求】","src":"物一轮132.用动能定理求解变力做功_笔记","note":"视频|10:22","orig":"（例）物块以 v₀ 冲上粗糙面接触弹簧：从初态到最短压缩全过程列式，摩擦力功 Wf=−μmg(s+x)（含接触前位移 s 与压缩距离 x），由 ½mv₀²−Wf=0 解得克服弹力功为 ½mv₀²−μmg(s+x)","link":""},{"id":"phy0848","t":"曲线运动·动能定理适用不同轨迹","s":"看到【同一高度不同路径（直线斜面、曲面、自由落体）下落比较末动能】","c":"想到【重力做功只与高度差有关（mgh），与路径无关，初动能为零则末动能相同】；警惕【动能定理不区分运动轨迹类型，只关注功与动能变化的关系】","src":"物一轮133.用动能定理分析曲线运动_笔记","note":"视频|00:08-00:54","orig":"（知识）只要过程条件充足（合外力做功和初末状态已知），无论轨迹是直线还是曲线（斜面滚动、自由落体、平抛等）均可应用动能定理；实例：相同质量小球从同一高度静止释放，沿不同路径下落，不计阻力时重力做功均为 mgh，末动能相同","link":""},{"id":"phy0849","t":"曲线运动·标量式不能分方向列式","s":"看到【想对平抛或类平抛的某个分运动方向列动能定理】","c":"想到【动能定理只对合运动整体列式，不能按 x、y 方向分解】；警惕【虽然某些正交分解情形下数值上可能凑对，但考试中分方向列式物理意义错误，会失分】","src":"物一轮133.用动能定理分析曲线运动_笔记","note":"视频|00:54-02:48","orig":"（知识）动能定理 W合=ΔEk 为标量式，不能针对分运动方向列式，如平抛运动中单独对 y 方向列 mgh=½mv²_y 是错误的","link":""},{"id":"phy0850","t":"曲线运动·动能变化量与末动能辨析","s":"看到【比较不同路径下落物体的末动能或动能变化量】","c":"想到【动能变化量由合力功决定（同高度即相同），末动能还要加上各自初动能；比较时间须用运动学而非动能定理】；警惕【动能变化量相同$\\neq$末动能相同；斜面下滑因加速度小耗时最长】","src":"物一轮133.用动能定理分析曲线运动_笔记","note":"视频|02:48-06:29","orig":"（例）质量相同的物块 a（斜面下滑）、b（自由落体）、c（平抛）从同一高度释放：落地时间 a 最长（加速度 gsinθ），b、c 竖直方向时间相同（2h/g）；动能变化量三者均为 mgh 相同；末动能 c 有初动能故 Ek_c>Ek_a=Ek_b","link":""},{"id":"phy0851","t":"曲线运动·最大高度与最高点速度","s":"看到【同一初速度沿不同光滑路径上升，比较最大高度】","c":"想到【光滑路径下仅重力做功，最高点速度为零时最大高度仅由初速度决定 h=v_{0}^{2}/(2g)；最高点速度非零则该部分动能未转化为势能，高度降低】；警惕【斜抛最高点有水平分速度、圆弧最高点需维持向心力，二者最高点速度均不为零】","src":"物一轮133.用动能定理分析曲线运动_笔记","note":"视频|06:29","orig":"（例）物体以 v₀ 沿光滑斜面上滑至高度 h 时速度为零（−mgh=0−½mv₀²）；对比：竖直上抛、光滑曲线路径最高点速度为零，最大高度仍为 h；但斜抛（截去顶端）最高点速度不为零，高度 h″<h；圆弧路径最高点需 v≥√(gr)，高度也小于 h","link":""},{"id":"phy0852","t":"曲线运动·动能定理与时间的界限","s":"看到【题目要求比较运动时间或求时间】","c":"想到【能量关系用动能定理，时间关系必须回到运动学公式或牛顿定律】；警惕【误用动能定理直接比较或求解时间】","src":"物一轮133.用动能定理分析曲线运动_笔记","note":"视频|02:48-06:29","orig":"（知识）动能定理无法直接求解运动时间，比较时间需结合运动学公式（如自由落体时间公式）；动能定理仅分析能量关系","link":""},{"id":"phy0853","t":"多过程问题·方法选择","s":"看到【圆周+直线+平抛等多段组合且不涉及时间和加速度】","c":"想到【优先对全过程列动能定理，只关心初末状态与各段做功，可省去大量联立计算】；警惕【动能定理无法直接求时间与瞬时加速度，题目若要求这些量需改用牛顿定律+运动学】","src":"物一轮134.用动能定理分析多过程问题_笔记","note":"视频|00:13-01:36","orig":"（知识）典型组合：竖直圆周运动+匀变速直线运动+平抛运动。传统分段法需逐段用 F=ma 与运动学联立，变速圆周段难以求解；动能定理解法无需分段，直接对全过程列 ΔEk=W总","link":""},{"id":"phy0854","t":"多过程问题·基本流程与过程选择","s":"看到【需要列动能定理求解多过程问题的末速度或某段长度】","c":"想到【按流程先定初末状态，再分阶段列各力做功（重力 mg$\\Delta$h、摩擦 −$\\mu$mgL 等），最后解方程】；警惕【摩擦力做功只发生在有摩擦的区段，勿把摩擦功算到全程；功的正负要判断】","src":"物一轮134.用动能定理分析多过程问题_笔记","note":"视频|01:36-17:36","orig":"（知识）流程：①确定已知和待求速度；②选定合适过程列动能定理；③分阶段受力分析确定各力做功；④列方程求解。原则：选择包含待求量且已知条件最多的过程","link":""},{"id":"phy0855","t":"圆周运动·管道模型弹力分析","s":"看到【管道（或双轨）约束下的圆周运动求弹力】","c":"想到【管道弹力需同时考虑水平分量（提供向心力）和竖直分量（平衡重力），再勾股合成】；警惕【只算向心力分量而漏掉竖直平衡分量导致错误】","src":"物一轮134.用动能定理分析多过程问题_笔记","note":"视频|01:36-17:36","orig":"（例）小球在竖直管道内做匀速圆周运动：水平向心力 fx=mv²_B/r=1200N，竖直平衡力 fy=mg=600N，合力 F=√(1200²+600²)=600√5 N","link":""},{"id":"phy0856","t":"圆周运动·保留整体量与临界条件","s":"看到【求最高点压力/支持力，或问「刚好通过最高点」的最小释放高度】","c":"想到【保留 mv^{2} 整体量代换简化计算；「刚好通过」对应最高点重力全部充当向心力 mg=mv^{2}/R，再由动能定理反推初始条件】；警惕【临界条件的物理意义：最高点速度不可低于 √(gR)；过程选择要包含待求量且条件最完整】","src":"物一轮134.用动能定理分析多过程问题_笔记","note":"视频|17:36-28:10","orig":"（例）小物块滑至半圆轨道：PC 段 ½mv²_C=mgR/2，向心力方程 F_N−mg=mv²_C/R=mg 得 F_N=2mg；PQ 全过程 mgR/2−μmg·2R=0 得 μ=0.25；「刚好通过最高点 A」临界 mg=mv²_A/R，DA 段 mg(H−2R)−0.25mg·2R=½mv²_A 得 H=3R","link":""},{"id":"phy0857","t":"综合应用·图像与动能定理结合","s":"看到【题目给出 F-x、v-t 等图像并要求结合动能定理求解】","c":"想到【先从图像提取功（面积）或位移、速度信息，再代入动能定理】；警惕【勿忽略图像横纵坐标的物理意义与单位换算】","src":"物一轮134.用动能定理分析多过程问题_笔记","note":"视频|28:10","orig":"（知识）图像综合问题关注斜率与面积等几何特征：F-x 图像面积表示功，v-t 图像斜率反映加速度；将图像信息转化为物理量关系，结合 W合=ΔEk 建立方程，注意横纵坐标的物理意义和单位","link":""},{"id":"phy0858","t":"综合应用·机车启动模型","s":"看到【机车/汽车以恒定功率启动，求位移、速度或能量】","c":"想到【恒功率段牵引力做功用 W=Pt 计算，配合阻力功列动能定理 W_F+W_f=$\\Delta$Ek】；警惕【牵引力是变力，不能用 Fs 直接算功；区分两阶段动力学特征】","src":"物一轮134.用动能定理分析多过程问题_笔记","note":"视频|28:10","orig":"（知识）机车启动中牵引力是速度的函数 F(v)，功率 P 恒定时满足 P=Fv；两阶段：恒定牵引力阶段（a 恒定、P 增大）与恒定功率阶段（F 随 v 增大而减小、a 趋于零）；用动能定理需计牵引力功 W_F 和阻力功 W_f，满足 W_F+W_f=½mv²−½mv₀²","link":""},{"id":"phy0859","t":"图像综合·F-x 图像求功","s":"看到【给出 F-x 图像求变力做功或末速度】","c":"想到【用图线下面积（必要时分割成梯形、三角形）求功，再列 W=$\\Delta$Ek】；警惕【面积在横轴下方表示做负功，需带符号代入】","src":"物一轮135.动能定理与图像综合_笔记","note":"视频|00:46-01:45","orig":"（知识）F-x 图像线下面积表示功的大小，可直接代入动能定理求解速度等物理量；物体受变力作用时通过面积计算变力做功","link":""},{"id":"phy0860","t":"图像综合·v-t 图像信息提取","s":"看到【给出 v-t 图像并结合动能定理分析】","c":"想到【纵轴读初末速度定动能变化，面积求位移算恒力功，两条路径信息配合使用】；警惕【曲线段的位移虽然可由面积求出，但变加速段不能用匀变速运动学公式】","src":"物一轮135.动能定理与图像综合_笔记","note":"视频|00:46-01:45","orig":"（知识）v-t 图像中纵坐标速度可直接作为动能定理的初末状态量，线下面积表示位移，可用于计算恒力做功","link":""},{"id":"phy0861","t":"图像综合·F-x 例题求最大速度","s":"看到【变力 F 与恒定摩擦力共同作用，求最大速度】","c":"想到【变加速问题优先用动能定理+F-x 图面积求功；合力为零（F=f）时加速度为零，速度达到最大】；警惕【最大速度出现在 a=0 处而非 F 最大处】","src":"物一轮135.动能定理与图像综合_笔记","note":"视频|01:45-12:57","orig":"（例）物块受向右变力 F 和恒定摩擦力 f=μmg=1N：F<1N 时减速、F>1N 时加速，最大速度出现在 F 再次降为 1N 处（x=10m）；用 F-x 图梯形面积求变力功 17J，摩擦功 −10J，列 17−10=0.1(v_m²−25) 得 v_m","link":""},{"id":"phy0862","t":"图像综合·Ek-x 图像斜率意义","s":"看到【给出 Ek-x（动能-位移）图像判断受力或运动性质】","c":"想到【斜率即合外力：直线=恒力，曲线切线斜率=变化的合力】；警惕【恒力作用下动能随位移线性变化，曲线选项对应变力，可据此排除选项】","src":"物一轮135.动能定理与图像综合_笔记","note":"视频|12:57-15:05","orig":"（知识）Ek-x 图像斜率表示合外力大小：直线对应恒力，曲线对应变力（切线斜率）；Δx→0 时 ΔEk/Δx=F合，可用于分析受力变化情况","link":""},{"id":"phy0863","t":"图像综合·斜抛运动 Ek-h 与功率图像","s":"看到【判断斜抛（或仅受重力）运动的 Ek-h 图或 P-t 图形状】","c":"想到【仅受恒定重力时 Ek-h 为直线；重力功率取决于竖直分速度大小 P=mg|v_y|，上升下降对称形成 V 型】；警惕【功率计算需取竖直分速度绝对值，注意运动方向改变处的函数转折】","src":"物一轮135.动能定理与图像综合_笔记","note":"视频|15:05-19:41","orig":"（例）斜抛小球仅受重力（恒力），Ek-h 应为直线（重力做负功、动能线性减小，斜率 k=mg 恒定）；重力功率 P=mg|v_y|=mg|v_y0−gt|，随时间呈 V 型图像","link":""},{"id":"phy0864","t":"机车启动·动力学基础","s":"看到【机车（汽车）在不同牵引力下判断运动状态或求瞬时加速度】","c":"想到【用 a=(F牵−f)/m 判断：牵引力与阻力比较即知加减速，相等时匀速】；警惕【P=F牵v 是瞬时功率，速度变化会影响牵引力或功率，注意同一性（同时刻的 F 与 v）】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|00:11-02:24","orig":"（知识）机车功率=发动机功率=牵引力功率；瞬时功率 P=F牵v；F牵>f 加速、F牵=f 匀速、F牵<f 减速；瞬时加速度 a=(F牵−f)/m","link":""},{"id":"phy0865","t":"机车启动·恒功率启动","s":"看到【机车以恒定功率启动，求最大速度或分析 v-t 图像】","c":"想到【最大速度出现在 F牵=f 处，vm=P/f；全程是加速度减小的变加速运动】；警惕【恒功率启动不是匀加速，v-t 图是曲线而非直线】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|02:24-07:34","orig":"（知识）保持功率 P 不变：v↑→F牵=P/v↓→F合↓→a↓，加速度减小但速度继续增大；当 F牵=f 时 a=0，速度达最大 vm=P/f，此后匀速；v-t 图为加速度逐渐减小的上升曲线，最终趋于水平","link":""},{"id":"phy0866","t":"机车启动·瞬时牵引力与加速度","s":"看到【恒功率行驶中求某一速度处的牵引力或加速度】","c":"想到【先用匀速状态求阻力 f=P/vm，再用 F=P/v 求任意速度处牵引力，代 a=(F−f)/m】；警惕【功率瞬时性：不同速度下牵引力不同，勿用最大速度处的力代替任意时刻的力】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|07:34-09:44","orig":"（例）功率恒为 P，最大速度 vm 时 F牵=f：由 P=fvm 得 f=P/vm；当速度为 (2/3)vm 时 F牵=P/((2/3)vm)=3P/(2vm)，a=(F牵−f)/m=P/(2mvm)","link":""},{"id":"phy0867","t":"机车启动·恒加速度启动（匀加速阶段）","s":"看到【机车匀加速启动，求匀加速阶段末速度或牵引力】","c":"想到【匀加速阶段 F0=ma+f 恒定，功率线性增大，临界点是功率恰好达到额定功率，v1=Pm/(ma+f)】；警惕【匀加速阶段功率并未恒定，勿把阶段中的功率当额定功率】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|10:02-11:35","orig":"（知识）保持加速度 a 不变，牵引力 F0=ma+f 恒定；功率 P=F0v 随 v 均匀增加而线性增大；当 P 达额定功率 Pm 时进入下一阶段，匀加速末速度 v1=Pm/F0；v-t 图为过原点直线段，P-t 图线性增长","link":""},{"id":"phy0868","t":"机车启动·恒加速度启动（恒功率阶段）","s":"看到【匀加速转恒功率后的后续运动分析】","c":"想到【转入恒功率后重复恒功率启动的规律，最终匀速速度 v2=Pm/f】；警惕【区分两个最终速度：匀加速末速 v1=Pm/F0 与全程最大速度 v2=Pm/f，二者不同】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|11:35-15:03","orig":"（知识）P 达 Pm 后保持不变：v↑→F牵↓→F合↓→a↓，加速度逐渐减至零；最终速度 v2=Pm/f，牵引力等于阻力 f；v-t 图曲线上升后趋于水平，F牵-t 图阶梯式下降至 f","link":""},{"id":"phy0869","t":"机车启动·v-t 图像三阶段分析","s":"看到【v-t 图像上折线+曲线+水平段的机车启动图】","c":"想到【识别三阶段：直线段匀加速（F 恒定）、曲线段恒功率、水平段匀速（F=f）；A 点是匀加速与额定功率的公共临界点，两条件联立求 f、a】；警惕【最大速度 v2=Pm/f 与匀加速末速 v1=Pm/(ma+f) 不能混用】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|15:03-21:04","orig":"（例）新能源汽车 v-t 图：OA 段匀加速（a=2m/s²）、AB 段变加速（额定功率 Pm=60kW 恒定）、BC 段匀速（v2=30m/s）；v2=Pm/f=60×10³/2000=30m/s；匀加速末速 v1=Pm/(ma+f)=60×10³/(1500×2+2000)=12m/s；A 点同时满足匀加速末态和额定功率条件","link":""},{"id":"phy0870","t":"机车启动·恒功率段用动能定理求位移","s":"看到【求恒功率变加速阶段的位移】","c":"想到【恒功率段牵引力功用 W=Pt 计算，列 P$\\Delta$t−fs=$\\Delta$Ek 解位移】；警惕【匀加速阶段中途的功率按 P^{'}=F0v 线性变化（如半速点为 P/2），不能全按额定功率算；阻力功带负号】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|21:18-27:49","orig":"（例）恒功率阶段牵引力功 P(t2−t1)，阻力功 −fs_AB，列 P(t2−t1)−fs_AB=½mv₂²−½mv₁²，得 s_AB=[P(t2−t1)−½m(v₂²−v₁²)]/f；匀加速段二分之一速度点功率 P′=F0·(v1/2)=P/2","link":""},{"id":"phy0871","t":"机车启动·F-t 图像与分段位移","s":"看到【给出 F-t 图像（先恒力后恒功率），求全程位移】","c":"想到【匀加速段用运动学求位移，变加速段必须用动能定理 P$\\Delta$t−fs=$\\Delta$Ek 求位移；额定功率 P=F0v1（匀加速末速度处）】；警惕【变加速阶段不可用匀变速公式；最大功率要用 v1=at_{1} 计算而非直接读图】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|27:49-35:22","orig":"（例）汽车 0-4s 匀加速：a=(F0−f)/m=(5×10³−2×10³)/1.2×10³=2.5m/s²，x1=½at₁²=20m；4-12s 功率恒为 P=F0v1=5×10⁴W；12s 后匀速 vmax=P/f=25m/s；变加速段由 PΔt−fx2=½mv₂²−½mv₁² 得 x2=42.5m，总位移 62.5m","link":""},{"id":"phy0872","t":"机车启动·F-1/v 图像分析","s":"看到【给出 F-1/v 图像判断功率、牵引力或启动阶段】","c":"想到【原点连线斜率=P；末端点纵坐标即阻力 f，由 P=f·vmax 求额定功率；水平线段=匀加速、下降曲线=恒功率】；警惕【混淆图线斜率与原点连线斜率的物理意义】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|35:22","orig":"（知识）F-1/v 图上点与原点连线的斜率表示瞬时功率 P=Fv（不是图线本身斜率）；从右向左分析更符合直觉（右侧 1/v 大对应速度小）；同一水平线上各点功率相同；水平线段对应恒力匀加速，下降曲线对应恒功率变加速，末端点 F=f、v=vmax 对应匀速","link":""},{"id":"phy0873","t":"机车启动·F-1/v 与 a-1/v 例题","s":"看到【F-1/v 或 a-1/v 图像与机车启动综合的选择题】","c":"想到【抓住三阶段联立：匀加速 F0−f=ma、额定功率点 P=F0v1、最大速度点 P=fv2，逐项验证】；警惕【误将非临界点速度（如图上 15m/s）当作匀加速末速度，或把该处功率当作额定功率】","src":"物一轮136.动能定理与变力模型综合 (机车启动)_笔记","note":"视频|35:22","orig":"（例）F-1/v 图：末端牵引力 2×10³N 等于阻力（A 对）；额定功率 P=fvmax=2×10³×30=6×10⁴W；a=(F−f)/m=(6×10³−2×10³)/2×10³=2m/s²；匀加速时间 t=v1/a=10/2=5s（15m/s 非匀加速末速度）。变式 a-1/v 图：a=(F−f)/m 本质仍是力与速度关系，三阶段方程联立（F0−f=ma、P=F0v1、P=fv2）","link":""},{"id":"phy0874","t":"机械能守恒定律·考情","s":"看到【机械能守恒定律的复习规划与考情定位】","c":"想到【守恒条件判断与功能关系应用是核心，动量+能量综合题为一轮重点难点】；警惕【功能关系基础题属于必拿分数，勿因看似简单而失分】","src":"物一轮137.【课前必看】本讲听课建议_笔记","note":"视频|03:00","orig":"（知识）机械能守恒定律近100%必考，选择题（如2024重庆/北京/甲卷/江苏）与解答题（2024福建/重庆/海南等7省）均出现；单独考查难度中等，与动量综合时难度显著提升。","link":""},{"id":"phy0875","t":"功能关系·考情","s":"看到【功能关系类选择题】","c":"想到【用三大功能关系（合力功$\\to$动能、保守力功$\\to$势能、其他力功$\\to$机械能）逐项分析】；警惕【需在一轮复习掌握核心概念，确保基础分全拿】","src":"物一轮137.【课前必看】本讲听课建议_笔记","note":"视频|03:00","orig":"（知识）功能关系为中频考点，主要出现在选择题（2024山东/浙江），解答题中较少独立出现。","link":""},{"id":"phy0876","t":"机械能·知识框架","s":"看到【机械能一章的知识体系梳理】","c":"想到【按「功$\\to$动能定理$\\to$守恒判断$\\to$功能关系$\\to$动量综合」主线串联复习】；警惕【守恒条件判断（系统边界）与势能零点选取是易混淆点】","src":"物一轮137.【课前必看】本讲听课建议_笔记","note":"","orig":"（知识）本讲链条：功的计算→动能定理→机械能守恒条件判断（系统内力/外力做功分析）→势能零点选取与能量转化→动量与机械能综合。","link":""},{"id":"phy0877","t":"重力做功·路径无关性","s":"看到【求重力做功、物体沿不同路径运动】","c":"想到【重力做功只与初末位置高度差有关：WG=mgh，与路径无关】；警惕【正负由升降方向决定：下降做正功、上升做负功，勿用路径长度计算】","src":"物一轮138.重力做功与重力势能变化的关系_笔记","note":"视频|00:58-02:54","orig":"（例）质量为m的小球从不同斜面下滑相同高度差h，重力做功均为WG=mgh。","link":""},{"id":"phy0878","t":"重力势能·定义","s":"看到【求某位置的重力势能或判断势能正负】","c":"想到【Ep=mgh，h相对零势能面：在参考面上方为正、下方为负】；警惕【势能是标量，负值只表示比零势能少，不同于矢量方向的意义】","src":"物一轮138.重力做功与重力势能变化的关系_笔记","note":"视频|04:35-08:32","orig":"（知识）Ep=mgh，其中h为物体与零势能面的高度差（不同于做功的高度差），零势能面通常选地面但可任意选取。","link":""},{"id":"phy0879","t":"重力势能·相对性","s":"看到【更换参考面后势能值不同】","c":"想到【势能值随参考面变化，但只有势能变化量$\\Delta$Ep具有物理意义，与参考面无关】；警惕【重力做功与$\\Delta$Ep均与参考面无关，勿把势能值当成绝对量】","src":"物一轮138.重力做功与重力势能变化的关系_笔记","note":"视频|08:32-09:40","orig":"（例）同一位置：以地面为参考面Ep=mgh2，以初始高度为参考面Ep=-mg(h1-h2)。","link":""},{"id":"phy0880","t":"功能关系·重力做功与势能","s":"看到【判断重力做功与重力势能变化的对应方向】","c":"想到【WG=Ep1-Ep2：重力做正功势能减小、做负功势能增大】；警惕【与动能定理「正功增动能」符号相反；动能定理中是合外力功，此处特指重力这一保守力的功】","src":"物一轮138.重力做功与重力势能变化的关系_笔记","note":"视频|09:42-12:42","orig":"（知识）核心公式WG=Ep1-Ep2，记忆口诀「正功减势能，负功增势能」。","link":""},{"id":"phy0881","t":"重力势能·应用","s":"看到【求物体在参考面上方或下方处的势能】","c":"想到【先明确参考平面，再按位置在参考面上/下方确定正负后代入Ep=mgh】；警惕【忽略物体在参考面上方还是下方，导致符号出错】","src":"物一轮138.重力做功与重力势能变化的关系_笔记","note":"视频|12:42-15:53","orig":"（例）以桌面为参考平面，物体B在参考面下方，EpB=-mgh2，答案B。","link":""},{"id":"phy0882","t":"重力势能·参考面影响","s":"看到【多参考面下计算重力做功与势能变化】","c":"想到【换参考面只改变势能值，重力做功WG与变化量$\\Delta$Ep不变】；警惕【$\\Delta$Ep=Ep末-Ep初，顺序勿颠倒；WG恒定仅取决于高度差$\\Delta$h】","src":"物一轮138.重力做功与重力势能变化的关系_笔记","note":"视频|15:53","orig":"（例）同一过程分别以天花板/地板/楼外地面为参考面，势能值为-10J、5J、35J，而WG=5J、ΔEp=-5J均不变。","link":""},{"id":"phy0883","t":"弹力做功·图像法","s":"看到【求弹簧变力做功】","c":"想到【变力做功用F-x图像线下面积求解，梯形面积=(kx1+kx2)(x2-x1)/2】；警惕【弹力方向与位移相反时功需加负号，勿直接用面积当正功】","src":"物一轮139.弹力做功与弹性势能变化的关系_笔记","note":"视频|00:13-04:19","orig":"（例）弹力F=kx为变力，形变量由x1到x2，用F-x图像线下梯形面积求功：W=-(1/2)(kx1+kx2)(x2-x1)，化简得W=(1/2)kx1²-(1/2)kx2²。","link":""},{"id":"phy0884","t":"弹性势能·表达式","s":"看到【直接用Ep=½kx^{2}解题或比较储存的弹性势能】","c":"想到【弹性势能Ep=½k$x^2$：形变量越大储存越多，伸长x与压缩x储存相等（含$x^2$）】；警惕【选择题可直接用，计算题需题干明确给出表达式方可使用】","src":"物一轮139.弹力做功与弹性势能变化的关系_笔记","note":"视频|04:19-05:46","orig":"（知识）Ep=(1/2)kx²，x为形变量（伸长或压缩量）；课本未直接给出该公式。","link":""},{"id":"phy0885","t":"功能关系·弹力做功与势能","s":"看到【判断弹力做功与弹性势能变化的对应方向】","c":"想到【弹力做功W=Ep1-Ep2，统一形式「正功势能减、负功势能增」】；警惕【勿把弹力做功的正负与势能增减方向弄反】","src":"物一轮139.弹力做功与弹性势能变化的关系_笔记","note":"视频|05:46-06:54","orig":"（知识）W=Ep1-Ep2：弹力做正功→弹性势能减小，弹力做负功→弹性势能增大，与重力做功关系形式相同。","link":""},{"id":"phy0886","t":"微小形变模型·绳杆做功","s":"看到【分析轻绳或轻杆两端做功、选择系统是否包含绳杆】","c":"想到【轻绳/杆$\\Delta$Ep=0故两端做功之和为零，系统含不含绳不影响机械能守恒判断】；警惕【真实弹簧两端做功之和不一定为零，因其存在弹性势能变化】","src":"物一轮139.弹力做功与弹性势能变化的关系_笔记","note":"视频|06:54-08:40","orig":"（知识）轻绳、杆、平面等形变趋于零，不储存弹性势能，绳/杆两端做功代数和必为零（ΔEp=0故W总=0）。","link":""},{"id":"phy0887","t":"弹力做功·应用","s":"看到【由F-x图像求k并计算拉力做功与弹性势能增量】","c":"想到【先由图像斜率求k，再用面积或½k$x^2$求功；物体静止位移为零则弹力做功为零】；警惕【图像斜率的单位换算（如横轴$\\times$10^{-2}m）；混淆作用点位移与物体位移】","src":"物一轮139.弹力做功与弹性势能变化的关系_笔记","note":"视频|08:40-13:58","orig":"（例）F-x图斜率k=5N/0.1m=50N/m；拉力功W=½kx²=0.04J；物块静止位移为零→弹力做功为零；弹力对右侧做负功-0.04J→ΔEp=0.04J。","link":""},{"id":"phy0888","t":"保守力·通用关系","s":"看到【识别保守力并求对应势能变化】","c":"想到【保守力做正功势能减小、做负功势能增大，统一用W=Ep1-Ep2（初减末）】；警惕【摩擦力等非保守力不满足该式，其做功与路径有关】","src":"物一轮139.弹力做功与弹性势能变化的关系_笔记","note":"视频|13:58","orig":"（知识）W=Ep1-Ep2适用于重力、弹力、万有引力、分子力、静电力等保守力，共同特点：做功与路径无关。","link":""},{"id":"phy0889","t":"机械能·定义","s":"看到【求系统机械能或判断机械能包含哪些能量】","c":"想到【先定研究对象与系统边界，再决定是否计入弹性势能】；警惕【同一过程选取不同系统（单独物体 vs 物体+弹簧）机械能计算结果不同】","src":"物一轮140.对机械能守恒定律的理解_笔记","note":"视频|00:34-01:40","orig":"（知识）机械能E=Ek+Ep+E弹，讨论时必须先明确研究对象：单个物体可能不含弹性势能，含弹簧的系统需计入弹性势能。","link":""},{"id":"phy0890","t":"机械能守恒·含义","s":"看到【判断「机械能守恒」的确切含义】","c":"想到【守恒=三种能量总和全程不变，内部转化不改变总和】；警惕【中间过程有波动即不守恒；内能、电势能等非机械能参与转化直接破坏守恒】","src":"物一轮140.对机械能守恒定律的理解_笔记","note":"视频|01:40-05:01","orig":"（知识）守恒指系统内动能、重力势能、弹性势能总和全过程恒定，不是仅初末相等；内部相互转化（如重力势能减少10J转化为动能增加10J）不影响总和。","link":""},{"id":"phy0891","t":"机械能守恒·条件","s":"看到【判断机械能是否守恒、找「其他力」做功】","c":"想到【逐个分析做功的力，确认只有系统内重力、弹力做功才守恒】；警惕【摩擦力、系统外弹力（如单独研究小球时弹簧的弹力）、电场力/安培力做功均破坏守恒】","src":"物一轮140.对机械能守恒定律的理解_笔记","note":"视频|05:41-10:25","orig":"（知识）守恒前提：只有系统内重力和弹力做功（其他力做功和为零）；典型非守恒力：摩擦力、系统外弹力、电场力/安培力。","link":""},{"id":"phy0892","t":"机械能守恒·功能本质","s":"看到【理解守恒条件背后的功能关系】","c":"想到【仅重力/弹力做功时能量只在机械能内部转化，故总和不变】；警惕【有力但无位移（做功为零）时不影响守恒】","src":"物一轮140.对机械能守恒定律的理解_笔记","note":"视频|10:25-13:11","orig":"（知识）功是能量转化的量度：系统内重力做功实现动能与重力势能转化，系统内弹力做功实现动能与弹性势能转化，能量转化封闭在机械能内部故守恒。","link":""},{"id":"phy0893","t":"机械能守恒·应用","s":"看到【自由落体或仅重力做功过程求某位置的机械能】","c":"想到【先定零势能面，用动能定理求动能，机械能=动能+势能】；警惕【零势能面下方的位置势能为负值】","src":"物一轮140.对机械能守恒定律的理解_笔记","note":"视频|13:11-15:27","orig":"（例）指定释放点势能为零：mg(H+h)=½mv²，落地时势能-mg(H+h)，机械能(0+0)=落地时(mg(H+h)-mg(H+h))=0，验证守恒。","link":""},{"id":"phy0894","t":"机械能守恒·系统选取","s":"看到【蹦极、弹性绳类问题判断机械能守恒】","c":"想到【先明确系统范围再判断守恒：弹性体在系统内则弹力为系统内力】；警惕【同一问题因系统边界不同可能得出相反守恒结论】","src":"物一轮140.对机械能守恒定律的理解_笔记","note":"视频|15:27","orig":"（例）蹦极模型：单独研究蹦极者，弹性绳弹力属系统外力做负功→机械能不守恒；研究「蹦极者+弹性绳」系统，弹力为内力→机械能守恒。","link":""},{"id":"phy0895","t":"机械能守恒·定义法","s":"看到【单物体的机械能是否守恒判断】","c":"想到【定义法：直接看Ek+Ep+E弹总和是否不变，适合单物体且能量变化方向明确的情形】；警惕【各项一增一减时无法直接判断总和，需改用功能关系法】","src":"物一轮141.对机械能是否守恒的判断_笔记","note":"视频|00:09-01:46","orig":"（例）小球匀速下降：动能不变、重力势能减小→机械能减小；小球加速下降且考虑空气阻力：动能增加、势能减小→无法直接判断总和。","link":""},{"id":"phy0896","t":"机械能守恒·功能关系法","s":"看到【多物体系统的机械能守恒判断】","c":"想到【功能关系法三步：确认系统边界$\\to$分析所有做功的力$\\to$排除系统外力和非保守力】；警惕【多物体系统首选功能关系法，勿逐个能量相加硬算】","src":"物一轮141.对机械能是否守恒的判断_笔记","note":"视频|01:46-02:26","orig":"（例）考虑空气阻力的小球下落：存在外力做功→不守恒；光滑弧形槽上小球-滑块系统仅重力做功→守恒。","link":""},{"id":"phy0897","t":"机械能守恒·圆周运动","s":"看到【匀速圆周运动问机械能是否守恒】","c":"想到【按运动平面分别判断：水平面匀速圆周守恒，竖直面不守恒】；警惕【不能一概说「匀速圆周守恒」，关键看高度是否变化】","src":"物一轮141.对机械能是否守恒的判断_笔记","note":"视频|02:26-07:02","orig":"（例）水平面匀速圆周：动能不变、重力势能不变→守恒；竖直面匀速圆周：动能不变、重力势能变化→不守恒，结论为「不确定」。","link":""},{"id":"phy0898","t":"机械能守恒·定义法应用","s":"看到【物体匀速率沿螺旋/斜面下滑】","c":"想到【匀速率但高度下降时机械能必减小】；警惕【匀速$\\neq$机械能守恒，匀速下降必有其他力做负功】","src":"物一轮141.对机械能是否守恒的判断_笔记","note":"视频|02:26-07:02","orig":"（例）传菜车沿螺旋轨道匀速率下行：动能不变、重力势能减小→总和减小，不守恒。","link":""},{"id":"phy0899","t":"机械能守恒·图像分析","s":"看到【由v-t图像或运动阶段分析机械能变化】","c":"想到【看加速度是否等于g：a=g仅重力做功守恒，a$\\neq$g存在其他力做功】；警惕【不能仅凭动能变化判断机械能；条件不足时结论是「不确定」，不能臆断「先增后减」】","src":"物一轮141.对机械能是否守恒的判断_笔记","note":"视频|07:02","orig":"（例）无人机t1-t2加速上升：动能增、势能增→机械能增大；t3-t4减速上升：动能减、势能增→总和变化不确定；若加速度等于g则仅重力做功守恒。","link":""},{"id":"phy0900","t":"机械能守恒·系统选取","s":"看到【绳连接的两物体系统用机械能守恒求解】","c":"想到【绳两端做功代数和为零，系统含不含绳不影响守恒；列式需结合关联速度vA=vB】；警惕【先判断守恒条件再列式，勿漏关联速度条件】","src":"物一轮142.用机械能守恒解决实际问题_笔记","note":"视频|02:29-10:23","orig":"（例）A、B由轻绳连接，选A、B组成的系统（包含或不包含轻绳不影响结果），绳两端做功之和为零，系统内只有重力做功，机械能守恒。","link":""},{"id":"phy0901","t":"机械能守恒·列式方法","s":"看到【列多物体机械能守恒方程】","c":"想到【两种列式：①初机械能=末机械能（需设零势能面）；②增加能量=减少能量（无需零势能面）】；警惕【方法②必须明确各能量的增减方向，勿漏某物体的动能或势能项】","src":"物一轮142.用机械能守恒解决实际问题_笔记","note":"视频|10:23","orig":"（例）能量增减平衡式：mBgh减少=mAgh+½mAvA²+½mBvB²增加（A下降B上升模型）。","link":""},{"id":"phy0902","t":"机械能守恒·杆连接体","s":"看到【轻杆连接两球在光滑轨道上运动】","c":"想到【杆连接体沿杆方向速度分量相等；先由几何关系定角度，再分解速度代入守恒式】；警惕【两球速度大小一般不相等，勿直接令vP=vQ】","src":"物一轮142.用机械能守恒解决实际问题_笔记","note":"视频|10:23","orig":"（例）双球杆系统：轻杆两端小球P、Q沿杆速度分量相等vPcos60°=vQcos30°；以CD面为零势能面，势能减少3mgr=动能增加½mvP²+½mvQ²。","link":""},{"id":"phy0903","t":"机械能守恒·含弹簧系统","s":"看到【圆环、弹簧等多体系统求弹性势能变化】","c":"想到【系统必须包含所有做功的保守力（重力、弹簧弹力）；弹性势能变化用守恒式反推】；警惕【不含弹簧时机械能不守恒；需先由几何关系确定各物体高度变化】","src":"物一轮142.用机械能守恒解决实际问题_笔记","note":"视频|10:23","orig":"（例）圆环-弹簧多体系统：必须取「A+B+弹簧」系统守恒，ΔE弹+ΔEk=ΔEpA+ΔEpB，由几何关系h=(3-√5)R求重力势能变化，再反推弹性势能增量。","link":""},{"id":"phy0904","t":"机械能守恒·与动能定理选择","s":"看到【纠结用动能定理还是机械能守恒】","c":"想到【单物体优先动能定理（适用范围更广），多物体系统用机械能守恒】；警惕【有摩擦生热时不能用机械能守恒，只能用动能定理或能量守恒】","src":"物一轮142.用机械能守恒解决实际问题_笔记","note":"","orig":"（知识）适用于多物体系统；单个物体机械能守恒时动能定理与守恒表达式等价，存在摩擦力时仅能用动能定理。","link":""},{"id":"phy0905","t":"功能关系·动能定理","s":"看到【求合力做功或动能变化量】","c":"想到【W合=$\\Delta$Ek，动能定理是功能关系的「一杆秤」】；警惕【按末减初顺序计算；合力做负功时$\\Delta$Ek为负】","src":"物一轮143.回顾机械运动中的功能关系_笔记","note":"视频|00:26-05:18","orig":"（知识）功是能量转化的量度：合力做功对应动能变化，W合=ΔEk，正功→动能增加，负功→动能减少。","link":""},{"id":"phy0906","t":"功能关系·保守力与势能","s":"看到【求重力或弹力做功对应的势能变化】","c":"想到【保守力做功W保=-$\\Delta$Ep，与动能定理符号相反】；警惕【负号勿丢：保守力做正功对应势能减少而非增加】","src":"物一轮143.回顾机械运动中的功能关系_笔记","note":"视频|00:26-05:18","orig":"（知识）保守力（重力/弹力）做功对应势能变化：W保=-ΔEp，正功→势能减小，负功→势能增加，与动能定理符号相反。","link":""},{"id":"phy0907","t":"功能关系·机械能定理","s":"看到【求摩擦力、外力等做功对应的机械能变化】","c":"想到【非保守力做功等于机械能变化量$\\Delta$E机=W其他】；警惕【仅当W其他=0时机械能才守恒】","src":"物一轮143.回顾机械运动中的功能关系_笔记","note":"视频|00:26-05:18","orig":"（知识）其他力（非保守力）做功对应机械能变化：W其他=ΔE机械，正功→机械能增加，负功→机械能减小。","link":""},{"id":"phy0908","t":"功能关系·摩擦生热","s":"看到【求摩擦生热或系统内能增量】","c":"想到【Q=f·$\\Delta$s相对，必须用相对路程而非位移】；警惕【相对路程$\\neq$相对位移：往返运动时需累加全部相对运动距离】","src":"物一轮143.回顾机械运动中的功能关系_笔记","note":"视频|00:26-05:18","orig":"（知识）系统摩擦力做功对应摩擦热：Q=f·Δs，Δs为相对路程；往返运动需累加全部相对运动距离。","link":""},{"id":"phy0909","t":"板块模型·摩擦生热推导","s":"看到【板块相对滑动后求系统损失的机械能】","c":"想到【对两物体分别列动能定理联立，系统机械能损失完全转化为摩擦热Q=f·$\\Delta$s】；警惕【$\\Delta$s的计算与运动方向无关；初始机械能-末态机械能=摩擦热】","src":"物一轮143.回顾机械运动中的功能关系_笔记","note":"视频|05:18","orig":"（例）光滑地面板块模型：对物块-fx1=Ek1-Ek0，对木板fx2=Ek2，联立得f(x1-x2)=Ek0-(Ek1+Ek2)，即Q=fΔs（Δs=|x1-x2|）。","link":""},{"id":"phy0910","t":"功能关系·找功","s":"看到【变力或未知力做功难以直接计算】","c":"想到【「功难求时看能量」：W合=$\\Delta$Ek，用动能变化间接求合力功】；警惕【求单个力做功不能直接套合力功，需结合其他力做功分析】","src":"物一轮144.功能关系的应用_笔记","note":"视频|00:22-00:57","orig":"（知识）转化视角法：功难以通过定义直接求解时（存在变力或未知力），通过动能变化量求解合力做功。","link":""},{"id":"phy0911","t":"功能关系·找能","s":"看到【重力势能或机械能变化量难以直接计算】","c":"想到【「能难算时找做功」：势能变化用重力功反推，机械能变化用其他力功求解】；警惕【$\\Delta$Ep=-Wg中负号勿丢】","src":"物一轮144.功能关系的应用_笔记","note":"视频|00:57-01:37","orig":"（知识）逆向转化法：能量难以直接求解时通过功来分析，ΔEp=-Wg，ΔE机=W其他。","link":""},{"id":"phy0912","t":"功能关系·返回舱应用","s":"看到【飞船返回舱减速下降分析各力做功关系】","c":"想到【减速阶段合力做功为负，比较大小需用绝对值；匀速阶段重力功与阻力功等大反向】；警惕【比较负数绝对值时不等号方向会反转（如-3>-5对应3<5）】","src":"物一轮144.功能关系的应用_笔记","note":"视频|01:37-07:47","orig":"（例）神舟18号返回：|W合|=|ΔEk|<|Wf|；匀速阶段Wg=-Wf平衡。答案BD。","link":""},{"id":"phy0913","t":"功能关系·多力做功分配","s":"看到【物体受多个力求各类能量变化】","c":"想到【逐个力分类：合力功$\\to$动能、重力功$\\to$势能、其他力功$\\to$机械能】；警惕【斜面支持力不做功但摩擦力做功，二者同属「其他力」】","src":"物一轮144.功能关系的应用_笔记","note":"视频|07:47-11:05","orig":"（例）滑块受W1~W4四个力：动能变化=W1+W2+W3+W4；重力势能变化=-W3；机械能变化=W1+W2+W4（W2为斜面作用力，含支持力与摩擦力）。","link":""},{"id":"phy0914","t":"功能关系·摩擦生热","s":"看到【板块相对滑动且位移成比例求内能】","c":"想到【Q=f·$\\Delta$s相对，位移比例关系可转化为动能增量关系】；警惕【物块克服摩擦力做功$\\neq$内能，内能必须用相对位移计算】","src":"物一轮144.功能关系的应用_笔记","note":"视频|11:05-14:51","orig":"（例）木板位移x、物块位移kx（k>1）：Wf=fx=ΔEk木板；Q=f(k-1)x=(k-1)ΔEk木板。答案BD。","link":""},{"id":"phy0915","t":"功能关系·比例问题","s":"看到【下落过程中势能与动能变化成比例求阻力】","c":"想到【由$\\Delta$Ep与$\\Delta$Ek的比例求阻力与重力之比；机械能减少量=克服阻力做的功】；警惕【题目问「减少量」取绝对值，单独问「做功」需带正负号】","src":"物一轮144.功能关系的应用_笔记","note":"视频|14:51-19:03","orig":"（例）跳伞运动员匀速/匀加速下落：由ΔEp:ΔEk=9:8推得mg:f=9:1，机械能减少量=克服阻力做功=(1/9)mgh（阻力做功实为-(1/9)mgh）。答案C。","link":""},{"id":"phy0916","t":"功能关系·总结","s":"看到【功与能分析卡壳、需要转换求解视角】","c":"想到【双向转化：功难求看能量，能难算找做功】；警惕【超重失重看加速度方向：返回舱减速下降加速度向上为超重】","src":"物一轮144.功能关系的应用_笔记","note":"视频|19:03","orig":"（知识）三大关系式：W合=ΔEk（动能定理）、Wg=-ΔEp（势能关系）、W其他=ΔE机（机械能定理），建立功与能的双向转化通道。","link":""},{"id":"phy0917","t":"动量·动力学三大视角","s":"看到【动力学问题需要选择分析视角：瞬时关系/空间积累/时间积累】","c":"想到【求瞬时加速度用牛顿定律F=ma；涉及位移用动能定理W=$\\Delta$Ek；涉及时间用动量定理I=$\\Delta$p】；警惕【混淆时间积累与空间积累对应的物理量——冲量对应动量变化，功对应动能变化】","src":"物一轮145.【课前必看】本讲听课建议_笔记","note":"视频|00:30-02:20","orig":"（知识）力—运动分析三条基本规律：牛顿定律视角F=ma为瞬时效应；功能视角W=F·s·cosθ做功实现空间积累，W=ΔEk；动量视角I=F·Δt冲量实现时间积累，I=Δp。","link":""},{"id":"phy0918","t":"动量·动量定理基础","s":"看到【力作用一段时间后求速度变化或平均作用力】","c":"想到【用动量定理F·$\\Delta$t=$\\Delta$p列式，平均力F=$\\Delta$p/$\\Delta$t】；警惕【动量是状态量、冲量是过程量，冲量与功含义不同不可混用】","src":"物一轮145.【课前必看】本讲听课建议_笔记","note":"视频|02:20-02:37","orig":"（知识）动量定义p=mv，冲量定义I=F·Δt，动量定理F·Δt=Δp；平均力求解F=Δp/Δt是高频考点。","link":""},{"id":"phy0919","t":"动量·流体冲击力（高阶）","s":"看到【连续流体冲击物体或变力场景下间接求位移】","c":"想到【流体冲击建柱状微元模型用动量定理；特殊位移需结合其他规律（如动能定理）综合求解】；警惕【质量流量$\\Delta$m/$\\Delta$t与速度变化关系的建模是难点】","src":"物一轮145.【课前必看】本讲听课建议_笔记","note":"视频|02:20-02:37","orig":"（知识）用动量定理处理连续流体（如水柱）冲击物体的平均力计算；特殊场景（变力或时间-位移隐含关系）下通过动量定理间接求位移，需结合动能定理综合。","link":""},{"id":"phy0920","t":"动量·动量概念与变化量","s":"看到【判断动量是否变化或计算动量变化量$\\Delta$p】","c":"想到【动量是矢量，大小和方向任一变化即动量变化；$\\Delta$p=p末-p初必须用矢量运算法则（三角形定则或一维正负号）】；警惕【匀速圆周运动速度大小不变但方向持续变化，动量始终在变化，$\\Delta$p$\\neq$0】","src":"物一轮146.理解动量的概念_笔记","note":"视频|00:30-04:37","orig":"（知识）p=mv，单位kg·m/s，矢量、方向与速度相同；Δp=p末-p初需用矢量运算法则，如60°转向的匀速圆周运动Δp大小等于原动量值。","link":""},{"id":"phy0921","t":"动量·动量与动能对比","s":"看到【动量与动能之间的换算或标矢性比较】","c":"想到【选择题可直接用Ek=p^{2}/2m与p=√(2mEk)换算；功能视角看空间积累改变动能，动量视角看时间积累改变动量】；警惕【动能是标量只看大小，动量是矢量须同时考虑大小和方向】","src":"物一轮146.理解动量的概念_笔记","note":"视频|04:37-07:15","orig":"（知识）动量p=mv矢量遵循平行四边形定则；动能Ek=½mv²标量遵循代数运算法则；换算关系Ek=p²/2m、p=√(2mEk)。","link":""},{"id":"phy0922","t":"动量·矢量标量判断","s":"看到【判断「动能不变则动量不变」或反之的说法】","c":"想到【速度变化（大小或方向）必导致动量变化；动量不变$\\to$速度不变$\\to$动能必不变；动能不变只保证速度大小不变，方向可能变】；警惕【混淆矢量与标量的判断标准，如匀速圆周运动动能不变而动量变】","src":"物一轮146.理解动量的概念_笔记","note":"视频|07:15-11:15","orig":"（例）动量/动能变化判断题：速度变化（大小或方向）必导致动量变化；仅方向变化时动能可能不变；动量不变则速度不变、动能必然不变；动能不变只保证速度大小不变。","link":""},{"id":"phy0923","t":"动量·抛体运动动量动能对比","s":"看到【多个抛体运动比较落地的动量与动能变化量】","c":"想到【动能变化用动能定理mgh=$\\Delta$Ek，只与高度有关；动量变化需矢量运算，末动量方向不同则$\\Delta$p不同】；警惕【动量问题先判断方向，一维情况可用正负号表示方向】","src":"物一轮146.理解动量的概念_笔记","note":"视频|11:15","orig":"（例）上抛、下抛、平抛三球（初动能相同）落地对比：末动能相同（mgh=ΔEk），但落地动量方向各异、Δp不同。答案BD。","link":""},{"id":"phy0924","t":"冲量·定义与表达式","s":"看到【计算恒力的冲量】","c":"想到【恒力冲量直接用I=Ft；变力不能直接套用，需分段计算或用F-t图像面积】；警惕【变力冲量不可直接用力乘总时间】","src":"物一轮147.理解冲量的概念_笔记","note":"视频|00:04-01:30","orig":"（知识）冲量I表示力在时间上的累积效应，I=Ft仅适用于恒力，单位N·s；如恒力3N作用2s，I=6N·s。","link":""},{"id":"phy0925","t":"冲量·矢量性","s":"看到【求某力的冲量或判断冲量方向】","c":"想到【冲量方向仅由力方向决定，与物体运动方向无关】；警惕【误将速度方向夹角纳入冲量计算】","src":"物一轮147.理解冲量的概念_笔记","note":"视频|01:30-02:00","orig":"（知识）冲量是矢量，方向与力的方向相同（如斜向力产生的冲量方向与力一致），与物体运动方向无关。","link":""},{"id":"phy0926","t":"冲量·不同运动场景恒力冲量","s":"看到【同一恒力作用在不同运动轨迹（直线/斜面/抛体）上比较冲量】","c":"想到【冲量只由F和t决定，I=Ft，与运动轨迹无关】；警惕【冲量方向与运动方向无关，不要被轨迹干扰】","src":"物一轮147.理解冲量的概念_笔记","note":"视频|02:00-04:38","orig":"（例）水平直线、斜面、平抛三种运动场景中10N力作用1s，冲量均为10N·s。","link":""},{"id":"phy0927","t":"冲量·冲量与功对比","s":"看到【比较冲量与功，或判断「有力有位移是否一定做功」】","c":"想到【有力有时间必有冲量；有力有位移不一定做功，取决于cos$\\theta$；多个冲量合成需矢量运算，多个功直接代数相加】；警惕【混淆时间积累（冲量）与空间积累（功）的积累对象】","src":"物一轮147.理解冲量的概念_笔记","note":"视频|04:38-08:26","orig":"（知识）冲量I=Ft为时间积累、矢量；功W=Flcosθ为空间积累、标量。有力作用一段时间必产生冲量；有力有位移不一定做功（力与位移垂直时W=0）。","link":""},{"id":"phy0928","t":"冲量·分段求各力冲量","s":"看到【求某过程中重力、支持力、摩擦力等多个力的冲量】","c":"想到【方向不变的恒力冲量直接F$\\times$总时间；方向改变的力（如往返中摩擦力反向）需分段求矢量和】；警惕【变方向力不可直接用F全程相乘】","src":"物一轮147.理解冲量的概念_笔记","note":"视频|08:26-16:35","orig":"（例）斜面下滑上滑过程：重力冲量mg(t1+t2)方向恒向下，支持力冲量mgcosθ(t1+t2)方向不变，摩擦力冲量Ff(t2-t1)需考虑方向变化。答案C。","link":""},{"id":"phy0929","t":"冲量·F-t图像应用","s":"看到【给出F-t图像求冲量或结合运动求位移】","c":"想到【F-t图线与t轴围成的面积表示冲量，t轴上方为正、下方为负，代数和为合冲量；位移可结合v-t图像面积求解】；警惕【面积绝对值只是冲量大小，方向需单独判断】","src":"物一轮147.理解冲量的概念_笔记","note":"视频|16:35","orig":"（例）F-t图前2s正方向冲量、后2s负方向冲量，合冲量(6×1+2×1)-(2×2)=4N·s；位移由v-t图像面积得8m，第4s末速度为0。答案B。","link":""},{"id":"phy0930","t":"动量定理·表达式与矢量性","s":"看到【用动量定理列方程求速度变化或冲量】","c":"想到【I合=$\\Delta$p是矢量式，合外力冲量与动量变化量方向相同；多力冲量先求矢量和，再与$\\Delta$p对应】；警惕【左边是过程量（时间积累），右边是状态量的变化，不要混淆】","src":"物一轮148.动量定理的理解及使用步骤_笔记","note":"视频|00:50-03:21","orig":"（知识）I合=Δp是矢量式，两端大小相等且方向相同；I合为过程量（时间积累），Δp为状态量变化；多个外力冲量求矢量和，Δp用矢量减法（从p0首端指向p首端）。","link":""},{"id":"phy0931","t":"动量定理·适用场景","s":"看到【板块模型系统或平抛运动中问能否用动量定理】","c":"想到【对系统列式时内力冲量矢量和为零，只需计外力冲量；可单独对x、y方向列式（如平抛竖直方向mgt=mvy-0）；变力只要能求冲量即可用】；警惕【系统列式只看外力，内力冲量不需计入】","src":"物一轮148.动量定理的理解及使用步骤_笔记","note":"视频|03:21-05:56","orig":"（知识）适用于多质点系统（板块模型：Ft=(mv1+Mv2)-0，内力摩擦力冲量不计）、曲线运动（平抛竖直方向mgt=mvy-0）、变力（F-t图面积可求冲量即可用）。","link":""},{"id":"phy0932","t":"动量定理·与动能定理对比","s":"看到【平抛或系统问题中选择动量定理还是动能定理】","c":"想到【动量定理可分解方向单独列式，动能定理必须对合运动整体列式；动量定理可对系统列（内力冲量抵消），动能定理对系统列需内力功相同否则出错】；警惕【动能定理对系统列式时两物体位移不等、摩擦生热会导致错误】","src":"物一轮148.动量定理的理解及使用步骤_笔记","note":"视频|05:56-14:04","orig":"（知识）I合=Δp矢量式可分解方向列式；W合=ΔEk标量式必须对合运动整体列式（平抛竖直方向列mgh=½mvy²是错误的）；系统列动能定理因x1≠x2及内力生热而出错。","link":""},{"id":"phy0933","t":"动量定理·变力求末速度步骤","s":"看到【变力（F随t线性变化）作用下求末速度】","c":"想到【步骤：定研究对象$\\to$受力分析并分段$\\to$规定正方向$\\to$F-t图像面积求变力冲量$\\to$列I合=$\\Delta$p】；警惕【重力与支持力冲量抵消只算水平方向；阻力冲量取负号；分段判断物体是否先保持静止】","src":"物一轮148.动量定理的理解及使用步骤_笔记","note":"视频|14:12-22:22","orig":"（例）F=4t变力作用于物块（fmax=μmg=4N），分段分析后用F-t图梯形面积求1-3s冲量16N·s，规定向右为正，末速度v=4m/s。","link":""},{"id":"phy0934","t":"动量定理·全过程比较冲量","s":"看到【直接比较冲量大小失效（力大时间短），且初末状态动量相同】","c":"想到【对全过程列∑I=0（初末动量均为零），用动量定理反推各力冲量关系；v-t图平行段意味着加速度相同从而摩擦因数相同】；警惕【推力作用时间$\\neq$全过程时间，列式时区分两段时间】","src":"物一轮148.动量定理的理解及使用步骤_笔记","note":"视频|22:22-29:58","orig":"（例）两物体F1>F2但t1<t2，全过程初末动量均为零，∑I=0；由If1=ft1、If2=ft2得IF2>IF1；v-t图中AB∥CD⇒减速加速度相同⇒μ相同。","link":""},{"id":"phy0935","t":"动量定理·系统整体法求末速度","s":"看到【系统内连接断开、内力变化但外力不变，求末速度】","c":"想到【内力变化不影响系统合外力，选整体为研究对象对全过程列I合=$\\Delta$p，免分段分析内力】；警惕【研究对象自由选择，选使问题更简单的系统；末态分量式按动量守恒形式书写】","src":"物一轮148.动量定理的理解及使用步骤_笔记","note":"视频|29:58","orig":"（例）细线断裂前后系统合外力不变（F合=8N），全过程I=F合t=24N·s，由m1v1+m2v2=24、v2=0得v1=8m/s，避免分析内力张力。","link":""},{"id":"phy0936","t":"平均力·两类平均力定义","s":"看到【题目求「平均作用力」需先确定类型】","c":"想到【给时间参数（作用时间t）求时间平均力；给空间参数（作用距离h）求空间平均力】；警惕【两类平均力不等价，不能互相替代计算】","src":"物一轮149.用动量定理求平均力完整视频_笔记","note":"视频|00:24-00:29","orig":"（知识）对时间平均F̅t=I/t（冲量除以时间）；对空间平均F̅x=W/x（功除以位移）；两种平均力不等价，不能互相替代。","link":""},{"id":"phy0937","t":"平均力·小球落地求平均力","s":"看到【小球落地撞击求平均力，条件给作用时间t或陷入深度h】","c":"想到【先由v=√(2gH)求触地速度；给t列动量定理求时间平均力，给h列动能定理求空间平均力】；警惕【混淆两种平均力的计算公式；t$\\to$0时F̅t远大于F̅x验证不等价】","src":"物一轮149.用动量定理求平均力完整视频_笔记","note":"视频|00:29-06:39","orig":"（例）小球从H落地陷入h：给时间t列动量定理mgt-Ft=0-(-mv)得F̅t=mg+mv/t；给深度h列动能定理mg(H+h)-Fh=0得F̅x=mg(H+h)/h。","link":""},{"id":"phy0938","t":"平均力·忽略重力的判断","s":"看到【碰撞/冲击求平均力时判断能否忽略重力】","c":"想到【比较平均冲击力与重力的数量级，远大于（约10倍以上）才可忽略；短时作用产生极大瞬时力】；警惕【两者同数量级时不可忽略重力】","src":"物一轮149.用动量定理求平均力完整视频_笔记","note":"视频|06:39-07:42","orig":"（知识）当F̅t/mg≫1（通常>10倍）时可忽略重力；相同数量级时不可忽略；短时间作用（如碰撞）会产生极大瞬时力。","link":""},{"id":"phy0939","t":"平均力·作用时间对结果的影响","s":"看到【同一动量变化在不同作用时间下求平均力】","c":"想到【F̅t=$\\Delta$p/t，作用时间越短平均力越大；重力是否保留由力的数量级对比决定】；警惕【长时作用（28N vs 10N重力）必须计入重力，极短作用（10^{5}N）才可忽略】","src":"物一轮149.用动量定理求平均力完整视频_笔记","note":"视频|07:42-10:10","orig":"（例）相同动量变化Δp=18kg·m/s：t=1s时F̅t=28N（不可忽略10N重力）；t=0.0001s时F̅t≈1.8×10⁵N（可忽略重力）。","link":""},{"id":"phy0940","t":"平均力·蹦床反弹求平均作用力","s":"看到【蹦床/反弹类问题求网对人的平均作用力】","c":"想到【先由v=√(2gh)分别求着网与离网速度，对接触过程列动量定理，动量变化为m(v1+v2)（两速度同取大小相加）】；警惕【速度方向处理：先规定正方向，反向速度取负号】","src":"物一轮149.用动量定理求平均力完整视频_笔记","note":"视频|10:10-14:30","orig":"（例）蹦床：着网v1=√(2gh1)=8m/s，离网v2=√(2gh2)=10m/s，列(mg-F)t=-mv2-mv1，动量变化项m(v1+v2)=900kg·m/s，解得F=1625N。","link":""},{"id":"phy0941","t":"平均力·弹簧问题中冲量与功的区别","s":"看到【用弹簧弹力（力随位移线性变化）求冲量】","c":"想到【功用动能定理（力对空间平均）求，冲量只能用动量定理I=mv求，不可把空间平均力代入冲量公式】；警惕【混淆空间平均与时间平均；简谐运动中力与时间呈非线性关系】","src":"物一轮149.用动量定理求平均力完整视频_笔记","note":"视频|14:30","orig":"（例）弹簧滑块：解法一误用空间平均力kx/2代入冲量计算；解法二正确——动能定理½kx²=½mv²求v，冲量用I=mv=x√(mk)求。答案B。","link":""},{"id":"phy0942","t":"流体冲击·柱状微元建模","s":"看到【连续流体（水柱/气流）冲击物体求冲击力】","c":"想到【统一框架：建柱状模型$\\to$取微元$\\to$表质量（$\\Delta$m=$\\rho$S$\\Delta$l）$\\to$列动量定理Ft=$\\Delta$m·v$\\to$用$\\Delta$l/t=v消元】；警惕【微元须取在冲击面附近以保证速度均匀】","src":"物一轮150.用动量定理求流体冲击力_笔记","note":"视频|00:09-00:58","orig":"（知识）核心公式Ft=mv-mv0；因流体各点速度不同，需建柱状模型，取冲击面附近柱状微元保证速度均匀，微元质量Δm=ρ·ΔV。","link":""},{"id":"phy0943","t":"流体冲击·迎风面空气阻力","s":"看到【运动物体推开空气/流体求阻力（给迎风面积S、密度$\\rho$、速度v）】","c":"想到【F=$\\rho$Sv^{2}：由$\\Delta$m·v=$\\rho$S$\\Delta$l·v与$\\Delta$t=$\\Delta$l/v消元得出；$\\Delta$l与t总是通过速度v关联消去】；警惕【误将$\\Delta$t或$\\Delta$l当作已知量保留在结果中】","src":"物一轮150.用动量定理求流体冲击力_笔记","note":"视频|00:58-08:35","orig":"（例）电动车迎风面积S、空气密度ρ、速度v：Δm=ρSΔl，Ft=Δm·v，由Δl/t=v消去Δl与t，得平均阻力F=ρSv²。答案A。","link":""},{"id":"phy0944","t":"流体冲击·离散微粒流冲击","s":"看到【离散微粒流冲击物体（给出单位体积微粒数n和单粒质量m）】","c":"想到【质量用$\\Delta$m=n·m·S·$\\Delta$l计算，得F=nmSv^{2}；连续流体用密度$\\rho$，离散微粒用微粒数$\\times$单粒质量】；警惕【两种质量计算方式不可混用】","src":"物一轮150.用动量定理求流体冲击力_笔记","note":"视频|08:35-13:15","orig":"（例）宇宙飞船在微粒区（分布密度1个/m³，单粒质量2×10⁻⁵g）：Δm=n·m·ΔV，微粒速度0→v，计算得推力F=0.98N。答案B。","link":""},{"id":"phy0945","t":"流体冲击·直升机悬停反推气流","s":"看到【直升机/风扇悬停求空气获得的速度】","c":"想到【研究对象转换为被推的空气柱：悬停平衡F=mg结合动量定理F$\\Delta$t=$\\Delta$m·v与$\\Delta$m=$\\rho$S$\\Delta$l、$\\Delta$l/$\\Delta$t=v，得v=√(mg/$\\rho$S)】；警惕【作用力与反作用力：桨对空气的力向下，空气对桨的力向上】","src":"物一轮150.用动量定理求流体冲击力_笔记","note":"视频|13:15-17:47","orig":"（例）直升机悬停：升力F=mg，空气受向下反作用力F，FΔt=Δm·v，Δm=ρSΔl，Δl/Δt=v，联立得v=√(mg/ρS)。答案D。","link":""},{"id":"phy0946","t":"动量定理进阶·f=kv时冲量化为位移","s":"看到【力与速度成正比（f=kv）且题目要求位移】","c":"想到【将变力冲量写为I=k·v̅·t=kh代入动量定理，把冲量转化为位移表达式；同类方法适用电磁感应中F∝v的安培力】；警惕【阻力冲量方向与正方向相反需加负号】","src":"物一轮151.用动量定理求特殊场景下的位移_笔记","note":"视频|00:03-00:38","orig":"（知识）当力与速度成正比（f=kv）时，变力冲量IF=k·v̅·t=k·h（v̅·t即位移h），动量定理可转化为含位移的表达式；适用电磁感应安培力问题。","link":""},{"id":"phy0947","t":"动量定理进阶·雨滴收尾速度与位移","s":"看到【雨滴/收尾速度模型（阻力f=kv）求下落位移或时间】","c":"想到【收尾速度由平衡mg=kvm得vm=mg/k；过程非匀变速不能用运动学公式，变力功不能用动能定理，优先对全过程列动量定理mgt-kh=mvm-0】；警惕【v̅·t=h的转换是关键；注意符号处理，如h表达式中的减号】","src":"物一轮151.用动量定理求特殊场景下的位移_笔记","note":"视频|00:38","orig":"（例）雨滴下落：收尾速度由mg=kvm得vm=mg/k（选项A）；全过程动量定理mgt-kh=mvm-0，代入vm得h=(mg/k)(t-m/k)（选项D）；非匀变速排除运动学公式，变力功无法用动能定理。","link":""},{"id":"phy0948","t":"动量守恒·守恒条件判断","s":"看到【判断系统动量是否守恒（选择题常见）】","c":"想到【看系统所受合外力是否为零（或不受外力）；内力不改变系统总动量】；警惕【判断前先明确系统边界，再做受力分析】","src":"物一轮152.【课前必看】本讲听课建议_笔记","note":"","orig":"（知识）系统总动量p=∑mivi保持不变的前提：系统不受外力或合外力为零；内力作用不影响系统总动量，需明确系统边界与受力分析。","link":""},{"id":"phy0949","t":"动量守恒·典型应用场景","s":"看到【碰撞、爆炸、反冲等瞬时作用过程求速度关系】","c":"想到【瞬时作用内力远大于外力，优先考虑用动量守恒作过程分析的核心条件】；警惕【严格说外力不为零时守恒是近似，需判断瞬时性是否成立】","src":"物一轮152.【课前必看】本讲听课建议_笔记","note":"","orig":"（知识）动量守恒常作为过程分析的核心条件，典型场景为碰撞、爆炸、反冲等瞬时作用过程；已知某时刻动量可推知任意时刻动量状态。","link":""},{"id":"phy0950","t":"动量守恒·考情与模型分级","s":"看到【人与船相对运动的「人船模型」或火箭推进类反冲问题】","c":"想到【用动量守恒分析相对运动/反冲：系统总动量为零（或守恒）时，两部分的动量大小相等方向相反】；警惕【人船模型常与高难度题目结合，需关注平均动量与位移关系】","src":"物一轮152.【课前必看】本讲听课建议_笔记","note":"","orig":"（知识）守恒判断为中频选择题考点；反冲问题（如火箭推进）为中等难度选择/解答题；人船模型为高频综合考点，近年考察频率上升。","link":""},{"id":"phy0951","t":"动量·动量守恒定律的内容","s":"看到【判断系统动量是否守恒、划定研究对象系统】","c":"想到【先明确系统边界，区分内力与外力，再检验合外力是否为零】；警惕【守恒指全程保持不变，而非仅初末相等】","src":"物一轮153.动量守恒定律及其前提_笔记","note":"视频|00:57-04:03","orig":"（知识）系统不受外力或所受外力矢量和为零时，系统总动量保持不变；系统内物体间作用力为内力，系统外物体对系统的作用力为外力。","link":""},{"id":"phy0952","t":"动量·动量守恒的矢量性","s":"看到【动量大小不变但方向变化（如匀速圆周运动）】","c":"想到【动量是矢量，方向变化即总动量不守恒】；警惕【不能只看大小相等就判守恒】","src":"物一轮153.动量守恒定律及其前提_笔记","note":"视频|04:03-07:14","orig":"（例）匀速圆周运动中动量大小不变但方向时刻改变，动量不守恒。","link":""},{"id":"phy0953","t":"动量·二维碰撞的矢量合成","s":"看到【二维斜碰求系统总动量】","c":"想到【总动量按矢量合成，用平行四边形法则】；警惕【动量不能直接代数相加】","src":"物一轮153.动量守恒定律及其前提_笔记","note":"视频|04:03-07:14","orig":"（例）台球母球（p₀）撞击静止球后，两球动量 p₁、p₂ 的矢量和等于 p₀。","link":""},{"id":"phy0954","t":"动量·分方向动量守恒","s":"看到【系统仅某一方向不受外力（如光滑水平面）】","c":"想到【该方向动量守恒，可分方向独立列式】；警惕【斜面类系统竖直方向动量不守恒】","src":"物一轮153.动量守恒定律及其前提_笔记","note":"视频|07:14-10:17","orig":"（知识）系统在某方向（如光滑水平面上的水平方向）不受外力时，该方向动量守恒。","link":""},{"id":"phy0955","t":"动量·守恒的常规条件","s":"看到【光滑面上碰撞、系统竖直方向重力与支持力抵消】","c":"想到【无外力或外力矢量和为零，系统动量守恒】；警惕【需逐方向核查外力是否真的平衡】","src":"物一轮153.动量守恒定律及其前提_笔记","note":"视频|10:17-10:34","orig":"（知识）无外力（如理想光滑面上两球碰撞）或外力平衡（重力与支持力抵消，∑F_外=0）时动量守恒。","link":""},{"id":"phy0956","t":"动量·内力远大于外力的近似守恒","s":"看到【碰撞、爆炸瞬间虽存在摩擦力等微小外力】","c":"想到【内力远大于外力时可忽略次要因素，近似动量守恒（理想化建模）】；警惕【这第三条守恒条件常被忽略】","src":"物一轮153.动量守恒定律及其前提_笔记","note":"视频|10:58","orig":"（例）粗糙面上两球碰撞，碰撞力 F_AB 远大于摩擦力 F_f（如10⁵N≫1N），可忽略外力近似守恒。","link":""},{"id":"phy0957","t":"动量·守恒判断误区","s":"看到【判断守恒时混淆动量与机械能的条件】","c":"想到【动量守恒看合外力，机械能守恒看做功，两套条件相互独立】；警惕【动量方向改变即不守恒】","src":"物一轮153.动量守恒定律及其前提_笔记","note":"视频|10:58","orig":"（知识）常见误区：误将机械能守恒条件套用于动量守恒、忽视瞬时过程（如爆炸）、混淆「守恒」与「不变」。","link":""},{"id":"phy0958","t":"动量·守恒判断的基本流程","s":"看到【判断系统动量是否守恒】","c":"想到【先直接看动量矢量和是否变化，复杂时再受力分析验证】；警惕【系统边界划定不同结论不同，需先明确包含哪些物体】","src":"物一轮154.判断系统动量是否守恒_笔记","note":"视频|00:16-03:02","orig":"（知识）直接分析法：先不分析受力，观察各物体动量矢量和是否不变；受力分析法：验证无外力／外力矢量和为零／内力远大于外力三条之一即守恒。","link":""},{"id":"phy0959","t":"动量·墙面弹力对守恒的影响","s":"看到【物块被墙（挡板）挡住，判断动量与机械能是否守恒】","c":"想到【墙的弹力是外力则动量不守恒；弹力作用点无位移不做功，机械能仍守恒】；警惕【「有外力」$\\neq$「外力做功」，两套守恒条件独立判断】","src":"物一轮154.判断系统动量是否守恒_笔记","note":"视频|03:02-10:54","orig":"（例）A 未离开墙壁时，墙面给 A 的弹力是外力，系统动量不守恒；但弹力作用点无位移不做功，机械能守恒。","link":""},{"id":"phy0960","t":"动量·脱离墙壁的临界状态","s":"看到【弹簧连接物块与墙壁，问何时脱离】","c":"想到【脱离前动量不守恒、机械能守恒；脱离后合外力为零，动量也守恒】；警惕【脱离临界点是弹力恰好为零（弹簧原长）】","src":"物一轮154.判断系统动量是否守恒_笔记","note":"视频|03:02-10:54","orig":"（例）弹簧恢复原长后继续伸长，弹力方向变为拉向墙面一侧，墙面无法提供反向力，A 开始脱离墙壁。","link":""},{"id":"phy0961","t":"动量·分方向守恒判断","s":"看到【物块滑上曲面小车、系统各方向运动不同】","c":"想到【分方向判断：某方向合外力为零则该方向守恒；任一方向不守恒则总动量必不守恒】；警惕【有竖直加速度时支持力不等于总重力】","src":"物一轮154.判断系统动量是否守恒_笔记","note":"视频|10:54-20:18","orig":"（例）光滑地面上物块滑上圆弧小车：水平方向合外力为零动量守恒；竖直方向物块有加速度（a_y≠0），支持力 N≠(m+M)g，动量不守恒。","link":""},{"id":"phy0962","t":"动量·机械能守恒与摩擦耗散","s":"看到【轨道部分光滑部分粗糙，判断机械能】","c":"想到【只有重力、弹力做功机械能才守恒；滑动摩擦力做功生热则机械能不守恒】；警惕【摩擦力是内力不影响动量守恒，但会耗散机械能】","src":"物一轮154.判断系统动量是否守恒_笔记","note":"视频|10:54-20:18","orig":"（例）圆弧段光滑仅重力做功机械能守恒；CD 段粗糙面滑动摩擦生热，部分动能转化为内能，机械能不守恒。","link":""},{"id":"phy0963","t":"动量·碰撞瞬间的守恒判断","s":"看到【两物体碰撞（含粘性碰撞）瞬间判断守恒】","c":"想到【碰撞内力远大于外力，动量守恒；完全非弹性碰撞动能损失最大】；警惕【误把碰撞冲击力当外力】","src":"物一轮154.判断系统动量是否守恒_笔记","note":"视频|10:54-20:18","orig":"（例）粘性碰撞属完全非弹性碰撞，动能损失最大转化为内能；碰撞时冲击力属系统内力，动量守恒。","link":""},{"id":"phy0964","t":"动量·子系统守恒判断","s":"看到【多物体弹簧系统，问某个子系统是否守恒】","c":"想到【先按题给对象重新划定系统边界，再逐一查外力】；警惕【误认为弹力一定是内力——换系统后可能变外力】","src":"物一轮154.判断系统动量是否守恒_笔记","note":"视频|20:18-24:28","orig":"（例）弹簧+滑块+小车系统整体水平动量守恒；但对「弹簧+滑块」子系统，小车对弹簧的弹力是外力且滑块动量从零增大，动量不守恒。","link":""},{"id":"phy0965","t":"动量·爆炸与反冲类图景判断","s":"看到【人船反向运动、火箭分离、鞭炮爆炸等图景】","c":"想到【水平无外力或爆炸内力远大于外力时近似守恒，各部分反向动量大小相等】；警惕【留意题干关键词「光滑」「忽略阻力」「高速」】","src":"物一轮154.判断系统动量是否守恒_笔记","note":"视频|24:28","orig":"（例）人船反向运动（水平无外力）、火箭分离（爆炸力≫重力）、鞭炮爆炸均近似动量守恒，各部分动量方向相反、大小相等。","link":""},{"id":"phy0966","t":"动量·人车锤多物体相互作用","s":"看到【人在车上挥锤/抛物，系统初始总动量为零】","c":"想到【光滑水平方向动量守恒，由一部分动量方向反推另一部分速度方向，任意时刻两部分动量等大反向】；警惕【中间存在瞬时静止点，速度是变化的】","src":"物一轮155.利用动量守恒分析问题_笔记","note":"视频|00:08-16:29","orig":"（例）人在车上挥锤：锤向右挥时车向左动，锤竖直时车瞬时静止，锤向左挥时车向右动，任意时刻 p锤+p人车=0。","link":""},{"id":"phy0967","t":"动量·碰撞求质量比","s":"看到【已知碰前碰后各速度，求两物体质量比】","c":"想到【规定正方向，速度以正负号代入 m_{1}v_{1}+m_{2}v_{2}=m_{1}v_{1}^{'}+m_{2}v_{2}^{'} 求解】；警惕【速度方向通过正负号体现，符号代错全盘皆错】","src":"物一轮155.利用动量守恒分析问题_笔记","note":"视频|00:08-16:29","orig":"（例）v₁=6m/s（向右）、v₂=-2m/s（向左），碰后 v₁′=-4m/s、v₂′=4m/s，由 6m₁-2m₂=-4m₁+4m₂ 得 m₁:m₂=3:5。","link":""},{"id":"phy0968","t":"动量·平板车持续运动判断","s":"看到【车上的人抛出/敲打物体，判断车能否持续朝某方向运动】","c":"想到【列 p锤+p人+p车=0 逐阶段分析动量方向；物体留在系统内则守恒使其最终静止，脱离系统才可能持续运动】；警惕【区分抛回车内（内力守恒）与抛出车外（守恒被打破）】","src":"物一轮155.利用动量守恒分析问题_笔记","note":"视频|16:29-22:42","orig":"（例）平板车上人处理锤子：只有把锤丢出车外（锤脱离系统）车才能持续向左运动；锤落回车内则落地后系统恢复静止。","link":""},{"id":"phy0969","t":"动量·动量定理求平均作用力","s":"看到【已知作用时间与速度变化，求平均作用力】","c":"想到【用动量定理 F·t=m(v_{2}-v_{0})】；警惕【失重环境下推力即合外力；注意题干中的干扰质量（如旁观者甲）】","src":"物一轮155.利用动量守恒分析问题_笔记","note":"视频|22:42","orig":"（例）空间站中航天员推箱子：F×0.2s=50kg×(4m/s-2m/s)，得 F=500N（失重环境仅考虑推力）。","link":""},{"id":"phy0970","t":"动量·无外力系统的反冲速度","s":"看到【宇航员/人推开物体后求自身速度】","c":"想到【无外力系统动量守恒 (M+m)v_{0}=Mv_{1}+mv_{2}，代数求解并注明方向】；警惕【答案方向表述必须完整（向左/向右）】","src":"物一轮155.利用动量守恒分析问题_笔记","note":"视频|22:42","orig":"（例）航天员（乙+箱子）系统初动量 300kg×2m/s=600kg·m/s，末态 250v₁+50×4=600，解得 v₁=1.6m/s（向左）。","link":""},{"id":"phy0971","t":"动量·反冲现象的本质","s":"看到【火箭喷气、发射炮弹等反冲现象】","c":"想到【内力远大于外力，按动量守恒建模处理】；警惕【先确认题给速度是对地还是相对速度】","src":"物一轮156.反冲问题_笔记","note":"视频|00:33-01:05","orig":"（知识）反冲现象源于系统内部作用力远大于外力（如火箭重力），可近似为动量守恒过程；人船模型常结合综合题隐蔽考查。","link":""},{"id":"phy0972","t":"动量·反冲问题（对地速度）","s":"看到【喷出气体（或抛出物）的速度为对地速度】","c":"想到【以地面为参考系列动量守恒式，动量用对地速度表示】；警惕【喷气后主体质量变为 m-$\\Delta$m，质量变化最易被忽略】","src":"物一轮156.反冲问题_笔记","note":"视频|01:05-07:07","orig":"（知识）以地面为参考系：mv=(m-Δm)v′-Δmu，解得 v′=(mv+Δmu)/(m-Δm)。","link":""},{"id":"phy0973","t":"动量·反冲问题（相对速度）","s":"看到【喷出气体的速度是相对火箭的速度】","c":"想到【以喷气前火箭为参考系、出动量为零列式，速度增量用 $\\Delta$v】；警惕【两种参考系列式不可混用，新高考可能考教材推导细节】","src":"物一轮156.反冲问题_笔记","note":"视频|01:05-07:07","orig":"（知识）以喷气前火箭为参考系（初动量为零）：末动量=(m-Δm)Δv-Δmu，其中 Δv 为速度增量；人教版教材采用此推导。","link":""},{"id":"phy0974","t":"动量·斜射炮身的反冲速度","s":"看到【炮身与水平成 $\\alpha$ 角发射炮弹，求炮车反冲速度】","c":"想到【只有水平方向动量守恒，炮弹动量取水平分量 mv_{0}cos$\\alpha$】；警惕【竖直方向炮弹加速度不平衡不守恒；速度方向符号易错】","src":"物一轮156.反冲问题_笔记","note":"视频|07:07-10:15","orig":"（例）炮身斜向上发射炮弹：水平方向无摩擦守恒，末动量=炮弹水平分量 mv₀cosα-炮车动量 Mv，解得 v=mv₀cosα/M。","link":""},{"id":"phy0975","t":"动量·两船抛接货物的临界问题","s":"看到【两船间抛接货物，问恰好不相撞/距离保持恒定】","c":"想到【两船最终速度相等是临界条件，先用整体法求共同速度，再对单个船列守恒式求抛出速度】；警惕【系统划分：整体与隔离交替使用】","src":"物一轮156.反冲问题_笔记","note":"视频|10:15","orig":"（例）甲乙船和货物视为整体：初动量 6m×2v₀+15m×v₀=27mv₀，末动量 21m·v共，得 v共=9v₀/7；再对乙船列 15mv₀=12mv共-3mv₁，得 v₁=17v₀/7。","link":""},{"id":"phy0976","t":"动量·人船模型识别","s":"看到【初始静止的系统中两部分反向运动（人走船移、球摆车移）】","c":"想到【水平方向动量守恒，两部分速度（动量）等大反向】；警惕【初始静止是常见但非必须条件】","src":"物一轮157.人船模型_笔记","note":"视频|01:12-01:58","orig":"（知识）人和船静止于水面（忽略水阻力），人走船反向移动；水平方向合外力为零，m人v人=m船v船。","link":""},{"id":"phy0977","t":"动量·由动量守恒推位移关系","s":"看到【动量守恒条件下求位移】","c":"想到【对守恒式同乘 $\\Delta$t 并累积，转化为位移关系 m_{1}x_{1}=m_{2}x_{2}（微元思想）】；警惕【该式对变速过程同样成立，不必假设匀速】","src":"物一轮157.人船模型_笔记","note":"视频|02:38-05:04","orig":"（知识）动量守恒式本身不含位移项，需两边同乘 Δt 累积微小时间段，得 m₁x₁=m₂x₂；变速运动也成立（时间足够小可视为匀速）。","link":""},{"id":"phy0978","t":"动量·人船模型的几何方程","s":"看到【求「人走船移」类各自的对地位移】","c":"想到【动量守恒给出第一个位移方程，几何关系（相对位移和）给出第二个方程，联立求解】；警惕【两部分对地位移方向相反，勿把对地位移与相对位移混为一谈】","src":"物一轮157.人船模型_笔记","note":"视频|05:04-06:04","orig":"（知识）第二方程来自几何关系：x人+x船=L（船长），通过示意图分析相对位移关系，与位移守恒式联立求解。","link":""},{"id":"phy0979","t":"动量·初始不静止的扩展","s":"看到【系统初动量不为零的人船类位移问题】","c":"想到【用总动量$\\times$时间=Σmx 变形求位移】；警惕【时间 t 是否给出是隐含条件，缺 t 则此路不通】","src":"物一轮157.人船模型_笔记","note":"视频|06:04-08:36","orig":"（知识）初速度不为零时需已知时间 t，通过 (m+M)v₀t=mx₁+Mx₂ 变形求解位移。","link":""},{"id":"phy0980","t":"动量·小球摆车模型","s":"看到【光滑车上单摆/小球摆动，求车移动距离】","c":"想到【水平方向动量守恒转化为位移关系，加上摆长（水平投影）几何方程联立】；警惕【小球水平位移与车位移方向相反】","src":"物一轮157.人船模型_笔记","note":"视频|08:36-13:31","orig":"（例）光滑车上小球摆动：m₀x₁=mx₂ 且 x₁+x₂=l，解得 x车=m₀l/(m₀+m)。","link":""},{"id":"phy0981","t":"动量·子弹连发求车移动距离","s":"看到【车上连发子弹，求每次或总计移动距离】","c":"想到【对每次发射时刻的「剩余系统」列动量守恒，再配几何关系 x_{1}+x_{2}=d】；警惕【已击中的子弹仍属系统，总质量不变；发射对象质量逐次变化】","src":"物一轮157.人船模型_笔记","note":"视频|13:31","orig":"（例）每次射击子弹向左、车向右：单次 mx₁=[M+(n-1)m]x₂ 且 x₁+x₂=d，单次移动距离为 md/(M+nm)。","link":""},{"id":"phy0982","t":"动量·碰撞与类碰撞的课程框架","s":"看到【表面不是碰撞但过程类似（弹簧缓冲、滑上圆弧轨、子弹打入木块）】","c":"想到【识别「类碰撞」模型，套用碰撞规律：动量守恒+能量转化分析】；警惕【类碰撞理解成本高，需先扎实掌握基本碰撞规律】","src":"物一轮158.【课前必看】本讲听课建议_笔记","note":"视频|01:47-03:15","orig":"（知识）碰撞需同时结合动量守恒与能量转化规律；类碰撞指表面不是碰撞但规律与碰撞相似、可用碰撞规律分析的过程。","link":""},{"id":"phy0983","t":"动量·碰撞类型与能量对应关系","s":"看到【判断碰撞类型并选择对应规律】","c":"想到【按能量特征分三类：弹性（动能守恒）、非弹性（部分损失）、完全非弹性（共速、损失最大）】；警惕【动能损失最大化的条件是碰后共速】","src":"物一轮158.【课前必看】本讲听课建议_笔记","note":"视频|01:47-03:15","orig":"（知识）弹性碰撞：动能守恒（质量相等时速度交换）；非弹性碰撞：动能有损失，完全非弹性碰撞共速且动能损失最大；类碰撞含弹簧类、圆弧轨类、子弹打木块三大模型。","link":""},{"id":"phy0984","t":"动量·多过程问题中的碰撞环节","s":"看到【多过程综合题中嵌入碰撞环节】","c":"想到【在过程交接处快速识别碰撞，单独隔离碰撞瞬间列动量守恒式，再衔接前后过程的能量或运动分析】；警惕【碰撞前后阶段分开列式，勿把碰撞瞬间的冲击力混入其他过程】","src":"物一轮158.【课前必看】本讲听课建议_笔记","note":"视频|03:15","orig":"（知识）碰撞是高频考点（2024 年多省考查），常作为多过程问题（如碰撞+平抛）的环节出现，选择题和解答题均涉及。","link":""},{"id":"phy0985","t":"碰撞·碰撞的动量特征","s":"看到【碰撞过程求碰后速度/判断碰撞】","c":"想到【碰撞内力远大于外力，系统动量必守恒，可无条件先列动量守恒式】；警惕【动量守恒普适，但动能不一定守恒】","src":"物一轮159.了解碰撞基本规律与碰撞分类_笔记","note":"视频|00:34-05:56","orig":"（知识）任何碰撞过程内力远大于外力，系统动量守恒：mAvA+mBvB=mAvA′+mBvB′。","link":""},{"id":"phy0986","t":"碰撞·碰撞的能量特征","s":"看到【验证某碰后速度是否可能成立】","c":"想到【碰前总动能$\\geq$碰后总动能，动能不可能凭空增加】；警惕【等号仅在弹性碰撞时成立】","src":"物一轮159.了解碰撞基本规律与碰撞分类_笔记","note":"视频|00:34-05:56","orig":"（知识）碰撞可能存在动能损失但不会凭空产生能量：½mAvA²+½mBvB²≥½mAvA′²+½mBvB′²，取等号时为弹性碰撞。","link":""},{"id":"phy0987","t":"碰撞·碰撞的速度特征","s":"看到【两物体同向运动碰撞，检验碰后速度】","c":"想到【碰后前车速度$\\geq$后车速度（不穿透原则）】；警惕【反向（对碰）情形不适用该限制】","src":"物一轮159.了解碰撞基本规律与碰撞分类_笔记","note":"视频|00:34-05:56","orig":"（知识）碰后速度需符合现实：同向运动时「前方」物体碰后速度不小于「后方」物体，否则会穿过重叠；反向运动无此限制。","link":""},{"id":"phy0988","t":"碰撞·碰撞的三种分类","s":"看到【区分弹性、非弹性、完全非弹性碰撞】","c":"想到【按「动能是否守恒」与「是否共速」两个维度分类，完全非弹性是动能损失的极限情况】；警惕【动量守恒是三者共性，差异只在能量】","src":"物一轮159.了解碰撞基本规律与碰撞分类_笔记","note":"视频|06:07-09:22","orig":"（知识）弹性碰撞：动量、动能均守恒；非弹性碰撞：动量守恒但动能损失；完全非弹性碰撞：碰后共速（vA′=vB′），动能损失最大。","link":""},{"id":"phy0989","t":"碰撞·题型关键词与类型判别","s":"看到【题干出现「黏在一起」「共速」「动能损失最大」「弹性正碰」等关键词】","c":"想到【据关键词锁定碰撞类型，选用对应方程组】；警惕【正碰$\\neq$弹性碰撞，能量是否守恒需单独判断】","src":"物一轮159.了解碰撞基本规律与碰撞分类_笔记","note":"视频|09:22-12:44","orig":"（知识）「弹性碰撞」「弹性正碰」「无动能损失」→弹性碰撞；「黏在一起」「共速」「动能损失最大」→完全非弹性碰撞；「正碰」仅表示速度沿同一直线。","link":""},{"id":"phy0990","t":"碰撞·碰后速度可能值判断","s":"看到【选择题给出多组碰后速度，问哪个可能】","c":"想到【三步验证：动量守恒$\\to$动能不增$\\to$速度合理性（不穿透重叠）】；警惕【最易漏掉速度的物理合理性检查】","src":"物一轮159.了解碰撞基本规律与碰撞分类_笔记","note":"视频|12:44-20:40","orig":"（例）判断碰后速度候选值：D 选项碰后动能大于碰前被排除，A、B 选项导致物体重叠被排除，答案 C。","link":""},{"id":"phy0991","t":"碰撞·弹性正碰速度公式推导","s":"看到【弹性正碰求两物体碰后速度】","c":"想到【联立动量守恒与动能守恒，用平方差公式降幂消元；结论 v_{1}=(m_{1}-m_{2})v_{0}/(m_{1}+m_{2})、v_{2}=2m_{1}v_{0}/(m_{1}+m_{2}) 可直接使用】；警惕【等质量弹性碰撞两速度交换】","src":"物一轮159.了解碰撞基本规律与碰撞分类_笔记","note":"视频|20:40","orig":"（例）联立 m₁v₀=m₁v₁+m₂v₂ 与 ½m₁v₀²=½m₁v₁²+½m₂v₂²，平方差消元得 v₁=(m₁-m₂)v₀/(m₁+m₂)、v₂=2m₁v₀/(m₁+m₂)。","link":""},{"id":"phy0992","t":"碰撞·一般非弹性碰撞规律","s":"看到【碰撞后不粘连、动能部分损失的一般碰撞】","c":"想到【动量守恒照列，动能损失用 $\\Delta$E=初动能-末动能 计算】；警惕【非弹性碰撞只有动量守恒这一条「免费」方程】","src":"物一轮160.弹性碰撞的结论与应用_笔记","note":"视频|00:17-01:12","orig":"（知识）动量守恒 m₁v₁+m₂v₂=m₁v₁′+m₂v₂′；动能损失 ΔE=碰前总动能-碰后总动能；碰后物体不粘连、动能部分损失。","link":""},{"id":"phy0993","t":"碰撞·完全非弹性碰撞共速","s":"看到【两物体碰后粘在一起/具有共同速度】","c":"想到【按完全非弹性碰撞处理，一个动量守恒方程直接解出 v共】；警惕【共速即动能损失最大的极限情形】","src":"物一轮160.弹性碰撞的结论与应用_笔记","note":"视频|01:12-07:22","orig":"（知识）碰后两物体共速：m₁v₁+m₂v₂=(m₁+m₂)v共，v共=(m₁v₁+m₂v₂)/(m₁+m₂)，此时动能损失最大。","link":""},{"id":"phy0994","t":"碰撞·完全非弹性碰撞动能损失公式","s":"看到【求完全非弹性碰撞损失的动能】","c":"想到【$\\Delta$E=½·(m_{1}m_{2})/(m_{1}+m_{2})·(v_{1}-v_{2})^{2}，分子质量积、分母质量和、速度取相对速度平方】；警惕【记不住公式时回归基本原理：先求 v共 再算动能差】","src":"物一轮160.弹性碰撞的结论与应用_笔记","note":"视频|01:12-07:22","orig":"（知识）ΔE=½·(m₁m₂)/(m₁+m₂)·(v₁-v₂)²，口诀「积在和上飞，速度取相对」；也可先求 v共 再代入动能差计算。","link":""},{"id":"phy0995","t":"碰撞·雨滴融合类共速计算","s":"看到【液滴/雨滴融合合为一体，求共同速度或损失能量】","c":"想到【按完全非弹性碰撞处理：先由几何比例（V∝r^{3}、密度相同）定质量比，再套共速与损失公式】；警惕【半径正比定速度、立方比定质量，两个比例勿混淆】","src":"物一轮160.弹性碰撞的结论与应用_笔记","note":"视频|07:22-13:15","orig":"（例）两雨滴融合：半径比 2:1 → 速度比 2:1（v∝r）、体积比 8:1（V∝r³）故质量比 8:1，代入得 v共=17v/9，ΔEk=8Ek/9。","link":""},{"id":"phy0996","t":"碰撞·结论公式的适用范围","s":"看到【多球/非两体碰撞（如一连串球）求共速与能量损失】","c":"想到【两球碰撞结论公式有适用范围，模型不符时回归动量守恒基本原理重新列式】；警惕【死套两球公式而不检验模型条件】","src":"物一轮160.弹性碰撞的结论与应用_笔记","note":"视频|13:15","orig":"（例）一小球与 2023 个球碰后共速：两球公式不适用，回归动量守恒 mv₀=2023m·v共，得 v共=v₀/2023，ΔE=2022Ek/2023。","link":""},{"id":"phy0997","t":"动量·一般非弹性碰撞","s":"看到【碰撞问题需同时涉及动量与能量分析】","c":"想到【动量守恒对所有碰撞类型恒成立，列 mv 初=mv 末；动能损失用初末总动能之差求】；警惕【非弹性碰撞动能不守恒，不能列动能守恒方程】","src":"物一轮161.非弹性碰撞的结论与应用_笔记","note":"视频|00:17-01:12","orig":"（知识）碰撞过程动量守恒 m₁v₁+m₂v₂=m₁v₁′+m₂v₂′；系统动能不守恒，损失量 ΔE=初总动能−末总动能","link":""},{"id":"phy0998","t":"动量·完全非弹性碰撞","s":"看到【两物体碰后粘在一起或达到共同速度】","c":"想到【按完全非弹性碰撞处理：先共速公式求 v共，动能损失用折合质量乘相对速度平方；能量损失最大但动量仍守恒】；警惕【最大能量损失指动能损失最大，不是动量有损失】","src":"物一轮161.非弹性碰撞的结论与应用_笔记","note":"视频|01:12-07:22","orig":"（知识）碰后共速 v共=(m₁v₁+m₂v₂)/(m₁+m₂)；动能损失 ΔE=½·m₁m₂/(m₁+m₂)·(v₁−v₂)²，口诀「积在和上飞，速度取相对」","link":""},{"id":"phy0999","t":"动量·液滴融合类碰撞","s":"看到【球形液滴或小球融合的完全非弹性碰撞且给出半径关系】","c":"想到【密度相同则 m∝r^{3}，先由半径比定质量比，再代入共速公式与能量损失公式】；警惕【误认为质量比等于半径比，忽略立方关系】","src":"物一轮161.非弹性碰撞的结论与应用_笔记","note":"视频|07:22-13:16","orig":"（例）雨滴融合：收尾速度 vm∝r，两雨滴半径比使体积比 8:1，求融合后共速与动能损失（答案 v共=17v/9，ΔEk=8Ek/9）","link":""},{"id":"phy1000","t":"动量·多体碰撞","s":"看到【多个物体连续碰撞最终达到共同速度】","c":"想到【不必分析中间过程，直接对初末整体状态列动量守恒，动能损失=初动能−末动能】；警惕【超出两体基本模型时不能机械套用两体碰撞结论，须回归动量守恒和能量守恒基本原理】","src":"物一轮161.非弹性碰撞的结论与应用_笔记","note":"视频|13:16","orig":"（例）2023 个相同小球多次碰撞最终共速，直接对初末状态列 mv₀=2023mv共，动能损失 ΔE=2022/2023·Ek","link":""},{"id":"phy1001","t":"动量·弹簧类碰撞模型","s":"看到【光滑水平面上物体通过轻弹簧发生碰撞（弹簧初始原长）】","c":"想到【系统动量守恒、机械能守恒；弹力为内力，形变量决定弹力与加速度，整个过程是变加速运动】；警惕【弹力变化导致加速度变化，不能用匀变速公式】","src":"物一轮162.弹簧类碰撞模型_笔记","note":"视频|01:06-01:47","orig":"（知识）光滑水平面上 m₁ 以 v₀ 撞向经轻弹簧（原长）连接的静止 m₂：v₁>v₂ 时弹簧压缩，弹力 F=kx 随形变量增大，两者做变加速运动","link":""},{"id":"phy1002","t":"动量·弹簧模型共速状态","s":"看到【弹簧类问题中两物体速度相等（共速）】","c":"想到【共速时弹簧形变量最大、弹性势能最大，用动量守恒 m_{1}v_{0}=(m_{1}+m_{2})v共 求共速】；警惕【共速时弹力不为零，之后两物体继续变速，不是稳定状态】","src":"物一轮162.弹簧类碰撞模型_笔记","note":"视频|09:21-14:04","orig":"（知识）v₁=v₂ 时弹簧压缩量最大（最短），v-t 图两曲线在共速时刻相交；此时仍有弹力，速度不会保持恒定","link":""},{"id":"phy1003","t":"动量·弹簧模型恢复原长","s":"看到【弹簧第一次恢复原长时刻的状态分析】","c":"想到【此时弹性势能为零、系统为纯动能，两物体速度满足弹性碰撞结论；后续伸长阶段对称重复压缩过程】；警惕【恢复原长时两物体速度不相等，动能也不是最小值】","src":"物一轮162.弹簧类碰撞模型_笔记","note":"视频|14:04-15:36","orig":"（知识）第一次恢复原长时 F=0、a=0，弹性势能为零，v₂>v₁；之后弹簧伸长，过程与压缩阶段对称，再次共速时弹簧最长","link":""},{"id":"phy1004","t":"动量·弹簧与完全非弹性碰撞类比","s":"看到【求弹簧最大弹性势能】","c":"想到【在共速时刻列动量守恒求 v共，最大势能 Epm=½·m_{1}m_{2}/(m_{1}+m_{2})·(v_{1}−v_{2})^{2}，即动能损失全部转化为弹性势能】；警惕【动碰动时相对速度取 v_{1}−(−v_{2})=v_{1}+v_{2}，速度要带正负号】","src":"物一轮162.弹簧类碰撞模型_笔记","note":"视频|15:36-19:46","orig":"（知识）从原长到弹簧最短的压缩阶段类比完全非弹性碰撞：共速公式相同，动能损失最大并全部转化为弹性势能 Epm=½·m₁m₂/(m₁+m₂)·v₀²","link":""},{"id":"phy1005","t":"动量·弹簧与弹性碰撞类比","s":"看到【弹簧恢复原长时求两物体各自速度】","c":"想到【全程动量守恒且动能无损失，直接套用弹性碰撞速度公式】；警惕【类碰撞与真实碰撞本质差异在弹性势能参与能量转换，只在特定时刻结论等价】","src":"物一轮162.弹簧类碰撞模型_笔记","note":"视频|19:46-25:04","orig":"（知识）从原长到第一次恢复原长全程类比弹性碰撞：动量、动能双守恒，v₁=(m₁−m₂)/(m₁+m₂)·v₀，v₂=2m₁/(m₁+m₂)·v₀；v₁ 与 v₂ 同向说明 m₁>m₂，反向说明 m₁<m₂","link":""},{"id":"phy1006","t":"动量·弹簧模型动碰动例题","s":"看到【两滑块相向运动且其中之一连有轻弹簧】","c":"想到【先规定正方向列动量守恒求共速，最大势能用相对速度公式，恢复原长用弹性碰撞公式，冲量用动量定理 I=$\\Delta$p】；警惕【相向运动时动量与相对速度都须带正负号，Q 先减速到零再反向，共速时其动能并非最小】","src":"物一轮162.弹簧类碰撞模型_笔记","note":"视频|25:04-33:56","orig":"（例）P(3m) 与 Q(m) 以 v₀ 相向运动、Q 连轻弹簧：v共=½v₀，Epm=3/2·mv₀²，恢复原长后 P 速度为 0、Q 速度 2v₀，P 受冲量大小 3mv₀","link":""},{"id":"phy1007","t":"动量·弹簧模型 v-t 图像","s":"看到【弹簧模型给出 v-t 图像并标注共速与恢复原长时刻】","c":"想到【交点即共速，用动量守恒求质量比；由牛顿第三定律 m_{1}a_{1}=m_{2}a_{2} 得加速度比；能量差法求动能与势能之比】；警惕【图像交点对应共速而非恢复原长，斜率变化反映弹力变化】","src":"物一轮162.弹簧类碰撞模型_笔记","note":"视频|33:56-39:47","orig":"（例）m₁ 初速 3m/s 撞静止 m₂，v-t 图标出 t₁ 共速 1m/s（弹簧最短）、t₂ 第一次恢复原长、t₃ 弹簧最长、t₄ 第二次恢复原长，推得 m₂=2m₁，Ek:Ep=1:2","link":""},{"id":"phy1008","t":"动量·弹簧模型 a-t 图像","s":"看到【弹簧模型给出 a-t 图像求质量比或速度】","c":"想到【a=0 对应弹簧恢复原长；a-t 图面积等于速度变化量；由 aP/aQ=mQ/mP 定质量比，再用弹性碰撞结论验证】；警惕【面积有正负，对应速度增减方向，勿丢符号】","src":"物一轮162.弹簧类碰撞模型_笔记","note":"视频|39:47","orig":"（例）a-t 图标出 t₁ 弹簧最长（加速度极值）、t₂ 第一次恢复原长（a=0），由 aP/aQ=mQ/mP 得 mP:mQ=2:1，面积 S₁:S₂=2:1，恢复原长速度 v₁′=v₀/3、v₂′=4v₀/3","link":""},{"id":"phy1009","t":"动量·圆弧轨类碰撞模型","s":"看到【小球在可移动的圆弧轨道上运动】","c":"想到【只列水平方向动量守恒，配合全程机械能守恒联立求解】；警惕【竖直方向动量不守恒，不能对全方向列守恒式】","src":"物一轮163.圆弧轨类碰撞模型_笔记","note":"视频|00:55-04:28","orig":"（知识）水平地面上可移动圆弧轨道（M）与小球（m），忽略摩擦：水平方向系统动量守恒 mv₀=mv_mx+Mv_M，竖直方向不守恒（M 竖直速度恒为零）；系统机械能守恒","link":""},{"id":"phy1010","t":"动量·圆弧轨最高点","s":"看到【求小球沿可动圆弧轨上升的最大高度或最大重力势能】","c":"想到【最高点两者共速，按完全非弹性碰撞列水平动量守恒求 v共，再由机械能守恒求 Epm 或 h】；警惕【共速是水平方向共速，不是小球速度为零】","src":"物一轮163.圆弧轨类碰撞模型_笔记","note":"视频|06:30-08:38","orig":"（知识）最高点小球竖直速度为零、相对速度为零，两者水平共速 v_m=v_M；此时重力势能最大 Epm=½·mM/(m+M)·v₀²，类比完全非弹性碰撞","link":""},{"id":"phy1011","t":"动量·圆弧轨返回最低点","s":"看到【圆弧轨模型求小球返回最低点后的速度或运动形式】","c":"想到【直接套用弹性碰撞速度公式；质量相等时动能完全转移，小球对地速度为零】；警惕【区分相对运动与对地运动——m=M 时相对轨道向左但对地静止下落，并非向左平抛】","src":"物一轮163.圆弧轨类碰撞模型_笔记","note":"视频|08:38-14:35","orig":"（知识）小球返回最低点类比弹性碰撞：v小=(m−M)/(m+M)·v₀，v大=2m/(m+M)·v₀；特例 m=M 时 v小=0，小球对地做自由落体","link":""},{"id":"phy1012","t":"动量·圆弧轨选择题判断","s":"看到【圆弧轨类碰撞模型的选择题选项判断】","c":"想到【分两步类比：上升过程按完全非弹性碰撞（共速+能量损失最大），返回过程按弹性碰撞（速度公式）】；警惕【选项常设陷阱：误认为最高点小球静止、返回时方向判断错误】","src":"物一轮163.圆弧轨类碰撞模型_笔记","note":"视频|14:35-20:52","orig":"（例）小球滑上可动圆弧轨：最大高度 h=v₀²/6g（类比完全非弹性碰撞），最高点共速 v共=2v₀/3，返回后小球向右平抛（答案 B）","link":""},{"id":"phy1013","t":"动量·可动半圆滑槽","s":"看到【小球沿可动光滑滑槽下滑求位移或最大速度】","c":"想到【水平动量守恒推人船模型分配相对位移；速度最大位置在最低点，联立水平动量守恒与机械能守恒；斜方向速度按几何角度正交分解】；警惕【相对速度与对地速度的区别——D 点合速度方向约束须用对地速度】","src":"物一轮163.圆弧轨类碰撞模型_笔记","note":"视频|20:52-50:00","orig":"（例）小球自半圆滑槽最高点由静止滑下：人船模型 mx₁=Mx₂、x₁+x₂=2R 得 x₂=2R/3；最低点速度最大，½mv₁²+½Mv₂²=mg·3R 与 mv₁=Mv₂ 联立；D 点速度按 30° 夹角分解","link":""},{"id":"phy1014","t":"动量·子弹打木块模型概述","s":"看到【子弹打木块类问题】","c":"想到【水平动量守恒为主线，结合能量守恒（动能定理）辅助分析，区分弹性与非弹性情形】；警惕【先确定系统边界与守恒条件，再动笔列式】","src":"物一轮163.圆弧轨类碰撞模型_笔记","note":"视频|50:00","orig":"（知识）子弹打木块与板块模型类似：碰撞前后系统动量守恒，部分动能转化为内能；需关注子弹与木块的相对运动，先明确系统边界判断守恒条件","link":""},{"id":"phy1015","t":"动量·子弹打木块（共速情形）","s":"看到【子弹射入木块未穿出（最终相对静止）】","c":"想到【按完全非弹性碰撞列动量守恒求共速，摩擦生热 Q=½·mM/(m+M)·v_{0}^{2}】；警惕【生热用相对位移 $\\Delta$s 计算，不是对地位移】","src":"物一轮164.子弹打木块模型_笔记","note":"视频|00:08-02:17","orig":"（知识）子弹未穿出木块最终共速：mv₀=(M+m)v共；能量关系 ½mv₀²=½(M+m)v共²+Q，Q=f·Δs 为摩擦生热；属完全非弹性碰撞，能量损失最大","link":""},{"id":"phy1016","t":"动量·子弹打木块（穿出情形）","s":"看到【子弹穿出木块求两者末速度或生热】","c":"想到【动量守恒联立能量关系求解，Q=f·L（L 为木块长度）】；警惕【穿出时能量损失并非更大——共速（未穿出）时能量损失才最大】","src":"物一轮164.子弹打木块模型_笔记","note":"视频|00:08-02:17","orig":"（知识）子弹穿出：mv₀=mv₁+Mv₂，能量关系 ½mv₀²=½mv₁²+½Mv₂²+Q；此时相对位移 Δs 即木块长度","link":""},{"id":"phy1017","t":"动量·子弹打木块位移关系","s":"看到【比较子弹对地位移、木块位移与相对位移的大小关系】","c":"想到【用能量本质判断：摩擦力对子弹做功 fx_{1}、生热 f$\\Delta$x、对木块做功 fx_{2}，三者排序恒为 x_{1}>$\\Delta$x>x_{2}】；警惕【仅凭直觉看图判断，忽略位移关系背后的能量本质】","src":"物一轮164.子弹打木块模型_笔记","note":"视频|02:17-11:25","orig":"（例）比较子弹位移 x₁、木块位移 x₂ 与相对位移 Δx：W₁=fx₁>Q=fΔx>W₂=fx₂，故 x₁>Δx>x₂（答案 A）","link":""},{"id":"phy1018","t":"动量·板块模型（子弹打木块变形）","s":"看到【板块两物体初速度等大反向的动量问题】","c":"想到【板块本质是子弹打木块的变形：先列动量守恒求共速（方向由质量大小决定），摩擦生热 Q=$\\mu$mg$\\Delta$x，求时间用动量定理 $\\mu$mgt=$\\Delta$p】；警惕【初速度方向设定影响各量符号；冲量按动量变化计算而非直接写 mv_{0}】","src":"物一轮164.子弹打木块模型_笔记","note":"视频|11:25","orig":"（例）板块以等大反向 v₀ 运动：v共=(M−m)/(M+m)·v₀；最大位移 v₀²/2μg 与质量比无关；冲量 I=2Mm/(M+m)·v₀；时间由 μmgt=Δp 得 t=2Mv₀/[μ(M+m)g]（答案 D）","link":""},{"id":"phy1019","t":"动量·摩擦生热通用结论","s":"看到【求滑动摩擦产生的热量】","c":"想到【一律用 Q=f·$\\Delta$x，$\\Delta$x 为相对路程/相对位移】；警惕【误将对地位移代入热量计算】","src":"物一轮164.子弹打木块模型_笔记","note":"视频|00:08","orig":"（知识）摩擦热 Q 恒等于摩擦力乘相对位移，与对地位移无关，Q=f·Δx 适用于所有情况","link":""},{"id":"phy1020","t":"静电场·复习主线","s":"看到【静电场一轮复习的主线梳理】","c":"想到【以场的「力学特征」为主线：先掌握场强、电场线等描述工具，再进入叠加与综合应用】；警惕【电场线与场强不能割裂学习，前者是后者的可视化】","src":"物一轮165.【课前必看】本讲听课建议_笔记","note":"视频|00:50-01:04","orig":"（知识）静电场力学特征重点研究电场强度、电场线等描述电场力学性质的物理量，电场线是电场强度的可视化表达","link":""},{"id":"phy1021","t":"静电场·考情与命题趋势","s":"看到【静电场模块的高考考情分析】","c":"想到【主攻场强与电势的叠加计算和空间立体场强矢量合成，解答题按电磁场综合压轴标准准备】；警惕【电路部分高考以实验为主，计算比重小，复习精力需相应分配】","src":"物一轮165.【课前必看】本讲听课建议_笔记","note":"视频|01:04-05:50","orig":"（知识）静电场模块占高考卷面 40% 以上分值：选择题高频考场强与电势叠加计算（如 24 贵州/河北、23 重庆/湖南），解答题常以电磁场综合问题压轴，典型题型为空间立体图形中的场强计算","link":""},{"id":"phy1022","t":"静电场·难度分层学法","s":"看到【静电场复习内容按难度分层（概念$\\to$场强$\\to$连续带电体叠加）】","c":"想到【按先重建概念、再练场强与电场线、最后攻微元法与对称性的立体场强叠加的顺序推进，根据自身掌握灵活调整】；警惕【连续带电体叠加属高阶空间思维内容，基础不牢时勿直接跳级刷难题】","src":"物一轮165.【课前必看】本讲听课建议_笔记","note":"视频|03:10-05:50","orig":"（知识）内容分层：电荷守恒定律（★）、电场强度与电场线（★★）、连续带电体场强叠加（★★★★，涉及微元法/对称性分析等物理思想方法）；零基础走 1-2 星路径，中等基础走 2-4 星路径","link":""},{"id":"phy1023","t":"静电场·元电荷","s":"看到【判断某电荷量数值是否可能存在】","c":"想到【验证是否为 1.6$\\times$10^{-19}C 的整数倍：6.4$\\times$10^{-19}C（4 倍）可能，2.4$\\times$10^{-19}C（1.5 倍）不可能】；警惕【元电荷是电荷量的大小而非客观存在的粒子，无正负之分，高中阶段它是最小电荷量】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|00:40-05:00","orig":"（知识）元电荷 e=1.6×10⁻¹⁹C，是一个质子或电子所带电荷量的大小；所有带电体电量都是元电荷的整数倍 Q=ne","link":""},{"id":"phy1024","t":"静电场·电荷量离散性","s":"看到【概念判断题问带电体电量是否连续】","c":"想到【电荷量离散不连续，对应元电荷整数倍；发现者为密立根（油滴实验）】；警惕【「电荷量可任意取值」的说法错误】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|05:00-07:35","orig":"（知识）带电体电荷量具有离散性（不连续），必须是 1.6×10⁻¹⁹C 的整数倍；密立根油滴实验测出该最小单位","link":""},{"id":"phy1025","t":"静电场·点电荷","s":"看到【判断带电体能否视为点电荷】","c":"想到【类比质点模型：忽略形状大小与电荷分布影响即可视为点电荷，常用于研究受力与运动】；警惕【点电荷是理想化模型，与场源电荷（激发电场的源头）不是同一概念，场源电荷对电量体积无特殊限制】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|07:35-09:06","orig":"（知识）当带电体的形状、大小及电荷分布对作用力的影响可忽略时，可视为点电荷；理解方法类比质点","link":""},{"id":"phy1026","t":"静电场·场源电荷与试探电荷","s":"看到【区分场源电荷与试探电荷的作用】","c":"想到【场的性质由场源电荷唯一决定，试探电荷只是「探测器」】；警惕【误认为场强随试探电荷改变——不放试探电荷场依然存在】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|09:06-11:24","orig":"（知识）场源电荷激发电场；试探电荷（检验电荷）仅用于研究电场各点性质，要求电量足够小、体积足够小，电场性质与试探电荷无关","link":""},{"id":"phy1027","t":"静电场·摩擦起电","s":"看到【摩擦起电的带电性质判断】","c":"想到【本质是电子转移，两物体带等量异种电荷（如 +3e 与 −3e）】；警惕【同一玻璃棒与不同材料摩擦可能带正电也可能带负电，取决于材料组合】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|11:51-16:33","orig":"（知识）因原子核对核外电子束缚能力不同导致电子转移：丝绸摩擦玻璃棒带正电，毛皮摩擦橡胶棒带负电；两物体必带等量异种电荷，转移电量只能是 e 的整数倍","link":""},{"id":"phy1028","t":"静电场·接触起电","s":"看到【两个相同导体接触后分配电荷】","c":"想到【先中和再平分：先求净电荷代数和再均分；金属中只有电子能自由移动】；警惕【电子移动方向与「正电荷移动」方向相反，需判断谁得谁失电子】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|16:33-25:07","orig":"（例）+2C 与中性球接触各带 +1C；−2C 与中性球接触各带 −1C；+2C 与 −4C 接触各带 −1C，3C 电子从 −4C 球转移到 +2C 球","link":""},{"id":"phy1029","t":"静电场·感应起电","s":"看到【带电体靠近导体引起两端带电的判断】","c":"想到【近端吸异号、远端聚同号；先分开导体再移走外电荷才能把电荷「冻结」保留】；警惕【顺序颠倒（先移走外电荷）则电荷复原、分开后不带电；接地不改变最近端电性，最远端变为大地】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|25:07-31:56","orig":"（知识）外部电荷靠近导体引起电荷重新分布：近端感应异种电荷、远端同种电荷；整体电荷守恒，转移仍是电子整数倍","link":""},{"id":"phy1030","t":"静电场·电荷守恒定律","s":"看到【分析起电过程中系统总电量】","c":"想到【一切起电本质都是电荷转移或重新分布，系统总电量不变】；警惕【三种起电方式都体现电量离散性（电子转移整数倍）】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|31:56-32:34","orig":"（知识）电荷既不会创生也不会消灭，只能从一个物体转移到另一物体（摩擦、接触起电）或从物体一部分转移到另一部分（感应起电），总量保持不变","link":""},{"id":"phy1031","t":"静电场·元电荷概念例题","s":"看到【物体带电后求电子数目的增减】","c":"想到【由 Q=Ne 求电子数，带负电是得到电子、带正电是失去电子】；警惕【误认为质子移动导致带电——实际只有电子能自由移动】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|32:34-35:59","orig":"（例）判定元电荷概念：电子/质子是实物粒子而元电荷是电量最小单位；物体带 −1.6×10⁻¹⁰C 由 Q=Ne 得 N=10⁹ 且是得到电子（答案 C）","link":""},{"id":"phy1032","t":"静电场·感应起电例题","s":"看到【感应起电中移走外电荷与分开导体的先后顺序】","c":"想到【先分开后移走则电荷保留，先移走则中和不带电；无论哪端接地，最近端始终聚集异种电荷】；警惕【接地后最远端电荷被排斥入大地，而非消失】","src":"物一轮166.电荷守恒定律_笔记","note":"视频|35:59","orig":"（例）带正电玻璃棒 C 靠近导体 AB：负电荷聚于 A 端（最近端）、正电荷聚于 B 端；先分开后移走 C 电荷保留（答案 C）","link":""},{"id":"phy1033","t":"静电场·电场概念","s":"看到【两电荷不接触却有力的作用】","c":"想到【通过电场传递的「非接触力」：每个电荷各自激发电场并独立作用于对方，叠加时分别考虑】；警惕【电场是客观存在的物质，不是虚构的辅助概念】","src":"物一轮167.电场强度_笔记","note":"视频|00:18-02:55","orig":"（知识）电场看不见摸不着但客观存在，是传递电荷间相互作用的媒介：电荷 A 激发电场 A 作用于 B，电荷 B 激发电场 B 作用于 A，两个电场相互独立","link":""},{"id":"phy1034","t":"静电场·场强定义式","s":"看到【电场强度定义式 E=F/q 的理解判断】","c":"想到【E 只由场源决定，定义式是「测量」而非「决定」关系】；警惕【不能说 E∝F、E∝1/q；q 只取绝对值不带正负号】","src":"物一轮167.电场强度_笔记","note":"视频|02:55-05:35","orig":"（知识）E=F/q，q 为试探电荷电量且仅取绝对值；场强由场源电荷决定，与试探电荷无关，即使不放试探电荷场强依然存在","link":""},{"id":"phy1035","t":"静电场·点电荷场强决定式","s":"看到【点电荷周围场强大小的计算或比较】","c":"想到【用决定式 E=kQ/r^{2} 计算各场源在某点的场强】；警惕【公式只适用点电荷场源，r 是到点电荷的距离】","src":"物一轮167.电场强度_笔记","note":"视频|05:35-06:49","orig":"（知识）E=kQ/r²，Q 为场源电荷量（仅取绝对值），仅适用于点电荷或可视为点电荷的场源；场强与 Q 成正比、与 r² 成反比","link":""},{"id":"phy1036","t":"静电场·场强方向判断","s":"看到【判断某点场强方向或多个场强矢量合成】","c":"想到【正出负入定方向，再按平行四边形（正交分解）矢量合成】；警惕【电场线方向不等于试探电荷运动方向】","src":"物一轮167.电场强度_笔记","note":"视频|06:49-13:06","orig":"（知识）方向判定三法：与正电荷受力同向（与负电荷受力反向）；正场源向外辐射、负场源向内汇聚；沿电场线切线方向；场强是矢量遵循平行四边形叠加法则","link":""},{"id":"phy1037","t":"静电场·F-q 图像","s":"看到【F-q 图像求场强大小之比】","c":"想到【E=F/q 为线性关系，图线斜率表示场强，斜率比即场强比】；警惕【只有过原点的直线才能直接比斜率】","src":"物一轮167.电场强度_笔记","note":"视频|13:06-16:44","orig":"（例）F-q 图中两图线斜率比 ka:kb=4:1，由 E=F/q 知斜率即场强，场强比 4:1（答案 D）","link":""},{"id":"phy1038","t":"静电场·多电荷合场强为零","s":"看到【某点合场强为零（试探电荷静止/受力平衡）的多电荷组合判断】","c":"想到【矢量式 E_{1}+E_{2}+E_{3}=0 要求大小方向同时满足：先定性排除全同号电荷，再建坐标系正交分解，验证 x、y 分量分别平衡】；警惕【场强方向由电荷正负决定（正出负入），几何距离关系勿用错三角函数（斜边邻边混淆）】","src":"物一轮167.电场强度_笔记","note":"视频|16:44-29:02","orig":"（例）三个场源电荷使 P 点合场强为零：同号组合场强无法抵消先排除；对 D 选项正交分解验证水平 E₂x=E₃x、竖直 E₁+E₃y=E₂y 均平衡","link":""},{"id":"phy1039","t":"静电场·限定方向求电荷量比","s":"看到【合场强方向被限定（如沿切线）求两电荷量之比】","c":"想到【由几何关系定各分场强方向，利用垂直/角度关系建矢量三角形，再用 E=kQ/r^{2} 联立求比值；电性未定时分类讨论】；警惕【先用电性排除不可能组合（如同号无法合成指定方向），另一种电性组合结果可能相同】","src":"物一轮167.电场强度_笔记","note":"视频|29:02-36:50","orig":"（例）圆上 A、B 电荷在 C 点产生沿切线方向的合场强：同种电荷无法合成切线方向须为异种；EA⊥EB 且夹角 60° 得 EA=√3EB，联立 E=kQ/r² 解得 qA/qB=√3/3（答案 B）","link":""},{"id":"phy1040","t":"静电场·两异号电荷场强零点","s":"看到【两电荷连线上某点场强为零，反推另一电荷位置】","c":"想到【先用物理意义排除不可能区间（场强同向叠加区、靠近大电荷区），再由 kq_{1}/r_{1}^{2}=kq_{2}/r_{2}^{2} 解距离】；警惕【场强为零点必在电量小的电荷一侧，距离比按电量的平方根计算】","src":"物一轮167.电场强度_笔记","note":"视频|36:50","orig":"（例）负电荷 q₁ 在原点、正电荷 q₂=8q₁ 在 x 轴上，x₀ 处合场强为零：排除 q₂ 在右侧（场强同向）与两电荷之间（E₂>E₁），由 1/x₀²=8/(x+x₀)² 解得 x=(2√2−1)x₀（答案 B）","link":""},{"id":"phy1041","t":"静电场·电场线本质","s":"看到【判断电场线是否真实存在或读电场线信息】","c":"想到【区分电场（客观存在）与电场线（假想工具）；看疏密定大小、看切线定方向】；警惕【不能把电场线当作真实存在的线】","src":"物一轮168.电场线_笔记","note":"视频|00:16-02:45","orig":"（知识）电场线是为形象描述电场而假想的线，实际不存在，但电场客观存在；疏密程度反映场强大小，切线方向表示场强方向","link":""},{"id":"phy1042","t":"静电场·点电荷电场线","s":"看到【正/负点电荷的电场线分布判断】","c":"想到【正电荷发散、负电荷汇聚，与「正出负入」场强方向规则对应】；警惕【同一点电荷电场线疏密不同处场强不同，远处稀疏场强小】","src":"物一轮168.电场线_笔记","note":"视频|02:45-03:43","orig":"（知识）正点电荷电场线呈辐射状向外发散，负点电荷呈汇聚状向内收敛，与场强叠加原理一致","link":""},{"id":"phy1043","t":"静电场·等量同种电荷电场","s":"看到【等量同种电荷连线或中垂线上场强分布】","c":"想到【连线中点场强为零；中垂线场强先增后减有极值，非单调变化】；警惕【误认为中垂线上场强单调递减或中点场强最大】","src":"物一轮168.电场线_笔记","note":"视频|03:43-14:04","orig":"（知识）等量同种电荷：连线中点场强为零（两侧等大反向抵消）；中垂线上场强从中点向无穷远先增后减、存在最大值；电场线分布上下左右对称，对称点场强大小相等方向不同","link":""},{"id":"phy1044","t":"静电场·等量异种电荷电场","s":"看到【等量异种电荷连线或中垂线上场强分布】","c":"想到【连线上中点场强最小但不为零；中垂线场强方向统一且单调递减；对称点大小方向都相同】；警惕【与等量同种电荷规律区分记忆：中点是否为零、中垂线是否单调正好相反】","src":"物一轮168.电场线_笔记","note":"视频|03:43-14:04","orig":"（知识）等量异种电荷：连线上场强方向始终指向负电荷、中点场强最小（电场线最稀疏）；中垂线上场强方向水平指向负电荷一侧，向无穷远单调递减；对称点场强大小方向均相同","link":""},{"id":"phy1045","t":"静电场·匀强电场","s":"看到【匀强电场的电场线特征或受力分析】","c":"想到【等间距平行线对应场强处处相同，粒子受恒力做匀变速运动】；警惕【平行板电容器内部（忽略边缘）可视为匀强电场】","src":"物一轮168.电场线_笔记","note":"视频|14:04-14:43","orig":"（知识）匀强电场电场线为等间距平行直线：方向相同（平行）、大小相同（等间距），带电粒子在其中受力均匀","link":""},{"id":"phy1046","t":"静电场·场强相同的判断","s":"看到【选择题判断两点「场强相同」】","c":"想到【场强是矢量，必须大小和方向都相同才叫相同，双重判断】；警惕【只比大小漏方向是选择题常见陷阱】","src":"物一轮168.电场线_笔记","note":"视频|14:43-16:47","orig":"（例）判断哪些点场强相同：A 辐射状大小同方向不同；B 对称点大小同方向相反；C 异种电荷中垂线对称点大小方向均相同（答案 C）","link":""},{"id":"phy1047","t":"静电场·对称性分析法","s":"看到【等量电荷电场中比较对称位置点的场强】","c":"想到【优先用对称性分析代替复杂矢量叠加：对称点场强大小相等，方向由切线方向逐点核对】；警惕【对称点方向可能相同也可能相反（如同种电荷连线中点两侧），不能一概而论】","src":"物一轮168.电场线_笔记","note":"视频|16:47-20:55","orig":"（例）等量异号电荷电场中比较 M、N、P 各点场强：M、P 疏密相同（大小相等），N、P 大小相同且方向一致（答案 C）","link":""},{"id":"phy1048","t":"静电场·电场线三特性","s":"看到【判断电场线能否相交、相切或闭合】","c":"想到【三不特性：不相交源于场强方向唯一性、不相切源于场强不能无限大、不闭合源于静电场特性】；警惕【理解物理本质而非死记结论，定义式与决定式中电荷量均取绝对值】","src":"物一轮168.电场线_笔记","note":"视频|20:55","orig":"（知识）电场线不相交（相交则一点有两个场强方向）、不相切（相切处场强无穷大不合理）、不闭合（静电场特性）；起于正电荷/无穷远，止于负电荷/无穷远","link":""},{"id":"phy1049","t":"静电场·连续带电体场强叠加","s":"看到【均匀带电细杆、圆环、圆盘、球壳等连续带电体求场强】","c":"想到【连续带电体不能直接套用点电荷公式 kQ/r^{2}，需微元分割+对称性分析求场强】；警惕【把连续带电体当成点电荷直接代入公式】","src":"物一轮169.连续带电体的场强叠加问题_笔记","note":"视频|00:38-01:24","orig":"（知识）连续带电体指电荷连续分布在物体上的带电体，常见类型：均匀带电细杆、圆环（线分布），圆盘、球壳（面分布），由无限多个点电荷组成。","link":""},{"id":"phy1050","t":"静电场·连续带电体场强叠加","s":"看到【连续带电体需要计算场强/电场叠加】","c":"想到【微元法：无限分割为点电荷元，先写单个微元的场，再对称求和或积分】；警惕【分割后忘记取极限求和，只算一份微元】","src":"物一轮169.连续带电体的场强叠加问题_笔记","note":"视频|01:27-01:40","orig":"（知识）微元法原理：将带电体分成n份，每份电量q=Q/n，当n→∞时每个微元可视为点电荷，计算每个点电荷的电场后积分求和。","link":""},{"id":"phy1051","t":"静电场·对称法求场强","s":"看到【均匀带电圆环轴线上一点求场强】","c":"想到【对称性分析优先于直接计算：对称微元的垂直分量抵消，只叠加轴向分量，结果分母为 ($x^2$+R^{2})^(3/2) 形式】；警惕【漏掉余弦投影，直接把微元场强代数相加】","src":"物一轮169.连续带电体的场强叠加问题_笔记","note":"视频|01:40-09:28","orig":"（知识）均匀带电圆环轴线上场强：利用对称点对，垂直分量相互抵消，只叠加同向分量，最终 E=kQx/(x²+R²)^(3/2)。","link":""},{"id":"phy1052","t":"静电场·带电体截取与对称反推","s":"看到【带电细杆/带电体截去一部分后求剩余部分场强】","c":"想到【整体=各部分之和：先确认某点场强由哪部分产生，再利用对称关系用整体场强减去已知部分反推】；警惕【场强方向的正负号处理，题目只求大小时别漏矢量方向判断】","src":"物一轮169.连续带电体的场强叠加问题_笔记","note":"视频|09:28-","orig":"（例）均匀带电细杆，已知完整杆在P₁处场强E₁（仅由右半部分产生）、整体在P₂处场强E₂=E左+E右，截去右半边后P₂场强 E′=E₂-E₁。","link":""},{"id":"phy1053","t":"静电场·点电荷与圆盘组合","s":"看到【点电荷与圆盘组合，某点合场强为零】","c":"想到【以合场强为零的点列方程：点电荷场=带电体场，再借对称点把带电体场强转移到待求点】；警惕【圆盘不是点电荷，其场强不可直接用 kQ/r^{2}，只能通过对称性转化】","src":"物一轮169.连续带电体的场强叠加问题_笔记","note":"视频|09:28-","orig":"（例）点电荷q与带电圆盘系统，b、d两点关于圆盘对称，b点合场强为零给出 kq/R²=E圆盘→b，由此求出d点合场强。","link":""},{"id":"phy1054","t":"静电场·补全法求不完整带电体场强","s":"看到【不完整带电体（半球面等）+某点场强为零的条件】","c":"想到【补全构造对称系统：利用「均匀球壳内部场强为零」逆向求出部分带电体的场，再矢量叠加】；警惕【混淆面电荷q与点电荷Q的贡献；忽略方向判定导致符号错误】","src":"物一轮169.连续带电体的场强叠加问题_笔记","note":"视频|09:28-","orig":"（例）均匀带电半球面与点电荷Q组合，P点场强为零；补全另一半球面构成完整球壳，利用「封闭带电球壳内部场强处处为零」得 E半球面→M=kQ/4R²，最终 M点合场强 3kQ/4R²。","link":""},{"id":"phy1055","t":"静电场·场强叠加解题策略","s":"看到【题干出现「某点场强为零」等看似多余的条件】","c":"想到【该条件往往是建立方程的突破口：由已知点场强反推场源贡献或待求场强】；警惕【忽略隐含的对称性提示，硬算积分浪费时间】","src":"物一轮169.连续带电体的场强叠加问题_笔记","note":"视频|09:28-","orig":"（知识）方法总结：对不完整带电体通过补全构造对称系统；特别关注题目中「看似无关」的条件（如封闭球壳条件），通过已知点场强反推未知参数。","link":""},{"id":"phy1056","t":"静电场·能量特征总览","s":"看到【求电荷在电场中移动时的做功或电势能变化】","c":"想到【静电力是保守力，做功只看初末位置：W=qU 或 W=-$\\Delta$Ep，与路径无关】；警惕【混淆「做功多」与「电势能大」的因果关系】","src":"物一轮170.【课前必看】本讲听课建议_笔记","note":"视频|00:33-03:49","orig":"（知识）静电力做功与路径无关，仅与初末位置有关；W_AB=E_pA-E_pB，电势能变化 ΔEp=-W；电势 φ=Ep/q，电势差 U=φA-φB。","link":""},{"id":"phy1057","t":"静电场·等势面与电场线","s":"看到【给出等势面分布图判断场强或电势】","c":"想到【电场线与等势面处处垂直，可相互推导；等势面疏密反映场强大小，沿电场线电势降低】；警惕【等势面密$\\neq$电势高，只说明场强大】","src":"物一轮170.【课前必看】本讲听课建议_笔记","note":"视频|00:33-03:49","orig":"（知识）等势面是电势相等点构成的面，与电场线垂直；等差等势面越密处场强越大；沿电场线方向电势降低。","link":""},{"id":"phy1058","t":"静电场·场强与电势关系","s":"看到【非匀强电场中通过 $\\varphi$-x 图像求场强】","c":"想到【图像切线斜率的绝对值表示场强大小（E=-d$\\varphi$/dx），斜率为零处场强为零】；警惕【U=Ed 只适用于匀强电场，非匀强场中误用】","src":"物一轮170.【课前必看】本讲听课建议_笔记","note":"视频|00:33-03:49","orig":"（知识）匀强电场中 E=U/d；非匀强电场中 E=-dφ/dr，通过 φ-x 图像斜率分析场强变化。","link":""},{"id":"phy1059","t":"静电场·力的概念辨析","s":"看到【辨析库仑力、静电力、电场力的适用范围】","c":"想到【电场力⊃静电力⊃库仑力：库仑力仅存在于点电荷间，静电力仅存在于静电场中】；警惕【匀强电场中的力是静电力而非库仑力】","src":"物一轮171.静电力做功与电势能_笔记","note":"视频|01:11-04:52","orig":"（知识）库仑力是两个点电荷之间的相互作用力 F=kq₁q₂/r²；包含关系：电场力⊃静电力⊃库仑力。匀强电场中的力是静电力但不是库仑力，涡旋电场中的力是电场力但不是静电力。","link":""},{"id":"phy1060","t":"静电场·静电力做功特点","s":"看到【电荷沿曲线或折线在静电场中移动求电场力做功】","c":"想到【静电力做功与路径无关，只取决于初末位置，直接用 W=qU 计算，不必沿实际路径积分】；警惕【误沿复杂路径分段求和浪费时间】","src":"物一轮171.静电力做功与电势能_笔记","note":"视频|04:54-10:14","orig":"（知识）静电力做功与路径无关，只与初末位置有关，类似重力做功；匀强电场中直线、折线、曲线三种路径做功相同。","link":""},{"id":"phy1061","t":"静电场·匀强电场做功计算","s":"看到【匀强电场中求电场力做功】","c":"想到【W=qEd，d取沿电场线方向的投影距离；功的正负由电场力与位移夹角判断】；警惕【把d当成两点间直线距离；负电荷受力与场强反向，同位移下功的正负会反转】","src":"物一轮171.静电力做功与电势能_笔记","note":"视频|10:14-13:06","orig":"（知识）W=qEd：q不带正负号仅表电荷量大小，正负功由力与位移夹角判断（锐角正功、钝角负功）；d是沿电场线方向的位移分量，不是两点间直线距离。","link":""},{"id":"phy1062","t":"静电场·电势能性质","s":"看到【比较不同电荷在某点电势能的大小或正负】","c":"想到【电势能是标量，正负直接参与大小比较；其数值依赖零势能面的选取】；警惕【换零势能面后各点电势能数值改变，但差值不变】","src":"物一轮171.静电力做功与电势能_笔记","note":"视频|13:49-15:44","orig":"（知识）电势能三性：相对性（大小由零势能面位置决定，默认地面或无穷远为零势能面）、标量性（可正可负，正负表示大小关系，如5J>-8J）、系统性（电场和电荷共有）。","link":""},{"id":"phy1063","t":"静电场·功能关系","s":"看到【电场力做功与电势能变化的相互判断】","c":"想到【W=-$\\Delta$Ep：做正功电势能减小，克服电场力做功（负功）电势能增加】；警惕【「克服电场力做功」意味着电场力做负功；某点电势能=移至零势能面过程电场力做的功】","src":"物一轮171.静电力做功与电势能_笔记","note":"视频|15:44-18:23","orig":"（知识）W=-ΔEp：电场力做正功电势能降低，做负功电势能升高；电荷在某点的电势能等于将其移到零势能位置时电场力做的功 W_A0=E_pA。","link":""},{"id":"phy1064","t":"静电场·点电荷电场中的电势能","s":"看到【求点电荷电场中某电荷的电势能】","c":"想到【Ep=kQq/r，以无穷远为零势能面，Q、q带正负号代入】；警惕【分母是 r 而非库仑力公式的 r^{2}；公式仅适用于点电荷场源】","src":"物一轮171.静电力做功与电势能_笔记","note":"视频|18:23-21:10","orig":"（知识）点电荷电场中 Ep=kQq/r（以无穷远为零势能面），Q、q需带正负号运算，仅适用于点电荷电场，分母为r。","link":""},{"id":"phy1065","t":"静电场·做功计算例题","s":"看到【题目中某点位置未明确说明是中点】","c":"想到【不能默认取l/2，设各段长度分别计算再求和】；警惕【审题陷阱：未言明中点就是中点；正负电荷受力方向相反，需分别判断功的正负】","src":"物一轮171.静电力做功与电势能_笔记","note":"视频|21:10-25:27","orig":"（例）匀强电场中杆两端异号电荷，o点未说明是中点，设l₁+l₂=l，分别求正负电荷做功后相加，答案 qEl。","link":""},{"id":"phy1066","t":"静电场·功能关系辨析","s":"看到【判断「移到无穷远做功多少与电势能大小」类选项】","c":"想到【从功能关系 W=-$\\Delta$Ep 原理出发推导，勿死记结论：克服做功（负功）越多电势能越大，做正功越多电势能越小】；警惕【混淆「某点$\\to$无穷远」与「无穷远$\\to$某点」两个方向的做功关系】","src":"物一轮171.静电力做功与电势能_笔记","note":"视频|25:27-","orig":"（例）判断「某点→无穷远做正功越多电势能越大」「克服做功越多电势能越大」等选项，从 W=-ΔEp 推导，答案AC。","link":""},{"id":"phy1067","t":"静电场·电势的定义式","s":"看到【比较电势能大的两点电势高低】","c":"想到【电势计算中q必须带正负号：正电荷处 Ep 与 $\\varphi$ 同向变化，负电荷处反向变化，故电势能大不代表电势大】；警惕【与 E=F/q 混淆，场强计算中q不带号】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|00:27-03:31","orig":"（知识）电势定义式 φ=Ep/q（q带正负号），类比场强定义式 E=F/q（q不带正负号）；正电荷 Ep大则φ大，负电荷 Ep大则φ小。","link":""},{"id":"phy1068","t":"静电场·电势的属性","s":"看到【换用不同试探电荷问某点电势是否改变】","c":"想到【电势由场源决定，与试探电荷有无、正负、大小均无关】；警惕【把电势当成试探电荷的属性；点电荷电势分母是r，Q要带符号】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|03:31-05:44","orig":"（知识）电势是描述电场能量特征的物理量，仅由场源电荷决定，与试探电荷无关；点电荷电势决定式 φ=kQ/r（Q带正负号）。","link":""},{"id":"phy1069","t":"静电场·沿电场线的电势与场强","s":"看到【沿电场线方向比较各点场强或电势】","c":"想到【沿电场线电势必降低；场强看电场线疏密，与电势高低无必然联系】；警惕【三个误区：沿电场线场强必降（错）、场强大处电势必大（错）、电势能大处电势必大（错，取决于试探电荷正负）】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|05:44-17:38","orig":"（知识）沿电场线方向电势必降低（与场源正负无关）；场强不一定降低，取决于电场线疏密。口诀「沿电场线方向电势降，场强看疏密不相干」。","link":""},{"id":"phy1070","t":"静电场·电势的标量叠加","s":"看到【多个点电荷共同作用下求某点电势】","c":"想到【电势标量代数相加（各电荷带正负号），与场强的矢量平行四边形合成区分开】；警惕【按矢量合成处理电势；漏掉负电荷贡献的负号】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|17:38-18:37","orig":"（知识）电势是标量，叠加遵循代数运算法则直接相加减，无需考虑方向；φ总=∑kQi/ri，Qi带正负号。","link":""},{"id":"phy1071","t":"静电场·等量电荷连线中点与中垂线","s":"看到【等量同种或异种电荷连线中点、中垂线上场强与电势的判断】","c":"想到【场强为零处电势不一定为零（同种电荷中点），电势为零处场强不一定为零（异种电荷中点及中垂线）】；警惕【由场强为零推电势为零、或反之，两者无必然联系】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|18:37-26:05","orig":"（例）等量同种正电荷连线中点：合场强为零（矢量抵消）而电势为2kq/r₁≠0；等量异种电荷中点：场强2kq/r₁²≠0而电势为零，且中垂线上电势处处为零。","link":""},{"id":"phy1072","t":"静电场·电势差的定义式","s":"看到【求电场中两点电势差】","c":"想到【U_AB=$\\varphi$A-$\\varphi$B（初减末），与电势变化量互为相反数；U_AB>0表示沿A到B电势降低】；警惕【把电势差当「末减初」处理，符号弄反】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|37:58-39:34","orig":"（知识）U_AB=φA-φB，初位置电势减末位置电势，是高中唯一用「初减末」定义的物理量；Δφ_AB=φB-φA，故 U_AB=-Δφ_AB。","link":""},{"id":"phy1073","t":"静电场·电势差与做功","s":"看到【已知电场力做功和电荷量求电势差或电势】","c":"想到【U=W/q 适用于任意电场，W、q 均带正负号代入；再结合 U=$\\varphi$A-$\\varphi$B 求某点电势】；警惕【「克服电场力做功」要记为负功；U_AB=-U_BA 方向别搞反】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|39:34-42:07","orig":"（知识）U_AB=W_AB/q，由 W_AB=-ΔEp=q(φA-φB) 推导得出，适用于任意电场，计算时q需带正负号。","link":""},{"id":"phy1074","t":"静电场·匀强电场U=Ed","s":"看到【匀强电场中由场强求两点电压，或由电压求场强】","c":"想到【U=Ed，d 必须取沿电场线方向的距离分量】；警惕【在非匀强电场中使用该式；d 误用两点间直线距离】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|42:07-46:09","orig":"（知识）U=Ed 仅适用于匀强电场，d为沿电场线方向的距离；由通用式 W=qU 与匀强场 W=qEd 联立得到。","link":""},{"id":"phy1075","t":"静电场·电势差的绝对性","s":"看到【更换零势能面（参考点）后判断电势或电势差的变化】","c":"想到【电势具有相对性（随零势能面变），电势差具有绝对性（两点差值恒定）】；警惕【误以为换零势能面后电势差也变】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|47:14-53:12","orig":"（例）匀强电场中分别以c、b为零势能面，算得各点电势不同但 U_AB=1V 保持不变，验证电势差与零势能面选择无关。","link":""},{"id":"phy1076","t":"静电场·等势面性质","s":"看到【沿等势面移动电荷或判断等势面与电场线关系】","c":"想到【等势面上移动电荷 W=qU=0；电场线$\\perp$等势面；等差等势面密处场强大】；警惕【等势面上移动电荷「不做功」但电荷可能受其他力做功】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|01:01:27-01:04:20","orig":"（知识）沿等势面移动电荷电场力做功为零；电场线与等势面处处垂直；等差等势面越密集处场强越大；点电荷等势面为同心球面（内密外疏），匀强电场为等距平行平面。","link":""},{"id":"phy1077","t":"静电场·等势面图像判断","s":"看到【给等势面分布图比较两点的场强、电势或判断场源电性】","c":"想到【先看疏密定场强大小，再沿电场线方向定电势高低；由电势升降反推场源正负】；警惕【场强方向要看电场线指向，等势面密处方向未必指向低电势面最短处】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|01:11:13-01:12:42","orig":"（例）电场线/等势面分布图：由疏密比较场强（A稀疏则EA<EB），由等势面平移结合「沿电场线电势降低」比较电势；由电势变化方向反推场源电荷正负。","link":""},{"id":"phy1078","t":"静电场·等差等势面计算","s":"看到【等差等势面数间隔求电势差】","c":"想到【相邻等势面电势差相等，数间隔数乘以每级电势差即得总电势差】；警惕【负场源附近场强方向指向场源；等势面数目与电势差对应关系数错】","src":"物一轮172.电势、电势差、等势面_笔记","note":"视频|01:12:42-","orig":"（例）等差等势面分布：n点等势面更密得 EN>EM；p点与零势面间隔4个等势面得 U_PM=12V；m点场强方向实际指向负电荷。","link":""},{"id":"phy1079","t":"静电场·匀强电场E与U关系","s":"看到【匀强电场中求场强或某段距离上的电压】","c":"想到【E=U/d，d取沿电场线方向的距离分量；场强方向指向电势降低最快的方向】；警惕【d误用两点间直线距离而非沿场线分量】","src":"物一轮173.匀强电场中电场强度与电势差关系_笔记","note":"视频|00:42-01:06","orig":"（知识）匀强电场中 E=U/d 或 U=Ed，d为沿电场线方向的距离；场强在数值上等于单位距离上的电势差，方向指向电势降低最快的方向。","link":""},{"id":"phy1080","t":"静电场·推论一：同线段电压比=长度比","s":"看到【求同一线段上按比例分点的电势】","c":"想到【匀强电场中同一方向线段上电势均匀变化：电压比=长度比，中点电势为两端电势的平均值】；警惕【前提是两段共线且与电场线夹角相同，非共线线段不成立】","src":"物一轮173.匀强电场中电场强度与电势差关系_笔记","note":"视频|01:06-05:03","orig":"（知识）匀强电场中一条线段分成两段，电压差之比等于长度之比 U_AO/U_OB=l₁/l₂；前提是两段与电场线夹角相同。例：两端点电势3V和6V，中点电势必为4.5V。","link":""},{"id":"phy1081","t":"静电场·矩形顶点电势与场强","s":"看到【已知匀强电场中三个顶点电势求第四点电势或场强】","c":"想到【用推论定出等势点$\\to$连等势面$\\to$作垂线得电场线方向$\\to$E=U/d 计算场强】；警惕【d必须取沿电场线方向的距离，需借助几何关系求出】","src":"物一轮173.匀强电场中电场强度与电势差关系_笔记","note":"视频|05:03-06:39","orig":"（例）矩形三个顶点电势已知（10V、17V、26V），按电压比定等势点，连等势面作垂线定场强方向，E=U/d=9V/3.6cm=2.5V/cm。","link":""},{"id":"phy1082","t":"静电场·推论二：平行等长线段电压差相等","s":"看到【平行四边形或矩形中已知三点电势求第四点】","c":"想到【平行且等长的线段两端电压差相等，直接列 $\\varphi$A-$\\varphi$B=$\\varphi$C-$\\varphi$D 解出未知电势】；警惕【两线段必须平行且长度相等才可用】","src":"物一轮173.匀强电场中电场强度与电势差关系_笔记","note":"视频|06:39-09:07","orig":"（知识）匀强电场中平行且相等的两条线段，两端点电势差相等 U_AB=U_CD；因沿电场线方向分量 d∥ 相同。常用于矩形、平行四边形已知三顶点电势求第四顶点。","link":""},{"id":"phy1083","t":"静电场·等分法找电势求场强","s":"看到【需在匀强电场中定位等势面再求场强】","c":"想到【等分法四步：由 W=qU 求各点电势$\\to$按比例找等势点连等势面$\\to$作垂线定电场线方向$\\to$E=U/d 求场强】；警惕【电荷为负时算电势差要带负号；d通过几何关系（如勾股定理）求解】","src":"物一轮173.匀强电场中电场强度与电势差关系_笔记","note":"视频|09:07-19:32","orig":"（例）已知d点电势8V及两段做功，由 W=qU 求出a点-4V、b点0V，确定y轴为等势面、电场沿x轴正方向，E=8V/0.04m=200V/m。","link":""},{"id":"phy1084","t":"静电场·电子伏与做功计算","s":"看到【题目能量以 eV 为单位或涉及电子做功】","c":"想到【W=qU 直接计算；1 eV=1.6$\\times$10^{-19} J 换算；Ep=q$\\varphi$ 中电子的q为负】；警惕【电子带负电，电势高处电势能反而低】","src":"物一轮173.匀强电场中电场强度与电势差关系_笔记","note":"视频|19:32-","orig":"（知识）电场力做功 W=qU 与路径无关；1 eV=1.6×10⁻¹⁹ J，表示一个电子在1V电势差下的能量变化；Ep=qφ 电子带负电需注意符号。","link":""},{"id":"phy1085","t":"静电场·场强与电势的微分关系","s":"看到【非匀强电场中由电势变化求场强】","c":"想到【E=-d$\\varphi$/dx：场强等于$\\varphi$-x图像斜率的负值；场强与电势大小无直接关系（场强为零处电势可不为零）】；警惕【误用 U=Ed 于非匀强场；类比时混淆 a=$\\Delta$v/$\\Delta$t 中各量的角色】","src":"物一轮174.非匀强电场中电场强度与电势关系_笔记","note":"视频|00:16-08:05","orig":"（知识）非匀强电场中 Ex=-dφ/dx，场强是电势梯度的负值；Δφ=-∫E·dx；基于微元思想将非匀强电场局部视为匀强电场推导。类比 a=Δv/Δt。","link":""},{"id":"phy1086","t":"静电场·φ-x图像分析","s":"看到【$\\varphi$-x图像判断场源位置、性质或场强零点】","c":"想到【三步法：电势趋于±$\\infty$处定位场源电荷（正电荷对应+$\\infty$、负电荷对应-$\\infty$）$\\to$看斜率变化定场强分布$\\to$斜率为零处场强为零（可能为平衡点）】；警惕【斜率正负对应场强方向，别只看大小】","src":"物一轮174.非匀强电场中电场强度与电势关系_笔记","note":"视频|08:05-13:01","orig":"（例）φ-x图像：x→0时φ→-∞说明原点有负电荷；x=1处切线斜率为零对应场强零点；由斜率变化判断场强分布。","link":""},{"id":"phy1087","t":"静电场·E-x图像分析","s":"看到【E-x图像求两点电势差或比较电势高低】","c":"想到【图线与x轴围成的面积=电势差，正面积电势降、负面积电势升；面积对称抵消则两点电势相等】；警惕【忘记面积的正负号；E=0 处是电势极值点而非场强极值点】","src":"物一轮174.非匀强电场中电场强度与电势关系_笔记","note":"视频|13:01-15:51","orig":"（知识）E-x图像线下面积表示电势差Δφ，面积正负对应电势升降；正负x轴线下面积抵消时对应两点电势相等；图像与x轴交点处电势取极值。","link":""},{"id":"phy1088","t":"静电场·φ-x图像综合判断","s":"看到【$\\varphi$-x图像中判断电荷移动时的电势能、电场力变化】","c":"想到【先定场源与各点电势高低，再按「正电荷在电势能高$\\to$低即电场力做正功」规则判断：负电荷沿电势降低方向移动电势能减小；斜率绝对值变化反映电场力大小变化】；警惕【电荷正负不同，电势能随电势的变化方向相反】","src":"物一轮174.非匀强电场中电场强度与电势关系_笔记","note":"视频|15:51-19:24","orig":"（例）y轴φ→-∞判断原点有负电荷；x₂处斜率零点为正电荷平衡点；负电荷从x₁→x₂沿电势降低方向移动电势能减小；斜率绝对值减小则电场力减小。","link":""},{"id":"phy1089","t":"静电场·E-x图像与做功判断","s":"看到【E-x图像结合正电荷移动判断做功与电势能】","c":"想到【先由面积比较电势，再用 W=qU（q带符号）判断做功正负，进而得电势能增减】；警惕【混淆电势差正负与电势升降关系；忽略场强方向对做功正负的影响】","src":"物一轮174.非匀强电场中电场强度与电势关系_笔记","note":"视频|19:24-","orig":"（例）x₂→x₄线下面积为负得 φ₂<φ₄；x₁→x₃绝对值增大场强增大；正电荷x₁→x₄电场力做负功电势能增大。","link":""},{"id":"phy1090","t":"静电场·场强公式体系","s":"看到【选择求场强的公式】","c":"想到【分清定义式与决定式：E=F/q 普适，E=kQ/r^{2} 仅限点电荷场源】；警惕【把决定式用于非点电荷场源；把 W=qEd 用到非匀强场】","src":"物一轮175.必看：静电场概念梳理_笔记","note":"视频|00:33-02:18","orig":"（知识）定义式 E=F/q 适用于所有电场，计算时q不带正负号；决定式 E=kQ/r² 仅要求场源为点电荷；匀强场做功 W=qEd 仅适用匀强电场。","link":""},{"id":"phy1091","t":"静电场·电势公式体系","s":"看到【区分电势与场强的公式并计算】","c":"想到【$\\varphi$=kQ/r 与 E=kQ/r^{2} 只差分母一次方；标量公式（$\\varphi$、Ep、W）中电荷量带正负号】；警惕【把电势分母写成r^{2}；电势能计算漏带负电荷的负号】","src":"物一轮175.必看：静电场概念梳理_笔记","note":"视频|02:18-03:19","orig":"（知识）定义式 φ=Ep/q 或 Ep=qφ，电势能计算需带电荷正负号；决定式 φ=kQ/r（对比场强分母为r²）；点电荷场中 Ep=kQq/r。","link":""},{"id":"phy1092","t":"静电场·功能关系网络","s":"看到【电场中功、电势能、电势差之间的换算】","c":"想到【功能链：W=qU=-$\\Delta$Ep，U=W/q 沟通功与电势，匀强场再加 U=Ed】；警惕【公式中q的正负号必须代入；混淆电场力做功与电势能变化（差一个负号）】","src":"物一轮175.必看：静电场概念梳理_笔记","note":"视频|03:19-05:40","orig":"（知识）电场力做功 W=-ΔEp；电势差 U=W/q 是连接功与电势的桥梁；匀强场中 U=Ed。","link":""},{"id":"phy1093","t":"静电场·电场线与等势面","s":"看到【由等势面分布推断场强方向或大小】","c":"想到【三关系：垂直、同密同疏（密处场强大）、沿电场线电势降低；可由等势面逆向推出电场线】；警惕【等势面疏密反映场强而非电势大小】","src":"物一轮175.必看：静电场概念梳理_笔记","note":"视频|05:40-06:55","orig":"（知识）电场线与等势面处处垂直，可相互推导；等差等势面越密处场强越大；沿电场线方向电势降低。","link":""},{"id":"phy1094","t":"静电场·判断场强的四类方法","s":"看到【题目要求计算或比较某点场强】","c":"想到【按条件选方法：有F和q用定义式；点电荷场源用kQ/r^{2}；匀强场用U/d；只给电场线图看疏密定性比】；警惕【各公式适用条件混淆，乱套公式】","src":"物一轮175.必看：静电场概念梳理_笔记","note":"视频|06:55-07:44","orig":"（知识）四类方法：定义法 E=F/q（无条件限制）、点电荷公式 E=kQ/r²（需点电荷场源）、电势梯度 E=U/d（仅匀强场）、电场线疏密（定性比较）。","link":""},{"id":"phy1095","t":"静电场·正负号规则","s":"看到【计算时纠结电荷量要不要带正负号】","c":"想到【口诀：矢量式不带号（方向单独分析），标量式必带号（正负参与运算）】；警惕【矢量公式里代负号又另判方向造成重复；标量公式漏负号】","src":"物一轮175.必看：静电场概念梳理_笔记","note":"视频|07:44-09:02","orig":"（知识）矢量式规则：场强E、力F等矢量量公式中q不带号（方向单独判断）；标量式规则：电势φ、功W、电势能Ep等标量量公式中q需带正负号。","link":""},{"id":"phy1096","t":"静电场·场量与电荷量的对应关系","s":"看到【已知场量求电荷受到的力、具有的能量或做的功】","c":"想到【场量$\\times$q=电荷量：F=Eq、Ep=q$\\varphi$、W=qU；E与F、$\\varphi$与Ep、U与W 一一对应】；警惕【混淆场量（与试探电荷无关）和电荷量（依赖q）两个层次】","src":"物一轮175.必看：静电场概念梳理_笔记","note":"视频|09:02-11:06","orig":"（知识）下层（场性质）：场强E、电势φ、电势差U；上层（电荷性质）：电场力F、电势能Ep、功W；上下层通过乘以q相互转化（如F=Eq，W=Uq）。","link":""},{"id":"phy1097","t":"静电场·场问题研究思路","s":"看到【带电粒子在电场中的运动问题】","c":"想到【两条主线：动力学（E$\\to$F=Eq$\\to$a$\\to$运动）或能量（W=qU$\\to$功能关系/守恒）；始终先把场量转化为力或功】；警惕【只盯运动学轨迹硬套，忽略先做受力或能量分析】","src":"物一轮175.必看：静电场概念梳理_笔记","note":"视频|11:06-","orig":"（知识）动力学分析：场强→电场力→加速度→运动状态；能量分析：电势差→功→能量转化，或电势→电势能→综合能量守恒。方法论：把场量转化为力/功/能再求解。","link":""},{"id":"phy1098","t":"静电场·粒子轨迹问题","s":"看到【给出带电粒子在电场中的运动轨迹（虚线）与电场线（实线）组合图】","c":"想到【由轨迹弯曲方向判断电场力指向，结合电荷正负定场强方向，再分析速度、加速度及电势能变化】；警惕【把轨迹当成运动方向——粒子可能沿轨迹两个方向运动】","src":"物一轮176.【课前必看】本讲听课建议_笔记","note":"视频|01:06-02:46","orig":"（知识）粒子轨迹问题是选择题高频考点，考查轨迹与电场线关系、速度与加速度变化分析，综合检验电场概念理解。","link":""},{"id":"phy1099","t":"静电场·涉及电场力的力学问题","s":"看到【电场中的平衡、加速类力学综合问题】","c":"想到【把电场力 F=Eq 当成普通力纳入受力分析，再用平衡条件或牛顿定律、能量守恒求解】；警惕【漏画电场力或搞错其方向（正电荷顺场线、负电荷逆场线）】","src":"物一轮176.【课前必看】本讲听课建议_笔记","note":"视频|01:06-02:46","orig":"（知识）将电场力纳入传统力学分析框架，如平衡、加速问题；关键是受力分析、能量守恒与动力学结合。","link":""},{"id":"phy1100","t":"静电场·电场公式综合运用","s":"看到【电磁场综合题中电场部分的小问】","c":"想到【先按力学、能量两条主线拆解：E$\\to$F=Eq 定动力学，U、φ$\\to$W=qU 定能量，再衔接后继运动】；警惕【E 与 $\\varphi$ 混用——场强看疏密、电势看沿场线降低，两者无必然大小联系】","src":"物一轮176.【课前必看】本讲听课建议_笔记","note":"视频|02:46-","orig":"（知识）本讲训练关键：电场强度E与电势φ的关联应用，快速调用电场相关公式解决综合问题；选择题常考粒子轨迹分析，解答题多出现在电磁场综合问题中。","link":""},{"id":"phy1101","t":"静电场·粒子轨迹问题","s":"看到【电场线或等势面中给出粒子运动轨迹，比较两点的E、a、v、Eₖ、Eₚ】","c":"想到【一切比较最终回归受力分析：由轨迹与电场线/等势面共同确定电场力方向，再沿「力$\\to$场强$\\to$电势$\\to$电势能」「力$\\to$加速度$\\to$速度$\\to$动能」的路径推理】；警惕【忽略「曲线运动合力指向轨迹内侧」这一约束，单靠电场线定不了力】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|00:17-01:52","orig":"（知识）题目情境为电场线+粒子轨迹或等势面+粒子轨迹，粒子仅受电场力（不考虑重力），要求比较两点场强、加速度、速度、动能、电势能等物理量大小","link":""},{"id":"phy1102","t":"静电场·粒子轨迹问题","s":"看到【比较两点场强或加速度大小】","c":"想到【看电场线（等差等势面）疏密：密处场强大$\\to$电场力大$\\to$加速度大，与粒子电性无关】；警惕【等势面必须是等差等势面才能用疏密比场强】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|01:52-03:41","orig":"（知识）场强比较：F=qE，电场力大则场强大；加速度比较：F=ma，力大则a大；均通过电场线（或等差等势面）疏密判断","link":""},{"id":"phy1103","t":"静电场·粒子轨迹问题","s":"看到【比较两点的速度、动能大小或判断加减速】","c":"想到【用电场力与速度方向的夹角判断：锐角加速、钝角减速；再由电场力做功定动能，能量守恒反推电势能】；警惕【无论粒子沿轨迹哪个方向运动，速度大小关系结论一致，不必纠结运动方向】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|01:52-03:41","orig":"（知识）速度比较：力与速度夹角为锐角则加速、钝角则减速；动能看电场力做功，电势能变化与动能变化相反（ΔEₖ=-ΔEₚ）","link":""},{"id":"phy1104","t":"静电场·粒子轨迹问题","s":"看到【给出电场线和粒子轨迹，要求确定电场力方向或电性】","c":"想到【双重约束定力：指向轨迹凹侧＋沿电场线切线，两者交集为唯一方向；再由力与场强同向为正电荷、反向为负电荷】；警惕【场强方向、力方向、电性三者知二求一，缺一个条件时电性无法判断】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|04:14-10:20","orig":"（知识）电场线+轨迹：力必指向轨迹内侧，且沿电场线切线方向（正电荷同向、负电荷反向），取同时满足两个约束的唯一方向","link":""},{"id":"phy1105","t":"静电场·粒子轨迹问题","s":"看到【给出等势面和粒子轨迹求力或电性】","c":"想到【把等势面转化为垂直的电场线，套用电场线+轨迹的双重约束法】；警惕【不做转化、直接在等势面上找力方向会出错】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|04:14-10:20","orig":"（知识）等势面+轨迹：利用电场线与等势面处处垂直，先由等势面画出电场线，再转化为电场线+轨迹问题处理","link":""},{"id":"phy1106","t":"静电场·粒子轨迹问题","s":"看到【要求比较两点电势高低或电势能大小】","c":"想到【电势沿电场线方向降低直接判断；电势能用Eₚ=q$\\varphi$结合电性判断（正电荷电势高处电势能大），或由电场力做功判断（做正功电势能减小）】；警惕【电势能判断必须结合电荷正负，正负电荷结论相反】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|12:07-25:05","orig":"（知识）判断路径：速度可走动力学、功能关系或能量守恒三条路；电势沿电场线方向降低；正电荷在电势高处电势能大","link":""},{"id":"phy1107","t":"静电场·粒子轨迹问题","s":"看到【等势面+轨迹的综合多选项判断题】","c":"想到【固定流程：找力$\\to$判电性$\\to$比场强$\\to$析速度$\\to$定能量；熟练后按选项灵活选最短路径】；警惕【忘了等势面越密场强越大这一等差等势面特性】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|25:05-27:39","orig":"（例）例题按固定四步分析：确定力方向→判断电性→由等势面疏密比场强与加速度→由夹角判加速减速定动能电势能；灵活法可直接沿电场线降电势得φO>φP>φQ","link":""},{"id":"phy1108","t":"静电场·粒子轨迹问题","s":"看到【题目只给轨迹和等势面/电场线形状，未给电场线方向或电性】","c":"想到【力、场强大小、动能、电势能相对变化照常判断；电性与电势高低属「知二求一」缺条件项，直接排除相关选项】；警惕【误判出电性或电势高低——信息不足时不能硬判】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|37:23-42:23","orig":"（例）电场线方向未知时：可判断力方向（指向凹侧）、场强疏密比较（Ea>Eb则Fa>Fb）、动能变化（钝角减速），但电性与电势高低无法判断","link":""},{"id":"phy1109","t":"静电场·粒子轨迹问题","s":"看到【轨迹上某点速度方向与力先成钝角后成锐角，问是否存在速度/动能极值点】","c":"想到【夹角由钝变锐说明动能先减后增，存在最小值点；钝角段电场力做负功电势能增大】；警惕【轨迹方向未说明时假设一种情况分析即可，结论不受影响】","src":"物一轮177.粒子轨迹问题_笔记","note":"视频|42:23","orig":"（例）粒子在等差等势面间运动，M到N力与速度夹角先钝角后锐角，动能先减后增存在最小值点；由Ep=qφ结合电性判断电势能大小","link":""},{"id":"phy1110","t":"静电场·库仑力","s":"看到【两电荷（或类两体）间的相互作用力，力沿连线、随距离平方反比变化】","c":"想到【与万有引力类比：一切平方反比径向力的结论可互相迁移（如球壳内部结论）】；警惕【忘记库仑力方向始终沿连线方向，它是构造相似三角形的关键】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|00:26-02:43","orig":"（知识）F=kq₁q₂/r²，与距离平方成反比；方向沿两点电荷连线（径向力），同种相斥、异种相吸；高中只有库仑力与万有引力满足平方反比","link":""},{"id":"phy1111","t":"静电场·均匀带电球壳","s":"看到【均匀带电球壳（或半径变化的带电球体），问壳内场强、电势或壳外物理量】","c":"想到【壳内场强为零、电势等于边缘值kQ/R；壳外按点电荷公式处理，与半径R无关】；警惕【负电荷电势为负值，半径变化时电势绝对值变化方向易判反】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|02:43-11:31","orig":"（例）壳内（r<R）E=0、电势处处等于壳边缘电势φ=kQ/R；壳外（r>R）E=kQ/r²、φ=kQ/r，等效于电荷集中在球心；壳外场强和电势与R无关","link":""},{"id":"phy1112","t":"静电场·库仑力做功","s":"看到【库仑力（或其他径向力）作用下的圆周/圆弧运动，问场强或速度】","c":"想到【径向力始终垂直于速度不做功，能量方程只写其余力做的功；向心力方程列径向合力；「恰好无压力」即弹力为零的临界条件】；警惕【误把库仑力做功写进动能定理——径向力不做功】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|11:31-16:47","orig":"（例）细管内小球在B点对管壁恰好无压力（临界：弹力为零），Fₑ-mg=mv²/r提供向心力；库仑力沿半径方向始终与速度垂直不做功，动能定理mgr=½mv²，联立解得E=3mg/q","link":""},{"id":"phy1113","t":"静电场·库仑力动态平衡","s":"看到【库仑力参与的三力平衡，且力沿连线构成与几何结构相似的三角形】","c":"想到【相似三角形法：把力三角形与几何三角形对应成比例，由不变的几何边判断不变/变化的力】；警惕【忽略库仑力沿连线方向这一条件——它是相似关系成立的前提】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|16:47-21:11","orig":"（例）缓慢漏电动态平衡：力三角形与几何三角形相似，mg/PQ=F/AB=T/PB=定值；PB长度不变→T不变；F减小→AB距离减小","link":""},{"id":"phy1114","t":"静电场·库仑力平衡","s":"看到【两带电小球悬线平衡，问夹角/等高关系与电荷量的关系】","c":"想到【等质量+共悬点时用相似三角形证明几何对称性：$\\alpha$=$\\beta$与电量无关；质量不等则不对称】；警惕【误认为绳长相等就一定等高——悬线夹角不同高度不同】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|21:11-33:30","orig":"（例）两等质量小球用等长绳悬挂，受库仑斥力平衡：由相似三角形mg/OP=Tₐ/AO=f/AP与mg/OP=T_B/BO=f/BP推得AP=BP，故悬线夹角α=β与电荷量无关；质量不等时α≠β","link":""},{"id":"phy1115","t":"静电场·整体隔离法","s":"看到【多个带电体相互连接（绳、杆）在电场中平衡】","c":"想到【优先整体法+隔离法结合：整体消去内部库仑力（内力），隔离单个物体求局部】；警惕【电场力方向判断：正电荷与场强同向、负电荷反向】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|33:30-01:14:00","orig":"（例）两球各受重力、库仑力与电场力，用绳悬挂平衡：整体法(q₁-q₂)E=2mgtanθ，隔离B：q₂E=mgtanθ，解得q₁=-3q₂","link":""},{"id":"phy1116","t":"静电场·电场中的动力学","s":"看到【带电粒子在电场中运动的v-t图像，问场强或电势】","c":"想到【斜率=加速度$\\to$由F=ma定电场力$\\to$定场强E；再沿电场线电势降低定电势，电场中运动分析仍是「力$\\to$加速度$\\to$运动状态」】；警惕【负电荷受力方向与场强方向相反，容易定反场强】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|33:30-01:14:00","orig":"（例）v-t图斜率增大→a增大→电场力增大→E增大；速度增加且负电荷受力与场强反向→场强方向确定→沿电场线电势降低判断电势","link":""},{"id":"phy1117","t":"静电场·电场中的圆周运动","s":"看到【库仑力（平方反比径向力）作用下的圆周/远近轨迹运动，判断v、a变化】","c":"想到【本质是圆周运动供需关系：比较库仑力与所需向心力分匀速圆周/向心/离心三类；远离过程中力随r^{2}增大而减小$\\to$a减小但电场力做正功v增大】；警惕【「v减小而a增大」这类组合违反平方反比规律，可直接排除】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|33:30-01:14:00","orig":"（例）库仑力提供向心力时按供需关系分类：F库=F向匀速圆周（v、a不变）；F库>F向向心运动；F库<F向离心运动；斥力场景轨迹远离→加速但a减小（距离增大力减小）","link":""},{"id":"phy1118","t":"静电场·电场中的能量问题","s":"看到【电场+重力共同作用下的竖直圆周运动，求速度或场强】","c":"想到【向心力公式+动能定理两条腿：径向合力提供向心力，全程用动能定理；电场力做功与路径无关，用qU直接算】；警惕【混淆「拉力为零」与「压力为零」处的向心力组成】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|33:30-01:14:00","orig":"（例）细线小球在电场中圆周运动：A点拉力为零时qE-mg=mv²/L提供向心力；匀强电场U=EL；A到B用动能定理-mgL+qU=½mv²_B-½mv²_A，重势增mgL、电势能减qU","link":""},{"id":"phy1119","t":"静电场·类库仑力动量问题","s":"看到【两物体在斥力/引力（平方反比力）作用下相互靠近或远离，求最大势能或最终速度】","c":"想到【类碰撞双守恒模型：相对速度为零（共速）时势能最大、距离最小，用动量守恒；回到原距离/无穷远时势能复原，动量动能双守恒按类弹性碰撞解】；警惕【矢量方向处理及动量守恒条件（系统仅受内力）的检查】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|33:30-01:14:00","orig":"（例）两球受F∝1/r²斥力，先靠近后远离：最小距离（最大势能）时共速，动量守恒mv₀=(m+2m)v共，Epₘₐₓ=⅓mv₀²；最终相距无穷远（类弹性碰撞），动量、动能双守恒解得vₐ=-⅓v₀、v_B=⅔v₀","link":""},{"id":"phy1120","t":"静电场·方法总纲","s":"看到【带电体在电场中的平衡、动力学、能量、动量综合问题】","c":"想到【先算好电场力qE并定方向，把电场力当作一个普通外力套用力学全套方法】；警惕【对电场问题产生畏惧心理——本质仍是力学方法迁移】","src":"物一轮178.涉及电场力的力学问题_笔记","note":"视频|01:14:00","orig":"（知识）电磁场问题并非全新题型，而是在新环境中运用传统力学方法：牛顿力学、能量守恒等照样适用；f=qE方向判定贯穿平衡、动力学、能量、动量各类问题","link":""},{"id":"phy1121","t":"静电场·电容器动态分析","s":"看到【电容器极板移动/介质变化后判断C、Q、U、E的变化】","c":"想到【先判工作模式（断开$\\to$Q不变，接电源$\\to$U不变），再按固定步骤推变化链】；警惕【混淆Q不变与U不变两种情形下的场强公式】","src":"物一轮179.【课前必看】本讲听课建议_笔记","note":"视频|00:32-03:01","orig":"（知识）典型题型为改变板间距离、平移极板后各物理量的变化，有固定解题方法，难度不大；需区分电压不变与电荷量不变两种情形","link":""},{"id":"phy1122","t":"静电场·带电粒子在匀强电场中的运动","s":"看到【带电粒子在匀强电场中被加速或偏转】","c":"想到【加速用动能定理qU=½mv^{2}，偏转按类平抛分解处理】；警惕【这是电磁场压轴题的关键一环，基础公式必须熟练】","src":"物一轮179.【课前必看】本讲听课建议_笔记","note":"视频|00:32-03:01","orig":"（知识）分为加速电场（使粒子速度增加）与偏转电场（使运动方向改变）两类，高考极高频，是电磁场综合压轴题的基础环节，方法为牛顿第二定律+运动学公式","link":""},{"id":"phy1123","t":"静电场·重电复合场与周期变化电场","s":"看到【粒子同时受重力与电场力，或电场随时间周期性变化】","c":"想到【恒定复合场合成等效重力；交变电场用U-t$\\to$a-t$\\to$v-t图像链分段分析】；警惕【复合场中等效最高点$\\neq$几何最高点】","src":"物一轮179.【课前必看】本讲听课建议_笔记","note":"视频|00:32-03:01","orig":"（知识）重电复合场（4星）用等效思想（等效重力场）解题；周期变化电场（5星）难度最高，需分段分析+图像法","link":""},{"id":"phy1124","t":"静电场·电容","s":"看到【问电容C是否随所带电荷量Q或电压U变化】","c":"想到【C是容器固有属性，Q或U改变时比值Q/U恒等于C不变】；警惕【把定义式当决定式，误认为Q增C就增】","src":"物一轮180.电容器_笔记","note":"视频|01:53-04:06","orig":"（知识）定义式C=Q/U仅是量度关系不表示决定关系（类比E=F/q），C由电容器本身决定，不随Q、U变化","link":""},{"id":"phy1125","t":"静电场·平行板电容器","s":"看到【改变极板间距d、正对面积S或插入介质，问电容变化】","c":"想到【代入决定式逐参分析：d↑$\\to$C↓，S↑$\\to$C↑，插介质$\\to$C↑】；警惕【正对面积要用投影确定，不等于极板总面积】","src":"物一轮180.电容器_笔记","note":"视频|04:06-07:56","orig":"（知识）决定式C=εrS/(4πkd)：C与εr、S成正比，与d成反比；S为有效正对面积（按垂线投影确定，边缘未对齐部分不计入）","link":""},{"id":"phy1126","t":"静电场·电容器动态分析","s":"看到【电容器动态分析题，判断工作模式】","c":"想到【口诀「断Q不断U」：断开连接则Q不变，连电源则U不变】；警惕【电容器接在含内阻电源或滑动变阻器两端时电压可能变化，并非严格U不变】","src":"物一轮180.电容器_笔记","note":"视频|09:25-10:29","orig":"（知识）Q不变：电容器与电路断开（含开关断开），电荷无法逃逸；U不变：电容器直接连恒压电源（开关闭合），稳定时U极板=U电源","link":""},{"id":"phy1127","t":"静电场·电容器动态分析","s":"看到【移动极板后问板间场强E的变化】","c":"想到【先定模式再选公式：U不变用E=U/d，Q不变用E=4$\\pi$kQ/($\\varepsilon$rS)（场强不变）】；警惕【混淆两模式的场强公式——「场强要看谁不变」】","src":"物一轮180.电容器_笔记","note":"视频|19:43-20:25","orig":"（知识）U不变模式：d↑→C↓→Q减小（Q=CU），场强E=U/d与d成反比；Q不变模式：E=4πkQ/(εrS)与d无关","link":""},{"id":"phy1128","t":"静电场·电容器动态分析","s":"看到【板间悬浮液滴（油滴），问极板移动后液滴如何运动】","c":"想到【先判E变化，再比较qE与mg定运动方向；由平衡条件判带电性】；警惕【忽略液滴带电正负对受力方向的影响】","src":"物一轮180.电容器_笔记","note":"视频|20:25-22:23","orig":"（知识）液滴初始平衡mg=qE，场强变化后比较mg与qE：E减小则qE<mg向下加速，E增大则向上运动；由平衡时电场力方向与场强方向关系判断带电性质","link":""},{"id":"phy1129","t":"静电场·电容器动态分析","s":"看到【求板间某点P的电势或两点间电势差】","c":"想到【u与D必须对应：选哪两点就用该两点沿场强方向的距离；不同情境中d含义不同，按所选点确定】；警惕【把任意两点距离误用成板间距】","src":"物一轮180.电容器_笔记","note":"视频|22:23-25:57","orig":"（知识）u=ED中u是任意两点间电势差、D为两点沿电场线方向距离；与C=εrS/(4πkd)中的固定板间距d含义不同","link":""},{"id":"phy1130","t":"静电场·电容器动态分析","s":"看到【问板间某固定点P电势如何变化】","c":"想到【找参考极板：Q不变找接地极板，U不变找与P距离不变的极板，用$\\varphi$ₚ=ED'判断】；警惕【参考点选择不当导致电势变化方向判反】","src":"物一轮180.电容器_笔记","note":"视频|25:57-29:12","orig":"（知识）q不变时：选接地极板为参考点（φ=0），由φₚ=u=ED直接得电势；u不变时：选与P点距离不变的极板作参考，分析该电势差变化","link":""},{"id":"phy1131","t":"静电场·电容器动态分析","s":"看到【开关闭合、上极板上移的动态分析综合题】","c":"想到【按固定链条：模式$\\to$C$\\to$Q/U$\\to$E$\\to$液滴$\\to$电势，一步步推】；警惕【电势判断中参考点到P的距离d'是否变化要单独确认】","src":"物一轮180.电容器_笔记","note":"视频|29:24-35:47","orig":"（例）开关闭合U不变：上极板上移→d增大→C减小→Q=CU减小→E=u/d减小→液滴向下加速→下极板为参考（d'不变）φₚ=ED'减小","link":""},{"id":"phy1132","t":"静电场·电容器动态分析","s":"看到【开关断开（充电后脱离电源）后移动极板】","c":"想到【Q不变时场强与d无关，一切由E不变出发：液滴不动、与距离不变处的电势不变，只有U=q/C变化】；警惕【误用E=U/d判断，得出E减小的错误结论】","src":"物一轮180.电容器_笔记","note":"视频|35:47-36:02","orig":"（例）开关断开Q不变：上极板上移→C减小→U=q/C增大→E=4πkq/(εrS)不变→液滴保持静止→接地极板参考下φₚ不变","link":""},{"id":"phy1133","t":"静电场·电容器与电路综合","s":"看到【介质（溶液）性质变化引起电容变化，问充放电电流方向】","c":"想到【先由介质定C变化，再由Q=CU定充放电；充电时电流方向与电源极性一致，放电相反】；警惕【U不变时电势差不变，别误判】","src":"物一轮180.电容器_笔记","note":"视频|39:40","orig":"（例）不导电溶液作介质连恒压源：浓度降低→εr增大→C增大→Q=CU增大（充电）；电流方向与电源极性一致，口诀「充电同向，放电反向」","link":""},{"id":"phy1134","t":"静电场·静电计与电容器能量","s":"看到【静电计与电容器并联的实验题，问张角/能量变化】","c":"想到【静电计张角反映板间电压U而非场强E；能量用三种表达式按不变量选择：Q不变用W=Q^{2}/2C】；警惕【混淆张角与场强的直接关系——张角实际反映U】","src":"物一轮180.电容器_笔记","note":"视频|39:40","orig":"（例）静电计测电压保持Q不变：d增大→C减小→U增大→张角增大；Q不变时E=4πkQ/(εrS)与d无关；储能W=½QU=Q²/2C=½CU²，U增大则W增大","link":""},{"id":"phy1135","t":"静电场·含内阻电源的含容电路","s":"看到【电容器接在含滑动变阻器/内阻的电路中，问液滴或电势变化】","c":"想到【先确定电容器电压由哪个元件分压决定，再按U不变或Q不变模式分析】；警惕【把含内阻电源当成真正恒压源，忽略串联分压变化】","src":"物一轮180.电容器_笔记","note":"视频|39:40","orig":"（例）含内阻电源+滑动变阻器分压：电容器电压等于所并联元件分压（非恒压源）；仅移动极板时U不变液滴不动；滑片移动改变分压→E变化→液滴移动；断开S₀转Q不变，E不变","link":""},{"id":"phy1136","t":"电场·加速电场","s":"看到【带电粒子在电场中由静止加速，求末速度】","c":"想到【求速度优先用动能定理qU=½mv^{2}，结果与板间距d无关；求时间必须用动力学】；警惕【能量法虽快但无法求时间】","src":"物一轮181.带电粒子在匀强电场中的运动_笔记","note":"视频|00:28-02:44","orig":"（知识）粒子从静止在匀强电场中做匀加速直线运动；能量法：qU=½mv²得v=√(2qU/m)，无需板间距d；动力学法：a=qU/(md)，可求时间t∝d","link":""},{"id":"phy1137","t":"电场·加速电场","s":"看到【粒子先在电压下加速、中途撤去电压的多过程直线运动】","c":"想到【分段分析：加速段用运动学或能量求末速度，匀速段用v=t关系，注意两段速度衔接】；警惕【多过程问题不能全程套一个匀变速公式】","src":"物一轮181.带电粒子在匀强电场中的运动_笔记","note":"视频|08:21-14:42","orig":"（例）前半程有电压匀加速（d/2=½at₁²），后半程撤电压匀速；分段求时间t₁=d√(m/qU)、t₂=½d√(m/qU)，总时间t=3d/2·√(m/qU)","link":""},{"id":"phy1138","t":"电场·加速电场与电容器综合","s":"看到【改变板间距d，问粒子加速后获得的动能】","c":"想到【关键看电压是否变：U一定则动能不变；Q一定（断开电源）则d增大$\\to$U增大$\\to$动能增大】；警惕【混淆U一定与Q一定两种情形】","src":"物一轮181.带电粒子在匀强电场中的运动_笔记","note":"视频|14:42-18:32","orig":"（例）U一定时动能Ek=qU为定值与d无关；Q一定时增大d→C减小→U=q/C增大→动能增大；a·d=qU/m为定值","link":""},{"id":"phy1139","t":"电场·多级加速器","s":"看到【粒子连续穿过多对平行板间隙持续加速】","c":"想到【同步条件：穿越间隙时间=半周期，电压极性随位置交替反转】；警惕【以为用直流电源就能持续加速】","src":"物一轮181.带电粒子在匀强电场中的运动_笔记","note":"视频|18:32-26:16","orig":"（知识）多级加速器必须用交流电源：粒子在每个间隙的运动时间等于交变电压半个周期，进入新间隙时电压极性恰好反转，保证每次都被加速","link":""},{"id":"phy1140","t":"电场·多级加速器","s":"看到【多级加速器板间距设计，误套零初速匀变速1:3:5位移比】","c":"想到【各段加速度不同（d不同$\\to$E不同），不是同一匀变速过程，比例推论不适用】；警惕【把分段匀加速误当全程匀加速乱用比例结论】","src":"物一轮181.带电粒子在匀强电场中的运动_笔记","note":"视频|26:16-31:34","orig":"（知识）忽略穿过极板时间时：U恒定但板间距d必须逐级增大（E=U/d减小、a减小），每段虽匀加速但加速度不同，位移比不满足初速为零匀变速的1:3:5推论","link":""},{"id":"phy1141","t":"电场·多级加速器","s":"看到【多级加速器圆筒模型，求筒长或速度关系】","c":"想到【筒内匀速（静电屏蔽E=0）、缝隙加速；vn=√(n·2qU/m)，筒长Ln=vn·T/2，比例1:√2:√3…】；警惕【离开第1个筒时只加速一次，速度是√(2qU/m)不是√(2·2qU/m)】","src":"物一轮181.带电粒子在匀强电场中的运动_笔记","note":"视频|31:34-34:31","orig":"（知识）忽略极板间时间时：粒子在圆筒（极板）内因静电屏蔽不受电场力做匀速运动，只在缝隙间匀加速；第n个筒长Ln=vn·T/2，速度比与筒长比均为1:√2:√3…","link":""},{"id":"phy1142","t":"电场·多级加速器","s":"看到【多级加速器选项题综合判断】","c":"想到【四查：筒内运动性质、加速次数与速度对应、筒长公式、Ln固定时由Ln=（T/2)√(n·2qU/m)反推周期与比荷关系】；警惕【忽略加速次数与n的对应关系】","src":"物一轮181.带电粒子在匀强电场中的运动_笔记","note":"视频|35:10","orig":"（例）多级加速器原理图选择题：A错（筒内匀速非加速）、B错（速度值差一次加速）、C对（Ln=vn·T/2）、D错（Ln不变时比荷增大则周期T应减小）","link":""},{"id":"phy1143","t":"电场·偏转电场","s":"看到【带电粒子以水平初速进入平行板间（上下放置）的偏转电场】","c":"想到【完全类比平抛：运动合成与分解，水平、竖直独立列式，时间由水平方向t=L/v_{0}定】；警惕【加速度用qU/(md)而不是重力加速度g】","src":"物一轮182.带电粒子在偏转电场中的运动_笔记","note":"视频|00:09-09:05","orig":"（知识）初速度v₀水平、电场力竖直→类平抛：水平匀速x=v₀t，竖直匀加速y=½at²，a=qU/(md)；已知U、d、L，粒子荷质比q/m为变量","link":""},{"id":"phy1144","t":"电场·偏转电场","s":"看到【同种元素同位素（q同m不同）以相同初速度进入偏转电场，比较轨迹】","c":"想到【轨迹由荷质比q/m决定：q/m越大偏转越厉害；动能增量只看qU偏，同q则相同】；警惕【动能增量误认为与质量有关】","src":"物一轮182.带电粒子在偏转电场中的运动_笔记","note":"视频|09:05-16:31","orig":"（例）氕氘氚同初速入偏转电场：水平位移小的先打板（时间短）；相同偏转y下t越小→q/m越大，轨迹由荷质比决定；动能增量ΔEk=qU偏三者相同（q相同）","link":""},{"id":"phy1145","t":"电场·先加速后偏转","s":"看到【粒子经加速电压U_{1}加速后进入偏转电压U_{2}的偏转电场，求偏移量或出射角】","c":"想到【两段联立消去v得y_{1}=U_{2}L_{1}^{2}/(4U_{1}d)、tan$\\theta$=U_{2}L_{1}/(2U_{1}d)，与q、m无关】；警惕【只记结论不记推导——参数变化时需重新推导】","src":"物一轮182.带电粒子在偏转电场中的运动_笔记","note":"视频|09:05-16:31","orig":"（知识）加速段qU₁=½mv²；偏转段y₁=qU₂L₁²/(2mdv²)=U₂L₁²/(4U₁d)，出射角tanθ=U₂L₁/(2U₁d)——均与荷质比无关","link":""},{"id":"phy1146","t":"电场·先加速后偏转","s":"看到【粒子飞出偏转电场后打到荧光屏，求屏上偏移】","c":"想到【用「反向延长线过水平位移中点」的平抛推论构造相似三角形，比全程运动分解更快】；警惕【死记公式不用推论，几何关系一变就束手无策】","src":"物一轮182.带电粒子在偏转电场中的运动_笔记","note":"视频|16:31-28:57","orig":"（知识）飞出后匀速直线：类平抛推论——速度反向延长线过水平位移中点，几何关系y₂=(2L₂/L₁)·y₁；总偏移y=y₁+y₂","link":""},{"id":"phy1147","t":"电场·轨迹重合条件","s":"看到【问不同粒子（质子、氘核、$\\alpha$粒子等）在同一装置中的轨迹是否重合】","c":"想到【从静止经相同U_{1}加速+U_{2}偏转$\\to$轨迹重合（y与q、m无关）；若只是初速度相同进入，偏移y∝q/m·1/v_{0}^{2}则不同】；警惕【误以为初速度相同轨迹就相同——必须经过相同加速电场】","src":"物一轮182.带电粒子在偏转电场中的运动_笔记","note":"视频|16:31-28:57","orig":"（知识）相同加速-偏转电场条件下不同粒子轨迹完全重合（需同种电荷）；仅以相同初速度进入偏转电场不能保证轨迹相同","link":""},{"id":"phy1148","t":"电场·三种粒子参量比较","s":"看到【多种粒子经过同一套加速偏转装置，比较a、v、Ek】","c":"想到【记住比例关系：a∝q/m，v∝√(q/m)，$\\Delta$Ek∝q（加速偏转电压相同时），逐一代入各粒子q、m】；警惕【$\\alpha$粒子的q=2e、m=4mH，荷质比与氘核相同】","src":"物一轮182.带电粒子在偏转电场中的运动_笔记","note":"视频|28:57-35:06","orig":"（例）氢核、氘核、α粒子经同一加速+偏转电场：加速度比a∝q/m为2:1:1；末速度比v∝√(q/m)为2:1:1；动能增量ΔEk=qU₁+qU'∝q为1:1:2","link":""},{"id":"phy1149","t":"电场·示波管模型","s":"看到【示波管：加速电场+偏转电场+匀速直线段打到荧光屏，求偏移量】","c":"想到【标准三段流程：动能定理$\\to$类平抛$\\to$相似三角形（或匀速段分解）逐段求】；警惕【忘记匀速段贡献的偏移，只算出射点偏移】","src":"物一轮182.带电粒子在偏转电场中的运动_笔记","note":"视频|35:06","orig":"（例）三段分析：加速v₀=√(2eU₁/m)；偏转y=eU₂L²/(2mdv₀²)=U₂L²/(4U₁d)；荧光屏偏移OP=y(1+2D/L)=U₂L(L+2D)/(4U₁d)，用相似三角形y/OP=(L/2)/(L/2+D)","link":""},{"id":"phy1150","t":"复合场·等效重力法","s":"看到【带电小球同时受重力与匀强电场力做圆周/摆动运动】","c":"想到【平行四边形合成mg^{'}，把复合场转化为斜向「重力场」，整套纯重力场模型（圆周、摆动）照搬】；警惕【等效只适用于恒力场（匀强电场），变力场不可等效】","src":"物一轮183.带电粒子在重电复合中的运动_笔记","note":"视频|00:45-13:29","orig":"（知识）匀强电场力与重力都是恒力，可合成等效重力mg′；等效重力加速度g′=√(g²+(qE/m)²)；绳拉力始终与速度垂直不做功","link":""},{"id":"phy1151","t":"复合场·等效最低点与最高点","s":"看到【问复合场圆周运动中速度最大位置或恰能完成整圆的条件】","c":"想到【过圆心作mg^{'}平行线定等效最低/最高点；临界速度类比我最高点：v^{'}min=√(g^{'}r)】；警惕【把临界点错放在几何最高点——完整圆周的关键是过等效最高点】","src":"物一轮183.带电粒子在重电复合中的运动_笔记","note":"视频|00:45-13:29","orig":"（知识）速度最大（动能最大）点在等效重力方向最低点；不能只考虑重力做功最多或电场力做功最多；完整圆周条件是过等效最高点v′min=√(g′r)，而非几何最高点","link":""},{"id":"phy1152","t":"复合场·直线释放","s":"看到【复合场中细线小球从非常规位置（如水平）静止释放】","c":"想到【先判断绳是否一直张紧：初位置绳上速度为零时拉力可能为零，小球沿合力（等效重力）方向做匀加速直线运动】；警惕【默认沿圆弧运动、乱套圆周公式】","src":"物一轮183.带电粒子在重电复合中的运动_笔记","note":"视频|13:29-21:15","orig":"（例）细线与竖直成45°平衡时qE=mg，合力方向即等效重力方向（45°斜向下、大小√2mg）；水平释放后绳松弛，小球沿等效重力方向做匀加速直线运动a=√2g，位移√2L，t=√(2L/g)——不是圆周运动","link":""},{"id":"phy1153","t":"复合场·圆周临界与能量","s":"看到【复合场中带电小球恰能完成圆周运动，求最小初速度】","c":"想到【先由平衡条件定E，再求g^{'}，套「等效最高点临界速度+能量守恒」：初速度v_{0}=√(5g^{'}L)】；警惕【机械能变化只看电场力做功（除重力外其他力做的功）】","src":"物一轮183.带电粒子在重电复合中的运动_笔记","note":"视频|21:15","orig":"（例）平衡时qE=mgtanθ→E=mgtanθ/q；等效重力mg′=mg/cosθ，g′=g/cosθ；恰能整圆初速v₀=√(5g′L)=√(5gL/cosθ)；机械能变化仅由电场力做功决定，从初位到最左端减少mgLtanθ(1+sinθ)","link":""},{"id":"phy1154","t":"复合场·电势能变化","s":"看到【带电粒子在匀强电场中沿闭合路径运动，问电势能变化】","c":"想到【逐段看电场力与速度夹角定做功正负；匀强电场中闭合路径一周电场力做功为零，电势能复原】；警惕【只看起点终点位置而忽略过程中先增后减的细节】","src":"物一轮183.带电粒子在重电复合中的运动_笔记","note":"视频|21:15","orig":"（例）小球顺时针运动一周：电场力先做负功后做正功，电势能先增大后减小，一周回到原值","link":""},{"id":"phy1155","t":"交变电场·基本分析","s":"看到【平行板间电势周期性变化，粒子某时刻无初速释放，问能否到达对板及末速度】","c":"想到【按释放瞬间的极性定场强方向与受力，算a后用位移公式与板间距比较判断能否到达】；警惕【电势差的正负与电场方向对应关系弄反】","src":"物一轮184.带电粒子在周期变化电场中的运动_笔记","note":"视频|00:39-23:47","orig":"（例）B板接地，A板电势在-2.5V与+2.5V间周期变化：t=0无初速释放时φB>φA电场由B指向A，正电荷向右加速，a=qU/(md)，用x=½at²验证恰好到达A板，末速度v=at₁","link":""},{"id":"phy1156","t":"交变电场·图像法","s":"看到【交变电压下的粒子运动分析题】","c":"想到【按U$\\to$E$\\to$a$\\to$v逐级转换图像，用v-t图面积（位移）代数和判断净位移方向】；警惕【忘记先规定正方向，电子带负电时方向还要再翻转】","src":"物一轮184.带电粒子在周期变化电场中的运动_笔记","note":"视频|23:47-30:17","orig":"（知识）解题链：U-t图→E-t图→a-t图→v-t图；规定正方向后，比较v-t图中上下方面积判断位移方向：下方面积大则整体向左，上方面积大则向右","link":""},{"id":"phy1157","t":"交变电场·临界条件","s":"看到【问某时间窗口内释放的粒子不能到达对板，求频率或周期范围】","c":"想到【找窗口内位移最大的临界释放时刻（通常T/4），令其最大位移恰好等于允许值列不等式】；警惕【用窗口两端时刻而非最不利时刻列临界条件】","src":"物一轮184.带电粒子在周期变化电场中的运动_笔记","note":"视频|23:47-30:17","orig":"（例）求频率f使T/4到T/2间释放的粒子不能到达A板：临界是T/4时刻释放者向右位移最大，½a(T/4)²<d/2，解得T<√2×10⁻⁵s，f>√2/2×10⁵Hz","link":""},{"id":"phy1158","t":"交变电场·释放时刻的影响","s":"看到【问不同释放时刻t_{0}的粒子最终向哪侧偏/能否到达某板】","c":"想到【对每个释放时刻画v-t图，比较一个周期内上下方面积代数和定净位移方向】；警惕【凭直觉认为「先向右就到不了左板」——要看面积代数和】","src":"物一轮184.带电粒子在周期变化电场中的运动_笔记","note":"视频|30:17","orig":"（例）不同释放时刻粒子运动方向不同：0<t₀<T/4先右后左但上方面积大整体向右；T/2<t₀<3T/4下方面积大整体向左能到达A板；3T/4以后多向右运动","link":""},{"id":"phy1159","t":"交变电场·偏转与周期对称性","s":"看到【电子穿越交变偏转电场所用时间恰为整数个周期，问出射速度或动能】","c":"想到【周期对称性：整周期后vy=0，出射速度=入射水平速度，动能都相同；只有非完整周期产生净偏转，不同入射时刻偏移方向不同】；警惕【误认为出射速度不同或动能不同】","src":"物一轮184.带电粒子在周期变化电场中的运动_笔记","note":"视频|30:17","orig":"（例）电子穿越时间t=L/v₀=2T（两个完整周期）：完整周期数内vy归零，离开时所有电子vy=0、速度均为v₀、动能相同均为½mv₀²；不同时刻入射偏转方向不同","link":""},{"id":"phy1160","t":"交变电场·最大偏移临界","s":"看到【问板间电子的最大侧向位移或恰好从边缘飞出的条件】","c":"想到【找位移最大的入射时刻，用a-t图/分段匀加速累加位移，「刚好从边缘飞出」即最大偏移=板间距一半，据此列方程求未知量】；警惕【忽略分段累加：一个周期内偏移由多个½at^{2}片段构成】","src":"物一轮184.带电粒子在周期变化电场中的运动_笔记","note":"视频|30:17","orig":"（例）最大偏距条件d/2=4×½a(T/2)²用于定a；T/4入射电子最大侧移ymax=2×½a(T/4)²=d/16；利用「最大偏距刚好从边缘飞出」建立方程","link":""},{"id":"phy1161","t":"电路·本讲体系与难度分级","s":"看到【闭合电路知识体系梳理或电学计算分级】","c":"想到【按「结构识别$\\to$概念与定律$\\to$能量问题$\\to$动态分析」层次推进，动态分析为最高阶能力，含容电路是难点】；警惕【动态分析考频虽降但属高阶训练，不能完全放弃】","src":"物一轮185.【课前必看】本讲听课建议_笔记","note":"视频|00:15-03:36","orig":"（知识）闭合电路欧姆定律本讲难度分级：1星电路结构识别（串并联、短路/断路、电表测量对象）；2星基本概念与闭合电路欧姆定律、能量传输；4星电源最大输出功率与效率；5星动态电路分析（常规与含容）。","link":""},{"id":"phy1162","t":"电路·考情分布","s":"看到【电路模块考情与复习方向判断】","c":"想到【重点抓概念与计算基础（电学实验常与仪器使用、误差分析结合）；综合计算常与电磁感应结合，闭合电路是前置知识】；警惕【只刷早期动态分析真题会偏离近年考向】","src":"物一轮185.【课前必看】本讲听课建议_笔记","note":"视频|03:55-06:45","orig":"（知识）电路模块考情：基础模块至少覆盖10分（主要在电学实验）；动态分析选择题近十年考频显著下降，综合计算题保持高频且常与电磁感应综合出题。","link":""},{"id":"phy1163","t":"电路·知识要点总览","s":"看到【需要快速定位电路易错点清单】","c":"想到【核心易混五处：电动势vs电压、短路vs断路、电表测量对象、能量转化效率计算、动态变量逻辑推导】；警惕【最大功率条件（负载匹配R=r）与效率随外阻增大并不矛盾】","src":"物一轮185.【课前必看】本讲听课建议_笔记","note":"视频|06:45","orig":"（知识）知识小结列出易混点：电动势与电压的区别、电阻的计算方法、短路与断路的区分、电流表/电压表测量对象判定、电容器等效电阻处理、最大功率条件（负载匹配）。","link":""},{"id":"phy1164","t":"电路结构识别·串并联特征与混联","s":"看到【混联电路求总电阻或判断串并联关系】","c":"想到【串联同流分压、并联同压分流；混联先找最小并联单元逐级等效，遵循先并后串】；警惕【两电阻并联「积在和上飞」口诀仅适用于两个电阻，不能随意扩展】","src":"物一轮186.电路结构的识别_笔记","note":"视频|00:49-08:48","orig":"（例）三个小灯泡混联：先识别最小并联单元L1与L2并联，等效为R₁R₂/(R₁+R₂)后再与L3串联，得R总=R₁R₂/(R₁+R₂)+R3。","link":""},{"id":"phy1165","t":"电路结构识别·通路断路短路","s":"看到【判断电路处于通路、断路还是短路】","c":"想到【断路看回路是否断开，短路看用电器是否被导线「包围/跨接」】；警惕【短路时用电器两端电压为零但电路中仍有电流】","src":"物一轮186.电路结构的识别_笔记","note":"视频|08:48-11:36","orig":"（知识）通路：形成完整闭合回路；断路：某处断开无电流，用电器不工作；短路：用电器两端被导线直接连接，电流优先走无电阻导线。","link":""},{"id":"phy1166","t":"电路结构识别·多开关电路","s":"看到【开关组合不同导致电路结构改变】","c":"想到【逐个开关状态用电流路径追踪法：从正极出发看每条回路能否走通，被导线包围的元件被短路】；警惕【开关断开会阻断所在支路，不能只看局部】","src":"物一轮186.电路结构的识别_笔记","note":"视频|11:36-17:02","orig":"（例）电流路径追踪法分析多开关电路：仅闭合S1时L1与L3串联（L2断路）；闭合S2和S3时仅L2工作（L3被短路）；全部闭合时L1与L2并联（L3持续被短路）。","link":""},{"id":"phy1167","t":"电路结构识别·滑动变阻器接法","s":"看到【判断滑动变阻器是限流接法还是分压接法】","c":"想到【将变阻器从滑片一分为二分析：一部分被纯导线完全包围$\\to$被短路$\\to$限流；两部分均接入电路$\\to$先并后串为分压】；警惕【忽略导线完全包围导致的短路是高频错误】","src":"物一轮186.电路结构的识别_笔记","note":"视频|17:02-20:50","orig":"（例）滑动变阻器从滑片一分为二：右半部分被导线完全包围而短路，仅左半部分与Rx串联→限流；右半部分未被短路，形成Rx与右半并联再与左半串联→分压。","link":""},{"id":"phy1168","t":"电路结构识别·电表等效简化","s":"看到【电路图中含电流表电压表需先简化分析】","c":"想到【电流表≈导线、电压表≈断路，先去掉电表分析裸电路结构，再还原电表确定测量对象】；警惕【还原时电压表连接点可沿导线移动找等效位置，勿直接按原图连线判断】","src":"物一轮186.电路结构的识别_笔记","note":"视频|20:50-23:01","orig":"（知识）理想电流表电阻为零视为导线，测通过自身的电流；理想电压表电阻无穷大视为断开，测自身两端电压。简化步骤：先等效→分析结构→还原电表定测量对象。","link":""},{"id":"phy1169","t":"电路结构识别·测量对象判断","s":"看到【问电表测量的是哪个元件的电学量】","c":"想到【电流表看它与谁串联，电压表看它与谁并联；利用节点沿导线移动法确定等效并联对象】；警惕【同一电压表在并联结构中可有多个等效测量对象，答案要写并联部分整体】","src":"物一轮186.电路结构的识别_笔记","note":"视频|23:01","orig":"（例）R1与R2并联后再与R3串联电路中：A1与R3串联测R3电流，A2测R2电流，V1并联在R3两端测R3电压，V2可视为并联在R1或R2两端测并联部分电压。","link":""},{"id":"phy1170","t":"电流·定义式与方向","s":"看到【由电荷量与时间求电流或判断电流方向】","c":"想到【I=Q/t；方向按正电荷定向移动方向确定】；警惕【负电荷（电子）运动方向与电流方向相反，判断环形电流方向要先换向】","src":"物一轮187.电流与电阻_笔记","note":"视频|00:26-00:48","orig":"（知识）电流定义式I=Q/t，单位时间通过横截面的电荷量；正电荷移动方向为电流方向，负电荷移动方向与电流方向相反。","link":""},{"id":"phy1171","t":"电流·等效电流","s":"看到【周期性运动的带电粒子（电子绕核、环形运动）求等效电流】","c":"想到【I=q/T，q为一个周期内通过横截面的电荷量；电解液中正负离子电荷量相加同向贡献】；警惕【离子价态不同电荷量不同（如SO_{4}^{2-}为2e），不能只数个数】","src":"物一轮187.电流与电阻_笔记","note":"视频|00:48-06:18","orig":"（例）电子绕核运动：任取横截面，电子每周期T通过一次、带电量e，等效电流I=e/T；电子顺时针运动对应逆时针电流。扩展：电解液中n1个Na⁺和n2个SO₄²⁻定向移动时I=(n1+2n2)e/t。","link":""},{"id":"phy1172","t":"电流·微观决定式","s":"看到【从微观角度求电流或考查I=nesv各量含义】","c":"想到【I=nesv，类比「单价$\\times$数量=总价」：n是单位体积电荷数，svt是体积】；警惕【n是单位体积内自由电荷数而非单位长度，横截面积s变化时v随之变化】","src":"物一轮187.电流与电阻_笔记","note":"视频|06:20-13:51","orig":"（知识）决定式I=nesv：n为单位体积自由电荷数（个/m³），e为单个电荷电量，s为横截面积，v为定向移动速率。推导：宏观Q=It与微观Q=neV=ne·svt联立。","link":""},{"id":"phy1173","t":"电流·定义式与决定式对比应用","s":"看到【同一电流问题可用定义式和决定式两条路求解】","c":"想到【定义式I=q/T优先、更简便；决定式需构造管道模型补辅助参数，两法结果必一致可互验】；警惕【决定式中要自己构造n与s时容易漏单位或量纲】","src":"物一轮187.电流与电阻_笔记","note":"视频|13:51-18:53","orig":"（例）已知物理量求电流：构造管道模型算n=1/(s·2πR)、v=2πR/T，代入I=nesv得I=e/T，与定义式结果一致；定义式更简便，决定式需构造辅助参数。","link":""},{"id":"phy1174","t":"电流·圆周运动综合","s":"看到【静电引力提供向心力的带电粒子圆周运动求电流】","c":"想到【先由引力=向心力解周期T，再I=e/T；必要时用量纲（单位化简）快速排除选项】；警惕【k、m、R等常数的位置易代错，量纲检验可兜底】","src":"物一轮187.电流与电阻_笔记","note":"视频|18:53-29:25","orig":"（例）电子绕核：库仑力提供向心力ke²/R²=m·4π²R/T²，解出周期后I=e/T；再用量纲验证，仅选项单位化简为A。答案C。","link":""},{"id":"phy1175","t":"电阻·定义式","s":"看到【判断电阻由什么决定或比较定义式形式】","c":"想到【R=U/I是测量关系式，电阻由导体本身决定，与U、I无关】；警惕【对定值电阻R=U/I=$\\Delta$U/$\\Delta$I成立，对变化电阻二者不等，不可混用】","src":"物一轮187.电流与电阻_笔记","note":"视频|29:35-30:59","orig":"（知识）电阻定义式R=U/I（不是ΔU/ΔI）；「电阻与电压成正比、与电流成反比」说法均错误，电阻本质上与U、I无关。","link":""},{"id":"phy1176","t":"电阻·决定式与电阻率","s":"看到【由材料几何尺寸和电阻率求电阻】","c":"想到【R=$\\rho$L/S：L取沿电流方向的长度，S取垂直电流方向的横截面积，先定电流方向再取L、S】；警惕【同一导体不同流向阻值不同；$\\rho$随温度变化，普通金属电阻率受温度影响】","src":"物一轮187.电流与电阻_笔记","note":"视频|30:59-33:12","orig":"（例）长方体电阻(a×b×c)：电流沿a方向时R=ρa/(b×c)，沿c方向时R=ρc/(a×b)，同一导体不同电流方向阻值不同。合金电阻率受温度影响小可作定值电阻。","link":""},{"id":"phy1177","t":"欧姆定律·适用范围","s":"看到【判断欧姆定律能否用于某用电器】","c":"想到【先判断纯电阻还是非纯电阻：电能是否全部转化为热能】；警惕【电动机、电风扇等非纯电阻元件不能直接用I=U/R求电流】","src":"物一轮187.电流与电阻_笔记","note":"视频|34:46-36:01","orig":"（知识）局部电路欧姆定律I=U/R仅适用纯电阻（电能全转化为热能，如电阻丝、电烙铁、小灯泡）；非纯电阻（电冰箱、电风扇、电吹风）电能部分转化为机械能等，不适用。","link":""},{"id":"phy1178","t":"欧姆定律·U-I图像","s":"看到【由U-I曲线求电阻或电阻率】","c":"想到【「纵比横得阻，连线非切线」：阻值用原点连线斜率，曲线斜率变化反映阻值变化】；警惕【误用切线斜率求电阻；忽略坐标单位（mA、kV）导致数量级错误】","src":"物一轮187.电流与电阻_笔记","note":"视频|36:01-38:42","orig":"（例）电解液电阻率计算：电阻值=U-I图原点连线斜率（非切线斜率），注意mA→A单位换算，确定电流方向后选L、S。答案C（160Ω·m）。","link":""},{"id":"phy1179","t":"电阻率·图像分段计算","s":"看到【导体某图像出现斜率转折、需分段求电阻率】","c":"想到【分段建立函数关系，图像斜率与$\\rho$成正比，用斜率比代替电阻率比】；警惕【分段后电流I与截面积S若不变可直接约去，变了则要分别代入】","src":"物一轮187.电流与电阻_笔记","note":"视频|42:23-52:21","orig":"（例）ux图像斜率变化分两段：第一段斜率Iρ1/S=0.2/0.25，第二段Iρ2/S=0.3/0.75，由斜率比求电阻率比。答案B（2:1）。","link":""},{"id":"phy1180","t":"非纯电阻·电动机电路","s":"看到【串联电路中含电动机求其两端电压】","c":"想到【串联分压（总电压=各段之和）对任意电路成立；先用总电压减纯电阻段电压得非纯电阻电压】；警惕【对电动机直接用欧姆定律或按电阻比分配电压都是错误】","src":"物一轮187.电流与电阻_笔记","note":"视频|52:21","orig":"（例）电动机与定值电阻串联：先算定值电阻电压U=IR=10V，总电压33V-10V=23V得电动机电压。串联分压规律成立，但「电压比等于电阻比」仅适用纯电阻。答案C（23V）。","link":""},{"id":"phy1181","t":"电压·本质与电势参考点","s":"看到【电压表接在不是单个用电器两端的位置】","c":"想到【电压表读数=所接两点间的电势差，先设负极0V求各点电势再作差】；警惕【电势是相对量，必须先定零电势参考点才能算】","src":"物一轮188.电压与电动势_笔记","note":"视频|00:33-00:57","orig":"（知识）电压是两点之间的电势差（区别于初中「用电器两端电压」的狭义理解）；电压表可接在电路中任意两点间测电势差；通常规定电源负极为0V参考点，正极为电源电压值。","link":""},{"id":"phy1182","t":"电压·电势法求电压表读数","s":"看到【双支路并联电路中间跨接电压表求读数】","c":"想到【电势分析法：每条支路按串联分压求各节点电势，电压表读数=两点电势之差】；警惕【电压表不限定测某个元件，先识别它跨接在哪两点之间】","src":"物一轮188.电压与电动势_笔记","note":"视频|00:57-07:21","orig":"（例）R1(5Ω)与R2(5Ω)串联、R3(4Ω)与R4(6Ω)串联，两组并联接12V电源：a点电势12-6=6V，b点电势12-4.8=7.2V，电压表读数=7.2-6=1.2V。","link":""},{"id":"phy1183","t":"电动势·物理意义","s":"看到【辨析电源内部电荷如何被搬运】","c":"想到【外电路靠静电力、电源内部靠非静电力克服电场力搬运电荷，非静电力做功=其他能转化为电能】；警惕【正电荷在电源内部由负极向正极移动，方向别记反】","src":"物一轮188.电压与电动势_笔记","note":"视频|07:32-12:13","orig":"（知识）电动势描述电源非静电力做功本领：外电路静电力驱动电荷由正极→负极，电源内部需非静电力克服静电力做功由负极→正极；电源是把其他形式能转化为电能的装置。","link":""},{"id":"phy1184","t":"电动势·定义式","s":"看到【由非静电力做功与电荷量求电动势】","c":"想到【E=W非/q，反映电源转化能量的本领，由电源自身决定】；警惕【外电路变化会改变电流和路端电压，但不改变电动势】","src":"物一轮188.电压与电动势_笔记","note":"视频|12:13-13:40","orig":"（知识）E=W非/q，表示搬运单位电荷（1C）非静电力做的功；电动势是电源本身的特性量，与外电路无关。","link":""},{"id":"phy1185","t":"电压与电动势·对比辨析","s":"看到【问电动势与电压有何区别或能否等同】","c":"想到【从做功主体区分：非静电力做功$\\to$电动势（电能产生），静电力做功$\\to$电压（电能消耗）】；警惕【单位相同不代表物理量相同，二者不可直接画等号】","src":"物一轮188.电压与电动势_笔记","note":"视频|13:40","orig":"（知识）电动势对应非静电力做功（W非/q），描述电能产生；电压对应静电力做功（W/q），描述电能消耗。单位相同（伏特）但本质是不同的物理量。","link":""},{"id":"phy1186","t":"闭合电路·基本表达与术语","s":"看到【闭合电路中求电流、电压或内电压】","c":"想到【E=U外+Ir对任意电路成立；I=E/(R+r)仅在纯电阻电路可用】；警惕【区分外电压、内电压、路端电压三个说法，路端电压=外电压】","src":"物一轮189.闭合电路欧姆定律_笔记","note":"视频|00:09-04:47","orig":"（知识）E=U外+I干r，适用于任意电路结构（无论外电路纯电阻与否）；外电路纯电阻时才可推出I=E/(R+r)；路端电压即电源两端电压，与外电压实质相同。","link":""},{"id":"phy1187","t":"闭合电路·E与U外关系","s":"看到【判断路端电压与电动势的大小关系】","c":"想到【E$\\geq$U外；断路时U外=E（断路电压=电动势），短路时U外=0】；警惕【有电流通过内阻时路端电压必小于电动势，不能说二者总相等】","src":"物一轮189.闭合电路欧姆定律_笔记","note":"视频|04:47-07:26","orig":"（知识）E≥U外，恒成立；等号条件：r=0（不计内阻）或I=0（断路）。断路时路端电压数值上等于电动势。","link":""},{"id":"phy1188","t":"闭合电路·U-I图像要素","s":"看到【电源的U-I图像提取E、r、短路电流】","c":"想到【纵截距读E、横截距读I短=E/r、斜率绝对值读r；与元件伏安线的交点为工作点，矩形面积即输出功率】；警惕【非定值电阻的伏安线可能为曲线，电阻用原点连线斜率求】","src":"物一轮189.闭合电路欧姆定律_笔记","note":"视频|07:26-16:06","orig":"（知识）电源U-I图U=-rI+E为斜率为负的直线：纵截距=电动势E（断路电压），横截距=短路电流E/r，斜率绝对值=内阻r。工作点=电源线与外电阻伏安线交点，对应矩形面积=输出功率。","link":""},{"id":"phy1189","t":"闭合电路·联立方程求E和r","s":"看到【两组不同的U、I数据求电动势和内阻】","c":"想到【对每组数据列E=U+Ir联立消元；再配合局部欧姆定律逐段求各电阻】；警惕【滑片处于不同位置时外电路结构不同，先画等效电路再代数据】","src":"物一轮189.闭合电路欧姆定律_笔记","note":"视频|17:30-23:46","orig":"（例）理想电压表测外电压、电流表测干路电流，两组数据列方程组：E=16+0.2r，E=4+0.8r，解得E=20V、r=20Ω；再结合局部欧姆定律求出R2=5Ω、滑动变阻器最大值R3=300Ω。","link":""},{"id":"phy1190","t":"闭合电路·双电源图像比较","s":"看到【同一图中两条电源特性线比较E、r或功率】","c":"想到【分别从截距、斜率、与电阻线交点提取各电源参数，功率用交点UI乘积（矩形面积）计算】；警惕【区分电源特性曲线（U=-rI+E）与元件伏安特性曲线两类图线】","src":"物一轮189.闭合电路欧姆定律_笔记","note":"视频|23:46-27:06","orig":"（例）两电源U-I线纵截距均为10V，斜率绝对值给出内阻比10/7:10/11=11:7；由工作点UI乘积（矩形面积）比较功率。答案C。","link":""},{"id":"phy1191","t":"闭合电路·非零起点图像","s":"看到【U-I图纵轴不从零开始】","c":"想到【内阻必须用$\\Delta$U/$\\Delta$I差值法计算，电动势仍看纵截距；短路电流由E/r求，不是图中横轴末端读数】；警惕【把纵轴起点值当短路电压、把图线终点电流当短路电流都是高频错误】","src":"物一轮189.闭合电路欧姆定律_笔记","note":"视频|27:06","orig":"（例）U-I图纵轴从1.5V到2.0V、横轴0-0.5A：E=2.0V（纵截距），r=(2.0-1.5)/(0.5-0)=1Ω（差值法），接7Ω电阻时I=2/(7+1)=0.25A、U=1.75V。答案D。","link":""},{"id":"phy1192","t":"能量传输·能量分配框架","s":"看到【电路能量分配或总电能的计算】","c":"想到【画能量流转树：总电能EIt=内阻发热I^{2}rt+外电路获得UIt，逐级往下分】；警惕【电源总功率是EI而非U外I，二者差值为内阻消耗】","src":"物一轮190.电路中的能量传输_笔记","note":"视频|00:36-15:39","orig":"（知识）电源产生电能EI，内阻发热I²r，外电路获得U外I；能量分配树：电源总输出EIt=内阻发热I²rt+外电路能量UIt；外电路再分为发热与机械能输出。","link":""},{"id":"phy1193","t":"能量传输·含电动机电路守恒","s":"看到【含电动机电路中判断各能量表达式正误】","c":"想到【用能量守恒逐项展开：总电能减去所有发热（I^{2}rt+I^{2}Rt）才是输出机械能】；警惕【UI对非纯电阻是输入功率，I^{2}R只是其发热部分，UI>I^{2}R】","src":"物一轮190.电路中的能量传输_笔记","note":"视频|15:39-21:35","orig":"（例）电源（E、r）给电动机（电阻R、电压U、电流I）供电：I²(R+r)t只是内外发热总和；(E-Ir)It=UIt是电动机输入功率；机械能=[E-I(R+r)]It=EIt-I²rt-I²Rt，即总电能减所有发热。","link":""},{"id":"phy1194","t":"电动机·功率计算与卡住陷阱","s":"看到【电动机正常工作求机械功率或被卡住后的电流】","c":"想到【转动时：P机=UI-I^{2}R；卡住时按纯电阻处理，电流重新用I=U/R算】；警惕【卡住后电流$\\neq$工作电流，发热功率暴增是烧毁原因，也是保险丝设计依据】","src":"物一轮190.电路中的能量传输_笔记","note":"视频|21:35","orig":"（例）电风扇：P入=UI=220×0.3=66W，P热=I²R=0.3²×10=0.9W，P机=66-0.9=65.1W；卡住时转纯电阻I'=U/R=22A，发热I'²R=4840W剧增而烧毁。","link":""},{"id":"phy1195","t":"能量传输·功率术语辨析","s":"看到【「消耗功率/输入功率/发热功率/输出功率」指代不明】","c":"想到【按对象套对应公式：电源总功率EI、输出U外I、内阻热I^{2}r；电动机输入UI、热I^{2}R、机械UI-I^{2}R】；警惕【同一题干中相同措辞可能指不同功率，须结合上下文定位对象】","src":"物一轮190.电路中的能量传输_笔记","note":"视频|21:35","orig":"（知识）总功率=输入功率=EI（电源侧）或UI（用电器侧）；内阻功率=I²r；输出功率=外电路功率=U外I；电动机机械功率=UI-I²R。","link":""},{"id":"phy1196","t":"输出功率·外阻变化求最大值","s":"看到【外电阻变化、内阻固定，求电源最大输出功率】","c":"想到【「内外相等功率大」：R=r时Pmax=E^{2}/4r；前提是纯电阻电路】；警惕【该结论不能用于含电动机等非纯电阻元件的电路】","src":"物一轮191.电源的输出功率及效率_笔记","note":"视频|00:45-06:04","orig":"（知识）纯电阻电路、内阻定值时：P=I²R=E²R/(R+r)²=E²/(R+r²/R+2r)，由均值不等式R+r²/R≥2r，当R=r时输出功率最大Pmax=E²/4r；P-R图先增后减在R=r处峰值。","link":""},{"id":"phy1197","t":"输出功率·内阻变化情形","s":"看到【题目变的是内阻而非外电阻求功率极值】","c":"想到【内阻越小输出功率越大，内阻趋于零时达最大E^{2}/R外】；警惕【与R=r结论是两种不同情形，先分清变化的是内阻还是外阻】","src":"物一轮191.电源的输出功率及效率_笔记","note":"视频|06:04-08:14","orig":"（知识）内阻变化、外阻定值时：内阻越小输出功率越大；极限情况内阻为零时功率最大为E²/R。","link":""},{"id":"phy1198","t":"电源效率·公式与特点","s":"看到【求电源效率或比较不同外阻下效率高低】","c":"想到【$\\eta$=U外/E通用；纯电阻时$\\eta$=R/(R+r)，外阻越大效率越高】；警惕【输出功率最大（R=r，效率仅50%）与效率最高不是同一条件】","src":"物一轮191.电源的输出功率及效率_笔记","note":"视频|08:14-10:07","orig":"（知识）η=输出功率/输入功率×100%；通用式η=U外/E×100%适用于任意电路；纯电阻特例η=R/(R+r)×100%；效率随外阻增大而提高。","link":""},{"id":"phy1199","t":"输出功率·等效电源法","s":"看到【求电路中某个可变电阻的最大功率】","c":"想到【等效电源法：把其余定值电阻并入内阻，对新「电源」套R=r'结论】；警惕【定值电阻功率最大对应电流最大（等效内阻越小越好），不能套用内外阻相等】","src":"物一轮191.电源的输出功率及效率_笔记","note":"视频|10:07-19:27","orig":"（例）将部分外电阻等效为「新电源」内阻：R总=r时Pmax=12²/(4×2)=18W；将R1并入内阻得新内阻3Ω，R2=3Ω时Pmax=12W；定值电阻功率在R2=0电流最大时最大16W。","link":""},{"id":"phy1200","t":"输出功率·变阻器功率图像","s":"看到【P-R图像纵轴是滑动变阻器（非电源总输出）功率】","c":"想到【峰值条件需按含定值电阻的实际电路重新推导，或用等效电源法；图像上两个等功率点可列方程组求E、r】；警惕【把变阻器功率曲线的峰值条件直接当成R=r会出错】","src":"物一轮191.电源的输出功率及效率_笔记","note":"视频|19:27","orig":"（例）纵轴为滑动变阻器功率的图像不能直接套R=r：建立P=E²Rp/(R+Rp+r)²，由已知点(8Ω,0.4W)和(2Ω,0.4W)列方程组，解得E=4V、r=2Ω。","link":""},{"id":"phy1201","t":"动态分析·基本框架","s":"看到【滑动变阻器阻值变化引起各电学量连锁变化】","c":"想到【逻辑链：局部电阻变化$\\to$总电阻$\\to$干路电流I=E/(R外+r)$\\to$路端电压U=E-Ir$\\to$支路电学量】；警惕【跳步直接猜电表示数易错，先判结构再逐层推】","src":"物一轮192.常规电路动态分析_笔记","note":"视频|01:18-07:33","orig":"（知识）「局部→整体→局部」：先判串并联结构，再判断局部电阻变化对总电阻的影响，用闭合电路欧姆定律定干路电流和路端电压，最后按串并联规律细化到各支路。","link":""},{"id":"phy1202","t":"动态分析·总电阻变化规律","s":"看到【判断局部电阻变化导致总电阻如何变】","c":"想到【无论串并联，任一局部电阻增大总电阻同向增大；开关闭合=并入支路，总电阻减小】；警惕【并联「同增同减」易记反；分压接法要先明确有效接入部分】","src":"物一轮192.常规电路动态分析_笔记","note":"视频|01:28-07:33","orig":"（知识）串联R总=R1+R2、并联1/R总=1/R1+1/R2中任一电阻增大则总电阻增大；开关闭合等效为支路电阻从∞变为有限值，使并联总电阻减小。","link":""},{"id":"phy1203","t":"动态分析·三表示数例题","s":"看到【滑片移动后判断多个电压表电流表示数变化】","c":"想到【优先分析定值电阻支路（控制变量），串联支路电流用干路与并联支路电流相减求变化，逐级推导】；警惕【U2这类「两变化量之差」不能直接判，需借助另一段电压间接确定】","src":"物一轮192.常规电路动态分析_笔记","note":"视频|09:08-16:04","orig":"（例）R1与R2串联后与R3并联：滑片上移→R2减小→总外阻减小→I干增大、U路减小→R3电流I3=U路/R3减小→串联支路I串=I干-I3增大→U1增大、U2=U路-U1减小。结论：A↑、V1↑、V2↓。","link":""},{"id":"phy1204","t":"动态分析·串反并同技巧","s":"看到【需要快速判断多处电学量变化方向】","c":"想到【串反并同：与变化电阻广义串联的元件其电流电压功率反向变化，广义并联的同向变化；广义串联=能形成回路即可】；警惕【适用条件：仅一处电阻变化、电源有内阻且E、r恒定；复杂题优先基本方法】","src":"物一轮192.常规电路动态分析_笔记","note":"视频|22:08-23:23","orig":"（例）滑片上移R2减小：电流表与R2广义串联→「串反」→示数增大；V1与R2广义串联→增大；V2与R2并联→「并同」→减小。","link":""},{"id":"phy1205","t":"动态分析·定值与变化电阻的ΔU/ΔI","s":"看到【对变化电阻问U/I或$\\Delta$U/$\\Delta$I的值】","c":"想到【定值电阻两个式子相等；变化电阻只能用U/I（原点连线斜率），$\\Delta$U/$\\Delta$I是另一含义需另求】；警惕【把$\\Delta$U/$\\Delta$I直接当成变化电阻的阻值是高频错误】","src":"物一轮192.常规电路动态分析_笔记","note":"视频|29:53-32:55","orig":"（知识）定值电阻满足R=U/I=ΔU/ΔI（过原点直线）；变化电阻仅满足R=U/I≠ΔU/ΔI（曲线）；U/I对应原点连线斜率，ΔU/ΔI对应两点连线斜率。","link":""},{"id":"phy1206","t":"动态分析·变化量间接求解","s":"看到【求变化电阻的$\\Delta$U/$\\Delta$I（含负号的比值）】","c":"想到【借助电动势守恒：变化电阻电压变化=其余各段（含内阻）电压变化之和的相反数，转化为定值电阻与内阻之和的负值】；警惕【变化量符号别丢，结果通常是-(r+某定值电阻)形式】","src":"物一轮192.常规电路动态分析_笔记","note":"视频|32:55","orig":"（例）滑片下移R0减小：对变化电阻R2，ΔU2/ΔI=-(r+R1)（由电动势守恒ΔU2=-Δ(U内+U1)推导）；对U3=U路，ΔU3/ΔI=-r。答案B、D。","link":""},{"id":"phy1207","t":"含容电路·等效简化方法","s":"看到【含容电路求电容器电压/电荷量，或含容动态分析】","c":"想到【电容器稳态等效为电压表、同支路串联电阻当导线，先化简成常规电路再算 U_C，Q=CU_C；动态分析先定 U_C 怎么变】；警惕【把与电容器串联电阻的分压算进电容器电压】","src":"物一轮193.含容电路动态分析_笔记","note":"视频|00:07-04:07","orig":"（知识）电路稳定时电容器等效为电压表，与电容器直接串联的电阻（同支路）等效为导线、两端电压为零；用「去电容化」把含容电路转为常规电路，重点求电容器电压 U_C 与电荷量 Q=CU_C。","link":""},{"id":"phy1208","t":"含容电路·电容器受力分析","s":"看到【电容器极板间悬挂/支持着带电小球，问拉力或电场力变化】","c":"想到【先等效求 U_C 的变化，再用 F_E=qU_C/d 链式分析受力；与电容器同支路的电阻调节无效】；警惕【未做电路等效就直接分析，或混淆改变 d 对 E=U/d 的影响】","src":"物一轮193.含容电路动态分析_笔记","note":"视频|04:07-08:23","orig":"（例）增大 R2 使 R0 分压减小→U_MN↓→电场力 F_E↓→拉力 F↓；调节与电容器同支路的 R1 无效；答案选「上移 M 板不改变场强」的选项。关键技巧：先完成电路等效，再结合 F_E=qE=qU/d 分析受力。","link":""},{"id":"phy1209","t":"含容电路·开关状态改变","s":"看到【开关闭合或断开前后比较电容器电荷量/电压】","c":"想到【开关改变电路拓扑，断开、闭合各画一次等效电路再分别求 U_C】；警惕【忽略开关闭合导致的短路效应而算错等效电阻】","src":"物一轮193.含容电路动态分析_笔记","note":"视频|08:23","orig":"（例）S 断开时等效为两电阻串联与第三电阻并联，U1=E/2，Q1=CE/2；S 闭合时上方电阻被短路，U2=E，Q2=CE；Q1:Q2=1:2。","link":""},{"id":"phy1210","t":"含容电路·动态分析技巧","s":"看到【滑动变阻器阻值变化引起电容器电压、带电粒子受力变化】","c":"想到【按「电阻变化$\\to$定值电阻分压变化$\\to$U_C 变化$\\to$E=U/d$\\to$F=qE」的链条逐步分析】；警惕【对变化电阻直接套用 $\\Delta$U/$\\Delta$I=U/I】","src":"物一轮193.含容电路动态分析_笔记","note":"视频|00:07-04:07","orig":"（知识）动态分析先确定 U_C 变化，再由 E=U/d 求比例关系；口诀「容变表，串变线，电压决定Q大小」；定值电阻 ΔU/ΔI=U/I 成立，变化电阻不适用，优先分析定值电阻。","link":""},{"id":"phy1211","t":"磁场·模块主线","s":"看到【磁场模块整体复习规划】","c":"想到【按主线推进：先基础量与场线，再两大磁场力，最后带电粒子在场中运动专题；复合场大题是压轴高频】；警惕【只刷受力判断而跳过粒子运动专题】","src":"物一轮194.【课前必看】本讲听课建议_笔记","note":"视频|00:14-01:15","orig":"（知识）磁场模块主线：磁感应强度、磁感线→安培力（左手定则、大小计算）→洛伦兹力（对象为运动电荷）→有界磁场、电磁组合场、电磁叠加场专题；后三节高考常以大题形式出现。","link":""},{"id":"phy1212","t":"磁场·考向与题型","s":"看到【磁场选择题或解答题的命题方向判断】","c":"想到【选择题主攻 B 矢量叠加、地磁场、有效长度；解答题主攻粒子圆周运动与电磁感应综合；压轴常考复合场】；警惕【忽视地磁场单独命题的可能】","src":"物一轮194.【课前必看】本讲听课建议_笔记","note":"视频|03:51-04:32","orig":"（知识）电磁场合计约占高考内容 60%；选择题常考磁感应强度矢量叠加、地磁场、安培力有效长度；解答题常考带电粒子在磁场中运动（有界磁场/组合场/叠加场）及安培力与电磁感应综合。","link":""},{"id":"phy1213","t":"磁场·近年高频考点","s":"看到【安培力有效长度或地磁场空间转化类新题】","c":"想到【安培力有效长度、洛伦兹力特点、地磁场空间方位转化是近年高频，优先级依次为：有效长度＞洛伦兹力特点＞地磁场转化】；警惕【轻视磁感线分布这类基础考点】","src":"物一轮194.【课前必看】本讲听课建议_笔记","note":"视频|07:02-08:14","orig":"（知识）近年典型考题分布：磁感应强度叠加（21福建、21全国、20浙江）、常见磁场磁感线（24贵州、21浙江、20北京）、地磁场（23福建、22全国）、安培力（22江苏、24重庆）、洛伦兹力（24浙江、22北京）。","link":""},{"id":"phy1214","t":"磁感应强度·定义式","s":"看到【磁感应强度定义式或判断 B 是否与试探导线有关】","c":"想到【类比 E=F/q 记忆 B=F/IL，B 由磁场本身决定，与试探导线无关】；警惕【误认为 B 随试探电流或导线长度改变】","src":"物一轮195.磁感应强度_笔记","note":"视频|01:39-05:38","orig":"（知识）定义式 B=F/(IL)，F 为通电导线所受安培力；类比电场 E=F/q，都是「试探物体所受的力÷试探物体自身属性量」，B 大小与试探导线无关，由磁场本身决定。","link":""},{"id":"phy1215","t":"磁感应强度·垂直条件","s":"看到【导线与磁场不垂直时求磁感应强度或安培力】","c":"想到【定义式只在 B$\\perp$I 时成立；导线与磁场平行时不受力】；警惕【不加垂直条件直接套用定义式】","src":"物一轮195.磁感应强度_笔记","note":"视频|05:38-07:22","orig":"（知识）B=F/(IL) 成立前提是磁场方向与电流方向垂直：导线与磁场平行时 F=0，有夹角时受力变化；电场中试探电荷是点电荷，无此垂直条件。","link":""},{"id":"phy1216","t":"磁感应强度·决定式","s":"看到【通电直导线周围某点磁场强弱比较】","c":"想到【B∝I/r，I 越大、离导线越近磁场越强；类比 E=kQ/r^{2} 记忆】；警惕【把 B∝I/r 用于磁体产生的磁场】","src":"物一轮195.磁感应强度_笔记","note":"视频|07:22-11:43","orig":"（知识）电场决定式 E=kQ/r²，由场源电荷决定；磁场决定式 B∝I/r（高中为比例关系，不定量计算），由场源导线决定，仅适用于通电导线产生的磁场，不适用于磁体。","link":""},{"id":"phy1217","t":"磁感应强度·方向判断","s":"看到【判断某点磁感应强度方向】","c":"想到【用小磁针 N 极指向或磁感线切线；通电导线用右手螺旋定则】；警惕【仿照电场用受力方向判断磁场方向——安培力与 B 垂直，行不通】","src":"物一轮195.磁感应强度_笔记","note":"视频|11:43-14:22","orig":"（知识）磁场方向三种判法：小磁针静止时 N 极指向、磁感线切线方向、右手螺旋定则；不能用安培力方向判断，因为安培力与磁场方向垂直。口诀「谁弯谁是四指方向，谁直谁是大拇指方向」。","link":""},{"id":"phy1218","t":"磁感应强度·矢量叠加","s":"看到【多条长直导线在某点产生的磁场叠加】","c":"想到【先画以导线为圆心的圆确定切线方向，等大反向先抵消，剩余矢量再按平行四边形法则合成】；警惕【混淆 ⊗（电流向里）与 ⊙（电流向外），或漏掉矢量方向判断】","src":"物一轮195.磁感应强度_笔记","note":"视频|17:05-31:00","orig":"（例）正方形四顶点四条等电流平行长直导线，a 点电流向里其余向外：O 点 b、c 磁场等大反向抵消，a、d 同向叠加，合场由 O 指向 c；e 点 c、d 抵消，a、b 合成沿 y 轴负方向。答案 A。","link":""},{"id":"phy1219","t":"磁感应强度·导线磁场加外磁场","s":"看到【导线磁场与匀强外磁场叠加，已知合磁场反求分量】","c":"想到【先用右手螺旋定各场源方向，再利用对称性设分量，规定正方向后列矢量方程组求解；外磁场作为独立场源参与叠加】；警惕【矢量加减时符号出错或漏掉外磁场】","src":"物一轮195.磁感应强度_笔记","note":"视频|31:00","orig":"（例）两互相垂直长直导线加垂直纸面向外的匀强磁场 B0，a、b 两点关于 L2 对称且到 L1 等距，合磁场分别为 B0/3、B0/2；规定向外为正列矢量方程组，解得 B1=7B0/12、B2=B0/12。答案 B。","link":""},{"id":"phy1220","t":"磁感线·基本特性","s":"看到【判断磁感线与电场线特性的说法正误】","c":"想到【疏密表大小、切线表方向；磁感线闭合、电场线不闭合】；警惕【把磁感线当成真实存在的线，或忽略其闭合性】","src":"物一轮196.常见磁感线_笔记","note":"视频|00:20-01:44","orig":"（知识）磁感线是假想曲线：疏密反映磁感应强度大小，切线方向反映 B 方向；磁感线是闭合曲线，与电场线（正电荷出发终止于负电荷）的关键区别在于闭合性。","link":""},{"id":"phy1221","t":"常见磁场·条形磁铁","s":"看到【条形磁铁内部/外部磁场走向或与等量异种电荷电场线对比】","c":"想到【外 N$\\to$S、内 S$\\to$N，内外条数相等；与异种电荷电场线只比形状、不比闭合性】；警惕【漏掉磁铁内部的闭合路径】","src":"物一轮196.常见磁感线_笔记","note":"视频|01:44-03:41","orig":"（知识）条形磁铁外部磁感线从 N 极出发回到 S 极，内部从 S 极回到 N 极形成闭合回路，内外磁感线数量相同；分布形状与等量异种电荷电场线相似，但本质区别是闭合性。","link":""},{"id":"phy1222","t":"常见磁场·通电直导线","s":"看到【通电直导线周围磁场分布或俯视/主视图中的点叉表示】","c":"想到【同心圆、近密远疏，B∝I/r；方向由右手螺旋定则定，视图转换时点叉对应】；警惕【点叉与电流方向对应关系记反】","src":"物一轮196.常见磁感线_笔记","note":"视频|03:41-05:53","orig":"（知识）通电直导线磁场为以导线为中心的同心圆，越靠近导线越密集（B∝I/r）；俯视电流向外时磁场逆时针，主视图左侧点（向外）、右侧叉（向里）；方向用右手螺旋定则。","link":""},{"id":"phy1223","t":"常见磁场·通电线圈与螺线管","s":"看到【环形电流或通电螺线管的磁场方向/磁极判断】","c":"想到【环形电流内点外叉；螺线管用右手螺旋定则——四指随电流、拇指指 N 极】；警惕【环内与环外磁场方向相反，勿混用】","src":"物一轮196.常见磁感线_笔记","note":"视频|05:53-07:35","orig":"（知识）通电线圈环内磁场均匀、环外发散，环内外磁感线数量相同（闭合性要求）；通电螺线管可视为多个通电线圈的叠加，四指环绕电流方向、大拇指指向 N 极。","link":""},{"id":"phy1224","t":"常见磁场·地磁场","s":"看到【地磁场极性、成因或飞机/电缆切割地磁场类问题】","c":"想到【地理北极附近是地磁南极；成因是地表负电荷随自转的环形电流，电流方向与自转方向相反；磁偏角一般忽略】；警惕【地磁极与地理极对应关系记反】","src":"物一轮196.常见磁感线_笔记","note":"视频|07:35-11:09","orig":"（知识）地磁南极位于地理北极附近，地磁北极位于地理南极附近；主要源于地表负电荷随地球自转形成的环形电流；存在磁偏角但解题通常忽略。","link":""},{"id":"phy1225","t":"常见磁场·场线对比判断","s":"看到【电场线与磁感线混合判断、对称点场强比较】","c":"想到【先看闭合性区分电场线与磁感线，再由对称性定场强大小与方向】；警惕【把相似形状误认为性质相同】","src":"物一轮196.常见磁感线_笔记","note":"视频|11:09-13:52","orig":"（例）同种电荷电场线向外发散，条形磁铁（异种电荷）场线闭合；对称的 P、Q 两点场强大小方向均相同；答案 AD。","link":""},{"id":"phy1226","t":"常见磁场·地磁场成因计算","s":"看到【地球电荷量或自转角速度变化对地磁场的影响】","c":"想到【按 I=q/t 分析：电量↑或周期↓都使电流增大、磁场增强；先定电荷电性再定电流方向】；警惕【电流方向与自转方向的关系判断错误】","src":"物一轮196.常见磁感线_笔记","note":"视频|13:52-16:29","orig":"（例）I=q/t，ω 影响 t：地表负电荷由右手定则判断；电量增加→电流增大→磁场增强；角速度减小→周期增大→电流减小→磁场减弱。答案 AC。","link":""},{"id":"phy1227","t":"安培力·左手定则内容","s":"看到【判断通电导线在磁场中所受安培力方向】","c":"想到【左手定则：磁穿掌心、四指为 I、拇指为 F；安培力垂直于 B 与 I 构成的平面】；警惕【掌心朝向与磁场方向记反——磁场箭头尖扎掌心】","src":"物一轮197.安培力的方向——左手定则_笔记","note":"视频|00:47-04:15","orig":"（知识）磁场垂直穿过掌心、四指指电流方向、大拇指指安培力方向；磁场向里掌心冲外、向外掌心冲里；大拇指（F）、四指（I）、掌心（B）三者两两垂直，安培力始终垂直于电流与磁场构成的平面。","link":""},{"id":"phy1228","t":"安培力·平面图方向判断","s":"看到【纸面内给出 B 与 I 方向求安培力方向】","c":"想到【按「磁场对应掌心、四指对电流」逐一定位再读出拇指方向；立体感不强时想象手掌的立体摆放】；警惕【掌心朝向与磁场方向混淆】","src":"物一轮197.安培力的方向——左手定则_笔记","note":"视频|04:15-05:27","orig":"（例）磁场垂直纸面向里、电流竖直向上→安培力向左；磁场水平向右、电流竖直向上→安培力垂直纸面向里。","link":""},{"id":"phy1229","t":"安培力·线面垂直关系","s":"看到【磁场垂直纸面而电流斜向，怀疑二者不垂直】","c":"想到【线面垂直原理：B 垂直纸面则与纸面内任意方向的电流都垂直，直接用左手定则】；警惕【被斜向电流误导，误认为磁场与电流不垂直】","src":"物一轮197.安培力的方向——左手定则_笔记","note":"视频|05:27-06:32","orig":"（例）磁场垂直纸面向外、电流在纸面内斜向右上：磁场与纸面内任意电流方向均垂直，掌心朝里、四指沿电流，安培力朝左下。","link":""},{"id":"phy1230","t":"安培力·不垂直时的分解","s":"看到【磁场与电流不垂直时求安培力方向或大小】","c":"想到【优先分解磁场，取垂直于电流的分量产生安培力；分解电流也可，结果一致】；警惕【忘记平行分量不产生安培力】","src":"物一轮197.安培力的方向——左手定则_笔记","note":"视频|06:32-11:03","orig":"（例）磁场水平向左、电流斜向右上（不垂直）：把磁场分解为垂直电流的 B1（产生安培力）与平行电流的 B2（不产生力），用 B1 判断得安培力垂直纸面向外；分解电流结果一致。","link":""},{"id":"phy1231","t":"安培力·立体图降维处理","s":"看到【三维立体图中的安培力方向判断】","c":"想到【降维：把三维图转为主视/俯视等二维视图，优选使电流垂直纸面的视角，必要时多视角互验】；警惕【立体图中垂直关系不明显而误判不垂直】","src":"物一轮197.安培力的方向——左手定则_笔记","note":"视频|11:03","orig":"（例）立体图中主视图（电流垂直纸面向外、磁场竖直向上）判断安培力向左，俯视图验证结果一致；斜向磁场、电流垂直纸面时同理，线面垂直关系仍满足，安培力朝左上。","link":""},{"id":"phy1232","t":"安培力·大小公式与夹角","s":"看到【求安培力大小或判断 B、I 成角度时的受力】","c":"想到【F=BILsin$\\theta$，$\\theta$ 由箭头尾部重合后的方向夹角确定；B∥I 时不受安培力】；警惕【直接量图中两条线的夹角而未平移箭头】","src":"物一轮198.安培力的大小_笔记","note":"视频|00:35-01:54","orig":"（知识）F=BILsinθ，θ 是电流 I 与磁场 B 的方向夹角：把两箭头尾部平移重合后取所夹最小角；B⊥I 时 F=BIL 最大，B∥I 时 sinθ=0、F=0。","link":""},{"id":"phy1233","t":"安培力·有效长度","s":"看到【折导线、弯曲导线在匀强磁场中求安培力】","c":"想到【非直导线取首尾连线长度作 L，电流方向取首尾连线方向；或分段计算后矢量合成，两法等价】；警惕【各段电流不一致时滥用有效长度法】","src":"物一轮198.安培力的大小_笔记","note":"视频|01:54-04:56","orig":"（例）两段垂直的折导线在匀强磁场中：分段法各段受力 BIL，合成 2BIL；有效长度法连首尾得 L'=2L，同样得 2BIL，两法一致。","link":""},{"id":"phy1234","t":"安培力·线框与并联分流","s":"看到【线框、多支路导体框整体或某边受安培力】","c":"想到【先按并联分流定各支路电流关系，再用有效长度+左手定则求各支路力后合成】；警惕【忽略支路电流不同，直接按同一电流计算】","src":"物一轮198.安培力的大小_笔记","note":"视频|04:56-15:51","orig":"（例）等边三角形线框三边电阻相同，MN 边接电源受力 2F：MLN 支路电阻是 MN 的 2 倍、电流为 I/2，等效为从 M 到 N 的直导线受力 F，方向同为向上，总力 3F。答案 C。","link":""},{"id":"phy1235","t":"安培力·平行直导线相互作用","s":"看到【两平行直导线通电流判断吸引或排斥、比较力的大小】","c":"想到【同向电流相吸、异向电流相斥（无外磁场时成立）；以一根为场源、另一根受力的分步推导；F∝I_{1}I_{2}，两电流各变 n 倍则力变 n^{2} 倍】；警惕【有其他外磁场干扰时结论不成立】","src":"物一轮198.安培力的大小_笔记","note":"视频|15:51-19:30","orig":"（例）开关接 a、b 时两平行导线电流始终反向，相互排斥；接 b 时两边电流都加倍，B∝I 使磁场加倍、受力再乘电流，F_b=4F_a。答案 D。","link":""},{"id":"phy1236","t":"安培力·环形电流与螺线管等效","s":"看到【环形电流/通电线圈在磁铁附近判断转动与靠近远离】","c":"想到【等效思想：环形电流等效为小磁针，通电螺线管等效为条形磁铁，转化为磁极间相互作用快速判断】；警惕【等效后的 N/S 极方向定错】","src":"物一轮198.安培力的大小_笔记","note":"视频|19:30-21:27","orig":"（例）通电线圈在磁铁 N 极附近：等效为小磁针，由右手螺旋定则定 N 极指向纸面内，N 极被排斥、S 极被吸引→线圈顺时针转动且靠近磁铁。答案 A。","link":""},{"id":"phy1237","t":"安培力·斜面临界平衡","s":"看到【通电导体棒静止在斜面上求电阻/电流范围】","c":"想到【静摩擦方向两可$\\to$按下滑、上滑两个临界分别列平衡方程，得安培力范围$\\to$电流范围$\\to$电阻范围；立体图先转为电流垂直纸面的平面图】；警惕【只算一个临界方向漏解】","src":"物一轮198.安培力的大小_笔记","note":"视频|21:27-30:47","orig":"（例）导体棒静止在斜面导轨上：阻值大→电流小→安培力小，棒有下滑趋势，mg·sinθ=BIL+f；阻值小→安培力大，有上滑趋势，BIL=mg·sinθ+f；临界时 f=μmg·cosθ，由闭合电路欧姆定律求滑动变阻器阻值范围（1.6Ω~16Ω）。答案 C。","link":""},{"id":"phy1238","t":"安培力·悬挂导线受力分析","s":"看到【通电导线被绳/悬线悬挂静止于磁场中，判断磁场方向的可能性】","c":"想到【立体图转平面图后按「先场力后接触力」受力分析，用共点力平衡或矢量三角形求解】；警惕【受力分析顺序颠倒，或安培力方向与绳不共线仍认为可平衡】","src":"物一轮198.安培力的大小_笔记","note":"视频|30:47-36:18","orig":"（例）通电直导线由悬线静止悬挂：先画场力（重力、安培力）再画接触力（绳拉力）；磁场沿 y 正向时安培力向上可与重力平衡、绳无拉力；沿 z 负向时三力平衡 BIL=mg·tanθ。答案 BC。","link":""},{"id":"phy1239","t":"安培力·电磁弹射功能问题","s":"看到【电磁炮/导轨弹射类安培力做功求速度】","c":"想到【安培力做功=动能变化（动能定理）；导轨磁场由电流产生，B∝I，电流变 n 倍则力变 n^{2} 倍】；警惕【只把电流加倍而不让 B 同步加倍】","src":"物一轮198.安培力的大小_笔记","note":"视频|36:18-41:35","orig":"（例）电磁枪弹体在导轨磁场中受安培力加速：F·L=½mv² 得 F=mv²/(2L)；电流变 2I 时磁场也变 2B，安培力变 4F，速度变 2 倍；轨道长度变 2L 时动能与速度平方都变 2 倍。答案 C。","link":""},{"id":"phy1240","t":"洛伦兹力·定义与受力对象","s":"看到【辨析安培力与洛伦兹力的区别】","c":"想到【受力对象不同：安培力对电流/导线，洛伦兹力对运动电荷】；警惕【把两者受力对象混为一谈】","src":"物一轮199.洛伦兹力的特点_笔记","note":"视频|00:06-01:21","orig":"（知识）安培力是磁场对通电导线（电流）的作用力，洛伦兹力是磁场对运动电荷的作用力，本质区别在受力对象不同。","link":""},{"id":"phy1241","t":"洛伦兹力·大小公式","s":"看到【求运动电荷在磁场中受洛伦兹力大小】","c":"想到【f=qvBsin$\\theta$；速度与磁场平行时无洛伦兹力，垂直时最大】；警惕【v∥B 时仍给粒子算洛伦兹力】","src":"物一轮199.洛伦兹力的特点_笔记","note":"视频|01:21-02:15","orig":"（知识）f=qvBsinθ，θ 为速度方向与磁场方向的夹角；θ=0°或180°（速度与磁场平行）时 f=0，θ=90° 时最大 f=qvB。","link":""},{"id":"phy1242","t":"洛伦兹力·方向左手定则","s":"看到【判断运动电荷所受洛伦兹力方向】","c":"想到【左手定则：磁穿掌心、拇指为力；正电荷四指沿运动方向，负电荷四指与运动方向相反】；警惕【负电荷四指方向不反向导致力方向判反】","src":"物一轮199.洛伦兹力的特点_笔记","note":"视频|02:15-05:35","orig":"（例）磁场垂直纸面向里、正电荷斜向右上运动→四指同向，洛伦兹力指向左上；磁场向外、负电荷同速运动→四指取反向，洛伦兹力仍指左上。","link":""},{"id":"phy1243","t":"洛伦兹力·垂直与不做功特性","s":"看到【判断洛伦兹力做功或速度大小是否变化】","c":"想到【f$\\perp$v$\\Rightarrow$洛伦兹力永不做功，只改变速度方向、不改变速率】；警惕【用动能定理给洛伦兹力计功】","src":"物一轮199.洛伦兹力的特点_笔记","note":"视频|05:35-26:19","orig":"（知识）洛伦兹力始终与速度垂直（f⊥v），永不做功、不改变速度大小；仅受洛伦兹力时速度方向持续改变，粒子做曲线运动。","link":""},{"id":"phy1244","t":"洛伦兹力·匀速圆周运动公式","s":"看到【带电粒子仅在磁场中做匀速圆周运动，比较半径、周期或求螺距】","c":"想到【r=mv/(qB)（∝p/q）、T=2$\\pi$m/(qB) 与速度无关；v 与 B 不垂直时按螺旋线处理，重点用垂直分量】；警惕【认为周期随速度变化】","src":"物一轮199.洛伦兹力的特点_笔记","note":"视频|05:35-26:19","orig":"（知识）v⊥B 且仅受洛伦兹力时做匀速圆周运动，洛伦兹力提供向心力：半径 r=mv/(qB)=p/(qB)，与动量成正比；周期 T=2πm/(qB)，与速度无关；v 与 B 有夹角时分解为平行分量（匀速直线）与垂直分量（圆周），合成等距螺旋线，螺距 h=v∥T。","link":""},{"id":"phy1245","t":"洛伦兹力·动量相同比例比较","s":"看到【两粒子动量相同（或速度相同）在同一磁场中比较 r、T、v、F】","c":"想到【用 r=p/(qB)、T=2$\\pi$m/(qB)、F=qvB 统一写成比例式，先把动量或速度关系代入再比】；警惕【动量相同误当速度相同使用】","src":"物一轮199.洛伦兹力的特点_笔记","note":"视频|05:35-26:19","orig":"（例）α粒子（He²⁺）与质子动量相同、在同一磁场中：r∝p/q 得半径比 1:2（选项错）；T∝m/q 得 2:1（对）；v∝1/m 得 1:4（对）；F=qvB 得 1:2（错）。答案 BC。","link":""},{"id":"phy1246","t":"洛伦兹力·轨迹反推与变力动力学","s":"看到【由圆轨迹半径变化反推粒子运动方向/电性，或含洛伦兹力的动态减速问题】","c":"想到【先由 r∝v 定穿行方向，再由左手定则定电性；含洛伦兹力的动力学按「速度变化$\\to$洛伦兹力变化$\\to$弹力/摩擦力联动$\\to$加速度变化」动态链分类讨论，由初始 qv_{0}B 与 mg 比较定运动类型】；警惕【忽略速度衰减条件或末状态匀速条件判断错误】","src":"物一轮199.洛伦兹力的特点_笔记","note":"视频|26:19","orig":"（例）粒子穿铝板后速度减小、r∝v，由 rⅠ<rⅡ 判断粒子从Ⅱ穿向Ⅰ，再由左手定则结合磁场向外定粒子带负电。答案 D。带电圆环类：qv₀B=mg 匀速直线；qv₀B<mg 加速度增大的减速至停止；qv₀B>mg 加速度减小的减速至最终匀速。","link":""},{"id":"phy1247","t":"安培力与洛伦兹力·表达式推导","s":"看到【由安培力公式推导洛伦兹力公式或电流微观表达式 I=nqSv】","c":"想到【路径：B=F/IL$\\to$F=BILsin$\\theta$$\\to$代入 I=nqSv 微观化$\\to$f=qvBsin$\\theta$】；警惕【忘记公式 F=BIL 成立的前提是 B$\\perp$I】","src":"物一轮200.了解安培力和洛伦兹力关系_笔记","note":"视频|01:18-09:44","orig":"（知识）安培力由定义式 B=F/(IL) 在 B⊥I 时得 F=BIL，有夹角时分解得 F=BILsinθ；洛伦兹力将电流微观式 I=nqSv 代入安培力公式，除以电荷总数 N=nSL 后得 f=qvBsinθ。","link":""},{"id":"phy1248","t":"安培力与洛伦兹力·宏观微观联系","s":"看到【概念辨析题考安培力与洛伦兹力的关系】","c":"想到【宏观对微观：安培力对应大量洛伦兹力的合力；电流的微观本质是电荷定向移动】；警惕【把「安培力是洛伦兹力的宏观表现」当成严谨表述，做功问题需修正】","src":"物一轮200.了解安培力和洛伦兹力关系_笔记","note":"视频|09:44-11:09","orig":"（知识）电流是运动电荷的宏观表现，运动电荷是电流的微观本质；初步理解：安培力是大量洛伦兹力的宏观表现，洛伦兹力是安培力的微观本质（考虑做功时需修正）。","link":""},{"id":"phy1249","t":"安培力与洛伦兹力·做功差异","s":"看到【安培力做功而洛伦兹力不做功的矛盾或导棒中电荷做功分析】","c":"想到【按合速度分解出两个洛伦兹力分量，一正功一负功恰好抵消，总功恒为零；安培力可做功，洛伦兹力永不做功】；警惕【认为「洛伦兹力是安培力的微观本质」就意味着安培力也不做功】","src":"物一轮200.了解安培力和洛伦兹力关系_笔记","note":"视频|11:58-22:02","orig":"（知识）导棒模型中电荷实际速度 v 为随导棒运动速度 v1 与沿导棒速度 v2 的矢量和，产生两个洛伦兹力分量：f1=qv2B 做正功 W1=qv2B·v1Δt，f2=qv1B 做负功 W2=-qv1B·v2Δt，总功为零，验证洛伦兹力永不做功；安培力可以做功（如电动机）。","link":""},{"id":"phy1250","t":"安培力与洛伦兹力·修正关系与能量守恒","s":"看到【选择题考安培力微观本质或其做功的能量来源】","c":"想到【安培力=洛伦兹力垂直分力的宏观表现；安培力做功的能量由电路/电磁感应机制守恒转化】；警惕【概念题直接写「安培力是洛伦兹力的宏观表现」这种不严谨说法】","src":"物一轮200.了解安培力和洛伦兹力关系_笔记","note":"视频|22:02","orig":"（知识）严谨表述：安培力仅是洛伦兹力垂直导棒分力 f1 的宏观表现，平行导棒分力 f2 对应电磁感应现象；做功差异源于分力一正一负相互抵消，宏观做功对应微观分力做功的代数和，保持能量守恒。","link":""},{"id":"phy1251","t":"磁场·安培力冲量","s":"看到【求安培力的冲量】","c":"想到【安培力冲量 Ia=BILt；电流恒定时由 I=q/t 可化为 Ia=BLq】；警惕【符号 Ia 与电流 I 区分，勿混用】","src":"物一轮201.磁场力中的微元思想完整视频_笔记","note":"视频|01:02-01:52","orig":"（知识）安培力冲量 Ia=BIL·t，物理本质是安培力 BIL 在时间上的累积效应","link":""},{"id":"phy1252","t":"磁场·安培力冲量","s":"看到【恒定电流通过导体棒，求安培力冲量】","c":"想到【Ia=BLq，冲量只与通过的电量成正比，与通电时间无直接关系】；警惕【比例系数是 BL 而非 B】","src":"物一轮201.磁场力中的微元思想完整视频_笔记","note":"视频|01:52-02:58","orig":"（知识）电流恒定时 q=It，安培力冲量 Ia=BLq，与电量 q 成正比，比例系数 BL","link":""},{"id":"phy1253","t":"磁场·安培力冲量（微元法）","s":"看到【电流随时间变化，求安培力冲量】","c":"想到【微元累积：无论电流是否变化，安培力冲量恒为 BLq】；警惕【不必纠结电流变化细节，直接用电量建立动量关系即可】","src":"物一轮201.磁场力中的微元思想完整视频_笔记","note":"视频|02:58-08:42","orig":"（知识）电流变化时将时间分割为无数 Δt，每段内近似 I 不变，∑BILΔt=BL∑IΔt=BLq；I-t 图像曲线下面积即电量 q","link":""},{"id":"phy1254","t":"磁场·电容器放电+导轨（电磁弹射）","s":"看到【电容器放电驱动导轨上的金属棒（电磁弹射/电磁炮）求末速度】","c":"想到【放电量 $\\Delta$q=C$\\Delta$U 全部通过棒，由动量定理 BL$\\Delta$q=mv 求末速度，绕开电流变化】；警惕【此类情境必涉及电量变化，勿用牛顿定律硬解】","src":"物一轮201.磁场力中的微元思想完整视频_笔记","note":"视频|08:42-12:59","orig":"（例）电容器电压由 U 降为 U/4，Δq=CΔU=3CU/4 全部通过金属棒，BLΔq=mv，得 v=3BLCU/4m","link":""},{"id":"phy1255","t":"磁场·洛伦兹力冲量","s":"看到【带电粒子在磁场中受洛伦兹力，求其冲量】","c":"想到【速度恒定时洛伦兹力冲量 I=qBx，比例系数 qB】；警惕【冲量是矢量，注意方向】","src":"物一轮201.磁场力中的微元思想完整视频_笔记","note":"视频|12:59-13:27","orig":"（知识）洛伦兹力冲量表达式 I=qvB·t；速度恒定时 x=vt，得 I=qBx，冲量与位移成正比","link":""},{"id":"phy1256","t":"磁场·洛伦兹力冲量（微元法）","s":"看到【速度方向不断变化（匀速圆周）时求洛伦兹力冲量】","c":"想到【微元分割处理：速度大小不变仅方向变，冲量仍只与位移关联，I=qBx】；警惕【速度是矢量，但此处标量累积成立】","src":"物一轮201.磁场力中的微元思想完整视频_笔记","note":"视频|13:27-17:09","orig":"（知识）仅受洛伦兹力时粒子做匀速圆周运动，速度方向不断变化；用时间分割法或 v-t 图像，Δt 足够小则速度近似恒定，∑qBvΔt=qBx","link":""},{"id":"phy1257","t":"磁场·与速度成正比的力的冲量","s":"看到【力的大小与速度成正比（F=kv、洛伦兹力、切割安培力），求冲量】","c":"想到【此类力的冲量正比于位移，直接用 I=qBx、I=kx、I=B^{2}l^{2}x/(R+r)】；警惕【空气阻力比例系数 k 不是弹簧劲度系数，注意区分】","src":"物一轮201.磁场力中的微元思想完整视频_笔记","note":"视频|17:09-20:53","orig":"（知识）普遍规律 F∝v 则 I∝x：洛伦兹力 F=qvB→I=qBx；空气阻力 F=kv→I=kx；导体棒切割安培力 F=B²l²v/(R+r)→I=B²l²x/(R+r)","link":""},{"id":"phy1258","t":"磁场·细管中带电小球模型","s":"看到【绝缘细管（或管道）中带电小球在匀强磁场中运动，求管壁弹力冲量】","c":"想到【分解两方向：弹力平衡一个方向的洛伦兹力分量，另一方向匀加速；∫Ndt=qB$\\times$(该方向位移)，优先位移关联法】；警惕【注意洛伦兹力各分量的方向对应，勿张冠李戴】","src":"物一轮201.磁场力中的微元思想完整视频_笔记","note":"视频|20:53","orig":"（例）光滑绝缘细管以恒定速度 v 运动，竖直向下磁场 B，+q 小球：x 方向 N=qvyB 平衡，y 方向匀加速 ay=qvB/m，IN=∫Ndt=qBL","link":""},{"id":"phy1259","t":"磁场·地磁场方向（赤道）","s":"看到【赤道处地磁场方向或赤道上空的磁学问题】","c":"想到【赤道磁场平行地面指北；俯视图按「上北下南、左西右东、里下外上」标方位】；警惕【头顶方向为上、脚踩方向为下，勿与纸面上下混淆】","src":"物一轮202.地磁场空间方位与平面方位转化问题_笔记","note":"视频|01:54-02:09","orig":"（知识）赤道处地磁场与地面平行且指向北方；俯视图规则：上北下南、左西右东、里下外上","link":""},{"id":"phy1260","t":"磁场·地磁场方向（北半球）","s":"看到【北半球地磁场问题】","c":"想到【分解为水平指北分量 b1 与竖直向下分量 b2，合成方向斜向下指北】；警惕【「上」在俯视图中对应「外」、「下」对应「里」】","src":"物一轮202.地磁场空间方位与平面方位转化问题_笔记","note":"视频|02:09-03:39","orig":"（知识）北半球地磁场分解：b1 平行地平面指向北，b2 垂直地平面向下指地面，合成方向由南指向北、斜向下","link":""},{"id":"phy1261","t":"磁场·地磁场方向（南半球）","s":"看到【南半球地磁场问题】","c":"想到【水平分量仍指北，唯一区别是竖直分量 b2 向上（指向头顶）】；警惕【南北半球磁场方向不要写反，差别只在竖直分量】","src":"物一轮202.地磁场空间方位与平面方位转化问题_笔记","note":"视频|03:39-05:04","orig":"（知识）南半球 b1 平行分量仍指北，b2 垂直分量向上指向头顶，合成方向由南指向北、斜向上","link":""},{"id":"phy1262","t":"磁场·地磁场方位标定通法","s":"看到【空间立体方位（东西南北上下）与平面图互相转化】","c":"想到【三原则：头顶方向=上、磁场切线=北、自转方向定东西（外侧为西、内侧为东）】；警惕【东西方向由自转决定，勿凭感觉标】","src":"物一轮202.地磁场空间方位与平面方位转化问题_笔记","note":"视频|05:04-05:58","orig":"（知识）记忆要点：头顶方向始终为上，磁场切线方向始终为北，地球自西向东自转决定东西方向","link":""},{"id":"phy1263","t":"磁场·指南针偏转反推电流","s":"看到【指南针（小磁针）偏转，反推附近电流方向】","c":"想到【先定地磁场初始指向，再由偏转结果定附加磁场方向，最后用右手定则反推电流】；警惕【空间「竖直向上」在平面图中=垂直纸面向外，勿与纸面上方混淆】","src":"物一轮202.地磁场空间方位与平面方位转化问题_笔记","note":"视频|05:58-13:14","orig":"（例）地面上指南针转 180°，说明电流磁场方向朝南且强于地磁场，结合右手定则判断电缆电流竖直向上","link":""},{"id":"phy1264","t":"磁场·小磁针偏转原因判断","s":"看到【小磁针 N 极向某方向偏转，判断可能原因】","c":"想到【N 极指向=该处磁场方向，偏转即存在该方向的附加磁场；电子流方向与等效电流方向相反】；警惕【含「一定」的绝对化选项慎选】","src":"物一轮202.地磁场空间方位与平面方位转化问题_笔记","note":"视频|13:14-19:22","orig":"（例）赤道上空小磁针 N 极向东偏转，说明存在向东的附加磁场；电子流自南向北时等效电流自北向南，在其下方产生向东磁场","link":""},{"id":"phy1265","t":"磁场·视图转换方法论","s":"看到【俯视图难以想象空间方位关系】","c":"想到【灵活切换视图：俯视图强调东西南北，主视图强调上下；再配合地磁场分量分解或磁场叠加分析】；警惕【换视图后要先重新标注方位再推理】","src":"物一轮202.地磁场空间方位与平面方位转化问题_笔记","note":"视频|19:22","orig":"（知识）俯视图难以分析时可转换为侧视图（主视图）辅助理解，主视图中明确上下对应空间竖直方向","link":""},{"id":"phy1266","t":"磁场·有界磁场概述","s":"看到【磁场区域有限（有界磁场），粒子只走一段圆弧】","c":"想到【与无限大磁场区分：这里运动时间非整周期，核心流程是「定圆心$\\to$找半径$\\to$找圆心角$\\to$代物理公式」】；警惕【勿按完整圆周运动算时间】","src":"物一轮204.有界磁场问题的处理方法_笔记","note":"视频|00:02-06:58","orig":"（知识）磁场区域有限时粒子轨迹为圆弧而非完整圆周；常考速度计算与在磁场中的运动时间（非完整周期）","link":""},{"id":"phy1267","t":"磁场·定圆心（三线定圆心）","s":"看到【需确定圆弧轨迹的圆心】","c":"想到【三线取二交点即圆心；题目只给入射方向时，配弦中垂线共同确定】；警惕【速度垂线即半径方向，先在图中画出两条特征线再求交点】","src":"物一轮204.有界磁场问题的处理方法_笔记","note":"视频|06:58-11:39","orig":"（知识）三线定圆心：入射速度垂线、出射速度垂线、弦中垂线，任取两条即可定圆心；几何依据是切线垂直半径、弦中垂线过圆心","link":""},{"id":"phy1268","t":"磁场·找半径","s":"看到【求轨迹半径，图中给出角度或边长条件】","c":"想到【构造直角三角形：已知角用三角函数、已知边用勾股定理，明确半径对应哪条边】；警惕【先标注全部几何量再列式，防止边角对应错位】","src":"物一轮204.有界磁场问题的处理方法_笔记","note":"视频|11:39-13:17","orig":"（知识）找半径＝把物理问题转化为几何问题：已知角度用三角函数（sinθ、cosθ），已知两边用勾股定理，在轨迹图上标注所有已知几何关系","link":""},{"id":"phy1269","t":"磁场·找圆心角","s":"看到【求粒子在磁场中的运动时间】","c":"想到【先求圆心角$\\theta$，再用 t=($\\theta$/2$\\pi$)T，时间与$\\theta$成正比】；警惕【$\\theta$ 必须用弧度制；分清所求是劣弧还是优弧对应的圆心角】","src":"物一轮204.有界磁场问题的处理方法_笔记","note":"视频|13:17-16:05","orig":"（知识）圆心角两种求法：平面几何倒角（同位角、内错角）或由边长比反推（如 sinθ=1/2→θ=30°）；圆心角决定弧长占整圆比例","link":""},{"id":"phy1270","t":"磁场·物理公式应用","s":"看到【几何求出半径后求速度或比荷】","c":"想到【v=qBr/m 直接代入；整体逻辑永远是先几何定圆、后代物理公式】；警惕【几何关系错误会连锁导致物理量全错，先检查图形】","src":"物一轮204.有界磁场问题的处理方法_笔记","note":"视频|16:05","orig":"（知识）速度公式 r=mv/qB→v=qBr/m；时间公式 t=(θ/2π)T，T=2πm/qB；解题逻辑：先几何（定圆）后物理（代公式）","link":""},{"id":"phy1271","t":"磁场·双边界磁场定圆心","s":"看到【平行或垂直双边界磁场，求轨迹】","c":"想到【按已知条件选三线中的两条：给速度方向用两速度垂线，给位置用垂线+中垂线】；警惕【先判断题目给的是角度还是位置，选错线会卡死】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|00:31-03:20","orig":"（知识）双边界（平行/垂直）磁场仍用三线定圆心：已知入射和出射速度方向→两垂线交点定圆心；已知入射点与出射点位置→入射速度垂线+弦中垂线定圆心","link":""},{"id":"phy1272","t":"磁场·双边界找半径（角度型）","s":"看到【双边界磁场已知入射角$\\theta$，求半径】","c":"想到【r=d/sin$\\theta$，用同角余角相等把入射角转换到直角三角形中】；警惕【sin/cos 别用反，先确认 $\\theta$ 对应的对边】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|03:20-05:50","orig":"（知识）已知角度时构造直角三角形、半径作斜边，r=d/sinθ（d 为磁场宽度），原理是同角的余角相等转换角度","link":""},{"id":"phy1273","t":"磁场·双边界找半径（位置型）","s":"看到【已知入射点与出射点高度差 h（而非角度）】","c":"想到【勾股定理列式后利用 (r−h)^{2}=r^{2}−2rh+h^{2} 消元，得 r=(d^{2}+h^{2})/2h】；警惕【消元是关键技巧，勿死代公式不懂来源】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|03:20-05:50","orig":"（知识）已知高度差 h 与磁场宽度 d：由 d²+(r−h)²=r² 消去 r² 得 r=(d²+h²)/2h（勾股定理法）","link":""},{"id":"phy1274","t":"磁场·双边界圆心角与时间","s":"看到【双边界磁场中求运动时间】","c":"想到【先由几何倒出圆心角，再 t=$\\theta$m/qB，角度统一化为弧度】；警惕【150$^{\\circ}$ 这类角度直接代入弧度公式会出错】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|05:50-06:18","orig":"（知识）入射角与出射角互补定圆心角；时间 t=(θ/2π)·(2πm/qB)，角度先化弧度（如 150°=5π/6）","link":""},{"id":"phy1275","t":"磁场·垂直双边界例题","s":"看到【两条边界互相垂直（非平行）的磁场问题】","c":"想到【方法与平行边界完全相同：定圆心$\\to$r=2d$\\to$圆心角 5$\\pi$/6】；警惕【电性判断用左手定则；速度 v=2qBd/m 勿漏系数 2】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|06:18-22:41","orig":"（例）边界垂直（非平行）磁场：30°入射、垂直出射，30-60-90 三角形得 r=2d，圆心角 150°=5π/6，时间 5πm/3qB，电性由左手定则判断","link":""},{"id":"phy1276","t":"磁场·平行双边界速度偏转例题","s":"看到【平行双边界中已知速度偏转角】","c":"想到【速度偏转角=圆心角，先由几何定半径再求 B、$\\omega$】；警惕【无 B 时时间可用弧长/速度替代求解】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|06:18-22:41","orig":"（例）平行双边界：速度偏转 30° 即圆心角 30°，构造直角三角形得 r=2d，ω=v₀/2d，B=mv₀/(2qd)","link":""},{"id":"phy1277","t":"磁场·单边界对称性","s":"看到【单边界磁场（只有一个磁场边界）】","c":"想到【入射角=出射角（关于边界对称），先利用对称性补全轨迹再定圆心】；警惕【对称轴是磁场边界本身】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|22:44-24:59","orig":"（知识）单边界磁场轨迹对称：以多大角度入射就以相同角度射出；圆心仍用三线中两条确定","link":""},{"id":"phy1278","t":"磁场·单边界找半径","s":"看到【单边界已知入射角$\\theta$与入射出射点距离 d，求半径】","c":"想到【用 sin($\\pi$−$\\theta$)=d/2r 求半径，或与洛伦兹力半径公式联立】；警惕【$\\pi$−$\\theta$ 与 $\\theta$ 的三角函数值关系（互角）别代错】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|24:59-27:53","orig":"（知识）单边界斜入射：sin(π−θ)=d/2r（θ 为入射角，d 为入射点与出射点间距离）；也可由 r=mv/qB 转换","link":""},{"id":"phy1279","t":"磁场·单边界圆心角","s":"看到【单边界斜入射求圆心角或时间】","c":"想到【劣弧圆心角 2($\\pi$−$\\theta$)、优弧 2$\\pi$−2$\\theta$，再代 t=$\\theta$m/qB】；警惕【优弧情形易漏 2$\\pi$ 这一整圆修正】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|27:53-30:16","orig":"（知识）单边界劣弧圆心角 2(π−θ)，优弧圆心角 2π−2θ；时间 t=(θ/2π)T","link":""},{"id":"phy1280","t":"磁场·单边界垂直入射","s":"看到【单边界垂直入射】","c":"想到【垂直进必垂直出，轨迹是半圆，弦长=直径 2r=2mv/qB，时间 t=$\\pi$m/qB】；警惕【比荷计算注意单位换算与约分】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|30:16-41:44","orig":"（例）粒子垂直边界入射必垂直边界射出，轨迹为半圆、弦长=直径 2r；OM=0.4m，比荷约 4.36×10⁶ C/kg","link":""},{"id":"phy1281","t":"磁场·单边界两粒子对比例题","s":"看到【两粒子在同一磁场中运动时间相同，求质量比/速度比】","c":"想到【用 t=$\\theta$m/qB 列时间相等方程，配合半径/速度关系联立求解】；警惕【45$^{\\circ}$ 入射走 1/4 圆而非半圆，圆心角必须逐个算准】","src":"物一轮205.直线边界有界磁场问题_笔记","note":"视频|41:44","orig":"（例）P 垂直入射走半圆，Q 45° 入射走 1/4 圆，运动时间相同：由时间关系建质量比方程、半径关系建速度比方程，得质量比 1:2、速度比 2:1","link":""},{"id":"phy1282","t":"磁场·圆形边界对称进出特性","s":"看到【粒子射入圆形磁场区域】","c":"想到【对称进出：$\\theta$入=$\\theta$出（以磁场圆半径为基准），同侧对称，可直接定出射方向】；警惕【与单边界的区别：夹角基准是磁场圆半径而非边界线】","src":"物一轮206.圆形边界有界磁场问题_笔记","note":"视频|00:26-08:22","orig":"（知识）圆形有界磁场中，入射速度与磁场圆半径的夹角等于出射速度与对应半径的夹角（θ入=θ出），由等腰三角形证明；入射速度在半径左侧，出射速度也在同侧","link":""},{"id":"phy1283","t":"磁场·径向入径向出特例","s":"看到【粒子沿磁场圆半径方向（指向圆心）射入】","c":"想到【径向入必径向出，选择题可秒定出射方向】；警惕【这是高频特例，见到「沿半径/对准圆心射入」立即反应】","src":"物一轮206.圆形边界有界磁场问题_笔记","note":"视频|00:26-08:22","orig":"（知识）粒子沿磁场圆半径方向射入（径向入射）时，必定沿半径方向射出（径向出射）；原理：θ=0 时由对称性出射角也为 0","link":""},{"id":"phy1284","t":"磁场·圆筒磁场碰撞问题","s":"看到【带电粒子在圆筒（圆形腔壁）内碰撞＋磁场偏转的组合运动】","c":"想到【碰撞等效为镜面反射（法向反向、切向不变），每次碰后速度沿半径方向；由对称性分析最少碰撞次数（需满足整周期偏转）】；警惕【轨迹不可能过圆心；速度增大时半径变化可能破坏精确返回】","src":"物一轮206.圆形边界有界磁场问题_笔记","note":"视频|08:22-20:13","orig":"（例）粒子从圆筒 P 点沿径向射入匀强磁场，与筒壁碰撞：切向速度分量不变、法向分量反向（等效二维弹性碰撞，入射角=反射角），形成周期性「反射-偏转」运动","link":""},{"id":"phy1285","t":"磁场·圆筒磁场粒子运动","s":"看到【粒子沿径向射入圆筒磁场，问能否返回/射出小孔】","c":"想到【径向入射必径向出射，配合碰撞反射逐段画轨迹，最少碰撞次数由圆周等分确定】；警惕【勿默认速度越大时间越短，需检查轨迹是否仍闭合返回】","src":"物一轮206.圆形边界有界磁场问题_笔记","note":"视频|20:13-26:03","orig":"（例）粒子沿 PO 径向射入圆筒：轨迹不可能通过圆心 O，最少 2 次碰撞即可从小孔射出，碰撞后速度方向平行于碰撞点与圆心连线","link":""},{"id":"phy1286","t":"磁场·圆形磁场速度比","s":"看到【粒子沿直径方向射入圆形磁场，已知偏转角求速度比】","c":"想到【径向入径向出；偏转 90$^{\\circ}$$\\to$r=R，偏转 60$^{\\circ}$$\\to$r=√3R，由 v∝r 得速度比】；警惕【先画磁场圆＋轨迹圆的完整几何图再找特殊四边形/三角形】","src":"物一轮206.圆形边界有界磁场问题_笔记","note":"视频|26:03-31:33","orig":"（例）沿直径方向射入的粒子必沿直径方向射出；偏转 90° 时轨迹半径 r=R（构成正方形），偏转 60° 时 r=√3R（全等三角形），故 v1/v2=√3","link":""},{"id":"phy1287","t":"磁场·圆形磁场电性与比荷","s":"看到【两粒子在圆形磁场中偏转方向不同，比较电性/比荷/时间】","c":"想到【偏转方向由左手定则定电性；对称性定出射角$\\to$几何求半径$\\to$q/m∝1/r；时间比=圆心角比$\\times$(m/q)比】；警惕【圆心角必须化弧度再代 t=$\\theta$m/qB】","src":"物一轮206.圆形边界有界磁场问题_笔记","note":"视频|31:33-40:05","orig":"（例）A 粒子 30° 入射 30° 出射构成等边三角形 rA=2R；B 粒子 60° 入射出射构成 120° 等腰三角形 rB=2R/√3；由 r=mv/qB 得 qA/qB=1:√3，tA/tB=√3:2","link":""},{"id":"phy1288","t":"磁场·有界磁场通用解题步骤","s":"看到【任意有界磁场（单边界/圆形边界）求速度、半径或时间】","c":"想到【统一流程「定圆心$\\to$找半径$\\to$找圆心角$\\to$代公式」，先几何后物理】；警惕【单边界看与边界的夹角、圆形边界看与半径的夹角，基准勿混】","src":"物一轮206.圆形边界有界磁场问题_笔记","note":"视频|40:05","orig":"（知识）通用三步：定圆心（三线取二）→找半径（直角三角形：三角函数或勾股）→找圆心角（平面几何），再代 r=mv/qB 与 t=(θ/2π)T","link":""},{"id":"phy1289","t":"磁场·动态圆分类","s":"看到【粒子速度可变的磁场轨迹问题】","c":"想到【先分类再选法：方向不变大小变$\\to$放缩圆；大小不变方向变$\\to$旋转圆】；警惕【两类临界分析方法不同，勿混用】","src":"物一轮207.速度方向不变的放缩圆问题_笔记","note":"视频|00:44-01:03","orig":"（知识）动态圆分两类：速度方向不变、大小可变→放缩圆（难度较低）；速度大小不变、方向可变→旋转圆（难度较高）","link":""},{"id":"phy1290","t":"磁场·放缩圆原理","s":"看到【粒子速度方向固定、大小可变，求临界速度或速度范围】","c":"想到【放缩圆法：想象轨迹圆膨胀，找出与边界相切（或刚好打上）的临界态，由几何关系列临界半径方程】；警惕【临界点常不止一个，上、下临界都要找】","src":"物一轮207.速度方向不变的放缩圆问题_笔记","note":"视频|01:03-12:11","orig":"（知识）速度大小可变时轨迹半径 r=mv/qB 随之变化，形成可放缩的圆；用「吹泡泡」类比：圆从最小逐渐膨胀，寻找与边界/极板相切的临界状态","link":""},{"id":"phy1291","t":"磁场·放缩圆双临界例题","s":"看到【求「不打在极板上」的速度范围】","c":"想到【分别求小速度临界（直径=板间距）与大速度临界（与远端边界相切），取值范围在两临界之外】；警惕【只算小速度漏掉大速度情形是最常见错误】","src":"物一轮207.速度方向不变的放缩圆问题_笔记","note":"视频|01:03-12:11","orig":"（例）正方形磁场中粒子不打在极板：上临界圆直径=板间距 l/2 得 v1=qBl/4m，下临界圆与右边界相切得 v2=5qBl/4m，故不打极板条件 v<qBl/4m 或 v>5qBl/4m","link":""},{"id":"phy1292","t":"磁场·放缩圆相切几何","s":"看到【放缩圆中圆与边界/极板相切的临界图】","c":"想到【过切点构造直角三角形，用勾股定理列半径方程；先检查几何结构有无对称性可简化】；警惕【相切点即速度临界点，勿把相交情形当临界】","src":"物一轮207.速度方向不变的放缩圆问题_笔记","note":"视频|01:03-12:11","orig":"（知识）相切临界状态用直角三角形勾股定理列方程；板长与板间距相等时可利用对称性简化","link":""},{"id":"phy1293","t":"磁场·多边形磁场中的放缩圆","s":"看到【多边形（三角形）磁场中速度变化的粒子，问时间/路程极值】","c":"想到【圆心所在直线垂直于入射方向，先定圆心轨迹，再依次检验各边临界；从某边射出阶段圆心角恒定$\\to$时间不变，换边后才变化】；警惕【最长路程看相切情形的弧长 s=圆心角$\\times$r，勿凭感觉选】","src":"物一轮207.速度方向不变的放缩圆问题_笔记","note":"视频|12:11","orig":"（例）三角形磁场（30°-60°-90°）：低速从 AC 边射出时圆心角恒为 120°、时间不变；高速从 BC 边射出后圆心角减小；最长路程对应与 BC 边相切（r=l，s=2πl/3）；tmax=2πm/3qB","link":""},{"id":"phy1294","t":"磁场·旋转圆模型","s":"看到【粒子源速度大小恒定、方向可变（各方向均匀发射），求打在板上的区域】","c":"想到【旋转圆：所有轨迹圆半径相同 r=mv/qB，绕粒子源旋转；先算半径并与源到板的距离比较判断能否打上】；警惕【半径$\\neq$直径，先比较直径与距离再定结论】","src":"物一轮208.速度大小不变的旋转圆问题_笔记","note":"视频|00:26-17:41","orig":"（例）感光板平行磁场，放射源距板 l=0.32m，α 粒子 v=3.0×10⁶ m/s 恒定、q/m=5.0×10⁷ C/kg：半径相同的不同方向轨迹相当于「旋转的圆」，r=mv/qB=0.2m，直径 0.4m＞l","link":""},{"id":"phy1295","t":"磁场·旋转圆临界点确定","s":"看到【旋转圆求打击区域的两端边界】","c":"想到【两类临界：一侧是轨迹与边界相切，另一侧是轨迹弦长=直径；分别用勾股关系求交点坐标后相加】；警惕【另一端点常不是相切而是直径弦，勿全按相切算】","src":"物一轮208.速度大小不变的旋转圆问题_笔记","note":"视频|00:26-17:41","orig":"（例）最左端：轨迹圆与板相切，0.2²=x²+(0.32−0.2)² 得 x=0.16m（3-4-5 三角形）；最右端：轨迹弦长为直径，0.4²=y²+0.32² 得 y=0.24m；区域长 0.16+0.24=0.40m","link":""},{"id":"phy1296","t":"磁场·旋转方向判断","s":"看到【需确定粒子轨迹旋转（偏转）方向】","c":"想到【左手定则先定洛伦兹力方向：正电荷逆时针、负电荷顺时针（磁场垂直纸面向里时）】；警惕【必须先定旋转方向才能确定交点顺序与区域范围】","src":"物一轮208.速度大小不变的旋转圆问题_笔记","note":"视频|00:26-17:41","orig":"（知识）α 粒子（正电）在垂直纸面向里的磁场中洛伦兹力由左手定则判断，逆时针偏转；负电荷则相反，顺时针偏转","link":""},{"id":"phy1297","t":"磁场·旋转圆粒子数比例","s":"看到【粒子源各方向均匀发射，求能击中板的粒子数比例】","c":"想到【先找两个临界发射方向，再算可击中角度范围占总发射角的比例】；警惕【比例只由临界方向夹角决定，与轨迹细节无关】","src":"物一轮208.速度大小不变的旋转圆问题_笔记","note":"视频|17:41-38:17","orig":"（例）粒子源向各方向均匀发射共 N 个，速度方向在向上、向下两临界角度之间的粒子可击中板，可击中粒子数为 N/2","link":""},{"id":"phy1298","t":"磁场·旋转圆运动时间差","s":"看到【旋转圆中求最短/最长运动时间（或时间差）】","c":"想到【时间由圆心角决定：找最小与最大圆心角，$\\Delta$t=($\\theta$max−$\\theta$min)m/qB；弦长越小对应圆心角越大】；警惕【最长轨迹可能对应优弧（如 270$^{\\circ}$），勿只按劣弧算】","src":"物一轮208.速度大小不变的旋转圆问题_笔记","note":"视频|17:41-38:17","orig":"（例）r=d 时打中区域长 (√3+1)d；最短时间对应最小圆心角 60°，得 πm/3qB；最长时间对应 270° 圆心角，时间差 7πm/6qB","link":""},{"id":"phy1299","t":"磁场·负电荷粒子源打屏区域","s":"看到【负电荷粒子源、发射方向限制在角度 $\\theta$ 内，求打中区域长度】","c":"想到【L=2r(1−cos$\\theta$)，由弦长公式与角度关系推导最近端 2rcos$\\theta$、最远端 2r】；警惕【先确认顺/逆时针再排交点顺序，负电荷方向与正电荷相反】","src":"物一轮208.速度大小不变的旋转圆问题_笔记","note":"视频|38:17","orig":"（例）负电荷顺时针旋转；发射角范围 θ 内：最近端 2rcosθ、最远端 2r（直径），区域长度 L=2r(1−cosθ)=2mv(1−cosθ)/qB","link":""},{"id":"phy1300","t":"磁场·动态圆方法论对比","s":"看到【旋转圆空间想象困难】","c":"想到【分步绘制不同旋转角度下的圆位置，或用圆形纸片实物模拟旋转过程找临界轨迹】；警惕【旋转圆比放缩圆多考虑角度变化带来的几何关系，勿漏方向因素】","src":"物一轮208.速度大小不变的旋转圆问题_笔记","note":"","orig":"（知识）放缩圆：速度方向不变大小变，想象「吹泡泡」膨胀找临界，较易理解；旋转圆：速度大小不变方向变，空间想象要求高，建议分步画不同旋转角度的圆位置（或纸片实物模拟）","link":""},{"id":"phy1301","t":"磁场·有界磁场最小面积（圆形·劣弧）","s":"看到【圆形有界磁场中粒子轨迹为劣弧（圆心角小于180°），求最小磁场面积】","c":"想到【弦长AB$\\leq$直径，把入射点与出射点连线取作磁场圆直径，则 r^{'}=r·sin$\\theta$、S_min=$\\pi$r^{2}sin^{2}$\\theta$；先定轨迹半径和圆心角，再求弦长】；警惕【先判定轨迹是劣弧还是优弧，两类构造方法完全不同】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|02:00-06:55","orig":"（知识）轨迹劣弧（圆心角θ<180°）时，当入射点与出射点连线（公共弦）作为磁场圆直径时磁场面积最小；磁场圆半径 r′=AB/2=r·sinθ（r 为轨迹圆半径），最小面积 S_min=πr²sin²θ","link":""},{"id":"phy1302","t":"磁场·有界磁场最小面积（圆形·优弧）","s":"看到【圆形磁场中粒子轨迹为优弧（圆心角大于180°），求最小磁场面积】","c":"想到【最小磁场圆与轨迹圆重合，r^{'}=r，直接用轨迹圆面积】；警惕【优弧情况考试较少出现，掌握基本结论即可】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|06:55-08:46","orig":"（知识）轨迹优弧（圆心角θ>180°）时，磁场圆与粒子运动轨迹圆完全重合时面积最小，此时磁场圆半径等于轨迹圆半径 r′=r","link":""},{"id":"phy1303","t":"磁场·有界磁场最小面积（圆形·例题）","s":"看到【圆形磁场最小面积计算题中给出出射方向或偏转角】","c":"想到【先由 r=mv_{0}/(qB) 求轨迹半径，再由速度方向变化确定偏转角（圆心角），证明入射点与出射点连线为磁场圆直径后求弦长】；警惕【出射点是轨迹与磁场边界的交点而非给定的边界点；偏转角需通过速度方向变化确定，勿混淆劣弧与优弧】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|08:46-15:07","orig":"（例）粒子从y轴上O点沿y轴正向射入圆形磁场，出射方向偏转120°，OC=√3r，磁场圆半径 r′=(√3/2)r，最小面积 S_min=3πm²v₀²/(4q²B²)","link":""},{"id":"phy1304","t":"磁场·有界磁场最小面积（半圆形·劣弧）","s":"看到【半圆形有界磁场、粒子轨迹为劣弧，求最小面积】","c":"想到【原理与圆形磁场劣弧情况完全一致，把公共弦作直径求出磁场圆半径后，面积取半圆 $\\pi$r^{'2}/2 即可】；警惕【先按圆形磁场方法求磁场圆半径，再取一半】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|15:15-16:08","orig":"（知识）半圆形磁场劣弧最小面积：入射点与出射点连线为磁场半圆的直径，面积取圆形磁场的一半，为 πr′²/2","link":""},{"id":"phy1305","t":"磁场·有界磁场最小面积（半圆形·优弧）","s":"看到【半圆形磁场中粒子轨迹为优弧，求最小磁场面积】","c":"想到【作轨迹圆的外切半圆包裹轨迹，半径 r^{'}=r(1+cos$\\theta$)，面积为 $\\pi$r^{'2}/2】；警惕【与圆形磁场不同，半圆形优弧必须保证轨迹完全被磁场包含】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|16:08-18:53","orig":"（知识）半圆形磁场优弧：连接入射点与出射点，以连线中点为圆心作轨迹圆，再作轨迹圆的外切半圆；半径 r′=r(1+cosθ)（θ为入/出射方向与连线的夹角），最小面积 π[r(1+cosθ)]²/2","link":""},{"id":"phy1306","t":"磁场·有界磁场最小面积（半圆形·例题）","s":"看到【半圆形磁场最小面积计算题给出出射角度】","c":"想到【由 r=mv_{0}/(qB) 求轨迹半径，用几何关系求入射出射点连线长，得磁场圆半径后代入半圆面积公式】；警惕【出射角度与轨迹圆心角之间的换算关系】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|18:53-20:18","orig":"（例）粒子质量m、电量+q、初速度v₀、磁感应强度B，出射角度30°，OC=√3r，磁场圆半径 r′=(√3/2)r，最小面积 πr′²/2=3πm²v₀²/(8q²B²)","link":""},{"id":"phy1307","t":"磁场·有界磁场最小面积（矩形）","s":"看到【矩形有界磁场，求包裹粒子圆弧轨迹的最小面积】","c":"想到【以入射点与出射点连线为边界构造最小包络矩形，劣弧按长2r·sin$\\theta$、宽r(1−cos$\\theta$)，优弧按长2r、宽r(1+cos$\\theta$)计算】；警惕【连线是边界而非边，矩形可能超出连线范围】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|20:22-24:53","orig":"（知识）矩形磁场最小面积通用方法：连接入射点与出射点，以连线为一条边界构造刚好包裹轨迹的矩形；劣弧时长 2r·sinθ、宽 r(1−cosθ)；优弧时长 2r（直径）、宽 r(1+cosθ)","link":""},{"id":"phy1308","t":"磁场·有界磁场最小面积（矩形·例题）","s":"看到【矩形磁场最小面积计算题给出具体圆心角】","c":"想到【按劣弧公式长=2r·sin$\\theta$、宽=r(1−cos$\\theta$)代入对应角度计算，再以 r=mv_{0}/(qB) 回代】；警惕【区分连线作为边界还是边的不同构造方式】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|24:53-26:34","orig":"（例）矩形匀强磁场，轨迹圆心角120°，矩形长√3r、宽½r（即r−r·cos60°），最小面积 (√3/2)r²，即 √3m²v₀²/(2q²B²)","link":""},{"id":"phy1309","t":"磁场·有界磁场最小面积（正三角形·包裹）","s":"看到【正三角形有界磁场，圆心角小于120°，轨迹被三角形完全包裹】","c":"想到【以入射出射点连线为底边、顶点取在连线中垂线上构造最小正三角形，S=√3r^{2}sin^{2}$\\theta$（$\\theta$为速度方向与边的夹角）】；警惕【30$^{\\circ}$-60$^{\\circ}$-90$^{\\circ}$三角形关系在计算中反复应用】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|26:44-30:27","orig":"（知识）正三角形磁场（圆心角<120°、轨迹被完全包裹）：以入射点与出射点连线AB为底边、顶点取在AB中垂线上构造最小正三角形；底边 2r·sinθ，利用30°角关系得高 √3r·sinθ，面积 S=√3r²sin²θ；θ=60°时 S=3√3r²/4","link":""},{"id":"phy1310","t":"磁场·有界磁场最小面积（正三角形·相切与判断）","s":"看到【正三角形磁场中轨迹与边相切，或需判断轨迹能否被包裹】","c":"想到【以圆心角120$^{\\circ}$为分界：小于120$^{\\circ}$用包裹公式 √3r^{2}sin^{2}$\\theta$，大于120$^{\\circ}$按相切情况由边长与高计算；判断依据是观察速度方向是否在三角形边内侧】；警惕【临界状态速度方向与边重合，此时圆心角恰为120$^{\\circ}$】","src":"物一轮209.不同形状磁场的最小面积问题_笔记","note":"视频|30:27-32:54","orig":"（知识）圆心角大于120°时轨迹与正三角形边相切：由几何关系得总高√3r、按30°-60°-90°三角形关系求边长，再按三角形面积公式计算；圆心角120°是包裹与相切两种情况的分界点","link":""},{"id":"phy1311","t":"磁场·磁聚焦","s":"看到【圆形磁场中平行入射的粒子束汇聚于一点】","c":"想到【判定 r=R，聚焦点必为入射方向所垂直直径的端点，可用菱形对角线性质证明任意入射点均满足】；警惕【忘记检验轨迹半径与磁场圆半径相等这一前提】","src":"物一轮210.涉及磁聚焦的最小面积问题_笔记","note":"视频|00:18-07:55","orig":"（知识）磁聚焦核心条件：轨迹圆半径与磁场圆半径相等（r=R）；粒子沿垂直磁场圆直径方向射入，所有粒子必汇聚于该直径的一个端点（平行入射→单点汇聚）","link":""},{"id":"phy1312","t":"磁场·磁发散","s":"看到【粒子从磁场圆边界上一点向各方向射入，出射后变为平行粒子束】","c":"想到【磁发散是磁聚焦的逆过程，同样要求 r=R，出射方向垂直于该直径】；警惕【聚焦图与发散图互为逆过程，可互相推证】","src":"物一轮210.涉及磁聚焦的最小面积问题_笔记","note":"视频|00:18-07:55","orig":"（知识）磁发散：粒子从磁场圆直径端点射入（单点入射），出射方向必垂直于该直径（单点入射→平行出射），是磁聚焦的逆过程","link":""},{"id":"phy1313","t":"磁场·磁聚焦（速度选择器衔接）","s":"看到【速度选择器中粒子匀速直线通过（电场力与洛伦兹力平衡）】","c":"想到【由 qvB=qU/d 得 v=U/(Bd)，该速度与电荷量及电性无关】；警惕【只有满足平衡条件且入射方向确定的粒子才能被选中通过】","src":"物一轮210.涉及磁聚焦的最小面积问题_笔记","note":"视频|07:55-16:29","orig":"（例）平行极板间粒子经速度选择器：qvB=qE=qU/d，得 v=U/(Bd)，结果与电荷正负无关；磁聚焦使所有粒子汇聚于中点E","link":""},{"id":"phy1314","t":"磁场·磁聚焦最小磁场面积","s":"看到【磁聚焦装置中求磁场区域的最小面积】","c":"想到【最小磁场区域只需覆盖粒子实际经过的轨迹，用割补法（规则图形面积与圆弧部分加减）求解】；警惕【聚焦点不同对应的最小磁场形状不同（完整圆/割补区域），注意对称性分析】","src":"物一轮210.涉及磁聚焦的最小面积问题_笔记","note":"视频|07:55-16:29","orig":"（例）磁聚焦求最小磁场面积：粒子聚焦于中点E需完整圆形磁场 πd²/4；聚焦于端点C时磁场只需覆盖粒子实际轨迹区域，用割补法（正方形减四分之一圆）计算面积","link":""},{"id":"phy1315","t":"磁场·磁聚焦解题要点总结","s":"看到【综合的磁聚焦/磁发散计算题】","c":"想到【按「判特征$\\to$验r=R$\\to$用对称性$\\to$算覆盖区域」的流程处理】；警惕【不同聚焦点对应不同最小磁场形状，需分别分析】","src":"物一轮210.涉及磁聚焦的最小面积问题_笔记","note":"视频|16:29","orig":"（知识）磁聚焦问题解题要点：识别「平行入射+单点汇聚」特征；牢记核心条件 r=R；优先利用对称性简化计算；最小面积取实际粒子覆盖区域","link":""},{"id":"phy1316","t":"电磁组合场·定义与特点","s":"看到【电场与磁场分区域拼接、空间上不重叠的带电粒子问题】","c":"想到【识别为组合场，分段独立分析各场区的力和运动，不把两场叠加处理】；警惕【与叠加场区分：组合场中两场不同时存在】","src":"物一轮211.电磁组合场的处理方法_笔记","note":"视频|00:25-02:22","orig":"（知识）组合场（电磁拼接场）：电磁场空间位置交替、互不叠加（如以y轴为界左侧纯电场、右侧纯磁场），同一时刻粒子仅受单一力作用","link":""},{"id":"phy1317","t":"电磁组合场·各场区运动形式","s":"看到【粒子依次经过电场区和磁场区】","c":"想到【按场区直接判定运动形式：电场区匀变速（直线或类平抛），磁场区匀速圆周】；警惕【交界处运动形式发生突变，需重新分析受力】","src":"物一轮211.电磁组合场的处理方法_笔记","note":"视频|02:22-03:30","orig":"（知识）电场区受恒定电场力做匀变速运动；磁场区（v⊥B时）受洛伦兹力做匀速圆周运动；多过程本质是粒子在不同场区的分段运动","link":""},{"id":"phy1318","t":"电磁组合场·关联速度","s":"看到【组合场问题需要联立电场与磁场两段计算】","c":"想到【分段分析各场区，用交界处速度的大小和方向衔接两段运动，必要时再建能量方程】；警惕【速度是矢量，大小和方向都要衔接，勿混淆不同场区的速度关系】","src":"物一轮211.电磁组合场的处理方法_笔记","note":"视频|03:30-05:09","orig":"（知识）组合场解题核心：通过关联速度建立运动联系——两场交界处的速度既是前段运动的末速度，也是后段运动的初速度","link":""},{"id":"phy1319","t":"电磁组合场·匀强电场中的运动","s":"看到【粒子在匀强电场中加速或偏转】","c":"想到【加速电场优先用动能定理 qU=½mv^{2}，偏转电场用类平抛分解（x=v_{0}t，y=½at^{2}）】；警惕【偏转电场中加速度方向与初速度垂直，轨迹为抛物线】","src":"物一轮211.电磁组合场的处理方法_笔记","note":"视频|05:18-07:35","orig":"（知识）匀强电场中：电场力与初速度共线时做匀变速直线运动，用运动学公式或动能定理；不共线（常见垂直）时做匀变速曲线运动（类平抛），用运动的合成与分解","link":""},{"id":"phy1320","t":"电磁组合场·磁场中解题三步法","s":"看到【粒子在有界磁场中做匀速圆周运动，求半径、时间或磁感应强度】","c":"想到【按「定圆心$\\to$找半径$\\to$求圆心角」三步走，时间用 t=$\\theta$T/(2$\\pi$)，其中 T=2$\\pi$m/(qB)】；警惕【需结合磁场边界形状分析，几何关系（尤其直角三角形）优先】","src":"物一轮211.电磁组合场的处理方法_笔记","note":"视频|07:35-10:12","orig":"（知识）有界磁场解题三步法：定圆心（入射/出射速度垂线或弦的中垂线交点）→找半径（几何关系结合 r=mv/(qB)）→求圆心角，运动时间 t=θ/(2π)·T","link":""},{"id":"phy1321","t":"电磁组合场·例：加速→偏转→磁场","s":"看到【加速电场$\\to$偏转电场$\\to$有界磁场的多段组合场大题】","c":"想到【逐段列式：加速用动能定理、偏转用类平抛、磁场用 qvB=mv^{2}/r，用关联速度（前段末速度=后段初速度）衔接各段】；警惕【d与r等单位要统一；磁场偏转要同时满足物理公式和几何约束】","src":"物一轮211.电磁组合场的处理方法_笔记","note":"视频|10:12-24:26","orig":"（例）粒子经C₁加速（qU=½mv²）→C₂偏转（类平抛，tanα=1得α=45°）→磁场中垂直x轴射出（1/4圆弧，r=2d），由 qv_B=mv²/r 解得B","link":""},{"id":"phy1322","t":"电磁组合场·例：磁场圆周+电场往返求总时间","s":"看到【粒子在磁场与电场间多次往返、求运动总时间】","c":"想到【分段求各段时间再求和：磁场段 t=$\\theta$T/(2$\\pi$)（$\\theta$为总圆心角），电场往返按对称性 t=2v_{0}/a】；警惕【逐次穿越边界对应哪段轨迹要分段标记；保持物理量符号运算到最后一步】","src":"物一轮211.电磁组合场的处理方法_笔记","note":"视频|24:26-40:18","orig":"（例）粒子上方磁场做圆周、下方电场往返：由等腰直角三角形几何关系得 r=√2h，v₀=qB√2h/m；电场中匀减速最大位移h求E；多次穿越x轴，t总=t磁+t电=7πm/(4qB)+2√2m/(qB)","link":""},{"id":"phy1323","t":"电磁组合场·例：类平抛接磁场的极值与选项验证","s":"看到【类平抛后进入磁场，判断出射速度、半径表达式或极值】","c":"想到【用平抛推论「速度方向角正切=2倍位移方向角正切」快速求出射速度；进磁场时用合速度 v=√(v_{0}^{2}+v$y^2$) 而非 v_{0}】；警惕【区分入射速度v_{0}与进入磁场时的合速度v；速度合成是矢量运算勿漏分量】","src":"物一轮211.电磁组合场的处理方法_笔记","note":"视频|40:18","orig":"（例）粒子先类平抛（x₀=v₀t，y₀/2=½at²）后进磁场偏转：由平抛推论 tanβ=2tanα，粒子从区域最高点N射出时速度最大","link":""},{"id":"phy1324","t":"电磁组合场·质谱仪原理与落点公式","s":"看到【粒子经加速电场后进入偏转磁场、按落点位置区分粒子的装置】","c":"想到【识别质谱仪模型：动能定理与 qvB=mv^{2}/r 联立得 x=(2/B)√(2mU/q)，落点只由比荷倒数 m/q 及U、B决定】；警惕【电场末速度即磁场初速度，是两段衔接的关联量】","src":"物一轮212.质谱仪_笔记","note":"视频|00:05-00:50","orig":"（知识）质谱仪=加速电场+单边界偏转磁场：qU=½mv²得 v=√(2qU/m)；磁场中 r=mv/(qB)=(1/B)·√(2mU/q)，落点距离 x=2r=(2/B)·√(2mU/q)，故 x∝√(m/q)","link":""},{"id":"phy1325","t":"电磁组合场·质谱仪与同位素分离","s":"看到【用质谱仪分离同位素或判断两种粒子能否被区分】","c":"想到【比较 m/q：质量大落点远；两种粒子比荷相同则落点重合、无法分离】；警惕【电荷量相同质量不同是同位素，但「能否分离」只看比荷是否相等，勿凭质量判断】","src":"物一轮212.质谱仪_笔记","note":"视频|00:05-00:50","orig":"（知识）落点与比荷负相关：x∝√(m/q)，质量越大落点越远；相同 q/m 的粒子无法分离（如氘核与氦核比荷均为1/2），仅当 m₁/q₁≠m₂/q₂ 时才能区分","link":""},{"id":"phy1326","t":"电磁组合场·质谱仪例：隐含条件与图像","s":"看到【质谱仪题中「飘入」「轻轻放置」等表述或给出 x-U 图像】","c":"想到【「飘入/轻轻放置」是初速度为零的隐含条件；由 x=(2/B)√(2mU/q) 变形得 x-U 图像斜率求比荷；磁场中半圆时间 t=$\\pi$m/(qB)】；警惕【x与U是开方关系而非线性，图像斜率含义要按公式变形确定】","src":"物一轮212.质谱仪_笔记","note":"视频|10:25-19:49","orig":"（例）粒子「飘入」质谱仪（初速度为零），由磁场中偏转方向用左手定则判出带正电；x-U图像斜率 k=(2/B)·√(m/q)=0.5，得 q/m=8×10⁸ C/kg；磁场中运动时间 t=πm/(qB)=1.96×10⁻⁵ s","link":""},{"id":"phy1327","t":"电磁组合场·质谱仪例：同位素比较与落点重叠","s":"看到【同位素离子经加速后进入磁场，比较速度、半径或落点远近】","c":"想到【加速后 v=√(2qU/m) 质量大速度小，但半径公式中质量影响占优，质量大半径大、落点远】；警惕【电压波动会使同种离子不同时刻落点不同，可能出现前后落点重合】","src":"物一轮212.质谱仪_笔记","note":"视频|19:49-25:56","orig":"（例）氖20与氖22同位素电荷量相同：电场做功 W=qU 与质量无关，质量大的氖22速度较小但半径较大（r=(1/B)·√(2mU/q)）；电压波动时不同时刻同种离子落点可能不同，甚至前后离子落点重合","link":""},{"id":"phy1328","t":"电磁组合场·质谱仪变形：静电分析器","s":"看到【辐射状电场（静电分析器）+偏转磁场的质谱仪变形题】","c":"想到【辐射电场中 qE=mv^{2}/R 提供向心力，与匀强电场处理方式不同；能否被收集由磁场偏转半径与收集器尺寸共同决定】；警惕【到达P点的离子不一定都能被收集，还需比荷满足条件】","src":"物一轮212.质谱仪_笔记","note":"视频|25:56-35:11","orig":"（例）静电分析器（辐射状非匀强电场）提供向心力 qE=mv²/R，联立 qU=½mv² 得 U=ER/2；磁场偏转半径 d=(1/B)·√(mER/q)；能否通过静电分析器只取决于U、E设置，进入收集器还需满足特定比荷","link":""},{"id":"phy1329","t":"电磁组合场·质谱仪例：立体图平面化与无重叠临界","s":"看到【质谱仪给出立体结构图（环形通道、照相底片）或问落点无重叠条件】","c":"想到【先将立体通道简化为二维平面圆环模型，再用落点公式 x=(2/B)√(mU/q) 结合通道几何关系定落点；无重叠临界是「前者最近落点=后者最远落点」】；警惕【先明确粒子落点与通道尺寸的对应关系，勿跳过几何转化直接代公式】","src":"物一轮212.质谱仪_笔记","note":"视频|35:11","orig":"（例）半圆环磁场通道（内半径R、外半径3R）立体图平面化：P₁（q、m）恰击中底片正中间对应落点4R；P₂（2q、3m）落点2√6R，距离差 Δx=2(√6−2)R；由「P₂最近落点>P₁最远落点」推导得 ΔU<U₀/5 时落点无重叠","link":""},{"id":"phy1330","t":"电磁组合场·回旋加速器最大速度与最大动能","s":"看到【回旋加速器求粒子的最大速度或最大动能】","c":"想到【最大速度和动能由D形盒半径R与磁场B决定：v=qBR/m、E_k=q^{2}B^{2}R^{2}/(2m)，与加速电压U无关】；警惕【电压U只影响加速次数，不影响最终动能】","src":"物一轮213.回旋加速器_笔记","note":"视频|03:57-05:16","orig":"（知识）两D形盒内匀强磁场、狭缝处加交变电压；粒子偏转半径达到D形盒半径R时，由 qvB=mv²/R 得 v_max=qBR/m，最大动能 E_k=q²B²R²/(2m)","link":""},{"id":"phy1331","t":"电磁组合场·回旋加速器加速次数","s":"看到【回旋加速器求加速次数】","c":"想到【用 n=E_k/(qU) 联立最大动能表达式求解】；警惕【改变U只改变加速次数，不改变最大动能】","src":"物一轮213.回旋加速器_笔记","note":"视频|05:16-06:10","orig":"（知识）每次通过狭缝获得能量qU，n次加速后 E_k=nqU，故 n=E_k/(qU)=qB²R²/(2mU)；加速次数与B、R正相关，与U、m负相关","link":""},{"id":"phy1332","t":"电磁组合场·回旋加速器运动时间","s":"看到【回旋加速器求粒子运动的总时间】","c":"想到【总时间=磁场偏转时间+电场加速时间；狭缝极小或题干说「忽略宽度」时只算磁场时间】；警惕【第n次加速结束时粒子只完成n−1次完整半圆偏转】","src":"物一轮213.回旋加速器_笔记","note":"视频|06:14-12:00","orig":"（知识）磁场中时间 t₁=n·T/2=nπm/(qB)（T=2πm/(qB)）；考虑狭缝宽度d时加速度 a=qU/(md)，电场时间 t₂=v_max/a；题目注明「忽略电场时间」时只算t₁","link":""},{"id":"phy1333","t":"电磁组合场·回旋加速器交变电压同步","s":"看到【回旋加速器中交变电压的频率或周期设置】","c":"想到【T电=T磁=2$\\pi$m/(qB)，每半圈电场方向同步反转一次，否则出现减速】；警惕【更换粒子（q/m改变）时必须同步调整电场频率】","src":"物一轮213.回旋加速器_笔记","note":"视频|12:00-13:30","orig":"（知识）交变电压周期必须等于粒子回旋周期：T电=T磁=2πm/(qB)；粒子每完成半圈偏转，电场方向需反转一次以保证持续加速","link":""},{"id":"phy1334","t":"电磁组合场·回旋加速器例：更换粒子调整参数","s":"看到【回旋加速器更换加速粒子类型（q/m改变）】","c":"想到【由 E_k=q^{2}B^{2}R^{2}/(2m) 和 T=2$\\pi$m/(qB) 同步调整B与电场周期，两者缺一不可】；警惕【只调磁场会导致电场周期失配，粒子无法被持续加速】","src":"物一轮213.回旋加速器_笔记","note":"视频|16:04-22:26","orig":"（例）加速对象由氘核（m=2u，q=1e）改为氦核（m=4u，q=2e）并保持相同动能：将B降为(√2/2)B₀，同时电场周期调整为2T₀；改D形盒半径法不实用","link":""},{"id":"phy1335","t":"电磁组合场·回旋加速器例：动能与次数计算","s":"看到【回旋加速器计算题求最大动能或加速次数】","c":"想到【最大动能只由B、R、m、q决定；加速次数用 nqU=E_k 求解】；警惕【二者决定因素不同，勿把U代入动能表达式】","src":"物一轮213.回旋加速器_笔记","note":"视频|22:26-38:12","orig":"（例）粒子贴着D形盒边缘射出时动能最大：qvB=mv²/R 得 v=qBR/m、E_k=q²B²R²/(2m)；由 nqU=½mv² 得 n=qB²R²/(2mU)","link":""},{"id":"phy1336","t":"电磁组合场·回旋加速器例：时间比值论证","s":"看到【回旋加速器题中要求论证电场加速时间可忽略】","c":"想到【用 t_E/t_B$\\to$0（R≫d）论证忽略电场时间的合理性】；警惕【磁场时间按n−1次半圆计，不是n次】","src":"物一轮213.回旋加速器_笔记","note":"视频|22:26-38:12","orig":"（例）第n次加速结束时磁场时间 t_B=(n−1)πm/(qB)；电场时间由 v=at_E（a=qU/(md)，v=√(2nqU/m)）求得；当R≫d时 t_E/t_B→0，电场时间可忽略","link":""},{"id":"phy1337","t":"电磁组合场·回旋加速器例：电流与平均功率","s":"看到【回旋加速器求输出电流、被加速粒子数或平均功率】","c":"想到【用电流定义 I=Nq/t 求粒子数，再由 P̄t=NE_k 求平均功率】；警惕【N是时间t内被加速的粒子总数，功率对应总动能除以时间】","src":"物一轮213.回旋加速器_笔记","note":"视频|22:26-38:12","orig":"（例）由输出电流 I=Nq/t 得被加速粒子数 N=It/q；由能量守恒 P̄t=NE_k 得平均功率 P̄=IqB²R²/(2m)","link":""},{"id":"phy1338","t":"电磁组合场·回旋加速器例：概念判断选择","s":"看到【回旋加速器选择题判断周期、速度、动能的影响因素】","c":"想到【牢记「周期与半径和速度无关、最大动能与U无关」两大结论；测粒子质量可用 m=qB/(2$\\pi$f)】；警惕【换粒子后荷质比改变，需同步调整交变电压频率】","src":"物一轮213.回旋加速器_笔记","note":"视频|38:12","orig":"（例）回旋周期 T=2πm/(qB) 与半径无关；最终速度 v=qBR/m 与电压无关；由 f=qB/(2πm) 可求质量 m=qB/(2πf)；荷质比变化需调整频率","link":""},{"id":"phy1339","t":"电磁组合场·粒子电性判断","s":"看到【组合场题要求判断粒子电性】","c":"想到【电场中受力与场强同向为正电、反向为负电；磁场中用左手定则由偏转方向反推，两种途径可互相验证】；警惕【电子等负电荷在电场中受力与场强反向】","src":"物一轮214.电磁组合场难题精讲_笔记","note":"视频|01:17","orig":"（例）电性判断两途径：由静止经电场向右加速，受力方向与场强同向，故带正电；或由磁场偏转方向结合左手定则（洛伦兹力指向轨迹圆心）确认带正电","link":""},{"id":"phy1340","t":"电磁组合场·由磁场时间反求电荷量","s":"看到【粒子在磁场中运动时间恰好对应半个圆周（从直径一端进另一端出）】","c":"想到【由 t=T/2 与 T=2$\\pi$m/(qB) 联立反求q、m或B；书写时从 qvB=mv^{2}/r 和 T=2$\\pi$r/v 推导，二级结论需展示过程】；警惕【先确认轨迹对应的圆心角再套时间公式】","src":"物一轮214.电磁组合场难题精讲_笔记","note":"视频|01:17","orig":"（例）粒子在磁场中运动时间t₀对应半个周期：t₀=½×2πm/(qB)，推导得 q=πm/(Bt₀)","link":""},{"id":"phy1341","t":"电磁组合场·交变电压下的偏转","s":"看到【偏转电场中电压周期性反转，粒子先加速偏转再减速回摆】","c":"想到【对称分段偏转可合并为「加速段位移+减速段位移」，偏移量只由前半段时间与加速度决定，再与磁场几何条件联立】；警惕【交变电场方向反转时刻要与粒子运动阶段对应；几何关系（如d=3r）是连接电场与磁场的桥梁】","src":"物一轮214.电磁组合场难题精讲_笔记","note":"视频|01:17","orig":"（例）板长L=πd/3：水平方向 L=vt₀；竖直方向先加速0.5t₀再减速0.5t₀，偏移 y=2×½a(t₀/2)²=qU₀t₀²/(4md)；与磁场出射点高度 y=2r=√2mv/(qB) 联立解得v和d","link":""},{"id":"phy1342","t":"电磁组合场·电场力总功的分段计算","s":"看到【求粒子在组合场中电场力做的总功】","c":"想到【按运动阶段分段用动能定理，W=qU 中U取该段对应电势差，善用前问结果简化】；警惕【对称往返段电场力做功存在抵消情况，需逐段核对】","src":"物一轮214.电磁组合场难题精讲_笔记","note":"视频|01:17","orig":"（例）完整周期包含加速→偏转（3次半径对应电势差U₀/3）→减速→返回：电场力总功 W=W₁+W₂=½mv²+qU₀/3，各段分开计算无需合并","link":""},{"id":"phy1343","t":"电磁组合场·速度衰减循环模型","s":"看到【磁场中插入「速度衰减器」，粒子多次循环、速度最终稳定】","c":"想到【「稳定」指循环前后速度不变，用能量守恒 eU=½mv^{2}(1−k^{2}) 求稳定速度；半径与速度成正比 r=mv/(qB)】；警惕【左右半圆半径不同但运动周期相同（周期与速度无关）】","src":"物一轮214.电磁组合场难题精讲_笔记","note":"","orig":"（例）双半圆环磁场+电场加速+速度衰减器（通过后速度变为k倍，k<1）：进入衰减器前后半径比 r₁/r₂=v₁/v₂=1/k；稳定条件为循环一周速度复原：eU=½mv²(1−k²)，得 v=√(2eU/(m(1−k²)))","link":""},{"id":"phy1344","t":"电磁组合场·循环偏移累积求次数与时间","s":"看到【粒子每循环一圈横向偏移一定距离，求循环次数或总时间】","c":"想到【将离散循环转化为偏移量累积：N=总偏移/每次偏移，总时间=N$\\times$周期T】；警惕【总偏移是从中点到边界的半径差一半，不是直径差】","src":"物一轮214.电磁组合场难题精讲_笔记","note":"","orig":"（例）每次循环横向偏移 Δx=2(r右−r左)=2mv(1−k)/(eB)，总偏移量(R₂−R₁)/2，循环次数 N=(R₂−R₁)eB/(4mv(1−k))；总时间 t=N·T","link":""},{"id":"phy1345","t":"电磁组合场·边界约束下的多次穿越","s":"看到【有界电场与外围磁场拼接、粒子多次穿越边界】","c":"想到【先画轨迹定圆心与半径（几何约束优先），再用动能定理求速度、qvB=mv^{2}/r 求B】；警惕【判断能否再次从某点进入电场必须定量验证距离，不能想当然】","src":"物一轮214.电磁组合场难题精讲_笔记","note":"","orig":"（例）正方形区域内电场、外围磁场：粒子由静止加速离开边界，磁场偏转半圆返回边界再垂直进入电场；由轨迹几何得 r=d/3，联立 qE·2d=½mv² 与 qvB=mv²/r 解得B","link":""},{"id":"phy1346","t":"电磁组合场·方法论总结","s":"看到【复杂电磁组合场综合大题】","c":"想到【按「分解运动$\\to$定衔接（速度+几何约束）$\\to$列方程」流程处理，边界问题用勾股定理与三角函数】；警惕【「恰好」「最大位移」等隐含条件往往对应临界几何关系】","src":"物一轮214.电磁组合场难题精讲_笔记","note":"","orig":"（知识）组合场处理步骤：分解运动（电场匀加速直线/类平抛、磁场匀速圆周）→抓衔接关键（速度大小方向变化点、几何约束条件）；常用公式 qEd=ΔE_k、r=mv/(qB)、T=2πm/(qB)","link":""},{"id":"phy1347","t":"电磁叠加场·组合场与叠加场的区别","s":"看到【需判断题目属于组合场还是叠加场】","c":"想到【看电场与磁场是否空间共存：共存为叠加场（受力复杂、计算少），分区拼接为组合场（分析易、计算繁），解题策略完全不同】；警惕【两类场特点恰好相反，勿混用处理方法】","src":"物一轮215.【课前必看】本讲听课建议_笔记","note":"视频|00:06-00:23","orig":"（知识）组合场中粒子同一时刻只受单一力（分析易、计算繁）；叠加场（复合场）中电场磁场空间重合，粒子同时受多个场力，受力复杂、运动形式判断难但计算量较小","link":""},{"id":"phy1348","t":"电磁叠加场·题型特征与考查方向","s":"看到【叠加场相关内容的备考与选题定位】","c":"想到【选择题重点准备现代科技应用（尤其霍尔元件及其变形），解答题按「叠加场+组合场」综合题准备】；警惕【压轴问可能涉及配速法，非高分目标可战略性放弃】","src":"物一轮215.【课前必看】本讲听课建议_笔记","note":"视频|04:44-06:24","orig":"（知识）叠加场问题分析难度高、计算量较小；选择题主要考现代科技应用（速度选择器/磁流体发电机/电磁流量计/霍尔元件，近年重现趋势），解答题常与组合场综合考查","link":""},{"id":"phy1349","t":"电磁叠加场·难度分级与解题入口","s":"看到【叠加场题目中出现绳/杆/圆环等约束物】","c":"想到【有约束叠加场用等效重力场法处理；一般曲线运动的压轴题用配速法】；警惕【无约束与有约束的解题入口不同，先识别是否存在约束物再选方法】","src":"物一轮215.【课前必看】本讲听课建议_笔记","note":"视频|00:23-03:13","orig":"（知识）叠加场内容难度分级：无约束叠加场粒子运动（两星，无绳/杆/圆环约束）、现代科技应用（两星）、有约束叠加场（四星，等效重力场法）、配速法求解一般曲线运动（五星）","link":""},{"id":"phy1350","t":"叠加场·定义与组合场区别","s":"看到【电场、磁场（及重力场）在同一空间共存的粒子问题】","c":"想到【识别为叠加场，本质是多力作用下的运动判断问题，需综合受力分析而非分段处理】；警惕【与组合场（分区拼接、单一力）区分，解题入口完全不同】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|00:41-02:22","orig":"（知识）叠加场（复合场）：电磁场空间位置重合，同一时刻粒子同时受电场力、磁场力、重力等多个场力作用；组合场则是同一空间只存在单一场","link":""},{"id":"phy1351","t":"叠加场·力和运动关系判断维度","s":"看到【需要判断粒子在叠加场中的运动形式】","c":"想到【按四步走：定是否计重力$\\to$分析各场力特征（恒力/变力、方向关系）$\\to$合成判断F合性质$\\to$用力和运动关系下结论】；警惕【洛伦兹力随v变化，F合是否恒定不能想当然】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|02:58-05:37","orig":"（知识）判断维度：F合=0匀速直线；F合恒定且与v共线为匀变速直线、不共线为匀变速曲线；F合与v共线为直线运动、不共线为曲线运动；F合沿v的分量与v同向加速、反向减速","link":""},{"id":"phy1352","t":"叠加场·三种场力特点","s":"看到【判断带电液滴/尘埃/电子/质子是否计重力，或判断各场力的大小与方向】","c":"想到【重力看宏观微观、电场力看电性正负、洛伦兹力看速度方向；v=0或v∥B时无洛伦兹力】；警惕【微观粒子通常忽略重力，但题目给出g且涉及平衡时需考虑】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|05:52-10:18","orig":"（知识）重力G=mg恒力（宏观物体必须考虑，微观粒子通常忽略——「宏观重力微观无」）；匀强电场力qE恒力（方向「正同负反」）；洛伦兹力f=qvB为变力，始终f⊥v，v=0或v∥B时f=0","link":""},{"id":"phy1353","t":"叠加场·直线运动形式判断","s":"看到【粒子（v$\\perp$B）在叠加场中做直线运动】","c":"想到【直线运动必为匀速直线，由三力平衡求未知量（勾股定理、三角函数）】；警惕【该结论前提是v$\\perp$B；若v∥B则不受洛伦兹力，可能做匀变速直线】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|11:05-20:58","orig":"（知识）v⊥B的叠加场中：匀速直线运动可能（mg、qE、qvB三力平衡，三恒力构成闭合矢量三角形）；匀变速直线与非匀变速直线均不可能（速度变化→洛伦兹力变化→合力必变，且f⊥v使垂直分量无法持续抵消）","link":""},{"id":"phy1354","t":"叠加场·曲线运动形式判断","s":"看到【判断粒子能否在叠加场中做匀速圆周运动】","c":"想到【检验除洛伦兹力外的其他力是否平衡（mg=qE），平衡则洛伦兹力单独提供向心力做匀速圆周】；警惕【存在未平衡恒力时无法实现匀速圆周；无约束叠加场中变速圆周不可能实现】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|20:58-25:20","orig":"（知识）匀变速曲线运动不可能（速度变化导致洛伦兹力变化，a不可能恒定）；匀速圆周运动可能：需 mg+qE=0（重力与电场力等大反向抵消），仅洛伦兹力提供向心力 qvB=mv²/r","link":""},{"id":"phy1355","t":"叠加场·变速圆周不可能的原因","s":"看到【选项中出现「叠加场中粒子做变速圆周运动」】","c":"想到【直接排除：qvB线性与mv^{2}/r二次比例矛盾，无约束叠加场中变速圆周不可能】；警惕【匀速圆周a∥=0、变速圆周a∥$\\neq$0，加速度特征是区分标志】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|31:40-34:10","orig":"（知识）变速圆周运动不可能实现：向心加速度 a⊥=v²/r 随v二次增长，而洛伦兹力F=qvB随v线性增长，无法持续满足 qvB=mv²/r 的比例关系","link":""},{"id":"phy1356","t":"叠加场·例：液滴三力平衡求速度","s":"看到【液滴/微粒在叠加场中做直线运动，求速度大小和方向】","c":"想到【直线即匀速，先由平衡定洛伦兹力方向（与重力、电场力合力反向），再用勾股定理求合力、v=F/(qB)求速度，夹角用tan$\\theta$确定】；警惕【液滴是宏观微粒必须计重力】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|35:22-41:22","orig":"（例）液滴（mg=2×10⁻⁵N）在E=10³N/C、B=1T叠加场中做直线运动：必为匀速直线，qE向右、mg向下，洛伦兹力与二者合力平衡，F合=√((qE)²+(mg)²)=4×10⁻⁵N，v=F合/(qB)=20m/s，tanθ=qE/mg=√3得θ=60°","link":""},{"id":"phy1357","t":"叠加场·例：电场周期性变化的分阶段运动","s":"看到【叠加场中电场方向周期性变化，粒子交替做直线运动和圆周运动】","c":"想到【分阶段受力分析：直线段三力平衡、圆周段恒力抵消；由 mg=qE 求q、平衡方程求B、T=2$\\pi$m/(qB) 化简求周期】；警惕【电场方向反转后需重新判断力平衡；圆周半径不必显式计算】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"","orig":"（例）微粒先匀速直线（三力平衡）后匀速圆周（重力与电场力平衡，洛伦兹力提供向心力）：圆周段 mg=qE 得 q=mg/E；直线段 2qE=qvB 得 B=2E/v；周期 T=2πm/(qB)=πv/g","link":""},{"id":"phy1358","t":"叠加场·例：电子v∥B的直线运动","s":"看到【判断电子能否在叠加场中做匀变速直线运动】","c":"想到【「v$\\perp$B时直线必匀速」有前提；当v∥B时无洛伦兹力，粒子仅受电场力可做匀变速直线】；警惕【对电场方向与磁场方向的组合分类讨论，逐一检验各力能否平衡】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|47:46-52:29","orig":"（例）电子在电磁场中：速度与磁场垂直时直线必为匀速（需qE=qvB反向平衡，选项中两力同向无法平衡故错）；电场、磁场均与速度平行时不受洛伦兹力，仅受电场力做匀变速直线运动","link":""},{"id":"phy1359","t":"叠加场·例：平衡转圆周与有界磁场射出","s":"看到【小球在叠加场中先平衡后转为圆周运动（如改变电场方向）】","c":"想到【圆周运动条件是除洛伦兹力外其他力平衡（mg=qE），由平衡条件表达qvB再代入 r=mv/(qB)；入射方向改变后重新检验三力是否平衡】；警惕【电性、磁场方向要分类讨论；有界磁场中射出位置需几何验证】","src":"物一轮216.无约束下的叠加场粒子运动问题_笔记","note":"视频|52:29","orig":"（例）小球分类讨论：只有「正电荷+磁场向里」时 mg、qE、qvB 可三力平衡；改变入射方向后三力不平衡则做曲线运动；电场改竖直向上后 mg与qE平衡，洛伦兹力提供向心力，r=(√2/2)a，几何验证恰好从D点射出","link":""},{"id":"phy1360","t":"电磁叠加场·微观粒子受力","s":"看到【电磁叠加场中带电微观粒子的装置问题】","c":"想到【先确认受力仅qE与qvB、忽略重力，再画受力判断平衡或偏转】；警惕【负电荷受力方向要反向：电场力与场强反向、洛伦兹力四指反向】","src":"物一轮217.速度选择器_笔记","note":"视频|00:02-00:56","orig":"（知识）电磁叠加场现代科技装置研究对象均为微观粒子，不考虑重力，仅受电场力qE和洛伦兹力qvB作用","link":""},{"id":"phy1361","t":"速度选择器·工作原理","s":"看到【平行板电容器加正交磁场、粒子直线通过】","c":"想到【列平衡式qvB=qE得v=E/B，筛选速度只由E/B比值决定】；警惕【筛选速度与粒子电荷量、质量、比荷均无关】","src":"物一轮217.速度选择器_笔记","note":"视频|00:56-07:42","orig":"（知识）平行板间加匀强电场与垂直纸面向里匀强磁场，qvB=qE时粒子直线通过，筛选速度v=E/B；调节E/B比值可选不同速度","link":""},{"id":"phy1362","t":"速度选择器·三大特性","s":"看到【速度选择器概念判断题：问比荷、电性、入射方向】","c":"想到【三特性：选速不选粒、电中性无关、单向性——反向入射时电场力与洛伦兹力同向必偏转】；警惕【误认为速度与粒子种类或比荷相关，实际仅由E/B决定】","src":"物一轮217.速度选择器_笔记","note":"视频|07:42-09:01","orig":"（知识）速度选择器只筛选速度v=E/B的粒子，正负电荷均可通过（需满足相同速度），且仅从左向右入射能直线通过（单向性）","link":""},{"id":"phy1363","t":"速度选择器·普适性应用","s":"看到【某粒子以v0直线通过选择器，问其他粒子能否通过】","c":"想到【直接用选速不选粒特性：任何粒子只要以v=E/B、同一方向入射即可通过】；警惕【速度不等于E/B的粒子一律偏转，与电性正负无关】","src":"物一轮217.速度选择器_笔记","note":"视频|09:01","orig":"（例）质子以v0直线通过速度选择器，问哪种粒子也能直线通过：电子以v0速度入射即可，其他选项速度不符v0条件，答案B","link":""},{"id":"phy1364","t":"装置对比·叠加场与组合场","s":"看到【区分现代科技装置属于叠加场还是组合场】","c":"想到【叠加场=电场磁场同时共存同区域；组合场=分区先后经过】；警惕【装置归类混淆导致分析方法选错】","src":"物一轮217.速度选择器_笔记","note":"视频|09:01","orig":"（知识）质谱仪/回旋加速器属组合场，速度选择器/磁流体发电机/电磁流量计/霍尔元件属叠加场，叠加场装置研究对象均为微观粒子","link":""},{"id":"phy1365","t":"磁流体发电机·基本原理","s":"看到【等离子体射入磁场、两极板间形成电势差的发电装置】","c":"想到【先由洛伦兹力方向判断正负电荷各往哪块极板偏转、确定电源正负极，再列平衡qvB=qE】；警惕【正负电荷受洛伦兹力方向相反，偏转方向判断错则极板极性全错】","src":"物一轮218.磁流体发电机_笔记","note":"视频|00:02-08:02","orig":"（知识）等离子体以速度v垂直进入磁场B，正负电荷受相反洛伦兹力分离，在两极板堆积形成电场，稳定时qE=qvB平衡，电路中充当电源","link":""},{"id":"phy1366","t":"磁流体发电机·电动势","s":"看到【求磁流体发电机的电动势或稳定电压】","c":"想到【由qvB=qU/d得U=Bdv，电动势三要素为B、d、v】；警惕【电动势与粒子数密度无关，密度只影响达到平衡的快慢】","src":"物一轮218.磁流体发电机_笔记","note":"视频|00:02-08:02","orig":"（知识）稳定时E=U/d=vB，得开路电压U=Bdv，等效电源电动势ε=Bdv（d为板间距）","link":""},{"id":"phy1367","t":"磁流体发电机·内阻与等效电路","s":"看到【发电机外接电阻求电流或路端电压】","c":"想到【等效为电源：I=$\\varepsilon$/(R+r)，r=$\\rho$d/S，U=IR】；警惕【内阻公式中l是沿电流方向的长度（板间距）、S是正对面积，弄混则r算错；路端电压$\\neq$电动势】","src":"物一轮218.磁流体发电机_笔记","note":"视频|00:02-08:02","orig":"（知识）内阻用电阻决定式r=ρl/S，l为电流方向长度即板间距d，S为极板正对面积；接负载后遵循闭合电路欧姆定律，路端电压需扣内阻分压","link":""},{"id":"phy1368","t":"磁流体发电机·极板极性与电路计算","s":"看到【立体图给出的磁流体发电机电路计算】","c":"想到【先转成平面图，正电荷偏转方向即电源正极位置，再套闭合电路欧姆定律】；警惕【忽略内阻分压直接把Bdv当路端电压是常见陷阱】","src":"物一轮218.磁流体发电机_笔记","note":"视频|08:02-11:47","orig":"（例）立体图判断：由洛伦兹力方向定极板正负，再由I=ε/(R+r)=Bdv/(R+ρd/S)求路端电压U=BdvSR/(ρd+RS)，答案B","link":""},{"id":"phy1369","t":"磁流体发电机·电压影响因素","s":"看到【问改变某参数（d、v、粒子密度、B）后极板电压如何变】","c":"想到【由U=Bdv判断：电压只随B、d、v增大而增大】；警惕【误以为粒子数密度影响稳定电压——它只影响达到平衡的快慢】","src":"物一轮218.磁流体发电机_笔记","note":"视频|11:47","orig":"（例）判断极板电压影响因素：增大板间距d电压增大、增大喷入速度v电压增大、粒子数密度只影响堆积快慢不影响最终电压，答案AC","link":""},{"id":"phy1370","t":"电磁流量计·流量定义","s":"看到【求流量Q或区分流量与流速】","c":"想到【Q=SV，矩形管道S=ab、圆管S=$\\pi$r^{2}，先算有效横截面积】；警惕【流量与流速是两个量：粗细管流量相同但流速不同】","src":"物一轮219.电磁流量计_笔记","note":"","orig":"（知识）流量为单位时间内通过横截面的体积，Q=SV（横截面积×流速），圆柱形与矩形管道公式形式相同但截面积算法不同","link":""},{"id":"phy1371","t":"电磁流量计·测量原理","s":"看到【管道加磁场测出两壁电压、求流速或流量】","c":"想到【稳态平衡qvB=qU/d得v=U/(Bd)，再乘横截面积得Q=SV】；警惕【d是产生电压方向的两壁间距，代入错距离则全错】","src":"物一轮219.电磁流量计_笔记","note":"","orig":"（知识）洛伦兹力使带电粒子偏转形成电势差U=Bdv，稳定时qE=qvB，电势差与流速成线性关系，由电压反推流速v=U/(Bd)","link":""},{"id":"phy1372","t":"电磁流量计·仪器改装","s":"看到【把电压表刻度盘改装成流量刻度】","c":"想到【U与Q成正比（Q=SU/Bd），刻度均匀，按比例换算即可】；警惕【管道形状不同横截面积表达式不同，比例系数随S改变】","src":"物一轮219.电磁流量计_笔记","note":"","orig":"（例）电压表刻度改为流量值（如U=2时Q=4），需根据管道形状调整公式；非圆形管道横截面积按矩形S=ab计算","link":""},{"id":"phy1373","t":"电磁流量计·压强差综合","s":"看到【流量计与压强差、流体阻力结合的综合题】","c":"想到【压力差$\\Delta$P·S与阻力kv^{2}平衡，联立Q=SV消元求解】；警惕【粗细管中流量相同、流速与截面积成反比，别把流速当相同】","src":"物一轮219.电磁流量计_笔记","note":"","orig":"（知识）压强差平衡流体阻力：ΔP·S=kv²，需结合流量公式联立求解；粗细管流量相同但流速不同","link":""},{"id":"phy1374","t":"电磁流量计·实际应用与单位换算","s":"看到【两管道直径不同、流量相同，比较流速或电压】","c":"想到【v=Q/S，流速与截面积（直径平方）成反比】；警惕【单位换算陷阱：m^{3}/h化成m^{3}/s要除以3600，时间维度易漏】","src":"物一轮219.电磁流量计_笔记","note":"","orig":"（例）排污管与流量计直径比2:1时，流量相同但流速比为1:4；单位换算70m³/h≈2.5×10⁻²m³/s量级需注意时间维度","link":""},{"id":"phy1375","t":"霍尔元件·结构对比","s":"看到【实心导体/半导体薄片通电流置于磁场中】","c":"想到【识别为霍尔元件：内部自由电荷受洛伦兹力偏转堆积产生霍尔电压，与空腔型装置区分】；警惕【空腔装置靠外部粒子通过，霍尔元件无粒子流入】","src":"物一轮220.霍尔元件_笔记","note":"视频|00:26-00:28","orig":"（知识）与速度选择器、磁流体发电机、电磁流量计等平行板空腔结构不同，霍尔元件是实心导体或半导体，不需要外部粒子通过，靠内部自由电荷在磁场中偏转产生效应","link":""},{"id":"phy1376","t":"霍尔元件·工作原理","s":"看到【霍尔元件通电流加磁场，问载流子运动】","c":"想到【先定载流子类型：金属为电子、半导体可能为空穴；电流方向与电子运动方向相反】；警惕【默认情况下载流子是电子，除非明确说明是正电荷】","src":"物一轮220.霍尔元件_笔记","note":"视频|00:28-04:41","orig":"（知识）前后表面加磁场、左右表面通电流；金属导体中自由电子定向移动（电流方向与电子运动方向相反），半导体中可能是空穴（正电荷）移动","link":""},{"id":"phy1377","t":"霍尔元件·金属与半导体差异","s":"看到【问霍尔元件某表面带什么电或电势高低】","c":"想到【左手定则定洛伦兹力方向$\\to$定堆积面$\\to$按电荷正负定电势高低；同样偏转方向下电子与空穴形成电势相反】；警惕【电子堆积的一侧电势较低，别按正电荷习惯直接判高电势】","src":"物一轮220.霍尔元件_笔记","note":"视频|04:41-06:10","orig":"（知识）电子受洛伦兹力向上偏转→上极板带负电（电势低）；空穴受洛伦兹力向上偏转→上极板带正电（电势高）；判断须同时考虑洛伦兹力方向和电荷性质","link":""},{"id":"phy1378","t":"霍尔元件·电势高低判断步骤","s":"看到【判断霍尔元件两端电势高低的选择题】","c":"想到【标准化四步流程：定磁场$\\to$定洛伦兹力$\\to$定电荷性质$\\to$定电势】；警惕【跳过电荷性质判断直接定电势，是最高频错误】","src":"物一轮220.霍尔元件_笔记","note":"视频|06:10-07:09","orig":"（知识）判断步骤：确定磁场方向和电流方向→左手定则判断洛伦兹力方向→明确材料中自由电荷性质→根据电荷堆积确定电势高低","link":""},{"id":"phy1379","t":"霍尔元件·霍尔电压计算","s":"看到【求霍尔电压或问霍尔电压与哪些量有关】","c":"想到【稳态平衡qU/h=qvB$\\to$U=Bhv，理解推导不死记】；警惕【h是产生电压的两面间距离，与磁场方向距离d含义不同，h与d易混淆】","src":"物一轮220.霍尔元件_笔记","note":"视频|07:09-10:28","orig":"（知识）电荷偏转堆积产生内部电场E=U/h，稳定时qE=qvB，得微观表达式U=Bhv（h为产生电压方向的极板间距），公式中距离需按装置方向确定","link":""},{"id":"phy1380","t":"霍尔元件·霍尔系数推导","s":"看到【推导霍尔系数k或问k由什么决定】","c":"想到【用I=nqsv把v换成I，代入U=Bhv对比得k=1/(nq)】；警惕【n是单位体积内自由电荷数，不是单位长度电荷数】","src":"物一轮220.霍尔元件_笔记","note":"视频|10:28-14:24","orig":"（知识）由U=Bhv与电流微观式I=nqsv（s=hd）联立得U=IB/(nqd)，与宏观式U=kIB/d对比得k=1/(nq)；霍尔系数与自由电荷浓度成反比","link":""},{"id":"phy1381","t":"霍尔元件·概念判断例题","s":"看到【霍尔元件综合选择题：混入力的大小、系数定义等选项】","c":"想到【逐项核对：电势看堆积面、电场力F=qU/h用电压方向距离、k=1/(nq)中n为单位体积电荷数】；警惕【选项常把h偷换成d、把单位体积偷换成单位长度】","src":"物一轮220.霍尔元件_笔记","note":"视频|14:24-24:34","orig":"（例）判断电势高低、洛伦兹力与静电力大小（F=qU/h而非qU/d）、霍尔系数中n的定义等选项，答案B","link":""},{"id":"phy1382","t":"霍尔元件·测大电流装置","s":"看到【霍尔电压恰好为零、元件处于两个磁场中测电流】","c":"想到【U=0$\\Leftrightarrow$元件处磁感应强度为零，转化为两磁场等大反向叠加，先用右手定则定各磁场方向】；警惕【零电压不是无电流通过，而是磁场被完全抵消】","src":"物一轮220.霍尔元件_笔记","note":"视频|24:34-31:01","orig":"（例）霍尔电压为零的条件是元件处合磁场为零：螺绕环磁场与直导线磁场叠加B总=B+B'=0，由k₁I₀=k₂I'解得I'=(k₁/k₂)I₀","link":""},{"id":"phy1383","t":"霍尔元件·速度计应用","s":"看到【霍尔传感器做速度计、脉冲计数类应用题】","c":"想到【脉冲频率对应转速，求线速度需知道轮半径v=2$\\pi$rn；传感器关注脉冲频率而非电压幅值】；警惕【把车速与U=Bhv中的定向移动速度混为一谈，两者无关】","src":"物一轮220.霍尔元件_笔记","note":"视频|31:01-37:16","orig":"（例）自行车速度计：轮每转一圈磁铁靠近传感器一次产生一个脉冲电压；仅知脉冲数无车轮半径r不能算车速（v=2πrn）；霍尔电压中的v是电荷定向移动速度与车速无关，答案D","link":""},{"id":"phy1384","t":"装置总结·三类电荷堆积装置对比","s":"看到【比较电磁流量计、磁流体发电机、霍尔元件的异同】","c":"想到【共同原理=电荷堆积达到qE=qvB平衡，再按测量对象区分装置用途】；警惕【速度选择器无电荷堆积现象，与这三者原理层次不同】","src":"物一轮220.霍尔元件_笔记","note":"视频|37:16","orig":"（知识）电磁流量计/磁流体发电机/霍尔元件共同点：稳态均满足电场力等于洛伦兹力qvB=qU/d；区别：流量计测流速、发电机发电、霍尔元件测磁场","link":""},{"id":"phy1385","t":"等效重力法·合成原理","s":"看到【带电粒子在重力场和匀强电场复合场中受杆、圆环等约束运动】","c":"想到【将重力与电场力合成等效重力，力系简化（5力$\\to$3力），旋转坐标系把等效重力方向视为新竖直方向】；警惕【等效重力方向要由合力方向确定，须用勾股/三角函数算大小与夹角】","src":"物一轮221.等效重力场处理有约束下的叠加场粒子运动问题_笔记","note":"视频|00:02-01:51","orig":"（知识）匀强电场力qE与重力mg都是恒力，可矢量合成得等效重力mg'，大小g'=√(g²+(qE/m)²)，方向为合力方向，适用于重力场+匀强电场复合场中的约束运动（圆环、杆等）","link":""},{"id":"phy1386","t":"等效重力法·约束与无约束区别","s":"看到【叠加场中有杆/环约束的直线运动判断】","c":"想到【先判断有无约束：有约束时弹力、摩擦力参与，无约束匀速直线结论不可直接套用】；警惕【把无约束结论硬搬到有约束模型】","src":"物一轮221.等效重力场处理有约束下的叠加场粒子运动问题_笔记","note":"视频|00:02-01:51","orig":"（知识）电磁叠加场中无约束物体做直线运动必为匀速直线；但有约束（如绝缘杆）时该结论不成立，需重新受力分析","link":""},{"id":"phy1387","t":"杆约束·临界速度与匀速条件","s":"看到【杆上带电小球在复合场中运动，问何时摩擦力为零或何时匀速】","c":"想到【临界条件：等效重力=洛伦兹力$\\Rightarrow$N=0$\\Rightarrow$f=0，此后沿杆无阻力做匀速直线】；警惕【N=0是中间量，要能从垂直杆方向平衡推出摩擦力消失】","src":"物一轮221.等效重力场处理有约束下的叠加场粒子运动问题_笔记","note":"视频|01:51-19:26","orig":"（例）等效重力与洛伦兹力平衡时垂直杆方向合力为零⇒弹力N=0⇒摩擦力f=0，解得临界速度v₀=2mg/(qB)，此时沿杆仅剩初速度⇒保持匀速直线运动","link":""},{"id":"phy1388","t":"杆约束·不同初速度的最终状态","s":"看到【杆约束下比较不同初速度对应最终运动状态】","c":"想到【动态分析链：v变化$\\to$洛伦兹力变化$\\to$N变化$\\to$f变化$\\to$a变化；判断终点看速度减为零还是加速度减为零】；警惕【大于临界值不会停止而是趋向临界速度匀速，误判停止是高频错】","src":"物一轮221.等效重力场处理有约束下的叠加场粒子运动问题_笔记","note":"视频|01:51-19:26","orig":"（例）v₀大于临界值：qvB>等效重力，N向外，速度减小⇒洛伦兹力减小⇒加速度减小，最终以临界速度匀速；v₀小于临界值：N向内，速度减小⇒弹力增大⇒加速度增大，最终停止","link":""},{"id":"phy1389","t":"圆环约束·速度最大位置","s":"看到【复合场圆环/圆轨模型问速度最大点或能否做完整圆周】","c":"想到【速度最大点=等效最低点（等效重力势能最小处）；能否完整圆周看能否越过等效最高点（势能极大点）】；警惕【几何最低点$\\neq$等效最低点，别按真实竖直方向找极值】","src":"物一轮221.等效重力场处理有约束下的叠加场粒子运动问题_笔记","note":"视频|19:26-33:18","orig":"（例）小环在等效重力方向左下方，从静止释放向左滑下；实际最低点速度非最大，速度最大值出现在等效重力方向最低点（旋转坐标系后的新最低点），因无法越过等效最高点只能做往复运动","link":""},{"id":"phy1390","t":"圆环约束·最大压力与洛伦兹力极值","s":"看到【求圆环上最大压力或最大洛伦兹力】","c":"想到【先由等效重力做功（动能定理）求v_max，再在等效最低点列向心力学方程；f=qvB∝v，速度最大处洛伦兹力最大】；警惕【压力计算别漏掉洛伦兹力项，向心方程须包含qvB】","src":"物一轮221.等效重力场处理有约束下的叠加场粒子运动问题_笔记","note":"视频|19:26-33:18","orig":"（例）等效最低点处由动能定理求v_max，再列向心方程F_N-等效重力-qvB=mv²/R求最大压力；洛伦兹力最大值f_max=qBv_max出现在等效最低点","link":""},{"id":"phy1391","t":"等效重力·能量分析","s":"看到【复合场圆周中比较各段动能、电势能、重力势能变化】","c":"想到【等效重力做功定动能变化；电场力单独做功定电势能变化，二者不能混用】；警惕【等效重力不做功$\\neq$各自不做功：实际重力与电场力做功代数和为零，但各势能需分别分析】","src":"物一轮221.等效重力场处理有约束下的叠加场粒子运动问题_笔记","note":"视频|33:18","orig":"（例）电场力F_E=mg时等效重力g'=2g、方向与竖直成45°，坐标系旋转45°分析；动能变化看等效重力做功，电势能变化看电场力做功（b→c电场力做负功电势能增大），重力势能与电势能需分别计算","link":""},{"id":"phy1392","t":"配速法·方法识别特征","s":"看到【叠加场中粒子做一般性（非直线、非圆周）曲线运动】","c":"想到【识别为配速法题：常规动能定理、牛顿定律、动量定理往往受阻，需速度分解建等效平衡】；警惕【先试常规方法确认失效，再启用配速法，不要盲目硬算】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|00:15-01:06","orig":"（知识）带电粒子在电磁复合场中同时受电场力qE和洛伦兹力qvB，运动轨迹既非匀速直线也非圆周运动的不规则曲线时，适用配速法","link":""},{"id":"phy1393","t":"配速法·解题障碍识别","s":"看到【叠加场曲线运动中位移未知、动能定理列不出】","c":"想到【用运动分解补足信息：由对称性与功能关系先定性（等高点、速度极值点），再配速法求定量位移】；警惕【等高点由电场力做功为零判断，速度最大点在电场力做功最多处】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|01:06-06:14","orig":"（例）粒子A→C→B曲线，A/B点速度为零、C为最低点；AB等高（电场力做功W=qEΔh=0）、C点速度最大；动能定理qEd=½mv²中d为待求量，无法直接求解","link":""},{"id":"phy1394","t":"配速法·四步流程","s":"看到【要用配速法处理叠加场曲线运动】","c":"想到【标准化四步：找恒力$\\to$配反向洛伦兹力$\\to$分解出v_{1}=E/B与v_{2}$\\to$f_{2}作向心力】；警惕【速度分解不要求正交，目的是让v_{1}对应平衡的f_{1}】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|06:14-11:00","orig":"（知识）第一步找等效恒力（有重力场+电场先求合力，仅电场则qE）；第二步配等大反向洛伦兹力f₁：qv₁B=qE⇒v₁=E/B；第三步把实际速度分解为v₁与v₂（不要求正交）；第四步分析f₂提供向心力","link":""},{"id":"phy1395","t":"配速法·运动合成与摆线","s":"看到【问叠加场曲线运动的分解结果或轨迹名称】","c":"想到【一般曲线运动=匀速直线+匀速圆周合成，轨迹为摆线，圆周旋转方向由洛伦兹力方向决定】；警惕【f_{1}与恒力永久平衡、f_{2}大小不变方向持续变化，别把f_{2}当恒力】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|11:00-14:48","orig":"（知识）v₁对应匀速直线运动（速度E/B），v₂对应匀速圆周运动（半径r=mv₂/qB），二者矢量叠加形成摆线（旋轮线）；任一时刻合速度v=v₁+v₂","link":""},{"id":"phy1396","t":"配速法·最大最小速度","s":"看到【求摆线运动的最大速度或最小速度】","c":"想到【速度极值=两分速度同向相加、反向相减，代入v_{1}=E/B与v_{2}计算】；警惕【v_{1}与v_{2}反向相减可能为零，别默认最小速度为正】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|16:33-22:17","orig":"（知识）v₁与v₂同向时v_max=v₁+v₂（轨迹最高点），反向时v_min=|v₁-v₂|可能为零；v₁=v₂时最小速度为零，v₁>v₂时保持原方向，v₁<v₂会出现速度反向","link":""},{"id":"phy1397","t":"配速法·最高最低点距离","s":"看到【求摆线轨迹最高点与最低点的距离】","c":"想到【高度差=圆周分量直径2r=2mv_{2}/qB，只由v_{2}决定】；警惕【误用v_{1}参与半径计算，v_{1}只管平动不影响轨迹高度差】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|22:17-23:04","orig":"（例）轨迹最高点与最低点高度差h=2r=2mv₂/(qB)，等于匀速圆周运动直径，与v₁无关仅取决于v₂；可先用配速法确定v₂再代入半径公式","link":""},{"id":"phy1398","t":"配速法·三种摆线形态","s":"看到【给定摆线轨迹形状，判断v_{1}与v_{2}的大小关系】","c":"想到【看极值点：出现回环/速度反向$\\Rightarrow$v_{1}<v_{2}；出现尖角$\\Rightarrow$v_{1}=v_{2}；平滑单向$\\Rightarrow$v_{1}>v_{2}】；警惕【尖角与回环混淆，尖角点速度为零但方向不反转】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|23:04-25:00","orig":"（知识）v₁<v₂：轨迹有回环（速度会反向）；v₁=v₂：轨迹在极值点形成尖角；v₁>v₂：轨迹平滑无反向；判断依据是极值点处速度方向是否反转","link":""},{"id":"phy1399","t":"配速法·高考真题应用","s":"看到【粒子在正交电场磁场中从静止释放的运动】","c":"想到【配速后v_{1}=v_{2}=E/B，v_max=2E/B；位移既可用能量角度qEd=½mv^{2}也可用圆周直径2r求，双法互验】；警惕【两种方法结果必须一致，算不一致说明v_{2}或平衡条件用错】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|25:00-29:26","orig":"（例）粒子从静止出发的摆线运动：v₁=v₂=E/B，最大速度v_max=2E/B；竖直位移由qEd=½mv²得d=2mE/(qB²)，与圆周直径2r=2mE/(qB²)两种解法等价","link":""},{"id":"phy1400","t":"配速法·组合场综合题","s":"看到【组合场+叠加场串联的综合大题：先加速、再偏转、再进叠加场】","c":"想到【分段处理：逐段用动能定理/半径公式/配速法，几何上套30$^{\\circ}$-60$^{\\circ}$-90$^{\\circ}$三角形（1:√3:2）或120$^{\\circ}$等腰三角形】；警惕【√3与特殊三角形的对应关系记错、数值敏感度（√3/6与1/2）易错】","src":"物一轮222.配速法求解叠加场中一般曲线运动_笔记","note":"视频|29:26","orig":"（例）山东卷改编：加速电场qU=½mv²求速度→磁场偏转构造120°等腰三角形或30°直角三角形定几何关系→叠加场中配速v₁=E/B与剩余v₂分别做匀速直线与圆周，再求最近距离","link":""},{"id":"phy1401","t":"电磁感应·章节逻辑链","s":"看到【电磁感应综合大题不知从何入手】","c":"想到【按逻辑链推进：磁通量变化$\\to$电动势$\\to$电流$\\to$安培力$\\to$加速度/功能，逐环列式】；警惕【跳环分析：未先求电动势和电流就直接谈安培力或能量】","src":"物一轮223.【课前必看】本讲听课建议_笔记","note":"视频|00:04-00:28","orig":"（知识）磁通量变化→产生感应电动势（法拉第电磁感应定律）→闭合回路产生感应电流（方向由楞次定律判断）→感应电流受安培力→动力学问题与能量问题","link":""},{"id":"phy1402","t":"电磁感应·感应电流产生条件","s":"看到【判断回路中有无感应电流的问题】","c":"想到【核查两个条件：回路闭合+磁通量发生变化（B、S或夹角任一变化即可）】；警惕【磁场变化但回路断开、或回路面积变化但磁通量不变的假象情形】","src":"物一轮223.【课前必看】本讲听课建议_笔记","note":"视频|00:28-02:21","orig":"（知识）磁通量φ=BScosθ；闭合回路中磁通量变化是产生感应电流的本质原因","link":""},{"id":"phy1403","t":"电磁感应·楞次定律与自感","s":"看到【要求判断感应电流方向或自感电动势方向】","c":"想到【标准化四步流程判方向，核心是「阻碍」原磁通变化；自感方向同理由楞次定律关联】；警惕【把「阻碍变化」误当「阻止变化」或「与原磁场方向相反」】","src":"物一轮223.【课前必看】本讲听课建议_笔记","note":"视频|02:21-04:03","orig":"（知识）楞次定律判断感应电流方向：四步法——原磁场方向→变化趋势→感应磁场方向（阻碍变化）→电流方向；延伸至安培力方向（结合左手定则）与自感（电流变化时线圈产生阻碍电流变化的感应电动势）","link":""},{"id":"phy1404","t":"磁通量·定义","s":"看到【直接套$\\varphi$=BS求磁通量】","c":"想到【先核验两个前提：匀强磁场、面与磁场垂直，否则需投影修正】；警惕【答题漏写单位Wb被扣分】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|00:45-01:18","orig":"（知识）匀强磁场中与磁场方向垂直的平面，φ=BS；前提必须是匀强磁场且平面与磁场垂直，单位韦伯（Wb）","link":""},{"id":"phy1405","t":"磁通量·通用公式与角度陷阱","s":"看到【题目给的角是平面与磁场的夹角，求磁通量】","c":"想到【先辨清角是相对法线还是相对磁场：相对法线用cos$\\alpha$、相对磁场用sin$\\theta$，二者互补】；警惕【直接把题目角度代进cos造成37$^{\\circ}$类题用cos不用sin的典型错误】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|01:18-03:07","orig":"（知识）平面不垂直磁场时φ=BS⊥=BScosα，α是平面与垂直磁场方向的夹角；若题目给的是平面与磁场方向夹角θ，则φ=BSsinθ（θ+α=90°）","link":""},{"id":"phy1406","t":"磁通量·有效面积","s":"看到【大线框套小磁场区域或两框比较磁通量】","c":"想到【只取磁场真实穿过且投影后的面积，不是几何框面积】；警惕【用外框总面积乘B算磁通量】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|03:07-03:59","orig":"（知识）有效面积指磁场实际覆盖且投影到垂直磁场方向的面积；两平面只要有效面积相同（如同为小圈面积），外圈再大磁通量也相等","link":""},{"id":"phy1407","t":"磁通量·磁感线净条数法","s":"看到【非匀强磁场或闭合曲面问磁通量大小】","c":"想到【改用数磁感线净条数：穿入与穿出相减；封闭曲面若净条数为零则$\\varphi$=0】；警惕【只数穿入不抵消穿出，或忽视方向相反的磁感线相互抵消】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|04:19-07:51","orig":"（知识）非匀强磁场中φ=BS失效，可用磁感线净条数计算：磁通量数值等于穿过平面的磁感线净条数，同方向相加、反方向相减（2上1下净条数=1）","link":""},{"id":"phy1408","t":"磁通量·数线比较例题","s":"看到【比较两个位置磁通量大小】","c":"想到【数净条数比较，先抵消反向线再比大小】；警惕【面内进出的线相互抵消后为零，误以为条数多磁通就大】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|07:51-08:45","orig":"（例）左图S₁穿2条、S₂穿3条⇒S₂磁通量大；右图左平面4进4出φ=0、右平面4进⇒右平面大","link":""},{"id":"phy1409","t":"磁通量·标矢性与正负规定","s":"看到【线框翻转或磁感线从两面穿入求磁通量】","c":"想到【先规定正方向再带正负号计算，翻转180$^{\\circ}$后$\\varphi$=-$\\varphi$_{0}】；警惕【磁通量是标量却忘了正负号规则，翻转后正负变化被忽略】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|08:45-11:36","orig":"（知识）磁通量是标量，但用正负表示穿入方向：人为规定平面正面，磁感线从正面穿入为正、穿出为负；实际大小取绝对值","link":""},{"id":"phy1410","t":"磁通量·变化量计算","s":"看到【平面转动180°后求磁通量变化量】","c":"想到【$\\Delta$φ=$\\varphi$末-$\\varphi$初，全程带符号运算，末态正负翻转时变化量为两倍大小】；警惕【提前取绝对值导致$\\Delta$φ算成0】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|11:36-15:08","orig":"（例）线框以ad为轴转动180°：φ₀=0.5Wb、末态φ=-0.5Wb，Δφ=(-0.5)-0.5=-1Wb，变化量大小1Wb；计算过程必须保留正负号，仅在最终求大小时取绝对值","link":""},{"id":"phy1411","t":"磁通量·通电导线旁移动圆环","s":"看到【通电直导线旁圆环平移，问磁通量变化】","c":"想到【直线电流两侧磁场方向相反，圆环跨越导线时两侧磁通抵消，$\\varphi$有先增后减为零再反向增的非单调变化】；警惕【误判圆环全程磁通量单调变化】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|15:08-19:34","orig":"（例）右手定则判直导线磁场：右侧向里左侧向外；P、Q关于导线对称则B等大反向；圆环右移时磁通量先增大、过导线正下方减为零、再反向增大、远离时减小","link":""},{"id":"phy1412","t":"磁通量·磁单极子模型","s":"看到【磁单极子或辐射状磁场的封闭球面磁通量】","c":"想到【类比点电荷电场线：以单极子为球心的任意球面净条数相等，$\\varphi$相同；B随距离增大而减小】；警惕【误以为球面越大磁通量越大，净条数不变】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|19:34-22:34","orig":"（例）磁单极子磁感线类似点电荷电场线呈辐射状发散；以其为球心的任意球面穿过磁通量相同（净条数相等）；靠近的a点磁感应强度大于远离的b点","link":""},{"id":"phy1413","t":"磁通量·转动线框综合计算","s":"看到【线框绕不同轴转动求磁通量变化量】","c":"想到【先按角度规则（磁场与平面夹角用sin）算初末$\\varphi$并带符号，再$\\varphi$末-$\\varphi$初；转轴不同初末磁通不同】；警惕【角度代错（sin/cos混淆）与转动后正负号未翻转是双重陷阱】","src":"物一轮224.了解磁通量及其变化完整视频_笔记","note":"视频|22:34-28:34","orig":"（例）卫星导线框：磁场与平面成37°时用sin37°=0.6计算；以ad为轴从水平转至竖直φ由6×10⁻⁶Wb变-8×10⁻⁶Wb，Δφ大小1.4×10⁻⁵Wb；以ab为轴转至竖直时磁感线与平面平行φ=0；转动改变正面方向时正负号变","link":""},{"id":"phy1414","t":"电磁感应·感应电流的产生条件","s":"看到【判断某场景中是否产生感应电流】","c":"想到【依次检查两个必要条件：回路是否闭合、磁通量是否变化，两者同时成立才有感应电流】；警惕【断开回路时即使磁通量变化也无感应电流】","src":"物一轮225.了解感应电流的产生条件_笔记","note":"视频|00:26-00:45","orig":"（知识）电磁感应现象：穿过闭合回路的磁通量发生变化时电路中产生电流；产生条件为闭合回路+磁通量变化，缺一不可。","link":""},{"id":"phy1415","t":"电磁感应·磁通量变化分析","s":"看到【分析磁通量是否发生变化】","c":"想到【从B、S、$\\theta$三个因素入手判断$\\varphi$变化，先明确磁场分布再看线圈位置】；警惕【只看面积或只看磁场强弱而漏掉夹角因素】","src":"物一轮225.了解感应电流的产生条件_笔记","note":"视频|00:45-00:54","orig":"（知识）φ=B·S·cosθ，可通过改变B、S或θ来改变磁通量；需先确定磁场分布，再分析线圈位置变化的影响。","link":""},{"id":"phy1416","t":"电磁感应·线框平移判断","s":"看到【线框在磁场中平移，判断有无感应电流】","c":"想到【匀强磁场中平移$\\varphi$不变无电流；非匀强磁场中平移$\\varphi$变化有电流】；警惕【平移是否产生电流取决于磁场随位置是否变化】","src":"物一轮225.了解感应电流的产生条件_笔记","note":"视频|00:54-02:59","orig":"（例）线框在通电直导线右侧向右移→磁场变弱φ减小→有感应电流；线框在匀强磁场中平移→B、S均不变→无感应电流。","link":""},{"id":"phy1417","t":"电磁感应·通电直导线周围磁场","s":"看到【线圈在通电直导线周围移动】","c":"想到【直导线磁场越靠近导线越强，正上方位置$\\varphi$=0且不随沿导线方向平移变化；对称点磁感应强度等大但方向相反】；警惕【B是矢量，大小相等方向不同则不相同】","src":"物一轮225.了解感应电流的产生条件_笔记","note":"视频|02:59-09:22","orig":"（例）线圈沿导线正上方移动时φ恒为零不变；从P到N移动φ由零变非零→有电流；对称点pq处B等大反向故不相同。","link":""},{"id":"phy1418","t":"电磁感应·平移与转动的磁通量差异","s":"看到【线圈平移或绕轴转动，判断磁通量变化】","c":"想到【在匀强磁场中平移不改有效面积则$\\varphi$不变，绕垂直于磁场的轴转动会改变有效面积使$\\varphi$变化】；警惕【需将俯视图转化为正视图做空间想象】","src":"物一轮225.了解感应电流的产生条件_笔记","note":"视频|09:22-12:39","orig":"（例）线圈沿纸面平移φ不变；绕OO′轴转动改变有效面积→φ变化产生感应电流。","link":""},{"id":"phy1419","t":"电磁感应·非匀强磁场分布细节","s":"看到【通电直导线一侧线圈做上下平移或转动】","c":"想到【直导线磁场分布不均匀但沿导线方向不变：沿导线方向平移$\\varphi$不变，转动或远离才使$\\varphi$变化】；警惕【磁通量先增后减再增类描述需逐段核对】","src":"物一轮225.了解感应电流的产生条件_笔记","note":"视频|12:39","orig":"（例）直导线右侧磁场垂直纸面向里；上下平移时磁感线密度不变φ不变；转动时φ从非零变为零。","link":""},{"id":"phy1420","t":"电磁感应·楞次定律理解","s":"看到【判断由磁通量变化引起的感应电流方向】","c":"想到【三步法：定原磁场方向及$\\varphi$增减$\\to$用增反减同定感应磁场方向$\\to$用安培定则定电流方向】；警惕【阻碍的是$\\varphi$的变化量而非$\\varphi$本身，最终磁通量仍会变化只是被减弱】","src":"物一轮226.用楞次定律判断感应电流方向_笔记","note":"视频|00:43-02:04","orig":"（知识）感应电流的磁场总要阻碍引起感应电流的磁通量的变化；阻碍的是变化而非原状态，阻碍不等于阻止。","link":""},{"id":"phy1421","t":"电磁感应·增反减同应用","s":"看到【磁通量减小（或增大），判断感应磁场方向】","c":"想到【增反减同：$\\varphi$减小则感应磁场与原磁场同向，$\\varphi$增大则反向】；警惕【误把阻碍理解为感应磁场总与原磁场方向相反】","src":"物一轮226.用楞次定律判断感应电流方向_笔记","note":"视频|02:04-05:44","orig":"（例）线圈在非匀强磁场中右移φ从10减到5，原磁场向里，感应磁场同向（减同），由安培定则得顺时针电流。","link":""},{"id":"phy1422","t":"电磁感应·磁通量先减后增的判断","s":"看到【磁通量先减小后增大、中间经过零点】","c":"想到【对每一段分别用增反减同；$\\varphi$=0只是转折点，两阶段感应磁场方向可能相同，电流方向可保持不变】；警惕【漏判$\\varphi$为零的临界转折点】","src":"物一轮226.用楞次定律判断感应电流方向_笔记","note":"视频|08:18-11:17","orig":"（例）条形磁铁经过线圈：N极向上φ减至0，感应磁场向上电流逆时针；S极向上φ从0增加，感应磁场仍向上，电流保持逆时针。","link":""},{"id":"phy1423","t":"电磁感应·原磁场反向时的判断","s":"看到【原电流变化导致磁场先减弱后反向增强】","c":"想到【磁场方向反转时分段判断，两阶段的感应电流方向可能恒定不变】；警惕【未意识到磁场方向反转后感应磁场方向反而不变】","src":"物一轮226.用楞次定律判断感应电流方向_笔记","note":"视频|11:17-14:06","orig":"（例）导线电流先减小（原磁场向里减弱→感应磁场同向→顺时针），后反向增大（原磁场向外增强→感应磁场仍向里→仍顺时针）。","link":""},{"id":"phy1424","t":"电磁感应·右手定则","s":"看到【导体棒切割磁感线判断感应电流或电动势方向】","c":"想到【直接用右手定则：磁感线穿掌心、拇指指切割方向、四指即电流方向】；警惕【右手管磁生电、左手管电磁生力；运动方向与磁场平行时不切割、无感应电流】","src":"物一轮226.用楞次定律判断感应电流方向_笔记","note":"视频|14:06-18:53","orig":"（知识）导体切割磁感线时：磁感线垂直穿入掌心，拇指指切割（运动）方向，四指弯曲方向即感应电流方向。","link":""},{"id":"phy1425","t":"电磁感应·右手定则与左手定则综合","s":"看到【一棒运动引起回路中另一棒受安培力】","c":"想到【先右手定则定感应电流方向，再左手定则定安培力方向；磁场方向与运动方向两个条件同时改变时安培力方向不变】；警惕【混淆左右手使用场景】","src":"物一轮226.用楞次定律判断感应电流方向_笔记","note":"视频|18:53-20:29","orig":"（例）ab棒运动产生感应电流（右手定则），经闭合回路流过cd棒，再用左手定则判断cd棒所受安培力方向。","link":""},{"id":"phy1426","t":"电磁感应·三大定则对比","s":"看到【需要区分右手定则、左手定则、安培定则的适用场景】","c":"想到【口诀右动左力：右手管运动生电，左手管电磁生力，安培定则管电生磁】；警惕【左手定则中负电荷运动方向与电流方向相反】","src":"物一轮226.用楞次定律判断感应电流方向_笔记","note":"视频|20:29","orig":"（知识）右手定则：切割磁感线（磁生电）；安培定则：电流产生磁场（电生磁，直线电流拇指指电流四指绕磁场，环形电流反之）；左手定则：安培力/洛伦兹力方向。","link":""},{"id":"phy1427","t":"电磁感应·楞次定律安培力推论","s":"看到【判断感应电流所受安培力（楞次力）方向】","c":"想到【安培力方向总以阻碍磁通量变化为目标，可用来拒去留、增缩减扩快速判断】；警惕【口诀失效（非匀强磁场）时回归阻碍$\\varphi$变化的本质】","src":"物一轮227.用楞次定律判断安培力方向_笔记","note":"视频|00:15-00:26","orig":"（知识）感应电流所受安培力方向总指向能阻碍磁通量变化的方向；机制有两种：受力产生运动趋势、受力产生形变趋势。","link":""},{"id":"phy1428","t":"电磁感应·来拒去留","s":"看到【磁体与线圈靠近或远离、导体在磁场中运动】","c":"想到【来拒去留：安培力总阻碍导体与磁场的相对运动，先判断$\\varphi$增减再确定阻碍方向】；警惕【来拒去留针对整体受力而非形变】","src":"物一轮227.用楞次定律判断安培力方向_笔记","note":"视频|00:26-02:03","orig":"（知识）磁体靠近线圈则被拒绝（远离），远离则被挽留（靠近）；线圈向右移致φ减小则安培力向左使其减速。","link":""},{"id":"phy1429","t":"电磁感应·增缩减扩","s":"看到【判断通电线圈（圆环）的收缩或扩张趋势】","c":"想到【增缩减扩：$\\varphi$增大则收缩、$\\varphi$减小则扩张】；警惕【该规律仅适用匀强磁场，非匀强磁场中可能扩张以引入外部磁感线，需回归本质分析】","src":"物一轮227.用楞次定律判断安培力方向_笔记","note":"视频|02:03-04:32","orig":"（知识）磁通量增加时线圈有收缩趋势，减少时有扩张趋势；本质是通过改变面积S阻碍φ变化（φ=BS）。","link":""},{"id":"phy1430","t":"电磁感应·闭环与开环的区别","s":"看到【磁极靠近闭合圆环或断开圆环】","c":"想到【闭合环受安培力表现出来拒；开环仅产生感应电动势而无电流、不受安培力】；警惕【磁通量变化即有感应电动势，与回路是否闭合无关】","src":"物一轮227.用楞次定律判断安培力方向_笔记","note":"视频|04:32-07:52","orig":"（例）无论N极还是S极靠近，A环都远离（来拒）；B环断开无电流故不动；有磁通量变化就有感应电动势。","link":""},{"id":"phy1431","t":"电磁感应·非匀强磁场中的形变趋势","s":"看到【小环套在通电大环内、处于非匀强磁场中】","c":"想到【净磁通量取正反两方向磁通之差；机械套用增缩减扩会出错，应分析如何通过扩张或收缩阻碍$\\varphi$净变化】；警惕【非匀强场中口诀失效】","src":"物一轮227.用楞次定律判断安培力方向_笔记","note":"视频|07:52-13:52","orig":"（例）A环套在通电B环内，电流增大使φ净（向里减向外）增加：感应电流逆时针（增反减同），且A环有扩张趋势以引入更多向外的磁通。","link":""},{"id":"phy1432","t":"电磁感应·φ-t图像与相互作用","s":"看到【在$\\varphi$-t图像上取多个时刻比较相互作用或电流大小】","c":"想到【由$\\varphi$增减定吸引/排斥与缩扩趋势；感应电流大小取决于斜率（变化率）而非$\\varphi$数值】；警惕【把$\\varphi$最大当成电流最大】","src":"物一轮227.用楞次定律判断安培力方向_笔记","note":"视频|13:52","orig":"（例）φ-t图像上：φ减小的时刻两环相互吸引（阻碍φ减小），φ增大的时刻环有收缩趋势；φ变化率最大时刻感应电流最大。","link":""},{"id":"phy1433","t":"电磁感应·自感现象定义","s":"看到【线圈中自身电流发生变化】","c":"想到【自感本质：电流变化$\\to$磁通量变化$\\to$产生感应电动势阻碍原电流变化（增反减同）】；警惕【强调的是自感电动势而非感应电流的简单叠加】","src":"物一轮228.用楞次定律分析自感现象_笔记","note":"视频|00:06-02:01","orig":"（知识）自感：导体回路因自身电流变化产生感应电动势；感应电流总阻碍原电流的变化，实际电流为原电流与感应电流的叠加。","link":""},{"id":"phy1434","t":"电磁感应·通电自感","s":"看到【接通电源瞬间灯泡逐渐变亮而非立即变亮】","c":"想到【通电自感：线圈阻碍电流增大，电流呈缓慢增加特征】；警惕【闭合瞬间电流变化率最大，自感效应最强】","src":"物一轮228.用楞次定律分析自感现象_笔记","note":"视频|02:12-04:38","orig":"（知识）开关闭合瞬间线圈电流试图从0突变，自感电动势阻碍电流增加：初始电流几乎为0，随后缓慢增至稳定，灯泡逐渐变亮。","link":""},{"id":"phy1435","t":"电磁感应·断电自感","s":"看到【断开开关瞬间灯泡不立即熄灭而是逐渐变暗】","c":"想到【断电自感：线圈维持原电流方向缓慢衰减，磁场能转化为电能】；警惕【断电后感应电流方向与原电流相同、不反转】","src":"物一轮228.用楞次定律分析自感现象_笔记","note":"视频|04:38-06:36","orig":"（知识）断开电源瞬间线圈电流试图从I突变到0，自感电动势阻碍电流减小：电流保持I后缓慢衰减至0，灯泡渐暗；能量来自线圈储存的磁场能。","link":""},{"id":"phy1436","t":"电磁感应·电感与电容对电流的阻碍","s":"看到【比较电感、电容、电阻对直流/交流及不同频率的阻碍作用】","c":"想到【口诀：电感怕高频，电容爱高频；电阻与频率无关】；警惕【电感与电容对频率的响应规律恰好相反，勿记混】","src":"物一轮228.用楞次定律分析自感现象_笔记","note":"视频|06:36-09:47","orig":"（知识）电感通直流阻交流、通低频阻高频；电容隔直流通交流、通高频阻低频；电阻对频率无响应。","link":""},{"id":"phy1437","t":"电磁感应·断电自感灯泡是否闪亮","s":"看到【断电自感中判断灯泡是闪亮后熄灭还是直接熄灭】","c":"想到【比较断开前线圈支路与灯泡支路电流大小：线圈电流更大则流过灯泡的电流突增、先闪亮后熄灭；不构成回路则立即熄灭】；警惕【忽略线圈初始电流的方向和大小】","src":"物一轮228.用楞次定律分析自感现象_笔记","note":"视频|09:47-12:09","orig":"（例）L电阻很小稳定时短路并联灯P：断开后L维持原电流经P缓慢减小→P先闪亮后熄灭；Q支路立即断电熄灭。","link":""},{"id":"phy1438","t":"电磁感应·断电前后电流路径比较","s":"看到【断开后电流改经线圈支路流过灯泡的电路比较】","c":"想到【灯泡断电后的表现取决于流经它的电流如何变化：从较小电流衰减则直接变暗，从较大电流衰减则先更亮后变暗】；警惕【混淆断开前后电流路径】","src":"物一轮228.用楞次定律分析自感现象_笔记","note":"视频|12:09-15:09","orig":"（例）R和L电阻都小于灯泡电阻：电路甲断开后电流从较小值衰减→灯直接变暗；电路乙线圈较大电流流过灯→灯先更亮后变暗。","link":""},{"id":"phy1439","t":"电磁感应·交流频率变化对亮度影响","s":"看到【交流电频率变化时判断电感/电容/电阻支路灯泡亮度】","c":"想到【频率升高：电感阻碍增强$\\to$变暗，电容阻碍减弱$\\to$变亮，电阻不变；反之亦然】；警惕【方向判断与通高频/低频特性直接关联】","src":"物一轮228.用楞次定律分析自感现象_笔记","note":"视频|15:09","orig":"（例）50Hz时三灯亮度相同，频率升至60Hz：电感支路阻碍增强灯变暗，电容支路阻碍减弱灯变亮，电阻支路不变。","link":""},{"id":"phy1440","t":"电磁感应·法拉第电磁感应定律定位","s":"看到【涉及感应电动势与电流的定量计算】","c":"想到【以E=n$\\Delta$φ/$\\Delta$t和$\\varepsilon$=BLv为核心工具，先求电动势再入电路、动力学求解】；警惕【只背公式而忽略其作为综合问题基础的定位】","src":"物一轮229.【课前必看】本讲听课建议_笔记","note":"视频|00:28-00:33","orig":"（知识）法拉第电磁感应定律定量分析感应电动势与感应电流，是后续电路分析、动力学综合问题的定量基础。","link":""},{"id":"phy1441","t":"电磁感应·感应电动势分类","s":"看到【区分动生电动势与感生电动势】","c":"想到【按磁通量变化原因分类：S变化（切割）为动生，B变化为感生，本质分别是洛伦兹力与涡旋电场】；警惕【两类电动势本质不同但都遵循法拉第定律】","src":"物一轮229.【课前必看】本讲听课建议_笔记","note":"视频|00:33-02:03","orig":"（知识）动生电动势：导体切割磁感线产生（本质为洛伦兹力）；感生电动势：磁场变化产生（本质为涡旋电场）。","link":""},{"id":"phy1442","t":"电磁感应·考情与备考重点","s":"看到【备考电磁感应定律的考向】","c":"想到【重点掌握定律公式的推导与场景应用，尤其$\\varepsilon$=BLv的适用条件与磁通量变化率随时间的关系】；警惕【磁通量变化率与时间的对应关系是常见易错点】","src":"物一轮229.【课前必看】本讲听课建议_笔记","note":"视频|02:03","orig":"（知识）2024年8个省份考查：选择题考电磁感应定律（福建/北京/广东/山东），计算题考动生电动势（浙江/河北/甲卷/安徽）。","link":""},{"id":"phy1443","t":"电磁感应·感应电流产生的本质","s":"看到【分析感应电流产生的前提条件】","c":"想到【磁通量变化产生感应电动势，闭合回路中才形成持续电流；感应电动势将机械能等转化为电能】；警惕【有电动势无闭合回路时只有电压无电流】","src":"物一轮230.了解电磁感应定律的内容_笔记","note":"视频|00:47-03:34","orig":"（知识）磁通量变化是因、产生感应电动势是果；持续感应电流的条件=闭合回路+感应电动势，类比普通电路的闭合回路+电源。","link":""},{"id":"phy1444","t":"电磁感应·法拉第电磁感应定律公式","s":"看到【计算感应电动势的大小】","c":"想到【用E=n·$\\Delta$φ/$\\Delta$t，多匝线圈按有效匝数放大电动势】；警惕【E取决于变化快慢，与Φ大小、$\\Delta$Φ大小均无必然关系】","src":"物一轮230.了解电磁感应定律的内容_笔记","note":"视频|03:34-06:49","orig":"（知识）E=n·Δφ/Δt：感应电动势与磁通量变化率成正比，n为线圈匝数；类比a=Δv/Δt理解变化率。","link":""},{"id":"phy1445","t":"电磁感应·Φ、ΔΦ、Δφ/Δt三者辨析","s":"看到【辨析磁通量大、变化大、变化快与电动势的关系】","c":"想到【Φ大若不变则E=0；$\\Delta$Φ大需限定相同$\\Delta$t才能比；变化快即E大】；警惕【类比v=0时a$\\neq$0：Φ=0但斜率不为零时E$\\neq$0】","src":"物一轮230.了解电磁感应定律的内容_笔记","note":"视频|06:49-09:36","orig":"（知识）Φ=10000Wb不变时E=0；ΔΦ大但Δt更大时E可能小；变化快即Δφ/Δt大则E大。","link":""},{"id":"phy1446","t":"电磁感应·平均与瞬时电动势","s":"看到【区分平均感应电动势与瞬时感应电动势】","c":"想到【Φ-t图像上割线斜率为平均值、切线斜率为瞬时值】；警惕【图像题中混淆割线与切线】","src":"物一轮230.了解电磁感应定律的内容_笔记","note":"视频|09:36-11:56","orig":"（知识）Δt为有限时间段得平均电动势（Φ-t图割线斜率）；Δt→0得瞬时电动势（切线斜率）。","link":""},{"id":"phy1447","t":"电磁感应·概念判断选择题","s":"看到【判断关于感应电流、电动势的概念性选项】","c":"想到【逐项核对闭合回路与磁通量变化两条件；凡涉及$\\Delta$Φ比较必先检查$\\Delta$t是否相同】；警惕【混淆Φ、$\\Delta$Φ、$\\Delta$φ/$\\Delta$t三者关系】","src":"物一轮230.了解电磁感应定律的内容_笔记","note":"视频|11:56-16:15","orig":"（例）概念题：只有同时满足闭合回路与磁通量变化才有感应电流；未控制Δt变量不能由ΔΦ大得出E大。","link":""},{"id":"phy1448","t":"电磁感应·B-t图像分析","s":"看到【给出B-t或Φ-t图像求电动势变化与电流方向】","c":"想到【有效面积不变时斜率直接反映E的大小变化，方向用增反减同判断】；警惕【把B的大小当成E的大小】","src":"物一轮230.了解电磁感应定律的内容_笔记","note":"视频|16:15-20:41","orig":"（例）B-t图像：S不变时Δφ/Δt∝ΔB/Δt，斜率减小则E减小；B增大时感应磁场反向，电流顺时针。","link":""},{"id":"phy1449","t":"电磁感应·定量计算综合","s":"看到【结合电阻定量计算感应电流】","c":"想到【流程：E=n($\\Delta$B/$\\Delta$t)·S$\\to$求总电阻$\\to$I=E/R；注意有效面积与单位长度电阻的换算】；警惕【有效面积取错（如整圆与半圆）】","src":"物一轮230.了解电磁感应定律的内容_笔记","note":"视频|20:41-26:09","orig":"（例）半圆回路：Φ=B·S=0.2T×½π(0.5m)²，E=(ΔB/Δt)·S，R=λ·2πr为单位长度电阻换算，得I=5A。","link":""},{"id":"phy1450","t":"电磁感应·电动势比值问题","s":"看到【比较不同半径（大小）回路在同磁场变化下的电动势】","c":"想到【$\\Delta$B/$\\Delta$t相同时E∝S∝r^{2}，按面积比处理】；警惕【误将周长比当作面积比】","src":"物一轮230.了解电磁感应定律的内容_笔记","note":"视频|26:09","orig":"（例）ΔB/Δt相同、半径比1:3：E∝S∝r²得电动势比1:9；B增大时感应电流为顺时针。","link":""},{"id":"phy1451","t":"电磁感应·两类感应电动势","s":"看到【区分感生电动势与动生电动势】","c":"想到【按磁通量变化原因分类：磁场B变为感生、面积S变（切割）为动生，统一遵循法拉第定律】；警惕【混用两类产生机制】","src":"物一轮231.了解动生电动势的计算方法_笔记","note":"视频|00:17-02:19","orig":"（知识）φ=B·S：B变化产生感生电动势（如电磁炉），S变化产生动生电动势（导体棒切割，如发电机）；两者都遵循E=Δφ/Δt。","link":""},{"id":"phy1452","t":"电磁感应·动生电动势基本公式","s":"看到【导体棒平动切割磁感线求电动势】","c":"想到【直接用E=Blv，v取瞬时值得瞬时电动势、取平均值得平均值；电动势产生不依赖回路闭合】；警惕【误认为无闭合回路则无电动势】","src":"物一轮231.了解动生电动势的计算方法_笔记","note":"视频|02:19-08:36","orig":"（知识）E=Δφ/Δt=B·ΔS/Δt，ΔS=l·vΔt，得E=Blv（B、l、v两两垂直）；v可为瞬时或平均速度，与回路是否闭合无关。","link":""},{"id":"phy1453","t":"电磁感应·非垂直场景的投影处理","s":"看到【B、l、v三者不完全垂直求动生电动势】","c":"想到【将不垂直的量投影到垂直方向，弯曲导体取首尾相连后的等效长度投影】；警惕【三者共面时无同时垂直于另两量的分量，E=0】","src":"物一轮231.了解动生电动势的计算方法_笔记","note":"视频|08:36-13:17","orig":"（知识）B与v不垂直取v⊥=vsinθ；l与v不垂直取等效长度（垂直速度方向的投影）；B、l、v共面时电动势为零。","link":""},{"id":"phy1454","t":"电磁感应·旋转切割公式","s":"看到【导体棒绕一端旋转切割磁感线或圆盘发电机模型】","c":"想到【用E=½Bl^{2}$\\omega$，等效为平动切割取中点速度】；警惕【圆盘问题实际研究的是电刷间的半径导体棒而非整个圆盘】","src":"物一轮231.了解动生电动势的计算方法_笔记","note":"视频|13:17-16:29","orig":"（知识）导体棒绕端点旋转：ΔS=½l²Δθ，E=½Bl²ω=B·l·v中点（v中点=ωl/2）。","link":""},{"id":"phy1455","t":"电磁感应·公式适用条件判断","s":"看到【判断不同方位组合下电动势表达式】","c":"想到【逐项检查两两垂直关系，不垂直的量取sin$\\theta$投影，共面则E=0】；警惕【忽视共面情形的零电动势】","src":"物一轮231.了解动生电动势的计算方法_笔记","note":"视频|16:29-20:34","orig":"（例）方向判断题：B⊥l且B⊥v、v与l夹θ等多种组合均可得E=Blvsinθ；B、l、v共面的选项电动势为零。","link":""},{"id":"phy1456","t":"电磁感应·电动势比值与电流方向","s":"看到【比较不同条件下的电动势比值并判断棒中电流方向】","c":"想到【E=Blv中各量比例关系直接迁移；方向用右手定则：掌心对磁场、拇指指运动、四指即电流】；警惕【混淆电流方向与电子流动方向】","src":"物一轮231.了解动生电动势的计算方法_笔记","note":"视频|20:34-22:13","orig":"（例）导体棒匀速运动：磁感应强度加倍则电动势加倍，E₁:E₂=1:2；电流方向由右手定则判断。","link":""},{"id":"phy1457","t":"电磁感应·不规则导体的等效长度","s":"看到【弯曲/折线导体穿越磁场边界切割磁感线】","c":"想到【用等效长度（首尾相连后垂直速度方向的投影）随时间的变化分析E：进入阶段均匀变化、完全进入不变、离开阶段再变化；多边切割需叠加或抵消】；警惕【投影长度变化规律判断错】","src":"物一轮231.了解动生电动势的计算方法_笔记","note":"视频|25:59","orig":"（例）三角形线框穿越边界：0→d/v等效长度均匀减小，d/v→2d/v不变，2d/v→3d/v减小；两边切割效应相减得净电动势。","link":""},{"id":"phy1458","t":"电磁感应·感生电动势本质","s":"看到【追问感生电动势产生的本质原因】","c":"想到【变化磁场激发涡旋电场，作为非静电力搬运电荷形成电动势；动生电动势的非静电力是洛伦兹力】；警惕【把磁通量变化本身当作非静电力】","src":"物一轮232.感生电动势本质_笔记","note":"视频|01:09-09:44","orig":"（知识）电动势E=W非/q；磁通量变化是表面原因，非静电力做功才是本质：感生对应涡旋电场力，动生对应洛伦兹力。","link":""},{"id":"phy1459","t":"电磁感应·涡旋电场与静电场区别","s":"看到【比较涡旋电场（感生电场）与静电场】","c":"想到【涡旋电场线闭合、做功与路径相关、不存在电势概念】；警惕【对涡旋电场套用电势、电势能等静电场概念】","src":"物一轮232.感生电动势本质_笔记","note":"视频|01:09-09:44","orig":"（知识）静电场线起于正电荷止于负电荷；涡旋电场线闭合无端点，做功与路径有关（沿电场线一周W≠0），属非保守力场，无电势能概念。","link":""},{"id":"phy1460","t":"电磁感应·感生电动势计算","s":"看到【电荷在变化磁场中运动一周求感生电动势或涡旋电场强度】","c":"想到【电动势定义式与法拉第定律联立，再用功的定义W=F·路径反推场强】；警惕【混淆电动势E与电场强度E场的物理意义】","src":"物一轮232.感生电动势本质_笔记","note":"视频|09:44-15:11","orig":"（例）小球在变化磁场中运动一周：联立E=W非/q与E=ΔΦ/Δt=πr²·ΔB/Δt=kπr²，由W=F·2πr反推涡旋电场，场强为kr/2。","link":""},{"id":"phy1461","t":"电磁感应·圆盘实验与涡流","s":"看到【旋转圆盘（或金属块）在磁场中产生涡流的现象】","c":"想到【整体磁通量不变不等于无涡流：任取局部回路磁通量变化即产生涡流；涡流受电磁作用体现楞次定律（阻碍相对运动）】；警惕【只用整体磁通量判断而漏掉局部回路】","src":"物一轮232.感生电动势本质_笔记","note":"视频|15:11","orig":"（例）旋转铜盘可视为径向导体棒切割产生动生电动势（圆心与边缘间电势差）；局部涡流产生附加磁场带动磁针转动；整体磁通量始终为零但局部回路磁通量变化。","link":""},{"id":"phy1462","t":"电磁感应·涡流的应用与防止","s":"看到【分析涡流热效应的利用或防护措施】","c":"想到【增大涡流可加热（冶炼炉），叠层切断涡流路径可减少发热（变压器硅钢片）】；警惕【不理解叠层设计背后的切断涡流回路原理】","src":"物一轮232.感生电动势本质_笔记","note":"视频|15:11","orig":"（知识）应用：真空冶炼炉利用高频交流电产生涡流自加热；防止：变压器铁芯采用绝缘硅钢片叠层切断大涡流路径。","link":""},{"id":"phy1463","t":"电磁感应·动生电动势的微观本质","s":"看到【导体棒切割磁感线，追问电动势的非静电力来源/微观本质】","c":"想到【洛伦兹力沿棒方向的分力充当非静电力，E=W非/q；宏观表现为E=Blv】；警惕【洛伦兹力整体不做功，但分力可做功且代数和为零，两者不矛盾】","src":"物一轮233.动生电动势本质_笔记","note":"视频|00:14-05:00","orig":"（知识）导体棒中自由电荷随棒运动，受洛伦兹力沿棒方向的分量F1作为非静电力搬运电荷，产生电动势","link":""},{"id":"phy1464","t":"电磁感应·电荷聚集与电势高低","s":"看到【分析棒内电荷聚集过程及两端电势高低】","c":"想到【运动电荷受洛伦兹力偏转向一端聚集，建立静电场后达动态平衡，聚集正电的一端为高电势】；警惕【电势高低由非静电力搬运方向决定，勿凭电流方向想当然】","src":"物一轮233.动生电动势本质_笔记","note":"视频|00:14-05:00","orig":"（知识）负电荷受F1向下聚集，上端显正电、下端显负电，形成向下的静电场阻碍电荷继续移动","link":""},{"id":"phy1465","t":"电磁感应·洛伦兹力分量的速度分解","s":"看到【讨论洛伦兹力做功与速度分解的关系】","c":"想到【把电荷实际运动分解为随棒速度与沿棒迁移速度，两个洛伦兹力分量分别对应；nF2等于宏观安培力，方向与棒运动相反】；警惕【F1做正功、F2做负功，W1+W2=0，不能说洛伦兹力做功】","src":"物一轮233.动生电动势本质_笔记","note":"视频|00:14-05:00","orig":"（知识）电荷实际速度v是随棒运动速度v1与沿棒迁移速度v2的合速度，F1对应v1产生的分量，F2对应v2产生的分量","link":""},{"id":"phy1466","t":"电磁感应·法拉第定律推导E=Blv","s":"看到【要求从磁通量变化角度推导动生电动势表达式】","c":"想到【$\\Delta$Φ=B·l·v$\\Delta$t，E=$\\Delta$Φ/$\\Delta$t=Blv】；警惕【$\\Delta$S=l·v$\\Delta$t的几何关系，l是有效切割长度】","src":"物一轮233.动生电动势本质_笔记","note":"视频|05:00","orig":"（例）Δφ=BΔS=B(vΔt)l，E=Δφ/Δt=Blv","link":""},{"id":"phy1467","t":"电磁感应·电动势定义法推导E=Blv","s":"看到【要求从非静电力做功角度推导动生电动势】","c":"想到【F1=Bqv，W非=Bqvl，E=W非/q=Blv，两种方法结果一致可互为验证】；警惕【W非是分力F1做的功，不是洛伦兹力合力做的功】","src":"物一轮233.动生电动势本质_笔记","note":"视频|05:00","orig":"（例）非静电力F1=Bqv，W非=F1l=Bqvl，E=W非/q=Blv，与法拉第定律结果一致","link":""},{"id":"phy1468","t":"电磁感应·动生与感生电动势对比","s":"看到【对比动生电动势与感生电动势的本质区别】","c":"想到【动生由洛伦兹力分力驱动，能量来自机械能；感生由变化磁场激发的感应电场驱动，能量来自磁场能】；警惕【两者能量转换机制不同，驱动电荷的「非静电力」来源不同】","src":"物一轮233.动生电动势本质_笔记","note":"视频|05:00","orig":"（知识）动生：洛伦兹力分力驱动，机械能→电能；感生：变化磁场激发的感应电场驱动，磁场能→电能","link":""},{"id":"phy1469","t":"电磁感应与电路·考情与解题定位","s":"看到【电磁感应综合题，第一步要求解电路参量】","c":"想到【先求感应电流I，它是后续求电压U、电功率P、安培力及动力学分析的基础】；警惕【解题第一步常是电流求解，跳过直接分析受力会卡壳】","src":"物一轮234.【课前必看】本讲听课建议-电磁感应与电路综合_笔记","note":"视频|02:24-03:24","orig":"（知识）电磁感应与电路综合为中频考点、难度中等，主要出现在选择题，解答题中作为前置知识；电流求解是动力学问题的必备基础","link":""},{"id":"phy1470","t":"电磁感应与电路·基本工具链","s":"看到【由感应电动势求回路电流】","c":"想到【工具链：楞次定律定方向＋法拉第定律算e＋闭合电路欧姆定律求I】；警惕【e与I之间必须借助电路结构（内外电阻）衔接】","src":"物一轮234.【课前必看】本讲听课建议-电磁感应与电路综合_笔记","note":"视频|03:24","orig":"（知识）需掌握楞次定律（判断电流方向）、法拉第电磁感应定律（计算电动势e），建立e与I的联系需结合电路知识","link":""},{"id":"phy1471","t":"电磁感应与电路·电路结构识别","s":"看到【电磁感应场景下的电路分析，电路结构不熟悉】","c":"想到【先识别电路结构：产生感应电动势的部分（线圈/导体棒）等效为电源内电路，其余为外电路，再画等效电路图】；警惕【不先等效转换电路就直接套欧姆定律易出错】","src":"物一轮234.【课前必看】本讲听课建议-电磁感应与电路综合_笔记","note":"视频|03:24","orig":"（知识）电磁感应场景下需区分串并联及等效电路，把产生感应电动势的部分等效为电源处理","link":""},{"id":"phy1472","t":"电磁感应电路·感生电动势与等效电源","s":"看到【线圈中磁场变化（增强/减弱）产生感应电流，要分析电路】","c":"想到【用楞次定律判断感应电流方向（磁场增强时感应磁场与原磁场反向）；产生感生电动势的线圈等效为电源，线圈电阻即内阻】；警惕【电源内部电流从负极流向正极，据此定正负极】","src":"物一轮235.识别电路结构与电路规律应用-电磁感应与电路综合_笔记","note":"视频|01:04-01:21","orig":"（知识）线圈中磁场持续增强时，按楞次定律产生感生电动势；产生感生电动势的部分等效为电源，其阻值为电源内阻","link":""},{"id":"phy1473","t":"电磁感应电路·动生电动势与右手定则","s":"看到【导体棒在导轨上平动切割磁感线，要判断电流方向或极性】","c":"想到【用右手定则判断，切割磁感线的导体棒等效为电源，棒电阻为内阻，四指指向一端为正极】；警惕【动生用右手定则，感生用楞次定律/安培定则，别混用】","src":"物一轮235.识别电路结构与电路规律应用-电磁感应与电路综合_笔记","note":"视频|01:21-01:50","orig":"（知识）导体棒切割磁感线产生动生电动势；右手定则：磁感线穿掌心，大拇指指向运动方向，四指指向电流方向","link":""},{"id":"phy1474","t":"电磁感应电路·等效电路转换通法","s":"看到【电磁感应题中要求电流、电压，电路结构复杂难以下手】","c":"想到【两步转化：①产生感应电动势的部分（线圈/导体棒）划为内电路，其余为外电路；②结合楞次定律或右手定则判断电流方向，按「电源内部电流负极$\\to$正极」定正负极，画出熟悉电路】；警惕【正负极判断错会导致所有电势比较全错】","src":"物一轮235.识别电路结构与电路规律应用-电磁感应与电路综合_笔记","note":"视频|01:50-05:09","orig":"（知识）步骤一：识别电源部分（产生感应电动势处）为内电路，其余为外电路；步骤二：确定等效电源正负极（电源内部电流从负极流向正极）","link":""},{"id":"phy1475","t":"电磁感应电路·闭合电路欧姆定律","s":"看到【电路中含电动机、电容器等非纯电阻元件，求电流】","c":"想到【E=U外+U内恒成立；I=E/(R+r)只适用于纯电阻电路】；警惕【非纯电阻电路中UIT$\\neq$I^{2}Rt，电能部分转化为其他形式能量】","src":"物一轮235.识别电路结构与电路规律应用-电磁感应与电路综合_笔记","note":"视频|05:09-06:39","orig":"（知识）E=U外+U内适用于任意闭合电路（含非纯电阻）；纯电阻电路I=E/(R+r)","link":""},{"id":"phy1476","t":"电磁感应电路·电功与电热","s":"看到【区分电功与电热，或分析电动机的功率问题】","c":"想到【W=UIt与Q=I^{2}Rt任意电路都适用；纯电阻电路两者相等可互换，非纯电阻电路W>Q（电能部分转化为机械能等）】；警惕【求电动机发热只能用I^{2}Rt，不能用UI】","src":"物一轮235.识别电路结构与电路规律应用-电磁感应与电路综合_笔记","note":"视频|06:39-08:06","orig":"（知识）W=UIt、P=UI、Q=I²Rt（焦耳定律）任意电路适用；纯电阻电路W=Q，非纯电阻电路W>Q","link":""},{"id":"phy1477","t":"电磁感应电路·通过回路的电荷量","s":"看到【电磁感应中求通过回路（或导体棒横截面）的电荷量】","c":"想到【q=n$\\Delta$Φ/R总，与过程快慢无关，适用于非恒定电流；前提是回路电流仅由电磁感应产生（无其他电源）】；警惕【算出的是干路电荷量，问支路时按q1/q2=I1/I2比例分配；含外部电源的回路不可用】","src":"物一轮235.识别电路结构与电路规律应用-电磁感应与电路综合_笔记","note":"视频|08:06","orig":"（知识）q=It、I=E/R、E=nΔΦ/Δt联立得q=nΔΦ/R总；用平均值推导，适用于非恒定电流；结果为干路电荷量，支路按电流比例分配","link":""},{"id":"phy1478","t":"电磁感应电路·感应电流与电势综合计算","s":"看到【线圈磁通量均匀变化，求感应电流并比较某两点电势高低】","c":"想到【E=n$\\Delta$Φ/$\\Delta$t，I=E/R总（外阻+内阻）；方向用楞次定律，电势用「电源内部电流由负极流向正极」判断，正极电势高】；警惕【R总勿漏线圈内阻；开路时E=U仍可比较电势】","src":"物一轮236.例题讲解与练习完整视频-电磁感应与电路综合_笔记","note":"视频|00:03-07:52","orig":"（例）线圈n=100匝，ΔΦ=0.05Wb、Δt=0.1s得E=50V；R总=40+10=50Ω，I=1A；楞次定律判逆时针电流，电源内部电流负→正故φA>φB","link":""},{"id":"phy1479","t":"电磁感应电路·焦耳热与电荷量双法验证","s":"看到【求电磁感应回路的焦耳热和通过的电荷量】","c":"想到【恒定电流时Q=I^{2}R总t、q=It；一般情形q=n$\\Delta$Φ/R总；两种方法可互相验证】；警惕【Q要用全电路总电阻（含内阻），电荷量公式中R也是R总】","src":"物一轮236.例题讲解与练习完整视频-电磁感应与电路综合_笔记","note":"视频|00:03-07:52","orig":"（例）Q=I²Rt=1²×50×0.2=10J；q=It=0.2C，或q=nΔΦ/R总=100×0.1/50=0.2C，两法一致","link":""},{"id":"phy1480","t":"电磁感应电路·并联支路电荷量分配","s":"看到【求电磁感应中通过某一并联支路的电荷量】","c":"想到【先算等效总电阻和干路电流，再按并联分流比例求支路电流，q支=I支t】；警惕【不能直接把n$\\Delta$Φ/R总用在支路上，那是干路电荷量】","src":"物一轮236.例题讲解与练习完整视频-电磁感应与电路综合_笔记","note":"视频|00:03-07:52","orig":"（例）并联R=20Ω后R新=40×20/(40+20)+10=40/3Ω，I总=15/7A，I_R=5/7A，q'=5/7×0.2=1/7C","link":""},{"id":"phy1481","t":"电磁感应电路·旋转切割电势比较","s":"看到【导体棒绕一端在磁场中旋转切割，比较多点电势高低】","c":"想到【旋转切割电动势U=½B$\\omega$L^{2}，L为各点到转轴的距离（有效长度）；选固定参考点（转轴），分段算电动势再比较电势差】；警惕【有效长度是到转轴的距离，不是杆总长；无电流（开路）时电动势等于路端电压仍可比电势】","src":"物一轮236.例题讲解与练习完整视频-电磁感应与电路综合_笔记","note":"视频|07:52-16:49","orig":"（例）OA段U_OA=½BωR²、φO>φA；OB段U_OB=½Bω(√5R)²更大，得φO>φA>φB=φC","link":""},{"id":"phy1482","t":"电磁感应电路·导轨并联电阻发热","s":"看到【导体棒匀速切割，外电路多电阻（含并联），求某电阻（如内阻）产生的热量】","c":"想到【E=Blv$\\to$I=E/R总（并联先化简）$\\to$目标电阻用Q=I^{2}Rt单独计算】；警惕【时间单位换算（分钟$\\to$秒）；区分电源内部与外部电流方向；只算目标电阻的发热】","src":"物一轮236.例题讲解与练习完整视频-电磁感应与电路综合_笔记","note":"视频|16:49-19:33","orig":"（例）E=Blv=9V，R总=1+(3×6)/(3+6)=3Ω，I=3A，内阻发热Q=I²rt=3²×1×60=540J","link":""},{"id":"phy1483","t":"电磁感应电路·多棒旋转切割的等效电路","s":"看到【多根导体棒共点旋转，部分在磁场内切割，分析电流方向与大小】","c":"想到【空间结构简化为平面等效电路（多电阻并联）；切割棒为电源（电流负$\\to$正），不切割的棒为用电器（电流从高电势流向低电势）；多电源可用叠加原理分别计算】；警惕【同一根棒作电源与作用电器时电流方向相反，但端点电势高低可能不变；电流大小只有有限几种取值】","src":"物一轮236.例题讲解与练习完整视频-电磁感应与电路综合_笔记","note":"视频|19:33","orig":"（例）三根相同电阻丝共点O，1根在磁场内切割（电源）、2根为用电器（三电阻并联）；单独切割I=2E/3r，共同切割I=E/3r；A点电势始终高于O点","link":""},{"id":"phy1484","t":"电磁感应图像·分析流程通法","s":"看到【电磁感应图像题，要判断I、U、F、P随位移x（或时间）的变化】","c":"想到【分析顺序：先由E=Blv和闭合电路欧姆定律求电流I，再推F=BIL、P=Fv或I^{2}R、U=IR等其他量】；警惕【电流是其余电路参量的计算基础，顺序错则全错】","src":"物一轮237.用图像方法分析电路参量-电磁感应与电路综合_笔记","note":"视频|00:04-00:47","orig":"（知识）电磁感应问题先计算电流大小，再以此为基础计算安培力、功和功率等物理量","link":""},{"id":"phy1485","t":"电磁感应图像·线框穿磁场三阶段","s":"看到【线框以恒定速度穿入、完全在磁场内、穿出磁场，判断I-U-F-x图像】","c":"想到【按磁场边界分段：进/出磁场单边切割电流恒定，完全在磁场内两边电动势抵消电流为零；进出磁场安培力大小相等、方向相同（均阻碍运动）】；警惕【U随「该边作电源还是用电器」而变：作电源是路端电压3/4BLv，作用电器是1/4BLv】","src":"物一轮237.用图像方法分析电路参量-电磁感应与电路综合_笔记","note":"视频|00:47-10:23","orig":"（例）线框0→L进磁场I=BLv/4R恒定；L→2L全在磁场内两边切割抵消I=0；2L→3L出磁场I恒定；Uab依次为3/4BLv、BLv、1/4BLv；进出磁场安培力等大同向（均向左）","link":""},{"id":"phy1486","t":"电磁感应图像·线框穿越两个磁场区域","s":"看到【线框依次进入、离开两个相邻磁场区域，判断电流图像】","c":"想到【按区域边界分段，等效切割长度决定电动势大小；电流方向由楞次定律判断，进入不同区域方向相反（图像正负号变化）】；警惕【两侧边同时切割时电动势叠加，电流可达单侧的2倍，别漏这段】","src":"物一轮237.用图像方法分析电路参量-电磁感应与电路综合_笔记","note":"视频|10:23-17:30","orig":"（例）线框依次进入I区（逆时针/正方向）、II区（顺时针/负方向）；II区最大电流是I区的2倍（两侧同时切割）","link":""},{"id":"phy1487","t":"电磁感应图像·有效长度线性变化（斜切割）","s":"看到【导体棒沿三角形/斜边界导轨运动，有效切割长度随时间线性变化，判断F、P图像】","c":"想到【先分段写出有效长度L(t)：I=BL(t)v/R与L线性相关；F=B^{2}L^{2}v/R与P=B^{2}L^{2}v^{2}/R是L的二次函数，U=IR与I规律相同】；警惕【安培力和电功率是长度的二次函数（图像为抛物线型），勿画成线性】","src":"物一轮237.用图像方法分析电路参量-电磁感应与电路综合_笔记","note":"视频|17:30","orig":"（例）有效长度先线性增加（I=Bv0(L0+kV0t)/R线性增大）、中间恒定、后线性减小；F=B²L²v0/R为二次函数（含常数项）、P=B²L²v0²/R与F同规律、U=IR与I同规律","link":""},{"id":"phy1488","t":"电磁感应图像·图像细节读法","s":"看到【图像题选项中问斜率、截距或突变点的物理意义】","c":"想到【图像突变点对应磁场边界或切割状态切换处；斜率反映该量对位移/时间的变化率，结合表达式判断线性或非线性】；警惕【突变不等于渐变，边界处I可能跳变】","src":"物一轮237.用图像方法分析电路参量-电磁感应与电路综合_笔记","note":"视频|00:47-10:23","orig":"（知识）通过位移-时间图像关联物理量（I、U、F、P随x变化），识别图像斜率与截距的物理意义（如电流突变点对应磁场边界）","link":""},{"id":"phy1489","t":"电磁感应综合·模型分类体系","s":"看到【电磁感应背景下导体棒或线框的动力学与能量综合题】","c":"想到【先归入模型类别（单杆无外力/有外力/含源、线框、双杆、含容），再按「运动过程$\\to$动力学$\\to$动量能量」流程分析，求解力学或运动学参量】；警惕【不同模型解法路径不同，先识别模型再套方法，别混用】","src":"物一轮238.【课前必看】本讲听课建议_笔记","note":"视频|00:40-02:19","orig":"（知识）单杆无外力/单杆有外力/单杆及线框/单杆含源/线框/动量守恒双杆/动量不守恒双杆/含容模型，每个模型分析运动过程确定方法、动量能量关系","link":""},{"id":"phy1490","t":"电磁感应综合·考情与难点分布","s":"看到【压轴选择题中的单杆/双杆/含容电磁感应题】","c":"想到【单杆重点是匀变速判断、能量转化（焦耳热）与稳定状态条件；双杆重点是双棒相对运动、电荷量与系统能量分配；含容重点是电容充电与导体棒运动的关联】；警惕【含容模型涉及电流瞬态分析，理解难度最大】","src":"物一轮238.【课前必看】本讲听课建议_笔记","note":"视频|02:19-04:16","orig":"（知识）单杆模型高频（选择题压轴为主，涉及匀变速判断、焦耳热、稳定状态条件）；双杆中频（动量与能量综合、系统能量分配）；含容模型考频上升（电容充电特性与导体棒匀加速运动关联、电流瞬态分析）","link":""},{"id":"phy1491","t":"电磁感应综合·学习方法论","s":"看到【备考电磁感应综合题，纠结要不要背结论】","c":"想到【优先掌握通用分析方法（动力学流程、动量视角、能量视角），结论由推导得出】；警惕【高考题型变化多，死记具体结论易失效】","src":"物一轮238.【课前必看】本讲听课建议_笔记","note":"视频|04:16","orig":"（知识）重点掌握分析方法而非死记结论，因高考题型变化较多","link":""},{"id":"phy1492","t":"电磁感应动力学·单杆无外力安培力表达式","s":"看到【水平导轨上导体棒以初速度v0滑行（无外力、无摩擦），写安培力表达式】","c":"想到【F安=B^{2}L^{2}v/R（由F=BIL、I=BLv/R联立）】；警惕【表达式成立有前提：I仅由动生电动势产生；模型条件改变（如增加电源）需重新推导】","src":"物一轮239.单杆无外力模型完整视频_笔记","note":"视频|01:35-05:03","orig":"（知识）F安=BLI=BL·(BLv/R)=B²L²v/R；推导前提：F=BIL成立、I仅由感应电动势产生、E=BLv为动生电动势","link":""},{"id":"phy1493","t":"电磁感应动力学·运动性质与v-t图像","s":"看到【判断无外力单杆的运动性质或选择v-t图像】","c":"想到【a∝v且反向，导体棒做加速度减小的减速运动直至静止；v-t曲线斜率绝对值逐渐减小、渐近于零】；警惕【这是变减速运动，不能用匀变速公式】","src":"物一轮239.单杆无外力模型完整视频_笔记","note":"视频|05:03-08:13","orig":"（知识）a=F安/m=B²L²v/(mR)，与速度成正比且方向相反，做加速度逐渐减小的减速运动；v-t曲线从v0出发、斜率绝对值渐减、最终趋于零","link":""},{"id":"phy1494","t":"电磁感应动力学·动量定理求电荷量与位移","s":"看到【无外力单杆求通过的电荷量或滑行位移，且不知道运动时间】","c":"想到【对全过程用动量定理，安培力取平均：-BLq=0-mv0得q=mv0/(BL)；用x=v̅$\\Delta$t转化得x=mv0R/(B^{2}L^{2})】；警惕【安培力是变力，必须用平均值/累积量（Ī$\\Delta$t=q、v̅$\\Delta$t=x）过渡】","src":"物一轮239.单杆无外力模型完整视频_笔记","note":"视频|08:13-13:44","orig":"（知识）-BĪLΔt=0-mv0，其中ĪΔt=q得q=mv0/(BL)；-B²L²v̅Δt/R=0-mv0，其中v̅Δt=x得x=mv0R/(B²L²)；优势是无需知道时间","link":""},{"id":"phy1495","t":"电磁感应动力学·电荷量与位移的联系","s":"看到【已知电荷量求位移，或已知位移求电荷量（无外力单杆）】","c":"想到【q=BLx/R直接互算】；警惕【x是沿磁场方向扫过的面积对应的长度，BLx即磁通量变化】","src":"物一轮239.单杆无外力模型完整视频_笔记","note":"视频|12:26-13:44","orig":"（知识）q=BLx/R，由ΔΦ=BLx结合q=ΔΦ/R推得","link":""},{"id":"phy1496","t":"电磁感应能量·安培力做功与能量转化链","s":"看到【求无外力单杆回路产生的总焦耳热】","c":"想到【安培力做功量度电能变化（W安=-$\\Delta$E电）；纯电阻电路能量守恒：初动能全部转化为焦耳热，Q=½mv0^{2}】；警惕【做负功是动能$\\to$电能，做正功是电能$\\to$动能，方向别弄反】","src":"物一轮239.单杆无外力模型完整视频_笔记","note":"视频|13:44-17:31","orig":"（知识）W安=-ΔE电；安培力做正功：电能→动能；做负功：动能→电能；完整链：动能→电能→内能，纯电阻电路Q=½mv0²","link":""},{"id":"phy1497","t":"电磁感应动力学·电磁阻拦（共速减速）应用","s":"看到【飞机（或滑块）勾住导体棒瞬间共速后在磁场中减速（电磁阻拦类）】","c":"想到【等效为单杆无外力模型：F安=B^{2}L^{2}v/R总，加速度随v减小；位移用动量定理求，无需时间；总热量=系统初动能，各电阻热量按阻值比例分配】；警惕【加速度减小的减速运动不能用匀变速公式；区分回路总热量与单个电阻热量的提问方式】","src":"物一轮239.单杆无外力模型完整视频_笔记","note":"视频|17:31-28:23","orig":"（例）飞机勾住ab棒瞬间共速，仅受安培力F安=B²L²v/2R；动量定理求位移x=2MRv0/(B²L²)；总热量Q=½Mv0²，电阻R与导体棒各产生¼Mv0²","link":""},{"id":"phy1498","t":"电磁感应动力学·圆弧导轨接水平导轨","s":"看到【导体棒从竖直圆弧导轨滑下进入带磁场的水平导轨】","c":"想到【圆弧段无电磁感应，机械能守恒求进入水平段速度（与磁场无关）；水平段用动量定理求位移，热量按电阻比例分配】；警惕【最低点压力用向心力方程N=mg+mv^{2}/r再由牛顿第三定律转化；回路总电阻勿漏导体棒自身电阻】","src":"物一轮239.单杆无外力模型完整视频_笔记","note":"视频|28:23","orig":"（例）圆弧段机械能守恒v=√2gh；最低点N=mg+2mgh/r（牛顿第三定律转压力）；水平段动量定理求位移；总热量Q=mgh，电阻R分得2/3mgh（电阻比1:2）","link":""},{"id":"phy1499","t":"电磁感应动力学·单杆有外力启动过程","s":"看到【导体棒由静止受恒力F启动切割磁场，分析运动过程】","c":"想到【流程：受力$\\to$加速度$\\to$运动性质$\\to$最终状态；初始v=0无安培力，a0=F/m；之后做加速度减小的加速运动】；警惕【初始时刻无安培力是解题突破口，误认为一开始就有安培力会错】","src":"物一轮240.单杆有外力模型_笔记","note":"视频|00:05-03:43","orig":"（知识）v=0时无感应电动势故无安培力，初始a0=F/m；运动后a=(F-F安)/m=F/m-B²L²v/(mR)，v↑→F安↑→a↓，做加速度减小的加速运动","link":""},{"id":"phy1500","t":"电磁感应动力学·最大速度（稳定状态）","s":"看到【求恒力下拉杆的最终（最大/匀速）速度】","c":"想到【稳定条件是合力为零：F=F安=B^{2}L^{2}vm/R，解得vm=FR/(B^{2}L^{2})；斜面上则F为重力沿斜面分量】；警惕【vm由平衡条件推导，换个外力形式需重新列式，别死套】","src":"物一轮240.单杆有外力模型_笔记","note":"视频|03:43-06:17","orig":"（知识）当F=F安时达到平衡，最大速度vm=FR/(B²L²)（不需死记，掌握推导原理）；v-t曲线斜率渐减，渐近线为v=vm","link":""},{"id":"phy1501","t":"电磁感应动力学·动量定理双形式","s":"看到【有外力单杆模型求电荷量、位移或时间】","c":"想到【动量定理：F$\\Delta$t-BLq=mv或F$\\Delta$t-B^{2}L^{2}x/R=mv，配合q=$\\Delta$Φ/R求解】；警惕【$\\Delta$t是必要已知量，变加速过程无法用匀变速公式求时间】","src":"物一轮240.单杆有外力模型_笔记","note":"视频|06:17-09:04","orig":"（知识）FΔt-BILΔt=mv（向右为正）；电荷量形式FΔt-BLq=mv（q=ĪΔt）；位移形式FΔt-B²L²x/R=mv（x=v̅Δt）","link":""},{"id":"phy1502","t":"电磁感应能量·功能分析与能量守恒","s":"看到【有外力单杆求焦耳热或能量分配】","c":"想到【动能定理W合=$\\Delta$Ek，其中克服安培力做功=焦耳热；能量守恒WF=$\\Delta$Ek+Q，热量按电阻比例分配】；警惕【F可能是重力/弹力等，对应能量形式要具体分析；不能用匀变速公式处理变加速段】","src":"物一轮240.单杆有外力模型_笔记","note":"视频|09:04-15:00","orig":"（知识）WF+W安=ΔEk，即Fx-Q=½mvm²；F做功量度其他形式能与动能的转化；安培力始终做负功：动能→电能→内能；守恒式WF=½mvm²+Q","link":""},{"id":"phy1503","t":"电磁感应动力学·斜面导轨综合例题","s":"看到【倾斜导轨上金属棒由静止释放，求初始加速度、匀速速度、焦耳热】","c":"想到【初始a0=gsin$\\theta$（v=0无安培力）；匀速条件mgsin$\\theta$=B^{2}L^{2}vm/(R+r)；总热量用能量守恒，位移x用动量定理求；串联热量按电阻比例分配】；警惕【区分总热量与局部热量，直接用总热量代局部会错】","src":"物一轮240.单杆有外力模型_笔记","note":"视频|15:00-25:43","orig":"（例）a0=gsinθ=5m/s²；匀速时mgsinθ=B²L²vm/(R+r)得vm=2m/s；动量定理求x=2.4m后能量守恒mgxsinθ=½mvm²+Q得Q=2J，棒发热0.5J","link":""},{"id":"phy1504","t":"电磁感应动力学·恒功率拉力模型","s":"看到【题目出现「拉力功率恒定」，求位移或最大速度】","c":"想到【F=P/v是变力，最大速度时P=(F安+其他恒力)vm；求功用WF=Pt直接算，配合动能定理求解】；警惕【F为变力时动量定理失效，改用能量法；重力做功的正负看高度变化】","src":"物一轮240.单杆有外力模型_笔记","note":"视频|25:43-39:40","orig":"（例）恒功率P下F=P/v随v增大而减小；最大速度时P=(F安+mgsinθ)vm；动能定理Pt-W安-mgxsinθ=ΔEk（W安=0.06J），解得x=0.1m","link":""},{"id":"phy1505","t":"电磁感应动力学·多过程与非均匀磁场","s":"看到【导体棒经历自由落体$\\to$电磁平衡$\\to$非均匀磁场中运动的多过程问题】","c":"想到【匀速段的平衡条件反求速度作为阶段衔接量；不同阶段用冲量（动量定理）连接速度变化；非均匀磁场中B^{2}随x变化时，联立牛顿第二定律与v^{2}=v0^{2}-2ax建立B^{2}(x)表达式】；警惕【动能差可用mah表示（速度平方差=2ah）简化热量计算；非均匀磁场导致匀减速是特殊条件，需动态验证】","src":"物一轮240.单杆有外力模型_笔记","note":"视频|39:40","orig":"（例）自由落体→电磁平衡（mg=B1²L²v1/R得v1=4m/s，v1²=2gh1）→CD段非均匀磁场中匀减速，Q=m(g+a)h3=18J；B2²=m(g+a)R/(L²v)，v²=v2²-2ax联立得B2²随x的表达式","link":""},{"id":"phy1506","t":"电磁感应·单杆含源模型","s":"看到【回路中既有恒定电源又有导体棒切割磁感线】","c":"想到【等效电动势按电流方向叠加：同向相加、反向相减，如E总=E−BLv】；警惕【先用右手定则判定感应电动势方向，再与电源电动势比较叠加关系】","src":"物一轮241.单杆含源模型_笔记","note":"视频|00:06-00:25","orig":"（知识）回路中含恒定电源（电动势E）和运动导体棒（感应电动势BLv）两个电动势源，初速为零，电阻R，忽略其他电阻与摩擦","link":""},{"id":"phy1507","t":"电磁感应·单杆含源模型","s":"看到【单杆含源模型分析运动全过程】","c":"想到【列牛顿第二定律：a=(BEL−B^{2}Lv)/(mR)，安培力随v增大而减小，做加速度减小的加速运动，最终电流为零时匀速】；警惕【最大速度条件是电流为零（E=BLvm），而非安培力与外力平衡，与无源模型不同】","src":"物一轮241.单杆含源模型_笔记","note":"视频|00:25-08:41","orig":"（例）F安=B(E−BLv)/R，a=BEL/(mR)−B²Lv/(mR)，随v增大a减小，E=BLvm时匀速，vm=E/(BL)","link":""},{"id":"phy1508","t":"电磁感应·单杆含源模型","s":"看到【含源单杆用动量定理求电荷量或末速度】","c":"想到【对棒列动量定理 F̄安$\\Delta$t=mvm，其中BLq=mvm可直接求电荷量q】；警惕【含源时q=BLx/R不再成立，该式推导前提是纯感应电路，含外源需重新推导】","src":"物一轮241.单杆含源模型_笔记","note":"视频|08:41-08:55","orig":"（知识）动量定理：BLq=mvm 或 (BEL/R)Δt−(B²Lv̄/R)Δt=mvm","link":""},{"id":"phy1509","t":"电磁感应·单杆含源模型","s":"看到【需用安培力冲量求含源单杆的位移】","c":"想到【区分Ī与v̄的不同表达式：求电荷量用BLq=mvm形式，求位移须展开为含E、R的形式并已知时间$\\Delta$t】；警惕【两种冲量形式不可混用，求位移还需补充已知条件】","src":"物一轮241.单杆含源模型_笔记","note":"视频|08:55-12:14","orig":"（知识）求电荷量用形式1（BLq=mvm），求位移需用形式2并已知Δt或电源参数E","link":""},{"id":"phy1510","t":"电磁感应·单杆含源模型","s":"看到【含源单杆的能量分配与效率】","c":"想到【电源输出的电能E电=½mvm^{2}+Q，一部分转化为动能、一部分耗散为焦耳热，安培力做正功量度电能向动能的转化】；警惕【电能不会全部转化为动能，效率按动能占总电能之比计算】","src":"物一轮241.单杆含源模型_笔记","note":"视频|12:14-13:36","orig":"（知识）E电=½mvm²+I²Rt，效率η=½mvm²/(EIt)","link":""},{"id":"phy1511","t":"电磁感应·单杆含源模型","s":"看到【闭合开关瞬间求导体棒（或连接体）加速度】","c":"想到【初速度为零时感应电动势为零，电流仅由外电源决定I=E/(R+r)，再用左手定则定安培力方向，连接体用整体法求a】；警惕【先判断安培力是否大于最大静摩擦（$\\mu$Mg）棒才会动】","src":"物一轮241.单杆含源模型_笔记","note":"视频|13:36-21:47","orig":"（例）闭合开关瞬间I=E/(R+r)，F安=BEL/(R+r)，整体法a=(BEL/(R+r)−μMg)/(M+m)","link":""},{"id":"phy1512","t":"电磁感应·单杆含源模型","s":"看到【恒压源下单杆在外力F作用下求最大速度】","c":"想到【最大速度由力学平衡F=B^{2}d^{2}vm/(R+r)决定，vm=F(R+r)/(B^{2}d^{2})仅与力有关、与时间无关】；警惕【此平衡条件对应电流不为零的稳态，与含源模型电流为零的条件不同】","src":"物一轮241.单杆含源模型_笔记","note":"视频|21:47","orig":"（例）恒压源：F=B²d²vm/(R+r)，vm=F(R+r)/(B²d²)，与时间无关","link":""},{"id":"phy1513","t":"电磁感应·单杆含源模型","s":"看到【回路接恒流源（电流恒为I0）】","c":"想到【电流不变则安培力恒定，棒做匀加速a=BI0d/m，电源电压需补偿感应电动势U−Bdv=I0r，U随时间线性增大】；警惕【恒流源始终有电流、无「电流为零的平衡态」，与恒压源本质不同】","src":"物一轮241.单杆含源模型_笔记","note":"视频|21:47","orig":"（例）恒流源I0恒定，a=BI0d/m匀加速，U(t)=B²d²I0t/m+I0r线性增大","link":""},{"id":"phy1514","t":"电磁感应·线框模型","s":"看到【线框从高处自由下落进入磁场】","c":"想到【进入磁场前先由动能定理求初速度v0=√(2gh)，h越大v0越大】；警惕【进入磁场后的运动性质取决于v0与mgR/(B^{2}L^{2})的大小关系，需先比较再讨论】","src":"物一轮242.线框模型_笔记","note":"视频|00:06-00:50","orig":"（例）线框从高h处自由下落，mgh=½mv0²，v0=√(2gh)","link":""},{"id":"phy1515","t":"电磁感应·线框模型","s":"看到【线框刚进入磁场做受力分析】","c":"想到【仅下边切割，安培力F=B^{2}L^{2}v0/R方向与运动方向相反（由楞次定律确定），合力以运动方向为正列式】；警惕【安培力方向与速度相反，不要与重力方向混淆】","src":"物一轮242.线框模型_笔记","note":"视频|01:39-02:53","orig":"（知识）进入磁场时受重力mg与安培力B²L²v0/R（方向向上），F合=mg−B²L²v0/R","link":""},{"id":"phy1516","t":"电磁感应·线框模型","s":"看到【讨论线框进入磁场后是加速、匀速还是减速】","c":"想到【以v0与mgR/(B^{2}L^{2})比较分三种情况；无论加速还是减速，速度变化都使安培力变化，最终都趋向加速度减小的变速运动】；警惕【非匀速阶段的加速度方向与大小变化趋势不能混谈，加速度绝对值都在减小】","src":"物一轮242.线框模型_笔记","note":"视频|02:53-05:21","orig":"（知识）v0<mgR/(B²L²)加速、v0=mgR/(B²L²)匀速、v0>mgR/(B²L²)减速；加速时v增→F安增→a减，减速时v减→F安减→a减","link":""},{"id":"phy1517","t":"电磁感应·线框模型","s":"看到【线框穿越磁场、只有一边切割磁感线】","c":"想到【本质等同单杆模型，动量定理、能量关系可类比迁移，用于求位移、电荷量】；警惕【线框完全进入磁场后磁通量不变、无感应电流，安培力消失】","src":"物一轮242.线框模型_笔记","note":"视频|05:21-06:29","orig":"（知识）线框仅下边切割，相当于单杆切割模型，动量定理、能量关系与单杆类似","link":""},{"id":"phy1518","t":"电磁感应·线框模型","s":"看到【题目说明线框由相同材料制成】","c":"想到【立即联想密度相同、电阻率相同两个隐含条件，代入m=$\\rho$V、R=$\\rho$电L/S可消去尺寸，证明不同大小线框加速度、落地速度、时间相同】；警惕【运动同步但焦耳热因质量不同而不同，不能默认热量也相同】","src":"物一轮242.线框模型_笔记","note":"视频|06:29-15:11","orig":"（例）相同材料两线框，Ⅱ横截面积为Ⅰ两倍，代入m=ρV、R=ρ电L/S化简得a相同，全程同步运动，落地速度、时间相同，热量不同（Q=mgh−½mv²因质量不同）","link":""},{"id":"phy1519","t":"电磁感应·线框模型","s":"看到【线框受斜向恒力运动后进入磁场】","c":"想到【先分解恒力，水平、竖直两方向独立分析（水平匀加速、竖直另算），进入磁场后竖直匀速时用Fy−mg=B^{2}L^{2}v/R求B或v】；警惕【两方向通过时间关联，利用运动等时性传递条件】","src":"物一轮242.线框模型_笔记","note":"视频|15:11","orig":"（例）恒力F=4√2N与水平成45°，分解得ax=20m/s²、ay=10m/s²，进入磁场后竖直匀速：Fy−mg−B²L²vy/R=0，解得B=0.2T","link":""},{"id":"phy1520","t":"电磁感应·线框模型","s":"看到【线框在磁场中匀速运动阶段求焦耳热】","c":"想到【安培力为恒力时直接用Q=F安·l计算，比写完整能量守恒式简便】；警惕【只有安培力大小恒定时才能这样算，变速阶段需用能量守恒】","src":"物一轮242.线框模型_笔记","note":"视频|15:11","orig":"（例）安培力恒定F安=2N时，Q=F安L=0.4J，避免用WF=mg(2L)+½mv²+Q的复杂计算","link":""},{"id":"phy1521","t":"电磁感应·动量守恒双杆模型","s":"看到【等宽导轨上双杆系统，A有初速v0、B静止】","c":"想到【两棒受等大反向安培力F=B^{2}L^{2}(v1−v2)/(2r)，与相对速度成正比；A减速、B加速且加速度都减小】；警惕【用左手定则分别判断两棒安培力方向，电流由电动势大的棒主导】","src":"物一轮243.动量守恒双杆模型_笔记","note":"视频|00:43-06:02","orig":"（例）A初速v0、B静止，F1=F2=B²L²(v1−v2)/(2r)，A做加速度减小的减速运动，B做加速度减小的加速运动","link":""},{"id":"phy1522","t":"电磁感应·动量守恒双杆模型","s":"看到【分析双杆系统的最终状态】","c":"想到【相对速度减小导致安培力与加速度都减小，v1=v2时回路电流为零、两棒以共同速度匀速运动】；警惕【共速后无电流、无安培力，但两棒仍以v共继续运动，不会停下】","src":"物一轮243.动量守恒双杆模型_笔记","note":"视频|06:02-07:31","orig":"（知识）随v1减小、v2增大，(v1−v2)减小，v1=v2时安培力为零，两棒以v共匀速运动","link":""},{"id":"phy1523","t":"电磁感应·动量守恒双杆模型","s":"看到【双杆系统求电荷量或相对位移】","c":"想到【对单棒列动量定理BLq=m$\\Delta$v，配合q=BL(x1−x2)/(2r)，可在电荷量与相对位移之间互求】；警惕【q与相对位移的关系式仅适用于纯电磁感应回路】","src":"物一轮243.动量守恒双杆模型_笔记","note":"视频|07:31-12:03","orig":"（例）对A：−BLq=m1v共−m1v0；q=BL(x1−x2)/(2r)，对A、B列式所得q相同","link":""},{"id":"phy1524","t":"电磁感应·动量守恒双杆模型","s":"看到【双杆系统求共同速度】","c":"想到【两安培力严格等大反向时系统动量守恒，m1v0=(m1+m2)v共直接求v共】；警惕【动量守恒的前提是两安培力等大反向，磁场或导轨不对称时（如宽度不同）不守恒，须验证】","src":"物一轮243.动量守恒双杆模型_笔记","note":"视频|12:03-15:12","orig":"（例）联立两棒动量定理，利用F1=F2消元得m1v0=(m1+m2)v共","link":""},{"id":"phy1525","t":"电磁感应·动量守恒双杆模型","s":"看到【双杆系统的能量转化与焦耳热计算】","c":"想到【能量流向：A动能$\\to$电能$\\to$B动能+焦耳热，守恒式½m1v0^{2}=½(m1+m2)v共^{2}+Q，系统动能损失即总焦耳热】；警惕【总热量按电阻比例分配，电阻相等时才均分】","src":"物一轮243.动量守恒双杆模型_笔记","note":"视频|15:12-18:09","orig":"（例）½m1v0²=½(m1+m2)v共²+Q热，A损失动能→电能→（B获得动能+回路发热）","link":""},{"id":"phy1526","t":"电磁感应·动量守恒双杆模型","s":"看到【双杆系统综合题求热量与电荷量】","c":"想到【先机械能守恒求进入速度，再动量守恒求v共，系统动能损失=总焦耳热并按电阻比分配，电荷量对单棒列动量定理BLq=m$\\Delta$v】；警惕【求某棒热量先算总量再按电阻比分配，不能直接把动能损失全给它】","src":"物一轮243.动量守恒双杆模型_笔记","note":"视频|18:09-25:29","orig":"（例）a从高L处滑下，mgL=½mv0²，v0=√(2gL)；动量守恒mv0=3mv共；总热Q=⅔mgL，b棒电阻相同分得⅓mgL；BLq=2mv共求q","link":""},{"id":"phy1527","t":"电磁感应·动量守恒双杆模型","s":"看到【两棒先后进入磁场的多阶段双杆问题】","c":"想到【分阶段处理：磁场外的单棒独立运动用机械能守恒，双棒共存后用动量守恒；最大加速度对应刚进入（速度最大）时刻】；警惕【共速后电流消失，但求最终距离需用BLq=m$\\Delta$x类关系追踪相对位移】","src":"物一轮243.动量守恒双杆模型_笔记","note":"视频|25:29","orig":"（例）多阶段：a下滑机械能守恒得v0=4m/s；b下滑加速至4m/s；b进入磁场后动量守恒v共=3m/s；最大加速度在a刚进入磁场时a=0.5m/s²；初始距16m，相对位移8m，最终距8m","link":""},{"id":"phy1528","t":"电磁感应·动量不守恒双杆模型","s":"看到【不等宽导轨（L1$\\neq$L2）上的双杆系统】","c":"想到【回路电流I=B(L1v1−L2v2)/(2r)，随v2增大电动势反向抵消，A减速、B加速且加速度都减小】；警惕【两棒安培力大小不相等，系统动量不守恒】","src":"物一轮244.动量不守恒双杆模型_笔记","note":"视频|00:40-06:06","orig":"（例）导轨间距L1≠L2，I=(B(L1v1−L2v2))/(2r)，A受向左安培力减速，B受向右安培力加速","link":""},{"id":"phy1529","t":"电磁感应·动量不守恒双杆模型","s":"看到【判断动量不守恒双杆的最终稳定状态】","c":"想到【稳定条件是L1v1=L2v2（电动势平衡），速度比v1/v2=L2/L1与导轨宽度成反比，并非共速】；警惕【误认为最终共速——v-t图像两曲线渐近但不相交】","src":"物一轮244.动量不守恒双杆模型_笔记","note":"视频|06:06-08:58","orig":"（例）稳定条件L1v1=L2v2时a1=a2=0，速度比v1/v2=L2/L1（非共速），v-t图两曲线渐近不相交","link":""},{"id":"phy1530","t":"电磁感应·动量不守恒双杆模型","s":"看到【动量不守恒双杆求末速度、电荷量】","c":"想到【分别对两棒列动量定理再联立，用稳定状态条件（速度比或共速）补充方程，电荷量用q=$\\Delta$Φ/R总】；警惕【两安培力冲量不相等，不能对系统用动量守恒】","src":"物一轮244.动量不守恒双杆模型_笔记","note":"视频|08:58-13:05","orig":"（例）对两棒分别列动量定理−BL1q=m1v1−m1v0等，联立q=ΔΦ/R总，结合L1x1−L2x2与稳定条件求解","link":""},{"id":"phy1531","t":"电磁感应·动量不守恒双杆模型","s":"看到【已知具体参数的不等宽双杆求末状态】","c":"想到【建立三个方程：两棒各自的动量定理+稳定速度比，联立解出v1、v2和q】；警惕【若用安培力冲量-位移形式列式会引入四个未知数（v1、v2、x1、x2），除非题目额外给定位移条件】","src":"物一轮244.动量不守恒双杆模型_笔记","note":"视频|13:05-17:52","orig":"（例）B=1T、L1=1m、L2=0.5m等参数，联立两棒动量定理+速度比v1/v2=L2/L1三方程解出v1、v2、q","link":""},{"id":"phy1532","t":"电磁感应·动量不守恒双杆模型","s":"看到【倾斜光滑导轨上的双棒系统】","c":"想到【重力分量mgsin$\\theta$使系统动量不守恒，对系统列动量定理含重力冲量项，位移用含$\\Delta$x的安培力冲量形式求解】；警惕【释放瞬间另一棒除重力分量外还受同向安培力，加速度要两项相加】","src":"物一轮244.动量不守恒双杆模型_笔记","note":"视频|17:52-32:12","orig":"（例）倾斜角θ光滑导轨双棒，单棒平衡B²L²v0/(2R)=mgsinθ；系统动量定理2mgsinθ·t0=2mv−mv0；对b棒列式解相对位移Δx","link":""},{"id":"phy1533","t":"电磁感应·动量不守恒双杆模型","s":"看到【交叉连接或宽度不同的两导轨回路】","c":"想到【先按实际电流路径判断电动势是叠加还是抵消，最大电流在初始时刻；安培力与宽度成正比，宽度大的棒先减速至零再可能反向】；警惕【棒会经历减速到零再反向加速的分阶段过程，热量按电阻比例分配】","src":"物一轮244.动量不守恒双杆模型_笔记","note":"视频|32:12","orig":"（例）交叉连接导轨宽L与2L，两棒电动势同向叠加E总=3BLv0；b棒安培力是a棒2倍先减速至零再反向加速，稳定时BLv1=2BLv2即v1=2v2","link":""},{"id":"phy1534","t":"电磁感应·动量不守恒双杆模型","s":"看到【场景陌生的双杆电磁感应综合题】","c":"想到【按通用流程：受力分析$\\to$运动过程分析$\\to$列动量/能量方程，特殊情形额外注意电动势比例关系与安培力差异】；警惕【不要套用守恒结论，先判断安培力是否等大反向】","src":"物一轮244.动量不守恒双杆模型_笔记","note":"视频|32:12","orig":"（知识）核心方法：无论场景如何变化，均按「受力分析→运动过程→动量/能量守恒」流程处理","link":""},{"id":"phy1535","t":"电磁感应·单杆无外力含容模型","s":"看到【导体棒有初速v0、回路中接电容器C】","c":"想到【用含容电路欧姆定律I=(BLv−U)/R，棒切割给电容充电，U从零持续上升，电流由BLv与U之差决定】；警惕【电流不是恒定的，随v减小、U增大而减小】","src":"物一轮245.单杆无外力含容模型_笔记","note":"视频|01:05-02:10","orig":"（例）电容器初始U=0，E0=BLv0=I0R，电流I=(BLv−U)/R，随充电U持续上升","link":""},{"id":"phy1536","t":"电磁感应·单杆无外力含容模型","s":"看到【含容单杆分析运动性质与最终状态】","c":"想到【a=(B^{2}L^{2}v−BLU)/(mR)，v减小、U增大使加速度减小，当BLv=U时电流为零，棒以vm匀速运动】；警惕【最终状态是匀速而非静止，因电容充满后无电流、无安培力】","src":"物一轮245.单杆无外力含容模型_笔记","note":"视频|02:10-04:32","orig":"（例）a=B²L²v/(mR)−BLU/(mR)，v减小而U增大，a绝对值减小，BLv=U时电流为零保持匀速vm","link":""},{"id":"phy1537","t":"电磁感应·单杆无外力含容模型","s":"看到【含容单杆求最大速度vm】","c":"想到【对棒列动量定理−BLq=mvm−mv0，用q=C·$\\Delta$U（电容电荷变化量）且$\\Delta$U=BLvm代入，解得vm=mv0/(m+B^{2}L^{2}C)】；警惕【q是流过棒的电荷量=电容电荷变化量，不是任意时刻的电容电荷】","src":"物一轮245.单杆无外力含容模型_笔记","note":"视频|04:32-10:04","orig":"（例）−BLq=mvm−mv0，联立q=ΔQ=C·BLvm，解得vm=mv0/(m+B²L²C)","link":""},{"id":"phy1538","t":"电磁感应·单杆无外力含容模型","s":"看到【含容回路的能量转化分析】","c":"想到【动能经安培力做功转化为电能，再分配为焦耳热与电场能½CU^{2}】；警惕【非纯电阻回路，电阻产热不等于全部电能，还有电容器储能】","src":"物一轮245.单杆无外力含容模型_笔记","note":"视频|10:04-11:51","orig":"（知识）W安=½mvm²−½mv0²，动能→电能，分配为电阻焦耳热+电容器电场能E=½CU²","link":""},{"id":"phy1539","t":"电磁感应·单杆无外力含容模型","s":"看到【电容器放电推动导体棒（电磁炮类）】","c":"想到【放电时棒加速产生反向电动势BLv使电流减小，u=BLv时达到最大速度vm=CBLu形式（电荷守恒+动量定理联立求解）】；警惕【流过棒的电荷量q=$\\Delta$Q=C(E−u)，不是电容总电荷CE】","src":"物一轮245.单杆无外力含容模型_笔记","note":"视频|11:51-20:46","orig":"（例）电磁炮：S接a充电至u=E、Q=CE；接b后棒加速，I=(u−BLv)/R减小，u=BLv时vm=CBLE/(m+CB²L²)","link":""},{"id":"phy1540","t":"电磁感应·单杆无外力含容模型","s":"看到【带电电容经电阻、导体棒放电问最终状态】","c":"想到【最大电流在v=0时刻Imax=Q/(RC)；用假设法判断终态——假设匀速会与u持续下降矛盾，故棒减速至静止】；警惕【速度最大时安培力为零而非最大；电流大者产热多，比较各电阻热量看电流大小】","src":"物一轮245.单杆无外力含容模型_笔记","note":"视频|20:46","orig":"（例）闭合开关瞬间v=0，Imax=Q/(RC)；假设匀速推出矛盾（R持续耗能u下降I不为零），棒最终减速至静止；R上焦耳热大于棒上热量","link":""},{"id":"phy1541","t":"交变电流·知识框架","s":"看到【交变电流章节的知识体系梳理】","c":"想到【两条主线：产生原理对应瞬时值与最大值，有效值与平均值另算一套方法】；警惕【四个值的定义、表达式与物理意义需分别掌握，不可混用】","src":"物一轮247.【课前必看】本讲听课建议_笔记","note":"视频|00:09-00:18","orig":"（知识）交流电主线：正余弦交流电的产生原理（重点理解瞬时值和最大值）→交变电流的有效值与平均值","link":""},{"id":"phy1542","t":"交变电流·四值概念","s":"看到【交流电的瞬时值、最大值、有效值、平均值四值问题】","c":"想到【按物理意义区分：瞬时值代入e=Emsin/cos$\\omega$t，最大值为峰值nBS$\\omega$，有效值按热效应等效，平均值用$\\Delta$Φ/$\\Delta$t求】；警惕【求热量、功率用有效值，求电荷量用平均值，不能用瞬时值或最大值代替】","src":"物一轮247.【课前必看】本讲听课建议_笔记","note":"视频|00:18-01:24","orig":"（知识）四个关键值：瞬时值（某时刻的电流值）、最大值（变化过程的峰值）、有效值（与直流等效的热效应值）、平均值（一段时间内的平均电流值）","link":""},{"id":"phy1543","t":"交变电流·考情与备考","s":"看到【交变电流的高考命题特点】","c":"想到【定位为必得分的选择题，复习重点放在与变压器结合的综合命题上】；警惕【不能因难度低而忽视，两讲内容通常对应一道选择题】","src":"物一轮247.【课前必看】本讲听课建议_笔记","note":"视频|01:24-02:40","orig":"（知识）交变电流属非主干知识，以选择题为主（通常在前4-5题），难度中等偏下，多与变压器结合考查，单独考查较少","link":""},{"id":"phy1544","t":"交变电流·交流电的判断","s":"看到【给电流图像判断是否为交变电流】","c":"想到【核心标准是方向是否周期性变化，大小变化不是必要条件；方向不变的脉动电流是直流电】；警惕【恒定电流是直流电的特例，不要把「大小不变」当作交流电的判断依据】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|00:28-04:46","orig":"（例）图a、b、c、d方向均周期性变化为交变电流；大小变化但方向不变的图为脉动直流电；恒定电流⊂直流电，交流与直流互斥","link":""},{"id":"phy1545","t":"交变电流·交流电的产生","s":"看到【线框在匀强磁场中匀速旋转切割磁感线】","c":"想到【先判断有效切割边：导体运动方向与磁感线垂直才切割（类比「刀割韭菜」），平行磁场平面旋转的边不切割】；警惕【电动势只由垂直磁场的分速度决定，需做速度分解】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|04:46-10:39","orig":"（例）线框AB、CD边垂直磁场运动为有效切割边，AD、BC边平行磁场平面旋转不切割；转过θ时只有垂直分量切割，电流方向保持不变","link":""},{"id":"phy1546","t":"交变电流·交流电的产生","s":"看到【定量推导旋转线框的电动势表达式】","c":"想到【两有效边电动势相加得$\\varepsilon$=BS$\\omega$cos$\\omega$t，只取决于线框面积S、磁场B和角速度$\\omega$，与转轴位置无关】；警惕【先设零时刻和转轴，再对各边分别写B·l·v$\\perp$后叠加】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|17:55-23:50","orig":"（例）AB、CD两边电动势叠加：ε=B l1ωr1cosωt+B l1ωr2cosωt=BSωcosωt，S为线框面积，与转轴位置无关","link":""},{"id":"phy1547","t":"交变电流·瞬时值表达式","s":"看到【选正弦还是余弦表达式、写瞬时值表达式】","c":"想到【由零时刻状态定函数形式：磁场与线框平行时取cos，垂直（中性面）时取sin；n匝线框表达式前乘n】；警惕【表达式与转轴位置无关，但与零时刻的选取有关】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|23:50-27:45","orig":"（例）以磁场与线框平行时刻为零时刻取cosωt（零时刻有切割，电动势不为零）；以垂直时刻为零时刻取sinωt（零时刻电动势为零）；多匝乘n：e=nBSωsinωt","link":""},{"id":"phy1548","t":"交变电流·最大值","s":"看到【求交流电电动势的最大值】","c":"想到【直接用Em=nBS$\\omega$，最大值即瞬时值表达式的系数，与角频率成正比】；警惕【$\\omega$增大时Em增大且周期减小，两者同时变化】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|27:45-29:27","orig":"（例）Em=nBSω，最大值与ω成正比，转速越快最大值越大；中性面处电动势瞬时值为零","link":""},{"id":"phy1549","t":"交变电流·中性面与垂直中性面","s":"看到【分析中性面或垂直中性面位置的各量特征】","c":"想到【中性面：磁通量最大、电动势和电流为零、电流方向改变；垂直中性面：磁通量为零、电动势最大，二者物理量反相】；警惕【中性面处切割速度为零$\\neq$运动速度为零，是垂直分速度v$\\perp$=0】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|29:27-33:23","orig":"（例）中性面：Φ=BS最大、e=0、I=0、电流方向在此改变（每周期两次）；垂直中性面：Φ=0、e=Emax；v⊥从0→vmax，ε正弦变化、Φ余弦变化","link":""},{"id":"phy1550","t":"交变电流·变化率法求电动势","s":"看到【用磁通量变化率求电动势（尤其非矩形线框）】","c":"想到【先写$\\varphi$=BSsin/cos$\\omega$t再对时间求导，e=n·dΦ/dt，比切割法（需积分）简便】；警惕【Φ最大时导数为零、e=0；Φ=0时斜率最大、e最大，二者反相】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|33:23-38:33","orig":"（例）E=NΔφ/Δt=Nφ′；以平行时刻为零时刻φ=BSsinωt→E=NBSωcosωt；以垂直时刻为零时刻φ=BScosωt→E=−NBSωsinωt","link":""},{"id":"phy1551","t":"交变电流·变化率法求电动势","s":"看到【圆形（非矩形）线框在磁场中转动求电动势表达式】","c":"想到【面积用S=$\\pi$R^{2}代入$\\varphi$，再求导得e=B$\\pi$R^{2}$\\omega$sin$\\omega$t形式的正弦式】；警惕【求导中的负号只表示方向，计算大小时可忽略】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|38:33-42:19","orig":"（例）单匝圆形线框半径R：φ=BπR²cosωt，求导得E=BπR²ωsinωt（负号表示方向，算大小时可忽略）","link":""},{"id":"phy1552","t":"交变电流·辐向磁场","s":"看到【辐向磁场（磁感线呈辐射状过圆心）中导体棒切割】","c":"想到【任意位置速度与磁场垂直，电动势大小恒为Blv但方向周期变化，产生方波交流电】；警惕【匀强磁场$\\to$正弦交流电、辐向磁场$\\to$方波交流电，波形完全不同】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|42:19-44:37","orig":"（例）辐向磁场中导棒任意位置速度均与磁场垂直，E=Blv大小恒定、方向周期性变化，形成方波交流电","link":""},{"id":"phy1553","t":"交变电流·交流电的产生","s":"看到【判断装置能否产生正弦交流电、磁极转动画景】","c":"想到【产生正弦交流电需同时满足匀强磁场（等间距平行磁感线）+匀速转动；磁极转动等效于线圈反向转动，用相对运动分析】；警惕【题目未说明匀速转动时不能默认正弦；磁通量为零时电动势最大】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|44:37-49:55","orig":"（例）磁感线为等间距平行线才可视为匀强磁场；未说明匀速转动不能断定产生正弦交流电；磁极转动等效于线圈反向运动，Φ=0时电动势最大","link":""},{"id":"phy1554","t":"交变电流·电动势图像","s":"看到【由t=0状态选电动势图像或表达式】","c":"想到【t=0时Φ=0则e最大（cos型）、Φ最大则e=0（sin型），先核对幅值nBS$\\omega$再核对初相】；警惕【$\\omega$增大导致Emax增大，图像幅值与周期同时检查】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|49:55-51:32","orig":"（例）t=0时φ=0，电动势应取最大值，选e=NBSωcosωt，排除正弦选项；Emax=NBSω代入BS=0.2Wb、ω=5πrad/s算得20πV","link":""},{"id":"phy1555","t":"交变电流·电动势图像","s":"看到【发电机问题中结合图像找电流方向改变点】","c":"想到【电流方向改变总发生在中性面（Φ最大、I=0处），一个周期改变两次；感应电动势是磁通量的变化率E=N·d$\\varphi$/dt】；警惕【不要把磁通量最大误认为电动势最大】","src":"物一轮248.正余弦交流电的产生原理_笔记","note":"视频|51:32","orig":"（例）中性面处磁通量最大、电流为零，电流方向改变发生在中性面；E=Ndφ/dt，磁通量变化率最大值对应Emax","link":""},{"id":"phy1556","t":"交变电流·有效值的定义","s":"看到【交变电流有效值的概念辨析或定义类判断】","c":"想到【热效应等效：相同电阻、相同时间（完整周期）产生相同热量即等效】；警惕【有效值必须对应完整周期，不能取任意一段时间】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|00:32-01:36","orig":"（知识）让交变电流与恒定电流分别通过相同电阻，一个周期内产生相同热量，则该恒定电流的I、U为有效值；必须满足「三同」——相同时间（完整周期）、相同电阻、相同热量。","link":""},{"id":"phy1557","t":"交变电流·非正弦（方波）有效值计算","s":"看到【题目给出分段恒定或非正弦的周期性电流（方波），求有效值】","c":"想到【三步法：分段算各段热量$\\to$求总热量Q总$\\to$由I^{2}RT=Q总联立求解】；警惕【T要取完整周期（含所有分段），不能只取其中一段】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|01:36-05:35","orig":"（例）方波周期分段：0-1s电流4√2A、1-2s电流3√2A，分段算热量Q₁=32R、Q₂=18R，Q总=50R，由I²RT=Q总（T=2s）解得I=5A。","link":""},{"id":"phy1558","t":"交变电流·正弦交流电有效值","s":"看到【正弦交流电，要求有效值或由峰值换算有效值】","c":"想到【正弦有效值=峰值/√2直接换算】；警惕【半波整流不是简单除以2再除√2的问题，需用割补法按热量等效重新计算】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|05:35-06:32","orig":"（知识）正弦交流电I=Im/√2、U=Um/√2；半波整流（仅保留正弦波上半部分）用割补法：先补齐完整正弦波算总热量，取一半再等效，半波有效值=最大值/2而非除以√2。","link":""},{"id":"phy1559","t":"交变电流·非完整正弦波周期判定","s":"看到【波形图中有零电流段或波形不完整的交流电，求有效值】","c":"想到【先确定真实完整周期（零值段计入周期），再利用波形对称性算热量】；警惕【不能直接套用完整正弦波公式，周期判定要含零电流段】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|06:32-12:40","orig":"（例）正余弦电流有效值计算：看似周期1s实际为2s（需包含零电流段），利用上下半周期热量对称，答案2.5A。","link":""},{"id":"phy1560","t":"交变电流·有效值的四大应用场景","s":"看到【交流电路中判断电表读数、铭牌参数、灯泡额定电压或电容器耐压值的取值】","c":"想到【电表、铭牌、热量、默认给定值都用有效值；灯泡额定电压取有效值】；警惕【电容器耐压（击穿电压）按最大值/瞬时值考虑，不能用有效值】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|12:40-17:09","orig":"（知识）仪表读数、电器铭牌（如220V，最大值约311V）、焦耳定律热量计算、题目未说明时默认给定值均为有效值；电容器击穿电压指最大值/瞬时值。","link":""},{"id":"phy1561","t":"交变电流·平均值与电荷量计算","s":"看到【电磁感应中求通过导体横截面的电荷量q】","c":"想到【用q=n$\\Delta$Φ/R总（磁通量变化法），优先于I平均$\\times$$\\Delta$t】；警惕【电量用平均值、热量用有效值，二者不可混用；不同时间间隔的平均值不同，某段平均电流可为0】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|17:09-19:46","orig":"（知识）平均值用于计算电量，I平均=q/t=nΔΦ/(R总·Δt)，故q=nΔΦ/R总；有效值用于计算热量。平均值可在任意时间间隔内计算，与时间区间强相关。","link":""},{"id":"phy1562","t":"交变电流·平均值分段计算","s":"看到【求某段时间内转动线圈的平均感应电流或电荷量】","c":"想到【只看该时间段内磁通量变化量$\\Delta$Φ的大小（含方向变化），代入q=n$\\Delta$Φ/R总】；警惕【$\\Delta$Φ要按末态减初态的代数量取绝对值，转过半圈$\\Delta$Φ可能是2BS而非0】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|19:46-24:27","orig":"（例）转动线圈：0~T/4磁通量0→BS，I=4BS/((R+r)T)；0~T/2磁通量0→0，I=0；T/4~3T/4磁通量BS→-BS（注意方向变化），I=4BS/((R+r)T)。","link":""},{"id":"phy1563","t":"交变电流·复合波热量计算","s":"看到【复合波形（三角波、方波、正弦波拼接）求产生的热量之比】","c":"想到【热量必须用有效值，复合波分段计算再加总；三角脉冲有效值按题目给的峰值/有效值关系换算】；警惕【各段只算自己持续时间内产生的热量，不要按整周期重复计入】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|24:27-27:45","orig":"（例）三角形脉冲峰值是有效值的3倍、方波段与正弦波对比：分段用各自有效值算Q，正弦段U有=U₀/√2，三角段U有=U₀/√3，求Q₁:Q₂=4:3。","link":""},{"id":"phy1564","t":"交变电流·电动势图像综合判断","s":"看到【给交流电e-t（或i-t）图像，综合判断频率、方向变化次数、热量与电荷量】","c":"想到【图像读峰值与周期$\\to$有效值=峰值/√2、f=1/T、每秒方向改变2f次；热量用有效值、电荷量用磁通量变化】；警惕【电动势最大时刻对应磁通量为0（垂直中性面），不要混淆】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|27:45-36:26","orig":"（例）单匝线圈e-t图像：T=0.04s，Em=100V，E=50√2V；f=25Hz，每周期方向改变2次→每秒50次；热量用I=50√2/25=2√2A算Q；电荷量q=ΔΦ/(R+r)，BS=Em/ω，旋转60°时ΔΦ=BS/2。","link":""},{"id":"phy1565","t":"交变电流·线圈转动的最大值与转轴","s":"看到【线圈绕垂直于磁场的轴匀速转动，求电动势最大值或有效值】","c":"想到【Emax=NBS$\\omega$（S为线圈面积），正弦式有效值=Emax/√2；转轴位置（只要垂直磁场）不影响最大值】；警惕【正方形面积是L^{2}，别漏乘匝数N或用错面积】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|36:26-38:00","orig":"（例）N匝边长L正方形线圈在磁场B中绕垂直磁场轴以ω匀速转动，Emax=NBSω=NBL²ω，有效值=√2/2·NBL²ω，转轴位置不影响最大值。","link":""},{"id":"phy1566","t":"交变电流·图像与瞬时值表达式","s":"看到【由u-t图像写交流电瞬时值表达式或求电功】","c":"想到【三要素：振幅（峰值）、角频率$\\omega$=2$\\pi$/T、初相位，u=Umax·sin($\\omega$t+$\\varphi$)；算电功/电热用有效值】；警惕【频率f=1/T与$\\omega$的区别，别把$\\omega$当频率代入】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|38:00-40:31","orig":"（例）u-t图像：峰值10√2V，T=0.02s，f=50Hz，ω=2π/T=100πrad/s，u=10√2sin(100πt)V；电流峰值Imax=Umax/R，W=I²Rt用有效值。","link":""},{"id":"phy1567","t":"交变电流·转动线圈中电压表读数与电荷量","s":"看到【线圈在磁场中转动，问电压表读数或通过电路的电荷量】","c":"想到【交流电压表读数恒为有效值（不随转动变化），按内外电阻分压；电荷量用q=n$\\Delta$Φ/R总与转动过程无关】；警惕【电压表读数不是瞬时值、也不是0；别把转动角度算错磁通量变化】","src":"物一轮249.交变电流的有效值与平均值_笔记","note":"视频|40:31","orig":"（例）线圈匀速转动：电压表读数为外电阻分压的有效值，恒定不随转角变化，UR=R/(R+r)×E有效；电荷量q=nΔΦ/R总，图示位置磁通量为0，转90°后为BL²，串联电路内外电阻电荷量相同。","link":""},{"id":"phy1568","t":"交变电流·变压器基本规律（考情与方法）","s":"看到【变压器选择题，判断电压、电流及动态变化】","c":"想到【按「电压比=匝数比、电流比=匝数反比」的框架分析，变压器与电路综合是主导题型】；警惕【注意理想变压器与非理想变压器的区别】","src":"物一轮250.【课前必看】本讲听课建议_笔记","note":"视频|01:04-01:52","orig":"（知识）变压器为非主干知识，以选择题为主、难度中等偏下属必得分题；核心是原副线圈电压、电流与匝数关系，重点方向为变压器与电路综合、判断电压电流变化。","link":""},{"id":"phy1569","t":"交变电流·远距离输电","s":"看到【远距离输电问题（升压—输电线—降压模型）】","c":"想到【套用通用解题框架：围绕回路和变压器逐级推算，损耗用P损=I^{2}R】；警惕【根据本省考情决定学习深度，非考查省份可降低比重】","src":"物一轮250.【课前必看】本讲听课建议_笔记","note":"视频|01:52-02:39","orig":"（知识）远距离输电考频较低、部分省份考查，掌握通用解题方法即可；核心是高压输电原理及损耗计算，P损=I²R与电压提升的关系。","link":""},{"id":"phy1570","t":"交变电流·备考策略","s":"看到【规划交变电流模块复习优先级】","c":"想到【所有考生必须掌握变压器，远距离输电按省份考纲调整优先级】；警惕【变压器题常出现在高考前4-5题位置，属于必得分题目不可失分】","src":"物一轮250.【课前必看】本讲听课建议_笔记","note":"视频|02:39","orig":"（知识）变压器高频考查（重庆、浙江、海南、北京、全国甲卷等近三年连续考查）；远距离输电仅个别省份考查（湖南、天津、山东、福建等，约1-2省/年）。","link":""},{"id":"phy1571","t":"变压器·工作原理","s":"看到【判断变压器能否工作、能量如何传递或能否接直流电】","c":"想到【变压器靠电磁感应（变化的磁场）传能，只能变交流不能变直流；电能通过磁场而非导线直接传导】；警惕【铁芯是导磁不是导电，线圈与铁芯间绝缘】","src":"物一轮251.变压器的基本规律_笔记","note":"视频|01:34-05:57","orig":"（知识）变压器由铁芯和原/副线圈组成，原线圈通交流电产生变化磁场（自感），铁芯导磁，副线圈磁通量变化产生感应电动势（互感）；变交不变直，对直流电无效；线圈与铁芯绝缘。","link":""},{"id":"phy1572","t":"变压器·理想变压器三大近似","s":"看到【理想变压器概念题，考查其理想化条件或能量传递】","c":"想到【三大近似（无漏磁、无线圈电阻、无铁芯涡流）推出P_{1}=P_{2}】；警惕【涡流是磁场变化在铁芯中感生的电流，与线圈通电电流不同】","src":"物一轮251.变压器的基本规律_笔记","note":"视频|06:03-09:58","orig":"（知识）①无漏磁：磁感线全束缚在铁芯内，ΔΦ₁=ΔΦ₂；②线圈电阻为零：U₁=E₁、U₂=E₂；③铁芯电阻为零：无涡流发热。结果：输入功率100%转化为输出功率。","link":""},{"id":"phy1573","t":"变压器·电压与匝数关系","s":"看到【求变压器副线圈电压，含多个副线圈情形】","c":"想到【电压与匝数成正比，多副线圈各自独立满足匝数比】；警惕【公式中的U_{1}是原线圈两端实际电压，不是电源电压】","src":"物一轮251.变压器的基本规律_笔记","note":"视频|09:58-16:21","orig":"（知识）U₁/U₂=n₁/n₂，由U=nΔΦ/Δt比值消去相同磁通量变化率得证；多副线圈时U₁:U₂:U₃=n₁:n₂:n₃仍成立。","link":""},{"id":"phy1574","t":"变压器·原线圈串电阻的电压关系","s":"看到【原线圈电路中串联电阻再接变压器】","c":"想到【先扣除电阻分压得U_{1}=U-I_{1}R，再代入匝数比公式】；警惕【不能把电源电压直接当原线圈电压代入匝数比公式】","src":"物一轮251.变压器的基本规律_笔记","note":"视频|16:21-20:10","orig":"（例）原线圈回路有串联电阻时：U₁=U-I₁R，匝数比公式必须用实际线圈电压（U₁-I₁R)/U₂=n₁/n₂。","link":""},{"id":"phy1575","t":"变压器·功率守恒与电流关系","s":"看到【求变压器电流比，或题目含多个副线圈】","c":"想到【单副线圈用电流反比I_{1}/I_{2}=n_{2}/n_{1}；多副线圈一律回到功率守恒P_{1}=∑P副】；警惕【电流反比关系不可盲目推广到多线圈情况】","src":"物一轮251.变压器的基本规律_笔记","note":"视频|20:10-25:28","orig":"（知识）理想变压器P₁=P₂即U₁I₁=U₂I₂，故I₁/I₂=n₂/n₁；该电流反比关系仅适用单副线圈，多副线圈时U₁I₁=U₂I₂+U₃I₃，需按∑P出=P入处理。","link":""},{"id":"phy1576","t":"变压器·变压不变频与电流双解法","s":"看到【给输入电压表达式和功率，求副线圈电流或频率】","c":"想到【变压器不变频，副线圈频率=原线圈频率；电流可走「功率守恒+匝数反比」或「匝数比得电压+P=UI」两条路】；警惕【代入功率计算必须用有效值电压220V，不能用峰值】","src":"物一轮251.变压器的基本规律_笔记","note":"视频|25:28-30:23","orig":"（例）输入u=220√2sin(100πt)V，P₂=8.8kW：由ω=100π得T=1/50s、f=50Hz；电流法一（功率法）I₁=P/U₁=40A，再按匝数反比得I₂=20A；法二（电压法）U₂=440V，I₂=P/U₂=20A。","link":""},{"id":"phy1577","t":"变压器·自耦变压器动态分析","s":"看到【自耦变压器滑动触头移动，判断输出电压变化】","c":"想到【仍用U_{1}/U_{2}=n_{1}/n_{2}，先弄清触头移动改变的是n_{1}还是n_{2}，再由匝数变化定U_{2}】；警惕【原副线圈匝数取值段要与接线端对应，共用绕组部分别数错】","src":"物一轮251.变压器的基本规律_笔记","note":"视频|30:23-33:54","orig":"（例）自耦变压器原副线圈共用部分绕组：AB间为原线圈（总匝数n₁），CD间为副线圈（部分匝数n₂）；触头顺时针旋转→n₂减小→U₂=U₁n₂/n₁减小。","link":""},{"id":"phy1578","t":"变压器·电压互感器与电流互感器","s":"看到【两个互感器分别接电压表、电流表，求高压侧的电压或电流】","c":"想到【测电压的互感器用匝数正比关系，测电流的互感器用匝数反比关系】；警惕【电压表用正比、电流表用反比，两组关系不能交叉套用】","src":"物一轮251.变压器的基本规律_笔记","note":"视频|33:54","orig":"（例）甲图测电压：U₁/U=k₁→高压线电压U₁=k₁U（匝数正比）；乙图测电流：I₁/I=1/k₂→高压线电流I₁=I/k₂（匝数反比）。","link":""},{"id":"phy1579","t":"变压器电路·原线圈无负载的解题三步法","s":"看到【原线圈直接接电源（中间无分压元件）的变压器电路】","c":"想到【按「电压比$\\to$副线圈欧姆定律$\\to$电流反推」链条求解】；警惕【输入电压=原线圈电压成立的前提是原线圈回路无负载分压】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|00:17-02:36","orig":"（知识）原线圈无负载时输入电压全部加在原线圈上（u=u₁）：①电压传递U₂=U₁n₂/n₁；②副线圈回路用闭合电路欧姆定律求I₂；③由I₁/I₂=n₂/n₁反推I₁。","link":""},{"id":"phy1580","t":"变压器电路·无负载基本计算","s":"看到【给输入电压表达式和匝数比、负载电阻，求电表读数】","c":"想到【电表读数均为有效值，功率P=U_{1}I_{1}用有效值计算；变压器不改变频率】；警惕【电流表在原线圈读的是I_{1}，不是I_{2}】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|02:36-05:46","orig":"（例）u=220√2sin(100πt)V，匝数比2:1，R=55Ω：U₁=220V、U₂=110V、I₂=2A、I₁=1A；电流表读I₁，电压表读有效值110V，T=0.02s。","link":""},{"id":"phy1581","t":"变压器电路·无负载动态分析","s":"看到【变压器电路中滑动变阻器或匝数调节触头移动，判断电流电压变化】","c":"想到【动态分析按「电压比$\\to$电流比$\\to$功率关系」链条式推导：匝数定电压，负载定电流】；警惕【触头与滑片可能同时改变两个量，注意双重效应叠加】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|05:46-11:19","orig":"（例）副线圈接R₀与(R₁+R)并联：触头T不动→匝数比不变→U₂不变；滑片移动改变R₁支路电流；T移动改变U₂与R可双重增大/减小。","link":""},{"id":"phy1582","t":"变压器电路·灯泡正常发光问题","s":"看到【用电器（灯泡）正常发光，求匝数比或原线圈输入功率】","c":"想到【铭牌参数均为有效值：U_{2}取额定电压、I_{2}=P额/U额，输入功率=输出功率】；警惕【输入电压给峰值要先除√2化为有效值再算匝数比】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|11:19-14:16","orig":"（例）输入最大值24√2V，灯泡「6V 3W」正常发光：U₁=24V（有效值）、U₂=6V→匝数比4:1；I₂=P/U=0.5A；P₁=P₂=3W。","link":""},{"id":"phy1583","t":"变压器电路·匝数与电阻谁定什么","s":"看到【两个可调量（调匝数的触头+调电阻的滑片）独立变化判断I_{1}变化】","c":"想到【匝数变化决定U_{2}（电压），负载电阻变化决定I_{2}（电流），再由I_{1}/I_{2}=n_{2}/n_{1}传到原线圈】；警惕【U_{2}不变$\\neq$I_{2}不变，负载电阻变化仍会改变电流】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|14:16-17:39","orig":"（例）原线圈仅接电流表（无负载）：Q不动→U₂不变，P上滑→R增大→I₂减小→I₁减小；P不动→R不变，Q上滑→n₂增大→U₂增大→I₂、I₁增大。口诀「匝数调压定电压，电阻调流定电流」。","link":""},{"id":"phy1584","t":"变压器电路·有负载之列方程法","s":"看到【原线圈电路串有电阻（有分压）的变压器，求匝数比或各量】","c":"想到【构建四方程组联立（两侧欧姆定律+电压比+电流比），系统性强】；警惕【输入电压$\\neq$U_{1}，必须写U=I_{1}R_{1}+U_{1}的回路方程】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|17:39-19:25","orig":"（知识）原线圈有负载时输入电压≠原线圈电压：需列四个方程——原线圈回路欧姆定律、副线圈回路欧姆定律、U₁/U₂=n₁/n₂、I₁/I₂=n₂/n₁，联立求解全部未知量。","link":""},{"id":"phy1585","t":"变压器电路·两种状态联立求匝数比","s":"看到【电路开关切换导致副线圈负载变化，前后两个状态求匝数比】","c":"想到【对每个状态分别列回路方程+变压器关系，用不变的输入电压联立两状态】；警惕【两种状态下U_{2}、I_{2}都变了，不能混用一组变压器关系式】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|19:25-26:50","orig":"（例）开关S断开时副线圈R₂+R₃串联（总阻5Ω，电流I）；S闭合时仅R₂（总阻1Ω，电流4I）。两状态各列四方程，由3I+5k²I=12I+4k²I解得k=3。","link":""},{"id":"phy1586","t":"变压器电路·等效电阻法","s":"看到【有负载变压器电路求定量结果或复杂动态分析】","c":"想到【把副线圈电阻乘k^{2}折算到原线圈侧，变成纯电阻电路直接分析，计算简便】；警惕【k是匝数比n_{1}/n_{2}，等效时平方关系不能丢；此法仅限理想变压器】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|26:50-30:51","orig":"（知识）将变压器及副线圈整体等效为原线圈侧电阻：R等效=U₁/I₁=k²R副（k=n₁/n₂），推导由U₁=kU₂、I₁=I₂/k代入。仅适用理想变压器。","link":""},{"id":"phy1587","t":"变压器电路·等效电阻法解开关切换题","s":"看到【开关切换改变副线圈负载，比较两种解法求匝数比】","c":"想到【等效电阻法把两状态各写成一条欧姆定律式子，比四方程组更快；列方程组法思路直接但计算复杂，按计算能力选择】；警惕【等效电阻随副线圈总电阻变化，别忘了并联/短路改变R副】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|30:51-34:00","orig":"（例）S断开时等效电阻5k²，U=I(3+5k²)；S闭合时R₃被短路，U=4I(3+k²)；两式联立解出k。等效电阻法思路需理解等效关系但计算简便。","link":""},{"id":"phy1588","t":"变压器电路·等效电阻法动态分析","s":"看到【有负载变压器中滑动变阻器移动，判断U_{2}、I_{2}变化】","c":"想到【R副变化$\\to$R等效同向变化$\\to$原线圈电流变化$\\to$经匝数比传导回副边】；警惕【U_{2}不再恒定：有负载时原线圈分压随I_{1}变，U_{2}会跟着变】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|34:00-40:53","orig":"（例）滑片P下移→R减小→副线圈总电阻减小→R等效=(n₃/n₄)²R副减小→U₂减小、I₂增大。等效电阻法把副边折到原边直接看电流电压变化，更直观。","link":""},{"id":"phy1589","t":"变压器电路·电流图像与分压计算","s":"看到【给副线圈电流i-t图像，求原线圈侧电阻分压或电表读数】","c":"想到【先从图像取峰值化有效值，逐级算U_{2}$\\to$U_{1}，再用总电压减去U_{1}得分压】；警惕【图像给的通常是峰值，要先换算有效值；频率用f=1/T】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|40:53-47:03","orig":"（例）从R₂电流图像得有效值I₂=1A→U₂=10V→匝数比10:1得U₁=100V→由总电压220V得R₁分压120V（电压表读数120V）；图像周期0.02s→f=50Hz。","link":""},{"id":"phy1590","t":"变压器电路·两级变压器串联","s":"看到【两个变压器级联的电路，判断各表读数或功率变化】","c":"想到【分层处理：先分析无负载变压器（输出电压固定），再把后级用等效电阻折算进前级分析】；警惕【电压表测的是恒定的U_{2}，负载变化只影响电流不影响该读数】","src":"物一轮252.变压器与电路综合_笔记","note":"视频|47:03-52:01","orig":"（例）两级理想变压器串联：左侧原线圈直接接电源→U₂恒定；右侧等效电阻R等效=(n₃/n₄)²R副，开关闭合→R副减小→R等效减小→I₂增大→I₁、I₃随之增大；电压表测U₂不变。","link":""},{"id":"phy1591","t":"远距离输电·高压输电原理与流程","s":"看到【远距离输电示意图，问为什么要高压输电】","c":"想到【高压输电是为了减小输电电流、降低P损=I^{2}R的热损耗】；警惕【升压不是目的本身，减小损耗才是】","src":"物一轮253.远距离输电_笔记","note":"视频|00:15-02:06","orig":"（知识）流程：发电站→升压变压器→远距离输电→降压变压器→用户；采用高压输电的核心目的是减小输电过程中的热损耗。","link":""},{"id":"phy1592","t":"远距离输电·减小电阻途径的可行性分析","s":"看到【问为什么不用加粗导线或换材料来降低输电损耗】","c":"想到【从R=$\\rho$L/S逐项分析可行性：距离固定、成本受限，实际靠高压输电减小电流】；警惕【减小电阻途径理论上成立但实际不可行/不经济，答题要逐条说明原因】","src":"物一轮253.远距离输电_笔记","note":"视频|02:06-04:04","orig":"（知识）由PQ=I²R和R=ρL/S：减小L不可行（距离固定）；增大S效果有限（成本高、质量大）；减小ρ不现实（金银成本过高）。结论：减小电阻在实际中效果不佳。","link":""},{"id":"phy1593","t":"远距离输电·高压输电与欧姆定律的辨析","s":"看到【质疑「电压增大电流怎么反而减小」或问高压输电是否违背欧姆定律】","c":"想到【输电电压U$\\neq$输电线上的电压降U线，欧姆定律只对输电线电阻本身成立（R=U线/I）】；警惕【不能用I=U/R直接算输电电流，U中大部分分给了降压变压器（非纯电阻负载）】","src":"物一轮253.远距离输电_笔记","note":"视频|04:04-06:42","orig":"（知识）由P=UI，输出功率一定时增大U可减小I从而降低PQ=I²R；输电电路不是纯电阻电路，U是输电电压、被分配给输电线电阻和降压变压器原线圈，不能用I=U/R算整个电路电流；欧姆定律只适用于输电线本身：R线=U线/I。","link":""},{"id":"phy1594","t":"远距离输电·通用解法框架","s":"看到【完整的远距离输电模型（升压—输电线—降压），求各段电压电流或匝数比】","c":"想到【按「三回路+两变压器」框架逐个方程顺序求解，题目条件已知可减少方程数，无需全部联立】；警惕【输电线电流I线是连接两个变压器的关键纽带，抓住它逐级推算】","src":"物一轮253.远距离输电_笔记","note":"视频|06:42-11:14","orig":"（知识）围绕「三个回路、两个变压器」列七个方程：发电厂回路U=IaRa+U₁、输电线回路U₂=IbRb+U₃、用户端回路U₄=IcRc；升压变压器U₁/U₂=n₁/n₂、Ia/Ib=n₂/n₁；降压变压器U₃/U₄=n₃/n₄、Ib/Ic=n₄/n₃。","link":""},{"id":"phy1595","t":"远距离输电·能耗演示电路逐级推算","s":"看到【升压—输电线—降压的演示电路，由负载功率反推输电线电阻或新状态功率】","c":"想到【先由P=I^{2}R反推电流，再通过匝数比逐级推算电压、电流，最后用U_{2}-U_{3}=IR线求线阻】；警惕【左侧变压器原线圈直接接电源时U_{1}=电源电压、U_{2}固定；换挡后要重新列方程不能沿用旧电流】","src":"物一轮253.远距离输电_笔记","note":"视频|11:14-22:17","orig":"（例）左侧变压器1:3、输入7.5V→U₂=22.5V固定；负载10Ω、功率10W→IC=1A→U₄=10V；右侧2:1→U₃=20V、IB=0.5A；输电线分压2.5V→r=5Ω。开关接2时列方程22.5=5IB+U₃联立解得IB=3A、IC=1.5A、P=22.5W。","link":""},{"id":"phy1596","t":"远距离输电·典型功率损耗计算","s":"看到【已知输送功率、输电线电阻和损失功率，求匝数比或用户电压】","c":"想到【由P损=I^{2}R线直接求输电线电流；升压匝数比=I线:I_{1}（电流反比）；逐级算U_{2}$\\to$减去线损电压$\\to$得U_{3}定降压比】；警惕【损耗功率直接对应I^{2}R求电流，不要用输送功率去算；U_{3}=U_{2}-U线别漏掉输电线分压】","src":"物一轮253.远距离输电_笔记","note":"视频|22:17","orig":"（例）P=100kW、U₁=250V→I₁=400A；P损=5kW、R=8Ω→I线=√(P损/R)=25A；升压比n₁:n₂=I线:I₁=1:16→U₂=4000V；U线=I线R=200V→U₃=3800V；降压比U₃:U₄=3800:220=190:11。","link":""},{"id":"phy1597","t":"机械振动·本讲结构与常考模型","s":"看到【规划机械振动复习或判断题目属于哪类模型】","c":"想到【抓两个常考模型：弹簧振子、单摆；振动方程计算需较强三角函数能力】；警惕【基础薄弱者重点掌握2星内容即可应对基础选择题】","src":"物一轮254.【课前必看】本讲听课建议（机械振动）_笔记","note":"视频|00:20-03:22","orig":"（知识）本讲含四部分：简谐运动特点（2星）、阻尼振动与受迫振动（2星）、振动方程计算（3星）、简谐运动物理证明（5星）；重点模型为弹簧振子和单摆。","link":""},{"id":"phy1598","t":"机械振动·考情与主流题型","s":"看到【波形图与振动图像综合的题目】","c":"想到【波振关系综合是主流考查形式，重点练习两图互推】；警惕【山东曾考不定项选择题、海南24年出证明类多选选项，个别省份题型特殊】","src":"物一轮254.【课前必看】本讲听课建议（机械振动）_笔记","note":"视频|03:22-06:54","orig":"（知识）机械振动机械波属非主干知识模块，约75%以选择题出现、位于试卷前部难度较低；主流题型是波振关系（波形图与振动图综合），单独考机械振动约占25%；北京可能在压轴题结合机械振动出解答题。","link":""},{"id":"phy1599","t":"机械振动·考点频率分布","s":"看到【判断阻尼振动、受迫振动或简谐运动证明题的备考优先级】","c":"想到【核心抓简谐运动图像与两个模型；阻尼/受迫振动仅浙江考生需额外关注，物理证明部分了解即可】；警惕【省份差异明显，按本省考纲分配复习时间】","src":"物一轮254.【课前必看】本讲听课建议（机械振动）_笔记","note":"视频|06:54","orig":"（知识）高频：简谐运动特点及图像（24年贵州/北京/河北等6省考查）；中频：单摆模型（24浙江）、弹簧振子模型（24辽宁）；低频：阻尼振动与受迫振动（主要出现在浙江卷）；罕见：简谐运动物理证明（仅24海南）。","link":""},{"id":"phy1600","t":"简谐运动·运动学参数与初相位","s":"看到【区分振幅与位移，或由初相位判断振动起始位置】","c":"想到【振幅无正负、位移有方向；由$\\varphi$定起点：0对应平衡位置、$\\pi$/2对应最大位移处】；警惕【勿把位移负值当作振幅，振幅恒取正值】","src":"物一轮255.简谐运动特点_笔记","note":"视频|01:13-08:17","orig":"（知识）x=Asin(ωt+φ)或Acos(ωt+φ)；振幅A是偏离平衡位置的最大距离、标量恒为正；位移x是矢量有正负（以平衡位置为参考点）；ω=2π/T；初相位决定起始位置：φ=0从平衡位置、φ=π/2从x=A处开始。","link":""},{"id":"phy1601","t":"简谐运动·x-t图像基本读取","s":"看到【x-t图像，判断某时刻位移、速度、加速度的大小或方向】","c":"想到【位移读纵坐标、速度看切线斜率、加速度由a∝-x判断（与位移反向、越远越大）】；警惕【加速度不能直接从图读，要经a∝-x换算；切线斜率正负反映速度方向】","src":"物一轮255.简谐运动特点_笔记","note":"视频|08:17-11:41","orig":"（知识）振幅=纵坐标最大值的绝对值；周期=相邻波峰（波谷）间时间间隔或任意完整波形对应时间；位移=纵坐标值；速度看切线斜率（斜率陡→速度大）；加速度a∝-x与位移反向、位移越大加速度越大。","link":""},{"id":"phy1602","t":"简谐运动·图像特殊点特征","s":"看到【问图像上过平衡位置或最大位移处的速度、加速度状态】","c":"想到【平衡位置：速度最大、加速度为零；最大位移处：速度为零、加速度最大】；警惕【过零点不是速度为零，而是速度最大】","src":"物一轮255.简谐运动特点_笔记","note":"视频|09:05-11:41","orig":"（知识）平衡位置对应横轴（y=0）；极值点（波峰/波谷）为最大位移处；过零点速度最大、加速度为零；拐点为加速度方向改变点。","link":""},{"id":"phy1603","t":"简谐运动·图像题解题步骤","s":"看到【给x-t图像的综合判断选择题】","c":"想到【按「振幅$\\to$周期$\\to$t=0初状态$\\to$逐项比较」的固定顺序分析】；警惕【加速度方向始终指向平衡位置，不要与位移方向弄混】","src":"物一轮255.简谐运动特点_笔记","note":"视频|11:41-16:00","orig":"（知识）图像题步骤：先定振幅（纵坐标极值）→再定周期（完整波形时间）→分析特殊点（t=0初相位）→比较不同位置运动状态。","link":""},{"id":"phy1604","t":"简谐运动·图像对称性","s":"看到【比较图像上两对称点的位移、速度、加速度或运动时间】","c":"想到【判定对称关系（关于平衡位置或波峰/波谷）后直接得四量相等结论，无需死记分类】；警惕【速度等大但方向可能相反，要看斜率正负】","src":"物一轮255.简谐运动特点_笔记","note":"视频|16:00-22:01","orig":"（知识）「双对称四维度」：关于平衡位置（中心对称）和振幅位置（轴对称）的两点，其位移、速度、加速度、时间四个量均对称——位移和加速度等大、速度等大（方向可能相反）、运动时间相等。","link":""},{"id":"phy1605","t":"简谐运动·全振动概念","s":"看到【判断某段过程是否为一次全振动】","c":"想到【看是否回到起点且速度大小、方向都复原，二者缺一不可】；警惕【路径回到原位但速度方向反了不算全振动】","src":"物一轮255.简谐运动特点_笔记","note":"视频|22:01-23:59","orig":"（知识）一个完整周期内的振动过程：需满足空间完整性（如O→B→O→A→O）且再次经过某点时速度大小和方向均相同；仅O→B→O不算全振动（速度方向未复原）。","link":""},{"id":"phy1606","t":"简谐运动·周期与路程的关系","s":"看到【求某段时间内振动的路程，或从任意位置出发问1/4周期路程】","c":"想到【整周期/半周期的路程与起点无关（4A、2A）；1/4周期路程=1A仅限端点或平衡位置起始】；警惕【一般位置出发的1/4周期路程$\\neq$振幅，靠近平衡位置速度大、相同时间位移更长】","src":"物一轮255.简谐运动特点_笔记","note":"视频|23:59-32:13","orig":"（知识）1个周期必定对应4倍振幅路程、1/2周期必定对应2倍振幅路程（任何起点均成立）；1/4周期仅当从平衡位置或振幅位置出发才对应1倍振幅，一般位置不成立。","link":""},{"id":"phy1607","t":"简谐运动·动力学特征与回复力","s":"看到【判断某运动是否为简谐运动，或辨析回复力概念】","c":"想到【验证合力能否写成F=-kx形式；回复力是效果力、由真实力的合力提供】；警惕【k不一定是弹簧劲度系数（如单摆无弹簧）、x不一定是形变量；别把F=-kx与胡克定律F=kx混淆】","src":"物一轮255.简谐运动特点_笔记","note":"视频|32:13-35:42","orig":"（知识）物体做简谐运动的本质是合力充当回复力，F=-kx；回复力是效果力（振动方向合力的效果，类比向心力），不是实际存在的力；k为回复力系数，不一定是弹簧劲度系数；x是由平衡位置指向末位置的位移。","link":""},{"id":"phy1608","t":"简谐运动·加速度与能量特点","s":"看到【判断振动中动能、势能（或其他能）随位置的转化】","c":"想到【平衡位置动能最大、端点势能最大，系统机械能守恒、动能与势能此消彼长】；警惕【单摆中是动能与重力势能转化，不一定是弹性势能】","src":"物一轮255.简谐运动特点_笔记","note":"视频|35:42-37:13","orig":"（知识）由F=ma和F=-kx得a=-(k/m)x，加速度与位移成正比、方向相反；系统总能量守恒：平衡位置速度最大→动能最大、势能最小；振幅位置速度为零→动能最小、势能最大。","link":""},{"id":"phy1609","t":"简谐运动·图像判断例题","s":"看到【给x-t图像上具体时刻，判断速度与加速度】","c":"想到【水平切线$\\to$速度为零；位移最大$\\to$加速度最大且与位移反向】；警惕【位移方向与加速度方向相反，别由位移正负直接推加速度正负】","src":"物一轮255.简谐运动特点_笔记","note":"视频|37:13-43:27","orig":"（例）x-t图像：t=1s处波峰→速度为零、位移正最大→加速度负最大；t=4s处平衡位置→速度最大、加速度为零。","link":""},{"id":"phy1610","t":"简谐运动·对称性与周期倍数应用","s":"看到【问经过若干个半整数周期后物体所处位置和状态】","c":"想到【用周期倍数拆分：整数T回原状态，多0.5T到关于平衡位置的对称位置】；警惕【最高点加速度方向指向平衡位置（负方向），别与位移同向】","src":"物一轮255.简谐运动特点_笔记","note":"视频|43:27","orig":"（例）初始在最低点，经1.5T=1T+0.5T完成全振动后到对称的最高点：位移正最大、速度为零、加速度负最大、回复力最大。","link":""},{"id":"phy1611","t":"弹簧振子·基本水平模型","s":"看到【光滑水平面弹簧振子，问平衡位置或回复力来源】","c":"想到【平衡位置=弹簧原长处，回复力仅由弹簧弹力提供F=-kx】；警惕【负号表示力与位移方向相反，体现「恢复」特性】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|00:45-04:45","orig":"（知识）光滑水平面上弹簧（劲度系数k）+物块（质量m）：平衡位置与弹簧原长重合，弹力为零；位移x由平衡位置起算，水平模型中形变量与位移数值相等；回复力F=-kx，k既是劲度系数也是回复力系数。","link":""},{"id":"phy1612","t":"弹簧振子·周期公式","s":"看到【问弹簧振子周期与振幅的关系，或改变振幅问周期变化】","c":"想到【T=2$\\pi$√(m/k)与振幅无关，只由m和k决定】；警惕【振动范围变大不代表周期变长】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|04:45-05:57","orig":"（知识）T=2π√(m/k)，周期仅取决于物块质量m和回复力系数k，与振幅大小无关——振动范围是MN还是M'N'周期都相同。","link":""},{"id":"phy1613","t":"弹簧振子·能量与振幅","s":"看到【比较不同振幅下振动系统的总能量】","c":"想到【总能量由振幅决定，振幅越大能量越高】；警惕【总能量守恒指系统，单个物体的机械能不一定守恒】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|05:57-07:08","orig":"（知识）系统总能量=动能+弹性势能，端点处动能全部转化为势能；振幅越大→最大形变量越大→系统总能量越高；振动中动能与势能周期性转化，总能量守恒（忽略阻尼）。","link":""},{"id":"phy1614","t":"弹簧振子·竖直弹簧模型","s":"看到【竖直悬挂的弹簧振子，问平衡位置或是否为简谐运动】","c":"想到【恒定重力只平移平衡位置（mg=kx_{0}），不改变简谐本质，周期公式仍适用】；警惕【平衡位置$\\neq$原长位置，位移要从平衡位置起算而非原长】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|07:08-11:26","orig":"（知识）竖直弹簧振动仍是简谐运动：平衡位置满足mg=kx₀（弹簧伸长x₀），不再与原长重合；以平衡位置起算位移x，合力F=mg-k(x₀-x)=-kx仍满足简谐条件；周期公式T=2π√(m/k)形式不变。","link":""},{"id":"phy1615","t":"弹簧振子·斜面弹簧模型","s":"看到【光滑斜面上的倾斜弹簧振子】","c":"想到【类比竖直模型：把mgsin$\\theta$当作等效恒力，平衡位置kx_{0}=mgsin$\\theta$，周期不变】；警惕【垂直斜面分量被支持力抵消，回复力只看沿斜面方向】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|12:27-15:04","orig":"（知识）光滑斜面上：重力分解为mgsinθ（沿斜面）和mgcosθ（被支持力抵消）；平衡位置满足kx₀=mgsinθ；周期T=2π√(m/k)；与竖直弹簧仅恒力大小方向不同，受力形式相似。","link":""},{"id":"phy1616","t":"简谐运动·模型识别判定条件","s":"看到【判断新场景（含重力、斜面等）中的振动是否为简谐运动】","c":"想到【检查「恒定外力+弹簧弹力」能否化成F=-kx形式，恒力只移动平衡位置不改k】；警惕【若其他力的合力不恒定（如摩擦力变向），则不是简谐运动】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|15:04-16:28","orig":"（知识）判定简谐运动：①除弹簧弹力外其他力的合力恒定；②弹簧弹力与合外力共线。竖直弹簧、斜面弹簧等满足即判定为简谐运动。","link":""},{"id":"phy1617","t":"弹簧振子·双弹簧模型","s":"看到【物块两端连两个弹簧振动】","c":"想到【两弹簧弹力同向叠加，等效k=k_{1}+k_{2}代入周期公式】；警惕【位移变化时两弹簧总是一个压缩一个拉伸，回复力是两者之和不是之差】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|16:28-18:57","orig":"（知识）两端弹簧（k₁、k₂）作用于同一物块：合力F=-(k₁+k₂)x，平衡位置在弹簧原长处，回复力系数k_eff=k₁+k₂，周期T=2π√(m/(k₁+k₂))。","link":""},{"id":"phy1618","t":"弹簧振子·粗糙水平面弹簧","s":"看到【粗糙面上弹簧振子往复运动，问是否简谐或平衡位置】","c":"想到【摩擦力双向变号$\\to$全过程非简谐，但单方向各是简谐片段、平衡位置各偏移$\\mu$mg/k】；警惕【最大速度点不在原长处，而在各自运动方向的平衡位置】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|18:57-22:58","orig":"（知识）粗糙水平面：摩擦力f=μmg与运动方向相反，方向随运动改变→全过程非简谐运动；单方向运动可视为简谐运动片段，平衡位置偏移x=μmg/k（右移时kx₁=μmg压缩态、左移时kx₂=μmg拉伸态）；摩擦耗能使振幅衰减。","link":""},{"id":"phy1619","t":"弹簧振子·分离与对称例题","s":"看到【物体被竖直弹簧弹起后脱离弹簧的运动阶段分析】","c":"想到【分离条件：接触面间弹力为零（即弹簧原长处）；平衡位置速度最大；能量决定最大高度】；警惕【最低点与原长位置不对称，最低点加速度大于g；平衡位置到原长时间随释放高度变化】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|22:58-31:58","orig":"（例）小球竖直弹簧弹起：脱离弹簧前简谐运动、脱离后匀减速（仅受重力）；平衡位置Fk=mg处速度最大；分离点=原长位置（弹力为零临界点）；最低点加速度>g（与原长不对称）；更低位置释放→能量增大→最大高度增大。","link":""},{"id":"phy1620","t":"弹簧振子·恒力加弹簧例题","s":"看到【弹簧振子受恒力作用，判断运动细节或撤力后的状态】","c":"想到【恒力不改简谐本质，平衡位置由「恒力=弹力」确定，往复发生在平衡位置两侧】；警惕【远离平衡位置时加速度增大而非一直减速；振幅范围以平衡位置为对称中心】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|31:58-36:36","orig":"（例）恒力F与弹簧组合：平衡位置在恒力与弹力平衡处（非原长点O）；存在加速度增大的减速阶段（远离平衡位置时）；弹簧始终伸长，最大弹力=2F；O点速度为零时撤力系统保持静止。","link":""},{"id":"phy1621","t":"弹簧振子·匀速段与简谐段组合","s":"看到【物体在两弹簧原长之间往复（中间无弹力），判断运动性质、周期或v-t图像】","c":"想到【有匀速段就不是简谐运动；简谐段周期T=2$\\pi$√(m/k)与速度无关，动能变化周期为T/2】；警惕【总周期变化$\\neq$2倍，只算匀速部分的时间变化；简谐运动图像中不应存在匀速部分】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|36:36-45:25","orig":"（例）小球在两弹簧间运动：中间段不受力做匀速运动→整体非简谐运动，v-t图像由匀速直线段与正弦曲线段交替组成；动能、势能变化周期均为T/2；初速度减半仅匀速段时间加倍（t=x/v），简谐段周期不变，总周期非2倍关系。","link":""},{"id":"phy1622","t":"弹簧振子·粗糙面往复的能量衰减","s":"看到【粗糙面上弹簧振子最终停在哪、或某速度出现几次】","c":"想到【停止条件：弹簧弹力$\\leq$最大静摩擦力，停在原长点左右对称区域；摩擦耗能$\\to$最大速度逐次递减】；警惕【最大速度点不在原长点；速度对称点只在单方向运动内存在】","src":"物一轮256.弹簧振子模型_笔记","note":"视频|45:25","orig":"（例）粗糙面上弹簧振子：向左/右运动各自构成简谐运动但平衡位置不同；每次转向后最大速度递减（摩擦做功）；最终停在|F弹|≤fmax的任何位置（原长点左右对称区域）；全过程速度为v₀的时刻仅两个（首次向左运动阶段）。","link":""},{"id":"phy1623","t":"机械振动·单摆受力分析","s":"看到【单摆最低点「合力为零」的表述】","c":"想到【平衡位置仅指振动方向合力为零，径向 T−mg 提供 v^{2}/l 的向心力，故最低点 T>mg；非平衡位置靠重力切向分量回复】；警惕【把「合力为零」误认为所有方向合力都为零】","src":"物一轮257.单摆模型_笔记","note":"视频|00:40","orig":"（知识）平衡位置（最低点）振动方向合力为零，但径向 T−mg≠0 提供向心力；其他位置重力沿切线方向分量提供回复力","link":""},{"id":"phy1624","t":"机械振动·单摆周期公式","s":"看到【单摆周期、等时性或摆长取值问题】","c":"想到【T=2$\\pi$√(l/g)，摆长取悬点到重心距离，周期与振幅、摆球质量无关】；警惕【摆长漏加小球半径，或误认为摆角大小影响周期】","src":"物一轮257.单摆模型_笔记","note":"视频|02:36","orig":"（知识）T=2π√(l/g)，l 为悬点到小球重心（球心）的距离，g 为当地重力加速度；周期与振幅无关（等时性）","link":""},{"id":"phy1625","t":"机械振动·等效摆长（多绳悬挂）","s":"看到【多绳悬挂小球求等效摆长】","c":"想到【按摆动方向定等效悬点：垂直纸面摆动看三绳共同交点并计入几何分量，纸面内小角度摆动摆长缩短】；警惕【纸面内必须小角度摆动，角度过大 BC 绳松弛、绳力突变，破坏简谐运动条件】","src":"物一轮257.单摆模型_笔记","note":"视频|04:07","orig":"（例）三绳悬挂小球：垂直纸面摆动时等效悬点为三绳交点，摆长 l+r+lsinα；纸面内小角度摆动时等效悬点为 AB 绳交点，摆长 l+r","link":""},{"id":"phy1626","t":"机械振动·圆弧轨道类单摆","s":"看到【小球在圆弧面/圆弧轨道内小角度往复运动】","c":"想到【类单摆模型，等效摆长 R−r（轨道半径减小球半径），周期套用 T=2$\\pi$√(l/g)】；警惕【摆长用 R 而忘记减去小球半径】","src":"物一轮257.单摆模型_笔记","note":"视频|04:07","orig":"（知识）小球在圆弧轨道内小角度往复：弹力始终指向圆心，受力形式与单摆相同，等效摆长为 R−r","link":""},{"id":"phy1627","t":"机械振动·摆长比求几何量","s":"看到【给出两段摆动的时间或周期关系，求几何高度/摆长】","c":"想到【先由时间比得周期比，再由 T∝√L 转化为摆长比，最后用几何总长求未知高度】；警惕【把周期比直接当成摆长比，忘记开平方关系】","src":"物一轮257.单摆模型_笔记","note":"视频|10:18","orig":"（例）细线跨窗沿摆动：T(AO)=½T(BO)，得 L(AO)=¼L(BO)；总绳长 2m，BO 段摆长 2m，AO 段摆长 0.5m，窗沿高 1.5m","link":""},{"id":"phy1628","t":"机械振动·双线摆受力与周期","s":"看到【双线/对称细线悬挂的单摆求周期】","c":"想到【先受力平衡定几何角度（光滑细线两侧张力相等），再由几何关系求等效摆长代入周期公式】；警惕【忽略「光滑细线」隐含张力相等条件，或误认为摆角影响周期】","src":"物一轮257.单摆模型_笔记","note":"视频|14:33","orig":"（例）双线对称悬挂：光滑细线 TA=TB，由 TA sin30°=TB sinθ 得 θ=30°；几何求等效摆长 1m，T=2π√(1/10)≈2s","link":""},{"id":"phy1629","t":"机械振动·单摆与天体综合","s":"看到【T^{2}-L 图像或单摆测重力加速度与天体问题综合】","c":"想到【斜率 k=4$\\pi$^{2}/g 与 g 成反比，由斜率比反推 g 比；再用黄金代换 GM=gR^{2} 求天体质量、密度及宇宙速度 v=√(gR)】；警惕【把斜率与 g 的反比关系写成正比】","src":"物一轮257.单摆模型_笔记","note":"视频|24:55","orig":"（例）T²-L 图像斜率 k=4π²/g，g(k):g(地)=1:4；结合 GM=gR² 得质量比 64、密度比 1:1、宇宙速度比 4","link":""},{"id":"phy1630","t":"机械振动·复合场中的单摆","s":"看到【带电小球在电场/磁场/复合场中摆动】","c":"想到【先判断场力是否恒定：恒力与重力合成得 g^{'}=F合/m，周期 T=2$\\pi$√(l/g^{'})；库仑力、洛伦兹力方向随位置或速度变化，只影响向心力不影响回复力，周期不变】；警惕【对方向可变的场力也做等效重力处理】","src":"物一轮257.单摆模型_笔记","note":"视频|32:29","orig":"（知识）匀强电场恒力可与重力合成得等效 g′，g′ 增大则周期减小；库仑力方向随位置变化不提供回复力，洛伦兹力始终垂直速度仅提供向心力，周期均不变","link":""},{"id":"phy1631","t":"机械振动·超失重中的单摆","s":"看到【电梯超重/失重环境中的单摆】","c":"想到【在加速参考系中取等效重力加速度 g^{'}=g±a（加速下降 g−a、加速上升 g+a），周期随 g^{'} 减小而增大】；警惕【忘记换到非惯性系分析】","src":"物一轮257.单摆模型_笔记","note":"视频|32:29","orig":"（知识）须以加速参考系（电梯内）观察；T=mg−ma 推出 g′=g−a，加速下降时周期增大","link":""},{"id":"phy1632","t":"机械振动·简谐运动判定总结","s":"看到【判断某运动是否为简谐运动或求其周期】","c":"想到【三维度判定：动力学 F=−kx、运动学正余弦位移式、能量守恒；周期公式弹簧振子 T=2$\\pi$√(m/k)、单摆 T=2$\\pi$√(l/g)】；警惕【1 周期路程等于 4A，但任意 1/4 周期路程不一定等于 A】","src":"物一轮257.单摆模型_笔记","note":"视频|32:29","orig":"（知识）运动学 x=Asin(ωt+φ)，1 周期对应 4 振幅路程；动力学回复力 F=−kx；能量机械能守恒；弹簧振子 T=2π√(m/k)","link":""},{"id":"phy1633","t":"机械振动·阻尼振动","s":"看到【振幅逐渐减小的振动】","c":"想到【阻尼振动：能量不断耗散、振幅衰减；与简谐运动（能量守恒、振幅不变）相区分】；警惕【阻尼振动周期近似不变，变化的是振幅而非频率】","src":"物一轮258.阻尼振动与受迫振动完整视频_笔记","note":"视频|00:40","orig":"（知识）振动中存在阻力（如空气阻力）持续耗能，系统总能量不断减小，振幅逐渐衰减；多数自然振动属阻尼振动","link":""},{"id":"phy1634","t":"机械振动·受迫振动","s":"看到【系统在周期性驱动力下稳定振动，问振动频率】","c":"想到【受迫振动稳定后频率等于驱动力频率，与固有频率无关】；警惕【把振动频率当成固有频率 f_{0}】","src":"物一轮258.阻尼振动与受迫振动完整视频_笔记","note":"视频|02:12","orig":"（知识）周期性驱动力做功补偿阻尼耗能，振幅稳定；振动频率完全由驱动力频率决定，与系统固有频率无关","link":""},{"id":"phy1635","t":"机械振动·共振","s":"看到【驱动力频率接近固有频率，问振幅变化】","c":"想到【f驱=f_{0} 时共振，振幅最大；A-f 曲线为单峰，峰值在固有频率处】；警惕【振幅随 f驱 并非单调变化，离 f_{0} 越近越大而非一直增大】","src":"物一轮258.阻尼振动与受迫振动完整视频_笔记","note":"视频|02:12","orig":"（知识）f驱动力=f₀ 时发生共振，振幅最大；振幅-频率关系呈单峰曲线，峰值位于 f₀ 处","link":""},{"id":"phy1636","t":"机械振动·受迫振动判断","s":"看到【一个振动体带动多个不同摆长的摆振动】","c":"想到【被带动各摆均做受迫振动，频率/周期相同（等于驱动源）；摆长与驱动源相同的那个发生共振、振幅最大】；警惕【误认为摆长不同的球周期不同】","src":"物一轮258.阻尼振动与受迫振动完整视频_笔记","note":"视频|06:16","orig":"（例）A 球振动带动 B、C、D 三球做受迫振动，周期均等于 A 球振动周期；lC=lA 时 C 球共振、振幅最大","link":""},{"id":"phy1637","t":"机械振动·共振与自由振动辨析","s":"看到【持续驱动源与单次敲击后的振动对比】","c":"想到【受迫振动需持续外力、频率=驱动力频率；打击结束后的振动是自由振动、频率=固有频率】；警惕【把敲击结束后的振动仍当作受迫振动】","src":"物一轮258.阻尼振动与受迫振动完整视频_笔记","note":"视频|08:44","orig":"（例）振动器工作使树做受迫振动（频率=振动器频率）；打击结束后树做自由振动（频率由树干固有特性决定）；不同树固有频率不同、最佳采摘频率不同","link":""},{"id":"phy1638","t":"机械振动·振动方程书写步骤","s":"看到【要求写出/补全简谐运动振动方程】","c":"想到【按 A$\\to$$\\omega$$\\to$φ 顺序确定三要素：A 看纵坐标最大值，$\\omega$=2$\\pi$/T，$\\varphi$ 代入已知点解两个候选值再取舍】；警惕【初相位两解取错，需结合平移方向判断】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|01:07","orig":"（知识）标准形式 y=Asin(ωt+φ)：A 取纵坐标最大值；ω=2π/T；φ∈[−π,π]，代入已知点解出两值，一个绝对值小于 π/2、另一个大于 π/2","link":""},{"id":"phy1639","t":"机械振动·初相位取舍（左加右减）","s":"看到【由图像平移情况确定初相位两个候选值】","c":"想到【左加右减定 $\\varphi$ 符号；看平移是否越过波峰/波谷定 |$\\varphi$| 与 $\\pi$/2 的大小关系】；警惕【只解出两解不结合平移判断，选错初相位】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|03:06","orig":"（知识）φ>0 图像由正弦曲线向左平移得到，φ<0 向右平移；平移超过波峰/波谷则 |φ|>π/2，未超过则 |φ|<π/2","link":""},{"id":"phy1640","t":"机械振动·振动方程求参例题","s":"看到【给出周期和某点坐标求振动方程】","c":"想到【先写 y=Asin($\\omega$t+$\\varphi$) 骨架，代点解 $\\varphi$ 双解，再按平移方向和是否过峰谷取唯一解】；警惕【两个候选 $\\varphi$ 都代回均满足方程，须靠图像走势定取舍】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|04:09","orig":"（例）T=2s、A=4、过点(0,2)：ω=π，sinφ=1/2 得 φ=π/6 或 5π/6；图像向左平移且未过波峰，取 φ=π/6，得 y=4sin(πt+π/6)","link":""},{"id":"phy1641","t":"机械振动·振动方程与运动状态分析","s":"看到【由振动图像两点定方程，再判断某时刻速度/加速度】","c":"想到【图像斜率正负判速度方向，斜率变小说明速度减小；波谷处位移负向最大、加速度正向最大】；警惕【代 t=0 验证选项可快速排除矛盾项】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|11:05","orig":"（例）过(0,5)与(0.2,10)：A=10cm，φ=π/6，0.2ω+π/6=π/2+2kπ 得 ω=5π/3，T=1.2s；t=0.6s 斜率为负速度减小；t=0.8s 处波谷加速度正向最大","link":""},{"id":"phy1642","t":"机械振动·弹簧振子受力极值","s":"看到【竖直弹簧振子+「刚好为零/恰好离开」类临界条件】","c":"想到【用简谐运动对称性：最高点与最低点加速度等大反向，由最高点临界受力推出最低点弹力与地面压力】；警惕【振幅误取、漏掉底座自身重力】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|19:35","orig":"（例）物块 A 在底座 B 上振动，最高点时 B 对地面作用力刚好为零；由对称性最低点加速度 2g 向上，弹力 3mg，底座对地面最大压力 4mg","link":""},{"id":"phy1643","t":"机械振动·对称点与路程计算","s":"看到【从非特殊位置（非平衡位置/最大位移处）开始算一段时间内的路程】","c":"想到【一般位置起算的 1/4 周期路程$\\neq$振幅，必须代振动方程逐点求位移再相减；关于平衡位置对称的两时刻速度等大同向、加速度等大】；警惕【机械套用「1/4 周期走 A」】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|28:04","orig":"（例）振子在弹簧原长下方平衡，弹力 kx=mg；x=−5cos(πt) 或 5sin(πt−π/2)；关于平衡位置对称的 t=0.25s 与 0.75s 速度等大同向、加速度等大；路程=5√2 cm","link":""},{"id":"phy1644","t":"机械振动·固定时间最大路程","s":"看到【给定小于 T/4 的时间，求振子最大路程】","c":"想到【速度在平衡位置最大，让时间段对称地套在平衡位置两侧可最大化路程；此时路程可用振动方程代入端点计算】；警惕【默认从最大位移处出发、认为路程=对应比例的振幅】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|36:25","orig":"（例）T/6 时间内最大路程：让振子尽量久地在平衡位置附近（速度最大区），两侧各分 T/12，路程恰为 A","link":""},{"id":"phy1645","t":"机械振动·多解问题（位移方向不确定）","s":"看到【只给位移大小不给方向，求振幅或周期】","c":"想到【分位移同侧/异侧两种情况分别列几何关系求振幅；周期含整数 k 有多解，需由振动方程代入两点解出通式】；警惕【漏掉位移同侧情形或漏写 k 的取值讨论】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|56:38","orig":"（例）A、B 两点位移大小给定向量未给方向：两种情况（−A/2 与 3A/2、A/2 与 3A/2）对应不同振幅；周期解含 k：T=12t/(4k+1) 或 T=6t/(2k+1)","link":""},{"id":"phy1646","t":"机械振动·浮力类简谐运动","s":"看到【浮体（木筷/木块）在液面上下振动求振幅、质量或路程】","c":"想到【振幅=最深与最浅浸入深度差的一半，平衡位置浮力=重力解质量；求初相位优先代波峰/波谷坐标避免多解】；警惕【振幅误取 ½(h_{1}+h_{2})，质量表达式漏掉 $\\rho$ 或 S】","src":"物一轮259.通过振动方程计算简谐运动的时间和位移完整视频_笔记","note":"视频|01:05:36","orig":"（例）木筷竖直浮沉：A=½(h₂−h₁)；平衡时 mg=ρgS(h₁+A)，解得 m=½ρS(h₁+h₂)；t₀~5t₀ 为 1/4 周期，动能先增后减；代波峰/波谷坐标可避免初相位多解","link":""},{"id":"phy1647","t":"机械振动·简谐运动证明方法","s":"看到【证明某运动是简谐运动】","c":"想到【首选动力学证明：设偏离平衡位置位移 x，分析回复力并化简为 F=−kx 形式即得证】；警惕【忘记以平衡位置为原点列力，导致常量力未消去】","src":"物一轮260.简谐运动的物理证明_笔记","note":"视频|00:06","orig":"（知识）运动学证明：位移满足 x=Asin(ωt+φ) 或余弦式；动力学证明：振动方向合力满足 F=−kx（k 为比例系数，负号表示力与位移反向）","link":""},{"id":"phy1648","t":"机械振动·浮力模型证明","s":"看到【木块/浮体在液体中上下振动要求证明简谐】","c":"想到【以平衡位置（浮力=重力）为原点，合力化简后只剩与位移成正比的部分 F=−$\\rho$gSx，比例系数即 $\\rho$gS】；警惕【从水面而非平衡位置列式，多余常量力未消掉】","src":"物一轮260.简谐运动的物理证明_笔记","note":"视频|02:42","orig":"（例）水中木块：平衡时 mg=ρgSx₀；偏离 x 时 F合=ρgS(x₀+x)−mg=−ρgSx，满足 F=−kx，k=ρgS","link":""},{"id":"phy1649","t":"机械振动·地心隧道模型证明","s":"看到【物体沿穿透地球的隧道运动，问运动性质】","c":"想到【匀质球体内部万有引力 F∝r 且指向球心，得 F=−(GMm/R^{3})x，属简谐运动】；警惕【直接用表面引力公式 GMm/R^{2} 而不知球内引力的线性推论】","src":"物一轮260.简谐运动的物理证明_笔记","note":"视频|06:50","orig":"（例）质量均匀实心球内部引力与到球心距离成正比；隧道中 F=−(GMm/R³)x，k=GMm/R³，为简谐运动","link":""},{"id":"phy1650","t":"机械振动·电场中带电粒子简谐证明","s":"看到【带电粒子在两固定电荷中垂线附近微振动】","c":"想到【对 (r±x)^{2} 做小量近似 1/(1±$\\alpha$)ⁿ≈1∓n$\\alpha$，合力化简为 F≈−(4kq/r^{3})x 形式即证简谐】；警惕【不做 x≪r 近似硬算，或忽略受力方向随偏移反转】","src":"物一轮260.简谐运动的物理证明_笔记","note":"视频|06:50","orig":"（例）两等量负电荷相距 2r，电子在中垂线附近偏移 x：F合≈−(4kq_e/r³)x（x≪r 近似），满足线性回复力","link":""},{"id":"phy1651","t":"静电场·等量同种电荷中垂线场强极值","s":"看到【求等量同种电荷中垂线上场强最大位置】","c":"想到【写出 E 随距离的函数后求导取极值；O 点场强为零、无穷远为零，故中间存在极大值】；警惕【根式化简出错，需有理化处理】","src":"物一轮260.简谐运动的物理证明_笔记","note":"视频|09:45","orig":"（例）求导得中垂线上场强最大点距 O 点 (√2/2)r，最大场强值 4√3kq/(9r²)","link":""},{"id":"phy1652","t":"机械振动·带电小环平衡位置与稳定性","s":"看到【两固定电荷间放第三个电荷，问能否平衡及平衡是否稳定】","c":"想到【先逐区域排除找平衡位置（两点间力同向不能平衡），再微移看合力指向：指向平衡位置为稳定可振动，背离则不稳定】；警惕【电荷正负改变时受力方向全部反转，稳定性结论随之改变】","src":"物一轮260.简谐运动的物理证明_笔记","note":"视频|26:23","orig":"（例）杆上小环 C 在电荷 4q 与 q 之间：平衡方程解得 x=d（B 右侧距 d 处）；A 左侧、AB 间均无法平衡；C 带 +q 时偏移后合力背离平衡位置、不稳定；C 带 −q 时合力总指向平衡位置","link":""},{"id":"phy1653","t":"机械振动·小量近似证简谐","s":"看到【库仑力表达式中含 (d±x)^{2}，要求证明简谐运动】","c":"想到【提取 d^{2} 凑 (1±$\\alpha$)^{2}，用近似 1/(1±$\\alpha$)ⁿ≈1∓n$\\alpha$ 化简为 F=−kx 形式；须验证两个方向位移合力均指向平衡位置】；警惕【近似公式记错符号方向，或只验证单方向】","src":"物一轮260.简谐运动的物理证明_笔记","note":"视频|26:23","orig":"（例）负电荷小环偏移 x：F合=k·4q²/(2d+x)²−k·q²/(d+x)²，提取 d² 构造 (1±α) 形式，x≪d 时 F合≈−(kq²/d³)x，两个方向均指向平衡位置","link":""},{"id":"phy1654","t":"机械波·复习策略","s":"看到【机械波模块复习时间分配问题】","c":"想到【按选择题标准备考，优先攻克波振图像综合与干涉/衍射现象识别两大高频考点】；警惕【按解答题难度过度投入】","src":"物一轮261.【课前必看】本讲听课建议_笔记","note":"视频|03:30","orig":"（知识）机械振动与机械波属非主干知识，大部分省份以选择题出现、难度偏低；核心考点为波振关系（占 70% 以上考题）与波的干涉","link":""},{"id":"phy1655","t":"机械波·知识模块与学习路径","s":"看到【机械波零基础或有基础的学习顺序选择】","c":"想到【路径：波的描述$\\to$波的特性$\\to$波动图像$\\to$振动方程$\\to$多解性；基础薄弱先掌握 1-2 星，进阶再攻多解性】；警惕【跳过波形图与振动图的区别直接做多难题】","src":"物一轮261.【课前必看】本讲听课建议_笔记","note":"视频|00:10","orig":"（知识）基础模块（1-2 星）：波的描述（v、T、λ）、波的图像、波的特性（衍射/干涉）；进阶模块（3-4 星）：由波形图建振动方程 y=Asin(ωt+φ)、多解性问题","link":""},{"id":"phy1656","t":"机械波·预备数学工具","s":"看到【机械波章节涉及的振动方程参数求解】","c":"想到【先掌握 y=Asin($\\omega$x+$\\varphi$) 三参数的图像求法（对应数学三角函数章节），再进入波的学习】；警惕【数学工具不熟导致波形图建方程卡壳】","src":"物一轮261.【课前必看】本讲听课建议_笔记","note":"视频|06:56","orig":"（知识）必备三角函数：y=Asin(ωx+φ) 中振幅 A、角频率 ω、相位 φ 的求法；需具备波形图与三角函数图像的转换能力","link":""},{"id":"phy1657","t":"机械波·波的形成","s":"看到【波源振动一段时间后问形成多长波形】","c":"想到【波源每完成一次全振动（一个周期）向外传出一个完整波形；传播距离可按 s=vt 分段累加】；警惕【把波形传播距离与质点振动位移混为一谈】","src":"物一轮262.波的描述_笔记","note":"视频|00:31","orig":"（知识）绳波：波源端点上下振动，振动状态依次向右传递；t=T 时形成一个完整波形，每周期产生一个完整波形","link":""},{"id":"phy1658","t":"机械波·质点不随波迁移","s":"看到【选项出现「质点随波迁移/向前运动」】","c":"想到【机械波传播的是振动形式和能量，质点只在平衡位置附近振动，必错项直接排除】；警惕【被波形整体平移的演示误导】","src":"物一轮262.波的描述_笔记","note":"视频|02:06","orig":"（知识）每个质点仅围绕平衡位置上下振动，不随波形移动；质点间靠分子间作用力传递振动","link":""},{"id":"phy1659","t":"机械波·振动形式的传递规律","s":"看到【问某质点何时开始振动、起振方向如何】","c":"想到【每个质点的振动形式（含起振方向）都重复波源，只是时间上延迟传播距离/v；本质是前质点驱动的受迫振动】；警惕【忽略传播延迟，认为所有质点同时开始振动】","src":"物一轮262.波的描述_笔记","note":"视频|03:38","orig":"（知识）后一质点模仿前一质点的振动（振幅、频率相同，有时间延迟）；所有质点振动形式与波源一致；力学本质是受迫振动","link":""},{"id":"phy1660","t":"机械波·周期的一致性","s":"看到【波的周期/频率由什么决定】","c":"想到【波的周期与频率完全由波源决定，与介质无关；波速才由介质决定】；警惕【跨介质时误认为频率改变】","src":"物一轮262.波的描述_笔记","note":"视频|07:12","orig":"（知识）波源完成一次全振动的时间等于产生一个完整波形的时间，即波的传播周期=波源振动周期","link":""},{"id":"phy1661","t":"机械波·横波与纵波","s":"看到【判断某波是横波还是纵波，或问波形特征】","c":"想到【按振动方向与传播方向垂直/平行分类；横波有峰谷、纵波有密疏部】；警惕【误记声波为横波，实际声波是纵波】","src":"物一轮262.波的描述_笔记","note":"视频|08:47","orig":"（知识）横波：振动方向⊥传播方向，有波峰波谷（绳波、电磁波）；纵波：振动方向∥传播方向，有密部疏部（弹簧波、声波）","link":""},{"id":"phy1662","t":"机械波·机械波与电磁波","s":"看到【问某波能否在真空中传播】","c":"想到【机械波需介质、真空不能传播；电磁波与引力波无需介质】；警惕【把声波当成可在真空传播】","src":"物一轮262.波的描述_笔记","note":"视频|13:23","orig":"（知识）机械波传播需要介质，真空不能传播（绳波、声波）；电磁波、引力波可在真空中传播","link":""},{"id":"phy1663","t":"机械波·v、T、λ 的决定因素","s":"看到【波进入另一种介质，问 v、T、$\\lambda$、f 哪些变】","c":"想到【跨介质时频率（周期）不变、波速变、波长随 v 同比例变；$\\lambda$ 是完整波形的空间长度】；警惕【波长误按波形曲线长度测量】","src":"物一轮262.波的描述_笔记","note":"视频|14:26","orig":"（知识）波速 v 由介质决定（声波空气 340m/s、水中 1450m/s、固体更快）；周期由波源决定；波长是一个完整波形的长度（平衡位置间距，非曲线长度），受波源和介质共同影响","link":""},{"id":"phy1664","t":"机械波·三量关系公式","s":"看到【已知波速、周期/频率求波长，或反向计算】","c":"想到【三量一台戏：$\\lambda$=vT、v=$\\lambda$f；类比 s=vt 记忆，频率与周期互为倒数】；警惕【单位不统一（km/s 与 m/s 混用）】","src":"物一轮262.波的描述_笔记","note":"视频|18:22","orig":"（知识）λ=vT，v=λf（由 f=1/T 推得）","link":""},{"id":"phy1665","t":"机械波·地震波应用","s":"看到【地震纵波横波的速度差、时间差问题】","c":"想到【纵波快先到、上下震；横波慢后到、水平晃且危害大；时间差 $\\Delta$t=s(1/v_{1}−1/v_{2})，计算取初始时刻】；警惕【危害性只看振幅大小】","src":"物一轮262.波的描述_笔记","note":"视频|20:31","orig":"（例）纵波 8km/s 先到（先上下震）、横波 4km/s 后到（后水平晃）；危害主要取决于振动方向而非振幅；预警是利用震后波速差，不等于预测","link":""},{"id":"phy1666","t":"机械波·声波跨介质计算","s":"看到【同一声源的声音进入不同介质比较波长/时间】","c":"想到【波源频率跨介质不变，波长用 $\\lambda$=v/f 分别计算；时间差 $\\Delta$t=s(1/v_{1}−1/v_{2})】；警惕【误认为频率随介质变化，或水中波长小于空气波长】","src":"物一轮262.波的描述_笔记","note":"视频|28:54","orig":"（例）频率 400Hz 的声波从空气（340m/s）入水（1450m/s）：频率不变；Δt=2000/340−2000/1450≈4.5s；λ空气=0.85m，λ水=3.625m","link":""},{"id":"phy1667","t":"机械波·波形图读图方法","s":"看到【从波形图读振幅、波长、位移或加速度方向】","c":"想到【四要素读图法：峰值读振幅、整波读波长、纵值读位移、加速度指向平衡位置且 a∝x】；警惕【纵轴厘米与横轴米单位混淆，波长漏数完整波形】","src":"物一轮263.波形图像_笔记","note":"视频|00:31","orig":"（知识）振幅=纵坐标最大值；波长=完整波形长度（相邻波峰间距或平衡位置间距）；位移看正负号；加速度与位移成正比、方向指向平衡位置","link":""},{"id":"phy1668","t":"机械波·波形图求周期与路程","s":"看到【给出质点第一次到达某状态的时间+周期限制条件】","c":"想到【先画出质点振动路径（平衡位置$\\to$波峰$\\to$波谷 对应 3T/4），用限制条件排除多解后求 T、v；n·T/4 时间路程=nA（从特殊点起算）】；警惕【漏掉 T 限制条件取错周期解】","src":"物一轮263.波形图像_笔记","note":"视频|16:11","orig":"（例）Q 点 2s 内第一次到波谷（平衡位置→波峰→波谷，历时 3T/4=2s）且 T>2s，得 T=8/3s、f=0.375Hz；λ=8m，v=3m/s；2s 内路程 3A=0.3m","link":""},{"id":"phy1669","t":"机械波·波源起振与振动延迟","s":"看到【波源只振动有限时间（非持续振动），问某质点某时刻状态或总路程】","c":"想到【先算波传到该质点的延迟时间，用总时间减延迟得有效振动时间，再化为周期数算路程；波源起振方向看波前】；警惕【未扣延迟时间直接按全部时长算路程】","src":"物一轮263.波形图像_笔记","note":"视频|21:55","orig":"（例）波源 0-2s 振动向双向传波：2.1s 时未振动区宽 0.25m 得 v=0.25/0.1=2.5m/s，λ=1m、T=0.4s；波源起振方向由波前判断；质点 b 振动延迟 t₁=0.75/2.5=0.3s，有效振动 1.7s=4.25 周期，路程 2.55m","link":""},{"id":"phy1670","t":"机械波·传播方向判断与 T/4 状态","s":"看到【已知某质点振动方向问波传播方向（或反向）】","c":"想到【同侧法/微平移法互推振动方向与传播方向；相差半周期的两质点运动状态总相反；T/4、3T/4 后质点位置按波形平移推】；警惕【在波峰/波谷处直接套同侧法】","src":"物一轮263.波形图像_笔记","note":"视频|34:15","orig":"（例）质点 b 向 y 轴负方向运动，由同侧法判波沿 x 轴负方向传播；a、c 相差半周期运动方向必相反；T/4 后质点 a 从波峰到平衡位置速度向下，3T/4 后 b 到波峰速率为零","link":""},{"id":"phy1671","t":"机械波·T/4 路程与振幅比较","s":"看到【比较某质点 T/4 内路程与振幅的大小】","c":"想到【看 T/4 过程中质点是靠近还是远离平衡位置：靠近则平均速度大、路程>A；远离则路程<A；从最大位移或平衡位置出发时恰等于 A】；警惕【不分情形一律写路程=A】","src":"物一轮263.波形图像_笔记","note":"视频|37:57","orig":"（例）λ=16m（4m 到 20m），v=2m/s 得 T=8s；波向右传 P 靠近平衡位置速度大、路程>0.1m；向左传 P 远离平衡位置速度小、路程<0.1m","link":""},{"id":"phy1672","t":"机械波·波源振动方程","s":"看到【由波形图和传播数据建某点（或波源）振动方程】","c":"想到【先算传播延迟确定该点何时起振，起振方向（初相位）由波前方向决定，再按 A、$\\omega$=2$\\pi$/T、$\\varphi$ 三要素写方程】；警惕【初相位不结合起振方向，直接代点取错解】","src":"物一轮263.波形图像_笔记","note":"视频|42:54","orig":"（例）v=2.5/0.5=5m/s，λ=2m、T=0.4s；质点 x=1m 处 0.2s 后开始振动；A=0.02m，ω=5π，波前向下振动取 φ=π，y=0.02sin(5πt+π)m","link":""},{"id":"phy1673","t":"机械波·波形图易错总结","s":"看到【波形图选择题中的概念判断项】","c":"想到【三条排错口诀：波速$\\neq$质点振动速度、质点不随波走、先看该点是否已振动再谈运动状态】；警惕【对未开始振动的质点分析其位移或速度】","src":"物一轮263.波形图像_笔记","note":"视频|50:04","orig":"（知识）易错：混淆波速 v 与质点振动速度；质点不随波迁移；判断质点运动前需先确认该点是否已开始振动","link":""},{"id":"phy1674","t":"机械波·振动方向判断两法","s":"看到【波形图上判断某质点向上还是向下振动】","c":"想到【微平移法（万能）或同侧法（快），沿坡判断方向；波峰波谷处两法失效需按周期性推导】；警惕【对波峰/波谷质点硬套同侧法】","src":"物一轮263.波形图像_笔记","note":"视频|50:04","orig":"（知识）微平移法：波形沿传播方向微移后看质点下一时刻位置；同侧法：传播方向与质点振动方向在波形同一侧（波峰/波谷除外）","link":""},{"id":"phy1675","t":"机械波·振动图像读法","s":"看到【y-t 图像判断其是振动图还是波形图】","c":"想到【横轴是时间即振动图，描述单个质点随时间振动；斜率正负定振动方向】；警惕【把振动图当成某一时刻的波形图来读波长】","src":"物一轮264.波振图像综合_笔记","note":"视频|00:27","orig":"（知识）振动图（y-t）：单个质点不同时刻的位移；横轴 t 纵轴 y；可读周期 T（完整振动时间）、振幅（纵坐标最大值）、振动方向（切线斜率正为向上、负为向下）","link":""},{"id":"phy1676","t":"机械波·波形图像读法","s":"看到【y-x 图像提取波长或判断传播方向】","c":"想到【横轴是位置即波形图，描述同一时刻各质点位移分布；读 $\\lambda$ 用同侧法/微平移法定向】；警惕【从振动图里找波长或从波形图里找周期】","src":"物一轮264.波振图像综合_笔记","note":"视频|01:11","orig":"（知识）波形图（y-x）：同一时刻多个质点的空间分布；横轴 x 为各质点平衡位置；可读波长 λ，传播方向与振动方向用同侧法/微平移法判断","link":""},{"id":"phy1677","t":"机械波·波速求解","s":"看到【波振图像综合题求波速】","c":"想到【两图各取一半：波形图读 $\\lambda$、振动图读 T，代入 v=$\\lambda$/T】；警惕【$\\lambda$ 与 T 来源弄反，或单位不统一】","src":"物一轮264.波振图像综合_笔记","note":"视频|04:14","orig":"（知识）v=λ/T：λ 从波形图取，T 从振动图取；原理是振动周期与传播周期相同","link":""},{"id":"phy1678","t":"机械波·传播方向判断（公共点法）","s":"看到【同时给振动图和波形图，问传播方向】","c":"想到【公共点搭桥：振动图给振动方向$\\to$波形图反推传播方向（知一求一）】；警惕【两图时刻不一致就硬套公共点，或找错对应质点】","src":"物一轮264.波振图像综合_笔记","note":"视频|05:20","orig":"（知识）找两图公共点（同一质点同一时刻）：由振动图读该点此刻振动方向，再在波形图中用同侧法/微平移法反推传播方向；必须先明确对应时刻和质点位置","link":""},{"id":"phy1679","t":"机械波·综合例题（振幅陷阱与路程）","s":"看到【给时间求质点总路程或问振幅大小】","c":"想到【振幅直接读纵坐标最大值（勿双倍）；总路程先化 t/T 为周期数，整数周期路程=n·4A，从特殊点起算的半周期为 2A】；警惕【振幅读成峰谷差、周期数换算出错】","src":"物一轮264.波振图像综合_笔记","note":"视频|09:27","orig":"（例）λ=4m、T=2s 得 v=2m/s；x=2m 处斜率负向下振动判波向左传；7s=3.5T 路程 14A=14×5cm=70cm；振幅 5cm 非 10cm","link":""},{"id":"phy1680","t":"机械波·综合例题（时刻对应与排除法）","s":"看到【波形图标注非零时刻，与振动图互相验证】","c":"想到【先确认波形图对应的时刻，用公共质点在该时刻的振动方向核对两图；排除法优先抓方向矛盾与速率零点】；警惕【默认波形图是 t=0 时刻】","src":"物一轮264.波振图像综合_笔记","note":"视频|13:53","orig":"（例）波形图对应 t=T/2 时刻：验证原点质点 T/2 时向下振动与振动图一致；0 时刻 P 在波谷（离平衡位置最远）Q 在平衡位置；排除 A（方向矛盾）、B（P 速率应为零）","link":""},{"id":"phy1681","t":"机械波·时间化周期数速解","s":"看到【求某质点经过一段时间后所处的位置/状态】","c":"想到【时间差化为周期数（含半周期取反、整周期不变），由初状态直接推末状态，可绕开传播方向】；警惕【忽略两时刻差要先减去波形图对应时刻】","src":"物一轮264.波振图像综合_笔记","note":"视频|18:42","orig":"（例）11s−1s=10s=2.5T；x=0 处质点 1s 时在波峰，2.5T 后应在波谷；无需确定传播方向直接得答案","link":""},{"id":"phy1682","t":"机械波·振动方程定位质点","s":"看到【给出振动方程，问波形图上哪个质点符合某时刻状态】","c":"想到【由方程算出该时刻质点位移与振动方向，再用同侧法在波形图上定位传播方向筛选选项】；警惕【余弦形式方程的相位对应关系代错时刻】","src":"物一轮264.波振图像综合_笔记","note":"视频|22:26","orig":"（例）振动方程 y=Acos(2πt/T)，t=3T/4 时质点在平衡位置向上振动；波向左传播，同侧法判定该位置质点为 D 选项正确；排除不在平衡位置的 A、B","link":""},{"id":"phy1683","t":"机械波·波的衍射","s":"看到【波遇到障碍物或窄缝，问能否绕过/衍射是否明显】","c":"想到【比较波长与障碍物/孔尺寸，λ$\\geq$尺寸时明显衍射；v=$\\lambda$f 中 v 由介质决定，降低频率 f 可增大波长$\\lambda$】；警惕【改变波源与障碍物的距离不影响波长，无法改变衍射明显程度】","src":"物一轮265.波的特性_笔记","note":"视频|00:21-02:55","orig":"（知识）波绕过障碍物继续传播的现象；明显衍射条件：波长λ≥障碍物或孔的尺寸，差距越大衍射越明显","link":""},{"id":"phy1684","t":"机械波·波的叠加","s":"看到【两列波相遇区域求合位移或画叠加后波形】","c":"想到【逐点矢量合成：平衡位置+波峰上移、波谷+波峰抵消】；警惕【叠加后两波仍独立传播、波形不变，不因相遇而改变各自特性】","src":"物一轮265.波的特性_笔记","note":"视频|04:15-09:33","orig":"（知识）两列波相遇时某点位移是两波位移的矢量和，逐点矢量合成可画叠加波形；相遇后两波保持原有频率、振幅独立传播互不影响","link":""},{"id":"phy1685","t":"机械波·干涉条件与强弱判定","s":"看到【两列波叠加判断某点加强还是减弱】","c":"想到【先验证相干条件（频率相同是前提），再用波程差判据：同向起振时半波长偶数倍加强、奇数倍减弱；加强点振幅为两振幅之和】；警惕【加强点是振幅增大仍在振动，并非静止不动；反向起振时结论整体反过来】","src":"物一轮265.波的特性_笔记","note":"视频|09:33-16:34","orig":"（知识）稳定干涉条件：频率相同、相位差恒定、振动方向相同；同向起振时波程差Δs=2n·λ/2 为加强点，Δs=(2n+1)λ/2 为减弱点，反向起振结论相反；加强点振幅A₁+A₂，减弱点|A₁−A₂|","link":""},{"id":"phy1686","t":"机械波·干涉图样分析","s":"看到【两波源连线的中垂线或波峰波谷相遇图，判断振动加强/减弱】","c":"想到【中垂线上任一点到两波源等距（$\\Delta$s=0），均为加强线；波峰对波谷处为减弱区】；警惕【加强点某一时刻可能正从平衡位置向波峰运动，不在极值处】","src":"物一轮265.波的特性_笔记","note":"视频|16:34-20:13","orig":"（知识）到两波源距离相等的点波程差为零，属加强线；波峰与波谷相遇线为减弱线；加强点振幅大但未必时刻处于波峰","link":""},{"id":"phy1687","t":"机械波·多普勒效应","s":"看到【火车鸣笛经过、波源与观察者相对运动，问接收频率/音调变化】","c":"想到【「近高远低」口诀：靠近时接收频率 f^{'} 高于发射频率 f，远离时低于 f】；警惕【频率变化与相对运动方向有关，与距离绝对值大小无关】","src":"物一轮265.波的特性_笔记","note":"视频|20:13-23:08","orig":"（知识）波源与观察者相对运动时接收频率变化：相互靠近频率变大、相互远离频率变小；本质是波前压缩或拉伸；应用如测速雷达、医疗彩超","link":""},{"id":"phy1688","t":"机械波·衍射例题","s":"看到【要求波绕过障碍物，问改变什么条件可实现明显衍射】","c":"想到【在波速不变（介质不变）前提下，降频增波长达标即可】；警惕【误以为增大波源振动频率或移动波源位置能增强衍射】","src":"物一轮265.波的特性_笔记","note":"视频|23:08-25:37","orig":"（例）水波要绕过桥墩到达叶片，v=λf 且 v 由介质决定，降低频率 f 增大波长λ，答案 B","link":""},{"id":"phy1689","t":"机械波·相干波源例题","s":"看到【相干波源叠加图中判断某点状态（加强/减弱/静止）】","c":"想到【加强=振幅相加仍在振动，减弱=振幅相减可能为零；波谷与波谷相遇也是加强且能量最大】；警惕【两波振幅相等时减弱点才完全不振动；中垂线全是加强点】","src":"物一轮265.波的特性_笔记","note":"视频|25:37-28:57","orig":"（例）两列相干波叠加，加强点振幅加倍但仍振动，波谷与波谷相遇点能量最大，波峰与波谷相遇为减弱区，答案 D","link":""},{"id":"phy1690","t":"机械波·多普勒效应例题","s":"看到【多个情景判断音调升高还是降低】","c":"想到【只看相对运动方向：靠近$\\to$频率升高，远离$\\to$频率降低】；警惕【波源转动、观察者移动要分解成沿连线方向的速度来判断靠近还是远离】","src":"物一轮265.波的特性_笔记","note":"视频|28:57-30:32","orig":"（例）四个情景中判断音调变化，唯一相互远离的情景音调变低，答案 B","link":""},{"id":"phy1691","t":"机械波·干涉判断例题","s":"看到【两列波叠加图形，问能否形成稳定干涉图样】","c":"想到【先验证相干条件：同一介质中 v 相同，比较波长是否相同定频率是否相同】；警惕【被叠加图形迷惑，跳过相干条件直接判断强弱分布】","src":"物一轮265.波的特性_笔记","note":"视频|30:32-32:45","orig":"（例）两列水波叠加区域图，波峰间距不同说明波长不同，v 相同则 f 不同，不能发生稳定干涉，答案 B","link":""},{"id":"phy1692","t":"机械波·声波干涉计算例题","s":"看到【声波干涉中拉长或缩短一侧路程后加强变减弱，求波长或振幅比】","c":"想到【首次加强转减弱对应波程差为半波长，注意拉长距离是双程、波程差要乘 2；强度比=振幅平方比，联立 (A_{1}+A_{2})^{2} 与 (A_{1}−A_{2})^{2} 解振幅】；警惕【忘记路程变化的双程效应；把强度当振幅直接相加】","src":"物一轮265.波的特性_笔记","note":"视频|32:45-38:29","orig":"（例）两路声波初始等长（加强），拉长后波程差 30cm 时首次减弱，得λ=60cm；由 (A₁+A₂)²=400、(A₁−A₂)²=100 解得 A₁:A₂=3:1，答案 C","link":""},{"id":"phy1693","t":"机械波·波的特性综合例题","s":"看到【一道题同时考波长计算、衍射条件、回声干涉与频率变化】","c":"想到【逐选项套四个知识点：$\\lambda$=v/f、明显衍射条件、多普勒规律、干涉需恒定相位差】；警惕【波长换算单位（m 与 mm）；回声频率可能变化故不能与原声稳定干涉】","src":"物一轮265.波的特性_笔记","note":"视频|38:29-43:02","orig":"（例）声呐 ultrasound λ=v/f=1500/(1.5×10⁶)=1mm≪1m 不满足明显衍射；介质改变导致波长变化；回声涉及多普勒与干涉条件，答案 B","link":""},{"id":"phy1694","t":"机械波·波形图转化为振动图像","s":"看到【给波形图，要求某质点的振动图像或振动方程】","c":"想到【先锁定目标质点在波形图中的初始位移和振动方向，再按简谐运动三要素（A、T、$\\varphi$）写方程，把空间问题化归为熟悉的振动问题】；警惕【漏看质点初始时刻的运动方向，导致初相位取错】","src":"物一轮266.根据波形图求某点的振动方程_笔记","note":"视频|00:40-01:27","orig":"（知识）核心方法：将波形图问题转化为振动图像处理——先确定研究质点位置，观察其位移随时间变化，绘制位移-时间曲线","link":""},{"id":"phy1695","t":"机械波·简谐运动方程书写步骤","s":"看到【要求写出 y=Asin($\\omega$t+$\\varphi$) 形式的振动方程】","c":"想到【三步定参：读图取 A，由完整振动时间定 T，代入 t=0 的位移并结合作动方向定 $\\varphi$，$\\varphi$>0 图像左移、$\\varphi$<0 右移（左加右减）】；警惕【初相位有两个解时需用振动方向取舍；$\\varphi$ 超过 $\\pi$/2 表示已过波峰或波谷】","src":"物一轮266.根据波形图求某点的振动方程_笔记","note":"视频|01:27-02:10","orig":"（知识）标准形式 y=Asin(ωt+φ)；振幅 A 取纵坐标最大值，角频率 ω=2π/T，初相位 φ 由 t=0 时刻位移和运动方向确定，取值范围 [−π,π]","link":""},{"id":"phy1696","t":"机械波·波形图综合例题","s":"看到【波形图+质点速度变化，求传播方向、波速和振动方程】","c":"想到【同侧法定传播方向；用质点到达波峰的时间反推周期（结合分数个周期）；代入 t=0 位移解 $\\varphi$ 并用振动方向取舍两解】；警惕【周期对应的是几分之几个周期要算准；0.3s 内路程不等于振幅整数倍时需逐段累加】","src":"物一轮266.根据波形图求某点的振动方程_笔记","note":"视频|02:10-26:49","orig":"（例）由 P 点速度增大（向平衡位置运动）用同侧法判波向右传；1.5λ=2.4m 得λ=1.6m；P 到波峰 0.3s 对应 3/8 周期得 T=0.8s，v=λ/T=2m/s；代入 t=0 位移 y=−8√2cm 得 φ=−π/4，ω=5π/2","link":""},{"id":"phy1697","t":"机械波·振动方程传递规律","s":"看到【已知某质点振动方程，求波线上另一质点的振动方程】","c":"想到【「后减前加」：沿传播方向前方质点相位加 x/v 项、后方质点减 x/v 项，本质是传播时间差 $\\Delta$t=x/v】；警惕【符号写反导致相位超前滞后颠倒；距离与波长要同单位换算】","src":"物一轮266.根据波形图求某点的振动方程_笔记","note":"视频|02:10-26:49","orig":"（知识）波从 A 传向 B 时 B 点方程 y=Asin(ωt−x/v+φ)，波从 B 传向 A 时为 y=Asin(ωt+x/v+φ)；减号表示振动延迟到达，加号表示超前；Δt=x/v 反映传播延迟","link":""},{"id":"phy1698","t":"机械波·由已知点方程推另一质点方程例题","s":"看到【给出某点位移值和振幅，反解初相位】","c":"想到【由 sin$\\varphi$=位移/振幅得两个候选相位，再按该质点振动方向（未过波峰或波谷取较小相位）取舍】；警惕【丢掉另一个相位解；忘记用振动方向筛选】","src":"物一轮266.根据波形图求某点的振动方程_笔记","note":"视频|26:49","orig":"（例）b 点位移 4cm（振幅 8cm）对应 sinφ=0.5，φ=π/6 或 5π/6，按未达波峰取 φ=π/6；p 点方程 yp=10sin(10πt−π/4)，pq 间距 10.5m、波长 12m、波速 60m/s","link":""},{"id":"phy1699","t":"机械波·位移与时间计算例题","s":"看到【给振动方程求某时刻位移、波峰到达时间或一段时间的路程】","c":"想到【相位先做模运算化简再求值；令 y=±A 解出波峰时刻通式；包含完整半周期的时间段路程为振幅整数倍，从平衡位置出发 3/4T 路程=3A】；警惕【相位超过 2$\\pi$ 不化简直接算错；通解时间漏加 nT】","src":"物一轮266.根据波形图求某点的振动方程_笔记","note":"视频|26:49","orig":"（例）由 yp=10sin(10πt−π/4) 求 t=0.25s 位移：y=10sin(2.5π−π/4)=5√2cm；令 y=A 解得波峰时刻 t=0.075+0.2n s；从 t=0.1s 到 0.25s 为 3/4 周期，q 从平衡位置出发路程 3A=30cm","link":""},{"id":"phy1700","t":"机械波·双图联用解题技巧","s":"看到【波形图与振动图像同时给出的综合题】","c":"想到【从两图各取所需：波形图读 $\\lambda$ 与空间位置，振动图读 T 与某点振动方向，联立求 v=$\\lambda$/T】；警惕【两图时间基准不同步时需先对齐同一时刻】","src":"物一轮266.根据波形图求某点的振动方程_笔记","note":"视频|26:49","orig":"（知识）波形图确定空间分布，振动图确定时间特性；优先通过已知点建立方程再按距离差调相位；超 2π 相位做模运算；同侧法「上坡下振，下坡上振」快速判传播方向","link":""},{"id":"phy1701","t":"机械波·多解性命题特征识别","s":"看到【实线虚线两个波形图对比，给时间间隔求波速】","c":"想到【识别为波的多解性问题，先分类传播方向再列通式，不能直接取最小值作答】；警惕【只按一种传播方向或只取 n=0 导致漏解】","src":"物一轮267.波的多解性问题_笔记","note":"视频|00:32-01:15","orig":"（知识）典型命题：给出实线（t₁=0）和虚线（t₂=0.1s）两个波形图，已知 Δt 与波长λ，求波速","link":""},{"id":"phy1702","t":"机械波·多解性来源","s":"看到【两波形重合，问传播距离或时间】","c":"想到【多解三来源：传播方向不确定、传播距离含 n$\\lambda$、时间含 nT；列通式后按题目约束定 n】；警惕【忽略波形在 x 轴两侧的无限延伸性，漏掉反向传播解】","src":"物一轮267.波的多解性问题_笔记","note":"视频|01:15-03:17","orig":"（知识）波形周期性导致多解：同一方向波峰可平移 λ/4、5λ/4、9λ/4 等多个位置重合；向右 x=2+8n，向左 x=6+8n（n=0,1,2…）","link":""},{"id":"phy1703","t":"机械波·距离解法","s":"看到【已知两时刻波形间波峰（或某相位点）的平移距离】","c":"想到【分方向列距离通式 $\\Delta$x=n$\\lambda$+$\\Delta$x_{0}，再代 v=$\\Delta$x/$\\Delta$t 得含 n 的通解，n=0 验证基础情况】；警惕【左右传播对应的基础位移不同（$\\lambda$/4 与 3$\\lambda$/4），不要混用】","src":"物一轮267.波的多解性问题_笔记","note":"视频|03:17-07:50","orig":"（例）波峰右移 2m（λ/4）：x=2+8n，v=(2+8n)/0.1=20+80n m/s；左移 6m（3λ/4）：x=6+8n，v=60+80n m/s","link":""},{"id":"phy1704","t":"机械波·周期解法","s":"看到【已知传播时间，求波速且题中有周期约束】","c":"想到【列时间通式 $\\Delta$t=($\\Delta$x_{0}/$\\lambda$+n)T，结合约束条件定 n，v=$\\lambda$/T 收尾】；警惕【时间不足一个周期时误以为只有一个方向的可能解】","src":"物一轮267.波的多解性问题_笔记","note":"视频|07:50-10:31","orig":"（知识）向右传播 Δt=(1/4+n)T，向左 Δt=(3/4+n)T，再由 v=λ/T 求波速；与距离法本质等价","link":""},{"id":"phy1705","t":"机械波·周期限定消多解例题","s":"看到【题目给出周期范围或「$\\Delta$t 小于周期」类限定条件】","c":"想到【用约束条件定 n 的取值（如 T>$\\Delta$t $\\Rightarrow$ n=0），把多解问题转化为有限解逐一代入验证选项】；警惕【两个方向各算一组解再对照选项，不要默认只考一个方向】","src":"物一轮267.波的多解性问题_笔记","note":"视频|10:31-17:17","orig":"（例）Δt=0.02s 且 T>0.02s，Δt 不足一周期：右传对应 1/4λ 得 T=0.08s、v=1m/s；左传对应 3/4λ 得 T=0.08/3s、v=3m/s，答案 B","link":""},{"id":"phy1706","t":"机械波·振动反相判断例题","s":"看到【两质点振动图像完全反相（步调相反）】","c":"想到【反相对应空间间距为半波长奇数倍：$\\Delta$x=(n+1/2)$\\lambda$，列通式求波长与波速；由振动图斜率定某时刻振动方向】；警惕【同相点对应整数倍波长，与反相判据混用】","src":"物一轮267.波的多解性问题_笔记","note":"视频|17:17-22:55","orig":"（例）P、Q 振动图像完全相反说明相位差为π，Δx=(1/2+n)λ=6m，λ=12/(2n+1)m，v=λ/T=3/(2n+1) m/s，答案 B、C","link":""},{"id":"phy1707","t":"机械波·质点位置多解例题","s":"看到【给某质点某时刻振动状态，求波速且选项带分数或多个可能值】","c":"想到【由振动方向+传播方向用同侧法定位质点相位，列 (n+1/2)$\\lambda$ 或 n$\\lambda$ 型空间关系通式，逐个 n 代入对照选项】；警惕【坐标位置未明确标注本身含多解性，容易漏 n 的取值】","src":"物一轮267.波的多解性问题_笔记","note":"视频|22:55","orig":"（例）波向左传、T=4s，t=2s 时 x=2m 处质点向下振动且处于平衡位置附近，(1/2+n)λ=2m，λ=4/(2n+1)m，v=1/(2n+1) m/s，n=2 时 v=1/5 m/s，答案 A","link":""},{"id":"phy1708","t":"热学·研究框架","s":"看到【热学题中区分宏观量与微观量】","c":"想到【宏观三参量（温度/压强/体积）对应实验定律体系，微观动力学参量对应分子动理论体系，两条线分别作答】；警惕【研究对象是大量分子的统计行为而非单个分子；气体分子是重点，固体液体非重点】","src":"物一轮268.【课前必看】本讲听课建议_笔记","note":"视频|00:06-03:39","orig":"（知识）热学双视角：宏观研究热力学系统（如封闭气体）的温度、压强、体积等状态参量，用气体实验定律与热力学定律；微观研究大量气体分子的速率、分子力、动能势能，用分子动理论","link":""},{"id":"phy1709","t":"热学·分子动理论知识结构","s":"看到【分子动理论概念题，问基本内容或内能、压强的微观本质】","c":"想到【按三大基础＋两大进阶框架检索：组成（分子模型与 NA）、运动（扩散与布朗运动）、作用力（引力斥力）；内能=分子动能+分子势能，压强源于分子碰撞】；警惕【分子动能与势能的影响因素不同：温度对应动能、间距对应势能】","src":"物一轮268.【课前必看】本讲听课建议_笔记","note":"视频|03:39-05:24","orig":"（知识）分子动理论三大基础：物体由大量分子组成、分子做永不停息的无规则运动、分子间存在作用力；进阶内容为分子动能与势能、内能本质、气体压强的微观解释","link":""},{"id":"phy1710","t":"热学·考情与备考策略","s":"看到【热学选择题概念辨析（分子运动、内能、压强微观解释）】","c":"想到【按送分题标准准备：概念性结论精确记忆，重点抓内能微观本质与压强微观形成机制两个关联考点】；警惕【统计规律与单个分子行为的表述差异是高频设错点】","src":"物一轮268.【课前必看】本讲听课建议_笔记","note":"视频|05:24","orig":"（知识）分子动理论基本内容为低频考点（如 23 北京/海南、25 浙江），选择题概念题属必拿送分题；内能与压强微观本质为中低频考点（如 24 浙江），考查概念理解","link":""},{"id":"phy1711","t":"分子动理论·分子的定义与尺度","s":"看到【题目出现原子或离子，问是否属于热学「分子」范畴】","c":"想到【热学统一称分子，忽略化学性质差异；记住直径数量级 10^{-10}m 用于估算与数量级判断】；警惕【物理与化学中「分子」定义的差异】","src":"物一轮269.物体是由大量分子组成的_笔记","note":"视频|00:54-01:58","orig":"（知识）热学中把化学的分子、原子、离子统称为分子；分子直径数量级 10⁻¹⁰m（约 0.1 纳米），r=d/2","link":""},{"id":"phy1712","t":"分子动理论·球体模型（固液）","s":"看到【估算固体或液体分子直径、分子体积】","c":"想到【球体模型：先求单个分子体积 V_{0}=M/($\\rho$Nₐ)，再由 d=三次根号(6V_{0}/$\\pi$) 求直径】；警惕【固体液体忽略间距误差小，此模型才可视为分子实际体积】","src":"物一轮269.物体是由大量分子组成的_笔记","note":"视频|02:15-03:34","orig":"（知识）固体液体分子用球体模型：假设分子紧密排列间距可忽略；单个分子体积 V=(4/3)πr³=(1/6)πd³，直径 d=三次根号(6V/π)","link":""},{"id":"phy1713","t":"分子动理论·立方体模型（气体）","s":"看到【估算气体分子间平均距离】","c":"想到【气体用立方体模型：单个分子占据空间 V_{0}=M/($\\rho$Nₐ)，间距 d=三次根号(V_{0})=三次根号(Vm/Nₐ)，算出的是间距而非直径】；警惕【把气体分子占据空间当成分子实际体积，导致重大计算错误】","src":"物一轮269.物体是由大量分子组成的_笔记","note":"视频|03:34-06:44","orig":"（知识）气体分子间距远大于自身尺寸（约 10 倍以上），用立方体模型：V₀ 为分子占据空间体积（含周围空隙），边长 a 即分子间距 d=a","link":""},{"id":"phy1714","t":"分子动理论·两种模型的本质区别","s":"看到【问固液模型与气体模型能否互换、差别在哪】","c":"想到【判据只有一条：是否计入分子间距；形状只是几何包装】；警惕【选择题用「形状不同」作区分项的设错方式】","src":"物一轮269.物体是由大量分子组成的_笔记","note":"视频|06:44-07:19","orig":"（知识）固液与气体模型差异不在几何形状（球体/立方体可互换），而在是否必须考虑分子间距；气体忽略间距会导致错误","link":""},{"id":"phy1715","t":"分子动理论·物质的量与阿伏伽德罗常数","s":"看到【求一定质量物质所含分子数】","c":"想到【桥梁公式 N=nNₐ=(m/M)Nₐ=(m总/M)Nₐ，宏观量（质量、体积、密度）与微观量（分子数、分子质量）全靠 Nₐ 换算】；警惕【物质的量$\\neq$分子数，必须经 Nₐ 换算；漏掉 Nₐ 无法求解微观量】","src":"物一轮269.物体是由大量分子组成的_笔记","note":"视频|07:50-11:11","orig":"（知识）物质的量 n 从分子数目角度描述物质多少，单位 mol；Nₐ≈6.02×10²³ mol⁻¹，分子总数 N=n×Nₐ","link":""},{"id":"phy1716","t":"分子动理论·摩尔质量与摩尔体积","s":"看到【在 M、$\\rho$、Nₐ、摩尔体积之间互相推导】","c":"想到【核心关系链：M=$\\rho$Vm、Vm=V_{0}Nₐ、m_{0}=M/Nₐ、V_{0}=M/($\\rho$Nₐ)，一条链走通所有估算题】；警惕【气体摩尔体积不反映分子实际大小】","src":"物一轮269.物体是由大量分子组成的_笔记","note":"视频|11:11-12:54","orig":"（知识）摩尔质量 M=m₀×Nₐ=m总/n；摩尔体积 Vm=M/ρ=V₀×Nₐ；气体摩尔体积含分子间距，固液摩尔体积近似等于分子实际体积总和","link":""},{"id":"phy1717","t":"分子动理论·气体分子间距估算例题","s":"看到【判断「还需哪些已知量才能估算气体分子间距/大小】","c":"想到【气体间距走 V_{0}=M/($\\rho$Nₐ)，逐项核对是否凑齐 M、$\\rho$、Nₐ 三要素】；警惕【混淆气体（需间距模型）与固体（可直接球体模型）所需条件】","src":"物一轮269.物体是由大量分子组成的_笔记","note":"视频|14:21-17:42","orig":"（例）求气体分子平均距离需 V₀=Vm/Nₐ=M/(ρNₐ)，须同时知道 Nₐ、M 和 ρ，答案 B；缺 Nₐ 的选项无法计算","link":""},{"id":"phy1718","t":"分子动理论·气凝胶分子数与直径例题","s":"看到【给密度与摩尔质量求固体分子直径或物质所含分子数】","c":"想到【固体分子体积可直接 V_{0}=M/($\\rho$Nₐ)，再套球体模型 d=三次根号(6V_{0}/$\\pi$)；分子数走 nNₐ】；警惕【把分子占据空间与分子实际体积混用；公式中立方根与 $\\pi$ 位置记错】","src":"物一轮269.物体是由大量分子组成的_笔记","note":"视频|17:42","orig":"（例）分子数 n=(a/M)×Nₐ 型计算；固体分子直径 d=三次根号(6M/(πρNₐ))，答案 D","link":""},{"id":"phy1719","t":"分子动理论·扩散现象","s":"看到【两种物质接触后彼此进入对方的现象】","c":"想到【认定为扩散现象，直接证明分子在做永不停息的无规则运动】；警惕【扩散是分子本身的迁移，与宏观的机械流动（如对流）区分】","src":"物一轮270.分子在做永不停息的无规则运动_笔记","note":"视频|00:24-01:01","orig":"（知识）扩散：不同种物质彼此进入对方的现象，如酱油分子进入蛋清、墨水扩散到水中","link":""},{"id":"phy1720","t":"分子动理论·扩散的影响因素","s":"看到【比较不同温度、物态或浓度下扩散快慢】","c":"想到【三要素排序：温度越高越快、浓度差越大越快、气＞液＞固；温度是分子热运动剧烈程度的标志】；警惕【误以为固体不发生扩散】","src":"物一轮270.分子在做永不停息的无规则运动_笔记","note":"视频|01:01-02:10","orig":"（知识）浓度差越大扩散越快；扩散速率气态＞液态＞固态（固态也扩散，如金块铅块紧贴数年相互渗透）；温度越高扩散越快","link":""},{"id":"phy1721","t":"分子动理论·布朗运动的定义与本质","s":"看到【悬浮颗粒无规则运动，问证明了什么】","c":"想到【布朗运动证明的是周围液体/气体分子的无规则运动，运动主体是颗粒而非分子】；警惕【高频设错点：说成「证明颗粒内部分子的运动」或「布朗运动就是分子运动」】","src":"物一轮270.分子在做永不停息的无规则运动_笔记","note":"视频|02:10-04:24","orig":"（知识）布朗运动：悬浮在液体/气体中的宏观颗粒（如墨汁中的小炭粒）的无规则运动，需显微镜观察；反映周围液体分子的无规则撞击","link":""},{"id":"phy1722","t":"分子动理论·布朗运动的特点","s":"看到【问布朗运动剧烈程度的影响因素或轨迹图含义】","c":"想到【两规律：温度越高越剧烈、颗粒越小越明显；轨迹连线不等于真实运动轨迹】；警惕【把连线当作颗粒真实轨迹；忽略颗粒越小越易受力不平衡的逻辑】","src":"物一轮270.分子在做永不停息的无规则运动_笔记","note":"视频|04:24-08:04","orig":"（知识）观测方法是间隔拍照记录位置连线（非真实轨迹）；温度越高、颗粒越小运动越剧烈；颗粒足够小时分子撞击的不平衡性显现","link":""},{"id":"phy1723","t":"分子动理论·布朗运动判断例题","s":"看到【选项围绕布朗运动的主体、温度与颗粒大小影响作判断】","c":"想到【抓住因果关系：液体分子撞击不平衡$\\to$颗粒运动，主体是宏观颗粒，证明对象是周围分子】；警惕【混淆「运动主体」与「证明对象」两层含义】","src":"物一轮270.分子在做永不停息的无规则运动_笔记","note":"视频|08:04","orig":"（例）判断布朗运动定义的正误选项，表述成证明颗粒自身分子运动的选项错误","link":""},{"id":"phy1724","t":"分子动理论·分子间存在间隙","s":"看到【水结冰爆管、酒精与水混合体积减小等宏观现象，要求微观解释】","c":"想到【分子大小不变，宏观体积变化只能由分子间距改变解释：混合体积减小=分子进入彼此间隙，结冰膨胀=间距增大】；警惕【用「分子变大」解释体积变化；忽略分子间隙是分子力存在的前提】","src":"物一轮271.分子间存在作用力完整视频_笔记","note":"视频|00:38-02:35","orig":"（例）水结冰体积膨胀致水管爆裂：分子间距增大而分子大小不变；50ml 酒精与 50ml 水混合后总体积小于 100ml，证明分子相互渗入间隙","link":""},{"id":"phy1725","t":"分子动理论·分子力的微观本质","s":"看到【问分子力的来源或「分子间只有引力/只有斥力】","c":"想到【分子力本质是电荷间库仑作用，引力和斥力同时存在、同时随 r 变化，表现出的只是合力】；警惕【「只有斥力」「只有引力」类表述均为错误选项】","src":"物一轮271.分子间存在作用力完整视频_笔记","note":"视频|02:35-03:21","orig":"（知识）分子力源于分子内部正负电荷间的库仑力，引力与斥力同时存在，合力为二者叠加","link":""},{"id":"phy1726","t":"分子动理论·分子力 F 与间距 r 的关系","s":"看到【比较不同分子间距下引力与斥力的大小或合力方向】","c":"想到【以 r_{0} 为分界：r<r_{0} 斥力主导（且斥力大于引力而非只有斥力），r=r_{0} 合力为零，r>r_{0} 引力主导】；警惕【r<r_{0} 误答「引力消失」；r 增大时误以为斥力先消失】","src":"物一轮271.分子间存在作用力完整视频_笔记","note":"视频|03:21-06:03","orig":"（知识）r 增大时引力、斥力同时减小；r=r₀ 时合力为零（平衡位置，F斥=F引）；r<r₀ 时合力表现为斥力，r>r₀ 时表现为引力；口诀「近推远拉」","link":""},{"id":"phy1727","t":"分子动理论·分子力作用距离例题","s":"看到【选项问某间距下「引力与斥力谁大」或「是否共存】","c":"想到【任何间距下引力和斥力都共存，比较大小即可：r<r_{0} 斥力大，r>r_{0} 引力大】；警惕【「小于 r_{0} 时只有斥力」这类混淆表现力与分力的表述】","src":"物一轮271.分子间存在作用力完整视频_笔记","note":"视频|06:03-07:40","orig":"（例）判断 r<r₀ 与 r=2r₀ 时引力斥力关系：r<r₀ 时斥力大于引力（共存），2r₀>r₀ 时引力大于斥力，答案 D","link":""},{"id":"phy1728","t":"分子动理论·分子力图像判断例题","s":"看到【F-r 图像中多条曲线与交点，判断哪条是合力、哪条是引力或斥力线】","c":"想到【横轴 r 纵轴 F，合力曲线过零点即 r_{0}；交点处 F=0 而非只有某一种力；r_{0} 数量级 10^{-10}m≈分子直径】；警惕【把交点误读为仅引力或仅斥力作用；混淆气体分子间距与 r_{0} 的数量级】","src":"物一轮271.分子间存在作用力完整视频_笔记","note":"视频|07:40","orig":"（例）F-r 图像中交点 e 对应平衡位置 r₀，左侧区域斥力主导；r₀≈10⁻¹⁰m 与分子直径同量级，答案 B（ab 为斥力线，cd 为引力线）","link":""},{"id":"phy1729","t":"内能·分子热运动的速率分布","s":"看到【温度升高，问每个分子速率是否都增大】","c":"想到【统计规律只适用大量分子：升温是高速分子比例增加，个别分子速率可能减小；速率分布曲线右移而非整体平移各点】；警惕【把统计规律外推到少量或单个分子；「每个分子」与「大量分子平均」表述差异】","src":"物一轮272.了解分子动能和分子势_笔记","note":"视频|01:30-07:52","orig":"（知识）单个分子运动状态随机且频繁改变；大量分子呈统计规律（各方向运动分子数几乎相等）；温度升高时高速率分子占比增多（分布曲线整体右移），并非所有分子速率都增大","link":""},{"id":"phy1730","t":"内能·温度与分子平均动能","s":"看到【比较温度不同的两物体，问分子平均动能关系】","c":"想到【温度相同$\\Rightarrow$分子平均动能相同，与物质种类、分子数无关；温度变化必然引起平均动能同向变化】；警惕【总动能还与分子数有关，不能唯一对应温度；混淆宏观物体速度与微观分子动能】","src":"物一轮272.了解分子动能和分子势_笔记","note":"视频|00:52-01:30","orig":"（知识）温度是分子平均动能的宏观表征，平均动能是温度的微观解释；T∝E̅k，二者严格一一对应；平均动能消除分子数量影响，只反映运动剧烈程度","link":""},{"id":"phy1731","t":"内能·三类分子动能指标","s":"看到【问哪个量能标志温度高低或反映热运动剧烈程度】","c":"想到【选「分子平均动能」：它既排除分子数影响，又排除个体随机性】；警惕【用单个分子动能或总动能判断温度高低】","src":"物一轮272.了解分子动能和分子势_笔记","note":"视频|07:52-10:44","orig":"（知识）总动能与分子数和热运动程度都相关；单个分子动能无法反映宏观热学性质；分子平均动能与温度严格一一对应，是描述热运动剧烈程度的最佳指标","link":""},{"id":"phy1732","t":"内能·分子力做功与分子势能","s":"看到【两分子间距变化，问分子势能增减】","c":"想到【用 W=−$\\Delta$Ep 判断：分子靠近时引力做正功势能减小，斥力区间继续靠近时分子力（斥力）做负功势能增大】；警惕【不分析力与位移方向夹角直接下结论；把分子力当成非保守力】","src":"物一轮272.了解分子动能和分子势_笔记","note":"视频|11:25-12:41","orig":"（知识）分子力本质是静电场力，属保守力，做功与路径无关；W=−ΔEp：分子力做正功势能减小，做负功势能增大","link":""},{"id":"phy1733","t":"内能·分子势能的分布与极值","s":"看到【问分子势能最小值位置或 r_{0} 处势能是否为零】","c":"想到【势能最小值在平衡位置 r_{0}（此时分子力为零），口诀「引力外，斥力内，平衡位置势能最低」；最小值可为负值，取决于零点选取】；警惕【把「势能最小」当成「势能为零」；混淆力平衡点与势能零点】","src":"物一轮272.了解分子动能和分子势_笔记","note":"视频|12:41-15:38","orig":"（知识）r>r₀ 区域引力做正功，势能随距离减小而减小；r<r₀ 区域斥力做负功，势能随距离减小而增大；r=r₀ 时势能最小（不是零）；势能零点可任选，常取无穷远处","link":""},{"id":"phy1734","t":"内能·分子动能判断例题","s":"看到【选项涉及「物体速度大分子动能大」或「每个分子动能都增大」类说法】","c":"想到【热运动与机械运动相互独立：物体宏观速度不影响分子平均动能；「每个分子」的绝对化表述必错】；警惕【宏观机械能与内能混为一谈】","src":"物一轮272.了解分子动能和分子势_笔记","note":"视频|15:38-17:50","orig":"（例）判断分子动能说法：混淆宏观速度与微观动能的选项错误；「温度升高每个分子动能都增大」忽视统计规律错误；温度与平均动能严格对应正确，答案 CD","link":""},{"id":"phy1735","t":"内能·分子力与动能转化例题","s":"看到【两分子从远处相互靠近，问速度、动能、势能的最值位置】","c":"想到【靠近到 r=r_{0} 前引力加速、动能增大，越过 r_{0} 后斥力减速，故 r_{0} 处动能最大、势能最小；结合势能曲线与动能转化分析】；警惕【认为越靠近分子力越大；忽略势能零点选取导致其为负值】","src":"物一轮272.了解分子动能和分子势_笔记","note":"视频|17:50-20:00","orig":"（例）分子从远处靠近，F-r 曲线上 r₀ 处（c 点）速度最大、动能最大；分子力绝对值先增后减；势能为负值非零，答案 B","link":""},{"id":"phy1736","t":"内能·分子力与势能综合判断例题","s":"看到【多个说法组合判断分子力方向与势能变化】","c":"想到【背牢 r_{0} 处双重特征：合力为零＋势能最小；r>r_{0} 引力、r<r_{0} 斥力，对应口诀逐项排查】；警惕【「r>r_{0} 表现为斥力」类方向性错误表述】","src":"物一轮272.了解分子动能和分子势_笔记","note":"视频|20:00","orig":"（例）判断分子力和势能说法：r>r₀ 表现为引力；靠近过程势能减小；r₀ 处势能最小，答案 C","link":""},{"id":"phy1737","t":"热学·内能的定义","s":"看到【问内能的本质或构成】","c":"想到【内能=所有分子热运动动能+分子势能的总和，是宏观量；动能与温度对应、势能与分子间距对应】；警惕【内能是宏观量，不存在「单个分子的内能」的概念】","src":"物一轮273.了解内能的本质与影响因素_笔记","note":"视频|00:03-00:35","orig":"（知识）内能=物体中所有分子热运动动能与分子势能的总和，即总分子的动能+总势能；是描述物体的宏观物理量，微观上包含与温度相关的分子热运动动能和与分子间距相关的分子势能","link":""},{"id":"phy1738","t":"热学·内能的决定因素","s":"看到【比较或判断两个物体内能大小】","c":"想到【从质量（分子数）、温度（平均动能）、体积（分子间距）三方面逐一比较】；警惕【物体的整体机械运动速度不影响内能；相同质量与温度、体积不同内能也可不同】","src":"物一轮273.了解内能的本质与影响因素_笔记","note":"视频|00:35-02:31","orig":"（知识）三个决定因素：分子数目（宏观对应质量）、分子平均动能（宏观对应温度）、分子间距（宏观对应体积）；物体整体机械运动速度不影响内能；内能是相对值（势能需选零势能面）","link":""},{"id":"phy1739","t":"热学·温度与内能的关系","s":"看到【温度升高，判断内能是否一定增大】","c":"想到【温度升高只保证平均动能增大，内能还要看分子势能变化，需结合热力学第一定律分析】；警惕【0℃的物体内能$\\neq$0（分子永不停息运动）；「每个分子动能都增大」是错误说法】","src":"物一轮273.了解内能的本质与影响因素_笔记","note":"视频|00:35-02:31","orig":"（知识）温度是分子平均动能的宏观表现；温度升高→平均动能必增大，但内能可能不变（势能减小可抵消动能增加）；0℃物体内能不为零","link":""},{"id":"phy1740","t":"热学·内能变化判断（例题）","s":"看到【选择题逐项判断「温度、平均动能、内能」说法正误】","c":"想到【三步拆解：温度$\\to$平均动能（统计意义）、内能$\\to$动能+势能（宏观量）、用热力学第一定律看$\\Delta$U=Q+W】；警惕【统计规律与个体行为混谈：温度升高时个别分子动能可能减小】","src":"物一轮273.了解内能的本质与影响因素_笔记","note":"视频|02:31-04:47","orig":"（例）判断物体内能说法：A温度升高→平均动能必增大但内能可能不变；B 0℃物体内能≠0；C温度升高指平均动能增大、个别分子动能可能减小；D无单个分子内能——答案A","link":""},{"id":"phy1741","t":"热学·相变中的内能变化（例题）","s":"看到【物态变化（水结冰、水汽化）过程中问内能/平均动能变化】","c":"想到【相变时温度不变$\\to$平均动能不变，内能变化全看分子势能；结合热力学第一定律：放热且不做功则内能减小】；警惕【吸热后内能不一定增大（可能对外做功），不能只看热交换】","src":"物一轮273.了解内能的本质与影响因素_笔记","note":"视频|04:47","orig":"（例）100℃水→水蒸气温度不变→平均动能不变；0℃水→冰放热且不做功→内能减小（平均动能不变、势能减小）；吸热同时可能对外做功——答案C","link":""},{"id":"phy1742","t":"热学·理想气体内能特性","s":"看到【题目说明气体可视为理想气体，判断其内能】","c":"想到【一定质量理想气体内能只由温度决定：温度升内能必增、温度降内能必减】；警惕【该结论只对理想气体成立，一般物体内能还与体积（势能）有关】","src":"物一轮273.了解内能的本质与影响因素_笔记","note":"视频|04:47","orig":"（知识）理想气体忽略分子势能，一定质量理想气体内能仅由温度决定；水→冰凝固放热内能减小","link":""},{"id":"phy1743","t":"热学·气体压强的微观成因","s":"看到【问气体压强是怎么产生的（微观解释）】","c":"想到【压强是大量分子频繁碰撞器壁的统计结果，本质是单位面积上的平均撞击力 p=F/S】；警惕【压强与分子间作用力（斥力）无关，气体分子间作用力可忽略】","src":"物一轮274.了解气体压强的微观解释_笔记","note":"视频|00:24-04:47","orig":"（知识）气体分子无规则热运动不断撞击器壁，宏观表现为压力，单位面积上的压力即压强；单分子完全弹性碰撞动量定理 F·Δt=2mv，Δt内有n个分子撞击面积S的器壁时 F·Δt=2nmv","link":""},{"id":"phy1744","t":"热学·压强的宏观影响因素","s":"看到【分析温度或体积变化如何影响气压】","c":"想到【两条链：温度$\\to$平均速率+碰撞频率；体积$\\to$数密度$\\to$碰撞次数；从「撞击力$\\times$频率」两角度分析压强变化】；警惕【单位体积分子数只由体积决定、与温度无关】","src":"物一轮274.了解气体压强的微观解释_笔记","note":"视频|00:24-04:47","orig":"（知识）体积增大→单位体积分子数减少→撞击次数n减小→压强降低；温度升高→分子平均速率v增大且单位时间撞击次数增加→压强增大","link":""},{"id":"phy1745","t":"热学·气体说法判断（例题）","s":"看到【判断密闭气体「分子速率、分子力、压强」说法正误】","c":"想到【逐项套用：温度$\\to$平均速率（统计）、理想气体分子力可忽略、压强$\\to$单位面积撞击力】；警惕【统计规律与个体行为混谈：温度升高$\\neq$每个分子速率都增大】","src":"物一轮274.了解气体压强的微观解释_笔记","note":"视频|04:47-06:13","orig":"（例）密闭容器氧气说法判断：体积增大降低分子密集程度（A错在表述对象）；温度升高仅使平均速率增大并非每个分子速率都增大；分子间作用力可忽略；压强本质是单位面积上分子作用力的宏观表现——答案D","link":""},{"id":"phy1746","t":"热学·温度降低压强减小分析（例题）","s":"看到【等容（体积不变）下温度降低，解释压强减小的原因】","c":"想到【体积不变$\\to$数密度不变；温度降低$\\to$平均速率减小+撞击频率降低，两者共同使压强减小，平均作用力可用 F=2nmv/$\\Delta$t 估算】；警惕【选项常设「数密度变化」的半对半错陷阱】","src":"物一轮274.了解气体压强的微观解释_笔记","note":"视频|06:13-08:36","orig":"（例）温度降低时：分子平均速率减小（A对）、平均动能减小（B对）、由 F=2nmv/Δt 平均作用力减小（C对）；D前半句错（单位体积分子数不变）后半句对（撞击次数减少）——答案D","link":""},{"id":"phy1747","t":"热学·微观与宏观的对应","s":"看到【要求区分宏观现象与微观解释】","c":"想到【建立对应：温度↔分子平均动能、体积↔分子平均间距（数密度）、压强↔分子撞击的统计效果】；警惕【一切「每个分子都…」的说法基本是错的，只有平均值/统计说法才可靠】","src":"物一轮274.了解气体压强的微观解释_笔记","note":"视频|08:36","orig":"（知识）压强本质是大量分子碰撞的统计结果；体积通过改变分子数密度影响压强，温度通过改变分子动能和碰撞频率影响压强；p=F/S与微观推导相联系","link":""},{"id":"phy1748","t":"热学·气体实验定律模块总览","s":"看到【从分子动理论进入气体实验定律模块】","c":"想到【研究对象切换为一定质量的宏观封闭气体，核心任务是在平衡态之间分析 p、V、T 三个状态参量的变化规律】；警惕【不再讨论单个分子，全部用宏观参量描述系统】","src":"物一轮275.【课前必看】本讲听课建议_笔记","note":"视频|00:13-00:35","orig":"（知识）研究对象从微观视角的气体分子（分子动理论）转向宏观封闭气体系统，研究气体状态变化过程中状态参量（温度、体积、压强）在平衡态之间的相互关系","link":""},{"id":"phy1749","t":"热学·实验定律知识框架","s":"看到【需要梳理气体实验定律的知识框架】","c":"想到【按「状态参量（含压强计算）$\\to$三种等值变化（等温/等压/等容）$\\to$三种图像相互转化」两条线搭建框架复习】；警惕【压强成因与计算是常考易错点，参量关系分析是解答题高频考点】","src":"物一轮275.【课前必看】本讲听课建议_笔记","note":"视频|00:35-02:23","orig":"（知识）两大模块：状态参量模块（温度、体积、压强及压强成因与计算）+实验定律模块（等温、等压、等容三种变化及 p-V、p-T、V-T 图像的相互转换与分析）","link":""},{"id":"phy1750","t":"热学·考情与备考策略","s":"看到【规划热学板块的备考】","c":"想到【热学属于必考且易得分板块，优先掌握压强计算与参量关系分析等基础方法即可稳定拿分】；警惕【不可因模块小而放弃，选择题与解答题两个题型都要练】","src":"物一轮275.【课前必看】本讲听课建议_笔记","note":"视频|02:23-03:31","orig":"（知识）新高考后热学出题频率显著提升（2024年重庆、海南、北京等多地考查选择题，贵州、浙江、广东等24个省级考区考解答题），难度低于动力学等模块","link":""},{"id":"phy1751","t":"热学·热力学系统与状态参量","s":"看到【封闭气体问题（活塞、气缸封气）】","c":"想到【研究对象是一定质量的气体这一热力学系统，用 p、V、T 三个状态参量描述其状态】；警惕【研究的是大量分子的集体行为，不是单个分子运动】","src":"物一轮276.气体的温度和体积完整视频_笔记","note":"视频|00:27-03:08","orig":"（知识）高中热力学系统一般为一定质量的理想气体（如内燃机活塞封闭的气体），关注大量粒子的集体行为；用压强p、温度T、体积V三个宏观量描述系统状态","link":""},{"id":"phy1752","t":"热学·平衡态与热平衡的区别","s":"看到【判断气体是否处于平衡态/热平衡，或两系统接触是否传热】","c":"想到【平衡态看三个参量全部稳定；热平衡只看温度相等，达到热平衡即停止热传递，温度计测温和被测物热平衡后读数】；警惕【平衡态$\\neq$热平衡，二者条件不同】","src":"物一轮276.气体的温度和体积完整视频_笔记","note":"视频|03:08-05:36","orig":"（知识）平衡态：系统状态参量p、V、T不随时间变化且空间分布均匀（微观上分子仍在运动但统计效果稳定）；热平衡：系统间或内部各部分温度均一，仅要求温度相等，不涉及压强和体积","link":""},{"id":"phy1753","t":"热学·温度的科学定义","s":"看到【问温度的微观意义或温度计的测量原理】","c":"想到【温度是分子平均动能的标志，由热平衡定义；「冷热程度」只是定性体感、存在误差】；警惕【温度相同只代表平均动能相同，不代表每个分子动能相同】","src":"物一轮276.气体的温度和体积完整视频_笔记","note":"视频|05:36-09:47","orig":"（知识）温度的微观本质是分子平均动能的宏观标志；科学定义基于热平衡原理：两系统停止传热时温度相同；温度计通过与被测物达热平衡显示对应温度","link":""},{"id":"phy1754","t":"热学·热力学温标与换算","s":"看到【摄氏温度与热力学温度互换、或比较温度变化量】","c":"想到【T=t+273.15（粗算+273）；温度变化量上 $\\Delta$T=$\\Delta$t，数值相等】；警惕【区分温度值与温度变化量：升高3℃是升高3K，不能说温度变为3K】","src":"物一轮276.气体的温度和体积完整视频_笔记","note":"视频|11:48-17:04","orig":"（知识）摄氏温标t：0℃冰水混合物、100℃沸水；热力学温标T：单位开尔文K，绝对零度-273.15℃（理论极限不可达）；换算 T=t+273.15，温差关系 ΔT=Δt（1K温差=1℃温差）","link":""},{"id":"phy1755","t":"热学·体积的微观意义","s":"看到【问气体体积由什么决定】","c":"想到【气体体积=容器容积，由分子平均间距的宏观体现；活塞移动改变容积即改变气体体积】；警惕【气体不像液体有固定表面，气体始终充满整个容器】","src":"物一轮276.气体的温度和体积完整视频_笔记","note":"视频|18:40-20:08","orig":"（知识）气体体积是分子平均间距的宏观表现；封闭系统中气体体积等于容器容积，气体自发填满可用空间，容器容积增大则气体体积直接增大","link":""},{"id":"phy1756","t":"热学·温度换算（例题）","s":"看到【判断哪个开尔文温度接近室温/常温】","c":"想到【室温约 27℃≈300K，快速换算 T=t+273 比较即可】；警惕【换算时加减273不要方向弄反，负摄氏度对应低于273K】","src":"物一轮276.气体的温度和体积完整视频_笔记","note":"视频|20:08-20:57","orig":"（例）应用 T=t+273 换算各选项后判断：300K 最接近室温，对应 27℃——答案B","link":""},{"id":"phy1757","t":"热学·温标概念辨析（例题）","s":"看到【选项同时出现温度值T与变化量$\\Delta$T/$\\Delta$t】","c":"想到【逐项核对：温差上 1K=1℃，温度值换算 T=t+273.15，绝对零度-273.15℃不可达】；警惕【最高频错误就是温度值与温度变化量混淆】","src":"物一轮276.气体的温度和体积完整视频_笔记","note":"视频|20:57","orig":"（例）温标辨析：Δ1K=Δ1℃正确；绝对零度对应关系正确；混淆温度值与温度变化量（应升高3K）、温差计算错误的选项不对——答案CD","link":""},{"id":"phy1758","t":"热学·气体压强的定义与特点","s":"看到【求封闭气体中不同位置的压强】","c":"想到【平衡态下封闭气体处处压强相等，可把气体内部与各接触面的压强直接画等号传递】；警惕【气体压强各方向都有，不要只考虑竖直方向】","src":"物一轮277.气体的压强_笔记","note":"视频|00:06-01:45","orig":"（知识）定义式 p=F/S，适用于固体、液体和气体，单位帕斯卡Pa；气体对容器壁各个方向均有压强；平衡态下气体各处压强相同（某点10000Pa则处处10000Pa）","link":""},{"id":"phy1759","t":"热学·大气压强的成因","s":"看到【区分封闭气体压强与大气压强的成因】","c":"想到【封闭气体压强←分子碰撞；大气压强←气体自重（按$\\rho$gh思路理解）】；警惕【两者成因不同，解释时不能混用】","src":"物一轮277.气体的压强_笔记","note":"视频|01:45-03:56","orig":"（知识）封闭容器中气体压强主要由分子碰撞产生；大气压强主要由气体自重导致，需考虑气体重力、可忽略分子碰撞；标准值 p0=1.013×10⁵Pa，考试常用 1×10⁵Pa","link":""},{"id":"phy1760","t":"热学·液体压强公式","s":"看到【求液体内部某深度的压强或液柱产生压强】","c":"想到【直接用 p=$\\rho$gh，h 是竖直深度，与容器形状无关】；警惕【h 取竖直高度而非液柱长度；同一液体向各个方向都有压强】","src":"物一轮277.气体的压强_笔记","note":"视频|04:51-06:01","orig":"（知识）平衡状态下 p=ρgh（ρ液体密度、h深度）；由液柱受力 F=G=ρShg 推导；与容器形状无关，倾斜容器等效后仍满足；液压大小仅取决于密度、g和深度","link":""},{"id":"phy1761","t":"热学·液体中两点压强差","s":"看到【同一连通液体中两点压强换算】","c":"想到【沿连通液体用 pB=pA+$\\rho$gh 逐点推算，h 取竖直高度差，倾斜管乘 sin$\\theta$】；警惕【两点间若有气体隔断（如U型管中部气柱），不能直接套 $\\rho$gh 高度差】","src":"物一轮277.气体的压强_笔记","note":"视频|09:08-11:27","orig":"（知识）适用条件：液体连通且不流动；两点压强差 Δp=ρgh（h为竖直高度差），B点更深时 pB=pA+ρgh；倾斜管用实际高度差 h·sinθ 计算","link":""},{"id":"phy1762","t":"热学·压强单位换算","s":"看到【题目压强用 cmHg/mmHg/atm 表示】","c":"想到【记住 76cmHg=1atm≈1.013$\\times$10^{5}Pa，同一方程内单位统一即可直接用 cmHg 参与加减】；警惕【cmHg 与 Pa 混用时必须先统一单位】","src":"物一轮277.气体的压强_笔记","note":"视频|11:27-14:53","orig":"（知识）托里拆利实验用液柱高度表示压强：cmHg、mmHg；换算 1atm=760mmHg=76cmHg=1.013×10⁵Pa；计算中可直接用液柱高度作单位运算","link":""},{"id":"phy1763","t":"热学·液柱封闭气体压强（例题）","s":"看到【U形管（或多段液柱）中间夹封闭气体，求各部分气体压强】","c":"想到【沿「开口端$\\to$连通液体$\\to$封闭气体$\\to$下段液体」逐段用液面高度差递推，气体段两侧压强画等号】；警惕【中间被气体隔断的两段液体不能跨过气体直接用高度差相减】","src":"物一轮277.气体的压强_笔记","note":"视频|14:53-20:53","orig":"（例）开口端液面 p0=76cmHg，由高度差 h1=14cm 得 pA=p0+14cmHg=90cmHg；气体A处处压强相等，经 h2=20cm 液柱得 pB=pA−20cmHg=70cmHg","link":""},{"id":"phy1764","t":"热学·活塞封闭气体——受力平衡法","s":"看到【活塞（气缸）封闭气体，求气体压强】","c":"想到【对活塞列受力平衡：气体压力 pS 与大气压力 p0S、重力等平衡，解出 p】；警惕【研究对象不唯一，优先选受力简单的对象列方程】","src":"物一轮277.气体的压强_笔记","note":"视频|21:10-24:37","orig":"（知识）核心方法：选活塞或气缸为研究对象，分析所有受力，建立平衡方程解出封闭气体压强p；研究对象选择不绝对，需选最简便的分析对象","link":""},{"id":"phy1765","t":"热学·水平与竖直活塞对比（例题）","s":"看到【活塞水平放置或竖直放置求封闭气体压强】","c":"想到【水平放置重力与气压方向垂直、可不计：p=p0；竖直放置必含重力项：p=p0±mg/S（看气体在活塞上方还是下方定加减）】；警惕【竖直布置漏掉 mg/S 是最常见的错】","src":"物一轮277.气体的压强_笔记","note":"视频|24:37-30:54","orig":"（例）水平活塞：p0S=pS，得 p=p0，无需考虑重力；竖直活塞（质量m）：pS=p0S+mg，得 p=p0+mg/S，必须考虑重力","link":""},{"id":"phy1766","t":"热学·复杂系统整体法与隔离法（例题）","s":"看到【多活塞/气缸+物块的组合系统求各处压强】","c":"想到【先整体后隔离：整体方程消去内力求一个压强，再对单个活塞列平衡求另一个；连通气体各处压强相等】；警惕【忽略活塞质量不同或截面积不同带来的影响，逐个活塞都要单独列平衡式】","src":"物一轮277.气体的压强_笔记","note":"视频|30:54","orig":"（例）气缸+物块系统：先取整体求 pA=p0−Mg/S，再隔离单个活塞求 pB=p0−Mg/S−mg/S；两活塞管道连通的系统中各处压强相等均为p，即使 S1≠S2 仍可得 p=p0","link":""},{"id":"phy1767","t":"热学·探究等温变化实验","s":"看到【气体等温变化（玻意耳定律）实验的操作/注意事项】","c":"想到【一切操作都为保两个不变：质量不变（气密性、润滑油防漏气）与温度不变（不触壁、缓慢移动充分热交换）】；警惕【快速推拉活塞会使气体温度变化，破坏等温条件】","src":"物一轮278.气体等温变化的规律完整视频_笔记","note":"视频|01:54-05:20","orig":"（知识）探究温度不变时封闭气体p与V的关系：压力表读p、刻度管测V；控制气体质量不变（封闭）且温度恒定；操作上禁止手触管壁、缓慢移动活塞使充分热交换、涂润滑油（减小摩擦生热+填补间隙防漏气）","link":""},{"id":"phy1768","t":"热学·数据处理——化曲为直","s":"看到【实验数据画出的曲线形状难以判断函数关系】","c":"想到【化曲为直：猜测反比关系就改画 p-1/V 图，过原点直线即验证；直线图像比曲线更有说服力】；警惕【不能仅凭 p-V 曲线「像双曲线」就下结论】","src":"物一轮278.气体等温变化的规律完整视频_笔记","note":"视频|05:20-09:37","orig":"（例）测得p-V数据后，p-V曲线形态不唯一（可能是反比例或对数函数）；改画 p-1/V 图像，若得过原点的直线则证明 pV=C 成立","link":""},{"id":"phy1769","t":"热学·玻意耳定律","s":"看到【一定质量气体等温变化，已知三个参量求第四个】","c":"想到【列 p1V1=p2V2，只抓初末两个平衡态，不管中间过程】；警惕【前提是质量不变+温度不变；等式两边单位必须统一，但不强制国际单位制】","src":"物一轮278.气体等温变化的规律完整视频_笔记","note":"视频|09:37-12:21","orig":"（知识）一定质量气体温度不变时，压强p与体积V成反比：pV=C 或 p1V1=p2V2；适用于两个平衡态之间的计算，中间过程无需考虑；比例式中只需等式两边单位一致，压强、体积单位均可任选","link":""},{"id":"phy1770","t":"热学·等温线图像分析","s":"看到【p-V图上多条双曲线比较温度高低】","c":"想到【离原点越远（位置越高）的等温线温度越高，可用 pV 乘积大小判断】；警惕【同一等温线上各点温度处处相同，不要把曲线当成温度渐变】","src":"物一轮278.气体等温变化的规律完整视频_笔记","note":"视频|12:21-14:04","orig":"（知识）p-V图中等温线为双曲线，同一曲线上各点温度相同；位置越高的等温线对应温度越高（T越高，pV乘积越大）","link":""},{"id":"phy1771","t":"热学·玻意耳定律的微观解释","s":"看到【要求从微观角度解释等温变化中压强变化】","c":"想到【等温$\\to$平均速率不变，压强变化全由数密度（碰撞频率）变化造成】；警惕【微观解释中不要引入「分子速率变化」，等温时它不变】","src":"物一轮278.气体等温变化的规律完整视频_笔记","note":"视频|14:04-15:25","orig":"（知识）温度不变→分子平均速率不变；体积增大→数密度减小→碰撞频率降低→压强减小；压强变化由分子碰撞频率决定","link":""},{"id":"phy1772","t":"热学·气泡上升问题（例题）","s":"看到【气泡/水下气团上升（或下沉），求体积变化】","c":"想到【缓慢上升+水温恒定$\\to$等温，用 p1V1=p2V2；水下压强=p0+$\\rho$gh，液面处=p0】；警惕【液体压强必须叠加大气压，不能只用 $\\rho$gh】","src":"物一轮278.气体等温变化的规律完整视频_笔记","note":"视频|15:25-20:39","orig":"（例）气泡从水下缓慢升至水面，水温恒定视为等温：初态 p1=p0+ρgh=1.5×10⁵Pa（含大气压与5m水柱压强），末态压强 p0；由 p1V0=p0V2 得 V2=1.5V0","link":""},{"id":"phy1773","t":"热学·变质量问题——充气/漏气","s":"看到【打气、放气、漏气等气体质量变化的问题】","c":"想到【把所有参与的气体（原有+充入/剩余）合并为一个研究对象，质量守恒下套「∑初态pV=末态pV」】；警惕【不能只对轮胎里原有气体用玻意耳定律，必须包含充入的气体】","src":"物一轮278.气体等温变化的规律完整视频_笔记","note":"视频|20:39-28:20","orig":"（例）轮胎充气：把轮胎内原有气体与所有充入气体视为整体，末态 2.5p0×1.2V0 = 初态总和 1.5p0V0+n×p0×0.005V0，解得 n=300次；通用推论：等温充/漏气问题中 末态pV=各初态pV之和","link":""},{"id":"phy1774","t":"热学·充气次数计算（例题）","s":"看到【求打气/抽气次数n（容积与温度均不变）】","c":"想到【统一套路：末态pV=初始pV+每打一次的pV$\\times$n，解出n；体积单位全程一致即可不必换算成m^{3}】；警惕【p、V单位两边一致即可，但同一方程内必须统一】","src":"物一轮278.气体等温变化的规律完整视频_笔记","note":"视频|28:20","orig":"（例）蹦蹦球容积2.5L恒定、温度300K恒定：末态 2.4atm×2.5L = 1atm×2.5L + n×1atm×0.1L，得 6=2.5+0.1n，n=35次","link":""},{"id":"phy1775","t":"热学·盖-吕萨克定律（等压变化）","s":"看到【封闭气体压强不变，温度变化求体积（或反之）】","c":"想到【用 V1/T1=V2/T2，T 必须换成开尔文】；警惕【代入摄氏温度直接比值是最常见错误，T=t+273 先换算】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|00:25-01:02","orig":"（知识）一定质量气体压强不变时，体积V与热力学温度T成正比：V/T=C 或 V1/T1=V2/T2；温度必须用开尔文温标；微观：温度升高分子速率增加，为保持压强不变必须增大体积降低数密度","link":""},{"id":"phy1776","t":"热学·查理定律（等容变化）","s":"看到【刚性容器（体积不变）中气体温度变化求压强】","c":"想到【用 p1/T1=p2/T2，T 用开尔文；可记速算式 $\\Delta$p/p1=$\\Delta$T/T1】；警惕【容器必须体积不变（如密封硬容器），有活塞时通常不是等容】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|00:25-01:02","orig":"（知识）一定质量气体体积不变时，压强p与热力学温度T成正比：p/T=C 或 p1/T1=p2/T2；微观：温度升高分子速率和碰撞次数增加，体积（数密度）不变时压强必然增大","link":""},{"id":"phy1777","t":"热学·等压线与等容线的图像","s":"看到【比较 V-T 或 p-T 图中不同直线的参量大小】","c":"想到【p-T图：斜率大$\\to$体积小；V-T图：斜率大$\\to$压强小；用等温/等压线辅助判断】；警惕【两图斜率含义相反，先认横轴是T再定结论】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|01:24-06:16","orig":"（知识）V-T图中等压线是过原点的正斜率直线（原点附近虚线）；p-T图中等容线同理；V-T图斜率越大表示压强越小，p-T图斜率越大表示体积越小","link":""},{"id":"phy1778","t":"热学·理想气体状态方程","s":"看到【气体两个状态间多个参量同时变化】","c":"想到【直接用 pV/T=C（或 p1V1/T1=p2V2/T2），一步覆盖等温、等压、等容各种情形】；警惕【三个等值定律只是特例，遇到非等值过程别硬套单一定律】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|07:12-08:33","orig":"（知识）pV=nRT（n为物质的量，R为普适气体常量），一定质量气体可写 pV/T=C；三个等值变化都是它的特例：T不变→pV=常数，p不变→V/T=常数，V不变→p/T=常数","link":""},{"id":"phy1779","t":"热学·理想气体模型","s":"看到【题目说明气体可视为理想气体】","c":"想到【可用全部气体实验定律；内能只由温度决定，判断内能变化只看温度】；警惕【高压、低温下气体偏离理想模型，不适用该结论】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|08:33-12:13","orig":"（知识）理想气体假设：忽略分子大小和分子间作用力、忽略碰撞动能损失、不计分子势能；一定质量理想气体内能仅与温度有关；常温常压下气体可视为理想气体","link":""},{"id":"phy1780","t":"热学·气体温度计刻度问题（例题）","s":"看到【用气体的热胀冷缩做温度计，判断刻度是否均匀及量程】","c":"想到【先确认等压（p=p0），由 V/T=C 推出 $\\Delta$V=C·$\\Delta$T：等分温度对应等分体积；均匀管则刻度均匀；量程由气柱最长/最短（油柱到两端）确定】；警惕【拉出吸管时T、p均不变则V不变，油柱位置不动，不要想当然认为距离增大】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|12:13-23:16","orig":"（例）油柱平衡使罐内气压恒为p0（等压过程），V=V罐+S·h；由 V1/T1=V2/T2 得 ΔV=C·ΔT，均匀吸管上相同ΔT对应相同长度变化，刻度均匀分布；最高温对应油柱到吸管顶端（T2≈304.5K→31.5℃），最低温对应油柱到罐口（≈22.5℃）","link":""},{"id":"phy1781","t":"热学·等容降温与释放气体（例题）","s":"看到【密封容器降温（体积不变）+放出部分气体求末压强】","c":"想到【降温阶段用查理定律 p1/T1=p2/T2；放气阶段选「留在容器内的那部分气体」为研究对象，等温用 pV 叠加（p2·V总=p3·V盒）】；警惕【研究对象要选剩余气体而非全部气体】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|23:16-29:47","orig":"（例）保鲜盒 V=6L、p1=1.0×10⁵Pa、27℃（300K）降温至 p2=9.2×10⁴Pa：由 p1/T1=p2/T2 得 T2=276K（3℃）；释放20%气体且温度不变：选留在盒内的80%气体，p1×0.8V=p3×V，p3=0.8p1=8×10⁴Pa","link":""},{"id":"phy1782","t":"热学·开瓶漏气求质量比（例题）","s":"看到【密封容器升温后开瓶漏气，求逸出气体质量（比例）】","c":"想到【先等容升温求 p2（查理），再等温放气：p2V0=p0(V0+V逸出)求「同压下的逸出体积」，压强相同时质量比=体积比】；警惕【比例题无需真实体积数值，用 V0 表达即可，最后比值化简】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|29:47-36:51","orig":"（例）坚果瓶装瓶时 T1=250K、p0，到海南 T2=300K 体积不变：p2=(300/250)p0=6p0/5；开瓶后气体逸出至内外均为p0：p2V0=p0V0+p0V逸出，V逸出=V0/5；压强相等时质量比=体积比，逸出与原有质量比1:6","link":""},{"id":"phy1783","t":"热学·拔火罐问题（例题）","s":"看到【拔火罐/吸盘类：容器冷却吸附，求压力或体积变化】","c":"想到【先判断过程类型：刚性罐冷却$\\to$等容用查理定律求低压强，再 F=(p0−p)S 压差$\\times$面积；带轻质活塞$\\to$等压用盖-吕萨克求体积比】；警惕【准确识别等容/等压/等温是解题关键；面积 S=$\\pi$d^{2}/4 勿用直径当半径】","src":"物一轮279.气体等压、等容变化的规律_笔记","note":"视频|36:51","orig":"（例）罐内气体 T1=360K 冷却到 T2=300K 体积不变：p=p0T2/T1=5p0/6，由 S=πd²/4（d=10cm）得 F=pS≈654N；改用轻质活塞则为等压变化（p=p0）：V2=(T2/T1)V=5V/6，体积比 k=(V−V2)/V2=0.2","link":""},{"id":"phy1784","t":"热学·等温线的图像形态与转化","s":"看到【pV图中的双曲线，要求转化到pT或VT图】","c":"想到【等温线在pV图是双曲线、在pT/VT图中都是竖直线，箭头按压强/体积变化方向画】；警惕【同一段过程在不同图中形态完全不同，先认横纵轴再画线】","src":"物一轮280.P、V、T图像的分析与转化_笔记","note":"视频|00:20-02:11","orig":"（知识）pV图中等温线为双曲线（pV=常数）；转化到pT图、VT图均为竖直线；等温降压过程在pT图箭头向下，等温膨胀在VT图箭头向上；等温膨胀对应压强减小，等温压缩对应压强增大","link":""},{"id":"phy1785","t":"热学·等容线的图像形态与转化","s":"看到【pT图中的过原点直线，要求转化到VT或pV图】","c":"想到【等容线在pT图是过原点直线、在VT图是水平线、在pV图是竖直线；比较体积用斜率：pT图斜率大$\\to$V小】；警惕【过原点直线必须标虚线延伸，斜率比较只在pT图中表示体积】","src":"物一轮280.P、V、T图像的分析与转化_笔记","note":"视频|02:11-03:13","orig":"（知识）pT图中等容线为过原点的直线（正比例函数）；转化到VT图为水平线（等容升温箭头向右），到pV图为竖直线（等容增压箭头向上）；pT图中斜率越大对应体积越小","link":""},{"id":"phy1786","t":"热学·等压线的图像形态与转化","s":"看到【VT图中的过原点直线，要求转化到pT或pV图】","c":"想到【等压线在VT图是过原点直线、在pT图和pV图中都是水平线】；警惕【pV图中的水平线表示压强不变，是等压过程而非等容】","src":"物一轮280.P、V、T图像的分析与转化_笔记","note":"视频|03:13-04:06","orig":"（知识）VT图中等压线为过原点的直线（V/T=常数）；转化到pT图为水平线（等压升温箭头向右），到pV图为水平线（等压膨胀箭头向右）","link":""},{"id":"phy1787","t":"热学·循环过程图像转化（例题）","s":"看到【一段 a$\\to$b$\\to$c$\\to$a 循环过程要求在另一坐标系中重画】","c":"想到【逐段判定过程类型（等温/等压/等容）$\\to$按每种过程在目标图中的标准形态逐段绘制$\\to$用关键点位置（如竖直线对应水平线）交叉验证】；警惕【分段处理，某一段画错整条循环就错；画完检查每段的箭头方向】","src":"物一轮280.P、V、T图像的分析与转化_笔记","note":"视频|04:06-09:07","orig":"（例）a→b等温升压（pV图双曲线）、b→c等压升温（水平线）、c→a等容降压（竖直线）；转画VT图：a→b等温压缩为竖直线向下、b→c等压膨胀为斜向上直线、c→a等容降温为水平线向左","link":""},{"id":"phy1788","t":"热学·图像转化排除法（例题）","s":"看到【选择题给出多幅图像判断哪个正确转化】","c":"想到【排除法优先：先抓最有把握的一段（如等压段对应水平线、等温段对应竖线/双曲线），逐一排除错误选项】；警惕【不必每段都精算，一段不符即可排除；注意箭头方向也要核对】","src":"物一轮280.P、V、T图像的分析与转化_笔记","note":"视频|09:07-10:41","orig":"（例）pT图转pV图：a→b段必为等压过程（排除p变化的选项）；b→c等温膨胀对应压强减小；c→d等容过程在pT图中应为过原点直线——仅C选项同时满足三段特征","link":""},{"id":"phy1789","t":"热学·利用变化趋势快速锁定答案（例题）","s":"看到【图像题中某段曲线形状复杂难画】","c":"想到【不用精确还原曲线：只看该段两端物理量的增减趋势（如等压升温必体积增大）即可排除选项锁定答案】；警惕【复杂曲线段往往只需判断趋势，别陷入逐点描画浪费时间】","src":"物一轮280.P、V、T图像的分析与转化_笔记","note":"视频|10:41","orig":"（例）第一阶段等压升温必伴随体积增大（排除体积减小的选项）；第二阶段压强降低趋势直接排除压强增加的选项——仅B选项满足；虽 b→c 段曲线形状复杂，但用压强变化趋势即可快速锁定","link":""},{"id":"phy1790","t":"热学·热力学第一定律","s":"看到【热学计算题结合气体状态变化问能量】","c":"想到【热力学第一定律$\\Delta$U=W+Q与气体实验定律结合是计算题常客，重点掌握其应用解题方法】；警惕【只背公式不练与实验定律的综合应用】","src":"物一轮281.【课前必看】本讲听课建议_笔记","note":"视频|01:26","orig":"（知识）热力学第一定律描述系统内能与做功、热传递的关系，中高频考点，计算题几乎必考，常与气体实验定律综合考查","link":""},{"id":"phy1791","t":"热学·热力学第二定律","s":"看到【热力学第二定律的选择题选项】","c":"想到【掌握两种表述与热现象方向性理解即可，出现则题目简单，属低成本必得分点】；警惕【概念表述不熟造成基础性失分】","src":"物一轮281.【课前必看】本讲听课建议_笔记","note":"视频|01:26","orig":"（知识）热力学第二定律为低频考点，侧重概念性考查，通常以小题或选项形式出现","link":""},{"id":"phy1792","t":"热学·命题特点","s":"看到【热学模块规划复习重点】","c":"想到【复习主线：热一重公式与应用，热二重表述理解，命题均围绕与气体实验定律的综合展开】；警惕【轻视热二导致意外丢分】","src":"物一轮281.【课前必看】本讲听课建议_笔记","note":"视频|01:26","orig":"（知识）热学题目多结合气体实验定律综合考查，热一定难度适中是重要得分点","link":""},{"id":"phy1793","t":"热学·改变内能的两种方式","s":"看到【判断内能改变途径或区分做功与热传递】","c":"想到【做功是机械能与内能的相互转化（外界对气体做功内能增、气体对外做功内能减），热传递是内能由高温物体向低温物体的转移，二者均可改变内能】；警惕【混淆能量的「转化」与「转移」】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|01:25-03:20","orig":"（知识）改变内能有做功与热传递两种方式；活塞压缩空气使硝化棉燃烧（做功），打气筒塞子顶开产生白雾（气体膨胀对外做功降温）","link":""},{"id":"phy1794","t":"热学·热传递","s":"看到【判断吸热/放热时物体内能变化】","c":"想到【吸热则内能增加、放热则内能减小，热传递由温度差驱动，不需要机械功参与】；警惕【误认为热量会自发从低温物体流向高温物体】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|03:20-04:28","orig":"（知识）热量自发地从高温物体向低温物体转移，吸热内能增加（烧水），放热内能减小（食物冷藏）","link":""},{"id":"phy1795","t":"热学·热力学第一定律","s":"看到【用$\\Delta$U=W+Q分析气体内能变化】","c":"想到【做功通过能量转化改变内能，热传递通过能量转移改变内能，内能不会凭空产生或消失】；警惕【W、Q都是过程量，必须针对具体过程】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|04:35-06:15","orig":"（知识）ΔU=W+Q，左边是内能总变化，右边是做功与热传递分别引起的内能变化之和；本质是能量守恒定律在热学范畴的体现","link":""},{"id":"phy1796","t":"热学·过程量与状态量","s":"看到【选项出现「某时刻物体具有多少热量/功」】","c":"想到【热量和功都是过程量，只能说「过程中传递了多少热量」「过程中做了多少功」，某时刻含多少热量的说法必错】；警惕【被生活语言「食物含多少热量」误导】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|06:46-08:15","orig":"（知识）W和Q是过程量，只对特定过程有意义，「某时刻物体热量为300焦」的表述必错","link":""},{"id":"phy1797","t":"热学·热一律正负号规则","s":"看到【判断$\\Delta$U=W+Q中各量的正负】","c":"想到【$\\Delta$U看温度变化、W看体积变化、Q看吸放热；计算顺序：先由温度定$\\Delta$U，再由体积定W，最后由公式反推Q】；警惕【「气体对外做功」对应W为负，勿与力学中功的正负混淆】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|08:49-12:48","orig":"（知识）ΔU：升温为正降温为负；W：压缩（外界对气体做功）为正、膨胀为负；Q：吸热为正、放热为负","link":""},{"id":"phy1798","t":"热学·特殊过程·自由膨胀","s":"看到【气体向真空自由膨胀】","c":"想到【无外力阻碍，气体不做功W=0；若同时绝热Q=0，则$\\Delta$U=0，温度不变】；警惕【体积增大$\\neq$对外做功，必须对外界有力作用才做功】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|12:48-14:52","orig":"（知识）气体向真空膨胀：外界无阻力，W=0（如隔板抽离后气体自由膨胀）","link":""},{"id":"phy1799","t":"热学·特殊过程·绝热","s":"看到【绝热容器/绝热过程】","c":"想到【无热交换Q=0，内能变化完全由做功决定：外界对气体做功则升温，气体对外做功则降温】；警惕【绝热$\\neq$温度不变，温度变化由$\\Delta$U=W判断】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|12:48-14:52","orig":"（知识）绝热容器无热交换，Q=0，ΔU=W","link":""},{"id":"phy1800","t":"热学·功的计算","s":"看到【求气体做功的数值或p-V图像面积】","c":"想到【等压过程用W=p$\\Delta$V；非等压过程用p-V图线下面积；体积增大W为负、减小W为正；循环过程净功=闭合曲线面积，顺时针系统对外做净功】；警惕【面积算大小、正负另判，别一步到位】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|15:52-26:28","orig":"（知识）等压过程W=pΔV（柱形与非柱形容器均适用，微元法证明）；p-V图线下面积为功；循环净功=闭合曲线面积","link":""},{"id":"phy1801","t":"热学·能量守恒的体现","s":"看到【选择题问某规律是否体现能量守恒】","c":"想到【楞次定律、闭合电路欧姆定律、热力学第一定律都是能量守恒在不同领域的具体体现；动量守恒与能量守恒无直接关系】；警惕【把动量守恒当成能量守恒的体现】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|26:28-29:56","orig":"（例）判断哪些定律体现能量守恒：楞次定律、闭合电路欧姆定律、热力学第一定律均体现，动量守恒不体现，选B","link":""},{"id":"phy1802","t":"热学·热一律与实验定律综合","s":"看到【等压过程判断体积、内能与吸放热】","c":"想到【由V∝T判断体积变化；理想气体内能只由温度决定；再由$\\Delta$U=W+Q结合W符号反推Q的正负】；警惕【忘记理想气体内能仅与温度有关】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|29:56-32:45","orig":"（例）等压过程温度降低，判断体积、内能与热量：体积减小、ΔU减小、放出热量","link":""},{"id":"phy1803","t":"热学·绝热气缸综合","s":"看到【绝热气缸内气体被压缩或膨胀】","c":"想到【Q=0时$\\Delta$U=W：压缩侧W>0内能增加，膨胀侧W<0内能减小，两气室分别独立分析】；警惕【把两气室当成整体分析】","src":"物一轮282.了解热力学第一定律的内容_笔记","note":"视频|32:45","orig":"（例）绝热气缸内两气室：甲被压缩ΔU>0，乙膨胀ΔU<0","link":""},{"id":"phy1804","t":"热学·热一律与气体实验定律结合","s":"看到【热学综合题需同时分析状态参量与能量】","c":"想到【用pV=nRT定状态、用$\\Delta$U=W+Q定能量，两式的桥梁是温度T（定$\\Delta$U）和体积V（定W）】；警惕【热量Q与压强p之间没有直接公式关联】","src":"物一轮283.应用热力学第一定律解决实际问题完整视频_笔记","note":"视频|00:22-00:27","orig":"（知识）ΔU=W+Q与pV=nRT通过温度T和体积V建立联系，热量Q与压强p无直接关联","link":""},{"id":"phy1805","t":"热学·理想气体内能","s":"看到【判断理想气体内能变化$\\Delta$U】","c":"想到【理想气体内能只看温度：T升高$\\Delta$U>0，T降低$\\Delta$U<0，双向可推】；警惕【该结论仅限理想气体，真实气体需考虑分子势能】","src":"物一轮283.应用热力学第一定律解决实际问题完整视频_笔记","note":"视频|00:27-01:18","orig":"（知识）一定质量理想气体分子势能忽略不计，内能仅由温度决定：温度升高ΔU>0，温度降低ΔU<0","link":""},{"id":"phy1806","t":"热学·体积变化与做功","s":"看到【由体积变化判断W或由W反推体积变化】","c":"想到【膨胀对外做功W<0、压缩W>0，体积变化与W符号一一对应】；警惕【向真空膨胀时W=0，不适用此对应关系】","src":"物一轮283.应用热力学第一定律解决实际问题完整视频_笔记","note":"视频|01:18-02:32","orig":"（知识）外界环境非真空时：体积膨胀气体对外做功W<0，体积压缩外界对气体做功W>0，一一对应可反推","link":""},{"id":"phy1807","t":"热学·多选项综合判断","s":"看到【多选项判断气体状态与能量变化的可能性】","c":"想到【逐项套「温度定$\\Delta$U、体积定W、$\\Delta$U=W+Q定Q」检验；PV乘积增大则理想气体T必升高，与$\\Delta$U<0矛盾；吸热的同时可以对外做功，只要|Q|>|W|】；警惕【凭单项直觉排除，忽略多个条件可同时成立】","src":"物一轮283.应用热力学第一定律解决实际问题完整视频_笔记","note":"视频|02:32-06:26","orig":"（例）一定质量理想气体过程多选项判断：A（升温+对外做功+吸热且|Q|>|W|）、D、E正确，B（PV增大但ΔU<0）矛盾","link":""},{"id":"phy1808","t":"热学·循环过程","s":"看到【p-V图循环过程求净功与吸放热】","c":"想到【循环回到初态$\\Delta$U=0，净功=闭合曲线面积，再由$\\Delta$U=W+Q得Q与净功等值反号；「气体对外做正功」对应热一律中W<0（系统能量减少）】；警惕【混淆力学中功的正负与热一律中W的符号】","src":"物一轮283.应用热力学第一定律解决实际问题完整视频_笔记","note":"视频|06:26-12:13","orig":"（例）理想气体循环过程：回到初态ΔU=0，净功用p-V图面积计算，Q>0吸热","link":""},{"id":"phy1809","t":"热学·循环分段判断","s":"看到【循环中含等温/绝热段的说法判断】","c":"想到【等温段$\\Delta$U=0是关键判断依据；绝热段$\\Delta$U=W；分段与全程分别列$\\Delta$U=W+Q，全程净功$\\neq$0则净热必$\\neq$0】；警惕【把分段结论直接当成全程结论】","src":"物一轮283.应用热力学第一定律解决实际问题完整视频_笔记","note":"视频|12:13-17:50","orig":"（例）等压膨胀→绝热→等温压缩的循环说法判断，选C","link":""},{"id":"phy1810","t":"热学·多过程计算","s":"看到【等容与等压两阶段分别吸热升温的比较计算】","c":"想到【等容W=0则$\\Delta$U=Q；等压W=p$\\Delta$V（膨胀为负）；相同$\\Delta$T则理想气体$\\Delta$U相同，可交叉验证各量】；警惕【等压过程体积比例漏乘初态体积】","src":"物一轮283.应用热力学第一定律解决实际问题完整视频_笔记","note":"视频|17:50-25:08","orig":"（例）等容吸热400J升温100K，等压吸热600J升温100K，求V0与等压做功，错误项为C","link":""},{"id":"phy1811","t":"热学·p-V图像计算","s":"看到【p-V图直线过程且已知$\\Delta$U与$\\Delta$T的比例关系】","c":"想到【功用图线下面积（梯形）计算；中间状态温度用pV/T=常量求解；两端温度相同则$\\Delta$U=0，由$\\Delta$U=W+Q得Q=-W】；警惕【直线过程$\\neq$等温过程，各点温度需用状态方程逐点求】","src":"物一轮283.应用热力学第一定律解决实际问题完整视频_笔记","note":"视频|25:08","orig":"（例）pV图像直线过程，最高温度Tmax=320K，ΔU=δΔT（δ=1000J/K），功用梯形面积求，TM=240K，Q=4×10⁵J","link":""},{"id":"phy1812","t":"热学·第一类永动机","s":"看到【判断机器是否为第一类永动机】","c":"想到【无外部能量输入却持续对外供能，违背能量守恒（热力学第一定律），不可能实现】；警惕【物体可以永远运动但不做功，持续做功必须消耗能量】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|00:39-02:05","orig":"（知识）第一类永动机：设想无需外部能源却持续向外供能的机器，所有实验均失败","link":""},{"id":"phy1813","t":"热学·第二类永动机","s":"看到【判断第二类永动机（如从海水吸热完全变功）】","c":"想到【它不违背能量守恒，但违背热力学第二定律：不可能把吸收的热量全部变为有用功而不产生其他影响】；警惕【误用第一定律去解释第二类永动机】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|02:05-04:27","orig":"（知识）第二类永动机：不违背能量守恒但无法实现，如利用海水内能或效率接近100%的理想热机","link":""},{"id":"phy1814","t":"热学·克劳修斯表述","s":"看到【冰箱/制冷把热量从低温搬到高温是否违背热二】","c":"想到【不违背：自发过程是高温$\\to$低温，冰箱靠外界做功实现非自发过程，必须付出能量代价】；警惕【忽略「自发」二字，误判为违反热力学第二定律】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|04:27-07:59","orig":"（知识）热量不能自发地从低温物体传到高温物体；冰箱制冷需压缩机做功，属非自发过程","link":""},{"id":"phy1815","t":"热学·开尔文表述","s":"看到【热机效率能否达到100%的判断】","c":"想到【由开尔文表述，从单一热库吸热不可能完全变功而不产生其他影响，热机效率必小于100%】；警惕【即使消除摩擦和漏气，体积变化等「其他影响」仍不可避免】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|07:59-12:24","orig":"（知识）不可能从单一热库吸收热量使之完全变成功而不产生其他影响；热机效率无法达100%","link":""},{"id":"phy1816","t":"热学·不可逆过程","s":"看到【判断某热现象能否自发逆转】","c":"想到【一切自发热现象均不可逆，逆过程需外界干预；克劳修斯与开尔文两种表述本质相同，都揭示热过程的方向性】；警惕【两种表述只是切入角度不同，不要当成两条独立定律】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|12:24-14:32","orig":"（知识）一切自发的热现象均不可逆：墨水扩散不自发聚集、摩擦生热的内能不自发变机械能、气体膨胀不自发恢复","link":""},{"id":"phy1817","t":"热学·熵的微观解释","s":"看到【用微观状态数解释气体自由膨胀不可逆】","c":"想到【分子全回原处的概率为1/$2^n$，宏观下概率实际为零；系统自发从有序（低概率）状态向无序（高概率）状态过渡】；警惕【不是「绝对不可能」，而是概率极小】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|14:34-16:43","orig":"（知识）n个分子全回原区域概率为1/2ⁿ，n→∞时P→0；宏观分子数极大，自发恢复初态概率实际为零","link":""},{"id":"phy1818","t":"热学·熵增原理","s":"看到【熵及熵增原理的概念判断】","c":"想到【熵越大越无序，孤立系统自发熵增，这是热现象不可逆的宏观表现；局部熵减需外界输入能量，更大系统总熵仍增】；警惕【把「局部熵减」当成违背熵增原理】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|17:56-19:56","orig":"（知识）熵表征系统无序程度；孤立系统总是自发向熵增方向演化；局部熵减（如打扫房间）需外界能量输入","link":""},{"id":"phy1819","t":"热学·热二定律应用","s":"看到【热力学第二定律正误判断类选择题】","c":"想到【先区分自发与非自发过程：非自发过程在有外界做功的条件下可以发生，不违背热二】；警惕【表述本身正确但与题意无关的干扰选项】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|19:56-21:02","orig":"（例）电冰箱传热说明题：通过压缩机做功实现热量从低温到高温，不违背热二，选B","link":""},{"id":"phy1820","t":"热学·热二定律应用","s":"看到【永动机与热一律、热二定律的对应关系判断】","c":"想到【第一类违背热一（能量守恒），第二类违背热二；表述中「不产生其他影响」条件缺失时，从单一热源吸热全部变功是有可能的】；警惕【漏看「不产生其他影响」这一限定条件】","src":"物一轮284.对热力学第二定律的理解_笔记","note":"视频|21:02","orig":"（例）两类永动机与热二定律综合判断，选D：允许产生其他影响时吸热全变功可能实现","link":""},{"id":"phy1821","t":"热学·气缸模型总览","s":"看到【气缸类计算题定位模型】","c":"想到【先辨模型：活塞模型以受力平衡+等压/等温变化判断为主，液柱模型以压强递推+假设法为主，两类解法路径不同】；警惕【两类模型解法混用】","src":"物一轮285.【课前必看】本讲听课建议_笔记","note":"视频|00:22-02:36","orig":"（知识）气缸类计算题分活塞模型与液柱模型两大类，活塞模型考频占绝对优势","link":""},{"id":"phy1822","t":"热学·气缸类考情","s":"看到【气缸活塞类计算题】","c":"想到【核心套路是「活塞受力平衡求压强 + 气体实验定律求状态变化」，是高考高频得分点，时间紧张优先掌握活塞模型】；警惕【受力分析与热学方程脱节、各算各的】","src":"物一轮285.【课前必看】本讲听课建议_笔记","note":"视频|02:36","orig":"（知识）活塞/液柱模型约80%以计算题形式考查，难度中等偏上，核心考点是气缸活塞受力平衡与气体实验定律综合","link":""},{"id":"phy1823","t":"热学·气缸类考查形式","s":"看到【液柱移动方向判断或变质量气体问题】","c":"想到【均属力学热学综合题：移动方向需比较两侧压强差，变质量问题要跟踪气体总量变化，重点训练模型构建与多过程分析】；警惕【只看温度变化不看压强差就下结论】","src":"物一轮285.【课前必看】本讲听课建议_笔记","note":"视频|02:36","orig":"（知识）典型考查形式：压强计算与状态变化分析、力学热学综合（液柱移动方向判断）、变质量系统分析","link":""},{"id":"phy1824","t":"热学·活塞模型·等温判定","s":"看到【判断封闭气体是否等温变化】","c":"想到【三条件齐备（环境温度恒定+导热良好+缓慢移动）才可判定等温，此时pV=常量；导热良好保证热交换，缓慢移动保证热平衡有时间建立】；警惕【缺「缓慢移动」就不能直接套等温结论】","src":"物一轮286.解读活塞问题中的常见条件_笔记","note":"视频|00:31-01:28","orig":"（知识）等温判定三条件：室温恒定、气缸导热性良好、活塞缓慢移动","link":""},{"id":"phy1825","t":"热学·活塞模型·等温应用","s":"看到【导热气缸位置改变（水平转竖直等）且活塞缓慢移动】","c":"想到【温度不变按等温处理，用p1V1=p2V2；先由活塞受力定新压强（竖直后气体压强增大），再定体积减小】；警惕【跳过受力分析直接猜压强变化】","src":"物一轮286.解读活塞问题中的常见条件_笔记","note":"视频|01:28-01:59","orig":"（例）导热气缸由水平转竖直，活塞缓慢移动，气体体积减小温度不变","link":""},{"id":"phy1826","t":"热学·活塞模型·等压判定","s":"看到【判断封闭气体是否等压变化】","c":"想到【活塞受力平衡且外界大气压不变时，p内=p0+Mg/S恒定，内外压强差恒定即等压过程】；警惕【外界条件变化（加沙、下压）会破坏等压前提】","src":"物一轮286.解读活塞问题中的常见条件_笔记","note":"视频|01:59-03:32","orig":"（知识）活塞平衡pS=p0S+Mg，得p=p0+Mg/S；外侧压强（大气压）不变则内部压强恒定","link":""},{"id":"phy1827","t":"热学·活塞模型·等压应用","s":"看到【加热气体、活塞缓慢移动到新位置】","c":"想到【全程保持力平衡即等压过程，用盖-吕萨克定律V/T=常量；缓慢移动保证动态平衡始终成立】；警惕【误当成等温或等容过程处理】","src":"物一轮286.解读活塞问题中的常见条件_笔记","note":"视频|03:32-04:55","orig":"（例）加热气体使活塞从A缓慢移至B，全程满足力平衡方程","link":""},{"id":"phy1828","t":"热学·常见条件识别","s":"看到【题目给出绝热/等容/向真空扩散等条件】","c":"想到【绝热$\\to$Q=0；等容、自由膨胀$\\to$W=0；代入$\\Delta$U=W+Q即可快速锁定内能变化】；警惕【混淆「绝热Q=0」与「等容W=0」两类条件】","src":"物一轮286.解读活塞问题中的常见条件_笔记","note":"视频|04:55-05:35","orig":"（知识）绝热条件Q=0；零功条件包括等容过程和自由膨胀（向真空扩散）两种；气体可先后经历不同过程","link":""},{"id":"phy1829","t":"热学·多过程组合","s":"看到【活塞移动中途被卡环/挡板限制】","c":"想到【分阶段处理：活塞自由移动阶段为等压，被固定后转为等容；转折点是力学条件（是否受限）变化处】；警惕【全程只用一个过程定律硬套】","src":"物一轮286.解读活塞问题中的常见条件_笔记","note":"视频|05:35","orig":"（例）缓慢升温：活塞移动阶段为等压过程，被卡槽固定后转为等容过程","link":""},{"id":"phy1830","t":"热学·活塞模型·压强计算","s":"看到【活塞静止或缓慢移动求封闭气体压强】","c":"想到【对活塞列受力平衡：p内S=p0S+mg（有外力再加上外力项），气柱体积用V=S·h表示便于用长度比值计算】；警惕【漏掉活塞重力或额外外力】","src":"物一轮287.例题讲解与练习_笔记","note":"视频|00:03-12:22","orig":"（知识）活塞初始静止：p1S=p0S+mg，得p1=p0+mg/S；体积V1=Sh0用气柱高度表示","link":""},{"id":"phy1831","t":"热学·活塞模型·力热综合","s":"看到【活塞加速运动且需求外力F等力学量】","c":"想到【双路径：力学路径（牛顿第二定律）与热学路径（气体状态方程）；力学未知量多时先用热学求压强，再返回力学方程整体法+隔离法联立消元】；警惕【整体法漏掉气缸质量、体积变化量$\\Delta$h与高度h混淆】","src":"物一轮287.例题讲解与练习_笔记","note":"视频|00:03-12:22","orig":"（例）活塞加速上升1/5·h0，先由等温p1V1=p2V2求p2=5/6·(p0+mg/S)，再联立活塞与整体方程解出F","link":""},{"id":"phy1832","t":"热学·连通汽缸·等温计算","s":"看到【连通双汽缸系统求末态压强】","c":"想到【连通系统末态各处压强相等；两部分气体合并用p1V1=p2V2，总体积=左右两侧体积之和，用高度变化逐侧更新体积】；警惕【体积只算一侧、活塞位移与初态高度对应错误】","src":"物一轮287.例题讲解与练习_笔记","note":"视频|12:22-21:32","orig":"（例）左右汽缸面积S与2S经细管连通，等温压缩后p2=18/17·p0","link":""},{"id":"phy1833","t":"热学·连通汽缸·弹簧与平衡","s":"看到【汽缸问题中求弹簧劲度系数或所加物体质量】","c":"想到【弹簧弹力由压强差提供：F=kx=$\\Delta$p·S；活塞平衡：mg=$\\Delta$p·S；x由活塞位移（形变量）确定】；警惕【各活塞面积不同（S与2S）代错、弹簧拉伸压缩方向判断错误】","src":"物一轮287.例题讲解与练习_笔记","note":"视频|12:22-21:32","orig":"（例）由kx=Δp·S求k=2p0S/17H，由mg=Δp·S'求沙子质量m=2p0S/17g","link":""},{"id":"phy1834","t":"热学·VT图像·热量计算","s":"看到【VT图像分段过程求热量】","c":"想到【先由活塞平衡定初压强，再用p1V1/TA=p3V3/TC求末态压强；W=-p$\\Delta$V只算等压段，等容段W=0；最后Q=$\\Delta$U-W】；警惕【面积单位cm^{2}$\\to$m^{2}漏换算、功的正负号漏处理】","src":"物一轮287.例题讲解与练习_笔记","note":"视频|21:32-30:16","orig":"（例）等压膨胀A→B+等容升温B→C，p1=p0+mg/S=1.32×10⁵Pa，p3=1.76×10⁵Pa，Q=98.4J","link":""},{"id":"phy1835","t":"热学·真空膨胀与等压综合","s":"看到【气体先向真空扩散再等压升温，求W和Q】","c":"想到【向真空膨胀W=0，若绝热则Q=0、$\\Delta$U=0、温度不变；等压段W=-p$\\Delta$V，全程用$\\Delta$U=W+Q分阶段求热量】；警惕【给向真空膨胀的过程误算功】","src":"物一轮287.例题讲解与练习_笔记","note":"视频|30:16","orig":"（例）气体向真空扩散（W=0、Q=0、ΔU=0、温度不变），再等压升温：W=-25.5J，Q=89.3J","link":""},{"id":"phy1836","t":"热学·等压条件识别","s":"看到【恒力压活塞且缓慢移动】","c":"想到【恒力+缓慢移动=准静态等压过程，p内=p0+F/S，用W=p$\\Delta$V算功】；警惕【恒力方向与大气压力方向叠加弄错】","src":"物一轮287.例题讲解与练习_笔记","note":"视频|30:16","orig":"（知识）恒力F作用且活塞缓慢移动：F+p0S=p内S，压强恒定","link":""},{"id":"phy1837","t":"热学·能量交换判定","s":"看到【绝热容器内用电热丝加热气体】","c":"想到【绝热外壳只隔绝与外界的热交换，电阻丝放热是系统内部电能转化为内能，Q按焦耳热计入$\\Delta$U=W+Q】；警惕【误认为绝热容器内Q必为0而漏算电热】","src":"物一轮287.例题讲解与练习_笔记","note":"视频|30:16","orig":"（知识）电阻丝放热属于系统内部能量交换，不受绝热容器限制","link":""},{"id":"phy1838","t":"热学·液柱模型总览","s":"看到【液柱封闭气体求参量与能量变化】","c":"想到【解题流程：液柱受力（压强递推）定p $\\to$ 气体实验定律定V、T $\\to$ 热一律$\\Delta$U=W+Q定$\\Delta$U、Q】；警惕【cmHg与Pa单位混用】","src":"物一轮288.求解液柱问题中的参量与能量变化_笔记","note":"视频|00:04-01:08","orig":"（知识）液柱模型结合气体实验定律和热力学定律，求压强p、体积V、温度T及ΔU、Q等参量","link":""},{"id":"phy1839","t":"热学·液柱·热一律应用","s":"看到【玻璃管缓慢旋转（导热良好）问吸放热】","c":"想到【缓慢旋转+导热良好=等温$\\Delta$U=0；先由受力比较末初压强判断压缩还是膨胀：被压缩W>0，则Q=$\\Delta$U-W<0放热】；警惕【不看压强变化直接判断吸放热方向】","src":"物一轮288.求解液柱问题中的参量与能量变化_笔记","note":"视频|01:14-04:10","orig":"（例）2022海南卷：19cm水银柱封闭25cm空气柱，缓慢旋转后气体被压缩，Q<0放热","link":""},{"id":"phy1840","t":"热学·液柱·等温计算","s":"看到【液柱封闭气体等温变化求气柱长度】","c":"想到【p1V1=p2V2中V用l·S表示，S可约去，直接用cmHg与cm计算；竖直段液柱压强p=p0±液柱高（上端开口取加、下端取减）】；警惕【水平段液柱不产生压强差，误计入】","src":"物一轮288.求解液柱问题中的参量与能量变化_笔记","note":"视频|04:10-05:35","orig":"（例）76×25=95×l2，解得l2=20cm；末态压强p2=76+19=95cmHg","link":""},{"id":"phy1841","t":"热学·液柱·等压过程","s":"看到【液柱总量与长度不变时升温或降温】","c":"想到【液柱长不变$\\to$内外压强差恒定$\\to$等压过程，用盖-吕萨克定律V/T=常量】；警惕【与等温过程pV=常量混淆】","src":"物一轮288.求解液柱问题中的参量与能量变化_笔记","note":"视频|05:35-07:20","orig":"（例）液柱长度不变，由20/300=l3/360得l3=24cm","link":""},{"id":"phy1842","t":"热学·液柱·压强递推","s":"看到【多段液柱串联封闭多段气体】","c":"想到【沿液柱逐段递推压强：下段气体压强=上段压强±该段液柱高度（视重力方向定）；体积用长度$\\times$S代替】；警惕【需结合管的几何方位判断哪些液柱段计入压强差】","src":"物一轮288.求解液柱问题中的参量与能量变化_笔记","note":"视频|07:35-09:51","orig":"（例）Z形管两段水银柱：p1=p0+15=90cmHg，p2=p1+30=120cmHg，体积用长度代替","link":""},{"id":"phy1843","t":"热学·液柱·假设法","s":"看到【液柱最终位置不明确的问题】","c":"想到【假设法：设液柱移动h $\\to$ 建立末态压强关系+玻意耳定律方程 $\\to$ 解出后代回检验；结果为负值或超出管长等物理限制则否定假设重新设置】；警惕【多解时不检验物理合理性直接作答】","src":"物一轮288.求解液柱问题中的参量与能量变化_笔记","note":"视频|09:51-24:14","orig":"（例）设液柱B下移h，列(15+h)(75-h)=120×15，解得h=15或45，取15cm（45超出管长）","link":""},{"id":"phy1844","t":"热学·液柱·移动距离","s":"看到【求液柱（或活塞）实际移动距离】","c":"想到【先解各段气体末态长度，再用几何关系扣除液柱自身长度/重叠部分，气柱长度变化$\\neq$液柱位移】；警惕【把气柱长度的变化量直接当成液柱移动距离】","src":"物一轮288.求解液柱问题中的参量与能量变化_笔记","note":"视频|24:14-26:53","orig":"（例）气体1由90×30=75×l1'得l1'=36cm，结合几何关系扣除重叠部分得液柱A移动21cm","link":""},{"id":"phy1845","t":"热学·气体实验定律","s":"看到【气体状态变化方向不确定、液柱移动情况未知】","c":"想到【先假设液面高度不变（最便于列式），再由规律推导实际变化】；警惕【假设只是分析手段，结论必须回到实际变化验证】","src":"物一轮289.假设法在液柱问题中的应用_笔记","note":"视频|00:00-00:06","orig":"（知识）假设法核心思想：当不确定状态如何变化时，先假设其不变（最便于列式的情况），再通过物理规律推导实际变化。","link":""},{"id":"phy1846","t":"热学·假设法液柱问题","s":"看到【等容过程中两段封闭气柱随温度变化、问液柱是否移动】","c":"想到【对两气柱分别用查理定律列式，联立比较两端压强变化量】；警惕【只有两侧 $\\Delta$T 相同时才可直接比较，需先核对初始温度与温变是否一致】","src":"物一轮289.假设法在液柱问题中的应用_笔记","note":"视频|00:06-11:07","orig":"（例）温度变化时假设液面高度不变，由 p/T=c 对两气柱分别列式 p_A/T_A=p_A'/T_A'、p_B/T_B=p_B'/T_B'，联立消元判断。","link":""},{"id":"phy1847","t":"热学·假设法液柱问题","s":"看到【等温条件下放出（或加入）水银、问两液面最终高低】","c":"想到【假设液面等高，用玻意耳定律列式后比较新压强，压强大的一侧液面将下降】；警惕【截面积相同的管中体积变化可用长度比代替体积比】","src":"物一轮289.假设法在液柱问题中的应用_笔记","note":"视频|00:06-11:07","orig":"（例）等温放出银时假设液面等高，由 pV=c 列式，比较 p_A'/p_B' = L_A/L_B × (L_B+h)/(L_A+h) 判断液面移动方向。","link":""},{"id":"phy1848","t":"热学·液柱移动方向","s":"看到【细管由竖直转水平（或倾斜角度变化）、判断水银柱移动方向】","c":"想到【先假设液柱不动分析压强差，压强大的一端推动液柱向压强小的一端移动，最终两气柱压强相等】；警惕【转动后原来有高度差压强项消失，两气柱一压一胀】","src":"物一轮289.假设法在液柱问题中的应用_笔记","note":"视频|11:07","orig":"（例）竖直放置时 p_B=p_A+ρgh；转至水平若液柱不动则压强不变，因 p_B>p_A 液柱右移，最终 p_A'=p_B'。","link":""},{"id":"phy1849","t":"热学·热力学第一定律","s":"看到【等温过程中气体被压缩或膨胀、判断吸放热】","c":"想到【温度不变则 $\\Delta$U=0，由体积变化定 W 的符号，Q=-W 反号即得吸放热】；警惕【压缩放热、膨胀吸热，符号规则不可颠倒】","src":"物一轮289.假设法在液柱问题中的应用_笔记","note":"视频|11:07","orig":"（例）等温过程中对a气体 ΔU=0=W1+Q1（压缩 W1>0 故 Q1<0 放热），对b气体 ΔU=0=W2+Q2（膨胀 W2<0 故 Q2>0 吸热）。","link":""},{"id":"phy1850","t":"热学·热量比较","s":"看到【两气柱体积变化量相同、比较吸放热量的多少】","c":"想到【热量大小通过功的大小间接比较：|Q|=|W|≈p·$\\Delta$V，$\\Delta$V 相同时压强大的功大】；警惕【过程中压强在变，严格说比较的是平均压强，相对大小结论不变】","src":"物一轮289.假设法在液柱问题中的应用_笔记","note":"视频|11:07","orig":"（例）ΔV 相同且 p_B>p_A，故 |W2|>|W1|，从而 |Q2|>|Q1|，即b气体吸热量大于a气体放热量。","link":""},{"id":"phy1851","t":"热学·玻璃管空气柱","s":"看到【玻璃管（水银柱封气）做自由落体或完全失重运动】","c":"想到【完全失重时水银柱不产生压强，封闭气体压强等于大气压 p=p0，再按等容（或题给过程）列气体定律】；警惕【失重不是没有大气压，只是 $\\rho$gh 项消失】","src":"物一轮290.解决液体总量变化问题的方法_笔记","note":"视频|00:15-09:31","orig":"（例）总长100cm玻璃管用12cm水银柱封空气柱，p0=75cmHg、T1=300K；自由落体时水银恰好不溢出，液柱仅受重力，内外压强相等 p2=p0=75cmHg，等容 p1/T1=p2/T2 求温度。","link":""},{"id":"phy1852","t":"热学·注液极限问题","s":"看到【向封闭管中注水银、求最多能注入多少】","c":"想到【极限状态是液柱恰好充满管子，水银柱长度既增大压强又减小气体体积，用管长关系表示 p 与 V 后联立气体定律】；警惕【方程的解需检验：初态解要舍去，保留极限态解】","src":"物一轮290.解决液体总量变化问题的方法_笔记","note":"视频|00:15-09:31","orig":"（例）向管中注水银，极限状态为水银完全填满玻璃管；设空气柱长 l，则水银柱长 100-l，p=75+(100-l)=175-l，由 p1V1=p2V2 得 87×88=(175-l)l，解得 l=87cm（舍去初态解88cm）。","link":""},{"id":"phy1853","t":"热学·U形管气体问题","s":"看到【U形管两侧粗细不同、加热（或加液）后液面移动】","c":"想到【两侧液体体积变化量相等，用截面积比换算两侧液面移动距离，再结合几何关系（移动量之和等于高度差变化）列方程】；警惕【$\\Delta$V 相等但 $\\Delta$h 不等，内径比是面积比（直径比的平方）】","src":"物一轮290.解决液体总量变化问题的方法_笔记","note":"视频|09:31-16:47","orig":"（例）右管内径为左管2倍（面积比4:1），左管空气柱76cm、高度差6cm；加热后液面齐平，由 ΔV 相等得 s·Δl1=4s·Δl2，结合 Δl1+Δl2=6cm 得 Δl1=4.8cm，再用理想气体状态方程求末温。","link":""},{"id":"phy1854","t":"热学·U形管等温过程","s":"看到【U形管等温条件下注液后求液面高度差】","c":"想到【先用玻意耳定律求新压强，高度差数值上等于（新压强-大气压当量）之差】；警惕【压强单位统一用 cmHg 时可直接做差，用 Pa 则需换算】","src":"物一轮290.解决液体总量变化问题的方法_笔记","note":"视频|09:31-16:47","orig":"（例）注水银过程等温：p2V2=p3V3，V3=76s，得 p3=80.8cmHg，高度差 80.8-76=4.8cm（右管液面更高）。","link":""},{"id":"phy1855","t":"热学·液柱问题通法","s":"看到【水银柱增减同时影响封闭气体的压强与体积】","c":"想到【把液柱长度同时代入压强式 p=p0±$\\rho$gh 和体积表达式，联立求解】；警惕【只考虑体积或只考虑压强都会漏解，动态参量必须关联分析】","src":"物一轮290.解决液体总量变化问题的方法_笔记","note":"视频|16:47","orig":"（知识）液柱对封闭气体有双重影响：液柱长度变化直接改变气体体积；液柱高度变化改变压强 p=p0±ρgh。解题须同时考虑压强和体积变化。","link":""},{"id":"phy1856","t":"热学·液柱问题通法","s":"看到【题目问『能否继续注入』『恰好不溢出』类临界条件】","c":"想到【先写出临界状态的几何特征（液柱充满/液面齐平/恰好到管口），以此作为方程的附加条件】；警惕【临界状态不等同于初态，解出的多余根要按物理意义舍去】","src":"物一轮290.解决液体总量变化问题的方法_笔记","note":"视频|16:47","orig":"（知识）注液过程需分析『不能再注入』的临界状态；U形管问题注意两侧截面积比（ΔV 相等但 Δh 不等）。","link":""},{"id":"phy1857","t":"光学·模块框架","s":"看到【光学题需判断属于哪类模块（光路计算/波动现象/粒子性）】","c":"想到【先分模块定方法：几何光学靠定律+几何计算，波动性靠现象辨析，粒子性归近代物理】；警惕【粒子性内容与几何光学方法完全不同，不可混用】","src":"物一轮291.【课前必看】本讲听课建议_笔记","note":"视频|00:10-01:36","orig":"（知识）光学模块分三部分：几何光学（光路研究）、光的波动性（实验现象）、光的粒子性（近代物理模块）。","link":""},{"id":"phy1858","t":"光学·光的直线传播","s":"看到【反射、折射、全反射、色散现象的综合判断题】","c":"想到【逐条核对基本定律：反射/折射定律、全反射两条件、色散由折射率随波长不同引起】；警惕【角度均指与法线的夹角，不是与界面的夹角】","src":"物一轮291.【课前必看】本讲听课建议_笔记","note":"视频|01:36-04:13","orig":"（知识）光的直线传播规律包含反射、折射、全反射和折射色散现象，是几何光学的基础定律。","link":""},{"id":"phy1859","t":"光学·全反射","s":"看到【光纤通信、钻石切割、海市蜃楼等全反射应用情境】","c":"想到【认准全反射两要素：光密$\\to$光疏、入射角$\\geq$临界角，用 sinC=1/n 求临界角】；警惕【光疏$\\to$光密永远不可能发生全反射】","src":"物一轮291.【课前必看】本讲听课建议_笔记","note":"视频|04:13","orig":"（知识）全反射条件：光从光密介质射向光疏介质、入射角≥临界角；临界角公式 sinC=1/n；典型应用如光纤通信。","link":""},{"id":"phy1860","t":"光学·考情与备考","s":"看到【光学解答题（光路计算类）】","c":"想到【本质是物理定律+平面几何：画光路图、标法线、找三角形边角关系求解】；警惕【几何光路题失分多在几何关系而非物理公式】","src":"物一轮291.【课前必看】本讲听课建议_笔记","note":"视频|04:13","orig":"（知识）几何光学为非主干知识，以选择题为主（中等偏下难度），部分地区含解答题；解答题聚焦光路计算，侧重几何应用能力。","link":""},{"id":"phy1861","t":"几何光学·光的反射定律","s":"看到【光的反射问题中标角度】","c":"想到【所有角度一律标注为光线与法线的夹角，先画法线再定光线】；警惕【因果表述只能是「反射角等于入射角」，与界面夹角需先换算成与法线的夹角】","src":"物一轮292.光的反射与折射_笔记","note":"视频|00:33-03:10","orig":"（知识）反射定律：三线共面、两线分居、反射角等于入射角（θ2=θ1）；入射角和反射角都是光线与法线的夹角。","link":""},{"id":"phy1862","t":"几何光学·光的折射定律","s":"看到【光穿过两种介质界面求折射角或入射角】","c":"想到【用 n=sin i/sin r 列式，必要时利用光路可逆性反向处理】；警惕【正弦比只对固定介质组合恒定，换介质组合需重新确定 n】","src":"物一轮292.光的反射与折射_笔记","note":"视频|03:10-06:25","orig":"（知识）折射定律：三线共面、两线分居、sin i/sin r=n21（固定介质组合比值恒定）；入射角增大折射角相应增大；折射光路可逆。","link":""},{"id":"phy1863","t":"几何光学·折射率","s":"看到【计算结果折射率小于1（或需要检验折射率合理性）】","c":"想到【n<1 必是计算或角度用错，立即回头检查】；警惕【空气折射率近似取1，但 n 是介质属性，与入射角无关】","src":"物一轮292.光的反射与折射_笔记","note":"视频|06:25-08:03","orig":"（知识）绝对折射率：介质相对真空的折射率，真空为1；高中阶段空气折射率近似为1；除真空和空气外其他介质 n>1，若算出 n<1 必定有错。","link":""},{"id":"phy1864","t":"几何光学·折射率公式","s":"看到【题目给角度求折射率，或给（求）介质中光速】","c":"想到【有角度用 n=sin$\\theta$大/sin$\\theta$小，涉及光速用 n=c/v，两式可互相换算】；警惕【不必死记分子分母顺序，只需保证大角正弦在上】","src":"物一轮292.光的反射与折射_笔记","note":"视频|08:03-11:14","orig":"（知识）折射率两公式：角度公式 n=sinθ大/sinθ小（大角在上小角在下）；速度公式 n=c/v（c=3×10⁸ m/s）。","link":""},{"id":"phy1865","t":"几何光学·折射率与偏折","s":"看到【通过光路偏折程度（或折射角大小）比较介质折射率】","c":"想到【用 n大·sin$\\theta$小=n小·sin$\\theta$大 判断：折射率大的一侧角度小】；警惕【反射光能量占比再大也不改变反射角、折射角的关系】","src":"物一轮292.光的反射与折射_笔记","note":"视频|11:14-18:21","orig":"（知识）折射率大的介质中光线与法线夹角小；光路偏折程度越大说明折射率越大；反射和折射同时发生，两者能量之和等于入射能量，能量分配不影响角度关系。","link":""},{"id":"phy1866","t":"几何光学·应用案例","s":"看到【大气（或渐变介质）中折射率随高度单调变化、判断光路弯曲方向】","c":"想到【折射率单调变化时光线弯曲方向保持一致，光向折射率大的一侧偏折；可用界面分层法逐层用折射定律分析】；警惕【光路先弯下后拐上的选项与单调变化矛盾，可直接排除】","src":"物一轮292.光的反射与折射_笔记","note":"视频|18:36-21:53","orig":"（例）地球表面附近空气折射率随高度降低而增大，光线应持续向折射率大的一侧（下方）弯曲，用界面分析法逐层处理。","link":""},{"id":"phy1867","t":"几何光学·新概念题","s":"看到【题干给出负折射率等新概念材料】","c":"想到【严格按题干新定义套用公式，默认规律（n>1、两线分居）被题干明确改写时以题干为准】；警惕【无特殊说明默认 n>1；题干「但是」转折后的信息往往是解题关键】","src":"物一轮292.光的反射与折射_笔记","note":"视频|21:53-27:57","orig":"（例）负折射率材料（n<0）是特殊人工材料，仍满足 sin i/sin r=n，但折射光线与入射光线位于法线同侧；n=-1 时 |i|=|r|。","link":""},{"id":"phy1868","t":"几何光学·实验测折射率","s":"看到【反射光线与折射光线恰好垂直的测折射率情境】","c":"想到【垂直条件导出 n=tan$\\alpha$（仅限此特定几何条件），再用几何边角关系（勾股/三角函数）求角】；警惕【n=tan$\\alpha$ 不是普适公式，条件不满足时不能套用】","src":"物一轮292.光的反射与折射_笔记","note":"视频|27:57","orig":"（例）反射光与折射光垂直时 α+β=90°，折射率公式化为 n=sinα/sinβ=tanα；结合容器半宽8cm与液深h构造直角三角形求 n。","link":""},{"id":"phy1869","t":"几何光学·光密与光疏介质","s":"看到【判断某介质是光密还是光疏】","c":"想到【必须指明比较对象，n 大者为光密介质】；警惕【同一介质在不同比较中角色可以相反，不能脱离对比对象下结论】","src":"物一轮293.光的全反射_笔记","note":"视频|00:07-02:00","orig":"（知识）光密介质：折射率较大；光疏介质：折射率较小。光密/光疏是相对的，取决于比较对象：水对空气是光密，对玻璃是光疏。","link":""},{"id":"phy1870","t":"几何光学·全反射条件","s":"看到【判断光在界面能否发生全反射】","c":"想到【逐条核对两条件：介质方向（光密$\\to$光疏）+角度（$\\geq$临界角），缺一不可】；警惕【空气$\\to$水不可能全反射；未达临界角时反射与折射同时存在】","src":"物一轮293.光的全反射_笔记","note":"视频|06:24-09:56","orig":"（知识）全反射两个必要条件：光从光密介质射向光疏介质（n1>n2）、入射角≥临界角（θ≥θc）；临界角 sinθc=n2/n1。","link":""},{"id":"phy1871","t":"几何光学·折射率三公式","s":"看到【求折射率但题目给的条件分别是角度、光速或临界角】","c":"想到【按已知条件灵活选公式：角度用定义式、速度用 c/v、全反调用 1/sinC】；警惕【三式相等仅对介质相对真空（或空气）成立】","src":"物一轮293.光的全反射_笔记","note":"视频|09:56-10:46","orig":"（知识）折射率三大公式：n=sinθ大/sinθ小（定义式）、n=c/v（速度关系）、n=1/sinC（临界角）。","link":""},{"id":"phy1872","t":"几何光学·全反射能量","s":"看到【全反射发生后的能量（光强）分配问题】","c":"想到【全反射时反射光能量=入射光能量，折射光能量为零】；警惕【是折射光能量为零，不是折射光线这个概念消失】","src":"物一轮293.光的全反射_笔记","note":"视频|09:56-10:46","orig":"（知识）全反射时折射光线能量为零（理论存在但实际不可见），入射能量全部转化为反射能量。","link":""},{"id":"phy1873","t":"几何光学·光导纤维","s":"看到【光导纤维（光纤）传光原理判断题】","c":"想到【内芯必须是光密介质（n内>n外），全反射位置在内芯-外套界面】；警惕【外套作用是保护与折射率匹配，与韧性等材料性能描述无关】","src":"物一轮293.光的全反射_笔记","note":"视频|10:56-14:14","orig":"（知识）光纤由内芯和外套组成，光线在内芯中通过全反射传播；内芯折射率 n1 必须大于外套折射率 n2，全反射发生在内芯-外套界面。","link":""},{"id":"phy1874","t":"几何光学·水中看天","s":"看到【水下观察者通过水面看到外界景物的圆锥形视场】","c":"想到【圆锥边界由水面全反射临界角决定，用 sinC=1/n 求 C，再由几何关系 r=htanC 求视场半径】；警惕【是光路可逆+全反射共同作用，光从空气进水时入射角受临界角限制】","src":"物一轮293.光的全反射_笔记","note":"视频|14:14-21:16","orig":"（例）潜水者抬头看见岸上景物都出现在一个倒立圆锥区域内；tanθc=r/h，sinθc=1/n，圆锥半径 r=htanθc，视场面积 A=πr²。","link":""},{"id":"phy1875","t":"几何光学·水流导光","s":"看到【水流导光（激光沿弯曲水流传播）实验的变量分析】","c":"想到【增强全反射两条路：增大入射角（调激光方向、提高液面使界面平缓）或减小临界角（选折射率更大的液体）】；警惕【激光强度、激光器水平距离不是决定是否全反射的因素】","src":"物一轮293.光的全反射_笔记","note":"视频|21:16-26:26","orig":"（例）激光沿弯曲水流传播：水流弯曲处形成水-空气界面（n水>n空气）且入射角大于临界角；水量多→水流平缓→入射角大→更易全反射。","link":""},{"id":"phy1876","t":"几何光学·全反射计算","s":"看到【题目给光线与界面的夹角而非与法线的夹角】","c":"想到【先用 $\\theta$+$\\alpha$=90$^{\\circ}$ 换算成入射角，再与临界角比较判断全反射】；警惕【入射角是光线与法线的夹角，直接拿界面夹角与临界角比较必错】","src":"物一轮293.光的全反射_笔记","note":"视频|26:26","orig":"（例）已知界面夹角 α>41° 对应入射角 θ1<49°，恰不发生全反射得临界角 C=49°，n=1/sinC=1/sin49°；角度关系 θ1+α=90°。","link":""},{"id":"phy1877","t":"几何光学·色散现象","s":"看到【白光通过三棱镜形成彩色光带】","c":"想到【这是折射色散而非干涉/衍射；同一入射角下各色光折射率不同导致偏折不同】；警惕【色散发生在两次折射过程，判断现象类别是第一道关】","src":"物一轮294.光的折射色散_笔记","note":"视频|00:16-01:25","orig":"（知识）白光通过三棱镜分解为红橙黄绿青蓝紫七色光带，本质是不同色光在介质中折射角不同，经入射、出射两次折射实现色散分离，从上到下为红→紫。","link":""},{"id":"phy1878","t":"几何光学·色散物理量规律","s":"看到【比较红光与紫光（或两束色光）的频率、折射率、速度、波长、临界角】","c":"想到【记住一条主线：紫光频率大$\\to$折射率大$\\to$速度小、波长短、临界角小；由任一物理量推出其余全部】；警惕【频率符号是 ν 不是速度 v；波长比较要区分真空中与介质中】","src":"物一轮294.光的折射色散_笔记","note":"视频|01:25-02:40","orig":"（知识）从红光到紫光：频率ν、折射率n 增大；传播速度v、波长λ、临界角C 减小。口诀：带「率」的增（折射率、频率），不带的减（速度、波长、临界角）。","link":""},{"id":"phy1879","t":"几何光学·折射率比较","s":"看到【两束色光以相同入射角入射、比较折射角大小】","c":"想到【折射角小者折射率大，进而判定其频率高、波长短、速度小、临界角小】；警惕【比较前提是入射角相同，光路不同时要先画图确认入射角关系】","src":"物一轮294.光的折射色散_笔记","note":"视频|03:20-04:21","orig":"（知识）用折射定律 n=sinθ大/sinθ小比较色光折射率：相同入射角下紫光折射角更小→分母更小→折射率更大（n紫>n红）。","link":""},{"id":"phy1880","t":"几何光学·色光速度与波长","s":"看到【比较两色光在同种介质中的传播速度或波长】","c":"想到【速度用 v=c/n 排序；波长用 v=$\\lambda$ν 结合速度与频率结论推出】；警惕【真空中各色光速度相同，波长差异只在介质中体现为折射率差】","src":"物一轮294.光的折射色散_笔记","note":"视频|04:21-05:04","orig":"（知识）介质中光速 v=c/n，折射率大的光速小（v红>v紫）；波长由 v=λν 判断，红光速度大而频率小→红光波长必然更大（真空中和介质中均成立）。","link":""},{"id":"phy1881","t":"几何光学·临界角与全反射顺序","s":"看到【色散光带随入射角增大逐色消失、判断先消失的颜色】","c":"想到【消失顺序由临界角决定：折射率最大（临界角最小）的色光最先发生全反射而消失，折射率最小的最后消失】；警惕【先确认全反射发生的界面（如水$\\to$真空$\\neq$玻璃$\\to$空气），再比较色光折射率】","src":"物一轮294.光的折射色散_笔记","note":"视频|05:04-06:17","orig":"（例）水中中空（真空）棱镜：全反射发生在水→真空界面；紫光折射率大→临界角小→先达到全反射条件先消失，红光临界角最大最后消失。","link":""},{"id":"phy1882","t":"几何光学·光路与色光判断","s":"看到【由光路图（偏折程度或出射位置）反推色光的物理量关系】","c":"想到【先画法线定入射角相同，再比折射角定折射率大小，最后按「带率的增」链式推出全部物理量】；警惕【反射点位置影响出射光高低，必须画图验证而非凭感觉】","src":"物一轮294.光的折射色散_笔记","note":"视频|08:06-16:32","orig":"（例）甲乙两束光画光路图，乙光反射点在甲光右侧才能保证出射点更高；乙光折射角更小→折射率更大→乙光对应紫光特性（频率高、波长短、速度小）。","link":""},{"id":"phy1883","t":"几何光学·特殊光路","s":"看到【光线垂直射向界面（沿法线入射）】","c":"想到【垂直入射时光沿直线传播不偏折，但介质中光速仍变为 c/n】；警惕【不偏折不等于速度不变，方向不变而速率改变】","src":"物一轮294.光的折射色散_笔记","note":"视频|16:32-19:41","orig":"（例）光沿法线方向入射（出射）时光线不发生偏折；比较b、c光折射角 θb<θc 得 nb>nc，b光频率更高、波长更短、速度更小。","link":""},{"id":"phy1884","t":"几何光学·知识准备","s":"看到【几何光路计算题（玻璃砖、棱镜、圆形介质）】","c":"想到【工具箱=两个物理公式+平面几何（三角函数、勾股、相似、圆的对称性），先画光路标法线再套几何关系】；警惕【角度必须标成与法线的夹角】","src":"物一轮295.几何光路计算_笔记","note":"视频|00:22-02:25","orig":"（知识）物理公式：折射率公式 n=sinθ大/sinθ小、全反射公式 n=1/sinC；数学工具：三角函数、勾股定理、相似三角形、垂径定理与圆形对称性。","link":""},{"id":"phy1885","t":"几何光学·全反射判断","s":"看到【光从玻璃（水）等光密介质射向空气】","c":"想到【先算 sinC=1/n，再比较入射角与 C：$\\geq$C 全反射（只有反射光），<C 才有折射】；警惕【默认发生折射而跳过全反射判断是最大失分点】","src":"物一轮295.几何光路计算_笔记","note":"视频|02:25-03:04","orig":"（知识）光线从光密介质射向光疏介质时，必须先计算临界角并判断入射角是否达到全反射条件；光密到光疏不一定折射，需考虑全反射可能。","link":""},{"id":"phy1886","t":"几何光学·棱镜多次反射","s":"看到【棱镜内光线经多次反射折射后问出射方向】","c":"想到【逐个界面计算入射角并与临界角比较，决定全反射（改方向继续传）还是折射（出射），用折射定律求出射角】；警惕【每次反射后入射角可能不变（对称），但必须逐面验证而不能只算一次】","src":"物一轮295.几何光路计算_笔记","note":"视频|03:04-14:05","orig":"（例）n=2 棱镜临界角 C=45°；光线在AB面入射角60°>45°全反射，至BC面仍60°再全反射，至CD面入射角30°<45°折射射出，由 n=sinθ/sin30° 得出射角45°。","link":""},{"id":"phy1887","t":"几何光学·三角形几何计算","s":"看到【声（光）波折射类问题中求深度、距离，涉及 sinr 含参数 i】","c":"想到【由 n（或波速比）写出 sinr 表达式后，构造直角三角形（斜边、对边、邻边）直接读出 tanr，避免求反三角函数】；警惕【对称光路（等腰三角形）是简化关键，先证对称再列式】","src":"物一轮295.几何光路计算_笔记","note":"视频|14:05-20:57","orig":"（例）B超问题：超声波折射满足 sinθ1/sinθ2=v1/v2，v2=0.9v1 得 sinr=9sini/10；肿瘤表面平行于肝表面时光路成等腰三角形，构造直角三角形（斜边10、对边9sini）直接写出 tanr，代入 h=(d/2)/tanr。","link":""},{"id":"phy1888","t":"几何光学·相似三角形法","s":"看到【玻璃砖两次折射、出射光与入射光平行，求光斑（平移）距离】","c":"想到【先证平行关系，再用相似三角形比例求线段差，可完全绕开折射率计算】；警惕【入射方向或介质改变则平行前提失效，需重新作图】","src":"物一轮295.几何光路计算_笔记","note":"视频|20:57-30:19","orig":"（例）入射方向和折射率不变时两次折射光线必然平行，构造相似三角形用比例 AC/DF=BC/EF 求线段，最终 x=FG-EF=L/3；全程未直接算折射率。","link":""},{"id":"phy1889","t":"几何光学·圆形介质对称光路","s":"看到【光线射入圆形（球形）玻璃砖求折射率或光路】","c":"想到【利用圆的对称性定光路（入射点出射点对称、法线沿半径方向），非直角三角形用余弦定理/正弦定理求角】；警惕【圆形介质中法线沿半径方向；中间结果保留根号形式不必展开，长度含 R 因子可约去】","src":"物一轮295.几何光路计算_笔记","note":"视频|30:19-43:58","orig":"（例）圆形介质中入射点与出射点关于中心轴对称，反射点必在底面中心（光路可逆保证）；sin i=0.6R/R，r 用余弦定理 cosr=(AO²+AC²-OC²)/2AO·AC 求得，n=sin i/sin r。","link":""},{"id":"phy1890","t":"几何光学·全反射边界","s":"看到【求玻璃内恰好发生全反射的位置（边界、范围）】","c":"想到【先由折射定律求 n 和临界角 C，令入射角=C 定出临界点，再用特殊角三角形（30$^{\\circ}$-45$^{\\circ}$-60$^{\\circ}$）算边界距离】；警惕【上下（两侧）边界各有一个临界位置，答案常是两者的差或范围】","src":"物一轮295.几何光路计算_笔记","note":"视频|43:58-50:01","orig":"（例）楔形玻璃：n=sin45°/sin30°=√2，临界角C=45°；上下边界入射角恰为45°处为临界位置，建 30°-45° 特殊三角形求两边界距离，差为 d。","link":""},{"id":"phy1891","t":"几何光学·复合元件","s":"看到【半圆形/复合光学元件上求发生全反射的区域范围】","c":"想到【转化为纯几何问题：定临界角$\\to$找入射角恰等于临界角的临界点（用三角函数表示位置）$\\to$写不等式确定范围】；警惕【善用圆的对称性和特殊三角形；光路范围题的答案是几何区间而非单点】","src":"物一轮295.几何光路计算_笔记","note":"视频|50:01","orig":"（例）复合光学元件：EF边折射角30°，n=sinθ/sin30°=1.5 得 sinθ=0.75；临界角 sinC=2/3，越靠左入射角越大，临界点 OH/R=2/3，几何关系得 DE=AH/cos30°。","link":""},{"id":"phy1892","t":"光的波动性·模块框架","s":"看到【波动光学现象辨析题（衍射/偏振/干涉）】","c":"想到【先按现象归类：双缝干涉看等间距条纹、薄膜干涉看等厚条纹、衍射看光绕障碍物、偏振看振动方向】；警惕【干涉与衍射现象易混，需按装置和条纹特征区分】","src":"物一轮296.【课前必看】本讲听课建议_笔记","note":"视频|00:08-01:01","orig":"（知识）光的波动性包含三大现象：光的衍射、光的偏振、光的干涉；干涉又分为双缝干涉和薄膜干涉两部分，均为必须掌握的基础内容。","link":""},{"id":"phy1893","t":"光的波动性·物理量综合","s":"看到【波动现象题选项中出现 n、ν、$\\lambda$、C、v 的比较判断】","c":"想到【用「频率大$\\to$折射率大$\\to$速度小、波长短、临界角小」链条逐项核对】；警惕【跨模块综合题（波动+几何光学）需先定色光再代公式】","src":"物一轮296.【课前必看】本讲听课建议_笔记","note":"视频|01:34-02:59","orig":"（知识）常围绕光学物理量综合考查：折射率n、频率ν、波长λ、临界角C、介质中传播速度v，光学现象常与物理量结合命题。","link":""},{"id":"phy1894","t":"光的波动性·考情重点","s":"看到【双缝干涉或薄膜干涉相关考题】","c":"想到【这是波动光学的高频必拿分点，优先掌握明暗条纹与薄膜等厚干涉的判断方法】；警惕【偏振、衍射考题少但常以新情境综合形式出现，不可完全放弃】","src":"物一轮296.【课前必看】本讲听课建议_笔记","note":"视频|02:59","orig":"（知识）考查以光的干涉为主，衍射和偏振相对较少；双缝干涉和薄膜干涉出题频率最高，是学习重点，多以选择题（前几题）形式出现。","link":""},{"id":"phy1895","t":"光的衍射·明显衍射条件","s":"看到【判断能否发生明显衍射】","c":"想到【比较波长与障碍物/孔尺寸，λ$\\geq$l 才明显衍射；机械波与光波条件一致】；警惕【条件是波长与尺寸比较，与波速、距离无关】","src":"物一轮297.光的衍射_笔记","note":"视频|00:43-01:11","orig":"（知识）发生明显衍射的基本条件：波长 λ 大于等于障碍物或孔的尺寸 l，即 λ≥l；高中阶段只记忆应用，不深究原理。","link":""},{"id":"phy1896","t":"光的衍射·现象解释","s":"看到【用衍射解释生活现象（如隔墙闻声）】","c":"想到【声波波长远大于光波波长，更易满足 λ$\\geq$l 而衍射】；警惕【不能解释为声音传播速度比光快】","src":"物一轮297.光的衍射_笔记","note":"视频|01:11-02:55","orig":"（例）解释「未见其人，先闻其声」：光被障碍物挡住未衍射，声波绕过障碍物发生衍射。","link":""},{"id":"phy1897","t":"光的衍射·单色光衍射图样","s":"看到【条纹明暗相间但不等间距】","c":"想到【这是衍射图样；不等间距是区分衍射与干涉的关键依据】；警惕【波长越短（蓝、紫光）衍射越弱、条纹越窄】","src":"物一轮297.光的衍射_笔记","note":"视频|03:10-05:26","orig":"（知识）红光单缝衍射：明暗相间的不等间距条纹；λ红>λ蓝，红光衍射更明显、亮条纹更宽。","link":""},{"id":"phy1898","t":"光的衍射·白光衍射","s":"看到【白光通过单缝/圆孔出现彩色条纹】","c":"想到【各色光波长不同、衍射图样宽度不同而叠加成彩色，中心为白色】；警惕【不是黑白相间，也不会是单一颜色的条纹】","src":"物一轮297.光的衍射_笔记","note":"视频|05:26-07:28","orig":"（知识）白光衍射：七种色光各自衍射叠加，形成彩色条纹；中心各色光均为亮纹叠加为白色，外围缺色呈彩色。","link":""},{"id":"phy1899","t":"光的衍射·泊松亮斑与圆孔衍射","s":"看到【暗影中心出现小亮斑】或【同心圆环且中心亮】","c":"想到【泊松亮斑（圆板衍射）中心亮、圆孔衍射同心环中心亮，均属衍射】；警惕【与牛顿环区分：牛顿环中心为暗区】","src":"物一轮297.光的衍射_笔记","note":"视频|07:28-08:08","orig":"（知识）泊松亮斑：大暗区中心出现小亮斑，是典型衍射现象；圆孔衍射：一圈圈同心圆环，最中间为亮区。","link":""},{"id":"phy1900","t":"光的衍射·牛顿环辨析","s":"看到【牛顿环』归类的判断】","c":"想到【牛顿环属薄膜干涉，中心为暗区；泊松亮斑/圆孔衍射中心为亮区】；警惕【名字带「环」不等于衍射，按干涉处理】","src":"物一轮297.光的衍射_笔记","note":"视频|08:21-09:28","orig":"（知识）牛顿环本质是薄膜干涉（非衍射）；识别特征：中心无小亮点（暗区），与泊松亮斑、圆孔衍射相反。","link":""},{"id":"phy1901","t":"光的衍射·实验题：条纹宽窄调控","s":"看到【要求衍射条纹变窄/变宽（或衍射更明显/更弱）】","c":"想到【条纹宽窄只由波长 $\\lambda$ 与障碍物尺寸 l 决定：$\\lambda$↓或 l↑则衍射减弱、条纹变窄；$\\lambda$↑或 l↓则相反】；警惕【改变光源到屏的距离、亮度等与明显衍射条件无关】","src":"物一轮297.光的衍射_笔记","note":"视频|09:28","orig":"（例）减小单缝衍射条纹宽度：减弱衍射现象需 λ 减小或 l 增大，改用绿光（波长比红光短）可行，答案选波长更短的光。","link":""},{"id":"phy1902","t":"光的偏振·偏振现象与横波特性","s":"看到【波通过狭缝/偏振片后能否通过的比较】","c":"想到【偏振是横波特有现象：缝方向与振动方向一致才能通过，斜缝只通过部分分量；纵波任意缝方向都能通过】；警惕【偏振证明光是横波，不能用于判断纵波】","src":"物一轮298.光的偏振_笔记","note":"视频|00:22-08:44","orig":"（知识）横波振动方向与传播方向垂直，同一传播方向上振动方向可不同，即偏振现象；绳波过木板缝隙实验演示：竖缝允许上下振动通过，横缝完全阻挡。","link":""},{"id":"phy1903","t":"光的偏振·自然光与偏振光","s":"看到【判断光源/光是自然光还是偏振光】","c":"想到【自然光振动方向随机，偏振光只在特定方向振动；反射光、折射光多为偏振光】；警惕【偏振片靠分子结构筛选振动方向，不是物理缝隙】","src":"物一轮298.光的偏振_笔记","note":"视频|08:44-11:15","orig":"（知识）自然光：垂直于传播方向上包含所有振动方向的光（太阳光、日光灯）；偏振光：只在特定方向振动（激光、反射光、折射光）。","link":""},{"id":"phy1904","t":"光的偏振·实际应用","s":"看到【3D眼镜/偏振滤光片/全息投影的原理判断】","c":"想到【3D眼镜与滤光片利用偏振；全息投影利用干涉、无需佩戴偏振眼镜】；警惕【银幕需同时放映两部偏振方向垂直的画面；全息不是偏振应用】","src":"物一轮298.光的偏振_笔记","note":"视频|11:15-15:49","orig":"（知识）3D眼镜：左右镜片偏振方向垂直，分别接收不同偏振方向的影像，大脑合成立体视觉；相机偏振滤光片减少镜面反射光；全息投影属干涉现象（裸眼可见），非偏振应用。","link":""},{"id":"phy1905","t":"光的偏振·例题：偏振方向判断","s":"看到【偏振片（镜片）旋转前后明暗变化】","c":"想到【明亮=入射光振动方向与偏振片方向平行，灰暗=垂直；旋转90$^{\\circ}$后平行关系互换】；警惕【旋转后两个镜片的偏振关系同时改变，不能只分析一个镜片】","src":"物一轮298.光的偏振_笔记","note":"视频|15:49","orig":"（例）屏幕光经3D眼镜观察，左镜片明亮，将屏幕旋转90°后左镜片变暗、右镜片变明，答案判断左右镜片明暗互换。","link":""},{"id":"phy1906","t":"光的干涉·相干光条件","s":"看到【判断两束光能否发生干涉】","c":"想到【先查频率（颜色相同即频率相同），再查光源性质——自然光（如普通灯泡光）振动方向随机不能干涉，偏振光才可】；警惕【颜色相同不必然干涉，还要看是否自然光】","src":"物一轮299.双缝干涉_笔记","note":"视频|00:35-01:18","orig":"（知识）相干光三要素：频率相同、振动方向一致、相位差恒定；需偏振光，自然光振动方向随机无法干涉。","link":""},{"id":"phy1907","t":"光的干涉·例题：干涉条件判断","s":"看到【两种色光/两个光源能否干涉的判断】","c":"想到【不同频率必不干涉；同频率的普通光源因是自然光也不干涉】；警惕【频率判断看颜色排序：红光频率最小、紫光最大】","src":"物一轮299.双缝干涉_笔记","note":"视频|01:18-03:16","orig":"（例）红光与紫光：频率不同（v红<v紫），不能干涉；两个黄色小灯泡的黄光：颜色相同但为自然光，振动方向随机，不能干涉。","link":""},{"id":"phy1908","t":"双缝干涉·条纹特征与间距公式","s":"看到【计算/比较干涉条纹间距】","c":"想到【套用 $\\Delta$x=$\\lambda$L/d：波长越长、缝屏距越大、缝距越小，条纹越宽】；警惕【等间距是干涉图样标志，与衍射的不等间距区分】","src":"物一轮299.双缝干涉_笔记","note":"视频|03:38-06:38","orig":"（知识）双缝干涉条纹明暗相间且等间距；Δx=λL/d，λ为波长，L为双缝到屏距离，d为双缝间距。","link":""},{"id":"phy1909","t":"双缝干涉·不同色光与白光干涉","s":"看到【比较不同色光干涉条纹宽窄】或【白光干涉图样】","c":"想到【红宽紫窄按波长排序；白光干涉中央白色、两侧彩色且红$\\to$紫逐渐变窄】；警惕【各色光独立干涉、互不叠加成新条纹】","src":"物一轮299.双缝干涉_笔记","note":"视频|06:38-08:22","orig":"（知识）波长越大条纹间距越宽：红光>蓝光>紫光（「红宽紫窄」）；白光干涉：中央亮纹为白色，两侧因各色光 Δx 不同呈彩色条纹。","link":""},{"id":"phy1910","t":"双缝干涉变形·洛埃镜：干涉区域确定","s":"看到【平面镜反射光与直射光叠加求干涉区域】","c":"想到【作对称点找虚光源，两束光重叠区才干涉，单束光区域不干涉】；警惕【镜面移动或倾斜会改变叠加区边界与虚光源位置，需重新作对称点】","src":"物一轮299.双缝干涉_笔记","note":"视频|10:23-13:46","orig":"（例）洛埃镜干涉条纹范围：作光源S关于平面镜的对称点S'（虚光源），反射光视为S'发出；直接照射光与反射光在屏上的重叠区域才是有效干涉区。","link":""},{"id":"phy1911","t":"双缝干涉变形·洛埃镜：条纹间距与介质","s":"看到【洛埃镜/等效双光源求条纹间距，或介质中条纹变化】","c":"想到【洛埃镜 d=2a 代入 $\\Delta$x=$\\lambda$L/d；介质中建立折射率$\\to$波速$\\to$波长$\\to$条纹间距的关联链（$\\lambda$'=$\\lambda$/n）】；警惕【a 与 l 含义勿混：a是光源到镜距离，l是光源到屏距离；注意 a≪l 的近似条件】","src":"物一轮299.双缝干涉_笔记","note":"视频|13:46-15:22","orig":"（例）洛埃镜条纹间距 Δx=λl/(2a)（d=2a，a为光源到镜面距离）；光进入折射率n的介质后 λ'=λ/n，条纹间距同步减小，n=λl/(2aΔx)。","link":""},{"id":"phy1912","t":"光的干涉·图样识别：干涉与衍射","s":"看到【给出图样判断是干涉还是衍射、是哪种色光】","c":"想到【先看间距均匀性分干涉/衍射，再看中央亮纹宽度与间距大小按波长排色光】；警惕【衍射图样重点观察中央亮纹是否最宽；实际图像可能有绘制误差】","src":"物一轮299.双缝干涉_笔记","note":"视频|15:22-17:40","orig":"（例）四幅图样判断红光/紫光的干涉与衍射：等间距为干涉（甲、乙），中央亮纹最宽且不等间距为衍射（丙、丁）；波长大的红光条纹更宽。","link":""},{"id":"phy1913","t":"双缝干涉·复色光与色散综合","s":"看到【干涉条纹信息反推波长，再结合棱镜色散定位光谱位置】","c":"想到【$\\Delta$x∝$\\lambda$ 由条纹间距排波长；棱镜中红光偏折最小、紫光最大】；警惕【不同波长光互不干涉、各自成独立图样；偏转角小对应折射率小、波长长】","src":"物一轮299.双缝干涉_笔记","note":"视频|23:14-28:01","orig":"（例）半反半透镜将光分为双缝干涉与三棱镜色散两路：由 Δx1>Δx2 得 λ1>λ2；棱镜折射率 n 与波长成反比（红小紫大），偏转角越小的位置对应波长越长的光。","link":""},{"id":"phy1914","t":"双缝干涉变形·洛埃镜：镜面移动的影响","s":"看到【平面镜平移/倾斜后条纹移动或疏密变化】","c":"想到【先重新作虚光源对称点，再分析 d、L 变化代入 $\\Delta$x=$\\lambda$L/d；d 不变则间距不变，只动干涉区】；警惕【镜面平移不一定改变间距，先分清「区域移动」与「间距变化」两类效果】","src":"物一轮299.双缝干涉_笔记","note":"视频|28:01","orig":"（例）平面镜倾斜/移动时重新定虚光源：左移镜面→干涉区域移动→条纹整体移动；右移（改变间距）→d 增大→Δx=λL/d 减小；水平平移不改变虚光源相对位置时条纹间距不变。","link":""},{"id":"phy1915","t":"薄膜干涉·半波损失","s":"看到【题目明确提及半波损失/相位突变，或光疏$\\to$光密界面反射】","c":"想到【在光程差中加减 $\\lambda$/2 再套干涉条件】；警惕【教材不深究原理，题目不提示就不考虑；区分「反射与辐射」类概念干扰】","src":"物一轮300.薄膜干涉_笔记","note":"视频|01:06-02:48","orig":"（知识）光从光疏介质射向光密介质时，反射光发生 π 相位突变，相当于增加 λ/2 光程差；高中阶段仅当题目明确提及时才考虑，处理方法是直接增减半个波长。","link":""},{"id":"phy1916","t":"薄膜干涉·劈尖干涉条纹间距","s":"看到【劈尖（楔形空气膜）求条纹间距或疏密】","c":"想到【间距只与波长 $\\lambda$ 和倾角 $\\theta$ 有关：$\\theta$ 越大条纹越密；与屏距、缝距无关】；警惕【与双缝干涉公式 $\\Delta$x=$\\lambda$L/d 区分，勿混用公式】","src":"物一轮300.薄膜干涉_笔记","note":"视频|02:48-13:10","orig":"（知识）劈尖干涉发生在空气膜上表面，两反射光光程差 Δx=2d（d为当地膜厚）；相邻亮纹对应 Δd=λ/2，条纹间距 Δx=λ/(2tanθ)≈λ/(2θ)（小角度近似）。","link":""},{"id":"phy1917","t":"薄膜干涉·平整度检验","s":"看到【干涉条纹弯曲判断工件表面凹凸】","c":"想到【先定劈尖薄端方向，条纹弯向薄端为凹陷、背离为凸起；也可将图样朝劈尖方向旋转90$^{\\circ}$看凹凸】；警惕【弯曲处是局部缺陷，整体平移不是缺陷；干涉由空气膜上下表面反射光形成，不是玻璃板表面】","src":"物一轮300.薄膜干涉_笔记","note":"视频|13:10-17:22","orig":"（例）标准平板与待测面间形成空气劈尖：条纹向劈尖（薄端）弯曲→该处下凹；背离劈尖弯曲→该处上凸；条纹整体平移不弯曲说明倾角未变，无局部缺陷。","link":""},{"id":"phy1918","t":"薄膜干涉·肥皂液薄膜","s":"看到【竖直肥皂膜/薄膜上疏下密的条纹】","c":"想到【条纹间距由当地倾角 $\\theta$ 决定：$\\Delta$x=$\\lambda$/(2tan$\\theta$)，疏$\\to$$\\theta$ 小、密$\\to$$\\theta$ 大；平移边界线比较夹角变化判断形状】；警惕【条纹等间距不代表膜厚均匀，只说明 $\\theta$ 处处相同】","src":"物一轮300.薄膜干涉_笔记","note":"视频|17:22-21:07","orig":"（知识）重力使肥皂液上窄下宽形成厚度梯度，白光照射各色光条纹位置不同叠加成彩色条纹；单色光下膜倾角处处相同则条纹等间距；膜形不规则时 θ 随位置变化，条纹不等间距。","link":""},{"id":"phy1919","t":"薄膜干涉·牛顿环","s":"看到【牛顿环内疏外密/中心暗斑的判断】","c":"想到【空气膜厚度不均匀：越向外 $\\theta$ 越大条纹越密；中心暗斑源于半波损失】；警惕【属薄膜干涉而非孔径衍射；高中通常忽略半波损失，除非题目提示】","src":"物一轮300.薄膜干涉_笔记","note":"视频|21:07-24:06","orig":"（知识）牛顿环由平凸透镜与平面玻璃间空气膜形成：中心因半波损失呈暗斑；边缘处 θ 增大，Δx=λ/(2tanθ) 减小，故条纹内疏外密。","link":""},{"id":"phy1920","t":"薄膜干涉·增透膜与增反膜","s":"看到【镀膜（增透/增反/防蓝光）求最小膜厚】","c":"想到【增透用相消条件、增反用相长条件；题目给真空波长需除以折射率再算 d=$\\lambda$'/(4n')】；警惕【混淆相长与相消的厚度条件；增反膜会选择性反射特定色光导致成像偏色，偏振片才能均匀减光保色】","src":"物一轮300.薄膜干涉_笔记","note":"视频|24:06-28:27","orig":"（知识）增透膜：使两反射光相消，2d=(n+1/2)λ，最小厚度 d=λ/(4n)（λ为真空中波长需先换算 λ'=λ/n）；增反膜：使反射光相长，2d=nλ；均只对特定波长有效。","link":""},{"id":"phy1921","t":"薄膜干涉·例题：热膨胀与条纹移动","s":"看到【温度变化/材料膨胀引起干涉条纹移动】","c":"想到【画图比较膨胀前后空气层形态：夹角不变而厚度增加时，等厚线整体向薄端一侧移动】；警惕【先比较两材料膨胀系数定厚度增减，再定条纹移动方向，勿凭感觉选】","src":"物一轮300.薄膜干涉_笔记","note":"视频|28:27-31:18","orig":"（例）石英环G与样品C构成劈形空气层，αC<αG，升温后G膨胀更多→空气层增厚，相同厚度位置偏移，整体条纹向一侧移动。","link":""},{"id":"phy1922","t":"薄膜干涉·例题：由条纹疏密反推膜形","s":"看到【由条纹疏密分布反推薄膜/空气层形状】","c":"想到【疏=$\\theta$ 小、密=$\\theta$ 大，逐段由 $\\Delta$x=$\\lambda$/(2tan$\\theta$) 反推倾角分布，再平移边界线验证形状】；警惕【平行边界 $\\theta$=0 无条纹；各处 $\\theta$ 相同则条纹等间距】","src":"物一轮300.薄膜干涉_笔记","note":"视频|31:18-33:13","orig":"（例）肥皂膜条纹上疏下密→Δx上大下小→θ角上小下大；用平移边界线法比较各处夹角，选 θ 上小下大的膜形。","link":""},{"id":"phy1923","t":"薄膜干涉·例题：劈尖综合判断","s":"看到【劈尖检验工件的多选项综合判断】","c":"想到【凹凸看弯曲方向（弯向薄端为凹）；波长变小条纹变密、$\\theta$ 变小条纹变疏；干涉光源是空气膜两表面】；警惕【口诀「凸向厚处是凹陷，波长变小条纹密」；勿把干涉面误认为玻璃板外表面】","src":"物一轮300.薄膜干涉_笔记","note":"视频|37:03-39:29","orig":"（例）条纹弯曲凸向劈尖方向→工件凹陷；改用紫光（波长更短）→条纹变密；抽去薄片→θ减小→条纹变疏；干涉光是空气膜上下表面反射光。","link":""},{"id":"phy1924","t":"薄膜干涉·例题：厚度变化图像判断","s":"看到【由条纹疏密变化判断 d-x 图像形状】","c":"想到【条纹间距变化↔$\\theta$ 变化↔d-x 图像斜率变化：斜率恒定则等间距，斜率变化则疏密渐变】；警惕【线性厚度变化对应恒定 $\\theta$、等间距条纹，不是渐密】","src":"物一轮300.薄膜干涉_笔记","note":"视频|39:29-42:10","orig":"（例）条纹间距逐渐增大→θ 逐渐减小→厚度 d 沿位置的变化率（图像斜率）逐渐减小，选厚度减小速率变缓的图像。","link":""},{"id":"phy1925","t":"薄膜干涉·例题：含半波损失的膜厚计算","s":"看到【判断两反射光各自是否存在半波损失后求膜厚】","c":"想到【逐面判断：光疏$\\to$光密反射有半波损失（加 $\\lambda$/2），光密$\\to$光疏没有；再按相长/相消条件列 2d 方程】；警惕【注意题给波长是真空还是介质中波长，避免重复换算】","src":"物一轮300.薄膜干涉_笔记","note":"视频|42:10","orig":"（例）增反膜：前反射（光疏→光密）有半波损失、后反射（光密→光疏）无，2d=mλ+λ/2，最小厚度 d=λ/4（λ已是介质波长，无需换算）。","link":""},{"id":"phy1926","t":"近代物理·考点权重分级","s":"看到【近代物理模块复习优先级安排】","c":"想到【以光电效应（含电路综合）为绝对核心优先突破，黑体辐射、康普顿、波粒二象性按概念记忆即可】；警惕【不要因攻克光压难题而挤占基础内容复习时间】","src":"物一轮301.【课前必看】本讲听课建议_笔记","note":"视频|00:36-01:04","orig":"（知识）近代物理（光的粒子性+原子与原子核）难度分级：黑体辐射一星（考评低）、光电效应二星（核心考点，占光学模块30%以上分值）、康普顿效应三星（次要）、波粒二象性四星（概念性）、光压问题五星（高难度建模）。","link":""},{"id":"phy1927","t":"近代物理·光电效应命题趋势","s":"看到【光电效应与其他模块综合命题的备考方向】","c":"想到【复习时把光电效应方程与电路分析（分压、正反向电压）打通训练】；警惕【光电效应单独考多是选择题选项，综合考则在电磁感应大题的电路环节】","src":"物一轮301.【课前必看】本讲听课建议_笔记","note":"视频|01:19-01:44","orig":"（知识）光电效应近年出现与电磁感应的综合题（八省联考等），解题关键是建立光电流与电路参数的关联模型；解答题常作为电磁感应大题的电路环节，约每3-5年出现一次。","link":""},{"id":"phy1928","t":"近代物理·选择题命题特点","s":"看到【光学/近代物理选择题多选项组合题】","c":"想到【按「折射率—频率—波速—波长—临界角」关联链逐项排查，一个选项只查一个子知识点】；警惕【五大量中频率决定颜色与能量，折射率与波长成反比，勿张冠李戴】","src":"物一轮301.【课前必看】本讲听课建议_笔记","note":"视频|03:26-03:39","orig":"（知识）光学选择题高频考察五大物理量综合：折射率、频率、波数（波速）、波长、临界角，四个选项常分别考查不同子知识点（如2024湖南卷）；波粒二象性常与康普顿效应组成选项对。","link":""},{"id":"phy1929","t":"黑体辐射·黑体定义与辨析","s":"看到【黑体是否反射/是否辐射的判断】","c":"想到【黑体不反射但自发辐射；吸收与辐射是两个独立概念】；警惕【「黑体」不等于黑色物体，也非不发光，空腔小孔才是理想模型】","src":"物一轮302.普朗克黑体辐射理论完整视频_笔记","note":"视频|00:36-03:51","orig":"（知识）黑体：完全吸收电磁波而不反射电磁波的理想化物体，可用带小孔的空腔近似模拟；黑体辐射是黑体自发向外辐射电磁波（区别于反射），所有物体都因分子热运动产生辐射。","link":""},{"id":"phy1930","t":"黑体辐射·实验规律","s":"看到【比较不同温度的黑体辐射曲线】","c":"想到【温度高的曲线整体在上、峰值波长更短（峰值左移）】；警惕【「温度高波长短」勿记反；各波长强度都增大而非只峰值处增大】","src":"物一轮302.普朗克黑体辐射理论完整视频_笔记","note":"视频|03:51-09:27","orig":"（知识）黑体辐射三大特征：同一温度下辐射所有波长的电磁波（连续谱）；温度越高各波长辐射强度均增大；温度升高时辐射强度峰值向短波方向移动（维恩位移定律）。","link":""},{"id":"phy1931","t":"黑体辐射·普朗克能量量子化","s":"看到【能量子/普朗克常量的概念题】","c":"想到【辐射能量一份一份，最小单位 $\\varepsilon$=hν，ν 是频率】；警惕【公式中 ν 是频率符号，勿与速度 v 混淆；能量子化针对辐射过程】","src":"物一轮302.普朗克黑体辐射理论完整视频_笔记","note":"视频|03:51-09:27","orig":"（知识）普朗克提出能量量子化假说：能量辐射不连续，最小单位 ε=hν；h=6.626×10⁻³⁴ J·s，开创量子理论先河。","link":""},{"id":"phy1932","t":"黑体辐射·图像题解题通法","s":"看到【给多条辐射强度-波长曲线判断温度/峰值】","c":"想到【两步排查：先看曲线整体高低定温度，再看峰值位置定波长长短（升温峰值向短波移）】；警惕【只需记规律不用推导；反射与辐射对曲线的影响勿混淆】","src":"物一轮302.普朗克黑体辐射理论完整视频_笔记","note":"视频|09:27-10:21","orig":"（例）黑体辐射图像判断：确认温度高低与曲线位置（温度越高整体上移）、识别峰值波长偏移方向（升温峰值左移），排除违反规律的选项，答案选符合规律的曲线。","link":""},{"id":"phy1933","t":"黑体辐射·实际应用：测温枪","s":"看到【测温枪/红外测温的生活情境题】","c":"想到【套用规律：温度升高$\\to$辐射强度增大、峰值波长变短；黑体辐射特性只与温度相关，与材料、形状无关】；警惕【混淆波长变化方向是本题最大失分点】","src":"物一轮302.普朗克黑体辐射理论完整视频_笔记","note":"视频|10:21","orig":"（例）测温枪原理题：人体温度升高→总辐射强度 I 增大，峰值波长 λ 减小，据此判断选项（答案为波长变短、强度增大的一项）。","link":""},{"id":"phy1934","t":"光电效应·现象定义与逸出方向","s":"看到【判断光电子从哪个面逸出】","c":"想到【电子从受光照射的表面飞出，从背面飞出需突破多层束缚更困难】；警惕【电子不能凭空飞出，逸出面即光照面】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|00:21-02:36","orig":"（知识）光电效应：照射金属表面的光使金属表面电子逸出的现象；光电子从光照射的那个面飞出（只需突破一层束缚），飞出的电子称光电子。","link":""},{"id":"phy1935","t":"光电效应·验电器带电判断","s":"看到【光电效应中验电器张角/带电性判断】","c":"想到【电子飞走$\\to$板与验电器整体缺电子带正电，属接触起电】；警惕【带正电的是失去电子的金属板，不是得到光的板带负电】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|02:36-03:35","orig":"（知识）金属板与验电器导线连接，电子从金属板飞出后金属板带正电，验电器因接触起电随之带正电。","link":""},{"id":"phy1936","t":"光电效应·经典理论与实验的矛盾","s":"看到【经典电磁理论无法解释光电效应的原因】","c":"想到【抓住两点矛盾：瞬时性（无延迟）与频率条件（低于截止频率照多久都不发生）】；警惕【累积做功与瞬时吸收是两种机制的本质区别】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|03:35-07:21","orig":"（知识）经典理论认为电场力对电子做功累积能量：矛盾一——效应应延迟，实际瞬时发生；矛盾二——任何光都应能发生，实际有截止频率限制。","link":""},{"id":"phy1937","t":"光电效应·截止频率","s":"看到【判断某光照是否发生光电效应】","c":"想到【只比较入射光频率与金属截止频率：够频率瞬时发生，不够频率无论强度多大、时间多长都不发生】；警惕【截止频率由金属本身决定，与入射光无关】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|07:21-08:23","orig":"（知识）截止频率（极限频率）νc：能发生光电效应的最小频率；入射光频率大于 νc 才能发生，小于则不能。","link":""},{"id":"phy1938","t":"光电效应·爱因斯坦光子说","s":"看到【解释光电效应为何瞬时/弱光长时间照射为何不发生】","c":"想到【一个电子一次吸收一个光子，能量不累积、不足即耗散】；警惕【普朗克与爱因斯坦观点的区别：辐射过程量子化 vs 光子存在本身量子化】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|08:30-11:26","orig":"（知识）光能量一份一份（光子），电子一次只吸收一个光子，能量足够则逸出、不足则以热运动耗散不累积，故效应瞬时；与普朗克区别：普朗克认为辐射量子化但能量本身连续，爱因斯坦认为能量存在本身不连续。","link":""},{"id":"phy1939","t":"光电效应·光电效应方程","s":"看到【求光电子最大初动能/逸出功/光子能量】","c":"想到【直接套 Ek=hν−W0 及其变形：ν=(Ek+W0)/h，W0=hν−Ek】；警惕【「最大」初动能对应最表层电子；单位需统一（J 与 eV）】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|11:26-16:23","orig":"（知识）Ek=hν−W0：hν 为光子能量，W0 为逸出功（由金属本身决定），Ek 为最大初动能（最外层电子克服束缚最少故动能最大）。","link":""},{"id":"phy1940","t":"光电效应·截止频率与逸出功关系","s":"看到【求截止频率或比较不同金属的 νc】","c":"想到【νc=W0/h，逸出功越大截止频率越高】；警惕【截止频率是金属属性，与入射光频率、光强均无关】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|11:26-16:23","orig":"（知识）当 Ek=0 时为临界情况：hνc=W0，即 νc=W0/h；不同金属逸出功不同，截止频率也不同。","link":""},{"id":"phy1941","t":"光电效应·例题：方程变形求频率","s":"看到【已知最大初动能和逸出功反求频率/波长】","c":"想到【方程线性变形即可，必要时结合 c=$\\lambda$ν 换算波长】；警惕【hν 中 ν 是频率；代入数据注意 10^{-19} 与 10^{-34} 量级估算】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|16:23-17:27","orig":"（例）已知 Ek 与 W0 求入射光频率：由 Ek=hν−W0 变形得 ν=(Ek+W0)/h，直接代入求解。","link":""},{"id":"phy1942","t":"光电效应·例题：由波长和初动能求截止频率","s":"看到【已知波长与最大初动能求截止频率】","c":"想到【先求 W0 再除以 h，或合并为 νc=c/$\\lambda$−Ek/h；c/$\\lambda$=3$\\times$10^{8}/300$\\times$10^{-9}=1$\\times$10^{15}Hz 这类量级估算要熟练】；警惕【波长先换米制；估算时 1.28$\\times$5≈6.4 接近 6.63 的近似技巧】","src":"物一轮303.光电效应的基本内容完整视频_笔记","note":"视频|17:27","orig":"（例）波长 300nm 光照射，Ek=1.28×10⁻¹⁹J：W0=hc/λ−Ek，νc=W0/h=c/λ−Ek/h≈1×10¹⁵−0.2×10¹⁵=8×10¹⁴Hz。","link":""},{"id":"phy1943","t":"光电效应电路·光电管与电流计","s":"看到【光电管电路中电流计有无读数的判断】","c":"想到【电流读数取决于到达阳极的光电子数，飞出$\\neq$到达】；警惕【不能默认所有光电子都形成电流】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|00:15-01:07","orig":"（知识）光照射光电管阴极K产生光电子，光电子飞出方向任意、不一定飞向阳极A；只有到达阳极A的电子才使灵敏电流计偏转。","link":""},{"id":"phy1944","t":"光电效应电路·滑动变阻器分压结构","s":"看到【光电管+滑动变阻器的分压电路求电压变化】","c":"想到【先识别分压结构：光电管电压=滑片与端点间那部分电阻的分压，滑片移动即电压增减】；警惕【电压表/光电管支路断路不影响主电路电流，别把整根变阻器当成光电管电压】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|01:17-02:37","orig":"（知识）滑动变阻器全部接入与电源串联，电压表支路与光电管支路均为断路；光电管AK电压等于变阻器左半部分分压，K接左端、A接滑片P，P右移则电压增大。","link":""},{"id":"phy1945","t":"光电效应电路·正向电压与饱和电流","s":"看到【正向电压增大光电流变化/求饱和电流决定因素】","c":"想到【饱和电流由光强（单位时间光子数）决定，与频率无关；电压再大电流也不再增大】；警惕【「强黄光饱和电流大于弱黄光」——同频率比光强才影响饱和电流】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|02:37-10:14","orig":"（知识）正向电压促进电子到达A极：滑片右移电压增大、电流增大但趋于最大值——饱和电流；原因是单位时间产生的光电子总数有限（一个光子最多激发一个光电子）。同种色光下光强越大，单位时间光子数越多，饱和电流越大。","link":""},{"id":"phy1946","t":"光电效应电路·反向电压与遏止电压","s":"看到【求遏止电压/判断遏止电压的影响因素】","c":"想到【eUc=hν−W0：遏止电压只由频率（和金属）决定，与光强无关】；警惕【遏止电压消耗的是最大初动能；蓝光遏止电压大于黄光因频率更高】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|12:13-16:13","orig":"（知识）反向电压阻碍电子到达A极：电压增大电流减小，恰好为零时的电压为遏止电压 Uc；eUc=Ekmax=hν−W0；同种金属频率越大遏止电压越大，同频率（同色光）强弱不同遏止电压相同。","link":""},{"id":"phy1947","t":"光电效应电路·正反向电压判别通法","s":"看到【电路图/开关位置判断加速还是减速电场】","c":"想到【先标电源正负极$\\to$定A、K电势高低$\\to$定电场力方向对电子加速还是减速】；警惕【电子带负电，受力方向与电场方向相反，勿直接按场向判断】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|16:13-20:07","orig":"（知识）判断加的是正向还是反向电压：看A、K两极电势高低与电场方向——A极电势高为正向（加速），K极电势高为反向（减速）；开关接不同触点即改变正负极接法。","link":""},{"id":"phy1948","t":"光电效应电路·例题：逸出功与截止频率求解","s":"看到【用遏止电压表示逸出功/截止频率】","c":"想到【联立 eUc=Ekmax 与 hν=Ekmax+W0 两条关系即可互推任意量】；警惕【光强只改饱和电流不改遏止电压；滑片不动电压表示数不变】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|16:13-20:07","orig":"（例）由遏止电压 U1 与入射光频率 ν1：hν1=Ekmax+W0，Ekmax=eU1，得 W0=hν1−eU1，截止频率 νc=ν1−eU1/h；增光强不影响遏止电压，改高频率光则遏止电压变大。","link":""},{"id":"phy1949","t":"光电效应·图像：Uc-ν 直线","s":"看到【Uc-ν 图像求斜率/截距/截止频率】","c":"想到【斜率是 h/e、横截距即截止频率（Uc=0 处）】；警惕【图线不过原点，横轴交点不是(0,0)；斜率不是h本身；光强不影响图线】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|20:07-24:41","orig":"（例）由 eUc=hν−W0 得 Uc=(h/e)ν−W0/e：斜率 k=h/e（非h），纵截距为负值 −W0/e，图线与横轴交点为截止频率（由图读出约5.5×10¹⁴Hz）。","link":""},{"id":"phy1950","t":"光电效应·图像：Ek-1/λ 直线与截止波长","s":"看到【Ek-(1/$\\lambda$) 图像或问截止波长是最大还是最小】","c":"想到【由两点求斜率得 hc=E$\\lambda$0，h=E$\\lambda$0/c；$\\lambda$0 为最大波长，波长大于 $\\lambda$0（频率低于 νc）不发生效应】；警惕【截距分析：纵截距为 −W0 而非 −E；斜率是 hc 不是 E$\\lambda$0】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|24:41-31:26","orig":"（例）Ek=hc·(1/λ)−W0：斜率 k=hc，纵截距 −W0；图线与横轴交点 1/λ0 对应 Ek=0，λ0 是能发生光电效应的最大波长（截止波长）；判断600nm光（ν=5×10¹⁴Hz）小于截止频率不能发生效应。","link":""},{"id":"phy1951","t":"光电效应·图像：I-U 曲线比较三束光","s":"看到【多条光电流-电压曲线比较频率与光强】","c":"想到【两看：反向区看遏止电压定频率，正向区看饱和电流定光强（光子数）】；警惕【光电子数与频率无关；光电效应瞬时发生，各光逸出时间间隔无差异】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|31:26-34:34","orig":"（例）三条 I-U 曲线：遏止电压相同→最大初动能相同→频率相同；饱和电流大→光强强、单位时间逸出光电子数多；甲乙频率相同但甲饱和电流更大，故甲光更强。","link":""},{"id":"phy1952","t":"光电效应·图像：Ekm-U 双材料比较","s":"看到【不同金属在相同光照下的 Ekm-U（或Ekm随电压）图线比较】","c":"想到【斜率由电荷量 e 决定必相同，截距由 νc 决定：截止频率越大截距越小、图线越低】；警惕【用动能定理 Ekm−Ek0=eU 与光电效应方程联立，勿直接比较初动能】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|34:34-38:34","orig":"（例）两材料截止频率 ν1<ν2，同一入射光：Ekm=eU+(hν−hνc)，斜率均为 e 相同；ν2 大→截距 hν−hν2 更小→材料2图线更低。","link":""},{"id":"phy1953","t":"光电效应·三大量对应关系总结","s":"看到【区分「光强决定什么、频率决定什么、材料决定什么」】","c":"想到【一图记牢：光强$\\to$饱和电流；频率$\\to$遏止电压/最大初动能；材料（W0）$\\to$截止频率】；警惕【截止频率大的金属，同频率光下遏止电压反而更小】","src":"物一轮304.光电效应与电路综合完整视频_笔记","note":"视频|38:34","orig":"（知识）饱和光电流与光强（单位时间光子数）有关；遏止电压与入射光频率有关、与光强无关；截止频率由金属逸出功决定，与入射光无关；截止频率越大逸出功越大，相同频率下遏止电压越小。","link":""},{"id":"phy1954","t":"原子物理·康普顿效应现象","s":"看到【散射光中出现波长变大的部分】","c":"想到【康普顿效应：光子与电子碰撞，光子动量减小，由p=h/$\\lambda$知波长变大，体现光的粒子性】；警惕【经典受迫振动理论预测散射光频率不变、波长不变，无法解释波长变大部分】","src":"物一轮305.康普顿效应_笔记","note":"视频|00:04-00:59","orig":"（知识）用X射线照射石墨，散射光中出现波长变大的部分（λ>λ₀）","link":""},{"id":"phy1955","t":"原子物理·经典理论的矛盾","s":"看到【用经典波动理论解释散射却与实验矛盾】","c":"想到【需引入光的粒子性：光子不仅具有能量E=hν，还具有动量p=h/$\\lambda$】；警惕【矛盾点在波长变化，经典理论预测$\\lambda$=$\\lambda$_{0}与实际$\\lambda$>$\\lambda$_{0}不符】","src":"物一轮305.康普顿效应_笔记","note":"视频|00:59-03:05","orig":"（知识）经典理论：入射电磁波引起带电微粒受迫振动产生散射光，频率应等于入射光频率","link":""},{"id":"phy1956","t":"原子物理·光子动量公式推导","s":"看到【推导光子动量p与波长$\\lambda$的关系】","c":"想到【推导链条：E=hν$\\to$E=hc/λ$\\to$p=E/c=h/$\\lambda$，光子动量p=h/$\\lambda$】；警惕【p=h/$\\lambda$与E=hν同时适用于光子和实物粒子，是波粒二象性的桥梁】","src":"物一轮305.康普顿效应_笔记","note":"视频|03:05-06:58","orig":"（知识）由E=hν、ν=c/λ得E=hc/λ，结合E=mc²得m=E/c²，故p=mc=E/c=h/λ","link":""},{"id":"phy1957","t":"原子物理·康普顿碰撞模型","s":"看到【光子与电子碰撞后发生散射】","c":"想到【碰撞过程动量守恒，光子把部分动量传给电子，p减小则$\\lambda$增大】；警惕【康普顿效应强调动量守恒的碰撞，与光电效应共同支持光的粒子性，但更突出动量守恒】","src":"物一轮305.康普顿效应_笔记","note":"视频|03:05-06:58","orig":"（知识）光子与石墨中电子碰撞，光子动量减小，p=h/λ中h不变，故λ增大","link":""},{"id":"phy1958","t":"原子物理·电磁波参量比较","s":"看到【比较两种波长（或频率）电磁波的频率、能量、动量、速度】","c":"想到【链式判断：$\\lambda$大$\\to$ν小$\\to$E=hν小$\\to$p=h/$\\lambda$小；真空中所有电磁波传播速度均为c】；警惕【速度永远是光速c，不要因波长不同而认为速度不同】","src":"物一轮305.康普顿效应_笔记","note":"视频|06:58","orig":"（例）真空中波长21cm与18cm辐射比较频率、能量、动量、传播速度，答案BC","link":""},{"id":"phy1959","t":"原子物理·光的波粒二象性含义","s":"看到【判断「有的光是波，有的光是粒子」类说法】","c":"想到【光在任何时候都同时具有波动性和粒子性，只是不同条件下某一种特性表现得更突出】；警惕【两大误区：不同光有不同属性、不同时刻有不同属性，均错误】","src":"物一轮306.波粒二象性_笔记","note":"视频|01:34-04:21","orig":"（知识）光同时具有波动性和粒子性，并非一部分光是波、另一部分是粒子，也不是有时是波有时是粒子","link":""},{"id":"phy1960","t":"原子物理·波动性与粒子性突出条件","s":"看到【判断大量/少量光子或波长长短时突出何种性质】","c":"想到【数量维度：大量光子集体行为$\\to$波动性突出，个别光子$\\to$粒子性突出；波长维度：波长越大越易衍射$\\to$波动性，波长越小$\\to$粒子性】；警惕【典型现象对应：干涉衍射偏振是波动性，光电效应康普顿效应是粒子性】","src":"物一轮306.波粒二象性_笔记","note":"视频|01:34-04:21","orig":"（知识）大量光子、波长较大（频率较小）时波动性突出；少量光子、波长较小（频率较大）时粒子性突出","link":""},{"id":"phy1961","t":"原子物理·双缝干涉与概率波","s":"看到【少量光子逐个通过双缝，屏上先出现散点后出现条纹】","c":"想到【光是概率波：单个光子落点随机，概率大处形成亮条纹、概率小处形成暗条纹，条纹是大量光子的统计结果】；警惕【紫外光肉眼不可见但可通过荧光效应观察，仍能做该实验】","src":"物一轮306.波粒二象性_笔记","note":"视频|04:21-08:16","orig":"（例）极微弱光双缝干涉：少量光子屏上杂乱散点，大量光子形成明暗相间条纹，答案ABD","link":""},{"id":"phy1962","t":"原子物理·物质波（德布罗意波）","s":"看到【实物粒子（电子、质子等）的波长或频率计算】","c":"想到【德布罗意关系：$\\lambda$=h/p、ν=$\\varepsilon$/h，与光子公式形式相同，是波粒二象性的数学桥梁】；警惕【电子衍射图样、电子干涉条纹是实物粒子波动性的实验证据】","src":"物一轮306.波粒二象性_笔记","note":"视频|08:40-09:46","orig":"（知识）一切实物粒子也具有波动性：v=ε/h（能量对应频率），λ=h/p（动量对应波长）","link":""},{"id":"phy1963","t":"原子物理·宏观物体波动性","s":"看到【问宏观物体为何观察不到波动性】","c":"想到【波长极短远小于障碍物尺度，衍射等波动现象难以观测，主要表现粒子性，但理论上仍具有波动性】；警惕【不是宏观物体没有波动性，而是波动性不明显、难以观测】","src":"物一轮306.波粒二象性_笔记","note":"视频|09:46-11:50","orig":"（知识）h约10⁻³⁴数量级，宏观物体动量p很大，物质波波长极短（约10⁻³⁴m量级），远小于原子尺度","link":""},{"id":"phy1964","t":"原子物理·光电效应与物质波综合","s":"看到【由双缝干涉条纹间距$\\Delta$x反推实物粒子动量或动能】","c":"想到【链条：$\\Delta$x=$\\lambda$L/d$\\to$λ=d$\\Delta$x/L$\\to$p=h/$\\lambda$=hL/(d$\\Delta$x)$\\to$Ek=p^{2}/2m；光子能量E=W_{0}+Ek】；警惕【动能含平方Ek=p^{2}/2m不要漏平方；光子动量p=E/c，分母不要多乘h】","src":"物一轮306.波粒二象性_笔记","note":"视频|13:10-22:19","orig":"（例）紫外线照射材料产生电子束，经双缝干涉，由Δx=λL/d反推电子动量p=hL/(dΔx)，答案AD","link":""},{"id":"phy1965","t":"原子物理·电子逐个发射双缝干涉","s":"看到【问电子能否一个一个发射形成干涉图样】","c":"想到【单个电子落点随机，大量电子累积仍形成干涉图样，不需要成对同时通过双缝】；警惕【数量级估算：10^{-34}/10^{-23}=10^{-11}，可将9.1近似为9简化计算】","src":"物一轮306.波粒二象性_笔记","note":"视频|22:19-27:27","orig":"（例）电子动量1.2×10⁻²³kg·m/s，λ=h/p≈5.5×10⁻¹¹m，Ek=p²/2m≈8.0×10⁻¹⁷J，答案BD","link":""},{"id":"phy1966","t":"原子物理·德布罗意波长比","s":"看到【两粒子动能（或动量）相同，比较德布罗意波长之比】","c":"想到【动能相同：Ek=p^{2}/2m$\\to$p=√(2mEk)$\\to$λ∝1/√m，波长比等于质量反比的平方根；动量相同则$\\lambda$=h/p直接反比】；警惕【油滴质量需由密度和体积（球形4$\\pi$r^{3}/3）计算，估算时$\\pi$可近似为3约分】","src":"物一轮306.波粒二象性_笔记","note":"视频|27:27-32:58","orig":"（例）电子与油滴动能相同，λ∝1/√m，波长比λ₁/λ₂=√(m₂/m₁)，数量级10⁸，答案C","link":""},{"id":"phy1967","t":"原子物理·碰撞与物质波结合","s":"看到【粒子碰撞（结合）后求新粒子的物质波波长】","c":"想到【粒子性用动量守恒p_{1}+p_{2}=p，波动性用p=h/$\\lambda$把动量换成波长，约去h解出$\\lambda$】；警惕【同向正碰动量相加对应1/$\\lambda$相加，方向相反时动量相减】","src":"物一轮306.波粒二象性_笔记","note":"视频|32:58","orig":"（例）中子（λ₁）与氘核（λ₂）同向正碰结合成氚核，动量守恒得1/λ₁+1/λ₂=1/λ，λ=λ₁λ₂/(λ₁+λ₂)，答案A","link":""},{"id":"phy1968","t":"近代物理·光压定义与模型","s":"看到【求光照射物体表面产生的压强（光压）】","c":"想到【构造柱状（流体）模型：研究极短时间$\\Delta$t内打到表面上的光子群，从光的粒子性出发用动量定理】；警惕【多数题目光压定义为压强，若题目定义为压力则按压强乘面积计算】","src":"物一轮307.光压问题_笔记","note":"视频|01:48-02:58","orig":"（知识）光压是光对物体单位面积的压力（即压强）；将一束光视为柱状流体模型，光子像小物块持续撞击物体表面","link":""},{"id":"phy1969","t":"近代物理·动量定理求光压","s":"看到【光子被表面吸收/反射（或给定吸收率、反射率）求光压】","c":"想到【动量定理PS·$\\Delta$t=N·$\\Delta$p；全吸收$\\Delta$p=p，全反射$\\Delta$p=2p；给定吸收率$\\eta$：$\\Delta$p=$\\eta$p+(1-$\\eta$)2p，给定反射率$\\eta$：$\\Delta$p=$\\eta$·2p+(1-$\\eta$)p】；警惕【吸收率与反射率对应的$\\Delta$p公式不同，看清题给比例的含义】","src":"物一轮307.光压问题_笔记","note":"视频|02:58-08:55","orig":"（知识）F·Δt=N·Δp，F=PS；全吸收Δp=p=h/λ，全反射Δp=2p，吸收率η时Δp=ηp+(1-η)2p","link":""},{"id":"phy1970","t":"近代物理·发射光子功率模型","s":"看到【求定向光束（激光）或点光源（太阳）的发光功率与光子数】","c":"想到【能量守恒：P·$\\Delta$t=N·hν，单位时间发射光子数n=P/hν；定向光用柱状模型，各向同性辐射用球面模型】；警惕【球面模型中远处物体只接收到总能量的一部分，不是全部功率】","src":"物一轮307.光压问题_笔记","note":"视频|09:13-10:21","orig":"（知识）定向发射（如激光）用柱状模型；点光源向四面八方均匀辐射用球面模型，单位面积功率P₀/4πR²","link":""},{"id":"phy1971","t":"近代物理·球面模型接收功率","s":"看到【求天体辐射到达某行星（或接收器）的功率】","c":"想到【接收功率=辐射强度P_{0}/(4$\\pi$r^{2})$\\times$有效接收面积；有效面积是与光线垂直的投影面积（大圆面积$\\pi$R^{2}）】；警惕【接收面积取投影面积而非半球表面积，类比磁通量的有效面积】","src":"物一轮307.光压问题_笔记","note":"视频|10:21-13:30","orig":"（知识）太阳总功率P₀均匀分布在半径R球面上，地球接收功率=P₀/(4πR²)×πr₀²（投影面积）","link":""},{"id":"phy1972","t":"近代物理·地球接收太阳能与光压综合","s":"看到【光子全吸收时求光对物体的作用力】","c":"想到【动量方程F·$\\Delta$t=N·p与能量方程P_{0}·$\\Delta$t=N·E相除消去N和$\\Delta$t，利用E=pc得F=P_{0}/c】；警惕【E=pc是关联光子动量与能量的关键，联立相除消元是通用套路】","src":"物一轮307.光压问题_笔记","note":"视频|13:30-20:20","orig":"（例）日地距离r=ct=1.5×10¹¹m，地球接收功率P₀≈1.7×10¹⁷W；全吸收时光压作用力F=P₀/c≈5.7×10²N","link":""},{"id":"phy1973","t":"近代物理·天体发射功率反推","s":"看到【已知接收器每秒接收光子数和接收效率，反推天体总发射功率】","c":"想到【接收功率N·hν$\\to$除以效率$\\eta$得射向接收器的功率$\\to$等于P/(4$\\pi$L^{2})$\\times$$\\pi$R^{2}，反解总功率P】；警惕【效率$\\eta$小于1时发射功率要除以$\\eta$而不是乘】","src":"物一轮307.光压问题_笔记","note":"视频|20:20-25:45","orig":"（例）天眼每秒接收N个光子（能量hν），接收效率η，天体总功率P=4NL²hν/(R²η)，答案A","link":""},{"id":"phy1974","t":"近代物理·光压表达式推导","s":"看到【部分反射部分吸收（反射比例K）时推导光压表达式】","c":"想到【每个光子平均动量变化(1+K)p，动量方程p压·S·$\\Delta$t=N(1+K)p与能量方程P_{0}S$\\Delta$t=N·E相除，得光压=(1+K)P_{0}/c】；警惕【全吸收K=0时光压=P_{0}/c，全反射K=1时光压=2P_{0}/c，可作检验】","src":"物一轮307.光压问题_笔记","note":"视频|25:45","orig":"（例）太阳帆反射比例K、吸收比例1-K，联立动量定理与能量关系得光压p=(1+K)P₀/c","link":""},{"id":"phy1975","t":"原子物理·阴极射线性质判断","s":"看到【判断阴极射线（或某射线）是粒子流还是波、带什么电】","c":"想到【粒子流还是波：看能否发生衍射（障碍物后阴影=粒子流，屏上亮斑=波）；电性：加电场或磁场看偏转方向，磁场用左手定则】；警惕【汤姆孙的结论：原子不是最小结构，内部存在带负电的电子】","src":"物一轮309.电子的发现与核式结构模型_笔记","note":"视频|00:25-08:50","orig":"（知识）汤姆孙用阴极射线管发现电子：路径上放小十字障碍物，屏现阴影说明无衍射→粒子流；加电场或磁场观察偏转判断电性","link":""},{"id":"phy1976","t":"原子物理·汤姆孙枣糕模型","s":"看到【枣糕模型（葡萄干面包/西瓜模型）】","c":"想到【汤姆孙模型：正电荷均匀分布的实心球+电子镶嵌其中，首次提出原子内部有结构】；警惕【该模型后被卢瑟福$\\alpha$粒子散射实验推翻，无法解释大角度偏转】","src":"物一轮309.电子的发现与核式结构模型_笔记","note":"视频|00:25-08:50","orig":"（知识）原子是球体，带正电部分均匀分布于整个球内，电子镶嵌其中（枣糕/葡萄干面包/西瓜/曲奇模型）","link":""},{"id":"phy1977","t":"原子物理·α粒子散射实验现象","s":"看到【$\\alpha$粒子散射实验的三类现象（绝大多数/少数/极少数）】","c":"想到【绝大多数通过$\\to$原子内部绝大部分是空的；少数大角度偏转$\\to$存在质量大带正电的核产生库仑斥力；极少数被弹回$\\to$原子核质量极大】；警惕【偏转原因是原子核的库仑斥力，不是电子吸引（电子质量太小无法改变$\\alpha$粒子运动状态）】","src":"物一轮309.电子的发现与核式结构模型_笔记","note":"视频|09:11-16:36","orig":"（知识）绝大多数α粒子沿原方向前进，少数发生大角度偏转，极少数偏转超过90°甚至被弹回","link":""},{"id":"phy1978","t":"原子物理·核式结构模型","s":"看到【卢瑟福核式结构模型的内容或电子绕核运动的原因】","c":"想到【库仑引力提供电子做圆周运动的向心力；$\\alpha$粒子越靠近核库仑斥力越大、偏转越明显，越远则轨迹越接近直线】；警惕【原子核体积很小但质量几乎全部集中，原子尺度10^{-10}m而核仅10^{-15}m量级】","src":"物一轮309.电子的发现与核式结构模型_笔记","note":"视频|16:36-18:04","orig":"（知识）原子核位于中心，体积很小但几乎占有全部质量、带正电；电子绕核运动，库仑引力提供向心力","link":""},{"id":"phy1979","t":"原子物理·散射轨迹与能量分析","s":"看到【分析$\\alpha$粒子靠近又远离原子核过程中的力、加速度、电势能变化】","c":"想到【F=kQq/r^{2}随距离先减后增再减，加速度同步变化；靠近过程斥力做负功电势能增大，远离过程做正功电势能减小】；警惕【题目常问「不正确」选项，注意审题】","src":"物一轮309.电子的发现与核式结构模型_笔记","note":"视频|18:04-21:09","orig":"（例）α粒子沿轨迹2运动：库仑斥力与距离平方成反比，先增后减，加速度同步；电势能先增后减，D错误","link":""},{"id":"phy1980","t":"原子物理·散射示意图判断","s":"看到【选择正确反映$\\alpha$粒子散射结果的轨迹示意图】","c":"想到【正确图景：靠近核弯折明显、正对核被弹回、远离核近似直线】；警惕【排除所有粒子直线通过、正对核未被弹回、外围轨迹弯折过大的图】","src":"物一轮309.电子的发现与核式结构模型_笔记","note":"视频|21:09-22:38","orig":"（例）选D：越靠近原子核轨迹弯折越明显，正对核的α粒子被弹回，远离核的轨迹近似直线","link":""},{"id":"phy1981","t":"原子物理·核式结构模型缺陷","s":"看到【问卢瑟福核式结构模型（经典理论）的缺陷】","c":"想到【两大矛盾：①电子辐射能量减少最终坠核，与原子稳定性矛盾；②经典预测连续光谱与实际线状光谱矛盾】；警惕【玻尔模型正是通过轨道量子化和定态假设解决这两大缺陷】","src":"物一轮309.电子的发现与核式结构模型_笔记","note":"视频|22:47-26:18","orig":"（知识）缺陷一：经典理论下电子辐射电磁波能量减少→轨道减小→坠入原子核，原子不稳定；缺陷二：辐射应为连续光谱，实际观测为线状光谱","link":""},{"id":"phy1982","t":"原子物理·光谱分类","s":"看到【区分连续光谱、线状谱、吸收光谱及其产生条件】","c":"想到【发射光谱含连续谱（炽热固体/液体/高压气体）与线状谱（原子/稀薄气体/金属蒸汽）；吸收光谱是连续谱经低温气体出现暗线】；警惕【太阳光谱是吸收光谱：内部炽热光源+外层低温气体吸收特定波长】","src":"物一轮309.电子的发现与核式结构模型_笔记","note":"视频|26:18","orig":"（知识）连续光谱：炽热固体、液体或高压气体发光；线状光谱：原子、稀薄气体或金属蒸汽发光；吸收光谱：连续光谱通过低温气体出现暗线（如太阳光谱）","link":""},{"id":"phy1983","t":"原子物理·轨道量子化与定态","s":"看到【玻尔模型与卢瑟福模型的区别】","c":"想到【玻尔提出轨道和能量量子化：电子只在特定轨道运动且不辐射电磁波（定态），解决原子稳定性问题】；警惕【定态不辐射电磁波是大胆假设，没有经典物理的推导依据】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|00:33-01:47","orig":"（知识）电子只能在特定分立轨道上运动，处于定态时原子有确定的能量值（能级）；卢瑟福模型半径连续，玻尔模型不连续","link":""},{"id":"phy1984","t":"原子物理·能级与能量正负","s":"看到【判断氢原子处于哪一能级时最稳定/最不稳定】","c":"想到【轨道越高（n越大）能量越高越不稳定；能量越负越低越稳定，基态n=1能量-13.6eV最稳定】；警惕【能级单位是eV不是J，计算时注意换算1eV=1.6$\\times$10^{-19}J】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|02:02-04:17","orig":"（知识）能级单位用eV（1eV=1.6×10⁻¹⁹J）；能量均为负值（以无穷远处势能为零），越负能量越低越稳定；基态n=1为-13.6eV","link":""},{"id":"phy1985","t":"原子物理·能级能量公式","s":"看到【求氢原子第n能级的能量】","c":"想到【En=E_{1}/n^{2}，由基态能量-13.6eV除以n^{2}快速得各能级能量】；警惕【n=2是-3.4eV、n=3约-1.51eV，负号不要丢】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|04:17-04:39","orig":"（知识）En=E₁/n²：E₁=-13.6eV，E₂=-3.4eV，E₃≈-1.51eV","link":""},{"id":"phy1986","t":"原子物理·跃迁规律","s":"看到【电子跃迁时辐射或吸收光子能量的计算】","c":"想到【光子能量hν=$\\Delta$E=E高-E低；能级差分立导致光子能量与频率不连续，完美解释氢原子线状光谱】；警惕【从高到低辐射光子、从低到高需吸收能量，方向别搞反】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|05:25-06:02","orig":"（知识）高→低跃迁辐射光子，低→高跃迁吸收光子，hν=ΔE=E高-E低；能级差分立故光谱为线状光谱","link":""},{"id":"phy1987","t":"原子物理·光谱线系","s":"看到【某线系（如巴尔末系、莱曼系）的谱线来源判断】","c":"想到【线系=从各激发态向同一低能级跃迁产生的一组谱线：向n=1是莱曼系、向n=2是巴尔末系，公式中低能级数对应替换】；警惕【线系名称与公式通常在题干给出，理解含义即可，无需死记】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|16:04-18:01","orig":"（知识）莱曼系（→n=1）、巴尔末系（→n=2）、帕邢系（→n=3）、布拉开系（→n=4）；巴尔末公式1/λ=R(1/2²-1/n²)","link":""},{"id":"phy1988","t":"原子物理·谱线能量与跃迁条件","s":"看到【比较两条谱线的能量、频率、波长或判断能否使某态氢原子跃迁】","c":"想到【能量大$\\to$频率高$\\to$波长短；判断跃迁先确认原子当前所处能级，光子能量须恰好等于该能级到目标能级的差】；警惕【2.55eV虽等于n=2到n=4的能级差，但对基态（n=1）氢原子无效，别套错初始能级】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|18:01-21:33","orig":"（例）Hα（n=3→n=2，1.89eV）与Hβ（n=4→n=2，2.55eV）比较：Hα能量小频率低波长长；2.55eV不能使基态氢原子跃迁，答案BD","link":""},{"id":"phy1989","t":"原子物理·一群氢原子辐射种类","s":"看到【大量（或一个）处于n能级的氢原子向低能级跃迁，问辐射光子种类数】","c":"想到【一群氢原子最多辐射Cn^{2}种频率，一个氢原子最多n-1种；再逐条计算各跃迁的能级差与给定临界能量比较】；警惕【区分「一个」与「一群」是解题关键：前者线性递减，后者组合数】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|21:33-24:00","orig":"（例）大量n=3氢原子最多辐射C₃²=3种频率光，其中能量大于3.11eV的（12.09eV和10.2eV）为紫外光，共2种，答案B","link":""},{"id":"phy1990","t":"原子物理·跃迁与光电效应干涉综合","s":"看到【跃迁辐射的光结合光子动量、光电效应、双缝干涉多考点综合】","c":"想到【光子动量p=hν/c=(E高-E低)/c；光电效应Ek=hν-W_{0}，两光最大初动能之差=h(ν_{1}-ν_{2})恰为第三种光子能量；条纹间距$\\Delta$x=L$\\lambda$/d=Lc/(dν)】；警惕【1/ν_{31}-1/ν_{21}$\\neq$1/ν_{32}，倒数差不能合并；动量p=E/c分母是c不是hc】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|24:00-30:15","orig":"（例）n=3氢原子辐射三种光：p=(E₃-E₁)/c；两光最大初动能之差=hv₃₂；条纹间距之差≠Lc/d·1/v₃₂，答案B","link":""},{"id":"phy1991","t":"原子物理·激发光子能量的分类讨论","s":"看到【给基态氢原子吸收某能量后，判断辐射光中是否包含特定波段（蓝光/紫光）】","c":"想到【逐一假设激发到的能级n，列出向下跃迁所有可能的光子能量，与给定波段范围逐条比对；用En=E_{1}/n^{2}算吸收与辐射能量】；警惕【能量$\\geq$电离能13.6eV时原子被电离，不再发生跃迁辐射；「有蓝光且无紫光」需同时满足】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|30:15-38:05","orig":"（例）蓝光2.53~2.76eV、紫光2.76~3.10eV，基态氢原子激发后辐射蓝光不辐射紫光：激发到n=4（吸收12.75eV）符合，答案C","link":""},{"id":"phy1992","t":"原子物理·吸收的两种方式","s":"看到【原子吸收光子或被电子碰撞而跃迁的条件】","c":"想到【吸收光子：能量必须恰好等于能级差，不满足则不吸收；电子碰撞：提供能量大于等于能级差即可】；警惕【两种吸收方式条件不同，光子能量「大于」能级差时不能发生跃迁】","src":"物一轮310.玻尔的原子模型完整视频_笔记","note":"视频|38:05","orig":"（知识）以光子形式吸收：能量必须恰好等于能级差；以碰撞形式吸收：能量只需大于或等于能级差","link":""},{"id":"phy1993","t":"原子核·三种射线","s":"看到【三种射线在磁场中偏转方向或本质、带电性判断】","c":"想到【$\\alpha$是氦核带正电、$\\beta$是电子带负电、$\\gamma$是光子不带电；磁场中$\\alpha$与$\\beta$反向偏转、$\\gamma$不偏转，用左手定则判方向】；警惕【$\\alpha$粒子即氦核：2个质子+2个中子，电荷数2、质量数4】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|00:57-04:50","orig":"（知识）α射线是氦核（²⁴He）带正电，β射线是电子带负电，γ射线是光子不带电；速度约0.1c、0.99c、c","link":""},{"id":"phy1994","t":"原子核·穿透性与电离性","s":"看到【比较三种射线的穿透性或电离性强弱】","c":"想到【两者规律相反：穿透性$\\gamma$>$\\beta$>$\\alpha$，电离性$\\alpha$>$\\beta$>$\\gamma$；记忆逻辑：更像波（$\\gamma$）穿透性强，更像粒子（$\\alpha$）通过碰撞电离性强】；警惕【记住一个规律即可推出另一个，别记混方向】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|00:57-04:50","orig":"（知识）穿透性：γ最强（可穿透几厘米铅板）>β（几毫米铝板）>α（一张纸）；电离性相反：α最强、γ最弱","link":""},{"id":"phy1995","t":"原子核·两种衰变本质","s":"看到【写$\\alpha$衰变、$\\beta$衰变方程或问$\\beta$衰变电子的来源】","c":"想到【$\\alpha$衰变放^{4}_{2}He，$\\beta$衰变放^{0}_{-1}e；$\\beta$衰变电子是核内中子转变生成（n$\\to$p+e），不是核外电子】；警惕【$\\gamma$射线是衰变过程伴随产生的能量，不单独对应衰变方程，通常不写出】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|04:50-10:49","orig":"（知识）α衰变：质量数-4、质子数-2，核内2质子2中子打包成氦核放出；β衰变：核内中子→质子+电子，质量数不变质子数+1","link":""},{"id":"phy1996","t":"原子核·半衰期概念","s":"看到【判断半衰期的影响因素或单个/少量原子核的说法】","c":"想到【半衰期是统计概念，只对大量原子核有意义；高温高压、化学环境均不影响】；警惕【三个错误说法：单个核「衰变一半」、10个核太少无法确定、两个半衰期不是全部衰变完】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|10:49-17:46","orig":"（知识）半衰期由原子核本身决定，与温度、压强、酸碱等理化环境无关；是大量原子核的统计概念","link":""},{"id":"phy1997","t":"原子核·半衰期计算","s":"看到【求经过时间t后放射性元素的剩余质量（数目）】","c":"想到【m=m_{0}(1/2)^(t/T)；从任意比例衰变到其一半所需的时间即为一个半衰期】；警惕【指数是t/T，剩余比例按(1/2)ⁿ递减而非线性减少】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|10:49-17:46","orig":"（知识）m剩=m原×(1/2)ⁿ，n=经历时间/半衰期；经1/2/3个半衰期剩1/2、1/4、1/8","link":""},{"id":"phy1998","t":"原子核·核反应方程双守恒","s":"看到【核反应方程配平或判断未知粒子】","c":"想到【双守恒配平：质量数、电荷数分别列守恒式解出未知粒子；反应物1个是天然衰变，2个是人工核反应（粒子轰击）】；警惕【裂变方程中反应物与生成物的中子不能相互抵消，否则改变反应的物理含义】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|18:04-18:59","orig":"（知识）核反应方程必须满足质量数（左上角）和质子数（左下角）双守恒；天然衰变一变二，人工核反应二变多","link":""},{"id":"phy1999","t":"原子核·常见核反应类型","s":"看到【区分天然衰变、人工核反应、重核裂变、轻核聚变】","c":"想到【人工核反应用粒子轰击（反应物2个）；裂变是中子轰击重核且放出中子形成链式反应；聚变是轻核结合成较重的核】；警惕【常见方程无需死记，会双守恒配平并识别类型即可】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|18:59-22:03","orig":"（知识）发现质子：¹⁴₇N+⁴₂He→¹⁷₈O+¹₁H；发现中子：⁹₄Be+⁴₂He→¹²₆C+¹₀n；裂变：中子轰击U-235产生3个中子（链式反应）；聚变：²₁H+³₁H→⁴₂He+¹₀n","link":""},{"id":"phy2000","t":"原子核·衰变次数计算","s":"看到【求一系列$\\alpha$、$\\beta$衰变中$\\beta$粒子（电子）总数】","c":"想到【设$\\alpha$衰变m次、$\\beta$衰变n次，由质量数守恒先解m，再由质子数守恒解n；图像法：坐标图中向右下移动（质子+1中子-1）的次数即$\\beta$衰变次数】；警惕【先列质量数守恒解$\\alpha$次数更简便，两方程联立勿遗漏】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|22:23-28:21","orig":"（例）²³⁸₉₂X→²⁰⁶₈₂Y：质量数守恒238=206+4m，质子数守恒92=82+2m-n，得m=8、n=6","link":""},{"id":"phy2001","t":"原子核·半衰期图像计算","s":"看到【由剩余比例-时间图像求半衰期】","c":"想到【找两个时刻使剩余比例恰为一半关系（如2/3$\\to$1/3），时间差就是一个半衰期；或公式法两式相除消元】；警惕【不必从原始量算起，任意比例减半所经时间都是半衰期】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|28:21-32:40","orig":"（例）剩余2/3（67.3天）衰变到1/3（182.4天）恰为衰变一半，T=182.4-67.3=115.1天，答案C","link":""},{"id":"phy2002","t":"原子核·半衰期比较与衰变产物","s":"看到【比较两种不同半衰期元素经相同时间后的剩余数目】","c":"想到【半衰期短的经历次数多、剩余少；判断衰变产物先用双守恒定粒子类型（$\\beta$或$\\alpha$）】；警惕【经历半衰期次数可为非整数，需按(1/2)^(t/T)比较大小】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|32:40-35:33","orig":"（例）Sr半衰期29年、Pu为87年：87年后Sr剩1/8、Pu剩1/2，Sr剩余更少，答案D","link":""},{"id":"phy2003","t":"原子核·核反应方程综合判断","s":"看到【判断核反应方程中的粒子类型与衰变类型】","c":"想到【由双守恒定未知粒子：电荷0质量1是中子，电荷1质量1是质子；生成物含^{0}_{-1}e是$\\beta$衰变，含^{4}_{2}He是$\\alpha$衰变】；警惕【$\\beta$衰变电子来自核内中子转化，原子核内部本身并没有电子】","src":"物一轮311.放射性元素衰变与人工核反应_笔记","note":"视频|35:33","orig":"（例）未知粒子X质子数0质量数1为中子；反应物1个、生成物2个且含电子的为β衰变，答案B","link":""},{"id":"phy2004","t":"原子核·四种基本相互作用","s":"看到【判断某种力属于哪种基本相互作用】","c":"想到【四种作用：引力、电磁、强（核力）、弱（$\\beta$衰变的原因）；高中受力分析中绝大部分力属于引力或电磁相互作用】；警惕【弹力、摩擦力微观本质是电磁相互作用，不是强相互作用】","src":"物一轮312.核力与结合能_笔记","note":"视频|00:30-03:16","orig":"（知识）引力相互作用、电磁相互作用（弹力摩擦力的微观本质）、强相互作用（核力）、弱相互作用（引起β衰变）","link":""},{"id":"phy2005","t":"原子核·强相互作用（核力）","s":"看到【问核力（强相互作用）的特点或作用范围】","c":"想到【核力是短程力，范围约10^{-15}m（原子核大小），克服质子间库仑斥力将核子「压缩」成原子核】；警惕【原子核大小10^{-15}m远小于原子大小10^{-10}m，两个尺度勿混淆】","src":"物一轮312.核力与结合能_笔记","note":"视频|01:24-03:16","orig":"（知识）核力使核子（质子和中子）紧密结合成原子核，克服质子间电磁斥力；短程力，作用范围10⁻¹⁵m内明显","link":""},{"id":"phy2006","t":"原子核·结合能概念","s":"看到【判断结合能是不是原子核本身具有的能量】","c":"想到【结合能是核反应过程的能量变化（过程量）：拆开吸能、结合放能】；警惕【结合能不是原子核内部储存的能量，而是分开或结合所需的能量】","src":"物一轮312.核力与结合能_笔记","note":"视频|04:45-06:04","orig":"（知识）核子结合成原子核时释放能量，原子核分开成核子需克服核力做功吸收能量，该能量即结合能","link":""},{"id":"phy2007","t":"原子核·平均结合能与稳定性","s":"看到【比较不同原子核的稳定性】","c":"想到【比结合能越大越稳定；曲线规律：轻核、重核比结合能低，中核最高最稳定】；警惕【比结合能是「每个核子分摊」的结合能，不是结合能总量大就稳定】","src":"物一轮312.核力与结合能_笔记","note":"视频|06:07-06:44","orig":"（知识）平均结合能（比结合能）=结合能/核子数，越大原子核越稳定；随质量数先增大后减小，中核最稳定","link":""},{"id":"phy2008","t":"原子核·聚变裂变与放能判断","s":"看到【判断某核反应是放能还是吸能】","c":"想到【比结合能低$\\to$高为放能（吸少放多），高$\\to$低为吸能（吸多放少）；聚变和裂变都向中核方向进行，均放能】；警惕【不要误以为只有重核裂变放能，轻核聚变同样放能】","src":"物一轮312.核力与结合能_笔记","note":"视频|08:22-11:47","orig":"（知识）轻核聚变、重核裂变都是由低平均结合能→高平均结合能，均为放能反应（吸少放多）","link":""},{"id":"phy2009","t":"原子核·质量亏损与质能方程","s":"看到【由质量亏损求释放的核能】","c":"想到【$\\Delta$E=$\\Delta$mc^{2}；核反应遵循质量数守恒但实际质量亏损，亏损的质量以能量形式释放】；警惕【质量数$\\neq$实际质量：质子与中子质量数均为1但实际质量不同，勿混淆】","src":"物一轮312.核力与结合能_笔记","note":"视频|11:56-15:13","orig":"（知识）原子核质量小于组成它的核子质量之和，差值Δm对应能量ΔE=Δmc²；1u=931.5MeV","link":""},{"id":"phy2010","t":"原子核·半衰期与比结合能综合判断","s":"看到【题目未给数据，判断反应前后原子核比结合能大小】","c":"想到【自发放能反应的生成物更稳定$\\to$比结合能更大；无数据时优先用稳定性判断，有数据时比结合能=结合能/核子数】；警惕【半衰期与理化条件无关、少量原子核（如100个）不能用半衰期计算，常作错误选项出现】","src":"物一轮312.核力与结合能_笔记","note":"视频|15:13-20:44","orig":"（例）天然β衰变是自发放能反应，生成物能量更低更稳定，故钡核比结合能大于铯核，答案B","link":""},{"id":"phy2011","t":"原子核·核聚变能量计算","s":"看到【给各核质量（单位u），求一定量燃料聚变释放的总能量】","c":"想到【单个反应能量=$\\Delta$m$\\times$931.5MeV，再乘以核个数（质量/摩尔质量$\\times$NA）；只需估算数量级时用近似值快速计算】；警惕【聚变需核间距达10^{-15}m量级克服库仑斥力，10^{-10}m是原子尺度不能发生核反应；放能反应生成物比结合能更大】","src":"物一轮312.核力与结合能_笔记","note":"视频|20:44","orig":"（例）氘氚聚变：反应物5.0302u、生成物5.0113u，Δm=0.0189u；5g氘核2.5mol，总能量数量级10²⁵MeV，答案C","link":""},{"id":"phy2012","t":"动态平衡·悬挂物三力正交分解","s":"看到【悬挂物被缓慢拉动，绳与竖直方向的夹角逐渐增大，问绳张力或水平拉力如何变化】","c":"想到【对悬挂物正交分解：$T=\\frac{mg}{\\cos\\theta}$、$F=mg\\tan\\theta$，夹角增大时 $\\cos\\theta$ 减小、$\\tan\\theta$ 增大，故 T 与 F 都一直增大】；警惕【认为水平拉力「可能保持不变」；绳张力只由悬挂物自身的平衡决定，与绳另一端连什么无关】","src":"2019全国卷·斜面滑轮动态平衡","note":"课件|2019 实时演示（拖θ看力三角形变形）","orig":"（新）跨过定滑轮的细绳下端悬挂物块，水平力缓慢拉动物块使绳与竖直方向夹角 $\\theta$ 由 0° 逐渐增大，物块始终平衡，判断绳张力与水平拉力的变化","link":"http://192.168.31.12:9000/courseware/2019_斜面滑轮动平衡.html"},{"id":"phy2013","t":"相互作用·斜面静摩擦走势分类","s":"看到【斜面（或接触面）上物体保持静止，沿斜面的外力（绳张力等）逐渐增大，问摩擦力大小如何变化】","c":"想到【沿斜面列平衡：$f=m_Mg\\sin\\alpha-T$，初态方向由 $T_0$ 与 $m_Mg\\sin\\alpha$ 的大小关系决定——初态摩擦沿斜面向上则随 $T$ 增大先减小为零（$T$ 恰等于下滑分力处为临界）再反向增大；初态沿斜面向下或为零则大小一直增大】；警惕【「一定一直增加/减小」类绝对化选项——走势取决于初态方向，必须分类讨论；漏掉摩擦力为零的临界时刻】","src":"2019全国卷·斜面滑轮动态平衡","note":"课件|2019 实时演示（拖k看三类走势）","orig":"（新）斜面上物块经定滑轮受绳张力作用始终保持静止，缓慢拉动绳另一端使张力 $T$ 逐渐增大，判断物块所受摩擦力的大小走势","link":"http://192.168.31.12:9000/courseware/2019_斜面滑轮动平衡.html"},{"id":"phy2014","t":"运动的描述·质点能否被看作质点的判定","s":"看到【判断某物体能否看成质点，题干涉及研究动作、旋转、击球部位或尺寸远小于路程】","c":"想到【能否看成质点由研究的问题决定，而非物体本身：物体尺寸远小于运动路程、研究天体公转时可看成质点；研究动作细节（体操动作、扣球击球部位）、自转、乒乓球旋转发球时不能看成质点。质点有质量而几何点没有，属于理想模型法】；警惕【同一物体换个问题结论就变：研究地球公转可看成质点，研究地球自转不能】","src":"跳跳物一轮01.1 运动的描述_笔记","note":"视频|03:19","orig":"（知识）质点是忽略形状和大小、只保留质量的理想模型点，能否看成质点由所研究的问题决定。","link":""},{"id":"phy2015","t":"运动的描述·参考系判断的动词主语法","s":"看到【语文式描述如“桥流水不流”“轻舟已过万重山”，问以谁为参考系】","c":"想到【句子中动词的主语一定不是参考系，句中另一物体即参考系：“桥流”的动词是“流”、主语是桥，参考系是水；“轻舟已过万重山”的参考系是万重山；高中阶段默认以大地为参考系，没有绝对静止的物体】；警惕【别把动词的主语选成参考系；无特殊说明时不要另选非大地参考系】","src":"跳跳物一轮01.1 运动的描述_笔记","note":"视频|05:34","orig":"（知识）参考系是为研究运动而人为选定假定静止的物体，判断参考系可用“动词主语法”。","link":""},{"id":"phy2016","t":"运动的描述·时间与时刻的说法辨析","s":"看到【“第n秒内”“前n秒”“第n秒初/末”“n秒”等说法，判断是时刻还是时间】","c":"想到【第n秒=持续1秒的一段时间（第2秒指1~2）；前n秒=0到n的整段；第n秒初对应点 $n-1$、第n秒末对应点 $n$；单说“n秒”是时刻，第n秒末与n秒是同一时刻；$t_{n-1}$ 到 $t_n$ 这一段就是第n秒内】；警惕【“第n秒内”只有1秒而“前n秒”有n秒，二者时间长短不同；“2s内”表示一段时间而非时刻】","src":"跳跳物一轮01.1 运动的描述_笔记","note":"视频|07:35","orig":"（知识）时刻对应时间轴上的一个点，时间（间隔）对应一段，“第n秒”类说法必须精确辨析。","link":""},{"id":"phy2017","t":"运动的描述·位移与路程的关系及一维位移计算","s":"看到【比较路程与位移大小，或在给定坐标下计算位移、比较位移大小】","c":"想到【路程 $\\geq$ 位移大小，等号仅在单向直线运动时成立；一维位移=末位置坐标−初位置坐标，坐标的负号必须代入运算（如初坐标 $-1$ m、末坐标 $2$ m，位移 $=2-(-1)=3$ m）；位移比大小只看绝对值，正负号仅表示方向（如 $-3$ m的位移大于 $2$ m的位移）】；警惕【直线运动有折返时路程仍大于位移大小；比位移大小时误把正负号当大小、算位移时漏掉坐标的负号】","src":"跳跳物一轮01.1 运动的描述_笔记","note":"视频|10:07","orig":"（知识）位移是由初位置指向末位置的矢量，路程是标量，二者大小满足路程$\\geq$位移大小。","link":""},{"id":"phy2018","t":"运动的描述·平均速率与平均速度大小的关系","s":"看到【同一运动中同时出现平均速度与平均速率，问二者大小关系或分别求值】","c":"想到【平均速率 $\\geq$ 平均速度的大小，本质等同于路程与位移大小的关系，仅在单向直线运动时取等号；平均速度是矢量，方向与该段时间的位移方向一致（由初位置指向末位置）；求平均速度必须先明确是哪一段时间，初末位置由该段时间确定】；警惕【平均速率不一定等于平均速度的大小；速度单位换算 km/h→m/s 要 $\\div 3.6$（如 $5.4$ km/h $=1.5$ m/s）】","src":"跳跳物一轮01.1 运动的描述_笔记","note":"视频|13:46-14:32","orig":"（知识）平均速度=位移/时间是矢量，平均速率=路程/时间是标量，二者大小一般不相等。","link":""},{"id":"phy2019","t":"运动的描述·瞬时速度方向与极短较短的判定","s":"看到【曲线运动问某点速度方向，或出现“极短/较长时间内的速度”的表述】","c":"想到【瞬时速度方向沿运动轨迹的切线方向；“极短时间内的速度”指瞬时速度，“较长时间内的速度”指平均速度；瞬时速率一定等于瞬时速度的大小（极短时间内路程$\\approx$位移大小），但平均速率不一定等于平均速度大小；题目单说“速度”“运动方向”通常指瞬时速度】；警惕【把“较长”当成“瞬时”；曲线运动中把速度方向画成沿轨迹本身而非切线方向】","src":"跳跳物一轮01.1 运动的描述_笔记","note":"视频|16:09-17:35","orig":"（知识）瞬时速度是某一时刻（极短时间内）的速度，方向沿轨迹切线；瞬时速率恒等于瞬时速度的大小。","link":""},{"id":"phy2020","t":"运动的描述·加速度概念与同加反减判定","s":"看到【问加速度的物理意义、区分变化率与变化量，或判断物体做加速还是减速】","c":"想到【加速度=速度变化量÷所用时间，是矢量，方向与 $\\Delta v$ 方向一致；“同加反减”：加速度与速度（该时刻瞬时速度）方向相同则加速、相反则减速；任何变化量=末状态量−初状态量；加速、减速运动都可以有加速度】；警惕【加速度不是速度变化量（变化率说快慢、变化量说多少）；只看 $a$ 或只看 $v$ 的正负就判加减速而不比两者方向；变化量误算成初减末】","src":"跳跳物一轮01.1 运动的描述_笔记","note":"视频|18:42-20:34","orig":"（知识）加速度 $a=\\Delta v/\\Delta t$ 是速度变化率（变化快慢），判断加速减速用“同加反减”。","link":""},{"id":"phy2021","t":"运动的描述·加速度逐渐减小到零的运动情况讨论","s":"看到【$a$ 方向不变、大小逐渐减为零，初速度与 $a$ 的方向关系未定，问速度怎么变】","c":"想到【先按 $a$ 与 $v$ 同向/反向分支：同向则速度一直增大，$a$ 减为零后以最大速度匀速；反向则先减速，再按速度与加速度谁先减到零分三种情况——$v$ 先减为零则随即反向加速、最后匀速，$a$ 先减为零则以剩余速度匀速，两者同时为零则最终静止；全程逐段用“同加反减”判断】；警惕【$a$ 方向不变时速度不可能先增大后减小（那需要 $a$ 先与 $v$ 同向再反向）；漏掉“减速到零后反向加速”和“$a$ 先减为零改匀速”两种情况】","src":"跳跳物一轮01.1 运动的描述_笔记","note":"视频|28:45","orig":"（例）物体做变速直线运动，加速度方向不变、大小逐渐减小到零，判断它可能的运动情况。","link":""},{"id":"phy2022","t":"匀变速直线运动公式·四大公式及变形","s":"看到【匀变速直线运动已知量与待求量组合，需要选用公式列方程】","c":"想到【四大公式：$v_T=v_0+at$；$x=v_0t+\\frac{1}{2}at^2$；$v_T^2-v_0^2=2ax$（不含时间t）；$x=\\frac{v_0+v_T}{2}t$（不含加速度a）。变形：初速度为零时把含 $v_0$ 的项置零；匀减速时把a前的“+”变“−”；末速度为零的匀减速用逆向思维等效为初速度为零的匀加速】；警惕【速度位移公式里没有t、平均速度公式里没有a，列式前先核对是否需要引入该量】","src":"跳跳物一轮01.2 匀变速直线运动公式_笔记","note":"视频|05:08-05:47","orig":"（知识）单向匀变速直线运动有四大基本公式：速度时间、位移时间、速度位移、平均速度公式。","link":""},{"id":"phy2023","t":"匀变速直线运动公式·黄金路径法选公式","s":"看到【匀变速题不知用哪个公式下手，已知条件里有没有时间或加速度是关键】","c":"想到【第一步看是否涉及t：无t（不提也不求时间）必用速度位移公式 $v_T^2-v_0^2=2ax$；有t再看是否涉及a：无a（不提也不求加速度）必用平均速度公式 $x=\\frac{v_0+v_T}{2}t$；有t有a用速度时间公式或位移时间公式】；警惕【硬用含“本题没有的量”的公式，会引入多余未知数使方程变复杂】","src":"跳跳物一轮01.2 匀变速直线运动公式_笔记","note":"视频|10:24","orig":"（知识）通过“是否有t”“是否有a”两步判断，快速定位匀变速问题该用哪个公式。","link":""},{"id":"phy2024","t":"匀变速直线运动公式·末速度为零的逆向思维","s":"看到【末速度为零的匀减速（刹车、滑行到停），或求“最后一段”的位移/时间】","c":"想到【逆向等效：原匀减速的初速度 $v_0$ 对应逆向匀加速的末速度，运动时间、位移大小均不变；列方程直接用初速度为零的匀加速公式（如 $x=\\frac{1}{2}at^2$），并把式中末速度换成原过程的初速度；“最后1s位移”类条件即用此法】；警惕【只适用于末速度为零的匀减速（或其末段）；中途仍有速度的过程不能整体逆向套用】","src":"跳跳物一轮01.2 匀变速直线运动公式_笔记","note":"视频|07:04","orig":"（知识）末速度为零的匀减速直线运动，可逆向看作初速度为零的匀加速直线运动。","link":""},{"id":"phy2025","t":"匀变速直线运动公式·列方程的正方向设定","s":"看到【匀变速过程中速度方向会反转（掉头、竖直上抛全程），要对全程列方程】","c":"想到【单向匀变速：列方程前不设正方向，方程只表示大小关系，$a$、$v$、$x$ 一律代正数；有掉头的匀变速（如竖直上抛全程）：先设正方向，与正方向同向的矢量代正数、反向的代负数，解出为正表示与正方向同向、为负表示反向】；警惕【有掉头的运动仍全代正数，会把往返位移算成同向叠加；解出负值漏判为“方向与正方向相反”】","src":"跳跳物一轮01.2 匀变速直线运动公式_笔记","note":"视频|02:24-04:03","orig":"（知识）列匀变速方程前必须明确是否设正方向：单向运动不设正方向，有掉头的运动必须设。","link":""},{"id":"phy2026","t":"匀变速直线运动公式·刹车问题先判刹停","s":"看到【刹车/减速到停，问某段时间内位移或平均速度，时间可能超过刹停时刻】","c":"想到【一律先算刹车时间 $=v_0/a$ 并与所问时间比较：所问时间$\\geq$刹车时间则车已停，位移就是全程刹车位移（用 $v_0^2=2ax$ 求），之后保持静止；“最后1s”类条件逆向视为初速度为零的匀加速，用 $x=\\frac{1}{2}at^2$；平均速度 $=\\frac{v_0+v_T}{2}$ 或位移/时间，平均速度是矢量，答案须说明方向（与初速度方向相同）】；警惕【所问时间超过刹车时间仍把全时间代入公式，把停止后算成反向运动；平均速度漏写方向被扣分】","src":"跳跳物一轮01.2 匀变速直线运动公式_笔记","note":"视频|22:27","orig":"（知识）刹车问题（末速度为零的匀减速）必须先算刹车时间判断车是否已停，再决定怎么列式。","link":""},{"id":"phy2027","t":"匀变速直线运动公式·非质点列车过隧道盯车头","s":"看到【有长度的列车过隧道，分减速、匀速、加速多阶段，求总时间或位移】","c":"想到【非质点运动盯死一头（如车头），把列车运动转化为车头这个质点的运动：车头匀速段位移=隧道长+车长；减速段、加速段分别用速度时间公式求时间，总时间=三段时间之和，逐段“一段一式”列方程】；警惕【匀速段位移误用隧道长而漏加车身长度；对列车“整体”而非某一点分析导致位移关系混乱】","src":"跳跳物一轮01.2 匀变速直线运动公式_笔记","note":"视频|14:29","orig":"（例）列车（有长度）依次经历减速进隧道、隧道内匀速、加速出隧道三个阶段，求全程总时间。","link":""},{"id":"phy2028","t":"匀变速直线运动公式·反应时间加制动的两段模型","s":"看到【司机反应时间匀速+刹车匀减速（末速度为零）两段模型，求 $a$、$v_0$ 或总时间】","c":"想到【分段处理：匀速段位移 $=v_0\\times$ 反应时间；制动段末速度为零——不求时间用速度位移公式 $v_0^2=2ax$，已知制动时间不求a用平均速度公式 $s=\\frac{1}{2}v_0t$；总时间=反应时间+制动时间，全程平均速度=总位移/总时间】；警惕【全程平均速度误用 $\\frac{v_0+v_T}{2}$（只对单一匀变速段成立，含匀速段的全程不适用）；漏掉反应时间内的匀速位移】","src":"跳跳物一轮01.2 匀变速直线运动公式_笔记","note":"视频|17:48","orig":"（例）汽车先在反应时间内匀速直线运动，随后制动做末速度为零的匀减速运动，已知各段条件判断关于加速度、速度、时间的说法。","link":""},{"id":"phy2029","t":"x-t图像·图线陡峭程度的判定","s":"看到【比较几条图线（或曲线各处）谁更陡峭、谁更平缓】","c":"想到【陡峭程度=斜率的绝对值：绝对值越大图线越接近垂直越陡峭，越小越接近水平越平缓，与图线上扬（斜率为正）还是下降（斜率为负）无关；判断曲线是否越来越陡，看各点切线：切线越来越陡→曲线越来越陡峭，切线越来越平缓→曲线越来越平缓】；警惕【把“下降的图线”误判为不陡；只看曲线整体走势而不看各点切线斜率绝对值的变化】","src":"跳跳物一轮01.3 x-t图像_笔记","note":"视频|00:23-01:41","orig":"（知识）图线的陡峭程度指斜率的绝对值，只论大小不论正负；曲线看各点切线。","link":""},{"id":"phy2030","t":"x-t图像·基本概念与交点含义","s":"看到【给出x-t图像，问图线含义、交点意义或是否表示轨迹】","c":"想到【纵坐标表示该时刻物体的位置（不是位移）；图线不表示物体的真实运动轨迹；只有直线运动才有x-t图（曲线运动的位置需要两个坐标）；两条图线的交点表示两物体在该时刻相遇（同一时刻到达同一位置），交点个数即相遇次数】；警惕【把x-t图线当成运动轨迹（误以为图线弯曲则轨迹弯曲）；把纵坐标读数直接当成位移】","src":"跳跳物一轮01.3 x-t图像_笔记","note":"视频|02:40-02:56","orig":"（知识）x-t图像表示直线运动物体的位置随时间变化，纵坐标是位置、横坐标是时刻。","link":""},{"id":"phy2031","t":"x-t图像·速度方向与掉头判定","s":"看到【x-t图像问某时刻速度大小/方向，或图线出现拐点问是否掉头】","c":"想到【速度大小=该点切线斜率的绝对值（直线段就等于该直线斜率的绝对值）；方向看上扬/下降：图线上扬斜率为正、速度沿正方向，下降斜率为负、沿负方向；掉头发生在图线由上扬变下降或由下降变上扬的拐点处（瞬时速度方向改变的时刻）】；警惕【图线由水平变倾斜的拐点（由静止开始运动）不是掉头；判断“速度相同”必须大小和方向都相同】","src":"跳跳物一轮01.3 x-t图像_笔记","note":"视频|04:26-06:00","orig":"（知识）x-t图线上某点的瞬时速度等于该点切线的斜率：绝对值定大小、正负定方向。","link":""},{"id":"phy2032","t":"x-t图像·加减速判定与加速度方向","s":"看到【x-t图像问物体做加速还是减速、加速度方向如何】","c":"想到【图线越来越陡峭→速度大小增大（加速），越来越平缓→速度大小减小（减速）；推加速度方向分两步：先由上扬/下降定速度方向，再由陡缓变化定加减速，加速则 $a$ 与 $v$ 同向、减速则 $a$ 与 $v$ 反向】；警惕【x-t图只能定加速度的方向，无法判断加速度大小及其增减；只看图线上扬/下降就直接下加速/减速的结论】","src":"跳跳物一轮01.3 x-t图像_笔记","note":"视频|07:36-08:13","orig":"（知识）x-t图像看加减速比图线陡峭程度的变化，加速度方向再用“同加反减”口诀推。","link":""},{"id":"phy2033","t":"x-t图像·位移与路程的计算","s":"看到【由x-t图像求一段时间内的位移或全程路程】","c":"想到【位移=末纵坐标−初纵坐标（末减初，坐标负号代入，结果正负表示方向）；路程必须先找出所有掉头点，把运动分成若干单向直线段，分别计算每段位移大小再相加】；警惕【有掉头时直接用末减初的绝对值当路程；漏找掉头点导致路程少算】","src":"跳跳物一轮01.3 x-t图像_笔记","note":"视频|10:08","orig":"（知识）x-t图像中位移=末时刻纵坐标−初时刻纵坐标，路程=各单向段位移大小之和。","link":""},{"id":"phy2034","t":"x-t图像·图线形状对应的运动类型","s":"看到【x-t图像中图线是水平线、倾斜直线、抛物线或一般曲线，问运动性质】","c":"想到【水平直线→静止；倾斜直线→匀速直线运动（斜率恒定、速度恒定）；抛物线→匀变速直线运动（位置随时间是二次函数关系）；其他曲线→变加速直线运动（加速度也在变化）】；警惕【把倾斜直线误判为匀加速（匀变速的x-t图是抛物线不是直线）；把水平直线段当成物体消失或没画】","src":"跳跳物一轮01.3 x-t图像_笔记","note":"视频|12:06","orig":"（知识）x-t图像的图线形状直接对应运动类型：水平直线、倾斜直线、抛物线、其他曲线各不相同。","link":""},{"id":"phy2035","t":"x-t图像·交点相遇的速度与平均速度比较","s":"看到【x-t图像两图线相交（相遇），问相遇时速度是否相等或平均速度大小】","c":"想到【交点只保证同时刻同位置，速度各自等于自己图线在该点的切线斜率，两线斜率不同则速度不相等；比较平均速度看位移和时间：若两物体起点、终点位置都相同（如两次相遇之间），则位移相同、所用时间相同，平均速度必相同】；警惕【“相遇即速度相等”是典型错误；比较平均速度时误用某时刻的瞬时速度代替】","src":"跳跳物一轮01.3 x-t图像_笔记","note":"视频|17:37","orig":"（例）甲的x-t图线为倾斜直线、乙为抛物线，两图线相交两次，比较相遇时刻的速度及各时间段内的平均速度。","link":""},{"id":"phy2036","t":"x-t图像·超声波测速的声波图线分析","s":"看到【声波/超声波测速的x-t图，声波往返传播、物体运动，求声速或物体速度】","c":"想到【声波匀速传播，到达物体的时刻=发射时刻+回波总时间的一半，故声速=2×单程位移/回波总时间，即声速 $=2x_1/T_1$；物体速度=两位置差/两时刻差，两时刻分别是两次回波的时间中点，物体速度 $=2(x_2-x_1)/(T_2-T_1+\\Delta t)$，$\\Delta t$ 为两次发射的时间间隔】；警惕【物体在 $x_1$ 处的时刻是 $T_1/2$ 而不是 $T_1$（漏掉往返时间平分）；物体速度误除以 $\\Delta t$（$\\Delta t$ 是发射间隔，不是物体运动时间）】","src":"跳跳物一轮01.3 x-t图像_笔记","note":"视频|25:51","orig":"（例）超声波测速仪每隔 $\\Delta t$ 发射一次短脉冲，声波在x-t图中为倾斜直线且往返时间相等，物体匀速运动，由两次回波求声速与物体速度。","link":""},{"id":"phy2037","t":"v-t图像·速度方向与掉头判定","s":"看到【v-t图问某物体速度方向，或问何时掉头、运动方向何时反向】","c":"想到【纵坐标的正负表示速度方向：图线在t轴上方为正方向、下方为负方向，纵坐标绝对值才是速度大小；掉头指速度方向反转180°，判断标准是图线穿过t轴，穿轴时刻即掉头时刻】；警惕【图线只是挨着t轴但没穿过去（如触底弹回），速度方向未反转，不叫掉头】","src":"跳跳物一轮01.4 v-t图像_笔记","note":"视频|01:51","orig":"（知识）v-t图中纵坐标的正负表示速度方向，图线是否穿过t轴用于判断掉头。","link":""},{"id":"phy2038","t":"v-t图像·加减速判定口诀","s":"看到【v-t图判断某段是加速还是减速，图线可能在t轴上方或下方】","c":"想到【口诀“离加近减”：图线远离t轴（纵坐标绝对值增大）为加速，接近t轴（绝对值减小）为减速；t轴上方、下方均适用，如t轴下方且远离t轴表示沿负方向加速】；警惕【这是v-t图的判定法，x-t图判断快慢变化看图线陡峭程度（变陡加速、变平减速），两图方法完全不同，混用必错】","src":"跳跳物一轮01.4 v-t图像_笔记","note":"视频|05:27","orig":"（知识）v-t图中通过图线远离还是靠近t轴判断加速与减速。","link":""},{"id":"phy2039","t":"v-t图像·切线斜率看加速度","s":"看到【v-t图比较不同时刻或不同物体加速度的大小、方向，图线含曲线段】","c":"想到【切线斜率绝对值=加速度大小，图线越陡峭加速度越大；斜率正负=加速度方向：图线上扬（斜率为正）加速度沿正方向，图线下降则沿负方向；某时刻切线水平，该时刻加速度为零】；警惕【t轴上方的下降段加速度沿负方向：加速度方向由斜率正负决定，与图线在t轴哪一侧无关】","src":"跳跳物一轮01.4 v-t图像_笔记","note":"视频|07:21","orig":"（知识）v-t图线某时刻切线的斜率表示该时刻的瞬时加速度。","link":""},{"id":"phy2040","t":"v-t图像·面积法求位移与路程","s":"看到【v-t图求一段时间内的位移或路程，图线与t轴围出的面积有上有下】","c":"想到【总位移=上方面积-下方面积，差值正负表示总位移方向；总路程=上方面积+下方面积；平均速度=总位移÷时间，平均速率=总路程÷时间】；警惕【上下面积直接相加得到的是路程而非位移；t轴下方面积对应负方向位移，求总位移时正负号不能丢】","src":"跳跳物一轮01.4 v-t图像_笔记","note":"视频|08:29","orig":"（知识）v-t图线与t轴围成的面积对应位移，路程由面积累加得到。","link":""},{"id":"phy2041","t":"v-t图像·运动类型识别","s":"看到【v-t图出现水平线、倾斜直线、曲线或穿t轴的直线，判断运动性质】","c":"想到【水平直线=匀速；倾斜直线=匀变速（斜率恒定）；曲线=变加速；穿过t轴的直线=有掉头的匀变速，先匀减速到零再反向匀加速，全程加速度不变；图线由直线变为曲线的转折点=运动状态改变时刻（如跳水入水、阻力出现）】；警惕【v-t图水平直线是匀速不是静止（静止是x-t图水平线的含义）；穿t轴前后加速度大小方向均不变，只是速度反向】","src":"跳跳物一轮01.4 v-t图像_笔记","note":"视频|10:57","orig":"（知识）v-t图线的形状直接对应直线运动的类型与运动状态的改变。","link":""},{"id":"phy2042","t":"v-t图像·与x-t图的交点及水平线含义对比","s":"看到【两条运动图线相交，或图线出现水平段，判断是否相遇或静止】","c":"想到【交点：x-t图两线相交=相遇（同一时刻同一位置），v-t图两线相交=共速（该时刻速度相同）不代表相遇；水平直线：x-t图=静止，v-t图=匀速直线运动】；警惕【x-t图根本看不出加速度大小及增减，v-t图看不出物体位置和是否相遇；把v-t图交点当相遇、水平段当静止是高频错误】","src":"跳跳物一轮01.4 v-t图像_笔记","note":"视频|13:26","orig":"（知识）x-t图与v-t图中交点和水平直线的物理含义完全不同。","link":""},{"id":"phy2043","t":"v-t图像·面积抵消与离出发点最远时刻","s":"看到【v-t图上下都有面积（有正有负），问总位移、平均速度或离出发点最远的时刻】","c":"想到【上下全等三角形面积相等互相抵消，总位移=中间梯形面积=$(2+4)\\times 10\\div 2=30\\ \\mathrm{m}$，平均速度=$30\\ \\mathrm{m}\\div 6\\ \\mathrm{s}=5\\ \\mathrm{m/s}$；离出发点最远的时刻=图线穿t轴（速度反向）的时刻即5s末，此前物体一直沿正方向远离出发点】；警惕【水平段是匀速不是静止；上下面积相加得到路程而非位移；4~6s图线更陡故加速度更大】","src":"跳跳物一轮01.4 v-t图像_笔记","note":"视频|15:04","orig":"（例）物体在0~6s内做直线运动，其v-t图中t轴上方和下方各围出一个全等三角形，中间剩余梯形面积可按$(2+4)\\times 10\\div 2$计算；图线在2~4s为水平线，5s末穿过t轴到达负速度。问各段运动性质、全程平均速度及离出发点最远的时刻。","link":""},{"id":"phy2044","t":"v-t图像·上凸曲线平均速度与弦的比较","s":"看到【v-t图为上凸或下凹曲线，比较实际平均速度与两端速度平均值的大小】","c":"想到【连接两端点的直线（弦）对应匀加速，其下三角形面积=$\\frac{1}{2}v_2\\Delta t$，平均速度=$v_2/2$；上凸曲线位于弦上方，图线下实际面积更大，故实际平均速度$>v_2/2$（下凹曲线则小于）；加速度看切线斜率，切线水平处斜率为零即加速度最小】；警惕【曲线不是匀变速，禁止套用平均速度=$(v_1+v_2)/2$；上凸与下凹方向不同，结论相反】","src":"跳跳物一轮01.4 v-t图像_笔记","note":"视频|20:38","orig":"（例）物体做直线运动，其v-t图中$t_1$~$t_2$段为上凸曲线，起点在t轴上（速度为零），终点速度为$v_2$且该处切线水平。比较$t_1$~$t_2$内实际平均速度与$v_2/2$的大小，并找出加速度最小的时刻。","link":""},{"id":"phy2045","t":"a-t图像·面积表示速度变化量","s":"看到【a-t图求某段时间的速度变化量，或初速为零求某时刻瞬时速度】","c":"想到【图线与t轴围成的面积=速度变化量$\\Delta v$：上方面积为正、下方面积为负，面积有上有下时$\\Delta v$=上方面积-下方面积；末速度$v=v_0+\\Delta v$；初速度为零时，某时刻瞬时速度=从0到该时刻的上方面积-下方面积】；警惕【各图面积含义不同：a-t图面积是$\\Delta v$，v-t图面积才是位移，不能张冠李戴；初速度不为零时面积只是变化量，末速度须加回$v_0$】","src":"跳跳物一轮01.5 其他运动学图像_笔记","note":"视频|01:09-02:42","orig":"（知识）a-t图中图线与t轴围成的面积表示速度变化量。","link":""},{"id":"phy2046","t":"v²-x图像·斜率与截距的物理意义","s":"看到【v$^2$-x图为倾斜直线，求初速度、加速度或判断运动性质】","c":"想到【由速度位移公式$v^2-v_0^2=2ax$变形得$v^2=2ax+v_0^2$，与直线方程$y=kx+b$对比：斜率$k=2a$（即$a=k/2$），纵截距$b=v_0^2$；推荐现推：先写出直线方程$v^2=kx+b$，再与公式对比，不死记结论】；警惕【斜率是$2a$不是$a$；纵截距是$v_0^2$不是$v_0$，开平方才得初速度；与x/t-t图的斜率$k=a/2$恰好相反，最易混】","src":"跳跳物一轮01.5 其他运动学图像_笔记","note":"视频|04:14","orig":"（知识）v$^2$-x图中图线为倾斜直线表示匀变速直线运动，斜率和截距可求加速度与初速度。","link":""},{"id":"phy2047","t":"x/t-t图像·平均速度图像的斜率意义","s":"看到【x/t-t图为倾斜直线，求初速度、加速度或某段时间平均速度】","c":"想到【由位移时间公式$x=v_0t+\\frac{1}{2}at^2$两边除以t得$x/t=v_0+\\frac{1}{2}at$，与直线方程$y=kx+b$对比：斜率$k=\\frac{1}{2}a$（即$a=2k$），纵截距$b=v_0$；图线某时刻的纵坐标值即0到该时刻的平均速度】；警惕【斜率是$a/2$不是$a$（v$^2$-x图才是$k=2a$）；把纵坐标当成瞬时速度（x/t是平均速度）】","src":"跳跳物一轮01.5 其他运动学图像_笔记","note":"视频|08:02","orig":"（知识）x/t-t图的纵坐标表示0到该时刻的平均速度，倾斜直线对应匀变速直线运动。","link":""},{"id":"phy2048","t":"x-t²图像·初速度为零匀变速的判定","s":"看到【x-t$^2$图为过原点的直线，求加速度或判断初速度】","c":"想到【设直线方程$x=kt^2$，与初速为零的位移公式$x=\\frac{1}{2}at^2$对比得$k=\\frac{1}{2}a$，即$a=2k$；图线过原点意味着纵截距为零，初速度$v_0=0$】；警惕【斜率不是$a$而是$a/2$，直接当加速度会差2倍；图线不过原点（有截距）时初速度不为零，须用$x=v_0t+\\frac{1}{2}at^2$完整对比】","src":"跳跳物一轮01.5 其他运动学图像_笔记","note":"视频|24:50","orig":"（知识）x-t$^2$图中过原点的倾斜直线表示初速度为零的匀变速直线运动。","link":""},{"id":"phy2049","t":"a-t图像·转画v-t图与面积代数和","s":"看到【a-t图上下交替（有正有负），要求转画v-t图或判断速度、位移】","c":"想到【逐段累积面积求速度：某时刻速度=之前各段面积的代数和（上正下负），如2$T_0$末速度回到零、4$T_0$末速度为零；画v-t图时加速度大处图线陡、加速度小处图线缓；全过程$\\Delta v$代数和为零→末速度回到初值，v-t图上下面积抵消→位移为零、物体返回出发点】；警惕【只算单段面积忽略前面各段的累积；v-t图线的陡峭由加速度大小决定，不能照搬a-t图的形状】","src":"跳跳物一轮01.5 其他运动学图像_笔记","note":"视频|10:34","orig":"（例）物体由静止开始运动，其a-t图中四个三角形面积均为$\\frac{1}{2}T_0A_0$且正负上下交替（0~$T_0$正、$T_0$~2$T_0$负、2$T_0$~3$T_0$正、3$T_0$~4$T_0$负）。要求转画v-t图并判断4$T_0$末物体的位置。","link":""},{"id":"phy2050","t":"v²-x图像·匀减速直线运动分析","s":"看到【v$^2$-x图从$v_0^2$均匀减小到零，求加速度、时间或位移中点速度】","c":"想到【直线降到零=匀减速直线运动；斜率$k=-v_0^2/(2x_0)$，由$k=2a$得$a=-v_0^2/(2x_0)$；运动时间$T=v_0/|a|=2x_0/v_0$；位移中点处$v^2=v_0^2/2$，故$v=v_0/\\sqrt{2}$，大于$v_0/2$】；警惕【位移中点速度是$v_0/\\sqrt{2}$不是$v_0/2$（$v_0/2$是时间中点速度）；纵截距$v_0^2$要开平方才是初速度】","src":"跳跳物一轮01.5 其他运动学图像_笔记","note":"视频|18:08","orig":"（例）物体沿直线运动，其v$^2$-x图为倾斜直线：起点（$x=0$）纵坐标为$v_0^2$，终点（$x=x_0$）纵坐标为零（末速度为零）。求运动性质、加速度大小、运动时间及位移中点的速度。","link":""},{"id":"phy2051","t":"x/t-t图像·火箭匀减速分析","s":"看到【x/t-t图为倾斜直线（截距100、斜率-50），求初速度、加速度或平均速度】","c":"想到【由$x/t=v_0+\\frac{1}{2}at$对比直线方程：纵截距=初速度$v_0=100\\ \\mathrm{m/s}$，斜率$k=\\frac{1}{2}a$故$a=2k=-100\\ \\mathrm{m/s^2}$，火箭做匀减速直线运动；某时刻速度$v=v_0+at=100-100t$，1s末为零；0~1s平均速度=x/t在t=1s的纵坐标值=$50\\ \\mathrm{m/s}$】；警惕【把斜率直接当加速度（实际差2倍）；把x/t-t图纵坐标当成瞬时速度（它是平均速度）】","src":"跳跳物一轮01.5 其他运动学图像_笔记","note":"视频|21:35","orig":"（例）火箭沿直线运动，其x/t-t图为倾斜直线：纵截距为$100\\ \\mathrm{m/s}$，斜率为$-50$。求火箭的初速度、加速度、1s末速度及0~1s内平均速度。","link":""},{"id":"phy2052","t":"运动学图像·陌生图像通用解法","s":"看到【陌生的运动学图像（x-t$^2$、x/t-t、v$^2$-x、a-t等），问斜率、截距或面积的物理意义】","c":"想到【通用套路：设图线的函数表达式（如$v^2=kx+b$），再与对应运动学公式对比，斜率和截距的物理意义自然浮现——v$^2$-x图配速度位移公式$v^2-v_0^2=2ax$，x/t-t图配位移时间公式$x=v_0t+\\frac{1}{2}at^2$；不建议死记各图斜率结论，现推更稳】；警惕【公式配错则系数差2倍（如v$^2$-x图斜率是$2a$、x/t-t图斜率是$a/2$）；忽视公式的适用前提（如$x=\\frac{1}{2}at^2$仅适用于初速度为零）】","src":"跳跳物一轮01.5 其他运动学图像_笔记","note":"视频|24:50","orig":"（知识）遇到不熟悉的运动学图像时，通过写函数表达式与运动学公式匹配来求解。","link":""},{"id":"phy2053","t":"匀变速推论·零点推论的使用条件","s":"看到【初速度为零的匀加速或末速度为零的匀减速，按等时或等距划分求比例】","c":"想到【条件一：运动类型必须是初速度为零的匀加速，或末速度为零的匀减速（初速不为零的加速、末速不为零的减速不能用）；条件二：必须从零点（速度为零的点）开始等时或等距划分——匀加速的零点在起点，匀减速的零点在终点；末速度为零的匀减速逆向视为初速度为零的匀加速，从终点倒着数】；警惕【划分不从零点开始（如从运动中间某点开始划分）时比例结论全部失效，只能回到基本公式】","src":"跳跳物一轮01.6 匀变速直线运动推论_笔记","note":"视频|00:31","orig":"（知识）零点推论（比例结论）必须满足两个条件才能使用。","link":""},{"id":"phy2054","t":"匀变速推论·零点推论等时划分位移比","s":"看到【初速度为零的匀加速（或末速度为零的匀减速）按相等时间分段，问各段位移比】","c":"想到【从零点开始以t为间隔等时划分，各段位移之比为$1:3:5:7:\\cdots$（第n段为$2n-1$份）；累计总位移之比为$1:4:9:\\cdots$（前n段为$n^2$份）；末速度为零的匀减速从终点倒着数同样适用】；警惕【该比例只对从零点开始的划分成立，从中间某点开始的等时划分不满足$1:3:5:7$；等距划分结论完全不同（时间比$1:\\sqrt{2}:\\sqrt{3}:2$），两套别混】","src":"跳跳物一轮01.6 匀变速直线运动推论_笔记","note":"视频|01:43","orig":"（知识）零点推论等时划分：从零点起连续相等时间内的位移之比。","link":""},{"id":"phy2055","t":"匀变速推论·零点推论等距划分时间比","s":"看到【初速度为零的匀加速（或末速为零的匀减速）按相等位移分段，问时间、速度或每段用时】","c":"想到【从零点开始等距划分，零点到第1、2、3段末尾的时间之比为$1:\\sqrt{2}:\\sqrt{3}:2:\\cdots$；由$v=at$知速度与时间成正比，各段末速度之比等于时间之比$1:\\sqrt{2}:\\sqrt{3}:2$；每段实际用时之比用相邻累计时间相减：$1:(\\sqrt{2}-1):(\\sqrt{3}-\\sqrt{2}):(2-\\sqrt{3}):\\cdots$】；警惕【“各段用时比”与“累计时间比”混淆（前者必须后项减前项）；末速度为零的匀减速必须倒着数段】","src":"跳跳物一轮01.6 匀变速直线运动推论_笔记","note":"视频|01:43","orig":"（知识）零点推论等距划分：零点到各段末尾的时间之比及其三种考法。","link":""},{"id":"phy2056","t":"匀变速推论·位移差公式","s":"看到【匀变速直线运动按相等时间间隔分段（可从中间任意点开始），求加速度或某段位移】","c":"想到【相邻两段位移差$\\Delta x=x_2-x_1=aT^2$（T为每段的时间间隔），计算时大位移减小位移，主要用途是求加速度；不相邻两段$x_M-x_N=(M-N)aT^2$，如第3段减第1段=$2aT^2$；各段位移成等差数列，可递推未知段】；警惕【条件是匀变速+等时划分即可，不要求初/末速度为零、不要求从零点开始；初速度为零但划分从中间A点开始时零点推论失效，须改用位移差公式】","src":"跳跳物一轮01.6 匀变速直线运动推论_笔记","note":"视频|08:44-09:09","orig":"（知识）匀变速直线运动在等时划分下，相邻时间段的位移差恒定。","link":""},{"id":"phy2057","t":"匀变速推论·均速法（中间时刻速度等于平均速度）","s":"看到【匀变速直线运动求某点瞬时速度，或纸带上求某计数点速度】","c":"想到【中间时刻瞬时速度=该段平均速度=$(v_0+v)/2$；纸带应用：某计数点的瞬时速度=相邻两计数点间的平均速度，如$v_C=x_{BD}/t_{BD}$（C为BD段中间时刻）；全程平均速度等于全程中间时刻的瞬时速度】；警惕【中间时刻速度$\\neq$中间位置速度（中点位移处速度更大，两者不能互换）；用均速法前必须确认该点确为所取段的时间中点】","src":"跳跳物一轮01.6 匀变速直线运动推论_笔记","note":"视频|10:55","orig":"（知识）匀变速直线运动中，某段时间中间时刻的瞬时速度等于该段的平均速度。","link":""},{"id":"phy2058","t":"匀变速推论·刹车拆段逆向法","s":"看到【末速度为零的匀减速按时间分段，时间间隔不能整除总刹车时间】","c":"想到【先算总刹车时间$T=v_0/a=10/4=2.5\\ \\mathrm{s}$；1s不整除2.5s，把间隔拆成0.5s共5段；逆向视为从静止开始的匀加速，连续5个0.5s内位移比为$1:3:5:7:9$；再组合回题目时段：第1s=逆向最后两段=$7+9=16$份，第2s=中间两段=$3+5=8$份，第3s（2~2.5s）=靠静止端第1段=$1$份，故位移比$16:8:1$】；警惕【时间不整除时硬套$1:3:5:7$必错；2.5s后车已停止，第3s内实际只运动0.5s，不能按完整1s处理】","src":"跳跳物一轮01.6 匀变速直线运动推论_笔记","note":"视频|14:47","orig":"（例）汽车以36km/h（10m/s）初速度刹车，加速度大小为$4\\ \\mathrm{m/s^2}$，做末速度为零的匀减速直线运动。求刹车后第1s内、第2s内、第3s内的位移之比。","link":""},{"id":"phy2059","t":"匀变速推论·车厢过立柱模型","s":"看到【列车（或物块序列）由静止匀加速通过某点，给首段和全程时间，问段数或分段情况】","c":"想到【转化为“列车前端点”由静止匀加速：通过L、2L、3L…的时间比为$1:\\sqrt{2}:\\sqrt{3}:\\cdots$，即通过n节车厢用时$t_n=\\sqrt{n}\\cdot t_1$；由$6\\sqrt{N}=18$得共9节；前12s通过$6\\sqrt{N}=12$即4节（第2个6s内通过3节）；最后一节用时=通过9节总时-通过8节总时=$18-6\\sqrt{8}=18-12\\sqrt{2}\\ \\mathrm{s}$】；警惕【节数与时间不是线性关系（差一个$\\sqrt{}$），前12s通过的远多于半数车厢；求某时段通过节数必须用两个$\\sqrt{N}$的值相减】","src":"跳跳物一轮01.6 匀变速直线运动推论_笔记","note":"视频|17:38","orig":"（例）列车由静止开始匀加速直线运动，前端通过立柱：第一节车厢（前端到末端）通过立柱用时6s，全部车厢通过立柱用时18s。求车厢总节数、前12s内通过的车厢数、最后一节车厢通过立柱的时间。","link":""},{"id":"phy2060","t":"匀变速推论·纸带数据分析（均速法+逐差法）","s":"看到【纸带打点问题，求某点瞬时速度、加速度或判断打点先后】","c":"想到【先换算时间：打点周期$0.02\\ \\mathrm{s}$，相邻计数点间隔$T=0.02\\times 5=0.1\\ \\mathrm{s}$，跨两点$0.2\\ \\mathrm{s}$；最先打出的点是间距最小处（匀加速位移随时间增大）；C点速度用均速法$v_C=x_{BD}/t_{BD}=4.65\\times 10^{-2}\\div 0.2\\approx 0.233\\ \\mathrm{m/s}$；加速度取大整段（AC、CE各$0.2\\ \\mathrm{s}$）用位移差公式$a=(x_{CE}-x_{AC})/0.2^2=0.75\\ \\mathrm{m/s^2}$，多用数据减小误差（即逐差法思想）】；警惕【点距cm忘换成m；大整段时间是$0.2\\ \\mathrm{s}$，代成$0.1\\ \\mathrm{s}$则加速度差4倍】","src":"跳跳物一轮01.6 匀变速直线运动推论_笔记","note":"视频|30:02","orig":"（例）物块沿倾斜木板匀加速下滑打纸带，交流电频率50Hz，相邻计数点间有4个点未画出；图中各点间距依次增大，其中$x_{AC}=3.15\\ \\mathrm{cm}$、$x_{BD}=4.65\\ \\mathrm{cm}$、$x_{CE}=6.15\\ \\mathrm{cm}$。判断最先打出的点，求C点速度和物块加速度。","link":""},{"id":"phy2061","t":"自由落体与竖直上抛·自由落体三公式","s":"看到【物体从静止开始只受重力下落，求某时刻速度、下落高度或时间】","c":"想到【三公式：$v=gt$、$h=\\frac{1}{2}gt^2$、$v^2=2gh$，位移用$h$表示下落高度；竖直上抛的上升段是末速度为零的匀减速，公式形式相同：$v_0=gt$、$h=\\frac{1}{2}gt^2$、$v_0^2=2gh$】；警惕【上升段公式中的$v_0$是减速到零的过程量，与自由落体从零加速物理意义相反，勿混用】","src":"跳跳物一轮01.7 自由落体与竖直上抛_笔记","note":"视频|00:42","orig":"（知识）自由落体是初速度为零、只受重力的运动，即加速度为g的匀加速直线运动。","link":""},{"id":"phy2062","t":"自由落体与竖直上抛·零点推论等时与等距划分","s":"看到【自由落体每隔相等时间释放一物（水滴）或将下落高度等分，问时间或位移比例】","c":"想到【等时划分（从零点起）：连续相等时间内位移比为$1:3:5:7$…，如水滴每隔$T$滴一滴，相邻水滴间距之比即此；等距划分（从零点起）：通过连续相等高度的时间比为$1:(\\sqrt{2}-1):(\\sqrt{3}-\\sqrt{2})$…，如前后两半段用时比为$1:(\\sqrt{2}-1)$】；警惕【比例只对从释放点开始的划分成立，中间截取的段不满足$1:3:5:7$，此时改用位移差公式$\\Delta x=aT^2$处理】","src":"跳跳物一轮01.7 自由落体与竖直上抛_笔记","note":"视频|08:49","orig":"（知识）自由落体从释放点开始的等时划分和等距划分有固定比例结论。","link":""},{"id":"phy2063","t":"自由落体与竖直上抛·分段法与全程法","s":"看到【竖直上抛已知初速度和总时间（总时间可超过上升时间），求路程、位移大小与方向】","c":"想到【分段法：上升时间$t=v_0/g$，分别求上升高度$h_1$与下落高度$h_2$，路程$=h_1+h_2$，位移大小$=|h_1-h_2|$，$h_1>h_2$位移向上、$h_2>h_1$位移向下；全程法（只用于位移）：取向上为正，$x=v_0t+\\frac{1}{2}gt^2$，$v_0$代正值、$g$代负值，公式一律写加号，$x$的正负即位移方向】；警惕【路程只能用分段法、不能用全程法；全程法忘记给$g$代负号会得到错误方向】","src":"跳跳物一轮01.7 自由落体与竖直上抛_笔记","note":"视频|02:56-05:12","orig":"（知识）求竖直上抛的路程与位移：分段法与全程法分工不同。","link":""},{"id":"phy2064","t":"自由落体与竖直上抛·竖直上抛对称性","s":"看到【竖直上抛物体两次经过同一位置，问两次速度大小关系或上升与回落时间】","c":"想到【速度对称：两次经过同一位置的速度大小相等、方向相反；时间对称：从某点到最高点的时间等于从最高点落回该点的时间；可推广到轨迹上任意两点，A到B与B到A用时相等、末速度大小对称】；警惕【对称给出的是速度大小相等而方向相反，列矢量方程时必须带正负号，勿直接相等】","src":"跳跳物一轮01.7 自由落体与竖直上抛_笔记","note":"视频|07:31","orig":"（知识）竖直上抛轨迹上任一点与最高点之间的往返运动对称。","link":""},{"id":"phy2065","t":"自由落体与竖直上抛·频闪照片分析","s":"看到【频闪照片给出自由落体连续相等时间的各段位移，问首位置是否为释放点、求加速度或某点速度】","c":"想到【判初始位置：从零点等时下落位移比应为$1:3:5:7$，实际$2:3:4:5$不符，位置1不是释放点；求加速度：连续相等时间位移差恒为$d$，由$\\Delta x=aT^2$得$a=d/T^2$；求某点速度：该点是前后两段的中间时刻，瞬时速度等于该两段的平均速度，$v_3=(3d+4d)/(2T)=7d/(2T)$】；警惕【比例不符只说明不从零点开始，不代表不是匀变速；中间时刻法的位移要取包含该点的前后两段之和】","src":"跳跳物一轮01.7 自由落体与竖直上抛_笔记","note":"视频|15:45","orig":"（例）频闪照片记录物体连续相等时间T的位置，各段位移依次为2d、3d、4d、5d，判断第一个位置是否为释放点，并求加速度与位置3的瞬时速度。","link":""},{"id":"phy2066","t":"自由落体与竖直上抛·竖直上抛运动图像","s":"看到【竖直上抛运动的v-t或x-t图像选择题，判断图线形状及过轴含义】","c":"想到【v-t图像：全程匀变速，是一条倾斜直线，图线穿过t轴表示速度减为零并掉头，t轴上方为向上匀减速、下方为向下匀加速；x-t图像：一定是曲线，上升段逐渐平缓（速度减小）、越过最高点后下降段逐渐陡峭（速度增大）】；警惕【只有匀速直线运动的x-t图才是直线，匀变速的x-t图必为曲线；v-t图穿t轴对应到达最高点，并非位移为零】","src":"跳跳物一轮01.7 自由落体与竖直上抛_笔记","note":"视频|18:43","orig":"（知识）竖直上抛的v-t图像与x-t图像特征不同。","link":""},{"id":"phy2067","t":"自由落体与竖直上抛·速度改变量与平均速度","s":"看到【竖直上抛已知初速度和总时间，求速度改变量、平均速度或平均速率】","c":"想到【先求上升时间$t=v_0/g$，把总时间拆成上升与下落两段；速度改变量是矢量差，初末速度反向时大小相加（如初速度$30\\ \\mathrm{m/s}$向上、末速度$20\\ \\mathrm{m/s}$向下，改变量$=30+20=50\\ \\mathrm{m/s}$）；平均速度=位移/总时间（带方向），平均速率=路程/总时间】；警惕【初末速度反向时直接大减小会漏掉方向反转；平均速度对应位移、平均速率对应路程，二者不可互换】","src":"跳跳物一轮01.7 自由落体与竖直上抛_笔记","note":"视频|25:02","orig":"（知识）竖直上抛计算中速度改变量与平均速度是易错量。","link":""},{"id":"phy2068","t":"自由落体与竖直上抛·上抛与自由落体相遇临界","s":"看到【一球竖直上抛、另一球同时自由下落，判断在最高点、途中还是地面相遇的条件】","c":"想到【两个临界：$v_0=\\sqrt{gH}$时恰在B球最高点相遇；$v_0=\\sqrt{gH/2}$时恰在地面相遇。分类：$v_0>\\sqrt{gH}$在上升途中相遇；$\\sqrt{gH/2}<v_0<\\sqrt{gH}$在下落途中相遇；$v_0<\\sqrt{gH/2}$时B球先落地、待A球落地时才相遇】；警惕【$H$是两球初始高度差，临界式由相遇条件（两球位移之和等于$H$或时间相等）联立得出，勿把$H$当成单球上升高度】","src":"跳跳物一轮01.7 自由落体与竖直上抛_笔记","note":"视频|28:55","orig":"（知识）B球从地面竖直上抛的同时，A球从高H处自由下落，相遇位置由初速度v$_0$决定。","link":""},{"id":"phy2069","t":"追及相遇·距离公式与前后车判定","s":"看到【两物体沿同一直线一前一后运动，求某时刻两者距离或判断谁在前】","c":"想到【距离公式$x=D_0+x_1-x_2$（$D_0$为初始距离，$x_1$为前车位移、$x_2$为后车位移）；谁是前车、谁是后车以开始运动时刻的位置为准，一旦确定全程不变，中途反超也不调换；$x>0$前车仍在前，$x<0$后车已反超】；警惕【反超后仍要用初始前车的位移代入$x_1$，不能中途换人；$D_0$是零时刻的距离，不是任意时刻的距离】","src":"跳跳物一轮01.8 追及相遇问题_直线运动模块完结撒花~_笔记","note":"视频|01:22-03:12","orig":"（知识）追及相遇问题的核心工具是距离公式，前后车身份以初始位置判定。","link":""},{"id":"phy2070","t":"追及相遇·不同时出发时D₀的选取","s":"看到【追及相遇中两物体开始运动时刻不同，需要确定距离公式中的初始距离】","c":"想到【以后动物体开始运动的时刻为零时刻，$D_0$取该时刻两物体的距离：先动物体已走过的位移要补进初始距离，即$D_0=$原间距$+$先动物体已发生的位移，如$3\\ \\mathrm{m}+2\\ \\mathrm{m/s}\\times 2\\ \\mathrm{s}=7\\ \\mathrm{m}$】；警惕【$D_0$不能直接取题目最初给的距离，两物体不同时出发时先动物体的位移已改变零时刻间距】","src":"跳跳物一轮01.8 追及相遇问题_直线运动模块完结撒花~_笔记","note":"视频|05:31","orig":"（例）A、B两物体相距3 m均静止，B先以2 m/s向右匀速运动，2 s后A才开始向右运动，求以A出发时刻为零时刻的初始距离D$_0$。","link":""},{"id":"phy2071","t":"追及相遇·距离函数的单调性与最值","s":"看到【追及相遇中分析两车距离如何随时间变化、何时相距最远或最近】","c":"想到【至少一车匀变速时$x$关于$t$必为二次函数，图像是抛物线；单调性由速度差决定：前车速度大于后车速度时距离增大，前车速度小于后车速度时距离减小；两车共速时距离取最值，抛物线开口向上取最小值（最近）、开口向下取最大值（最远）】；警惕【共速时刻是距离的极值点而不是相遇时刻；两车加速度相同时二次项抵消、无极值】","src":"跳跳物一轮01.8 追及相遇问题_直线运动模块完结撒花~_笔记","note":"视频|06:47-11:22","orig":"（知识）两车距离x随时间t的变化是二次函数，单调性和最值有固定规律。","link":""},{"id":"phy2072","t":"追及相遇·相遇时间与次数的计算","s":"看到【已知两车运动规律和初始距离，求相遇时刻或判断相遇几次】","c":"想到【三步走：先确定前后车并算出$D_0$；把两车位移公式代入距离公式得到$x$关于$t$的函数；令$x=0$解二次方程，正数解即相遇时刻，正数解的个数即相遇次数】；警惕【负数解无物理意义必须舍去；两车不同时出发时要先折算$D_0$再列式，否则零点全错】","src":"跳跳物一轮01.8 追及相遇问题_直线运动模块完结撒花~_笔记","note":"视频|12:24","orig":"（知识）计算相遇时间和次数的标准流程是解距离函数的零点。","link":""},{"id":"phy2073","t":"追及相遇·由v-t图画距离-时间图","s":"看到【给出两车v-t图像，判断相遇次数、何时刻最远最近或谁在前】","c":"想到【画距离x-t图抓三个关键点：纵截距为$D_0$且必在正半轴；单调性看前车速度减后车速度的正负（对照v-t图线的上下位置）；最值在两图线交点即共速时刻取得；图线与时间轴的交点个数即相遇次数】；警惕【v-t图本身无法确定初始谁前谁后，必须结合题目条件（如相遇时刻、选项描述）分情况讨论；此x-t图的$x$是两车距离而非位置】","src":"跳跳物一轮01.8 追及相遇问题_直线运动模块完结撒花~_笔记","note":"视频|14:03-17:11","orig":"（知识）已知v-t图分析追及相遇，核心方法是画出两车距离随时间变化的x-t图。","link":""},{"id":"phy2074","t":"追及相遇·距离图增减顺序与相遇次数","s":"看到【距离随时间先减小后增大（或先增大后减小），判断两车相遇次数】","c":"想到【先增后减：图像与时间轴必有且只有一个交点，一定相遇一次，无需分析最值；先减后增：交点个数不确定，必须看最小值正负——最小值大于$0$不相遇、等于$0$相遇一次（恰在共速时刻相遇）、小于$0$相遇两次】；警惕【先减后增时漏判最小值正负就直接下结论；最小值等于$0$对应恰好共速时相遇的临界情形，勿当成两次】","src":"跳跳物一轮01.8 追及相遇问题_直线运动模块完结撒花~_笔记","note":"视频|17:11","orig":"（知识）距离x-t抛物线先增后减还是先减后增，决定相遇次数的判定方式。","link":""},{"id":"phy2075","t":"追及相遇·v-t图与对称性定再次相遇","s":"看到【已知两车v-t图和某时刻相遇，判断初始前后、某时刻谁在前及再次相遇时刻】","c":"想到【先用v-t图面积（位移）判前后：0~5 s甲位移大于乙而5 s末相遇，说明初始乙在前；画距离图：0~10 s距离减小、10 s后增大，$t=5\\ \\mathrm{s}$是第一个交点；抛物线关于共速时刻（对称轴）对称，两交点关于对称轴对称，故第二次相遇在$t=15\\ \\mathrm{s}$；各时刻$x$的正负判断谁在前】；警惕【v-t图线下面积差才是位移差；共速时刻对应距离最小值（最近）而非相遇时刻】","src":"跳跳物一轮01.8 追及相遇问题_直线运动模块完结撒花~_笔记","note":"视频|30:50","orig":"（例）甲、乙两车v-t图中甲的图线更陡，0~10 s内甲速度大于乙、10 s后乙速度大于甲，两车在t=5 s时相遇，判断初始位置关系及t=3 s、12 s、15 s时的情况。","link":""},{"id":"phy2076","t":"追及相遇·匀加速与匀速两次相遇计算","s":"看到【匀加速与匀速两车追及，给初始距离，求相遇时间间隔或能相遇两次的距离范围】","c":"想到【建距离函数$x=D_0+\\frac{1}{2}at^2-vt$，令$x=0$解二次方程，两正根之差即时间间隔（如$D_0=4\\ \\mathrm{m}$、$a=1\\ \\mathrm{m/s^2}$、$v=3\\ \\mathrm{m/s}$时$t_1=2\\ \\mathrm{s}$、$t_2=4\\ \\mathrm{s}$，间隔$2\\ \\mathrm{s}$）；相遇两次的条件是最小值小于零：共速时刻$t=v/a$处距离最小值为$D_0-v^2/(2a)$，令其小于零得$D_0<v^2/(2a)$（本题为$4.5\\ \\mathrm{m}$）】；警惕【最小值等于零只相遇一次（恰在共速时追上），不是两次；前车加速会导致追上后再被拉开，形成第二次相遇】","src":"跳跳物一轮01.8 追及相遇问题_直线运动模块完结撒花~_笔记","note":"视频|26:07","orig":"（例）前车从静止以1 m/s$^2$匀加速，后车以3 m/s匀速追赶，初始相距4 m，求两次相遇的时间间隔；并求要相遇两次，初始距离不能超过多少。","link":""},{"id":"phy2077","t":"重力·方向与重心","s":"看到【判断重力方向的表述（如垂直于地面、指向地心）或重心位置的陈述】","c":"想到【重力$G=mg$，方向竖直向下，等价说法：沿重锤线向下、自由落体方向、垂直于水平面；重心是人为等效的作用点，物体各部分均受重力，重心不一定在物体上（铁环重心在环心），质量分布均匀且形状规则时重心才在几何中心】；警惕【垂直于地面、指向地心（仅赤道和两极成立）、垂直于接触面（斜面上不成立）均为错误说法；静止物体对水平面的压力是弹力，不是重力】","src":"跳跳物一轮02.1 重力、弹力、摩擦力基本概念_笔记","note":"视频|00:24-01:06","orig":"（知识）重力的大小、方向和重心是基本概念，方向说法有多个易错点。","link":""},{"id":"phy2078","t":"弹力·产生条件与形变来源","s":"看到【判断两接触物体间有无弹力，或弹力由谁的形变产生】","c":"想到【产生条件：直接接触且接触处发生弹性形变，缺一不可；弹力由施力物体的形变产生——分析A对B的弹力，是A发生形变、要恢复原状而施加给B的力】；警惕【两物体只是轻轻挨着、虽接触但无形变时无弹力；勿把受力物体的形变当成弹力来源】","src":"跳跳物一轮02.1 重力、弹力、摩擦力基本概念_笔记","note":"视频|03:33-04:36","orig":"（知识）弹力的产生需要两个条件，且来源于施力物体的形变。","link":""},{"id":"phy2079","t":"弹力·绳与杆的弹力方向","s":"看到【绳或杆连接（支撑）物体，判断弹力方向是否沿绳或沿杆】","c":"想到【绳的弹力一定沿绳，指向绳子收缩的方向；杆的弹力不一定沿杆，需结合平衡条件分析，如杆支撑小球静止时球只受重力与杆的弹力，二力平衡，故弹力竖直向上而非沿杆】；警惕【见到杆就默认弹力沿杆是典型错误；绳只能施加拉力不能推，杆的弹力可沿任意方向】","src":"跳跳物一轮02.1 重力、弹力、摩擦力基本概念_笔记","note":"视频|05:17","orig":"（知识）绳和杆的弹力方向规律不同。","link":""},{"id":"phy2080","t":"弹力·弹力与接触面的方向关系","s":"看到【点与面、点与球面或两球面接触，判断弹力方向】","c":"想到【弹力一定垂直于接触面：平面接触垂直于平面；尖点与平面接触垂直于平面；尖点与球面接触先过接触点作球面的切面，弹力垂直该切面；两球面接触过接触点作公切面，弹力垂直公切面（如碗对筷子的弹力指向碗的球心）】；警惕【曲面接触不能直接沿曲面画弹力，必须先作切面再作垂线；碗对筷子的弹力不沿筷子方向】","src":"跳跳物一轮02.1 重力、弹力、摩擦力基本概念_笔记","note":"视频|06:44","orig":"（知识）弹力方向一定垂直于接触面，不同接触类型的作法不同。","link":""},{"id":"phy2081","t":"弹力·拆除法判断弹力有无","s":"看到【物体与多个面（物体）接触，判断某个接触处有无弹力或支持力】","c":"想到【拆除法：假想把待判断的面（或物体）拆掉，若物体仍能保持原状态（静止），则该面上无弹力；若物体不能保持静止（会掉落、滑动、荡起），则该面上有弹力；原理是拆除后弹力消失、合力不再为零】；警惕【接触不等于挤压，无形变就无弹力；只能拆待判断的那个面，拆错对象结论全错】","src":"跳跳物一轮02.1 重力、弹力、摩擦力基本概念_笔记","note":"视频|08:00","orig":"（知识）判断某个接触面是否存在弹力用拆除法。","link":""},{"id":"phy2082","t":"摩擦力·滑动摩擦力","s":"看到【接触面粗糙且发生相对滑动，求摩擦力大小或判断谁受滑动摩擦】","c":"想到【大小$f=\\mu N$，$N$为接触面正压力；产生条件：接触面粗糙、接触并挤压、有相对运动；摩擦力与对地运动状态无关——静止的物体也能受滑动摩擦力（如擦黑板时静止的黑板）】；警惕【不能无脑用$f=\\mu mg$，只有正压力$N$等于重力$mg$时才成立，存在其他竖直方向外力（如向下按压）时须先求$N$再算摩擦力】","src":"跳跳物一轮02.1 重力、弹力、摩擦力基本概念_笔记","note":"视频|11:12","orig":"（知识）滑动摩擦力的大小、产生条件和易错点。","link":""},{"id":"phy2083","t":"摩擦力·静摩擦力","s":"看到【物体相对静止但有相对运动趋势，求静摩擦力大小或范围】","c":"想到【大小范围$0<f\\le f_{max}$（$f_{max}$为最大静摩擦力）；平衡状态用平衡法：静摩擦与外力平衡（受$3\\ \\mathrm{N}$水平拉力静止则静摩擦为$3\\ \\mathrm{N}$）；非平衡状态用牛顿第二定律（板块一起加速时静摩擦提供加速度）；无特殊说明时认为最大静摩擦等于滑动摩擦$\\mu N$】；警惕【静摩擦力大小与正压力无关，但最大静摩擦与正压力成正比；运动的物体也可受静摩擦力（板块一起运动时）】","src":"跳跳物一轮02.1 重力、弹力、摩擦力基本概念_笔记","note":"视频|14:20","orig":"（知识）静摩擦力没有直接计算公式，按运动状态分类求解。","link":""},{"id":"phy2084","t":"摩擦力·五个一定与五个不一定","s":"看到【判断摩擦力与粗糙、弹力、运动方向、静止之间关系的概念性说法】","c":"想到【五个一定：有摩擦则接触面粗糙、有弹力，方向与相对运动（趋势）相反，一定阻碍相对运动，受静摩擦则两物体相对静止；五个不一定：粗糙未必有摩擦，有弹力未必有摩擦，方向未必与运动方向相反（可与速度不共线），未必阻碍运动（可为动力，如人走路），受静摩擦未必对地静止（板块一起运动）】；警惕【核心是看相对运动而非对地运动；只有滑动摩擦大小与正压力成正比，静摩擦大小与正压力无关】","src":"跳跳物一轮02.1 重力、弹力、摩擦力基本概念_笔记","note":"视频|18:10","orig":"（知识）摩擦力的存在、方向和作用效果有一组「一定与不一定」结论。","link":""},{"id":"phy2085","t":"相互作用·弹簧弹力方向判定","s":"看到【弹簧处于拉伸或压缩状态，判断弹簧对两端所连物体的弹力方向】","c":"想到【弹力沿弹簧轴线指向恢复原长的方向：被拉伸时两端弹力都指向弹簧内侧（往回缩），被压缩时两端弹力都指向弹簧外侧（往回顶）；两端弹力大小相等、方向相反，各作用在自己所连的物体上；原长状态弹力为零】；警惕【把弹簧两端的弹力相加当“合力”——两力作用在不同物体上不能求和；把弹簧弹力当成弹簧受到的合力】","src":"跳跳物一轮02.2 弹簧弹力问题_笔记","note":"视频|00:24","orig":"（知识）弹簧弹力是弹簧自身发生形变而产生的力，施力物体是弹簧，受力物体是两端所连的物体。","link":""},{"id":"phy2086","t":"相互作用·胡克定律","s":"看到【已知弹簧弹力与形变量（或长度）求劲度系数，或由劲度系数求弹力、形变量】","c":"想到【$F=kx$中$F$是弹簧一端的弹力大小而非两端之和，弹簧测力计读数也等于一端弹力；$x$是形变量（当前长度与原长之差的绝对值），不是弹簧总长度；$k$是描述弹簧软硬的自身属性，与是否挂重物无关；单位要配套：$x$用米则$k$用$\\mathrm{N/m}$，$x$用厘米则$k$用$\\mathrm{N/cm}$】；警惕【把弹簧总长度当形变量代入；两端各受拉力$F$时误以为弹簧弹力是$2F$】","src":"跳跳物一轮02.2 弹簧弹力问题_笔记","note":"视频|04:49","orig":"（知识）弹性限度内，弹簧弹力大小与形变量成正比，即胡克定律。","link":""},{"id":"phy2087","t":"相互作用·弹簧两端受力与形变量判断","s":"看到【相同弹簧一端被墙固定另一端受拉力$F$，与两端各受拉力$F$的情形比较弹力或形变量】","c":"想到【弹簧弹力只由一端受力决定：两种情况弹簧一端的弹力都是$F$，$k$相同，由$F=kx$知形变量必然相同；墙对固定端的拉力与人的拉力平衡，与两端人拉在本质上完全等效】；警惕【被“一端一人拉、另一端两人拉”的人数表象迷惑，误认为受力的端多则弹簧弹力或形变量加倍】","src":"跳跳物一轮02.2 弹簧弹力问题_笔记","note":"视频|05:32","orig":"（例）两根完全相同的弹簧：一根左端固定在墙上、右端受人的水平拉力$F$；另一根左右两端各受大小均为$F$的拉力。比较两弹簧的形变量大小。","link":""},{"id":"phy2088","t":"相互作用·弹簧F-x图像","s":"看到【给出弹簧的$F$-$x$图像，横轴为总长度或形变量，问原长、劲度系数或伸长量】","c":"想到【图线斜率表示劲度系数$k$，斜率大者$k$大；横轴为总长度时图线不过原点，横截距即弹簧原长；横轴为形变量时图线过原点、横截距为零；已知弹力求伸长量用$\\Delta x=F/k$】；警惕【把横截距误当伸长量；用总长度直接当形变量代入$F=kx$（须先减去原长）】","src":"跳跳物一轮02.2 弹簧弹力问题_笔记","note":"视频|07:48","orig":"（知识）弹簧弹力$F$随长度$x$变化的图像。","link":""},{"id":"phy2089","t":"相互作用·弹簧串并联","s":"看到【多根弹簧串联或并联，求等效劲度系数或各弹簧的弹力、形变量分配】","c":"想到【串联：各弹簧弹力大小相等（由牛顿第三定律沿连接点逐段传递），总形变量等于各形变量之和，故各弹簧形变量与劲度系数成反比，等效劲度系数满足$1/k=1/k_1+1/k_2+\\cdots$，比任一根都小；并联：各弹簧形变量相等，总弹力等于各弹力之和，等效劲度系数$k=k_1+k_2+\\cdots$，比任一根都大】；警惕【把两种关系记反——串联是形变量相加、弹力相等，并联是弹力相加、形变量相等】","src":"跳跳物一轮02.2 弹簧弹力问题_笔记","note":"视频|08:36","orig":"（知识）弹簧串联、并联时弹力与形变量的分配规律及等效劲度系数。","link":""},{"id":"phy2090","t":"相互作用·弹簧两次受力问题","s":"看到【弹簧两次受力而原长未知，给两次弹力（或对应物重）与两次长度，求$k$或原长】","c":"想到【对两次状态分别列胡克定律再相加减消去原长：两次同为拉伸或同为压缩时，弹力之差等于$k$乘两次总长度之差，$|F_2-F_1|=k\\cdot|L_2-L_1|$；一次拉伸一次压缩时，弹力之和等于$k$乘两次总长度之差，$|F_1+F_2|=k\\cdot|L_2-L_1|$；解出$k$后回代任一次方程可得原长】；警惕【式中的长度是弹簧总长度而非形变量；两次同向时误用求和、一拉一压时误用做差】","src":"跳跳物一轮02.2 弹簧弹力问题_笔记","note":"视频|12:14","orig":"（知识）弹簧两次受力而原长未知时，用两次胡克定律方程相加减消去原长直接求$k$。","link":""},{"id":"phy2091","t":"相互作用·弹簧串并联综合计算","s":"看到【坐垫类多弹簧系统：每组合两根串联、各组间并联，给总压力、总形变与单弹簧劲度系数，求数量】","c":"想到【按整体→组→单根逐层分析：整体弹力等于总压力、总形变量已知；各组并联，每组弹力=总弹力/组数，每组形变量等于总形变量；组内两根串联，每根弹力等于组弹力，每根形变量为组形变量的一半；对单根列$F=kx$解出组数，总根数=组数$\\times$每组合数（本例200组共400根）】；警惕【组内串联时把弹力也平分——串联弹力相等、形变量才相加；厘米未化成米；总数漏乘每组合数】","src":"跳跳物一轮02.2 弹簧弹力问题_笔记","note":"视频|21:41","orig":"（例）坐垫由若干组相同的弹簧组并联组成，每组由两根劲度系数均为$10\\,\\mathrm{N/m}$的相同弹簧串联而成。体重$100\\,\\mathrm{N}$的人坐在坐垫上，坐垫总形变量为$10\\,\\mathrm{cm}$，求弹簧总根数。","link":""},{"id":"phy2092","t":"相互作用·弹簧状态变化计算","s":"看到【弹簧由压缩变为拉伸（形变跨越原长），给前后两态弹力，求劲度系数或端点移动距离】","c":"想到【两态分别用胡克定律：初态压缩量=$F_1/k$，末态拉伸量=$F_2/k$（“刚好离开地面”意味着支持力为零，弹力恰等于该物块重力）；形变跨越原长，端点移动距离=压缩量+拉伸量=$(F_1+F_2)/k$，A提升的高度即弹簧长度的总变化量】；警惕【把移动距离当成两次形变量之差——压缩与拉伸方向相反，必须相加；忽略末态“刚好离地”隐含的临界条件】","src":"跳跳物一轮02.2 弹簧弹力问题_笔记","note":"视频|26:41","orig":"（例）A、B两物块与竖直弹簧相连，g取$10\\,\\mathrm{m/s^2}$。初始弹簧被压缩$10\\,\\mathrm{cm}$，弹力恰等于质量$1\\,\\mathrm{kg}$的A的重力（$10\\,\\mathrm{N}$）；现向上拉A，直到质量$2\\,\\mathrm{kg}$的B刚好离开地面，此时弹簧变为拉伸，弹力恰等于B的重力（$20\\,\\mathrm{N}$）。求劲度系数和A被提升的高度。","link":""},{"id":"phy2093","t":"相互作用·滑动摩擦力方向","s":"看到【问“A对B”的滑动摩擦力方向，或叠放物体间相对运动方向不直观】","c":"想到【滑动摩擦力方向与相对运动方向相反，分析时无需考虑物体受力情况；研究对象是受力物体：分析“A对B”时看B相对A的运动方向，摩擦力与它相反；分析地面对物体的摩擦力时默认以大地为参考系，直接看物体运动方向即可】；警惕【把相对运动方向看反——应看受力物体相对施力物体的运动，而不是施力物体相对受力物体的运动】","src":"跳跳物一轮02.3 摩擦力常考问题_笔记","note":"视频|00:30","orig":"（知识）滑动摩擦力的方向判定原则。","link":""},{"id":"phy2094","t":"相互作用·滑动摩擦与最大静摩擦计算","s":"看到【叠放物体模型中计算某接触面的滑动摩擦力或最大静摩擦力大小】","c":"想到【滑动摩擦力$F=\\mu N$，计算题中最大静摩擦力也取$\\mu N$；正压力$N$只由接触面上方的物体决定：无外力按压或上拉时，$N$等于接触面上方所有物体的总重力；如A压在B上，AB间$N$等于A的重力，与B及更下方物体的重力无关】；警惕【把接触面下方物体的重力计入$N$；有外力按压或上拉时仍套用$N$=上方总重力】","src":"跳跳物一轮02.3 摩擦力常考问题_笔记","note":"视频|02:16","orig":"（知识）叠块模型中滑动摩擦力与最大静摩擦力的计算。","link":""},{"id":"phy2095","t":"相互作用·静摩擦力状态反推法","s":"看到【物体静止或匀速直线运动，判断接触面间静摩擦力的有无、方向或大小】","c":"想到【状态反推法：先确认物体处于平衡状态（合力为零）；沿接触面方向求除摩擦力外其他力的合力，所需静摩擦力与该合力等大反向；若沿接触面无其他力则摩擦力为零；再用牛顿第三定律确定另一物体受到的摩擦力（等大反向）】；警惕【误以为维持匀速运动需要摩擦力——匀速靠惯性维持；把静摩擦力当成固定值——其大小由其他力反推决定】","src":"跳跳物一轮02.3 摩擦力常考问题_笔记","note":"视频|04:15","orig":"（知识）静摩擦力的有无、方向与大小用状态反推法分析。","link":""},{"id":"phy2096","t":"相互作用·传送带匀速运动的摩擦力","s":"看到【物体随传送带匀速运动（水平带或倾斜带），判断摩擦力有无及方向】","c":"想到【匀速即合力为零，摩擦力只负责平衡其他力沿传送带的分量：水平传送带上物体不受其他水平力则无摩擦；倾斜传送带上重力沿传送带的分量恒向下，故无论物体随带向上还是向下匀速运动，摩擦力都沿传送带向上；若传送带加速（水平），摩擦力方向沿加速度方向】；警惕【用运动方向判摩擦力方向——倾斜带上向下匀速运动时摩擦力仍沿带向上】","src":"跳跳物一轮02.3 摩擦力常考问题_笔记","note":"视频|14:00","orig":"（知识）物体随传送带匀速运动时摩擦力的有无与方向。","link":""},{"id":"phy2097","t":"相互作用·最大静摩擦与滑动摩擦突变","s":"看到【水平拉力从零逐渐增大，画或判断摩擦力随拉力变化的图像】","c":"想到【静摩擦阶段摩擦力随拉力等大增大；达到最大静摩擦力后物体被拉动，摩擦力突降为滑动摩擦力$\\mu N$并保持不变；图像题中最大静摩擦略大于滑动摩擦，图像须画出突降台阶；计算题中默认最大静摩擦等于滑动摩擦】；警惕【把图像画成平滑过渡——静摩擦段结束后应有突然下降；计算题与图像题对两者大小关系的处理不同（相等与略大）】","src":"跳跳物一轮02.3 摩擦力常考问题_笔记","note":"视频|14:00","orig":"（知识）拉力从零增大过程中摩擦力的变化与图像突变。","link":""},{"id":"phy2098","t":"相互作用·能否保持静止的判断","s":"看到【平衡物体所受的其他力发生变化，问是否仍保持静止及摩擦力方向如何变】","c":"想到【先假设仍静止，用合力为零反推所需静摩擦力（与其余力的合力等大反向）；用初始静止状态确定最大静摩擦的下限（至少等于初始所需的静摩擦力），新的所需值不超过该下限则仍静止；物体未动则弹簧长度不变、读数不变】；警惕【认为其他力变了摩擦力方向不变——所需静摩擦方向随合外力方向翻转（本例由向左变为向右）；漏用“初始能静止”这一隐含条件估出最大静摩擦下限】","src":"跳跳物一轮02.3 摩擦力常考问题_笔记","note":"视频|14:00","orig":"（例）木块A静止在水平桌面上，右端绕过定滑轮的轻绳挂总重10N的砝码（绳对A的拉力水平向右），左端连一弹簧测力计（对A的拉力水平向左，读数6N）。现将砝码减为总重2N，判断A是否仍静止、桌面对A的摩擦力方向如何变化、弹簧测力计读数是否变化。","link":""},{"id":"phy2099","t":"相互作用·板块模型摩擦力与临界条件","s":"看到【板块模型中外力拉上方木块，问木板相对地面是否滑动或求不滑动的条件】","c":"想到【一起运动时块与板间为静摩擦（大小由平衡或牛顿定律反推，不一定达最大值）；发生相对滑动后块对板为滑动摩擦，大小为$\\mu_1$乘以木块重力；地面给板的最大静摩擦为$\\mu_2$乘以板与块的总重力；$F$极大时块在板上滑动，板不被带动的条件是地面最大静摩擦$\\geq$块对板的滑动摩擦，即$\\mu_1\\le 3\\mu_2$】；警惕【认为$F$越大板越容易滑动——$F$作用在块上，板是否滑动只取决于块对板的摩擦与地面最大静摩擦的比较；把一起运动时的静摩擦当成最大静摩擦计算】","src":"跳跳物一轮02.3 摩擦力常考问题_笔记","note":"视频|14:00","orig":"（例）质量$M$的木块放在质量$2M$的长木板上，板置于水平地面；块与板间动摩擦因数为$\\mu_1$，板与地面间为$\\mu_2$。用水平力$F$向右拉木块，问无论$F$多大长木板都不相对地面滑动的条件。","link":""},{"id":"phy2100","t":"相互作用·合力与分力等效替代","s":"看到【判断几个力与某个力是否为合力与分力关系，或受力分析中合力和分力同时出现】","c":"想到【合力的作用效果与几个分力的共同作用效果完全相同，效果相同即可互相替代（如右灯两绳拉力的共同效果与左灯单绳拉力相同，则前者是分力、后者是合力）；合力与分力不能同时作用在物体上，受力分析时要么用分力、要么用合力，不能重复计入】；警惕【把合力与分力同时计入受力分析造成重复；认为效果不同的力也等效——如拉力向上、重力向下，方向不同不能等效】","src":"跳跳物一轮02.4 力的合成_笔记","note":"视频|00:19","orig":"（知识）合力与分力是等效替代关系。","link":""},{"id":"phy2101","t":"相互作用·求合力的条件","s":"看到【对不同物体的两个力（如一对相互作用力）求合力或说它们合力为零】","c":"想到【只有作用在同一物体上的多个力才能求合力；一对相互作用力（如物块与地面间的摩擦力及反作用力）分别作用在两个物体上，不能求合力，更不能说它们的合力为零】；警惕【把作用在不同物体上的力当共点力合成；对相互作用力求和为零——作用对象不同谈不上抵消】","src":"跳跳物一轮02.4 力的合成_笔记","note":"视频|01:25","orig":"（知识）多个力能够求合力的前提条件。","link":""},{"id":"phy2102","t":"相互作用·平行四边形与三角形定则","s":"看到【两个力求合力，两力共起点或首尾相接，问用哪个定则或如何作图】","c":"想到【两力共起点用平行四边形定则：以两力为邻边作平行四边形，共起点的对角线即合力；两力首尾相接用三角形定则：从第一个力的起点指向第二个力终点的有向线段即合力；力可平移，两定则本质一致，可互相转换】；警惕【三角形定则把合力方向画反——应从第一个力的起点指向第二个力的终点；忽视两定则可互换而死用一种作图】","src":"跳跳物一轮02.4 力的合成_笔记","note":"视频|02:50","orig":"（知识）力的合成的平行四边形定则与三角形定则。","link":""},{"id":"phy2103","t":"相互作用·特殊夹角求合力","s":"看到【两力同向、反向或互相垂直，求合力大小】","c":"想到【同向（0°）：合力等于两力直接相加；反向（180°）：合力等于大力减小力，结果取正值；垂直（90°）：合力等于$\\sqrt{F_1^2+F_2^2}$（勾股定理）；其余夹角用平行四边形定则或三角形定则作图求解】；警惕【反向时两力直接相减出现负值——须用大减小保证合力为正；非特殊角仍套用加减或勾股】","src":"跳跳物一轮02.4 力的合成_笔记","note":"视频|03:49","orig":"（知识）两力夹角为0°、180°、90°时合力的速算。","link":""},{"id":"phy2104","t":"相互作用·合力与分力大小关系","s":"看到【判断“合力一定大于分力”“分力增大合力必增大”等说法的正误】","c":"想到【两个一定：夹角越大合力一定越小，夹角0°时合力最大等于两分力之和、180°时最小等于两分力之差；两分力同倍增大或减小，合力一定同倍变化。其余说法均不一定：合力不一定大于分力（等大反向两力合力为零）；某分力增大合力不一定增大（反向两力中增大较小分力，合力反而减小）】；警惕【绝对性描述（一定、只要…就…）通常错误，除非属于两个一定；判断时可用等大反向、反向增小力构造反例】","src":"跳跳物一轮02.4 力的合成_笔记","note":"视频|05:37","orig":"（知识）合力与分力大小关系中只有两个“一定”。","link":""},{"id":"phy2105","t":"相互作用·等大力合成特殊角结论","s":"看到【两个等大的力求合力，夹角为60°或120°，或弓弦、结点等对称情境】","c":"想到【特殊角结论：夹角0°合力$2F$，60°合力$\\sqrt{3}F$，90°合力$\\sqrt{2}F$，120°合力等于$F$，180°合力为零，其中60°和120°结论要重点记忆可秒杀高考题；非特殊角时合力=$2F\\cdot\\cos(\\alpha/2)$（$\\alpha$为两力夹角），用菱形对角线垂直构建直角三角形推导】；警惕【只背结论不懂菱形推导——一般角高考题需现场推导；三力平衡情境中把两等大力的合力方向画错，它应与第三个力等大反向】","src":"跳跳物一轮02.4 力的合成_笔记","note":"视频|07:48","orig":"（知识）两个大小相等的力（均为$F$）夹角特殊时的合力结论。","link":""},{"id":"phy2106","t":"相互作用·三力合力范围","s":"看到【三个大小一定的力方向不定，求合力最大值、最小值或判断合力能否为零】","c":"想到【两力的合力大小介于两力之差与两力之和之间（$|F_1-F_2|$到$F_1+F_2$）；三力合力最大值为三力同向相加；最小值：任取两力求其合力范围，第三个力落在范围内则三力合力最小值为零，不在范围内则用该范围内最接近第三个力的取值与第三个力大减小；判断合力能否为零等价于第三力是否落在前两力合力范围内】；警惕【不检验第三个力是否在前两力合力范围内就断言最小值为零——不在范围内时最小值不为零；范围端点须用大减小取正值】","src":"跳跳物一轮02.4 力的合成_笔记","note":"视频|11:06","orig":"（知识）三个大小一定、方向可变的力，合力的取值范围。","link":""},{"id":"phy2107","t":"相互作用·由合力极值反推分力","s":"看到【给两力同向时的合力与反向时的合力（或合力随夹角变化图像的两端点），反推两分力大小】","c":"想到【同向时合力最大等于两分力之和，反向时合力最小等于两分力之差（大减小）；据此列二元一次方程组：$F_1+F_2$等于最大值，$F_1-F_2$等于最小值，两式相加减即可解出两分力】；警惕【把反向时的合力当成两力之和；反向时忘记大减小、得出负值】","src":"跳跳物一轮02.4 力的合成_笔记","note":"视频|15:40","orig":"（例）两个共点力$F_1$、$F_2$（$F_1>F_2$）的夹角在0°到180°间变化。已知两力同向（夹角0°）时合力最大为5N，反向（夹角180°）时合力最小为1N，求$F_1$、$F_2$的大小。","link":""},{"id":"phy2108","t":"力的分解·分解的多解性与合成的唯一性","s":"看到【问力的分解方案是否唯一，或给定一个合力能画出多少个平行四边形】","c":"想到【给定两个分力，用平行四边形定则合力唯一；但给定一个合力，可作无数个平行四边形，分解方案有无数种，因此实际解题必须按作用效果或正交分解确定分力方向】；警惕【不能因分解有无数种就随意分解，解题时分力方向必须由作用效果或坐标轴唯一确定】","src":"跳跳物一轮02.5 力的分解_笔记","note":"视频|00:19","orig":"（知识）力的分解是用几个分力等效替代一个合力，是力的合成的逆运算。","link":""},{"id":"phy2109","t":"力的分解·按作用效果分解的适用情景","s":"看到【两绳吊重物、斜面上物体、绳靠墙小球等作用效果明显的情景，要求分解重力】","c":"想到【两绳吊物：重力沿两绳方向分解，分力与绳对物体的拉力等大反向；斜面物体：沿斜面向下和垂直压紧斜面分解；绳靠墙小球：沿绳和垂直墙壁方向分解】；警惕【力的作用效果不明显或超过两个时此法失效，应改用正交分解】","src":"跳跳物一轮02.5 力的分解_笔记","note":"视频|01:39","orig":"（知识）按力的作用效果分解：先分析力产生哪两个效果，再沿效果方向作平行四边形。","link":""},{"id":"phy2110","t":"力的分解·正交分解建系原则与一夹就咳嗽","s":"看到【需把力沿两个互相垂直方向分解，力与坐标轴夹角为$\\theta$求各轴分力】","c":"想到【建系原则是让尽量多的力落在坐标轴上：非斜面问题沿水平、竖直建系，斜面问题沿斜面和垂直斜面建系；力$F$与某轴夹角为$\\theta$，则该轴分力为$F\\cos\\theta$，另一轴分力为$F\\sin\\theta$（一夹就咳嗽：夹指夹角，咳嗽谐音cos）】；警惕【cos配的是与力夹角的那个轴，sin配另一轴，两轴分力写反是常见错误】","src":"跳跳物一轮02.5 力的分解_笔记","note":"视频|04:30","orig":"（知识）正交分解：先建坐标系，再分解不在坐标轴上的力，口诀「一夹就咳嗽」。","link":""},{"id":"phy2111","t":"力的分解·分力可能性的解数判定","s":"看到【已知合力、一个分力的大小和另一分力的方向，问有几组解或另一分力的取值范围】","c":"想到【几何作图：以合力末端为圆心、已知分力$F_1$为半径画圆，与另一分力$F_2$方向线的交点数即解数；$F_2$方向线到圆心的最小距离为$F\\sin\\theta$，故$F_1<F\\sin\\theta$无解，$F_1=F\\sin\\theta$或$F_1\\geq F$唯一解，$F\\sin\\theta<F_1<F$两解；$F_2$的最小值$=F\\sin\\theta$，当$F_2\\perp F_1$时取得】；警惕【漏掉$F_1\\geq F$仍有唯一解的情形；最小距离是$F\\sin\\theta$而不是$F\\cos\\theta$】","src":"跳跳物一轮02.5 力的分解_笔记","note":"视频|08:35-11:08","orig":"（知识）已知合力$F$、一个分力$F_1$的大小、另一个分力$F_2$的方向（与合力成$\\theta$角），判断分解方案有几种。","link":""},{"id":"phy2112","t":"力的分解·投影法求某方向的分力","s":"看到【给定一个力和一个目标方向，直接求该方向分力的大小】","c":"想到【过力的箭头末端向目标方向作垂线，垂足与力起点的线段即该方向分力；直角三角形中原力是斜边、分力是夹角的邻边，如力与水平方向成$30°$，则水平分力为$F\\cos 30°=\\frac{\\sqrt{3}}{2}F$】；警惕【把分力误当对边用了$\\sin$；夹角必须取与目标方向的夹角，不是与其他方向的夹角】","src":"跳跳物一轮02.5 力的分解_笔记","note":"视频|13:10","orig":"（知识）求力$F$在某一方向上的分力，只需在该方向上作投影。","link":""},{"id":"phy2113","t":"力的分解·极限法比较两绳拉力","s":"看到【两绳吊同一重物，问哪根先断或哪个拉力大，常规作图难以比较】","c":"想到【拉力大的先断；把重力沿两绳方向分解，用极限法：令一根绳极长、另一根极短，力的平行四边形被拉得狭长，沿短绳方向的分力明显更大，故短绳BO先断】；警惕【凭直觉认为长绳受力大；实际拉力大小由重力沿绳方向的分解决定，与绳长本身无关】","src":"跳跳物一轮02.5 力的分解_笔记","note":"视频|14:16","orig":"（例）两根承受最大拉力相等的绳子AO、BO悬挂铁球并不断注入铁砂，已知AO>BO，判断哪根绳先断。","link":""},{"id":"phy2114","t":"力的分解·劈柴分力与顶角的关系","s":"看到【斧头劈木、楔子挤开物体，问施力大小或顶角宽窄与劈开效果的关系】","c":"想到【按作用效果把$F$分解为垂直斧子两侧面的两个分力；$F$越大平行四边形越大、分力越大，顶角$\\theta$越小时两分力越接近水平且越大，越容易劈开】；警惕【误认为斧子钝（$\\theta$大）更省力，实际顶角越小分力越大、越锋利越易劈开】","src":"跳跳物一轮02.5 力的分解_笔记","note":"视频|16:35","orig":"（例）斧子劈木桩：对斧子竖直施加力$F$，斧子顶角为$\\theta$，分析$F$和$\\theta$对劈开难易程度的影响。","link":""},{"id":"phy2115","t":"力的分解·曲辕犁正交分解与相互作用力","s":"看到【两个类似情景拉力等大但与竖直方向夹角不同，比较水平、竖直分力大小】","c":"想到【与竖直方向夹角为$\\theta$时，水平分力$=F\\sin\\theta$、竖直分力$=F\\cos\\theta$；$\\alpha<\\beta$时$\\sin\\alpha<\\sin\\beta$、$\\cos\\alpha>\\cos\\beta$，故曲辕犁水平分力小、竖直分力大；耕索与犁之间的拉力是相互作用力，无论匀速还是加速始终等大反向】；警惕【夹角是相对竖直方向时水平分力要用$\\sin$而非$\\cos$；误以为加速运动时相互作用力大小不再相等】","src":"跳跳物一轮02.5 力的分解_笔记","note":"视频|18:12","orig":"（例）曲辕犁与直辕犁所受拉力$F$大小相等，与竖直方向夹角分别为$\\alpha$、$\\beta$且$\\alpha<\\beta$，比较两犁水平分力和竖直分力。","link":""},{"id":"phy2116","t":"受力分析·画受力图的规范与易漏点","s":"看到【要求画受力示意图或数物体受力个数，判断哪些力该画】","c":"想到【只画性质力（重力、电磁场力、人为外力、弹力、摩擦力），不画效果力（如下滑力）；按重力→人为外力→弹力→摩擦力的顺序分析防漏力；各力作用点画在重心上形成共点力，便于求合力或正交分解】；警惕【最易漏重力，先无脑画上重力；唯一特例是杆受到的弹力，画在的实际作用点上而非重心】","src":"跳跳物一轮02.6 受力分析_笔记","note":"视频|00:40","orig":"（知识）受力分析的规范：只画性质力不画效果力，力的作用点画在物体重心上。","link":""},{"id":"phy2117","t":"受力分析·整体法的原理与相对静止条件","s":"看到【多个物体（叠放、并排、连接）需要受力分析，求系统受到的外力】","c":"想到【整体内部相互作用力（如A对C的支持力与C对A的压力）等大反向可抵消，只分析整体之外的物体对整体的力；使用条件是各物体保持相对静止——每个物体都可以运动，但彼此间无相对运动】；警惕【相对静止$\\neq$静止，一起加速运动的物体也能用整体法；合力与合外力没有区别，只是叫法不同】","src":"跳跳物一轮02.6 受力分析_笔记","note":"视频|02:18","orig":"（知识）整体法：把多个物体看成一个整体，内力成对抵消，只分析外力。","link":""},{"id":"phy2118","t":"受力分析·整体法选择研究对象的两个原则","s":"看到【题目要求分析某两个物体之间的相互作用力，考虑整体范围怎么选】","c":"想到【原则一：待分析的力不能是内力，如求A、B间摩擦力就不能把A、B、C看成整体，否则该摩擦力被藏进内部无法分析；原则二：满足原则一时包含物体越多，需要分析的力越少越简单】；警惕【不存在所谓「隔离法」，要么用整体法，要么单独分析某一个物体，两者择一】","src":"跳跳物一轮02.6 受力分析_笔记","note":"视频|06:23","orig":"（知识）选整体的范围：要分析的力不能被包进整体内部；在满足此前提下尽量多包含物体。","link":""},{"id":"phy2119","t":"受力分析·球面接触的弹力方向","s":"看到【物体与球面（曲面、圆弧面）接触，要求画弹力方向或判断受力图正误】","c":"想到【弹力垂直于过接触点的切面；由球的几何性质，过接触点垂直切面的方向必过球心，故球面弹力沿半径方向（指向或背离球心）】；警惕【误把弹力画成垂直于杆身或其他想当然的方向；有接触不一定有弹力，可用假设法（拿走对方看物体是否仍平衡）检验】","src":"跳跳物一轮02.6 受力分析_笔记","note":"视频|07:43","orig":"（知识）球面对杆或其他物体的弹力方向：过接触点作球面的切面，弹力垂直于切面。","link":""},{"id":"phy2120","t":"受力分析·假设法判断弹力与摩擦力","s":"看到【物体贴附在板（墙）上静止，已知力不足以平衡，判断弹力或摩擦力是否存在】","c":"想到【假设法：假设没有弹力则也没有摩擦力，只剩重力与磁力且两力不在同一直线上无法平衡，故板擦必受弹力和摩擦力；物体静止合力为零，板面对板擦全部作用力的合力与重力等大反向、竖直向上】；警惕【凭感觉认为摩擦力可有可无；静止$\\neq$不受摩擦力，应由平衡条件反推未知力】","src":"跳跳物一轮02.6 受力分析_笔记","note":"视频|09:44","orig":"（例）板擦被磁力吸附在白板上静止，已知受重力（竖直向下）和磁力（垂直板面），判断弹力、摩擦力有无及板面对板擦总作用力的方向。","link":""},{"id":"phy2121","t":"受力分析·整体法补判墙对物体的摩擦力","s":"看到【叠放物体被水平压力压在墙上静止，问各自受力个数或墙对物体的摩擦力】","c":"想到【先隔离受力清晰的P：重力、外力$F$、N对P的弹力、N对P的摩擦力共4个；N单独分析时墙对N的摩擦力难判断，改用整体法：P与N整体竖直方向只受重力，故墙必须给N竖直向上的摩擦力才能平衡，N共5个力】；警惕【漏掉墙对N的摩擦力；整体法分析时不要再把P与N之间的内力计入】","src":"跳跳物一轮02.6 受力分析_笔记","note":"视频|12:34","orig":"（例）P、N两物体叠放并紧靠竖直墙壁，用水平外力$F$把它们压在墙上保持静止，判断P和N各自的受力个数。","link":""},{"id":"phy2122","t":"受力分析·转换研究对象结合牛顿第三定律","s":"看到【叠放物体中甲对乙的作用力难以直接分析，或问下层物体的受力个数】","c":"想到【转换研究对象：先分析受力较易的A，由平衡得B对A提供竖直向上的弹力和水平向右的摩擦力，再由牛顿第三定律反推A对B的力等大反向；B的受力=重力+斜面对B（支持力必有、摩擦力不确定）+A对B的弹力与摩擦力，故为4个或5个】；警惕【漏掉斜面摩擦力可有可无的不确定情形，把受力个数答死】","src":"跳跳物一轮02.6 受力分析_笔记","note":"视频|16:15","orig":"（例）A、B叠放（A在上）置于斜面上，A在重力和外力$F$作用下平衡，问B受几个力。","link":""},{"id":"phy2123","t":"受力分析·竖直夹书的对称整体与逐本递推","s":"看到【一摞书或多个物块被竖直夹在两侧木板间，求板与物、物与物间的摩擦力或动摩擦因数】","c":"想到【两侧对称：把整摞书当整体，总重力由两板静摩擦力均分（各$15\\mathrm{N}$）；再从外侧向内逐本隔离递推出相邻书间摩擦力需求（最大$10\\mathrm{N}$），用$\\mu F_N\\geq 10\\mathrm{N}$得书间动摩擦因数$\\geq 0.25$；抽出一本书需克服重力加两侧向下的滑动摩擦力，$F\\geq G+2\\mu F_N=25\\mathrm{N}$】；警惕【任意相邻书间弹力均等于板压书的压力；不要认为相邻书间处处有摩擦，对称中心附近书间摩擦力可为零】","src":"跳跳物一轮02.6 受力分析_笔记","note":"视频|19:58","orig":"（例）6本相同的书被竖直夹在两块木板之间，每本质量0.5kg，板对书的压力为40N，g取$10\\mathrm{m/s^2}$，求板对书的静摩擦力、书与书间动摩擦因数的最小值、竖直抽出左侧第二本书所需的最小拉力。","link":""},{"id":"phy2124","t":"共点力平衡·正交分解法三步与建系原则","s":"看到【物体平衡且受力较复杂（含多角度的力），需要列方程求解未知力】","c":"想到【三步走：受力分析→按建系原则正交分解→列$x$、$y$方向合力均为零的平衡方程联立求解；建系原则是让尽可能多的力落在坐标轴上：非斜面问题沿水平、竖直建系，斜面问题沿斜面和垂直斜面建系】；警惕【建系不当导致多数力都要分解，计算量翻倍；平衡时$x$、$y$两个方向的方程缺一不可】","src":"跳跳物一轮02.7 共点力平衡问题_笔记","note":"视频|00:36","orig":"（知识）正交分解法解共点力平衡问题：最通用的方法，适用于所有共点力平衡。","link":""},{"id":"phy2125","t":"共点力平衡·斜面正交分解的必背结论","s":"看到【斜面上的物体做受力分析或平衡计算，要写出重力分力、支持力或摩擦力】","c":"想到【重力沿斜面向下的分力为$G\\sin\\alpha$，垂直斜面向下的分力为$G\\cos\\alpha$；只受重力和支持力时$N=G\\cos\\alpha$；粗糙斜面上物体滑动时$f=\\mu N=\\mu G\\cos\\alpha$，这几条要熟练到不加思索直接写出】；警惕【$N=G\\cos\\alpha$仅在没有其他垂直斜面方向的力时成立，一旦另有外力在垂直斜面方向有分力，必须重列该方向平衡方程求$N$】","src":"跳跳物一轮02.7 共点力平衡问题_笔记","note":"视频|01:46","orig":"（知识）斜面倾角为$\\alpha$时，重力分力、支持力、滑动摩擦力的正交分解结论。","link":""},{"id":"phy2126","t":"共点力平衡·三角形法的适用条件与步骤","s":"看到【三力平衡且其中两个力互相垂直，求某个未知力的大小】","c":"想到【三角形法定则推论：两力首尾相连，第三力与其合力等大反向，三力恰好封闭；步骤：受力分析→平移两个力与第三个力首尾相连画出直角三角形→用三角函数或边长比例求解，如$\\cos\\theta=G/F_1$、$\\tan\\theta=F_2/G$；要求两力垂直是为了得到直角三角形，方便用三角函数】；警惕【三角形法仅适用于三力平衡，四力及以上无法构成三角形，须退回正交分解】","src":"跳跳物一轮02.7 共点力平衡问题_笔记","note":"视频|03:39","orig":"（知识）三个力平衡时，这三个力经平移后必可构成首尾相连的封闭三角形。","link":""},{"id":"phy2127","t":"共点力平衡·30°与37°特殊直角三角形份数法","s":"看到【三力平衡的直角三角形中出现30°或37°角，求各力大小】","c":"想到【30°直角三角形：30°角对边:另一直角边:斜边$=1:\\sqrt{3}:2$；37°直角三角形：37°角对边:另一直角边:斜边$=3:4:5$；份数法：先看已知力占几份，一份=已知力/份数，所求力占几份就乘几，如重力$G$为37°三角形斜边（5份），则37°角对边$=3G/5=0.6G$、邻边$=4G/5=0.8G$】；警惕【记错对应关系（37°的对边是3份不是4份）；考试九成直角三角形是这两种，用份数法比三角函数更快】","src":"跳跳物一轮02.7 共点力平衡问题_笔记","note":"视频|07:25","orig":"（知识）必会两种特殊直角三角形：30°三角形三边比$1:\\sqrt{3}:2$，37°三角形三边比$3:4:5$。","link":""},{"id":"phy2128","t":"共点力平衡·活绳与死绳模型","s":"看到【绳子跨过滑轮或系于同一绳结，判断各段绳的拉力是否相等】","c":"想到【活绳：受力点能自由移动（绳可绕滑轮滑动），本质是一根完整的绳，各处弹力大小相等，滑轮两侧绳对滑轮的弹力等大；死绳：受力点被固定（绳结），各段绳独立，弹力大小一般不相等，需分别由平衡条件求解】；警惕【见多段绳就默认拉力相等；只有同一根绳（跨过滑轮）才等大，系在同一结上的不同绳各自独立】","src":"跳跳物一轮02.7 共点力平衡问题_笔记","note":"视频|09:03","orig":"（知识）两类绳模型：活绳（如滑轮）绳上各处弹力大小处处相等；死绳（如绳结）各段弹力未必相等。","link":""},{"id":"phy2129","t":"共点力平衡·活杆与死杆模型","s":"看到【杆连接或支撑物体的结构，要求判断杆对物体的作用力方向】","c":"想到【活杆：一端可绕固定点自由转动（如铰链），弹力方向唯一确定、沿杆的轴线；死杆：一端固定不能转动，弹力方向不固定，须结合物体平衡状态判断，如固定杆顶住小球静止，杆的弹力竖直向上与重力平衡，而非沿杆方向】；警惕【一律把杆的弹力画成沿杆；只有可转动的活杆才保证沿杆】","src":"跳跳物一轮02.7 共点力平衡问题_笔记","note":"视频|10:40","orig":"（知识）两类杆模型：活杆（铰链连接、可转动）弹力方向一定沿杆；死杆（一端固定）弹力方向未必沿杆。","link":""},{"id":"phy2130","t":"共点力平衡·斜面上加水平外力时的支持力与摩擦力","s":"看到【斜面上的物体还受水平（或其他方向）外力作用而平衡，求支持力$N$或摩擦力$f$】","c":"想到【沿斜面、垂直斜面建系正交分解：x轴方程$F\\cos\\theta=G\\sin\\theta+f$，y轴方程$N=G\\cos\\theta+F\\sin\\theta$，故$f=F\\cos\\theta-G\\sin\\theta=\\mu N=\\mu(G\\cos\\theta+F\\sin\\theta)$，两种表达式必须同时成立】；警惕【垂直斜面方向有外力分力时$N\\neq G\\cos\\theta$，再写$f=\\mu G\\cos\\alpha$就错；漏掉外力在垂直斜面方向的分力是本题最大陷阱】","src":"跳跳物一轮02.7 共点力平衡问题_笔记","note":"视频|11:43","orig":"（例）物体在水平恒力$F$作用下沿粗糙斜面匀速向上运动，斜面倾角$\\theta$，求滑动摩擦力$f$（可分别用平衡方程和$f=\\mu N$表达）。","link":""},{"id":"phy2131","t":"共点力平衡·活绳死杆与死绳活杆组合模型","s":"看到【绳与杆组合悬挂重物，判断杆的作用力方向大小或各段绳拉力的关系】","c":"想到【先辨模型：活绳跨滑轮同一根绳各处拉力相等，两等大拉力夹角$120°$时合力大小等于分力，死杆弹力与该合力等大反向；死绳+活杆时活杆弹力沿杆，绳结两力垂直则画30°直角三角形用份数法：三边比$1:\\sqrt{3}:2$，重力对边1份、杆弹力$\\sqrt{3}$份、斜绳拉力斜边2份】；警惕【死杆弹力误画成沿杆、活杆弹力不沿杆画；滑轮两侧绳等大是因为同一根绳，任意两段绳并不同】","src":"跳跳物一轮02.7 共点力平衡问题_笔记","note":"视频|19:42","orig":"（例）图甲：跨过滑轮的绳两端各挂质量$m_1$的物体，两段绳夹角$120°$，滑轮由一杆固定；图乙：绳结下挂质量$m_2$的物体，另有水平活杆的弹力和与水平成$30°$的斜绳拉力系于该结。求两图中杆的作用力。","link":""},{"id":"phy2132","t":"动态平衡·缓慢移动的近似平衡","s":"看到【物体“缓慢”移动（速度极小、趋近于零），要求受力分析或判断某个力的大小】","c":"想到【缓慢移动属于近似平衡：无论物体做直线还是曲线运动、匀速还是变速，都忽略运动状态，近似看成静止，一律按合力为零列平衡方程，与严格平衡（静止/匀速直线运动）在解题上没有任何区别】；警惕【缓慢移动（尤其沿曲线）时真实合力未必为零，“合力为零”只是解题近似；做题时不能因真实合力不为零而放弃平衡方程】","src":"跳跳物一轮02.8 动态平衡问题_五大常考模型一网打尽_笔记","note":"视频|00:20","orig":"（知识）平衡的拓展：严格平衡与近似平衡（缓慢移动）的区分与统一处理原则。","link":""},{"id":"phy2133","t":"动态平衡·题型判定四大特征","s":"看到【物体受三个力，某个力的方向不断变化，只定性问某力变大还是变小】","c":"想到【四大特征缺一不可：①力在旋转（有的力方向在变）②物体处于平衡状态（严格或近似均可）③恰好受三个力且其中一个为恒力（通常是重力，恒力保证前后力三角形对应边重合、便于比较）④只定性分析、不定量计算。满足即用三角形法：平移力构造首尾相连的三角形，看边长变化定力的大小变化】；警惕【所有力都只有大小变化、方向不变，则不属于动态平衡；受力多于或少于三个力都无法画力三角形，不能套动态平衡口诀】","src":"跳跳物一轮02.8 动态平衡问题_五大常考模型一网打尽_笔记","note":"视频|02:00","orig":"（知识）动态平衡问题的判定：一题是否属于动态平衡，需同时满足四个特征。","link":""},{"id":"phy2134","t":"动态平衡·晾衣杆模型（活绳）","s":"看到【挂钩挂在同一根活绳上（两段张力相等），绳一端上下或左右移动，问绳中张力变化】","c":"想到【活绳两段弹力相等，平移后与重力构成等腰三角形。口诀：上下移动绳一端，绳上弹力大小不变（方向也不变）；左右移动遵循“近小远大”——端点移近弹力变小，端点移远弹力变大（端点越远绳越接近水平，力三角形对应边越长）】；警惕【上下与左右移动结论不同，左右移动只看水平距离变化；若挂钩处是死结、两段绳不连续，两段张力可以不等，等腰三角形前提失效】","src":"跳跳物一轮02.8 动态平衡问题_五大常考模型一网打尽_笔记","note":"视频|04:42","orig":"（知识）晾衣杆模型：挂钩可在绳上自由滑动的活绳结构，绳一端移动时判断绳中弹力变化。","link":""},{"id":"phy2135","t":"动态平衡·横不转模型","s":"看到【三力平衡中一个力始终沿水平方向不变，另一个力在旋转，问各力大小变化】","c":"想到【口诀“竖小平大”：旋转的力越转越接近竖直方向时，除重力外另外两个力都变小；旋转的力越转越接近水平方向时，除重力外另外两个力都变大。分析关键就是观察旋转的力相对竖直、水平的接近程度】；警惕【结论对“除重力外的另外两个力”同时成立，水平方向那个不变的力也会跟着变，不要误以为它恒定】","src":"跳跳物一轮02.8 动态平衡问题_五大常考模型一网打尽_笔记","note":"视频|09:02","orig":"（知识）横不转模型：三力动态平衡中有一个力方向始终水平（如竖直墙的弹力）。","link":""},{"id":"phy2136","t":"动态平衡·斜不转模型","s":"看到【三力平衡中一个力方向倾斜且固定不变，另一力在旋转，问两个力的大小变化】","c":"想到【转动力遵循“垂直最小”：当旋转的力与不转的力方向垂直时，转动力取最小值，全过程先减小后增大（或先增大后减小）。不转的力没有固定口诀，画出两个时刻的力三角形比较对应边长定趋势】；警惕【最小值条件是与“不转的力”垂直，不是与重力或竖直方向垂直；不转力的变化趋势必须画图比较，不能凭口诀硬套】","src":"跳跳物一轮02.8 动态平衡问题_五大常考模型一网打尽_笔记","note":"视频|11:51","orig":"（知识）斜不转模型：三力动态平衡中有一个力始终倾斜且方向不变（如固定斜面的支持力），另一个力旋转。","link":""},{"id":"phy2137","t":"动态平衡·定角转模型","s":"看到【三力平衡中两个力同时旋转且两者夹角保持不变，问两个力的大小变化】","c":"想到【口诀“你越水平我越大”：分析某个力时看另一个力的旋转情况——另一个力越接近水平，该力越大；另一个力越远离水平，该力越小。两个力互相由对方与水平方向的接近程度判断】；警惕【每个力都由“对方”的方向判断，不能只盯自己；两力夹角固定是前提，夹角不固定时口诀失效，应改用相似三角形法】","src":"跳跳物一轮02.8 动态平衡问题_五大常考模型一网打尽_笔记","note":"视频|15:00","orig":"（知识）定角转模型：两个力都在旋转，但两力夹角始终保持固定（如框内两根绳吊住小球）。","link":""},{"id":"phy2138","t":"动态平衡·不定角转模型（相似三角形法）","s":"看到【三力平衡中两个旋转力的夹角不固定（如杆转动吊重物、几何边长变化），问力的大小变化】","c":"想到【相似三角形法五步：①以节点为对象受力分析（重力、两个旋转力）②平移两旋转力与重力构成首尾相连的力三角形③在几何图中找与力三角形三边两两平行的相似三角形④列对应边成比例式（如 $\\frac{AO}{G}=\\frac{OC}{T_c}=\\frac{AC}{T_a}$）⑤由已知边长变化判断未知力的变化】；警惕【只有力三角形三边与几何三角形三边两两平行才能列比例；对应关系勿弄错——绳的拉力对应绳长、杆的弹力对应杆长】","src":"跳跳物一轮02.8 动态平衡问题_五大常考模型一网打尽_笔记","note":"视频|18:40","orig":"（知识）不定角转模型：两个力都在旋转且夹角不固定，首选构造相似三角形分析。","link":""},{"id":"phy2139","t":"动态平衡·横不转模型与整体法综合（人夹球）","s":"看到【人夹球贴墙，人身体斜面逐渐转到竖直，问墙弹力、地面摩擦力与支持力变化】","c":"想到【先隔离球：球受重力、墙的水平弹力 $N$、人背部斜向上的弹力 $T$；人站直时 $T$ 越转越接近水平，由“竖小平大”知 $T$、$N$ 都变大。再整体（人+球）：水平方向地面摩擦力 $f=N$ 随 $N$ 变大，竖直方向支持力恒等于总重力保持不变】；警惕【球对人的压力与 $T$ 等大、同步变大；地面对人的支持力看整体竖直方向恒定，勿因 $N$ 变大而误判支持力变大】","src":"跳跳物一轮02.8 动态平衡问题_五大常考模型一网打尽_笔记","note":"视频|24:49","orig":"（例）人用背部（可视为斜面）把球压在竖直墙上保持静止，人逐渐站直（背部越来越竖直），判断墙对球的弹力、地面对人的摩擦力、地面对人的支持力、球对人的压力如何变化。","link":""},{"id":"phy2140","t":"牛顿三定律·牛顿第一定律（理想实验与惯性维持）","s":"看到【问牛顿第一定律能否用实验验证，或匀速运动的物体是否需要力来维持】","c":"想到【①牛一是高中唯一无法用实验直接验证的定律——现实中无法创造“完全不受力”的环境，伽利略用的是理想实验法（实验+逻辑推理）；②物体做匀速直线运动靠惯性维持，不需要任何方向的力；如物块一起匀速运动时，物块之间没有摩擦力（加速阶段才需要摩擦力）】；警惕【不要认为物体朝某方向运动就一定受该方向的力；匀速运动时物体所受合力为零】","src":"跳跳物一轮03.1 牛顿三定律_终于开始复习牛二律啦_笔记","note":"视频|00:20","orig":"（知识）牛顿第一定律的两大关键点：无法实验验证、匀速运动不需要力维持。","link":""},{"id":"phy2141","t":"牛顿三定律·惯性大小的唯一决定因素","s":"看到【问“速度越大惯性是否越大”，或比较不同物体、不同速度下惯性的大小】","c":"想到【惯性是物体的固有属性，只与质量有关：质量越大惯性越大；与速度大小、受力情况均无关。维持运动靠惯性，改变运动（产生加速度）才靠力】；警惕【“速度越快越难停下来”不等于惯性大——速度大时从运动到停所需时间长，但让速度每改变 $1\\ \\mathrm{m/s}$ 的难易程度相同，惯性不变】","src":"跳跳物一轮03.1 牛顿三定律_终于开始复习牛二律啦_笔记","note":"视频|03:06","orig":"（知识）惯性：物体保持当前速度的性质，其大小只由质量决定。","link":""},{"id":"phy2142","t":"牛顿三定律·牛顿第二定律三大关键点","s":"看到【用牛顿第二定律计算加速度或合力，涉及方向、正负号或力的取舍】","c":"想到【①加速度的决定式：a=合力/质量，即加速度由合力与质量共同决定；②计算不带负号——$F=ma$（$F$ 指合力）代入计算一律取大小，方向问题单独分析；③物体做直线运动时求合力只分析运动方向上的力，垂直方向合力必为零（如重力与支持力等大反向），无需考虑】；警惕【代入负号算大小会算错；直线运动时仍把竖直方向各力计入合力，会画蛇添足算错】","src":"跳跳物一轮03.1 牛顿三定律_终于开始复习牛二律啦_笔记","note":"视频|05:26","orig":"（知识）应用牛顿第二定律时的三大关键点。","link":""},{"id":"phy2143","t":"牛顿三定律·牛顿第三定律与答题规范","s":"看到【题目要求的力不是研究对象所受的力，如求小车对凹形路面的压力】","c":"想到【作用力与反作用力总是大小相等、方向相反、作用在同一直线上。答题规范：先求出研究对象受到的力（如路面对小车的支持力），再补一句“由牛顿第三定律可知，小车对路面的压力与路面对小车的支持力大小相等”，不写说明会被扣分】；警惕【没看清题目问的是“谁对谁”的力就直接作答；反作用力与原力等大，但作用对象不同】","src":"跳跳物一轮03.1 牛顿三定律_终于开始复习牛二律啦_笔记","note":"视频|07:44","orig":"（知识）牛顿第三定律内容及“求谁对谁的力”的答题规范。","link":""},{"id":"phy2144","t":"牛顿三定律·相互作用力与平衡力的辨析","s":"看到【两个等大、反向的力，问它们是平衡力还是相互作用力】","c":"想到【相同点：都等大、反向。三看不同点：①作用对象——平衡力作用在同一物体上，相互作用力作用在两个物体上；②合力——平衡力可求合力且为零，相互作用力作用在两个物体上不能求合力；③力的性质——平衡力不一定是同种力（如重力与支持力），相互作用力一定是同种力（同为弹力或摩擦力）】；警惕【等大反向不等于平衡力，先看是否作用在同一物体上；平衡力性质可不同，相互作用力必同种性质】","src":"跳跳物一轮03.1 牛顿三定律_终于开始复习牛二律啦_笔记","note":"视频|07:44","orig":"（知识）一对相互作用力与一对平衡力的异同对比。","link":""},{"id":"phy2145","t":"牛顿三定律·力学单位制","s":"看到【问某单位（牛、米每秒、千克等）是基本单位还是导出单位，或单位换算】","c":"想到【力学基本单位只有三个：$\\mathrm{m}$（米）、$\\mathrm{kg}$（千克）、$\\mathrm{s}$（秒），对应基本物理量长度、质量、时间——力不是基本物理量。由 $F=ma$ 推得 $1\\ \\mathrm{N}=1\\ \\mathrm{kg\\cdot m/s^2}$（注意带平方）；牛、米每秒等其余单位均为导出单位】；警惕【国际单位制共 7 个基本单位（另含安培、开尔文、摩尔、坎德拉）；写 $1\\ \\mathrm{N}=1\\ \\mathrm{kg\\cdot m/s}$ 时常漏掉秒的平方】","src":"跳跳物一轮03.1 牛顿三定律_终于开始复习牛二律啦_笔记","note":"视频|10:31","orig":"（知识）国际单位制中的力学基本单位与“牛”的推导。","link":""},{"id":"phy2146","t":"牛顿三定律·速度、加速度、合外力的决定关系","s":"看到【比较速度、加速度、合外力之间的大小关系，或问速度为零时加速度是否为零】","c":"想到【加速度只由合外力和质量决定，与速度大小无关：速度大加速度不一定大（匀速时 $a=0$）；速度为零加速度可以很大（火箭点火瞬间 $v=0$、$a$ 很大、合外力很大）；加速度为零则合外力必为零；加速度大则合外力一定大】；警惕【把速度与加速度捆绑判断；速度为零不代表不受力，加速度为零不代表速度为零】","src":"跳跳物一轮03.1 牛顿三定律_终于开始复习牛二律啦_笔记","note":"视频|13:14","orig":"（例）判断“速度大则加速度大”“速度为零则加速度为零”“加速度大则合外力大”等说法（如火箭点火离地瞬间）。","link":""},{"id":"phy2147","t":"牛顿三定律·砚台与墨条的摩擦力与平衡力辨析（2024 辽宁高考）","s":"看到【物体 A 在 B 上滑动、B 静止在桌面上，问各接触面摩擦力方向及力的配对关系】","c":"想到【滑动摩擦力方向与相对运动方向相反：墨条向左运动，砚台对墨条的摩擦力向右；由牛三，墨条对砚台的摩擦力向左，砚台静止，故桌面对砚台的摩擦力向右与之平衡；竖直方向桌面对砚台的支持力=砚台重力+墨条对砚台的压力，大于墨条的压力】；警惕【桌面和墨条对砚台的摩擦力都作用在砚台上、等大反向，是平衡力而非相互作用力；支持力与墨条压力大小不等，不是平衡力】","src":"跳跳物一轮03.1 牛顿三定律_终于开始复习牛二律啦_笔记","note":"视频|20:30","orig":"（例）砚台静止在水平桌面上，墨条在砚台面上向左研磨（滑动），问砚台对墨条的摩擦力方向、桌面对砚台的摩擦力方向，并判断桌面对砚台的支持力与墨条对砚台的压力是否为平衡力。","link":""},{"id":"phy2148","t":"动力学两类问题·两类问题的定义与分析逻辑","s":"看到【已知受力情况求速度/位移/时间，或已知运动情况求某个力】","c":"想到【牛顿第二定律 $F=ma$ 是连接力学与运动学的桥梁。第一类（已知力求运动）：受力分析→正交分解求合力→用 $F=ma$ 求加速度→用运动学公式求速度、位移、时间。第二类（已知运动求力）：先用运动学公式求加速度→用 $F=ma$ 求合力→结合受力分析求出题目要求的某个力】；警惕【两类问题顺序相反：第一类从受力入手，第二类从运动（加速度）入手，入口选错全盘卡住】","src":"跳跳物一轮03.2 动力学两类问题、多过程问题_笔记","note":"视频|00:50-02:37","orig":"（知识）动力学两类问题：已知力求运动、已知运动求力，及各自的分析逻辑顺序。","link":""},{"id":"phy2149","t":"动力学多过程问题·段间桥梁（速度不能突变）","s":"看到【物体运动分多段（如先沿斜面后水平面、先弹射后滑跑），各段加速度不同】","c":"想到【单过程与多过程的区分依据是加速度是否恒定（单过程全程加速度不变）。多过程解题核心是抓住段间联系：速度不能突变，上一段的末速度就是下一段的初速度；要求某段的初速度，可先在它的前一段用运动学公式求出末速度再衔接】；警惕【漏用“末速度=初速度”的衔接关系，给某段凭空设初速度；各段加速度不同，不能全程套同一个运动学公式】","src":"跳跳物一轮03.2 动力学两类问题、多过程问题_笔记","note":"视频|04:20","orig":"（知识）多过程问题的区分依据与段间联系。","link":""},{"id":"phy2150","t":"动力学两类问题·无人机匀减速悬停求推力","s":"看到【已知初末速度和位移（不含时间）求某力，且该力方向斜向、不沿合力方向】","c":"想到【第二类问题（已知运动求力）：①已知量不含时间，选速度位移公式 $v^2=2ax$ 求加速度（位移取两高度之差 8 m）；②由 $F=ma$ 求合力（方向与运动相反）；③设推力为 $T$，$T$ 与重力、合力构成直角三角形且 $T$ 为斜边，用勾股定理 $T=\\sqrt{(mg)^2+F^2}$（$F$ 为合力）】；警惕【位移误用 10.5 m 或 2.5 m，应取两高度之差；只研究匀减速段，匀速段合力为零不要混入】","src":"跳跳物一轮03.2 动力学两类问题、多过程问题_笔记","note":"视频|05:29","orig":"（例）质量 44 kg 的无人机以 8 m/s 匀速竖直下降，在离地 10.5 m 处开始匀减速，降到离地 2.5 m 处速度恰好减为零（悬停）。求减速阶段无人机所受推力的大小。","link":""},{"id":"phy2151","t":"动力学多过程问题·飞机弹射起飞两段求推力与牵引力","s":"看到【多段加速过程（先弹射后推力）已知各段速度位移，段内含两个未知力】","c":"想到【多过程从信息最简单的一段入手：先分析无弹射的第二段，用 $v_2^2-v_1^2=2ax$ 求加速度、$F=ma$ 求合力，由 合力=推力-阻力 解出喷气推力；再回头分析第一段（多一个牵引力），由 合力=牵引力+推力-阻力 解出牵引力。两段由共同速度衔接】；警惕【第一段同时含牵引力与推力两个未知量，直接列式解不出，必须先用第二段把推力求出来】","src":"跳跳物一轮03.2 动力学两类问题、多过程问题_笔记","note":"视频|09:28","orig":"（例）总质量 2.0$\\times$10$^4$ kg 的飞机先由电磁弹射器牵引匀加速滑行（同时受喷气推力与阻力），后撤去弹射器、靠喷气推力继续匀加速至离舰速度，阻力恒为 mg/4。已知两段的初末速度与位移，求喷气推力与弹射牵引力。","link":""},{"id":"phy2152","t":"动力学多过程问题·斜面滑下接水平滑轨","s":"看到【物体先沿斜面加速下滑、再在水平面受摩擦减速，问各段加速度、衔接速度或水平位移】","c":"想到【已知力求运动的多过程：①斜面段沿斜面方向列 $mg\\sin\\theta-\\mu mg\\cos\\theta=ma$ 求加速度（垂直斜面方向合力为零）；②斜面末端速度由 $v^2=2aL_1$ 求（初速为零）；③水平段合力为摩擦力 $\\mu mg$、加速度与运动反向，以斜面末端速度为初速度，用 $v^2-v'^2=2aL_2$ 求最短长度】；警惕【斜面段漏掉摩擦分量 $\\mu mg\\cos\\theta$；水平段末速度是题给衔接值（2 m/s）时不要代成零】","src":"跳跳物一轮03.2 动力学两类问题、多过程问题_笔记","note":"视频|13:58","orig":"（例）货物由静止沿倾角 24° 的斜面（长 L$_1$、动摩擦因数 $\\mu$）下滑，进入水平滑轨后受滑动摩擦力匀减速，要求：斜面上的加速度、斜面末端的速度、货物在水平滑轨上减速到 2 m/s 所需的最短长度。","link":""},{"id":"phy2153","t":"动力学多过程问题·火箭三段上升（勿漏最后减速段）","s":"看到【火箭（或物体）动力阶段结束后仍继续上升，问最大速度或最大高度】","c":"想到【动力结束不等于最高点：最大速度出现在推力刚消失时，之后还有只受重力的匀减速段。逐段用 $F-mg=ma$ 求各段加速度，用 $v=v_0+at$ 逐段衔接求末速度，末段（末速度为零）上升高度用 $v^2=2gh$ 求，各段高度相加得总高度】；警惕【误把动力段结束当作最高点，漏掉最后只受重力的匀减速段，导致最大速度、最大高度都算错】","src":"跳跳物一轮03.2 动力学两类问题、多过程问题_笔记","note":"视频|17:47","orig":"（例）火箭竖直上升分三段：第一段在恒定推力作用下匀加速上升时间 T；第二段推力（或质量）变化后继续匀加速上升时间 T；第三段推力消失后只受重力匀减速上升到最高点。求火箭的最大速度和最大高度（用 g、T 表示）。","link":""},{"id":"phy2154","t":"超重与失重·判断依据是加速度方向","s":"看到【题目问超重还是失重，或给出速度方向让人判断超失重】","c":"想到【只看加速度（或合力）方向：加速度向上为超重，此时支持力或拉力大于重力；加速度向下为失重，支持力或拉力小于重力；只受重力、加速度为 $g$ 向下为完全失重；速度方向与超失重无关】；警惕【凭速度方向判断——向上减速是失重，向下减速是超重】","src":"跳跳物一轮03.3 超重与失重、瞬时性问题_笔记","note":"视频|00:24","orig":"（知识）判断物体处于超重还是失重状态的依据。","link":""},{"id":"phy2155","t":"瞬时性问题·弹簧与绳杆弹力能否突变","s":"看到【剪断绳子或撤去某个力的瞬间，求物体的加速度或弹力】","c":"想到【弹簧两端都连物体时弹力不能突变，剪断瞬间弹力与剪断前相同，先用剪断前的平衡状态求出弹簧弹力；非弹性绳、杆、接触面的弹力可以突变，把被剪断的绳直接擦掉，对剩余部分重新受力分析】；警惕【把弹簧弹力也当成瞬间消失或改变；弹簧一端不连物体时弹力反而可突变】","src":"跳跳物一轮03.3 超重与失重、瞬时性问题_笔记","note":"视频|00:24","orig":"（知识）剪断绳子（或撤去某个力）瞬间，弹簧弹力与绳、杆、接触面弹力的变化规律及解题套路。","link":""},{"id":"phy2156","t":"超重与失重·v-t图像分析超失重","s":"看到【v-t 图描述竖直下降运动，图线先上扬后下降且越来越陡，问超失重与阻力变化】","c":"想到【图线斜率即加速度：上扬段加速度沿正方向，下降段反向；正方向向下时，加速度向下为失重、向上为超重，全程先失重后超重；下降段越来越陡说明加速度增大，重力不变则空气阻力越来越大】；警惕【用速度方向判超失重；平均速度不能用 $(v_1+v_2)/2$ 直接算，必须用图线与时间轴围成的面积除以时间】","src":"跳跳物一轮03.3 超重与失重、瞬时性问题_笔记","note":"视频|07:13","orig":"（例）特种兵从空中沿竖直方向向下滑，v-t 图线全程在 t 轴上方（正方向向下），0~$T_1$ 图线上扬，$T_1$~$T_2$ 图线下降且越来越陡，判断平均速度、阻力变化、超失重过程及先后两人的距离变化。","link":""},{"id":"phy2157","t":"超重与失重·下蹲起立全过程","s":"看到【人下蹲起立过程给出加速度变化图线，判断超失重阶段、重心最低点或速度最大时刻】","c":"想到【下蹲：先向下加速（失重）再向下减速（超重），速度减为零时重心才到最低；起立：先向上加速（超重）再向上减速（失重）；加速度由正变负处速度最大；加速度向下段支持力小于重力；人不能看成质点，要跟踪重心运动】；警惕【把加速度方向切换点当成重心最低点——此时速度尚未减为零，重心还会继续下降】","src":"跳跳物一轮03.3 超重与失重、瞬时性问题_笔记","note":"视频|12:59","orig":"（例）人先下蹲再起立，给出以竖直向上为正方向的重心加速度随时间变化的图线，判断各阶段超失重、重心最低点位置、速度最大点及支持力与重力的大小关系。","link":""},{"id":"phy2158","t":"瞬时性问题·多物块系统剪断瞬间","s":"看到【多个物块由相同弹簧串联竖直悬挂，剪断顶部绳瞬间求加速度或弹簧伸长量之比】","c":"想到【先用剪断前平衡求弹簧弹力：某弹簧弹力等于其下方所悬挂的全部物块总重力（$S_2$ 为 $mg$，$S_1$ 为 $2mg$）；剪断瞬间弹簧弹力不变，最上方物块受重力加同向不变的弹簧弹力，合力 $3mg$、加速度 $3g$；相同弹簧劲度系数相同，伸长量与弹力成正比，之比为 $2:1$】；警惕【剪断瞬间误认为弹簧弹力消失使 a 只受重力；伸长量之比按弹力大小算而不是按物块个数算】","src":"跳跳物一轮03.3 超重与失重、瞬时性问题_笔记","note":"视频|17:09","orig":"（例）质量均为 $m$ 的 a、b、c 三物块竖直悬挂，a、b 之间连弹簧 $S_1$，b、c 之间连相同弹簧 $S_2$，剪断顶部吊绳瞬间，求最上方物块 a 的加速度及两弹簧伸长量之比。","link":""},{"id":"phy2159","t":"瞬时性问题·剪断后圆周运动的初始瞬间","s":"看到【剪断某绳后一球将绕绳的悬点摆动，求剪断瞬间剩余绳或弹簧的拉力、加速度之比】","c":"想到【剪断瞬间被剪绳拉力突变为零、弹簧弹力不变；摆动的球合力沿切线方向（垂直于剩余绳），由几何关系得 $L_1$ 拉力=$mg\\cos\\theta$、合力=$mg\\sin\\theta$；另一球弹簧弹力不变，重力与弹簧弹力的合力仍等于原 $L_2$ 拉力 $mg\\tan\\theta$；质量相等时加速度之比=合力之比=$\\cos\\theta:1$，拉力之比=$\\cos^2\\theta:1$】；警惕【认为剪断后合力沿绳方向或绳拉力不变——圆周运动初始瞬间合力必须垂直于绳、沿切线方向】","src":"跳跳物一轮03.3 超重与失重、瞬时性问题_笔记","note":"视频|19:39","orig":"（例）A、B 两质量相等的球，A 由轻绳 $L_1$ 斜向上悬挂，B 由与竖直方向成同样 $\\theta$ 角的弹簧斜向上拉住，A、B 之间用水平绳 $L_2$ 相连且均平衡。剪断 $L_2$ 瞬间，求 $L_1$ 拉力与弹簧弹力之比及 A、B 的加速度之比。","link":""},{"id":"phy2160","t":"连接体·共a与不共a的分类","s":"看到【几个物体通过叠放、并排、细绳、细杆或弹簧连在一起运动，或说一起运动】","c":"想到【一起运动意味着各物体运动状态完全相同、加速度相同，即共$a$连接体，优先用整体法加内力公式；各物体加速度不同为不共$a$连接体，用逐个动力学分析并结合动量守恒、能量守恒】；警惕【对含相对滑动的叠块等不共$a$情景硬套内力公式】","src":"跳跳物一轮03.4 内力公式_笔记","note":"视频|00:24-02:14","orig":"（知识）连接体的定义及共a、不共a两类连接体的判别与对应解法。","link":""},{"id":"phy2161","t":"连接体·内力公式本体","s":"看到【共a连接体已知外力求两物体间内力，或已知内力反求外力】","c":"想到【外力 $F$ 推在 $M_1$ 上时，两物体间的内力 $T=\\frac{M_2}{M_1+M_2}\\times F$，即内力=未受外力物体的质量占总质量的比例×人为外力；$F$ 只算人为施加的推力、拉力，重力、摩擦力、支持力都不算；推导用整体法和隔离法各列一次牛二联立】；警惕【计算题直接套公式不写整体加隔离的牛二过程会丢步骤分；把重力等非人为外力当成 $F$ 代入】","src":"跳跳物一轮03.4 内力公式_笔记","note":"视频|03:22","orig":"（知识）两物体组成的共a连接体，内力公式的内容与适用对象。","link":""},{"id":"phy2162","t":"连接体·内力公式适用条件","s":"看到【想用内力公式时，题给接触面粗糙程度、叠块或斜面等场景条件】","c":"想到【三条件：两物体加速度必须相同；接触面粗糙时要求各物体与接触面的动摩擦因数 $\\mu$ 相同；叠块模型仅地面光滑时可用，因为上物体不接触地面（$\\mu=0$）而下物体 $\\mu\\neq 0$，等 $\\mu$ 条件被破坏；水平面、竖直方向、斜面上的运动均可使用】；警惕【地面粗糙的叠块套内力公式——上下物体 $\\mu$ 不同，公式失效】","src":"跳跳物一轮03.4 内力公式_笔记","note":"视频|07:55","orig":"（知识）使用内力公式的前提条件与失效场景。","link":""},{"id":"phy2163","t":"连接体·斜面上共a连接体求弹力","s":"看到【斜面上两物体用弹簧相连一起匀加速，问弹力大小或倾角、质量变化对间距的影响】","c":"想到【对整体列牛二求加速度 $a=\\frac{F}{M_1+M_2}-g\\sin\\theta$；弹簧弹力为内力，$T=\\frac{M_2}{M_1+M_2}\\times F$；内力公式中不含 $\\theta$，倾角增大弹力不变、间距不变；增大 $M_2$ 则内力增大、弹簧伸长量变大、间距变大】；警惕【求加速度漏掉重力沿斜面的分力；认为倾角变化会改变两物体间的内力】","src":"跳跳物一轮03.4 内力公式_笔记","note":"视频|10:57","orig":"（例）两物块 $M_1$、$M_2$ 在光滑斜面上用弹簧相连，一起沿斜面向上做匀加速直线运动，人为外力 $F$ 作用在 $M_1$ 上，求加速度、弹簧弹力，并判断增大 $M_2$ 或增大倾角 $\\theta$ 对两物块间距的影响。","link":""},{"id":"phy2164","t":"连接体·叠块不滑动的最大外力","s":"看到【叠块在光滑地面上被推，问保持相对静止的最大外力或开始滑动的临界条件】","c":"想到【临界条件是 A、B 间静摩擦达到最大值 $\\mu M_A g$；该摩擦力是连接体的内力，由内力公式 $f=\\frac{M_A}{M_A+M_B}\\times F$ 解得 $F_{\\max}=\\mu M_A g\\left(1+\\frac{M_B}{M_A}\\right)$；内力公式可用正是因为地面光滑】；警惕【地面粗糙时叠块不能套内力公式；最大静摩擦的正压力是上面物体的重力而不是总重力】","src":"跳跳物一轮03.4 内力公式_笔记","note":"视频|14:15","orig":"（例）光滑水平面上，质量 $M_A$ 的物块 A 叠放在质量 $M_B$ 的物块 B 上，A、B 间动摩擦因数为 $\\mu$，水平外力 $F$ 推 B，保持 A、B 相对静止，求 $F$ 的最大值。","link":""},{"id":"phy2165","t":"连接体·多物体分组用内力公式","s":"看到【几十节车厢组成的长连接体，已知某一位置的内力求另一位置的内力】","c":"想到【多物体连接体按需要分组等效成两个整体：从第 3 节到最后一节视为一个整体，其受外力就是 $F$；求倒数第 3 节对倒数第 2 节的力时，取倒数第 1、2 节为未受外力部分（$2M$），第 3 节至倒数第 3 节为受 $F$ 部分（$36M$），$T=\\frac{2M}{38M}\\times F=\\frac{F}{19}$】；警惕【分组边界数错车厢数目导致总质量错误；把已知内力误当成作用在整个系统之外的外力】","src":"跳跳物一轮03.4 内力公式_笔记","note":"视频|16:14","orig":"（例）40 节相同车厢（每节质量 $M$）在水平轨道上匀加速行驶，已知第 2 节对第 3 节车厢的牵引力为 $F$，求倒数第 3 节对倒数第 2 节车厢的牵引力。","link":""},{"id":"phy2166","t":"连接体·滑轮连接的等效转换","s":"看到【滑轮连接一物在桌面一物悬空，问互换两物位置后绳拉力或加速度怎么变】","c":"想到【等效转换：把悬空物的重力等效为水平拉力，整体看成光滑水平面上的共$a$连接体再用内力公式；互换前后绳拉力都是 $T=\\frac{M_A M_B g}{M_A+M_B}$，大小不变；加速度由互换前的 $\\frac{M_B g}{M_A+M_B}$ 变为 $\\frac{M_A g}{M_A+M_B}$，因 $M_A>M_B$ 而变大】；警惕【误以为拉力不变加速度也不变；互换后忘记把分子换成新的悬空物质量】","src":"跳跳物一轮03.4 内力公式_笔记","note":"视频|19:07","orig":"（例）A、B 两物块（$M_A>M_B$）经光滑滑轮用轻绳相连，A 在光滑桌面、B 悬空，由静止释放。比较将 A、B 位置互换前后绳的拉力与加速度如何变化。","link":""},{"id":"phy2167","t":"临界问题·五大临界条件","s":"看到【题目出现恰好、刚好、正好等字眼，问临界状态或临界值】","c":"想到【五类临界条件：两物体恰好分离时接触面弹力为零且加速度仍相同；恰好相对滑动时摩擦力等于最大静摩擦（可按滑动摩擦计算）；绳恰好被拉直时绳上弹力为零；绳恰好断裂时弹力等于最大承受力；速度取极值时加速度为零】；警惕【最大静摩擦忘记可按滑动摩擦力计算；把分离前一瞬与分离后一瞬的受力混为一谈】","src":"跳跳物一轮03.5 临界问题_运动和力的关系模块完结撒花~_笔记","note":"视频|00:30","orig":"（知识）高中常见的五类临界问题及其临界条件。","link":""},{"id":"phy2168","t":"临界问题·施力瞬间先整体后隔离","s":"看到【叠放在弹簧上的物体施加拉力瞬间，求两物体间弹力大小】","c":"想到【弹簧弹力不能突变：施力前整体静止，弹簧弹力与总重力平衡，施力瞬间不变，故对 A、B 整体列牛二先解出拉力 $F$（本题 $F=\\frac{3mg}{4}$）；再隔离上面的 B，由拉力、A 对 B 的弹力、重力列牛二解出所求弹力（本题 $F_{AB}=\\frac{mg}{2}$）；整体与隔离两个方程各含一个新未知数，必须先整体后隔离】；警惕【施力瞬间认为弹簧弹力已改变导致整体合力算错；隔离时方程含两个未知数解不出来】","src":"跳跳物一轮03.5 临界问题_运动和力的关系模块完结撒花~_笔记","note":"视频|03:55","orig":"（例）质量 $2m$ 的物体 A 与竖直弹簧拴接，质量 $m$ 的 B 叠放在 A 上，初始静止（弹簧处于压缩），现施加竖直向上的拉力 $F$ 使 A、B 一起以 $g/4$ 匀加速上升，求施力瞬间 A、B 间弹力的大小。","link":""},{"id":"phy2169","t":"临界问题·分离时刻与弹簧两次受力","s":"看到【叠放物体在弹簧上加速上升，问经多久或上升多高后两物体分离】","c":"想到【分离临界：A、B 间弹力为零且加速度仍相同，只隔离下面的 A 列牛二解出分离瞬间弹簧弹力（本题 $T=\\frac{5mg}{2}$）；位移由弹簧两次受力差求：$kx=$初始弹力$-$分离瞬间弹力（本题 $x=\\frac{mg}{2k}$）；整体从静止匀加速，再由 $x=\\frac{1}{2}at^2$ 求时间，$t=2\\sqrt{m/k}$】；警惕【把分离点当成弹簧恢复原长处；忘记用胡克定律的弹力差求位移而直接猜测】","src":"跳跳物一轮03.5 临界问题_运动和力的关系模块完结撒花~_笔记","note":"视频|03:55","orig":"（例）接上题：A（质量 $2m$，与劲度系数为 $k$ 的弹簧拴接）与叠放的 B（质量 $m$）一起以 $g/4$ 匀加速上升直至分离，求从施力到分离所经时间。","link":""},{"id":"phy2170","t":"临界问题·板块相对滑动的两个临界力","s":"看到【地面粗糙的板块模型受水平力，问恰好拉动、恰好相对滑动的临界力或某力下加速度】","c":"想到【两个临界力：下临界 $F_1=\\mu_2(m_A+m_B)g$，$F$ 小于它整体拉不动；上临界用先上后整：A、B 间摩擦达最大 $\\mu_1 m_A g$ 时对 A 求出共同临界加速度 $a=\\mu_1 g$，再对整体列牛二得 $F_2=(m_A+m_B)(\\mu_1+\\mu_2)g$（本题 $5\\,\\mathrm{N}$ 与 $30\\,\\mathrm{N}$）；$F$ 介于两临界之间一起运动用整体法（$21\\,\\mathrm{N}$ 时 $a=3.2\\,\\mathrm{m/s^2}$），超过 $F_2$ 分开隔离：$a_A=\\mu_1 g$ 不变、对 B 单独列式（$33\\,\\mathrm{N}$ 时 $a_A=5\\,\\mathrm{m/s^2}$、$a_B=6\\,\\mathrm{m/s^2}$）】；警惕【地面粗糙时套内力公式失效；超过临界力后仍用整体法求共同加速度】","src":"跳跳物一轮03.5 临界问题_运动和力的关系模块完结撒花~_笔记","note":"视频|11:59","orig":"（例）质量 $2\\,\\mathrm{kg}$ 的物块 A 放在质量 $3\\,\\mathrm{kg}$ 的木板 B 上，A、B 间动摩擦因数 $\\mu_1=0.5$，B 与地面间 $\\mu_2=0.1$，最大静摩擦等于滑动摩擦，$g=10$，对 B 施加水平向右的力 $F$，判断 A、B 何时一起运动、何时相对滑动，并求 $F=21\\,\\mathrm{N}$ 和 $F=33\\,\\mathrm{N}$ 时各自的加速度。","link":""},{"id":"phy2171","t":"临界问题·绳子恰好拉直与恰好拉断","s":"看到【两根绳系住的小球随车水平加速，问某绳刚拉直或恰好不断时的加速度】","c":"想到【BC 刚拉直时其弹力为零，小球只受重力与 AC 拉力，合力必须水平，由 $45^\\circ$ 几何三角形得合力$=mg$、加速度$=g$；BC 绷紧后 AC 拉力的大小方向都不变——否则它与重力的合力不水平，无法与水平的 BC 拉力合成水平合力；故 AC 不会断，BC 拉力达最大值 $mg$ 时加速度最大，合力$=2mg$、最大加速度$=2g$】；警惕【以为加速度增大 AC 绳会先被拉断——AC 拉力不变，先断的是 BC；忽略合力必须保持水平这一方向约束】","src":"跳跳物一轮03.5 临界问题_运动和力的关系模块完结撒花~_笔记","note":"视频|18:14","orig":"（例）小球 $m$ 用绳 AC（长 $\\sqrt{2}L$，与竖直方向成 $45^\\circ$）和水平的绳 BC（长 $L$）系于小车上 A、B 两点（AB 相距 $L$），小车水平向左加速。求 BC 刚被拉直时小车的加速度，以及不拉断绳的最大加速度（AC 最大拉力 $2mg$，BC 最大拉力 $mg$）。","link":""},{"id":"phy2172","t":"板块与传送带·模型地位与考试权重","s":"看到【高考力学压轴题，纠结一轮复习该优先突破哪个模型】","c":"想到【板块模型是力学压轴题的常客：高考压轴题若考力学，大概率考板块模型；传送带模型与板块并列，两者都是典型力学综合题，同属二轮复习重点】；警惕【一轮课未专门讲不等于不重要，勿因一轮跳过而完全搁置这两个模型】","src":"跳跳物一轮03.6 关于板块、传送带模型的说明_笔记","note":"视频|00:24","orig":"（知识）板块模型与传送带模型在高考力学中的地位。","link":""},{"id":"phy2173","t":"复习规划·三轮复习目标区分","s":"看到【规划各轮复习，分不清目标与题型侧重点】","c":"想到【一轮打基础：系统重学概念、知识点和解题技巧，练习以考点单一、基础向的选择题为主；二轮提升综合能力：主攻力学综合题和电磁场综合题；三轮提升应试能力：多做套卷，快速进入考试状态】；警惕【轮次目标张冠李戴——基础未固就狂刷综合压轴题或整套卷，事倍功半】","src":"跳跳物一轮03.6 关于板块、传送带模型的说明_笔记","note":"视频|00:58-01:36","orig":"（知识）一轮、二轮、三轮复习的核心目标与题型分工。","link":""},{"id":"phy2174","t":"板块与传送带·一轮复习资源定位","s":"看到【一轮复习中找不到板块、传送带专题，不知去哪补】","c":"想到【这两个模型一轮不专门讲，因系统课必修一合集第72-75课已详细覆盖且完美适配一轮：第72、73课为板块基础、进阶篇，第74、75课为传送带基础、进阶篇；二轮将作为重点再讲】；警惕【误以为一轮漏讲而另找新课重复学习，或一直拖到二轮才第一次接触模型】","src":"跳跳物一轮03.6 关于板块、传送带模型的说明_笔记","note":"视频|02:28","orig":"（知识）板块、传送带模型在一轮阶段的复习资源与定位。","link":""},{"id":"phy2175","t":"曲线运动·成因判定与恒力易错","s":"看到【问物体在什么条件下做曲线运动，或判断恒力能否使物体做曲线运动】","c":"想到【物体所受合力与速度方向不在同一条直线上时做曲线运动：力与速度同向则加速直线，反向则减速直线，共线仍是直线。合力是恒力也可能做曲线运动，典型如平抛运动只受重力、加速度恒为$g$。判断直线还是曲线，关键看合力与速度是否共线，而非合力是否为恒力】；警惕【误以为只有变力才能产生曲线运动，或以为受恒力必做直线运动】","src":"跳跳物一轮04.1 曲线运动的概念、运动的合成与分解_笔记","note":"视频|00:34-03:51","orig":"（知识）物体做曲线运动的条件，以及合力为恒力时能否做曲线运动。","link":""},{"id":"phy2176","t":"曲线运动·一定变化与不一定变化的物理量","s":"看到【问曲线运动物体一定变化的物理量，或判断速率、加速度是否变化】","c":"想到【速度方向沿轨迹切线方向、时刻变化，故速度一定变化；但速度大小不一定变，曲线运动可以是加速、减速或匀速（如匀速圆周运动速率不变）。加速度大小、方向都不一定变，由合力决定，合力可为恒力或变力。一定变化的只有速度，速率、加速度、合外力均不一定变】；警惕【把速度一定变误当速率一定变，或以为曲线运动的加速度一定变化】","src":"跳跳物一轮04.1 曲线运动的概念、运动的合成与分解_笔记","note":"视频|01:50-03:01","orig":"（知识）做曲线运动的物体，哪些物理量一定变化、哪些不一定变化。","link":""},{"id":"phy2177","t":"曲线运动·力指凹侧与轨迹夹中间","s":"看到【给出曲线轨迹，要求判断某点的合力方向或检验所标合力方向】","c":"想到【速度方向沿轨迹在该点的切线方向，需结合运动起点和终点确定切线具体指向；合力方向一定指向轨迹的凹侧（力指凹侧），轨迹向外鼓的一侧是凸侧、向内凹的一侧是凹侧；轨迹一定夹在速度方向（切线）与合力方向（指凹侧）两个箭头之间】；警惕【若所给合力与速度方向没把轨迹夹在中间，该合力方向必错；合力绝不可能指向轨迹的凸侧】","src":"跳跳物一轮04.1 曲线运动的概念、运动的合成与分解_笔记","note":"视频|05:13-05:51","orig":"（知识）曲线运动中轨迹与速度、合力方向的关系及检验方法。","link":""},{"id":"phy2178","t":"曲线运动·加减速判定口诀","s":"看到【曲线运动中已知速度与合力（加速度）方向的夹角，判断速率变化】","c":"想到【看速度方向与合力（或加速度）方向的夹角：锐角（小于$90^\\circ$）加速、速度增大，钝角（大于$90^\\circ$）减速、速度减小，直角速度大小不变——锐加钝减直不变。典型例子：匀速圆周运动合力（向心力）始终指向圆心、与速度方向垂直，故速率不变】；警惕【直角只是速率不变，速度方向仍时刻在变，勿当成匀速直线运动】","src":"跳跳物一轮04.1 曲线运动的概念、运动的合成与分解_笔记","note":"视频|08:00","orig":"（知识）曲线运动中物体加速还是减速的判断方法。","link":""},{"id":"phy2179","t":"运动的合成与分解·三性与平行四边形定则","s":"看到【涉及合运动与分运动的关系，或问分运动之间是否相互影响】","c":"想到【合成分解的对象是描述运动的矢量：加速度、速度、位移，都遵循平行四边形定则；合运动与分运动具有独立性（各分运动相互独立、互不干扰，研究水平方向无需考虑竖直方向）、等时性（分运动与合运动同时发生、同时停止，持续时间相同）、等效性（合运动效果与各分运动总效果可相互替代）】；警惕【忽视等时性——各分运动与合运动用时相同，不能按分运动各自计时】","src":"跳跳物一轮04.1 曲线运动的概念、运动的合成与分解_笔记","note":"视频|09:55","orig":"（知识）运动合成与分解的对象、法则及合运动与分运动的关系。","link":""},{"id":"phy2180","t":"运动的合成与分解·关联速度（绳杆模型）核心方法","s":"看到【绳、杆一端牵拉另一端运动，已知一端速度求另一端速度】","c":"想到【核心依据：绳（杆）两端沿绳（杆）方向的分速度大小相等。步骤：将绳（杆）两端的实际速度分别沿绳（杆）方向和垂直绳（杆）方向正交分解，求出两端沿绳方向的分速度，令两者相等建立等式，解出未知速度】；警惕【分解时实际速度必须是平行四边形的对角线、夹在两个分速度中间；不能沿任意方向硬拆，更不能把实际速度直接当成沿绳的分速度】","src":"跳跳物一轮04.1 曲线运动的概念、运动的合成与分解_笔记","note":"视频|12:26","orig":"（知识）绳或杆转动时，已知一端速度求另一端速度的关联速度问题解法。","link":""},{"id":"phy2181","t":"运动的合成与分解·汽车拉绳模型","s":"看到【汽车匀速行驶经滑轮用绳拉起物体，已知车速$v$与绳的水平夹角$\\theta$，求物体速度或拉力与重力关系】","c":"想到【将车速$v$沿绳方向与垂直绳方向分解，沿绳分速度$v_1=v\\cos\\theta$即物体上升速度；汽车匀速前进时$\\theta$减小、$\\cos\\theta$增大，物体速度增大而向上加速，加速度向上，由牛顿第二定律绳拉力大于物体重力】；警惕【匀速的是汽车不是物体，物体加速时拉力不等于重力；不能把车速$v$直接当物体速度，或误用$v\\sin\\theta$（角用错）】","src":"跳跳物一轮04.1 曲线运动的概念、运动的合成与分解_笔记","note":"视频|20:25","orig":"（例）汽车向右匀速行驶，通过跨过定滑轮的轻绳竖直拉起物体：某时刻车速为$v$、绳与水平方向夹角为$\\theta$，求物体上升速度大小，并判断绳拉力与物体重力的大小关系。","link":""},{"id":"phy2182","t":"运动的合成与分解·活塞连杆飞轮模型","s":"看到【活塞经连杆带动飞轮（曲柄）转动，给活塞速度$v$与两个夹角$\\alpha$、$\\beta$，求$B$点线速度】","c":"想到【两端沿杆分速度相等：$A$端活塞速度$v$分解得沿杆分量$v_1=v\\cos\\alpha$；$B$点速度沿圆周切线方向，也分解为沿杆、垂直杆两分量，其沿杆分量与$A$端相等；由几何关系$v_1$与$B$点速度的夹角为$\\beta-90^\\circ$，而$\\cos(\\beta-90^\\circ)=\\sin\\beta$，故$v_1=v_B\\sin\\beta$，解得$v_B=v\\cos\\alpha/\\sin\\beta$】；警惕【$B$点速度只能沿圆周切线，不能沿水平、竖直方向分解；两个端点都要按沿杆、垂直杆分解，几何角要靠垂直关系找等角】","src":"跳跳物一轮04.1 曲线运动的概念、运动的合成与分解_笔记","note":"视频|24:08","orig":"（例）活塞沿水平方向以速度$v$向左移动，通过连杆带动飞轮上的$B$点沿圆周转动：某时刻连杆与活塞速度方向夹角为$\\alpha$、与$B$点速度方向（圆切线）夹角为$\\beta$，求$B$点的线速度大小。","link":""},{"id":"phy2183","t":"平抛运动·概念与匀变速属性","s":"看到【题目说物体做平抛运动，或问平抛是否匀变速、速度变化量有何特点】","c":"想到【平抛运动：初速度方向水平、只受重力的运动，题目说做平抛就意味着忽略空气阻力。它虽是曲线运动，但加速度恒为$g$，是匀变速运动——判断匀变速只看加速度是否恒定，与轨迹是直线还是曲线无关。相同时间内的速度变化量相同，$\\Delta v=g\\cdot\\Delta t$】；警惕【误以为只有直线运动才是匀变速运动，或曲线运动的加速度一定变化】","src":"跳跳物一轮04.2 平抛运动_笔记","note":"视频|00:19-01:24","orig":"（知识）平抛运动的定义与运动性质，以及曲线运动能否是匀变速运动的判断。","link":""},{"id":"phy2184","t":"平抛运动·化曲为直与核心方程","s":"看到【平抛运动求时间、位移、速度等物理量，或问如何研究平抛】","c":"想到【化曲为直：水平方向不受力做匀速直线运动，$x=v_0t$；竖直方向初速度为0、只受重力做自由落体，$v_y=gt$、$y=\\frac{1}{2}gt^2$，还可用平均速度式$y=\\frac{v_y}{2}\\cdot t$简化计算。合速度两种求法：勾股定理$v=\\sqrt{v_0^2+v_y^2}$，或$v_0/\\cos\\theta$（$\\theta$为速度与水平方向夹角）】；警惕【求时间的突破口在竖直方向（水平$x=v_0t$中两量都未知无从下手）；$y=\\frac{v_y}{2}\\cdot t$中必须代该时刻的竖直分速度】","src":"跳跳物一轮04.2 平抛运动_笔记","note":"视频|02:18-03:33","orig":"（知识）平抛运动的研究方法、分方向方程与合速度求法。","link":""},{"id":"phy2185","t":"平抛运动·初速度对轨迹与时间的影响","s":"看到【比较不同初速度平抛轨迹的陡缓，或问初速度对飞行时间的影响】","c":"想到【轨迹：初速度越大轨迹越接近水平、越平缓，初速度很小则很陡，初速度为0退化为自由落体。时间：由竖直位移决定，$T=\\sqrt{2y/g}$——对着水平地面平抛，物体都落到同一水平面、下落高度相同，时间与初速度无关；沿斜面平抛，初速度越大飞得越远、下落高度越大，时间越长】；警惕【水平面上误以为初速度大就飞得久；斜面场景漏考虑初速度增大会使下落高度增大】","src":"跳跳物一轮04.2 平抛运动_笔记","note":"视频|06:15-09:07","orig":"（知识）初速度大小如何影响平抛轨迹形状与飞行时间。","link":""},{"id":"phy2186","t":"平抛运动·速度角与位移角正切二倍推论","s":"看到【平抛中已知长度求速度方向，或已知速度方向反求位移长度】","c":"想到【速度偏转角$\\theta$、位移偏转角$\\varphi$都是与水平方向（初速度方向）的夹角；任意时刻$\\tan\\theta=2\\tan\\varphi$。原因：$\\tan\\theta=v_y/v_0=gt/v_0$，$\\tan\\varphi=y/x=\\frac{\\frac{1}{2}gt^2}{v_0t}=\\frac{gt}{2v_0}$，后者恰为前者一半。用途是长度与角度互转：已知$x$、$y$可求$\\theta$，已知$\\theta$和$y$可反求$x$】；警惕【2倍是正切值关系而非角度关系：$\\varphi=30^\\circ$时$\\theta\\neq60^\\circ$，角度之间没有直接二倍关系】","src":"跳跳物一轮04.2 平抛运动_笔记","note":"视频|11:21","orig":"（知识）平抛运动中速度偏转角与位移偏转角的关系及用途。","link":""},{"id":"phy2187","t":"平抛运动·速度反向延长线过中点推论","s":"看到【平抛中只给速度方向要求水平位移，或长度与角度互转】","c":"想到【任意时刻平抛速度的反向延长线必过该段水平位移的中点：物体从$O$运动到$C$，水平位移$OB$，过$C$作速度反向延长线交$OB$于$A$，则$OA=AB$（$A$为$OB$中点）。该推论由$\\tan\\theta=2\\tan\\varphi$推得，用途与角度推论相同，用于长度和角度之间的相互转换】；警惕【中点截在“抛出点到该时刻位置”的水平位移上，不是别的线段；反向延长线与水平方向的夹角就等于速度偏转角】","src":"跳跳物一轮04.2 平抛运动_笔记","note":"视频|15:07","orig":"（知识）平抛运动速度反向延长线与水平位移的关系及用途。","link":""},{"id":"phy2188","t":"平抛运动·斜面上平抛（位移角等于斜面角）","s":"看到【物体沿水平方向抛出落到同一斜面上，给初速度和斜面倾角$\\theta$】","c":"想到【落点在斜面上，则位移偏转角等于斜面倾角$\\theta$：$\\tan\\theta=y/x=\\frac{\\frac{1}{2}gt^2}{v_0t}=\\frac{gt}{2v_0}$，解得$t=2v_0\\tan\\theta/g$；再依次用$x=v_0t$、$v_y=gt$、$v=\\sqrt{v_0^2+v_y^2}$求各量。本题$t=\\sqrt{3}/10$ s，A到B水平距离$=1.5\\sqrt{3}/10$ m，B点速度$=\\sqrt{21}/2$ m/s】；警惕【速度偏转角不等于2倍斜面角——位移角$30^\\circ$时速度角不是$60^\\circ$，正切二倍关系不是角度二倍关系】","src":"跳跳物一轮04.2 平抛运动_笔记","note":"视频|19:34","orig":"（例）游客从斜面顶端的$A$点以初速度1.5m/s沿水平方向滑出，落到倾角$30^\\circ$的斜面上$B$点，求运动时间、$A$到$B$的水平距离及$B$点速度大小。","link":""},{"id":"phy2189","t":"平抛运动·同高双平抛撞墙的比例问题","s":"看到【同一高度两个平抛撞同一竖直墙，给两个撞墙速度角，问各量比例】","c":"想到【两者水平位移相同（抛出点到墙的距离）：由$\\tan\\alpha=2\\tan\\varphi$得$y=x\\tan\\alpha/2$，下落高度比$y_1:y_2=\\tan30^\\circ:\\tan60^\\circ=1:3$；由$y=\\frac{1}{2}gt^2$得$y\\propto t^2$，时间比$1:\\sqrt{3}$；由$x=v_0t$得$v_0\\propto 1/t$，初速度比$\\sqrt{3}:1$；由$v=v_0/\\cos\\alpha$得撞墙速度比$1:1$】；警惕【水平位移相同时初速度与时间成反比，比例关系别写颠倒；$\\tan\\alpha=2\\tan\\varphi$是正切关系，不能直接用在角度上】","src":"跳跳物一轮04.2 平抛运动_笔记","note":"视频|22:40","orig":"（例）两个小球从同一高度分别以不同初速度水平抛出，都撞到同一竖直墙上，撞墙时速度方向与水平方向的夹角分别为$30^\\circ$和$60^\\circ$，求两者下落高度比、飞行时间比、初速度比与撞墙速度比。","link":""},{"id":"phy2190","t":"平抛运动·无碰撞进管（速度方向沿管）","s":"看到【小球水平抛出恰好无碰撞进入倾斜直管，给管倾角与两点高度】","c":"想到【“无碰撞”意味着到达管口时速度方向沿管方向，速度偏转角等于管与水平方向的夹角$45^\\circ$；用速度反向延长线过水平位移中点的推论，延长线与水平位移一半构成等腰直角三角形，由$\\tan45^\\circ=y/(x/2)$得$x=2y$（$y$为两点高度差）；再由$y=\\frac{1}{2}gt^2$求时间、$v_0=x/t$求初速度。本题$y=0.8$m，$x=1.6$m，$v_0=4$m/s】；警惕【“无碰撞”是速度方向沿管而不是位移方向沿管；等腰直角三角形的两直角边是$x/2$与$y$，中点截在水平位移上】","src":"跳跳物一轮04.2 平抛运动_笔记","note":"视频|26:45","orig":"（例）小球从离地1.2m处水平弹出，恰好无碰撞地进入离地0.4m、与水平方向成$45^\\circ$的直管管口$M$，求弹出点到管口的水平位移与弹出初速度。","link":""},{"id":"phy2191","t":"平抛运动·速度角关系与已知速度角求初速度","s":"看到【平抛中已知速度角（或某角正切），要求初速度$v_0$或需列速度方向方程】","c":"想到【速度矢量三角形中$\\tan\\theta=v_y/v_0$；求$v_0$用「缺啥补啥」三步：先列$\\tan\\theta=v_y/v_0$，再补$v_y=gt$，最后按已知条件补$x=v_0t$（已知水平位移）或$y=\\frac{1}{2}gt^2$（已知竖直位移）联立求解】；警惕【$\\theta$若指速度与竖直方向的夹角，公式变为$\\tan\\theta=v_0/v_y$，分子分母颠倒易张冠李戴；第三步方程须按已知位移条件选择，不可死记顺序】","src":"跳跳物一轮04.3 与斜面、圆弧面有关的平抛_笔记","note":"视频|00:39-01:43","orig":"（知识）平抛瞬时速度可分解为水平分速度$v_0$与竖直分速度$v_y$，速度角$\\theta$指合速度与水平方向的夹角。","link":""},{"id":"phy2192","t":"平抛运动·起点终点都在斜面的角度与比例结论","s":"看到【平抛的抛出点和落点都在同一斜面上，问角度关系或各物理量比例】","c":"想到【位移角=斜面角，速度角的正切=2×斜面角的正切，速度角与位移角只由斜面角决定、与初速度无关；位移量（$x$、$y$、$s$）$\\propto v_0^2$，非位移量（$t$、$v$、$v_y$）$\\propto v_0$】；警惕【起点或终点不在该斜面上（空中抛出、飞出斜面）时上述结论全部失效，必须回到基本方程联立求解】","src":"跳跳物一轮04.3 与斜面、圆弧面有关的平抛_笔记","note":"视频|03:42-08:19","orig":"（知识）平抛的抛出点与落点都在同一斜面上时，位移方向平行斜面。","link":""},{"id":"phy2193","t":"平抛运动·垂直打斜面的角度关系","s":"看到【平抛垂直打在斜面上，求时间或初速度（涉及速度与竖直方向夹角）】","c":"想到【速度与竖直方向的夹角$\\beta$等于斜面角$\\theta$；速度矢量三角形中对边是$v_0$、邻边是$v_y$，故$\\tan\\theta=v_0/v_y$；配合$v_y=gt$得$t=v_0/(g\\tan\\theta)$】；警惕【此处$\\theta$是速度与竖直方向的夹角，与基础式$\\tan\\theta=v_y/v_0$（与水平方向夹角）定义不同，公式分子分母正好颠倒】","src":"跳跳物一轮04.3 与斜面、圆弧面有关的平抛_笔记","note":"视频|08:42","orig":"（知识）小球平抛后垂直落在斜面上，落点瞬时速度方向与斜面垂直。","link":""},{"id":"phy2194","t":"平抛运动·平抛与上下半圆相切","s":"看到【平抛小球与圆弧轨道相切（无碰撞进入），已知半径和圆心角求初速度】","c":"想到【切点速度垂直于过切点的半径；切点速度角$\\theta$等于对应的圆心角$\\alpha$：下半圆取切点与最低点之间的圆心角，上半圆取切点与最高点之间的圆心角；再按$\\tan\\theta=v_y/v_0$、$v_y=gt$与几何关系联立求$v_0$】；警惕【上下半圆的圆心角参考点不同（最低点与最高点）；若已知的是半径与水平方向的夹角，需用90°减去它换算成速度角】","src":"跳跳物一轮04.3 与斜面、圆弧面有关的平抛_笔记","note":"视频|11:36-13:58","orig":"（知识）小球平抛后沿切线方向进入圆弧轨道（无碰撞进入）。","link":""},{"id":"phy2195","t":"平抛运动·从半圆弧边沿平抛","s":"看到【小球从半圆弧（凹槽）边沿水平抛出，问能否垂直打在圆弧面上】","c":"想到【不可能垂直打圆弧；反证：若速度垂直圆弧，其反向延长线必过圆心，但平抛速度反向延长线过水平位移中点，而圆心是直径中点、不可能是水平位移中点，矛盾】；警惕【判断依据是两个推论的矛盾而非直觉；等高落点只能推出时间相同，推不出速度垂直圆弧】","src":"跳跳物一轮04.3 与斜面、圆弧面有关的平抛_笔记","note":"视频|15:34","orig":"（知识）小球从半圆弧边沿（直径端点）水平抛出后落到圆弧上。","link":""},{"id":"phy2196","t":"平抛运动·斜面平抛比值计算套路","s":"看到【起点终点均在斜面的平抛，给位移（落点）关系求各量比例】","c":"想到【先由位移比开方得初速度比：位移量$\\propto v_0^2$，位移比2:1对应初速度比$\\sqrt{2}$:1；再用非位移量$\\propto v_0$得时间、落点速度之比均为$\\sqrt{2}$:1；离斜面最远时速度方向与斜面平行，$v=v_0/\\cos\\theta$，也与$v_0$成正比】；警惕【位移比与初速度比是平方（开方）关系，不是线性关系；选项常把$\\sqrt{2}$:1写成2:1设陷阱】","src":"跳跳物一轮04.3 与斜面、圆弧面有关的平抛_笔记","note":"视频|17:12","orig":"（例）两小球从斜面顶端先后平抛，分别落在同一斜面的中点和底端，选项比较运动时间、初速度、离斜面最远时速度、落斜面时速度之比（答案ACD）。","link":""},{"id":"phy2197","t":"平抛运动·抛出点不在斜面的落点条件翻译","s":"看到【抛出点不在斜面上的平抛，给落点方式（最小位移、垂直、中点）求时间】","c":"想到【把落点条件翻译成几何关系再联立：最小位移到达→位移垂直斜面，$y/x=\\tan\\theta$，得$t=2v_0/(g\\tan\\theta)$；垂直击中→速度与竖直方向夹角为$\\theta$，$v_0/(gt)=\\tan\\theta$，得$t=v_0/(g\\tan\\theta)$；击中中点→$y/x=\\tan\\theta$，得$t=2v_0\\tan\\theta/g$】；警惕【抛出点不在斜面上时，斜面平抛的角度与比例结论全部失效；三种落点的时间表达式互不相同，不能当成定值】","src":"跳跳物一轮04.3 与斜面、圆弧面有关的平抛_笔记","note":"视频|21:22","orig":"（例）小球从斜面外的空中某点平抛落到斜面上，选项讨论以最小位移到达斜面、垂直击中斜面、击中斜面中点的时间表达式（答案AB）。","link":""},{"id":"phy2198","t":"平抛运动·无碰撞进入圆弧轨道","s":"看到【平抛「无碰撞进入」圆弧轨道，给半径和角度求初速度】","c":"想到【「无碰撞进入」即相切：切点速度垂直半径，切点与最低点间圆心角=速度角$\\theta$；列$\\tan\\theta=v_y/v_0$、$v_y=gt$；竖直位移由几何求（过切点作水平辅助线，$y=R\\cos\\theta$），再由$y=\\frac{1}{2}gt^2$解出$t$，联立得$v_0$】；警惕【竖直位移不等于半径本身，须作水平辅助线用几何换算；若给的是半径与水平方向夹角，先用90°换算成速度角】","src":"跳跳物一轮04.3 与斜面、圆弧面有关的平抛_笔记","note":"视频|30:53","orig":"（例）小球平抛后无碰撞进入竖直放置的下半圆弧轨道，切点与最低点间的圆心角对应速度角53°，轨道半径3 m，求平抛初速度（答案4.5 m/s）。","link":""},{"id":"phy2199","t":"平抛运动·临界问题两步法","s":"看到【平抛过网/不出界问题，求临界初速度或速度范围】","c":"想到【两步法：先定临界轨迹——恰好擦网上沿是过网的最小初速度轨迹（再小则撞网），恰好落在边界线上是不出界的最大初速度轨迹（再大则出界）；再用轨迹方程$y=gx^2/(2v_0^2)$（由$x=v_0t$、$y=\\frac{1}{2}gt^2$消去$t$得到），把临界点的水平、竖直位移代入解出临界初速度】；警惕【过网对应速度下限、出界对应速度上限，方向别搞反；代入的$x$、$y$须是同一条临界轨迹上从抛出点量起的位移】","src":"跳跳物一轮04.4 平抛临界问题、斜抛_笔记","note":"视频|00:24-00:33","orig":"（知识）物体对着球网、挡板等障碍物做平抛运动，分析恰好过网或恰好不出界的条件。","link":""},{"id":"phy2200","t":"斜抛运动·分解方程与运动性质","s":"看到【斜抛（斜向上抛出、只受重力），求分速度、位移或判断运动性质】","c":"想到【斜抛是匀变速曲线运动，加速度恒为$g$、全程完全失重；正交分解：水平方向匀速直线，$v_{0x}=v_0\\cos\\theta$、$x=v_{0x}t$；竖直方向为竖直上抛，$v_{0y}=v_0\\sin\\theta$、$y=v_{0y}t-\\frac{1}{2}gt^2$；忽略空气阻力时以45°发射射程最远】；警惕【全程加速度竖直向下，不存在「先超重后失重」；最高点只有竖直分速度为零，水平分速度不为零】","src":"跳跳物一轮04.4 平抛临界问题、斜抛_笔记","note":"视频|03:53-05:29","orig":"（知识）斜抛运动：初速度方向斜向上、只受重力（题目提到斜抛即默认忽略空气阻力）。","link":""},{"id":"phy2201","t":"斜抛运动·最高点特征与两段平抛分解","s":"看到【斜抛求某点速度或位移，轨迹含最高点】","c":"想到【最高点竖直分速度为零、速度方向水平（任何运动的最高点或最低点竖直分速度均为零）；以最高点为界拆成两段平抛：后半段是平抛，前半段倒着看也是平抛；水平分速度全程不变，各段时间由各自竖直位移用$y=\\frac{1}{2}gt^2$求出】；警惕【最高点速度不为零（等于水平分速度）；两段竖直位移不同，时间不能共用】","src":"跳跳物一轮04.4 平抛临界问题、斜抛_笔记","note":"视频|07:08","orig":"（知识）斜抛轨迹可从最高点拆分：最高点之后是标准平抛，抛出点到最高点是平抛的逆运动。","link":""},{"id":"phy2202","t":"斜抛运动·对称性结论","s":"看到【斜抛轨迹上两点关于最高点对称，比较速度、时间或位移】","c":"想到【关于对称轴对称的两点速度大小相等、方向不同；对称两段运动所用时间相等；速度变化量$\\Delta v=g\\cdot t$，等时间必等变化量】；警惕【「速度大小相等」不是「速度相同」，方向并不一致；最高点前后对称段的时间相等才保证$\\Delta v$相同，别用位置对称冒充】","src":"跳跳物一轮04.4 平抛临界问题、斜抛_笔记","note":"视频|09:56","orig":"（知识）斜抛轨迹关于过最高点的竖直直线对称。","link":""},{"id":"phy2203","t":"平抛运动·套圈临界初速度范围","s":"看到【平抛套圈/穿环类问题，抛出物有横向尺寸，求能套住的初速度范围】","c":"想到【用两条临界轨迹定范围：环的远端恰好碰到杆上端→水平位移最大→最大初速度；近端恰好碰到→水平位移最小→最小初速度；竖直位移均为抛出点与杆上端的高度差；分别代入轨迹方程$y=gx^2/(2v_0^2)$解出两个边界速度，初速度取闭区间】；警惕【临界轨迹有最大、最小两条，只算一条会漏解；水平位移须加/减环自身横向尺寸】","src":"跳跳物一轮04.4 平抛临界问题、斜抛_笔记","note":"视频|11:32","orig":"（例）圆环从离地1 m高处水平抛出，去套住3 m外高0.2 m的细杆（圆环左右各宽0.1 m，水杯粗细忽略），问初速度在什么范围内能套住杆的上端（选项含7.6 m/s、7.7 m/s等，答案AB）。","link":""},{"id":"phy2204","t":"平抛运动·触网与越界的临界高度","s":"看到【平抛过网问题问「无论初速度多大都触网或出界」的高度条件】","c":"想到【找临界高度：恰有一个初速度使球恰好擦网上沿且恰好落在底线（同一条轨迹）；对完整轨迹（水平18 m、下落$h$）和到网前半段（水平9 m、下落$h-2.25$ m）分别列轨迹方程，两式相除消去初速度，由下落高度比=水平位移比的平方解出$h$；抛出点低于该高度则必触网或出界】；警惕【恰好过网与恰好落底线须对应同一初速度（同一条轨迹），方程要联立消元；下落高度比是水平位移比的平方，别当线性关系】","src":"跳跳物一轮04.4 平抛临界问题、斜抛_笔记","note":"视频|16:06","orig":"（例）排球场网高2.25 m，抛出点到球网水平距离9 m、到底线18 m，在离地h处以不同初速度水平发球，问h满足什么条件时无论初速度多大球总会触网或出界（答案h$\\leq$3 m，选A）。","link":""},{"id":"phy2205","t":"斜抛运动·拆两段平抛计算","s":"看到【斜抛已知某点速度方向和各点高度，求最高点速度、出手速度或水平位移】","c":"想到【以最高点为界拆成两段平抛：每段用竖直位移$y=\\frac{1}{2}gt^2$求该段时间，用$\\tan\\theta=v_y/v$由落点速度方向求水平速度（即最高点速度）；出手速度由水平分速度与该段竖直分速度合成$v=\\sqrt{v_{0x}^2+v_y^2}$；水平总位移=最高点速度×两段时间之和】；警惕【两段竖直位移不同、时间不同，须分别求；水平分速度全程不变，但出手速度不等于最高点速度】","src":"跳跳物一轮04.4 平抛临界问题、斜抛_笔记","note":"视频|22:00","orig":"（例）篮球从离地2.40 m的A点斜抛出手，经最高点B（离地4.85 m）后落到离地3.05 m的C点，C点速度与水平方向成45°，求最高点B的速度、出手速度及A到C的水平位移（答案6 m/s、$\\sqrt{85}$ m/s、7.8 m）。","link":""},{"id":"phy2206","t":"圆周运动·线速度定义与匀速圆周的含义","s":"看到【圆周运动给弧长与时间求线速度，或判断匀速圆周运动的性质】","c":"想到【线速度$v=\\Delta s/\\Delta t$（极短时间内的弧长与时间之比），方向沿圆周上该点的切线；极短时间内弧长$\\approx$位移，故线速度就是瞬时速度，无「平均线速度」的说法；匀速圆周运动的「匀速」只指线速度大小处处相等，方向时刻变化，属变速运动】；警惕【把匀速圆周运动当成匀速或匀加速运动——它大小不变但方向变，是变加速曲线运动】","src":"跳跳物一轮04.5 描述圆周运动的物理量、方程_笔记","note":"视频|00:23-02:54","orig":"（知识）线速度描述圆周运动的快慢，是做圆周运动物体的瞬时速度。","link":""},{"id":"phy2207","t":"圆周运动·角速度定义与弧度制","s":"看到【圆周运动给转过的角度与时间求角速度，或角度与弧度换算】","c":"想到【角速度$\\omega=\\Delta\\theta/\\Delta t$（与圆心连线扫过的角度与时间之比）；高中阶段一律按标量处理、不研究方向；计算时角度必须用弧度制：$180^\\circ=\\pi$ rad、$60^\\circ=\\pi/3$ rad，单位rad/s；题目未说明时按瞬时角速度处理】；警惕【用角度制数值直接代入会差一个换算因子；rad建议保留单位，别与圈数、度数混算】","src":"跳跳物一轮04.5 描述圆周运动的物理量、方程_笔记","note":"视频|03:49","orig":"（知识）角速度描述物体绕圆心转动的快慢。","link":""},{"id":"phy2208","t":"圆周运动·周期频率转速关系","s":"看到【圆周运动给周期、频率或转速（r/s、r/min），求其他量或时间】","c":"想到【周期$T$是转一圈所用时间；频率$f$是每秒转的圈数，$f=1/T$（互为倒数）；转速$n$无特殊说明时默认每秒转数，即$n=f$；三者只适用于匀速圆周运动（非匀速圆周没有固定周期和频率）】；警惕【转速单位是r/min时须先换算成r/s才能当频率用；周期越小、频率越大转得越快，别记反】","src":"跳跳物一轮04.5 描述圆周运动的物理量、方程_笔记","note":"视频|07:38","orig":"（知识）周期、频率、转速都用于描述匀速圆周绕圆心转动的快慢。","link":""},{"id":"phy2209","t":"圆周运动·向心力本质与匀速非匀速判别","s":"看到【圆周运动受力分析，或判断匀速/非匀速圆周、向心力来源】","c":"想到【向心力是效果力，不是真实存在的力，由某个力、某个力的分力或几个力的合力提供，受力分析时不画它；匀速圆周：合力就是向心力，大小不变、时刻指向圆心；非匀速圆周：向心力是合力指向圆心的分力（改变速度方向），切向分力改变速度大小；一切圆周运动都是变加速运动】；警惕【向心力与重力、弹力、摩擦力并列出现在受力分析中即错；非匀速圆周中合力并不指向圆心】","src":"跳跳物一轮04.5 描述圆周运动的物理量、方程_笔记","note":"视频|10:31-11:25","orig":"（知识）向心力是做圆周运动的物体受到的指向圆心的力。","link":""},{"id":"phy2210","t":"圆周运动·核心方程组","s":"看到【圆周运动求线速度、角速度、周期、向心加速度或向心力】","c":"想到【运动学：$v=\\omega r$；$\\omega=2\\pi/T$；$T=2\\pi r/v$；向心加速度$a=v^2/r=\\omega^2 r=4\\pi^2 r/T^2=\\omega v$。动力学：$F=ma=mv^2/r=m\\omega^2 r=m\\omega v$。除含$T$的式子（$4\\pi^2 r/T^2$）仅限匀速圆周运动外，其余各式可用于任何圆周运动】；警惕【方程只表示大小关系，代数只代大小；非匀速圆周用方程时各量必须取同一时刻的值】","src":"跳跳物一轮04.5 描述圆周运动的物理量、方程_笔记","note":"视频|11:25","orig":"（知识）描述圆周运动的核心运动学方程与动力学方程。","link":""},{"id":"phy2211","t":"圆周运动·离心与向心运动判据","s":"看到【圆周物体转速变化或提供的力不足，判断离心、向心还是飞出】","c":"想到【比较「提供」与「需要」：提供>需要→物体做向心运动（向圆心靠拢）；提供<需要→做离心运动（远离圆心）；提供的向心力完全消失（如绳断）→物体沿切线方向做直线运动】；警惕【离心不是受到了「离心力」，而是提供的力不够；力消失时沿切线飞出而非沿半径方向飞出】","src":"跳跳物一轮04.5 描述圆周运动的物理量、方程_笔记","note":"视频|11:25","orig":"（知识）物体做圆周运动的条件：提供的向心力等于需要的向心力。","link":""},{"id":"phy2212","t":"圆周运动·同轴转动各量关系","s":"看到【转动物体（转笔、转球、圆盘、杆）上不同点的线速度、加速度比较】","c":"想到【同轴转动各点角速度相同（相同时间内转过的角度相同）；各点的圆周运动半径是到转轴的垂直距离，可以不同；由$v=\\omega r$、$a=\\omega^2 r$知角速度相同时，离轴越远的点线速度、向心加速度越大】；警惕【半径须取到转轴的垂直距离，不是到某任意点距离；转杆上不与手接触的点，向心力由重力和杆弹力的合力提供，不是摩擦力】","src":"跳跳物一轮04.5 描述圆周运动的物理量、方程_笔记","note":"视频|25:46","orig":"（知识）同一转动物体（同轴）上的各点都绕轴做圆周运动。","link":""},{"id":"phy2213","t":"圆周运动·绳拉卷轴插销临界问题","s":"看到【绳拉转轴带动其上物体转动，弹力提供向心力，求速度最大值】","c":"想到【绳速=卷轴边缘线速度；卷轴、细管、插销同轴，角速度相同，$\\omega=v/r$（$r$为卷轴半径）；弹簧弹力提供插销的向心力：$k(R-L/2)=m\\omega^2 R$（$R$为插销运动半径）；「转动不停止」翻译为$R$不超过细管长$L$；$R$越大$v$越大，取$R=L$解得$v=r\\cdot\\sqrt{k/(2m)}$】；警惕【卷轴半径$r$与插销运动半径$R$是两个量；弹簧原长是$L/2$不是0，形变量为$R-L/2$】","src":"跳跳物一轮04.5 描述圆周运动的物理量、方程_笔记","note":"视频|38:04","orig":"（例）细绳绕在半径r的卷轴边缘以速度v匀速拉动，卷轴上固定长L的细管，管内劲度系数k的弹簧（原长L/2）连接质量m的插销随卷轴转动，求卷轴转动不停止的最大拉绳速度（答案$v=r\\cdot\\sqrt{k/(2m)}$，选A）。","link":""},{"id":"phy2214","t":"传动问题·同轴传动的判定条件","s":"看到【两点绕同一转轴转动或位于同一转动整体上，问角速度或线速度关系】","c":"想到【同轴传动时整体上各点角速度相同，与半径无关；判定必要条件是两点同在一个整体上、跟着整体一起转；同轴各点线速度与半径成正比，半径大的点 $v$ 大】；警惕【“绕同一圆心转”不等于同轴传动：两人绕同一旗杆追逐没有共同转动整体，角速度不一定相等】","src":"跳跳物一轮04.6 传动问题、圆锥摆_笔记","note":"视频|00:29","orig":"（知识）同轴传动指同一个整体绕同一轴自转，如粘在一起共轴的大小轮、自转篮球上的任意两点、转笔时笔杆上的两点。","link":""},{"id":"phy2215","t":"传动问题·共带/齿轮/摩擦传动的边缘线速度","s":"看到【两轮由皮带、齿轮啮合或摩擦连接传动，问边缘点线速度、角速度关系】","c":"想到【不打滑时两轮边缘接触点线速度大小相等，由此两轮角速度与半径成反比（$\\omega\\propto 1/r$）；一轮边缘点与另一轮非边缘点比较时结合同轴规则（$\\omega$ 相同、$v\\propto r$）综合判断】；警惕【“边缘线速度相等”只对两轮接触/连接点成立，轮上非边缘点不适用；打滑时结论失效（高中默认不打滑）】","src":"跳跳物一轮04.6 传动问题、圆锥摆_笔记","note":"视频|02:46","orig":"（知识）共带传动（皮带连接两轮）、齿轮传动（齿轮啮合）、摩擦传动（轮缘间摩擦）都是通过不同方式连接两轮边缘实现传动。","link":""},{"id":"phy2216","t":"传动问题·列表法求各量比值","s":"看到【同轴点与皮带/齿轮传动点混在同一体系，问各点 $\\omega$、$v$、$a$ 比例】","c":"想到【按 $r\\to\\omega\\to v\\to a$ 顺序填表：先填各点半径比；同轴的点 $\\omega$ 填相同值；由 $v=\\omega r$ 算出可算点的 $v$；由传动（边缘 $v$ 相等）补全其余 $v$；再反推剩余点的 $\\omega$；最后由 $a=\\omega v$（或 $a=\\omega^2 r$）算全表，各列相比即得答案】；警惕【顺序不能乱：先同轴定 $\\omega$ 再传动定 $v$，一环用错全表皆错；周期比等于角速度比的倒数】","src":"跳跳物一轮04.6 传动问题、圆锥摆_笔记","note":"视频|04:43","orig":"（知识）多个传动点求 r、$\\omega$、v、a 的比值用列表法，口诀“让(r)我($\\omega$)为(v)爱(a)”。","link":""},{"id":"phy2217","t":"圆锥摆·核心方程组","s":"看到【绳系小球在水平面做匀速圆周运动（圆锥摆），求 $\\omega$、$T$、$a$ 或高度关系】","c":"想到【圆周半径 $R=L\\sin\\theta$；向心加速度 $a=g\\tan\\theta$；角速度 $\\omega=\\sqrt{g/h}$，$h$ 为悬挂点到小球运动平面的竖直距离；拉力 $T=mg/\\cos\\theta$；四式联立可解各类圆锥摆问题】；警惕【$h$ 不是小球到地面的高度，而是悬挂点到圆周平面的竖直距离；合力方向水平指向圆心，不沿绳方向】","src":"跳跳物一轮04.6 传动问题、圆锥摆_笔记","note":"视频|09:02","orig":"（知识）圆锥摆：绳一端固定、另一端系小球，小球在水平面做匀速圆周运动，只受重力 $mg$ 和沿绳指向悬挂点的拉力 $T$，合力水平指向圆心。","link":""},{"id":"phy2218","t":"圆锥摆·等长摆更高更快更强","s":"看到【同长绳（或光滑半球碗）上小球在不同高度轨道做水平圆周，比较 $\\omega$、$v$、$T$ 大小】","c":"想到【口诀“更高、更快、更强”：小球越高，悬挂点到运动平面的距离 $h$ 越小、$\\theta$ 越大，由核心方程得 $a$、$v$、$\\omega$、向心力、绳拉力（碗支持力）均越大，周期越小；碗模型同法判断】；警惕【“更高”要翻译成 $h$ 更小（悬点到运动平面距离），不能代小球离地高度；碗中小球越高结论同样成立，勿因支持力方向不同而弃用】","src":"跳跳物一轮04.6 传动问题、圆锥摆_笔记","note":"视频|13:23","orig":"（知识）等长摆指绳长不变的圆锥摆；光滑半球形碗内壁上做水平圆周的小球是其变式（支持力相当于拉力、球心相当于悬挂点、碗半径相当于绳长）。","link":""},{"id":"phy2219","t":"圆锥摆·等高摆与倒锥筒","s":"看到【多个圆锥摆 $h$ 相同（同一水平面圆周）或两球贴同一锥筒内壁不同高度，比较各量】","c":"想到【等高摆：由 $\\omega=\\sqrt{g/h}$ 各球角速度相同，线速度、加速度与半径成正比，但拉力 $T=mg/\\cos\\theta$ 由摆角决定；倒锥筒：由 $a=g\\tan\\theta$ 各球向心加速度相同、支持力 $N=mg/\\cos\\theta$ 相同，半径大的球 $v$ 大、$\\omega$ 小】；警惕【等高摆推不出拉力相同，倒锥筒推不出角速度相同，两组结论不能互相搬用】","src":"跳跳物一轮04.6 传动问题、圆锥摆_笔记","note":"视频|19:17-19:57","orig":"（知识）等高摆：各圆锥摆悬挂点到小球运动平面的竖直距离 $h$ 相同；倒锥筒：两球贴同一锥形筒内壁，支持力与竖直方向夹角 $\\theta$ 相同。","link":""},{"id":"phy2220","t":"传动问题·齿轮系齿数比与几何关系","s":"看到【多个齿轮依次啮合，已知各轮齿数及啮合位置几何关系，求某轮角速度】","c":"想到【所有齿轮边缘线速度大小相等，故 $\\omega_3=\\omega R_1/R_3$；齿数比等于周长比等于半径比（$R_1:R_2=N_1:N_2$）；由啮合几何 $R_3=R_1+2R_2$，按齿数份数得 $R_3=N_1+2N_2$ 份，故 $\\omega_3=N_1\\omega/(N_1+2N_2)$】；警惕【几何关系中行星轮以直径 $2R_2$ 进入，不是齿数直接相加；相邻齿轮间是线速度相等，不能套角速度相等】","src":"跳跳物一轮04.6 传动问题、圆锥摆_笔记","note":"视频|21:42","orig":"（例）轮系中太阳轮（1 号轮，角速度 $\\omega$、齿数 $N_1$）带动行星轮（2 号轮，齿数 $N_2$），行星轮又与外侧大轮（3 号轮）啮合，求 3 号轮的角速度 $\\omega_3$。","link":""},{"id":"phy2221","t":"圆锥摆·恰好离开锥面的临界角速度","s":"看到【小球贴锥面随其转动，问恰好离开锥面的临界角速度或离开后某夹角下的角速度】","c":"想到【临界即锥面支持力为零：小球只受重力和绳拉力、夹角仍为锥面角，列 $mg\\tan\\theta=m\\omega_0^2 L\\sin\\theta$（即 $\\omega_0^2=g/(L\\cos\\theta)$）求临界角速度；绳夹角大于锥面角（$60^\\circ>37^\\circ$）时球已飞离锥面，仍只受两力，把 $\\theta$ 换成实际夹角重新列方程求解】；警惕【“恰好离开”时支持力为零但夹角仍是原锥面角，勿提前换角；离开后圆周半径按新夹角 $L\\sin\\theta$ 重算】","src":"跳跳物一轮04.6 传动问题、圆锥摆_笔记","note":"视频|36:39","orig":"（例）长 $L=1\\ \\mathrm{m}$ 的轻绳一端固定、另一端系小球放在圆锥面上，绳与竖直方向夹角 $37^\\circ$（$\\cos37^\\circ=0.8$），求小球恰好离开锥面时的角速度，以及绳与竖直方向夹角为 $60^\\circ$ 时的角速度。","link":""},{"id":"phy2222","t":"转弯模型·水平面转弯的向心力来源","s":"看到【汽车在水平路面转弯，问向心力来源、最大安全速度或不侧滑的条件】","c":"想到【静摩擦力提供向心力，其上限为最大静摩擦力（近似等于滑动摩擦力），最大向心力 $F=\\mu mg$；安全转弯需满足所需向心力 $mv^2/r\\leq\\mu mg$；恰不侧滑时最大向心加速度 $a=\\mu g$】；警惕【向心力是效果力不是实际受力，受力分析只画重力、支持力、摩擦力三类，不能把向心力画成第四个力】","src":"跳跳物一轮04.7 转弯模型、圆盘模型_你们催了好久的异侧圆盘模型_笔记","note":"视频|00:31","orig":"（知识）汽车在水平路面上转弯，做的是水平面内的圆周运动，向心力由地面对轮胎的静摩擦力提供。","link":""},{"id":"phy2223","t":"转弯模型·斜面完美转弯与速度偏离","s":"看到【火车或汽车在倾角 $\\theta$ 的弯道转弯，问完美转弯速度、内外轨挤压或支持力大小】","c":"想到【完美转弯条件 $mg\\tan\\theta=mv^2/R$，解得 $v=\\sqrt{gR\\tan\\theta}$，只由倾角和半径决定、与质量无关；向心加速度 $a=g\\tan\\theta$；速度偏小做向心运动、内侧车轮挤内轨，速度偏大做离心运动、外侧车轮挤外轨】；警惕【速度偏大时外轨弹力垂直于接触面、沿轨道平面斜向下而非水平方向；支持力是矢量三角形斜边、大于重力】","src":"跳跳物一轮04.7 转弯模型、圆盘模型_你们催了好久的异侧圆盘模型_笔记","note":"视频|01:59","orig":"（知识）火车在倾斜轨道上转弯：轨道倾斜但车身在水平面内做圆周运动，轮缘无侧向挤压（完美转弯）时由重力和支持力的合力提供向心力，受力本质与圆锥摆相同。","link":""},{"id":"phy2224","t":"圆盘模型·单物体的滑动临界角速度","s":"看到【物体放在转动圆盘上，问开始滑动的临界角速度或比较不同物体谁先滑动】","c":"想到【动力学方程 $f=m\\omega^2 r$；当静摩擦力达到最大值 $\\mu mg$ 时物体将滑，临界角速度 $\\omega=\\sqrt{\\mu g/r}$；离圆心越远（$r$ 越大）临界角速度越小，角速度增大时越先滑动】；警惕【摩擦力方向指向圆心（提供向心力）而非沿切线；最大静摩擦力近似按滑动摩擦力 $\\mu mg$ 计算】","src":"跳跳物一轮04.7 转弯模型、圆盘模型_你们催了好久的异侧圆盘模型_笔记","note":"视频|07:12","orig":"（知识）物体随水平圆盘一起转动，相对圆盘有向外滑动的趋势，圆盘对它的静摩擦力指向圆心并提供向心力。","link":""},{"id":"phy2225","t":"圆盘模型·连接体的两个临界角速度","s":"看到【绳连接的两物体随圆盘加速转动，问绳绷紧时刻的角速度或整体滑动临界角速度】","c":"想到【绳有力临界=远端物体的滑动临界，$\\omega_1=\\sqrt{\\mu g/R}$，$R$ 为远端物体到圆心的距离，此时远端物体被绳拉住并不真滑；一起滑临界用质心法：连接体等效为位于质心处的单物体，$\\omega_2=\\sqrt{\\mu g/r}$，$r$ 为质心到圆心的距离；质心在两物连线上，满足 $m_1L_1=m_2L_2$（质量相等时在中点），再按几何关系求出 $r$】；警惕【达到绳有力临界时远端物体并未滑动；质心到圆心距离要按同侧或异侧几何关系计算，质量不等时不能直接取中点】","src":"跳跳物一轮04.7 转弯模型、圆盘模型_你们催了好久的异侧圆盘模型_笔记","note":"视频|11:18-14:00","orig":"（知识）两物体用绳连接放在圆盘上（可分居圆心同侧或异侧），存在两个临界角速度：绳开始绷紧有力的临界与连接体整体开始滑动的临界。","link":""},{"id":"phy2226","t":"圆盘模型·异侧连接体阶段二的大减小法","s":"看到【绳连接两物体随圆盘加速转动，问绳绷紧到一起滑动前各物体摩擦力变化】","c":"想到【对两物体分别列 $T\\pm f=m\\omega^2 r$，两式用大减小相减消去绳力，得 $f_A-f_B=(m_A r_A-m_B r_B)\\omega^2$（或相反）；随 $\\omega$ 增大差值增大：已达到最大静摩擦的保持不变，另一个先减小到零、再反向（背离圆心）增大至最大静摩擦，两者均达最大时连接体即将一起滑动】；警惕【异侧两物体所需摩擦力方向一个指向圆心一个背离，列方程正负号按各自方向定；反向阶段摩擦力方向已发生突变】","src":"跳跳物一轮04.7 转弯模型、圆盘模型_你们催了好久的异侧圆盘模型_笔记","note":"视频|18:42","orig":"（知识）圆盘上绳连接的两物体（如分居圆心异侧）绳绷紧后，随角速度继续增大，需分析两物体静摩擦力的变化过程。","link":""},{"id":"phy2227","t":"转弯模型·火车斜面转弯选项判定","s":"看到【火车在倾斜轨道转弯，选项比较支持力与重力、分析内外轨挤压及外轨弹力方向】","c":"想到【合力水平指向圆心，力的矢量三角形中支持力是斜边，故支持力大于重力；速度小于完美速度做向心运动挤内轨、大于则挤外轨，恰好等于时对轨道无侧向挤压；完美速度 $v=\\sqrt{gR\\tan\\theta}$ 只由倾角和半径决定，乘客增多不变；外轨弹力垂直于接触面、沿轨道平面斜向下】；警惕【并非速度越小越安全；外轨弹力方向误判为水平是常见错误】","src":"跳跳物一轮04.7 转弯模型、圆盘模型_你们催了好久的异侧圆盘模型_笔记","note":"视频|30:03","orig":"（例）火车在倾角 $\\theta$ 的轨道上转弯，选项涉及：支持力与重力的大小关系、车速对轮轨挤压的影响、乘客增多时完美速度是否变化、车速偏大时外轨对车轮轮缘弹力的方向。","link":""},{"id":"phy2228","t":"圆盘模型·连接体临界与绳力计算","s":"看到【绳连接两物体随圆盘转动，求整体滑动临界角速度、绳最大弹力或某角速度下各力】","c":"想到【整体滑动临界用质心法：质量相等质心在连线中点，按几何关系求质心到圆心距离 $r$，得 $\\omega_2=\\sqrt{\\mu g/r}$；绳最大弹力出现在即将整体滑动时，对已达最大静摩擦的物体列 $T\\pm\\mu mg=m\\omega^2 r$ 解出 $T$；任意角速度先与两个临界比较，判断绳是否有力、是否滑动，再对单体列方程求绳力与摩擦力】；警惕【绳力方向按拉向圆心还是拉离圆心区分正负；摩擦力可能反向，列方程前先定方向】","src":"跳跳物一轮04.7 转弯模型、圆盘模型_你们催了好久的异侧圆盘模型_笔记","note":"视频|33:06","orig":"（例）水平圆盘上质量相等的 A、B 两物体用轻绳连接，A 距圆心 $L$、B 距圆心 $2L$（同侧），随圆盘一起转动，问整体开始滑动的临界角速度、绳的最大弹力及给定角速度下的绳力与摩擦力。","link":""},{"id":"phy2229","t":"圆盘模型·连接体摩擦力图线问题","s":"看到【连接体圆盘配摩擦力—角速度图线，图线先后达到水平平台，问对应物体与临界点】","c":"想到【先达到水平平台（最大静摩擦）的图线对应远端物体；绳有力临界 $\\omega_1$ 即远端物体的滑动临界；把特征点的摩擦力取值（最大静摩擦、零等）代入阶段二差值方程 $f_a-f_b=(m r_a-m r_b)\\omega^2$ 解出各特征角速度；绳张力对单个物体列 $T\\pm f=m\\omega^2 r$，可与图线读数联立求解】；警惕【近端物体摩擦力经历先增大、再减到零、后反向增大的完整过程，读图勿漏反向段；特征角速度间不一定成简单整数比】","src":"跳跳物一轮04.7 转弯模型、圆盘模型_你们催了好久的异侧圆盘模型_笔记","note":"视频|43:34","orig":"（例）圆盘上圆心同侧的 a、b 两物体（b 在远端）用细线连接随盘缓慢加速，给出两物体所受摩擦力随角速度变化的图线，问图线与物体的对应关系、各特征角速度及绳中张力。","link":""},{"id":"phy2230","t":"竖直圆·向心力两步法","s":"看到【竖直圆某位置求向心力或弹力，各力沿半径方向有指向和背离圆心两类】","c":"想到【两步法：第一步受力分析，把各力分为指心力（指向圆心）与背心力（背离圆心）；第二步向心力=指心力−背心力，如最低点向心力=$T-mg$（弹力指心、重力背心）】；警惕【合力必指向圆心，故指心力必大于背心力，方程两边方向写反会差一个符号】","src":"跳跳物一轮04.8 竖直圆模型_曲线运动完结撒花~_笔记","note":"视频|00:32","orig":"（知识）竖直圆中向心力是沿半径方向的合力，计算分两步：先受力分析，再求沿半径方向的合力。","link":""},{"id":"phy2231","t":"竖直圆·最低点统一方程","s":"看到【小球或汽车在竖直圆（凹形桥）最低点，求支持力、拉力或向心力】","c":"想到【最低点弹力竖直向上为指心力、重力背向圆心，统一方程 $T-mg=mv^2/R$，即 $T=mg+mv^2/R$ 恒大于重力（超重）；如凹形桥最低点车对桥压力大于重力，桥面更易损坏】；警惕【最低点弹力必大于重力，勿与拱桥最高点支持力小于重力混淆；各模型最低点方程相同，勿按模型分别记忆】","src":"跳跳物一轮04.8 竖直圆模型_曲线运动完结撒花~_笔记","note":"视频|03:34","orig":"（知识）竖直圆所有模型（绳、杆、圆弧轨道、管道）在最低点的动力学方程完全相同。","link":""},{"id":"phy2232","t":"竖直圆·绳模型最高点临界","s":"看到【绳系小球（或圆弧轨道内侧、水流星）在竖直面内做完整圆周运动，问最高点临界速度或拉力】","c":"想到【最高点方程 $T+mg=mv^2/R$；$T$ 最小为 0，此时重力完全提供向心力，得最小速度 $v_{\\min}=\\sqrt{gR}$，只要能到达最高点速度就不低于它、不可能为 0（最高点仍有水平分速度）；速度越大绳拉力越大】；警惕【最高点速度小于 $\\sqrt{gR}$ 就到不了最高点（中途脱离改做抛体运动），不是减速勉强通过】","src":"跳跳物一轮04.8 竖直圆模型_曲线运动完结撒花~_笔记","note":"视频|04:43","orig":"（知识）绳模型：绳子是软的，最高点弹力只能指向圆心（只能拉不能顶）；小球在圆弧轨道内侧运动到最高点时轨道弹力也只能指向圆心，与绳模型完全等效。","link":""},{"id":"phy2233","t":"竖直圆·拱桥模型最高点","s":"看到【汽车过拱形桥顶（或只压不拉的支撑面），问最高点速度限制或不脱离条件】","c":"想到【最高点方程 $mg-T=mv^2/R$；速度可减小到 0（此时 $T=mg$）；$T$ 最小为 0 时恰好脱离桥面，对应最大安全速度 $v_{\\max}=\\sqrt{gR}$，超过则车做离心运动飞离桥面】；警惕【拱桥最高点支持力小于重力（失重），与凹形桥最低点相反；速度超过 $\\sqrt{gR}$ 后车脱离桥面做抛体运动，不再是圆周】","src":"跳跳物一轮04.8 竖直圆模型_曲线运动完结撒花~_笔记","note":"视频|09:32","orig":"（知识）拱桥模型：桥面只能顶不能拉，最高点弹力只能背向圆心，受力特点与绳模型相反。","link":""},{"id":"phy2234","t":"竖直圆·杆与管道模型最高点分类","s":"看到【轻杆带球、穿在圆环或光滑管道中的小球过竖直圆最高点，问弹力方向或速度范围】","c":"想到【按速度分情况：$v^2/R>g$ 时所需向心力大于重力，弹力指向圆心，方程 $mg+T=mv^2/R$（等效绳模型）；$v^2/R<g$ 时弹力背向圆心，方程 $mg-T=mv^2/R$（等效拱桥）；恰有 $mg=mv^2/R$ 时弹力为零（完全失重）；最高点最小速度为 0】；警惕【杆和管道最高点速度可为零，不能套用绳模型的 $\\sqrt{gR}$ 作最小速度；弹力方向先由速度与临界值比较判定再列方程，勿默认方向】","src":"跳跳物一轮04.8 竖直圆模型_曲线运动完结撒花~_笔记","note":"视频|12:30","orig":"（知识）杆模型（硬杆、圆环穿小球、管道）弹力既能指向圆心（拉）也能背向圆心（顶），是绳模型与拱桥模型的综合；管道内壁弹力背向圆心、外壁弹力指向圆心。","link":""},{"id":"phy2235","t":"圆周运动·易错概念辨析","s":"看到【判断完全失重、离心力、脱水桶甩水、水流星、车对桥压力等说法正误】","c":"想到【完全失重指只受重力（如水流星最高点满足 $mv^2/R=mg$ 时），不是不受重力；脱水桶原理是需要的向心力大于提供的力（粘滞力），水滴做离心运动沿切线甩出，高中凡出现“离心力”的说法直接判错；求车对桥的力先以车为对象求桥对车的力，再经牛顿第三定律转换】；警惕【“不受重力”“受离心力”两种表述都是错的；大题求相互作用力必须经牛顿第三定律说明，不能直接以桥为对象】","src":"跳跳物一轮04.8 竖直圆模型_曲线运动完结撒花~_笔记","note":"视频|33:59","orig":"（知识）圆周运动常见概念辨析：完全失重、离心运动、相互作用力的研究对象转换。","link":""},{"id":"phy2236","t":"竖直圆·绳模型多过程综合","s":"看到【绳系小球恰好过最高点、最低点绳断后接平抛的多过程问题，求各阶段速度与落点】","c":"想到【恰好过最高点：绳力为零，列 $mg=mv^2/L$ 得 $v=\\sqrt{gL}$；最低点用 $T-mg=v'^2/L$，代入 $T=9mg$ 解出 $v'$；绳断后小球以 $v'$ 平抛：下落高度=手离地高度−绳长，由 $h=\\frac{1}{2}gt^2$ 求 $t$，水平距离 $x=v't$ 联立求解】；警惕【最低点与最高点方程不同（指心力、背心力互换）；平抛下落高度不是绳长也不是离地高度，要按几何关系重算】","src":"跳跳物一轮04.8 竖直圆模型_曲线运动完结撒花~_笔记","note":"视频|15:38","orig":"（例）长 $L$ 的轻绳一端系小球，第一次恰好能完成完整竖直圆周运动；第二次在最低点绳断（断前拉力达 $9mg$），手握端离地高 $2L$，求最高点最小速度、绳断时速度及断后平抛的水平距离。","link":""},{"id":"phy2237","t":"竖直圆·杆模型弹力—速度平方图像","s":"看到【杆（管道）模型配 $F_N$—$v^2$ 图像，图像经过零点后继续变化，求质量、g 或弹力】","c":"想到【分段列方程：低速段弹力背向圆心，$mg-F_N=mv^2/R$（支持力）；$F_N=0$ 处满足 $mg=mv^2/R$（完全失重点）；高速段 $mg+F_N=mv^2/R$（向下拉）。读图：$v^2=0$ 处 $F_N=mg$ 得 $mg=a$，零弹力点得 $g=ab/R$，联立求出质量；利用图像对称性可快速取弹力值】；警惕【先看清纵坐标是弹力大小还是带方向的代数值；两段斜率同为 $m/R$ 但方程形式不同，勿混用】","src":"跳跳物一轮04.8 竖直圆模型_曲线运动完结撒花~_笔记","note":"视频|18:40","orig":"（例）竖直圆杆模型小球在最高点，给出弹力 $F_N$ 随 $v^2$ 变化的图像（$v^2=0$ 时 $F_N=a$，$v^2=b$ 时 $F_N=0$，之后随 $v^2$ 线性增大），求小球质量、重力加速度及某速度下弹力的大小方向。","link":""},{"id":"phy2238","t":"万有引力与航天·开普勒第一定律与圆化默认","s":"看到【题目问行星轨道形状或太阳的位置，或未说明椭圆时按什么模型处理】","c":"想到【所有行星绕太阳运动的轨道都是椭圆，太阳位于椭圆的一个焦点上；高中无特殊说明时默认简化为匀速圆周运动，中心天体位于圆心】；警惕【题目明确提到椭圆运动（如近日点、远日点）时不能再按圆轨道处理，此时太阳在焦点而不在圆心】","src":"跳跳物一轮05.1 开普勒三定律、万有引力定律_笔记","note":"视频|01:19","orig":"（知识）行星绕太阳运动的轨道形状、太阳的位置，以及高中阶段的默认处理方式。","link":""},{"id":"phy2239","t":"万有引力与航天·开普勒第二定律近日远日速率","s":"看到【行星沿椭圆轨道运动，比较近日点、远日点速度大小或判断加速、减速过程】","c":"想到【行星与太阳的连线在相等时间内扫过的面积相等；近日点速度最大，远日点速度最小；从远日点向近日点做加速运动，从近日点向远日点做减速运动】；警惕【两点速度大小说反；选项称离太阳近处速度小、或远日点还在加速，均为错误说法】","src":"跳跳物一轮05.1 开普勒三定律、万有引力定律_笔记","note":"视频|02:03","orig":"（知识）开普勒第二定律（面积定律）的内容与行星在椭圆轨道上的速率变化。","link":""},{"id":"phy2240","t":"万有引力与航天·开普勒第三定律k的性质与质量比","s":"看到【用$\\frac{a^3}{T^2}=K$比较不同环绕体，或由两环绕体数据求中心天体质量之比】","c":"想到【$k=\\frac{a^3}{T^2}$，圆轨道时$a$取半径$r$，一个圆轨道与一个椭圆轨道混用依然成立；$k$只与中心天体有关、与中心天体质量成正比（$k\\propto M$），与环绕体无关；中心天体质量之比=$k$之比，周期相同时即=半长轴三次方之比】；警惕【$k$不同的两环绕体绕的是不同中心天体，不能直接用开三律比较；误认为$k$与环绕体质量有关】","src":"跳跳物一轮05.1 开普勒三定律、万有引力定律_笔记","note":"视频|03:24","orig":"（知识）开普勒第三定律（周期定律）中常量$k$的性质、中心天体质量比求法与适用前提。","link":""},{"id":"phy2241","t":"万有引力与航天·万有引力公式适用条件与r取值","s":"看到【用万有引力公式计算两物体（含球体）间的引力，或问距离$r$应取什么】","c":"想到【公式仅适用于两质点、两质量均匀的球体、一个质点与一个匀质球三种情况；两匀质球的$r$取球心间距而非表面距离；算星球表面物体所受引力时$r$取星球半径；中心天体默认匀质球、环绕体默认质点；两物体间的引力是一对相互作用力，等大反向】；警惕【不满足条件不代表没有引力，只是不能用该公式计算；$r$误取成两球表面间距】","src":"跳跳物一轮05.1 开普勒三定律、万有引力定律_笔记","note":"视频|10:53","orig":"（知识）用$F=\\frac{Gm_1m_2}{r^2}$计算万有引力时的适用条件与距离$r$的取法。","link":""},{"id":"phy2242","t":"万有引力与航天·椭圆轨道上加速度与引力随r变化","s":"看到【行星沿椭圆轨道绕太阳运动，问各点加速度、引力大小如何变化或引力是否等大】","c":"想到【行星只受太阳万有引力，由牛顿第二定律$F=ma$与万有引力公式得$a=\\frac{GM}{r^2}$，$r$越大加速度越小：近日点速度、加速度、引力均最大，远日点均最小；运动中$r$不断变化，引力大小随之变化；太阳与火星间的引力是一对相互作用力，等大反向】；警惕【认为运动中引力大小不变；把太阳与行星间的相互作用力当成不等大的两个力】","src":"跳跳物一轮05.1 开普勒三定律、万有引力定律_笔记","note":"视频|15:34","orig":"（例）火星绕太阳沿椭圆轨道运动，选项判断：近日点与远日点的线速度大小、运动过程中太阳对火星的引力是否变化、远日点的加速度是否最小、太阳与火星间的引力是否等大。","link":""},{"id":"phy2243","t":"万有引力与航天·万有引力物理学史人物分工","s":"看到【物理学史题问行星运动定律的得出者、万有引力定律的发现方式或$G$的测量者】","c":"想到【第谷只观察不计算（负责观测记录数据）；开普勒只计算不观察（用第谷数据算出椭圆轨道）；牛顿在开普勒三定律基础上理论推导出万有引力定律，并做月地检验（比较月球绕地向心加速度与地表重力加速度）；卡文迪许用扭秤实验（铅球）首次测出引力常量$G$】；警惕【第谷做计算、开普勒做观测、卡文迪许发现定律均为张冠李戴；月地检验当时没有近地卫星，定律也不是由实验得出】","src":"跳跳物一轮05.1 开普勒三定律、万有引力定律_笔记","note":"视频|18:51","orig":"（知识）第谷、开普勒、牛顿、卡文迪许在行星运动与万有引力研究中的分工与易混点。","link":""},{"id":"phy2244","t":"万有引力与航天·不计自转时重力等于万有引力","s":"看到【不计地球自转，同一物体在地表与离地$h$高处的重力（引力）数值均已知，求高度$h$】","c":"想到【不计自转时重力=万有引力；对地表与高空分别列$\\frac{GMm}{R^2}$与$\\frac{GMm}{(R+h)^2}$，两式相除整体消去$GMm$，得$R^2/(R+h)^2$等于高空与地表两力之比，解得$h\\approx 1593$ km】；警惕【不整体相除而硬算$GMm$的具体值；题目考虑自转时重力只是万有引力的一个分力，不能再令$mg=\\frac{GMm}{R^2}$】","src":"跳跳物一轮05.1 开普勒三定律、万有引力定律_笔记","note":"视频|22:56","orig":"（例）太空电梯问题：质量2.5 kg的物体在地面受重力25 N（$g$取10 m/s$^2$），随电梯升到离地高度$h$处时受地球引力变为16 N，地球半径$R=6371$ km，不计地球自转，求$h$。","link":""},{"id":"phy2245","t":"万有引力与航天·自转可忽略时重力等于万有引力","s":"看到【物体在空中（环绕或自由下落），或题目未提及赤道、两极、自转】","c":"想到【重力就是万有引力，重力加速度=引力加速度；天上物体只受万有引力（指向球心），重力与万有引力无区别；星球表面静置物体受万有引力与支持力二力平衡，重力=万有引力=支持力】；警惕【题目专门提到赤道、两极或自转不可忽略时本结论失效，重力只是万有引力的分力】","src":"跳跳物一轮05.2 万有引力定律三小题型_笔记","note":"视频|00:53","orig":"（知识）万有引力与重力关系的情况一：物体在天上，或星球表面且自转可忽略。","link":""},{"id":"phy2246","t":"万有引力与航天·自转不可忽略时重力是万有引力分力","s":"看到【物体在星球表面，且题目提到赤道、两极或明确自转不可忽略】","c":"想到【重力是万有引力的一个分力，另一个分力提供物体随星球自转的向心力；重力方向竖直向下、不指向地心；物体实际受万有引力、支持力、静摩擦力三个力；无论自转能否忽略，重力始终等于支持力（二者合力远小于重力，可忽略）】；警惕【认为自转不可忽略时重力仍指向地心，或认为此时重力不等于支持力】","src":"跳跳物一轮05.2 万有引力定律三小题型_笔记","note":"视频|03:21","orig":"（知识）万有引力与重力关系的情况二：星球表面且自转不可忽略。","link":""},{"id":"phy2247","t":"万有引力与航天·赤道两极方程与g大小比较","s":"看到【物体随星球自转，在赤道或两极处求重力、重力加速度或比较大小】","c":"想到【赤道方程：万有引力=重力+向心力，即$\\frac{GMm}{R^2}=mg+m\\omega^2 R$（g为赤道重力加速度），引力、重力、向心力均指向地心；两极方程：$\\frac{GMm}{R^2}=mg$（g为两极重力加速度，极点无需向心力）；故两极重力加速度大于赤道重力加速度，口诀北大南大】；警惕【两极也套引=重+向心（极点向心力为零）；认为赤道重力加速度更大】","src":"跳跳物一轮05.2 万有引力定律三小题型_笔记","note":"视频|09:23","orig":"（知识）物体随星球自转时赤道与两极处的动力学方程，及两处重力加速度大小比较。","link":""},{"id":"phy2248","t":"万有引力与航天·球壳推论与星球内部引力计算","s":"看到【物体位于星球内部（井下、深海等），求引力或重力加速度与地表之比】","c":"想到【质量均匀的球壳对内部任意位置物体的万有引力合力为零（球壳推论，高中可直接用）；从物体位置把星球切开，只算内部实心球的引力：物体在内部球表面，$r$=内部球半径，内部球质量按半径三次方缩比；深度$d$处重力加速度=$\\frac{g(R-d)}{R}$，高空$h$处=$\\frac{gR^2}{(R+h)^2}$】；警惕【外部球壳的引力也计入；仍用星球总质量或误取$r$为到球面的距离】","src":"跳跳物一轮05.2 万有引力定律三小题型_笔记","note":"视频|13:16","orig":"（知识）计算星球内部某深度处物体所受万有引力（或重力加速度）的方法。","link":""},{"id":"phy2249","t":"万有引力与航天·填补法计算挖球剩余部分引力","s":"看到【匀质大球挖去小球，求剩余不规则部分对某质点的万有引力】","c":"想到【把挖掉的小球补回成完整匀质大球，剩余部分引力=完整大球引力−补回小球引力；挖去部分质量按体积比（半径三次方比）缩比；若在空洞中改填其他密度的物质，再按剩余引力+新填球引力求总引力】；警惕【只有质点在大、小球球心连线上三个力才共线、才能直接相加减；质点不在连线上时必须用平行四边形定则合成】","src":"跳跳物一轮05.2 万有引力定律三小题型_笔记","note":"视频|16:15","orig":"（知识）匀质大球挖去小球后，剩余不规则部分对质点引力的计算方法（填补凑整思想）。","link":""},{"id":"phy2250","t":"万有引力与航天·极赤问题求自转角速度","s":"看到【已知两极与赤道处重力（或重力加速度）的比例关系，求自转角速度】","c":"想到【两极处万有引力完全充当重力，赤道处万有引力=重力+向心力；设赤道重力加速度为$g$，则两极为1.2$g$：$\\frac{GM}{R^2}=1.2g$与$\\frac{GM}{R^2}=g+\\omega^2 R$联立，得$0.2g=\\omega^2 R$，解得$\\omega=\\sqrt{\\frac{GM}{6R^3}}$】；警惕【赤道方程漏掉$\\omega^2 R$项或给两极也加向心力；不先由两极方程消元而硬算$G$】","src":"跳跳物一轮05.2 万有引力定律三小题型_笔记","note":"视频|20:30","orig":"（例）某行星质量$M$、半径$R$，测得物体在两极处所受重力是赤道处的1.2倍，求行星自转角速度$\\omega$。","link":""},{"id":"phy2251","t":"万有引力与航天·自转加快压力变化求星球密度","s":"看到【自转变化使赤道压力（视重）变为原来的某比例，求星球密度】","c":"想到【自转可忽略时万有引力=重力，$\\frac{GM}{R^2}=g$；角速度$\\omega$时赤道方程$\\frac{GM}{R^2}=\\frac{2}{3}g+\\omega^2 R$；联立消去$g$得$M=\\frac{3\\omega^2R^3}{G}$，密度$\\rho=\\frac{M}{4\\pi R^3/3}=\\frac{9\\omega^2}{4\\pi G}$，只与$\\omega$有关】；警惕【认为密度还与半径$R$有关（此结论$\\rho$只由$\\omega$决定）；联立时把重力比例式代错】","src":"跳跳物一轮05.2 万有引力定律三小题型_笔记","note":"视频|22:34","orig":"（例）星球自转角速度增大到$\\omega$时，赤道处物体对地面的压力减为自转可忽略时的2/3，已知星球半径$R$，求星球密度$\\rho$。","link":""},{"id":"phy2252","t":"万有引力与航天·填补法挖球与改填密度实例","s":"看到【挖去内切小球后求剩余部分对球心连线上质点的引力，或重新填充后求总引力】","c":"想到【补全凑整：剩余引力=完整大球引力−补回小球引力；小球质量=$M/8$（半径减半体积为1/8），质点到小球球心距离=$2R-R/2=\\frac{3R}{2}$；$\\frac{GMm}{4R^2}-\\frac{GMm}{18R^2}=\\frac{7GMm}{36R^2}$；填充密度2倍物质后总引力再加$\\frac{4GMm}{36R^2}$，得$\\frac{11GMm}{36R^2}$】；警惕【计算补回小球的引力时质点距离仍用$2R$（应到小球球心$\\frac{3R}{2}$）；质量缩比忘记按体积即半径三次方】","src":"跳跳物一轮05.2 万有引力定律三小题型_笔记","note":"视频|30:07","orig":"（例）匀质大球质量$M$、半径$R$，内部挖去半径$R/2$的小球（球心在大球与小球球心连线上、内部相切），球心连线上距大球球心$2R$处放质量$m$的质点。求剩余部分对质点的引力；若在空洞处填入密度为原来2倍的同体积物质，求整体对质点的引力。","link":""},{"id":"phy2253","t":"万有引力与航天·环绕模型注意事项","s":"看到【卫星/环绕体绕中心天体做圆轨道运动，确定轨道半径、圆心或参考系】","c":"想到【只要轨道是圆就一定是匀速圆周运动，速度大小若变化则轨道必为椭圆；圆心是中心天体的球心；轨道半径=环绕体到中心天体球心的距离（中心天体尺寸大不能视为质点，必须取球心距），环绕体可视为质点；研究时一律以中心天体为参考系、认为它静止】；警惕【轨道半径误取成到中心天体表面的距离；把中心天体也当质点处理】","src":"跳跳物一轮05.3 环绕模型、卫星比较问题、可求解问题_笔记","note":"视频|01:58","orig":"（知识）环绕模型（卫星绕中心天体匀速圆周运动）的三条注意事项。","link":""},{"id":"phy2254","t":"万有引力与航天·环绕模型核心方程","s":"看到【卫星环绕中心天体，列方程求线速度、角速度、周期或加速度】","c":"想到【万有引力=向心力：$\\frac{GMm}{r^2}=mg=ma=\\frac{mv^2}{r}=m\\omega^2 r=m\\frac{4\\pi^2 r}{T^2}$；环绕体质量$m$会被约去；周期形式$\\frac{GMm}{r^2}=m\\frac{4\\pi^2 r}{T^2}$最常用、必须熟练默写；由周期形式可导出中心天体质量$M=\\frac{4\\pi^2 r^3}{GT^2}$】；警惕【已知周期$T$却选$v^2/r$形式绕远路；忘记$m$可约去而认为环绕体质量影响环绕参量】","src":"跳跳物一轮05.3 环绕模型、卫星比较问题、可求解问题_笔记","note":"视频|03:50","orig":"（知识）环绕模型核心方程：万有引力（或重力）提供向心力的各形式。","link":""},{"id":"phy2255","t":"万有引力与航天·高轨低速大周期口诀","s":"看到【同一中心天体的两颗卫星或行星比较$v$、$\\omega$、$a$、$T$大小，含用季节时长换周期的信息】","c":"想到【高轨低速大周期：轨道半径$r$越大，$v$、$\\omega$、$a$都越小，$T$越大；比例$v\\propto 1/\\sqrt{r}$、$\\omega\\propto 1/\\sqrt{r^3}$、$a\\propto 1/r^2$、$T\\propto \\sqrt{r^3}$；题给四季时长等比例先换算成周期比再用口诀；口诀仅适用于中心天体相同且都做匀速圆周运动的两颗卫星】；警惕【不同中心天体、或一颗圆轨道一颗椭圆轨道时口诀失效；由季节时长换周期比时弄反大小关系】","src":"跳跳物一轮05.3 环绕模型、卫星比较问题、可求解问题_笔记","note":"视频|06:15-07:52","orig":"（知识）同一中心天体的两颗卫星各量随轨道半径的变化规律（高轨低速大周期）及口诀适用条件。","link":""},{"id":"phy2256","t":"万有引力与航天·知二求所有","s":"看到【题给环绕模型两个及以上已知量，问能求出哪些量（可求解问题）】","c":"想到【$r$、$M$、$a$、$v$、$\\omega$、$T$六个量中已知任意两个即可求出其余所有（$\\omega$与$T$只算一个，$\\omega=2\\pi/T$）；$M$是中心天体质量，环绕体质量$m$在方程中被约去、已知无用；$r$是轨道半径而非中心天体的星球半径；已知表面重力加速度$g$和星球半径$R$相当于已知$M$（黄金代换$GM=gR^2$）】；警惕【凡含环绕体质量$m$的量（万有引力、动能、卫星自身密度）在$m$未知时不可求；误把星球半径当轨道半径】","src":"跳跳物一轮05.3 环绕模型、卫星比较问题、可求解问题_笔记","note":"视频|11:27","orig":"（知识）环绕模型中各物理量之间的'知二求所有'规则与注意点。","link":""},{"id":"phy2257","t":"万有引力与航天·空间站环绕计算（距地高度+周期）","s":"看到【卫星距地面高度$h$、周期$T$已知，求线速度、地球质量、表面重力加速度或向心加速度】","c":"想到【轨道半径$r=h+R_0$；线速度$v=\\frac{2\\pi(h+R_0)}{T}$；由万有引力=向心力得地球质量$M=\\frac{4\\pi^2(h+R_0)^3}{GT^2}$；忽略自转时地表$\\frac{GMm}{R_0^2}=mg_0$，代入$M$得$g_0=\\frac{4\\pi^2(h+R_0)^3}{T^2R_0^2}$；向心加速度$a=\\frac{4\\pi^2(h+R_0)}{T^2}$】；警惕【轨道半径写成$R_0$漏掉$+h$；质量表达式分母漏写$G$；向心加速度分子多写平方；表面重力加速度与轨道处加速度混用】","src":"跳跳物一轮05.3 环绕模型、卫星比较问题、可求解问题_笔记","note":"视频|13:07","orig":"（例）空间站在距地面高度$h$处绕地球做匀速圆周运动，周期为$T$，地球半径为$R_0$，引力常量为$G$。求空间站线速度、地球质量、地球表面重力加速度、空间站向心加速度。","link":""},{"id":"phy2258","t":"万有引力与航天·不同中心天体环绕方程相除","s":"看到【两个环绕体绕不同中心天体运动，比较或求轨道半径、中心天体质量之比】","c":"想到【对两个环绕模型分别列周期形式方程后两式相除：$\\frac{GM}{r^2}=\\frac{4\\pi^2 r}{T^2}$给出$r^3\\propto MT^2$（同一中心天体时即$r\\propto T^{2/3}$）；代入地球质量$10M$、飞船周期$2T$得$R_1/R_2=\\sqrt[3]{\\frac{M(2T)^2}{10MT^2}}=\\sqrt[3]{\\frac{2}{5}}$】；警惕【被椭圆轨道等无关信息干扰；两式相除时中心天体质量与周期的对应关系弄反】","src":"跳跳物一轮05.3 环绕模型、卫星比较问题、可求解问题_笔记","note":"视频|22:54","orig":"（例）某飞船绕火星做匀速圆周运动，周期为2个火星日（设为$2T$）；地球同步卫星绕地球做匀速圆周运动，周期为1个地球日（$T$）；地球质量是火星的10倍（设火星质量为$M$，题干中'沿椭圆轨道飞行'为干扰信息）。求飞船轨道半径$R_1$与同步卫星轨道半径$R_2$之比。","link":""},{"id":"phy2259","t":"万有引力与航天·同轨卫星与向心力比较","s":"看到【同一中心天体的多颗卫星比较周期、速度、加速度，其中有轨道半径相同的两颗】","c":"想到【高轨低速大周期：轨道最高的c周期最大、向心加速度最小；轨道半径相同的a、b线速度大小一定相等；向心力$F=\\frac{GMm}{r^2}$的大小还与卫星质量$m$有关，质量未知时向心力无法比较】；警惕【认为同轨道的两颗卫星向心力也相等；误判轨道高的卫星周期小】","src":"跳跳物一轮05.3 环绕模型、卫星比较问题、可求解问题_笔记","note":"视频|28:16","orig":"（例）三颗卫星a、b、c绕地球做匀速圆周运动，轨道半径$R_A=R_B<R_C$。判断：周期$T_C$与$T_A$、$T_B$的大小；卫星a、b的向心力能否比较；$v_A$与$v_B$的大小；向心加速度$a_C$与$a_A$、$a_B$的大小。","link":""},{"id":"phy2260","t":"万有引力与航天·黄金代换求中心天体质量与密度","s":"看到【已知星球半径与表面重力加速度（忽略自转），问能求出哪些量】","c":"想到【忽略自转时星球表面重力=万有引力，黄金代换$GM=gR^2$，可解出中心天体质量$M=\\frac{gR^2}{G}$；平均密度$\\rho=\\frac{3g}{4\\pi GR}$；但空间站轨道半径未知，其线速度和周期无法求出】；警惕【黄金代换要求忽略自转且物体在星球表面；已知中心天体量但不知轨道半径时误认为能求卫星的速度和周期】","src":"跳跳物一轮05.3 环绕模型、卫星比较问题、可求解问题_笔记","note":"视频|31:46","orig":"（例）已知地球半径$R$、地球表面重力加速度$g$、引力常量$G$（忽略地球自转），空间站绕地球运行。判断：能否求出地球质量、地球平均密度、空间站线速度、空间站周期。","link":""},{"id":"phy2261","t":"万有引力与航天·极赤问题与环绕模型的区分","s":"看到【物体放在星球表面且不能忽略自转（给两极、赤道两处重力加速度）】","c":"想到【极赤问题中重力是万有引力的分力：两极$\\frac{GMm}{R^2}=mg_0$，赤道$\\frac{GMm}{R^2}=m\\cdot\\frac{4\\pi^2}{T^2}R+mg_1$（引力=向心力+重力）；环绕模型中物体做圆周运动，重力就是万有引力，直接用环绕方程+黄金代换】；警惕【把表面赤道物体当成环绕模型令万有引力=重力，或反过来漏掉自转向心力】","src":"跳跳物一轮05.4 环绕模型含g问题_祝大家七夕快乐~~_笔记","note":"视频|00:38-00:57","orig":"（知识）物体放在星球表面（不忽略自转）与作为环绕体在天上飞行时，重力与万有引力的关系不同。","link":""},{"id":"phy2262","t":"万有引力与航天·黄金代换的由来与含义","s":"看到【环绕模型题不给中心天体质量M，只给表面重力加速度g和星球半径R】","c":"想到【对地表附近的环绕体列$\\frac{GMm}{R^2}=mg$，得$GM=gR^2$，用它整体替换所有方程中的GM；“地表附近”指轨道高度远小于星球半径，轨道半径$\\approx$星球半径R；被代换掉的是中心天体质量M】；警惕【题目给的g不一定是地表附近的，先确认g的位置再选择代换半径】","src":"跳跳物一轮05.4 环绕模型含g问题_祝大家七夕快乐~~_笔记","note":"视频|01:29","orig":"（知识）环绕模型题目通常不直接给中心天体质量M，黄金代换用表面重力加速度g和星球半径R消去M。","link":""},{"id":"phy2263","t":"万有引力与航天·黄金代换中g的位置","s":"看到【题目给的重力加速度标注“距地心R'处”或某高度处，而非星球表面】","c":"想到【地表g用星球半径R：$GM=gR^2$；高空g用该点到地心的距离r：$GM=gr^2$；环绕模型中重力就是万有引力，g既是重力加速度也是引力加速度】；警惕【拿到g就写$gR^2$，半径张冠李戴；务必先看清g是地表还是高空处的】","src":"跳跳物一轮05.4 环绕模型含g问题_祝大家七夕快乐~~_笔记","note":"视频|03:28","orig":"（知识）黄金代换中g的取值位置决定方程该用哪个半径。","link":""},{"id":"phy2264","t":"万有引力与航天·黄金代换求卫星周期","s":"看到【已知星球半径、卫星轨道半径和地表g求卫星周期T，中心天体质量未给】","c":"想到【对卫星列环绕方程$\\frac{GMm}{r^2}=m\\cdot\\frac{4\\pi^2}{T^2}r$，对地表环绕体列$\\frac{GMm}{R^2}=mg$得$GM=gR^2$，联立解得$T=2\\pi\\sqrt{\\frac{r^3}{gR^2}}$；两个方程中的环绕体质量m都可约掉，可用同一字母表示】；警惕【r来自卫星轨道半径、R来自黄金代换中地表环绕体的半径，混淆两者导致结果错】","src":"跳跳物一轮05.4 环绕模型含g问题_祝大家七夕快乐~~_笔记","note":"视频|04:49","orig":"（例）已知地球半径R、卫星轨道半径r、地表重力加速度g，中心天体质量M未知，求卫星周期T。","link":""},{"id":"phy2265","t":"万有引力与航天·中心天体质量与密度三步法","s":"看到【给环绕体运动参数（v、$\\omega$、T）或天体表面g，求中心天体质量M或密度$\\rho$】","c":"想到【三步法：①用环绕方程或黄金代换求M；②天体视为球体，$V=\\frac{4}{3}\\pi R^3$；③$\\rho=M/V$；贴面环绕（轨道半径=天体半径R）时$\\rho=\\frac{3\\pi}{GT^2}$，密度只由周期决定；求法不唯一时观察选项表达式含g还是T来选路径】；警惕【体积公式中的R是中心天体半径，误用环绕体轨道半径r】","src":"跳跳物一轮05.4 环绕模型含g问题_祝大家七夕快乐~~_笔记","note":"视频|09:32","orig":"（知识）已知环绕体的v、$\\omega$、T或天体表面g，求中心天体质量M或密度$\\rho$的通用流程。","link":""},{"id":"phy2266","t":"万有引力与航天·天体表面附近的抛体问题","s":"看到【物体在星球表面附近竖直上抛或平抛，题目强调h远小于星球半径R】","c":"想到【“表面附近”两层含义：①忽略物体到表面的高度；②g恒定取表面值；抛体公式与地球上的完全相同，唯一区别是g不是已知量，需先由已知运动（如$v_0^2=2gh$、$h=\\frac{1}{2}gt^2$）或黄金代换求出g再代入】；警惕【把g当已知量直接代入地球的$9.8\\ \\mathrm{m/s^2}$；h与R可比时不能按g恒定处理】","src":"跳跳物一轮05.4 环绕模型含g问题_祝大家七夕快乐~~_笔记","note":"视频|10:27","orig":"（知识）物体在某星球表面附近做竖直上抛或平抛运动时的处理方法。","link":""},{"id":"phy2267","t":"万有引力与航天·每天转N圈的卫星求轨道高度","s":"看到【卫星每天（或每N天）绕地球转n圈，给地表g和R，求离地高度】","c":"想到【卫星周期=T/N（T为地球自转周期，N为每天圈数）；对轨道半径R+h列环绕方程（周期形式）并代入$GM=gR^2$，解得$h=\\sqrt[3]{\\frac{gR^2T^2N^2}{4\\pi^2}}-R$；轨道半径=R+h】；警惕【把卫星周期当成地球自转周期T；解出的是轨道半径，忘减R才是离地高度】","src":"跳跳物一轮05.4 环绕模型含g问题_祝大家七夕快乐~~_笔记","note":"视频|11:59","orig":"（例）“羲和号”卫星每天绕地球转N圈，已知地球半径R、地表重力加速度g、地球自转周期T，求卫星距地面高度h。","link":""},{"id":"phy2268","t":"万有引力与航天·两极与赤道重力加速度综合应用","s":"看到【同时给两极重力加速度g$_0$和赤道重力加速度g$_1$，求自转周期、同步卫星高度或密度】","c":"想到【两极$\\frac{GMm}{R^2}=mg_0$得$GM=g_0R^2$；赤道$\\frac{GMm}{R^2}=m\\cdot\\frac{4\\pi^2}{T^2}R+mg_1$，解得自转周期$T=2\\pi\\sqrt{\\frac{R}{g_0-g_1}}$；密度$\\rho=\\frac{3g_0}{4\\pi GR}$；近地卫星周期$2\\pi\\sqrt{R/g_0}$；同步卫星周期=自转周期，对R+h列环绕方程解h】；警惕【密度和近地卫星公式误代赤道$g_1$，两极与赤道的g张冠李戴】","src":"跳跳物一轮05.4 环绕模型含g问题_祝大家七夕快乐~~_笔记","note":"视频|19:29","orig":"（例）已知地球半径R、两极重力加速度g$_0$、赤道重力加速度g$_1$，求地球自转周期T、同步卫星离地高度h、地球平均密度$\\rho$和近地卫星周期。","link":""},{"id":"phy2269","t":"万有引力与航天·近地卫星与同步卫星","s":"看到【题目涉及近地卫星或同步（静止）卫星，问轨道半径、周期、角速度或新旧定义】","c":"想到【近地卫星在表面附近环绕，轨道半径$\\approx$地球半径R，是r最小的卫星，由低轨高速小周期知其v、$\\omega$最大、T最小；同步卫星周期=地球自转周期24h，角速度与自转相同；静止卫星（旧定义）必须一直在赤道正上方且相对静止，新定义同步卫星只要求周期相同、不一定相对静止】；警惕【把新定义同步卫星当成一定在赤道上方相对静止；近地卫星轨道半径直接取R不再加高度】","src":"跳跳物一轮05.5 宇宙航行三大考点_笔记","note":"视频|00:36-01:43","orig":"（知识）近地卫星与同步卫星是两类特殊卫星，各有确定的轨道和周期特征。","link":""},{"id":"phy2270","t":"万有引力与航天·三个宇宙速度与发射环绕速度之辨","s":"看到【题目给出发射速度或问卫星速度与7.9、11.2、16.7 km/s的关系】","c":"想到【第一宇宙速度$7.9\\ \\mathrm{km/s}$=最小发射速度=近地卫星环绕速度=最大环绕速度，由$mg=\\frac{mv^2}{R}$得$v=\\sqrt{gR}$；第二宇宙速度$11.2\\ \\mathrm{km/s}$脱离地球引力束缚，第三$16.7\\ \\mathrm{km/s}$脱离太阳系；卫星升空到高轨是减速过程，故环绕速度<发射速度，发射速度越大轨道越高、环绕速度反而越小】；警惕【发射速度与环绕速度张冠李戴；认为卫星速度绝不能超过$7.9\\ \\mathrm{km/s}$（发射速度可以超过）】","src":"跳跳物一轮05.5 宇宙航行三大考点_笔记","note":"视频|04:22-09:07","orig":"（知识）三个宇宙速度的数值含义，以及发射速度与环绕速度的区别。","link":""},{"id":"phy2271","t":"万有引力与航天·离心向心判断与卫星变轨过程","s":"看到【卫星沿椭圆轨道在两圆轨道之间转移，问点火加速还是减速、何时离心】","c":"想到【以原轨迹圆为参照：新轨迹往圈内拐=向心，往圈外拐=离心；小圆变大圆：在近地点和远地点各点火加速一次（两次加速、两次离心），中间沿椭圆从近地点到远地点持续减速，最终大圆速度小于原小圆速度；大圆变小圆完全相反（两次减速、两次向心）】；警惕【以为加速两次后最终速度应变大——两次加速都是瞬时操作，中间漫长减速才是主导】","src":"跳跳物一轮05.5 宇宙航行三大考点_笔记","note":"视频|09:46-11:28","orig":"（知识）卫星在小圆与大圆轨道之间变轨的操作序列与运动性质判断。","link":""},{"id":"phy2272","t":"万有引力与航天·变轨中速度与加速度的比较","s":"看到【比较椭圆近地点、远地点与内外圆轨道上的速度或加速度大小】","c":"想到【速度口诀“近大远小，椭圆在两端”：椭圆近地点速度>小圆速度>大圆速度>椭圆远地点速度；加速度只看卫星到地心的距离、与轨道形状无关，同一位置（如相切点）在圆轨道和椭圆轨道上加速度相同，点火瞬间不参与比较】；警惕【用轨道高低比较加速度——加速度与轨道形状无关；漏掉椭圆自身近地点速度大于远地点速度】","src":"跳跳物一轮05.5 宇宙航行三大考点_笔记","note":"视频|17:01-18:48","orig":"（知识）同一卫星变轨时，圆轨道与椭圆轨道上各点速度、加速度的比较方法。","link":""},{"id":"phy2273","t":"万有引力与航天·变轨中周期与机械能的比较","s":"看到【比较圆轨道卫星与椭圆轨道卫星的周期大小或机械能大小】","c":"想到【周期用开普勒第三定律$\\frac{a^3}{T^2}=K$：椭圆取半长轴、圆取轨道半径，a越大T越大；卫星在稳定圆或椭圆轨道上机械能守恒，同一卫星轨道越高机械能越大（点火加速把化学能转化为机械能），不同卫星质量关系未知则无法比较机械能】；警惕【椭圆周期误用近地点或远地点距离代入；比较机械能时纠缠点火导致的微小质量变化】","src":"跳跳物一轮05.5 宇宙航行三大考点_笔记","note":"视频|20:14-21:23","orig":"（知识）比较不同轨道（圆与椭圆）上卫星的周期与机械能。","link":""},{"id":"phy2274","t":"万有引力与航天·同轨道卫星对接的受力分析","s":"看到【同轨道上两飞船要对接，问喷气方向或所受合力方向】","c":"想到【加速对接（后船追前船）：需切线方向的动力+指向圆心的力（防止加速后离心），合力指向轨道内侧斜前方，喷气方向与合力相反；减速对接（前船等后船）：需切向阻力+背向圆心的力（防止减速后向心），合力指向轨道外侧斜后方】；警惕【只加速不做向心修正，飞船将离心脱离原轨道无法对接】","src":"跳跳物一轮05.5 宇宙航行三大考点_笔记","note":"视频|23:04","orig":"（知识）同一圆轨道上后船追前船（或前船等后船）完成对接所需的力与喷气方向。","link":""},{"id":"phy2275","t":"万有引力与航天·赤道物体与近地同步卫星三体比较","s":"看到【同时出现赤道表面物体、近地卫星、同步卫星三者，问T、v、a大小排序】","c":"想到【b与c都是卫星，用高轨低速大周期比较；a与c周期同为24h、角速度相同，用$v=\\omega R$、$a=\\omega^2 R$且$R_a<R_c$；结论$T_a=T_c>T_b$，$v_a<v_c<v_b$，$a_b>a_c>a_a$；赤道物体受万有引力和支持力，向心力由二者合力提供】；警惕【赤道物体不是卫星，不能直接用“高轨低速大周期”参与比较】","src":"跳跳物一轮05.5 宇宙航行三大考点_笔记","note":"视频|28:27","orig":"（例）比较赤道上的物体a、近地卫星b、同步卫星c的周期、线速度和向心加速度大小。","link":""},{"id":"phy2276","t":"万有引力与航天·径向喷气变轨的速度分析","s":"看到【飞船沿径向（非切向）喷气获得径向分速度后变轨，问速度或加速度变化】","c":"想到【P点变轨前后到地心距离不变，加速度相同；原切向速度$v_1$与径向反冲速度$v_2$合成，合速度大于$v_1$，P点速度变大；周期比较：圆轨道用半径、椭圆轨道用半长轴，半长轴更大则周期更大】；警惕【套用“减速向心”规律——其前提是物体只有切向速度且提供的向心力不变，本题获得径向速度不满足条件】","src":"跳跳物一轮05.5 宇宙航行三大考点_笔记","note":"视频|41:18","orig":"（例）空间站在圆轨道上逆时针运动，在P点沿径向（指向圆心方向）喷气获得反冲速度，变轨到半长轴更大的椭圆轨道，判断P点加速度、周期、速度的变化。","link":""},{"id":"phy2277","t":"万有引力与航天·卫星追及相遇与对接的辨析","s":"看到【两卫星同向绕行，问二者何时“相遇”或能否对接】","c":"想到【相同点：两类问题中两卫星转动方向必须相同；不同点：追及相遇问题中两卫星在不同轨道上，“相遇”指两卫星距离最近（并非真实碰撞）；对接问题中两卫星必须在相同轨道上，“相遇”指真实接触】；警惕【把追及相遇的“距离最近”当成真实碰到；不同轨道上的卫星无法直接对接】","src":"跳跳物一轮05.6 卫星追及相遇、双星模型_天体部分完结撒花~_笔记","note":"视频|00:50","orig":"（知识）卫星追及相遇问题与卫星对接问题的相同点与不同点。","link":""},{"id":"phy2278","t":"万有引力与航天·卫星追及相遇套圈模型","s":"看到【两卫星同向在不同轨道绕行，问再次相距最近或最远需多长时间】","c":"想到【设慢星不动，快星以相对角速度（快星角速度−慢星角速度）绕行：最近到最近（或最远到最远）=套一圈，$(\\frac{1}{T_1}-\\frac{1}{T_2})t=1$，即$t=\\frac{T_1T_2}{T_2-T_1}$；最近到最远（或最远到最近）=套半圈，时间为套一圈的一半，$t=\\frac{T_1T_2}{2(T_2-T_1)}$（T$_1$为快星周期，T$_2$为慢星周期）】；警惕【套半圈与套一圈的时间关系弄反；套圈时间只取决于相对角速度，与绝对快慢无关】","src":"跳跳物一轮05.6 卫星追及相遇、双星模型_天体部分完结撒花~_笔记","note":"视频|02:31-09:19","orig":"（知识）不同轨道上两颗同向卫星，从相距最近（或最远）到再次最近（或最远）的时间计算。","link":""},{"id":"phy2279","t":"万有引力与航天·冲日问题","s":"看到【问某地外行星（火星、木星、海王星等）两次冲日的间隔时间或日期估算】","c":"想到【冲日即三者排成直线、地球与行星相距最近，本质是最近到最近问题，地球是快的天体，两次冲日之间地球比行星恰好多转一圈；地外行星轨道半径超过地球5倍时可近似看成静止，冲日间隔比$365$天略大几天；轨道越远的行星冲日间隔越短，海王星间隔最短】；警惕【冲日间隔不可能恰好等于$365$天；远行星（天王星、海王星）间隔接近$365$天，不可能长达$800$天】","src":"跳跳物一轮05.6 卫星追及相遇、双星模型_天体部分完结撒花~_笔记","note":"视频|11:42","orig":"（知识）地外行星冲日（地球处在太阳与该行星之间且三者排成直线）的间隔时间规律。","link":""},{"id":"phy2280","t":"万有引力与航天·双星模型的基本特征","s":"看到【两颗星球绕它们之间的某点做圆周运动（无中心天体）】","c":"想到【双星没有静止的中心天体，彼此的万有引力互为向心力（相互作用力，大小相等方向相反）；两星球与圆心始终在同一直线上，如同绕圆心旋转的一根杆上的两个点；同轴传动：角速度$\\omega$相等、周期T相等，圆心在两星连线上】；警惕【把双星当成环绕模型处理；认为质量大的星“拉着”质量小的星转、引力不相等】","src":"跳跳物一轮05.6 卫星追及相遇、双星模型_天体部分完结撒花~_笔记","note":"视频|15:43-16:35","orig":"（知识）双星系统（两个天体互相绕转）的运动特征与向心力来源。","link":""},{"id":"phy2281","t":"万有引力与航天·双星模型核心方程与反比结论","s":"看到【双星系统给两星质量（或半径、速度）关系，问各星的r、v、a大小】","c":"想到【$R_1+R_2=L$（L为两星间距）；对每颗星列$\\frac{GM_1M_2}{L^2}=M\\omega^2R$；由$M_1\\omega^2R_1=M_2\\omega^2R_2$知轨道半径、线速度、向心加速度均与质量成反比——质量大的星球轨道半径小、线速度小、向心加速度小】；警惕【万有引力公式中的距离是两星间距L，误用成轨道半径；双星方程里两星用同一个L】","src":"跳跳物一轮05.6 卫星追及相遇、双星模型_天体部分完结撒花~_笔记","note":"视频|19:56-21:44","orig":"（知识）双星系统的动力学方程及轨道半径、线速度、向心加速度与质量的定量关系。","link":""},{"id":"phy2282","t":"万有引力与航天·双星总质量方程（麻辣烫方程）","s":"看到【双星系统已知间距L和周期T，求总质量或判断L与T的关系】","c":"想到【对两星的动力学方程相加得$\\frac{G(M_1+M_2)}{L^2}=\\frac{4\\pi^2}{T^2}L$，即$G(M_1+M_2)T^2=4\\pi^2L^3$，其中总质量M总=$M_1+M_2$；可求总质量、间距L或周期T；总质量恒定时L越大T越大】；警惕【该方程只能求出总质量，单独每颗星的质量需结合半径反比关系另求】","src":"跳跳物一轮05.6 卫星追及相遇、双星模型_天体部分完结撒花~_笔记","note":"视频|23:44","orig":"（知识）双星系统中总质量、两星间距与共同周期的关系式。","link":""},{"id":"phy2283","t":"万有引力与航天·追及相遇结合开普勒定律求半径比","s":"看到【给两卫星距离-时间图像（两次最近间隔已知），求轨道半径之比】","c":"想到【第一步用套圈公式$(\\frac{1}{T_1}-\\frac{1}{T_2})T_0=1$求出周期比；第二步对同一中心天体用开普勒第三定律$\\frac{R^3}{T^2}$为常数，得$\\frac{R_1}{R_2}=(\\frac{T_1}{T_2})^{2/3}$，例如周期比1:8对应半径比1:4】；警惕【把两次最近的时间间隔直接当成某颗卫星的周期；由周期比求半径比时忘记开$2/3$次方】","src":"跳跳物一轮05.6 卫星追及相遇、双星模型_天体部分完结撒花~_笔记","note":"视频|28:10","orig":"（例）两卫星绕同一中心天体同向运行，距离随时间变化的图像给出两次相距最近的间隔T$_0$，结合其中一颗的周期，求两卫星轨道半径之比。","link":""},{"id":"phy2284","t":"万有引力与航天·双星与环绕模型的周期比较","s":"看到【同一系统比较双星模型与环绕模型（中心天体静止）的周期之比】","c":"想到【双星模型用总质量：$\\frac{G(M_1+M_2)}{L^2}=\\frac{4\\pi^2L}{T_1^2}$；环绕模型只用中心天体质量：$\\frac{GM_1}{L^2}=\\frac{4\\pi^2L}{T_2^2}$；两式相除得$\\frac{T_1}{T_2}=\\sqrt{\\frac{M_1}{M_1+M_2}}$，双星周期更短】；警惕【环绕模型中把环绕体质量也计入提供引力的质量；两模型距离L相同但质量取法不同】","src":"跳跳物一轮05.6 卫星追及相遇、双星模型_天体部分完结撒花~_笔记","note":"视频|39:29","orig":"（例）同一对天体（如地球与月球，间距L），分别按双星模型（两者都动）和环绕模型（中心天体静止、另一天体绕转）计算周期，求两周期之比。","link":""},{"id":"phy2285","t":"功和功率·功的定义式与适用条件","s":"看到【用 $W=Fx\\cos\\theta$ 计算功，或问功是标量还是矢量、定义式的适用范围】","c":"想到【做功是力搬运能量的过程，功是搬运能量的多少；$W=Fx\\cos\\theta$，$\\theta$ 为力与位移方向的夹角；该式只适用于恒力（大小方向都不变）；$F$ 与 $x$ 均取绝对值，不带正负号；位移 $x$ 一律取对地位移而非相对位移；功是标量，单位焦耳】；警惕【变力做功直接套定义式、误用相对位移、把功当矢量合成】","src":"跳跳物一轮06.1 功和功率_让你彻底理解“功”_笔记","note":"视频|00:20","orig":"（知识）功的定义式、物理意义与使用时的三个注意事项。","link":""},{"id":"phy2286","t":"功和功率·功的正负与克服做功","s":"看到【判断某力做正功、负功还是不做功，或比较几个功的大小】","c":"想到【夹角为锐角→正功，力是动力，其他能量转化为动能；钝角→负功，力是阻力，动能转化为其他能量；垂直→不做功；只有力做负功时才说“克服”该力做功，克服功=该功的绝对值；比较功的大小只比绝对值、不看正负号】；警惕【动力做正功不等于动能一定增加，可能同时有阻力做负功，动能变化取决于各功的代数和】","src":"跳跳物一轮06.1 功和功率_让你彻底理解“功”_笔记","note":"视频|05:42","orig":"（知识）力与位移的夹角决定功的正负，以及“克服”的说法和比大小规则。","link":""},{"id":"phy2287","t":"功和功率·合力做功的两种方法","s":"看到【物体受多个力作用，求合力做的功或总功】","c":"想到【方法一先分后总：分别算出各力做的功，再带正负号求代数和；方法二先合后分：先求合力，再用 $W=Fx\\cos\\theta$ 算合力做的功；两法结果相同，哪个简单用哪个——各力的功容易求用方法一，合力容易求用方法二】；警惕【方法一的代数和必须带符号相加，不是把各功的绝对值加起来】","src":"跳跳物一轮06.1 功和功率_让你彻底理解“功”_笔记","note":"视频|10:31","orig":"（知识）求合力做功的两种方法及其选择策略。","link":""},{"id":"phy2288","t":"功和功率·用路程计算变力做功","s":"看到【力大小不变、方向始终与速度同向或反向（切向拉力、曲线摩擦力）求功】","c":"想到【此时不能用位移版公式，改用路程：同向 $W=Fs$、反向 $W=-Fs$（$s$ 为路程）；原理是微元法，把曲线切成无数小段，每段上力恒定，各段功相加=力×总路程；如驴拉磨沿切线的拉力转一周做功 $W=F\\cdot 2\\pi R$】；警惕【“力大小不变”和“方向始终与速度共线”两个条件缺一不可；反向时负号别丢】","src":"跳跳物一轮06.1 功和功率_让你彻底理解“功”_笔记","note":"视频|15:03","orig":"（知识）力大小不变、方向始终与速度共线时，用路程计算功。","link":""},{"id":"phy2289","t":"功和功率·平均功率与瞬时功率","s":"看到【求某段时间内或某时刻的功率，或比较功率大小】","c":"想到【功率描述做功快慢，是标量但有正负，比大小只比绝对值；平均功率 $P=\\frac{W}{t}$；瞬时功率 $P=Fv\\cos\\theta$，$F$、$v$ 取该时刻的值，$\\theta$ 为力与速度的夹角，力与速度垂直时功率为零】；警惕【$P=\\frac{W}{t}$ 只是平均功率不能当瞬时用，$P=Fv\\cos\\theta$ 不能当平均用；$v$ 大功率不一定大，还由 $F$ 与夹角共同决定】","src":"跳跳物一轮06.1 功和功率_让你彻底理解“功”_笔记","note":"视频|19:46","orig":"（知识）功率的定义、两套公式与比大小规则。","link":""},{"id":"phy2290","t":"功和功率·变力与速度成恒定夹角的正交分解法","s":"看到【变力大小不变但与速度方向成恒定夹角（不共线），求该变力做的功】","c":"想到【把 $F$ 沿速度方向和垂直速度方向正交分解：垂直分力始终与速度垂直、全程不做功；沿速度分力大小不变且与速度同向，用分力×路程计算；本题沿速度分力 $=10\\times 0.8=8\\,\\mathrm{N}$，路程=弧长 $=\\frac{1}{6}\\times 2\\pi\\times 6=2\\pi\\,\\mathrm{m}$，拉力功 $=16\\pi\\,\\mathrm{J}$；克服摩擦功 $=0.2\\times 2\\times 10\\times 2\\pi=8\\pi\\,\\mathrm{J}$】；警惕【误把变力当恒力、用起点到终点的位移套 $W=Fx\\cos\\theta$；“摩擦力做的功”（$-8\\pi\\,\\mathrm{J}$）与“克服摩擦力做的功”（$8\\pi\\,\\mathrm{J}$）差一个绝对值】","src":"跳跳物一轮06.1 功和功率_让你彻底理解“功”_笔记","note":"视频|40:32","orig":"（例）小球在水平桌面上沿半径 6m 的圆弧从 M 运动到 N（圆心角 60°），拉力大小恒为 10N、方向始终与速度成 37°，小球质量 2kg、动摩擦因数 0.2，求拉力做的功与克服摩擦力做的功。","link":""},{"id":"phy2291","t":"功和功率·斜拉物体时正压力与摩擦力做功","s":"看到【水平面上物体受斜向上（斜向下）拉力，求正压力、摩擦力或其做功】","c":"想到【竖直方向列平衡：$N=mg-F\\sin\\theta$，摩擦力 $f=\\mu N=\\mu (mg-F\\sin\\theta)$，克服摩擦做功 $=\\mu (mg-F\\sin\\theta)L$；拉力做功 $W=FL\\cos\\theta$；匀加速时 $F$ 与 $\\theta$ 恒定、$v$ 一直增大，瞬时功率 $P=Fv\\cos\\theta$ 一直增大】；警惕【别默认 $N=mg$，拉力有竖直分量时 $N=mg\\pm F\\sin\\theta$（斜上拉减、斜下拉加）；平均功率不能套瞬时式 $P=Fv\\cos\\theta$】","src":"跳跳物一轮06.1 功和功率_让你彻底理解“功”_笔记","note":"视频|27:45","orig":"（例）木箱在水平面上受与水平方向成 $\\theta$ 角的斜向上恒定拉力 F，沿水平面匀加速前进 L，求拉力做功、瞬时功率的变化和克服摩擦力做的功。","link":""},{"id":"phy2292","t":"功和功率·自动扶梯下楼中的摩擦力方向与做功","s":"看到【人随斜扶梯加速或匀速运动，问摩擦力方向、超失重或摩擦力做功】","c":"想到【把加速度正交分解为水平与竖直分量：水平方向人只受摩擦力，摩擦力与水平加速度分量同向；超失重只看竖直加速度分量，向下即失重；做功看力与位移夹角：加速阶段摩擦力（水平）与位移（沿斜面向下）成锐角，做正功；匀速阶段加速度为零、摩擦力为零，不做功】；警惕【超失重与水平加速度无关；摩擦力沿水平方向而非沿斜面方向】","src":"跳跳物一轮06.1 功和功率_让你彻底理解“功”_笔记","note":"视频|33:31","orig":"（例）乘客乘节能扶梯沿斜面向下运动，先加速后匀速（加速阶段加速度沿斜面向下），判断摩擦力方向、是否失重、摩擦力做功的正负。","link":""},{"id":"phy2293","t":"功和功率·图像面积含义的判定方法","s":"看到【$F$-$x$ 图或 $P$-$t$ 图求围成面积，或问某图像面积的物理意义】","c":"想到【判定方法：在图线上截一个小矩形，面积=纵坐标×横坐标，该乘积的物理意义就是整块面积的含义；$F$-$x$ 图面积=力×位移=力做的功，$P$-$t$ 图面积=功率×时间=力做的功；$a$-$t$ 图面积=$\\Delta v$（速度变化量）；$x$-$t$ 图面积无物理意义】；警惕【$a$-$t$ 图面积不是位移、$x$-$t$ 图面积不是速度、$F$-$x$ 图面积不是力，别与 $v$-$t$ 图面积（位移）混淆】","src":"跳跳物一轮06.2 F-x图、P-t图、常见力做功_笔记","note":"视频|00:25","orig":"（知识）图线与横轴围成面积的物理意义及微元法判定。","link":""},{"id":"phy2294","t":"功和功率·重力做功只看竖直位移","s":"看到【物体沿曲线或斜面运动求重力做功，已知斜面长与夹角】","c":"想到【重力是恒力，做功与路径无关，只看初末位置的竖直高度差：$W=mg\\Delta h$（下降做正功、上升做负功）；斜面倾角 $\\theta$（与水平方向）时 $W=mgL\\sin\\theta$】；警惕【题目给的是斜面与竖直方向的夹角 $\\alpha$ 时，高度差 $h=L\\cos\\alpha$，别套成 $L\\sin\\alpha$；不能用路程或斜面长直接当位移用】","src":"跳跳物一轮06.2 F-x图、P-t图、常见力做功_笔记","note":"视频|03:17","orig":"（知识）重力做功的特点与计算方法。","link":""},{"id":"phy2295","t":"功和功率·支持力是否做功的判断","s":"看到【物体被支持面支撑着运动，判断支持力做功情况】","c":"想到【接触面静止：物体位移沿接触面，支持力垂直于接触面，支持力不做功；接触面不静止（斜面可动、升降机中的斜面等）：物体对地位移不一定沿接触面，支持力可能做正功、负功或为零，必须画图比较支持力方向与对地位移方向】；警惕【不能凭感觉认为支持力永不做功；物块与木板一起水平匀速运动时接触面虽动，支持力与位移仍垂直、做功仍为零】","src":"跳跳物一轮06.2 F-x图、P-t图、常见力做功_笔记","note":"视频|05:55","orig":"（知识）支持力做功与否取决于接触面是否静止。","link":""},{"id":"phy2296","t":"功和功率·固定面上往复滑动的摩擦力做功","s":"看到【物体在固定粗糙面上往复滑动，求全程摩擦力做的功】","c":"想到【摩擦力方向始终与速度反向（阻力）、大小不变时用路程算：$W=-f\\cdot s$（$s$ 为路程）；如物体从 A 滑到 B（距离 $L$）再原路返回 A，全程位移为零但路程为 $2L$，摩擦力做功 $W=-f\\cdot 2L$，不为零】；警惕【往返时摩擦力方向改变、不是恒力，不能用位移计算；“总位移为零所以做功为零”对摩擦力不成立】","src":"跳跳物一轮06.2 F-x图、P-t图、常见力做功_笔记","note":"视频|09:25","orig":"（知识）接触面静止、摩擦力大小不变时，摩擦力做功用路程计算。","link":""},{"id":"phy2297","t":"功和功率·斜面摩擦力做功等效法","s":"看到【物体沿固定斜面滑动求摩擦力做功，涉及水平投影长度】","c":"想到【斜面上摩擦力做功等于在水平面上滑过相同投影距离的摩擦力做功：$W=-\\mu mg\\cdot x$（$x$ 为斜面的水平投影长度）；推导：斜面摩擦力 $\\mu mg\\cos\\theta$，斜面路程 $L=x/\\cos\\theta$，相乘即约去 $\\cos\\theta$】；警惕【等效后摩擦力大小必须用水平面上的 $\\mu mg$，不能用斜面上的 $\\mu mg\\cos\\theta$ 去乘投影长度】","src":"跳跳物一轮06.2 F-x图、P-t图、常见力做功_笔记","note":"视频|13:46","orig":"（知识）物体沿斜面滑动时，摩擦力做功的等效计算。","link":""},{"id":"phy2298","t":"功和功率·a-x图转换F-x图求变力做功","s":"看到【变加速直线运动给出 $a$-$x$ 图，求某位置的速度】","c":"想到【加速度随位移变化，运动学公式失效，改用动能定理：由 $F=ma$ 把 $a$-$x$ 图转换为 $F$-$x$ 图（各值乘质量 $m$，仍是过原点的直线）；$F$-$x$ 图与横轴围成的梯形面积=拉力做的功，本题 $W=\\frac{3m+5m}{2}\\times 4=16m$；再列 $16m=\\frac{1}{2}mv^2-0$，解得 $v=4\\sqrt{2}\\,\\mathrm{m/s}$】；警惕【$a$-$x$ 图的面积不是功，必须先乘 $m$ 转成 $F$-$x$ 图再算面积；梯形面积别只取一端的力】","src":"跳跳物一轮06.2 F-x图、P-t图、常见力做功_笔记","note":"视频|18:16","orig":"（例）物体在光滑水平面上从原点由静止出发做变加速直线运动，$a$-$x$ 图为一条过 $(0,3)$ 与 $(4,5)$ 的倾斜直线（$x$ 单位 m、$a$ 单位 $\\mathrm{m/s^2}$），求 $x=4\\,\\mathrm{m}$ 处物体的速度。","link":""},{"id":"phy2299","t":"功和功率·不同倾角斜面匀速上滑的做功比较","s":"看到【粗糙程度相同的几个斜面拉物体到同一高度，比较做功多少】","c":"想到【克服重力做功 $=mgh$，只由高度决定，各斜面相同；克服摩擦做功 $=\\mu mgh\\cot\\alpha=\\mu mg\\times$水平投影长度（$\\alpha$ 为倾角），倾角越小投影越长、克服摩擦越多；匀速上滑时拉力做功 $W_F=mgh+\\mu mgh\\cot\\alpha$，也是倾角越小越多】；警惕【克服摩擦力做功并非只由高度决定，随倾角（水平投影长度）变化；别把“克服重力做功相同”误推广到所有力】","src":"跳跳物一轮06.2 F-x图、P-t图、常见力做功_笔记","note":"视频|25:54","orig":"（例）物体沿倾角不同、动摩擦因数相同的斜面匀速上滑到相同高度 $h$，比较克服重力做功、克服摩擦力做功和拉力做功。","link":""},{"id":"phy2300","t":"功和功率·匀速圆周运动中的力三角形与做功","s":"看到【水平面上匀速圆周运动，物体受拉力与摩擦力，求拉力或功率】","c":"想到【摩擦力沿切线与速度反向，合力（向心力）指向圆心，拉力、摩擦力、向心力构成直角三角形且拉力为斜边：F=√(f$^2$+F向$^2$)，本题 $f=\\mu mg=40\\,\\mathrm{N}$、F向 $=mv^2/R=30\\,\\mathrm{N}$，得 $F=50\\,\\mathrm{N}$；拉力功率 $P=Fv\\cos\\alpha$，$\\cos\\alpha=f/F=4/5$，得 $P=120\\,\\mathrm{W}$；转一周克服摩擦功 $=f\\cdot 2\\pi R=1920\\pi\\,\\mathrm{J}$】；警惕【拉力不等于摩擦力大小（还有向心分量）；摩擦力做功用路程（周长 $2\\pi R$）而非位移（转一周位移为零）】","src":"跳跳物一轮06.2 F-x图、P-t图、常见力做功_笔记","note":"视频|39:46","orig":"（例）雪橇质量 $80\\,\\mathrm{kg}$，在水平雪面上被狗拖着以 $3\\,\\mathrm{m/s}$ 的速率做半径 $24\\,\\mathrm{m}$ 的匀速圆周运动，动摩擦因数 $0.05$，求拉力大小、拉力功率和转一周克服摩擦力做的功。","link":""},{"id":"phy2301","t":"机车启动·恒功率启动过程","s":"看到【机车以额定功率恒定启动，问运动性质或最大速度】","c":"想到【两大核心公式：$F-f=ma$ 与 $P=Fv$（$P$ 恒为额定功率）；$v$ 增大→牵引力 $F=P/v$ 减小→加速度减小，做加速度减小的加速运动，$v$-$t$ 图是越来越平缓的曲线；当 $F$ 减小到等于阻力 $f$ 时 $a=0$，机车匀速、速度达最大值 $v_M$，此时 $P=f\\cdot v_M$，常用来反求阻力】；警惕【恒功率加速不是匀加速直线运动，运动学公式失效；最大速度的标志是 $F=f$，不是功率最大时】","src":"跳跳物一轮06.3 机车启动_笔记","note":"视频|02:15","orig":"（知识）机车以恒定（额定）功率从静止启动的全程分析。","link":""},{"id":"phy2302","t":"机车启动·恒加速度启动三阶段","s":"看到【机车以恒定加速度（恒牵引力）启动，分析各阶段运动或 v-t 图】","c":"想到【第一阶段匀加速：$a$ 恒定→牵引力恒定（$F=f+ma$），功率 $P=Fv$ 随 $v$ 增大；第二阶段：功率达额定后不能再增，牵引力仍大于阻力、机车继续加速但 $F$ 减小，做加速度减小的加速；第三阶段：$F$ 减到等于 $f$ 时匀速，达最大速度；$v$-$t$ 图三段：斜直线→渐平曲线→水平线】；警惕【恒加速度启动并非全程匀加速，是“先匀加速后变加速”；匀加速结束点功率恰好达额定值，但牵引力和加速度仍保持匀加速阶段的值】","src":"跳跳物一轮06.3 机车启动_笔记","note":"视频|04:34","orig":"（知识）机车以恒定加速度启动的三个阶段及 v-t 图特征。","link":""},{"id":"phy2303","t":"机车启动·三个何时关键问题","s":"看到【问机车何时速度最大、何时功率达额定、何时牵引力等于阻力】","c":"想到【速度达到最大：机车匀速运动时；功率达到额定：恒功率启动全程都是额定值，恒加速度启动在匀加速阶段结束时刻达到；牵引力等于阻力：匀速运动时（此后加速度为零）】；警惕【恒加速度启动的功率并非一开始就是额定值，匀加速阶段功率随速度线性增大】","src":"跳跳物一轮06.3 机车启动_笔记","note":"视频|09:54","orig":"（知识）机车启动中三个“何时”的高频判断。","link":""},{"id":"phy2304","t":"机车启动·匀加速末速度与最终最大速度","s":"看到【恒加速度启动机车，求匀加速阶段的最大速度或最终行驶速度】","c":"想到【匀加速结束点：功率刚达额定 $P$、牵引力仍为匀加速值，联立 $P=F\\cdot V_1$ 与 $F=f+ma$ 得 $V_1=P/(f+ma)$；最终匀速时 $F=f$，得 $V_2=P/f$；匀加速阶段功率与速度成正比，$v=V_1/2$ 时功率为 $P/2$；速度超过 $V_1$ 后牵引力变为 $P/v$，加速度 $a'=\\frac{P}{mv}-\\frac{f}{m}$】；警惕【$V_1$ 用 $(f+ma)$ 除、$V_2$ 用 $f$ 除，两公式张冠李戴是最大易错点；$v=V_1/2$ 时仍处于匀加速阶段，别按恒功率算】","src":"跳跳物一轮06.3 机车启动_笔记","note":"视频|08:07","orig":"（知识）恒加速度启动中两个“最大速度”的求法对比。","link":""},{"id":"phy2305","t":"机车启动·加速阶段求时间与位移","s":"看到【机车启动过程求加速阶段的时间或位移】","c":"想到【分阶段处理：恒功率加速阶段用动能定理，牵引力功加阻力功等于动能变化，即 $P\\cdot t-f\\cdot x=\\frac{1}{2}mv^2-\\frac{1}{2}mv_0^2$，其中初速 $v_0$ 全程恒功率启动取 0，先匀加速再恒功率启动取匀加速末速度；匀加速阶段用初速度为零的运动学公式 $v=at$、$x=\\frac{1}{2}at^2$、$v^2=2ax$，按已知量选公式】；警惕【恒功率阶段加速度在变，不能用运动学公式；动能定理的 $v_0$ 取错前一段的末速度】","src":"跳跳物一轮06.3 机车启动_笔记","note":"视频|10:47","orig":"（知识）机车启动加速阶段求时间、位移的方法分工。","link":""},{"id":"phy2306","t":"机车启动·动车恒功率启动的判断","s":"看到【车辆恒功率从某初速加速到最大速度，判断说法正误】","c":"想到【恒功率加速是加速度减小的加速运动，不是匀加速；达到 $v_M$ 时牵引力等于阻力，功率 $P=f\\cdot v_M$，可用最大速度时的状态计算功率；动能定理：牵引力功+阻力功=动能变化量，故牵引力做的功不等于动能变化量（须补上阻力做的负功）】；警惕【把动能变化量直接当作牵引力做功、漏掉阻力做功；此阶段匀加速公式全部失效】","src":"跳跳物一轮06.3 机车启动_笔记","note":"视频|14:49","orig":"（例）动车以恒定功率从初速度 $v_0$ 加速到最大速度 $v_M$（阻力恒定），判断其运动性质、最大速度条件、功率表达式与做功关系。","link":""},{"id":"phy2307","t":"机车启动·v-F图像识别启动过程","s":"看到【给出 $v$-$F$ 图像（速度随牵引力变化），分析汽车启动过程】","c":"想到【水平段=牵引力恒定→匀加速直线运动；斜线段 $v$ 与 $F$ 成反比（整理得 $Fv=$常数）→恒功率加速；匀速时牵引力等于阻力，故最大速度端点的横坐标就是阻力；斜线段 $F$ 与 $v$ 的乘积即额定功率；匀加速末速度取水平段纵坐标，配合 $F-f=ma$ 与 $v=at$ 求时间；恒功率段位移用动能定理 $P\\cdot t_2-f\\cdot x=\\frac{1}{2}mv_M^2-\\frac{1}{2}mv_1^2$】；警惕【把水平段的牵引力 $4\\,\\mathrm{N}$ 当成阻力（阻力是匀速端的 $2\\,\\mathrm{N}$）；恒功率段套用运动学公式】","src":"跳跳物一轮06.3 机车启动_笔记","note":"视频|24:23","orig":"（例）汽车（质量 $1\\,\\mathrm{kg}$）从静止启动，其 $v$-$F$ 图像分两段：水平段对应牵引力 $F=4\\,\\mathrm{N}$，斜线段满足 $v=F/8$；最大速度 $4\\,\\mathrm{m/s}$，总运动时间 $5\\,\\mathrm{s}$，求阻力、匀加速时间、额定功率和总位移。","link":""},{"id":"phy2308","t":"机车启动·a-1/v图像与目标转化法求阻力","s":"看到【给出 $a$ 随 $1/v$ 变化的关系图像，分析汽车启动过程】","c":"想到【水平段=匀加速；下降段 $a$ 随速度增大而减小=恒功率加速；与横轴交点 $a=0$ 即最大速度（$1/30\\to v_M=30\\,\\mathrm{m/s}$）；求阻力用目标转化法联立两式：匀加速结束点 $P=(f+ma)\\cdot v_1$，匀速时 $P=f\\cdot v_M$，两式相等解出 $f$；车速不超过 $v_1$ 仍属匀加速，功率 $P=(f+ma)v$ 随速度增大】；警惕【横轴是 $1/v$ 不是 $v$，要取倒数才是速度（$1/10\\to 10\\,\\mathrm{m/s}$）；$v=5\\,\\mathrm{m/s}$ 在匀加速阶段内，不能按恒功率算】","src":"跳跳物一轮06.3 机车启动_笔记","note":"视频|30:54","orig":"（例）汽车（质量 $2\\times 10^3\\,\\mathrm{kg}$）测试行驶，加速度 $a$ 与车速倒数 $1/v$ 的关系图像分三段：水平段 $a=2\\,\\mathrm{m/s^2}$，随后下降，与横轴交于 $1/v=1/30$，匀加速结束点对应 $1/v=1/10$。求匀加速时间、阻力和车速 $5\\,\\mathrm{m/s}$ 时的功率。","link":""},{"id":"phy2309","t":"动能和动能定理·动能的定义与标量性","s":"看到【问动能的性质、速度方向为负或速度大小相同方向不同时比较动能】","c":"想到【动能是标量、无方向，代入公式只取速度大小，故动能永远为正或零；物体静止时动能最小为 0；速度大小相等而方向不同，动能相同】；警惕【速度为负值（表示与正方向相反）时把动能算成负——动能无负数，恒不小于零】","src":"跳跳物一轮06.4 动能和动能定理_笔记","note":"视频|00:22-01:03","orig":"（知识）动能是物体由于运动而具有的能量，公式 $E_K=\\frac{1}{2}mv^2$，$v$ 取该时刻瞬时速度的大小。","link":""},{"id":"phy2310","t":"动能和动能定理·动能定理表达式与做功正负","s":"看到【判断做正功/负功时动能如何变化，或列动能定理求动能变化量】","c":"想到【动能定理：合力做的功 = 末动能 - 初动能，变化量一律用末减初；正功把其他形式能量转化为动能，负功把动能转化为其他能量；单力作用看该力做功正负，多力作用看合力做功正负——合力做正功动能增、做负功动能减】；警惕【变化量误写成初减末；某分力做正功但合力做负功时动能仍在减小，别只看单个力】","src":"跳跳物一轮06.4 动能和动能定理_笔记","note":"视频|01:47-03:01","orig":"（知识）合力对物体做的功等于物体动能的变化量，做功的正负决定动能的增减。","link":""},{"id":"phy2311","t":"动能和动能定理·列动能定理的规范步骤","s":"看到【过程有多个力做功，要用动能定理求未知力或未知功】","c":"想到【先对物体受力分析，明确哪些力做功、防止漏力；写合力做功表达式时先一律用加号连接各力的功，具体代入数值时做负功的力前再补负号，如 W合=$W_F+W_f$，代入后为 $Fx-fx$】；警惕【漏计做功的摩擦力或阻力；一开始就带正负号又在代入时重复加负号，符号出错】","src":"跳跳物一轮06.4 动能和动能定理_笔记","note":"视频|04:26","orig":"（知识）用动能定理解题时合力做功的写法规范与防漏力方法。","link":""},{"id":"phy2312","t":"动能和动能定理·动能-位移图像斜率结论","s":"看到【给出 $E_K$-$X$ 或 $E_K$-$h$ 图像，问斜率含义、选图像或求合力】","c":"想到【图线斜率的大小等于物体所受合力的大小，比较时统一取绝对值；图线为直线说明该段合力恒定，为曲线说明合力大小变化，应分段取每段斜率讨论】；警惕【把 $E_K$-$X$ 图的斜率当成速度或加速度；曲线段各点斜率不同，整段只用一个合力值】","src":"跳跳物一轮06.4 动能和动能定理_笔记","note":"视频|06:35","orig":"（知识）$E_K$-$X$ 图（动能-位移图像）中图线斜率与物体所受合力的关系。","link":""},{"id":"phy2313","t":"动能和动能定理·平抛动能倍数与水平位移","s":"看到【平抛下落高度相同，动能（或速度）变为 $n$ 倍，问水平射程变化】","c":"想到【动能与速度平方成正比，动能变 4 倍则初速度变 2 倍；下落高度相同则平抛时间相同，水平位移 $x=v_0t$ 与初速度成正比，故水平位移也变 2 倍；一般地动能变 $n^2$ 倍对应速度变 $n$ 倍、水平位移变 $n$ 倍】；警惕【误以为位移随动能同倍数增大（实际随速度）；漏掉高度相同→时间相同这一前提】","src":"跳跳物一轮06.4 动能和动能定理_笔记","note":"视频|11:34","orig":"（例）小车先后两次从同一平台以不同初速度水平弹出做平抛运动，落到同一水平地面上，第二次的动能是第一次的 4 倍，求水平位移变为原来的几倍。","link":""},{"id":"phy2314","t":"动能和动能定理·粗糙水平面圆周运动求摩擦力","s":"看到【物体在粗糙面上沿曲线/圆弧运动后停下，求摩擦力或其做功】","c":"想到【对转一圈全程列动能定理，只有摩擦力做功：$W_f=0-\\frac{1}{2}mv_0^2$；滑动摩擦力大小不变时用路程计算做功 $W_f=-f\\cdot s$，一圈路程 $s=2\\pi L$，联立解得 $f=\\frac{mv_0^2}{4\\pi L}$】；警惕【误用位移代替路程——转一圈位移为零，会错误得出摩擦力不做功】","src":"跳跳物一轮06.4 动能和动能定理_笔记","note":"视频|15:04","orig":"（例）木块在粗糙水平桌面上绕轴做半径为 $L$ 的圆周运动，初速度为 $v_0$，恰好完整转完一圈后速度减为零，求木块受到的摩擦力大小。","link":""},{"id":"phy2315","t":"动能和动能定理·斜面下滑求克服摩擦力做功","s":"看到【沿斜面（或曲面）由静止滑下，已知高度和末速度，求克服摩擦力做的功】","c":"想到【对下滑全程列动能定理（支持力不做功）：$mgh+W_f=\\frac{1}{2}mv^2-0$，解得摩擦力做的功 $W_f=\\frac{1}{2}mv^2-mgh$，为负值；克服摩擦力做的功等于摩擦力做功的绝对值，即 $mgh-\\frac{1}{2}mv^2$】；警惕【“克服摩擦力做的功”与“摩擦力做的功”符号相反，答成负值或忘取绝对值；把不做功的支持力也计入】","src":"跳跳物一轮06.4 动能和动能定理_笔记","note":"视频|17:49","orig":"（例）人从粗糙斜坡顶端由静止滑下，滑到底端时的速度为 $v$，下滑的竖直高度为 $h$，求全程克服摩擦力做的功。","link":""},{"id":"phy2316","t":"动能和动能定理·竖直飞行E_K-h图像分段受力","s":"看到【竖直上升分加速/减速两段，给 $E_K$-$h$ 图像，求升力、重力或加速度比】","c":"想到【$E_K$-$h$ 图线斜率的大小等于该段合力的大小：加速段合力=升力-重力-阻力；减速段升力为零，合力=重力+阻力；对两段分别列方程联立解出未知力，两段加速度大小之比等于合力大小之比】；警惕【减速段照搬加速段的受力表达式、不重新做受力分析；斜率不取绝对值直接当合力导致符号错】","src":"跳跳物一轮06.4 动能和动能定理_笔记","note":"视频|24:26","orig":"（例）无人机竖直向上先加速后减速至最高点，加速段升力恒定，空气阻力恒为重力的 0.25 倍，已知 $E_K$-$h$ 图像两段斜率，求重力、升力大小及两段加速度之比。","link":""},{"id":"phy2317","t":"动能定理三大应用·变力做功三步法","s":"看到【力的大小随位置/时间变化的变力做功，无法直接用 $Fs$ 求功】","c":"想到【三步法：①对全程列动能定理求合力做功（=末动能-初动能）；②分别求出其他已知力的做功；③变力做功 = 合力做功 - 其他力做功之和】；警惕【圆弧轨道上支持力不断变化，摩擦力 $\\mu N$ 是变力，误用摩擦力×路程当恒力功计算】","src":"跳跳物一轮06.5 动能定理三大应用_生日当天的投稿_笔记","note":"视频|00:31","orig":"（知识）遇到变力做功问题，优先用动能定理间接求解的三步法。","link":""},{"id":"phy2318","t":"动能定理三大应用·多过程问题全程列式","s":"看到【物体经历多个运动阶段（先后下落、滑动、上抛等），求末速度、位移或某力做功】","c":"想到【对全程列动能定理，只关注初末状态，不管中间过程细节；每个力各自做功再代数相加即合力功（不同力可在不同时段做功，照样能相加）；重力做功只看初末高度差、与路径无关；若求中间某时刻速度则需分段列式】；警惕【以为不同时段的功不能直接相加；全程方程求不出中间状态量，忘了分段】","src":"跳跳物一轮06.5 动能定理三大应用_生日当天的投稿_笔记","note":"视频|02:20","orig":"（知识）多过程（多阶段）运动问题优先对全程列动能定理。","link":""},{"id":"phy2319","t":"动能定理三大应用·竖直圆两类问题的解法分工","s":"看到【竖直圆中已知最高点求最低点（或反之）的速度、力】","c":"想到【求“点上的力或速度”用圆周动力学方程（向心力公式）；把最高点与最低点联系起来用动能定理，从低到高时末动能为最高点、初动能为最低点（从高到低相反）；动能定理解决速度大小，向心力方程解决力】；警惕【动能变化量的“末减初”方向搞反（从低到高与从高到低相反）；只用动能定理解不出点上的弹力】","src":"跳跳物一轮06.5 动能定理三大应用_生日当天的投稿_笔记","note":"视频|05:43","orig":"（知识）竖直面内圆周运动：单纯分析某点与联系最高最低两点的解法分工。","link":""},{"id":"phy2320","t":"动能定理三大应用·恰好通过最高点的临界条件","s":"看到【绳、杆、圆弧轨道、管道模型中“恰好通过最高点”或求最小速度】","c":"想到【绳模型、圆弧（内轨）模型：最高点只受重力，重力完全提供向心力 $mg=\\frac{mv^2}{R}$，最小速度 $v=\\sqrt{gR}$，此时绳或轨道无弹力；杆模型、穿环、管道模型：最高点速度可为 0，杆或管道能提供支持力】；警惕【把绳模型的最小速度套到杆模型（杆能撑住，v 可为 0）；内轨与外轨（管道上下壁）弹力方向搞反】","src":"跳跳物一轮06.5 动能定理三大应用_生日当天的投稿_笔记","note":"视频|08:20","orig":"（知识）“恰好通过竖直圆最高点”在不同模型下的临界速度条件。","link":""},{"id":"phy2321","t":"动能定理三大应用·力径减半得动能","s":"看到【已知物体在圆周某点的向心力（或合力恰好提供向心力），求该点动能】","c":"想到【由向心力公式得向心力×半径 = $mv^2$，而动能 = $\\frac{1}{2}mv^2$，故动能 = 向心力×半径÷2，即“力径减半得动能”（力指向心力，径指半径，减半指除以 2）；如恰好过最高点时动能 = $\\frac{mgR}{2}$】；警惕【“力”误取成重力或某个单独的力，应是向心力（合力沿半径分量）；非圆周运动不能套用】","src":"跳跳物一轮06.5 动能定理三大应用_生日当天的投稿_笔记","note":"视频|05:43","orig":"（知识）已知物体在圆周某点的向心力时，快速求该点动能的口诀：力径减半。","link":""},{"id":"phy2322","t":"动能定理三大应用·圆弧加水平轨道求变摩擦功","s":"看到【圆弧（曲线）轨道+水平面组合，圆弧段摩擦力为变力，求其做功】","c":"想到【对 $A\\to C$ 全程列动能定理，初末速度均为 0、动能变化量为 0：$mgR+W_{AB}+(-\\mu mgR)=0$，解得 $W_{AB}=(\\mu-1)mgR$，克服摩擦功取绝对值为 $(1-\\mu)mgR$】；警惕【对圆弧段用 $\\mu mg\\times$弧长算功——支持力随位置变化，摩擦是变力；仅支持力恒定的水平段才能 $\\mu mg\\times$路程】","src":"跳跳物一轮06.5 动能定理三大应用_生日当天的投稿_笔记","note":"视频|09:31","orig":"（例）物体从四分之一圆弧轨道顶端 $A$ 由静止滑下，经底端 $B$ 进入粗糙水平轨道，恰好在 $C$ 处停止；圆弧半径为 $R$，$BC$ 段长为 $R$、动摩擦因数为 $\\mu$，求 $AB$ 段克服摩擦力做的功。","link":""},{"id":"phy2323","t":"动能定理三大应用·自由落体陷入泥中求平均阻力","s":"看到【物体下落一段高度后陷入泥/沙等阻力段，求平均阻力或克服阻力功】","c":"想到【求落地动能对空中段列式：$mgH=E_K$；求平均阻力与全程克服阻力功对全程列式：$mg(H+h)-fh=0$，得 $f=\\frac{mg(H+h)}{h}$，克服阻力做功 = $mg(H+h)$（大于落地动能 $mgH$）】；警惕【全程重力做功写成 $mgH$、漏掉泥中下降 $h$ 段的重力功；认为泥中克服阻力功等于落地动能——实际是 $mg(H+h)$】","src":"跳跳物一轮06.5 动能定理三大应用_生日当天的投稿_笔记","note":"视频|15:53","orig":"（例）小球从离地高 $H$ 处自由下落，落入泥中并陷入深度 $h$ 后停止，判断关于落地动能、泥的平均阻力、全程克服阻力做功的说法。","link":""},{"id":"phy2324","t":"动能定理三大应用·双圆轨道恰好过最高点求压力","s":"看到【两个半径不同的光滑竖直圆轨道，恰好通过其一最高点，求另一最高点压力】","c":"想到【三步套路：①恰好通过最高点→只受重力 $mg=\\frac{mv^2}{R}$，求出该点速度；②两点间列动能定理（重力做功 = $-mg\\times$高度差）联系两最高点速度；③在目标点列向心力方程 $N+mg=\\frac{mv^2}{R}$ 解支持力，由牛顿第三定律压力等大反向】；警惕【两圆最高点高度差算错（$2\\times 1.8R-2R=1.6R$）；最高点向心力方程漏掉重力项或方向弄错】","src":"跳跳物一轮06.5 动能定理三大应用_生日当天的投稿_笔记","note":"视频|19:29","orig":"（例）小球先后进入半径不同（小轨道半径 $R$、大轨道半径 $1.8R$）的两个光滑竖直圆轨道，恰能通过大轨道最高点 $B$，求小球在小轨道最高点 $A$ 处对轨道的压力。","link":""},{"id":"phy2325","t":"势能·势能概念与银行模型","s":"看到【问势能的含义，或重力/弹力做功与势能转化方向】","c":"想到【地球存储的叫重力势能，弹簧存储的叫弹性势能；重力（弹力）做负功相当于存钱——动能转化为势能；做正功相当于取钱——势能释放为动能；物体上升时重力做负功存入重力势能，下落时取回转化为动能】；警惕【存取方向记反：是“力做负功存、做正功取”，不是相反】","src":"跳跳物一轮06.6 势能、重力势能、弹性势能、机械能_笔记","note":"视频|00:56","orig":"（知识）势能是地球、弹簧把物体动能存储起来的能量，用“银行存取款”模型理解。","link":""},{"id":"phy2326","t":"势能·重力势能公式与零势面","s":"看到【计算某位置的重力势能数值，或题给参考平面/零势面】","c":"想到【零势面是人为定义的重力势能为零的平面，选取不唯一、通常选地面；物体在零势面上方 $h$ 取正、重力势能为正，在下方 $h$ 取负、重力势能为负，恰在零势面上为 0；重力势能是标量，单位焦耳】；警惕【不指明零势面就谈重力势能的数值——势能大小依赖于零势面的选取】","src":"跳跳物一轮06.6 势能、重力势能、弹性势能、机械能_笔记","note":"视频|06:45-07:23","orig":"（知识）重力势能 $E_{PG}=mgh$ 的计算与零势面的选取、高度 $h$ 的正负。","link":""},{"id":"phy2327","t":"势能·重力势能变化量与零势面无关","s":"看到【物体升降后问重力势能变化量，或零势面改变后重新判断】","c":"想到【重力做正功重力势能减少、做负功增加；变化量的大小 = $mg\\times$高度差，如物体下降 $l$，重力做正功 $mgl$、势能就减少 $mgl$，无论零势面选在哪、初末势能的数值如何，变化量都相同】；警惕【以为换零势面会改变势能变化量或重力做功；重力做正功时把势能写成增加（应为减少）】","src":"跳跳物一轮06.6 势能、重力势能、弹性势能、机械能_笔记","note":"视频|08:19","orig":"（知识）重力势能的变化量只与高度差有关，与零势面的选取无关。","link":""},{"id":"phy2328","t":"机械能·功与能比大小的正负号规则","s":"看到【比较做功多少或势能、机械能（含负值）的大小】","c":"想到【机械能 = 动能+重力势能+弹性势能（无弹簧时 = 动能+重力势能）；比做功多少只比绝对值、正负号不参与；动能、热能最小为 0 不会出现负值；所有势能（重力势能、弹性势能、电势能）和机械能比大小时正负号参与比较，正 > 负，如 $3\\,\\mathrm{J} > -5\\,\\mathrm{J} > -10\\,\\mathrm{J}$】；警惕【比较负的势能时按绝对值排序（应绝对值小的负数更大）；把做功的正负号也带入比大小】","src":"跳跳物一轮06.6 势能、重力势能、弹性势能、机械能_笔记","note":"视频|13:00-14:00","orig":"（知识）机械能的定义，以及比较功、能大小时正负号是否参与的规则。","link":""},{"id":"phy2329","t":"势能·弹性势能的性质与公式","s":"看到【弹簧被拉伸/压缩，问弹性势能变化、大小比较或 $E_P$-$x$ 图像】","c":"想到【弹簧原长时弹性势能为 0，无需人为定义零势面；形变量越大弹性势能越大；同一弹簧拉长 2cm 与压缩 2cm 弹性势能相同，恒为正值；$E_P=\\frac{1}{2}kx^2$（$k$ 为劲度系数、$x$ 为形变量）不在高中大纲内，大题不能直接使用，可用于选择题分析】；警惕【$E_P$-$x$ 图像画成先增后减——弹性势能只随形变量增大而一直增大；大题中直接引用 $\\frac{1}{2}kx^2$ 会被扣分】","src":"跳跳物一轮06.6 势能、重力势能、弹性势能、机械能_笔记","note":"视频|11:39","orig":"（知识）弹性势能的大小、正负与公式 $E_P=\\frac{1}{2}kx^2$ 的使用限制。","link":""},{"id":"phy2330","t":"势能·以桌面为零势面求落地重力势能","s":"看到【以某平面为零势面，物体最终落在零势面下方，求势能与变化量】","c":"想到【落地位置在零势面下方 $h$ 处，高度取负值，重力势能为 $-mgh$；变化量只看高度差：全程下落 $H+h$，重力做正功 $mg(H+h)$，故重力势能减少 $mg(H+h)$，与零势面选取无关】；警惕【下方位置的势能忘写负号得出 $+mgh$；变化量只算 $H$ 一段、漏掉零势面以下的 $h$ 段】","src":"跳跳物一轮06.6 势能、重力势能、弹性势能、机械能_笔记","note":"视频|19:08","orig":"（例）小球从桌面上方高 $H$ 处自由下落至地面，以桌面为参考平面（零势面），桌面离地面高 $h$，求小球落地时的重力势能及全过程中重力势能的变化量。","link":""},{"id":"phy2331","t":"机械能·匀速圆周运动中各量的变化判断","s":"看到【匀速圆周运动，问速度/加速度/动能/机械能哪些一定不变】","c":"想到【速度、加速度是矢量，方向时刻改变，二者都不变不成立；动能是标量，速度大小不变则动能不变；机械能=动能+重力势能，竖直面内高度变化使重力势能变化，机械能变化（不守恒），水平面内机械能则不变】；警惕【由“匀速”推出“机械能不变”——竖直面内匀速圆周需其他力做功补偿重力，机械能在变】","src":"跳跳物一轮06.6 势能、重力势能、弹性势能、机械能_笔记","note":"视频|27:14","orig":"（例）物体做匀速圆周运动，判断速度、加速度、动能、机械能是否一定不变。","link":""},{"id":"phy2332","t":"机械能·由v-t图像求电梯机械能增加量","s":"看到【电梯/升降机给 $v$-$t$ 图像，求机械能增加量或最大功率】","c":"想到【机械能增加量 = 动能变化量+重力势能增加量；初末速度均为 0 时动能变化为 0，机械能增加量 = $mg\\times$总上升高度，高度 = $v$-$t$ 图线与时间轴围成的面积（梯形面积法）；最大功率用 $P=Fv$，出现在速度最大的加速刚结束时刻，支持力 $F$ 由 $F-mg=ma$ 解出（超重状态力最大）】；警惕【高度只取某一段位移而非图线下总面积；最大功率取在匀速段（速度虽大但支持力小，$Fv$ 乘积并非最大）】","src":"跳跳物一轮06.6 势能、重力势能、弹性势能、机械能_笔记","note":"视频|29:36","orig":"（例）电梯载测试员经历加速、匀速、减速三段上升到最高处停止，已知 $v$-$t$ 图像（梯形）与人的质量，求全程机械能增加量及支持力的最大功率。","link":""},{"id":"phy2333","t":"功能关系·功是能量转化的量度","s":"看到【题目把某个力做的功与某种能量相加减，或问做功的物理意义】","c":"想到【做功是能量转化的过程，不创造也不消耗能量；做了多少功就有多少能量从一种形式转化为另一种形式，功是能量转化的量度；力做正功表示其他形式能转化为动能，做负功表示动能转化为其他形式能】；警惕【任何情况下功与能都不能直接相加，两个数值相加没有物理意义】","src":"跳跳物一轮06.7 功能关系_笔记","note":"视频|00:19-02:27","orig":"（知识）做功的本质及功与能的数值能否混算。","link":""},{"id":"phy2334","t":"功能关系·势能力做功与势能变化量互为相反数","s":"看到【已知重力或弹力做的功，求对应势能的变化量（或反之）】","c":"想到【势能力做的功与对应势能变化量互为相反数，$W=-\\Delta E_p$；重力做正功重力势能减少、做负功增加，如重力做功 $3\\ \\mathrm{J}$ 则重力势能变化量为 $-3\\ \\mathrm{J}$；此规律对弹力、电场力等一切势能力同样适用】；警惕【符号别记反成 $W=\\Delta E_p$；重力做功只由初末位置决定、与路径无关，不要受其他力做功干扰】","src":"跳跳物一轮06.7 功能关系_笔记","note":"视频|05:25-07:57","orig":"（知识）重力、弹力等势能力做功与对应势能变化量的符号关系。","link":""},{"id":"phy2335","t":"功能关系·其他力做功等于机械能变化量","s":"看到【求系统机械能的变化量，或判断机械能是否守恒、如何增减】","c":"想到【其他力（除重力和系统内弹力以外的力）做的功等于系统机械能的变化量；做正功机械能增加、做负功机械能减少，如其他力做功 $-2\\ \\mathrm{J}$ 则机械能变化量为 $-2\\ \\mathrm{J}$；重力和系统内弹力做功只在动能与势能之间搬运能量，不改变机械能】；警惕【别把重力或系统内弹力误计入其他力；机械能变化量不等于动能变化量，动能变化看合力做功】","src":"跳跳物一轮06.7 功能关系_笔记","note":"视频|08:14","orig":"（知识）除重力和系统内弹力以外的力做功与系统机械能变化的关系。","link":""},{"id":"phy2336","t":"功能关系·一对滑动摩擦力做功与摩擦生热","s":"看到【物块在木板上滑动，求摩擦生热或摩擦力对物块、木板做的功】","c":"想到【求某个摩擦力对某物体做的功一律用对地位移：对物块 $W=-F\\cdot x_P$，对木板 $W=F\\cdot x_Q$；摩擦生热 $Q=F\\cdot(x_P-x_Q)=F\\cdot\\Delta x$，$\\Delta x$ 为相对位移；一对滑动摩擦力做功的代数和等于 $-Q$，必然把系统部分动能单向转化为内能】；警惕【算单个物体的功用对地位移、算热量必须用相对位移，两者张冠李戴必错】","src":"跳跳物一轮06.7 功能关系_笔记","note":"视频|11:43","orig":"（知识）板块模型中一对滑动摩擦力对两物体分别做的功及摩擦生热的算法。","link":""},{"id":"phy2337","t":"功能关系·静摩擦与滑动摩擦做功对比","s":"看到【两物体一起运动或发生相对滑动，问是否生热及动能去向】","c":"想到【一对静摩擦力做功的代数和为零，只把动能从一个物体等量转移给另一个物体，不产生热量；一对滑动摩擦力做功则把动能单向转化为内能，生热 $Q=F\\cdot\\Delta x$，$\\Delta x$ 为相对位移】；警惕【静摩擦力对单个物体可做正功或负功，但一对静摩擦力总功恒为零；不能对静摩擦也套摩擦生热公式】","src":"跳跳物一轮06.7 功能关系_笔记","note":"视频|17:36","orig":"（知识）一对静摩擦力做功与一对滑动摩擦力做功的能量去向对比。","link":""},{"id":"phy2338","t":"功能关系·斜抛轨迹不对称暴露空气阻力","s":"看到【抛体轨迹图不对称且未说明忽略空气阻力，问动能、势能或机械能变化】","c":"想到【理想斜抛轨迹关于过最高点的竖直线左右对称，轨迹不对称即空气阻力不可忽略；重力势能变化只与高度差有关，上升 $h$ 重力势能仍增加 $mgh$，不受阻力影响；有阻力时合力做功大小不等于 $mgh$，动能变化量大小不等于 $mgh$，机械能因阻力做负功而减少】；警惕【轨迹已不对称还套机械能守恒，会把错误选项当成对的】","src":"跳跳物一轮06.7 功能关系_笔记","note":"视频|20:35","orig":"（例）足球被踢出，从位置1上升到最高点2（上升高度h）再下落到位置3，题目给出轨迹图但未说明是否忽略空气阻力，判断各段动能、重力势能、机械能的变化。","link":""},{"id":"phy2339","t":"功能关系·板块模型位移关系与做功比例","s":"看到【物块滑上木板并到达板端，已知板长和木板位移，求做功或能量比例】","c":"想到【物块滑到板端时对地位移满足 $x_P=x_Q+L$；摩擦力对两物体做功绝对值之比=对地位移之比，本题 $3:1$；物块减少动能:摩擦生热 $=x_P:(x_P-x_Q)=3:2$；木板增加动能:系统损失机械能 $=x_Q:(x_P-x_Q)=1:2$，系统损失机械能=摩擦生热】；警惕【P、Q间的摩擦力是相互作用力，大小之比为 $1:1$、与质量无关；系统损失机械能不等于物块损失的动能】","src":"跳跳物一轮06.7 功能关系_笔记","note":"视频|33:23","orig":"（例）光滑水平面上长L的木板Q静止，物块P以初速度滑上Q，P恰好滑到Q最右端时Q的位移为L/2，求摩擦力对P、Q做功绝对值之比及各能量比例。","link":""},{"id":"phy2340","t":"功能关系·恒力作用下弹簧连接体的机械能与速度极值","s":"看到【两物体夹弹簧受恒力往复运动，问机械能变化或速度最大的时刻】","c":"想到【恒力是外力且始终做功，机械能不守恒并呈周期性变化；两物体朝使弹簧伸长的方向运动时外力做正功、机械能增加，弹簧伸长到最长时系统机械能最大；弹力大小与外力大小相等时加速度为零、速度最大，加速和减速阶段的速率极值都出现在该位置】；警惕【别以为机械能一直增加，A、B相向运动时外力做负功机械能减少；速度最大不出现在弹簧原长处】","src":"跳跳物一轮06.7 功能关系_笔记","note":"视频|33:23","orig":"（例）水平面上A、B两物体由轻弹簧连接，分别受恒力 $F_1$、$F_2$ 作用做往复的加速减速运动，判断机械能是否守恒、何时机械能最大、何时速度最大。","link":""},{"id":"phy2341","t":"机械能守恒定律·守恒条件与系统内绳子拉力","s":"看到【判断绕过滑轮的绳连接体或含弹簧系统的机械能是否守恒】","c":"想到【只有重力和系统内弹力做功，系统机械能就守恒；系统内绳子的拉力属于系统内弹力，其做功不影响守恒；判断前必须先圈定研究对象，系统选不同结论可能不同：A、B取为一个系统时守恒，只取A时绳拉力变成其他力做功，A的机械能不守恒】；警惕【系统内的滑动摩擦力不是弹力，它做功照样破坏守恒；不明确系统就下守恒结论】","src":"跳跳物一轮06.8 机械能守恒定律_笔记","note":"视频|02:27-02:50","orig":"（知识）机械能守恒的条件，及系统内绳子拉力、系统选取对判断的影响。","link":""},{"id":"phy2342","t":"机械能守恒定律·合外力为零与存在其他力的两个误区","s":"看到【系统合外力为零，或存在其他力（如墙对弹簧的作用力），判断守恒】","c":"想到【判据只有一条：其他力（除重力和系统内弹力外）是否做功；光滑地面物块冲上粗糙木板，物块+木板合外力为零，但系统内滑动摩擦力做功生热，机械能不守恒；弹簧一端固定在墙上，墙对弹簧的弹力虽是其他力，但作用点位移始终为零、不做功，系统机械能守恒】；警惕【把合外力为零当成守恒条件；见到其他力就断定不守恒，应先查它做不做功】","src":"跳跳物一轮06.8 机械能守恒定律_笔记","note":"视频|02:50","orig":"（知识）用其他力是否做功（而非合外力、是否有其他力）判断机械能守恒。","link":""},{"id":"phy2343","t":"机械能守恒定律·机械能守恒与机械能不变的区别","s":"看到【物体在拉力与摩擦力并存下匀速运动，问机械能守恒还是不变】","c":"想到【守恒要求完全没有其他力做功，机械能与其他形式能零转化；不变只要求其他力做的正负功完全抵消、总量不变，如粗糙地面用 $3\\ \\mathrm{N}$ 拉力拉着物体匀速运动，拉力正功与滑动摩擦力负功抵消，机械能不变但不守恒；守恒的条件比不变严格】；警惕【把总量不变说成守恒，匀速运动物体往往只是机械能不变而非守恒】","src":"跳跳物一轮06.8 机械能守恒定律_笔记","note":"视频|09:07","orig":"（知识）机械能守恒与机械能总量不变两个概念的条件差异。","link":""},{"id":"phy2344","t":"机械能守恒定律·连接体机械能守恒一增等于一减","s":"看到【多物体连接体系统机械能守恒，求某物体动能或势能变化量】","c":"想到【系统守恒意味着增加的能量总和等于减少的能量总和，按三步走：一找系统中所有机械能增加的物体，把增量相加得总增加量；二找所有减少的物体，把减量相加得总减少量；三由守恒列总增加量等于总减少量求解未知量；跨定滑轮的轻绳两端速度大小、位移大小都相等】；警惕【漏数某个物体的动能或重力势能变化；单物体优先用动能定理，多物体系统才用守恒法】","src":"跳跳物一轮06.8 机械能守恒定律_笔记","note":"视频|12:15","orig":"（知识）多个物体组成的连接体系统机械能守恒时的解题三步法。","link":""},{"id":"phy2345","t":"机械能守恒定律·非质点链条类问题的处理","s":"看到【铁链、液柱等不能视为质点的物体滑过桌面或斜面，求速度或势能变化】","c":"想到【核心方程是动能变化量大小等于重力势能变化量大小，$|\\Delta E_k|=|\\Delta E_p|$；物体不转动时各部分速度大小相等，动能直接用总质量和共同速度计算；重力势能只算高度发生变化的那一段：把链条分段、每段等效为重心处的质点，高度不变的部分会自动抵消，不要对整体初末重力势能相减】；警惕【整体初末势能相减因重心位置复杂而易错；此类问题无弹簧，没有弹性势能】","src":"跳跳物一轮06.8 机械能守恒定律_笔记","note":"视频|12:15","orig":"（知识）铁链、液柱等非质点物体机械能守恒问题的求解技巧。","link":""},{"id":"phy2346","t":"机械能守恒定律·跨定滑轮连接体的能量转移","s":"看到【绕过定滑轮的A、B连接体由静止释放，求各自机械能变化量或速度】","c":"想到【绳长不变，B下降多少A就上升多少，两端速率时刻相等；系统守恒时一个物体减少的机械能等于其余物体增加的机械能之和，故B减少的机械能等于A增加的机械能；列一增=一减：A动能与A重力势能的增加量之和等于B重力势能的减少量】；警惕【A、B各自的机械能都不守恒（绳拉力分别对它们做功），只有系统守恒；B势能减少量不等于两物动能增加量之和，还差A势能增加量】","src":"跳跳物一轮06.8 机械能守恒定律_笔记","note":"视频|18:00","orig":"（例）质量m的A与质量3m的B用轻绳连接跨过定滑轮，初始两者等高、由静止释放，当两者高度差为2h时，求A、B各自的机械能变化及速率。","link":""},{"id":"phy2347","t":"机械能守恒定律·恰好静止临界与弹簧连接体最大位移","s":"看到【弹簧连接体含恰好保持静止条件，剪断释放后求物块最大位移】","c":"想到【恰好静止即弹簧弹力等于最大静摩擦力，$kx=2\\mu mg$，定出形变量；P与弹簧组成的系统机械能守恒，初末P动能均为零，故初末弹性势能相等、形变量相等，P的最大位移=伸长量+压缩量 $=2x=\\frac{4\\mu mg}{k}$】；警惕【最大位移是两次形变量之和，不是单个形变量；缓慢拉开阶段有拉力做功，不能对该过程用机械能守恒】","src":"跳跳物一轮06.8 机械能守恒定律_笔记","note":"视频|24:02","orig":"（例）光滑水平面上的P（质量m）与粗糙地面上的Q（质量2m、动摩擦因数$\\mu$）经弹簧相连，水平拉力将Q缓慢拉开后撤去，Q恰好保持静止；剪断轻绳后P开始运动，求P的最大位移。","link":""},{"id":"phy2348","t":"机械能守恒定律·轻杆连接体关联速度与机械能转移","s":"看到【两物体被刚性轻杆连接、沿相互垂直的杆滑动，求速度或某物机械能变化】","c":"想到【刚性轻杆不可伸长，两端速度沿杆方向的分量相等：设甲速 $v_1$、乙速 $v_2$，将两速度沿杆和垂直杆分解得 $v_1\\cos 53^\\circ=v_2\\sin 53^\\circ$（角度取杆与各物运动方向的夹角），再与系统机械能守恒方程（甲势能减少量=两物动能增加量）联立解速度；判断甲的机械能转化为看乙：乙在水平杆上势能不变，其机械能变化=动能变化，乙速度从零先增后减（杆水平时甲到最低点、乙速度为零），故乙机械能先增后减、甲机械能先减后增】；警惕【直接令甲、乙速度大小相等列式（两者方向不同，只有沿杆分量相等）；系统守恒不代表每个物体机械能都守恒】","src":"跳跳物一轮06.8 机械能守恒定律_笔记","note":"视频|31:33","orig":"（例）水平杆与竖直杆交于O点，甲（质量2.25 kg）套在竖直杆上、乙（质量1 kg）套在水平杆上，两者用长5 m的轻杆相连；轻杆与水平杆成53°时由静止释放，求轻杆与竖直杆成53°时乙的速度，并判断甲的机械能如何变化。","link":""},{"id":"phy2349","t":"能量守恒定律·无条件成立区别于机械能守恒","s":"看到【问某过程能量守恒是否成立，或机械能不守恒时该用什么规律】","c":"想到【能量既不会消灭也不会创生，只会从一种形式转化为其他形式或从一个物体转移到另一个物体，总量保持不变；能量守恒定律无条件成立、任何过程都适用，做题无需判断；机械能守恒才有条件：必须没有其他力做功】；警惕【浪费时间判断能量守恒是否成立；把能量守恒的无条件性与机械能守恒的有条件性混淆】","src":"跳跳物一轮06.9 能量守恒定律_功与能模块完结撒花~_笔记","note":"视频|00:20","orig":"（知识）能量守恒定律的内容及其与机械能守恒定律的条件差异。","link":""},{"id":"phy2350","t":"能量守恒定律·列式方法输入加初输出加末","s":"看到【板块、传送带或碰撞问题需列能量守恒等式或算系统能量变化】","c":"想到【三步列式：明确系统和初末状态→分别写出初、末状态的总能量→按“初态总能量+外界输入能量=末态总能量+输出到外界的能量”列等式；输入能量加在初状态一侧，输出能量加在末状态一侧，如系统初态总能量 $3\\ \\mathrm{J}$、外界输入 $2\\ \\mathrm{J}$，末态总能量为 $5\\ \\mathrm{J}$】；警惕【输入输出的能量放错一侧；全程在水平面运动时仍把重力势能写进总能量，制造多余未知量】","src":"跳跳物一轮06.9 能量守恒定律_功与能模块完结撒花~_笔记","note":"视频|01:29-04:04","orig":"（知识）板块、传送带、碰撞问题中列能量守恒等式的步骤。","link":""},{"id":"phy2351","t":"传送带模型·水平传送带轻放物体的能量分配","s":"看到【物体轻放在水平传送带上达到共速，问动能、热量或做功关系】","c":"想到【物体先匀加速、与带共速后匀速；加速度由滑动摩擦力提供 $a=\\mu g$，与传送带速度无关；由 $v$-$t$ 图可知加速阶段物体对地位移等于物体与传送带的相对位移，故物体增加的动能等于摩擦产生的热量；共速后无相对滑动不再生热】；警惕【认为物体一直匀加速；算热量时误用传送带对地位移】","src":"跳跳物一轮06.9 能量守恒定律_功与能模块完结撒花~_笔记","note":"视频|05:45","orig":"（知识）物体轻放在水平传送带上直至共速的运动与能量关系。","link":""},{"id":"phy2352","t":"传送带模型·倾斜传送带对物体做功","s":"看到【物体沿倾斜传送带被运送到高处，求传送带对物体做的功】","c":"想到【传送带对物体做的功等于物体机械能的变化量：物体动能增加 $\\frac{1}{2}mv^2$、重力势能增加 $mgh$，故做功为 $mgh+\\frac{1}{2}mv^2$；物体随带向上加速阶段的加速度 $a=\\mu g\\cos\\theta-g\\sin\\theta$（摩擦力沿带向上时）】；警惕【把传送带对物体做的功当成摩擦生热或只算动能增量而漏重力势能；倾斜传送带照搬水平传送带的 $a=\\mu g$】","src":"跳跳物一轮06.9 能量守恒定律_功与能模块完结撒花~_笔记","note":"视频|12:37","orig":"（知识）物体沿倾斜传送带向上被运送时传送带对物体做的功。","link":""},{"id":"phy2353","t":"板块模型·共速过程摩擦生热等于系统动能损失","s":"看到【物块滑上木板最终共速，求摩擦生热或共速速度（常配前置轨道）】","c":"想到【地面光滑时物块与木板系统动量守恒，$m_1v_1=(m_1+m_2)v_2$（$v_2$ 为共速速度）；再对共速过程列能量守恒：系统初动能=系统末动能+摩擦生热，即摩擦生热=系统初动能-系统末动能；物块在前置轨道上的入板速度先用动能定理求：重力做功与摩擦力做功之和等于动能变化】；警惕【共速后相对滑动停止、不再生热；把重力势能写进水平面系统的总能量表达式】","src":"跳跳物一轮06.9 能量守恒定律_功与能模块完结撒花~_笔记","note":"视频|19:20","orig":"（例）物块沿粗糙圆弧轨道从A滑到底端B后，滑上光滑水平地面上的静止木板，最终与木板共速，求A到B过程克服摩擦力做的功及系统的摩擦生热。","link":""},{"id":"phy2354","t":"传送带模型·电动机多消耗电能的组成","s":"看到【求传送带电动机多消耗的电能或额外做的功】","c":"想到【以物体+传送带为系统列能量守恒：多消耗电能=物体增加的机械能+摩擦生热；水平传送带运送物体为 $\\frac{1}{2}mv^2+Q$，倾斜传送带送上高处为 $mgh+\\frac{1}{2}mv^2+Q$；因摩擦生热恒为正，多耗电能必大于物体增加的动能】；警惕【漏加摩擦生热；把电动机额外做功当成等于传送带对物体做的功，后者不含生热部分】","src":"跳跳物一轮06.9 能量守恒定律_功与能模块完结撒花~_笔记","note":"视频|12:37","orig":"（知识）传送带把物体从一处运送到另一处时电动机多消耗电能的构成。","link":""},{"id":"phy2355","t":"动量·定义、矢量性与比大小规则","s":"看到【给出质量与速度求动量，或比较带正负号的动量大小】","c":"想到【动量$p=mv$，方向与速度方向一致，单位$\\mathrm{kg\\cdot m/s}$；动量是矢量，比大小只比绝对值，正负号仅表示方向、不参与大小比较】；警惕【把负动量当成小动量，$-6\\ \\mathrm{kg\\cdot m/s}$其实比$2\\ \\mathrm{kg\\cdot m/s}$大；标量比大小不能一概而论，温度的正负号参与比较而功的正负号不参与】","src":"跳跳物一轮07.1 动量、冲量、动量定理_笔记","note":"视频|00:33-01:23","orig":"（知识）动量是描述物体运动状态的矢量，来源于碰撞实验中守恒量的研究。","link":""},{"id":"phy2356","t":"冲量·定义与计算规则","s":"看到【计算某个力的冲量，或比较一对相互作用力的冲量大小】","c":"想到【冲量$I=F\\cdot t$，方向与力的方向一致，单位$\\mathrm{N\\cdot s}$；公式只适用于恒力，变力需用平均力计算；同一段时间内，一对相互作用力或一对平衡力的冲量等大反向】；警惕【计算冲量只看力和时间，与力跟速度的夹角无关，不要把力分解为$F\\cos\\theta$再乘时间；物体静止不代表每个力的冲量为零】","src":"跳跳物一轮07.1 动量、冲量、动量定理_笔记","note":"视频|03:59","orig":"（知识）冲量是力与作用时间的乘积，是矢量。","link":""},{"id":"phy2357","t":"动量定理·合力冲量与正方向设定","s":"看到【用动量定理求冲量或动量变化，涉及多个力和初末速度方向】","c":"想到【合力的冲量等于动量变化量，即$I=\\Delta p$（末动量减初动量）；列式前必须先设正方向，与正方向同向的力和速度取正、反向取负；被拉未动的箱子动量变化为零，是因为摩擦力使合力为零、合力冲量为零】；警惕【把某个分力的冲量当成合力冲量，箱子未动时拉力的冲量并不为零】","src":"跳跳物一轮07.1 动量、冲量、动量定理_笔记","note":"视频|07:32","orig":"（知识）动量定理描述合力的冲量与动量变化量的关系。","link":""},{"id":"phy2358","t":"动量与动能·关系辨析","s":"看到【由动量相同推断动能相同，或由速度大小不变推断动量不变】","c":"想到【动量是矢量，由速度大小和方向共同决定；动能是标量，只由速率决定；动量相同动能不一定相同，动能大动量也不一定大；速度大小不变而方向改变时，动量变化量不为零，如匀速圆周运动半圈动量变化量大小为$2mv$】；警惕【匀速圆周运动动能不变但动量时刻变化；转整圈回到起点时初末动量相同，动量变化量为零】","src":"跳跳物一轮07.1 动量、冲量、动量定理_笔记","note":"视频|13:06","orig":"（知识）动量与动能是描述运动的两个不同物理量，无必然大小对应关系。","link":""},{"id":"phy2359","t":"超重与失重·判断依据","s":"看到【物体沿竖直方向运动，判断某阶段超重还是失重】","c":"想到【只看竖直方向加速度：加速度向上为超重，向下为失重，为零则既不超重也不失重；螺旋匀速下降的物体竖直方向匀速、加速度为零，既不失重也不超重】；警惕【把速度方向当判断依据，向上减速实为失重、向下减速实为超重】","src":"跳跳物一轮07.1 动量、冲量、动量定理_笔记","note":"视频|10:11","orig":"（知识）超重失重的判断只取决于加速度方向，与速度方向无关。","link":""},{"id":"phy2360","t":"动量定理·（例）冷发射火箭的最大动能与冲量判断","s":"看到【火箭被弹射后先加速后减速，判断加速度为零时刻的动能，或某力冲量与动量变化的关系】","c":"想到【推力减小到等于重力加阻力时合力为零、加速度为零，此刻速度最大、动能最大；由动量定理，推力、重力、阻力冲量的代数和等于动量变化量；由动能定理，三力功的代数和等于动能变化量】；警惕【说推力冲量等于动量增加量时漏掉重力和阻力的冲量；说推力与阻力做功之和等于动能增量时漏掉重力做功】","src":"跳跳物一轮07.1 动量、冲量、动量定理_笔记","note":"视频|28:50","orig":"（例）山东2022真题：火箭冷发射，靠高压气体向上的推力从静止弹出，升到最高点速度减为零时点火，判断加速度为零时动能是否最大、推力冲量是否等于动量增加量等。","link":""},{"id":"phy2361","t":"动量定理·（例）垫球往返的平抛与冲量计算","s":"看到【垫球或击球前后速度等大反向，求水平射程、落地速度和作用冲量】","c":"想到【平抛阶段由下落高度$h_1-h_2=\\frac{1}{2}gt^2$求时间，$x=v_0t$求射程，末速度$v=\\sqrt{v_0^2+v_y^2}$；垫球过程用动量定理，设原速度方向为正，$I=-mv-mv=-2mv$，负号表示方向与正方向相反，大小取$2mv$】；警惕【不设正方向把末动量也写成正的，冲量会错成零；题目求冲量大小，最后须取绝对值】","src":"跳跳物一轮07.1 动量、冲量、动量定理_笔记","note":"视频|32:58","orig":"（例）北京2022真题：排球从高2.5 m处以初速度8.0 m/s水平飞出，落到离地0.7 m处被乙垫起，垫起前后速度大小相等方向相反，求水平飞行距离、垫起前速度及垫球过程冲量大小。","link":""},{"id":"phy2362","t":"动量定理·解题三步法","s":"看到【对某物体某段过程列动量定理求冲量、平均力或速度】","c":"想到【三步法：①明确研究对象和过程，分析该过程受力与初末速度；②设正方向，与正方向反向的力和速度前都要加负号；③合力冲量（各力冲量的代数和）等于动量变化量（末动量减初动量），列出等式求解】；警惕【不设正方向直接代数值导致符号混乱；把单个力的冲量当成合力冲量，合力冲量是各力冲量之和】","src":"跳跳物一轮07.2 F-t图、缓冲问题、流体冲击问题_笔记","note":"视频|00:23","orig":"（知识）用动量定理解题有一套固定步骤。","link":""},{"id":"phy2363","t":"动量定理·F-t图面积与冲量","s":"看到【给出力F随时间t变化的图线，求冲量或动量变化量】","c":"想到【$F$-$t$图面积表示该力的冲量，横轴上方为正冲量、下方为负冲量，总冲量=上方面积-下方面积；若$F$是合力，面积还同时等于动量变化量；求某段时间冲量只算该时间段的面积】；警惕【粗糙面上$F$不是合力时，面积只代表$F$自己的冲量，不能当作动量变化量；上下面积方向相反要抵消，不能直接相加】","src":"跳跳物一轮07.2 F-t图、缓冲问题、流体冲击问题_笔记","note":"视频|03:00","orig":"（知识）F-t图线与横轴围成的面积有明确物理意义。","link":""},{"id":"phy2364","t":"动量定理·缓冲过程的时间与平均力","s":"看到【物体落到软垫、沙地等缓冲物上减速到零，求平均作用力或缓冲时间】","c":"想到【对缓冲过程列动量定理，如竖直下落：$mgt-Ft=0-mv_0$（$F$为平均支持力）；缓冲物越软，缓冲时间越长、平均作用力越小，所以软地面摔不坏东西；合力冲量和动量变化量只由初速度决定，与缓冲物软硬无关】；警惕【支持力是变力，必须用平均力算冲量；只有水平面上运动或冲击力远大于重力时才能忽略重力，竖直下落情形重力冲量不能丢】","src":"跳跳物一轮07.2 F-t图、缓冲问题、流体冲击问题_笔记","note":"视频|03:00-16:45","orig":"（知识）缓冲是运动的物体在缓冲物作用下减速到零的过程。","link":""},{"id":"phy2365","t":"动量定理·流体冲击的柱体模型","s":"看到【水流或气流冲击墙面、风洞等，求流体对物体的平均作用力】","c":"想到【取$\\Delta t$时间内与障碍物碰撞的柱形流体为对象，柱长$l=v\\Delta t$，质量$m=\\rho Sv\\Delta t$；沿流速方向列动量定理，水不反弹时$-F\\Delta t=0-mv$，解得$F=\\rho Sv^2$，再由牛顿第三定律得流体对墙的平均作用力】；警惕【$F=\\rho Sv^2$依赖碰后沿墙流下不反弹的条件，若流体反弹公式就不同，必须现场推导不能死记结论】","src":"跳跳物一轮07.2 F-t图、缓冲问题、流体冲击问题_笔记","note":"视频|41:42","orig":"（知识）水流、气流冲击墙面等连续流体问题用柱体模型处理。","link":""},{"id":"phy2366","t":"动量定理·（例）光滑面F-t图的多选项判断","s":"看到【光滑面上给出合力F-t图，判断各时刻动量、位移、功率或某段冲量】","c":"想到【合力$F$-$t$图面积=动量变化量：0~2s面积为正动量增大，全程正负面积相等则末速度为零；但物体全程速度同向未掉头，位移一直增大，不可能回到出发点；功率$P=Fv$用端点法：两端时刻$F=0$则$P=0$，中间必有先增大后减小】；警惕【把总冲量为零推成回到出发点，速度为零不等于位移为零，物体未掉头就一直朝一个方向走】","src":"跳跳物一轮07.2 F-t图、缓冲问题、流体冲击问题_笔记","note":"视频|16:45","orig":"（例）光滑水平面上质点受合力F，F-t图0~2s为正向（先增大后减小回到零）、2~4s为负向且正负面积相等，判断第2s末动量、第4s末是否回到出发点、0~2s内功率变化、1~3s内冲量。","link":""},{"id":"phy2367","t":"动量定理·（例）粗糙面上F-t图与启动时刻","s":"看到【粗糙面上拉力随时间增大，用F-t图求物体开始运动时刻或末速度】","c":"想到【先求最大静摩擦力$f=\\\\mu mg$，令$F$等于它解出启动时刻，此前物体一直静止；启动后对这段时间列动量定理：拉力冲量（$F$-$t$图面积）减摩擦力冲量等于动量变化量，解出末速度】；警惕【$F$-$t$图面积只是拉力的冲量，粗糙面上还要减去摩擦力冲量才是动量变化量；物体并非从$t=0$就开始运动，冲量要从启动时刻算起】","src":"跳跳物一轮07.2 F-t图、缓冲问题、流体冲击问题_笔记","note":"视频|21:56","orig":"（例）粗糙水平面上质量1 kg的物块受水平拉力F，F随时间从0.8 N起线性增大（F=1.2t+0.8），动摩擦因数0.1，判断物块开始运动的时刻并求某时刻的速度。","link":""},{"id":"phy2368","t":"动�量定理·（例）风洞悬浮的气流速度","s":"看到【人悬浮在竖直向上的气流中，求气流速度或冲击力】","c":"想到【悬浮说明气流对人的冲击力$F=mg$；取$\\\\Delta t$内与人体作用的气柱为对象，质量$m'=\\\\rho Sv\\\\Delta t$，碰后速度为零，由动量定理$mg\\\\cdot\\\\Delta t=m'v=\\\\rho Sv^2\\\\Delta t$，约去$\\\\Delta t$得$mg=\\\\rho Sv^2$，解出$v=\\\\sqrt{mg/(\\\\rho S)}$】；警惕【研究对象是气柱不是人，列定理时用牛顿第三定律转换；碰后速度为零是题目条件，与水冲击墙不反弹的模型同类，条件变了结论就变】","src":"跳跳物一轮07.2 F-t图、缓冲问题、流体冲击问题_笔记","note":"视频|41:42","orig":"（例）风洞实验中游客悬浮在竖直向上的气流里，气流密度$\\rho$、与人体作用的截面积S，气柱碰到人后速度变为零，求气流速度v的大小。","link":""},{"id":"phy2369","t":"动量守恒·定律内容与守恒条件","s":"看到【判断一个系统的动量是否守恒，或列守恒方程】","c":"想到【系统不受外力或所受外力的矢量和为零时，系统总动量保持不变；如光滑地面上的板块系统，竖直方向重力与支持力抵消、水平方向无外力，动量守恒；判断时先圈定系统和研究过程，再看外力】；警惕【只对单个物体谈守恒，动量守恒是对系统整体说的；系统选取不同结论可能不同】","src":"跳跳物一轮07.3 动量守恒定律_笔记","note":"视频|00:20","orig":"（知识）动量守恒定律描述系统总动量保持不变的条件。","link":""},{"id":"phy2370","t":"动量守恒·与机械能守恒的关系对比","s":"看到【同时判断系统的动量守恒与机械能守恒】","c":"想到【两者互不相关：光滑地面上物块冲上粗糙木板，合外力为零动量守恒，但滑动摩擦生热机械能不守恒；弹簧一端固定在墙上的物块系统，只有重力和弹力做功机械能守恒，但墙对弹簧有外力动量不守恒】；警惕【把两个守恒条件混淆，由动量守恒推机械能守恒，或反过来推】","src":"跳跳物一轮07.3 动量守恒定律_笔记","note":"视频|00:45-03:27","orig":"（知识）动量守恒与机械能守恒没有必然联系，两个反例模型必须掌握。","link":""},{"id":"phy2371","t":"动量守恒·某方向合外力为零则该方向守恒","s":"看到【光滑地面上斜面滑块或小车摆球系统，问动量是否守恒】","c":"想到【合外力不为零总动量不守恒，但某方向合外力为零则该方向动量分量守恒；斜面滑块、小车摆球模型中竖直方向有加速度、动量变化，水平方向地面光滑无外力，水平方向动量守恒】；警惕【笼统地说系统动量守恒，正确说法是水平方向动量守恒；竖直方向动量明显在变化】","src":"跳跳物一轮07.3 动量守恒定律_笔记","note":"视频|07:06","orig":"（知识）系统总动量不守恒时，仍可能某一方向的动量守恒。","link":""},{"id":"phy2372","t":"动量守恒·时间极短的近似守恒情形","s":"看到【碰撞、爆炸或子弹打木块过程，判断能否用动量守恒】","c":"想到【过程时间极短时合外力冲量极小可忽略，动量近似守恒：碰撞无论地面是否粗糙都行（摩擦力冲量可忽略），爆炸（重力冲量可忽略），子弹打木块，高中阶段可直接列动量守恒】；警惕【把迅速当成时间极短：人推木箱动作远慢于碰撞，不能无脑用守恒，须如实分析外力】","src":"跳跳物一轮07.3 动量守恒定律_笔记","note":"视频|08:42","orig":"（知识）碰撞、爆炸等时间极短的过程可近似认为动量守恒。","link":""},{"id":"phy2373","t":"动量守恒·列守恒等式的方向约定","s":"看到【两球碰撞前后速度方向不全相同，要列动量守恒方程】","c":"想到【先设正方向，与正方向同向的速度取正、反向取负，再列碰前总动量等于碰后总动量，如$-m_1v_1+m_2v_2=m_1v_1'+m_2v_2'$；系统要包含所有参与相互作用的物体】；警惕【速度反向时忘记带负号；等式两边必须对同一系统在同一时刻求和，速度都是相对同一参考系】","src":"跳跳物一轮07.3 动量守恒定律_笔记","note":"视频|10:30","orig":"（知识）列动量守恒等式前必须先设正方向。","link":""},{"id":"phy2374","t":"动量守恒·（例）子弹打木块后压缩弹簧的分阶段判断","s":"看到【子弹打木块后接着压缩墙上弹簧，判断各阶段两守恒】","c":"想到【分阶段分析：子弹打物块阶段时间极短，弹簧弹力冲量可忽略，动量守恒，但钻入过程摩擦生热机械能不守恒；压缩弹簧阶段墙对弹簧有外力，动量不守恒；包含两个阶段的全过程动量也不守恒】；警惕【对全过程整体套用动量守恒；认为子弹钻入物块阶段机械能守恒（漏摩擦生热）】","src":"跳跳物一轮07.3 动量守恒定律_笔记","note":"视频|14:07","orig":"（例）光滑水平面上子弹射入物块并留在其中，随后子弹与物块一起压缩一端固定在墙上的弹簧，判断各阶段动量守恒与机械能守恒的选项。","link":""},{"id":"phy2375","t":"动量守恒·（例）火箭喷气的反冲速度","s":"看到【火箭喷气反冲，已知喷出燃气质量和速度，求火箭速度或上升高度】","c":"想到【喷气时间极短系统动量守恒，设向上为正：$0=(M-m)v-mv_0$，解得$v=\\frac{mv_0}{M-m}$；之后竖直上抛，最大高度$h=\\frac{v^2}{2g}$；喷气后上升阶段受重力合外力不为零，动量不守恒且燃气推力做功机械能不守恒】；警惕【上升阶段继续用动量守恒；算高度漏掉$2g$分母里的2；燃气动量与火箭反向，列式漏负号】","src":"跳跳物一轮07.3 动量守恒定律_笔记","note":"视频|22:24","orig":"（例）万户飞天：总质量M（含质量m的燃气）的火箭从静止开始竖直向下喷出燃气，燃气速度大小v$_0$，求火箭反冲速度及此后上升的最大高度，并判断各过程守恒情况。","link":""},{"id":"phy2376","t":"动量守恒·（例）车内挥锤的水平零动量模型","s":"看到【光滑面上人站车内挥锤敲车，判断车往哪动、何时停】","c":"想到【系统水平方向不受外力，水平动量守恒且初始为零：锤有向右的水平分动量时，人与车必向左运动产生反向动量抵消；锤停止运动水平动量为零时，人与车也必须停止；整体来回摆动，不会持续单向运动】；警惕【认为车会持续向右或向左运动，与初始水平总动量为零矛盾；竖直方向动量并不守恒，只水平方向守恒】","src":"跳跳物一轮07.3 动量守恒定律_笔记","note":"视频|26:46","orig":"（例）光滑水平面上人站在小车上，反复水平挥动锤子敲打小车，判断锤子挥动时和停下后人与车的运动情况。","link":""},{"id":"phy2377","t":"反冲模型·经典反冲核心方程与动量矢量性","s":"看到【原本静止的系统在内力作用下分裂成两部分反向运动，求两者速度或动量关系】","c":"想到【初动量为零且合外力为零，动量守恒给出 $M_1V_1=M_2V_2$，即任意时刻两部分动量大小相等、方向相反；内力对两部分都做正功，系统动能增加，增量来自化学能、弹性势能等能量的转化】；警惕【不能说“任意时刻两物体动量相同”——动量是矢量，二者等大反向；方程中 $V_1$、$V_2$ 均取速率（标量），列式前先设正方向】","src":"跳跳物一轮07.4 反冲模型_笔记","note":"视频|01:36","orig":"（知识）静止系统在合外力为零时靠内力分裂成两部分反向运动，即经典反冲模型。","link":""},{"id":"phy2378","t":"反冲模型·反冲前不静止的变式","s":"看到【两人抱在一起匀速滑行（或系统已有初速度）后互相推开，求分开后各自速度】","c":"想到【系统初动量不为零，经典反冲的 $M_1V_1=M_2V_2$ 不再成立；应以系统原运动方向为正方向，列完整动量守恒方程：初动量（总质量×共同初速）等于分开后各部分动量的代数和】；警惕【仍套用 $M_1V_1=M_2V_2$，漏掉初速度，相当于凭空消灭了系统动量】","src":"跳跳物一轮07.4 反冲模型_笔记","note":"视频|04:22","orig":"（知识）系统在反冲前整体已具有一定速度（非静止）的反冲变式。","link":""},{"id":"phy2379","t":"反冲模型·总动量不守恒但某方向守恒的分量法","s":"看到【系统在下落、沿斜面滑动等过程中发生反冲或相对移动，但存在一个不受外力的方向】","c":"想到【总动量不守恒，但不受外力的方向上动量守恒，只对该方向列动量守恒（或人船）方程；方程中的速度、位移一律取该方向的分量，如自由落体中互推只看水平方向，物块沿光滑斜面下滑只看水平方向】；警惕【把该方向的分量误当作合速度、合位移代入，或直接断言系统总动量守恒】","src":"跳跳物一轮07.4 反冲模型_笔记","note":"视频|04:22","orig":"（知识）系统合外力不为零，但某特定方向不受外力的反冲变式（如自由落体中互推）。","link":""},{"id":"phy2380","t":"反冲模型·剧烈反冲的守恒判定与减质量","s":"看到【爆炸、火箭（章鱼）喷水喷气，或明示“时间极短”的分裂过程，求分裂后速度】","c":"想到【时间极短则重力冲量可忽略，直接认定系统动量守恒；喷射主体末状态的质量必须减去喷出物质量，系统初静止时有 $(M-m)v_1=mv_0$，解得 $v_1=\\frac{mv_0}{M-m}$】；警惕【火箭末质量仍取原质量 $M$、忘记扣掉喷出的 $m$，速度必然算错】","src":"跳跳物一轮07.4 反冲模型_笔记","note":"视频|06:20","orig":"（知识）爆炸、火箭喷气类时间极短的剧烈反冲过程的处理原则。","link":""},{"id":"phy2381","t":"反冲模型·人船模型三个核心方程","s":"看到【光滑水平面上初始静止的系统，一部分相对另一部分移动，求各自对地位移】","c":"想到【人船模型三方程：①$M_1V_1=M_2V_2$，任意时刻两者动量大小相等；②速度比恒定，故对地位移之比等于质量反比 $X_1/X_2=M_2/M_1$；③两者对地位移之和等于相对位移（人从船一端走到另一端时 $X_1+X_2=L$），联立②③即可解各位移】；警惕【$X_1$、$X_2$ 必须是对地位移而非相对位移；水对船的阻力一律默认忽略，这是隐含条件，不依赖题目说明】","src":"跳跳物一轮07.4 反冲模型_笔记","note":"视频|04:22-06:20","orig":"（知识）人在静止的船上行走、船同时后退的人船模型位移规律。","link":""},{"id":"phy2382","t":"反冲模型·圆弧轨道接粗糙水平面的人船模型综合题","s":"看到【光滑圆弧接粗糙水平段的小车在光滑地面，滑块下滑后与小车相对静止，求水平段长度或位移】","c":"想到【全过程水平方向动量守恒且始末系统均静止，重力势能全部转化为摩擦生热：$mgR=\\mu mgL$，得 $L=\\frac{R}{\\mu}$；水平方向套人船模型：滑块与小车对地位移之比等于质量反比，水平相对位移$=R+L$，故小车对地位移=滑块质量/(系统总质量)$\\times(R+L)$】；警惕【下滑阶段竖直方向有加速度，系统总动量不守恒，只有水平方向守恒；滑块机械能也不守恒，小车被带动获得了动能】","src":"跳跳物一轮07.4 反冲模型_笔记","note":"视频|04:22-06:20","orig":"（例）小车静置于光滑地面，车上有光滑圆弧轨道（半径 $R=1$ m）与粗糙水平段平滑连接（动摩擦因数 $\\mu=0.5$），小车质量是滑块的 4 倍。滑块从圆弧顶由静止下滑，最终相对小车停于水平段。判断系统动量与滑块机械能是否守恒，并求水平段长度 $L$ 与小车全程对地位移。","link":""},{"id":"phy2383","t":"反冲模型·抛物防撞的共速临界与方法选择","s":"看到【光滑水平面上两人相向运动将相撞，靠互扔物体改变速度，问恰好不相撞的条件】","c":"想到【不相撞的临界状态是甲、乙、物体三者最终共速（速度同向等大），共速方向由系统总动量方向决定；求临界共速速度时，若不要求物体被扔出后的速度，对三人（含物体）全程列一个动量守恒方程即可，若要求物体速度则须对甲扔物、乙接物分阶段各列方程】；警惕【把最终速度方向相反当作不相撞临界——反向虽不相撞但不是临界；用全程方程求不出物体被扔出的速度，两种列法要按需选择】","src":"跳跳物一轮07.4 反冲模型_笔记","note":"视频|04:22-06:20","orig":"（知识）光滑水平面上两人相向运动，通过相互扔、接物体改变速度以避免相撞。","link":""},{"id":"phy2384","t":"反冲模型·水火箭变力下的动量定理","s":"看到【喷水火箭升空后受与速度成正比的变阻力，上升又下落，问最大速度或总飞行时间】","c":"想到【最大速度就是喷水结束瞬间的速度，由 $(M-m)v_1=mv_0$ 得 $v_1=\\frac{mv_0}{M-m}$；喷水阶段加速上升超重、喷完后减速上升失重，并非一直超重；受 $F=kv$ 阻力的阶段非匀变速，改用动量定理：平均阻力=k×平均速度，故该阶段平均阻力×时间=k$\\timesh$（$h$ 为该阶段上升或下落的高度），对上升、下落各列一个动量定理方程，相减消去含 $h$ 项即得总时间】；警惕【对变力过程套用匀变速公式；最大速度时刻找错（不在最高点而在喷水结束瞬间）；误认为火箭全程超重】","src":"跳跳物一轮07.4 反冲模型_笔记","note":"视频|19:46","orig":"（例）总质量 $M$ 的水火箭静置地面，喷出质量 $m$、速度大小 $v_0$ 的水后升空（喷水时间极短），此后火箭（质量 $M-m$）只受与速度成正比的空气阻力，升至最高点后落回原处。求最大速度、判断超重失重，并给出求总飞行时间的方法。","link":""},{"id":"phy2385","t":"碰撞·碰撞的瞬时性特点","s":"看到【两物体碰撞（时间极短），问碰后速度或碰撞瞬间对周围物体的作用】","c":"想到【碰撞时间极短，合外力冲量可忽略，系统动量守恒；碰撞瞬间物体位移可忽略，碰撞结束前不会对周围物体产生影响（相连的弹簧不被压缩、板上的物块间无摩擦）；速度可视为在碰撞结束瞬间发生突变】；警惕【动量守恒的对象是参与碰撞物体组成的系统而非单个物体——小球碰地面须把地球并入系统才守恒】","src":"跳跳物一轮07.5 碰撞、折合质量法_笔记","note":"视频|00:20","orig":"（知识）碰撞过程持续时间极短带来的三个简化特点。","link":""},{"id":"phy2386","t":"碰撞·碰撞分类与默认正碰","s":"看到【题目给出碰撞情景但未说明碰撞类型，要求判断类型或默认处理方式】","c":"想到【按速度方向分：正碰（对心碰撞）碰前两球速度沿球心连线、所有速度共线，斜碰则不在连线上，题目无特殊说明一律按正碰处理；按能量损失分：弹性碰撞无能量损失、非弹性碰撞有损失、完全非弹性碰撞碰后共速（粘在一起）】；警惕【正碰与弹性碰撞没有必然联系——正碰只描述速度方向，不决定有无能量损失】","src":"跳跳物一轮07.5 碰撞、折合质量法_笔记","note":"视频|07:03","orig":"（知识）碰撞按速度方向与按能量损失两种分类方式。","link":""},{"id":"phy2387","t":"碰撞·正碰双守恒方程","s":"看到【一维正碰已知碰前速度与质量，求碰后速度或能量损失】","c":"想到【动量守恒：$M_1V_1+M_2V_2=M_1V_1'+M_2V_2'$；能量守恒：$\\frac{1}{2}M_1V_1^2+\\frac{1}{2}M_2V_2^2=\\frac{1}{2}M_1V_1'^2+\\frac{1}{2}M_2V_2'^2+$E损，E损 为损失的能量、加在末态一侧；弹性碰撞 E损=0 即动能守恒，完全非弹性碰撞碰后共速、动量方程为两物动量之和等于总质量乘共速速度】；警惕【该动量方程只适用于一维正碰，斜碰不能单用它；能量方程漏加 E损 会把非弹性碰撞误当弹性碰撞】","src":"跳跳物一轮07.5 碰撞、折合质量法_笔记","note":"视频|09:46","orig":"（知识）一维正碰的动量守恒与能量守恒联立方程组。","link":""},{"id":"phy2388","t":"折合质量法·损失能量公式与相对速度判定","s":"看到【碰后两物体粘在一起（共速），求碰撞损失的机械能】","c":"想到【E损=$\\frac{1}{2}\\times$M并×V相$^2$，其中折合质量 M并$=\\frac{M_1M_2}{M_1+M_2}$，类比电阻并联“上乘下加”记忆；V相 为碰前两球相对速度：同向运动取速率之差、反向运动取速率之和（如同向速率 3、2 相减得 1，反向速率 2、3 相加得 5）】；警惕【该公式只适用于碰后共速的完全非弹性碰撞，弹性碰撞或一般非弹性碰撞套用必错】","src":"跳跳物一轮07.5 碰撞、折合质量法_笔记","note":"视频|12:48-14:35","orig":"（知识）完全非弹性碰撞中损失机械能的折合质量法公式及相对速度算法。","link":""},{"id":"phy2389","t":"折合质量法·计算题中的双轨答题策略","s":"看到【计算题中完全非弹性碰撞需求损失的能量，双守恒方程联立繁琐】","c":"想到【答题卡上先规范列出动量守恒与能量守恒双守恒方程拿下过程分，再在草稿纸上用折合质量法 E损=$\\frac{1}{2}$$\\times$M并×V相$^2$ 直接算出答案，最后在答题卡双守恒方程下方写“解得：”直接给出结果，既保过程分又省去解方程时间】；警惕【只写折合质量法结果而不在答题卡列双守恒方程会丢过程分；其他类型碰撞的损失能量仍须老老实实联立双守恒求解】","src":"跳跳物一轮07.5 碰撞、折合质量法_笔记","note":"视频|15:22-16:13","orig":"（知识）计算题中用折合质量法兼顾过程分与速度的答题策略。","link":""},{"id":"phy2390","t":"碰撞·碰后速度方向未知的类型判断","s":"看到【已知一球碰后速度与两球质量，另一球碰后速度方向未知，需判断碰撞类型】","c":"想到【方向未知先按正方向假设代入动量守恒解出该球速度，负号即表示反弹；判断类型：碰后未共速排除完全非弹性碰撞，比较碰前碰后总动能（碰前大则有损失）排除弹性碰撞；动量变化按末动量减初动量并带正负号计算】；警惕【速度方向未先设正方向直接按同向代入，解不出负值会误判类型；判断弹性碰撞只看有无动能损失，不能只看是否反弹】","src":"跳跳物一轮07.5 碰撞、折合质量法_笔记","note":"视频|19:51","orig":"（例）A（0.1 kg、2 m/s）与静止的 B（0.2 kg）正碰后，B 以 1.2 m/s 沿原方向运动，求 A 的碰后速度、判断碰撞类型并求 A 的动量变化。","link":""},{"id":"phy2391","t":"折合质量法·完全非弹性碰撞求质量与损失能量","s":"看到【x-t 图给出碰撞前后速度，碰后两物合在一起共速，求未知质量与损失的机械能】","c":"想到【先从 x-t 图斜率读出碰前与碰后速度；对系统列动量守恒解出未知质量（碰后总动量=总质量×共速速度）；损失能量用折合质量法：E损=$\\frac{1}{2}$$\\times$M并×V相$^2$，M并 按两质量“上乘下加”计算，V相 取碰前相对速度（一静一动时即运动者的速度）】；警惕【x-t 图须分段取斜率，别把碰后共速段读错；损失的机械能=初动能减末动能，碰后系统仍保留整体共速的动能，不能把初动能全当损失】","src":"跳跳物一轮07.5 碰撞、折合质量法_笔记","note":"视频|25:48","orig":"（例）质量 50 kg 的 A 以 5 m/s 撞上静止的 B，碰后 A 与 B 合在一起以 2 m/s 共同运动，求 B 的质量与碰撞损失的机械能。","link":""},{"id":"phy2392","t":"碰撞·购物车嵌套综合计算题","s":"看到【完全非弹性碰撞前后衔接匀减速运动与推力做功的综合计算题，多过程多对象】","c":"想到【分过程拆解：嵌套后整体匀减速，用 $L=\\frac{1}{2}aT^2$ 求滑行时间，共速速度=加速度×时间；两车质量相等，碰前速度=2×共速速度；碰撞损失能量答题卡列双守恒方程、草稿纸用折合质量法 E损=$\\frac{1}{2}\\times$M并×V相$^2$；对第一辆车被推阶段用动能定理：人的功-阻力功=末动能增量】；警惕【嵌套后仍按单车质量算摩擦（整体质量已加倍）；列被推阶段动能定理时漏掉阻力功，或把碰后滑行距离与被推距离混淆】","src":"跳跳物一轮07.5 碰撞、折合质量法_笔记","note":"视频|29:01","orig":"（例）质量均为 16 kg 的两辆购物车置于平直路面，路面摩擦使车匀减速。工人推第一辆车使其前进 1 m 时达到 5 m/s，随即与静止的第二辆车碰撞并嵌套在一起，整体再滑行 1.25 m 停下，减速大小 2.5 m/s$^2$。求嵌套后的滑行时间、碰撞损失的机械能与工人对第一辆车做的功。","link":""},{"id":"phy2393","t":"弹性碰撞·速度增量法等差数列求碰后速度","s":"看到【弹性碰撞已知两球碰前速度与质量，求碰后速度，直接联立双守恒太繁】","c":"想到【先用动量守恒算共速速度：V共$=\\frac{M_1V_1+M_2V_2}{M_1+M_2}$；弹性碰撞中每球的碰前速度、共速速度、碰后速度构成等差数列：公差=共速速度减该球碰前速度，碰后速度=2×共速速度-碰前速度】；警惕【等差规律仅弹性碰撞成立，非弹性碰撞套用必错；计算题卷面必须写双守恒方程拿过程分，速度增量法只在草稿纸上快速计算用】","src":"跳跳物一轮07.6 速度增量法、碰撞可能性问题_笔记","note":"视频|00:21-04:29","orig":"（知识）利用等差数列规律快速计算弹性碰撞碰后速度的方法。","link":""},{"id":"phy2394","t":"弹性碰撞·动碰静三种情况口诀","s":"看到【一物撞静止物的弹性碰撞，或物体与地面/墙弹性正碰，问碰后速度方向】","c":"想到【动碰静口诀：大碰小一起走（$M_1>M_2$ 时 $M_1$ 碰后仍向前）；小碰大小反弹（$M_1<M_2$ 时小质量的 $M_1$ 反弹）；等质量换速度（$V_1'=0$、$V_2'=V_1$，速度交换）；物体碰地面/墙可视为 $M_2$ 远大于 $M_1$ 的动碰静，物体以原速率反弹（$V_1'=-V_1$）】；警惕【口诀只对弹性碰撞且被碰物初速度为零才成立；把碰墙反弹误认为速率有损失】","src":"跳跳物一轮07.6 速度增量法、碰撞可能性问题_笔记","note":"视频|05:28","orig":"（知识）运动的物体撞静止物体的弹性碰撞（动碰静）碰后速度规律。","link":""},{"id":"phy2395","t":"碰撞可能性·已知碰前速度求碰后速度范围","s":"看到【碰撞类型未告知，已知碰前速度，选项给出各种碰后速度组合，判断哪些可能】","c":"想到【先算两个端点值：共速速度 V共 与弹性碰撞的碰后速度（用速度增量法求），每球碰后速度必介于这两个值之间（含端点）；合法组合恰三种：两球都取 V共 是完全非弹性碰撞，都取弹性值是弹性碰撞，都取中间值是一般非弹性碰撞】；警惕【某球速度超出两端点范围、或一球取最值另一球不取最值的组合，违反动量或能量守恒，必错】","src":"跳跳物一轮07.6 速度增量法、碰撞可能性问题_笔记","note":"视频|10:12","orig":"（知识）碰撞类型未知时，已知碰前速度求碰后速度可能性范围的排除法。","link":""},{"id":"phy2396","t":"碰撞可能性·已知动量求质量比的三原则","s":"看到【已知两物体碰前动量与碰后动量，求质量或质量比的取值范围】","c":"想到【碰撞三原则列不等式再取交集：①总动量守恒（先算出未知的碰后动量）；②总动能不增，动量已知时动能用 $E_K=\\frac{P^2}{2M}$ 计算；③速度合理——碰前同向须后面物体速度大于前面（才能追上），碰后同向须前面物体速度不小于后面（V前$\\geq$V后），碰前反向则碰后不可能两物体方向都不变（否则互相穿过）】；警惕【漏掉速度合理原则会多出违反追碰情境的解；三个不等式不取交集就下结论】","src":"跳跳物一轮07.6 速度增量法、碰撞可能性问题_笔记","note":"视频|15:53","orig":"（知识）碰撞类型未知时，已知动量判断碰后质量（比）可能性的三原则。","link":""},{"id":"phy2397","t":"弹性碰撞·等质量换速度加平抛影子例","s":"看到【等质量弹性碰撞后一球飞出做平抛，问影子的运动（投影问题）】","c":"想到【等质量弹性动碰静速度交换：$N$ 获得碰前 $M$ 的速度 $v$ 水平飞出、$M$ 碰后静止；平抛分运动判影子：竖直方向是自由落体（匀加速），竖直墙面上的影子做匀加速运动；水平方向是匀速直线，水平地面上的影子做匀速直线运动，速度大小等于平抛初速度】；警惕【影子的运动性质按对应分运动判断，别当作物体轨迹分析；还以为 $M$ 碰后带走速度，等质量碰撞速度是交换不是平分】","src":"跳跳物一轮07.6 速度增量法、碰撞可能性问题_笔记","note":"视频|21:25","orig":"（例）光滑平台上小球 $M$ 以速度 $v$ 水平撞上相同的静止小球 $N$（弹性碰撞），$N$ 从平台边缘飞出做平抛。问 $N$ 飞出后的速度、竖直墙面与水平地面上影子的运动性质。","link":""},{"id":"phy2398","t":"弹性碰撞·篮球碰网球多次碰撞例","s":"看到【多物体多次弹性碰撞（如篮球碰地又碰网球），求碰后速度或上升高度】","c":"想到【多次碰撞必须完全分开依次分析，分析一次时无视其他物体：先算篮球与地面碰撞（原速率反弹），以反弹后的篮球碰上网球时作为第二次碰撞的初态；第二次碰撞用速度增量法——设正方向列动量守恒求共速速度，再按等差规律得碰后速度；上升最大高度用 $v^2=2gh$ 以碰后速度反求】；警惕【两次碰撞混在一起处理或漏掉篮球碰地反弹这一步；正方向设错导致速度正负号混乱】","src":"跳跳物一轮07.6 速度增量法、碰撞可能性问题_笔记","note":"视频|23:35","orig":"（例）网球与篮球（质量为网球的 7 倍）一起从高 $h$ 处自由下落，落地前瞬间速度为 $V_0$，篮球先与地面弹性碰撞原速率反弹，上升中再与网球弹性正碰（此时网球仍以 $V_0$ 向下）。求碰后网球与篮球的速度及各自上升的最大高度。","link":""},{"id":"phy2399","t":"碰撞可能性·三原则求质量比例题","s":"看到【已知碰前碰后的动量数值，问质量比的可能范围或判断给定质量比是否可能】","c":"想到【按三原则列不等式：动量守恒先算出 A 碰后动量（$P_A'=P_A+P_B-P_B'$）；动能不增：碰前各 $\\frac{P^2}{2M}$ 之和$\\geq$碰后之和；速度合理：碰前能追上即 $P_A/M_A>P_B/M_B$，碰后同向前面不慢于后面即 $P_B'/M_B\\ge P_A'/M_A$；三个不等式取交集得质量比范围】；警惕【算 A 碰后动量时正负号出错；漏掉碰前能追上或碰后不穿过的速度条件，使范围偏大】","src":"跳跳物一轮07.6 速度增量法、碰撞可能性问题_笔记","note":"视频|35:27","orig":"（例）光滑水平面上 A（在前）与 B 同向运动，A 追上 B 发生碰撞。已知碰前 A 动量 18 kg$\\cdot$m/s、B 动量 24 kg$\\cdot$m/s，碰后 B 动量增大为 32 kg$\\cdot$m/s 且方向不变，求 A、B 质量比 $M_A/M_B$ 的可能取值范围。","link":""},{"id":"phy2400","t":"动量·板块模型等效完全非弹性碰撞","s":"看到【地面光滑，滑块冲上静止木板最终共速，求共速速度或摩擦生热】","c":"想到【系统合外力为零（摩擦力为内力），可等效为完全非弹性碰撞，列双守恒方程：动量守恒 $mv_0=(m+M)v'$，能量守恒 $\\frac{1}{2}mv_0^2=\\frac{1}{2}(m+M)v'^2+Q$（$v'$为共速速度，$Q$为摩擦生热）；摩擦生热还可用折合质量法一步求出：$Q=\\frac{1}{2}\\cdot\\frac{mM}{m+M}\\cdot v_0^2$，其中相对速度取初态两者的相对速度（板静止时即滑块初速度）】；警惕【等效前提是最终共速且板足够长；滑块中途滑离木板时不能视为完全非弹性碰撞，折合质量法也随之失效】","src":"跳跳物一轮07.7 板块模型、子弹打木块模型_笔记","note":"视频|00:50-04:37","orig":"（知识）地面光滑、木板足够长，滑块以初速度冲上静止木板，最终两者达到共速。","link":""},{"id":"phy2401","t":"动量·板的最小长度等于相对位移","s":"看到【滑块恰好不滑离木板，或求板的最小长度、相对滑行距离】","c":"想到【临界条件：滑块恰好运动到板的最右端时两者共速；板的最小长度=从开始到共速滑块相对板的位移$\\Delta x$；两步求解：先用折合质量法求摩擦生热Q，再由 $Q=f\\cdot\\Delta x$ 解出相对位移（即板长）】；警惕【$\\Delta x$是相对位移，不等于滑块或板各自的对地位移；摩擦力 $f=\\mu m g$ 用滑块质量（水平面上正压力来自滑块），别误用板的质量】","src":"跳跳物一轮07.7 板块模型、子弹打木块模型_笔记","note":"视频|05:55","orig":"（知识）求木板的最小长度，或判断滑块是否会滑离木板。","link":""},{"id":"phy2402","t":"动量·板块共速时间用动量定理","s":"看到【板块问题中求达到共速的时间或滑块在板上的滑行时间】","c":"想到【共速速度直接由动量守恒得出：共速速度=$\\frac{mv_0}{m+M}$；共速时间对单个物体列动量定理，优先选初速度为零的物体（如板）：$f\\cdot t=Mv'$（$v'$为共速速度），其动量变化就是末动量，计算最简单】；警惕【对初速度不为零的物体列式时摩擦力取负号（$-f\\cdot t=mv'-mv_0$），符号易错；动量守恒方程不含时间，时间必须靠动量定理或牛顿定律另求】","src":"跳跳物一轮07.7 板块模型、子弹打木块模型_笔记","note":"视频|07:48","orig":"（知识）板块达到共速后，求共速所需的时间（滑块在板上的滑行时间）。","link":""},{"id":"phy2403","t":"动量·子弹打木块留内与穿出的处理差异","s":"看到【子弹打木块，需判断能否用折合质量法，或求热量、末速度、深度】","c":"想到【先判断最终是否共速：留在木块内=完全非弹性碰撞，热量用折合质量法 $Q=\\frac{1}{2}\\cdot\\frac{mM}{m+M}\\cdot v_0^2$，钻入深度=相对位移=$Q/f$；穿出木块=一般非弹性碰撞，动量守恒但动能不守恒，必须老老实实列动量+能量双守恒方程求穿出速度和热量】；警惕【穿出情况误套折合质量法（该式仅共速时成立）；穿出后子弹速度仍大于木块速度，别按共速处理】","src":"跳跳物一轮07.7 板块模型、子弹打木块模型_笔记","note":"视频|11:11-12:28","orig":"（知识）子弹打木块模型的两种情况：子弹留在木块内与子弹穿出木块。","link":""},{"id":"phy2404","t":"动量·含碰撞的多物体多过程处理三原则","s":"看到【多物体叠放或先后发生多次碰撞，问如何选取系统、拆分过程】","c":"想到【三原则：①忽略无关物体——分析某次碰撞只取直接参与的物体（C撞B时，叠在B上的A忽略，除非A、B粘牢）；②碰撞顺序化——上一次碰撞彻底结束后，下一次才开始，逐段分析；③碰撞位移为零——碰撞瞬间物体位置不变（子弹打入摆球时物块不动，打完才开始摆动）】；警惕【把叠放但未粘牢的物体当整体处理碰撞；把碰撞瞬间与后续运动混进同一方程、漏拆过程】","src":"跳跳物一轮07.7 板块模型、子弹打木块模型_笔记","note":"视频|13:19","orig":"（知识）多物体、多过程的含碰撞问题，如叠放球被撞、篮球网球叠落、子弹打入悬挂摆球。","link":""},{"id":"phy2405","t":"动量·弹性碰撞速度增量法（等差数列）","s":"看到【弹性正碰已知质量比与碰前速度，求碰后各物体速度】","c":"想到【速度增量法（草稿纸速算）：先求共速速度 $v'=\\frac{2mv_0}{2m+m}=\\frac{2}{3}v_0=1.2\\mathrm{m/s}$；每个物体碰前、共速、碰后速度成等差数列——B序列1.8、1.2、0.6得碰后$0.6\\mathrm{m/s}$，C序列0、1.2、2.4得碰后$2.4\\mathrm{m/s}$；正式解答仍要列动量+动能双守恒方程拿过程分】；警惕【等差数列法仅弹性碰撞成立，完全非弹性碰撞碰后即共速；碰后方向——重撞轻两者同向（重慢轻快），轻撞重主碰物体反弹】","src":"跳跳物一轮07.7 板块模型、子弹打木块模型_笔记","note":"视频|23:58","orig":"（例）B与静止的C在光滑水平面上发生弹性正碰：质量$2m$的B以$1.8\\mathrm{m/s}$入射，C质量为$m$（叠在B上的A在碰撞瞬间忽略）。求碰后B、C的速度。","link":""},{"id":"phy2406","t":"动量·同一子弹射入滑块不同层的对比","s":"看到【同一子弹以相同速度射入同一滑块的不同部位（均未射出），比较末速度、热量、做功或作用力】","c":"想到【两种情况子弹均未射出、最终均共速，都属完全非弹性碰撞：末速度相同（$v'=\\frac{mv_0}{m+M}$）；热量相同（$Q=\\frac{1}{2}\\cdot\\frac{mM}{m+M}\\cdot v_0^2$）；子弹对滑块做的功相同（=滑块动能增量$\\frac{1}{2}Mv'^2$）；但 $Q=f\\cdot\\Delta x$ 中相对位移不同（射下层为滑块全长，射上层为全长一半），故摩擦力f不同】；警惕【做功相同指子弹对滑块的功（滑块动能增量），不等于子弹动能的损失；热量相同不代表作用力相同】","src":"跳跳物一轮07.7 板块模型、子弹打木块模型_笔记","note":"视频|41:53","orig":"（例）矩形滑块由不同材料的上、下两层粘合，置于光滑水平面，子弹以$v_0$水平射入：射下层时刚好不射出（留在滑块内），射上层时刚好射穿一半厚度。比较两种情况的子弹末速度、系统热量、子弹对滑块做的功、相互作用力。","link":""},{"id":"phy2407","t":"动量·摆球圆筒系统的最高点共速与最大速度","s":"看到【子弹击穿悬挂物体后物体上摆，支撑物在光滑水平面上滑动，求最大摆高或支撑物最大速度】","c":"想到【两阶段：①子弹击穿B后退出舞台（击穿瞬间B不动），B获$6\\mathrm{m/s}$；②B、C水平动量守恒+机械能守恒。B摆到最高点时与C共速（相对水平速度与竖直速度均为零），用折合质量法求出上升高度$h=0.6\\mathrm{m}$；C最大速度在B摆回正下方时，该过程等效弹性碰撞，速度增量法：共速$4\\mathrm{m/s}$，C序列0、4、8，最大$8\\mathrm{m/s}$】；警惕【C最大速度不在B最高点而在B回到最低点时；击穿后不能把子弹再计入B、C系统的动量】","src":"跳跳物一轮07.7 板块模型、子弹打木块模型_笔记","note":"视频|46:43","orig":"（例）圆筒C（$0.5\\mathrm{kg}$）可在光滑水平杆上滑动，下方轻绳悬挂物体B（$1.0\\mathrm{kg}$）。子弹A（$0.1\\mathrm{kg}$）以$100\\mathrm{m/s}$水平击穿B后速度减为$40\\mathrm{m/s}$，B随即上摆。求B上升的最大高度和C的最大速度（$g$取$10\\mathrm{m/s^2}$）。","link":""},{"id":"phy2408","t":"动量·弹簧滑块模型总述与长度循环","s":"看到【光滑水平面两滑块经弹簧相互作用，求最大弹性势能或分离速度】","c":"想到【滑块+弹簧系统合外力为零，动量守恒；弹簧长度循环变化：原长→最短→原长→最长→原长；两大问题对应两时刻——最大弹性势能在共速（形变最大）时，分离速度在恢复原长时】；警惕【墙、挡板对系统的弹力是外力，有外力阶段动量不守恒，守恒方程不能跨该阶段列】","src":"跳跳物一轮07.8 弹簧 滑块模型_笔记","note":"视频|00:42","orig":"（知识）光滑水平面上两滑块通过弹簧相连的运动模型，核心问题是最大弹性势能或分离速度。","link":""},{"id":"phy2409","t":"动量·弹簧滑块v-t图关键时刻与弹簧状态","s":"看到【弹簧滑块的v-t图像，判断弹簧最短/最长/原长的时刻或弹力方向】","c":"想到【两物块速度相等（图线交点）时弹簧形变量最大：第一次共速弹簧最短，再共速弹簧最长，弹性势能均最大；图线切线斜率为零的时刻弹簧恢复原长（弹力为零、加速度为零）；斜率正负对应弹力方向（规定向右为正，正斜率表示弹力向右）】；警惕【共速不等于弹力为零——共速时形变最大、弹力最大、加速度最大；恢复原长时弹力才为零】","src":"跳跳物一轮07.8 弹簧 滑块模型_笔记","note":"视频|01:29","orig":"（知识）弹簧连接两滑块在光滑水平面运动，利用v-t图像判断弹簧长度和弹力变化。","link":""},{"id":"phy2410","t":"动量·弹簧两次共速的速度与形变量关系","s":"看到【问弹簧最短与最长两个共速时刻的速度或形变量是否相同】","c":"想到【由动量守恒，无论弹簧最短还是最长，共速速度都相同（=$\\frac{m_1v_0}{m_1+m_2}$）；共速时系统动能相等→弹性势能相等→同一弹簧形变量相等（压缩量等于伸长量），过程对称】；警惕【两次共速时弹簧弹力方向相反（最短时推开两滑块、最长时拉近两滑块），但速度、动能、势能的数值完全相同】","src":"跳跳物一轮07.8 弹簧 滑块模型_笔记","note":"视频|11:34","orig":"（知识）弹簧滑块系统中，弹簧最短时和最长时两次共速状态的关系。","link":""},{"id":"phy2411","t":"动量·弹簧最大弹性势能的求法","s":"看到【光滑水平面弹簧滑块系统，求弹簧的最大弹性势能】","c":"想到【共速时形变量最大、弹性势能最大，从初始原长到共速的过程等效为完全非弹性碰撞：折合质量法 $E_P=\\frac{1}{2}\\cdot\\frac{m_1m_2}{m_1+m_2}\\cdot v^2$（$v$为初态两滑块的相对速度，另一滑块静止时即入射滑块初速度）；正式解答可列动量守恒+能量守恒双守恒方程拿过程分】；警惕【初态必须取弹簧原长时刻（此时势能为零）才能直接套用；系统受墙等外力时动量不守恒，禁用折合质量法】","src":"跳跳物一轮07.8 弹簧 滑块模型_笔记","note":"视频|13:44","orig":"（知识）求弹簧压缩最短（或拉伸最长）时的最大弹性势能。","link":""},{"id":"phy2412","t":"动量·弹簧恢复原长时的分离速度","s":"看到【弹簧与滑块不粘连，求滑块与弹簧分离时（再次恢复原长时）的速度】","c":"想到【弹簧恢复原长的瞬间滑块与弹簧分离，从初始原长到再次恢复原长的全过程等效为弹性碰撞，分离速度即弹性碰撞的碰后速度，用速度增量法（等差数列）速算；特例：两物体质量相等且一动一静，碰后速度交换，直接互换速度】；警惕【分离只发生在恢复原长时刻且以不粘连为前提；粘连的弹簧滑块不会分离，无分离速度可言】","src":"跳跳物一轮07.8 弹簧 滑块模型_笔记","note":"视频|16:36","orig":"（知识）弹簧与滑块不粘连时，求滑块与弹簧分离时的速度。","link":""},{"id":"phy2413","t":"动量·子弹嵌入物块后再经弹簧作用","s":"看到【子弹嵌入物块后，物块再经弹簧作用另一物块，求最大速度、共速速度或弹性势能】","c":"想到【分两阶段：①子弹嵌入A瞬间弹簧仍为原长、可忽略弹簧，动量守恒 $mv_0=2m\\cdot v$，得A最大速度$v=\\frac{v_0}{2}$；②弹簧压缩量最大时A（含子弹）与B共速，$4m\\cdot v'=2m\\cdot\\frac{v_0}{2}$，$v'=\\frac{v_0}{4}$（$v'$为共速速度）；最大弹性势能用折合质量法：$E_P=\\frac{1}{2}\\cdot\\frac{2m\\cdot 2m}{4m}\\cdot(\\frac{v_0}{2})^2=\\frac{mv_0^2}{8}$】；警惕【A的最大速度在刚被击中瞬间而非弹簧作用后；折合质量法中要用含子弹的组合质量】","src":"跳跳物一轮07.8 弹簧 滑块模型_笔记","note":"视频|21:20","orig":"（例）光滑水平面上，子弹（质量$m$）以$v_0$击中质量$m$的物块A并嵌入其中，A与质量$2m$的物块B通过轻弹簧相连（初始为原长，B静止）。求A的最大速度、弹簧压缩量最大时B的速度和最大弹性势能。","link":""},{"id":"phy2414","t":"动量·滑块靠墙阶段的守恒失效与离墙后等效弹性碰撞","s":"看到【弹簧滑块一侧靠墙或靠挡板，求靠墙阶段弹性势能、墙的冲量或离墙后速度】","c":"想到【靠墙阶段墙对B有弹力，动量不守恒，只能能量守恒：最大弹性势能=AC动能全部转化=$\\frac{1}{2}\\times 3\\times 3^2=13.5\\mathrm{J}$；墙的冲量用动量定理 $I=\\Delta p$=末动量-初动量$=-9-9=-18\\mathrm{N\\cdot s}$（大小$18\\mathrm{N\\cdot s}$）；B离墙后动量守恒，B最大速度在弹簧恢复原长时，等效弹性碰撞用速度增量法得$3.6\\mathrm{m/s}$】；警惕【靠墙阶段误用动量守恒或折合质量法；冲量的负号表示方向向左，答大小需取绝对值】","src":"跳跳物一轮07.8 弹簧 滑块模型_笔记","note":"视频|27:08","orig":"（例）光滑水平面上A、B质量均为$2\\mathrm{kg}$，B右侧与墙壁接触但不粘连，C与A碰撞后粘合。碰后AC以$3\\mathrm{m/s}$向右压缩弹簧，减速到零后被弹回，弹簧恢复原长时AC速度为$-3\\mathrm{m/s}$、B开始离开墙。求B离开墙前弹簧的最大弹性势能、此过程墙对B的冲量、B离墙后的最大速度。","link":""},{"id":"phy2415","t":"动量·碰撞压缩弹簧后分离再平抛的综合","s":"看到【滑块下滑碰撞后压缩弹簧推开另一滑块，滑块再平抛，求弹性势能或落点距离】","c":"想到【分四段：①下滑用动能定理 $mgh=\\frac{1}{2}mv^2$，$v=6\\mathrm{m/s}$；②碰撞粘合用动量守恒，$v_1=\\frac{1\\times 6}{3}=2\\mathrm{m/s}$；③弹簧最大弹性势能在AB与C共速时，折合质量法 $E_P=\\frac{1}{2}\\times\\frac{3\\times 3}{6}\\times 2^2=3\\mathrm{J}$；④分离时刻弹簧恢复原长，等效弹性碰撞——AB总质量等于C质量，等质量动碰静碰后速度交换，C分离速度=$2\\mathrm{m/s}$，平抛 $x=v\\cdot\\sqrt{2H/g}=2\\mathrm{m}$】；警惕【平抛初速度用分离速度而非共速速度；等质量换速度只适用于动碰静的弹性碰撞】","src":"跳跳物一轮07.8 弹簧 滑块模型_笔记","note":"视频|38:31","orig":"（例）A（$1\\mathrm{kg}$）从高$1.8\\mathrm{m}$处沿光滑曲面滑下，与静止的B（$2\\mathrm{kg}$）碰撞后粘合，压缩弹簧推动C（$3\\mathrm{kg}$）。C与弹簧分离后从高$5\\mathrm{m}$的桌面边缘水平飞出（$g$取$10\\mathrm{m/s^2}$）。求AB碰后瞬间的速度、弹簧最大弹性势能、C落地点与桌面边缘的水平距离。","link":""},{"id":"phy2416","t":"动量·四分之一圆弧轨道的守恒方向与做功正负","s":"看到【光滑地面上的圆弧轨道可自由滑动，小球冲上轨道，问动量守恒情况或做功正负】","c":"想到【系统竖直方向动量不守恒（轨道竖直速度恒为零而小球竖直动量时刻变化），故总动量不守恒；地面光滑使水平方向不受外力，水平方向动量守恒；小球对轨道的压力水平分力推动轨道加速，对轨道做正功，轨道对小球做负功（小球部分动能转移为轨道动能）】；警惕【不能对系统列总动量守恒方程；轨道被固定挡块挡住时挡块弹力是外力，该阶段水平动量也不守恒】","src":"跳跳物一轮07.9 圆弧轨道模型_动量模块完结撒花~_笔记","note":"视频|01:01-02:00","orig":"（知识）光滑地面上放置可自由滑动的四分之一圆弧轨道，小球从轨道底端以初速度冲上轨道。","link":""},{"id":"phy2417","t":"动量·圆弧轨道最高点共速条件","s":"看到【小球冲上可滑动圆弧轨道，问最高点（或离开轨道最上端）时两者的速度关系】","c":"想到【最高点小球与轨道共速：未离开时，以轨道为参考系，小球相对水平速度必须减为零才能掉头；恰好离开时，最上端相对速度沿切线竖直向上，水平方向共速。离开后小球斜抛、轨道匀速，水平速度始终相同，小球始终在轨道最上端正上方。求离开时速度：水平分量用水平动量守恒求，竖直分量由高度差用竖直上抛求】；警惕【共速指水平速度相同，地面系中小球水平速度不为零（向右）；恰好离开后做斜抛，不是竖直上抛】","src":"跳跳物一轮07.9 圆弧轨道模型_动量模块完结撒花~_笔记","note":"视频|04:09","orig":"（知识）小球冲上可滑动圆弧轨道，无论是否离开轨道，最高点时与轨道的速度关系。","link":""},{"id":"phy2418","t":"动量·圆弧轨道最大高度的折合质量法","s":"看到【小球冲上光滑可滑动圆弧轨道，求上升的最大高度】","c":"想到【从底端到最高点：水平动量守恒 $mv_0=(m+M)v'$（$v'$为共速速度）+能量守恒 $\\frac{1}{2}mv_0^2=\\frac{1}{2}(m+M)v'^2+mgh$，与完全非弹性碰撞方程完全相同；$mgh$即碰撞损失能量，用折合质量法一步算：$mgh=\\frac{1}{2}\\cdot\\frac{mM}{m+M}\\cdot v_0^2$（轨道初速为零时相对速度即$v_0$），解出$h$】；警惕【只能用水平方向的动量守恒列式；$h$是相对出发点（底端平面）的高度】","src":"跳跳物一轮07.9 圆弧轨道模型_动量模块完结撒花~_笔记","note":"视频|11:46","orig":"（知识）小球从底端冲上可滑动圆弧轨道，求上升的最大高度。","link":""},{"id":"phy2419","t":"动量·小球回到底端时的速度与轨道最大速度","s":"看到【小球冲上圆弧轨道再滑回底端，求各自速度或轨道（小车）的最大速度】","c":"想到【从底端出发再回到底端的全过程：水平动量守恒+机械能守恒（初末高度相同、势能不变），方程与弹性碰撞完全相同，用速度增量法（等差数列）直接得小球回到底端的速度和轨道速度；轨道全程被小球压力的水平分力推动加速，小球回到底端时轨道速度最大】；警惕【小球回到底端时速度方向反向（质量小者反弹），负号表示方向；轨道最大速度不在小球最高点而在小球回到底端时】","src":"跳跳物一轮07.9 圆弧轨道模型_动量模块完结撒花~_笔记","note":"视频|14:40","orig":"（知识）小球滑上可滑动圆弧轨道后又滑回底端，求小球速度和轨道的最大速度。","link":""},{"id":"phy2420","t":"动量·半圆弧轨道的人船模型","s":"看到【光滑水平面半圆弧轨道（小车），小球从一端进入另一端离开，问离开时速度或小车位移】","c":"想到【系统水平方向初动量为零且守恒，符合人船模型；小球从一端到最低点阶段小车被压力水平分力推动加速，过最低点到另一端阶段减速，到另一端时小车速度恰好减为零；小球离开端点时速度沿切线竖直向上、水平方向与轨道共速，由水平动量守恒得两者水平速度均为零，小球做竖直上抛；小车位移由 $m_1x_1=m_2x_2$ 与相对位移$2R$联立求】；警惕【离开端点时小车速度和小球水平速度均为零，别照搬四分之一圆弧共速速度非零的结论；竖直方向动量不守恒】","src":"跳跳物一轮07.9 圆弧轨道模型_动量模块完结撒花~_笔记","note":"视频|18:06","orig":"（知识）光滑水平面上的半圆弧轨道小车，小球从轨道一端进入、另一端离开。","link":""},{"id":"phy2421","t":"动量·四类类碰撞模型的共速时刻总结","s":"看到【板块/子弹打木块/弹簧滑块/圆弧轨道模型，问共速时刻或可等效为哪种碰撞】","c":"想到【四类统称类碰撞模型，各自共速时刻：板块——相对静止时；子弹打木块——木块（摆球）摆到最高点时；弹簧滑块——弹簧最短或最长时；圆弧轨道——小球到最高点时。共同规律：从开始到共速等效完全非弹性碰撞（折合质量法求损失能量），从开始经共速再回到初态的全过程等效弹性碰撞（速度增量法求末速度）】；警惕【板块模型没有弹性碰撞对应过程；共速时刻找错则整个等效失效】","src":"跳跳物一轮07.9 圆弧轨道模型_动量模块完结撒花~_笔记","note":"视频|22:14","orig":"（知识）板块、子弹打木块、弹簧滑块、圆弧轨道四类模型与碰撞模型的等效关系总结。","link":""},{"id":"phy2422","t":"动量·挡块固定的半圆弧轨道守恒分析","s":"看到【半圆弧轨道一侧被固定挡块挡住，小球在槽内运动，问各阶段动量或机械能守恒情况】","c":"想到【A→B（压向挡块）：挡块弹力是系统外力，水平动量不守恒；但轨道被挡住不动，小球机械能守恒。B→C（离开挡块）：系统水平不受外力，水平动量守恒；轨道被小球推动加速，小球机械能转化为轨道动能，小球机械能不守恒。离开C后小球既有水平又有竖直速度，做斜抛运动】；警惕【两阶段两种守恒恰好错开——有挡块时动量不守恒而机械能守恒，轨道动起来后动量守恒而机械能不守恒】","src":"跳跳物一轮07.9 圆弧轨道模型_动量模块完结撒花~_笔记","note":"视频|36:25","orig":"（例）光滑水平面上的光滑半圆槽，左侧有固定物块挡住轨道，小球从槽内A端经最低点B运动到另一端C离开。分析A→B、B→C两过程中小球机械能守恒与系统水平动量守恒情况，及离开C后的运动。","link":""},{"id":"phy2423","t":"动量·半圆弧小车中人船位移与二次摩擦生热","s":"看到【小球落入半圆小车从另一端冲出（粗糙内壁），问小车位移、离开后运动或第二次上升高度】","c":"想到【系统只在水平方向动量守恒（竖直方向受重力）；小球到B端时小车速度恰好为零（人船模型），小球只有竖直速度，做竖直上抛；小车向左最大距离用 人船模型（$m_1x_1=m_2x_2$，质量相等位移相等，$x_1+x_2=2R$得各移$R$）；第二次高度比较用摩擦生热：第一次损失$\\frac{1}{4}mgh_0$，第二次返回时速度小、对轨道压力小、摩擦生热更少，剩余机械能$>\\frac{1}{2}mgh_0$，故第二次上升高度$>\\frac{h_0}{2}$】；警惕【小车速度为零仅发生在小球到达B端瞬间；摩擦生热与速度（压力）有关，两次经过同一路径生热并不相等】","src":"跳跳物一轮07.9 圆弧轨道模型_动量模块完结撒花~_笔记","note":"视频|40:25","orig":"（例）光滑水平面上质量$m$的半圆轨道小车静止（内壁粗糙），质量$m$的小球从A端正上方$h_0$处自由下落入槽，从B端冲出后上升的最大高度为$\\frac{3h_0}{4}$（相对槽口平面）。分析系统动量守恒情况、小球离开B后的运动、小车向左的最大距离、小球第二次上升的最大高度。","link":""},{"id":"phy2424","t":"机械振动·平衡位置与回复力","s":"看到【判断某位置是否为平衡位置，或对做简谐运动的物体进行受力分析】","c":"想到【平衡位置只看振动方向上的合力，不看总合力：单摆最低点水平方向合力为零是平衡位置，但此时绳拉力与重力的合力提供向心力、总合力不为零；回复力是效果命名，由弹簧弹力、重力分力等真实力提供，受力分析时不能与弹力并列计入】；警惕【把回复力当成额外真实力重复计入，或因总合力不为零而否定单摆最低点是平衡位置】","src":"跳跳物一轮08.1 简谐运动_笔记","note":"视频|02:57","orig":"（知识）机械振动中平衡位置定义为振动方向上合力为零的位置，回复力是使物体回到平衡位置的效果力。","link":""},{"id":"phy2425","t":"简谐运动·位移振幅与全振动","s":"看到【题目涉及振动位移、振幅的定义，或判断一次全振动及其路程】","c":"想到【振动位移起点永远是平衡位置（与必修一初末位置定义不同）；振幅是标量，等于位移的最大值；全振动必须同时满足回到起点和速度方向相同，一次全振动路程为$4A$；频率与周期互为倒数 $f=\\frac{1}{T}$】；警惕【只回到起点而速度方向相反只是半次振动，漏掉速度方向条件会把周期算错一半；振幅是标量不能说成负】","src":"跳跳物一轮08.1 简谐运动_笔记","note":"视频|06:28-07:50","orig":"（知识）机械振动的位移从平衡位置指向当前位置，振幅是最远点到平衡位置的距离，全振动指以同样速度方向回到起点的过程。","link":""},{"id":"phy2426","t":"简谐运动·定义F=-kx与证明套路","s":"看到【要求证明弹簧振子（或某模型）做简谐运动】","c":"想到【证明套路：任取一位置，写出位移方向（由平衡位置指向该点）；找出真实回复力（如弹簧弹力，指向平衡位置）；以弹力方向为正方向，则位移为负，弹簧形变量等于位移大小；由胡克定律 $F=k\\times$形变量$=k(-x)=-kx$，即回复力与位移成正比、方向相反，得证】；警惕【负号只是方向关系的体现，若自选正方向与位移方向不一致需重新判定符号，不能死抄 $F=-kx$；回复力与位移是同一时刻的对应量】","src":"跳跳物一轮08.1 简谐运动_笔记","note":"视频|10:09","orig":"（知识）简谐运动定义为回复力满足 $F=-kx$ 的机械振动，$k$ 为正比例系数，负号表示回复力与位移方向时刻相反。","link":""},{"id":"phy2427","t":"简谐运动·特殊位置与往返过程物理量变化","s":"看到【比较简谐运动中速度、位移、回复力、加速度的大小关系或能量转化方向】","c":"想到【平衡位置：$v$ 最大、$x=0$、$F=0$、$a=0$；最远点：$v=0$，$x$、$F$、$a$ 均最大；远离平衡位置为减速过程（$v$ 减小，$x$、$F$、$a$ 增大，动能转化为势能），接近平衡位置为加速过程（各量反向变化，势能转化为动能）】；警惕【接近平衡位置时 $a$ 与 $v$ 同向，勿套用加速度增大必减速；势能类型依模型而定（弹簧振子为弹性势能、单摆为重力势能），勿混用】","src":"跳跳物一轮08.1 简谐运动_笔记","note":"视频|13:03","orig":"（知识）简谐运动中平衡位置与最远点是两个特殊位置，远离与接近平衡位置的过程中各物理量单调变化。","link":""},{"id":"phy2428","t":"简谐运动·对称性","s":"看到【比较关于平衡位置对称的两点的物理量，或利用时间对称关系求周期】","c":"想到【关于平衡位置对称的两点：位移、回复力、加速度均等大反向，速度等大但方向可能相同也可能相反，动能与势能均相同；时间上：同一段距离正着走与反着走所用时间相等，关于平衡位置对称的两段距离所用时间也相等】；警惕【对称点的速度方向不确定，说经过同一点速度一定反向是错的；比较位移、加速度等矢量必须带方向，不能只比大小】","src":"跳跳物一轮08.1 简谐运动_笔记","note":"视频|16:59","orig":"（知识）简谐运动的轨迹与受力关于平衡位置对称，对称点上各物理量有确定关系，时间上也具有对称性。","link":""},{"id":"phy2429","t":"简谐运动·多解性问题","s":"看到【质点连续两次通过同一点或依次通过两点，求时间或周期】","c":"想到【连续两次通过同一点一般有 2 种走法（先向右到最远点折返，或先向左到最远点折返），若该点恰为最远点则只有 1 种；依次通过 $a$、$b$ 两点一般 2 种（直接过去，或先反向到最远点再折返经过 $b$），若两点均为最远点只有 1 种；若题设以相同速度方向依次通过两点，多解性被消除，只有 1 种走法】；警惕【从 $a$ 反向绕最远点回来经过 $b$ 时，过 $b$ 速度方向虽符合但过 $a$ 时方向相反，不满足相同速度方向条件，勿多算一种解】","src":"跳跳物一轮08.1 简谐运动_笔记","note":"视频|20:59","orig":"（知识）题目描述质点连续两次通过同一点或依次通过两点时，因经过时速度方向不确定而产生多解。","link":""},{"id":"phy2430","t":"简谐运动·由一段对称行程求周期与路程","s":"看到【已知振子从最远点到平衡位置（或某段对称行程）的时间，求周期、振幅或一段时间内的路程】","c":"想到【振幅即最远点到平衡位置的距离 $A=BO$；由时间对称性，B→O、O→C、C→O、O→B 每段用时相等，周期 $T=4\\times 0.5\\,\\mathrm{s}=2\\,\\mathrm{s}$；一次全振动路程为 $4A$；求任意时长路程按周期数分段：$3\\,\\mathrm{s}=1.5T$，前一个周期路程 $4A$ 回到出发点，后半个周期是从一最远点到另一最远点、路程 $2A$，合计 $6A=30\\,\\mathrm{cm}$】；警惕【不足一个周期的时间要用实际轨迹分段累加，只有当时间为半周期的整数倍时才能用路程与时间成正比硬算】","src":"跳跳物一轮08.1 简谐运动_笔记","note":"视频|26:30","orig":"（例）弹簧振子在 B、C 间做简谐运动，O 为平衡位置，$BO=5\\,\\mathrm{cm}$，振子从 B 运动到 O 用时 $0.5\\,\\mathrm{s}$，求振幅、周期及 $3\\,\\mathrm{s}$ 内的路程。","link":""},{"id":"phy2431","t":"简谐运动·以相同速度通过两对称点求周期振幅","s":"看到【以相同速度（方向也相同）依次通过两点并给出两段时间，求周期和振幅】","c":"想到【相同速度意味着大小和方向都相同，两点必关于平衡位置对称且质点同向经过，无多解；将两段行程拼接：M→N 与 N→最右端→N 恰好拼成等效的半个全振动，其路程为 $2A$，故 $A=12\\,\\mathrm{cm}\\div 2=6\\,\\mathrm{cm}$；时间上由对称性 N→最右端与最右端→N 各 $0.5\\,\\mathrm{s}$，最左端到最右端为半周期，得 $T=4\\,\\mathrm{s}$】；警惕【相同速率与相同速度不同：只说速率相同仍有两种走法，多解性未消除；拼接路程时注意对称段距离相等才能相消】","src":"跳跳物一轮08.1 简谐运动_笔记","note":"视频|31:31","orig":"（例）质点做简谐运动，以相同速度依次通过 M、N 两点用时 $1\\,\\mathrm{s}$，从 N 到最右端再返回 N 又用时 $1\\,\\mathrm{s}$，且这 $2\\,\\mathrm{s}$ 内路程为 $12\\,\\mathrm{cm}$，求周期与振幅。","link":""},{"id":"phy2432","t":"振动图像·正余弦特殊点函数值","s":"看到【振动图像中某时刻处于从零到峰值段的三等分点、中点等位置，求位移大小】","c":"想到【把四分之一周期对应 $90^{\\circ}$：三分点（对应 $30^{\\circ}$）函数值为 $\\frac{A}{2}$，中点（$45^{\\circ}$）为 $\\frac{\\sqrt{2}}{2}A$，三分之二点（$60^{\\circ}$）为 $\\frac{\\sqrt{3}}{2}A$；图线在横轴下方时各特殊点函数值均取负；三等分必须从零点一侧开始数，靠近零点的第一个等分点是三分点】；警惕【从峰值一侧数起会把三分点与三分之二点认反；图线在 t 轴下方时忘记取负号】","src":"跳跳物一轮08.2 简谐运动的振动图像和振动方程_笔记","note":"视频|00:24","orig":"（知识）正余弦函数图线上从零点到最大值 $A$ 的一段（四分之一周期）内，按位置可读出三个特殊点的函数值。","link":""},{"id":"phy2433","t":"振动图像·读图方法与物理量变化","s":"看到【由振动图像读取振幅、周期、速度方向，或比较各物理量的变化】","c":"想到【平衡位置是图线与 t 轴的交点；振幅取最大值或最小值的绝对值；周期为一个完整波形的时间；图线斜率表示速度，上扬为正方向、下降为负方向；分析各量变化先判断图线是接近还是远离 t 轴：接近 t 轴（靠近平衡位置）则 $v$ 增大、$x$、$F$、$a$ 减小，远离 t 轴则相反】；警惕【振动图像不是物体的真实运动轨迹，图线切线方向不代表速度方向，速度方向只看上扬或下降；勿把峰峰值当成振幅】","src":"跳跳物一轮08.2 简谐运动的振动图像和振动方程_笔记","note":"视频|04:48-05:41","orig":"（知识）简谐运动的振动图像就是 $x$-$t$ 图像，图线为正弦或余弦函数，用 $\\sin$ 还是 $\\cos$ 取决于零时刻的选择。","link":""},{"id":"phy2434","t":"振动图像·一段时间内的路程结论","s":"看到【由振动图像求某段时间内振子通过的路程】","c":"想到【一个周期内路程恒为 $4A$（任意时刻开始都成立）；半个周期内路程恒为 $2A$（任意时刻开始，可把该段图线拼成一个从平衡位置到最远点再回到平衡位置的小山包理解）；四分之一周期内路程仅当从平衡位置或最远点开始时才等于 $A$，从其他时刻开始不等于 $A$】；警惕【时间段不是半周期的整数倍时不能按 $4A\\times(t/T)$ 比例硬算，须按轨迹分段累加；从一般位置开始的一个四分之一周期路程不等于 $A$】","src":"跳跳物一轮08.2 简谐运动的振动图像和振动方程_笔记","note":"视频|10:18","orig":"（知识）简谐运动一段时间内的路程与起始时刻有关，有三个常用二级结论。","link":""},{"id":"phy2435","t":"振动方程·形式与由图像求方程","s":"看到【由振动图像写出或验证质点的振动方程】","c":"想到【步骤：先读图得振幅 $A$ 与周期 $T$，由 $\\omega=\\frac{2\\pi}{T}$ 求圆频率；再将一个已知点 $(t,x)$ 代入方程解出初相 $\\varphi$；零时刻在平衡位置用 $\\sin$，在最远点用 $\\cos$；求位移用特殊点结论比解方程更快，方程主要用于被要求写出或验证】；警惕【验证方程先核对 $\\omega$ 是否等于 $\\frac{2\\pi}{T}$（最常见错误），再核振幅与初相；代点求 $\\varphi$ 时注意该点位移的正负】","src":"跳跳物一轮08.2 简谐运动的振动图像和振动方程_笔记","note":"视频|14:01-16:11","orig":"（知识）简谐运动的振动方程为 $x=A\\sin(\\omega t+\\varphi)$ 或 $x=A\\cos(\\omega t+\\varphi)$，$\\omega$ 为圆频率，$\\varphi$ 为初相位。","link":""},{"id":"phy2436","t":"振动图像·读图判断振幅频率与加速度方向","s":"看到【由振动图像判断振幅、周期频率、某时刻速度与加速度方向的选择题】","c":"想到【振幅取峰值的绝对值 $1\\,\\mathrm{cm}$ 而非峰峰值 $2\\,\\mathrm{cm}$；周期读一个完整波形 $0.4\\,\\mathrm{s}$，频率 $f=\\frac{1}{T}=2.5\\,\\mathrm{Hz}$；图线与 t 轴交点处振子处于平衡位置，速度最大不可能为零；加速度方向与位移方向相反：$0.2\\,\\mathrm{s}$ 位移为负，加速度为正方向】；警惕【题目未明确正方向时默认竖直向上为正方向再判断；把峰峰值 $2\\,\\mathrm{cm}$ 当振幅、认为平衡位置速度为零都是高频错误】","src":"跳跳物一轮08.2 简谐运动的振动图像和振动方程_笔记","note":"视频|17:42","orig":"（例）（2024福建）由振动图像（纵坐标最大值 $1\\,\\mathrm{cm}$，一个完整波形为 $0\\sim 0.4\\,\\mathrm{s}$）判断振幅、频率、$0.1\\,\\mathrm{s}$ 时的速度及 $0.2\\,\\mathrm{s}$ 时的加速度方向。","link":""},{"id":"phy2437","t":"振动图像·竖直弹簧振子综合判断","s":"看到【竖直方向简谐运动结合振动图像，判断平衡位置弹力、验证振动方程、比较对称时刻的速度】","c":"想到【平衡位置是合力为零而非弹力为零：竖直弹簧振子在平衡位置弹力与重力等大反向、不为零；验证方程按先 $A$、再 $\\omega=\\frac{2\\pi}{T}$、后代点求 $\\varphi$ 三步走；四分之一周期内从平衡位置运动到最大位移处路程等于 $A$；关于平衡位置对称的两时刻位移等大反向，速度大小方向可均相同】；警惕【竖直弹簧振子平衡位置弹力不为零（与重力平衡）；比较两时刻速度必须大小和方向都看图线斜率，不能只比大小】","src":"跳跳物一轮08.2 简谐运动的振动图像和振动方程_笔记","note":"视频|29:33","orig":"（例）竖直方向弹簧振子做简谐运动，振动图像峰值 $5\\,\\mathrm{cm}$、周期 $2\\,\\mathrm{s}$，验证方程 $x=5\\sin(\\pi t-\\frac{\\pi}{2})\\,\\mathrm{cm}$，并判断平衡位置弹力、$0.5\\sim 1.0\\,\\mathrm{s}$ 内路程、两时刻速度与加速度是否相同。","link":""},{"id":"phy2438","t":"振动图像·液体中物体的简谐运动","s":"看到【液体中物体做简谐运动（浮力参与提供回复力），判断某状态合力方向、能量守恒或验证方程】","c":"想到【位移为负（在平衡位置下方）时加速度指向平衡位置即向上，合力向上说明浮力大于重力；浮力做功，系统机械能不守恒；$12\\,\\mathrm{s}=3T$，路程为 $3\\times 4A=60\\,\\mathrm{cm}$；验证方程先算 $\\omega=\\frac{2\\pi}{T}=0.5\\pi\\,\\mathrm{rad/s}$，再代点验初相】；警惕【有重力、系统内弹力以外的力（此处为浮力）做功时机械能不守恒；$\\omega$ 必须按 $\\frac{2\\pi}{T}$ 计算，勿抄错数量级或漏除周期】","src":"跳跳物一轮08.2 简谐运动的振动图像和振动方程_笔记","note":"视频|34:35","orig":"（例）木棒在液体中做简谐运动，向下按 $5\\,\\mathrm{cm}$ 后释放，振幅 $5\\,\\mathrm{cm}$、周期 $4\\,\\mathrm{s}$、以竖直向上为正方向，判断位移为负时的加速度与浮力重力关系、机械能守恒、$12\\,\\mathrm{s}$ 内路程及振动方程正误。","link":""},{"id":"phy2439","t":"单摆·回复力与平衡位置","s":"看到【判断单摆回复力的来源，或平衡位置（最低点）处的受力情况】","c":"想到【回复力由重力的切向分力提供，方向沿圆弧切线；绳的拉力始终沿径向、与切线垂直，不提供回复力；最低点是平衡位置，此处重力与切线方向垂直、切向分力为零，回复力为零；但小球做圆周运动，重力与拉力的合力提供向心力，总合力不为零】；警惕【把重力和拉力的合力当成回复力；因最低点合力不为零而否认它是平衡位置】","src":"跳跳物一轮08.3 单摆、外力作用下的振动_笔记","note":"视频|00:25","orig":"（知识）单摆在竖直平面内来回摆动，回复力沿圆弧切线方向，由重力的切向分力提供，平衡位置在最低点。","link":""},{"id":"phy2440","t":"单摆·周期公式与摆长","s":"看到【单摆周期、摆长或重力加速度的计算与比较】","c":"想到【周期只与摆长 $L$ 和当地重力加速度 $g$ 有关，与小球质量、振幅无关；摆长是悬点到球心的距离，等于绳长加小球半径；光滑圆弧轨道上小球的摆长即圆弧半径；同一单摆在赤道与北极周期不同（两地 $g$ 不同）；题目未提偏角时默认公式成立】；警惕【把绳长当摆长（漏加小球半径）；比较周期时弄反单调性——$L$ 越大或 $g$ 越小，$T$ 越大】","src":"跳跳物一轮08.3 单摆、外力作用下的振动_笔记","note":"视频|03:02","orig":"（知识）单摆周期公式为 $T=2\\pi\\sqrt{\\frac{L}{g}}$，成立条件是最大偏角小于 $5^\\circ$。","link":""},{"id":"phy2441","t":"单摆·能量与振幅关系","s":"看到【单摆最高点与最低点间的能量转化，或由振幅比较机械能大小】","c":"想到【从最高点到最低点满足 $mgh=\\frac{1}{2}mv^2$（$h$ 为下落高度，$v$ 为最低点速度）；同一单摆振幅越大，最高点越高、$h$ 越大，机械能越大（最高点动能为零，机械能全部为重力势能 $mgh$）】；警惕【振幅大不代表最低点速度一定大，速度大小还与摆长有关；比较机械能必须在同一单摆（同摆长同 $g$）前提下进行】","src":"跳跳物一轮08.3 单摆、外力作用下的振动_笔记","note":"视频|05:47","orig":"（知识）单摆摆动过程中机械能守恒，从最高点到最低点重力势能转化为动能。","link":""},{"id":"phy2442","t":"等效重力摆·等效重力加速度求法与超失重单摆","s":"看到【斜面上、电场中或加速电梯里的单摆，求其周期】","c":"想到【周期 $T=2\\pi\\sqrt{\\frac{L}{g'}}$；$g'$ 由小球在平衡位置时背向圆心方向所有力的合力产生，列该合力等于 $mg'$ 的方程求解：斜面单摆 $g'=g\\cdot\\sin\\theta$（$\\theta$ 为斜面倾角），竖直向下匀强电场中 $g'=g+\\frac{qE}{m}$；超失重用反向添加 $ma$ 法：加速度向上（超重）$g'=g+a$、周期变小，加速度向下（失重）$g'=g-a$、周期变大】；警惕【$g'$ 不是当地重力加速度，不能直接代 $g$；斜面情形要先把各力沿斜面分解再取背向圆心方向，勿漏力】","src":"跳跳物一轮08.3 单摆、外力作用下的振动_笔记","note":"视频|07:48-12:14","orig":"（知识）回复力不由重力切向分力提供的单摆称为等效重力摆，周期公式中的 $g$ 换成等效重力加速度 $g'$。","link":""},{"id":"phy2443","t":"阻尼振动·特点与能量比较","s":"看到【阻尼振动中振幅、周期、频率、机械能随时间变化的判断】","c":"想到【阻尼振动振幅不断减小、机械能不断减小，但周期和频率不变、始终等于固有频率；比较两点能量套路：位移大小相等的两点在同一高度、重力势能相等，时刻靠后者机械能更小、动能更小；位移最大处（最高点）速度为零，一般位移处速度不为零】；警惕【振幅减小不代表频率减小，阻尼振动周期恒定；阻尼振动不是简谐运动（简谐运动振幅不变）】","src":"跳跳物一轮08.3 单摆、外力作用下的振动_笔记","note":"视频|15:29","orig":"（知识）阻尼振动是存在阻力使振幅逐渐减小的振动，但频率保持不变。","link":""},{"id":"phy2444","t":"受迫振动与共振·频率规律","s":"看到【受迫振动的周期频率判断，或由共振曲线分析振幅】","c":"想到【受迫振动的频率等于驱动力的频率，与系统固有频率无关；固有频率是系统自由振动（简谐运动）时的频率，由系统本身决定（单摆用 $T=2\\pi\\sqrt{\\frac{L}{g}}$ 计算）；驱动力频率越接近固有频率振幅越大，相等时振幅最大即共振；共振曲线峰值对应的横坐标就是固有频率，比较两摆振幅看驱动力频率离各自固有频率的远近】；警惕【受迫振动频率不等于固有频率，仅共振时两者相等；改变驱动力频率不会改变系统的固有周期】","src":"跳跳物一轮08.3 单摆、外力作用下的振动_笔记","note":"视频|17:30-18:25","orig":"（知识）受迫振动是周期性驱动力作用下的振动，其频率由驱动力决定；驱动力频率等于固有频率时发生共振。","link":""},{"id":"phy2445","t":"单摆·由拉力F-t图像求周期与摆长","s":"看到【给出单摆摆线拉力随时间变化的图像，求周期、摆长或某状态受力】","c":"想到【最低点绳子拉力最大（拉力与重力的合力提供向心力），拉力峰值对应经过最低点；连续两次经过最低点的时间间隔为半个周期，故周期为相邻峰值间隔的 2 倍；再由 $T=2\\pi\\sqrt{\\frac{L}{g}}$ 反解摆长 $L=\\frac{gT^2}{4\\pi^2}$，取 $\\pi^2\\approx 10$ 简算；回复力由重力切向分力提供，重力和拉力的合力提供向心力而非回复力】；警惕【把相邻两个拉力峰值的间隔当成一个周期（实为半周期）；摆长是悬点到球心的距离，不等于绳长】","src":"跳跳物一轮08.3 单摆、外力作用下的振动_笔记","note":"视频|20:42","orig":"（例）力传感器记录单摆摆线拉力随时间变化的 $F$-$t$ 图像，拉力周期性出现极大值（如相邻峰间隔 $0.8\\,\\mathrm{s}$，$g$ 取 $10\\,\\mathrm{m/s^2}$），判断回复力来源、最低点时刻并计算摆长。","link":""},{"id":"phy2446","t":"单摆·超失重周期变化与小摆角估算","s":"看到【单摆置于加速电梯中比较周期变化，或由振幅和摆长估算最大摆角】","c":"想到【向上匀加速为超重，$g'=g+a$ 变大，由 $T'=2\\pi\\sqrt{\\frac{L}{g'}}$ 知周期变小；向下匀加速为失重，$g'=g-a$ 变小，周期变大；小摆角（$\\theta<5^\\circ$）时 $\\tan\\theta\\approx\\theta$，最高点摆球偏离平衡位置的水平距离约为振幅 $A$，故 $\\theta\\approx\\frac{A}{L}$；摆长先由图像周期和 $T=2\\pi\\sqrt{\\frac{L}{g}}$ 反解得出】；警惕【$g'$ 增大时周期变小而非变大（在分母上）；估算摆角时振幅与弧长在小角下才可近似互换，摆长勿误用绳长】","src":"跳跳物一轮08.3 单摆、外力作用下的振动_笔记","note":"视频|30:08","orig":"（例）单摆振动图像给出周期 $2\\,\\mathrm{s}$（摆长可算得 $1\\,\\mathrm{m}$、$g$ 取 $10\\,\\mathrm{m/s^2}$），判断电梯向上或向下匀加速时新周期与 $2\\,\\mathrm{s}$ 的大小关系，并由振幅 $4\\,\\mathrm{cm}$ 估算最大摆角。","link":""},{"id":"phy2447","t":"机械波·形成条件与传播特性","s":"看到【判断产生机械波需要什么条件，或波源停止振动后波动是否立即消失】","c":"想到【产生机械波必须同时有波源和传播振动的介质，缺一不可；机械波不能在真空中传播；波上每个质点都做受迫振动，由波源依次带动相邻质点；波源停止振动后不再产生新波，但已产生的波动会继续传播】；警惕【把波源停振当成波动立即停止；真空中不能传播机械波，但电磁波可以】","src":"跳跳物一轮08.4 机械波、波形图_笔记","note":"视频|00:22","orig":"（知识）机械波的形成条件、对介质的要求，以及波源停止振动后波的传播情况。","link":""},{"id":"phy2448","t":"机械波·波长波速周期频率的决定因素","s":"看到【波源频率改变或波进入另一种介质，问周期、波速、波长各自如何变化】","c":"想到【周期和频率仅由波源决定，与介质无关；波速仅由介质决定，与波源无关；波长由波源和介质共同决定；核心公式$\\lambda=vT=v/f$，本质是一个周期内波走过的路程=速度×时间；同介质中增大波源频率，波速不变、波长变短】；警惕【波速是波形传播的速度，与质点振动速度是两回事；换介质时波长和波速变，周期频率不变】","src":"跳跳物一轮08.4 机械波、波形图_笔记","note":"视频|05:14","orig":"（知识）波的周期、频率、波速、波长各由什么决定，及相互关系公式。","link":""},{"id":"phy2449","t":"机械波·波形图可读量","s":"看到【给出波形图，问振幅、波长、周期、频率、波速中哪些能直接读出】","c":"想到【波形图相当于对正在传播的波拍一张照片：振幅=纵坐标最大值或最小值的绝对值，波长=相邻波峰（或波谷）间距即一个完整波形长度，二者可直接读；周期、频率、波速在波形图上看不出来，需结合波速数值或两个时刻的波形求出】；警惕【横坐标是各质点的平衡位置不是时间轴，不能像振动图那样直接读出周期】","src":"跳跳物一轮08.4 机械波、波形图_笔记","note":"视频|08:25","orig":"（知识）某一时刻的波形图上能直接读出哪些物理量。","link":""},{"id":"phy2450","t":"机械波·波形图上质点的加速度方向与路程","s":"看到【波形图中指定某质点，问其加速度方向，或问一段时间内通过的路程】","c":"想到【质点位移=该点纵坐标；加速度方向总是由当前位置指向平衡位置，离平衡位置越远加速度越大；路程=振动周期数×$4A$，质点振动周期等于波的周期；只有从平衡位置或最远点开始计时，$\\frac{1}{4}$周期内路程才等于振幅$A$】；警惕【质点只在平衡位置附近振动，不随波迁移；起点不在平衡位置和最远点时，$\\frac{1}{4}$周期路程可能大于也可能小于$A$】","src":"跳跳物一轮08.4 机械波、波形图_笔记","note":"视频|09:14","orig":"（知识）由波形图判断质点加速度方向，以及计算一段时间内质点通过的路程。","link":""},{"id":"phy2451","t":"机械波·同相反相质点的判定","s":"看到【问波形图上相距一定距离的两个质点振动步调是否相同或相反】","c":"想到【两质点平衡位置相距$n\\lambda$（$n$为整数）则同相，振动完全相同，位移和速度时刻相同；相距$(n+\\frac{1}{2})\\lambda$则反相，振动完全相反，一个在波峰时另一个必在波谷】；警惕【距离不是半波长的整数倍时既不同相也不反相；判断时用两质点间距除以波长，看商和余数】","src":"跳跳物一轮08.4 机械波、波形图_笔记","note":"视频|12:12","orig":"（知识）波形图上两个质点振动同相或反相的判定条件。","link":""},{"id":"phy2452","t":"机械波·同侧法","s":"看到【波形图上已知传播方向问某质点振动方向，或已知振动方向问波向哪边传播】","c":"想到【同侧法：在分析点画出已知方向的箭头（水平的传播方向或竖直的振动方向），再画另一个箭头并调整其指向，使两箭头都位于波形图线的同一侧（同在图线上方或同在下方），该箭头方向即为所求；可分别试探上下两个指向，只有满足同侧原则的那个才正确】；警惕【波峰、波谷处的质点瞬时速度为零，没有振动方向，不能用同侧法，应换相邻质点分析】","src":"跳跳物一轮08.4 机械波、波形图_笔记","note":"视频|13:48","orig":"（知识）已知波的传播方向求质点振动方向（或反过来）的同侧法操作步骤。","link":""},{"id":"phy2453","t":"机械波·起振方向判定","s":"看到【由波形图问波源或波上质点的起振方向（刚要开始振动时的方向）】","c":"想到【波上所有质点的起振方向都与波源的起振方向一致；沿波的传播方向找到波形图上的最远点（波刚传播到的点，即波前），该点此刻刚开始振动，用同侧法判断其当前振动方向，即为整个波的起振方向】；警惕【零时刻波形图上质点的振动方向不一定等于起振方向——零时刻是人为选定的，不一定是波源起振的时刻】","src":"跳跳物一轮08.4 机械波、波形图_笔记","note":"视频|17:54","orig":"（知识）由波形图分析波的起振方向，及起振方向与当前振动方向的区别。","link":""},{"id":"phy2454","t":"机械波·正弦波形特殊点","s":"看到【波形图上某质点位移为$(\\frac{\\sqrt{2}}{2})A$（约0.7倍振幅），求波长或位置关系】","c":"想到【从平衡位置到波峰的$\\frac{\\lambda}{4}$段，图线中点的位移为$(\\frac{\\sqrt{2}}{2})A$，该点距平衡位置$\\frac{\\lambda}{8}$、距波峰$\\frac{\\lambda}{8}$；利用特殊点的位置比例列式，可快速求出波长】；警惕【$(\\frac{\\sqrt{2}}{2})A$不是最大位移，不能当波峰处理；比例结论只对标准正（余）弦波形成立】","src":"跳跳物一轮08.4 机械波、波形图_笔记","note":"视频|34:08","orig":"（知识）简谐波形从平衡位置到波峰这段图线上特殊点的位移与位置关系。","link":""},{"id":"phy2455","t":"波的周期重复性·空间重复","s":"看到【问相距一定距离的两个位置波形是否相同，或两个质点运动情况的关系】","c":"想到【波形图是以$\\lambda$为周期的周期函数：相距$n\\lambda$（$n$为整数）的波形完全相同，相距$(n+\\frac{1}{2})\\lambda$的波形正好相反（一个在横轴上方、一个在下方）；波上质点同理，平衡位置相距$n\\lambda$的两质点位移、速度、加速度完全相同，相距$(n+\\frac{1}{2})\\lambda$则完全相反】；警惕【相距指两质点平衡位置之间的距离；距离不是半波长的整数倍时既不相同也不相反】","src":"跳跳物一轮08.5 波的周期重复性、波形图 振动图问题_笔记","note":"视频|00:27","orig":"（知识）波形图和波上质点在空间上的周期重复规律。","link":""},{"id":"phy2456","t":"波的周期重复性·时间重复与平移","s":"看到【问经过一段时间后的波形或质点状态，时间跨多个周期】","c":"想到【波的传播过程就是波形图沿传播方向平移：经过时间$t$平移距离$s=\\frac{t}{T}\\lambda$；经过$nT$平移$n\\lambda$，波形与原来重复；经过$(n+\\frac{1}{2})T$波形与原来相反；单个质点经$nT$运动状态复原，经$(n+\\frac{1}{2})T$状态相反】；警惕【平移是沿传播方向移波形，质点本身不随波移动；方向判反则平移方向也反】","src":"跳跳物一轮08.5 波的周期重复性、波形图 振动图问题_笔记","note":"视频|00:27","orig":"（知识）波的传播即波形图平移，及时间上的周期重复规律。","link":""},{"id":"phy2457","t":"波的周期重复性·整周期整波长化简","s":"看到【时间或距离数值很大（远超周期或波长），求波形或质点状态】","c":"想到【大数化简：把时间写成$nT$+余量、距离写成$n\\lambda$+余量，整周期（整波长）部分状态与初始相同直接扔掉，只分析不足一个周期（波长）的余量；如$102\\mathrm{s}=25T+\\frac{T}{2}$，状态与再过$\\frac{T}{2}$相同，即与初始时刻完全相反】；警惕【余量仍超过一个周期或波长时要继续化简；距离化简用的是质点平衡位置坐标，不是位移】","src":"跳跳物一轮08.5 波的周期重复性、波形图 振动图问题_笔记","note":"视频|08:10","orig":"（知识）利用周期重复性把整波长、整周期直接扔掉，只分析剩余部分。","link":""},{"id":"phy2458","t":"波形图·截断与传播范围误区","s":"看到【波形图只画到某处，问波传播到的最远位置或该点之后有无波形】","c":"想到【波形图是周期重复的，画到某点不代表波只传到那里，之后可能还有波形未画出；只有题目明确说明某时刻波（恰好）传播到某点，才能认为该点之后无波形；若未说明，默认波已传播到无限远】；警惕【把图形的截断当成波传播的终点；波前位置只能依据题目文字说明确定】","src":"跳跳物一轮08.5 波的周期重复性、波形图 振动图问题_笔记","note":"视频|06:33","orig":"（知识）波形图画到哪里不代表波只传播到哪里。","link":""},{"id":"phy2459","t":"波形图与振动图·三步法定传播方向","s":"看到【同时给出一个波形图和一个质点的振动图，问波向哪边传播或波速】","c":"想到【三步法：1在波形图上标出振动图所描述的质点；2在振动图上找到波形图对应的时刻，看图线是上扬还是下降，确定该时刻质点振动方向并画到波形图上；3在波形图上用同侧法判断传播方向。配套读数：波长从波形图读，周期从振动图读，振幅两图均可读，$v=\\lambda/T$】；警惕【振动图判方向看图线的上扬或下降趋势，不是看质点位置高低；两图必须对应同一列波】","src":"跳跳物一轮08.5 波的周期重复性、波形图 振动图问题_笔记","note":"视频|12:14","orig":"（知识）已知波形图和某质点的振动图，判断波的传播方向的三步法。","link":""},{"id":"phy2460","t":"波形图与振动图·振动图描述未知质点","s":"看到【振动图不知对应波形图上哪个质点，问该质点的位置或波速可能值】","c":"想到【两步法：1在振动图上找出波形图对应时刻的位移和振动方向；2在波形图上先找位移符合的点（如都在平衡位置），再用同侧法筛出振动方向也符合的点；满足条件的点沿$x$轴每隔一个波长重复出现，有无数个、不唯一，位置可写成$x=n\\lambda+x_0$（$x_0$为第一个满足点的坐标，$n=0,1,2…$）】；警惕【只找到一个点就下结论而漏解；波速可能值正是由这些点的位置方程解出的】","src":"跳跳物一轮08.5 波的周期重复性、波形图 振动图问题_笔记","note":"视频|16:05","orig":"（知识）已知波形图和某质点振动图但不知是哪个质点，确定其可能位置。","link":""},{"id":"phy2461","t":"波面图·圆形波波峰波谷判读","s":"看到【波源在O点的圆形波面图（实线、虚线同心圆）配某点振动图求各量】","c":"想到【实线圆为波峰、虚线圆为波谷，相邻波峰与波谷圆弧的间距为半波长$\\frac{\\lambda}{2}$，由此定波长；由波源到相邻波峰（波谷）的距离判断波源此刻在波峰还是波谷；波沿半径方向向外传播，某点振动方向沿该半径用同侧法分析；波在两点间传播时间=两点间距离/波速】；警惕【相邻波峰波谷间距是$\\frac{\\lambda}{2}$不是$\\lambda$；各方向波形都源自同一波源，起振时刻相同】","src":"跳跳物一轮08.5 波的周期重复性、波形图 振动图问题_笔记","note":"视频|27:08","orig":"（知识）圆形水面波的波面分布图（俯视同心圆）中波峰、波谷与波长的关系。","link":""},{"id":"phy2462","t":"波形图与振动图·波速可能值求解","s":"看到【已知传播方向、波形图和某质点振动图，求波速且选项给多个可能值】","c":"想到【由振动图在波形图上找出所有满足位移和振动方向的点，其位置满足$(n+\\frac{1}{2})\\lambda=d$（$d$为已知距离），解得$\\lambda=2d/(2n+1)$，代入$v=\\lambda/T$得波速通式，取$n=0,1,2…$逐一验证哪个选项对应整数$n$】；警惕【满足条件的点有无数个，只按一个点算会漏解；位置关系式要按本题的位移和方向条件推导，不能不经分析直接套$\\lambda/2$】","src":"跳跳物一轮08.5 波的周期重复性、波形图 振动图问题_笔记","note":"视频|41:55","orig":"（例）波沿$x$轴负方向传播，已知$t=2\\mathrm{s}$时的波形图与$x=2\\mathrm{m}$处质点的振动图（周期$T=4\\mathrm{s}$，$t=2\\mathrm{s}$时该质点位移为零、振动方向向下），求波速的可能值。","link":""},{"id":"phy2463","t":"波的多解·两质点振动图求波长","s":"看到【给出两个质点的振动图和它们间的距离，求波长或波速】","c":"想到【三步法：1由波的传播方向确定先振点和后振点；2把先振点的振动图沿时间轴向右平移，到与后振点的振动图第一次重合，平移量$\\Delta t_0$再加$n$个整周期即传播时间$\\Delta t=\\Delta t_0+nT$（$n=0,1,2…$）；3把传播时间换算成波长数，建立$(\\frac{\\Delta t_0}{T}+n)\\lambda=s$（$s$为两质点间距），解出波长通式；周期$T$从振动图直接读出，波速$v=\\lambda/T$】；警惕【必须从先振点的图向右平移到后振点的图，移反了时间就错；漏加$n$个整周期会丢掉多解】","src":"跳跳物一轮08.6 波的多解问题_笔记","note":"视频|01:20","orig":"（知识）已知波上两质点的距离和各自的振动图，求波长和波速的三步法。","link":""},{"id":"phy2464","t":"波的多解·传播方向未知的分类讨论","s":"看到【只给振动图或两时刻波形图加距离、时间，未说明传播方向，问可能值】","c":"想到【方向未知必分类讨论：波从A向B传时A是先振点，将A的振动图向右平移求滞后时间；波从B向A传时B是先振点，平移B的图；两个方向的平移量和所得通式（分母如$4n+1$与$4n+3$）都不同，要分别建立等式、分别解出波长波速通式，再分别验证选项；仅凭振动图和两点距离无法判断波的传播方向】；警惕【只按一个方向计算就排除选项；两个方向的通式分母不同，不能混用】","src":"跳跳物一轮08.6 波的多解问题_笔记","note":"视频|11:30-17:38","orig":"（知识）波的传播方向未知时，多解问题必须分两种方向分别求解。","link":""},{"id":"phy2465","t":"波的多解·两时刻波形图求周期","s":"看到【给出前后两个时刻的波形图和时间间隔，求周期或波速】","c":"想到【三步法：1区分早、晚时刻的波形图（波长$\\lambda$从图中直接读出）；2沿波的传播方向平移早时刻的波形，到与晚时刻的波形第一次重合，平移距离$l_0$再加$n$个整波长即传播距离$l=l_0+n\\lambda$（$n=0,1,2…$）；3把传播距离换算成周期数，建立$(\\frac{l_0}{\\lambda}+n)T=\\Delta t$（$\\Delta t$为两时刻的时间间隔），解出周期通式，波速$v=\\lambda/T$】；警惕【必须沿传播方向平移早时刻的图，不能反方向移；漏加$n$个整波长会漏解；传播方向未知要分左传右传两种情况】","src":"跳跳物一轮08.6 波的多解问题_笔记","note":"视频|13:27","orig":"（知识）已知两个时刻的波形图和时间间隔，求周期和波速的三步法。","link":""},{"id":"phy2466","t":"振动图·正弦特殊点A/2","s":"看到【振动图上某时刻位移为振幅一半A/2，求未知时间间隔或周期】","c":"想到【正弦函数从零到最大值的$\\frac{1}{4}$周期段内，函数值为$\\frac{A}{2}$的点位于该段的三分点，对应$\\frac{T}{12}$；振动图中读不出的时间段可用此比例表示，进而解出周期（如$3.3\\mathrm{s}+\\frac{T}{12}=T$，解得$T=3.6\\mathrm{s}$）】；警惕【$\\frac{A}{2}$对应$\\frac{T}{12}$，不是$\\frac{T}{8}$（$\\frac{T}{8}$对应$(\\frac{\\sqrt{2}}{2})A$）；图线在上升段还是下降段要数对】","src":"跳跳物一轮08.6 波的多解问题_笔记","note":"视频|19:06","orig":"（知识）正弦振动图从零到最大值的四分之一周期段内，位移为A/2的点的时间位置。","link":""},{"id":"phy2467","t":"波的多解·限制条件定唯一解","s":"看到【多解通式含n，题目又给间距小于波长或周期大于某值等限制】","c":"想到【把限制条件化为不等式：如两质点间距$s$小于波长$\\lambda$，将波长通式代入$s<\\lambda$解出$n$的取值范围，$n$取非负整数往往只剩一个值，代回通式即得唯一解（如$s=3\\mathrm{m}$、$\\lambda=\\frac{18}{6n+1}\\mathrm{m}$，由$3<\\frac{18}{6n+1}$得$n<\\frac{5}{6}$，唯一取$n=0$，$\\lambda=18\\mathrm{m}$）】；警惕【忽略限制条件，把多解当唯一解或把唯一解当多解；$n$只能取非负整数，不等式解出的范围要落到整数上】","src":"跳跳物一轮08.6 波的多解问题_笔记","note":"视频|19:06","orig":"（知识）多解通式中利用限制条件（如两点间距小于波长）确定n的唯一取值。","link":""},{"id":"phy2468","t":"波的多解·振动图分类讨论求波速可能值","s":"看到【两质点振动图加间距，方向未知，选项给出波长波速的具体可能值】","c":"想到【分两类：波从a向b传时a先振，a的振动图向右平移$1\\mathrm{s}$（$\\frac{T}{4}$）与b图重合，得$(\\frac{1}{4}+n)\\lambda=6\\mathrm{m}$，即$\\lambda=\\frac{24}{4n+1}\\mathrm{m}$；波从b向a传时b先振，平移$3\\mathrm{s}$（$\\frac{3T}{4}$），得$\\lambda=\\frac{24}{4n+3}\\mathrm{m}$；波速$v=\\lambda/T$即$\\frac{6}{4n+1}$或$\\frac{6}{4n+3}\\mathrm{m/s}$；把选项值代入两组通式，能解出非负整数$n$的才可能：$1.2\\mathrm{m/s}$对应$n=1$可能，$2\\mathrm{m/s}$对应$n=0$可能，$12\\mathrm{m}$两组均无整数解】；警惕【只用一个方向验证就下结论；代入后$n$不是非负整数则该值不可能】","src":"跳跳物一轮08.6 波的多解问题_笔记","note":"视频|25:19","orig":"（例）简谐横波在$x$轴上传播，a、b两质点平衡位置间距$6\\mathrm{m}$，已知两质点的振动图（周期均为$4\\mathrm{s}$），传播方向未知，判断波长可能是$12\\mathrm{m}$、波速可能是$1.2\\mathrm{m/s}$、波速不可能是$2\\mathrm{m/s}$等说法。","link":""},{"id":"phy2469","t":"波的多解·最小频率与最大周期","s":"看到【多解问题问最小频率、最大周期，或给出周期与时间差的范围关系】","c":"想到【频率$f=1/T$，最小频率对应最大周期；周期通式形如$T=\\frac{c}{4n+1}$，$n$取0时分母最小、周期最大（如$T=\\frac{0.24}{4n+1}\\mathrm{s}$，$n=0$时$T$最大为$0.24\\mathrm{s}$，最小频率约为$4.2\\mathrm{Hz}$）；若给范围如$2T<\\Delta t<3T$，则把通式代入不等式解出$n$的确定值，再求周期和波速】；警惕【最值方向搞反；给范围时用不等式定$n$，不能当成最值问题直接取$n=0$】","src":"跳跳物一轮08.6 波的多解问题_笔记","note":"视频|30:23","orig":"（知识）由周期通式求波的最小频率、最大周期，或由周期范围关系确定n的方法。","link":""},{"id":"phy2470","t":"波的干涉·干涉的三个必要条件","s":"看到【两列波相遇叠加，问能否发生干涉或判断干涉条件】","c":"想到【干涉条件缺一不可：波源频率相同（判断时最常用）、振动方向平行、相位差恒定；不要求振幅相同，振幅不同不影响干涉，只是减弱点振幅=$|A_1-A_2|$不为零】；警惕【把“振幅相同”错加进干涉条件；两列波频率不同时只能叠加不能干涉】","src":"跳跳物一轮08.7 干涉、衍射、多普勒效应_机械振动和机械波模块完_笔记","note":"视频|00:31","orig":"（知识）两列波叠加形成稳定干涉图样所需的条件。","link":""},{"id":"phy2471","t":"波的干涉·加强区减弱区特点与振幅位移易错","s":"看到【干涉图样中比较加强区与减弱区质点位移或强弱，问区域是否随时间移动交替】","c":"想到【加强区与减弱区相互隔开、位置固定，“强者恒强弱者恒弱”；各点仍在振动，振幅固定而位移时刻变化；振动强弱只看振幅：加强点振幅=$A_1+A_2$，减弱点振幅=$|A_1-A_2|$】；警惕【加强区质点的位移不一定大于减弱区质点：加强点回到平衡位置（位移0）而减弱点恰在波峰时，减弱点位移反而更大】","src":"跳跳物一轮08.7 干涉、衍射、多普勒效应_机械振动和机械波模块完_笔记","note":"视频|00:31","orig":"（知识）干涉图样中加强区、减弱区质点的位移大小比较及区域是否随时间变化。","link":""},{"id":"phy2472","t":"波的干涉·路程差判断加强点减弱点","s":"看到【给出某点到两波源的距离（路程差）及波源步调，判断加强点、减弱点】","c":"想到【波源步调相同（如同时过平衡位置向上）：路程差为偶数个半波长→加强点，奇数个半波长→减弱点；波源步调相反（一上一下）：结论相反，偶数个→减弱点，奇数个→加强点；步调由振动图像读出，如一个在最高点另一个在最低点即相反】；警惕【波源步调相反仍套用步调相同那套规则，把加强点减弱点判反】","src":"跳跳物一轮08.7 干涉、衍射、多普勒效应_机械振动和机械波模块完_笔记","note":"视频|03:57","orig":"（知识）已知两波源的振动步调，用某点到两波源的路程差判定加强点与减弱点。","link":""},{"id":"phy2473","t":"波的干涉·加强减弱性质不随时间改变","s":"看到【给定时刻干涉图样（实线波峰虚线波谷），判断某点加强减弱、速度或该点不好直接判断】","c":"想到【波峰遇波峰、波谷遇波谷为加强点，波峰遇波谷为减弱点；两列波振幅相等时减弱点振幅为零、始终静止、速度始终为零；不好判断的点看四分之一周期后，若两波峰同时到达该点则为加强点；某时刻判出的加强减弱性质此后保持不变】；警惕【认为加强点始终处于波峰，它仍在振动、位移时刻变化；任何质点振动频率都等于波源频率，频率不叠加】","src":"跳跳物一轮08.7 干涉、衍射、多普勒效应_机械振动和机械波模块完_笔记","note":"视频|14:24","orig":"（例）频率、振幅均相同的两列波稳定干涉，某时刻图中实线为波峰、虚线为波谷：A、C是波峰与波谷叠加点，B是波峰与波峰叠加点，O点不好直接判断；判断各点加强减弱性质与速度。","link":""},{"id":"phy2474","t":"机械波·半波长距离振动相反与整波长忽略","s":"看到【点到波源距离含整数波长加半波长（如$2\\lambda+\\frac{\\lambda}{2}$），判断该点加强减弱及振动方向】","c":"想到【先算波长$\\lambda=vT=4\\ \\mathrm{m}$；P到两波源路程差为0，属偶数个半波长，波源步调相同，故P为加强点；判振动方向：整波长距离振动完全相同，可忽略；半波长距离振动完全相反，故$S_1$过平衡位置向上时，P在平衡位置向下】；警惕【不剥离整波长直接拿P与波源比，振动方向判反；认为加强点始终在波峰，加强只说明振幅大】","src":"跳跳物一轮08.7 干涉、衍射、多普勒效应_机械振动和机械波模块完_笔记","note":"视频|17:54","orig":"（例）两波源振幅相等、振动步调相同（同时过平衡位置向上运动），周期0.8s，波速5m/s；P点到两波源距离均为10m，到$S_1$距离10m=$2\\lambda+\\frac{\\lambda}{2}$；求波长、P点加强减弱性质及振动方向。","link":""},{"id":"phy2475","t":"波的干涉·路程差范围法数加强减弱点个数","s":"看到【干涉中问某条连线或波源连线上加强点、减弱点的个数】","c":"想到【先算波长$\\lambda=vT$，再算该线两端点的路程差（距离用勾股定理求，相减）；化为半波长个数后在区间内数整数：波源步调相反时奇数个半波长为加强点、偶数个为减弱点，数出对应奇偶的整数个数；波源连线上两端点本身不算】；警惕【不先判步调用错奇偶；波源连线上数个数把两端点计入；振幅不等时减弱点不振幅为零，它仍振动、位移变化不会始终为某定值】","src":"跳跳物一轮08.7 干涉、衍射、多普勒效应_机械振动和机械波模块完_笔记","note":"视频|21:04","orig":"（例）两波源$S_1$、$S_2$振动步调相反，周期4s，波速0.25m/s；AB连线上A、B到两波源的路程差分别为2m和1m，两波源连线上两端点的路程差为$\\pm 6\\ \\mathrm{m}$；求AB连线上加强点个数与波源连线上减弱点个数。","link":""},{"id":"phy2476","t":"波的衍射·发生无条件与明显衍射条件","s":"看到【波遇到缝孔或障碍物（水波过窄缝、隔墙有耳），问衍射与缝宽波长关系】","c":"想到【任何波任何情况下都会发生衍射，无需条件，区别只在明显与否；明显衍射条件：缝、孔宽度或障碍物尺寸与波长差不多或比波长小；让衍射更明显的两法：减小缝孔尺寸，或改用波长更大的波】；警惕【说“波满足条件才发生衍射”；尺寸远大于波长时不是不发生衍射，只是不明显】","src":"跳跳物一轮08.7 干涉、衍射、多普勒效应_机械振动和机械波模块完_笔记","note":"视频|06:46-07:37","orig":"（知识）波发生衍射与发生明显衍射的条件，以及让衍射更明显的方法。","link":""},{"id":"phy2477","t":"多普勒效应·接收频率变化规律与应用","s":"看到【波源与观察者相对运动（鸣笛接近远离、红移、测速仪、B超），问接收频率变化】","c":"想到【相互靠近：接收频率大于发出频率，音调变高；相互远离：接收频率小于发出频率，音调变低；应用：炮弹尖叫声判远近、B超测血流、测速仪测速均利用多普勒效应；光的多普勒效应：星球远离时接收光频率变小、波长变长（红移）】；警惕【远离时光波波长变长而非变短；波源发出频率不变，变化的只是接收频率】","src":"跳跳物一轮08.7 干涉、衍射、多普勒效应_机械振动和机械波模块完_笔记","note":"视频|08:30-31:35","orig":"（知识）波源与观察者相对运动时接收频率的变化规律及典型应用。","link":""},{"id":"phy2478","t":"电荷量·标量比绝对值与净电荷量","s":"看到【比较电荷量大小（如$-5\\ \\mathrm{C}$与$+3\\ \\mathrm{C}$谁大）或问物体对外表现的电荷量】","c":"想到【电荷量是标量，正负只表示电性不参与比大小，只比较绝对值，故$-5\\ \\mathrm{C}>+3\\ \\mathrm{C}$；带电体对外显示的是正负电荷中和后的净电荷量，$+10\\ \\mathrm{C}$与$-9\\ \\mathrm{C}$中和后对外表现为$+1\\ \\mathrm{C}$而非19C；不带电不代表没有电荷，而是正负电荷完全中和】；警惕【把负号当大小参与比较得出+3C更大；把内部正负电荷量的绝对值相加当作对外表现的电荷量】","src":"跳跳物一轮09.1 电荷、起电与验电器_笔记","note":"视频|02:05","orig":"（知识）电荷量的性质、大小比较规则及对外表现的净电荷量。","link":""},{"id":"phy2479","t":"元电荷·最小电荷量单位","s":"看到【元电荷的性质、电荷量能否取任意值，或“质子是元电荷”这类说法】","c":"想到【元电荷是最小电荷量单位，$e=1.6\\times 10^{-19}\\ \\mathrm{C}$，任何带电体的电荷量都是元电荷的整数倍；元电荷是电荷量的单位而非实体粒子，只能说“质子所带的电荷量是一个元电荷”；元电荷本身没有正负；电子的电荷量最早由密立根油滴实验测出】；警惕【说“质子是元电荷”或给元电荷加正负号；微观粒子电荷量常用$e$作单位、宏观物体用C，别弄混】","src":"跳跳物一轮09.1 电荷、起电与验电器_笔记","note":"视频|05:06","orig":"（知识）元电荷的定义、性质与常见说法辨析。","link":""},{"id":"phy2480","t":"电荷守恒定律·守恒的是电荷量","s":"看到【电荷转移、起电或正负电子湮灭过程，问电荷总量是否守恒、粒子个数变化】","c":"想到【电荷既不会创生也不会消灭，只能从一个物体转移到另一个物体、或从物体的一部分转移到另一部分，转移过程中电荷总量保持不变；守恒的是电荷量而非带电粒子个数：正电子（$+1e$）与负电子（$-1e$）湮灭成光子，粒子个数由2变0，但总电荷量始终为0】；警惕【看到粒子湮灭就认为违背电荷守恒；把“带电粒子个数守恒”当成电荷守恒的内容】","src":"跳跳物一轮09.1 电荷、起电与验电器_笔记","note":"视频|08:48","orig":"（知识）电荷守恒定律的内容与守恒对象。","link":""},{"id":"phy2481","t":"摩擦起电·绝缘体间电子转移","s":"看到【两个绝缘体（玻璃棒与丝绸、橡胶棒与毛皮）摩擦后带电，问电性或电荷量关系】","c":"想到【摩擦起电的对象是两个对电子吸附能力不同的不带电绝缘体，本质是电子在两绝缘体之间转移：对电子吸附能力强的得电子带负电，弱的失电子带正电；结果是两物体带等量异种电荷，总电荷量仍为零】；警惕【认为绝缘体不能带电——绝缘体只是不能导电（电子不能自由移动）但可以带电；把摩擦起电的本质说成质子转移或凭空创造电荷】","src":"跳跳物一轮09.1 电荷、起电与验电器_笔记","note":"视频|10:25","orig":"（知识）摩擦起电的对象、本质与结果。","link":""},{"id":"phy2482","t":"接触起电·相同导体平分总电荷量","s":"看到【几个完全相同的带电导体球依次接触再分开，求最终各自电荷量】","c":"想到【完全相同的导体接触后平分总电荷量（带符号求和再除以2）：$Q_3$与$Q_1$接触，总和$+5\\ \\mathrm{C}$，各得$+2.5\\ \\mathrm{C}$；再与$Q_2$接触，总和$-0.5\\ \\mathrm{C}$，各得$-0.25\\ \\mathrm{C}$；接触起电本质是电子在导体间转移，分开后两球带同种电荷】；警惕【平分时不带符号运算导致电性判断错；两球形状、材质不同时不能平分；以为接触是平分电荷量的绝对值】","src":"跳跳物一轮09.1 电荷、起电与验电器_笔记","note":"视频|22:46","orig":"（例）三个完全相同的导体球，初始电荷量$Q_1=+5\\ \\mathrm{C}$、$Q_2=-3\\ \\mathrm{C}$、$Q_3=0$；$Q_3$先与$Q_1$接触后分开，再与$Q_2$接触后分开，求最终三球的电荷量。","link":""},{"id":"phy2483","t":"感应起电·近异远同与分开移走顺序","s":"看到【感应起电中导体分开与移走带电体的先后顺序不同，问最终带电或张角情况】","c":"想到【感应起电本质是电子在导体内部转移，不接地时导体总电荷量为零，规律“近异远同”：近端感应出与带电体相异的电荷、远端相同的电荷；先分开A、B再移走C：分开后正负电荷无法中和，A、B各自保留感应电荷，箔张开；先移走C再分开：A、B仍接触时正负电荷已中和，分开后不带电】；警惕【两种顺序结果完全不同，不能混；感应起电中导体并未与外界交换电荷，总电荷量始终为零】","src":"跳跳物一轮09.1 电荷、起电与验电器_笔记","note":"视频|24:46","orig":"（例）A、B两导体接触放置（均不带电），带正电的C靠近A端。比较：①C移近后先分开A、B再移走C；②C移近后先移走C再分开A、B；判断两种情况下A、B下方金属箔是否张开。","link":""},{"id":"phy2484","t":"感应起电·接地时近异远不带电","s":"看到【感应起电中导体接地（手指接触、接地线），问各端带电或撤去带电体后整体电性】","c":"想到【接地时规律“近异远不带电”：近端仍感应出与带电体相异的电荷，远端电荷被大地流入的异号电荷中和而不带电；手指接触相当于接地，远端的正电吸引地球电子流入导体；拿开手指后流入的电子留在导体中，整体带负电；再移走带正电的C，电子重新分布，两端均带负电】；警惕【认为接地后近端电荷也被中和；忽略“先断开接地再移走带电体”的顺序——若先移走C再断开，电荷将流回大地，最终不带电】","src":"跳跳物一轮09.1 电荷、起电与验电器_笔记","note":"视频|28:29","orig":"（例）带正电的C靠近相互接触的A、B导体（B为远端），B端接地（或用手指接触验电器小球相当于接地）；判断接地时A、B两端的带电情况，以及拿开地线（手指）再移走C后导体的整体带电情况。","link":""},{"id":"phy2485","t":"验电器·两种检验方式与金属箔电性","s":"看到【用验电器检验带电体（靠近不接触或直接接触），问金属箔张角与电性】","c":"想到【验电器原理是同性相斥使金属箔张开；两种检验方式：感应起电法（带电体靠近但不接触）与接触起电法（直接接触），两种方式下金属箔电性都与被检验物体相同；靠近不接触时把导体与验电器视为一个整体分析：近端带异种电荷，远端（验电器金属箔）带同种电荷】；警惕【认为带电体只靠近不接触时验电器不带电；混淆近端与金属箔（远端）的电性——两者相反】","src":"跳跳物一轮09.1 电荷、起电与验电器_笔记","note":"视频|29:19","orig":"（知识）用验电器检验带电体的两种方式及金属箔的电性规律。","link":""},{"id":"phy2486","t":"点电荷·理想化模型与判定依据","s":"看到【问某带电体能否视为点电荷，或点电荷与物体大小、电荷量多少的关系】","c":"想到【当带电体间的距离远大于自身大小，其形状、大小及电荷分布对作用力的影响可忽略时，可视为点电荷；本质是“带电的质点”，属于理想化模型，实际不存在；能否看作点电荷取决于所研究的问题，与物体自身尺寸无关】；警惕【认为“体积小的就能当点电荷、体积大的就不能”；把点电荷与元电荷（电荷量的单位）混淆】","src":"跳跳物一轮09.2 库仑定律_笔记","note":"视频|00:19","orig":"（知识）带电体可以看作点电荷的条件与对点电荷模型的理解。","link":""},{"id":"phy2487","t":"库仑定律·公式适用条件与电荷量符号处理","s":"看到【两点电荷间库仑力的计算，或问库仑定律适用条件、负电荷如何代入】","c":"想到【$F=kQ_1Q_2/r^2$，$k=9\\times 10^9\\ \\mathrm{N\\cdot m^2/C^2}$，力与电荷量乘积成正比、与距离平方成反比、方向在两点电荷连线上；适用条件：真空、静止、点电荷三者同时满足；库仑力、电场力、静电力是同一力的不同叫法；计算力的大小时电荷量一律取绝对值，负号只表示电性】；警惕【把负电荷量带符号代入公式；条件不满足时两点电荷间仍有库仑力，只是公式不适用；题目未特别说明时默认库仑定律成立直接计算】","src":"跳跳物一轮09.2 库仑定律_笔记","note":"视频|01:14","orig":"（知识）库仑定律的内容、公式、适用条件及电荷量符号的处理。","link":""},{"id":"phy2488","t":"库仑力·方向判定","s":"看到【已知两点电荷电性，判断各电荷所受库仑力的方向】","c":"想到【异种电荷相互吸引（引力）：每个电荷受的库仑力沿连线指向对方；同种电荷相互排斥（斥力）：每个电荷受的库仑力沿连线背向对方；两点电荷间的相互作用力遵循牛顿第三定律，总是等大反向】；警惕【“指向对方”“背向对方”的对象搞混；三个电荷共存时，每个电荷的库仑力要分别按另外两个电荷判断方向再合成】","src":"跳跳物一轮09.2 库仑定律_笔记","note":"视频|09:12","orig":"（知识）两点电荷间库仑力的方向规律。","link":""},{"id":"phy2489","t":"库仑定律·导体球近距离的静电感应修正","s":"看到【金属球（导体）间库仑力，球心距不足10倍半径，问实际力与球心距计算值比较】","c":"想到【导体球球心距小于10倍半径时静电感应不可忽略：异种电荷相互吸引，电荷中心向彼此靠近，实际中心距$d$小于球心距$l$，故实际库仑力$kQ^2/d^2$大于$kQ^2/l^2$；绝缘带电球无静电感应，$r$取球心距；球心距大于10倍半径（或可视为点电荷）时也取球心距】；警惕【近距离导体球仍取球心距计算；同种电荷时电荷中心相互远离、实际力偏小，别把偏差方向弄反】","src":"跳跳物一轮09.2 库仑定律_笔记","note":"视频|15:53","orig":"（例）两个带异种电荷的金属球壳，电荷量均为$Q$，球心距$l$仅为球半径的3倍；判断实际库仑力与用球心距计算的$kQ^2/l^2$的大小关系。","link":""},{"id":"phy2490","t":"库仑定律·三点共线平衡口诀","s":"看到【三个点电荷在同一直线上仅靠电场力均静止，判断电性、电量或位置关系】","c":"想到【口诀排除法：电性“两同夹异”（两边电性相同、中间相反）；电量“两大夹小”（中间电荷电量最小）；距离“近小远大”（电量小的离中间电荷近）；定量关系：中间电荷电荷量的倒数等于两边电荷电荷量的倒数之和；用口诀逐项排除，不必对每个电荷受力列方程】；警惕【不满足任一口诀的选项直接排除；“两大夹小”记反成中间电量最大；口诀只适用于三点共线、仅电场力作用的平衡】","src":"跳跳物一轮09.2 库仑定律_笔记","note":"视频|11:45-34:08","orig":"（例）A、B两点电荷（如A带$+4q$）固定在直线上，要在直线上引入第三个点电荷C，使三个点电荷仅在电场力作用下均静止；用口诀快速排除候选电荷量与位置选项。","link":""},{"id":"phy2491","t":"库仑定律·缓慢拉动中的相似三角形法","s":"看到【带电小球受重力、库仑力、绳拉力且“缓慢”移动，问距离、拉力变化或轨迹】","c":"想到【“缓慢”提示全程动态平衡；力的方向都在变，属不定角模型，用相似三角形法：力的三角形与几何三角形OAB相似（OA边对应重力、AB边对应库仑力、OB边对应拉力）；OA与重力均为定值，故AB与库仑力之比不变，而库仑力$=kQQ/AB^2$，推出AB距离不变；收绳时OB减小，拉力随之减小；B的轨迹是以A为圆心的圆弧】；警惕【对方向变化的力用正交分解硬算；认为收绳时AB距离会变或轨迹是直线；相似三角形对应边找错】","src":"跳跳物一轮09.2 库仑定律_笔记","note":"视频|20:37","orig":"（例）点电荷A固定，带同种电荷的小球B由绳系着，受重力、A的库仑斥力与绳拉力而平衡；现缓慢收绳使B移动；判断B与A的距离、绳拉力如何变化及B的运动轨迹。","link":""},{"id":"phy2492","t":"库仑定律·与牛顿第二定律结合的连接体内力","s":"看到【光滑水平面上两带电小球（连接体）共同加速，求外力与库仑力的关系】","c":"想到【两球加速度相同构成连接体，库仑力是内力：内力=被隔离部分质量/总质量×外力；先由库仑定律算内力（电荷量取绝对值），库仑力$=kQ^2/r^2$；两球质量相等时内力为外力的一半，故外力$F=2kQ^2/r^2$；也可整体求加速度再隔离其一验证】；警惕【把负电荷量带符号代入库仑力计算；内力公式的质量比弄反（应是“隔离部分质量比总质量”）；间距变化时库仑力不是恒力】","src":"跳跳物一轮09.2 库仑定律_笔记","note":"视频|26:29","orig":"（例）光滑绝缘水平面上，两个质量均为$m$的小球带等量异种电荷、保持间距$r$，在恒力$F$作用下一起做匀加速直线运动；求$F$与$r$、电荷量$Q$的关系。","link":""},{"id":"phy2493","t":"库仑定律·圆锥摆模型的合力方向与悬点受力","s":"看到【带电小球只受重力与库仑力做匀速圆周运动（电场版圆锥摆），问向心力、角速度或悬点受力】","c":"想到【合力提供向心力，方向始终指向圆心O，不是指向A球；由几何关系定夹角（$AB=2R$、$BO=R$得$\\theta=30^\\circ$），库仑力沿BA方向，其竖直分量平衡重力，库仑力$=mg/\\cos 30^\\circ$；角速度用圆锥摆公式$\\omega=\\sqrt{g/h}$，h为悬挂点到圆心的竖直距离；天花板对A的作用力要平衡两球总重力并抵消B对A库仑力的水平分力，故大于$2mg$】；警惕【把合力方向画成指向A球；认为天花板对A的力等于总重力$2mg$而漏掉库仑力水平分力；h误用绳长或AB长度】","src":"跳跳物一轮09.2 库仑定律_笔记","note":"视频|28:25","orig":"（例）带电球A静止悬挂于天花板下方，另一带电小球B与A相互吸引，只在重力和A的库仑力作用下于水平面内绕A正下方的O点做匀速圆周运动；已知$AB=2R$、$BO=R$；判断B的合力方向、角速度及天花板对A的作用力。","link":""},{"id":"phy2494","t":"电场强度·定义式与被定义量无关","s":"看到【场强的定义式 $E=F/q$，或问场强与试探电荷、电场力的关系】","c":"想到【$E=F/q$ 是定义式，场强由场源电荷和该点位置决定，与试探电荷的电性、电荷量、是否存在及所受电场力均无关（类比 $R=U/I$、$a=\\Delta v/\\Delta t$）；一切定义式的被定义量都与定义它的量无关；矢量方程代数计算时各量只带绝对值，纯标量方程才带正负号】；警惕【把 $q$ 加倍误认为 $E$ 加倍——实际 $F$ 随 $q$ 加倍而 $E$ 不变；动量定理、动量守恒需先设正方向再带正负号】","src":"跳跳物一轮09.3 电场强度、电场线_笔记","note":"视频|02:52","orig":"（知识）电场强度用试探电荷所受静电力与电荷量之比定义：$E=F/q$。","link":""},{"id":"phy2495","t":"电场强度·场强方向判定","s":"看到【电场中某点放入正电荷或负电荷，已知受力方向问场强方向（或反之）】","c":"想到【场强方向与正电荷受力方向相同、与负电荷受力方向相反；场强方向只由场源电荷决定，同一点换任何试探电荷，场强方向都不变；点电荷场源带正电时某点场强方向背向场源，带负电时指向场源】；警惕【把负电荷受力方向当成场强方向；同一点换不同试探电荷后误以为场强方向随之改变】","src":"跳跳物一轮09.3 电场强度、电场线_笔记","note":"视频|06:46","orig":"（知识）规定正电荷在电场中某点所受静电力的方向为该点场强的方向。","link":""},{"id":"phy2496","t":"电场强度·点电荷场强决定式","s":"看到【真空点电荷作场源，求某点场强大小或比较两点场强】","c":"想到【$E=kQ/r^2$ 是决定式：场强由场源电荷量 $Q$ 和距离 $r$ 共同决定，$Q$ 只代绝对值；$r$ 减半场强变为 4 倍；到点电荷等距离的各点场强大小相等，但方向沿径向各不相同，场强矢量并不相同】；警惕【把决定式当定义式用（决定式与试探电荷无关、但与 $Q$、$r$ 有关）；$Q$ 带符号代入；等距点只看大小就判场强相同】","src":"跳跳物一轮09.3 电场强度、电场线_笔记","note":"视频|14:41","orig":"（知识）真空中点电荷的场强由决定式 $E=kQ/r^2$ 计算。","link":""},{"id":"phy2497","t":"电场线·性质","s":"看到【电场线分布图，判断场强大小、方向或电场线说法正误】","c":"想到【疏密表示场强大小（越密场强越大），切线方向为该点场强方向；电场线从正场源或无穷远出发、终止于负场源或无穷远，永不指向正场源；电场线不相交、不闭合；电场线是假想的，电场本身才真实存在并遍布整个空间】；警惕【认为电场线真实存在或认为没画电场线处场强为零；认为电场线可以相交；把电场线方向直接当负电荷受力方向】","src":"跳跳物一轮09.3 电场强度、电场线_笔记","note":"视频|19:04","orig":"（知识）电场线是人为假想、用来描述场强分布的带箭头曲线。","link":""},{"id":"phy2498","t":"电场线·与运动轨迹的区别","s":"看到【问电荷是否会沿电场线运动，或沿曲线电场线判断电荷轨迹】","c":"想到【只有当电场线是直线、且电荷初速度为零或初速度方向与电场线共线时，运动轨迹才与电场线重合；曲线电场线中电荷受电场力沿切线方向，速度沿轨迹方向，轨迹不会与电场线重合】；警惕【看见电荷在某条电场线上就认为它沿线运动；漏掉初速度为零或与电场线共线这一前提条件】","src":"跳跳物一轮09.3 电场强度、电场线_笔记","note":"视频|19:04","orig":"（知识）一般情况下电场线不是电荷的运动轨迹。","link":""},{"id":"phy2499","t":"电场强度·F-q图像斜率法","s":"看到【$F$-$q$ 图像（过原点直线）比较不同点的场强】","c":"想到【由 $E=F/q$，$F$-$q$ 图像的斜率 $k=F/q$ 在数值上等于该点的场强，故两点场强之比等于两条直线斜率大小之比；也可取同一 $q$ 比较对应的 $F$，场强之比即电场力之比】；警惕【误把截距当物理量；比较斜率只比大小；坐标轴起点不为零时斜率不能由端点坐标粗算】","src":"跳跳物一轮09.3 电场强度、电场线_笔记","note":"视频|22:56","orig":"（例）电场中 A、B 两点分别放入试探电荷，给出两点的 $F$-$q$ 图像（两条过原点的直线），求两点场强大小之比。","link":""},{"id":"phy2500","t":"电场强度·两点电荷零场强点","s":"看到【两点电荷连线上某点合场强为零，求电荷间距或电荷量之比】","c":"想到【先定零场强点位置：同号电荷在两者之间，异号电荷在连线延长线上、靠电荷量较小的一侧；设该点到两场源距离为 $r_1$、$r_2$，由 $kQ_1/r_1^2=kQ_2/r_2^2$ 得 $r_1/r_2=\\sqrt{Q_1/Q_2}$，再由几何关系求电荷间距】；警惕【异号电荷之间场强同向、不可能为零，零点必在两电荷外侧；列方程时 $Q$ 只代绝对值，方向另行判断】","src":"跳跳物一轮09.3 电场强度、电场线_笔记","note":"视频|25:53","orig":"（例）真空中 $x$ 轴上有两个点电荷，$Q_1$ 电荷量为 $-Q$、$Q_2$ 电荷量为 $+8Q$，已知 $x=x_0$ 处合场强为零，求两电荷的间距。","link":""},{"id":"phy2501","t":"匀强电场·带电小球静态平衡","s":"看到【带电小球在匀强电场中被细线悬吊静止，求电场力或质量】","c":"想到【先由 $F=qE$ 求电场力（$q$、$E$ 均代绝对值，方向由电荷正负与场强方向定）；小球受重力、拉力、电场力三力平衡，用三角形定则列 $\\tan\\theta=F/(mg)$，解得 $m=qE/(g\\tan\\theta)$】；警惕【电场力方向搞反（正电荷沿场强方向、负电荷反向）；$\\theta$ 认错成与水平方向的夹角；10 的幂次运算出错】","src":"跳跳物一轮09.3 电场强度、电场线_笔记","note":"视频|34:11","orig":"（例）电荷量 $1.0\\times 10^{-6}\\ \\mathrm{C}$ 的带电小球用绝缘细线悬挂在 $E=3.0\\times 10^3\\ \\mathrm{N/C}$ 的匀强电场中静止，细线与竖直方向成 $37^\\circ$，求小球所受电场力和质量。","link":""},{"id":"phy2502","t":"场强叠加·等大特殊角结论","s":"看到【两个等大场强（或力）合成，夹角为 $0^\\circ$、$60^\\circ$、$90^\\circ$、$120^\\circ$、$180^\\circ$】","c":"想到【场强是矢量，叠加与力的合成法则完全相同：共线同向相加、反向大减小，不共线用平行四边形/三角形定则；等大两场强夹角 $0^\\circ$ 合场强 $2E$、$60^\\circ$ 合 $\\sqrt{3}E$、$90^\\circ$ 合 $\\sqrt{2}E$、$120^\\circ$ 合 $E$、$180^\\circ$ 合 0，其中 $60^\\circ$ 的 $\\sqrt{3}$ 倍结论最常考且推导麻烦必须记住】；警惕【把 $60^\\circ$ 与 $120^\\circ$ 的结论记反（$60^\\circ$ 是 $\\sqrt{3}$ 倍、$120^\\circ$ 是 1 倍）；合成的两个场强必须等大才能套用】","src":"跳跳物一轮09.4 场强叠加、静电的防止与利用_笔记","note":"视频|00:24","orig":"（知识）两个大小相等（均为 $E$）的场强叠加，夹角为特殊角时合场强有固定结论。","link":""},{"id":"phy2503","t":"场强叠加·正多边形点电荷割补法","s":"看到【正多边形顶点放点电荷（电荷不全相同），求几何中心场强】","c":"想到【等量同种电荷的正多边形中心场强为零；用割补法凑对称：在目标顶点同时补一个正电荷和一个等量负电荷（总效果为零、不改变原电场），使正电荷部分凑成等量同种电荷正多边形而在中心抵消，最后只需计算剩下的补入负电荷在中心产生的场强（大小用 $kQ/r^2$，$r$ 为外接圆半径）】；警惕【补的两个电荷必须等量异号，只补一个就改变了原电场；最后剩余电荷的正负决定场强方向（负电荷指向场源）】","src":"跳跳物一轮09.4 场强叠加、静电的防止与利用_笔记","note":"视频|02:15","orig":"（知识）带等量同种电荷的正多边形，其几何中心处的场强为零。","link":""},{"id":"phy2504","t":"场强叠加·非点电荷电场四种方法","s":"看到【带电球壳/圆环/金属板等非点电荷的电场，求某点场强】","c":"想到【对称法：对称分布电荷，对称点场强大小相等；填补法：缺一部分的球或圆环先补全再算，最后减去补入部分；等效法：点电荷+无限大金属板等效为点电荷与其镜像等量异种点电荷；微元法：均匀带电圆环 $n$ 等分，每份视为点电荷，垂直轴向的分量对称抵消、沿轴分量叠加】；警惕【对称法只保证大小相等、方向要另行判断；填补法最后必须扣除补入部分的贡献；均匀带电球壳外部等效于电荷集中于球心】","src":"跳跳物一轮09.4 场强叠加、静电的防止与利用_笔记","note":"视频|05:15","orig":"（知识）带电圆环、带电板等非点电荷电场的场强叠加有四种常用方法。","link":""},{"id":"phy2505","t":"静电平衡·导体内部场强为零","s":"看到【导体放入电场中，问内部场强、净电荷分布或附加电场】","c":"想到【静电感应使电子沿电场力方向移动、电荷重新分布，感应电荷在导体内部产生与外电场等大反向的附加电场，内部合场强为零；静电平衡的导体内部没有净电荷，净电荷只分布在外表面；高中默认只要把导体放入电场就达到静电平衡】；警惕【认为导体内部仍有未抵消的电场；认为内部存在净电荷（若有，其电场会破坏内部合场强为零）】","src":"跳跳物一轮09.4 场强叠加、静电的防止与利用_笔记","note":"视频|09:48","orig":"（知识）金属导体放入电场后达到静电平衡，内部合场强处处为零。","link":""},{"id":"phy2506","t":"静电屏蔽·两种方式与接地条件","s":"看到【金属罩/金属壳屏蔽电场，问是否需要接地或内外电荷影响】","c":"想到【屏蔽外电场：用金属罩罩住需保护的区域，接不接地都可以，罩内达到静电平衡、合场强为零；屏蔽场源：用金属罩罩住场源，必须接地——不接地时罩外表面感应出同种电荷对外仍有电场，接地后外表面电荷与大地中和、对外无电场】；警惕【两种方式接地要求混淆（屏蔽外电场不必接地、屏蔽场源必须接地）；误以为罩住场源不接地也能屏蔽；接地金属壳内外电荷互不影响】","src":"跳跳物一轮09.4 场强叠加、静电的防止与利用_笔记","note":"视频|12:53","orig":"（知识）静电屏蔽分屏蔽外电场和屏蔽场源（内电场）两种方式，接地要求不同。","link":""},{"id":"phy2507","t":"静电现象·尖端放电与静电吸附","s":"看到【避雷针、电子打火器、静电除尘、静电喷漆、口罩熔喷布等装置问原理】","c":"想到【尖端放电：导体尖端电荷密度大、周围场强大，使空气电离，异号电荷与尖端电荷中和——应用避雷针、燃气灶电子打火器（电极做针状）；防止：高压设备表面尽量圆润、避免尖端；静电吸附：异性相吸——静电除尘、静电喷漆、静电复印、口罩熔喷布阻隔带电微粒】；警惕【熔喷布阻隔病毒是静电吸附，不是静电屏蔽/静电平衡/尖端放电；静电除尘中尘埃须与集尘极板带异种电荷才会被吸引】","src":"跳跳物一轮09.4 场强叠加、静电的防止与利用_笔记","note":"视频|15:52-17:04","orig":"（知识）静电平衡导体外表面越尖锐处电荷密度越大，尖端可放电；异种电荷相吸可用于吸附。","link":""},{"id":"phy2508","t":"场强叠加·细杆与点电荷对称法例题","s":"看到【已知某点合场强为零，求另一点场强（涉及点电荷+带电细杆）】","c":"想到【由对称性，细杆在关于它对称的 A、M 两点产生的场强等大；用 B、C 两点电荷在 M 点的合场强（等大、夹角 $120^\\circ$，合场强等于单个场强）结合 M 点为零求出细杆场强大小；再算 B、C 在 A 点的合场强（等大、夹角 $60^\\circ$，合场强为 $\\sqrt{3}$ 倍），与细杆场强同向相加】；警惕【B、C 到 M 的距离与到 A 的距离不同（到 M 为 $a/\\sqrt{3}$、到 A 为 $a$），两处场强大小不同；$60^\\circ$ 与 $120^\\circ$ 结论用错】","src":"跳跳物一轮09.4 场强叠加、静电的防止与利用_笔记","note":"视频|17:39","orig":"（例）正三角形 ABC 边长 $a$，B、C 顶点固定电荷量均为 $Q$ 的正点电荷，M 为三角形中心；关于 AM 对称放置一根均匀带电细杆（与 BC 平行），电荷量为 $Q/2$，已知 M 点场强为 0，求顶点 A 处的场强大小。","link":""},{"id":"phy2509","t":"场强叠加·点电荷与金属板等效法","s":"看到【点电荷旁有无限大接地金属板，求板与电荷之间某点场强】","c":"想到【等效法（镜像电荷）：点电荷与无限大接地金属板间的电场，等效于在板另一侧对称位置放置等量异种点电荷后的电场（取原电荷所在一侧）；分别用点电荷场强公式算两个场源在待求点的场强，判断方向后合成】；警惕【镜像电荷必须与原电荷关于金属板对称且等量异号；两个场强方向要逐个判断（背离正电荷、指向负电荷）再决定相加或相减；O 到两场源的距离不同（$L/2$ 与 $3L/2$）】","src":"跳跳物一轮09.4 场强叠加、静电的防止与利用_笔记","note":"视频|30:48","orig":"（例）正点电荷 $Q$ 固定于 B 点，其左侧 $L$ 处有一无限大接地金属板，A 为板上正对 B 的点（AB=$L$），O 为 AB 中点，求 O 点的电场强度大小。","link":""},{"id":"phy2510","t":"电场力做功·路径无关与匀强电场两步法","s":"看到【匀强电场中电荷移动，求电场力做功（含大小和正负）】","c":"想到【做功只由初末位置决定，与沿直线还是曲线无关；匀强电场两步法：第一步用 $W=Eq\\cdot x$ 算大小（$q$、$E$、位移投影都取绝对值，$x$ 为位移沿电场线方向的投影长度）；第二步看电场力方向与位移方向的夹角定正负：锐角做正功、钝角做负功】；警惕【非匀强电场电场力不是恒力，不能套用此式，须改用电势差或动能定理；算大小时把 $q$ 的负号代进去导致正负混乱】","src":"跳跳物一轮09.5 电场力做功、电势能、电势、电势差、等势面_笔记","note":"视频|00:31-05:38","orig":"（知识）电场力做功与路径无关，只与初末位置有关；匀强电场中可用两步法计算。","link":""},{"id":"phy2511","t":"电势能·电场功能关系","s":"看到【电荷在电场中移动，已知做功求电势能变化（或反之）】","c":"想到【电场力做正功电势能减小、做负功电势能增大；$W_{AB}$ 等于初态电势能减末态电势能，与 $\\Delta E_p$（末减初）互为相反数；该关系对正、负电荷都适用，无需考虑电性；某点电势能等于把电荷从该点移到零势能面过程中电场力做的功】；警惕【$\\Delta E_p$ 是末减初、$W$ 是初减末，两者符号相反；电势能数值与零势能面选取有关，比较大小时须带正负号】","src":"跳跳物一轮09.5 电场力做功、电势能、电势、电势差、等势面_笔记","note":"视频|07:33","orig":"（知识）电场力做功与电势能变化的关系：$W_{AB}=E_{pA}-E_{pB}=-\\Delta E_p$。","link":""},{"id":"phy2512","t":"电势·定义与沿电场线降低","s":"看到【问某点电势与试探电荷的关系，或由电场线判断电势高低】","c":"想到【电势是标量，只由场源电荷和该点位置决定，与放入的试探电荷（是否存在、电性、电荷量）无关；沿电场线方向电势降低，电场线从 A 指向 B 则 $\\varphi_A>\\varphi_B$；电势高的地方场强不一定大，两者无必然联系；单位伏特，$1\\ \\mathrm{V}=1\\ \\mathrm{J/C}$】；警惕【把电势当矢量或认为与试探电荷有关；认为场强大处电势一定高；确定电势数值前忘选零势面】","src":"跳跳物一轮09.5 电场力做功、电势能、电势、电势差、等势面_笔记","note":"视频|11:05","orig":"（知识）电势 $\\varphi=E_p/q$，描述电场的能的性质；沿电场线方向电势逐渐降低。","link":""},{"id":"phy2513","t":"电势差·性质与W=qU","s":"看到【求两点间电势差或电荷移动时电场力做功，或问与零势面选取的关系】","c":"想到【$U_{AB}=-U_{BA}$，可分段求和 $U_{AB}=U_{AC}+U_{CB}$；电势差与零势面选取无关（零势面变则各点电势变、电势差不变）；$W=qU_{AB}$ 普适，三个量都是标量，负值必须带负号代入，等号两边角标顺序一致（顺毛驴）；微观粒子能量常用电子伏特，$1\\ \\mathrm{eV}=1.6\\times 10^{-19}\\ \\mathrm{J}$】；警惕【$U_{AB}$ 是 $\\varphi_A$ 减 $\\varphi_B$，角标颠倒正负号相反；$W=qU$ 中 $q$ 的正负漏带导致做功正负判断错】","src":"跳跳物一轮09.5 电场力做功、电势能、电势、电势差、等势面_笔记","note":"视频|14:44-16:38","orig":"（知识）电势差 $U_{AB}=\\varphi_A-\\varphi_B$，即电压；电场力做功 $W=qU_{AB}$ 对任意电场普适。","link":""},{"id":"phy2514","t":"等势面·性质与常见分布","s":"看到【等势面（或等差等势面）图，判断做功、场强大小或电场线关系】","c":"想到【同一等势面上移动电荷电场力不做功（$U=0$，$W=qU=0$）；等势面与电场线垂直，电场线带箭头、等势面不带；等差等势面越密集的地方场强越大；匀强电场的等势面是等间距平行线，点电荷电场的等势面是内密外疏的同心圆】；警惕【在等势面上移动电荷误认为做功不为零；认为等势面上各点场强也相同（只有电势相同）；忽视等差等势面疏密与场强大小的对应】","src":"跳跳物一轮09.5 电场力做功、电势能、电势、电势差、等势面_笔记","note":"视频|19:37-20:52","orig":"（知识）等势面是电场中电势相同的点构成的面，与电场线垂直。","link":""},{"id":"phy2515","t":"电势能·电性与电势高低关系","s":"看到【比较正电荷或负电荷在电势不同两点的电势能大小】","c":"想到【正电荷在电势越高的地方电势能越大（$E_p=q\\varphi$，同增同减）；负电荷在电势越高的地方电势能越小（不等号方向反转）；也可先比较两点电势再乘 $q$：$q$ 为负时电势能的大小关系与电势的大小关系相反】；警惕【对负电荷沿用正电荷的规律（电势高处电势能大）导致判断反向；比较电势能大小时忘带正负号】","src":"跳跳物一轮09.5 电场力做功、电势能、电势、电势差、等势面_笔记","note":"视频|25:52-27:41","orig":"（知识）同一电场中，正、负电荷的电势能随电势高低的变化规律相反。","link":""},{"id":"phy2516","t":"电势·不等量异种电荷综合判定","s":"看到【不等量异种点电荷电场，比较电势、判断场强方向或找场强零点】","c":"想到【不在同一条电场线上的两点比较电势时引入中间等势点过渡（A 与 S 等势，只需比较 P 与 A）；或用离场源距离判断：离正场源越近电势越高、离负场源越近电势越低；两异号电荷之间场强同向叠加不为零，零点在电荷量较小电荷的外侧，由 $kQ_1/r_1^2=kQ_2/r_2^2$ 解出唯一位置；同一等势面上移动电荷不做功，$W=qU$ 由电势差正负定做功正负】；警惕【不等量异种电荷连线上各区段场强方向分析错；忽略无穷远处场强也趋于零；$U_{TP}$ 借助同等势点转换时角标顺序出错】","src":"跳跳物一轮09.5 电场力做功、电势能、电势、电势差、等势面_笔记","note":"视频|31:26","orig":"（例）真空中 M 点固定 $+2Q$、N 点固定 $-Q$ 的两个点电荷；P、A 在同一条电场线上（P 在上游），S、T 在以 O 为圆心的同一圆形等势面上，A 也在该等势面上。判断：P 与 S 电势高低、T 点场强方向、MN 连线上场强零点个数、正检验电荷从 T 移到 P 电场力做功的正负。","link":""},{"id":"phy2517","t":"电场力做功·库仑力下滑块综合题","s":"看到【带电滑块沿斜面运动，某点加速度为零或速度为零，求功与电势差】","c":"想到【加速度为零处合力为零：重力、支持力、库仑力三力平衡，用三角形定则求出库仑力，再由库仑定律反求到 O 的距离；初末速度均为零的过程用动能定理：全程只有重力和电场力做功，两者之和为零，解出电场力做的功；再由 $W=qU$ 求电势差，正负号一并代入】；警惕【三力平衡的三角关系中角度用错；动能定理中重力做功漏乘沿斜面分量 $\\sin 30^\\circ$；电势差正负由 $W$ 与 $q$ 的符号共同决定】","src":"跳跳物一轮09.5 电场力做功、电势能、电势、电势差、等势面_笔记","note":"视频|44:52","orig":"（例）倾角 $30^\\circ$ 的光滑斜面，底端 O 处固定一带电小球；电荷量为 $q$、质量为 $m$ 的带电滑块从斜面上 A 点由静止释放，下滑经过 B 点时加速度为零，到达 C 点时速度再次为零，A、C 间沿斜面的距离为 $s$。求滑块在 B 点时到 O 的距离、从 A 到 C 电场力做的功及 A、C 间的电势差。","link":""},{"id":"phy2518","t":"静电场·电场线加轨迹三步法","s":"看到【电场线与粒子轨迹同图，问某点受力方向或两点速度、动能大小比较】","c":"想到【三步法：①选点，选轨迹与电场线的交点；②画力，电场力指凹侧且沿电场线切线，两条件唯一确定力的方向；③定速，把选点与待比两点分别连线，力与哪条连线成锐角就大致指向那个点，该点速度就大】；警惕【无论粒子从哪端进入轨迹，力指向的点速度都大（动力加速、阻力减速殊途同归）；别先看选项，先走完三步再对选项】","src":"跳跳物一轮09.6 电场轨迹问题、等量点电荷电场问题_笔记","note":"视频|00:44","orig":"（知识）已知电场线和带电粒子轨迹，分析电场力方向与各点速度大小的通用三步法。","link":""},{"id":"phy2519","t":"静电场·等势面加轨迹三步法","s":"看到【等差等势面与粒子轨迹同图，问电场力方向、电性或速度大小】","c":"想到【三步法照用，画力条件改为力指凹侧＋力垂直该点等势面的切线，两条件唯一确定电场力方向；可按电场线从高电势指向低电势且垂直等势面先补画电场线；定速只看轨迹和力，与电场线情形完全相同】；警惕【力沿切线是电场线的特征，等势面必须力垂切线，张冠李戴必错；轨迹弯曲方向改变的点附近要分段分析】","src":"跳跳物一轮09.6 电场轨迹问题、等量点电荷电场问题_笔记","note":"视频|05:02","orig":"（知识）已知等势面和带电粒子轨迹时，画电场力的依据与电场线情形不同，但定速方法相同。","link":""},{"id":"phy2520","t":"静电场·等量异种点电荷中垂线特点","s":"看到【等量异种点电荷的中垂线，问线上电势、场强大小或电场线分布】","c":"想到【中垂线上无电场线（否则会与其它电场线相交）；中垂线是等势面，可延伸到无穷远，而无穷远电势为零，故它也是零势面；线上中心处场强最大，沿中垂线向两侧场强逐渐减小；正电荷一侧电势为正，负电荷一侧电势为负】；警惕【中垂线电势为零但场强不为零，中心附近场强反而最大，别把零势面当成零场强面】","src":"跳跳物一轮09.6 电场轨迹问题、等量点电荷电场问题_笔记","note":"视频|08:08","orig":"（知识）等量异种点电荷连线的中垂线（中垂面）上的电场线、电势与场强分布结论。","link":""},{"id":"phy2521","t":"静电场·等量异种点电荷对称点场强与电势","s":"看到【等量异种电荷场中关于连线或中垂线对称的两点，问场强或电势关系】","c":"想到【对称点场强大小必相等，方向看该点电场线的切线（连线上关于中心对称的两点场强等大反向）；关于两电荷连线的对称点电势相等，关于中垂线的对称点电势互为相反数】；警惕【上下对称电势相等、左右对称互为相反数只对场源横放成立，场源竖放时结论互换，应按关于连线、关于中垂线来记忆】","src":"跳跳物一轮09.6 电场轨迹问题、等量点电荷电场问题_笔记","note":"视频|08:08","orig":"（知识）等量异种点电荷电场中，关于连线或中垂线对称的两点的场强与电势关系。","link":""},{"id":"phy2522","t":"静电场·等量同种点电荷中垂线与电势特点","s":"看到【等量同种点电荷电场，问中垂线上场强、电势或某点电势正负】","c":"想到【中垂线上有电场线（做题时建议自己补画），它不是等势面也不是零势面；中心处场强 $E=0$（两场源场强等大反向抵消），沿中垂线向两侧场强先增大后减小，存在最大值；全区域电势同号，两正电荷处处为正、两负电荷处处为负；上下、左右对称点电势都相等】；警惕【与等量异种混淆：同种电荷的中垂线既非等势面也非零势面，中心场强为零但电势不为零】","src":"跳跳物一轮09.6 电场轨迹问题、等量点电荷电场问题_笔记","note":"视频|14:07","orig":"（知识）等量同种点电荷（两正或两负）电场中，中垂线的场强分布与全区域电势符号。","link":""},{"id":"phy2523","t":"静电场·轨迹问题电性加速度动能判定","s":"看到【轨迹问题的选项问粒子电性，或两点加速度、动能的大小比较】","c":"想到【电性：画该点场强方向（沿电场线切线）与电场力方向比较，同向带正电、反向带负电；加速度：粒子仅受电场力，$a=qE/m$，电场线越密场强越大、加速度越大；动能与电势能：仅受电场力时两者之和守恒，力指向的点速度大、动能大，电势能则小】；警惕【电场线未标箭头（场源电性未知）时，电性与运动方向均无法判断，但速度大小、受力方向仍可判】","src":"跳跳物一轮09.6 电场轨迹问题、等量点电荷电场问题_笔记","note":"视频|16:07","orig":"（例）电场线与粒子轨迹同图，轨迹上有M、N两点，N处电场线更密，电场力方向大致指向N。判断粒子电性，并比较M、N两点的加速度与动能大小。","link":""},{"id":"phy2524","t":"静电场·虚线为电场线或等势面双情况讨论","s":"看到【轨迹配一簇虚线，题目不说明虚线是电场线还是等势面，问各量变化】","c":"想到【分两种情况各走一遍三步法：按电场线（力沿切线）与按等势面（力垂切线）画出的电场力方向相反，故速度、动能、电势能的变化结论恰好相反；但无论哪种，虚线越密处场强越大这一结论相同；两种情况下电性都无法判断（电场线方向未知）】；警惕【把其中一种情况的动能结论当成唯一答案；电势高低也均无法判断，不知电性就不能由电势能反推电势】","src":"跳跳物一轮09.6 电场轨迹问题、等量点电荷电场问题_笔记","note":"视频|28:44","orig":"（例）带电粒子从a点沿实线轨迹运动到b点，图中另有一簇疏密不同的虚线，未说明是电场线还是等差等势面，判断粒子动能、电势能、场强和电势的变化。","link":""},{"id":"phy2525","t":"静电场·等量同种电荷中垂面圆周运动模型","s":"看到【等量同种电荷分居圆心两侧，带电粒子在过圆心的中垂面内做匀速圆周运动】","c":"想到【从侧面看两场源在中垂面上重合，粒子所受库仑合力始终指向圆心O，提供向心力，可稳定回旋；中垂线上场强从O向外先增大后减小，不同半径处场强可能相等，由 $a=qE/m$ 两粒子向心加速度可能相等；再由 $a=v^2/r$ 且OM<ON，线速度大小关系不确定】；警惕【中垂线上场强非单调，别认定离O越远场强越小；电势能按 $E_p=q\\varphi$ 带符号计算，负电荷在电势高处电势能反而小】","src":"跳跳物一轮09.6 电场轨迹问题、等量点电荷电场问题_笔记","note":"视频|43:45","orig":"（例）真空中两个固定的等量正点电荷，O为连线中点，P、Q在连线上（PO=OQ），M、N在中垂线上（OM<ON）。两个相同的带负电粒子在过O点的中垂面内以O为圆心，分别以OM、ON为半径做匀速圆周运动，比较两粒子的电势能、向心加速度和线速度。","link":""},{"id":"phy2526","t":"静电场·匀强电场电势差与场强关系","s":"看到【匀强电场中已知场强和两点位置求电势差，或由电势差求场强】","c":"想到【$U=Ed$，其中 $d$ 是两点连线沿电场线方向的投影长度（连线不平行电场线时，过一点作电场线、过另一点作其垂线取垂线段）；推导：由 $W=qU$ 与 $W=Eqd$ 联立约去 $q$；计算时各量只代大小，电势差一律从高电势写到低电势，保证 $U$ 为正】；警惕【该式只适用于匀强电场；把两点连线长直接当 $d$（没作投影）是最常见错误】","src":"跳跳物一轮09.7 电势差与场强的关系_笔记","note":"视频|00:21","orig":"（知识）匀强电场中两点间电势差与场强的关系式、推导及使用规范。","link":""},{"id":"phy2527","t":"静电场·共线平行线段电势差比例","s":"看到【匀强电场中几点共线或线段平行，已知部分电势差求其它点电势】","c":"想到【共线或平行的线段，电势差之比等于长度之比，即 $U_{AB}/U_{CD}=AB/CD$；原因是各自沿电场线方向的投影比等于长度比（相似三角形）；书写电势差仍从高电势到低电势，避免出现负值】；警惕【比例只对共线或平行的线段成立；不平行也不共线的两段线段不能直接比长度】","src":"跳跳物一轮09.7 电势差与场强的关系_笔记","note":"视频|04:03","orig":"（知识）匀强电场中，共线或平行的线段上电势差与长度的比例关系。","link":""},{"id":"phy2528","t":"静电场·匀强场线段中点电势","s":"看到【匀强电场中已知线段两端电势，求中点电势或由中点电势反求端点】","c":"想到【线段中点的电势等于两端点电势之和的一半；由中点把线段分成等长两段、共线时电势差之比等于长度比，故两段电势差相等推得；应用：在最高最低点连线上找与第二高点等势的点（三点法）、由圆的一条直径一端电势求另一端（圆心为中点）、由中点电势反求端点】；警惕【仅匀强电场成立，点电荷等非匀强场不能用；对任意方向的线段都成立，不要求线段沿电场线方向】","src":"跳跳物一轮09.7 电势差与场强的关系_笔记","note":"视频|06:18","orig":"（知识）匀强电场中，任意一条线段中点的电势与两端点电势的关系。","link":""},{"id":"phy2529","t":"静电场·非匀强场等距电势差比较","s":"看到【同一电场线上等距的点或点电荷的同心圆等势面，比较两段电势差】","c":"想到【非匀强场中两点电势差等于两点间平均场强乘以沿电场线方向的距离；同一条电场线上取等距的两段，电场线越密（场强越大）的那段电势差越大；点电荷电场中离场源越近等势面越密，相同的半径间隔对应的电势差越大】；警惕【点电荷的等差等势面内密外疏，半径差相等的同心圆不是等差等势面；比较电势差大小只比绝对值，正负号仅表示电势高低不参与大小比较】","src":"跳跳物一轮09.7 电势差与场强的关系_笔记","note":"视频|07:25","orig":"（知识）非匀强电场中电势差与平均场强的关系，以及同一电场线上等距段电势差的比较。","link":""},{"id":"phy2530","t":"静电场·三点法求场强","s":"看到【匀强电场已知三点电势求场强，且三点连线间无垂直关系】","c":"想到【在电势最高点与最低点的连线上找与第二高点电势相等的点（常用中点电势等于两端平均），与第二高点连线即等势面；过等势面作垂线就是电场线方向（匀强场中电场线为直线）；再在沿电场线方向的线段上用 $E=U/d$ 求场强大小，选 $U$ 和 $d$ 最容易求的那条线】；警惕【别把最高最低点的连线本身当成等势面，等势面必须连接两个等电势的点；取 $d$ 的线段必须沿电场线方向】","src":"跳跳物一轮09.7 电势差与场强的关系_笔记","note":"视频|09:49","orig":"（知识）匀强电场中场强方向未知、已知三点电势且线段间无垂直关系时，用三点法（等势面法）求场强。","link":""},{"id":"phy2531","t":"静电场·正交法求场强","s":"看到【匀强电场已知三点电势求场强，三点间存在互相垂直的线段】","c":"想到【沿两条垂直边建 $x$、$y$ 轴，分别求两方向的电势差与分场强 $E_x=U_x/d_x$、$E_y=U_y/d_y$，分场强方向由该方向高电势指向低电势；两分场强互相垂直，合场强 $E=\\sqrt{E_x^2+E_y^2}$；三点所在平面与场强方向平行，场强无垂直该平面的分量，故合场强就是唯一场强】；警惕【不必再找第三个分量——若存在它必分解到 $x$、$y$ 方向，会与已知电势矛盾；分场强方向由各方向电势降低方向定，别统一沿坐标正方向】","src":"跳跳物一轮09.7 电势差与场强的关系_笔记","note":"视频|13:00","orig":"（知识）匀强电场中已知三点电势且线段间有垂直关系时，用正交分解法求场强。","link":""},{"id":"phy2532","t":"静电场·电场中能量守恒求电势与可达性","s":"看到【带电粒子只受电场力运动，已知各点动能，求电势、电势能或能否到达某点】","c":"想到【仅受电场力时动能与电势能之和守恒，总能量等于出发点动能加电势能；某点电势能=总能量-该点动能（如A点为$32-14=18\\,\\mathrm{eV}$）；再由 $\\varphi=E_p/q$ 求电势，电子 $q$ 为负值，电势与电势能反号（A点为$-18\\,\\mathrm{V}$）；判断能否到达某点：算该点电势能，若超过总能量则中途速度减为零、无法到达并反向返回】；警惕【电子带负电，$q$ 必须代负值，电势与电势能符号相反；别拿动能大小直接当电势高低比较】","src":"跳跳物一轮09.7 电势差与场强的关系_笔记","note":"视频|43:51","orig":"（例）电子在匀强电场中只受电场力，过O点时动能为32eV、电势为0；经过A点时动能为14eV，经过B点时动能为8eV。求A、B两点的电势，并判断电子能否到达电势更低的C点。","link":""},{"id":"phy2533","t":"静电场·等势面垂直关系求场强","s":"看到【匀强电场中已知两点电势相等，求场强大小和方向】","c":"想到【电势相等的两点（B、C）连线就是等势面；电场线垂直等势面且由高电势指向低电势，故场强沿AC方向由A指向C；大小用 $E=U_{AC}/d_{AC}$，$d$ 取沿电场线方向的AC长（$4\\,\\mathrm{m}$），得 $2\\,\\mathrm{V/m}$；D为AB中点，电势等于A、B电势之和的一半；题目已给等势面时优先用垂直关系直接求，不必正交分解】；警惕【$E=U/d$ 的 $d$ 必须沿电场线方向（此处是AC不是AB或BC）；场强方向必须由高电势指向低电势且垂直等势面】","src":"跳跳物一轮09.7 电势差与场强的关系_笔记","note":"视频|53:20","orig":"（例）匀强电场中，直角三角形ABC的顶点电势 $\\varphi_A=14\\,\\mathrm{V}$、$\\varphi_B=\\varphi_C=6\\,\\mathrm{V}$，∠C=90°，斜边 $AB=5\\,\\mathrm{m}$，D为AB中点。求D点电势、$U_{DC}$ 以及场强的大小和方向。","link":""},{"id":"phy2534","t":"电容器·电荷量定义与基本概念","s":"看到【问电容器的电荷量是多少，或两极板带电特点的判断】","c":"想到【电容器是彼此绝缘又相互靠近的导体，用于存储电荷，题目中默认指平行板电容器；两极板带等量异种电荷，板间电场视为匀强电场；电容器的电荷量指其中一个极板所带电荷量的绝对值】；警惕【正极板带$+2\\,\\mathrm{C}$、负极板带$-2\\,\\mathrm{C}$ 时，电荷量是$2\\,\\mathrm{C}$而不是两板绝对值之和$4\\,\\mathrm{C}$】","src":"跳跳物一轮09.8 电容器_笔记","note":"视频|00:19","orig":"（知识）电容器的构造、极板电荷特点以及电容器电荷量的定义。","link":""},{"id":"phy2535","t":"电容器·充放电电流方向判定","s":"看到【电容器充电或放电，问电路中电流方向或极板电荷量增减】","c":"想到【只分析正极板：充电时电流流入正极板（负极板流出），电荷量增加；放电时电流流出正极板（负极板流入），电荷量减少；与电源正极相连的极板带正电；电路中实际移动的是电子，电流方向与电子定向移动方向相反】；警惕【把放电时的电流方向弄反（放电是从正极板流出）；只盯着负极板分析容易搞反，应统一从正极板入手】","src":"跳跳物一轮09.8 电容器_笔记","note":"视频|02:10-05:25","orig":"（知识）电容器充电、放电过程中电流方向的快速判定方法。","link":""},{"id":"phy2536","t":"电容器·电容定义式与性质","s":"看到【问电容大意味着什么，或涉及电容与电荷量、电压关系的判断】","c":"想到【$C=Q/U$ 是比值定义式，适用于所有电容器，表示单位电压下容纳的电荷量，电容越大存储电荷本领越强；电容由电容器自身结构决定，与 $Q$、$U$ 无关，不带电时电容依然存在（类比水瓶容量与装水量无关）；单位法拉，$1\\,\\mathrm{F}=10^{6}\\,\\mu\\mathrm{F}=10^{12}\\,\\mathrm{pF}$】；警惕【电容大不等于电荷量大（还取决于充电电压，$Q=CU$），也不等于场强大；带相同电荷量时，电容大的电压反而小】","src":"跳跳物一轮09.8 电容器_笔记","note":"视频|07:31-09:15","orig":"（知识）电容的定义式、物理意义、单位换算及电容与 Q、U 的关系。","link":""},{"id":"phy2537","t":"电容器·平行板电容决定式","s":"看到【极板错开、插入电介质或改变板间距，问电容 C 的变化】","c":"想到【$C=\\frac{\\varepsilon_r S}{4\\pi k d}$，只适用于平行板电容器：$S$ 是两极板正对面积（错开时只算正对部分），$d$ 是板间距，$\\varepsilon_r$ 由介质决定；增大 $S$、增大 $\\varepsilon_r$、减小 $d$ 都使 $C$ 增大；真空或空气的 $\\varepsilon_r$ 约等于1，其它介质都大于1，故插入任何介质 $C$ 都增大】；警惕【插入或移出电介质不影响正对面积 $S$（$S$ 只由两板错开程度决定）；定义式适用所有电容器，决定式只适用平行板】","src":"跳跳物一轮09.8 电容器_笔记","note":"视频|11:52-15:17","orig":"（知识）平行板电容器电容的决定式及各参数（正对面积、板间距、介电常数）的理解。","link":""},{"id":"phy2538","t":"电容器·动态分析总流程","s":"看到【改变板间距、正对面积或介质，问电容、电荷量、电压、场强如何变化】","c":"想到【第一步分类：电容器接电源则 $U$ 不变，断开电源则 $Q$ 不变；第二步用决定式判断 $C$ 的变化；第三步用 $Q=CU$ 判断剩下的量（$U$ 不变时 $C$ 增大则 $Q$ 增大，为充电；$Q$ 不变时 $C$ 增大则 $U$ 减小）；第四步用 $E=U/d$ 分析场强；电荷量增大是充电（电流流入正极板），减小是放电】；警惕【不先判断“U不变还是Q不变”就套结论，全盘皆错；接电源时误以为 $Q$ 不变、断电源时误以为 $U$ 不变是最常见错误】","src":"跳跳物一轮09.8 电容器_笔记","note":"视频|15:50-17:00","orig":"（知识）平行板电容器动态分析的解题顺序：先分类不变量，再依次判断 C、Q 或 U、E。","link":""},{"id":"phy2539","t":"电容器·Q不变只变d的场强与储能","s":"看到【断开电源后增大或减小板间距，问场强 E 或储能的变化】","c":"想到【$Q$ 不变只变 $d$ 时不能直接用 $E=U/d$（$U$、$d$ 同时变），推导得 $E=U/d=Q/(Cd)=4\\pi kQ/(\\varepsilon_r S)$，与 $d$ 无关，故 $E$ 不变；储能可用 $E_C=\\frac{1}{2}CU^2$ 分析（选择题常用，大题需题目给出），$d$ 增大时 $C$ 减小、$U$ 增大，储能增大；功能关系理解：增大板间距时外力克服极板间引力做正功，储能增大】；警惕【“$E$ 不变”仅限 $Q$ 不变且只变 $d$；若 $Q$ 不变但改变 $S$ 或介质，$E=4\\pi kQ/(\\varepsilon_r S)$ 随之改变】","src":"跳跳物一轮09.8 电容器_笔记","note":"视频|17:27","orig":"（知识）电容器电荷量不变、只改变板间距 d 时，场强与储能的变化结论。","link":""},{"id":"phy2540","t":"电容器·板间电势分析口诀","s":"看到【电容器一极板接地，移动极板后问板间某点电势的变化】","c":"想到【顺高逆低看场线：顺着电场线方向移动极板，该点电势升高，逆着则降低；定Q孤板势不变：$Q$ 不变且移动的是不接地的极板时，该点电势不变；$d$ 不变时三步走：先由接地极板定零势面判断该点电势正负，再分析场强 $E$ 的变化，电势为正时 $E$ 越大电势越高，电势为负时 $E$ 越大电势越低】；警惕【“定Q孤板”只适用于 $Q$ 不变且只改板间距 $d$ 的情形；移动接地极板时必须回到“顺高逆低”，不能套特例口诀】","src":"跳跳物一轮09.8 电容器_笔记","note":"视频|19:12-23:05","orig":"（知识）电容器动态分析中，板间某点电势变化的判断口诀及各自适用条件。","link":""},{"id":"phy2541","t":"电容器·动态分析与油滴平衡","s":"看到【板间有带电油滴（或微粒）平衡，改变d、S或电源接法，问油滴运动或张角】","c":"想到【先分类再逐项分析：接电源 $U$ 不变——$S$ 减小则 $C$、$Q$ 都减小，电容器放电，电流从正极板流出；$d$ 增大则 $E=U/d$ 减小，油滴电场力小于重力，向下加速。断开电源 $Q$ 不变——$d$ 增大则 $E$ 不变，油滴仍静止；$C$ 减小使 $U=Q/C$ 增大，静电计张角变大；移动的是不接地极板，P 点电势不变】；警惕【静电计张角反映的是电压 $U$ 而非电荷量 $Q$；油滴运动由电场力与重力的大小比较决定，不能直接套电压结论】","src":"跳跳物一轮09.8 电容器_笔记","note":"视频|43:03","orig":"（例）平行板电容器板间有带电油滴恰好静止，两板间接静电计。讨论三种操作：接电源时两板错开（正对面积减小）；接电源时上极板上移（$d$增大）；断开电源后上极板上移。判断电流方向、油滴的运动、P点电势及静电计指针张角。","link":""},{"id":"phy2542","t":"静电场·带电粒子是否考虑重力的判断","s":"看到【题干未明说是否计重力，研究对象是粒子、小球、油滴等需自行判断】","c":"想到【题给条件优先：题干出现小g（如重力加速度为g）就要考虑，明说重力忽略不计就不考虑；未告知时看对象：宏观物体（小球、油滴）考虑，微观粒子（质子、电子、出现粒子二字）不考虑】；警惕【微观粒子但题干给了g仍要考虑重力；重力可忽略不等于质量可忽略，$F=ma$中质量不能取零】","src":"跳跳物一轮09.9 带电粒子在匀强电场中的运动_笔记","note":"视频|00:21","orig":"（知识）电场中处理带电粒子问题时如何判断是否计入重力。","link":""},{"id":"phy2543","t":"静电场·匀强电场中带电粒子的加速度公式","s":"看到【带电粒子在平行板匀强电场中只受电场力，求加速度或要用$a$列运动学方程】","c":"想到【联立$E=U/d$、$F=qE$、$F=ma$得$a=qU/(md)$，U为极板间电势差、d为板间距；粒子只经过板间一段时，U取初末位置间电势差】；警惕【题目用e表示电荷量时写成$a=eU/(md)$；粒子未走完全程却代全板电压】","src":"跳跳物一轮09.9 带电粒子在匀强电场中的运动_笔记","note":"视频|04:28","orig":"（知识）带电粒子只受电场力时加速度与极板电压的关系。","link":""},{"id":"phy2544","t":"静电场·带电粒子的类平抛方程","s":"看到【粒子以垂直场强方向的初速度进入偏转电场做类平抛运动】","c":"想到【垂直场强方向不受力做匀速直线，$x=v_0t$；沿场强方向初速度为零做匀加速，$y=\\frac{1}{2}at^2$，其中$a=qU/(md)$；消去$t$得轨迹$y=\\frac{1}{2}a\\left(\\frac{x}{v_0}\\right)^2$】；警惕【把场强方向当成竖直方向照搬重力平抛；沿场强方向初速度不为零时不能直接用$\\frac{1}{2}at^2$】","src":"跳跳物一轮09.9 带电粒子在匀强电场中的运动_笔记","note":"视频|06:18","orig":"（知识）带电粒子垂直场强方向射入匀强电场的运动分解与轨迹方程。","link":""},{"id":"phy2545","t":"静电场·电场中动能定理的电势差取法","s":"看到【带电粒子在电场中求速度或位移，准备列$qU=\\Delta E_k$】","c":"想到【只有电场力做功时$qU=\\Delta E_k$，U必须取粒子初、末位置间的电势差；粒子只走板间一段或中途撤去电压时，按实际过程取电势差（如走一半对应U/2）】；警惕【无脑代两极板间总电压；电荷量为e时写$eU=\\Delta E_k$与题面一致】","src":"跳跳物一轮09.9 带电粒子在匀强电场中的运动_笔记","note":"视频|08:03","orig":"（知识）对电场中的带电粒子列动能定理时电势差U的取法。","link":""},{"id":"phy2546","t":"静电场·示波器偏转角与偏移量公式","s":"看到【带电粒子先经加速电压$U_1$加速，再垂直进入电压$U_2$、板长$L$板距$d$的偏转电场，求偏转角或偏移量】","c":"想到【三阶段：加速场匀加速（$qU_1=\\frac{1}{2}mv_0^2$求$v_0$）→偏转场类平抛→出场后匀速直线打屏；$\\tan\\theta=U_2L/(2U_1d)$，$y=U_2L^2/(4U_1d)$，$q$、$m$全部约掉，偏移量与粒子种类无关，电性相同的粒子打在屏上同一位置】；警惕【电性相反偏转方向相反、打在屏另一侧；无加速电场（$v_0$直接给定）时不能套用此结论】","src":"跳跳物一轮09.9 带电粒子在匀强电场中的运动_笔记","note":"视频|12:01-15:56","orig":"（知识）粒子先经加速电场$U_1$加速、再进入偏转电场$U_2$后的偏转角与偏移量结论。","link":""},{"id":"phy2547","t":"静电场·类平抛出射速度反向延长线过中点","s":"看到【粒子离开偏转电场后匀速直线运动打到荧光屏，求打屏点到屏中心的距离】","c":"想到【类平抛出射速度的反向延长线过水平位移的中点（板中心）；以该点为顶点列相似三角形$y_1/(L/2)=OP/(L/2+L_2)$，$L_2$为偏转场右边界到屏的距离，解出$OP$】；警惕【把偏转电场内的偏移量当成打屏距离；相似三角形对应边比例写错】","src":"跳跳物一轮09.9 带电粒子在匀强电场中的运动_笔记","note":"视频|16:45","orig":"（知识）粒子飞出偏转电场后打在屏上位置的几何求法。","link":""},{"id":"phy2548","t":"静电场·不同粒子过同一示波器的比例结论","s":"看到【多种带电粒子从静止经同一示波器装置加速偏转，问打屏位置、时间或末动能之比】","c":"想到【偏移量与$q$、$m$无关→电性相同都打在同一位置；总时间$T=(2x_1+x_2)/v_0\\propto\\sqrt{m/q}$，代入得时间比$1:\\sqrt{2}:\\sqrt{2}$；末动能$E_k=(U_1+U')q$，因偏移量相同$U'$相同，动能比等于电荷量比$1:1:2$】；警惕【用$\\frac{1}{2}mv^2$逐个算动能把变量搅在一起；漏算偏转电场做的功】","src":"跳跳物一轮09.9 带电粒子在匀强电场中的运动_笔记","note":"视频|31:34","orig":"（例）质子、氘核、$\\alpha$粒子从静止先后经同一加速电场和偏转电场打在屏上（质量比1:2:4、电荷量比1:1:2），比较打屏位置、运动时间和末动能。","link":""},{"id":"phy2549","t":"静电场·喷墨打印机无加速电场的偏转","s":"看到【粒子不经加速电场、以给定初速度直接进入偏转电场，讨论偏移量与$q$、$d$、$U$、$v_0$的关系】","c":"想到【$y=\\frac{1}{2}\\cdot\\frac{qU}{md}\\cdot\\left(\\frac{L}{v_0}\\right)^2$，$q$、$U$在分子，$d$、$v_0^2$在分母：减小$q$或$U$使偏转量减小，减小$d$或$v_0$反而使偏转量增大】；警惕【套用示波器中偏移量与$q$无关的结论——那是靠加速电场把$q$约掉，本题$v_0$给定、$q$约不掉】","src":"跳跳物一轮09.9 带电粒子在匀强电场中的运动_笔记","note":"视频|31:34","orig":"（例）电荷控制式喷墨打印机没有加速电场，墨汁颗粒以初速度$v_0$直接进入板长$L$、板距$d$、电压$U$的偏转电场，要使字迹缩小应采取哪些措施。","link":""},{"id":"phy2550","t":"静电场·周期场U-t图转v-t图分析","s":"看到【平行板间电压随时间周期性变化（给出U-t图），分析带电粒子的运动】","c":"想到【$a=qU/(md)$，$q$、$m$、$d$为常数，$a$与$U$成正比，U-t图形状就是a-t图，可直接在U-t图上接着画v-t图：$a$的正负定斜率正负、大小定倾斜程度，v-t图面积=位移】；警惕【把U-t图当成v-t图直接读速度；不先确认粒子初速度和进入电场的时刻】","src":"跳跳物一轮09.10 周期场、复合场_笔记","note":"视频|00:20","orig":"（知识）平行板间电压周期性变化时分析带电粒子运动的核心方法。","link":""},{"id":"phy2551","t":"静电场·周期场进入时刻决定运动模式","s":"看到【带电粒子在交变电场中初速度为零，问是否掉头、往返或单向运动】","c":"想到【v-t图是否穿过$t$轴决定是否掉头：$t=0$进入且前半周期$a$为正、后半周期$a$等大反向时，图线始终在$t$轴上方，先加速后减速、始终朝同一方向不返回；$t=T/4$进入时图线反复穿过$t$轴，粒子不断掉头做折返运动】；警惕【进入时刻不同运动模式完全不同，照搬别的时刻的结论；只看电压正负对称就断定一定往返】","src":"跳跳物一轮09.10 周期场、复合场_笔记","note":"视频|01:48","orig":"（知识）初速度为零的粒子在不同时刻进入周期性电场，运动模式截然不同。","link":""},{"id":"phy2552","t":"静电场·复合场抛体的分解与重构路径","s":"看到【重力不可忽略的带电小球在匀强电场中做抛体或曲线运动，求力、动能或电势能变化】","c":"想到【先由轨迹定力：沿直线运动说明合力与速度共线，可反推电场力方向；曲线运动则分解——竖直方向只受重力、水平方向只受电场力，各自匀变速；功能关系用重构路径：重力、电场力做功均与路径无关，改为先竖直后水平的折线路径，竖直段只算重力做功、水平段只算电场力做功】；警惕【沿真实曲线逐段硬算功能关系；小球先升后降时忘记重力做功互相抵消、只剩电场力做功】","src":"跳跳物一轮09.10 周期场、复合场_笔记","note":"视频|06:01","orig":"（知识）重力不可忽略的带电小球在匀强电场中做抛体或曲线运动的分析方法。","link":""},{"id":"phy2553","t":"静电场·等效重力场法处理复合场圆运动","s":"看到【带电小球同时受重力和匀强电场力，在轻绳或圆轨道约束下做圆周运动】","c":"想到【把两场合成等效重力场：等效重力$F'$=重力与电场力的合力；过圆心沿$F'$方向的线与圆的交点是等效最低点（小球静止的位置），正对面是等效最高点；此后按纯重力场套路：等效最低到等效最高点合力做功$-F'\\cdot 2R$，恰能过圆的条件是等效最高点绳（轨道）弹力为零、$F'=mv^2/R$，最小动能$\\frac{1}{2}mv^2=\\frac{1}{2}F'R$】；警惕【等效最低点不是几何最低点；电场与重力共线（如竖直向上）时不必等效，直接用$qE$与$mg$的代数和】","src":"跳跳物一轮09.10 周期场、复合场_笔记","note":"视频|10:40","orig":"（知识）带电小球在重力场加匀强电场中做圆周运动的等效重力场法。","link":""},{"id":"phy2554","t":"静电场·复合场圆运动中动能与机械能的最值点","s":"看到【复合场中带电小球做圆周运动，问动能最大/最小、机械能最大/最小的位置】","c":"想到【动能最大在等效最低点、最小在等效最高点（都不是几何最高最低点）；系统总能量守恒：机械能+电势能不变，故机械能最大=电势能最小=沿电场力方向前进最远的点（如水平电场中的最右端），机械能最小=电势能最大=逆电场力方向最远的点】；警惕【把几何最高点当成动能最小或机械能最大点；机械能最值只由电场力做功决定，与等效最高最低点无关】","src":"跳跳物一轮09.10 周期场、复合场_笔记","note":"视频|48:58-59:37","orig":"（知识）复合场圆周运动中动能、机械能取最大最小值的位置判定。","link":""},{"id":"phy2555","t":"静电场·周期场粒子的射出条件与临界板距","s":"看到【粒子水平匀速射入交变电场，问沿原方向射出、极板长度或不碰撞的临界板距】","c":"想到【沿原方向射出=竖直分速度为零，在v-t图上找进入时刻之后$v=0$的时刻；板长$L=v_0t$；不碰板看v-t图面积：一个周期内$t$轴上下面积相等则回到中线，单侧最大位移（三角形面积）$\\le d/2$定最小板距；部分面积用相似三角形面积比=相似比平方求】；警惕【把电压周期当成射出周期；只算净位移漏看单侧极值导致碰板】","src":"跳跳物一轮09.10 周期场、复合场_笔记","note":"视频|17:01-25:52","orig":"（例）带电粒子以平行极板方向的初速度$v_0$射入电压周期性变化的平行板电场（U-t图已知），竖直方向初速度为零，分析恰沿原方向射出的时刻、极板长度以及不碰极板的最小板距。","link":""},{"id":"phy2556","t":"静电场·复合场曲线运动的最远点与动能最小点","s":"看到【复合场中带电小球做曲线运动，问离某条直线最远或动能最小时刻】","c":"想到【离直线最远处：把该直线平移到与轨迹相切，切点速度方向与直线平行；动能最小处：速度方向与合力方向垂直；在两处分别按$v_x/v_y=\\tan\\alpha$列比例，结合$v_x=at$、$v_y=v_0-gt$解时间】；警惕【把动能最小点当成最高点或速度为零处；两个特征点一般不重合，别用同一个时刻】","src":"跳跳物一轮09.10 周期场、复合场_笔记","note":"视频|37:10","orig":"（例）带正电小球以竖直初速度$v_0$射入水平向右的匀强电场（重力不可忽略），落点P与抛出点的连线OP和初速度方向成53°角（水平位移与竖直位移之比4:3），求电场力大小、P点动能、距OP最远的时刻和动能最小的时刻。","link":""},{"id":"phy2557","t":"静电场·复合场绳球模型的平衡与临界","s":"看到【复合场中绳系带电小球静止时偏离竖直方向$\\theta$角，问场强、恰过圆的临界量或最小动能】","c":"想到【静止平衡给出一切：电场力$F=mg\\tan\\theta$，场强$E=mg\\tan\\theta/q$，绳的拉力即等效重力$F'=mg/\\cos\\theta$；恰过圆条件为等效最高点拉力为零、$F'=mv^2/L$，最小动能$\\frac{1}{2}mv^2=\\frac{1}{2}F'L=mgL/(2\\cos\\theta)$】；警惕【电场力与重力之比是$\\tan\\theta$不是$\\sin\\theta$；最小动能按纯重力场算成$mgL/2$漏掉$\\cos\\theta$】","src":"跳跳物一轮09.10 周期场、复合场_笔记","note":"视频|48:58","orig":"（例）带电小球系在长$L$的轻绳上，处于水平向右的匀强电场中，静止时绳与竖直方向成$\\theta$角，此后恰能在竖直圆内做完整圆周运动，求电场强度、最小动能、机械能最小的位置及电势能的变化情况。","link":""},{"id":"phy2558","t":"静电场·E-x图的读法与画电场线","s":"看到【给出E-x（场强-位置）图像，问电场线方向、电势或电势差】","c":"想到【图线在x轴上方的区间场强沿x轴正方向（向右），在下方沿x轴负方向（向左），只看上下、不看单调性；E-x图只描述x轴上各点的场强，若该处场强不沿x轴，纵坐标是x方向的分场强】；警惕【把纵坐标正方向当成竖直向上；用$\\varphi$-x图的单调性法来画电场线】","src":"跳跳物一轮09.11 E-x图、φ-x图、Ep-x图_静电场模块完_笔记","note":"视频|00:58-04:33","orig":"（知识）E-x图的纵坐标含义与由图判断电场线方向。","link":""},{"id":"phy2559","t":"静电场·E-x图面积与电势差","s":"看到【E-x图中比较两点电势差大小或判断电势高低】","c":"想到【图线与x轴围成的面积=两点间电势差的大小，比较电势差只比面积绝对值；电势高低另由场向定：沿电场线方向电势降低，正电荷放在电势高处电势能大】；警惕【面积只给大小不给正负，$U_{AB}$的符号要靠场强方向另判；把面积直接当成电场力做的功】","src":"跳跳物一轮09.11 E-x图、φ-x图、Ep-x图_静电场模块完_笔记","note":"视频|05:05","orig":"（知识）E-x图中图线与x轴围成面积的物理意义。","link":""},{"id":"phy2560","t":"静电场·φ-x图的单调性与斜率","s":"看到【给出$\\varphi$-x（电势-位置）图像，问场强方向、大小或画电场线】","c":"想到【电场线方向看单调性：按单调区间分段，从电势最高点指向最低点（单调增区间电势升高、电场线向左，单调减区间电场线向右）；某点场强大小=该点切线斜率的大小，切线水平处场强为零】；警惕【套用E-x图看图线上下方的方法；忘取绝对值把斜率正负当场强方向】","src":"跳跳物一轮09.11 E-x图、φ-x图、Ep-x图_静电场模块完_笔记","note":"视频|06:26-08:29","orig":"（知识）$\\varphi$-x图的读法：由单调性画电场线、由斜率定场强。","link":""},{"id":"phy2561","t":"静电场·Ep-x图的斜率与电荷正负","s":"看到【给出Ep-x（电势能-位置）图像，问电场力、场强或电势分布】","c":"想到【同一电荷的Ep-x图，某点切线斜率的大小=该点电场力大小（$F=qE$）；正电荷时$E_p=q\\varphi$与$\\varphi$成正比，Ep-x图可直接当$\\varphi$-x图用；负电荷时先画关于x轴的镜像，镜像图当$\\varphi$-x图用】；警惕【负电荷直接把Ep-x图当$\\varphi$-x图，电势正负、场源电性全判反；把斜率大小直接当成场强大小】","src":"跳跳物一轮09.11 E-x图、φ-x图、Ep-x图_静电场模块完_笔记","note":"视频|09:33-11:10","orig":"（知识）Ep-x图的读法：斜率定电场力、电荷正负定图线形状。","link":""},{"id":"phy2562","t":"静电场·点电荷φ-x图的发散与中点电势","s":"看到【两个点电荷电场的$\\varphi$-x图，图线趋于正负无穷，判断电荷电性与电量】","c":"想到【图线趋于$+\\infty$处场源是正电荷，趋于$-\\infty$处是负电荷；连线中点电势=两点电荷电势的代数和（到中点等距，正负由电量代数和决定），据此比电量大小；某点切线斜率的绝对值=该点场强大小，切线水平处场强为零】；警惕【$\\varphi=kQ/r$中Q不代正负号；用图线高低比较场强大小（应比切线斜率）】","src":"跳跳物一轮09.11 E-x图、φ-x图、Ep-x图_静电场模块完_笔记","note":"视频|20:21","orig":"（知识）两点电荷电场$\\varphi$-x图中由发散点、中点电势和斜率获取的信息。","link":""},{"id":"phy2563","t":"静电场·φ-x图中的能量守恒与能否通过判断","s":"看到【带电粒子在$\\varphi$-x图描述的电场中运动，问能否到达某点、在哪往复】","c":"想到【先算总能量：总能量=动能+电势能，电势能$E_p=q\\varphi$（$q$带符号）；某点可达的条件是该点电势能不超过总能量（动能=总能量-电势能，须非负）；电势能超过总能量的区域进不去，粒子在势垒两侧往复运动】；警惕【负电荷的$E_p=q\\varphi$符号算错（电势越高电势能越小）；只看动能忘了与电势能加总比较】","src":"跳跳物一轮09.11 E-x图、φ-x图、Ep-x图_静电场模块完_笔记","note":"视频|15:39","orig":"（例）电荷量为$-e$的试探电荷在$\\varphi$-x图所示的电场中沿x轴运动，经过电势为1V的$x_2$点时动能为1.5eV，判断能否通过电势为2V的$x_3$点和电势为-1V的$x_0$点，并分析运动情况。","link":""},{"id":"phy2564","t":"静电场·Ep-x图与Ek-x图的关系","s":"看到【由Ep-x图推断对应的$\\varphi$-x、E-x、Ek-x图像形状】","c":"想到【Ep-x图切线斜率的绝对值=电场力大小，其变化趋势定E-x图的走势（斜率减小则场强减小的下降曲线）；仅电场力做功时总能量守恒，Ek-x与Ep-x变化趋势相反：Ep减小则Ek增大，且Ek-x斜率的绝对值=合力大小，也随电场力减小而减小】；警惕【把Ek-x图画成与Ep-x图同趋势；忘用能量守恒判断Ek增减】","src":"跳跳物一轮09.11 E-x图、φ-x图、Ep-x图_静电场模块完_笔记","note":"视频|24:22","orig":"（知识）由Ep-x图推断$\\varphi$-x图、E-x图和Ek-x图的形状。","link":""},{"id":"phy2565","t":"静电场·粗糙面上带电滑块的Ep-x图分析","s":"看到【带电滑块在粗糙面上运动并给出Ep-x图，问能否到达、合力或场源电荷】","c":"想到【Ep相等的两点间电场力做功为零，这段用动能定理只剩摩擦力做功$-\\mu mg\\cdot\\Delta x$，可判断能否到达；某点合外力=摩擦力+电场力，电场力大小由Ep-x图切线斜率绝对值给出、方向指向Ep减小的一侧；切线水平处场强为零，两点电荷场强抵消满足$kQ_1/r_1^2=kQ_2/r_2^2$，可比电量】；警惕【全程套电势能加动能守恒而漏掉摩擦生热；把电场力方向判反（应沿Ep下降方向）】","src":"跳跳物一轮09.11 E-x图、φ-x图、Ep-x图_静电场模块完_笔记","note":"视频|26:23","orig":"（例）带负电滑块在粗糙绝缘水平面上从x=1m处沿x轴以初速度$v_0$滑出，其Ep-x图中x=1m与x=4m处电势能相等、x=3m处图线切线水平，判断能否到达x=4m、x=3m处合外力、两场源电荷电量关系及加速减速情况。","link":""},{"id":"phy2566","t":"电流、电阻·电流定义式与宏观决定式的区分","s":"看到【问 $I$ 与 $q$、$t$ 或与 $U$、$R$ 是否有关，或对电动机等元件用欧姆定律求电流】","c":"想到【定义式 $I=q/t$ 是比值定义，被定义量 $I$ 与 $q$、$t$ 均无关；决定式 $I=U/R$ 中 $I$ 由 $U$、$R$ 共同决定，仅适用于纯电阻元件和电解质溶液；形成稳定电流需要闭合回路和电压（电压就是电势差）】；警惕【电动机等非纯电阻元件把电能转化为机械能，用 $I=U/R$ 算电流必错；$q$ 是通过整个横截面的电荷量，不是单位横截面积的】","src":"跳跳物一轮10.1 电流、电阻_笔记","note":"视频|04:10-05:23","orig":"（知识）电流的定义式 $I=q/t$ 与宏观决定式（欧姆定律）$I=U/R$ 性质不同。","link":""},{"id":"phy2567","t":"电流、电阻·电流微观表达式与n的含义","s":"看到【给出单位体积或单位长度内的自由电荷数，求电流或电荷数 $n$】","c":"想到【$I=neSv$ 中 $n$ 为单位体积内电子数、$e$ 为单个电子电荷量、$S$ 为横截面积、$v$ 为电子定向移动平均速率，适用于一切电路；若 $n$ 表示单位长度内的电子数，则 $n_L=n_V \\cdot S$，公式变为 $I=nev$（不再含 $S$）】；警惕【$n$ 的定义不同公式形式就不同，代入前必须先确认 $n$ 是单位体积还是单位长度的电子数】","src":"跳跳物一轮10.1 电流、电阻_笔记","note":"视频|06:56","orig":"（知识）电流微观表达式 $I=neSv$ 中各字母含义及 $n$ 的两种定义。","link":""},{"id":"phy2568","t":"电流、电阻·与电子相关的三种速率","s":"看到【比较电子定向移动速率、热运动速率与电流传导速率的大小】","c":"想到【电子定向移动平均速率约 $10^{-5}$ $\\mathrm{m/s}$，最慢，即微观表达式中的 $v$；电子热运动平均速率约 $10^{5}$ $\\mathrm{m/s}$，远大于定向移动速率；电流（电场）传导速率约 $3\\times 10^8$ $\\mathrm{m/s}$，等于光速，最快】；警惕【三者相差十个数量级左右，混用会得出合闸瞬间电子即刻到达灯泡的荒谬结论】","src":"跳跳物一轮10.1 电流、电阻_笔记","note":"视频|06:56","orig":"（知识）金属导体中与电子相关的三种速率数量级差异巨大。","link":""},{"id":"phy2569","t":"电流、电阻·电阻定律与体积不变的形变技巧","s":"看到【导体被拉长、对折或截断，强调体积（材料量）不变，问新电阻】","c":"想到【$R=\\rho L/S$，由材料电阻率 $\\rho$、长度 $L$、横截面积 $S$ 决定；体积不变时长度变为原来的 $n$ 倍，$S$ 必变为原来的 $1/n$，电阻变为原来的 $n^2$ 倍；对折则长度减半、面积加倍，电阻变为 $1/4$】；警惕【截去一段时横截面积不变、仅长度减小，电阻随长度线性减小，不能套用 $n^2$ 结论；$n^2$ 技巧的前提是体积不变】","src":"跳跳物一轮10.1 电流、电阻_笔记","note":"视频|14:13","orig":"（知识）电阻定律 $R=\\rho L/S$ 及导体体积不变时的形变结论。","link":""},{"id":"phy2570","t":"电流、电阻·伏安特性曲线（I-U图）读电阻","s":"看到【$I$-$U$ 图或 $U$-$I$ 图上给定点求电阻，或由图线形状判断元件类型】","c":"想到【$I$-$U$ 图中连接该点与原点的割线斜率的倒数等于该点电阻，切线斜率无物理意义；$U$-$I$ 图（横轴 $I$、纵轴 $U$）割线斜率直接等于电阻；图线为过原点直线是线性元件（标准电阻），曲线表示温度影响阻值，割线越平缓电阻越大】；警惕【动笔前先看清坐标轴是 $I$-$U$ 还是 $U$-$I$，两者求电阻方式相反；斜率须用 $\\Delta I/\\Delta U$ 计算，只有横纵轴标度相同时才等于 tan 值，不能用角度正切直接求阻】","src":"跳跳物一轮10.1 电流、电阻_笔记","note":"视频|16:04","orig":"（知识）$I$-$U$ 图（纵轴 $I$、横轴 $U$）中电阻的求法与图线形状含义。","link":""},{"id":"phy2571","t":"电流、电阻·串并联总电阻变化规律","s":"看到【电路中增大某支路电阻或新增一条支路，问总电阻变化】","c":"想到【串联增加一个电阻，总电阻变大，总电阻等于各阻值之和；并联中在某支路内增加电阻，该支路更难走，总电阻变大；新增一条支路相当于多开辟一条通路，总电阻变小；两电阻并联 $R=R_1 R_2/(R_1+R_2)$，两相同电阻并联总电阻为每个的一半】；警惕【新增支路使总电阻变小，与支路内加电阻使总电阻变大方向相反，二者最易混淆】","src":"跳跳物一轮10.1 电流、电阻_笔记","note":"视频|20:23","orig":"（知识）串、并联电路中增加电阻或增加支路对总电阻的影响。","link":""},{"id":"phy2572","t":"电流、电阻·细胞膜等效电容的跨膜电流","s":"看到【细胞膜视为电容器，给出膜电容、电势差变化量与时间，求平均电流】","c":"想到【跨膜电荷量等于电容器单极板所带电荷量的变化量，$\\Delta Q=C \\cdot \\Delta U$；先由末态电势差减初态电势差（带符号）求 $\\Delta U$，再代入 $I=\\Delta Q/\\Delta t$ 求平均电流】；警惕【$\\Delta U$ 必须末减初并保留正负号，负电势差变到正电势差时变化量是两者绝对值之和而非直觉的代数差；mV、ms、$\\mu$F 类单位先换算为 SI 单位】","src":"跳跳物一轮10.1 电流、电阻_笔记","note":"视频|24:21","orig":"（例）细胞膜可视为电容器，电容 $C=1\\times 10^{-8}\\ \\mathrm{F}$，膜两侧电势差在 2 ms 内由 $-70\\ \\mathrm{mV}$ 均匀变为 $30\\ \\mathrm{mV}$，求此段时间的平均跨膜电流。","link":""},{"id":"phy2573","t":"电流、电阻·电子绕核的等效环形电流","s":"看到【电子等带电粒子绕核做周期性圆周运动，求等效电流】","c":"想到【等效环形电流用定义式 $I=q/T$：取一个周期 $T$，通过横截面的电荷量恰为电子电荷量 $e$；周期由库仑力提供向心力求得 $ke^2/r^2=m \\cdot 4\\pi^2 r/T^2$，即 $T=2\\pi\\sqrt{mr^3/(ke^2)}$，故 $I=e/T$】；警惕【周期必须由向心力方程重新求出，不能跳步直接套；等效电流方向与电子实际运动方向相反】","src":"跳跳物一轮10.1 电流、电阻_笔记","note":"视频|29:01","orig":"（例）电子（质量 $m$、电荷量 $e$）绕原子核做半径为 $r$ 的匀速圆周运动，求其等效环形电流。","link":""},{"id":"phy2574","t":"闭合电路欧姆定律·电动势的定义与性质","s":"看到【问 $E=W/q$ 中的 $E$ 与 $W$、$q$ 是否有关，或解释电动势 2V 的含义】","c":"想到【电动势是非静电力把 1C 正电荷从负极搬到正极所做的功，定义式 $E=W/q$；$E$ 由电源本身性质决定，与 $W$、$q$ 及是否接入电路无关（类比 $R=U/I$ 中 $R$ 与 $U$、$I$ 无关），不接电路时干电池仍是 1.5V；$E=2\\ \\mathrm{V}$ 表示每通过 1C 电量非静电力做功 2J】；警惕【2V 不是每秒转化 2J 能量，电动势是搬运单位电荷的能力而非单位时间的能力；电源有内阻，对外输出的电能小于非静电力做的功】","src":"跳跳物一轮10.2 闭合电路欧姆定律_笔记","note":"视频|00:20-02:00","orig":"（知识）电动势 $E$ 描述电源把其他形式能转化为电势能的本领。","link":""},{"id":"phy2575","t":"闭合电路欧姆定律·闭合电路的能量关系","s":"看到【问电源总功率、内外电路功率分配或 $E=U+Ir$ 的来源】","c":"想到【能量守恒：电源功率 $IE=$外电路消耗功率+内阻消耗功率，即 $IE=IU+I^2 r$；两边约去 $I$ 得 $E=U+Ir$，即电动势=路端电压+内阻分压；此关系对非纯电阻电路同样成立】；警惕【内阻消耗功率是 $I^2 r$，别写成 $I^2 R$ 张冠李戴；非纯电阻电路外电路功率含机械能部分，不能全按 $I^2 R$ 算成热】","src":"跳跳物一轮10.2 闭合电路欧姆定律_笔记","note":"视频|05:22","orig":"（知识）闭合电路中电源产生能量与内外电路消耗能量的关系。","link":""},{"id":"phy2576","t":"闭合电路欧姆定律·定律三形式及适用条件","s":"看到【含电动机等非纯电阻的闭合电路，或求电流、电动势、内阻时选公式】","c":"想到【形式1 $I=E/(R+r)$ 仅适用纯电阻电路；形式2 $E=U+U_r$（路端电压+内阻分压）适用一切电路；内阻必是纯电阻、$U_r=Ir$ 恒成立，故形式3 $E=Ir+U$ 也适用一切电路，它是伏安法测电动势与内阻实验的原理式；断路时 $I=0$、路端电压等于电动势；短路时电流为 $E/r$】；警惕【对含电动机的电路套形式1 必错；内阻分压不属于路端电压，路端电压只是外电路总电压】","src":"跳跳物一轮10.2 闭合电路欧姆定律_笔记","note":"视频|10:31","orig":"（知识）闭合电路欧姆定律的三种常用形式及适用范围（$R$ 外电阻、$r$ 内阻、$U$ 路端电压）。","link":""},{"id":"phy2577","t":"闭合电路欧姆定律·电压表测量对象的判断","s":"看到【电压表与电阻串联或跨接多处，问它测的是谁的电压】","c":"想到【无视与电压表串联的电阻，只看电压表两端抱住了谁：只抱电源，测的是电动势（理想电压表内阻极大，电路近似断路，断路时路端电压等于电动势）；抱了电阻，忽略电源，抱谁测谁的电压；电压表与某电阻串联后跨接在电源两端，测的就是路端电压】；警惕【与电压表串联的电阻不影响判断，直接无视；理想电压表所在支路按断路处理】","src":"跳跳物一轮10.2 闭合电路欧姆定律_笔记","note":"视频|13:37","orig":"（知识）电路中电压表读数（含电动势）代表谁的电压的判断方法。","link":""},{"id":"phy2578","t":"闭合电路欧姆定律·路端电压电流图像","s":"看到【给电源的 $U$-$I$ 图像（下降直线），求电动势、内阻或短路电流】","c":"想到【$U=E-Ir$ 是一次函数，图线为下降的直线；纵截距等于电动势 $E$；横截距等于短路电流（外电阻为 0 时的电流，大小为 $E/r$）；斜率的绝对值等于内阻 $r$】；警惕【电动势只能读纵截距，不能用图线上某点的 $U/I$ 代替；内阻取斜率绝对值、短路电流取横截距，勿把两者来源弄混】","src":"跳跳物一轮10.2 闭合电路欧姆定律_笔记","note":"视频|16:11","orig":"（知识）路端电压 $U$ 随电流 $I$ 变化的图线的信息读取。","link":""},{"id":"phy2579","t":"闭合电路欧姆定律·开关切换求电阻比值","s":"看到【不同开关状态下电压表读数不同，求电阻比值或电动势】","c":"想到【电压表直接接在电源两端、外电路断开时读数即电动势；开关闭合后电压表测外电阻两端电压即路端电压，内阻分压=电动势-路端电压；串联电路电阻之比等于电压之比，外阻与内阻之比=路端电压/内阻分压】；警惕【开关状态一变，电压表测量对象随之改变，须重新判断；内阻分压是电动势减路端电压，不是两者相加】","src":"跳跳物一轮10.2 闭合电路欧姆定律_笔记","note":"视频|19:56","orig":"（例）开关 $S_1$ 断开、$S_2$ 闭合时电压表读数 3V（电压表直接接在电源两端）；两开关均闭合后外电阻 $R$ 与内阻 $r$ 串联，同一电压表读数变为 1.8V，求 $R/r$。","link":""},{"id":"phy2580","t":"闭合电路欧姆定律·电源与小灯泡U-I图线的交点","s":"看到【电源与小灯泡的 $U$-$I$ 图线画在同一坐标系，问工作状态或某点电阻】","c":"想到【电源直线：纵截距为电动势，斜率绝对值为内阻；灯泡曲线：割线斜率（该点电压与电流之比）为灯泡电阻，随电流增大割线变陡、电阻增大；两图线的交点即两者组成闭合回路时的工作点，交点坐标为回路电流与灯泡电压，工作点电阻=交点电压/交点电流】；警惕【求交点处灯泡电阻只能用交点电压除以交点电流，误用 $U_2/(I_2-I_3)$ 之类坐标差必错；灯泡电阻看割线斜率，不是切线】","src":"跳跳物一轮10.2 闭合电路欧姆定律_笔记","note":"视频|27:29","orig":"（例）同一坐标系中画出电源的 $U$-$I$ 直线与小灯泡的 $U$-$I$ 曲线（曲线上标注多个点，坐标含 $I_2$、$I_3$ 等），问小灯泡电阻变化及工作点处的电阻。","link":""},{"id":"phy2581","t":"闭合电路欧姆定律·U-I图像坐标轴非零起点陷阱","s":"看到【电源 $U$-$I$ 图像的某个坐标轴不从 0 开始，直接读截距或斜率】","c":"想到【纵轴非零起点时：电动势由图线反向延长到电流为 0 处的真正纵截距读出（本题 6.0V）；内阻用图线上两点的电压变化量除以电流变化量计算，即 $\\Delta U/\\Delta I$（本题 1.0V/0.5A=2Ω）；横截距因轴平移失真、不再是短路电流，须用 $E/r$ 重新计算（本题 3A）】；警惕【误把轴起点处的图线电压当电动势；误用单点 $U/I$ 当内阻（本题会错得 12Ω）；误把图上横截距当短路电流（本题会错得 0.5A）】","src":"跳跳物一轮10.2 闭合电路欧姆定律_笔记","note":"视频|29:13","orig":"（例）电源的 $U$-$I$ 图像纵轴从 5.0V 开始（横轴从 0 开始），图线过点 $(0.5\\ \\mathrm{A},\\ 5.0\\ \\mathrm{V})$，反向延长得真正纵截距 6.0V，求电动势、内阻与短路电流。","link":""},{"id":"phy2582","t":"电路动态分析·串反并同法","s":"看到【某电阻（滑动变阻器、光敏电阻等）阻值变化，问其他元件电流电压功率如何变】","c":"想到【三步：画圈——将变化电阻与电源连成一个圈；判趋势——明确变化电阻增大还是减小；定关系——看被分析元件在圈上还是圈外。圈上元件的 $I$、$U$、$P$ 与变化电阻趋势相反（串反），圈外元件与变化电阻趋势相同（并同）】；警惕【串、并只是形象说法，不代表元件实际串并联关系；连圈方法不唯一时，在任意一个圈上的元件都用串反，不在任何圈上的元件才用并同】","src":"跳跳物一轮10.3 电路动态分析、电路故障分析_笔记","note":"视频|00:26","orig":"（知识）电源内阻不为 0 时，某电阻阻值变化引起其他元件 $I$、$U$、$P$ 变化的判断方法。","link":""},{"id":"phy2583","t":"电路动态分析·开关等效与电源内阻为零情形","s":"看到【开关闭合或断开引起电路变化，或电源内阻为 0 时分析各元件变化】","c":"想到【开关视为变化电阻：断开=阻值从 0 变为无穷大（增大），闭合=阻值从无穷大变为 0（减小）；电源内阻为 0 时串反不受影响；并同要看干路：干路有电阻可将其等效为电源内阻，并同仍适用；干路无电阻则圈外元件 $I$、$U$、$P$ 均保持不变】；警惕【干路无电阻（理想电源）时圈外元件完全不变，此时套并同会误判】","src":"跳跳物一轮10.3 电路动态分析、电路故障分析_笔记","note":"视频|05:06","orig":"（知识）开关通断的等效处理及理想电源（内阻为 0）时串反并同的适用性。","link":""},{"id":"phy2584","t":"电路动态分析·ΔU/ΔI比值分析","s":"看到【问变化量之比 $\\Delta U/\\Delta I$ 等于多少，或该比值是否变化】","c":"想到【前提：列式中除 $U$、$I$ 外不能有其他变量；若 $U$、$I$ 是某定值电阻的电压和电流，则 $\\Delta U/\\Delta I=R$；若不是定值电阻的，把 $I$ 当自变量、$U$ 当因变量列闭合电路欧姆定律，比值即函数图像的斜率；路端电压与总电流之比 $\\Delta U/\\Delta I=$内阻 $r$，为定值】；警惕【非定值电阻（如滑动变阻器、路端电压）的 $\\Delta U/\\Delta I$ 不等于该元件阻值；斜率为负时比较大小须取绝对值】","src":"跳跳物一轮10.3 电路动态分析、电路故障分析_笔记","note":"视频|05:06","orig":"（知识）电路动态变化中电压变化量与电流变化量之比的分析方法。","link":""},{"id":"phy2585","t":"电路故障分析·将故障元件视为变化电阻","s":"看到【给出灯泡亮暗或电表变化现象，判断哪里短路或断路】","c":"想到【用排除法：将故障元件视为变化电阻——短路=阻值减小，断路=阻值增大；逐个假设选项故障成立，用串反并同分析其他元件的变化趋势，与题目已知现象相符则正确，不符则排除】；警惕【不要根据已知直接分析，应逐项假设验证；短路和断路的等效方向相反，勿弄反】","src":"跳跳物一轮10.3 电路动态分析、电路故障分析_笔记","note":"视频|16:52","orig":"（知识）不使用额外电表时电路故障的分析方法。","link":""},{"id":"phy2586","t":"电路故障分析·电压表检测法","s":"看到【将电压表逐处并联到电路中，问有无示数对应的故障】","c":"想到【被电压表包围的部分为内部，其余为外部；电压表有示数→内部断路或外部短路；电压表无示数→内部短路或外部断路；检测串联电路故障时，接某两点有示数（接近电动势）说明这两点间存在断路点，示数为 0 说明该段完好或被短路】；警惕【内部、外部以电压表接入的包围范围划分，判断前先明确接的是哪一段】","src":"跳跳物一轮10.3 电路动态分析、电路故障分析_笔记","note":"视频|18:48","orig":"（知识）用电压表并联检测电路故障的示数判断。","link":""},{"id":"phy2587","t":"电路动态分析·传感器阻值变化的全电路趋势判断","s":"看到【光敏、热敏等传感器阻值变化，问多个元件的趋势】","c":"想到【先确定变化电阻及其趋势（光敏电阻光照减弱阻值增大）；将 $R_2$ 与电源连圈：圈上元件（内阻、与 $R_2$ 串联的电压表）按串反，功率示数减小；圈外元件（与 $R_2$ 并联的小灯泡）按并同，功率增大变亮；只有一个电阻增大时总电阻必增大】；警惕【内阻也在圈上，其功率同样用串反判断；总电阻趋势由唯一变化的电阻决定】","src":"跳跳物一轮10.3 电路动态分析、电路故障分析_笔记","note":"视频|20:47","orig":"（例）含电源（内阻不为 0）、定值电阻、光敏电阻 $R_2$ 和小灯泡的电路，光照减弱使 $R_2$ 阻值增大，判断内阻功率、与 $R_2$ 串联的电压表示数、总电阻及灯泡亮度的变化。","link":""},{"id":"phy2588","t":"电路动态分析·多个电压变化量的大小比较","s":"看到【多个电压表或多个量同时变化，比较各自变化量 $\\Delta U$ 的大小】","c":"想到【统一以总电流变化量为公共分母构造 $\\Delta U/\\Delta I$：对每个电压列闭合电路欧姆定律，把该电压表示成总电流的一次函数，斜率绝对值等于若干电阻之和（本题分别为三阻之和、两阻之和与内阻 $r$），斜率绝对值大的 $\\Delta U$ 大】；警惕【不能凭串反并同的趋势判断变化量大小，趋势相同变化量也可能不等；斜率为负时取绝对值再比】","src":"跳跳物一轮10.3 电路动态分析、电路故障分析_笔记","note":"视频|24:34","orig":"（例）电路中某传感器阻值增大，三只电压表 $V_1$、$V_2$、$V_3$ 分别测电路中不同位置的电压，比较 $\\Delta U_1$、$\\Delta U_2$、$\\Delta U_3$ 的大小。","link":""},{"id":"phy2589","t":"电路故障分析·由灯泡亮暗反推故障位置","s":"看到【灯一亮一暗（组合现象），反推哪个电阻短路或断路】","c":"想到【逐项假设选项故障成立：短路=阻值减小、断路=阻值增大；把该电阻与电源连圈，用串反并同推两灯亮暗，与现象完全吻合的选项正确；断路电阻圈上的灯串反变暗、圈外的灯并同变亮】；警惕【只推一盏灯就下结论，须所有现象都吻合；短路与断路引起的趋势整体相反，勿混】","src":"跳跳物一轮10.3 电路动态分析、电路故障分析_笔记","note":"视频|36:29","orig":"（例）灯泡 A、B 与电阻 $R_1$~$R_4$ 组成的电路出现一处故障后，灯 A 变暗、灯 B 变亮，判断故障元件及类型。","link":""},{"id":"phy2590","t":"含电容器的电路·电容器充电放电稳定三状态类比","s":"看到【含电容器的电路，问电容器支路有无电流、串联电阻能否忽略】","c":"想到【充电时电容器相当于用电器，电流从正极板流入、负极板流出；放电时相当于电源，电流从正极板流出、负极板流入；稳定时相当于理想电压表，所在支路无电流，与电容器串联的电阻两端等电势、可忽略】；警惕【串联电阻可忽略仅限稳定状态，充放电过程中该电阻有电流通过、不可忽略】","src":"跳跳物一轮10.4 含电容器的电路、复杂电路化简_笔记","note":"视频|00:28","orig":"（知识）含电容器的电路中，电容器在充电、放电、稳定三种状态下的等效角色与电流特点。","link":""},{"id":"phy2591","t":"含电容器的电路·电容器U、Q、I分析与ΔQ计算","s":"看到【求电容器电荷量 $Q$、充放电平均电流，或电荷量变化量 $\\Delta Q$】","c":"想到【把电容器当电压表先求两端电压 $U$，再由 $Q=CU$ 算电荷量；充放电平均电流 $I=\\Delta Q/t$，$\\Delta Q$ 为电荷量变化量】；警惕【算 $\\Delta Q$ 先看极板电性是否改变：电性不变时 $|\\Delta Q|=|Q_2-Q_1|$，电性改变时 $|\\Delta Q|=Q_1+Q_2$】","src":"跳跳物一轮10.4 含电容器的电路、复杂电路化简_笔记","note":"视频|03:40","orig":"（知识）电路中电容器两端电压 $U$、电荷量 $Q$ 及充放电平均电流 $I$ 的分析顺序与公式。","link":""},{"id":"phy2592","t":"含电容器的电路·电桥中电容器电压求法","s":"看到【电容器跨接在电桥两条支路之间，不在同一条支路上，求电压或电荷量】","c":"想到【电容器两端电压等于同侧两个电阻电压之差的绝对值，即 $U=|U_1-U_2|$，$U_1$、$U_2$ 为电容器同一侧（左端或右端）两支路上电阻的分压】；警惕【不能把电容器当电压表并在某个电阻上直接读数，必须分别算出两条支路的分压再作差取绝对值】","src":"跳跳物一轮10.4 含电容器的电路、复杂电路化简_笔记","note":"视频|09:08","orig":"（知识）电桥电路中跨接在两条支路之间的电容器，其两端电压的求法。","link":""},{"id":"phy2593","t":"复杂电路化简·节点法四步与电流表处理","s":"看到【复杂电路看不出串并联关系，需要画等效电路图化简】","c":"想到【电源正极节点标1，每经过一个用电器节点数字加1；同一根导线或电流表两端电势相同、标同号；电压表和电容器当普通用电器参与标号；节点按数字从小到大排序，把元件挂在对应两节点之间】；警惕【电流表不画回化简图，应在化简后的图上分析电流路径确定其测量对象；无法比较电势高低时从电源负极入手，离负极越近电势越低】","src":"跳跳物一轮10.4 含电容器的电路、复杂电路化简_笔记","note":"视频|12:31-17:14","orig":"（知识）用节点法（电势法）化简复杂电路的步骤与各仪表的处理规则。","link":""},{"id":"phy2594","t":"电路动态分析·串反并同法则及适用条件","s":"看到【某电阻阻值变化，判断其他元件的电流、电压、功率或电容器电荷量如何变】","c":"想到【串反并同：与变化电阻串联（同一回路）的元件，其电流、电压、功率变化趋势与变化电阻相反；并联（不在同一回路）的元件则相同；电容器电荷量 $Q=CU$ 的增减也可用该法则直接判断】；警惕【前提是电路结构不变：开关在支路上相当于该支路电阻变化、可用；开关在干路上，断开或闭合会改变整个电路结构，串反并同失效】","src":"跳跳物一轮10.4 含电容器的电路、复杂电路化简_笔记","note":"视频|20:08-26:49","orig":"（知识）电路动态分析中，变化的电阻与其余元件各物理量变化趋势的关系及使用前提。","link":""},{"id":"phy2595","t":"含电容器的电路·开关断开后电容器抱电源","s":"看到【串联分压电路中的电容器，开关断开后问电容器电压或电荷量变化】","c":"想到【闭合时电容器电压等于与之并联电阻的分压，小于 $E$；断开后电容器直接接在电源两端（抱电源），电压升为电动势 $E$，电荷量增多】；警惕【开关在干路上不能用串反并同分析，断开后电路结构已变为电容器直接接电源】","src":"跳跳物一轮10.4 含电容器的电路、复杂电路化简_笔记","note":"视频|22:39","orig":"（例）$R_1=R_2$ 的两电阻串联接电源（电动势 $E$、内阻 $r$），$C_1$ 与 $R_2$ 并联、$C_2$ 与 $R_1$ 并联，分析开关由闭合到断开后两电容器电荷量的变化。","link":""},{"id":"phy2596","t":"含电容器的电路·电容器放电电荷按并联电阻反比分配","s":"看到【开关断开后电容器通过两个并联电阻放电，求流过某个电阻的电荷量】","c":"想到【先按断开前的电压算总放电量 $Q=CU$；放电时两电阻并联，电流与电阻成反比，电荷量也与电阻成反比：通过某电阻的电荷量=总放电量×（另一电阻/两电阻之和）】；警惕【电荷量与电阻成反比，电阻大的分得少；总放电量必须用断开前电容器两端电压计算，不能直接用电动势】","src":"跳跳物一轮10.4 含电容器的电路、复杂电路化简_笔记","note":"视频|26:49-31:43","orig":"（例）电源 $E=6\\,\\mathrm{V}$、内阻 $1\\,\\Omega$，$R_1=6\\,\\Omega$ 与 $R_3=3\\,\\Omega$ 并联后与 $R_2=5\\,\\Omega$ 串联，$C=2\\times 10^{-5}\\,\\mathrm{F}$ 并在 $R_1$、$R_3$ 并联部分两端，开关断开后电容器经 $R_1$、$R_3$ 放电，求通过 $R_1$ 的电荷量。","link":""},{"id":"phy2597","t":"含电容器的电路·电桥电容器电荷量计算","s":"看到【电桥中电容器跨接两条串联支路，内阻不计，求电荷量 $Q$】","c":"想到【两支路电压均为 $E$，分别算同侧电阻分压：$3R$ 分得 $3E/5$、$R$ 分得 $E/5$，电容器电压 $U=|3E/5-E/5|=2E/5$，电荷量 $Q=CU=2CE/5$】；警惕【作差必须取同侧电阻（都取左端或都取右端）；内阻不计时路端电压才等于 $E$，有内阻需先算路端电压】","src":"跳跳物一轮10.4 含电容器的电路、复杂电路化简_笔记","note":"视频|31:43","orig":"（例）电源电动势 $E$、内阻不计，两条支路并联在电源两端：上支路 $3R$ 与 $2R$ 串联，下支路 $R$ 与 $4R$ 串联，电容器跨接在两支路之间，求电容器电荷量。","link":""},{"id":"phy2598","t":"电功率·普适公式与纯电阻专属公式","s":"看到【电动机或充电电池等非纯电阻元件，求电功、电功率、焦耳热或化学能】","c":"想到【$W=UIt$、电功率 $P=UI$、焦耳热 $Q=I^2Rt$、热功率 $I^2R$ 四个公式对任何元件普适；非纯电阻中转化为其他形式的能量 $=W-Q=UIt-I^2Rt$，如电池充电的化学能 $=UIt-I^2Rt$】；警惕【$U^2/R$、$U^2t/R$ 等由欧姆定律推导的公式仅对纯电阻成立，用于非纯电阻算热量或功率必错】","src":"跳跳物一轮10.5 电动机、电源的功率和效率_恒定电流模块完结撒_笔记","note":"视频|00:21","orig":"（知识）电功、电功率、焦耳热、热功率四个公式的适用范围，以及非纯电阻元件中其他形式能的计算。","link":""},{"id":"phy2599","t":"电动机·等效模型与功率分配","s":"看到【电动机正常工作，求机械功率、输出功率或效率】","c":"想到【电动机等效为无内阻理想电机与内阻 $r$ 串联：总功率（电功率）$=UI$，热功率（损耗）$=I^2r$，机械功率 $=UI-I^2r$；机械功率即输出功率，效率=机械功率/总功率×100%】；警惕【电动机的输出功率指机械功率而非电功率，热功率是被浪费的部分，求机械功率必须扣除内阻发热】","src":"跳跳物一轮10.5 电动机、电源的功率和效率_恒定电流模块完结撒_笔记","note":"视频|02:47","orig":"（知识）电动机的等效电路模型及电功率、热功率、机械功率的分配关系。","link":""},{"id":"phy2600","t":"电动机·欧姆定律失效与卡住情形","s":"看到【已知电动机两端电压和内阻求电流，或电动机被卡住不转】","c":"想到【正常运转时无内阻电机也分压，$U \\neq Ir$，欧姆定律失效，电流须借助与电动机串联的其他电阻由电流处处相等间接求；电动机被卡住不转时，无内阻电机等效为导线，只剩内阻 $r$，可当纯电阻用欧姆定律】；警惕【正常运转时用 $I=U/r$ 算电流必错；卡住情形恰好相反，可直接用欧姆定律】","src":"跳跳物一轮10.5 电动机、电源的功率和效率_恒定电流模块完结撒_笔记","note":"视频|04:02-05:24","orig":"（知识）电动机正常运转与被卡住两种状态下欧姆定律的适用性及电流的求法。","link":""},{"id":"phy2601","t":"电源·三个功率与效率公式","s":"看到【求电源的总功率、输出功率、内阻消耗功率或电源效率】","c":"想到【总功率 $=EI$（$E$ 为电动势、$I$ 为总电流），输出功率 $=UI$（$U$ 为路端电压），内阻热功率 $=I^2r$；效率 $\\eta=U/E$，纯电阻电路还可写成 $\\eta=R/(R+r)$，路端电压或外电阻越大效率越高】；警惕【输出功率用路端电压乘电流，不是电动势乘电流；效率随外电阻增大而升高，不是固定值】","src":"跳跳物一轮10.5 电动机、电源的功率和效率_恒定电流模块完结撒_笔记","note":"视频|09:49-11:14","orig":"（知识）电源的总功率、输出功率、内阻热功率及电源效率的计算式。","link":""},{"id":"phy2602","t":"电源·最大输出功率条件与P-R图像特征","s":"看到【可变电阻接电源，问电源输出功率何时最大、最大值或P随R变化图像】","c":"想到【$R=r$ 时输出功率最大，最大值 $P_m=E^2/(4r)$（大题可直接用）；$P$ 随 $R$ 先增大后减小，图像关于最高点不对称，$R$ 越接近 $r$ 功率越大；同一输出功率对应两个 $R$ 值，其乘积等于 $r^2$】；警惕【图像不对称，两个 $R$ 值到 $r$ 的距离并不相等；最大输出功率的临界是 $R=r$，不是 $R$ 越大功率越大】","src":"跳跳物一轮10.5 电动机、电源的功率和效率_恒定电流模块完结撒_笔记","note":"视频|12:41","orig":"（知识）路端电阻变化时电源输出功率的最大条件、最大值及P随R的变化图像特征。","link":""},{"id":"phy2603","t":"电源·等效电源法求可变电阻最大功率","s":"看到【电源与定值电阻连接后再接滑动变阻器，求滑变消耗的最大功率】","c":"想到【把电源与定值电阻整体等效为新电源，滑变成为新电源的唯一外电阻，最大功率 $=E'^2/(4r')$：定值电阻与内阻串联时 $E'=E$、$r'=r+R_0$；并联时 $r'=rR_0/(r+R_0)$（上乘下加）、$E'=R_0E/(r+R_0)$】；警惕【串联等效电动势不变、并联等效电动势变小；求的是滑变功率而非原电源输出功率，不能直接套 $E^2/(4r)$】","src":"跳跳物一轮10.5 电动机、电源的功率和效率_恒定电流模块完结撒_笔记","note":"视频|15:45","orig":"（知识）路端除可变电阻外还有定值电阻时，求可变电阻最大功率的等效电源法。","link":""},{"id":"phy2604","t":"电源·输出功率最大与效率最大辨析","s":"看到【问输出功率最大时效率多大，或输出功率与效率能否同时最大】","c":"想到【输出功率最大要求 $R=r$，追求有效输出的绝对值最大；效率最大要求外电阻 $R$ 越大越好（趋近100%），追求能源利用率最高；$R=r$ 输出功率最大时效率仅50%，一半能量浪费在内阻上，两者不可兼得】；警惕【输出功率最大不等于效率最大，两目标条件相反；效率 $\\eta=U/E$ 随路端电压升高而增大】","src":"跳跳物一轮10.5 电动机、电源的功率和效率_恒定电流模块完结撒_笔记","note":"视频|17:40","orig":"（知识）电源输出功率最大与效率最大两个目标的条件与相互关系。","link":""},{"id":"phy2605","t":"电源·功率随路端电压U变化的图像分析","s":"看到【电源各功率随路端电压 $U$ 变化的图像，三条线要对应并求 $E$、$r$ 或最大功率】","c":"想到【总功率 $=EI=E(E-U)/r=E^2/r-(E/r)U$，是 $U$ 的一次函数：纵截距 $=E^2/r$、斜率大小 $=E/r$，故 $E=$ 截距/斜率 $=3\\,\\mathrm{V}$、$r=E/$ 斜率 $=1\\,\\Omega$；内阻功率 $=I^2r$ 随 $U$ 增大一直减小；输出功率先增后减；最大输出功率 $=E^2/(4r)=2.25\\,\\mathrm{W}$】；警惕【总功率图线随 $U$ 增大而递减，别与内阻功率曲线混淆（一为直线一为曲线）；斜率读数是 $E/r$ 而非 $r$ 本身】","src":"跳跳物一轮10.5 电动机、电源的功率和效率_恒定电流模块完结撒_笔记","note":"视频|34:21","orig":"（例）电源对可变外电阻供电，给出总功率、内阻热功率、输出功率随路端电压 $U$ 变化的图像，其中总功率图线为直线，斜率大小为3、纵截距为9，求电动势 $E$、内阻 $r$ 及最大输出功率。","link":""},{"id":"phy2606","t":"磁场·磁感应强度的定义与矢量性","s":"看到【问 $B$ 与 $F$、$I$、$L$ 的关系，或通电导线在某处不受磁场力能否说明无磁场】","c":"想到【$B=F/(IL)$ 是比值定义式，要求电流元与磁场垂直；$B$ 是磁场本身的性质，与 $F$、$I$、$L$ 均无关；$B$ 的方向规定为该点小磁针静止时N极所指的方向】；警惕【导线不受力不能断定无磁场，可能是电流方向与磁场平行；导线与 $B$ 不垂直时 $B>F/(IL)$，定义式不成立】","src":"跳跳物一轮11.1 磁场基本概念、安培定则、磁场叠加_笔记","note":"视频|00:22","orig":"（知识）磁感应强度 $B$ 的定义式、方向规定及比值定义法的含义。","link":""},{"id":"phy2607","t":"磁场·磁感线的性质","s":"看到【判断磁感线的疏密、闭合性、相交等说法，或与电场线对比】","c":"想到【磁感线是假想曲线，切线方向为该点磁场方向，疏密表示 $B$ 的大小；磁感线是闭合曲线，磁体外部从N极指向S极，内部从S极指向N极；磁感线不中断、不相交、不相切；匀强磁场的磁感线是等距平行线】；警惕【磁感线闭合而电场线不闭合（电场线从正电荷出发到负电荷终止），二者常放一起对比考查】","src":"跳跳物一轮11.1 磁场基本概念、安培定则、磁场叠加_笔记","note":"视频|00:22","orig":"（知识）磁感线的含义与基本性质。","link":""},{"id":"phy2608","t":"磁场·地磁场分布与半球判断","s":"看到【地磁场方向、竖直分量指向，或由测量分量判断南北半球与方位】","c":"想到【地磁南极在地理北极附近、地磁北极在地理南极附近；地磁场水平分量总指向地理北方；北半球有竖直向下的分量，南半球有竖直向上的分量；赤道附近地磁场接近水平】；警惕【地磁南北极与地理南北极正好相反但不完全重合；竖直分量向下即为北半球，向上为南半球】","src":"跳跳物一轮11.1 磁场基本概念、安培定则、磁场叠加_笔记","note":"视频|00:22","orig":"（知识）地磁场的磁极位置、水平与竖直分量的分布规律。","link":""},{"id":"phy2609","t":"磁场·安培定则直线穿环模型","s":"看到【直导线、环形电流或通电螺线管，判断磁场方向或小磁针N极指向】","c":"想到【统一为直线穿环模型，用右手点赞手势：直电流大拇指指电流方向，四指环绕方向为磁场方向；环形电流和通电螺线管四指沿电流方向弯曲，大拇指指向环内（内部）磁场方向】；警惕【直电流与环形电流中大拇指与四指的角色正好互换，最易张冠李戴；判断小磁针转向先定该点磁场方向，N极静止时指向与磁场方向相同】","src":"跳跳物一轮11.1 磁场基本概念、安培定则、磁场叠加_笔记","note":"视频|00:22","orig":"（知识）用安培定则（右手螺旋定则）判断电流与其产生磁场方向的关系。","link":""},{"id":"phy2610","t":"磁场·点叉表示法与叉顺点逆口诀","s":"看到【图中用点($\\cdot$)或叉($\\times$)表示电流或磁场方向，求环绕方向】","c":"想到【点表示垂直纸面向外，叉表示垂直纸面向里；口诀叉顺点逆：电流方向为叉，其周围磁场沿顺时针；电流方向为点，磁场沿逆时针；反向同样成立：磁场为叉则电流为顺时针，磁场为点则电流为逆时针】；警惕【点叉是通用方向符号，不只表示磁场也可表示电流；求直导线在某点的磁场时，过该点画以导线为圆心的圆，取切线方向】","src":"跳跳物一轮11.1 磁场基本概念、安培定则、磁场叠加_笔记","note":"视频|15:03","orig":"（知识）垂直纸面方向的点叉表示法及电流与磁场环绕方向的对应口诀。","link":""},{"id":"phy2611","t":"磁场·磁场叠加与等大特殊角结论","s":"看到【几条通电导线在同一点各产生磁场，求合磁场大小或方向】","c":"想到【磁感应强度是矢量，按平行四边形定则合成：共线时同向相加、反向相减；两个等大 $B$ 的磁场夹角 $60^\\circ$ 时合磁场为 $\\sqrt{3}B$，$90^\\circ$ 时为 $\\sqrt{2}B$，$120^\\circ$ 时为 $B$，$0^\\circ$ 时为 $2B$，$180^\\circ$ 时为 $0$】；警惕【夹角 $60^\\circ$ 的结论最重要须直接记住；先找等大反向的抵消对再合成其余分量，可大幅简化】","src":"跳跳物一轮11.1 磁场基本概念、安培定则、磁场叠加_笔记","note":"视频|19:52","orig":"（知识）多个电流产生的磁场在某点叠加的合成法则及等大特殊角结论。","link":""},{"id":"phy2612","t":"磁场·安培假设与地磁场环形电流方向","s":"看到【地磁场由绕过地心的环形电流产生，判断电流绕向（如自西向东）】","c":"想到【地球内部磁场从地磁S极指向N极，即从地理北极指向地理南极；将其视为环形电流内部的磁场，右手大拇指指向该方向，四指弯曲方向即为电流绕向（正面看自西向东）】；警惕【大拇指应指地球内部磁场方向而非外部磁场；内部磁场是从地理北极指向地理南极，方向别弄反】","src":"跳跳物一轮11.1 磁场基本概念、安培定则、磁场叠加_笔记","note":"视频|24:23","orig":"（例）安培假设认为地磁场由绕过地心的环形电流产生，已知地球内部磁场方向，判断该环形电流的绕行方向。","link":""},{"id":"phy2613","t":"磁场·合磁为零条件与电流拆分割补法","s":"看到【几条导线与匀强磁场叠加使某点合磁为零，或电流大小方向改变后再求合磁场】","c":"想到【两等大磁场夹角 $60^\\circ$，合磁场为 $\\sqrt{3}B'$，与 $B_0$ 等大反向抵消，故每根导线在 $a$ 点的磁场 $B'=B_0/\\sqrt{3}$；电流变化时用割补法拆分：把 $2I$ 拆成 $I$ 与 $I$，让一部分与原有电流共同抵消 $B_0$，剩余电流单独产生磁场；电流与磁场大小成正比，反向电流 $-2I$ 对应 $2B'$】；警惕【合磁为零意味着 $B_0$ 与导线合磁场等大反向，方向大小都要用足；拆分电流后按比例算剩余磁场，别重复计入已抵消部分】","src":"跳跳物一轮11.1 磁场基本概念、安培定则、磁场叠加_笔记","note":"视频|28:39","orig":"（例）$P$、$Q$ 两条通电导线电流均为 $I$（垂直纸面向里），$a$ 点到两导线等距且两磁场方向夹角 $60^\\circ$，再加入匀强磁场 $B_0$ 后 $a$ 点合磁感应强度为零，分析各导线在 $a$ 点的磁场大小及电流变化后的合磁场。","link":""},{"id":"phy2614","t":"安培力·大小公式前提与磁场来源","s":"看到【求安培力大小，或磁场中导线自身也产生磁场、问该用哪个B计算】","c":"想到【公式$F=BIL$的前提是$I$垂直于$B$；$I$与$B$平行时安培力为零；安培力垂直于$B$与$I$组成的平面，既垂直$B$也垂直$I$；计算时只取其他磁场，导线不受自身磁场的安培力，也不把自身磁场与外磁场叠加】；警惕【$I$与$B$平行时误以为仍有安培力；误把导线自身产生的磁场叠加进$B$参与计算】","src":"跳跳物一轮11.2 安培力_笔记","note":"视频|00:34","orig":"（知识）通电导线在磁场中所受安培力的大小计算前提与磁场来源。","link":""},{"id":"phy2615","t":"安培力·谁斜动谁分解原则","s":"看到【B与I不垂直（如B斜导线水平，或B竖直导线倾斜），求安培力大小】","c":"想到【谁斜动谁：$B$与$I$中方向倾斜的那个去分解或投影，水平/竖直方向的那个不动；可取$B$在垂直$I$方向的分量$B_y$，$F=IB_yL$；也可取导线在垂直$B$方向的投影长度$L'$，$F=IBL'$；两者都斜时动哪个都行】；警惕【点($\\cdot$)、叉($\\times$)与纸面上任何箭头必定垂直，磁场箭头画斜了与点叉电流仍垂直，别被倾角迷惑而多余分解】","src":"跳跳物一轮11.2 安培力_笔记","note":"视频|02:22","orig":"（知识）电流I与磁感应强度B不垂直时安培力的处理方法。","link":""},{"id":"phy2616","t":"安培力·左手定则与叉心点背","s":"看到【已知F、I、B中两个方向判断第三个，磁场为点场或叉场】","c":"想到【口诀：掌心迎磁场，四指指电流，拇指即安培力方向；点叉速判——叉心：叉场时掌心朝脸；点背：点场时手背朝脸；四指仍指电流，拇指给出安培力】；警惕【必须用左手且安培力同时垂直于$B$和$I$，若判出的力与$B$或$I$不垂直，说明手法用错】","src":"跳跳物一轮11.2 安培力_笔记","note":"视频|06:31-08:23","orig":"（知识）左手定则口诀及点场、叉场下的快速手法。","link":""},{"id":"phy2617","t":"安培力·两电流相互作用","s":"看到【两条平行直导线通电，问彼此间是吸引还是排斥】","c":"想到【同向电流相吸，反向电流相斥；推导套路：先对产生磁场的导线用安培定则判断它在受力导线处的磁场方向，再对受力导线用左手定则（叉心点背）得安培力】；警惕【每根导线只受对方磁场的作用，别把自己产生的磁场算进去；先看清受力导线处在对方磁场的哪一侧】","src":"跳跳物一轮11.2 安培力_笔记","note":"视频|09:38","orig":"（知识）两条平行通电直导线间的安培力方向结论。","link":""},{"id":"phy2618","t":"安培力·弯曲导线等效法","s":"看到【圆弧、折线、花瓣形等弯曲导线在匀强磁场中求安培力】","c":"想到【把弯曲导线等效为连接其首尾的直导线（长$L'$），电流方向从起点流向终点，$F=IBL'$；若$B$与等效导线不垂直，再取垂直分量或投影长度；并联线框（花瓣形）各支路按电阻反比分流，分别等效后方向相同则安培力相加；画完等效导线立即擦掉原导线】；警惕【原导线与等效导线只能保留一个，否则易误当成并联电路；此等效只用于求安培力的大小和方向，其他问题不能这样等效】","src":"跳跳物一轮11.2 安培力_笔记","note":"视频|11:54","orig":"（知识）弯曲导线在匀强磁场中所受安培力的等效计算。","link":""},{"id":"phy2619","t":"安培力·安培力冲量与动量定理","s":"看到【电流变化使安培力为变力（电容器放电、变阻棒加速），求末速度或电荷量】","c":"想到【对棒用动量定理：安培力冲量=平均安培力×时间=$B\\cdot L\\cdot q$（平均电流×时间=电荷量$q$），即$BLq=mv$；电容器放电时$q$等于电容器减少的电荷量$\\Delta Q=C\\cdot\\Delta U$；非匀变速不能用运动学公式，全靠动量定理搭桥】；警惕【$L$取有效长度（弯曲导线取等效长度）；电容器未放完电时$q$只取放出的那部分，不能当成初态$CU$】","src":"跳跳物一轮11.2 安培力_笔记","note":"视频|14:51","orig":"（知识）安培力为变力时用动量定理处理的套路。","link":""},{"id":"phy2620","t":"安培力·动态平衡中转动力与固定力","s":"看到【磁场或电流变化使安培力方向转动（转动力），另一力方向固定，问某力变化或极值】","c":"想到【先分清转动力与固定力：转动的力与固定方向的力垂直时该力最小（矢量三角形中重力为斜边，$\\sin\\alpha=F/mg$）；$B$沿悬线时安培力始终与悬线垂直，电流增大导线上摆，悬线拉力减小（你越水平我越大），且$\\sin\\theta=BIL/(mg)$与$I$成正比】；警惕【没分清哪个力在转哪个固定就套结论；定角转与斜不转两个模型的结论张冠李戴】","src":"跳跳物一轮11.2 安培力_笔记","note":"视频|34:06-39:35","orig":"（例）悬线吊着的通电导线静止，磁场方向始终沿悬线指向转轴，问电流增大后电流方向、拉力变化及偏角与电流的关系；另一题斜面导轨上金属杆静止、磁场方向可变，求电阻箱可取的最大阻值。","link":""},{"id":"phy2621","t":"安培力·动量定理与动能定理综合求电荷量","s":"看到【通电棒受短暂安培力获得速度后转入只受重力的摆动或上滑，求电荷量或速度】","c":"想到【分段处理：通电阶段用动量定理$Bdq=mv$（$d$为杆的有效长度）；摆动阶段用动能定理$-mgL(1-\\cos\\theta)=0-\\frac{1}{2}mv^2$；联立消去$v$得$q=m\\sqrt{2gL(1-\\cos\\theta)}/(Bd)$】；警惕【安培力冲量中的长度用杆长$d$，上升高度用悬线长$L$，两长度混用必错】","src":"跳跳物一轮11.2 安培力_笔记","note":"视频|47:00","orig":"（例）长$d$的金属杆在导轨上受瞬时安培力冲量后水平飞出，随即用长$L$的悬线拉着做圆周摆动，摆到最大偏角$\\theta$时速度为零，求通过金属杆的电荷量。","link":""},{"id":"phy2622","t":"洛伦兹力·产生条件与大小计算","s":"看到【判断运动电荷是否受洛伦兹力，或求洛伦兹力大小】","c":"想到【产生条件：电荷运动且$v$与$B$不平行（静止电荷、$v\\parallel B$均不受力）；大小：$v\\perp B$时$F=qvB$，不垂直时取$v$垂直$B$方向的分量，$F=qvB\\cdot\\sin\\theta$（$\\theta$为$v$与$B$的夹角）】；警惕【静止电荷不受洛伦兹力；$v\\parallel B$时$F=0$却仍按$qvB$计算】","src":"跳跳物一轮11.3 洛伦兹力、带电粒子在匀强磁场中的运动_笔记","note":"视频|00:35-00:52","orig":"（知识）洛伦兹力的产生条件与大小公式。","link":""},{"id":"phy2623","t":"洛伦兹力·方向判断左手定则","s":"看到【运动电荷在磁场中，判断洛伦兹力方向，磁场为点场或叉场】","c":"想到【左手定则：掌心迎磁场（叉场掌心朝脸、点场手背朝脸），四指指向正电荷运动方向，大拇指指向即正电荷所受洛伦兹力方向】；警惕【负电荷所受洛伦兹力方向与大拇指相反（或四指指其运动的反方向）；$v$与$B$平行时不受力，硬用左手定则必判错】","src":"跳跳物一轮11.3 洛伦兹力、带电粒子在匀强磁场中的运动_笔记","note":"视频|02:33","orig":"（知识）用左手定则判断洛伦兹力方向及负电荷的处理。","link":""},{"id":"phy2624","t":"洛伦兹力·永不做功与安培力可做功","s":"看到【问洛伦兹力或安培力是否做功、是否改变粒子动能】","c":"想到【洛伦兹力始终与速度垂直，任何情况下永不做功，只改变速度方向不改变速率；导线静止时安培力等于所有电荷洛伦兹力的合力，也不做功；导线运动时安培力只是洛伦兹力垂直导线方向分力的合力（该分力做正功，另一分力做等量负功，总功为零），故安培力可以做功】；警惕【由安培力可做功推出洛伦兹力也可做功；导线运动时仍认为安培力是洛伦兹力的合力】","src":"跳跳物一轮11.3 洛伦兹力、带电粒子在匀强磁场中的运动_笔记","note":"视频|03:36-04:31","orig":"（知识）洛伦兹力做功特点及安培力能做功的原因。","link":""},{"id":"phy2625","t":"带电粒子圆周运动·半径与周期公式","s":"看到【粒子垂直射入匀强磁场，求半径、周期、比荷或速度】","c":"想到【核心方程$qvB=mv^2/r$；半径$r=mv/(qB)$与速度成正比（速度大绕大圈）；周期$T=2\\pi m/(qB)$与速度无关（快慢粒子周期相同）；大题不能直接写半径、周期公式，必须由$qvB=mv^2/r$联立$T=2\\pi r/v$现场推导】；警惕【用$T=2\\pi r/v$分析$T$与$v$关系时忘记$r$随$v$变化，误得$T\\propto v$】","src":"跳跳物一轮11.3 洛伦兹力、带电粒子在匀强磁场中的运动_笔记","note":"视频|10:06-11:08","orig":"（知识）带电粒子在匀强磁场中做匀速圆周运动的半径、周期公式及大题推导规范。","link":""},{"id":"phy2626","t":"带电粒子圆周运动·画轨迹定圆心与圆心角","s":"看到【粒子射入有界磁场，求半径、运动时间或比荷】","c":"想到【先用左手定则定偏转方向，画与入射速度相切的圆弧；定圆心两法：过两点速度方向作垂线取交点，或过一点作速度垂线加弦的中垂线；求时间关键求圆心角$\\theta$，$t=(\\theta/360^\\circ)\\cdot T$；圆心角$=2\\times$速弦角（速度与弦的夹角），劣弧速弦角为锐角、优弧为钝角】；警惕【画的轨迹不与入射速度相切；优弧时速弦角仍取锐角导致圆心角算错】","src":"跳跳物一轮11.3 洛伦兹力、带电粒子在匀强磁场中的运动_笔记","note":"视频|15:34-20:53","orig":"（知识）磁场中圆周运动的三步分析法：画轨迹、定圆心、求目标。","link":""},{"id":"phy2627","t":"带电粒子圆周运动·由轨迹反推电性与速度","s":"看到【多条圆弧轨迹从同一点沿同方向射出，问电性、磁场方向或速度大小】","c":"想到【偏转方向相同则电性相同；洛伦兹力指向圆弧内侧（圆心一侧），用左手定则由速度方向和洛伦兹力方向反推磁场方向；半径$r=mv/(qB)$，同磁场中$m$、$q$相同时半径越大速度越大，半径逐渐变小说明受阻力、速度减小】；警惕【负电荷要用拇指反向修正；把半径大小直接当电性的判断依据】","src":"跳跳物一轮11.3 洛伦兹力、带电粒子在匀强磁场中的运动_笔记","note":"视频|39:02","orig":"（例）三个粒子（两个电子和一个正电子）从同一点P以相同初速度方向射入同一匀强磁场，形成三条不同的圆弧轨迹，判断电性、磁场方向及速度大小关系。","link":""},{"id":"phy2628","t":"洛伦兹力·与摩擦联动的动态分析","s":"看到【物块贴粗糙板/杆运动且洛伦兹力改变正压力，问v-t图像、加速度变化或最大速度】","c":"想到【正压力随速度变化：竖直木板$N=qvB$，摩擦力$\\mu qvB$随$v$变化，合力不恒定，不可能匀变速；摩擦力小于重力做加速度减小的加速、大于重力做加速度减小的减速，最终趋于匀速；水平杆$N=|mg-qvB|$，$qvB=mg$时$N=0$、摩擦为零、加速度最大$a=F_0/m$，匀速时$v_{max}=(F_0+\\mu mg)/(\\mu qB)$】；警惕【把v-t图画成直线（漏了合力随速度变化）；漏掉$qvB=mg$时弹力为零且方向反转的临界点】","src":"跳跳物一轮11.3 洛伦兹力、带电粒子在匀强磁场中的运动_笔记","note":"视频|26:38-31:40","orig":"（例）物块沿粗糙竖直木板下滑，磁场使洛伦兹力水平把它压向木板，问v-t图像与运动性质；另一题小球套在水平绝缘杆上受水平恒力$F_0$，问弹力、摩擦力和最大加速度、最大速度。","link":""},{"id":"phy2629","t":"带电粒子圆周运动·时间比等于圆心角比","s":"看到【同比荷粒子（如正负电子）在同一磁场中，求运动时间之比】","c":"想到【周期$T=2\\pi m/(qB)$与速度无关，同磁场周期相同，时间比=圆心角之比；各自用速弦角求圆心角（圆心角$=2\\times$速弦角）：如速度与$x$轴夹角$30^\\circ$向左偏的粒子速弦角$60^\\circ$、圆心角$120^\\circ$，向右偏的速弦角$30^\\circ$、圆心角$60^\\circ$，时间比$2:1$】；警惕【把时间比当成半径比或速率比；优弧速弦角应取钝角，取锐角使圆心角少算一半】","src":"跳跳物一轮11.3 洛伦兹力、带电粒子在匀强磁场中的运动_笔记","note":"视频|45:25","orig":"（例）正、负电子（比荷相同）从同一点O以不同方向射入同一匀强磁场，求两者在磁场中运动时间之比。","link":""},{"id":"phy2630","t":"有界磁场·直线边界入射出射角相等","s":"看到【粒子射入单条直线边界磁场，问出射方向或入射出射角度关系】","c":"想到【射入速度与边界的夹角等于射出速度与边界的夹角（两角是同一弦的弦切角）；推论：从同一点以相同角度射入的相同粒子，出射速度方向相同、圆心角相同，比荷相同则周期相同、运动时间也相同】；警惕【该结论只对一条完整直线边界成立，折线（V形）边界不能直接套用】","src":"跳跳物一轮11.4 常见有界磁场总结、弦长公式_笔记","note":"视频|00:24","orig":"（知识）直线边界磁场中粒子入射、出射方向与边界夹角的关系。","link":""},{"id":"phy2631","t":"有界磁场·直角边界勾股求半径","s":"看到【粒子穿过两条垂直边界（如从一角射入垂直对边射出），已知边界距离求半径】","c":"想到【分别作射入、射出速度方向的垂线，交点即轨迹圆心；由圆心、入射点、出射点构建直角三角形，用勾股定理列方程，如两直角边为$(r-a)$和$b$、斜边为$r$时$(r-a)^2+b^2=r^2$，解出半径$r$】；警惕【勾股方程中斜边必是轨迹半径$r$，别把边界距离当斜边；圆心到边界的距离是$r$与边界尺寸的差值，别直接写成$r$】","src":"跳跳物一轮11.4 常见有界磁场总结、弦长公式_笔记","note":"视频|02:16","orig":"（知识）两条互相垂直的直线边界磁场中求轨迹半径的几何方法。","link":""},{"id":"phy2632","t":"有界磁场·圆形磁场沿半径射入必沿半径射出","s":"看到【粒子沿圆形磁场的半径方向射入，求出射方向、半径比或时间比】","c":"想到【沿半径射入必沿半径射出；连接磁场圆心与轨迹圆心构成两个全等的直角三角形，用偏转角的三角关系求轨迹半径和圆心角（沿半径射入时速度偏转角=轨迹圆心角）；比荷相等时速率比=轨迹半径比、时间比=圆心角比】；警惕【入射方向不沿半径时结论失效，出射方向不沿半径，须回到定圆心或弦长公式常规步骤】","src":"跳跳物一轮11.4 常见有界磁场总结、弦长公式_笔记","note":"视频|04:23","orig":"（知识）圆形磁场中粒子沿半径方向射入的轨迹结论与求半径方法。","link":""},{"id":"phy2633","t":"有界磁场·弦长公式及应用条件","s":"看到【已知或易求弦长和速弦角，要求半径、速度、磁感应强度或比荷】","c":"想到【公式一 $L=2mv\\cdot\\sin\\theta/(qB)$（$\\theta$为速弦角），公式二 $r=L/(2\\sin\\theta)$；优点是跳过定圆心的几何分析一步到位；选择、填空题在弦长与速弦角已知或易求时优先使用】；警惕【大题中不能直接引用弦长公式，必须画轨迹、定圆心、由几何关系现场推导，否则扣过程分】","src":"跳跳物一轮11.4 常见有界磁场总结、弦长公式_笔记","note":"视频|11:02-13:00","orig":"（知识）弦长公式的两种形式、优势与使用规范。","link":""},{"id":"phy2634","t":"有界磁场·环形磁场相切临界求B最小值","s":"看到【环形磁场中粒子沿半径射入，'恰好不出外边界'或求$B$的最小值】","c":"想到【$B$越小半径$r=mv/(eB)$越大，临界状态是轨迹恰好与外圆相切；过切点作切线的垂线必同时过轨迹圆心和磁场圆心，再作入射速度的垂线定出轨迹圆心；直角三角形中内半径$a$、轨迹半径$r$为直角边，$(3a-r)$为斜边，勾股$a^2+r^2=(3a-r)^2$解得$r=4a/3$，代入$r=mv/(eB)$得$B$的最小值】；警惕【临界误设为轨迹与内圆相切；斜边误取$3a$而不是$(3a-r)$】","src":"跳跳物一轮11.4 常见有界磁场总结、弦长公式_笔记","note":"视频|28:52","orig":"（例）电子从环形磁场（内半径$a$、外半径$3a$）的圆心沿半径方向射入，要求电子始终被限制在外边界大圆内，求磁感应强度$B$的最小值。","link":""},{"id":"phy2635","t":"有界磁场·圆形磁场比例与磁感应强度变化","s":"看到【同比荷粒子沿半径射入圆形磁场偏转角不同，求速率比/时间比，或$B$改变后时间变化】","c":"想到【用全等直角三角形把偏转角化为半径：偏转角$120^\\circ$时轨迹半径$R/\\sqrt{3}$、偏转角$60^\\circ$时$\\sqrt{3}R$，速率比=半径比$=1:3$；时间比=圆心角比$=2:1$；$B$改变时$r=mv/(qB)\\propto 1/B$随之变化，沿半径射入对应的圆心角也变，时间$t=(\\alpha/360^\\circ)\\cdot 2\\pi m/(qB)$由$\\alpha$与$B$共同决定，必须重新计算】；警惕【$B$变化后仍沿用原圆心角算时间；只按$B$的比例算时间而漏掉圆心角变化】","src":"跳跳物一轮11.4 常见有界磁场总结、弦长公式_笔记","note":"视频|21:04","orig":"（例）两个比荷相等的粒子沿半径方向射入半径为$R$的同一圆形磁场，偏转角分别为$120^\\circ$和$60^\\circ$，求速率比、时间比，并分析磁感应强度变为原来的$3/4$后运动时间的变化。","link":""},{"id":"phy2636","t":"有界磁场·弦长公式的比例比较","s":"看到【同弦长不同速弦角求速度比，或同点同向射入不同点射出比较速度和时间】","c":"想到【弦长相等时$v\\cdot\\sin\\theta$为定值，速度比=速弦角正弦的反比（$60^\\circ$对$30^\\circ$即甲乙速度之比为$1:\\sqrt{3}$）；同点沿同方向射入时速弦角相同（都等于速度与弦的夹角），弦长越长速度越大，而圆心角$=2\\times$速弦角相同、比荷相同周期相同，运动时间必相同】；警惕【认为出射点远的粒子时间就长；速度比按$\\sin\\theta$正比算反了】","src":"跳跳物一轮11.4 常见有界磁场总结、弦长公式_笔记","note":"视频|35:18-36:38","orig":"（例）甲、乙两个相同粒子从同一点射入同一磁场并从同一点射出（弦长相同，速弦角分别为$60^\\circ$和$30^\\circ$），求速度比；另一题两比荷相同的粒子从同一点沿同方向射入三角形磁场，从不同点射出，比较速度与时间。","link":""},{"id":"phy2637","t":"有界磁场·同弦同时到达的全比例链","s":"看到【两粒子弦长相同且运动时间相同，求半径/周期/速率/比荷之比】","c":"想到【按链条算：半径比=速弦角正弦的反比（$r=L/(2\\sin\\theta)$，为$\\sqrt{3}:1$）；圆心角比=速弦角比（$60^\\circ:120^\\circ$即$1:2$）；时间相同由$t=(\\alpha/360^\\circ)T$得周期比=圆心角反比（$2:1$）；速率比=半径比$\\times$周期反比$=\\sqrt{3}:2$；比荷倒数比=半径比$\\times$速率反比$=2:1$】；警惕【周期比按圆心角正比算反；速率比漏乘周期项】","src":"跳跳物一轮11.4 常见有界磁场总结、弦长公式_笔记","note":"视频|38:27","orig":"（例）带异种电荷的粒子a、b从同一点射入宽为$d$的匀强磁场，入射方向与边界分别成$60^\\circ$和$30^\\circ$（速弦角$30^\\circ$和$60^\\circ$），两粒子弦长相同且同时到达同一点，求轨道半径、周期、速率、比荷倒数之比。","link":""},{"id":"phy2638","t":"带电粒子在磁场中的运动·放缩圆模型识别与临界相切","s":"看到【粒子从固定点沿固定方向射入磁场，速度大小可调，问恰好飞出或不飞出的临界速度】","c":"想到【放缩圆模型：半径 $R=\\frac{mv}{qB} \\propto v$，速度增大轨迹圆放大、速度减小轨迹圆缩小；从最小圆开始逐步放大找临界轨迹。恰好飞出与恰好不飞出等价，临界轨迹都是轨迹圆与边界相切，由相切几何关系定半径、再结合半径公式求速度】；警惕【临界不是速度取零或最大，而是轨迹与边界相切；两圆相切的几何条件漏用会把临界半径算错】","src":"跳跳物一轮11.5 放缩圆、旋转圆_笔记","note":"视频|00:22","orig":"（知识）粒子入射点与速度方向固定、速度大小可变的有界磁场轨迹模型及其临界条件。","link":""},{"id":"phy2639","t":"带电粒子在磁场中的运动·放缩圆时间最值与速弦角","s":"看到【放缩圆情境中问粒子在磁场中运动的最短或最长时间】","c":"想到【时间 $t=\\frac{\\alpha}{360^\\circ} \\cdot \\frac{2\\pi m}{qB}$，$\\alpha$为圆心角；圆心角 $\\alpha=2\\theta$（$\\theta$为速弦角，即弦与入射速度方向的夹角），故 $t \\propto \\theta$。放缩圆中入射方向固定、速弦角易定：时间最短对应速弦角最小的轨迹，时间最长对应速弦角最大的轨迹，通过放缩轨迹圆找速弦角极值】；警惕【圆心角是速弦角的2倍，把速弦角直接当圆心角代入时间公式会错一半；半径变化时周期 $\\frac{2\\pi m}{qB}$ 不变，时间只由圆心角决定】","src":"跳跳物一轮11.5 放缩圆、旋转圆_笔记","note":"视频|00:22","orig":"（知识）放缩圆中粒子在磁场内运动时间的计算与最值判定方法。","link":""},{"id":"phy2640","t":"带电粒子在磁场中的运动·旋转圆模型与经过区域","s":"看到【大量相同粒子从同一点以相同速率、不同方向射入磁场，问粒子能经过的区域】","c":"想到【旋转圆模型：速度大小固定则半径固定，方向变化时轨迹圆绕入射点旋转。求经过区域：先确定能进入磁场的速度方向范围，再让轨迹圆随速度方向旋转扫过全部范围，圆扫过的区域即粒子能经过的区域；方向转多少度圆就转多少度，复杂情形可把圆劈成两半分别分析】；警惕【与放缩圆相反：旋转圆是大小固定方向可变；速度方向的旋转范围找错，区域会多算或少算】","src":"跳跳物一轮11.5 放缩圆、旋转圆_笔记","note":"视频|00:22-16:25","orig":"（知识）粒子入射点与速度大小固定、方向可变的轨迹模型及能经过区域的判定。","link":""},{"id":"phy2641","t":"带电粒子在磁场中的运动·旋转圆最远射出点判定","s":"看到【旋转圆情境中问粒子离入射点最远能射到多远】","c":"想到【入射点到射出点的距离等于轨迹圆的弦长，弦越长射出点越远。先判断弦能否取到直径：边界允许（如无限长边界）则弦取直径时射出点最远；边界受限、直径弦取不到（粒子会提前出磁场）则轨迹圆与边界相切时最远，切点即最远射出点】；警惕【不能无脑取直径作答案，边界受限时直径弦根本取不到，必须改找相切临界】","src":"跳跳物一轮11.5 放缩圆、旋转圆_笔记","note":"视频|00:22-16:25","orig":"（知识）旋转圆中粒子射出点离入射点最远距离的判定方法。","link":""},{"id":"phy2642","t":"带电粒子在磁场中的运动·旋转圆时间最值与弧长","s":"看到【旋转圆情境中问粒子到达某边界或板所需的最长最短时间】","c":"想到【各粒子速度大小相同、周期相同，时间与弧长成正比：最短时间对应最短弧，常由最短弦长（如入射点到板的垂线段）得到；最长时间对应最长弧，常见陷阱是轨迹与板相切时弦虽短弧却是优弧（圆心角可达 $270^\\circ$），应旋转轨迹圆直接比较弧长而非弦长】；警惕【最长时间不等于最长弦：弦越短弧可能越长（优弧），按弦最长去找时间结论会反过来】","src":"跳跳物一轮11.5 放缩圆、旋转圆_笔记","note":"视频|00:22-16:25","orig":"（知识）旋转圆中粒子运动时间的最值分析方法。","link":""},{"id":"phy2643","t":"带电粒子在磁场中的运动·放缩圆打板速度范围","s":"看到【粒子沿固定方向射入磁场、下方有板，求能打在板上的上下限速度】","c":"想到【双临界放缩：下限对应轨迹圆与板相切，过P作板的垂线即为直径，得 $R=\\frac{L}{4}$、$v_{min}=\\frac{eBL}{4m}$；上限对应轨迹恰好过板右端点，由几何定弦长为 $\\frac{\\sqrt{2}L}{2}$、速弦角 $45^\\circ$，代入弦长公式（弦长 $=2mv\\sin\\theta/(qB)$）得 $v_{max}=\\frac{eBL}{2m}$】；警惕【上限不是与板相切而是恰好过端点；下限用相切几何配半径公式、上限用端点几何配弦长公式，两套几何不能混用】","src":"跳跳物一轮11.5 放缩圆、旋转圆_笔记","note":"视频|16:25","orig":"（例）电子从P点水平向右射入垂直纸面向里的匀强磁场向下偏转，P点到下方水平板的距离为 $\\frac{L}{2}$，板右端点到P点的水平距离为 $\\frac{L}{2}$，求电子能打在板上的速度 $v_0$ 范围。","link":""},{"id":"phy2644","t":"带电粒子在磁场中的运动·三角形磁场射出点与时间判断","s":"看到【粒子从三角形边界中点沿平行某边方向射入，多选项判断射出点及运动时间】","c":"想到【先左手定则定偏转方向；排除不可能射出点：所有轨迹圆在入射点的切线必沿入射方向，过B点的圆在D点切线不平行BC，故不能从B点射出；从AB边射出时速弦角恒定，圆心角恒定，时间与速度大小无关；从C点射出时利用D为AB中点、CD平分角ACB定速弦角 $30^\\circ$，圆心角 $60^\\circ$，$t=\\frac{\\pi m}{3qB}$】；警惕【入射方向固定时不是任意边界点都能成为射出点；从同一边射出的时间与速度无关，别以为速度大时间就长】","src":"跳跳物一轮11.5 放缩圆、旋转圆_笔记","note":"视频|25:58","orig":"（例）带负电粒子从边长 $L$ 的等边三角形磁场AB边中点D沿平行BC边的方向射入，判断粒子能否从B点射出、从C点射出（并求时间）、以及从AB边射出时时间的特点。","link":""},{"id":"phy2645","t":"带电粒子在磁场中的运动·旋转圆打板区域与时间最值","s":"看到【相同速率不同方向入射的粒子打在板上，问可打区域长度或时间最值】","c":"想到【旋转圆（半径固定为 $d$）绕P旋转分析：右侧弦能取直径 $2d$，最远点距垂足 $\\sqrt{3}d$；左侧取不到直径，轨迹与板相切时最远，距垂足 $d$，板上区域总长为 $d+\\sqrt{3}d$。时间与弧长成正比：相切时弧最长（优弧，圆心角 $270^\\circ$），$t=\\frac{3\\pi d}{2v}$；垂线弦最短（弦 $=d$），圆心角 $60^\\circ$，$t=\\frac{\\pi d}{3v}$；离P最远即直径 $2d$】；警惕【左侧最远不是直径而是相切临界；最长时间对应优弧而非最长弦，按弦长最长去找结论会反】","src":"跳跳物一轮11.5 放缩圆、旋转圆_笔记","note":"视频|30:51","orig":"（例）大量带电粒子从P点以相同速率、不同方向射入匀强磁场，轨迹圆半径 $r=d$，P到无限大平板的距离为 $d$，求板上粒子能打到的区域总长度、离P的最远距离、到达板上的最长时间和最短时间。","link":""},{"id":"phy2646","t":"带电粒子在磁场中的运动·速弦角与弦长求法","s":"看到【已知粒子入射和出射的速度方向，需要求弦长或轨迹尺寸】","c":"想到【三步法：先求速度偏转角 $\\alpha$（出射速度相对入射速度转过的角度），再由速弦角 $\\beta=\\frac{\\alpha}{2}$（速弦角即弦与速度切线方向的夹角，等于偏转角一半），最后代入弦长公式 $L=2R\\sin\\beta$（R为轨迹圆半径）求弦长】；警惕【速弦角不是偏转角本身而是其一半，直接拿偏转角代入弦长公式会算错；速弦角与圆心角也不同，圆心角=2×速弦角】","src":"跳跳物一轮11.6 最小磁场面积问题、磁聚焦与磁发散_笔记","note":"视频|00:52","orig":"（知识）由射入、射出速度方向求轨迹弦长的三步法。","link":""},{"id":"phy2647","t":"带电粒子在磁场中的运动·圆形磁场最小面积","s":"看到【给定入射出射速度方向，问圆形磁场区域的最小面积】","c":"想到【核心原则：磁场区域恰好包裹住圆弧轨迹时面积最小。劣弧情况下最小圆形磁场的直径恰等于轨迹弦长：设弦长L，磁场圆半径 $R=\\frac{L}{2}$，最小面积 $S=\\pi(\\frac{L}{2})^2=\\frac{\\pi L^2}{4}$。先按速弦角=偏转角一半求出弦长，再代入面积公式】；警惕【适用前提是劣弧（圆心角小于180°）；优弧时最小圆形磁场应取轨迹圆直径为磁场圆直径，套劣弧结论会错】","src":"跳跳物一轮11.6 最小磁场面积问题、磁聚焦与磁发散_笔记","note":"视频|04:09","orig":"（知识）已知粒子轨迹为劣弧时圆形磁场区域的最小面积求法。","link":""},{"id":"phy2648","t":"带电粒子在磁场中的运动·矩形磁场最小面积","s":"看到【给定入射出射速度方向，问矩形磁场区域的最小面积】","c":"想到【矩形长取弦长 $L$，宽由圆心到弦的垂距求：作弦的中垂线与入射速度的垂线相交定轨迹圆心，圆心到弦的距离 $d=\\sqrt{R^2-(\\frac{L}{2})^2}$（R为轨迹圆半径），矩形宽为 $R-d$，最小面积 $S=L\\times(R-d)$】；警惕【宽不是随意取的圆弧最高点到弦的距离，而是半径R减去圆心到弦的垂距d；漏掉勾股关系把宽直接当R会算大】","src":"跳跳物一轮11.6 最小磁场面积问题、磁聚焦与磁发散_笔记","note":"视频|04:09","orig":"（知识）已知粒子轨迹为劣弧时矩形磁场区域的最小面积求法。","link":""},{"id":"phy2649","t":"带电粒子在磁场中的运动·磁聚焦条件与射出点","s":"看到【多个同电性粒子以相同方向从不同点射入圆形磁场，问射出点或聚焦点】","c":"想到【磁聚焦四条件：磁场为圆形、轨迹圆半径等于磁场圆半径、粒子电性相同、以相同方向从各点射入；满足时所有粒子聚焦于同一点射出。射出点判定：作与入射速度方向垂直的磁场圆直径，射出点为该直径与磁场圆边界的交点（如水平射入、向下偏转，射出点为竖直直径的下端点）】；警惕【轨迹圆半径不等于磁场圆半径时不会聚焦；射出点在垂直于入射速度的直径上，不是沿速度方向的直径上】","src":"跳跳物一轮11.6 最小磁场面积问题、磁聚焦与磁发散_笔记","note":"视频|10:16","orig":"（知识）粒子从不同点以相同方向射入圆形磁场后聚焦于同一点的现象及射出点判定。","link":""},{"id":"phy2650","t":"带电粒子在磁场中的运动·磁发散条件与射出方向","s":"看到【同电性粒子从同一点以不同方向射入圆形磁场，问射出速度方向】","c":"想到【磁发散四条件：磁场为圆形、轨迹圆半径等于磁场圆半径、粒子电性相同、从同一点以各方向射入；满足时所有粒子射出速度方向相同。射出方向判定：过入射点作磁场圆的直径，射出速度方向与该直径垂直（如过入射点的直径竖直，则射出速度均沿水平方向）】；警惕【磁发散是磁聚焦的逆过程，条件同样是半径相等；射出方向垂直于过入射点的直径，不是沿入射方向找】","src":"跳跳物一轮11.6 最小磁场面积问题、磁聚焦与磁发散_笔记","note":"视频|12:08","orig":"（知识）粒子从同一点以各方向射入圆形磁场后射出速度方向相同的现象及射出方向判定。","link":""},{"id":"phy2651","t":"带电粒子在磁场中的运动·磁聚焦磁发散菱形求圆心角","s":"看到【圆形磁场中算出轨迹圆半径等于磁场圆半径，要求时间或弧长】","c":"想到【联想磁聚焦/磁发散性质：先定轨迹圆圆心（分别作入射、出射速度的垂线，交点即圆心）；依次连接入射点、磁场圆圆心、出射点、轨迹圆圆心，四条边均为半径且 $r=R$，四边形为菱形；利用菱形性质（对角线垂直平分、对角相等、邻角互补）结合已知角求出轨迹圆心角，再算时间或弧长】；警惕【不画菱形硬凑角度易漏邻角互补关系；菱形中磁场圆圆心角与轨迹圆心角不一定相等，须逐角核对】","src":"跳跳物一轮11.6 最小磁场面积问题、磁聚焦与磁发散_笔记","note":"视频|14:00","orig":"（知识）轨迹圆半径等于磁场圆半径时利用菱形求轨迹圆心角的方法。","link":""},{"id":"phy2652","t":"带电粒子在磁场中的运动·磁聚焦综合判断例题","s":"看到【轨迹圆半径等于磁场圆半径的圆形磁场题，判断时间、出射方向、聚焦点或最小面积】","c":"想到【由 $v_0=\\frac{qBR}{m}$ 得轨迹圆半径等于磁场圆半径，属磁聚焦模型：连接A、N与两圆心构成菱形，$\\angle AON=120^\\circ$ 即轨迹圆心角，$t=\\frac{120^\\circ}{360^\\circ} \\cdot \\frac{2\\pi m}{qB}=\\frac{2\\pi m}{3qB}$；相同速度从任一点入射仍聚焦于N；最小磁场面积以弦AN为直径，弦长 $\\sqrt{3}R$，$S=\\frac{3\\pi R^2}{4}$】；警惕【出射方向由菱形几何判定，不能想当然设为竖直向下；时间所用的圆心角须在菱形中核对，不能与磁场圆圆心角混用】","src":"跳跳物一轮11.6 最小磁场面积问题、磁聚焦与磁发散_笔记","note":"视频|28:25","orig":"（例）半径 $R$ 的圆形磁场中，带正电粒子从磁场边界A点以速度 $v_0=\\frac{qBR}{m}$ 垂直于直径MN的方向射入，恰好从N点射出，$\\angle AON=120^\\circ$。判断：粒子在磁场中的运动时间、出射方向、从边界另一点C以相同速度入射时的射出点、以及实现A到N偏转所需圆形磁场的最小面积。","link":""},{"id":"phy2653","t":"带电粒子在磁场中的运动·四分之一圆磁场磁聚焦与时间差","s":"看到【1/4圆形磁场中沿同一方向入射的粒子击中同一点，问速度条件或时间差】","c":"想到【击中同一点即磁聚焦：轨迹圆半径等于磁场圆半径，由 $\\frac{mv}{qB}=R$ 得 $v=\\frac{qBR}{m}$；聚焦点由最上方粒子（$y=R$，不进磁场直线打到y轴）确定；最长时间看速弦角最大的最下方（$y=0$）粒子，速弦角 $45^\\circ$、圆心角 $90^\\circ$，$t_{max}=\\frac{\\pi m}{2qB}$；最短时间 $t_{min}=\\frac{R}{v}=\\frac{m}{qB}$，时间差 $\\Delta t=\\frac{(\\pi-2)m}{2qB}$】；警惕【速弦角最大（弦最长）的粒子在入射区间最下端不是上端；最上方粒子未进入磁场，其时间用直线运动算，不能套磁场周期公式】","src":"跳跳物一轮11.6 最小磁场面积问题、磁聚焦与磁发散_笔记","note":"视频|32:35","orig":"（例）半径 $R$ 的1/4圆形匀强磁场（垂直纸面向里），粒子发射装置在 $0 \\le y \\le R$ 区间沿x轴正方向发射速度相同的带正电粒子，所有粒子经磁场偏转后击中y轴上同一位置。求粒子初速度、最长时间、最短时间与最大时间差。","link":""},{"id":"phy2654","t":"叠加场·三种运动模式判定与重力取舍","s":"看到【粒子在含磁场的叠加场中运动，问运动性质或轨迹特点】","c":"想到【先看题目是否提到重力加速度 $g$，提到才考虑重力。再判定模式：①合力为零（如不计重力时电场力与洛伦兹力等大反向）→匀速直线运动；②重力与电场力等大反向抵消→粒子只在洛伦兹力作用下做匀速圆周运动；③不满足前两种→一般周期性曲线运动，每个周期轨迹完全相同，用配速法或动能定理分析】；警惕【没提 $g$ 默认不计重力，多算重力会把匀速直线误判为曲线；匀速圆周模式要求两力精确等大反向，只部分抵消时仍属一般曲线运动】","src":"跳跳物一轮11.7 带电粒子在叠加场中的运动（含配速法）_笔记","note":"视频|00:29-03:53","orig":"（知识）带电粒子在叠加场（磁场+电场/重力场）中运动模式的判定方法。","link":""},{"id":"phy2655","t":"叠加场·配速法的力与分速度分配规则","s":"看到【把初速度分解为两个分速度，分别对应平衡分运动和圆周分运动】","c":"想到【分配规则：每个力只能影响一个分速度，具体影响哪个由解题者自行分配；可以多个力共同影响同一个分速度；但一个力绝不能同时影响多个分速度，否则该力的作用被重复计算，结果必然错误。正确分配方式不唯一，殊途同归结果一致】；警惕【最典型错误：让同一个力同时对两个分速度加速，等于把该力用了两次，算出的合速度偏大】","src":"跳跳物一轮11.7 带电粒子在叠加场中的运动（含配速法）_笔记","note":"视频|04:59","orig":"（知识）把初速度分解为分速度并让各力分别作用于分速度的规则。","link":""},{"id":"phy2656","t":"叠加场·配速法核心思想与运动分解","s":"看到【带电粒子在磁场+重力场（或电场）中做一般周期性曲线运动，需定量分析】","c":"想到【配速法：给初速度为零的粒子配一个速度 $v_0$，使其洛伦兹力 $qv_0B$ 与其他场力（如 $mg$）等大反向，再配一个等大反向的 $-v_0$ 保持与原状态等价；运动分解为 $v_0$ 的匀速直线分运动（对应场力被洛伦兹力平衡）与 $-v_0$ 的匀速圆周分运动（洛伦兹力提供向心力）的叠加】；警惕【配完 $v_0$ 必须补 $-v_0$，否则多出的速度改变了原题状态；平衡方程中洛伦兹力与场力方向须精确相反，方向配反全盘皆错】","src":"跳跳物一轮11.7 带电粒子在叠加场中的运动（含配速法）_笔记","note":"视频|09:36","orig":"（知识）用配速法处理带电粒子在磁场与重力场（或电场）叠加场中曲线运动的核心操作。","link":""},{"id":"phy2657","t":"叠加场·配速法适用时刻与静止释放三结论","s":"看到【配速法情境中问特定时刻的速度、位移或一个周期内的位移】","c":"想到【配速法最适合分析 $\\frac{nT}{2}$（$n=1,2,3\\ldots$）时刻，此时两分速度方向共线，合速度易求。静止释放三结论：$\\frac{T}{2}$ 时刻速度大小为 $2v_0$（两分速度同向叠加）；$0\\sim\\frac{T}{2}$ 时间内沿重力方向位移为 $2R$（半圆轨迹直径）；$0\\sim T$ 时间内总位移为 $v_0 T$（圆周分运动每周期位移为零）】；警惕【三结论前提是静止释放且 $qv_0B=mg$ 精确平衡；非 $\\frac{nT}{2}$ 时刻分速度不共线，须矢量合成不能简单相加】","src":"跳跳物一轮11.7 带电粒子在叠加场中的运动（含配速法）_笔记","note":"视频|13:27-18:13","orig":"（知识）静止释放的带电粒子在磁场+重力场（$qv_0B=mg$）中运动的时间节点结论。","link":""},{"id":"phy2658","t":"叠加场·动能定理适用与方法选择","s":"看到【叠加场曲线运动中问某点速度、下落高度或任意时刻的位移】","c":"想到【洛伦兹力永不做功，故合力做功等于其他场力（重力、电场力）做功，动能定理适用于任意点：如只有重力做功时 $mgh=\\frac{1}{2}mv^2$，可直接解出高度或速度。方法分工：分析 $\\frac{nT}{2}$（$n=1,2,3\\ldots$）时刻的点用配速法更简单；分析其他任意点用动能定理更简单】；警惕【动能定理只管速率不涉及方向，问速度方向或轨迹形状仍需配速法；列式时别把洛伦兹力计入做功项】","src":"跳跳物一轮11.7 带电粒子在叠加场中的运动（含配速法）_笔记","note":"视频|19:47-20:52","orig":"（知识）叠加场中用动能定理分析粒子运动的要点及与配速法的分工。","link":""},{"id":"phy2659","t":"叠加场·正交电磁场直线运动与反向入射","s":"看到【正交电场磁场中粒子沿直线穿过，问场量关系或不同电性方向的粒子能否直线通过】","c":"想到【速度选择器原理：直线运动时竖直方向合力为零，$qE=qvB$，得 $E=vB$，与粒子电性无关。电子从左向右：电场力竖直向上（负电荷与场强反向）、洛伦兹力竖直向下，等大反向，仍匀速直线；电子从右向左：电场力方向不变仍向上，洛伦兹力随速度反向也变为向上，两力同向，电子向上偏转】；警惕【洛伦兹力方向随速度反向而反向，电场力方向不随运动方向改变；反向入射时平衡被破坏，不能套 $E=vB$ 判直线】","src":"跳跳物一轮11.7 带电粒子在叠加场中的运动（含配速法）_笔记","note":"视频|21:13","orig":"（例）不计重力，正交的匀强电场（竖直向下）与匀强磁场（垂直纸面向里）区域中，正离子能从左向右沿直线飞越；判断场强与速度的关系，以及电子分别从左向右、从右向左射入时的运动情况。","link":""},{"id":"phy2660","t":"叠加场·三场叠加合力等效与位移垂直推论","s":"看到【电场力与重力互相垂直的叠加场中粒子静止释放做周期性运动，问速度极值或间距】","c":"想到【把恒定的电场力与重力的合力等效为'重力'，化归为静止释放配速法模型：由一个周期末速度为零、动能不变知合力不做功，故OB连线与合力垂直；轨迹最低点A（四分之一周期时）速度最大为 $2v_0$（$v_0=$ 合力 $/(qB)$）；半周期末B点速度为零；OB间距等于圆周分运动直径 $2R=\\frac{2mv_0}{qB}$】；警惕【电场力做功，机械能不守恒；OB⊥合力是速度为零加动能不变的推论，不能把OB当沿合力方向】","src":"跳跳物一轮11.7 带电粒子在叠加场中的运动（含配速法）_笔记","note":"视频|35:07","orig":"（例）重力场、电场、磁场三场叠加区域，带正电小球从O点静止释放，所受电场力与重力大小相等（各 $1\\,\\mathrm{N}$）且互相垂直（合力 $\\sqrt{2}\\,\\mathrm{N}$）；小球经一个周期到达B点时速度再次为零，A点为轨迹最低点（$\\frac{T}{4}$ 时刻）。判断机械能是否守恒、A点与B点的速度大小，并求O、B两点间距 $l$。","link":""},{"id":"phy2661","t":"叠加场·初速度不为零时的配速法","s":"看到【非零初速度射入不平衡电磁场做周期性运动，恰好垂直打在挡板，求打点速度】","c":"想到【初速不为零的配速法：在原速度 $v$ 之外再配一对速度 $v'$ 与 $-v'$。配向右的 $v'$ 使 $qv'B_1+qvB_1=qE_2$（补足洛伦兹力与电场力的平衡），则 $v+v'$ 为匀速直线分运动；$-v'$ 的洛伦兹力提供向心力做圆周分运动。粒子打在轨迹最低点O'时圆周分速度与直线分速度同向，合速度为 $v+2v'=\\frac{2E_2-E_1}{B_1}$】；警惕【配速对象是额外配出的 $v'$ 而不是把总速度重新分解；最低点两分速度同向相加、最高点相减，方向判错结果差一倍】","src":"跳跳物一轮11.7 带电粒子在叠加场中的运动（含配速法）_笔记","note":"视频|44:59","orig":"（例）质谱仪某区域为正交电磁场（磁场 $B_1$ 垂直纸面向里），电场强度由 $E_1$ 增大为 $E_2$（$E_2>E_1$）后，以速度 $v=\\frac{E_1}{B_1}$ 水平向右射入的粒子向下偏转做周期性曲线运动，恰好垂直打在下方挡板的O'点（轨迹最低点），求粒子打在O'点时的速度大小。","link":""},{"id":"phy2662","t":"电磁叠加场·速度选择器的平衡条件与选择性","s":"看到【正交电磁场中粒子沿直线穿过小孔，问哪些粒子能通过或改变电性、电量、速度后的运动】","c":"想到【$qvB=qE$ 时粒子做匀速直线运动，通过速度 $v=E/B$；速度选择器只选速度不选电性、电量、质量：正负电荷两力同时反向仍平衡，等式两边可约去 $q$；反向射入时洛伦兹力反向、与电场力同向，合力不为零必偏转】；警惕【认为电性或电量影响能否直线通过；速度大小改变后仍以为做直线运动】","src":"跳跳物一轮11.8 电磁叠加场四大应用_笔记","note":"视频|00:20","orig":"（知识）速度选择器中电场与磁场正交叠加，满足条件的粒子沿直线穿过小孔。","link":""},{"id":"phy2663","t":"电磁叠加场·霍尔电压的推导与电势高低判断","s":"看到【导体薄片通电流并加垂直磁场，问两侧电压表达式或哪一侧电势高】","c":"想到【稳定时 $qvB=qE$；联立 $U_H=E\\cdot d$ 与电流微观式 $I=nqvS$ 得 $U_H=IB/(nqd)$；电势高低必须按实际载流子的电性和运动方向用左手定则判断，电子积累的一侧带负电、电势低】；警惕【无脑把电流视为正电荷定向移动导致电势高低反号；公式分母的 $d$ 误用成其他长度】","src":"跳跳物一轮11.8 电磁叠加场四大应用_笔记","note":"视频|06:44","orig":"（知识）霍尔元件中载流子在磁场作用下偏转积累，稳定后两侧形成霍尔电压。","link":""},{"id":"phy2664","t":"电磁叠加场·电磁流量计的流量公式","s":"看到【导管加磁场测污水流速，已知电压表示数、管径和磁感应强度，求流量或判断流量与各量的关系】","c":"想到【稳定时 $qvB=qE$ 且 $E=U/d$，得流速 $v=U/(dB)$；流量 $Q=Sv=\\pi DU/(4B)$（圆管横截面积 $S=\\pi D^2/4$）；流量与离子浓度无关、与管长无关，与管径 $D$ 成正比；正离子偏转积累侧电势高】；警惕【漏算横截面积；误认为流量与离子浓度或管道长度有关】","src":"跳跳物一轮11.8 电磁叠加场四大应用_笔记","note":"视频|12:02","orig":"（知识）电磁流量计由霍尔元件加电压表构成，利用稳定后的电压测流体流量。","link":""},{"id":"phy2665","t":"电磁叠加场·磁流体发电机的电动势与路端电压","s":"看到【等离子体喷入磁场使两极板带电并接通外电路，求电动势、路端电压或电流】","c":"想到【正离子洛伦兹力偏转积累侧为正极；稳定时 $qvB=qE$，电动势 $\\varepsilon=vBd$（等于开路电压，外电路闭合与否稳定场强相同）；带内阻时路端电压 $U=\\varepsilon R/(R+r)$，内阻 $r=\\rho d/S$，电流 $I=\\varepsilon/(R+r)$；电压随板间距 $d$、喷入速率 $v$ 增大而增大，与粒子数密度无关】；警惕【漏算内阻直接写 $U=\\varepsilon$；用错洛伦兹力方向导致正负极判断反】","src":"跳跳物一轮11.8 电磁叠加场四大应用_笔记","note":"视频|17:59","orig":"（知识）磁流体发电机以等离子体为载流子，霍尔元件作为电源对外电路供电。","link":""},{"id":"phy2666","t":"电磁叠加场·速度选择器反向射入与参数改变的轨迹判断","s":"看到【粒子原沿直线通过速度选择器，问反向射入或增大速度、增大电量后的轨迹形状】","c":"想到【增大速度则 $qvB>qE$ 合力不为零、轨迹不再是直线；增大电量则电场力与洛伦兹力同步增大仍平衡、保持直线；反向射入后洛伦兹力与电场力同向，粒子向上偏转，轨迹是沿原方向的匀速直线运动与匀速圆周运动的叠加（配速法）】；警惕【把偏转轨迹误判为抛物线；认为增大电量会破坏平衡导致偏转】","src":"跳跳物一轮11.8 电磁叠加场四大应用_笔记","note":"视频|21:09","orig":"（例）粒子在速度选择器中沿水平方向做直线运动，讨论增大速度 $v_0$、增大粒子电量、粒子从右向左（反向）射入三种情况下的轨迹。","link":""},{"id":"phy2667","t":"电磁叠加场·四大应用的核心方程与稳定条件对比","s":"看到【电磁叠加场四大装置辨析，问各自稳定条件、核心方程或电势极性判断关键】","c":"想到【统一核心方程均为洛伦兹力=电场力 $qvB=qE$；速度选择器得 $v=E/B$，霍尔效应得 $U_H=IB/(nqd)$，流量计得 $Q=SU/(dB)$，发电机得 $\\varepsilon=vBd$；电势判断：霍尔元件须按实际载流子方向，流量计与发电机正离子偏转积累侧电势高】；警惕【不同装置的最终公式张冠李戴；发电机稳定是充电速度=放电速度的动态平衡，与其他三者合力为零不同】","src":"跳跳物一轮11.8 电磁叠加场四大应用_笔记","note":"视频|00:09","orig":"（知识）速度选择器、霍尔效应、电磁流量计、磁流体发电机同属电磁叠加场的四大应用。","link":""},{"id":"phy2668","t":"电磁拼接场·拼接场与叠加场的区分","s":"看到【电场和磁场各占一段区域（先电场后磁场），问场的特点或与叠加场的区别】","c":"想到【拼接场中同一区域只有一种场、不叠加；叠加场是同一区域电场磁场共存、粒子同时受两种场力；拼接场问题分区处理：电场区用动力学或类平抛规律，磁场区用圆周运动规律，衔接量是进入下一区域的速度大小和方向】；警惕【把拼接场当叠加场，在某一区域内同时考虑电场力和洛伦兹力】","src":"跳跳物一轮11.9 电磁拼接场_磁场模块完结撒花~_笔记","note":"视频|00:09","orig":"（知识）电磁拼接场指电场和磁场分区分布，粒子先后经历不同场。","link":""},{"id":"phy2669","t":"电磁拼接场·质谱仪分离比荷与同位素质量比","s":"看到【同位素经相同电压加速后进入磁场打到不同位置，求质量比或比荷关系】","c":"想到【电场加速 $qU=\\frac{1}{2}Mv^2$ 与磁场圆周 $qvB=Mv^2/R$ 联立得 $R=\\frac{1}{B}\\sqrt{\\frac{2U}{k}}$，$R\\propto 1/\\sqrt{k}$（$k$ 为比荷 $q/M$），故 $R^2\\propto M/q$；同位素电荷量相同，质量比 $M_1:M_2=R_1^2:R_2^2$；落点距离为直径，$R_1:R_2=x_1:x_2$，故 $M_1:M_2=x_1^2:x_2^2$】；警惕【同位素是电荷量相同、质量不同，不是质量相同；落点距离是直径不是半径，差 2 倍】","src":"跳跳物一轮11.9 电磁拼接场_磁场模块完结撒花~_笔记","note":"视频|18:13","orig":"（例）质谱仪中同位素两粒子电荷量相同（$q_1=q_2$），经同一加速电压 $U$ 加速后垂直进入同一偏转磁场，分别打到离出射口 $x_1$、$x_2$ 处（$x$ 为直径），求质量比 $M_1:M_2$。","link":""},{"id":"phy2670","t":"电磁拼接场·速度选择器与质谱仪综合","s":"看到【粒子先过速度选择器再进偏转磁场，问各粒子速度大小、质量关系或质量差表达式】","c":"想到【偏转方向定速度：偏向电场力一侧说明 $v<E/B_1$，直线说明 $v=E/B_1$，偏向洛伦兹力一侧说明 $v>E/B_1$；同速同电量的粒子在 $B_2$ 中由 $M=B_2 qR/v$，半径大者质量大；质量差 $\\Delta m=(B_2 q/v)\\cdot\\Delta r$，直径差 $\\Delta x$ 对应 $\\Delta r=\\Delta x/2$，速度选择器 $v=U/(B_1 L)$，代入得 $\\Delta m=B_1 B_2 qL\\Delta x/(2U)$】；警惕【直径差忘记除以 2 才是半径差；用 $E=U/L$ 换算速度时漏掉极板间距 $L$】","src":"跳跳物一轮11.9 电磁拼接场_磁场模块完结撒花~_笔记","note":"视频|20:18","orig":"（例）四个正离子先经速度选择器（场强 $E$、磁场 $B_1$、极板间距 $L$、电压 $U$）再进入偏转磁场 $B_2$：a 向电场力方向偏、b 向洛伦兹力方向偏、c 和 d 直线通过且偏转半径 $R_D>R_C$，判断速度与质量关系并推导质量差。","link":""},{"id":"phy2671","t":"电磁拼接场·回旋加速器的周期条件与最大动能","s":"看到【D形盒加磁场和交变电场多次加速粒子，问最大动能、加速次数或总时间】","c":"想到【加速条件：交变电场变化周期等于磁场中回旋周期 $T=2\\pi m/(qB)$；最大动能 $E_{km}=q^2B^2R^2/(2m)$ 由D形盒半径 $R$ 和磁感应强度 $B$ 决定，与加速电压 $U$ 无关；加速次数 $n=E_{km}/(qU)$，总时间 $t=(n/2)T$】；警惕【认为增大电压 $U$ 能提高最大动能——$U$ 只影响加速次数和总时间；漏写电场周期与回旋周期相等的条件】","src":"跳跳物一轮11.9 电磁拼接场_磁场模块完结撒花~_笔记","note":"视频|00:09-20:18","orig":"（知识）回旋加速器用磁场约束方向、周期性电场多次加速粒子。","link":""},{"id":"phy2672","t":"电磁拼接场·电场类平抛接磁场的衔接量","s":"看到【粒子先在电场中类平抛再进入有界磁场，求在磁场中的半径、时间或磁感应强度】","c":"想到【衔接关键：先求进入磁场时的速度大小和方向，$\\tan\\theta=v_y/v_0=2y/x$（速度角正切是位移角正切的 2 倍）；磁场区画轨迹、定圆心、求半径；直线边界入射角=出射角，磁场中时间由圆心角决定 $t=\\theta m/(qB)$】；警惕【把位移角当速度角使用；磁场中时间用位移角或弦长角计算而不用圆心角】","src":"跳跳物一轮11.9 电磁拼接场_磁场模块完结撒花~_笔记","note":"视频|00:09-20:18","orig":"（知识）粒子先在电场中做类平抛，再进入磁场做匀速圆周运动，是典型拼接场模型。","link":""},{"id":"phy2673","t":"电磁感应·磁通量的定义与正负号规则","s":"看到【比较两个带符号的磁通量大小，或求磁通量变化量、平面翻转180°后的磁通量】","c":"想到【$\\Phi=BS$ 仅适用于匀强磁场且 $B\\perp S$；磁通量是标量但有正负，正负只区分磁感线从哪个面穿入；比大小只比绝对值（$-5\\mathrm{Wb}>3\\mathrm{Wb}$）；变化量 $\\Delta\\Phi$=末态减初态且正负号代入运算；平面翻转 180° 磁通量变为 $-\\Phi$，变化量大小为 $2\\Phi$】；警惕【比大小时把负号当大小参与比较；算变化量丢掉正负号，翻转 180° 时变化量漏掉 2 倍】","src":"跳跳物一轮12.1 磁通量、电磁感应现象、楞次定律_笔记","note":"视频|00:22-07:05","orig":"（知识）磁通量是标量但有正负，正负号的含义和运算规则是易错点。","link":""},{"id":"phy2674","t":"电磁感应·磁通量计算技巧（谁斜动谁）","s":"看到【斜面（如三棱柱侧面）在匀强磁场中求磁通量，或线圈只有部分在磁场内，或题给线圈匝数】","c":"想到【谁斜动谁：$B$ 斜则分解 $B$ 取垂直于面的分量，$S$ 斜则取面在垂直于 $B$ 方向上的投影面积（如正方形侧面向竖直面投影后面积变为 $(\\sqrt{2}/2)L^2$）；有效面积只取磁场中的那部分（圆的一半在磁场中取 $S/2$）；匝数：多数教材计算磁通量不乘匝数，科教版要乘 $N$】；警惕【不看实际夹角直接套 $\\Phi=BS\\cdot\\sin\\theta$；把总面积当有效面积；匝数处理与所用教材版本不符】","src":"跳跳物一轮12.1 磁通量、电磁感应现象、楞次定律_笔记","note":"视频|07:05","orig":"（知识）平面与磁场不垂直、或平面只有部分处于磁场中时，磁通量需要处理后再套公式。","link":""},{"id":"phy2675","t":"电磁感应·条形磁铁穿过线圈的磁通量","s":"看到【环沿条形磁铁移动、两个同心圆环套在磁铁上、或环从磁铁上方落到下方，比较各位置磁通量】","c":"想到【环沿磁铁靠近正中间磁通量越大；两个同心圆环被磁铁穿过时圈越大磁通量越小——内部磁感线全部穿过、外部反向磁感线部分穿过相互抵消，圈越大包住的反向磁感线越多、剩余越小；环从上方无限远落到下方无限远：磁通量先增后减、经磁铁正中间（磁感线与环面平行）为零、再增再减】；警惕【同心圆环误套『越近中间越大』来比较；漏掉磁铁正中间磁通量为零的临界位置】","src":"跳跳物一轮12.1 磁通量、电磁感应现象、楞次定律_笔记","note":"视频|11:53","orig":"（知识）条形磁铁周围的磁通量分布有内部磁感线与外部反向磁感线抵消的特点。","link":""},{"id":"phy2676","t":"电磁感应·感应电流的产生条件","s":"看到【判断各种情境（磁铁落向线圈、导线旁圆环、不闭合线圈）中能否产生感应电流】","c":"想到【必须同时满足：①回路闭合；②穿过回路的磁通量发生变化；磁通量恒为零也属于不变——直导线旁共面圆环两半圆磁通量等大反向完全抵消，无论电流怎么变化都无感应电流；线圈不闭合则磁通量再变也无感应电流】；警惕【见『磁场变化』就断定有感应电流；忽略对称抵消使磁通量恒为零的情形】","src":"跳跳物一轮12.1 磁通量、电磁感应现象、楞次定律_笔记","note":"视频|16:56","orig":"（知识）产生感应电流需要同时满足两个条件，缺一不可。","link":""},{"id":"phy2677","t":"电磁感应·楞次定律判断感应电流方向三步法","s":"看到【闭合回路磁通量变化（开关通断、电流变化），问感应电流方向或电流表示数】","c":"想到【三步法：①确定原磁场方向和磁通量增减；②按『增反减同』定感应磁场方向；③用安培定则定感应电流方向（叉场对顺时针电流、点场对逆时针电流）；阻碍$\\neq$停止，只能让变化变慢；电流稳定后磁通量不变，无感应电流、示数为零】；警惕【把『阻碍变化』理解为感应磁场总与原磁场反向（减小时应同向）；电路稳定后仍认为有感应电流】","src":"跳跳物一轮12.1 磁通量、电磁感应现象、楞次定律_笔记","note":"视频|19:40","orig":"（知识）楞次定律：感应电流的磁场总要阻碍引起感应电流的磁通量的变化。","link":""},{"id":"phy2678","t":"电磁感应·增斥减引与增缩减扩","s":"看到【磁体靠近或远离线圈、滑片移动使电流变化，问线圈受力、缩扩趋势或对桌面压力】","c":"想到【增斥减引：磁通量增大时线圈与磁体相斥、减小时相吸（优于『来拒去留』）；增缩减扩：磁通量增大线圈有收缩趋势、减小时有扩张趋势；磁体靠近线圈时线圈受向下斥力，对桌面压力=重力+斥力而增大；安培力始终阻碍磁体相对运动，机械能转化为内能，磁体振动最终停止】；警惕【磁通量增大时误判成吸引；判断磁体能否一直振动时漏用能量耗散（阻力）角度】","src":"跳跳物一轮12.1 磁通量、电磁感应现象、楞次定律_笔记","note":"视频|22:06-23:59","orig":"（知识）用楞次定律直接判断线圈与磁体间的作用力及线圈的缩扩趋势。","link":""},{"id":"phy2679","t":"电磁感应·增缩减扩的大圈套小圈例外","s":"看到【两个同心圆线圈，小圈通变化电流，问大圈的收缩或扩张趋势】","c":"想到【口诀反转为增扩减缩：小圈电流增大使大圈内磁通量增大时，大圈反而要扩张——大圈变大能包住更多小圈外部的反向磁感线，抵消后净磁通量反而减小，从而阻碍增大；大圈的净磁通量=内部磁感线-外部反向磁感线】；警惕【大圈套小圈情境仍套用『增缩减扩』导致趋势判断反向；忘记大圈磁通量是内外磁感线抵消后的净值】","src":"跳跳物一轮12.1 磁通量、电磁感应现象、楞次定律_笔记","note":"视频|23:59-49:20","orig":"（知识）大圈套小圈（同心双线圈、小圈电流变化）时，缩扩口诀发生反转。","link":""},{"id":"phy2680","t":"电磁感应·线框旋转与翻转180°的磁通量计算","s":"看到【线框从垂直磁场位置转过某角度或翻转 180°，求磁通量或其变化量】","c":"想到【旋转 $\\theta$ 时取投影面积（乘 $\\cos\\theta$）：转 60° 得 $\\Phi=\\frac{1}{2}BS$，转 90°（面与 $B$ 平行）得 0；翻转 180° 磁通量变 $-BS$，变化量大小为 $2BS$ 不为零；初末都与磁场成 45° 再转过 90° 时，垂直分量均为 $(\\sqrt{2}/2)B$ 但穿向相反，$|\\Delta\\Phi|=\\sqrt{2}BS$（科教版乘匝数为 $\\sqrt{2}NBS$）】；警惕【旋转时用 sin 还是 cos 不看夹角实际定义；翻转 180° 误判变化量为零或漏 2 倍；45° 初末态忘记穿向相反导致变化量漏加倍】","src":"跳跳物一轮12.1 磁通量、电磁感应现象、楞次定律_笔记","note":"视频|29:15-31:40","orig":"（例）线框面积 $S$ 初始与匀强磁场 $B$ 垂直（$\\Phi=BS$），讨论绕轴旋转 60°、90° 后的磁通量及翻转 180° 后的变化量；另有一匝数 $N$ 的线圈初始与磁场成 45°，绕轴转 90°，求磁通量变化量的大小。","link":""},{"id":"phy2681","t":"电磁感应·法拉第电磁感应定律","s":"看到【闭合回路磁通量变化，求感应电动势，或判断所求是平均值还是瞬时值】","c":"想到【$E=N\\frac{\\Delta\\Phi}{\\Delta t}$，只适用于闭合回路；$\\Delta t$ 不趋近于 0 时算出的是平均值，$\\Delta t\\to 0$ 时才是瞬时值；$N=1$ 时简化为 $E=\\frac{\\Delta\\Phi}{\\Delta t}$；电动势大小须为正，$\\Delta\\Phi$ 为负时取绝对值】；警惕【拿它算切割的瞬时电动势——瞬时值应改用 $E=BLv$；$\\Delta\\Phi$ 为负仍直接代入得出负的电动势】","src":"跳跳物一轮12.2 法拉第电磁感应定律、动生电动势_笔记","note":"视频|03:20","orig":"（知识）法拉第电磁感应定律：闭合电路中感应电动势的大小，跟穿过这一电路的磁通量变化率成正比。","link":""},{"id":"phy2682","t":"电磁感应·磁通量变化量ΔΦ的三种情形","s":"看到【磁感应强度与回路面积都可能变化，求磁通量变化量或感应电动势】","c":"想到【$B$ 变 $S$ 不变：$\\Delta\\Phi=\\Delta B\\cdot S$；$S$ 变 $B$ 不变：$\\Delta\\Phi=\\Delta S\\cdot B$；$B$、$S$ 都变：绝不能写 $\\Delta\\Phi=\\Delta B\\cdot\\Delta S$，必须分别算出末态和初态的磁通量再相减，$\\Delta\\Phi=B_1S_1-B_0S_0$】；警惕【$\\Delta B\\cdot\\Delta S$ 只是两个变化量直接相乘，没有物理意义；$B$、$S$ 都变时漏看其中一个量的变化】","src":"跳跳物一轮12.2 法拉第电磁感应定律、动生电动势_笔记","note":"视频|05:23","orig":"（知识）计算磁通量变化量$\\Delta\\Phi$分三种情形：$B$ 变 $S$ 不变、$S$ 变 $B$ 不变、$B$ 与 $S$ 都变。","link":""},{"id":"phy2683","t":"电磁感应·Φ-t图与B-t图求电动势","s":"看到【给出 $\\Phi$-$t$ 或 $B$-$t$ 图像，问某段时间内感应电动势大小或比较大小】","c":"想到【$\\Phi$-$t$ 图的斜率 $k=\\frac{\\Delta\\Phi}{\\Delta t}$，$E=N\\cdot k$；$B$-$t$ 图（回路面积 $S$ 不变）的斜率 $k=\\frac{\\Delta B}{\\Delta t}$，$E=N\\cdot S\\cdot k$；电动势只由斜率绝对值决定，斜率越大电动势越大，斜率为 0 则电动势为 0】；警惕【图线下降段斜率为负，代入时忘记取绝对值算出负电动势；$B$-$t$ 图直接套 $\\Phi$-$t$ 图的结论漏乘面积 $S$】","src":"跳跳物一轮12.2 法拉第电磁感应定律、动生电动势_笔记","note":"视频|07:32","orig":"（知识）由 $\\Phi$-$t$ 图或 $B$-$t$ 图像求感应电动势。","link":""},{"id":"phy2684","t":"电磁感应·感应电荷量公式","s":"看到【问磁通量变化过程中通过电阻或回路的电荷量，或比较不同过程转移电荷】","c":"想到【$q=\\frac{N\\Delta\\Phi}{R}$，其中 $R$ 为回路总电阻；由“电荷量=平均电流$\\times\\Delta t$”与法拉第定律联立推出，$\\Delta t$ 自动消去；$q$ 只与磁通量变化量和回路总电阻有关，与变化快慢、所用时间无关】；警惕【拿最大电动势或瞬时电流乘时间；$R$ 代成部分电阻而非总电阻；以为磁通量变得越快 $q$ 越大】","src":"跳跳物一轮12.2 法拉第电磁感应定律、动生电动势_笔记","note":"视频|09:36","orig":"（知识）电磁感应中通过回路某截面的电荷量计算。","link":""},{"id":"phy2685","t":"电磁感应·动生电动势与有效切割长度","s":"看到【导体棒平动切割求电动势或安培力，杆弯曲、与速度不垂直或超出导轨间距】","c":"想到【$E=BLv$ 要求 $B$、$L$、$v$ 两两垂直，$v$ 为瞬时速度，$B$、$v$ 取绝对值只算大小；有效长度：弯曲杆取磁场中部分首尾相连的线段（半圆杆为 $2R$）；杆与 $v$ 不垂直取垂直 $v$ 方向的投影；棒长超过导轨间距时电动势与安培力都用间距 $d$，$F=\\frac{B^2d^2v}{R}$】；警惕【被导轨方向或棒总长误导——只看杆与速度方向的关系；把弧长当有效长度】","src":"跳跳物一轮12.2 法拉第电磁感应定律、动生电动势_笔记","note":"视频|11:04","orig":"（知识）动生电动势 $E=BLv$ 及有效切割长度的确定。","link":""},{"id":"phy2686","t":"电磁感应·左手定则与右手定则的选用","s":"看到【需判断安培力、洛伦兹力、电流或磁场方向，不确定该伸哪只手】","c":"想到【与力有关用左手——安培力、洛伦兹力；与力无关用右手——安培定则（电流的磁场）、右手定则（电磁感应 $B$、$v$、$I$）；右手定则操作：磁场穿手心（叉场手心朝脸、点场手背朝脸），拇指指速度，四指指电流；无闭合回路时四指指向电源正极】；警惕【判安培力方向时误伸右手；$B$ 方向反转后电流方向即使不变，安培力方向也会随之改变】","src":"跳跳物一轮12.2 法拉第电磁感应定律、动生电动势_笔记","note":"视频|16:04","orig":"（知识）左手定则与右手定则（含安培定则）的分工及右手定则的操作。","link":""},{"id":"phy2687","t":"电磁感应·B与S同时变化时的无感应电流条件","s":"看到【棒匀速运动的同时磁场也随时间变化，要求回路中不产生感应电流】","c":"想到【无感应电流的充要条件是总磁通量保持不变：$\\Phi=B(2L+vt)L$ 恒等于初值 $2B_0L^2$，解得 $B=\\frac{2B_0L}{2L+vt}$；一般策略是抓住“磁通量不变”对任意时刻列 $B(t)$ 方程】；警惕【$B$、$S$ 都变时用 $\\Delta B\\cdot\\Delta S$ 或只盯一个量变化；把“无电流”误解为磁通量为零】","src":"跳跳物一轮12.2 法拉第电磁感应定律、动生电动势_笔记","note":"视频|29:12","orig":"（例）金属棒 MN 以速度 $v$ 向右匀速运动切割磁感线，$t=0$ 时磁感应强度为 $B_0$，回路为宽 $L$、长 $2L$ 的矩形。为使 MN 棒中不产生感应电流，求磁感应强度 $B$ 随时间 $t$ 的变化规律。","link":""},{"id":"phy2688","t":"电磁感应·弯曲线框进磁场的最大与平均电动势","s":"看到【弯曲形状（半圆等）导线框匀速进入有界磁场，问电动势最大值或平均值】","c":"想到【最大电动势用 $E=BLv$，$L$ 取回路在磁场中部分首尾相连直线段的最长值——半圆进入一半时为半径 $a$，$E_M=Bav$；平均电动势用法拉第定律 $\\bar{E}=\\Delta\\Phi/\\Delta t=B\\cdot(\\pi a^2/2)\\div(2a/v)=\\pi Bav/4$；进入过程中磁通量增大，感应电流沿逆时针；有电流且处于磁场中的导线段始终受安培力】；警惕【把弧长当有效切割长度；用最大电动势乘某个比例估平均值；认为直导线段不在切割就不受力】","src":"跳跳物一轮12.2 法拉第电磁感应定律、动生电动势_笔记","note":"视频|42:29","orig":"（例）半径为 $a$ 的半圆形导线框以速度 $v$ 匀速进入方向垂直纸面向里的磁场，判断感应电流方向、直径段直导线是否始终受安培力，并求感应电动势的最大值与平均值。","link":""},{"id":"phy2689","t":"电磁感应·旋转切割（端点旋转）电动势","s":"看到【导体棒绕端点在恒定磁场中旋转，求电动势大小或电源正负极】","c":"想到【端点旋转 $E=\\frac{1}{2}BL^2\\omega$（$L$ 为有效切割长度，由各点线速度 $v=\\omega r$ 从零线性增大平均而来），大题中可直接使用无需推导；正负极用右手定则：在棒上任取一点画出该点速度方向，四指指向即为电源正极一端】；警惕【$L$ 只算磁场中实际切割的有效长度——磁场仅存在于半径 $r$ 区域内时用 $r$ 而非棒总长；把端点速度当切割速度漏掉$\\frac{1}{2}$】","src":"跳跳物一轮12.3 旋转切割模型、电磁感应中的电路问题_笔记","note":"视频|02:02","orig":"（知识）导体棒绕一端点在匀强磁场中旋转切割的电动势与正负极判定。","link":""},{"id":"phy2690","t":"电磁感应·旋转点在棒端之外的旋转切割","s":"看到【旋转轴在棒外延长线上或棒内部，棒仍在磁场中旋转切割】","c":"想到【旋转点在延长线上：补一段导体棒到支点，化为两个端点旋转电源串联，$E=\\frac{1}{2}B(L_1^2-L_2^2)\\omega$；旋转点在棒内部：支点把棒分成两段，两电源负极相连属于反接，总电动势等于两段之差的绝对值 $E=\\frac{1}{2}B|L_1^2-L_2^2|\\omega$；两类的正负极都用右手定则逐段判断】；警惕【内部旋转时把两段电动势直接相加——反接应相减取差；补棒后不判断两电源串反接就硬套公式】","src":"跳跳物一轮12.3 旋转切割模型、电磁感应中的电路问题_笔记","note":"视频|02:43-05:12","orig":"（知识）旋转点（支点）在导体棒延长线上或棒内部时的电动势计算。","link":""},{"id":"phy2691","t":"电磁感应·圆盘旋转切割（法拉第圆盘发电机）","s":"看到【金属圆盘绕中心轴在磁场中旋转（法拉第圆盘发电机），求电动势或电流方向】","c":"想到【圆盘等效为无数根从圆心到边缘的导体棒（每根都是绕端点旋转）并联，$E=\\frac{1}{2}BR^2\\omega$；每根棒圆心端为负极、边缘端为正极，相同电源并联总电动势仍等于单个电源的电动势；外电路电流从边缘（正极）流出】；警惕【认为并联会改变总电动势——相同电源并联电动势不变；把圆盘当理想电源，忽略其内阻（两条半径通路并联，约为单路电阻一半）】","src":"跳跳物一轮12.3 旋转切割模型、电磁感应中的电路问题_笔记","note":"视频|07:03","orig":"（知识）导体圆盘在匀强磁场中绕中心轴旋转的电动势与极性。","link":""},{"id":"phy2692","t":"电磁感应·画等效电路图","s":"看到【电磁感应与电阻、电容器、电表构成电路，问电流、电压或电势】","c":"想到【三步：先用楞次定律定线圈或棒内感应电流方向（增反减同、叉顺点逆）；再由电流流出的一端定电源正极；最后把导体替换成电源符号画等效电路图，按闭合电路欧姆定律计算；结构简单可心算，复杂必画图辅助】；警惕【正负极与电流绕向对不上——感应电流在电源内部从负极流向正极；漏画电源内阻导致路端电压算错】","src":"跳跳物一轮12.3 旋转切割模型、电磁感应中的电路问题_笔记","note":"视频|10:28","orig":"（知识）电磁感应电路问题：把导体棒或线圈等效为电源的步骤。","link":""},{"id":"phy2693","t":"电磁感应·感应电路中的电势差计算","s":"看到【问导体棒（电源）两端或外电路某两端的电势差、某点电势高低或正负】","c":"想到【电势差必须在外电路中分析：设电流 $I$，则 $U_{AB}=\\pm IR$，大小等于外电路电阻分得的电压而非电动势，$I=\\frac{E}{R+r}$；电源未接外电路（开路）时两端电势差才等于电动势 $E$；电势比较时正负号参与大小比较，可设接地端或旋转点电势为 0】；警惕【把 $U_{AB}$ 的大小直接等于 $E$——接通外电路后 $U=E\\cdot\\frac{R}{R+r}$；忽略电势差正负号（负极侧电势低，$U_{AB}$ 可为负）】","src":"跳跳物一轮12.3 旋转切割模型、电磁感应中的电路问题_笔记","note":"视频|12:33","orig":"（知识）求电磁感应电路中两点电势差的注意事项。","link":""},{"id":"phy2694","t":"电磁感应·弯折导体旋转的电势比较","s":"看到【弯折导线绕端点在磁场中旋转，比较导线上各点电势高低】","c":"想到【弯折导体用首尾相连的等效直棒替代（直角边 $R$、$2R$ 的折线等效为长 $\\sqrt{5}R$ 的直棒）；设旋转点 $\\varphi_O=0$，各等效棒绕 $O$ 端点旋转、$O$ 端为正极、末端为负极，故 $\\varphi_a=-\\frac{1}{2}BR^2\\omega$，$\\varphi_b=\\varphi_c=-\\frac{1}{2}B(\\sqrt{5}R)^2\\omega=-\\frac{5}{2}BR^2\\omega$，得 $\\varphi_O>\\varphi_a>\\varphi_b=\\varphi_c$】；警惕【对弯折段仍分段累加电动势——必须整体首尾相连等效；比较电势时丢掉负号只比数值大小】","src":"跳跳物一轮12.3 旋转切割模型、电磁感应中的电路问题_笔记","note":"视频|14:29","orig":"（例）导体绕 $O$ 点在垂直纸面的匀强磁场中匀速旋转：$Oa$ 段为长 $R$ 的直棒，$Ob$、$Oc$ 为直角边是 $R$ 和 $2R$ 的弯折导体，比较 $O$、$a$、$b$、$c$ 四点电势高低。","link":""},{"id":"phy2695","t":"电磁感应·地磁场中旋转切割（吊扇模型）","s":"看到【北半球吊扇、风车等在水平面旋转，涉及地磁场求电势差或极性】","c":"想到【地磁场斜向下须正交分解，北半球竖直分量向下 $B_1=B\\cos\\theta$，叶片在水平面内切割的正是竖直分量；每片叶片等效为绕端点旋转，$E=\\frac{1}{2}B_1L^2\\omega$，代入 $\\omega=2\\pi n$（$n$ 为转速）得 $E=\\pi nBL^2\\cos\\theta$；未接外电路时两端电势差大小等于 $E$；极性画俯视图用右手定则判断】；警惕【拿地磁场总磁感应强度代入——必须只取竖直分量；南北半球竖直分量方向相反导致极性反转；转速与角速度混用】","src":"跳跳物一轮12.3 旋转切割模型、电磁感应中的电路问题_笔记","note":"视频|18:26","orig":"（例）北半球吊扇叶片长 $L$（一端在转轴处），绕中心在水平面内旋转，已知地磁场与竖直方向夹角 $\\theta$、转速 $n$（转/秒），求叶片两端电势差大小并判断哪端电势高。","link":""},{"id":"phy2696","t":"电磁感应·立体空间旋转切割的投影法","s":"看到【杆在三维空间旋转，杆本身与磁场成一定夹角（非垂直），求两端电势差】","c":"想到【将杆分别投影到平行于磁场和垂直于磁场的方向：平行于磁场的投影不切割磁感线、不产生电动势；只分析垂直于磁场的投影部分（投影长度 $L\\sin\\theta$），把立体问题化为平面旋转切割，再按旋转点位置分类型计算】；警惕【直接用杆的真实长度代入 $E=\\frac{1}{2}BL^2\\omega$；旋转点在投影图中的位置会改变——须按投影后的几何关系重新确定各段长度】","src":"跳跳物一轮12.3 旋转切割模型、电磁感应中的电路问题_笔记","note":"视频|22:17","orig":"（知识）金属杆在立体空间中旋转，杆与磁场方向不垂直时的处理方法。","link":""},{"id":"phy2697","t":"电磁感应·无源单棒的定义与安培力方向","s":"看到【导轨上无外接电源（或电容器）的单棒切割模型，判断安培力方向或能量去向】","c":"想到【无源=无外接电源和电容器（电容器放电时也相当于电源），由动生电动势充当电源；安培力必为阻力、做负功，把棒的动能转化为电势能（纯电阻电路中最终全部变焦耳热）；方向直接判：安培力必与速度反向（棒向右运动则安培力向左），无需先用右手定则判电流再用左手定则判力】；警惕【把电容器放电的单棒当成无源模型；绕两步伸手判安培力把方向弄反】","src":"跳跳物一轮12.4 无源单棒_笔记","note":"视频|00:19-01:36","orig":"（知识）无源单棒的定义、能量转化与安培力方向的快捷判断。","link":""},{"id":"phy2698","t":"电磁感应·求安培力的一键三连","s":"看到【单棒切割需要求安培力，或要列牛顿第二定律、平衡方程】","c":"想到【一键三连：$E=BLv$ → $I=\\frac{E}{R}$（$R$ 为回路总电阻，棒电阻不可忽略时须计入）→ $F=BIL$；推论：安培力 $F=\\frac{B^2L^2v}{R}$，选择题可直接使用，计算题必须写出三个原始方程才有过程分】；警惕【棒电阻不可忽略时 $R$ 漏加棒电阻；计算题直接写推论结果丢过程分】","src":"跳跳物一轮12.4 无源单棒_笔记","note":"视频|03:45","orig":"（知识）单棒切割中求安培力的固定三步与推论。","link":""},{"id":"phy2699","t":"电磁感应·无外力单棒的运动性质","s":"看到【光滑导轨上具有初速度的单棒，无其他外力，问运动性质或 $v$-$t$ 图像】","c":"想到【合力只有安培力：$\\frac{B^2L^2v}{R}=ma$（$R$ 为回路总电阻），$v$ 减小则 $a$ 减小，做加速度减小的减速运动，最终停下；$v$-$t$ 图是逐渐平缓、趋近 $t$ 轴的曲线；动能全部经安培力做负功转化为焦耳热】；警惕【当成匀减速直线运动套匀变速公式求位移时间；以为棒最终会匀速滑行】","src":"跳跳物一轮12.4 无源单棒_笔记","note":"视频|06:02","orig":"（知识）仅受安培力的无外力单棒（有初速度）的运动分析。","link":""},{"id":"phy2700","t":"电磁感应·恒力单棒的稳定速度","s":"看到【单棒受恒定外力（含斜面重力分量）且有或无初速度，问最大或稳定速度、$v$-$t$ 图】","c":"想到【稳定时加速度为零，外力与安培力平衡：$F=\\frac{B^2L^2v}{R}$（$R$ 为回路总电阻），解得稳定速度 $v=\\frac{FR}{B^2L^2}$；稳定速度与初速度无关，只由外力、$B$、$L$ 和总电阻决定；初速为零时先做 $a$ 减小的加速后匀速；初速不为零时按初始安培力与外力的大小分加速、匀速、减速三类过程，最终同归匀速】；警惕【以为初速度大稳定速度就大；把稳定状态（匀速）误判为速度为零】","src":"跳跳物一轮12.4 无源单棒_笔记","note":"视频|10:06-14:01","orig":"（知识）恒定外力下单棒的最终状态与稳定速度。","link":""},{"id":"phy2701","t":"电磁感应·无源单棒的焦耳热求解","s":"看到【问单棒运动过程中电阻上产生的热量或电能，已知位移或初末速度】","c":"想到【回路总焦耳热等于安培力做功的负值（大题可直接使用）：先对棒列动能定理求出安培力的功，再取负即得总焦耳热；串联电路中某电阻的焦耳热按阻值成正比分配：该电阻的热量$=$总热量$\\times$该电阻阻值$\\div$回路总电阻】；警惕【电流在变还直接用 $I^2Rt$ 求热量；分配时分子分母口径不一（是否含棒电阻）】","src":"跳跳物一轮12.4 无源单棒_笔记","note":"视频|15:01","orig":"（知识）无源单棒回路中总焦耳热与某电阻焦耳热的求法。","link":""},{"id":"phy2702","t":"电磁感应·无源单棒的电荷量两法","s":"看到【问通过电阻或棒的电荷量，条件中给位移或给时间、初末速度】","c":"想到【位移已知用法拉第定律：$q=\\frac{BLx}{R}$（$R$ 为回路总电阻，$B$ 恒定、$\\Delta\\Phi=BLx$）；位移未知用动量定理：安培力冲量的大小$=qBL$，对棒列动量定理求出安培力冲量后除以 $BL$ 即得电荷量】；警惕【对电流变化的阶段乱用 $q=It$；已知位移却绕道动量定理徒增计算】","src":"跳跳物一轮12.4 无源单棒_笔记","note":"视频|20:05","orig":"（知识）单棒问题中电荷量的两种求法及其选择。","link":""},{"id":"phy2703","t":"电磁感应·两阶段位移相等的电荷量隐含条件","s":"看到【先加速后减速的两阶段过程，给出两阶段位移相等，求电荷量或相关量】","c":"想到【由 $q=\\frac{BLx}{R}$ 知两阶段位移相等则电荷量相等；对拉力未知的加速阶段改算减速阶段：对减速阶段列动量定理 $0-mv=-qBL$，得 $q=\\frac{mv}{BL}$，即两阶段电荷量均为 $\\frac{mv}{BL}$；再由 $q=\\frac{BLx}{R}$ 反解位移 $x=\\frac{mvR}{B^2L^2}$，配合匀加速平均速度可继续求时间、加速度】；警惕【对加速阶段直接列动量定理（外力冲量未知）卡死；两阶段位移相等却分开重复计算】","src":"跳跳物一轮12.4 无源单棒_笔记","note":"视频|34:21","orig":"（例）金属棒从静止被拉动做匀加速直线运动（拉力可变），达到最大速度 $v$ 后撤去拉力，减速至停止；已知加速阶段与减速阶段位移相等，不计摩擦及电阻，求加速阶段通过棒的电荷量。","link":""},{"id":"phy2704","t":"电磁感应·恒功率启动单棒（类机车启动）","s":"看到【拉力功率恒定（非恒力）的单棒在斜面上运动，求功率或位移】","c":"想到【匀速阶段沿导轨列平衡：拉力$=mg\\sin\\theta+$安培力，其中安培力$=\\frac{B^2L^2v}{R}$（$R$ 为回路总电阻，$v$ 取稳定速度），功率 $P=$拉力$\\times$稳定速度；加速阶段列动能定理：拉力做功（$P\\cdot t$）+安培力做功（取负）+重力做功（$-mgx\\sin\\theta$）$=$末动能$-$初动能，解出位移 $x$】；警惕【把恒功率当恒力（恒功率下拉力随速度增大而减小）；倾角导轨漏掉重力做功；安培力做功与克服安培力做功符号弄反】","src":"跳跳物一轮12.4 无源单棒_笔记","note":"视频|45:12","orig":"（例）倾角 $30^\\circ$ 的光滑导轨上，质量 $0.2\\ \\mathrm{kg}$ 的导体棒（有内阻）受沿导轨向上的恒定功率拉力作用，从 $0.5\\ \\mathrm{m/s}$ 经 $0.09\\ \\mathrm{s}$ 加速到 $1.5\\ \\mathrm{m/s}$（此过程克服安培力做功 $0.06\\ \\mathrm{J}$），稳定时速度为 $2\\ \\mathrm{m/s}$，求拉力功率与这段时间内的位移。","link":""},{"id":"phy2705","t":"电磁感应·单棒模型的两大分类（电动机与发电机）","s":"看到【单棒导轨问题，需判断安培力是动力还是阻力、棒是电源还是用电器】","c":"想到【电路中有外接电源或电容器放电、棒初速度为零，是电动机模型：安培力为动力做正功，棒相当于用电器，把电源电势能转化为棒的动能；无外接电源、棒以初速度切割磁感线（含给电容器充电），是发电机模型：安培力为阻力做负功，棒是电源】；警惕【两类模型终态不同：电动机模型最终匀速，无外力发电机模型一直减速到停止】","src":"跳跳物一轮12.5 含电源、电容器的单棒_笔记","note":"视频|00:33","orig":"（知识）所有单棒导轨模型本质上只有电动机模型和发电机模型两类。","link":""},{"id":"phy2706","t":"电磁感应·反电动势与总电动势","s":"看到【含电源单棒加速过程中电流为何减小，或求回路总电动势、瞬时电流】","c":"想到【反电动势大小为 $BLv$，随速度增大而增大；总电动势=电源电动势−反电动势（电容器放电单棒的电源电动势为 $Q/C$，随放电不断减小）；速度增大→总电动势减小→电流不断减小】；警惕【求电流时直接用电源电动势除以总电阻而漏掉反电动势；速度不为零时反电动势不可忽略】","src":"跳跳物一轮12.5 含电源、电容器的单棒_笔记","note":"视频|02:40","orig":"（知识）电动机模型中，导体棒运动后切割磁感线产生的、方向与原电流相反的感应电动势叫反电动势。","link":""},{"id":"phy2707","t":"电磁感应·含电源与放电单棒的稳定条件","s":"看到【含电源或电容器放电的单棒，求最大速度、稳定状态或稳定电荷量】","c":"想到【稳定条件为电源电动势=反电动势：含电源单棒 $E=BLv_M$，放电单棒 $Q_M/C=BLv_M$（$Q_M$ 为稳定时电容器电荷量）；匀速后回路无电流、安培力为零】；警惕【放电单棒的电源电动势 $Q/C$ 随放电衰减，不能视为恒量；稳定时电容器仍带电荷，电荷量不为零】","src":"跳跳物一轮12.5 含电源、电容器的单棒_笔记","note":"视频|08:53","orig":"（知识）含电源单棒与电容器放电单棒同属电动机模型，运动都是先加速度减小的加速后匀速。","link":""},{"id":"phy2708","t":"电磁感应·电容器充电单棒（发电机模型）","s":"看到【棒有初速度、回路接电容器，问最终速度、电流变化或最大电荷量】","c":"想到【棒做加速度减小的减速，当电容器电压增大到等于 $BLv$ 时电流为零，棒匀速运动；初始时刻电容器不带电相当于导线，初始电流 $I_0=BLv_0/R$（$R$ 为回路总电阻）；稳定速度 $v=mv_0/(m+CB^2L^2)$，最大电荷量即稳定时电荷量】；警惕【误认为棒会减速到零停止（回路接电阻才停，接电容器是匀速）；充电电流随电容器越来越难充而不断减小】","src":"跳跳物一轮12.5 含电源、电容器的单棒_笔记","note":"视频|09:50-14:44","orig":"（知识）导体棒带初速度给电容器充电的单棒是发电机模型，安培力为阻力，最终匀速而不会停止。","link":""},{"id":"phy2709","t":"电磁感应·电荷量三步法（动量定理）","s":"看到【单棒问题求通过回路的电荷量，或已知电荷量反过来求稳定速度】","c":"想到【三步法：①稳定方程 $E=BLv_M$ 或 $Q_M/C=BLv_M$；②对棒列动量定理，安培力冲量大小为 $qBL$，若安培力为合力则等于动量变化量；③电荷量关系：放电单棒 $Q_0-Q_M=q$，充电单棒 $q=Q_M$】；警惕【安培力冲量必须用平均电流计算，其大小恒为 $qBL$；放电与充电的电荷量关系式互为反向，不能套错】","src":"跳跳物一轮12.5 含电源、电容器的单棒_笔记","note":"视频|16:49","orig":"（知识）求单棒从开始到稳定（或停止）通过回路的电荷量，用「三步法」联立求解。","link":""},{"id":"phy2710","t":"电磁感应·电荷量与位移关系","s":"看到【单棒减速滑行（无外力），求滑行位移或通过的电荷量、平均电流】","c":"想到【$q=BLx/R$（$R$ 为回路总电阻）：由法拉第定律与电流定义联立导出（其中 $\\Delta\\Phi=BLx$），大题中要先推导再使用；再配合动量定理 $qBL=mv_0$ 可求滑行位移】；警惕【该式只对磁感应强度不变、磁通量变化仅由棒平移引起的情况成立；若 $B$ 也随时间变化，应改用 $q=\\Delta\\Phi/R$ 通式计算】","src":"跳跳物一轮12.5 含电源、电容器的单棒_笔记","note":"视频|18:53","orig":"（知识）单棒在匀强磁场中平移切割时，通过回路的电荷量与棒的位移成正比。","link":""},{"id":"phy2711","t":"电磁感应·无电阻充电单棒的匀加速结论","s":"看到【棒与电容器构成回路、棒电阻不计且受恒力（如重力分力），问运动性质或电流大小】","c":"想到【因棒无内阻，电容器电压 $U_C=BLv$，电流 $I=C\\cdot\\Delta U_C/\\Delta t=CBLa$ 恒定；牛二 $F-CB^2L^2a=ma$，解得 $a=F/(m+CB^2L^2)$ 为常数（恒力为重力分力时 $F=mg\\sin\\theta$）】；警惕【该结论仅当回路无电阻时成立；回路有电阻时电流随速度变化，棒做加速度减小的变加速运动】","src":"跳跳物一轮12.5 含电源、电容器的单棒_笔记","note":"视频|48:36","orig":"（知识）导体棒电阻不计、回路只与电容器相连且棒受恒力时，棒做匀加速直线运动，电流恒定。","link":""},{"id":"phy2712","t":"电磁感应·旋转切割作电源的单棒综合","s":"看到【一杆旋转切割当电源、另一杆在导轨上被驱动，问最大速度或停止后的生热分配】","c":"想到【旋转切割电动势用杆的平均速度 $\\frac{1}{2}\\omega L$ 计算：$E=\\frac{1}{2}BL^2\\omega$；MN匀速时其反电动势等于电源电动势，$\\frac{1}{2}BL^2\\omega=BLv_M$，得 $v_M=\\omega L/2$；OP停转后转为无外力单棒，MN动能全部转化为回路总焦耳热 $\\frac{1}{2}mv_M^2$，各电阻按阻值比例分配热量】；警惕【旋转切割电动势勿写成 $BL^2\\omega$（速度沿杆线性增大必须取平均）；动能全部生热仅在无其他外力做功时成立】","src":"跳跳物一轮12.5 含电源、电容器的单棒_笔记","note":"视频|24:58","orig":"（例）金属杆OP绕其一端以角速度$\\omega$匀速转动切割磁感线充当电源（杆长L、两杆电阻均为R），驱动导轨上的金属杆MN加速；求MN的匀速速度，以及OP停转后MN减速到停止过程中MN产生的焦耳热。","link":""},{"id":"phy2713","t":"电磁感应·线框穿越磁场的运动阶段","s":"看到【线框进入、离开或完全处于磁场中，问各阶段的电动势、电流、安培力】","c":"想到【进出磁场时只有一条边切割磁感线，等效于单棒模型分析；完全在磁场中时磁通量不变，电动势、电流、安培力均为零，线框只受其他力（光滑水平面则匀速）】；警惕【完全在磁场中仍按切割算电动势；进出阶段误认为两条边同时切割】","src":"跳跳物一轮12.6 线框模型_笔记","note":"视频|00:20","orig":"（知识）线框穿过磁场分两阶段：进出磁场阶段与完全在磁场中阶段。","link":""},{"id":"phy2714","t":"电磁感应·线框进出磁场的运动模式","s":"看到【线框穿过磁场给 v-t 图或问运动性质、最终状态】","c":"想到【无外力线框：加速度减小的减速，最终停止；初速度为零的恒力线框：先加速度减小的加速后匀速；初速度不为零的恒力线框比较初速度与稳定速度：小则加速后匀速、等则一直匀速、大则减速后匀速】；警惕【v-t 图是曲线不是直线（安培力随速度变化）；线框不够长时只取完整图线的一部分，可能达不到匀速或未停就已离开磁场】","src":"跳跳物一轮12.6 线框模型_笔记","note":"视频|01:53-04:00","orig":"（知识）线框进出磁场的运动模式与对应单棒模型相同，按有无外力和初速度分类。","link":""},{"id":"phy2715","t":"电磁感应·线框所受安培力","s":"看到【线框进出磁场，问安培力的大小、方向或受力来源】","c":"想到【其他边的安培力等大反向相互抵消，合力即切割边的安培力，大小为 $BIL$（$L$ 取切割边长度）；线框属发电机模型，安培力是阻力，进入和离开磁场时方向都与速度方向相反】；警惕【$L$ 误用线框周长或另一边长度；认为出磁场时安培力方向反转与速度同向】","src":"跳跳物一轮12.6 线框模型_笔记","note":"视频|05:17","orig":"（知识）线框进出磁场时，所受安培力的合力等于切割磁感线那条边受到的安培力。","link":""},{"id":"phy2716","t":"电磁感应·线框进出磁场的电荷量与安培力冲量","s":"看到【线框进出磁场求通过横截面的电荷量，或用动量定理涉及安培力冲量】","c":"想到【进、出磁场的磁通量变化量大小均为 $BS$，通过的电荷量相同，均为 $q=BS/R$（$R$ 为回路总电阻）；安培力冲量大小也相同，均为 $qBL$，连续穿越多个条形磁场时按进出总次数累加（穿 6 个磁场共 $12qBL$）；从尚未进入到完全离开的全程电荷量为零，因进出电流方向相反】；警惕【全程电荷量把两次直接相加（应抵消为零）；$\\Delta S$ 是有效面积变化量，大小为线框面积】","src":"跳跳物一轮12.6 线框模型_笔记","note":"视频|06:45","orig":"（知识）线框进、出磁场两个过程，通过的电荷量和安培力冲量的大小都相同。","link":""},{"id":"phy2717","t":"电磁感应·n匝线框的四大公式","s":"看到【多匝线圈（n 匝）穿过磁场，求电动势、电阻、安培力或电荷量】","c":"想到【各匝串联：总电动势 $E=nBLv$；总电阻 $R=nR_0$（$R_0$ 为单匝电阻）；安培力 $F=nIBL$（每匝切割边受力同向叠加）；电荷量 $q=nBS/R$（$R$ 为总电阻）】；警惕【求电动势或安培力漏乘匝数 $n$；总电阻同样要乘 $n$，不能沿用单匝电阻】","src":"跳跳物一轮12.6 线框模型_笔记","note":"视频|10:10","orig":"（知识）n 匝线框各匝串联，电动势、电阻、安培力都要乘以匝数。","link":""},{"id":"phy2718","t":"电磁感应·线框进出磁场的焦耳热","s":"看到【线框进出磁场求焦耳热，或比较进入与离开过程生热的多少】","c":"想到【焦耳热=克服安培力所做的功（安培力做负功）；进出磁场过程的位移大小都等于线框自身的长度；若进出过程除安培力外其他力相同，则初速度越大→平均速度越大→平均安培力越大→焦耳热越多】；警惕【无外力线框出磁场的初速度小于进磁场，出磁场生热更少，不能默认进出生热相等】","src":"跳跳物一轮12.6 线框模型_笔记","note":"视频|12:50","orig":"（知识）线框进出磁场产生的焦耳热等于克服安培力所做的功。","link":""},{"id":"phy2719","t":"电磁感应·线框模型中电压（电势差）的求法","s":"看到【线框一边在磁场中切割，求某两边之间的电压或电势差】","c":"想到【切割边为电源，电动势 $E=BLv$；其余边构成外电路，所求电压=电流×所考察路径的外电路电阻（$U=IR$）；各边电阻按边长比例分配总电阻；电源两端电压是路端电压，小于电动势】；警惕【直接把电动势当成所求电压；忽略电阻按边长均匀分配（如周长 $6L$、总电阻 $R$，则长 $L$ 的边电阻为 $R/6$）】","src":"跳跳物一轮12.6 线框模型_笔记","note":"视频|28:59","orig":"（知识）线框部分在磁场中时，只有切割边是电源，求另两点间电压必须从外电路分析。","link":""},{"id":"phy2720","t":"电磁感应·磁场运动时的相对速度与安培力方向","s":"看到【磁场本身在平移（如磁悬浮列车模型），导体也运动，判电流或安培力方向】","c":"想到【右手定则中大拇指指向导体相对磁场的速度（同向运动速度相减）；两侧切割边相当于两个电源，若感应电流同向则顺向串联、电动势相加；安培力阻碍的是相对运动——磁场静止时安培力是阻力，磁场运动时安培力可能成为动力（拖动导体跟着磁场动）】；警惕【用导体对地速度直接套右手定则；不加分析一律把安培力当阻力】","src":"跳跳物一轮12.6 线框模型_笔记","note":"视频|34:10","orig":"（知识）磁场运动而导体也运动时，感应电流和安培力方向的判断都必须用相对速度。","link":""},{"id":"phy2721","t":"电磁感应·无外力等距双棒的角色分工","s":"看到【双棒模型一根棒有初速度另一根静止，问各棒安培力性质或能量转化】","c":"想到【有初速度的棒充当电源，属发电机模型：安培力是阻力、做负功，把动能转化为电势能并减速；无初速度的棒充当用电器，属电动机模型：安培力是动力、做正功，把电势能转化为动能并加速】；警惕【认为两棒都是电源（同向运动时总电动势应为两棒电动势之差）；认为静止棒受的安培力也是阻力】","src":"跳跳物一轮12.7 无外力等距双棒_笔记","note":"视频|00:48","orig":"（知识）无外力等距双棒中，有初速度的棒与静止的棒分别充当电源和用电器。","link":""},{"id":"phy2722","t":"电磁感应·双棒回路的总电动势与安培力","s":"看到【双棒同向运动，求回路电动势、电流或安培力的大小】","c":"想到【快棒电动势 $BLv_2$，慢棒产生反电动势 $BLv_1$，总电动势$=BL(v_2-v_1)$；电流 $I=BL(v_2-v_1)/R$（$R$ 为两棒电阻之和）；每棒安培力 $F=B^2L^2(v_2-v_1)/R$，两棒安培力大小相等、方向相反，都与速度差成正比】；警惕【两棒电动势直接相加（同向运动应相减，反向运动才相加）；安培力随速度差减小而减小，不是恒力】","src":"跳跳物一轮12.7 无外力等距双棒_笔记","note":"视频|02:26","orig":"（知识）双棒同向运动时，回路总电动势等于两棒电动势之差。","link":""},{"id":"phy2723","t":"电磁感应·双棒的运动模式与共速终态","s":"看到【双棒模型给 v-t 图或问各自运动性质、最终状态】","c":"想到【电源棒做加速度减小的减速，用电器棒做加速度减小的加速，v-t 图上两条曲线逐渐靠拢；当两棒速度相等（速度差为零）时达到共速，此后总电动势、电流、安培力均为零，两棒一起做匀速直线运动】；警惕【误认为系统最终停下（无外力系统动量守恒，共速后保持匀速）；v-t 图两线在共速时刻才合为一条水平线】","src":"跳跳物一轮12.7 无外力等距双棒_笔记","note":"视频|05:28-07:14","orig":"（知识）无外力等距双棒从开始到共速，两棒分别做加速度减小的减速与加速运动。","link":""},{"id":"phy2724","t":"电磁感应·双棒间距变化规律","s":"看到【双棒同向运动，问两棒间距增大还是减小、会不会相碰】","c":"想到【快棒在前（速度大者位于运动方向前方）→间距越来越大；快棒在后→间距越来越小（需检验是否碰撞）；共速后两棒速度时刻相等，间距不再变化】；警惕【只比较速度大小不判断前后位置关系；快棒在后时忽略间距缩小可能相碰的临界问题】","src":"跳跳物一轮12.7 无外力等距双棒_笔记","note":"视频|09:08","orig":"（知识）共速前快棒始终比慢棒快，两棒间距如何变化取决于快棒在前还是在后。","link":""},{"id":"phy2725","t":"电磁感应·双棒共速速度（动量守恒）","s":"看到【无外力双棒求共速速度，或已知共速速度反求质量比】","c":"想到【从开始到共速列动量守恒：$m_2v_0=(m_1+m_2)v_c$（$m_2$ 为初速棒质量、$v_c$ 为共速速度）；两棒质量相等时 $v_c=v_0/2$；两棒都有初速度（含反向）时同样守恒，各动量沿正方向带符号代入】；警惕【动量守恒只对双棒系统整体成立，单根棒受安培力动量不守恒；反向初速度忘记带负号】","src":"跳跳物一轮12.7 无外力等距双棒_笔记","note":"视频|11:21","orig":"（知识）两棒所受安培力等大反向、属系统内力，无外力双棒系统动量守恒。","link":""},{"id":"phy2726","t":"电磁感应·双棒电荷量的两种求法","s":"看到【双棒模型求通过回路的电荷量或两棒间距的变化量】","c":"想到【法一（法拉第定律）：$q=BL\\Delta x/R$（$\\Delta x$ 为两棒间距的变化量，间距缩小时取绝对值；对比单棒的 $q=BLx/R$ 中 $x$ 是单棒位移）；法二（动量定理）：对初速度为零的棒列式，安培力冲量 $qBL=$该棒动量变化量，因初动量为零最简便；两式联立可反求间距变化量】；警惕【把 $\\Delta x$ 当成某根棒自己的位移；间距缩小时忘取绝对值使电荷量为负】","src":"跳跳物一轮12.7 无外力等距双棒_笔记","note":"视频|12:36-15:37","orig":"（知识）求双棒从开始到共速通过回路的电荷量，有法拉第定律和动量定理两条路。","link":""},{"id":"phy2727","t":"电磁感应·双棒焦耳热与折合质量法","s":"看到【双棒求从开始到共速产生的总焦耳热，尤其选择题要快速得数】","c":"想到【能量守恒：系统初动能=共速时总动能+焦耳热，即 $\\frac{1}{2}m_2v_0^2=\\frac{1}{2}(m_1+m_2)v^2+Q$（$v$ 为共速速度）；该过程动量守恒、最终共速、动能有损失，可等效为完全非弹性碰撞；折合质量法：$Q=\\frac{1}{2}\\mu v_r^2$，$\\mu=m_1m_2/(m_1+m_2)$（上乘下加），$v_r$ 为初态相对速度（反向运动取两速度之和）】；警惕【$v_r$ 误用某棒对地速度；大题要写动量守恒和能量守恒原始方程拿过程分，折合质量法用于草稿或选择题】","src":"跳跳物一轮12.7 无外力等距双棒_笔记","note":"视频|17:06-20:02","orig":"（知识）无外力双棒从开始到共速的过程可等效为完全非弹性碰撞，损失的能量即焦耳热。","link":""},{"id":"phy2728","t":"电磁感应·两棒反向运动的双棒问题","s":"看到【双棒初速度方向相反，求总电动势、某时刻另一棒速度或总生热】","c":"想到【两棒反向运动时电动势同向相加：总电动势$=BL(v_a+v_b)$，本题 $v_0$ 与 $2v_0$ 反向得 $3BLv_0$；质量相等时两棒加速度大小相等；a 棒减速到零后反向加速直至共速，「a 棒速度为 $v_0/2$」在反向减速与同向加速两个阶段各出现一次，用动量守恒分情况得两个解；总热量用折合质量法，相对速度取 $3v_0$】；警惕【反向运动仍按电动势相减处理；只按一个阶段列式漏掉第二个解】","src":"跳跳物一轮12.7 无外力等距双棒_笔记","note":"视频|27:31","orig":"（例）光滑导轨上质量均为 m 的 a、b 两棒分别以向左 v$_0$ 和向右 2v$_0$ 的初速度同时进入垂直导轨平面的磁场，求初始回路总电动势、a 棒速度大小为 v$_0$/2 时 b 棒的速度、系统产生的总热量。","link":""},{"id":"phy2729","t":"电磁感应·双棒模型的角色与能量转化","s":"看到【双棒模型中判断哪根棒是电源/用电器，或问安培力做功正负、能量如何转化】","c":"想到【受外力（或有初速度）的棒是电源：安培力做负功、是阻力，把动能转化为电势能；另一棒是用电器：安培力做正功、是动力，把电势能转化为动能。恒力双棒与无外力双棒的角色完全相同，区别只在电源棒的动力来源（外力 $F$ 或初速度）】；警惕【不要把两棒的安培力都当成阻力；角色由谁带动谁决定，与有无外力无关】","src":"跳跳物一轮12.8 恒力等距双棒、不等距双棒_笔记","note":"视频|06:32","orig":"（知识）双棒模型中两棒分别充当电源与用电器，分析安培力的作用性质与能量转化方向。","link":""},{"id":"phy2730","t":"电磁感应·恒力等距双棒的运动过程与稳定状态","s":"看到【等距双导轨一棒受恒力F、两棒由静止起动，问两棒v、a如何变化及最终运动】","c":"想到【总电动势 $E=BL(v_2-v_1)$，电流 $I=BL(v_2-v_1)/R$，安培力 $F=B^2L^2(v_2-v_1)/R$（$R$ 为回路总电阻，$v_2$ 为电源棒速度），三者只由速度差决定。开始阶段电源棒加速度大、速度差增大：电源棒做 $a$ 减小的加速，用电器棒做 $a$ 增大的加速；两棒加速度相等后进入稳定：以相同加速度做匀加速，速度差恒定且不为零，电流与安培力恒定且不为零】；警惕【恒力双棒最终不会匀速而是匀加速；稳定时速度差不为零，两棒并非相对静止】","src":"跳跳物一轮12.8 恒力等距双棒、不等距双棒_笔记","note":"视频|08:36-10:26","orig":"（知识）等距导轨上两棒由静止出发，其中一棒受恒定外力F，分析两棒运动全过程与最终稳定状态。","link":""},{"id":"phy2731","t":"电磁感应·恒力等距双棒求稳定电流与加速度","s":"看到【恒力等距双棒已稳定（两棒加速度相同），要求稳定的电流或加速度】","c":"想到【对两棒分别列牛顿第二定律再联立：电源棒 $F-ILB=m_2a$，用电器棒 $ILB=m_1a$。两式相加消去电流得共同加速度 $a=F/(m_1+m_2)$，再回代求电流 $I$】；警惕【该模型不考稳定速度、总电荷量、总焦耳热——稳定后它们仍随时间无限增大，无法求解】","src":"跳跳物一轮12.8 恒力等距双棒、不等距双棒_笔记","note":"视频|12:48","orig":"（知识）恒力等距双棒达到稳定状态后，求稳定的电流I和加速度a的标准方法。","link":""},{"id":"phy2732","t":"电磁感应·恒力与无外力等距双棒对比","s":"看到【比较恒力双棒与无外力双棒：动量是否守恒、开始阶段与稳定状态的差异】","c":"想到【相同点：双棒角色相同，总电动势、电流、安培力表达式完全一致。不同点：动量方面无外力模型守恒、恒力模型不守恒；开始阶段无外力模型速度差减小、三量减小，恒力模型速度差增大、三量增大；稳定时无外力模型两棒同速匀速、电流为零，恒力模型匀加速、电流恒定不为零】；警惕【别因有无外力而改写电动势、电流公式；恒力模型动量不守恒，禁止用动量守恒列式】","src":"跳跳物一轮12.8 恒力等距双棒、不等距双棒_笔记","note":"视频|14:55","orig":"（知识）恒力等距双棒与无外力等距双棒在动量守恒、开始阶段和稳定状态上的异同对比。","link":""},{"id":"phy2733","t":"电磁感应·不等距双棒的总电动势与稳定条件","s":"看到【导轨间距不同或两处B不同的双棒，问总电动势、稳定速度关系或动量是否守恒】","c":"想到【总电动势 $E=B_2L_2v_2-B_1L_1v_1$，各棒用各自的 $B$ 和 $L$。无外力模型稳定条件为 $B_2L_2v_2=B_1L_1v_1$，此时两棒速度未必相等；系统动量仅当 $B_1L_1=B_2L_2$ 时才守恒】；警惕【不能照搬等距结论 $v_2=v_1$；用动量守恒前必须先检验 $B_1L_1$ 是否等于 $B_2L_2$】","src":"跳跳物一轮12.8 恒力等距双棒、不等距双棒_笔记","note":"视频|17:14","orig":"（知识）导轨间距不等（或两处磁感应强度不同）的双棒模型，总电动势表达式、稳定条件与动量守恒条件。","link":""},{"id":"phy2734","t":"电磁感应·无外力不等距双棒的求解套路","s":"看到【不等距双棒一棒有初速度另一棒静止，求稳定速度、电荷量或焦耳热】","c":"想到【对两棒分别列动量定理，把安培力冲量写成电荷量×该棒自身的 $B\\cdot L$ 以消去未知时间，再联立稳定条件 $B_2L_2v_2=B_1L_1v_1$ 解出两棒稳定速度；焦耳热先由能量守恒求总量，再按电阻比例分配给各棒；电荷量用无初速度棒的动量定理直接求】；警惕【电源棒克服安培力做的功不等于回路焦耳热（还有部分转化为对方棒的动能）；不等距模型禁止用动量守恒或完全非弹性碰撞处理】","src":"跳跳物一轮12.8 恒力等距双棒、不等距双棒_笔记","note":"视频|17:14","orig":"（知识）无外力不等距双棒（一棒有初速度、一棒静止）求稳定速度、电荷量、焦耳热的通用方法。","link":""},{"id":"phy2735","t":"电磁感应·恒力不等距双棒的稳定条件","s":"看到【不等距双棒一棒受恒力F，问电流恒定（稳定）时两棒加速度关系或电流大小】","c":"想到【稳定条件是总电动势保持不变（变化率为零），即 $B_2L_2a_2=B_1L_1a_1$，两棒加速度未必相同但各自恒定，做加速度不同的匀加速运动。求电流和加速度：对两棒分别列牛顿第二定律，再联立该加速度条件方程求解】；警惕【稳定时电动势不为零而是保持不变；两棒加速度一般不同，不能直接设为相同】","src":"跳跳物一轮12.8 恒力等距双棒、不等距双棒_笔记","note":"视频|22:31","orig":"（知识）不等距双棒中一棒受恒定外力F，稳定状态的判定条件与求电流、加速度的方法。","link":""},{"id":"phy2736","t":"电磁感应·恒力等距双棒撤去外力的瞬间与之后","s":"看到【双棒已达稳定后突然撤去外力，问撤力瞬间各棒加速度或之后的运动与间距变化】","c":"想到【撤力瞬间速度不能突变，电动势、电流不变，用电器棒加速度不变，电源棒合力由 $F-ILB$ 突变为 $-ILB$，加速度与用电器棒大小相等、方向相反；之后系统退化为无外力等距双棒：原电源棒减速、原用电器棒加速，最终同速匀速，全程原电源棒速度不小于对方】；警惕【速度差恒定不等于间距恒定，只要两棒速度不同间距就一直变化；撤力瞬间电流不变而不是突变为零】","src":"跳跳物一轮12.8 恒力等距双棒、不等距双棒_笔记","note":"视频|27:18","orig":"（例）光滑等距导轨上ab、cd两棒均静止，cd棒受恒力F，当两棒以相同加速度沿导轨滑动时撤去F，判断撤力瞬间及之后两棒加速度、间距与速度关系。","link":""},{"id":"phy2737","t":"电磁感应·Φ-t图与B-t图求电动势","s":"看到【给出Φ-t图或B-t图，问感应电动势大小或选对应的E-t图像】","c":"想到【Φ-t图中电动势 $E=N\\cdot k$（$N$ 为匝数，$k$ 为图线斜率）；B-t图中若线圈面积 $S$ 不变，则 $E=N\\cdot S\\cdot k$。逐段取斜率比较电动势大小，再用楞次定律（增反减同）和安培定则定电动势正负】；警惕【斜率 $k$ 为负时，求电动势大小要取绝对值；图线水平段斜率为零，电动势为零】","src":"跳跳物一轮12.9 电磁感应中的图像问题_笔记","note":"视频|00:29","orig":"（知识）由Φ-t图或B-t图读取感应电动势的方法。","link":""},{"id":"phy2738","t":"电磁感应·单棒模型的v-t图特征","s":"看到【单棒切割磁感线运动，问或选v-t图像的形状】","c":"想到【无外力单棒：安培力是唯一作用力（阻力），做加速度减小的减速运动，v-t图为向下弯曲的曲线。恒力单棒看初速度与稳定速度（安培力与外力平衡时的速度）的关系：初速度小，先做加速度减小的加速后匀速；相等，一直匀速；初速度大，先做加速度减小的减速后匀速】；警惕【匀速段对应安培力与外力平衡而非电流为零；无外力单棒不会匀速而是一直减速】","src":"跳跳物一轮12.9 电磁感应中的图像问题_笔记","note":"视频|01:01","orig":"（知识）无外力单棒与恒力单棒的v-t图形状规律。","link":""},{"id":"phy2739","t":"电磁感应·无外力单棒的v-x图与电荷量","s":"看到【无外力单棒减速滑行，问v-x图像形状或v、电荷量与位移的关系】","c":"想到【对棒列动量定理，把安培力冲量改写为 $B^2L^2x/R$（$R$ 为回路总电阻）以消去时间，整理得 $v=v_0-\\frac{B^2L^2}{mR}x$：$v$ 是 $x$ 的一次函数，图线为斜率为负、纵截距为 $v_0$ 的向下直线；通过回路的电荷量 $q=BLx/R$，与位移 $x$ 成正比】；警惕【冲量改写 $B^2L^2x/R$ 仅适用于单棒模型，双棒不能用；v-x图是直线不是曲线】","src":"跳跳物一轮12.9 电磁感应中的图像问题_笔记","note":"视频|01:47","orig":"（知识）无外力单棒沿导轨滑行时v-x图像的推导结论与电荷量比例关系。","link":""},{"id":"phy2740","t":"电磁感应·I与F安图像的同形替换法","s":"看到【单棒模型给出I-t、I-x、F安-t、F安-x图像，要判断形状或选图】","c":"想到【单棒中 $I=BLv/R$、F安$=B^2L^2v/R$（$R$ 为回路总电阻），两者都与速度 $v$ 成正比，故 I-t 图、F安-t 图与 v-t 图形状相同，I-x 图、F安-x 图与 v-x 图形状相同；定性分析时把 $I$ 或 F安 的图像直接替换成 $v$ 的图像来分析】；警惕【同形只是纵向缩放、数值不同；替换前提是 $B$、$L$、$R$ 不变，磁场或回路变化时失效】","src":"跳跳物一轮12.9 电磁感应中的图像问题_笔记","note":"视频|06:34","orig":"（知识）单棒模型中纵轴为电流I或安培力F安的图像分析方法。","link":""},{"id":"phy2741","t":"电磁感应·线框匀速穿磁场的图像排除法三招","s":"看到【线框匀速穿过磁场，选感应电流i-t或i-x图像的选择题】","c":"想到【第一招看面积：完全穿出后 $\\Delta\\Phi=0$、总电荷量为零，图线在横轴上下围成的面积必须相等；第二招看头尾：用楞次定律（增反减同）加安培定则判断刚进入和将离开时的电流方向定正负；第三招看切割长度：$I=BLv/R$ 与有效切割长度成正比，逐段分析切割长度变化定图线形状。先排除后验证，不要直接画完整图像】；警惕【横轴上下面积不相等的选项直接排除；i-x图仅在匀速（$x\\propto t$）时才能当i-t图分析】","src":"跳跳物一轮12.9 电磁感应中的图像问题_笔记","note":"视频|10:05-13:20","orig":"（知识）线框匀速穿过磁场时选i-t图、i-x图像的排除法。","link":""},{"id":"phy2742","t":"电磁感应·无外力单棒的P-x图像","s":"看到【无外力单棒滑入磁场，问安培力功率或克服安培力做功功率随位移x的图像】","c":"想到【先由动量定理得 v-x 为斜率为负的直线；安培力瞬时功率 $P=B^2L^2v^2/R$，代入线性关系后 $P$ 是 $x$ 的二次函数、抛物线开口向上，但物理上速度减小、功率必随 $x$ 减小，实际图像取抛物线的下降段（单调递减）】；警惕【不能因开口向上就画成先减后增；一根棒固定时本质仍是单棒模型，别当双棒处理】","src":"跳跳物一轮12.9 电磁感应中的图像问题_笔记","note":"视频|17:46","orig":"（例）a棒以初速度 $v_0$ 滑入磁场，b棒固定在导轨上不动，问a棒速度 $v$ 和克服安培力做功的功率 $P$ 随位移 $x$ 变化的图像。","link":""},{"id":"phy2743","t":"电磁感应·线框穿磁场的电势差图像","s":"看到【线框穿磁场，问某两点间电势差随位移或时间变化的图像】","c":"想到【电势差必须从外电路入手：先用右手定则定切割边正负极，无阻导线相连的点等势，故 $U_{cd}$ 始终等于路端电压；每阶段外电路都是两段电阻 $r$ 并联（$r/2$），路端电压 $=BLv\\times\\frac{r/2}{3r/2}=\\frac{1}{3}BLv$，穿磁场全程恒定不变】；警惕【所求段自己是电源时读路端电压，不是电源时只读它分得的电压，不能混用；换边切割时外电路组合改变，须重画等效电路】","src":"跳跳物一轮12.9 电磁感应中的图像问题_笔记","note":"视频|29:12","orig":"（例）线框上ab、cd、ef三段导线电阻均为 $r$，其余部分电阻不计，线框匀速穿过匀强磁场，问cd两端电势差 $U_{cd}$ 随位移 $x$ 变化的图像。","link":""},{"id":"phy2744","t":"电磁感应·线框过三角形磁场的i、F、Φ图像","s":"看到【线框穿过边界倾斜的磁场（三角形或梯形），问i、安培力或Φ的图像】","c":"想到【电流 $I=BLv/R$ 与有效切割长度 $d$ 成正比：进入和离开磁场时 $d$ 都从 $L$ 线性减小到 0，故 i-x 图进入段为正、从最大值线性减到 0，离开段反向翻到横轴下方；外力 $F=BId$ 与 $d^2$ 成正比，是二次曲线不是直线；$\\Phi$-x 图若为直线则电动势、电流恒定，与 $i$ 线性变化矛盾，可用反证法排除】；警惕【进入与离开磁场电流方向相反，离开段必须翻到横轴下方；$F$ 与 $d$ 是平方关系，别画成直线】","src":"跳跳物一轮12.9 电磁感应中的图像问题_笔记","note":"视频|32:59","orig":"（例）边长为 $L$、每边电阻为 $R$ 的正方形线框匀速穿过直角三角形匀强磁场区域（磁场直角边长为 $L$），判断感应电流 $i$、外力 $F$、磁通量 $\\Phi$ 随位移 $x$ 变化的图像。","link":""},{"id":"phy2745","t":"电磁感应·互感与自感的对比","s":"看到【两个线圈无导线相连却相互影响，或线圈自身电流变化对自己产生感应】","c":"想到【互感：一个线圈电流变化产生变化磁场，使另一线圈磁通量变化而产生感应电动势（如变压器）；自感：线圈自身电流变化使自身磁通量变化而激发感应电动势。两者本质相同，都遵循法拉第电磁感应定律，区别只在磁通量变化的原因来自另一线圈还是自身】；警惕【互感不需要导线连接但需要磁耦合（如共用铁芯）；自感发生在同一个线圈上，勿把自感说成互感】","src":"跳跳物一轮12.10 自感、电磁阻尼与电磁驱动、涡流_电磁感应模_笔记","note":"视频|00:24-02:12","orig":"（知识）互感与自感现象的定义、本质与区别。","link":""},{"id":"phy2746","t":"电磁感应·自感电动势与自感系数","s":"看到【问自感电动势大小与电流变化的关系，或问什么操作能增大自感系数L】","c":"想到【自感电动势 $E=L\\frac{\\Delta I}{\\Delta t}$，与电流变化率成正比；自感系数 $L$ 简称自感（电感），单位亨利(H)，由线圈本身决定：线圈越大、匝数越多 $L$ 越大，插入铁芯 $L$ 增大】；警惕【$L$ 只由线圈自身（大小、匝数、铁芯）决定，与电流大小、变化快慢无关；别把公式中的 $L$ 当成线圈长度】","src":"跳跳物一轮12.10 自感、电磁阻尼与电磁驱动、涡流_电磁感应模_笔记","note":"视频|03:16","orig":"（知识）自感电动势的公式与自感系数的单位、影响因素。","link":""},{"id":"phy2747","t":"电磁感应·自感中感应电流方向的判定","s":"看到【线圈电流增大或减小，问自感电流（感应电流）的方向与原电流的关系】","c":"想到【口诀增反减同（针对原电流与感应电流）：原电流增大时，感应电流与原电流方向相反；原电流减小时，感应电流与原电流方向相同。本质是感应电流总是阻碍原电流的变化】；警惕【这里的增反减同说的是I原与I感的关系，楞次定律的增反减同说的是B原与B感的关系，对象不同勿混淆】","src":"跳跳物一轮12.10 自感、电磁阻尼与电磁驱动、涡流_电磁感应模_笔记","note":"视频|04:26","orig":"（知识）自感现象中原电流与感应电流方向的关系。","link":""},{"id":"phy2748","t":"电磁感应·自感电路中线圈的三种等效","s":"看到【电路中有自感线圈，分析开关闭合瞬间、稳定后或断开后灯的亮暗变化】","c":"想到【按状态把线圈等效成不同元件：稳定时线圈是阻值为 $R_L$ 的定值电阻（无自感）；闭合瞬间相当于无穷大电阻（断路），之后阻值逐渐降到 $R_L$；断开后线圈相当于电源，感应电流与稳态时流过线圈的电流同向、大小从稳态电流逐渐减到零；若线圈不在闭合回路中，只有电动势无电流】；警惕【断开后与线圈并联的灯电流方向会反转、大小从线圈稳态电流开始衰减；不与线圈构成回路的灯立即熄灭】","src":"跳跳物一轮12.10 自感、电磁阻尼与电磁驱动、涡流_电磁感应模_笔记","note":"视频|06:40","orig":"（知识）含线圈电路在开关闭合、稳定、断开各阶段中线圈的等效处理方法。","link":""},{"id":"phy2749","t":"电磁感应·电磁阻尼与电磁驱动","s":"看到【导体与磁体相对运动，问安培力是阻力还是动力、属于电磁阻尼还是驱动】","c":"想到【两者本质相同：安培力总是阻碍导体与磁体间的相对运动。安培力表现为阻力是电磁阻尼，把动能转化为电能（磁电仪表铝框使指针快速停下、铜盘快速停下靠涡流阻尼）；表现为动力是电磁驱动，把电能转化为动能（磁悬浮列车、转动磁铁带动铝笼同向转动）。相对速度越大，感应电流越大，阻尼/驱动越强】；警惕【铜不会被磁化，快停下靠涡流阻尼；被驱动者速度必小于磁铁（同速则无感应电流）；磁铁停转后铝笼反受阻尼减速至停】","src":"跳跳物一轮12.10 自感、电磁阻尼与电磁驱动、涡流_电磁感应模_笔记","note":"视频|10:44-11:47","orig":"（知识）电磁阻尼与电磁驱动的本质、判断方法、能量转化与典型应用。","link":""},{"id":"phy2750","t":"电磁感应·涡流的产生条件与影响因素","s":"看到【导体块处于变化的磁场中，问是否产生涡流或涡流大小如何变化】","c":"想到【涡流：变化的磁场在整块导体中激发涡旋电场，形成大量闭合感应电流，像水中漩涡。产生条件是变化的磁场加导体；导体尺寸越大、电阻越小、磁场变化频率越高，涡流越大】；警惕【恒定磁场不产生涡流；涡流在导体块内部自成回路，不需要外接导线；绝缘体（陶瓷面板、玻璃）中不产生涡流】","src":"跳跳物一轮12.10 自感、电磁阻尼与电磁驱动、涡流_电磁感应模_笔记","note":"视频|14:48","orig":"（知识）涡流的定义、产生条件与大小影响因素。","link":""},{"id":"phy2751","t":"电磁感应·涡流的应用与防止","s":"看到【电磁炉、冶炼炉、金属探测器的工作原理，或变压器铁芯为何用绝缘硅钢片】","c":"想到【应用热效应：电磁炉（高频交变电流使金属锅底产生涡流发热，绝缘面板不发热）、真空冶炼炉；应用磁效应：金属探测器（发射线圈必须通交变电流，使金属中感应出涡流，涡流磁场反过来影响探测器触发报警）。防止发热：增大导体电阻率；变压器铁芯用相互绝缘的硅钢片叠压，把涡流限制在小薄片内】；警惕【减小涡流切片方向必须垂直于涡流平面（水平涡流要纵向切），平行切无效；探测器用恒定电流则完全无法探测】","src":"跳跳物一轮12.10 自感、电磁阻尼与电磁驱动、涡流_电磁感应模_笔记","note":"视频|15:55","orig":"（知识）利用涡流热效应、磁效应的典型应用及减小涡流发热的方法。","link":""},{"id":"phy2752","t":"电磁感应·自感电路断开开关时灯是否闪亮","s":"看到【含线圈电路断开开关，问某灯是闪亮后再熄灭还是直接熄灭】","c":"想到【先比较稳定时线圈电流 $I_2$ 与P灯电流 $I_1$：线圈电阻很小故 $I_2$ 远大于 $I_1$。断开后线圈与P构成回路，P中电流从 $I_1$ 突变为 $I_2$（回路电流处处相等），因 $I_2$ 大于 $I_1$ 故P先闪亮再逐渐熄灭；Q不在线圈回路中，立即熄灭。若线圈电阻与灯相当（两支路电流相等），断开后电流不变大，各灯只逐渐变暗不闪亮】；警惕【易误以为断开后所有灯都闪亮，唯一判据是断开瞬间流过灯的电流是否大于断开前；不与线圈构成回路的灯立即熄灭】","src":"跳跳物一轮12.10 自感、电磁阻尼与电磁驱动、涡流_电磁感应模_笔记","note":"视频|19:01","orig":"（例）自感系数很大、电阻很小的线圈 $L$ 与灯泡P并联后再与相同灯泡Q串联接在电源上。闭合开关稳定后P微亮，判断断开开关瞬间两灯的亮度变化。","link":""},{"id":"phy2753","t":"交流电·交流电的定义与判定","s":"看到【给出电流随时间变化的波形图（方波、正弦波等），问该电流是否为交流电】","c":"想到【交流电的判断只看电流方向是否随时间周期性变化，与大小是否变化无关；方波电流（大小不变、方向周期性突变）也是交流电；图线为正弦或余弦的统称正弦交流电】；警惕【把方向周期性突变但大小不变的方波误判为直流；只凭图线是不是正弦曲线下结论】","src":"跳跳物一轮13.1 交流电的概念、图像、四值_笔记","note":"视频|00:27","orig":"（知识）交流电的定义与判断依据：什么样的电流算交流电，方波电流算不算。","link":""},{"id":"phy2754","t":"交流电·正弦交流电产生条件与峰值公式","s":"看到【判断线圈转动能否产生正弦交流电，或求最大电动势、写电动势瞬时值表达式】","c":"想到【三条件缺一不可：匀强磁场、转轴垂直磁场方向、线圈匀速转动；最大电动势 $E_M=NBS\\omega$，同一线圈只改转速时 $E_M\\propto\\omega\\propto 1/T$，但最大磁通量 $\\Phi_M=BS$ 不变；从中性面（$B\\parallel v$）计时用 $e=NBS\\omega\\sin(\\omega t)$，从平行面（$B\\perp v$）计时用 $e=NBS\\omega\\cos(\\omega t)$】；警惕【磁场非匀强、转轴与磁场平行均不产生正弦交流电；计时起点选错会把 sin 写成 cos】","src":"跳跳物一轮13.1 交流电的概念、图像、四值_笔记","note":"视频|01:29","orig":"（知识）线圈在磁场中转动产生正弦交流电的条件、最大电动势公式及瞬时表达式选 sin 还是 cos。","link":""},{"id":"phy2755","t":"交流电·中性面与平行面对比","s":"看到【问线圈处于中性面或平行面位置时 Φ、e、i 及磁通量变化率的取值】","c":"想到【中性面（与磁场方向垂直的平面）：$B\\parallel v$ 不切割，$i/u/e=0$、$\\Phi$ 最大、变化率为 0；平行面（与磁场方向平行的平面）：$B\\perp v$ 切割，$i/u/e$ 最大、$\\Phi=0$、变化率最大；口诀“你最大我为0”——$\\Phi$ 与 $i/u/e$ 永不同时达到最大】；警惕【误以为 $\\Phi$ 最大处电动势也最大；$e$ 正比于磁通量变化率而非 $\\Phi$ 本身】","src":"跳跳物一轮13.1 交流电的概念、图像、四值_笔记","note":"视频|06:17","orig":"（知识）线圈转至中性面、平行面时磁通量、电动势、电流和磁通量变化率各自的大小对比。","link":""},{"id":"phy2756","t":"交流电·图像交点与峰谷的位置含义","s":"看到【给 i-t 图或 Φ-t 图，问某时刻线圈在中性面还是平行面、电流何时变向】","c":"想到【$i/u/e$-$t$ 图：横轴交点=中性面（电流变向处），峰谷=平行面（值最大）；$\\Phi$-$t$ 图恰好相反：交点=平行面、峰谷=中性面；一个周期内电流方向改变 2 次，每秒改变 $2f$ 次；由图读 $T$，则 $f=1/T$、$\\omega=2\\pi/T$】；警惕【两幅图未必是同一交流电，须各自独立分析；变向次数漏乘 2；家用电 $T=0.02\\,\\mathrm{s}$、$f=50\\,\\mathrm{Hz}$，每秒变向 100 次】","src":"跳跳物一轮13.1 交流电的概念、图像、四值_笔记","note":"视频|11:56-12:54","orig":"（知识）i-t 图与 Φ-t 图的横轴交点、波峰波谷分别对应线圈哪个位置，电流方向何时改变、一周期变向几次。","link":""},{"id":"phy2757","t":"交流电·四值的定义与用途对应","s":"看到【交流电题涉及电表读数、电容器击穿、电热电功或电荷量计算，问该用哪个值】","c":"想到【峰值（$E_M=NBS\\omega$）用于判断电容器能否击穿；有效值（正弦交流电 $E=E_M/\\sqrt{2}$，按热效应等效定义）用于算电功、电功率、电热，也是所有交流电表读数、铭牌额定电压、保险丝熔断电流；平均值（$\\bar{E}=N\\cdot\\Delta\\Phi/\\Delta t$）用于算电荷量 $Q=N\\cdot\\Delta\\Phi/R$（$R$ 为回路总电阻）；题目给的数值无特殊说明一律是有效值】；警惕【算电荷量误用有效值；电表读数误用峰值；$E=E_M/\\sqrt{2}$ 只对完整正弦波成立】","src":"跳跳物一轮13.1 交流电的概念、图像、四值_笔记","note":"视频|16:11","orig":"（知识）瞬时值、峰值、有效值、平均值各自的用途及“无特殊说明默认有效值”规则。","link":""},{"id":"phy2758","t":"交流电·非正弦交流电的有效值求法","s":"看到【波形不是完整正弦（正弦与方波混合、三角波、分段恒定等），求有效值、电表读数或焦耳热】","c":"想到【方均根法四步：按“每段有效值可直接求”的原则把一个周期等分→求各段有效值的平方→取平均→开根；两类正弦残波（从0或波峰波谷开始的四分之一波形、任意半个周期内的波形）有效值均为峰值的 $1/\\sqrt{2}$，与完整正弦波相同；恒定电流段的有效值就是它本身】；警惕【各段不等长时须按时间加权平均，不能简单取算术平均；乱套 $E=E_M/\\sqrt{2}$ 于任意残缺波形】","src":"跳跳物一轮13.1 交流电的概念、图像、四值_笔记","note":"视频|20:19","orig":"（知识）非正弦交流电（正弦与方波混合等）的有效值求解：正弦残波结论与方均根法步骤。","link":""},{"id":"phy2759","t":"交流电·半边磁场与单电刷发电模型","s":"看到【线圈转轴与磁场边界重合、半边无磁场仍匀速转动，或发电机原理图只画一个电刷】","c":"想到【半边磁场：任一时刻只有一条边切割，电流峰值减半（每边电流为总电流的一半），但 $i$-$t$ 图仍是完整的正弦波形；单电刷：外电路电流方向始终不变，是直流电，教材原理图须两个电刷才输出交流电】；警惕【误以为半边磁场使波形残缺或不再是正弦交流电；把单电刷图当成教材标准交流发电机】","src":"跳跳物一轮13.1 交流电的概念、图像、四值_笔记","note":"视频|23:42","orig":"（例）线框绕转轴匀速转动，转轴与磁场右边界重合（只有半边有磁场），问产生的电流图像；对比情景：发电机只有一个电刷时外电路得到什么电流。","link":""},{"id":"phy2760","t":"交流电·磁极转动线圈固定的等效法","s":"看到【磁铁转动而线圈固定不动，要求某时刻感应电流的方向或大小】","c":"想到【等效法：磁极顺时针转动等效为线圈逆时针转动，再对切割边用右手定则；线圈平面与磁场垂直（中性面）时电流为零，线圈平面转到与磁场平行（平行面）时电流最大；用右手定则逐边判定电流从哪端流向哪端】；警惕【直接拿磁极的运动套右手定则致方向判反；忽略等效转动必须反向（磁顺时针对应线圈逆时针）】","src":"跳跳物一轮13.1 交流电的概念、图像、四值_笔记","note":"视频|30:21","orig":"（例）磁极（磁铁）绕固定不动的线圈转动，初始时磁场方向与线圈平面垂直，问磁极转过一定角度后线圈中感应电流的大小与方向如何判定。","link":""},{"id":"phy2761","t":"变压器·工作原理与理想变压器","s":"看到【问变压器依据什么原理工作，或讨论铜损、铁损、磁漏等能量损失】","c":"想到【原理是互感：原线圈通交流电产生变化磁场，沿闭合铁芯传导使副线圈磁通量变化，从而产生感应电动势；三损=铜损（线圈电阻发热）+铁损（铁芯涡流发热）+磁漏（磁场未全部穿过副线圈）；理想变压器无三损，原副线圈电阻为零、磁通量时刻相等，高中无特殊说明一律按理想变压器处理】；警惕【变压器通直流不工作——恒定电流不产生变化的磁通，副线圈无电动势；题目明示考虑损耗时不能再用 $P_1=P_2$】","src":"跳跳物一轮13.2 变压器基础（含等效电阻法）_笔记","note":"视频|00:20-01:16","orig":"（知识）变压器的工作原理（互感）、三损是什么，以及理想变压器的条件。","link":""},{"id":"phy2762","t":"变压器·理想变压器的基本关系","s":"看到【已知匝数比，求变压器某侧的电压、电流、功率或频率】","c":"想到【电压与匝数成正比：$U_1/U_2=N_1/N_2$；电流与匝数成反比：$I_1/I_2=N_2/N_1$（由功率相等推导）；功率：$P_1=P_2$（输入=输出）；频率：变压器不改变交流电的频率和周期，$f_1=f_2$】；警惕【电流关系式中匝数上下颠倒（与电压关系相反）；电流反比关系只对单副线圈成立；误以为变压器会改变频率】","src":"跳跳物一轮13.2 变压器基础（含等效电阻法）_笔记","note":"视频|03:02","orig":"（知识）理想变压器电压、电流、功率、频率四个基本关系及其适用条件。","link":""},{"id":"phy2763","t":"变压器·电压电流的决定关系与动态分析","s":"看到【匝数比与原线圈电压固定，负载电阻或用电器数量变化，问各量怎么变】","c":"想到【电压“原决定副”：$U_2=(N_2/N_1)U_1$，$U_1$ 和匝数比不变则 $U_2$ 恒定，与负载无关；电流、功率“副决定原”：$I_1=(N_2/N_1)I_2$、$P_1=P_2$；动态链条：负载电阻增大→副线圈电流 $I_2=U_2/R$ 减小→$I_1$、$P_1$ 随之减小】；警惕【$I_1/I_2=N_2/N_1$ 写成反比式，但 $I_1$ 与 $I_2$ 本身是正比关系；误以为负载变化会改变副线圈电压】","src":"跳跳物一轮13.2 变压器基础（含等效电阻法）_笔记","note":"视频|06:22","orig":"（知识）理想变压器中“谁决定谁”：电压由谁定，电流功率由谁定，负载变化时各量如何变化。","link":""},{"id":"phy2764","t":"变压器·多副线圈的电压功率电流关系","s":"看到【变压器有两个及以上副线圈，求各线圈电压、电流或原线圈功率】","c":"想到【电压仍与匝数成正比：$U_1:U_2:U_3=N_1:N_2:N_3$；功率：$P_1=P_2+P_3$（输入=各副线圈输出之和）；电流无反比关系，由 $P=UI$ 结合电压关系得 $N_1I_1=N_2I_2+N_3I_3$；各副线圈支路互不影响，某支路负载变化只改变自身电流和原线圈电流】；警惕【把单副线圈的电流反比公式套到多副线圈上；算输入功率时漏加某条副线圈支路】","src":"跳跳物一轮13.2 变压器基础（含等效电阻法）_笔记","note":"视频|09:04","orig":"（知识）多个副线圈的理想变压器，电压、功率、电流各满足什么关系，与单副线圈有何不同。","link":""},{"id":"phy2765","t":"变压器·电流互感器与电压互感器","s":"看到【变压器原线圈串在一根输电线上或并在两线之间，副线圈接电表】","c":"想到【电流互感器：原线圈串联在一根输电线上（原线圈电流=线路电流），起降流作用，匝数 $N_1<N_2$，副线圈接电流表，被测电流=读数$\\times N_2/N_1$；电压互感器：原线圈并联在两根输电线之间（原线圈电压=线路电压），起降压作用，$N_1>N_2$，副线圈接电压表，被测电压=读数$\\times N_1/N_2$】；警惕【两类互感器的接线与匝数关系正好相反，混淆会把电流表、电压表判断反】","src":"跳跳物一轮13.2 变压器基础（含等效电阻法）_笔记","note":"视频|11:59","orig":"（知识）电流互感器和电压互感器的接线方式、作用与匝数关系。","link":""},{"id":"phy2766","t":"变压器·等效电阻法","s":"看到【原线圈电路串有电阻，电源电压不等于原线圈电压，求电流、电压或电阻】","c":"想到【把“变压器+副线圈电路”整体等效为一个电阻：等效电阻 $R'=(N_1/N_2)^2\\cdot R$，$R$ 为副线圈电路的总电阻（先算并联总电阻）；等效后变压器消失，原线圈电路变成简单串并联电路，$R'$ 两端电压即原线圈电压 $U_1$、流过它的电流即 $I_1$，再按闭合电路欧姆定律列方程】；警惕【匝数比 $(N_1/N_2)$ 的平方别写反或漏平方；忘记合并副线圈并联总电阻；把 $R'$ 上的电压当成电源电压】","src":"跳跳物一轮13.2 变压器基础（含等效电阻法）_笔记","note":"视频|13:49","orig":"（知识）原线圈电路中串有电阻时，用等效电阻法把变压器+副线圈整体等效成一个电阻的方法与公式。","link":""},{"id":"phy2767","t":"变压器·含二极管的交流电路","s":"看到【副线圈（或负载）电路中有二极管，求电流/电压有效值、电表读数或功率】","c":"想到【电流方向与二极管箭头方向一致时导通（相当于导线）、相反时截止（相当于断路）；正弦交流下每个周期只有一半时间导通；有效值须用方均根法分段计算：导通段与截止段各取电流（电压）值，平方后按时间加权平均再开根】；警惕【对含二极管波形直接套 $P=UI$ 计算功率（非线性波形下不成立）；半波整流后有效值照搬原正弦有效值——已知正弦有效值 $U$ 时半波有效值为 $U/\\sqrt{2}$】","src":"跳跳物一轮13.2 变压器基础（含等效电阻法）_笔记","note":"视频|17:03","orig":"（知识）交流电路中有二极管时其导通规则，及有效值、功率的正确计算方法。","link":""},{"id":"phy2768","t":"变压器·变压器配灯泡的综合计算","s":"看到【给交流电图像峰值+副线圈灯泡正常发光，求电压有效值、匝数比或输入功率】","c":"想到【先由峰值$\\div\\sqrt{2}$得原线圈电压有效值；灯泡正常发光时其电压、电流均为额定值，$I_2=P/U$（$P$、$U$ 取灯泡额定值）；匝数比=电压比 $N_1:N_2=U_1:U_2$；理想变压器输入功率=输出功率，副线圈只接灯泡时输入功率即灯泡额定功率】；警惕【把图像峰值直接当有效值用；灯泡电流须按额定 $P/U$ 求，而非用原线圈电压计算】","src":"跳跳物一轮13.2 变压器基础（含等效电阻法）_笔记","note":"视频|21:37","orig":"（例）理想变压器原线圈接正弦交流电源，u-$t$ 图像峰值 $24\\sqrt{2}\\,\\mathrm{V}$；副线圈接一个“6V 3W”的灯泡且恰好正常发光，求原线圈电压有效值、通过灯泡的电流、原副线圈匝数比、变压器输入功率。","link":""},{"id":"phy2769","t":"变压器动态分析·电阻变化的串反并同法","s":"看到【变压器电路中滑动变阻器阻值变化，问各电表读数、某元件电流电压功率怎么变】","c":"想到【划掉变压器（原副线圈两端直接相连）化为普通电路，把变化电阻与电源连成一个“圈”：圈上元件（与变化电阻串联）的 $I$、$U$、$P$ 与阻值变化趋势相反（串反）；圈外元件（与变化电阻并联）的 $I$、$U$、$P$ 与阻值变化趋势相同（并同）】；警惕【直接与无内阻电源并联的元件是特例：电压恒为电动势、$I$、$U$、$P$ 均不变；不先划掉变压器就把原副线圈电路混在一起画圈，会判错串并联关系】","src":"跳跳物一轮13.3 变压器动态分析、远距离输电_笔记","note":"视频|00:07","orig":"（知识）变压器电路中滑动变阻器阻值变化时，用“划掉变压器+串反并同”判断各电表与功率的变化。","link":""},{"id":"phy2770","t":"变压器动态分析·匝数比变化（原线圈无电阻）","s":"看到【自耦变压器移动触头改变匝数比，原线圈直接接电源，问各电压电流功率变化】","c":"想到【$U_1$ 恒等于电源输出电压不变；从 $U_2$ 入手逐级顺推：$U_2=(N_2/N_1)U_1$ 随匝数比变→$I_2=U_2/R$、$P_2=U_2^2/R$（$R$ 为副线圈电路总电阻）→$P_1=P_2$→$I_1=P_1/U_1$；自耦变压器原副线圈共线，副线圈匝数小于原线圈匝数则为降压变压器】；警惕【把 $U_1$ 当成会变化；$N_2$ 增大时漏判 $I_2$、$P_2$ 随之增大；升压降压看匝数多少而非线圈位置】","src":"跳跳物一轮13.3 变压器动态分析、远距离输电_笔记","note":"视频|05:56","orig":"（知识）自耦变压器滑片移动改变匝数比、原线圈直接接电源（无串联电阻）时各量的推导顺序。","link":""},{"id":"phy2771","t":"变压器动态分析·匝数比变化（原线圈有电阻）","s":"看到【自耦变压器改匝数比且原线圈电路串有电阻，问原线圈电压 U$_1$、功率怎么变】","c":"想到【用等效电阻法：$R'=(N_1/N_2)^2\\cdot R$（$R$ 为副线圈电路总电阻）随匝数比变化；此时 $U_1$ 是 $R'$ 在原线圈电路中的分压，随匝数比变化而变（不再恒等于电源电压）；功率用等效电源法：把电源与定值电阻等效为有内阻的电源，$R'$ 越接近内阻输出功率越大、越远离越小】；警惕【仍按 $U_1$ 不变套 $U_2=(N_2/N_1)U_1$ 顺推；忽略原线圈电阻上的分压变化】","src":"跳跳物一轮13.3 变压器动态分析、远距离输电_笔记","note":"视频|05:56","orig":"（知识）原线圈电路串有定值电阻时匝数比变化，用等效电阻法与等效电源法分析 U$_1$ 与功率的变化。","link":""},{"id":"phy2772","t":"远距离输电·三个回路与电压功率关系","s":"看到【远距离输电电路（两个变压器三个回路），求或比较各处电压、电流、功率】","c":"想到【结构：发电回路→升压变压器→输电回路→降压变压器→用户回路，先升压后降压；输电回路满足 $U_2=\\Delta U+U_3$（$\\Delta U$ 为线损电压）、$P_2=\\Delta P+P_3$（$\\Delta P=I^2R$ 为线损功率，$R$ 为输电线总电阻）；输电线上电流处处相等，$I=P_2/U_2$；计算从已知端逐级推向未知端】；警惕【把 $U_3$、$P_3$ 当成 $U_2$、$P_2$（漏线损）；线路电流误用受端（用户）电压计算；忘记“发电端决定输电电压、用户端决定输送功率”的方向性】","src":"跳跳物一轮13.3 变压器动态分析、远距离输电_笔记","note":"视频|00:07-00:25","orig":"（知识）远距离输电电路的结构（升压-输电-降压三个回路）、输电回路中的电压功率关系与计算顺序。","link":""},{"id":"phy2773","t":"远距离输电·高压输电降损原理","s":"看到【问为什么要高压输电，或输送功率不变时输电电压变化对线路损耗的影响】","c":"想到【线损 $\\Delta P=I^2\\cdot R$，而 $I=P_2/U_2$：输送功率不变时提高输电电压 $U_2$→电流 $I$ 减小→线损按平方减小（电压减半则电流加倍、线损变四倍）；不能用 $\\Delta P=\\Delta U^2/R$ 判断趋势——损失电压 $\\Delta U=I\\cdot R$ 随电流减小而减小，并不随输电电压增大】；警惕【误认为提高输电电压会增大损失电压，实际 $\\Delta U$ 随电流减小；漏掉线损与输电电压平方成反比的比例关系】","src":"跳跳物一轮13.3 变压器动态分析、远距离输电_笔记","note":"视频|00:07-00:25","orig":"（知识）为什么远距离输电要采用高电压：提高输电电压如何降低线路损耗，及“P线=U线$^2$/R线”为何不能用。","link":""},{"id":"phy2774","t":"变压器动态分析·输入功率先增大后减小的判断","s":"看到【滑片全程滑动使副线圈阻值单调变化，问输入（或某电阻）功率是单调变还是先增后减】","c":"想到【电表示数用串反并同：变化电阻减小时，“圈”上电表读数增大、圈外减小；输入功率用等效电源法：把电源与定值电阻等效成内阻 $r$ 的电源，变压器输入功率即等效电阻 $R'=(N_1/N_2)^2\\times R$ 的功率，$R'$ 单调变化扫过 $r$ 时：接近 $r$ 功率增大、越过 $r$ 后远离则减小，故输入功率先变大后变小】；警惕【用串反并同判变压器输入功率——它是变化电阻自身的等效功率，非单调，须用等效电源法；套 $P_1=U_1I_1$ 判断（两因子一增一减无法定）；漏判等效电阻等于内阻时功率最大】","src":"跳跳物一轮13.3 变压器动态分析、远距离输电_笔记","note":"视频|19:20","orig":"（例）理想变压器匝数比 1:2，原线圈电路中电源串接定值电阻，副线圈接滑动变阻器，滑片从阻值最大处滑到零（接入阻值单调减小），问电流表、电压表示数及变压器输入功率的变化情况。","link":""},{"id":"phy2775","t":"远距离输电·从用户端倒推的计算顺序","s":"看到【已知用户端灯泡额定值与数量、两变压器匝数比、线路电阻，求线损、发电机输出功率或电动势】","c":"想到【从用户端倒推：先由每盏灯额定值与盏数求 $I_4$、$P_4$→由降压变压器匝数比得输电线电流 $I_2=I_4\\cdot N_4/N_3$→线损 $\\Delta P=I_2^2\\cdot R$→$P_2=P_4+\\Delta P$→由升压变压器匝数比得 $I_1$，$U_1=P_1/I_1$→最后按闭合电路欧姆定律 $E=I_1\\cdot r+U_1$ 求电动势（$r$ 为发电机内阻）】；警惕【把用户端功率直接当输送功率（漏线损）；求电动势忘记发电机内阻分压 $I_1r$；匝数比用反（电流比与匝数比交叉相乘）】","src":"跳跳物一轮13.3 变压器动态分析、远距离输电_笔记","note":"视频|00:07-00:25","orig":"（知识）远距离输电综合计算：用户端为大量相同规格灯泡、发电机有内阻时，从用户端倒推求线损、输出功率与电动势的顺序。","link":""},{"id":"phy2776","t":"远距离输电·用户用电器增减的动态分析","s":"看到【远距离输电中用户用电器增多或减少，问线路电流、线损、用户电压怎么变】","c":"想到【用户增多→用户端总电阻减小→用串反并同：输电线（圈上）电流增大、线损功率增大，用户端电压（降压变压器输出）减小；升压变压器输出电压 $U_2$ 由发电端决定保持不变；输送功率由用户端用电器决定（用户决定功率、发电端决定电压）】；警惕【认为用户电压不变——用户越多线路分压越大、用户电压越低；直接并联在电源两端的电压表示数不变（特例）】","src":"跳跳物一轮13.3 变压器动态分析、远距离输电_笔记","note":"视频|23:55","orig":"（例）远距离高压输电模型：升压变压器接发电端，降压变压器副线圈并联多组用电器，各回路装有电流表、电压表。用户并联的用电器增多，问各电表读数、线路损耗功率及用户电压如何变化。","link":""},{"id":"phy2777","t":"交变电流·感抗与容抗的特性对比","s":"看到【电路含电感线圈或电容器，交变电流频率变化，问阻碍作用、支路电流或灯泡亮度变化】","c":"想到【电感器：通直流阻交流、通低频阻高频，电感 $L$ 越大、频率 $f$ 越大，感抗越大；电容器：通交流隔直流、通高频阻低频，电容 $C$ 越大、频率 $f$ 越大，容抗越小；频率升高时，串电感的灯变暗、串电容的灯变亮】；警惕【电容“隔直流”是完全隔断，直流稳定后该支路电流为零；感抗与容抗随频率的增减方向恰好相反，勿记混】","src":"跳跳物一轮13.4 感抗与容抗、电磁振荡、电磁波_笔记","note":"视频|00:22-01:24","orig":"（知识）电感器与电容器对交变电流的阻碍作用（感抗、容抗）及其随频率的变化规律。","link":""},{"id":"phy2778","t":"电磁振荡·LC电路充放电判定与周期公式","s":"看到【LC振荡电路给出电流或电荷量随时间的变化，问充放电状态、能量转化方向或周期频率变化】","c":"想到【判定链条：电流增大→电容器放电（$q$ 减小，电场能转化为磁场能）；电流减小→电容器充电（$q$ 增大，磁场能转化为电场能）；周期 $T=2\\pi\\sqrt{LC}$，电容 $C$ 或自感 $L$ 减小→周期减小、频率增大】；警惕【电流最大时恰是放电完毕 $q=0$，勿以为电流大电荷量也大；液面降低使介质减少、极板距离增大等都会使电容 $C$ 减小】","src":"跳跳物一轮13.4 感抗与容抗、电磁振荡、电磁波_笔记","note":"视频|02:35","orig":"（知识）LC振荡电路中电流变化与电容器充放电、能量转化的对应关系及振荡周期公式。","link":""},{"id":"phy2779","t":"电磁振荡·电荷量与电流的极值对应关系","s":"看到【q-t或i-t图像，问某时刻电场能、磁场能、电流是否最大或自感电动势是否为零】","c":"想到【电荷量 $q$ 最大：充电完毕，电流 $i=0$，电场能最大、磁场能为零；$q=0$：放电完毕，$i$ 最大，磁场能最大，且电流变化率 $\\Delta i/\\Delta t=0$，自感电动势 $E=L\\cdot\\Delta i/\\Delta t$ 为零；$q$ 增大阶段即充电，电流逐渐减小】；警惕【自感电动势与电流错开四分之一周期：电流最大时自感电动势为零，电流为零时自感电动势才最大，勿同涨同落】","src":"跳跳物一轮13.4 感抗与容抗、电磁振荡、电磁波_笔记","note":"视频|02:35","orig":"（知识）LC振荡中电荷量与电流在极值时刻的对应关系及自感电动势的极值特点。","link":""},{"id":"phy2780","t":"电磁波·麦克斯韦电磁场理论","s":"看到【判断“变化的磁场（电场）产生什么电场（磁场）”类说法正误，或给B-t、E-t图像问感应出的场】","c":"想到【恒定的磁场（电场）不产生电场（磁场）；均匀变化的磁场（电场）产生恒定的电场（磁场）；周期性变化的磁场（电场）产生同频率的交变电场（磁场）】；警惕【“变化的磁场一定产生变化的电场”是错的——均匀变化只产生恒定场，只有交变（周期性变化）的场才产生交变场】","src":"跳跳物一轮13.4 感抗与容抗、电磁振荡、电磁波_笔记","note":"视频|05:31","orig":"（知识）麦克斯韦电磁场理论：恒定场、均匀变化场、周期性变化场各自感应出什么场。","link":""},{"id":"phy2781","t":"电磁波·电磁波与机械波的对比","s":"看到【比较电磁波与机械波性质（横纵波、是否需介质、波速与频率由谁决定），或真空、水中通信方式判断】","c":"想到【电磁波仅横波、无需介质、真空中速度为光速 $c$；机械波可横可纵、必须依赖介质；两种波的周期 $T$、频率 $f$ 均仅由波源决定；机械波波速 $v$ 仅由介质决定，介质中电磁波波速与介质和频率都有关，真空中电磁波波速与频率无关；波长 $\\lambda=vT=v/f$】；警惕【超声波、水声是机械波不是电磁波；真空中只能靠电磁波通信】","src":"跳跳物一轮13.4 感抗与容抗、电磁振荡、电磁波_笔记","note":"视频|07:24","orig":"（知识）电磁波与机械波在波的类型、介质需求、波速与波长决定因素上的差异。","link":""},{"id":"phy2782","t":"电磁波·信号的调制、调谐与解调","s":"看到【发射接收流程中问调制、调谐、解调（检波）各是什么操作，或判断接收电路固有频率】","c":"想到【发射要调制：把低频信号搭载到高频载波便于发射，调幅AM让载波振幅随信号变、调频FM让载波频率随信号变；接收先调谐：调节接收电路固有频率与目标电磁波频率相等，利用电谐振筛选信号；再解调还原原始信号，调幅波的解调专称检波】；警惕【调谐选的是调制后高频载波的频率，不是低频信号频率；调幅波的外包络应关于时间轴上下对称】","src":"跳跳物一轮13.4 感抗与容抗、电磁振荡、电磁波_笔记","note":"视频|10:56","orig":"（知识）无线电发射与接收中的调制（调幅/调频）、调谐、解调三步的含义与目的。","link":""},{"id":"phy2783","t":"电磁波·球面扩散的接收功率","s":"看到【已知发射总功率和到发射源的距离，求单位面积接收功率或安全距离（球面扩散模型）】","c":"想到【单位面积接收功率 $P'=P/(4\\pi R^2)$，$P$ 为发射总功率，$R$ 为接收点到发射点的距离；要求 $P'$ 不超过允许值 $P_0$ 时，安全距离 $R=\\sqrt{P/(4\\pi P_0)}$，允许值越大，安全距离越短】；警惕【$R$ 是到发射点的距离而非离地高度；分母 $4\\pi R^2$ 勿漏平方或漏 $4\\pi$】","src":"跳跳物一轮13.4 感抗与容抗、电磁振荡、电磁波_笔记","note":"视频|15:38","orig":"（知识）电磁波能量以球面形式向四面八方扩散，距发射点一定距离处单位面积的接收功率。","link":""},{"id":"phy2784","t":"电磁波·电磁波谱频率排序与波段应用","s":"看到【将$\\gamma$射线、X射线、紫外线、红外线、无线电波等排频率或波长顺序，或问某波段用途】","c":"想到【频率由高到低：$\\gamma$射线＞X射线＞紫外线＞可见光＞红外线＞无线电波；频率越高能量越强、波长越短；紫外线用于杀菌消毒、红外线用于加热理疗与遥控、X射线用于透视诊断、微波属无线电波高频段用于卫星通信】；警惕【超声波是机械波不是电磁波；杀菌消毒用紫外线而非红外线；除可见光与红外线、紫外线之间分界明显外，其他相邻波段频率范围有交错重叠】","src":"跳跳物一轮13.4 感抗与容抗、电磁振荡、电磁波_笔记","note":"视频|17:44","orig":"（知识）电磁波谱按频率由高到低的排序及各波段的典型应用。","link":""},{"id":"phy2785","t":"光的折射·折射率的定义与决定因素","s":"看到【问某介质折射率由什么决定、是否随入射角变化，或判断两种介质谁光密谁光疏】","c":"想到【折射率 $n=\\sin\\alpha/\\sin\\theta$（$\\alpha$ 为空气角、$\\theta$ 为介质角），由介质和光的频率共同决定；它与入射角、折射角大小无关，可用来计算但不随其变化（类比电阻 $R=U/I$）；空气 $n\\approx 1$，其他介质 $n>1$；折射率大的是光密介质，光从光疏射向光密时折射光线靠近法线】；警惕【勿认为折射率只由介质决定——同种介质对频率不同的光折射率不同；光密光疏是两介质比较的结果，不是绝对属性】","src":"跳跳物一轮14.1 光的折射、全反射_笔记","note":"视频|01:33","orig":"（知识）折射率的定义、决定因素及光密光疏介质的判定。","link":""},{"id":"phy2786","t":"光的折射·折射率的计算技巧与常考数值","s":"看到【给空气中和介质中光线与法线的夹角求折射率，或题中出现45°、30°、60°角度组合】","c":"想到【统一用 $n=\\sin\\alpha/\\sin\\theta$（$\\alpha$ 为空气角、$\\theta$ 为介质角），不必判断光从哪边射入；因任何介质 $n>1$，空气角必大于介质角，可直接用大角正弦比小角正弦；常考数值：空气角 $45^{\\circ}$、介质角 $30^{\\circ}$→$n=\\sqrt{2}$，空气角 $60^{\\circ}$、介质角 $30^{\\circ}$→$n=\\sqrt{3}$】；警惕【勿用“入射角比折射角”硬套而搞反分子分母；所有角度都是光线与法线的夹角，不是与界面的夹角】","src":"跳跳物一轮14.1 光的折射、全反射_笔记","note":"视频|04:36","orig":"（知识）用空气角与介质角之比计算折射率的技巧及两组常考角度组合。","link":""},{"id":"phy2787","t":"光的折射·同介质中红光到紫光的特性对比","s":"看到【同种介质中比较红光与紫光（或其他色光）的折射率、速度、波长或临界角大小】","c":"想到【口诀“波波宏大、率率紫大”：红光波长最长、波速最大，紫光频率最高、折射率最大；从红到紫频率升高，折射率 $n$ 增大，波速 $v=c/n$ 减小，波长变短，临界角 $C$（$\\sin C=1/n$）减小；色散光谱中紫光偏折最多、红光偏折最少】；警惕【折射率和光速是介质中的量，比较须限定同一种介质；$v=c/n$ 中 $c$ 是真空光速，介质中光速必小于 $c$】","src":"跳跳物一轮14.1 光的折射、全反射_笔记","note":"视频|08:37","orig":"（知识）同一介质中从红光到紫光，频率、折射率、波速、波长、临界角的递变规律。","link":""},{"id":"phy2788","t":"光的全反射·发生条件与临界角","s":"看到【光从一种介质射向另一种介质，问能否发生全反射、临界角多大或“恰好”出射问题】","c":"想到【两条件缺一不可：①光从光密介质射向光疏介质；②入射角$\\geq$临界角 $C$，$\\sin C=1/n$；常考数值：$n=\\sqrt{2}$ 时 $C=45^{\\circ}$，$n=\\sqrt{3}$ 时 $30^{\\circ}<C<45^{\\circ}$；“恰好有/没有光线射出”都指入射角恰等于临界角的临界状态】；警惕【只有光密射向光疏才可能全反射，反向不可能；无论是否发生全反射，反射光始终存在，全反射时只是折射光消失】","src":"跳跳物一轮14.1 光的折射、全反射_笔记","note":"视频|11:49","orig":"（知识）全反射现象的发生条件、临界角公式及相关易错点。","link":""},{"id":"phy2789","t":"光的全反射·光导纤维的传光原理与路程时间","s":"看到【光在直光导纤维（玻璃丝）中经多次全反射传播，求总路程或传播时间】","c":"想到【内芯为光密介质、外套为光疏介质，光在内芯与外套界面发生全反射；把“之”字形光路对称拉直成直角三角形：总路程 $d=l/\\sin\\beta$（$\\beta$ 为全反射入射角），恰好全反射时 $d=nL$；传播时间 $t=d/v=n^2L/c$（其中 $v=c/n$）】；警惕【$\\beta$ 是光在纤维内界面上全反射的入射角，不是进入端面的入射角；计算时间要用介质中光速 $c/n$，勿用真空光速 $c$】","src":"跳跳物一轮14.1 光的折射、全反射_笔记","note":"视频|11:49","orig":"（知识）光导纤维的结构、全反射传光原理及光在纤芯中的路程与时间计算。","link":""},{"id":"phy2790","t":"光的全反射·反射光与折射光垂直的几何关系","s":"看到【反射光线与折射光线互相垂直求折射率，或问换用白光、其他色光后反射折射光线如何变化】","c":"想到【反射光与折射光垂直⇒空气角 $\\alpha$ 与介质角 $\\theta$ 互余，用 $n=\\sin\\alpha/\\sin\\theta$ 求折射率（$\\theta=30^{\\circ}$、$\\alpha=60^{\\circ}$ 时 $n=\\sqrt{3}$）；判断c消失：比较入射角与临界角，$n=\\sqrt{3}$ 时 $30^{\\circ}<C<45^{\\circ}$，$\\theta=45^{\\circ}>C$ 则全反射；换白光：反射角只与入射角有关、与频率无关，反射光仍为白光；换紫光：折射率变大、折射光偏折更厉害，b与c不再垂直】；警惕【反射光方向不随光的频率改变；折射光才随频率（折射率）变化】","src":"跳跳物一轮14.1 光的折射、全反射_笔记","note":"视频|22:29","orig":"（例）光从某透明介质射向空气，反射光线b与折射光线c恰好垂直，介质中光线与法线夹角 $\\theta=30^{\\circ}$（空气角 $60^{\\circ}$）：求介质折射率；判断 $\\theta$ 增大到 $45^{\\circ}$ 时折射光线c是否消失；入射光换成白光后反射光线b的颜色；换成紫光后b与c是否仍垂直。","link":""},{"id":"phy2791","t":"光的全反射·油量计亮暗区的判定","s":"看到【塑料、玻璃等锯齿或端面一部分在空气中、一部分浸入液体中，问哪里亮哪里暗或折射率范围】","c":"想到【在空气中：塑料相对空气是光密介质，光从塑料射向空气，入射角$\\geq$临界角即全反射，反射光强形成亮区；浸入油中：油折射率更大、是光密介质，光从光疏射向光密不可能全反射，部分光折射入油，形成暗区；由入射角 $45^{\\circ}\\ge C$ 得 $\\sin 45^{\\circ}\\ge 1/n$，即 $n\\ge\\sqrt{2}$】；警惕【暗区恰恰是没有发生全反射造成的；油量增加时浸入锯齿增多，暗区变大、亮区变小】","src":"跳跳物一轮14.1 光的折射、全反射_笔记","note":"视频|29:10","orig":"（例）油量计中透明塑料锯齿一部分在空气中、一部分浸入油中：已知塑料折射率小于油的折射率，锯齿面处光的入射角为 $45^{\\circ}$，问亮区暗区的成因、塑料折射率的取值范围及油量增加时亮区范围的变化。","link":""},{"id":"phy2792","t":"光的全反射·玻璃球内点光源的最少反射次数","s":"看到【球形（或圆形）介质内点光源发光，折射角与入射角存在倍数几何关系，求折射率或回到原点的最短时间】","c":"想到【连球心与入射点得等腰三角形，配合出射光线与直径平行，用外角定理得空气角 $\\alpha$ 为介质角 $\\theta$ 的2倍（$\\alpha=2\\theta$），再由 $n=\\sin\\alpha/\\sin\\theta$ 求折射率；最短时间看全反射次数最少：正三角形光路入射角 $30^{\\circ}$、正方形光路入射角 $45^{\\circ}$，与临界角比较确定最少次数，总路程=边数×边长，时间 $t=nL/c$】；警惕【沿半径方向的光线入射角为 $0^{\\circ}$，不发生全反射；球内时间要用光速 $c/n$，勿用真空光速 $c$】","src":"跳跳物一轮14.1 光的折射、全反射_笔记","note":"视频|47:05","orig":"（例）玻璃球（折射率 $\\sqrt{3}$、半径 $R$）内一点光源S发出的一条光线在球面A处折射后沿AB射出，AB与过S的直径平行，由几何关系得空气角为 $60^{\\circ}$、球内光线与半径夹角为 $30^{\\circ}$：求折射率；并求光在球内经多次全反射回到S点的最短时间。","link":""},{"id":"phy2793","t":"光的干涉·双缝干涉亮暗条纹条件","s":"看到【双缝干涉中屏上某点到两缝的路程差，判断该处是亮纹还是暗纹】","c":"想到【路程差为波长的整数倍（偶数个半波长）→加强，为亮条纹中心；路程差为奇数个半波长→减弱，为暗条纹中心；光屏中心到两缝路程差为 $0$，一定是亮条纹中心；双缝 $S_1$、$S_2$ 是频率相同、步调一致的相干光源；干涉是波独有的现象，证明光具有波动性】；警惕【亮暗只由路程差与半波长的奇偶倍关系决定；中心必亮，不随波长或缝距改变】","src":"跳跳物一轮14.2 光的干涉、衍射、偏振_光学模块完结撒花~~_笔记","note":"视频|01:00","orig":"（知识）双缝干涉中亮暗条纹的出现条件及光屏中心条纹的性质。","link":""},{"id":"phy2794","t":"光的干涉·双缝干涉条纹间距公式","s":"看到【双缝干涉中改变缝间距、屏距、光的颜色或浸入介质，问条纹间距如何变化】","c":"想到【条纹间距 $\\Delta x=l\\lambda/d$（$l$ 为双缝到屏距离，$d$ 为双缝间距，$\\lambda$ 为波长），条纹等距；$\\lambda$ 增大（如绿光换红光）、$l$ 增大、$d$ 减小均使 $\\Delta x$ 增大；结合 $\\lambda=v/f$ 知 $\\Delta x$ 与光的频率成反比；装置浸入介质后波长变为 $\\lambda/n$，条纹变密】；警惕【光源到双缝的距离对 $\\Delta x$ 没有影响；双缝间距变大（如更粗的头发丝）时 $\\Delta x$ 减小】","src":"跳跳物一轮14.2 光的干涉、衍射、偏振_光学模块完结撒花~~_笔记","note":"视频|02:34","orig":"（知识）双缝干涉相邻条纹间距公式及各因素对间距的影响。","link":""},{"id":"phy2795","t":"光的干涉·薄膜干涉原理与膜中波长","s":"看到【薄膜（肥皂膜、空气膜、镀膜）前后表面反射光干涉，问路程差、亮暗或膜中波长】","c":"想到【薄膜前、后表面的两束反射光发生干涉，路程差为 $2d$（$d$ 为该处膜厚）；$2d$ 为偶数个半波长时干涉加强、奇数个半波长时干涉减弱；计算必须用光在薄膜中的波长：$\\lambda'=\\lambda/n$（$\\lambda'$ 为膜中波长，$n$ 为薄膜折射率）】；警惕【勿把空气中的波长直接代入薄膜干涉计算；肥皂膜受重力上薄下厚，条纹水平且上疏下密】","src":"跳跳物一轮14.2 光的干涉、衍射、偏振_光学模块完结撒花~~_笔记","note":"视频|04:23","orig":"（知识）薄膜干涉的形成原因、路程差与加强减弱条件及膜中波长的换算。","link":""},{"id":"phy2796","t":"光的干涉·零件验平与条纹弯曲方向","s":"看到【标准板与待测板间垫纸片形成劈形空气膜，问条纹疏密变化或条纹弯曲对应的凹凸】","c":"想到【板平整时空气膜厚度均匀变化，条纹平行且等距；同一条纹上各点空气膜厚度相同；条纹向薄端（“头”，垫纸片一端）弯曲处表面凹陷，向厚端（“屁股”，被垫起一端）弯曲处表面凸起；垫片越厚条纹越密，波长越短条纹越密】；警惕【弯曲方向与凹凸易判反，先认清哪端薄哪端厚再套口诀；加纸片或左移纸片都增大膜厚变化率，条纹变密】","src":"跳跳物一轮14.2 光的干涉、衍射、偏振_光学模块完结撒花~~_笔记","note":"视频|08:34","orig":"（知识）用劈形空气膜干涉检查工件表面平整度：条纹形状判断与“头凹屁股凸”口诀。","link":""},{"id":"phy2797","t":"光的干涉·增反膜与增透膜的最小厚度","s":"看到【镜头镀膜以增透（或增反）光，求膜的最小厚度，或问反射与透射能量分配】","c":"想到【能量守恒：入射光能量=反射光能量+折射（透射）光能量；增透膜使反射光干涉相消（减弱反射、增强透射，如镜头），$2d=(2k+1)\\cdot\\lambda'/2$，最小厚度 $d=\\lambda'/4$；增反膜使反射光干涉加强（如防蓝光眼镜），$2d=k\\lambda'$，最小厚度 $d=\\lambda'/2$；$\\lambda'$ 均为光在膜中的波长（$\\lambda'=\\lambda/n$）】；警惕【高考中只要题目未明确提到“半波损失”，一律不考虑；最小厚度对应 $k$ 取最小整数（增透 $k=0$，增反 $k=1$），勿把 $\\lambda'/4$ 与 $\\lambda'/2$ 用反】","src":"跳跳物一轮14.2 光的干涉、衍射、偏振_光学模块完结撒花~~_笔记","note":"视频|11:58","orig":"（知识）增反膜、增透膜的作用原理与最小厚度计算。","link":""},{"id":"phy2798","t":"光的衍射·明显衍射条件与图样特征","s":"看到【判断某图样是干涉还是衍射，或问障碍物尺寸、波长如何影响衍射明显程度】","c":"想到【明显衍射条件：障碍物尺度与波长差不多或更小；障碍物越小、波长越大，衍射越明显（单缝越窄中央条纹越宽）；单缝衍射条纹中间宽两边窄、不等距，中央最宽最亮；圆孔衍射为明暗相间同心圆环；圆盘衍射中心有泊松亮斑；可见光中红光衍射最明显、紫光最不明显】；警惕【单缝衍射条纹不等距、双缝干涉条纹等距，勿混淆；泊松亮斑对应圆盘（小圆板）衍射，不是圆孔衍射】","src":"跳跳物一轮14.2 光的干涉、衍射、偏振_光学模块完结撒花~~_笔记","note":"视频|15:19-16:03","orig":"（知识）光的明显衍射条件及单缝、圆孔、圆盘衍射图样的特征。","link":""},{"id":"phy2799","t":"光学现象·生活现象与光学原理的对应","s":"看到【生活现象（光导纤维、海市蜃楼、肥皂泡彩色、泊松亮斑、3D眼镜等）问其光学原理】","c":"想到【全反射→光导纤维、海市蜃楼；双缝干涉→等距条纹；薄膜干涉→肥皂泡彩色、零件验平、增反/增透膜；衍射→中间宽两边窄条纹、泊松亮斑、树叶间彩色光环；偏振→旋转偏振片亮度变化、3D眼镜、偏光太阳镜，偏振证明光是横波（纵波无偏振）】；警惕【海市蜃楼本质是全反射不是普通折射；树叶间光环是小孔衍射不是干涉；偏振片只允许特定方向振动的光通过，旋转 $90^{\\circ}$ 可由亮变暗】","src":"跳跳物一轮14.2 光的干涉、衍射、偏振_光学模块完结撒花~~_笔记","note":"视频|18:07","orig":"（知识）常见光学现象关键词与对应原理速查：全反射、干涉、衍射、偏振。","link":""},{"id":"phy2800","t":"光的干涉·平面镜双缝干涉（洛埃镜模型）","s":"看到【点光源放在平面镜附近，直射光与镜面反射光在屏上叠加，求条纹间距或浸液后变化】","c":"想到【平面镜干涉即洛埃镜模型：S与其虚像 $S'$ 构成一对相干光源，等效双缝间距 $d=SS'=2A$（$A$ 为S到镜面距离），条纹间距 $\\Delta x=l\\lambda/(2A)$；浸入液体后波长变为 $\\lambda/n$（不是 $n\\lambda$），条纹间距变为原来的 $1/n$，条纹变密】；警惕【虚像 $S'$ 到S的距离是S到镜面距离的2倍，勿直接把 $A$ 当双缝间距；介质中波长要除以 $n$，勿乘 $n$】","src":"跳跳物一轮14.2 光的干涉、衍射、偏振_光学模块完结撒花~~_笔记","note":"视频|22:31","orig":"（例）点光源S位于平面镜上方、距镜面 $A$ 处，与镜面平行且相距 $l$ 处放光屏，S发出的光一部分直射光屏、一部分经平面镜反射后射到光屏发生干涉（S与其虚像 $S'$ 等效为双缝）：求条纹间距，并讨论装置浸入折射率为 $n$ 的液体后条纹间距的变化。","link":""},{"id":"phy2801","t":"分子动理论·分子尺度数量级","s":"看到【题目问分子直径或分子质量的数量级，或问热学中原子与分子如何称呼】","c":"想到【分子直径量级为$10^{-10}$ m，分子质量量级为$10^{-26}$ kg；热学中不严格区分原子和分子，统称“分子”】；警惕【两个量级张冠李戴：直径是$10^{-10}$ m、质量才是$10^{-26}$ kg，各自记错一位就丢分】","src":"跳跳物一轮15.1 分子动理论_笔记","note":"视频|00:51","orig":"（知识）分子直径与分子质量的量级是热学常识类判断题考点。","link":""},{"id":"phy2802","t":"分子动理论·球体模型与立方体模型的选用","s":"看到【求分子直径、分子占据体积或分子间平均距离的估算题】","c":"想到【固体和液体用球体模型：分子紧密排列，占据体积等于分子本身体积，可用球体积公式反求直径；气体用立方体模型：每个分子占据一个小立方体，占据体积大于分子本身体积，立方体边长即分子间平均距离】；警惕【气体误用球体模型求直径——气体只研究占据体积，不研究分子本身体积】","src":"跳跳物一轮15.1 分子动理论_笔记","note":"视频|01:25","orig":"（知识）估算分子大小或间距前，必须在球体模型与立方体模型中选对模型。","link":""},{"id":"phy2803","t":"分子动理论·宏观量与微观量的链式换算","s":"看到【已知摩尔质量、密度或总质量，求分子质量、分子占据体积或分子数】","c":"想到【按“从上到下除、从下到上乘”链式换算：总质量÷摩尔数=摩尔质量，摩尔质量÷$N_A$=分子质量；总体积÷摩尔数=摩尔体积，摩尔体积÷$N_A$=分子占据体积；分子数=摩尔数$\\times N_A$，$N_A$是连接宏观与微观的桥梁；密度只用于宏观量（质量与体积）之间换算】；警惕【拿密度去除或乘微观量——密度换不出分子质量、分子占据体积】","src":"跳跳物一轮15.1 分子动理论_笔记","note":"视频|07:04","orig":"（知识）由总质量、摩尔质量、密度等宏观量求分子级微观量的换算套路。","link":""},{"id":"phy2804","t":"分子动理论·扩散布朗运动与分子热运动辨析","s":"看到【判断扩散现象、布朗运动或分子热运动的定义、主体、发生条件的说法正误】","c":"想到【扩散与分子热运动的主体都是分子，布朗运动的主体是宏观悬浮微粒；扩散在气、液、固中都能发生，温度越高越快，0°C也不停止，它是分子热运动的结果，不是化学反应也不是重力或对流；布朗运动只能在液体或气体中发生】；警惕【布朗运动是微粒运动而非分子运动；折线图只是各时刻位置记录的连线，不是运动轨迹；分子热运动光学显微镜看不到】","src":"跳跳物一轮15.1 分子动理论_笔记","note":"视频|10:28","orig":"（知识）扩散现象、布朗运动、分子热运动三者的主体、条件与观察方式辨析。","link":""},{"id":"phy2805","t":"分子动理论·分子速率分布曲线规律","s":"看到【分子速率分布曲线（占比-速率图），问峰值移动、面积含义或占比最多区间】","c":"想到【峰值对应的速率区间分子数占比最多，可代表分子整体运动情况；温度越高峰值越靠右，但只是大部分分子变快，仍有一小部分慢分子；速率很小和很大的分子占比都最低；曲线与横轴围成的面积恒为1，表示所有区间百分比之和为100%】；警惕【温度一升高就认为所有分子速率都变大，或认为不同温度的曲线面积不相等】","src":"跳跳物一轮15.1 分子动理论_笔记","note":"视频|12:44","orig":"（知识）分子速率分布图中峰值、面积、温度的固定规律。","link":""},{"id":"phy2806","t":"分子动理论·同温下不同气体的速率分布与质量关系","s":"看到【同温度下两种气体的速率分布曲线，峰值一左一右，问分子质量或平均速率关系】","c":"想到【温度相同则分子平均动能相同；由平均动能$\\frac{1}{2}mv^2$恒定可知，分子质量越大平均速率越小，峰值越靠左；质量小的气体平均速率大，峰值越靠右】；警惕【认为同温下不同气体平均速率也相同，或把峰值靠左的曲线误判为温度更低】","src":"跳跳物一轮15.1 分子动理论_笔记","note":"视频|28:59","orig":"（知识）同一温度下不同气体分子速率分布曲线峰值位置不同的原因。","link":""},{"id":"phy2807","t":"分子动理论·固体分子直径估算（气凝胶例）","s":"看到【固体物质已知密度$\\rho$和摩尔质量$M$，选分子数、分子体积或分子直径的表达式】","c":"想到【固体用球体模型：摩尔体积=$M/\\rho$，分子占据体积$V_0$=摩尔体积÷$N_A$=$M/(\\rho\\cdot N_A)$，再由球体积公式$V_0=\\frac{4}{3}\\pi(d/2)^3$解得$d=\\sqrt[3]{6M/(\\pi N_A\\rho)}$；求分子数先$a/M$得摩尔数再乘$N_A$】；警惕【分子数漏除摩尔质量写成$a\\cdot N_A$；占据体积分母$\\rho\\cdot N_A$写反；求直径忘开三次方】","src":"跳跳物一轮15.1 分子动理论_笔记","note":"视频|15:53","orig":"（例）某固体气凝胶密度为$\\rho$、摩尔质量为$M$、总质量为$a$，判断分子数、摩尔体积、分子占据体积、分子直径四个表达式的正误。","link":""},{"id":"phy2808","t":"分子动理论·地球大气分子总数与平均间距估算","s":"看到【已知地球半径、大气压强、大气层厚度，估算大气总质量、分子总数或分子平均间距】","c":"想到【用压强联系重力：$p_0\\times$地球表面积$4\\pi R^2$=大气总重力$mg$，得总质量$m=4\\pi R^2 p_0/g$；摩尔数$n=m/M$，分子总数$N=n\\cdot N_A$；平均间距用立方体模型：大气体积$V=4\\pi R^2 h$，单个分子占据体积$V_0=V/(n\\cdot N_A)$，间距$d=\\sqrt[3]{V_0}$】；警惕【气体间距误用球体模型；大气层体积按球壳相减复杂化——$h$远小于$R$时直接用$4\\pi R^2 h$】","src":"跳跳物一轮15.1 分子动理论_笔记","note":"视频|17:52","orig":"（例）地球半径为$R$、大气层厚度为$h$且$h$远小于$R$、地面大气压为$p_0$、空气摩尔质量为$M$，求大气分子总数与分子间平均距离的表达式。","link":""},{"id":"phy2809","t":"内能·温度与分子平均动能的关系","s":"看到【判断温度升高时分子动能的变化，或物体整体运动是否影响分子热运动】","c":"想到【温度是分子平均动能的标志，温度越高平均动能越大；温度升高只是大部分分子动能增大，少数分子可能减小；分子平均动能只取决于分子热运动的平均速率，与物体整体机械运动速度无关】；警惕【认为温度升高每个分子动能都增大，或认为运动快的物体分子平均动能更大】","src":"跳跳物一轮15.2 内能、固体和液体_笔记","note":"视频|00:30","orig":"（知识）温度与分子平均动能、物体机械运动三者的关系。","link":""},{"id":"phy2810","t":"内能·分子力随分子间距的变化规律","s":"看到【比较不同分子间距下的分子力是引力还是斥力，或判断分子力能否忽略】","c":"想到【引力和斥力都随间距$r$增大而减小，但斥力减小得更快；$r=r_0$（约$10^{-10}$ m）为平衡位置，合力为零；$r<r_0$时合力表现为斥力，$r>r_0$时表现为引力；$r>10r_0$时分子力可忽略】；警惕【记反变化快慢：斥力比引力减小得更快；破镜不能重圆是因断面分子间距远超分子力范围，并非分子间没有引力】","src":"跳跳物一轮15.2 内能、固体和液体_笔记","note":"视频|02:11","orig":"（知识）分子间引力、斥力随间距$r$的变化及合力表现。","link":""},{"id":"phy2811","t":"内能·分子势能随间距的变化与最低点","s":"看到【判断分子靠近或远离过程中分子势能的增减，或问势能最小、为负的位置】","c":"想到【以无穷远为零势面：分子从无穷远靠近到$r_0$的过程中分子力表现为引力、做正功，势能一直减小；在$r_0$处分子势能最小且为负值；从$r_0$继续靠近，分子力变为斥力、做负功，势能增大；势能的正负表示大小，正值一定大于负值】；警惕【认为分子间距足够大时势能最小——势能谷底就在$r_0$处，间距很大处势能只是趋于零】","src":"跳跳物一轮15.2 内能、固体和液体_笔记","note":"视频|03:37","orig":"（知识）以无穷远为零势面时，分子势能随间距的变化规律。","link":""},{"id":"phy2812","t":"内能·内能的组成与晶体熔化过程","s":"看到【晶体熔化或冰水同温时，判断温度、分子动能、分子势能与内能的变化】","c":"想到【内能=所有分子总动能+总分子势能，影响因素是温度、质量、体积、物态；晶体熔化时温度不变→分子平均动能不变→分子总动能不变，吸收的热量全部转化为分子总势能，故内能增加】；警惕【认为温度不变内能就不变——0°C的水比0°C的冰内能大；认为吸热一定升温——熔化段热量全部存进分子势能】","src":"跳跳物一轮15.2 内能、固体和液体_笔记","note":"视频|12:52","orig":"（知识）内能的定义、影响因素及晶体熔化过程中内能的变化。","link":""},{"id":"phy2813","t":"固体和液体·单晶体多晶体与非晶体辨析","s":"看到【由熔化曲线有无平台、外形规则、各向异性判断某固体是单晶体、多晶体还是非晶体】","c":"想到【单晶体分子按一定规律排列（题干见此表述即可断定单晶），有规则外形、固定熔点、某些物理性质各向异性；多晶体由许多单晶体杂乱组合，外形不规则、熔点固定、各向同性；非晶体分子完全杂乱，无固定熔点、各向同性；晶体与非晶体在一定条件下可相互转化】；警惕【把玻璃、松香、蜂蜡误当晶体——它们是非晶体；把液晶当晶体或非晶体——液晶介于固液之间，只具光学各向异性】","src":"跳跳物一轮15.2 内能、固体和液体_笔记","note":"视频|10:24","orig":"（知识）晶体（单晶、多晶）与非晶体在排列、外形、熔点、各向异性上的区别。","link":""},{"id":"phy2814","t":"固体和液体·液体表面张力的成因与方向","s":"看到【水面托住水黾、液滴呈球形、液桥等现象，问表面张力的成因或方向】","c":"想到【表面层分子间距大于$r_0$，分子间作用力表现为引力，使液面绷紧并趋向收缩成表面积最小的球形；表面张力方向与液面相切、与分界面垂直】；警惕【认为表面张力垂直于液面；认为玻璃板难拉离水面是表面张力——那是玻璃分子与水分子间的引力（浸润现象）】","src":"跳跳物一轮15.2 内能、固体和液体_笔记","note":"视频|14:10","orig":"（知识）液体表面张力的微观成因与方向判定。","link":""},{"id":"phy2815","t":"固体和液体·浸润不浸润与毛细现象","s":"看到【细管中液面上升或下降，问浸润不浸润的判断或毛细现象的影响因素】","c":"想到【浸润：液面下凹、细管内液面上升，液体与管壁分子作用力大于液体分子间作用力，附着层分子拥挤表现为斥力；不浸润：液面上凸、细管内液面下降，液体与管壁作用力较小，附着层稀疏表现为引力；管内径越细毛细现象越明显】；警惕【认为只有液面上升才叫毛细现象——下降同样是；锄松土壤是破坏毛细管防止水分蒸发，不是为了引水上来】","src":"跳跳物一轮15.2 内能、固体和液体_笔记","note":"视频|15:55-17:34","orig":"（知识）浸润与不浸润的液面形状、微观解释及毛细现象的升降规律。","link":""},{"id":"phy2816","t":"内能·f-r图与Ep-r图综合分析套路","s":"看到【给出分子力-间距或分子势能-间距图像，分析力、势能、动能变化或最小间距】","c":"想到【两步法：先找$r_0$——f-r图看图线与横轴交点，Ep-r图看曲线最低点；再补画出另一张图辅助分析。只有分子力做功时分子动能与势能之和守恒，势能减则动能增；f-r图线与横轴围成的面积等于分子力做的功，横轴上方正功、下方负功，用动能定理比较两块面积可确定最小间距位置】；警惕【两张图的$r_0$没对齐就下结论；分子有初速度时最小间距不在$r_0$处，需比面积判断】","src":"跳跳物一轮15.2 内能、固体和液体_笔记","note":"视频|18:38","orig":"（例）分子$a$固定，分子$b$从间距$R_4$处以初速度向$a$运动，题给f-r图与Ep-r图，判断运动中分子力性质、分子力大小变化、势能动能变化及最小间距。","link":""},{"id":"phy2817","t":"气体的压强·微观解释与决定因素","s":"看到【问气体压强产生的微观原因，或判断体积、温度变化如何影响压强】","c":"想到【气体压强是大量分子频繁碰撞器壁、产生持续稳定的压力形成的，由单位时间、单位面积撞击器壁的次数和单个分子平均碰撞力共同决定；撞击次数受体积（越小分子越密）和温度（越高运动越剧烈）影响，平均碰撞力只由温度决定；根本因素是体积和温度，体积越小、温度越高压强越大】；警惕【把压强增大归因于分子间斥力——气体分子间距大，压强与分子间作用力无关】","src":"跳跳物一轮15.3 气体的压强、理想气体、热力学定律_祝大家五一_笔记","note":"视频|00:29-01:47","orig":"（知识）气体压强的产生原因及由哪两个微观量决定。","link":""},{"id":"phy2818","t":"理想气体·模型与内能只由温度决定","s":"看到【判断理想气体的分子势能、内能变化，或何条件下气体不能视为理想气体】","c":"想到【理想气体忽略分子间作用力，分子势能为零，内能=分子总动能；一定质量理想气体的内能只由温度决定，温度是内能变化的标志：温度升则内能增，温度降则内能减；高中阶段无特殊说明，气体一律默认为理想气体】；警惕【认为分子小就永远是理想气体——体积被压缩到很小时分子间距变小、分子力不可忽略，不能再视为理想气体】","src":"跳跳物一轮15.3 气体的压强、理想气体、热力学定律_祝大家五一_笔记","note":"视频|02:07-03:57","orig":"（知识）理想气体模型及其内能与温度的关系。","link":""},{"id":"phy2819","t":"理想气体·热力学温度与摄氏温度换算","s":"看到【摄氏温度参与气体计算，或问绝对零度、开尔文与摄氏度的关系】","c":"想到【热力学温度$T$以绝对零度为0 K，单位开尔文；换算式$T=t+273.15$，做题简化为加273；温度变化1 K等于变化1°C，两温标每一度大小相同，只是零点不同】；警惕【把摄氏温度直接代入状态方程——必须先加273化成热力学温度；但只求温度变化量时1°C与1 K可直接通用】","src":"跳跳物一轮15.3 气体的压强、理想气体、热力学定律_祝大家五一_笔记","note":"视频|04:17","orig":"（知识）热力学温标的定义及与摄氏温度的换算。","link":""},{"id":"phy2820","t":"理想气体·理想气体状态方程","s":"看到【一定质量气体两个状态间$p$、$V$、$T$的换算或比较】","c":"想到【$pV/T=C$：$C$与压强、体积、温度无关，与气体质量成正比；一定质量理想气体$C$不变，两状态列$p_1V_1/T_1=p_2V_2/T_2$联立求解；三大气体实验定律（玻意耳、查理、盖-吕萨克）都可由它替代，无需单独记】；警惕【温度代入摄氏度——$T$必须用热力学温度；气体质量变化时$C$随之变化，不能再按恒定$C$列式】","src":"跳跳物一轮15.3 气体的压强、理想气体、热力学定律_祝大家五一_笔记","note":"视频|05:27","orig":"（知识）理想气体状态方程的内容与使用要点。","link":""},{"id":"phy2821","t":"热力学第一定律·公式与正负号系统","s":"看到【气体经历等容、等温、绝热或导热过程，判断$W$、$Q$、$\\Delta U$的正负】","c":"想到【$\\Delta U=Q+W$：$Q$吸热为正、$W$是外界对气体做的功；体积增大→$W<0$，体积减小→$W>0$，恒容→$W=0$；温度升高→$\\Delta U>0$，温度降低→$\\Delta U<0$，恒温→$\\Delta U=0$；绝热→$Q=0$，此时$\\Delta U=W$】；警惕【把$W$当气体对外界做的功（符号全反）；导热良好时气体温度始终等于外界温度，别漏看这一隐含条件】","src":"跳跳物一轮15.3 气体的压强、理想气体、热力学定律_祝大家五一_笔记","note":"视频|07:04","orig":"（知识）热力学第一定律$\\Delta U=Q+W$的符号规定及常见条件的翻译。","link":""},{"id":"phy2822","t":"热力学第一定律·与状态方程综合的分析路径","s":"看到【给出气体某过程的变化（如升温、放气、压缩），要求判断$Q$、$W$、$\\Delta U$或$p$的正负】","c":"想到【问$Q$必用热力学第一定律$\\Delta U=Q+W$；问$p$必用状态方程$pV/T=C$；问$T$或$\\Delta U$走双路径：先用状态方程定$T$增减再定$\\Delta U$正负，或先用热一律定$\\Delta U$再反推$T$；问$V$或$W$同理：先由状态方程定$V$再定$W$正负，或先由热一律定$W$再反推$V$】；警惕【只盯一个方程硬凑——两个工具各管一部分量需联合使用；忘记$V$增必$W<0$、$T$升必$\\Delta U>0$这些对应关系】","src":"跳跳物一轮15.3 气体的压强、理想气体、热力学定律_祝大家五一_笔记","note":"视频|10:41","orig":"（知识）已知$p$、$V$、$T$、$\\Delta U$、$Q$、$W$中某几个的变化，求其余量的分析路径。","link":""},{"id":"phy2823","t":"热力学定律·第二定律与第三定律表述","s":"看到【判断热传递方向、第二类永动机、绝对零度或熵的说法正误】","c":"想到【克劳修斯表述：热量不能自发地从低温物体传到高温物体；开尔文表述：不可能从单一热库吸收热量使之完全变成功而不产生其他影响；本质是热运动具有方向性，气体向真空自由膨胀等宏观热过程不可逆；第三定律：绝对零度不可能达到】；警惕【表述漏掉“自发地”三个字即错；第二类永动机违背的是第二定律而非能量守恒；孤立系统总熵只会增大或不变】","src":"跳跳物一轮15.3 气体的压强、理想气体、热力学定律_祝大家五一_笔记","note":"视频|13:14-14:08","orig":"（知识）热力学第二定律两种表述、第三定律及过程方向性问题。","link":""},{"id":"phy2824","t":"理想气体·变质量问题的密度比例法","s":"看到【容器放气或充气导致气体质量变化，求密度或压强】","c":"想到【变质量过程不能把$C$当常数，但$C=pV/T$与质量成正比；容积不变时密度与质量、与$C$都成正比：等压升温放气，密度与热力学温度成反比；等温放气降压，密度与压强成正比，按比例式连乘即可】；警惕【用$p_1V_1/T_1=p_2V_2/T_2$硬套变质量过程——质量变化时$C$不守恒；漏用“气体体积始终等于容器容积”这一隐含条件】","src":"跳跳物一轮15.3 气体的压强、理想气体、热力学定律_祝大家五一_笔记","note":"视频|16:00","orig":"（例）高压舱容积不变，初始压强$p_0$=1.2 atm、温度$T_0$=17°C、密度$\\rho_0$=1.46 kg/m$^3$，先升温至27°C并放出气体保持压强不变，再保持300 K释放气体把压强降到1.0 atm，求两次释放后的气体密度。","link":""},{"id":"phy2825","t":"理想气体图像·三图通用箭头判读规则","s":"看到【$p$-$T$、$v$-$T$ 或 $p$-$V$ 图上标着箭头，问某状态量的变化情况】","c":"想到【箭头尾部是变化前状态、尖部是变化后状态；箭头垂直哪个坐标轴，该轴的物理量就不变：垂直 $p$ 轴等压、垂直 $T$ 轴等温、垂直 $V$ 轴等容；箭头斜穿坐标系时两个量同时在变】；警惕【默认研究对象是一定质量的理想气体，若过程涉及充放气，$\\frac{pV}{T}=C$ 中的 $C$ 不再恒定，此法失效】","src":"跳跳物一轮15.4 理想气体图像问题、变质量问题_笔记","note":"视频|01:35","orig":"（知识）理想气体 $p$-$T$、$v$-$T$、$p$-$V$ 三种图像中，过程用箭头表示，核心依据是一定质量气体满足 $\\frac{pV}{T}=C$ 恒定。","link":""},{"id":"phy2826","t":"理想气体图像·p-T图与v-T图割线法判间接量","s":"看到【$p$-$T$ 图问体积怎么变，或 $v$-$T$ 图问压强怎么变】","c":"想到【$p$-$T$ 图中 $V=C\\cdot\\frac{T}{p}$，割线斜率倒数 $\\frac{T}{p}$ 与体积成正比，割线越平缓体积越大；$v$-$T$ 图中 $p=C\\cdot\\frac{T}{V}$，割线斜率倒数 $\\frac{T}{V}$ 与压强成正比，割线越平缓压强越大；两图中过原点的直线分别表示等容变化和等压变化】；警惕【若题目给的是 $T$-$p$ 图（横轴 $p$、纵轴 $T$），割线斜率本身就是 $\\frac{T}{p}$，直接看斜率即可，不要死记『看斜率的倒数』】","src":"跳跳物一轮15.4 理想气体图像问题、变质量问题_笔记","note":"视频|03:10-07:53","orig":"（知识）$p$-$T$ 图中间接量是体积，$v$-$T$ 图中间接量是压强，都要借助割线（图线上的点与坐标原点的连线）分析。","link":""},{"id":"phy2827","t":"理想气体图像·p-V图矩形面积判温度","s":"看到【$p$-$V$ 图上的过程，问温度或内能如何变化】","c":"想到【$T=\\frac{pV}{C}$，过某点作两轴垂线围成的矩形面积 $S=p\\times V$ 代表该点 $pV$ 乘积：矩形面积增大温度升高、减小温度降低；反比例函数图线（$pV=K$ 恒定）代表等温过程】；警惕【判温度的『矩形面积』与判做功的『图线与横轴围成的面积』是两回事，混用必错】","src":"跳跳物一轮15.4 理想气体图像问题、变质量问题_笔记","note":"视频|08:51","orig":"（知识）$p$-$V$ 图中间接量是温度，用过图线上某点向两坐标轴作垂线围成的矩形面积来判断。","link":""},{"id":"phy2828","t":"理想气体图像·p-V图线下面积表示做功","s":"看到【$p$-$V$ 图中问气体做功多少，或比较两次过程做功的大小】","c":"想到【把气体想象装在底面积为 1 $\\mathrm{m^2}$ 的气缸里，$p$-$V$ 图就转化为 $F$-$x$ 图，图线与横轴围成的面积等于外界对气体做功的绝对值 $|W|$；比较两次变化直接比图线下面积，面积大的 $W$ 大，无需纠结是外界对气体还是气体对外界做功（两者绝对值相等）】；警惕【面积只给做功的大小，正负仍由体积增减定：体积增大外界做负功，$W$ 取负值】","src":"跳跳物一轮15.4 理想气体图像问题、变质量问题_笔记","note":"视频|08:51","orig":"（知识）$p$-$V$ 图中图线与横轴围成的面积表示外界对气体做功的多少。","link":""},{"id":"phy2829","t":"理想气体图像·ΔU、W、Q正负判断流程","s":"看到【已知气体图像上的某段过程，问吸热放热或内能增减】","c":"想到【先看温度定 $\\Delta U$：温度升高为正、降低为负；再看体积定 $W$（外界对气体做功）：体积增大 $W$ 为负、体积减小 $W$ 为正；最后代入 $\\Delta U=W+Q$ 解出 $Q$ 的正负】；警惕【$W$ 的正负按『外界对气体』约定，与『气体对外界做功』互为相反数；等温过程 $\\Delta U=0$，此时 $Q=-W$】","src":"跳跳物一轮15.4 理想气体图像问题、变质量问题_笔记","note":"视频|15:18-16:26","orig":"（知识）图像题中判断内能变化、做功和吸放热的正负，配合热力学第一定律 $\\Delta U=W+Q$ 使用。","link":""},{"id":"phy2830","t":"变质量问题·充放气方程与体积恒等于容器容积","s":"看到【向容器充气或从容器放气、抽气，温度不变，求压强或体积】","c":"想到【充气满足『原有 $pV$ + 充入 $pV$ = 充气后 $pV$』；放气满足『原有 $pV$ − 放出 $pV$ = 放气后 $pV$』；容器中气体的体积始终等于容器的容积：钢瓶等刚性容器充放气前后容积不变，气球等可变容器充气后容积增大】；警惕【放掉一部分气体后，剩余气体仍扩散填满整个容器，体积不变而压强变小，不要误以为剩余气体的体积变小了】","src":"跳跳物一轮15.4 理想气体图像问题、变质量问题_笔记","note":"视频|17:00-18:11","orig":"（知识）温度不变的充气、放气问题是变质量问题，用 $pV$ 守恒列方程。","link":""},{"id":"phy2831","t":"变质量问题·抽气压强关系与n次抽气通项","s":"看到【抽气装置反复抽气，已知容器容积 $V_0$、抽气气室容积 $V_1$，问第 $n$ 次抽气后的压强】","c":"想到【每次抽气满足『抽出气体的压强 = 抽气后剩余气体的压强』（连通后两部分压强相等，再隔离排出）；等温下第 $n$ 次抽气后 $p_N=\\left(\\frac{V_0}{V_0+V_1}\\right)^{n}p_0$，压强按固定比例逐次递减】；警惕【每次抽气都是独立的一次等温放气，须逐次连乘，不能把 $n$ 次抽气合并成一次大抽气来算；连接细管的体积忽略不计】","src":"跳跳物一轮15.4 理想气体图像问题、变质量问题_笔记","note":"视频|19:45-22:01","orig":"（知识）用抽气装置（两阀门加活塞）反复抽气时，每次抽出的气体压强等于抽气后容器内剩余气体的压强。","link":""},{"id":"phy2832","t":"变质量问题·变温漏气的质量比结论","s":"看到【容器漏气且温度同时变化，求剩余或泄漏气体的质量之比】","c":"想到【同种气体质量之比等于 $\\frac{pV}{T}$ 之比，容积不变时即 $\\frac{p}{T}$ 之比：$M_2/M_1=\\frac{p_2/T_2}{p_1/T_1}=\\frac{6.5\\times10^6/260}{8.7\\times10^6/290}=\\frac{5}{6}$，故泄漏占 $\\frac{1}{6}$；不漏气时按等容过程 $\\frac{p}{T}$ 为定值求末态压强】；警惕【直接研究泄漏出的气体很困难，应转而研究剩余气体与原气体之比；温度必须用热力学温度 K 代入】","src":"跳跳物一轮15.4 理想气体图像问题、变质量问题_笔记","note":"视频|48:19","orig":"（例）容积不变的氧气瓶内充有 17°C（290 K）、$8.7\\times10^6$ Pa 的氧气，移到 -13°C（260 K）的室外。（1）若不漏气，求此时瓶内压强；（2）若稳定后实测压强为 $6.5\\times10^6$ Pa，求泄漏气体与泄漏前气体的质量之比。","link":""},{"id":"phy2833","t":"气缸问题·外界力定义与压强关系判定","s":"看到【气缸中气体状态变化前后活塞均静止，问前后气体压强是否相等】","c":"想到【活塞静止合力为零，外界力的合力与缸内气体压力 $pS$ 等大反向：外界力不变则气体压强相等；外界力变了（多出插销弹力、压上重物等）则压强不相等；外界力还有一大用途——其合力做的功就是外界对气体做的功】；警惕【受力对象是活塞而不是气体；别漏掉新增的外力（插销、重物），它们正是压强变化的原因】","src":"跳跳物一轮15.5 气缸问题_笔记","note":"视频|01:02-02:19","orig":"（知识）气缸问题中『外界力』指活塞受到的、除缸内气体压力之外的所有力（外部大气压力、活塞重力、插销弹力、重物压力等）。","link":""},{"id":"phy2834","t":"气缸问题·气缸三连求pVT","s":"看到【气缸内气体经历状态变化，已知部分量求压强、体积或温度】","c":"想到【第一步看不变：判断 $p$、$V$、$T$ 哪个不变，压强是否不变用外界力结论判断；第二步列气体方程 $\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}$，按第一步约掉不变量；第三步按需列活塞合力为零的方程补充条件】；警惕【第三步非必须，气体方程已能解出时不必列；列活塞方程要选已知量多、能直接解出未知量的那个状态】","src":"跳跳物一轮15.5 气缸问题_笔记","note":"视频|07:56","orig":"（知识）求气缸中一定质量理想气体变化前后的 $p$、$V$、$T$，用『气缸三连』按顺序求解。","link":""},{"id":"phy2835","t":"气缸问题·外界力合力做功与热一律求Q","s":"看到【活塞移动了一段位移，求外界对气体做功或气体吸放热】","c":"想到【外界力合力恒定时 $W=F\\cdot x\\cdot\\cos\\theta$（$F$ 为外界力合力，$\\theta$ 为其与活塞位移的夹角）；求出 $W$ 后代入 $\\Delta U=Q+W$，解出 $Q$ 的正负与大小】；警惕【外界力合力方向与活塞位移相反时 $W$ 为负（如活塞上移而大气压力、重力向下）；热一律中的 $W$ 恒指外界对气体做的功，与气体对外界做功互为相反数】","src":"跳跳物一轮15.5 气缸问题_笔记","note":"视频|09:38-12:11","orig":"（知识）气缸问题中外界对气体做的功 $W$ 等于外界力的合力对活塞做的功，求出后再用热力学第一定律定 $\\Delta U$ 和 $Q$。","link":""},{"id":"phy2836","t":"理想气体·向真空自由膨胀的结论","s":"看到【抽取隔板后气体向真空扩散，问温度、内能或分子平均动能的变化】","c":"想到【向真空膨胀不受阻力，$W=0$；容器绝热 $Q=0$；由 $\\Delta U=Q+W=0$ 内能不变，理想气体内能只由温度决定，故温度不变、分子平均动能不变；该过程不可逆（热力学第二定律）】；警惕【自由膨胀不是准静态过程，不能用等温过程公式算做功；『体积增大但温度不变』并不矛盾】","src":"跳跳物一轮15.5 气缸问题_笔记","note":"视频|19:02","orig":"（知识）绝热容器中气体向真空（隔板另一侧为真空）自由膨胀时的做功与内能结论。","link":""},{"id":"phy2837","t":"气缸问题·恰好离开卡销的临界条件","s":"看到【活塞被卡销挡住，问支持力大小或『恰好离开卡销』时的温度】","c":"想到【活塞停在某处被卡住时，列含卡销支持力的平衡方程求 $N$；『恰好离开卡销』的临界条件是支持力为零，此时由气体压力、大气压力和外力的平衡先解出末态压强，再对被卡销锁住（体积不变）的一段用查理定律 $\\frac{p}{T}$ 为定值求温度（本题 $N=100$ N、$T_2\\approx327$ K）】；警惕【活塞被卡销锁住期间体积不变是等容过程，别当等压处理；轻质活塞自身重力不计】","src":"跳跳物一轮15.5 气缸问题_笔记","note":"视频|12:30","orig":"（例）竖直气缸中轻质活塞（面积 100 $\\mathrm{cm^2}$）初始停在卡销 a 处，缸内气体与大气同温同压（300 K、$1.0\\times10^5$ Pa），几何关系 $BC=10AB$。先用竖直向下的恒力 $F=200$ N 把活塞缓慢压到卡销 b（此过程等温），求卡销 b 对活塞的支持力 $N$；再保持 $F$ 不变加热气体，求活塞恰好离开卡销 b 时的温度。","link":""},{"id":"phy2838","t":"气缸问题·抽气后变质量部分的压强求法","s":"看到【隔开的两部分气体有一部分被抽走或泄漏，求各自的压强】","c":"想到【质量不变的 A 直接用玻意耳定律，由总体积守恒定 A 的末态体积；质量变化的 B 用 $pV=nRT$，等温下 $pV\\propto$ 物质的量 $n$，抽走一半则 $n$ 减半，按倍数关系列式（本题 $p_A=\\frac{4}{5}p_0$、$p_B=\\frac{2}{3}p_0$）；最后对隔板受力分析，配合 $\\Delta V=S\\cdot\\Delta x$ 和胡克定律求劲度系数】；警惕【B 的质量变了不能直接套 $p_1V_1=p_2V_2$；隔板移动的位移要用体积变化量除以横截面积反推】","src":"跳跳物一轮15.5 气缸问题_笔记","note":"视频|29:03","orig":"（例）温度不变的刚性容器被连着弹簧的隔板分成 A、B 两部分，初始体积均为 $Sl$（$l$ 为长度、$S$ 为横截面积）、压强均为 $p_0$，弹簧处于原长。现将 B 中气体抽走一半，稳定后 B 的体积变为原来的 $\\frac{3}{4}$，求抽气后 A、B 内气体的压强和弹簧的劲度系数。","link":""},{"id":"phy2839","t":"气缸问题·差压阀先假设后验证","s":"看到【差压阀/单向阀连接两团气体，温度变化，求压强或需判断阀门开闭】","c":"想到【先假设阀门关闭、A 与 B 独立变化：A 的活塞与大气连通故 A 内压强恒为 $p_0$，B 体积不变用查理定律；算完验证压强差 $p_A-p_B$ 是否不超过 $\\Delta p$，满足则假设成立（本题 $p_{B2}=0.9\\times10^5$ Pa）；若要求阀门恰好关闭，对应压强差恰等于 $\\Delta p$，再由活塞平衡求外加重物质量】；警惕【不验证假设就下结论；导热良好意味着气体温度始终等于环境温度】","src":"跳跳物一轮15.5 气缸问题_笔记","note":"视频|38:07","orig":"（例）导热良好的气缸 A、B 间装差压阀：A 内压强减 B 内压强大于 $\\Delta p$ 时阀门打开、气体从 A 流入 B，否则关闭。A 上方是与大气连通的轻质活塞（面积 0.10 $\\mathrm{m^2}$），B 体积不变。初态 $T_1=300$ K，$V_{A1}=4.0\\times10^{-2}$ $\\mathrm{m^3}$，$p_{B1}=p_0=1.0\\times10^5$ Pa，$\\Delta p=0.11p_0$。环境温度降到 270 K，求此时 B 内压强；再问降温后往 A 的活塞上倒多少铁砂，能使 B 内压强恰好回到 $p_0$。","link":""},{"id":"phy2840","t":"液柱问题·液柱方程与连通条件","s":"看到【U 形管或直管中液柱封闭着一段气体，求气体压强或液面高度差】","c":"想到【液柱方程为 p上+$\\rho$gh=p下：竖直方向较高的液面是上液面、较低的是下液面；$h$ 是上下液面竖直方向的高度差，不一定等于液柱长度；研究对象是被液柱封闭的气体而非液柱本身】；警惕【上下液面之间的液柱必须连通，中间隔有气柱时不能直接用此方程，需分段分析；液柱底面只与大气接触时，该大气接触面也是下液面】","src":"跳跳物一轮15.6 液柱计算类问题、液柱移动问题_热学模块完结撒_笔记","note":"视频|01:12-02:45","orig":"（知识）被液柱封闭的理想气体，其压强用液柱方程 p上+$\\rho$gh=p下 联系上下液面。","link":""},{"id":"phy2841","t":"液柱问题·液柱三连求pVT","s":"看到【液柱封闭的气体经历状态变化，求变化前后的压强、体积或温度】","c":"想到【第一步看不变：判断 $p$、$V$、$T$ 哪个不变，压强不变常由液柱方程中大气压和液面高度差都不变推出；第二步列气体方程 $\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}$ 并约掉不变量；第三步按需列液柱方程 p上+$\\rho$gh=p下，建立压强与液面高度差的关系】；警惕【第三步非必须，气体方程已能解出目标量时不必列；研究对象是被封闭的气体，别错选成液柱】","src":"跳跳物一轮15.6 液柱计算类问题、液柱移动问题_热学模块完结撒_笔记","note":"视频|06:26","orig":"（知识）求被液柱封闭气体变化前后的 $p$、$V$、$T$，用『液柱三连』按顺序求解。","link":""},{"id":"phy2842","t":"液柱问题·cmHg与mmHg单位处理","s":"看到【题目压强给的是 cmHg 或 mmHg，液柱是水银或其他液体】","c":"想到【气体方程可直接代入这些数值，无需换算；液柱方程中若液柱是水银，$\\rho gh$ 直接替换为 $h$，单位与压强单位对应（压强用 cmHg 则 $h$ 用 cm）；液柱是其他液体、或要用 $F=pS$ 算力时，必须先换成帕斯卡（$10^5$ Pa $=75$ cmHg $=750$ mmHg，以题目给定值为准）】；警惕【非水银液柱的 $\\rho gh$ 与 cmHg 不能直接混算；用压强乘面积求力时忘换 Pa 会差好几个数量级】","src":"跳跳物一轮15.6 液柱计算类问题、液柱移动问题_热学模块完结撒_笔记","note":"视频|07:49","orig":"（知识）压强单位用 cmHg 或 mmHg 时，气体方程、液柱方程、压力公式的代入规则不同。","link":""},{"id":"phy2843","t":"液柱移动·温度不变试管移动的假设法","s":"看到【温度不变，玻璃管或试管整体上提、下插，问液面高度差怎么变】","c":"想到【三步假设法：先假设液面高度差 $h$ 不变，分析移动后封闭气体体积的变化；再由温度不变的 $pV=C$，从体积增减推出压强增减；最后代入液柱方程 $p+\\rho gh=p_0$（$p_0$ 不变）反推 $h$ 的实际变化】；警惕【忽略试管壁对液柱的粘滞力，液柱高度变化仅由压强差决定；不要想当然直接断定 $h$ 不变，必须走完三步】","src":"跳跳物一轮15.6 液柱计算类问题、液柱移动问题_热学模块完结撒_笔记","note":"视频|12:43","orig":"（知识）温度不变、玻璃管（试管）整体移动时，判断液面高度差变化的通用方法。","link":""},{"id":"phy2844","t":"液柱问题·水平管转竖直的三问套路","s":"看到【水平玻璃管缓慢转到竖直，问吸放热、气柱长度，或再升温求长度】","c":"想到【缓慢旋转近似等温，$\\Delta U=0$；竖直后水银柱压着气柱，气柱变短、体积减小、外界对气体做正功，故气体放热。竖直状态压强由液柱方程直接算：$p_1=76+19=95$ cmHg，玻意耳定律 $76\\times25=95\\times L'$ 得 $L'=20$ cm。升温时水银柱高度不变、大气压不变，故压强不变（等压过程），用 $\\frac{V}{T}$ 为定值，得 $L''=24$ cm】；警惕【判断吸放热先定 $\\Delta U$ 再定 $W$，别只看体积变化；第三问是等压不是等容，压强不变的根源是液面高度差不变】","src":"跳跳物一轮15.6 液柱计算类问题、液柱移动问题_热学模块完结撒_笔记","note":"视频|21:19","orig":"（例）水平放置的足够长玻璃管，用 19 cm 水银柱封闭 25 cm 长空气柱（理想气体），大气压 76 cmHg、温度 300 K。将管缓慢顺时针旋转至竖直（开口向上，水银柱在气柱下方）：（1）判断气体吸热还是放热；（2）求竖直时空气柱长度；（3）保持竖直再升温到 360 K，求空气柱长度。","link":""},{"id":"phy2845","t":"液柱问题·多管注水银的初态选取","s":"看到【三管连通灌水银，封闭气体被压缩，求各管水银柱高度或高度差】","c":"想到【初态选『水银刚封闭气体』的时刻，此时气体压强仍为大气压 $p_0$、体积为整管长乘横截面积；末态对每管分别联立玻意耳定律与液柱方程（以开口 C 管液面为上液面）；本题解得 B 管水银柱 2 cm、A 管 1 cm，高度差 1 cm】；警惕【初态选错则方程全错；各液面的高度差要逐管核对，别把管长当成水银柱长度】","src":"跳跳物一轮15.6 液柱计算类问题、液柱移动问题_热学模块完结撒_笔记","note":"视频|27:49","orig":"（例）粗细均匀的 A、B、C 三管下端连通，A 管（长 13.5 cm）、B 管（长 32 cm）上端封闭，C 管上端开口与大气相通。从 C 管灌入水银，恰好灌到 A、B 管下端时气体开始被封闭，继续灌至 B、C 管内水银面高度差为 5 cm。大气压 75 cmHg，求 A、B 管内水银柱的高度差。","link":""},{"id":"phy2846","t":"液柱问题·U形管液面等高与注入水银","s":"看到【U 形管问液面等高时的温度，或从开口注入水银求注入量】","c":"想到【液面等高时封闭气体压强等于大气压（75 cmHg），且水银总量守恒：一管液面降多少另一管就升多少，气柱长度变化对应两端液面变化之和；本题等高时气柱 $20-5=15$ cm，由气态方程得温度 202.5 K。注水银时先等温玻意耳算新压强 89.5 cmHg，再由液柱方程定右管液面上升 5.5 cm，注入长度$=$两管液面上升量之和 6.5 cm】；警惕【等高不等于回到初态，压强要按大气压重算；注入水银长度是左右两管液面上升量之和，不是单管的变化量】","src":"跳跳物一轮15.6 液柱计算类问题、液柱移动问题_热学模块完结撒_笔记","note":"视频|41:24","orig":"（例）竖直 U 形管粗细均匀，左端封闭、右端开口，左管内被水银封闭的气柱长 20 cm，右管水银面比左管高 10 cm，大气压 75 cmHg、初温 306 K。（1）缓慢降温至左右水银面等高，求此时温度；（2）在初温下从右管缓慢注入水银，当左管水银面上升 1 cm 时，求注入水银柱的长度。","link":""},{"id":"phy2847","t":"液柱移动·玻璃管上提下插的判定","s":"看到【托里拆利式玻璃管上提或下插，判断管内外水银面高度差的变化】","c":"想到【上提：假设 $h$ 不变，则气柱变长、体积增大，等温下压强减小，由 $p+\\rho gh=p_0$（$p_0$ 不变）得 $h$ 实际增大；下插：封闭气体可压缩但不能压缩为零，管内水银面必在管顶下方、管顶与管外水银面之间必有气柱，故管内外高度差必小于管顶与管外水银面的高度差（70 cm）】；警惕【上提管子不能想当然认为 $h$ 不变，必须走『假设—矛盾—修正』三步；下插时漏想『封闭气体占体积』会误判为高度差等于 70 cm】","src":"跳跳物一轮15.6 液柱计算类问题、液柱移动问题_热学模块完结撒_笔记","note":"视频|47:07","orig":"（例）长约 1 m 的玻璃管开口向下插入水银槽（托里拆利式），水银柱上方封闭一段气体，管内外水银面高度差 $h=72$ cm，大气压 76 cmHg。判断：（1）将管稍微上提，$h$ 如何变化；（2）将管下插至管顶与管外水银面高度差为 70 cm 时，管内外水银面高度差与 70 cm 的大小关系。","link":""},{"id":"phy2848","t":"光电效应·光电效应方程与截止频率","s":"看到【金属发生光电效应，求最大初动能、逸出功或截止频率之间的换算】","c":"想到【光子能量 $h\\nu$ 一部分用于克服逸出功 $W_0$，剩余为最大初动能，$E_K=h\\nu-W_0$；恰好发生时 $h\\nu_C=W_0$，即 $\\nu_C=W_0/h$；逸出功与截止频率都只与金属材质有关，是金属的固有属性，与照射光及外界条件无关】；警惕【频率低于截止频率时，无论光强多大、照射多久都不发生光电效应；逸出功和截止频率不随照射光改变】","src":"跳跳物一轮16.1 光电效应_笔记","note":"视频|02:54-04:46","orig":"（知识）光电效应方程，以及截止频率与逸出功的关系。","link":""},{"id":"phy2849","t":"光电效应·遏止电压的定义与计算","s":"看到【光电管加反向电压使光电流恰好减小为零，求遏止电压或最大初动能】","c":"想到【遏止电压是使光电流恰好为零的反向电压；对光电子从阴极到阳极用动能定理 $0-E_K=-eU_C$，得 $E_K=eU_C$；照射光频率越大，最大初动能越大，遏止电压也越大，$U_C=(h\\nu-W_0)/e$】；警惕【遏止电压只由频率和金属（逸出功）决定，与光强无关；增大光强遏止电压不变】","src":"跳跳物一轮16.1 光电效应_笔记","note":"视频|09:38","orig":"（知识）遏止电压的定义及其与最大初动能的关系。","link":""},{"id":"phy2850","t":"光电效应·光强与饱和光电流","s":"看到【增大光强或改变频率，问饱和光电流、单位时间光子数如何变化】","c":"想到【光强 $P=Nh\\nu$（$n$ 为单位时间内发出的光子数）；改变光强默认频率不变，只改变光子数 $n$；饱和光电流 $I_M$ 等于单位时间从阴极逃逸的光电子所带电荷量，只由光强决定；频率相同时光强大则 $I_M$ 大，光强相同时频率大则光子数少、$I_M$ 小】；警惕【光强相同的两束光若频率不同，频率高的光子数少、饱和光电流反而小，并非相同】","src":"跳跳物一轮16.1 光电效应_笔记","note":"视频|12:24-15:21","orig":"（知识）光强的本质，以及饱和光电流的决定因素。","link":""},{"id":"phy2851","t":"光电效应·各变量对特征量的影响","s":"看到【光电效应中改变频率、光强、电压或照射时间，判断各特征量是否变化】","c":"想到【能否发生光电效应与最大初动能只由频率决定；是否有光电流由频率和电压共同决定；光电流大小受电压和光强影响；饱和光电流只由光强决定；逸出功和截止频率是金属固有属性，不受任何外部因素影响；照射时间对任何特征量都没有影响】；警惕【频率不影响光电流大小（类比水管流量），光强不影响频率相关量（能否发生、最大初动能、遏止电压）】","src":"跳跳物一轮16.1 光电效应_笔记","note":"视频|16:23","orig":"（知识）频率、光强、电压、照射时间分别决定光电效应的哪些特征量。","link":""},{"id":"phy2852","t":"光电效应·Ek-v图与Uc-v图","s":"看到【$E_K$-$\\nu$ 或 $U_C$-$\\nu$ 图像，由斜率、横截距、纵截距求物理量】","c":"想到【两图都是倾斜向上的直线：$E_K$-$\\nu$ 图满足 $E_K=h\\nu-W_0$，斜率为普朗克常量 $h$，纵截距绝对值为逸出功 $W_0$；$U_C$-$\\nu$ 图满足 $U_C=(h/e)\\nu-W_0/e$，斜率为 $h/e$，纵截距绝对值为 $W_0/e$；两图横截距都是截止频率 $\\nu_C$】；警惕【两图斜率不同、纵截距含义不同，勿张冠李戴；频率低于横截距时不发生光电效应，无图线也无动能】","src":"跳跳物一轮16.1 光电效应_笔记","note":"视频|20:55","orig":"（知识）最大初动能—频率图与遏止电压—频率图的图像特征对比。","link":""},{"id":"phy2853","t":"光电效应·I-U图像分析","s":"看到【$I$-$U$ 图像上有多条曲线，比较频率、遏止电压、饱和光电流或光子数】","c":"想到【图线与横轴交点越靠左，遏止电压越大、频率越大，光子能量与最大初动能也越大；水平段越高，饱和光电流 $I_M$ 越大，单位时间内发出的光子数（光电子数）越多】；警惕【交点位置比频率、水平高度比光强（光子数），两个维度独立判断；饱和光电流大不代表频率大，频率大也不代表饱和光电流大】","src":"跳跳物一轮16.1 光电效应_笔记","note":"视频|22:31","orig":"（知识）光电流—电压图像的读图方法与比较套路。","link":""},{"id":"phy2854","t":"光电效应·光电管电路滑片与电源反接","s":"看到【光电管电路中滑片移动改变电压，或电源反接，判断电流表示数变化】","c":"想到【正向电压增大时，光电流可能一直增大，也可能先增大后达到饱和光电流保持不变；电源反接后变反向电压，滑片同向移动使反向电压增大，电流可能一直减小，也可能先减小后为零】；警惕【是否已达饱和需视正向电压是否足够大，结论带「可能」二字，不能武断单调变化；反向电压增大到遏止电压后电流恒为零】","src":"跳跳物一轮16.1 光电效应_笔记","note":"视频|30:56","orig":"（例）光电管电路中电源正向连接，滑动变阻器滑片从左向右滑动使正向电压增大，问电流表示数如何变化；电源反接后滑片同样从左向右滑动，电流又如何变化。","link":""},{"id":"phy2855","t":"光电效应·Uc-1/λ图像","s":"看到【$U_C$ 随 $1/\\lambda$ 变化的图像（横轴为波长倒数），求普朗克常量、截止频率或逸出功】","c":"想到【由 $E_K=eU_C=h\\nu-W_0$ 和 $c=\\lambda\\nu$ 得 $U_C=(hc/e)\\cdot(1/\\lambda)-W_0/e$：斜率为 $hc/e$，结合电子电荷量可求 $h$；纵截距绝对值为 $W_0/e$，乘 $e$ 得逸出功；横截距为 $1/\\lambda_C=\\nu_C/c$，乘 $c$ 得截止频率】；警惕【横轴是 $1/\\lambda$ 而非 $\\nu$，斜率是 $hc/e$ 而不是 $h/e$；图线不过原点，$U_C$ 与 $1/\\lambda$ 不成正比】","src":"跳跳物一轮16.1 光电效应_笔记","note":"视频|38:32","orig":"（知识）遏止电压—波长倒数（$1/\\lambda$）图像的斜率与截距含义。","link":""},{"id":"phy2856","t":"光的波粒二象性·光子三大核心方程","s":"看到【求光子能量、动量，或波长、频率、能量之间换算】","c":"想到【三大核心方程：$c=\\lambda\\nu$、$\\varepsilon=h\\nu$、$p=h/\\lambda$；联立可得 $\\varepsilon=h\\nu=hc/\\lambda$，且 $\\varepsilon=pc$（光子能量=动量×光速）；三个方程可在能量、频率、波长、动量之间任意互求】；警惕【$p$ 与 $\\lambda$ 成反比，频率越大的光子动量越大、波长越短，勿写成 $p=h\\lambda$；能量单位 eV 与 J 之间注意乘 $1.6\\times10^{-19}$ 换算】","src":"跳跳物一轮16.2 光的波粒二象性、玻尔原子理论_笔记","note":"视频|07:04","orig":"（知识）光子的三个核心方程及其联合换算。","link":""},{"id":"phy2857","t":"光的波粒二象性·波动性与粒子性证据分类","s":"看到【判断某实验证明光的波动性还是粒子性（干涉、偏振、光电效应等）】","c":"想到【波动性证据：干涉、衍射、偏振、多普勒效应，都是波特有的现象；粒子性证据：光电效应、黑体辐射、康普顿效应；光同时具有波动性和粒子性，即波粒二象性】；警惕【偏振、多普勒易被误归为粒子性证据；电子束穿过铝箔的衍射图样证明的是电子（实物粒子）的波动性】","src":"跳跳物一轮16.2 光的波粒二象性、玻尔原子理论_笔记","note":"视频|04:47","orig":"（知识）光的波动性与粒子性的实验证据清单。","link":""},{"id":"phy2858","t":"光的波粒二象性·康普顿效应","s":"看到【光子（X 射线）与电子碰撞散射后，问散射光波长如何变化】","c":"想到【散射光中既有与入射波长 $\\lambda$ 相同的成分，也有波长大于 $\\lambda$ 的成分，没有小于的；光子与电子碰撞把部分动量传给电子，自身动量减小，由 $p=h/\\lambda$ 知动量减小则波长变长；康普顿效应说明光子具有动量，是光的粒子性证据】；警惕【散射后波长只增不减；只有部分光子与电子碰撞，故仍保留原波长成分】","src":"跳跳物一轮16.2 光的波粒二象性、玻尔原子理论_笔记","note":"视频|02:43","orig":"（知识）康普顿效应的现象与光子动量解释。","link":""},{"id":"phy2859","t":"光的波粒二象性·黑体辐射规律","s":"看到【黑体辐射强度随波长变化的图像，或温度变化时比较辐射强度、峰值波长】","c":"想到【黑体能完全吸收各种波长的电磁波而不反射，相同温度下黑体的吸收和辐射能力都最强；实验规律：温度越高，图线越高，峰值对应的波长越短；普朗克据此提出能量子假说——黑体辐射能量不连续，只能是最小能量值 $\\varepsilon$ 的整数倍】；警惕【黑体不反射但仍能向外辐射；温度升高峰值波长变短（向高频移动），不是变长】","src":"跳跳物一轮16.2 光的波粒二象性、玻尔原子理论_笔记","note":"视频|00:22-02:43","orig":"（知识）黑体的定义与黑体辐射的实验规律。","link":""},{"id":"phy2860","t":"光的波粒二象性·物质波与概率波","s":"看到【求电子等实物粒子的德布罗意波长，或问大量粒子衍射图样、亮暗条纹含义】","c":"想到【任何运动的实物粒子都有波与之对应，物质波波长 $\\lambda=h/p$，动量越大波长越短；已知动能时由 $E_K=p^2/2m$ 得 $p=\\sqrt{2mE_K}$，故 $\\lambda=h/\\sqrt{2mE_K}$；粒子数越多波动性越明显；光波和物质波都是概率波，干涉亮条纹是光子到达概率大的地方，暗条纹是概率小处】；警惕【物质波是概率波不是机械波；动能相同的电子和中子质量不同、动量不同，波长也不同】","src":"跳跳物一轮16.2 光的波粒二象性、玻尔原子理论_笔记","note":"视频|05:21","orig":"（知识）物质波（德布罗意波）的波长公式与概率波特点。","link":""},{"id":"phy2861","t":"玻尔原子理论·跃迁规则与电离条件","s":"看到【氢原子跃迁，用光子或实物粒子提供能量，判断能否跃迁或电离】","c":"想到【跃迁光子能量 $h\\nu=E_M-E_N$（大能级减小能级）；用光子激发时，光子能量必须严格等于能级差，多一分少一分都不行；用实物粒子碰撞时，粒子能量大于等于能级差即可（原子可只吸收部分能量）；电离时，光子或粒子能量只需大于等于该能级能量的绝对值 $|E_n|$】；警惕【光子吸收要求严格相等而粒子碰撞只要求不小于，两者勿混；电离也不要求严格等于，达到或超过即可】","src":"跳跳物一轮16.2 光的波粒二象性、玻尔原子理论_笔记","note":"视频|11:21","orig":"（知识）氢原子跃迁吸收或辐射能量的规则，以及电离条件。","link":""},{"id":"phy2862","t":"玻尔原子理论·跃迁辐射光谱线条数","s":"看到【氢原子（一群或一个）从能级 n 向低能级跃迁，求辐射几种频率的光】","c":"想到【一群（大量）氢原子从能级 $n$ 跃迁可覆盖所有能级差，共发出 $C_n^2=\\frac{n(n-1)}{2}$ 种频率的光，如 $n=4$ 时 6 种；一个氢原子只能走一条路径，最多发出 $n-1$ 种（逐级往下跳），如 $n=4$ 时最多 3 种】；警惕【「一群」用组合数、「一个」用 $n-1$，审题先分清对象；一个氢原子若越级跳，发出的种数比 $n-1$ 更少】","src":"跳跳物一轮16.2 光的波粒二象性、玻尔原子理论_笔记","note":"视频|15:44","orig":"（知识）一群与一个氢原子从能级 n 向下跃迁，能发出多少种不同频率的光。","link":""},{"id":"phy2863","t":"玻尔原子理论·跃迁光子频率与能级差比较","s":"看到【多个跃迁辐射的光比较波长、频率，或判断哪种光能使金属发生光电效应】","c":"想到【跃迁光子频率由能级差决定：波长最长→频率最小→光子能量最小→能级差最小；最易发生光电效应的是频率最高即能级差最大的光；巴耳末系是从高能级跃迁到 $n=2$ 能级，其中 $n=3\\to2$ 能级差最小、波长最长】；警惕【比较时统一转化为能级差，勿直接看能级数字；氢原子可见光（巴耳末系）光子能量约 1.62eV~3.11eV，$n=3\\to1$ 的 12.09eV 属于不可见光】","src":"跳跳物一轮16.2 光的波粒二象性、玻尔原子理论_笔记","note":"视频|27:54-28:48","orig":"（例）大量氢原子向低能级跃迁辐射多种光子（含巴耳末系各谱线），问哪种光波长最长、哪种光最易使某金属发生光电效应。","link":""},{"id":"phy2864","t":"衰变·原子核符号与常见粒子","s":"看到【写核反应方程或判断粒子种类，需要质量数、电荷数或粒子符号】","c":"想到【原子核用左上角标 $A$、左下角标 $Z$ 的 $X$ 表示：$A$ 为质量数=核子数=质子数+中子数，$Z$ 为质子数=电荷数=原子序数；常见粒子：质子 $^{1}_{1}H$、中子 $^{1}_{0}n$（不带电）、$\\alpha$ 粒子 $^{4}_{2}He$（氦核）、$\\beta$ 粒子即电子（质量数 0、电荷数 $-1$，高中默认 $\\beta$ 负）；质子数相同而中子数不同的核互称同位素】；警惕【左上角是质量数、左下角是电荷数，勿颠倒；$\\beta$ 粒子虽是电子但来自核内，不是核外电子】","src":"跳跳物一轮16.3 衰变、核反应方程_一轮复习系统课全部完结撒花_笔记","note":"视频|01:00-03:55","orig":"（知识）原子核的表示方法与四种常见粒子的符号。","link":""},{"id":"phy2865","t":"衰变·三种射线性质对比","s":"看到【比较三种射线的电离能力、贯穿本领，或选择哪种射线做探测】","c":"想到【$\\alpha$ 射线是氦核，电荷量 $+2e$，速度约 $0.1c$；$\\beta$ 射线是电子，电荷量 $-e$，速度略小于 $c$；$\\gamma$ 射线是光子，不带电，速度为 $c$；规律：粒子电荷量越大，电离能力越强、贯穿本领越弱，故电离能力 $\\alpha>\\beta>\\gamma$，贯穿本领 $\\gamma>\\beta>\\alpha$】；警惕【电离与贯穿的排序正好相反，勿混淆；$\\gamma$ 射线不带电，在电场、磁场中都不偏转】","src":"跳跳物一轮16.3 衰变、核反应方程_一轮复习系统课全部完结撒花_笔记","note":"视频|05:25","orig":"（知识）$\\alpha$、$\\beta$、$\\gamma$ 三种射线的本质与电离、贯穿能力排序。","link":""},{"id":"phy2866","t":"衰变·αβ衰变规律与次数计算","s":"看到【原子核经 $\\alpha$、$\\beta$ 衰变变为新核，判断衰变类型或求两种衰变的次数】","c":"想到【$\\alpha$ 衰变：质量数减 4、电荷数减 2，实质是核内 2 个质子和 2 个中子结合成氦核射出；$\\beta$ 衰变：质量数不变、电荷数加 1，实质是核内一个中子转化为质子和电子，电子射出；求次数：设 $\\alpha$ 衰变 $x$ 次、$\\beta$ 衰变 $y$ 次，由质量数 $4x=\\Delta A$ 解出 $x$，代入电荷数 $2x-y=\\Delta Z$ 解出 $y$】；警惕【$\\beta$ 衰变的电子来自核内而非核外；判断类型先看质量数（减 4 是 $\\alpha$ 衰变、不变是 $\\beta$ 衰变）；两种衰变常伴随放出 $\\gamma$ 射线】","src":"跳跳物一轮16.3 衰变、核反应方程_一轮复习系统课全部完结撒花_笔记","note":"视频|08:11","orig":"（知识）$\\alpha$ 衰变与 $\\beta$ 衰变的规律，以及衰变次数的计算方法。","link":""},{"id":"phy2867","t":"衰变·半衰期特性与剩余量计算","s":"看到【放射性元素经历一段时间，求剩余质量或个数，或问半衰期是否随外界条件改变】","c":"想到【半衰期是大量原子核有一半发生衰变所需的时间；剩余质量=原质量×$(1/2)^n$，$n$ 为经历的半衰期个数（剩余个数同式）；半衰期只由元素种类（核内部结构）决定，与温度、压强、化学状态等外界因素均无关；测年应用：由剩余比例 $(1/2)^n$ 定出 $n$ 个半衰期，再乘半衰期值即得年代】；警惕【半衰期是统计规律，只对大量原子核有意义，对少数原子核无意义；经历整数个半衰期后元素不会衰变完毕】","src":"跳跳物一轮16.3 衰变、核反应方程_一轮复习系统课全部完结撒花_笔记","note":"视频|10:17","orig":"（知识）半衰期的定义、影响因素与剩余量计算。","link":""},{"id":"phy2868","t":"衰变·磁场中反冲核轨迹","s":"看到【静止核在匀强磁场中衰变，给出两圆轨迹图，判断衰变类型或半径、周期之比】","c":"想到【分离过程按爆炸模型：内力远大于洛伦兹力，动量守恒，两粒子动量大小相等、方向相反；分离后各做匀速圆周运动，$R=\\frac{p}{qB}$，动量相等时半径与电荷量成反比，电荷量小的粒子（$\\alpha$ 粒子或电子）半径大；周期 $T=\\frac{2\\pi m}{qB}$，与比荷成反比；$\\alpha$ 衰变两粒子均带正电，轨迹外切；$\\beta$ 衰变两粒子电性相反，轨迹内切；切点即分离点】；警惕【内切还是外切由电性异同决定，勿死记；动量相等时动能与质量成反比，新核质量大、动能小】","src":"跳跳物一轮16.3 衰变、核反应方程_一轮复习系统课全部完结撒花_笔记","note":"视频|12:54-18:38","orig":"（知识）静止原子核在匀强磁场中衰变后，反冲核与粒子轨迹的内外切及半径、周期关系。","link":""},{"id":"phy2869","t":"核反应方程·四种核反应类型判定","s":"看到【给出核反应方程，判断属于衰变、裂变、聚变还是人工转变】","c":"想到【衰变：方程左边只有一个原子核（自发放出粒子）；裂变：中子轰击重核分成两个中等质量的核，方程左右两边都有中子；聚变：方程左边是两个轻核（高中阶段几乎都是两个氢核）；人工转变：粒子轰击原子核使其转变，无统一特征，用排除法判断；经典方程：卢瑟福用 $\\alpha$ 粒子轰击氮核发现质子，查德威克用 $\\alpha$ 粒子轰击铍核发现中子】；警惕【裂变方程左右两边的中子不能互相抵消，左边没有中子反应无法引发；勿把人工转变误判为聚变】","src":"跳跳物一轮16.3 衰变、核反应方程_一轮复习系统课全部完结撒花_笔记","note":"视频|21:13","orig":"（知识）衰变、裂变、聚变、人工转变四种核反应方程的识别特征。","link":""},{"id":"phy2870","t":"核反应方程·质量亏损与核能计算","s":"看到【核反应给出反应前后各核质量，求释放的核能（质量亏损）】","c":"想到【质能方程 $E=mc^2$ 表示能量与质量成正比的对应关系；质量亏损 $\\Delta m$=反应物总质量-生成物总质量，释放能量 $\\Delta E=\\Delta mc^2$；若 $\\Delta m$ 以 u 为单位，直接用 $\\Delta E=\\Delta m\\times931.5\\,\\mathrm{MeV}$（1u 对应 $931.5\\,\\mathrm{MeV}$）；核反应前后质量数守恒，但质量不守恒（存在质量亏损）】；警惕【质量数守恒不等于质量守恒；不能说「质量转化为能量」，$E=mc^2$ 只表示质量与能量的对应关系】","src":"跳跳物一轮16.3 衰变、核反应方程_一轮复习系统课全部完结撒花_笔记","note":"视频|24:23","orig":"（知识）质量亏损、质能方程与核能的计算方法。","link":""},{"id":"phy2871","t":"核反应方程·结合能与比结合能","s":"看到【比结合能曲线或给出各核的比结合能，判断原子核稳定性或反应吸放能】","c":"想到【结合能是把原子核分解成自由核子所需的能量；比结合能=结合能÷核子数，比结合能越大原子核越稳定；结合能=比结合能×核子数；释放能量的核反应，生成物的比结合能必大于反应物的比结合能；用结合能算核能：$\\Delta E$=生成物总结合能-反应物总结合能（题目给比结合能时先乘核子数）】；警惕【判断稳定性必须用比结合能而非结合能（铀的结合能比银大却更不稳定）；中等质量核比结合能最大、最稳定】","src":"跳跳物一轮16.3 衰变、核反应方程_一轮复习系统课全部完结撒花_笔记","note":"视频|26:20","orig":"（知识）结合能与比结合能的区别，以及用比结合能判断稳定性和核反应能量变化。","link":""}]}};
